      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C     ..
C     ..
C     .. Equivalences ..
      SAVE
C     ..
C     .. Data ..
C     ..
C
C---- Form product of misseting angles and A matrix. 
C     First convert missets to a rotation matrix
C
       CALL ROTMAT(DELPHI,WORK,1)
C
C---- Form product with AMAT (A=BC)
C
       CALL MATMUL3(RMAT,WORK,AMAT)
C
C---- Get A*,B*,C* vectors       
C
       V1(1) = 1
       V1(2) = 0
       V1(3) = 0
       CALL MATVEC(ASTAR,RMAT,V1)
       V1(1) = 0
       V1(2) = 1
       V1(3) = 0
       CALL MATVEC(BSTAR,RMAT,V1)
       V1(1) = 0
       V1(2) = 0
       V1(3) = 1
       CALL MATVEC(CSTAR,RMAT,V1)
CAL       WRITE(6,*),'ASTAR,BSTAR,CSTAR',ASTAR,BSTAR,CSTAR
C
C---- Convert to unit vectors
C
       CALL UNIT(ASTAR)
       CALL UNIT(BSTAR)
       CALL UNIT(CSTAR)
C
C---- Get unit vectors along real space axes a,b,c
C
       CALL CROSS(AREAL,BSTAR,CSTAR)
       CALL CROSS(BREAL,CSTAR,ASTAR)
       CALL CROSS(CREAL,ASTAR,BSTAR)
       CALL CROSS(ACREAL,AREAL,CREAL)
C
C---- Convert to unit vectors
C
       CALL UNIT(AREAL)
       CALL UNIT(BREAL)
       CALL UNIT(CREAL)
       CALL UNIT(ACREAL)
CAL       WRITE(6,*),'AREAL,BREAL,CREAL',AREAL,BREAL,CREAL
      IF (DEBUG(60)) THEN
       WRITE(IOUT,FMT=6000) (DELPHI(I),I=1,3),
     +                       ((WORK(I,J),J=1,3),I=1,3),
     +                       ((RMAT(I,J),J=1,3),I=1,3),
     +      ASTAR,BSTAR,CSTAR,AREAL,BREAL,CREAL,ACREAL
       IF (ONLINE) WRITE(ITOUT,FMT=6000) (DELPHI(I),I=1,3),
     +                       ((WORK(I,J),J=1,3),I=1,3),
     +                       ((RMAT(I,J),J=1,3),I=1,3),
     +      ASTAR,BSTAR,CSTAR,AREAL,BREAL,CREAL,ACREAL
 6000  FORMAT(1X,'Missets ',3F10.3,/,1X,'Corresponding matrix:',/,
     +        3(1X,3F10.7/),/,1X,'Modified AMAT',/,
     +        3(1X,3F10.7/),/,1X,'Unit vectors along a*:',3F10.5,/,1X,
     +        '             along b*:',3F10.5,/,1X,
     +        '             along c*:',3F10.5,/,1X,
     +        '             along a :',3F10.5,/,1X,
     +        '             along b :',3F10.5,/,1X,
     +        '             along b :',3F10.5,/,1X,
     $      'cross product of a and c axes: ',3F10.5)
      END IF
C
C---- Get angles with lab X,Y,Z axes
C
       DO 20 I = 1,3
         IF (ABS(AREAL(I)).GT.1.0) AREAL(I) = SIGN(1.0,AREAL(I))
         IF (ABS(BREAL(I)).GT.1.0) BREAL(I) = SIGN(1.0,BREAL(I))
         IF (ABS(CREAL(I)).GT.1.0) CREAL(I) = SIGN(1.0,CREAL(I))
         IF (ABS(ACREAL(I)).GT.1.0) ACREAL(I) = SIGN(1.0,ACREAL(I))
 20    CONTINUE
C
C
      END
C $Id: anires.f,v 1.6 2007/12/18 14:55:49 harry Exp $
C Routine to allow different integration of different resolution limits in 
C each of three reciprocal axis directions; an ellipsoid is calculated with 
C its long principal axis coaxial with the longest reciprocal axis, and the
C shorter axes orthogonal to this. The observant will notice that the code 
C is derived from the CCP4 subroutine RBFR01.
C
C     ===============================
      SUBROUTINE ANIRES(ORTMAT)
      IMPLICIT NONE
C     ===============================
C
C
C   ORTMAT    (O)  (REAL(3,3))   Standard orthogonisational matrix
C
C  this generates the various orthogonalising matrices
C     ' NCODE =1 -  ORTHOG AXES ARE DEFINED TO HAVE'
C                    A PARALLEL TO XO   CSTAR PARALLEL TO ZO'
C
C   SET UP MATRICES TO ORTHOGONALISE H K L AND X Y Z FOR THIS CELL.
C
C
C---- Returned arrays
C
      REAL ORTMAT(3,3)
C
C---- Local arrays
C
C     RECELL is wavelength independent reciprocal cell
C
      REAL RECELL(6)
C     
C---- Local Scalars
C
      REAL A,ALPH,B,BET,C,GAMM,COSA,COSAS,SINAS,COSB,COSBS,SINBS,
     +     COSG,COSGS,SINGS,FCT,SINA,SINB,SING,SUM,V,VOL
      INTEGER I,J
C
C---- include files
C
C&&*&& include  ../inc/cell.f
C
C $Id: cell.f,v 1.4 2012/11/21 14:41:22 andrew Exp $
C
C--- awk generated include file  cell.h
C---- START of include file cell.h
C
C     CELL cell dimensions (real space)
C     RCELL reciprocal cell parameters in dimensionless rlu
C     LCELL indicator for cell parameters to be refined
C     
C     LCELL(I) = -1  parameter free
C              =  0  parameter fixed
C              >  0, = J  parameter I constrained to = parameter J
C
C     .. Arrays in Common /CELLCOM/ ..
      REAL UMAT,BMAT,GMAT,CELL,RCELL,UMATCELL,SOFTCELL,VOLUME
      INTEGER LCELL,ICRYST,NUMSPG,NLAUE
C     ..
C     .. Common Block /CELLCOM/ ..
      COMMON /CELLCOM/UMAT(3,3),BMAT(3,3),GMAT(3,3),CELL(6),RCELL(6),
     $       UMATCELL(6),SOFTCELL,VOLUME,LCELL(6),ICRYST,NUMSPG,NLAUE
C     ..
C
C
C&&*&& end_include  ../inc/cell.f
C&&*&& include  ../inc/misc.f
C
C $Id: misc.f,v 1.3 2012/03/23 12:02:50 harry Exp $
C
C--- awk generated include file  misc.h
C---- START of include file misc.h
C
C
C
C     .. Scalars in common /MISC/ ..
      DOUBLE PRECISION STARTTIME,ENDTIME
      REAL PHIBEG,PHIEND,PHIRNG,RMIN,RMAX,WAVE
      INTEGER IPACKID,MININT,IERRFLG
C     ..
C     .. Arrays in common /MISC/ ..
      REAL DELPHI,RESANI
      INTEGER IAX
C     ..
C     .. LOGICAL
      LOGICAL ANITES

C     ..
C     .. Common Block /MISC/ ..
      COMMON /MISC/DELPHI(3),RESANI(3),STARTTIME,ENDTIME,
     $     PHIBEG,PHIEND,PHIRNG,RMIN,RMAX,
     $     WAVE,IAX(3),IPACKID,MININT,IERRFLG,ANITES
C     ..
C
C
C&&*&& end_include  ../inc/misc.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C
C---- Intrinsic Functions
C
      INTRINSIC ATAN,ATAN2,COS,SIN,SQRT
C
C---- External routines
C
      EXTERNAL RECCEL
C
C---- Remember we're using the wavelength independent reciprocal cell...
C
      CALL RECCEL(RECELL,CELL,1.00)
      FCT = 8.0*PI*PI
      ALPH = RECELL(4)*DTOR
      BET = RECELL(5)*DTOR
      GAMM = RECELL(6)*DTOR
      SUM = (ALPH+BET+GAMM)*0.5
      V = SQRT(SIN(SUM-ALPH)*SIN(SUM-BET)*SIN(SUM-GAMM)*SIN(SUM))
      VOL = 2.0*RECELL(1)*RECELL(2)*RECELL(3)*V
      SINA = SIN(ALPH)
      COSA = COS(ALPH)
      SINB = SIN(BET)
      COSB = COS(BET)
      SING = SIN(GAMM)
      COSG = COS(GAMM)
      COSAS = (COSG*COSB-COSA)/ (SINB*SING)
      SINAS = SQRT(1.0-COSAS*COSAS)
      COSBS = (COSA*COSG-COSB)/ (SINA*SING)
      SINBS = SQRT(1.0-COSBS*COSBS)
      COSGS = (COSA*COSB-COSG)/ (SINA*SINB)
      SINGS = SQRT(1.0-COSGS*COSGS)
      A = RECELL(1)*RESANI(1)
      B = RECELL(2)*RESANI(2)
      C = RECELL(3)*RESANI(3)
C
C---- Zero matrices
C
        DO 30 I = 1,3
          DO 20 J = 1,3
            ORTMAT(I,J) = 0.0
   20     CONTINUE
   30   CONTINUE
        IF ((C.GT.A).AND.(C.GT.B)) THEN
C
C----  c* longest
C
           ORTMAT(1,1) = A
           ORTMAT(1,2) = B*COSG
           ORTMAT(1,3) = C*COSB
           ORTMAT(2,2) = B*SING
           ORTMAT(2,3) = -C*SINB*COSAS
           ORTMAT(3,3) = C*SINB*SINAS
        ELSE IF ((A.GT.B).AND.(A.GT.C))THEN
C
C----  a* longest
C
           ORTMAT(1,1) = A*COSG
           ORTMAT(1,2) = B
           ORTMAT(1,3) = C*COSA
           ORTMAT(2,1) = -A*SING*COSBS
           ORTMAT(2,3) = C*SINA
           ORTMAT(3,1) = A*SING*SINBS
        ELSE
C
C----  b* longest or equal to either a* or c*
C
           ORTMAT(1,1) = A*COSB
           ORTMAT(1,2) = B*COSA
           ORTMAT(1,3) = C
           ORTMAT(2,1) = A*SINB
           ORTMAT(2,2) = -B*SINA*COSGS
           ORTMAT(3,2) = B*SINA*SINGS
        ENDIF
C
C
C
      RETURN
      END


C $Id: area.f,v 1.2 2006/08/29 14:58:35 harry Exp $
C              
C== AREA ==
      REAL FUNCTION AREA(XYP,XY)
      IMPLICIT NONE
C     ..
C     .. Array Arguments ..
      REAL XYP(2),XY(2,4)
C
C     .. Local scalars
      REAL A,AR
      INTEGER I,J
C
C     .. Local arrays
      REAL DXY(2,4)
C     ..                      
C     .. External Subroutines ..
      EXTERNAL V2SUB,V2CROSS
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC ABS
C
      DO 10 I=1,4
        CALL V2SUB(XYP,XY(1,I),DXY(1,I))
 10   CONTINUE
      A = 0.0
      DO 20 I = 1,4
        J = I + 1
        IF (J.GT.4) J = 1
        CALL V2CROSS(DXY(1,I),DXY(1,J),AR)
        A = A + AR
 20   CONTINUE
      AREA = ABS(0.5*A)
      END         
C $Id: areaq.f,v 1.2 2006/08/29 14:58:35 harry Exp $
C         
C== AREAQ ==
      REAL FUNCTION AREAQ(XY)
      IMPLICIT NONE
C     ..
C     .. Array Arguments ..
      REAL XY(2,4)
C
C     .. Local scalars
      INTEGER I
      REAL XG,YG
C
C     .. Local arrays
      REAL XYG(2)
C     ..
C     .. External Functions ..    
      REAL AREA
      EXTERNAL AREA
      XG = 0.0
      YG = 0.0
      DO 10 I=1,4
        XG = XG + XY(1,I)
        YG = YG + XY(2,I)
 10   CONTINUE
      XYG(1) = XG/4.0
      XYG(2) = YG/4.0
      AREAQ = AREA(XYG,XY)
      END
