C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C&&*&& include  ../inc/xy.f
C
C $Id: xy.f,v 1.1 2002/05/02 10:47:25 harry Exp $
C
C--- awk generated include file  xy.h
C---- START of include file xy.h
C
C     .. Scalars in common block /XY/ ..
      REAL XTOFD,SINV,COSV,TANV,TWOTHETA
      INTEGER ICASS
C     ..
C     .. Common Block /XY/ ..
      COMMON /XY/XTOFD,SINV,COSV,TANV,TWOTHETA,ICASS
C     ..
C
C     XTOFD....  Crystal to detector distance in 10 micron units. Read from
C                keyworded input and never changed.
C
C                Spot positions are calculated in S/R XYSPOT (Called from
C                REEK) and are for an "ideal" detector at a distance of XTOFD.
C                These are converted into pixel positions in S/R MMTOPX
C                which applies the multiplicative factor XTOFRA to allow
C                for refinement of the distance. XTOFRA is the parameter
C                that is actually refined (in RDIST), rather than XTOFD.
C                The refined distance that is printed in the logfile is
C                actually XTOFRA*XTOFD
C
C     ICASS....  Indicates detector type:
C                0     Flat film
C                1     Vee shaped cassettes
C                2     FAST detector (only used in TESTGEN mode of OSCGEN)
C                3     Swung out FAST (ditto)
C                4     IP detector
C     TWOTHETA   Detector swing angle (degrees)
C&&*&& end_include  ../inc/xy.f
C     ..
C     .. Equivalences ..
      EQUIVALENCE (IRAS(1),NXS), (IRAS(2),NYS), (IRAS(3),NC)
      EQUIVALENCE (IRAS(4),NRX), (IRAS(5),NRY)
C     ..
      SAVE
C     .. Data statements ..
      DATA PSISTR/'PSIX','PSIY','PSIZ','DIV ','DIVH','DIVV'/
      DATA AWELIMIT/2.0/
C     ..
C     
C 
      IERR = 0
      IDDUM = 0
      DPOWDER = .FALSE.
      LPOSTREF = .FALSE.
      LLAST = .FALSE.
      MATCH = .TRUE.
      FAIL = .FALSE.
      FORCE = .FALSE.
      LIST = .FALSE.
      PRECESS = .FALSE.
      LPROFILE = .FALSE.
      INTERPOL = .FALSE.
      RESCAN = .TRUE.
      REFETA = .FALSE.
      LMULTISEG = .FALSE.
      INTCHK = .FALSE.
      LRESCALE = .TRUE.
C     
C     aelimit=20.
C     armslim=20.
C     
C---- initialize for mosaicity estimation
C     
      IF(MOSEST)THEN
        ETAMAX = 1.0
        IETAMAX = 1
        DELETA = 0.05
        SLOPEFAC = 0.1
      ENDIF
C     
C     
C---- Convert phi to psi
C     
      PHIAV = (PHIBEG+PHIEND)*0.5 + DELPHI(3)
C     
C     **************************
      CALL PHITOPSI(DELPHI,PSI,PHIAV)
C     **************************
C     
C---- Save these psi and starting delphi values
C     
      DO 10 I = 1,3
        XDELPHI(I) = DELPHI(I)
        SDELPHI(I) = DELPHI(I)
        SPSI(I) = PSI(I)
 10   ENDDO
C     
C     
      SETA = ETA
      SDIVH = DIVH
      SDIVV = DIVV
C     
C     
      IF (DEBUG(30)) THEN
        IF (ONLINE) WRITE (ITOUT,FMT=6000) DELPHI,PSI,PHIAV,2*ETA/DTOR,
     +       2*DIVH/DTOR,2*DIVV/DTOR
 6000   FORMAT ('  Entering AUTOMATCH',/1X,'DELPHI ',3F6.2,5X,'DELPSI ',
     +       3F6.2,5X,'PHIAV ',F6.2,' ETA ',F6.3,' DIVH,V ',2F6.3)
        WRITE (IOUT,FMT=6000) DELPHI,PSI,PHIAV,2*ETA/DTOR,
     +       2*DIVH/DTOR,2*DIVV/DTOR
      END IF
C     
C---- Do initial call to set up standard profiles and to RMAXR to
C     calculate box sizes, as these are needed by NEXT. For IP data,
C     only need to do this once, but for film data the position of
C     the direct beam in the digitised image can vary from one
C     pack to the next, so need to set it up for every pack.
C     (Same will be true for IP data from an offline scanner)
C     
      IF (.NOT.IMGP) THEN
        CALL PRSETUP
        IERR = 0
C     ***********************
        IF (FIRSTFILM) CALL RMAXR(LIMIT,THICK,IERR)
C     ***********************
      ELSE
        IF (FIRSTFILM.AND.NUMBLOCK.EQ.1) THEN
          CALL PRSETUP
          CALL RMAXR(LIMIT,THICK,IERR)
        END IF
      END IF
C     
C---- Skip centrs if in mode 2 operation
C     
      IF (.NOT.NOCENT)THEN
C     
C---- Initialise variables for centrs
C     
        PARTLS = .TRUE.
        OVRLDS = .TRUE.
        GENLIST = .FALSE.
        LPTMIN = 0.1
C     
C---- Test if oscillation range is large enough to get
C     sufficient overlap of calculated patterns and real
C     pattern with missetting equal to the desired range of
C     convergence
C     
        OSCRANGE = ABS(PHIEND-PHIBEG)
        IF (OSCRANGE.GT.360.0) OSCRANGE = OSCRANGE - 360.0
C     
C     
C---- Calculate resolution based on 'limit'
C     
      ENDIF
C     ..
C     .. REP_20 means repeat the block starting at the now non-existent
C     label 20, REP_40 at label 40.
      REP_20 = .TRUE.
      REP_40 = .TRUE.
      DO 260 WHILE(REP_20.OR.REP_40)

        IF(.NOT.NOCENT)THEN
          IF(REP_20)THEN
            REP_20 = .FALSE.
            R = LIMIT*1.4142
            IF (VEE) R = SQRT(LIMIT**2+VLIM**2)
            TH = ATAN(R/XTOFD)*0.5
            RESOL = 0.5*WAVE/SIN(TH)
            IF (OSCRANGE.LT. (RCONV+OVRLAP)) THEN
C     
C---- Not enough overlap, regenerate with increased mosaic spread
C     
              ETANEW = (RCONV+OVRLAP) - OSCRANGE
C     
              IF (ONLINE) WRITE (ITOUT,FMT=6010) OSCRANGE,RCONV,OVRLAP,
     +             ETANEW
 6010         FORMAT (/,' OSC Range of ',F5.1
     $             ,' Degrees is TOO SMALL to give '
     $             ,'a radius of convergence'/,1X,'of',F5.2
     $             ,' degrees with an overlap of',F6.1,' degrees.',
     $             /1X,'ETA increased to',F5.2,' degrees')
              WRITE (IOUT,FMT=6010) OSCRANGE,RCONV,OVRLAP,ETANEW
            ELSE
              ETANEW = SETA/DTOR
            END IF
C     
            IFLAG = 0
C     
C     ***********************************
            CALL NEWLIST(ETANEW,PSI,PHIAV,RESOL,IFLAG,IERR)
C     ***********************************
C     
C---- Now run centrs to locate spots in central region of film
C     note that fulls and partials will be used in centrs for the
C     first (low resolution) pass
C     
C     
C---- Store DELPHI values used at CENTRS time
C     
          ENDIF
          REP_40 = .FALSE.
          REPEAT = .TRUE.
          DO 100 WHILE(REPEAT)
            REPEAT = .FALSE.
C     
C     
            DO 20 I = 1,3
              XDELPHI(I) = DELPHI(I)
 20         ENDDO
C     
C---- Now do CENTRS refinement
C     
            DO 70 ICYC = 1,NCYCA
              FINAL = (ICYC.EQ.NCYCA)
              IF (ONLINE) THEN
C     
C     
                WRITE (ITOUT,FMT=6020) ICYC
 6020           FORMAT (/,' Refinement Cycle',I3)
              END IF
C     
C     
              WRITE (IOUT,FMT=6020) ICYC
C     
C---- In centrs, the background definition of the measurement box
C     is not used to determine the centre of gravity (the c of g over
C     the whole measurement box is calculated...this gives a greater
C     range of convergence). in second and subsequent cycles, if the
C     final residual of the previous cycle is less then rmslim
C     (default value 6.0, can be changed by keyword "resid"), use the
C     same list of reflections and s/r 'next' to evaluate the true
C     c of g for these reflections
C     
              IF (RRWEIGHT) THEN
                OKREF = (WRMSRES.LE.AWRMSLIM)
              ELSE
                OKREF = (RMSRES.LE.ARMSLIM)
              END IF
              IF ((ICYC.GT.1) .AND. (OKREF) .AND.
     +             (.NOT.DOPROFILE)) THEN
                LIST = .TRUE.
C     
C---- Restore original list of reflections from CENTRS so they are 
C     all remeasured by NEXT
C     
                NRS = NRSOLD
                DO 30 I = 1,NRS
                  RRS(I) = IRSAVE(I)
 30             ENDDO
                IF (ONLINE) WRITE (ITOUT,FMT=6030) NRS
 6030           FORMAT (/,' Repeating refinement using the same list of'
     $               ,I3,' Reflections')
                WRITE (IOUT,FMT=6030) NRS
                USEWEIGHT = .TRUE.
                LCENTRAL = .TRUE.
C     
C     *****************************************************
                CALL NEXT(LIST,IXSHIFT,IYSHIFT,PRECESS,MATCH,IFAIL
     $               ,PARTLS,ADDPART,LCENTRAL,NSIG,NIMGSUMREF)
C     ******************************************************
C     
              ELSE
                OLDLIST = (ICYC.NE.1)
                USEWEIGHT = .TRUE.
                IF (.NOT.USEBOX) THEN
                  USEWEIGHT = .FALSE.
C     
C---- If doing weighted refinement, set RMSLIM high so that on next
C     cycle it will use the measurement box
C     
                  IF (RWEIGHT) ARMSLIM = 100.0
                END IF
C     
C     ********************************************************
                CALL CENTRS(DOPROFILE,NSIG,IXSHIFT,IYSHIFT,NPROFL,LIMIT
     $               ,SEP,VLIM,MATCH,PARTLS,OVRLDS,MINREFAUTO,OLDLIST
     $               ,GENLIST,USEBOX,ADDPART,LPTMIN,NIMGSUMREF,NUSEFUL)
C     ********************************************************
                NRSOLD = NRS
C     
C---- Save this list of reflections for use in subsequent refinement
C     using
C     NEXT
C     
                DO 40 I = 1,NRS
                  IRSAVE(I) = RRS(I)
 40             ENDDO
C     
              END IF
C     
C     
              IF (NRS.LT.MINREFAUTO) THEN
                WRITE (IOUT,FMT=6040) NRS,MINREFAUTO
 6040           FORMAT (//1X,'**** ONLY',I3,' Refinement spots found,',
     &               ' minimum is',I3,'  Processing abandoned ***') 
                IF (ONLINE) WRITE (ITOUT,FMT=6040) NRS,MINREFAUTO
                FAIL = .TRUE.
C     
C---- reset divergences and mosaic spread, return
C     
                ETA = SETA
                DIVH = SDIVH
                DIVV = SDIVV
                RETURN
              ENDIF
C     
C---- Refinement
C     
              TEMP = DISPLAY
C     
C---- In centrs, only spots within 'limit' 10 micron units (default 25mm
C     )
C     of film centre are used except for vee when 'vlim' (default 40mm)
C     is the limit.
C     these limits can be changed by keywords 'limit' and 'vlimit' or
C     in centrs if all central reflections are overloads.
C     
              DISPLAY = LIMIT/100.0
              IF (VEE) DISPLAY = VLIM/100.0
C     
              DISPLAY = TEMP
              CENTRE = .TRUE.
C     
C     
              IF (VEE) THEN
C     
              ELSE
C     
                RRWEIGHT = (RWEIGHT.AND.USEWEIGHT)
                LIPACK = 1
                LNIMGSM = 0
                XMLONLY = .FALSE.
C     ******************************************
                CALL RDIST(LIPACK,ID,LNIMGSM,CENTRE,FINAL,AWELIMIT,
     $             AELIMIT,AELIMIT2,AELIMIT3,BADSTART,RRWEIGHT,REFREJ,
     +             XMLONLY,LRESCALE)
C     ******************************************
C     
              END IF
C     
C     
              CENTRE = .FALSE.
 70         ENDDO
C     
C---- End of loop over refinement cycles
C     
            LRESID = .FALSE.
            IF (RWEIGHT) THEN 
              IF (WRMSRES.LT.AWRMSLIM) THEN
                LRESID = .TRUE.
              ENDIF
            ELSE
              IF (RMSRES.LT.ARMSLIM) THEN
                LRESID = .TRUE.
              ENDIF
            END IF
            IF(.NOT.LRESID)THEN
C     
C---- If online, optionall call filmplot
C     
              IF (ONLINE) THEN
     &             
C     
                IF (RWEIGHT) THEN
                  WRITE (ITOUT,FMT=6050) AWRMSLIM
                  IF (BRIEF) WRITE (IBRIEF,FMT=6050) AWRMSLIM
 6050             FORMAT(1X,'Weighted residual is GREATER than limit (',
     &                 F5.1,')',/,1X,'Set by RESID on AUTOMATCH card',/,
     &                 1X,'Do you want to proceed anyway (Y/N)? ')
                ELSE
                  WRITE (ITOUT,FMT=6060) ARMSLIM
                  IF (BRIEF) WRITE (IBRIEF,FMT=6060) ARMSLIM
 6060             FORMAT ('  Residual is GREATER than limit (',F5.1,')',
     +                 /1X,'Set by RESID on AUTOMATCH card',/,1X,'Do y',
     +                 'ou want to proceed anyway (Y/N)? ')
                END IF
C     
C     **********
                CALL YESNO(YES)
C     **********
C     
                PROCEED = .FALSE.
                IF (YES) THEN
                  PROCEED = .TRUE.
                ELSE
                  WRITE (ITOUT,FMT=6070)
 6070             FORMAT ('  Do you want to repeat refinement (Y/N) ? ')
C     
C     **********
                  CALL YESNO(YES)
C     **********
C     
                  IF (YES) REPEAT = .TRUE.
                END IF
              END IF
              IF(.NOT.PROCEED.AND..NOT.REPEAT)THEN
                FAIL = .TRUE.
                IF (RWEIGHT) THEN
                  WRITE(IOUT,FMT=6080) AWRMSLIM
                  IF (ONLINE) WRITE(ITOUT,FMT=6080) AWRMSLIM
 6080             FORMAT(//1X
     $                 ,'Residual following refinement is greater '
     $                 ,'than ',F6.1,' (subkeyword RESID on AUTO)',
     $                 /,1X,'Processing abandoned')
                ELSE
                  WRITE(IOUT,FMT=6090) ARMSLIM
                  IF (ONLINE) WRITE(ITOUT,FMT=6090) ARMSLIM
 6090             FORMAT(//1X
     $                 ,'Residual following refinement is greater '
     $                 ,'than ',F6.1,' (subkeyword RESID on AUTO)',
     $                 /,1X,'Processing abandoned')
                END IF
C     
C---- reset divergences and mosaic spread, return
C     
                ETA = SETA
                DIVH = SDIVH
                DIVV = SDIVV
                RETURN
C     
C---- If centrs has already been repeated due to poor initial residual
C     do not allow a second repeat.
C     
              ENDIF
            ENDIF
            IF(.NOT.REPEAT)THEN
              PROCEED = BADSTART
              IF(.NOT.PROCEED)THEN
                IF (RWEIGHT) THEN
                  BADSTART = (WESTART.GT.AWELIMIT)
                  XLIMIT = AWELIMIT
                ELSE
                  BADSTART = (ESTART.GT.AELIMIT)
                  XLIMIT = AELIMIT
                END IF
C     
C---- Repeat centrs if initial residual high
C     
                IF (BADSTART) THEN
                  WRITE (IOUT,FMT=6100) XLIMIT
 6100             FORMAT (/
     $                 ,' Repeat refinement because initial residual is'
     $                 ,' GREATER than',F5.1)
                  IF (ONLINE) WRITE (ITOUT,FMT=6100) XLIMIT
                  REPEAT = .TRUE.
                END IF
C     
C---- Centrs refinement successful
C     update psix by the refined value of (ccomega-trueccom)
C     and adjust the value of OMEGA0 to reflect the change is PSIX
C     Remember only SINOM0, COSOM0 carried in common ORI
C     
              ENDIF
            ENDIF
 100      ENDDO
          IF (.NOT.NOREFINE)THEN
            IF (ONLINE) WRITE (ITOUT,FMT=6110) PSI,DELPHI
 6110       FORMAT (/,' Starting orientation refinement',/1X,
     $           'Initial MISSETTING Angles ',/1X,'in PSI',
     $           3F8.3,/1X,'in PHI',3F8.3)
            WRITE (IOUT,FMT=6110) PSI,DELPHI
            PSI(1) = PSI(1) + (CCOM - TRUECCOM)
            SPSI(1) = PSI(1)
            SHPSI(1) = CCOM - TRUECCOM
            OMEGA0 = ATAN2(SINOM0,COSOM0) - (CCOM - TRUECCOM)*DTOR
            SINOM0 = SIN(OMEGA0)
            COSOM0 = COS(OMEGA0)
            CCOM = TRUECCOM
          ENDIF
C     
C---- Now generate the big list of reflections to be used
C     in the pattern matching. the mosaic spread is increased
C     to give the specified radius of convergence 'rconv'
C     
        ENDIF
C     .. 
C     Go through this block again if we are repeating the refinement
C     for the beam divergence.
C     
        AGAIN = .TRUE.
        DO 250 WHILE (AGAIN)
          REPEST = .TRUE.
          DONEONCE = .FALSE.
          DO 220 WHILE (REPEST)
          BIGSHIFT = .FALSE.
          AGAIN = .FALSE.
          ETANEW = 2*RCONV
          IFLAG = 0
C     
C---- If refining divergences, set appropriate ETANEW and IFLAG
C     If not refining orientation, start with divergence refinement
C     
          IF (RMOSAIC.AND.NOREFINE) REFETA = .TRUE.
          IF (REFETA) THEN
            ETANEW = ETAMAX
            IFLAG = 4
C     
C---- Must set ETA to zero, so that total (beam divergence + mosaic
C     spread)
C     increases from zero
C     
            ETA = 0.0
          END IF
C     
C     ************************************
          CALL NEWLIST(ETANEW,PSI,PHIAV,RESOL1,IFLAG,IERR)
C     ************************************
C     
          IF (DEBUG(31)) THEN
            NPR = MIN(NSPOT,30)
            IF (ONLINE) WRITE (ITOUT,FMT=6120) (I,XG(I),YG(I),I=1,NPR)
 6120       FORMAT (/,' Coordinates of reflections from REEKE',
     +           / (1X,I3,3X,2F7.1))
            WRITE (IOUT,FMT=6120) (I,XG(I),YG(I),I=1,NPR)
          END IF
C     
C---- Measure intensities of all reflections in the big list
C     first convert film coordinates to sorted scanner coordinates
C     
          MAXR = 1000
          MODE = 6
C     
C     *****************************************************
          CALL GENSORT(MODE,FORCE,LIMIT,VLIM,NRM,ADDPART,LPTMIN,LLAST)
C     *****************************************************
C     
          NBIG = NRM
          WRITE (IOUT,FMT=6130) SHPSI(1),TRUECCOM
 6130     FORMAT ('  PSIX changed by',F6.2,' Degrees and CCOMEGA set to'
     $         ,F6.3)
          IF (ONLINE) WRITE (ITOUT,FMT=6130) SHPSI(1),TRUECCOM
C     
C     
          IF (DEBUG(30)) THEN
            IF (ONLINE) WRITE (ITOUT,FMT=6140) NSPOT,ETANEW,RESOL1,NRM
 6140       FORMAT (/1X,I5,' Spots generated in big list with ETA=',F5.2
     &           ,' Out to',F5.1,' Angstroms',/1X,I5
     &           ,' of these selected by GENSORT')
            WRITE (IOUT,FMT=6140) NSPOT,ETANEW,RESOL1,NRM
          END IF
C     
C---- Now measure reflections
C
CAL         resest = .true.     
C     *******************************************************
          IERR = 0
          CALL MEAS(MAXR,LPROFILE,INTERPOL,IXSHIFT,IYSHIFT,ADDPART,
     +         LPOSTREF,IDDUM,LMULTISEG,lastrec,NEWPREF,NUSPOT,IERR)
C     *******************************************************
C     
CAL         resest = .false.
          IF (DEBUG(31)) THEN
            NPR = MIN(NRM,30)
            IF (ONLINE) WRITE (ITOUT,FMT=6150) (I,XREF(I),YREF(I),I=1
     $           ,NPR)
 6150       FORMAT (/,' Coordinates after storing in XREF,YREF',
     +           / (1X,I3,3X,2I6))
            WRITE (IOUT,FMT=6150) (I,XREF(I),YREF(I),I=1,NPR)
          END IF
C     
C---- Now the fun bit.
C     reset mosaic spread to its correct value.
C     vary first psiz from -rconv to +rconv in steps of
C     rconv/nstep. for each value of psiz, calculate a
C     new reflection list, and go through the big list
C     and pick up the intensity and sd for these reflections.
C     print statistics on number and intensity of
C     reflections lost and gained.
C     repeat the whole procedure varying psiy at the optimum
C     value of psiz.
C     if necessary, iterate the procedure.
C     If refining mosaic spread, then increase divergence(s) from 0
C     to ETAMAX in (2*NSTEP+1) steps
C     
          ETANEW = 0.0
          DELPSI = RCONV/NSTEP
C     
C---- Set error limits for matching reflections to half box size
C     
          IDELX = IRAS(1)*0.5
          IDELY = IRAS(2)*0.5
          IF (REFETA) THEN
            IDELX = (IRAS(1)-2*IRAS(4))*0.5 + 1
            IDELY = (IRAS(2)-2*IRAS(5))*0.5 + 1
          END IF
C     
C     
          DO 120 I = 2,3
            SHPSI(I) = 0.0
 120      ENDDO
C     
C---- For divergence refinement, set number of passes to number of
C     parameters being refined
C     
          IF (REFETA) THEN
            NPASS = 1
            DELETA = ETAMAX/(2*NSTEP)
          END IF
C     ..
C     .. loop around mosaicity estimation (REPEST = REPeat ESTimation),
C     but we need to go through here anyway, which is why we can't just
C     test for MOSEST.
c          REPEST = .TRUE.
c          DONEONCE = .FALSE.
c          DO 225 WHILE (REPEST)
chrp 08.12.2005            REPEST = .FALSE.
            DO 210 IPASS = 1,NPASS
C     
C     
              IF (REFETA) THEN
                WRITE (IOUT,FMT=6160)
 6160           FORMAT (/1X,'Beam divergence refinement') 
                IF (ONLINE) WRITE (ITOUT,FMT=6160)
              ELSE
                WRITE (IOUT,FMT=6170) IPASS
 6170           FORMAT (/1X,'Orientation refinement pass',I3)
                IF (ONLINE) WRITE (ITOUT,FMT=6170) IPASS
C     
C---- Decrease delpsi by factor damp on each pass
C     
                IF (IPASS.NE.1) DELPSI = DELPSI*DAMP
                ETANEW = DELPSI*NSTEP*0.5
              END IF
C     
C     
              DO 200 IYZ = 3,2,-1
C     
C---- Only one parameter (IYZ) if only one beam divergence being refined
C     
                IF (.NOT.REFETA.OR.(NBEAM.NE.1).OR.(IYZ.EQ.3))THEN
                  INTMAX = 0
C     
C     
                  IF (IYZ.EQ.3) THEN
                    SECT = 0.0
                  ELSE
                    SECT = 90.0
                  END IF
C     
C     
                  JSTEP = 0
                  IF (REFETA) ETANEW = -DELETA
C     
C     
                  DO 140 ISTEP = -NSTEP,NSTEP
                    JSTEP = JSTEP + 1
                    XSTEP = (2 * ISTEP) + NSTEP
                    IF (REFETA) THEN
C     
C---- Divergence refinement
C     
                      ETANEW = ETANEW + DELETA
                      ETASTEP(JSTEP) = ETANEW
                      IF (NBEAM.EQ.1) THEN
                        IFLAG = 4
                      ELSE
                        IFLAG = 3 + IYZ
                      END IF
                    ELSE
C     
C---- Orientation refinement
C     
                      PSI(IYZ) = SPSI(IYZ) + ISTEP*DELPSI
                      IFLAG = IYZ
                    END IF

chrp 03.10.2011                    IF(DONEONCE.AND.(ISTEP.LE.0).AND..NOT.(DEBUG(30)))
chrp 03.10.2011      $                   THEN
chrp 03.10.2011                       IF(ISTEP.GT.-NSTEP)THEN
chrp 03.10.2011                         NGL(ISTEP) = NGL(XSTEP) + NGL(XSTEP - 1)
chrp 03.10.2011                       ELSE
chrp 03.10.2011                         NGL(ISTEP) = NGL(XSTEP)
chrp 03.10.2011                       ENDIF
chrp 03.10.2011                       IGN(ISTEP) = IGN(XSTEP)
chrp 03.10.2011                       ISDGN(ISTEP) = ISDGN(XSTEP)
chrp 03.10.2011                      ILO(ISTEP) = ILO(XSTEP)
chrp 03.10.2011                       ISDLO(ISTEP) =  ISDLO(XSTEP)
chrp 03.10.2011                       INTTOT(ISTEP,IYZ) = INTTOT(XSTEP,IYZ)
chrp 03.10.2011                       ISDTOT(ISTEP,IYZ) = ISDTOT(XSTEP,IYZ)
chrp 03.10.2011                         
chrp 03.10.2011                     ELSE
C     
C     **************************************
                      CALL NEWLIST(ETANEW,PSI,PHIAV,RESOL1,IFLAG,IERR)
C     **************************************
C     
                      IF (DEBUG(31)) THEN
                        NPR = MIN(NSPOT,30)
                        IF (ONLINE) WRITE (ITOUT,FMT=6020) 
     &                       (I,XG(I),YG(I),I=1,NPR)
                        WRITE (IOUT,FMT=6020) (I,XG(I),YG(I),I=1,NPR)
                      END IF
C     
C---- Flag reflections outside required sector (secangle around
C     sect=0 for psiz, around sect=90 for psiy refinement.
C     
C     *******************************
                      CALL SECTOR(SECT,SECANGLE,NSPOT,NRJ)
C     *******************************
C     
C---- Match reflections in small list to those in big list
C     
C     ****************************************************
                      CALL REFLMATCH(INT,FVAR,NBIG,NSPOT,NM,IDELX,IDELY
     $                     ,FORCE,LIMIT,VLIM,JSTEP,INTGAIN,ISDGAIN,
     $                     INTLOST,ISDLOST,NGAIN,NLOST,ADDPART,LPTMIN,
     $                     IERR2)
C     ****************************************************
C---- Check if error return due to too many spots lost/gained, change
C     resolution limit and do it again from automatch, but only three
C     times. 
C     
                      IF((IERR2.GE.1000).AND.(IERR2.LE.1002))THEN
                        IERR = IERR2
                        RETURN
                      ENDIF
                      NGL(ISTEP) = NGAIN + NLOST
                      IGN(ISTEP) = INTGAIN
                      ISDGN(ISTEP) = ISDGAIN
                      ILO(ISTEP) = INTLOST
                      ISDLO(ISTEP) = ISDLOST
                      INTTOT(ISTEP,IYZ) = INT/100
                      ISDTOT(ISTEP,IYZ) = SQRT(0.0001*FVAR)
                      MEANINT = 0
                      IF (NM.NE.0) MEANINT = INT/NM
C     
C
                      IF(RMOSAIC.AND.SOCKLO)THEN
                        WRITE(IOLINE,FMT=7000)
     $                       ETASTEP(JSTEP),INTTOT(ISTEP,IYZ)
                        CALL WRITE_SOCKET_LENGTH
     $                       (SERVERFD,LENSTR(IOLINE),IOLINE)
 7000                   FORMAT('<?xml version="1.0"?>',
     $                       '<!DOCTYPE mosaicity_estimation_response>',
     $                       '<mosaicity_estimation_response>',
     $                       '<mosaicity_trial_value>',F5.2,
     $                       '</mosaicity_trial_value>',
     $                       '<total_intensity>',I8,
     $                       '</total_intensity>',
     $                       '</mosaicity_estimation_response>')
                      ENDIF
chrp 03.10.2011                     ENDIF
                    IF (DEBUG(30)) THEN
                      IF (ONLINE) WRITE (ITOUT,FMT=6180) IYZ,ISTEP,PSI,
     $                     NSPOT,RESOL1,NM,IDELX,IDELY,INT,MEANINT,
     $                     SECANGLE,SECT,NRJ
 6180                 FORMAT (1X,'VARY PSI',I2,' ISTEP',I3,/,1X,'PSI',
     &                     3F8.2,' NSPOT',I5,' RESOL1',F5.1,' NMATCH',I5
     $                     ,' DX,DY',2I5,/1X,'Total intensity',I12
     $                     ,' Mean intensity per spot',I8,/,1X
     $                     ,'Number rejected by sector angleof',F5.1
     $                     ,' Degrees at PSI=',F5.0, ' is',I5)
                      WRITE (IOUT,FMT=6180) IYZ,ISTEP,PSI,NSPOT,RESOL1
     $                     ,NM,IDELX,IDELY,INT,MEANINT,SECANGLE,SECT,NRJ
                    END IF
C     
C
                    IF (INT.GE.INTMAX)THEN
                      INTMAX = INT
                      IS = ISTEP
                    ENDIF
 140              ENDDO
C     
C---- Don't attempt to find optimum for mosaic spread refinement
C     
                  IF (.NOT.REFETA)THEN
C---- Now find the best match. starting at the maximum intensity,
C     work outwards to find the two points where there is a
C     significant (gt. 15*sigma) change in the gained/lost
C     intensities.
C     
                    ISTEP = IS + 1
                    ILOST = 0
                    VAR = 0.0
                    SDLO = 99999.99
                    DO 150 WHILE((ISTEP.LE.NSTEP).AND.
     $                   (FLOAT(ILOST).LE.15.0*SDLO))
                      IF (ISTEP.LE.NSTEP) THEN
                        ILOST = ILO(ISTEP) + ILOST
                        VAR = FLOAT(ISDLO(ISTEP)) * 
     $                       FLOAT(ISDLO(ISTEP)) + VAR
                        SDLO = SQRT(VAR)
                        IF (DEBUG(30)) THEN
                          WRITE(IOUT,FMT=6200) ISTEP,ILO(ISTEP),
     $                         ISDLO(ISTEP),IGN(ISTEP),ISDGN(ISTEP),
     $                         ILOST,SDLO
 6200                     FORMAT(1X,'ISTEP=',I2,' intensity lost and sd'
     $                         ,I6,I4,'  Intensity gained and sd',I6,I4,
     $                         /,1X,'Total intensity lost and sd',I6,F5
     $                         .0)
                          IF (ONLINE) WRITE(ITOUT,FMT=6200) ISTEP,
     $                         ILO(ISTEP),ISDLO(ISTEP),IGN(ISTEP),
     $                         ISDGN(ISTEP),ILOST,SDLO
                        END IF
                      ENDIF
                      ISTEP = ISTEP + 1
 150                ENDDO
C     
C---- Significant point found stepping positive, now go negative
C     
                    ISPOS = ISTEP
                    ISTEP = IS
                    VAR = 0.0
                    IGAIND = 0
                    SDGN = 99999.99
                    DO 160 WHILE((ISTEP.GE.- (NSTEP-1)).AND.
     $                   (FLOAT(IGAIND).LE.15.0*SDGN))
                      IGAIND = IGN(ISTEP) + IGAIND
                      VAR = FLOAT(ISDGN(ISTEP)*ISDGN(ISTEP)) + VAR
                      SDGN = SQRT(VAR)
                      IF (DEBUG(30)) THEN
                        WRITE(IOUT,FMT=6200) ISTEP,ILO(ISTEP)
     $                       ,ISDLO(ISTEP),IGN(ISTEP),ISDGN(ISTEP),ILOST
     $                       ,SDLO
                        IF (ONLINE) WRITE(ITOUT,FMT=6200) ISTEP
     $                       ,ILO(ISTEP),ISDLO(ISTEP),IGN(ISTEP)
     $                       ,ISDGN(ISTEP),ILOST,SDLO
                      END IF
                      ISTEP = ISTEP - 1
 160                ENDDO           
                  ENDIF
C     
C---- Find  median
C     
                  ISNEG = ISTEP - 1
                  X = (ISPOS+ISNEG)*0.5
C     
C---- Scale INTTOT if necessary
C     
                  SCALE = 1.0
                  IF(INTMAX.NE.0)SCALE = 9999900/REAL(INTMAX)
C     
C---- Next bit for mosaicity estimation only 
C     
                  IF(MOSEST)THEN
C
C---- Work out gradient in a moving window of 5 points
C
                    DO 174 ISTART = 1,2*NSTEP-3       
C     
C---- work out slope etc here
C     
                      SIGX = 0.0
                      SIGY = 0.0
                      SIGXY = 0.0
                      SIGX2 = 0.0
C
C---- average slope over the five points
C
                      DO 170 ISTEP = ISTART, ISTART+4
                        SIGX = SIGX + ETASTEP(ISTEP)
                        SIGY = SIGY + 
     +                         NINT(SCALE*INTTOT(ISTEP-1-NSTEP,IYZ))
                        SIGXY = SIGXY + (ETASTEP(ISTEP)*
     $                     NINT(SCALE*INTTOT(ISTEP-1-NSTEP,IYZ)))
                        SIGX2 = SIGX2 + (ETASTEP(ISTEP)*ETASTEP(ISTEP))
 170                  ENDDO
                      SLOPEA(ISTART) = MAX(0.0,((SIGX*SIGY)-(5*SIGXY))/
     $                   ((SIGX*SIGX)-(5*SIGX2)))
 174                ENDDO
C
C---- Now set mosaicity to value where the slope has dropped to one tenth
C     of the initial slope
C
                    SLOPE = SLOPEFAC*SLOPEA(1)
                    DO 176 K = 1,2*NSTEP-3
                      IF (SLOPEA(K).LT.SLOPE) THEN
                        MOSNEW = ETASTEP(K)
                        GOTO 182
                      END IF
 176                ENDDO
                    MOSNEW = ETASTEP(2*NSTEP+1)
C
C---- Now set slope to slope for end of the graph, as this value
C     is used for various checks in ESTMOS
C
                    SLOPE = SLOPEA(2*NSTEP-3)
C     
C---  end of slope calculations
C
C
C--- Set a minimum intensity to be 1/8th of the intensity for
C    mosaicity = 0 plus 7/8ths of the maximum intensity
C    
                    INTMIN = NINT((SCALE*INTTOT(-NSTEP,IYZ)/8.0)+
     $                   (700000.0/8.0))
C
C---- Comment out the following, as the interpolation could end up giving
C     a value for mosaicity much greater than ETASTEP(III-1) if the slope
C     is small, leading to a redetermination with a bigger step size and
C     sometimes failure to converge at all.
C
CAL                    DO 180 III=1,2*NSTEP+1
CAL                      IF(INTMIN.LT.NINT(SCALE*INTTOT(III-1-(NSTEP),IYZ)
CAL     $                     +(ETASTEP(III)*SLOPE)).AND.
CAL     $                     (.NOT.INTCHK))THEN
C     
C---  linear interpolation to give estimate of mosaicity
CAL
CAL                        MOSNEW =  ETASTEP(III-1)+ETASTEP(2)*
CAL     $                       (INTMIN-NINT(SCALE*
CAL     $                       INTTOT(III-2-(NSTEP),IYZ)))/
CAL     $                       (NINT(SCALE*INTTOT(III-1-(NSTEP),IYZ)-
CAL     $                       (NINT(SCALE* 
CAL     $                       INTTOT(III-2-(NSTEP),IYZ)))))
CAL                        MOSNEW = (NINT(MOSNEW * 100.0))/100.0
CAL                        INTCHK = .TRUE.
CAL                      ENDIF
CAL 180                ENDDO
C
C
 182                IF (DEBUG(30)) THEN
                      WRITE(IOUT,FMT=6204) INTMIN, MOSNEW,SLOPEFAC,
     +                       0.001*SLOPEFAC*SLOPEA(1),IETAMAX,
     +                       (0.001*SLOPEA(K),K=1,20) 
                      IF (ONLINE) WRITE(ITOUT,FMT=6204) INTMIN,
     +                 MOSNEW,SLOPEFAC,0.001*SLOPEFAC*SLOPEA(1),
     +                 IETAMAX,(0.001*SLOPEA(K),K=1,20)  
 6204                 FORMAT(/,1X,'INTMIN',I8,' estimated mosaic',F9.4,
     +                ' slopefac',F6.2,' slope wanted',F6.1,
     +                ' IETAMAX',I3,'  SLOPE values',/,1X,20F6.1)
                    END IF
                  ENDIF
C     
C---- if the mosaicity is largish, we need to expand the range that we
C     test.
C     Only do this up to 4 degrees!
C     
c                    IF (REFETA) 
                    IF(MOSEST)DELPSI = DELETA
                    IF(ONLINE)THEN
                      WRITE (ITOUT,FMT=6210) PSISTR(IFLAG),DELPSI
                      IF (REFETA) THEN
                        WRITE(ITOUT,FMT=6230) (ETASTEP(JSTEP),
     +                       JSTEP=1,2*NSTEP+1)
                        WRITE(ITOUT,FMT=6250) (NGL(ISTEP),ISTEP = -NSTEP
     $                       ,NSTEP)
                      ELSE
                        WRITE(ITOUT,FMT=6220) 
     $                       (ISTEP,ISTEP = -NSTEP,NSTEP)
                        WRITE(ITOUT,FMT=6240)  
     $                       (NGL(ISTEP),ISTEP = -NSTEP
     $                       ,NSTEP)
                      END IF
                      WRITE(ITOUT,FMT=6260)  
     $                       (NINT(SCALE*INTTOT(ISTEP,IYZ))
     $                     ,ISTEP = -NSTEP,NSTEP)
                      WRITE(ITOUT,FMT=6270)  
     $                       (NINT(SCALE*ISDTOT(ISTEP,IYZ)),
     +                     ISTEP = -NSTEP,NSTEP)
                      write(itout,fmt=6275)scale
                      
                    ENDIF
                    WRITE (IOUT,FMT=6210) PSISTR(IFLAG),DELPSI
                    IF (REFETA) THEN
                      WRITE(IOUT,FMT=6230) (ETASTEP(JSTEP),
     +                     JSTEP=1,2*NSTEP+1)
                      WRITE(IOUT,FMT=6250) (NGL(ISTEP),ISTEP = -NSTEP
     $                     ,NSTEP)
                    ELSE
                      WRITE(IOUT,FMT=6220) (ISTEP,ISTEP = -NSTEP,NSTEP)
                      WRITE(IOUT,FMT=6240) (NGL(ISTEP),ISTEP = -NSTEP
     $                     ,NSTEP)
                    END IF
                    WRITE(IOUT,FMT=6260) (NINT(SCALE*INTTOT(ISTEP,IYZ))
     $                   ,ISTEP = -NSTEP,NSTEP)
                    WRITE(IOUT,FMT=6270) (NINT(SCALE*ISDTOT(ISTEP,IYZ)),
     +                   ISTEP = -NSTEP,NSTEP)
                    write(iout,fmt=6275)scale
 6210               FORMAT (/,' Refining ',A,' with stepsize',F6.2
     $                   ,' Degrees')
 6220               FORMAT(1X,'Step number    ',19I6)
 6230               FORMAT(1X,'Divergence     ',19F6.3)
 6240               FORMAT(1X,'No gained/lost ',19I6)
 6250               FORMAT(1X,'No gained      ',19I6)
 6260               FORMAT(1X,'Total intensity',19I6)
 6270               FORMAT(1X,'SD of intensity',19I6)
 6275               FORMAT(1X,'Intensities scaled by ',F12.3)

                  IF(MOSNEW.GT.0.9*ETAMAX.AND.MOSEST.AND.
     $                 IETAMAX.LE.4)THEN
C
C---- we want to cycle around again
C
                    ETAMAX = ETAMAX*2.0
                    IETAMAX = IETAMAX * 2
                    DELETA = DELETA*2.0
                    INTCHK = .FALSE. 
                    REPEST = .TRUE.
                  ELSE
C
C---- Want to avoid failure if we can, change the slope criterion, 
C     but not > 1
C
                     SLOPEFAC = SLOPEFAC*2.0
C
C---- Finished...
C                      
                    IF(IETAMAX.GT.4)THEN
                      ETAMAX = 1.0
                      IETAMAX = 1
                      DELETA = 0.05
                      INTCHK = .FALSE. 
                      REPEST = slopefac.lt.1
                      MOSEST = slopefac.lt.1
                      if(.not.mosest)mosnew = 999.0
C
C---- IETAMAX too big, so we say that it's failed
C
cal                      MOSNEW = 999.0
                    ELSE
                      MOSEST = .FALSE.
                      REPEST = .FALSE.
                    ENDIF
C
C---- must set INTCHK anyway
C     
                    INTCHK = .TRUE.
                  ENDIF
                  IF(DEBUG(30))THEN
                    write(iout,fmt=6280)(ETASTEP(ISTEP+NSTEP+1),
     +                   NINT(SCALE*INTTOT(ISTEP,IYZ)), 
     +                   ISTEP = -NSTEP,NSTEP)
 6280               format(F8.3,1X,I6)
                  endif
C     
C     
 6290             FORMAT (/,' Optimum step number is ',I3
     $                 ,' Median shift',F5.1,/1X,A,' Old value ',
     $                 F7.2,' New value ',F7.2,'  SHIFT',F6.2)
C     
                  IF (.NOT.REFETA) THEN
                    IF (ONLINE) WRITE (ITOUT,FMT=6290)
     $                   IS,X,PSISTR(IFLAG),SPSI(IYZ),
     $                   SPSI(IYZ) + X*DELPSI,X*DELPSI
                    WRITE (IOUT,FMT=6290) IS,X,PSISTR(IYZ),
     +                   SPSI(IYZ),SPSI(IYZ) + X*DELPSI,X*DELPSI
C     
C---- Update psi angle to optimum value
C     
                    SPSI(IYZ) = SPSI(IYZ) + X*DELPSI
                    SHPSI(IYZ) = SHPSI(IYZ) + X*DELPSI
                    PSI(IYZ) = SPSI(IYZ)
                  ENDIF
                ENDIF
 200          ENDDO
C     
C---- End of loop over two psi angles OR divergences
C     
 210        ENDDO
            DONEONCE = .TRUE.
 220      ENDDO
C     
C---- End of loop over passes
C     
          IF (REFETA)THEN
C     
C---- reset divergences, resolution and mosaic spread and return
C     
            ETA = SETA
            DIVH = SDIVH
            DIVV = SDIVV
            DSTMAX = DSTMAXS
            RETURN
          ELSE
C     
C---- Convert psi to phi
C     
C     ****************************
            CALL PSITOPHI(SPSI,RDELPHI,PHIAV)
C     ****************************
C     
            IF (ONLINE) WRITE (ITOUT,FMT=6300) SPSI,RDELPHI
 6300       FORMAT (/,' FINAL Refined Missetting angles ',/1X,'in PSI',
     $           3F8.3,/1X,'in PHI',3F8.3)
            WRITE (IOUT,FMT=6300) SPSI,RDELPHI
C     
C---- Update stored DELPHI values
C     
            DO 230 I = 1,3
              DELPHI(I) = RDELPHI(I)
 230        ENDDO
C     
C---- If shift in psix or psiy gt 0.6 degrees or rconv/2
C     or if the sum of the three shifts is greater than
C     1.5 degrees or rconv/2, then
C     repeat centrs and refinement at this resolution.
C     
            SHIFTM = MAX(SHPSI(1),SHPSI(2))
            SHIFTT = ABS(SHPSI(1)) + ABS(SHPSI(2)) + ABS(SHPSI(3))
            SHMAXM = MIN(0.5*RCONV,0.75)
            SHMAXT = MIN(0.5*RCONV,1.5)
C     
C     
            IF ((SHIFTM.GE.SHMAXM) .OR. (SHIFTT.GT.SHMAXT)) THEN
              IF (ONLINE) WRITE (ITOUT,FMT=6310) SHIFTM,SHIFTT,SHMAXM,
     $             SHMAXT
 6310         FORMAT (/,' MAX Shift in PSIX,PSIY of',F6.2,' or TOTAL ',
     &             'Shift of',F6.2,' Degrees is greater than allowed ',
     &             'limits of ',F6.2,' and',F6.2,' Degrees',/1X,'Repe',
     &             'at refinement using new orientation')
              WRITE (IOUT,FMT=6310) SHIFTM,SHIFTT,SHMAXM,SHMAXT
              BIGSHIFT = .TRUE.
            END IF
            IF(.NOT.BIGSHIFT)THEN
C     
C---- Repeat at higher resolution if required
C     
              IF ((RESOL2.NE.0.0) .AND. (RESOL2.NE.RESOL1)) THEN
C     
C---- Assume current solution is correct to within 2.0 steps
C     
                IF (ONLINE) WRITE (ITOUT,FMT=6320) RESOL2
 6320           FORMAT (//1X,'Repeat orientation refinement with ', 
     $               'resolution extended to ',F5.1,' Angstroms')
                WRITE (IOUT,FMT=6320) RESOL2
                RCONV = 2.0*DELPSI
                RESOL1 = RESOL2
C     
C---- If total shift is greater than 0.25 degrees, since last CENTRS
C     repeat CENTRS
C     
                SHIFT = 0.0
C     
C     
                DO 240 I = 1,3
                  SHIFT = ABS(RDELPHI(I)-XDELPHI(I)) + SHIFT
 240            ENDDO
C     
C     
                IF (SHIFT.GT.0.25 .AND. (.NOT.NOCENT)) THEN
C     
C---- Calculate resolution based on 'limit'
C     
                  R = LIMIT*1.4142
                  IF (VEE) R = SQRT(LIMIT**2+VLIM**2)
                  TH = ATAN(R/XTOFD)*0.5
                  R = 0.5*WAVE/SIN(TH)
                  IYZ = 0
                  ETANEW = RCONV
C     
C     *******************************
                  CALL NEWLIST(ETANEW,PSI,PHIAV,R,IYZ,IERR)
C     *******************************
C     
                  IF (ONLINE) WRITE (ITOUT,FMT=6330) SHIFT
 6330             FORMAT (/,' Total shift of',F6.2,
     $                 ' Degrees requires NEW CENTRS Refinement')
                  WRITE (IOUT,FMT=6330) SHIFT
C     
C     
                  IF (DEBUG(30)) THEN
                    IF (ONLINE) WRITE (ITOUT,FMT=6340) NSPOT,ETANEW,R
 6340               FORMAT (1X,I5,
     $                   ' Reflections generated with MOSAIC SPREAD ',
     $                   'set to',F5.2,' To resolution limit of',F5.1,
     $                   ' Angstroms')
                    WRITE (IOUT,FMT=6340) NSPOT,ETANEW,R
                  END IF
C     
C---- Initialise variables. Still have to allow partials because
C     enlarged mosaic spread means that there may not be enough
C     fully recorded reflections in central region
C     
                  PARTLS = .TRUE.
CAL                  MINREF = 20
                  REP_40 = .TRUE.
                  REP_20 = .FALSE.
                ELSE
C     
C---- Do not repeat CENTRS if shift less than 0.25
C     
                  BIGSHIFT = .TRUE.
                  AGAIN = .TRUE.
                ENDIF
              END IF
            ENDIF
C     ..
C     .. moved from above
            IF(BIGSHIFT.AND..NOT.AGAIN.AND..NOT.REP_40)THEN
              IF(NOCENT)THEN
                AGAIN = .TRUE.
              ELSE
                REP_20 = .TRUE.
              ENDIF
            ENDIF
C     
C---- Do beam divergence refinement if required
C     
            IF (RMOSAIC.AND..NOT.(REP_20.OR.REP_40)) THEN 
              BIGSHIFT = .TRUE.
              REFETA = .TRUE.
              AGAIN = .TRUE.
            END IF
C     
C---- reset divergences, resolution and mosaic spread
C     
          ENDIF
 250    ENDDO
 260  ENDDO
C
      ETA = SETA
      DIVH = SDIVH
      DIVV = SDIVV
      DSTMAX = DSTMAXS
C     
C     
      RETURN
      END
C     $Id: backstop.f,v 1.32 2021/02/11 11:34:07 andrew Exp $
      SUBROUTINE BACKSTOP(PACK,IMAGEID,IERR)
C
C
C---- simple edge detection using SOBEL operators on a Gaussian smoothed image; 
C     use 3x3 convolution mask
C     to find edges in a test image. This is partly based on common methods
C     of locating edges in photographic images, but the big difference is that 
C     we don't want to find the centre lines of the edges, but those parts
C     which distinguish the outer edge of the features (backstops) from the
C     X-ray background. So it's actually somewhat simpler.
C
C     (1) select the bit of the image around the beam centre we want to look at
C     (2) use a 5x5 Gaussian convolution to smooth a bit
C     (3) use 2 orthogonal 3x3 Sobel masks to determine gradients
C     (4) apply "below threshold suppression" to "zero" regions of low slope.
C     (5) walk in towards the beam centre, record the first point above some
C         threshold.
C     (6) repeat for 8 directions
C     (7) ignore any of these walks that crosses a tile boundary/NULLPIX
C     (8) do a best-fit circle on any points we get
C     (9) check against our points, reject any outliers, repeat (8) & (9) 
C     (10) that's probably about it.
C
C
C---- DEBUG BACKSTOP <NDEBUG>,  DEBUG(80) this routine
C
      IMPLICIT NONE
C     ..
C     .. Scalar arguments
      INTEGER IMAGEID,IERR
      LOGICAL PACK
C     ..
C     .. parameters
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C
C---- size of sub-image we're looking at 
C
      INTEGER SIZEX,SIZEY,NBINS,MinPoints,MinSegs
      parameter (SIZEX = 1024)
      parameter (SIZEY = 1024)
      parameter (NBINS = 32)
      parameter (MinPoints = 25)
      parameter (MINSEGS = 8)
C     ..
C     .. Local scalars
      INTEGER N,IC,JC,KC,LC,MC,NC,OC,QC,PC,RC,SC,TC,XC,YC,NCMITM,NMAX,
     $     NITEMS,IIX,IIY,IIXY,XGRAD,YGRAD,ABSGRAD,NGAUSS,MAXGRAD,
     $     MEANGRAD,IPOINTP1,NGAUSS2,NGAUSSSQ,DIVISOR,NSOBEL,NSOBEL2,
     $     IDEL,HIX,HIY,LOX,LOY,THRESH2,THRESH1,THRESH3,xcoord,
     $     xbeam,ybeam,xbeamlo,ybeamlo,xbeamhi,ybeamhi,ycoord,
     $     MODE,median,STARTX,STARTY,ENDX,ENDY,ipointer,medx,medy,
     $     MAXSLOPE,MINX,MAXX,MINY,MAXY,RANGEX,RANGEY,MAXVAL,MINGAUSS,
     $     octval,SUMGAUSS,THISX,THISY,ISIZE,thismask,IEPS,MEANIEPS,
     $     RMSIEPS,IEPS2,MEANIEPS2,RMSIEPS2,STHETA,direction,ifirst,
     $     olddirection,SIZEX2,SIZEY2,ICIRRAD,POINTER,minptr,MAXPTR,
     $     pixbeg,pixend,thisptr,thisval,diffs,OLDVAL,NLSQ,ICURRENT,
     $     Neighbours,sameline,differentline,length,oldlength,thisarm,
     $     firstx,firsty,lastx,lasty,IXYSTART,AREA,
     $     diagonal,orthogonal,steeper,shallower,ILEDGE,IREDGE,ITEDGE,
     $     IBEDGE,HEIGHT,WIDTH,DISTANCE,LIPROCESS
      REAL thisscore,radius,beamrms,notbeamrms,SLOPE,INTERCEPT,XLSQ,
     $     YLSQ,SUMX,SUMY,SUMXY,SUMXX,SUMYY,FOM,EXPECTED,RASTH,scale,
     $     minbin,BINMIN,percent,oldpercent,minval,firstmax,lastmax,
     $     TEST,IMGAVG,IMGRMS,SIGMA,sumgrad,rmsgrad,cantheta,MEANVAL,
