C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C&&*&& include  ../inc/xy.f
C
C $Id: xy.f,v 1.1 2002/05/02 10:47:25 harry Exp $
C
C--- awk generated include file  xy.h
C---- START of include file xy.h
C
C     .. Scalars in common block /XY/ ..
      REAL XTOFD,SINV,COSV,TANV,TWOTHETA
      INTEGER ICASS
C     ..
C     .. Common Block /XY/ ..
      COMMON /XY/XTOFD,SINV,COSV,TANV,TWOTHETA,ICASS
C     ..
C
C     XTOFD....  Crystal to detector distance in 10 micron units. Read from
C                keyworded input and never changed.
C
C                Spot positions are calculated in S/R XYSPOT (Called from
C                REEK) and are for an "ideal" detector at a distance of XTOFD.
C                These are converted into pixel positions in S/R MMTOPX
C                which applies the multiplicative factor XTOFRA to allow
C                for refinement of the distance. XTOFRA is the parameter
C                that is actually refined (in RDIST), rather than XTOFD.
C                The refined distance that is printed in the logfile is
C                actually XTOFRA*XTOFD
C
C     ICASS....  Indicates detector type:
C                0     Flat film
C                1     Vee shaped cassettes
C                2     FAST detector (only used in TESTGEN mode of OSCGEN)
C                3     Swung out FAST (ditto)
C                4     IP detector
C     TWOTHETA   Detector swing angle (degrees)
C&&*&& end_include  ../inc/xy.f

      DATA SOBELMASK /-1,0,1,-2,0,2,-1,0,1/
      DATA GAUSSMASK /2,4,5,4,2,
     $                4,9,12,9,4,
     $                5,12,15,12,5,
     $                4,9,12,9,4,
     $                2,4,5,4,2/
      DATA SUMGAUSS /159/
C top-hat mask
c      DATA GAUSSMASK /0,10,10,10,0,
c     $                10,10,10,10,10,
c     $                10,10,10,10,10,
c     $                10,10,10,10,10,
c     $                0,10,10,10,0/
c      DATA SUMGAUSS /210/
c Laplacian of Gaussian (LoG) edge detector http://fourier.eng.hmc.edu/e161/lectures/gradient/node10.html
      DATA LOGMASK /0,0,1,0,0,
     $                0,1,2,1,0,
     $                1,2,-16,2,1,
     $                0,1,2,1,0,
     $                0,0,1,0,0/
      DATA PIOVER8 /0.392699081698724139/,
     $     THREEPIOVER8 /1.178097245096172418/,
     $     FIVEPIOVER8 /1.963495408493620697/,
     $     SEVENPIOVER8 /2.748893571891068976/
      INTEGER INTPXL,PUTPXL,LENSTR
      EXTERNAL INTPXL,PUTPXL,LENSTR
      EXTERNAL SORTUP4
      WRITE(IOUT,FMT=6200)
      IF(ONLINE)WRITE(ITOUT,FMT=6200)
 6200 FORMAT(/,60('*'),/,16X,'Trying to find the backstop and arm',
     $     /)
      IF(.NOT.DEBUG(80))THEN
        WRITE (IOUT,FMT=6000)
        IF(ONLINE)WRITE (ITOUT,FMT=6000)
 6000   FORMAT(/,' Sorry, this option is not implemented yet. It may ',
     $       'appear to work,',/,' but as it''s being developed, you ',
     $       'might get unexpected or inappropriate results')
c        RETURN
      ENDIF
      FIRSTTIME = .FALSE.
      LIPROCESS = 4
      SLACTIVEMASK = LACTIVEMASK
      SLACTIVE = LACTIVE
      SFORCEREAD = FORCEREAD
      SREALLYFORCEREAD = REALLYFORCEREAD
C
C---- flags to determine what we're doing and how we do it
C
      CIRCLE = .TRUE.
      OLDCIRCLE = .FALSE.
      LSMOOTH = .TRUE.
      CALL CTIMER(TIMEC)
      COSTWOTHETA = ABS(COS(TWOTHETA*DTOR))
      SINTWOTHETA = ABS(SIN(TWOTHETA*DTOR))
      SIZEX2 = SIZEX/2
      SIZEY2 = SIZEY/2
      NULLPIX = 0
      MAXGRAD = 0
      SUMGRAD = 0.0
      N = 3
      NGAUSS = 5
      NGAUSSSQ = NGAUSS * NGAUSS * 4
      NGAUSS2 = 2
      NSOBEL = 3
      NSOBEL2 = 1
      SIGMA = 2.0
      IMGLOW = 1000000
      IMGHI = -IMGLOW
      XBEAM = XMM(1)/RAST
      YBEAM = YMM(1)/RAST
      IF(INVERTX)XBEAM = NREC - XBEAM
      IF(DEBUG(80))THEN
        WRITE(IOUT,FMT=7000)OMEGAFD,XMM(1),YMM(1)
        IF(ONLINE)WRITE(ITOUT,FMT=7000)OMEGAFD,XMM(1),YMM(1)
 7000   FORMAT('OMEGAFD = ',F6.1,/,'Beam (mm) ',2F8.2,/,
     $       ' (pixels) ',2I8)
      ENDIF
C     ..
C     .. set size of window to make sure it's no bigger than the image
      WIDTH = MIN(SIZEX,NREC)
      HEIGHT = MIN(SIZEY,IYLEN)
      IF(WIDTH.EQ.NREC.AND.HEIGHT.EQ.IYLEN)THEN
        IF(DEBUG(80))THEN
          print*,'both width and height are the same'
        ENDIF
        STARTX = 1
        ENDX = WIDTH
        STARTY = 1
        ENDY = IYLEN
C     ..
C     .. all is well, we use the window as it is the same size as the image
C     
      ELSE
C     ..
C     .. window is smaller than original image
C     ..
C     .. set startX, endX
        IF(XBEAM.GE.WIDTH/2.AND.NREC-XBEAM.GE.WIDTH/2)THEN
          IF(DEBUG(80))THEN
            print*,'the window is smaller than the image in X'
          ENDIF
          STARTX = XBEAM - (WIDTH/2)
          ENDX = XBEAM + (WIDTH/2)
        ELSEIF(XBEAM.LT.WIDTH/2)THEN
          IF(DEBUG(80))THEN
            print*,'the beam is closer to the first edge in X'
          ENDIF
          STARTX = 1
          ENDX = WIDTH
        ELSE
          IF(DEBUG(80))THEN
            print*,'the beam is closer to the last edge in X'
          ENDIF
          STARTX = NREC + 1 - WIDTH
          ENDX = NREC
        ENDIF
C     ..
C     .. set startY, endY
        IF(YBEAM.GE.HEIGHT/2.AND.IYLEN-YBEAM.GE.HEIGHT/2)THEN
        IF(DEBUG(80))THEN
          print*,'the window is smaller than the image in Y'
        ENDIF
          STARTY = YBEAM - (HEIGHT/2)
          ENDY = YBEAM + (HEIGHT/2)
        ELSEIF(YBEAM.LT.HEIGHT/2)THEN
        IF(DEBUG(80))THEN
          print*,'the beam is closer to the first edge in Y'
        ENDIF
          STARTY = 1
          ENDY = HEIGHT
        ELSE
        IF(DEBUG(80))THEN
          print*,'the beam is closer to the last edge in Y'
        ENDIF
          STARTY = IYLEN + 1 - HEIGHT
          ENDY = IYLEN
        ENDIF
      ENDIF
      IF(DEBUG(80))THEN
        print*,''
        print*,'original beam was ', xbeam,ybeam
      ENDIF
      xbeam = xbeam + 1 - startx
      ybeam = ybeam + 1 - starty
      IF(DEBUG(80))THEN
        print*,'adjusted beam is ',xbeam,ybeam
        print*,'nrec =   ',nrec,  ', iylen = ',iylen
        print*,'height = ',height,', width = ',width
        print*,'startx = ',startx,', endx = ',endx
        print*,'starty = ',starty,', endy = ',endy
      ENDIF
      XBEAMLO = xbeam - 8
      YBEAMLO = ybeam - 8
      XBEAMHI = xbeam + 8
      YBEAMHI = ybeam + 8
      RASTH = RAST * 100.0
      ICOLR = 1
c      if(debug(80))then
c        IF(WINOPEN)CALL DSPCRS
c     $       (xbeam,ybeam,1,ICOLR,4)
c        print*,'startx, y = ',startx,starty,' endx, y = ',endx,endy
c      ENDIF
      IPOINTP1 = 0
C
C---- read first N images and pick lowest pixel from each for each location
C
      NMAX = IERR
      IERR = 0
      
      IF(DEBUG(80))THEN
        print*,'IMAGEID, IERR = ',IMAGEID,IERR
        print*,'''Smoothing'' over ',NMAX,' images'
      ENDIF
      CALL CTIMER(TIMEA)
      IIY = IMAGEID+NMAX-1
      DO 10003 IIX=IMAGEID,IIY
        IF(DEBUG(80))THEN
          print*,'cycle ',iix
        ENDIF
        LACTIVE = .FALSE.
        LACTIVEMASK = .FALSE.
        FORCEREAD = .TRUE.
        REALLYFORCEREAD = .TRUE.
        CALL OPENODS(WAXFN,IIX,FILM,ODEXT,FDISK,MODEOP,
     +       PACK,ODFILE,SEPCHAR,FORCEREAD,NIMAG,
     +       TEMPLSTART,TEMPLEND,LIPROCESS,IERR)
        IPOINTER = ((IC+STARTX)*IYLEN)+JC+STARTY
        IF (IIX.EQ.IMAGEID)THEN
          DO 10101 JC=1,WIDTH,1
            DO 10001 IC = 1,HEIGHT,1
              IPOINTER = ((IC+STARTX)*IYLEN)+JC+STARTY
              NATIVE(IC,JC) = INTPXL(IMAGE(IPOINTER))
10001       ENDDO
10101     ENDDO
        ELSEIF (IIX.LT.IIY)THEN
          DO 10100 JC=1,WIDTH,1
            DO 10000 IC = 1,HEIGHT,1
              IPOINTER = ((IC+STARTX)*IYLEN)+JC+STARTY
              NATIVE(IC,JC) = MIN(NATIVE(IC,JC),INTPXL(IMAGE(IPOINTER)))
c              NATIVE(IC,JC) = NATIVE(IC,JC) + INTPXL(IMAGE(IPOINTER))
10000       ENDDO
10100     ENDDO
        ENDIF
C     ..
C     .. last image, copy to ISMOOTH and calculate statistics
        IF (IIX.EQ.IIY)THEN
          CALL CTIMER(TIMEB)
          PXMAX = 0
          SUMGRAD = 0.0
chrp 29.03.2011          IF(DEBUG(80))THEN
            TIMESTRING = 'minimising differences'
            WRITE(IOUT,FMT=6070)
     $           TIMESTRING(1:LENSTR(TIMESTRING)),TIMEB-TIMEA
            IF(ONLINE)WRITE(ITOUT,FMT=6070)
     $           TIMESTRING(1:LENSTR(TIMESTRING)),TIMEB-TIMEA
chrp 29.03.2011          ENDIF
C     ..
C     .. only one image
          IF(IIX.EQ.IMAGEID)THEN
            DO 10302 JC=1,WIDTH,1
              DO 10202 IC = 1,HEIGHT,1
                ISMOOTH(IC,JC) = NATIVE(IC,JC)
                IF (NATIVE(IC,JC).GT.NULLPIX)THEN
                  SUMGRAD =  NATIVE(IC,JC) + SUMGRAD
                  IPOINTP1 = IPOINTP1 + 1
                ENDIF
10202         ENDDO
10302       ENDDO
          ELSE
C     ..
C     .. last of several images
            IF(DEBUG(80))THEN
              print*,'copying last image'
            ENDIF
            DO 10102 JC=1,WIDTH,1
              DO 10002 IC = 1,HEIGHT,1
              IPOINTER = ((IC+STARTX)*IYLEN)+JC+STARTY
                NATIVE(IC,JC) = 
     $               MIN(NATIVE(IC,JC),INTPXL(IMAGE(IPOINTER)))
c                NATIVE(IC,JC) = 
c     $               NATIVE(IC,JC) + INTPXL(IMAGE(IPOINTER))
                ISMOOTH(IC,JC) = NATIVE(IC,JC)
                IF (NATIVE(IC,JC).GT.NULLPIX)THEN
                  SUMGRAD =  NATIVE(IC,JC) + SUMGRAD
                  IPOINTP1 = IPOINTP1 + 1
                ENDIF
10002         ENDDO
10102       ENDDO
            IF(DEBUG(80))THEN
              print*,'copied last image'
            ENDIF
          ENDIF
          SMOOTHFILE = 'canny_001.img'
          if(debug(80).and.ndebug(80).ne.0)
     $         CALL WRITEFILE(SMOOTHFILE,ISMOOTH,1,1,sizex,sizey)
          call ctimer(timea)
chrp 29.03.2011          if(debug(80))THEN
            TIMESTRING = 'sanded image file creation'
            write(iout,fmt=6070)
     $           timestring(1:lenstr(timestring)),timea-timeb
            if(online)write(itout,fmt=6070)
     $           timestring(1:lenstr(timestring)),timea-timeb
chrp 29.03.2011          endif
          
        ENDIF
10003 ENDDO
C
C---- sort and set all pixels in top octile to the max value in the 7th octile
C

      CALL CTIMER(TIMEa)
      CALL SORTUP4(WIDTH*HEIGHT,NATIVE,SORTVAL)
      OCTVAL = (7*WIDTH*HEIGHT)/8
      OCTVAL = SORTED(SORTVAL(OCTVAL))
      MEDIAN = sorted(sortval(WIDTH*HEIGHT/2))
      MEANVAL = INT(SUMGRAD / REAL(IPOINTP1))
      if(debug(80))THEN
        print*,'seventh octile value in this region is ',octval
        print*,'        median value in this region is ',median
        print*,'          mean value in this region is ',meanval
      endif
      PXAVG = 0.0
      PXRMS = 0.0
      PXMAX = 0.0
C
C---- average around beam & excluding beam
C
      BEAMMEAN = 0.0
      BEAMRMS = 0.0
      BEAMDIVISOR = 0.0
      NOTBEAMMEAN = 0.0
      NOTBEAMRMS = 0.0
      NOTBEAMDIVISOR = 0.0
      DO 1010 JC=1,HEIGHT,1
        DO 1000 IC = 1,WIDTH,1
          IF(IC.GE.XBEAMLO.AND.IC.LE.XBEAMHI.AND.
     $         JC.GE.YBEAMLO.AND.JC.LE.YBEAMHI)THEN
            IF (NATIVE(IC,JC).LT.2*OCTVAL)THEN
              BEAMMEAN = BEAMMEAN + NATIVE(IC,JC)
              BEAMRMS = BEAMRMS + NATIVE(IC,JC) * NATIVE(IC,JC)
              BEAMDIVISOR = BEAMDIVISOR + 1
            ENDIF
          ELSE
            IF (NATIVE(IC,JC).LT.2*OCTVAL)THEN
              NOTBEAMMEAN = NOTBEAMMEAN + NATIVE(IC,JC)
              NOTBEAMRMS = NOTBEAMRMS + NATIVE(IC,JC) * NATIVE(IC,JC)
              NOTBEAMDIVISOR = NOTBEAMDIVISOR + 1
            ENDIF
          ENDIF
          
 1000   ENDDO
 1010 ENDDO
      IF (BEAMDIVISOR.GT.0)THEN
        BEAMMEAN = BEAMMEAN/BEAMDIVISOR
        BEAMRMS = BEAMRMS/BEAMDIVISOR - (BEAMMEAN * BEAMMEAN)
        IF (BEAMRMS.GT. 0.0)THEN
          BEAMRMS = SQRT(BEAMRMS)
        ELSE
          BEAMRMS = 0.0
        ENDIF
      ELSE
        BEAMMEAN = 0.0
      ENDIF
      IF (NOTBEAMDIVISOR.GT.0)THEN
        NOTBEAMMEAN = NOTBEAMMEAN/NOTBEAMDIVISOR
        NOTBEAMRMS = NOTBEAMRMS/NOTBEAMDIVISOR - 
     $       (NOTBEAMMEAN * NOTBEAMMEAN)
        IF ( NOTBEAMRMS.GT. 0.0)THEN
           NOTBEAMRMS = SQRT( NOTBEAMRMS)
        ELSE
           NOTBEAMRMS = 0.0
        ENDIF
      ELSE
        NOTBEAMMEAN = 0.0
      ENDIF

      if(debug(80).and.ndebug(80).ne.0)
     $     CALL WRITEFILE(SMOOTHFILE,ISMOOTH,1,1,SIZEX,SIZEY)
      SUMGRAD = 0.0
      RMSGRAD = 0.0
      MEANGRAD = 0
      HIX = WIDTH - NGAUSS2
      HIY = HEIGHT - NGAUSS2
      LOX = NGAUSS - NGAUSS2
      LOY = NGAUSS - NGAUSS2
      if(debug(80))
     $     print*,'Gauss: LOX = ',lox,', HIX = ',hix,' LOY = ',loy,
     $     ' HIY = ',hiy
      call ctimer(timeb)
chrp 29.03.2011      IF(DEBUG(80))THEN
        TIMESTRING = 'Initial sort'
        WRITE(IOUT,FMT=6070)
     $       TIMESTRING(1:LENSTR(TIMESTRING)),TIMEB-TIMEA
        IF(ONLINE)WRITE(ITOUT,FMT=6070)
     $       TIMESTRING(1:LENSTR(TIMESTRING)),TIMEB-TIMEA
chrp 29.03.2011      ENDIF
C
      IF(.NOT.LSMOOTH)THEN
        DO 1030 JC = 1,5
          DO 1020 IC = 1,5
            GAUSSMASK(IC,JC) = 0
 1020     ENDDO
 1030   ENDDO
        GAUSSMASK(3,3) = SUMGAUSS
      ENDIF
c      goto 12345

      DO 1070 jC=1,HEIGHT,1
        DO 1060 iC=1,WIDTH,1
C
C---- Gaussian smooth
C
C     (i) treat image edges properly
C     (ii) avoid NULLPIX
C     (iii) replace strong pixels with either MEAN or 7th octile value
C
            SMOOTH = 0
            DIVISOR = SUMGAUSS
            IF(NATIVE(IC,JC).LE.NULLPIX)THEN
              WORK_ONE(IC,JC) = NULLPIX
            ELSE
C
C---- find median value in this box
C
              THISPTR = 0
              DO 1055 IX = -NGAUSS2,NGAUSS2,1
                THISX = IC + IX
                DO 1045 IY = -NGAUSS2,NGAUSS2,1

                  THISY = JC + IY
                  IF(THISX.GE.1.AND.THISX.LE.WIDTH.AND.
     $                 THISY.GE.1.AND.THISY.LE.HEIGHT)THEN
                    THISPTR = THISPTR + 1
                    MASK(THISPTR) = 
     $                   MIN(INT(NOTBEAMMEAN),NATIVE(THISX,THISY))
                    
                  ENDIF
 1045           ENDDO
 1055         ENDDO
c              CALL SORTUP4(thisptr,MASK,SORTVAL)
c              IF(SORTVAL(THISPTR)/2.GT.0)THEN
c                THISPTR = 2*SORTVAL(THISPTR)/8
c                IF(THISPTR.GT.0)MEDIAN = MASK(THISPTR)
c                if(median.ge.0) meanval = median
c              ENDIF
              DO 1050 IX = -NGAUSS2,NGAUSS2,1
                THISX = IC + IX
                DO 1040 IY = -NGAUSS2,NGAUSS2,1
                  THISY = JC + IY
                  thismask =  GAUSSMASK(IX+NGAUSS2+1,IY+NGAUSS2+1)
                  IF(THISX.GE.1.AND.THISX.LE.WIDTH.AND.
     $                 THISY.GE.1.AND.THISY.LE.HEIGHT)THEN
                    IF(NATIVE(THISX,THISY).NE.NULLPIX)THEN 
                      IF(NATIVE(THISX,THISY).LT.meanVAL)THEN
                        SMOOTH = SMOOTH +
     $                       (NATIVE(THISX,THISY) *
     $                      thismask)
                      ELSE
                        DIVISOR = DIVISOR - 
     $                       thismask
                      ENDIF
                    ELSE
                      DIVISOR = DIVISOR - 
     $                     thismask
                    ENDIF
                  ELSE
                    DIVISOR = DIVISOR - thismask
                  ENDIF
 1040           ENDDO
 1050         ENDDO
              IF(DIVISOR.GT.0)THEN
                WORK_ONE(IC,JC) = SMOOTH/DIVISOR
              ELSE
C     
C---- I hope this should never happen!
C
                WORK_ONE(IC,JC) = MIN(NATIVE(IC,JC),int(meanval))
              ENDIF
            ENDIF
          ISMOOTH(IC,JC) = WORK_ONE(IC,JC)
          pxmax = max(int(pxmax), WORK_ONE(IC,JC))
          PXAVG = PXAVG + WORK_ONE(IC,JC)
          PXRMS = PXRMS + WORK_ONE(IC,JC) * WORK_ONE(IC,JC)
 1060   enddo
 1070 enddo
C
      IF (IPOINTP1.GT.0) THEN
        PXAVG = PXAVG/IPOINTP1
        PXRMS = PXRMS/IPOINTP1 - PXAVG * PXAVG
        IF (PXRMS .GE. 0.0) THEN
          PXGAIN = PXRMS/PXAVG
          PXRMS = SQRT(PXRMS)
        ELSE
          PXRMS = 0.0
          PXGAIN = 1.0
        ENDIF   
      ENDIF
c      print*,'beam mean is now ',beammean
c      print*,'beamdivisor is ',beamdivisor
      IMGMAX = 0
      do 9999 jc=1,height
        do 9998 ic=1,width
          DIVISOR = 49
          IMGAVG = 0.0
          IMGRMS = 0.0
          do 9997 iy = -3,3,1
            thisy = jc + iy
            do 9996 ix = -3,3,1
              thisx = ic + ix
              IF(THISX.GE.1.and.THISX.LE.WIDTH.and.
     $             THISY.GE.1.and.THISY.LE.HEIGHT.AND.
     $             WORK_ONE(IC,JC).GT.NULLPIX)THEN
                IF(WORK_ONE(THISX,THISY).GT.NULLPIX)THEN
                  IMGAVG = IMGAVG +
     $                 WORK_ONE(THISX,THISY)
                  IMGRMS = IMGRMS +
     $                 (WORK_ONE(THISX,THISY) *
     $                 WORK_ONE(THISX,THISY))
                ELSE
                  DIVISOR = DIVISOR - 1
                ENDIF
              ELSE
                DIVISOR = DIVISOR - 1
              ENDIF
 9996       enddo
 9997     enddo
          IF(DIVISOR.GT.0)THEN
            IMGAVG = IMGAVG/DIVISOR
            IMGRMS = (IMGRMS/DIVISOR) - (IMGAVG * IMGAVG)
          ELSE
            IMGAVG = IMGAVG/49
            IMGRMS = (IMGRMS/49) - (IMGAVG * IMGAVG)
          ENDIF
          IF(IMGRMS.GT.0)THEN
            IMGRMS = SQRT(IMGRMS)
          ELSE
            IMGRMS = 0.0
          ENDIF
          SOBEL(IC,JC) = INT(IMGRMS)
          IF(IMGMAX.LT.IMGRMS)IMGMAX = IMGRMS
 9998   enddo
 9999 enddo
      SMOOTHFILE = 'canny_004.img'
      if(debug(80).and.ndebug(80).ne.0)
     $     CALL WRITEFILE(SMOOTHFILE,ISMOOTH,1,1,SIZEX,SIZEY)
C
C---- use stats to remove outliers
C
      do 9995 jc=1,height
        do 9994 ic = 1,width
          work_two(ic,jc) = min(int(work_one(ic,jc)),
     $         max(int(notbeammean-(1*notbeamrms)),
     $         int(beammean+(2*beamrms))))
          ismooth(ic,jc) = work_two(ic,jc)
 9994   enddo
 9995 enddo
      SMOOTHFILE = 'canny_005.img'
      if(debug(80).and.ndebug(80).ne.0)
     $     CALL WRITEFILE(SMOOTHFILE,ISMOOTH,1,1,SIZEX,SIZEY)
      if(debug(80))then
        print*,'Average, RMS and Gain = ',PXAVG,PXRMS,PXGAIN
        print*,'Gain for this detector should be ',GAIN
        print*,'For the region around the beam:'
        print*,'Average and RMS = ',beammean,beamrms
        print*,'Excluding this region:'
        print*,'Average and RMS = ',notbeammean,notbeamrms
      endif
      call ctimer(timea)
chrp 29.03.2011      if(debug(80))THEN
        TIMESTRING = 'Smoothing'
        write(iout,fmt=6070)
     $       timestring(1:lenstr(timestring)),timea-timeb
        if(online)write(itout,fmt=6070)
     $       timestring(1:lenstr(timestring)),timea-timeb
chrp 29.03.2011      endif

      timeb = timea
C
C---- test code to see how we can use image statistics to make things better
C
C need to work out a suitable value for lower and upper thresholds - 
C     histogram
      IF(DEBUG(80))THEN
        print*,'FIRST HISTOGRAM: values on image'
        print*,'         Bin   number    (smoothed)',
     $       '      max value       cumulative %    total ',
     $       'pixels'
      ENDIF
      SCALE = REAL(NBINS-1)/PXMAX
      PERCENT = 0.0
      THISVAL = 0
      DO 1080 IC = 1,NBINS
        HISTOGRAM(IC) = 0
 1080 ENDDO
      DO JC=1,WIDTH
        DO IC=1,HEIGHT
          HISTOGRAM(INT(1+WORK_ONE(IC,JC)*SCALE)) = 
     $         HISTOGRAM(INT(1+WORK_ONE(IC,JC)*SCALE)) + 1
        ENDDO
      ENDDO
C
C---- find minima in histogram - currently not used?
C
      MINPTR = 0
      MINVAL = 9999999.9
      lthresh1 = .false.
      lthresh2 = .false.
      DO 1090 IC = 1,NBINS
        PERCENT = PERCENT + (100.0*(REAL(HISTOGRAM(IC))/(WIDTH*HEIGHT)))
        THISVAL = THISVAL + HISTOGRAM(IC)
        IF (IC.LE.2.OR.IC.GT.NBINS-2)THEN
          IF(DEBUG(80))THEN
            PRINT*,IC,HISTOGRAM(IC),HISTOGRAM(IC),IC/SCALE,PERCENT,
     $           THISVAL
          ENDIF
        ELSE
          MINBIN = ((2*HISTOGRAM(IC)) + 
     $         HISTOGRAM(IC-1) + HISTOGRAM(IC+1))/4
          IF (MINBIN.NE.0)THEN
            IF(MINBIN.LT.MINVAL.AND.IC/SCALE.GT.BEAMMEAN)THEN
              MINVAL = MINBIN
              MINPTR = IC
            ENDIF
            IF(DEBUG(80))THEN
              PRINT*,IC,HISTOGRAM(IC),MINBIN,
     $             IC/SCALE,PERCENT,THISVAL
            ELSE
              
              IF(DEBUG(80))THEN
                PRINT*,IC,HISTOGRAM(IC),MINBIN,
     $               IC/SCALE,PERCENT,THISVAL
              ENDIF
            ENDIF
          ENDIF

        ENDIF
        IF(PERCENT.GT.50.0.and..not.lthresh2)then
          thresh2 = ic/scale
          lthresh2 = .true.
          IF(DEBUG(80))THEN
            print*,'setting thresh2 to ',thresh2,ic,scale
          endif
        ENDIF
        IF(PERCENT.GT.99.0.and..not.lthresh1)then
          thresh1 = ic/scale
          lthresh1 = .true.
          IF(DEBUG(80))THEN
            print*,'setting thresh1 to ',thresh1,ic,scale
          endif
        ENDIF
 1090 ENDDO
      IF(DEBUG(80))THEN
        print*,'thresh1 = ',thresh1,', thresh2 = ',thresh2
      ENDIF
      do 1092 JC=1,HEIGHT,1
        DO 1091 IC=1,WIDTH,1
          work_two(ic,jc) = min(work_two(ic,jc),thresh2)
          ismooth(ic,jc) = work_two(ic,jc)
 1091   ENDDO
 1092 ENDDO
      SMOOTHFILE = 'canny_006.img'
      if(debug(80).and.ndebug(80).ne.0)
     $     CALL WRITEFILE(SMOOTHFILE,ISMOOTH,1,1,SIZEX,SIZEY)
C
C---- end Gaussian smooth
C
C
C---- apply Sobel gradient masks in both X and Y, then obtain overall gradient
C
      HIX = WIDTH - NSOBEL2
      HIY = HEIGHT - NSOBEL2
      LOX = NSOBEL - NSOBEL2
      LOY = NSOBEL  - NSOBEL2
      if(debug(80))then
        print*,'Sobel: LOX = ',lox,', HIX = ',hix,' LOY = ',loy,
     $       ' HIY = ',hiy
        print*,'Sobel: NSOBEL = ',nsobel,', nsobel2 = ',nsobel2
      endif
      DO 1190 JC=1,HEIGHT,1
        DO 1180 IC=1,WIDTH,1
          absgrad = 0
          XGRAD = 0
          YGRAD = 0
          IF(((IC.GT.LOX).AND.(IC.LT.HIX).AND.(JC.GT.LOY)
     $         .AND.(JC.LT.HIY)).AND.WORK_TWO(IC,JC).NE.NULLPIX)
     $         THEN
            DO 1170 IX = -NSOBEL2,NSOBEL2,1
              DO 1160 IY = -NSOBEL2,NSOBEL2,1
                IF(WORK_TWO(IC+IX,JC+IY)
     $               .GT.NULLPIX)THEN
                  XGRAD = XGRAD + 
     $                 (WORK_TWO(IC+IX,JC+IY)
     $                 * SOBELMASK(IX+NSOBEL2+1,IY+NSOBEL2+1))
                  YGRAD = YGRAD + 
     $                 (WORK_TWO(IC+IX,JC+IY)
     $                 * SOBELMASK(IY+NSOBEL2+1,IX+NSOBEL2+1))
                ELSE
C
C---- need to do something for edge of tile effects, since dead areas should not
C     contribute to the slope calculations.
C
C
C---- Step in X
C
                  IIX = IC + IX
                  IIY = 1
                  DO 1140 WHILE (IIY.LT.10)
                    IF(WORK_TWO(IIX+1,JC+IY).GT.NULLPIX)THEN
                      IIX = IIX + 1
                    ELSEIF(WORK_TWO(IIX-1,JC+IY).GT.NULLPIX)THEN
                      IIX = IIX - 1
                    ENDIF
                    IF (WORK_TWO(IIX,JC+IY).GT.NULLPIX)THEN
                      XGRAD = XGRAD + 
     $                     (WORK_TWO(IIX,JC+IY) * 
     $                     SOBELMASK(IX+NSOBEL2+1,IY+NSOBEL2+1))
                      YGRAD = YGRAD + 
     $                     (WORK_TWO(IIX,JC+IY) *
     $                     SOBELMASK(IY+NSOBEL2+1,IX+NSOBEL2+1))
                      IIY = 20
                    ELSE
                      IIY = IIY + 1
                    ENDIF
 1140             ENDDO
C
C---- Step in Y
C
                  IF(IIY.LT.20)THEN
                    IIY = JC + IY
                    IIX = 1
                    DO 1150 WHILE(IIX.LT.10)
                      IF(WORK_TWO(IC+IX,IIY+1).GT.NULLPIX)THEN
                        IIY = IIY + 1
                      ELSEIF(WORK_TWO(IC+IX,IIY-1).GT.NULLPIX)THEN
                        IIY = IIY - 1
                      ENDIF
                      IF (WORK_TWO(IX+IC,IIY).GT.NULLPIX)THEN
                        XGRAD = XGRAD + 
     $                       (WORK_TWO(IC+IX,IIY) *
     $                       SOBELMASK(IX+NSOBEL2+1,IY+NSOBEL2+1))
                        YGRAD = YGRAD + 
     $                       (WORK_TWO(IC+IX,IIY) *
     $                       SOBELMASK(IY+NSOBEL2+1,IX+NSOBEL2+1))
                        IIX = 20
                      ELSE
                        IIX = IIX + 1
                      ENDIF
 1150               ENDDO
                  ENDIF
                ENDIF
 1160         ENDDO
 1170       ENDDO
            ABSGRAD = ABS(XGRAD) + ABS(YGRAD)
            SOBEL(IC,JC) = ABSGRAD
            IF(ABSGRAD.GT.NULLPIX + 5)THEN
              IF(XGRAD.EQ.0)THEN
                IF(YGRAD.EQ.0)THEN
                  RTHETA = 0
                ELSE
                  RTHETA = PI/2.0D0
                ENDIF
              ELSE
                RTHETA = ATAN2(REAL(YGRAD),REAL(XGRAD))
              ENDIF
C
C---- store edge directions
C
              IF(RTHETA.GT.TWOPI)RTHETA = RTHETA - PI
              IF(RTHETA.LT.0.0)RTHETA = RTHETA + PI
              IF(((RTHETA.GE.0).AND.(RTHETA.LT.PIOVER8)).OR.
     $             ((RTHETA.GE.SEVENPIOVER8).AND.(RTHETA.LE.TWOPI)))THEN
                ITHETA(IC,JC) = 1
              ELSEIF((RTHETA.GE.PIOVER8).AND.(RTHETA.LT.THREEPIOVER8))
     $               THEN
                ITHETA(IC,JC) = 2
              ELSEIF((RTHETA.GE.THREEPIOVER8).AND.
     $               (RTHETA.LT.FIVEPIOVER8))THEN
                ITHETA(IC,JC) = 3
              ELSEIF((RTHETA.GE.FIVEPIOVER8).AND.
     $               (RTHETA.LT.SEVENPIOVER8))THEN
                ITHETA(IC,JC) = 4
              ELSE
                ITHETA(IC,JC) = 0
              ENDIF
            ELSE
              ITHETA(IC,JC) = 0
            ENDIF
          ELSE
            ABSGRAD = 0
            SOBEL(IC,JC) = NULLPIX
          ENDIF
C
C---- 
C
          IF(ABSGRAD.GT.MAXGRAD)MAXGRAD = ABSGRAD
          SUMGRAD = SUMGRAD + ABSGRAD
          RMSGRAD = RMSGRAD + ABSGRAD * ABSGRAD
          ISMOOTH(IC,JC) = SOBEL(IC,JC)
 1180   ENDDO
 1190 ENDDO
      SMOOTHFILE = 'canny_008.img'
      if(debug(80).and.ndebug(80).ne.0)
     $     CALL WRITEFILE(SMOOTHFILE,ISMOOTH,1,1,SIZEX,SIZEY)
      if(debug(80))
     $     print*,'sum of gradients is ',sumgrad,', mean is ',
     $     MEANgrad,' rms is ',rmsgrad
      call ctimer(timeb)
chrp 29.03.2011      if(debug(80))THEN
        TIMESTRING = 'Gradient masks'
        write(iout,fmt=6070)
     $       timestring(1:lenstr(timestring)),timeb-timea
        if(online)write(itout,fmt=6070)
     $       timestring(1:lenstr(timestring)),timeb-timea
chrp 29.03.2011      endif
      timeb = timea
      MEANGRAD = SUMGRAD/(WIDTH*HEIGHT)
      rmsgrad = rmsgrad/(width*height) - meangrad*meangrad
      if (rmsgrad.gt.0.0)then
        rmsgrad = sqrt(rmsgrad)
      else
        rmsgrad = 0.0
      endif
      if(debug(80))THEN
        print*,'sumgrad = ',sumgrad
        print*,'maximum gradient is ',maxgrad,', mean is ',
     $       MEANgrad,' rms is ',rmsgrad
        print*,'twotheta is ',twotheta
      ENDIF
C     
C---- Now perform "non-maximal suppression", i.e. set all pixels to "zero" 
C     that are not on the top of a ridge.
C 
C step (1) set all pixels below T1 to NULLPIX 
C
C need to work out a suitable value for lower and upper thresholds - 
C     histogram
      SCALE = REAL(NBINS-1)/REAL(MAXGRAD)
      DO 1200 IC = 1,NBINS
        HISTOGRAM(IC) = 0
 1200 ENDDO
      DO 1220 JC=1,SIZEX
        DO 1210 IC=1,SIZEY
          HISTOGRAM(max(1,INT(1+SOBEL(IC,JC)*SCALE))) = 
     $         HISTOGRAM(max(1,INT(1+SOBEL(IC,JC)*SCALE))) + 1
 1210   ENDDO
 1220 ENDDO

C
C---- find thresholds from histogram
C
      if(debug(80))then
        PRINT*,'SECOND HISTOGRAM: Values in lines, ',
     $       'searching for Canny thresholds'
        print*,'         Bin   number    (smoothed)',
     $       '      min value   found?  cumulative % edge value'
      endif
      MINVAL = 9999999.9
      MINPTR = 0
      MINFOUND = .FALSE.
      PERCENT = 0.0
      lthresh1 = .false.
      lthresh2 = .false.
      DO 1230 IC = 1,NBINS
        OLDPERCENT = PERCENT
        PERCENT = PERCENT + 100.0*REAL(HISTOGRAM(IC))/(WIDTH*HEIGHT)
        IF (IC.EQ.1.OR.IC.EQ.NBINS)THEN
          MINBIN = HISTOGRAM(IC)
        ELSE
          MINBIN = ((2 * HISTOGRAM(IC)) + 
     $         HISTOGRAM(IC-1) + HISTOGRAM(IC+1))/4
        ENDIF
        if(debug(80))then
          PRINT*,IC,HISTOGRAM(IC),MINBIN,MINVAL,MINFOUND,
     $         percent,IC/SCALE
        ENDIF
C
C---- make sure LTHRESH2 is set before LTHRESH1
C
        IF(PERCENT.GT.99.5.AND..NOT.LTHRESH1.AND.LTHRESH2)THEN
          THRESH1 = IC/SCALE
C     ..
C     .. linear interpolation
          thresh1 = 
     $         ic/scale - (1.0/scale * (percent - 99.5)/
     $         (percent-oldpercent))
          LTHRESH1 = .TRUE.
        ENDIF
        IF(PERCENT.GT.98.5.AND..NOT.LTHRESH2)THEN
          THRESH2 = IC/SCALE
C     ..
C     .. linear interpolation
          thresh2 = 
     $         ic/scale - (1.0/scale * (percent - 98.5)/
     $         (percent-oldpercent))
          LTHRESH2 = .TRUE.
        ENDIF
C     ..
C     .. first minimum - do we use this for anything?
        IF(MINBIN.LT.MINVAL.AND..NOT.MINFOUND)THEN
          MINVAL = MINBIN
          MINPTR = IC
        ELSE
          MINFOUND = .true.
        ENDIF
 1230 ENDDO
C     ..
C     ..
      MINVAL = 0.0
      MINFOUND = .false.
      MAXFOUND = .false.
      DO 1240 IC = NBINS,MINPTR,-1
        IF (IC.EQ.1.OR.IC.EQ.NBINS)THEN
          MINBIN = HISTOGRAM(IC)
        ELSE
          MINBIN = ((2 * HISTOGRAM(IC)) + 
     $         HISTOGRAM(IC-1) + HISTOGRAM(IC+1))/4
        ENDIF
C     ..
C     .. last minimum
        IF(MINBIN.LT.MINVAL)THEN
          MAXFOUND = .TRUE.
        ELSE
          MINVAL = MINBIN
        ENDIF
        IF(MAXFOUND)THEN
          IF(MINBIN.LT.MINVAL.AND..NOT.MINFOUND)THEN
            MINVAL = MINBIN
c            THRESH1 = IC/SCALE
          ELSE
            MINFOUND = .TRUE.
          ENDIF
        ENDIF
 1240 ENDDO
      if(debug(80))then
        print*,'Non-maximal suppression'
        print*,'thresh1 = ',thresh1,', thresh2 = ',thresh2
      ENDIF
      DO 1280 JC=1,HEIGHT,1
        DO 1270 IC=1,WIDTH,1
          IF(SOBEL(IC,JC).GE.THRESH1)THEN
c          IF(SOBEL(IC,JC).GE.2.0*rmsgrad)THEN
            
            NMSUPPRESS(IC,JC) = SOBEL(IC,JC)
            LOGLINE(IC,JC) = .TRUE.
          ELSEIF(SOBEL(IC,JC).GE.THRESH2)THEN
            DO 1260 KC = -1,1,1
              DO 1250 LC = -1,1,1
                IF(LOGLINE(IC+KC,JC+LC))THEN
                  NMSUPPRESS(IC,JC) = SOBEL(IC,JC)
                  LOGLINE(IC,JC) = .TRUE.
                ENDIF
 1250         ENDDO
 1260       ENDDO
          ELSE
            NMSUPPRESS(IC,JC) = NULLPIX
            LOGLINE(IC,JC) = .FALSE.
          ENDIF
          ISMOOTH(IC,JC) = NMSUPPRESS(IC,JC)
 1270   ENDDO
 1280 ENDDO
      call ctimer(timea)
chrp 29.03.2011      if(debug(80))THEN
        TIMESTRING = 'Non-maximal suppression'
        write(iout,fmt=6070)
     $       timestring(1:lenstr(timestring)),timea-timeb
        if(online)write(itout,fmt=6070)
     $       timestring(1:lenstr(timestring)),timea-timeb
chrp 29.03.2011      endif
      timeb = timea
      SMOOTHFILE = 'canny_009.img'
      if(debug(80).and.ndebug(80).ne.0)
     $     CALL WRITEFILE(SMOOTHFILE,ISMOOTH,1,1,SIZEX,SIZEY)
      SMOOTHFILE = 'canny_010.img'
      if(debug(80).and.ndebug(80).ne.0)
     $     CALL WRITEFILE(SMOOTHFILE,Itheta,1,1,SIZEX,SIZEY)
C
C step (2) this is where we deviate from Canny edge detection. We don't want the 
C     top of the ridge, we want the bottom edge on the outside of the backstop.
C     This is rather simpler than Canny - we just start at the
C     beam centre and walk out, a pixel at a time...
C
C---- now locate the circular backstop using the beam centre as a reference. 
C
C     loop over 8 directions, start at current beam centre...
C
      IIXY = 0
c
c---- initialize edge array
c      
      DO 1290 IC = 1,8,1
        EDGE(1,IC) = 0
        EDGE(2,IC) = 0
        SUMEPS(IC) = 0.0
 1290 ENDDO
      DO 1360 JC = -1,1,1
        DO 1350 IC = -1,1,1
          XCOORD = XBEAM
          YCOORD = YBEAM
          FOUNDEDGE = .FALSE.
          NOTFOUND = .FALSE.
          MINGAUSS = WORK_ONE(XCOORD,YCOORD)
          IF(IC.NE.0.OR.JC.NE.0)THEN
C
C---- first make sure we avoid a hollow backstop
C
            DO 1300 WHILE((XCOORD.GE.1.AND.XCOORD.LE.WIDTH.AND.
     $               YCOORD.GE.1.AND.YCOORD.LE.HEIGHT))
              IF(WORK_ONE(XCOORD,YCOORD).LT.MINGAUSS.AND.
     $             WORK_ONE(XCOORD,YCOORD).GT.NULLPIX)THEN
                MINGAUSS = WORK_ONE(XCOORD,YCOORD)
              ENDIF
              XCOORD = XCOORD - IC
              YCOORD = YCOORD - JC 
 1300       ENDDO
C
C---- reset XCOORD, YCOORD
C
            XCOORD = XBEAM
            YCOORD = YBEAM
C
C---- look for a minimum in the background
C
            ICOLR = 2
            DO 1310 WHILE (.NOT.FOUNDEDGE.AND..NOT.NOTFOUND)
              IF(WORK_ONE(XCOORD,YCOORD).GT.MINGAUSS)THEN
              ELSE
                FOUNDEDGE = .TRUE.
              ENDIF
              XCOORD = XCOORD - IC
              YCOORD = YCOORD - JC 
              IF (XCOORD.LT.1.OR.XCOORD.GT.WIDTH.OR.
     $             YCOORD.LT.1.OR.YCOORD.GT.HEIGHT)NOTFOUND = .TRUE.          
 1310       ENDDO
              
C
C---- look for the maximum in the slope
C
            MAXSLOPE = RMSGRAD
            NOTFOUND = .FALSE.
            FOUNDEDGE = .FALSE.
            HIGHER = .FALSE.
            MAXX = 1
            MAXY = 1
            ICOLR = 3
            DO 1320 WHILE (.NOT.NOTFOUND)
              IF(NMSUPPRESS(XCOORD,YCOORD).GT.MAXSLOPE)THEN
                  MAXX     = XCOORD
                  MAXY     = YCOORD
                  HIGHER = .TRUE.
              ELSE
              ENDIF
C
C---- keep looking if we reach a tile edge, since this will distort the circle
C
              IF(WORK_ONE(XCOORD,YCOORD).LE.NULLPIX)THEN
                FOUNDEDGE = .false.
C
C---- stop looking if we get close to the edge of the area, and avoid edge effects
C
              ENDIF
              XCOORD = XCOORD - IC
              YCOORD = YCOORD - JC 
              IF((XCOORD.LT.5.OR.YCOORD.LT.5.OR.
     $             XCOORD.GT.WIDTH-4.OR.YCOORD.GT.HEIGHT-4))
     $             NOTFOUND = .TRUE.
 1320       ENDDO
            IF(HIGHER)FOUNDEDGE = .TRUE.
            XCOORD = mAXX
            YCOORD = MAXY
C
C---- having found a peak in the slope (which should be the steepest slope associated 
C     with the beamstop), we then want to keep going out until we reach the 
C     background. 
C
            NOTFOUND = .FALSE.
            FOUNDEDGE = .FALSE.
            ICOLR = 4
            isize = 1
            MAXSLOPE = nullpix + 5
            DO 1330 WHILE (.NOT.FOUNDEDGE.AND..NOT.NOTFOUND)
c              IF(rmsGRAD.GT.NMSUPPRESS(XCOORD,YCOORD))THEN
              IF(maxslope.Ge.NMSUPPRESS(XCOORD,YCOORD))THEN
                MAXVAL   = WORK_ONE(XCOORD,YCOORD)
                MAXX     = XCOORD
                MAXY     = YCOORD
                FOUNDEDGE = .TRUE.
              ENDIF
              XCOORD = XCOORD - IC
              YCOORD = YCOORD - JC 
              IF (XCOORD.LE.1.OR.XCOORD.GE.WIDTH.OR.
     $             YCOORD.LE.1.OR.YCOORD.GE.HEIGHT)then
                NOTFOUND = .TRUE. 
              endif
 1330       ENDDO
            IF(FOUNDEDGE)THEN
C
C---- avoid duplicates
C
              DO 1340 IIX = 1,IIXY,1
                IF((EDGE(1,IIX).EQ.MAXX+startx).AND.
     $               (EDGE(2,IIX).EQ.MAXY+starty))THEN
                  FOUNDEDGE = .FALSE.
                ENDIF
 1340         ENDDO
            ENDIF
            IF(FOUNDEDGE.AND..NOT.NOTFOUND)THEN
              IIXY = IIXY + 1
              EDGE(1,IIXY) = MAXX+startx
              EDGE(2,IIXY) = MAXY+starty
c              if(debug(80))
c     $     print*,'foundedge = ',edge(1,iixy),edge(2,iixy),iixy
              IF(debug(80).and.WINOPEN) THEN
                IXPA(1) = MAXX+startx
                IYPA(1) = MAXY+starty
                CALL DSPCRS(IXPA,IYPA,1,5,isize)
              END IF
              isize = isize + 1
            ENDIF
          ENDIF
 1350   ENDDO
 1360 ENDDO
      CALL CTIMER(TIMEA)
chrp 29.03.2011      if(debug(80))THEN
        TIMESTRING = 'Thresholds'
        write(iout,fmt=6070)
     $       timestring(1:lenstr(timestring)),timea-timeb
        if(online)write(itout,fmt=6070)
     $       timestring(1:lenstr(timestring)),timea-timeb
chrp 29.03.2011      endif
      timeb = timea
      MODE = 5
      IF(IIXY.GT.2)THEN
C
C---- remove worst point(s)
C         
C
C---- new method (20.05.2008) - four-point analysis, i.e. how well points  
C     fit the circles. 
C
        TARGET = 1.0
        ICOLR = 1
        ISIZE = 4
c
c---- four point analysis - start; EDGE is in pixels from the start of the image
c
        IF(DEBUG(80))THEN
          print*,' raw beam is ',xmm(1),ymm(1)
        ENDIF
        IF(WINOPEN)then
          IXPA(1) = int(xmm(1)/rast)
          IYPA(1) = int(Ymm(1)/rast)
          CALL DSPXCRS(IXPA,IYPA,1,1,25)
        endif
        IF(DEBUG(80))THEN
          print*,'Eight points for circular backstop'
          print*,'**********************************'
        ENDIF
        DO 1370 IC=1,8
          SUMEPS(IC) = 0.0
          IF(DEBUG(80))THEN
            print*,'point ',ic,': ',edge(1,ic),edge(2,ic),
     $           sqrt(real((edge(1,ic)-xbeam)**2 + 
     $           (edge(2,ic)-ybeam)**2))
            IF(WINOPEN)then
              CALL DSPXCRS
     $             (edge(1,ic),edge(2,ic),
     $             1,2,25)
            endif
          ENDIF
 1370   ENDDO
        BESTSOL = 99999.9
        IF(IIXY.GE.4)THEN
          DO 1420 IC = 1,IIXY-3,1
            FOURPOINTS(1,1) = EDGE(1,IC)
            FOURPOINTS(2,1) = EDGE(2,IC)
            DO 1410 JC = IC+1,IIXY-2,1
              FOURPOINTS(1,2) = EDGE(1,JC)
              FOURPOINTS(2,2) = EDGE(2,JC)
              DO 1400 KC = JC+1,IIXY-1,1
                FOURPOINTS(1,3) = EDGE(1,KC)
                FOURPOINTS(2,3) = EDGE(2,KC)
                DO 1390 LC = KC+1,IIXY,1
                  FOURPOINTS(1,4) = EDGE(1,LC)
                  FOURPOINTS(2,4) = EDGE(2,LC)
                  CALL FITCIR(4,4,FOURPOINTS,CENTRE,RADIUS,
     $                 RMSRES,MODE)
                  IF(RADIUS.LT.10.0.and.debug(80))THEN
                    PRINT*,IC,JC,KC,LC,' centre = ',CENTRE,
     $                   ', radius = ',RADIUS,
     $                   ', and RMS residual = ',RMSRES
                    print*,'Distance of this centre from beam is ',
     $                   sqrt(real((centre(1)-xmm(1))**2 + 
     $                   (centre(2)-ymm(1))**2))
                  endif
C     
C---- centre nearest to the beam position
C
                  RMSRES = SQRT(REAL((CENTRE(1)-XMM(1))**2 + 
     $                 (CENTRE(2)-YMM(1))**2))
                  IF(RMSRES.LT.BESTSOL)THEN
                    BESTSOL = RMSRES
                    BESTFOUR(1) = IC
                    BESTFOUR(2) = JC
                    BESTFOUR(3) = KC
                    BESTFOUR(4) = LC
                    SCORE(1) = CENTRE(1)
                    SCORE(2) = CENTRE(2)
                    SCORE(3) = RADIUS
                    SCORE(4) = RMSRES
                  ENDIF
                  IF(COSTWOTHETA.NE.0.0)RADIUS= RADIUS/COSTWOTHETA
                  SUMEPS(IC) = SUMEPS(IC) + RMSRES
                  SUMEPS(JC) = SUMEPS(JC) + RMSRES
                  SUMEPS(KC) = SUMEPS(KC) + RMSRES
                  SUMEPS(LC) = SUMEPS(LC) + RMSRES
                  MAXDIST = 0
                  SUMDIST = 0
                  
                  POINTSUSED = 0.0
                  DO 1380 MC = 1,IIXY,1
                    CALL PX2XYC(XX,YY,EDGE(1,MC), EDGE(2,MC))
                    EPS = ABS(SQRT((XX - CENTRE(1))**2 +
     $                   (YY - CENTRE(2))**2))
                    SUMDIST = SUMDIST + EPS
                    IF(EPS.GT.MAXDIST)MAXDIST = EPS
                    IF(MC.EQ.IC.OR.MC.EQ.JC
     $                   .OR.MC.EQ.KC.OR.MC.EQ.LC)
     $                   POINTSUSED = POINTSUSED + 
     $                   ABS(EPS-RADIUS)
 1380             ENDDO
                  POINTSUSED= POINTSUSED/4.0
 6010             FORMAT('Average error for the 4 points used is ',
     $                 F6.3)
 1390           ENDDO
 1400         ENDDO
 1410       ENDDO
 1420     ENDDO
          IC = BESTFOUR(1)
          JC = BESTFOUR(2)
          KC = BESTFOUR(3)
          LC = BESTFOUR(4)
          IF(DEBUG(80))THEN
            PRINT*,'Four best points',IC,JC,KC,LC
            PRINT*,' give a circle centre at ',score(1),score(2),
     $           ' with radius ',score(3),' and rmsres ',score(4)
          ENDIF

          CIRCEN(1) = SCORE(1)
          CIRCEN(2) = SCORE(2)
          CIRRAD = SCORE(3)

          DO 1430 MC = 1,4,1
            NEWEDGE(1,MC) = EDGE(1,BESTFOUR(MC))
            NEWEDGE(2,MC) = EDGE(2,BESTFOUR(MC))
 1430     ENDDO
          CALL FITCIR(4,4,newEDGE,CENTRE,RADIUS,
     $         RMSRES,MODE)
          IF(IIXY.GT.4)THEN
c     
c---- cycle through other points to see if there are any good ones.
c
            NC = 5
            DO 1440 MC = 1,IIXY,1
              IF(DEBUG(80))THEN
                PRINT*,NC
              ENDIF
              IF(MC.NE.IC.AND.MC.NE.JC.AND.MC.NE.KC.AND.MC.NE.LC)THEN
                NEWEDGE(1,NC) = EDGE(1,MC)
                NEWEDGE(2,NC) = EDGE(2,MC)
               
 6020           FORMAT(6X,I2,1X,4(F8.4,1X)) 
 6030           FORMAT(9X,4(F8.4,1X),/,9x,' this score = ',F8.4)
                CALL FITCIR(NC,NC,NEWEDGE,CENTRE,RADIUS,
     $               RMSRES,MODE)
                IF(DEBUG(80))THEN
                  WRITE(IOUT,FMT=6020)MC,CENTRE,
     $                 RADIUS/COSTWOTHETA,RMSRES
                  IF(ONLINE)WRITE(ITOUT,FMT=6020)MC,CENTRE,
     $                 RADIUS/COSTWOTHETA,RMSRES
                ENDIF
                THISSCORE = ABS(SCORE(1)-CENTRE(1))/SCORE(1) +
     $               ABS(SCORE(2)-CENTRE(2))/SCORE(2) +
     $               ABS(RADIUS - SCORE(3))/SCORE(3)
                THISSCORE = MAX(SCORE(1),CENTRE(1)) / 
     $               MIN(SCORE(1),CENTRE(1)) * 
     $               MAX(SCORE(2),CENTRE(2)) / 
     $               MIN(SCORE(2),CENTRE(2)) * 
     $               MAX(SCORE(3),RADIUS) / 
     $               MIN(SCORE(3),RADIUS)
                IF(DEBUG(80))THEN
                  WRITE(IOUT,FMT=6030)MAX(SCORE(1),CENTRE(1)) / 
     $                 MIN(SCORE(1),CENTRE(1)), 
     $                 MAX(SCORE(2),CENTRE(2)) / 
     $                 MIN(SCORE(2),CENTRE(2)), 
     $                 MAX(SCORE(3),RADIUS) / 
     $                 MIN(SCORE(3),RADIUS),
     $                 RMSRES/RAST,thisscore
                  IF(ONLINE)
     $                 WRITE(ITOUT,FMT=6030)MAX(SCORE(1),CENTRE(1))/ 
     $               MIN(SCORE(1),CENTRE(1)), 
     $               MAX(SCORE(2),CENTRE(2)) / 
     $               MIN(SCORE(2),CENTRE(2)), 
     $               MAX(SCORE(3),RADIUS) / 
     $               MIN(SCORE(3),RADIUS),
     $               RMSRES/RAST,thisscore
                ENDIF
                IF(THISSCORE.LT.1.2)THEN
                  IF(DEBUG(80))THEN
                    PRINT*,'Okay, added ',NC,'th point'
                  ENDIF
                  CIRCEN(1) = CENTRE(1)
                  CIRCEN(2) = CENTRE(2)
                  CIRRAD = RADIUS
                  NC = NC + 1
                ENDIF
              ENDIF
 1440       ENDDO
            NC = NC - 1
            DO 1450 IC = 1,IIXY,1
              EDGE(1,IC) = NEWEDGE(1,IC)
              EDGE(2,IC) = NEWEDGE(2,IC)
 1450       ENDDO
              
          ENDIF
        ENDIF
c
c---- four point analysis - end
c          
C     assign centre and radius to integer values relative to 
C     the central box
        ICENTRE(1) = CIRCEN(1)/RAST - STARTX
        ICENTRE(2) = CIRCEN(2)/RAST - STARTY
        ICIRRAD = (CIRRAD/RAST)**2
        IF(DEBUG(80))THEN
          PRINT*,'rmsres = ',rmsres
        ENDIF
        WRITE(IOUT,FMT=6040)CIRCEN(1),CIRCEN(2),CIRRAD
        IF(ONLINE)WRITE(ITOUT,FMT=6040)CIRCEN(1),CIRCEN(2),CIRRAD
 6040   FORMAT(/,1X,'Use these keywords to include the backstop ',
     $       'in a command file: ',//,6X,'BACKSTOP CENTRE ',2F8.2,
     $       ' RADIUS ',F8.2)
        if(winopen)
     $       CALL DSPCIRC(CIRCEN(1),CIRCEN(2),
     $       CIRRAD/COSTWOTHETA,icolr)
        
        IF(SOCKLO)THEN
          WRITE(XMLLINE,FMT=8000)CIRCEN(1),CIRCEN(2),CIRRAD
          CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(XMLLINE),
     $         XMLLINE)
 8000     FORMAT('<?xml version="1.0"?>',
     $         '<!DOCTYPE backstop_response>',
     $         '<backstop_response>',
     $         '<type>auto</type>',
     $         '<circle_centre_x>',F8.2,'</circle_centre_x>',
     $         '<circle_centre_y>',F8.2,'</circle_centre_y>',
     $         '<radius>',F8.2,'</radius>',
     $         '</backstop_response>')
        ENDIF
      ELSE
        WRITE(IOUT,FMT=6050)
        IF(ONLINE)WRITE(ITOUT,FMT=6050)
 6050   FORMAT(' too few points found to locate a beamstop!')

        IF(SOCKLO)THEN
          WRITE(XMLLINE,FMT=8060)
          CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(XMLLINE),
     $         XMLLINE)
 8060     FORMAT('<?xml version="1.0"?>',
     $         '<!DOCTYPE backstop_response>',
     $         '<backstop_response>',
     $         '<type>auto</type>',
     $         '<message>no circular backstop found</message>',
     $         '</backstop_response>')
        ENDIF
      ENDIF
C
C---- having found the backstop, start looking for a backstop arm.
C
C     start by thinning the edge, but try to keep contiguity.
C
      DO 1470 JC=1,HEIGHT,1
        DO 1460 IC = 1,WIDTH,1
          IF(JC.EQ.1.OR.JC.EQ.WIDTH.OR.IC.EQ.1.OR.IC.EQ.HEIGHT)THEN
            KC = 0
            LC = 0
          ELSEIF(ITHETA(IC,JC).EQ.1)THEN
            KC = 0
            LC = 1
          ELSEIF(ITHETA(IC,JC).EQ.2)THEN
            KC = 1
            LC = 1
          ELSEIF(ITHETA(IC,JC).EQ.3)THEN
            KC = 1
            LC = 0
          ELSEIF(ITHETA(IC,JC).EQ.4)THEN
            KC = -1
            LC = 1
          ELSE
            KC = 0
            LC = 0
            if(nmsuppress(ic,jc).ne.0)
     $           print*,'no slope information for ',ic,jc
          ENDIF
C
C---- thinning ridges
C
          IF(NMSUPPRESS(IC,JC).LT.NMSUPPRESS(IC+LC,JC+KC).or.
     $         NMSUPPRESS(IC,JC).LT.NMSUPPRESS(IC-LC,JC-KC))THEN
            WORK_ONE(IC,JC) = 0
          ELSE
            WORK_ONE(IC,JC) = NMSUPPRESS(IC,JC)
          ENDIF
C
C---- remove any points masked by the circular beamstop found above
C
          DISTANCE = ((IC-ICENTRE(1))**2) + 
     $         ((JC-ICENTRE(2))**2)
          IF(DISTANCE.LE.ICIRRAD)WORK_ONE(IC,JC) = 0
          ISMOOTH(IC,JC) = WORK_ONE(IC,JC)
 1460   ENDDO
 1470 ENDDO
      SMOOTHFILE = 'canny_011.img'
      if(debug(80).and.ndebug(80).ne.0)
     $     CALL WRITEFILE(SMOOTHFILE,ISMOOTH,1,1,SIZEX,SIZEY)
      OC = 1
      DO 1490 JC = 1,HEIGHT,1
        DO 1480 IC = 1,WIDTH,1
            
          IF(OC.LE.64*SIZEX)THEN
            IF(JC.LE.10.OR.JC.GE.HEIGHT-10.OR.
     $           IC.LE.10.OR.IC.GE.WIDTH-10)then
              ARM(1,OC) = IC
              ARM(2,OC) = JC
              ARM(3,OC) = 0
            ELSE
              IF(WORK_ONE(IC,JC).GT.0)THEN
                ARM(1,OC) = IC
                ARM(2,OC) = JC
                ARM(3,OC) = 32
                OC = OC + 1
              ENDIF
            ENDIF
c          ELSE
c            WRITE(IOUT,FMT=8100)
c            IF(ONLINE)WRITE(ITOUT,FMT=8100)
c 8100       FORMAT(/,80('*'),/,' too many points found in lines - ',
c     $           ' giving up')
c            RETURN
          ENDIF
          WORK_ONE(IC,JC) = 0
          ISMOOTH(IC,JC) = 0
 1480   ENDDO
 1490 ENDDO
 6060 format(3(3i8,/))
C
C---- use Hough transform to locate straight edges
C
      CALL CTIMER(TIMEB)
      CALL HOUGH(ARM,HOUGHLINES,OC,RC)
C     ..
C     .. plot on xdl display
c      DO IC=1,OC
c        IF(WINOPEN.AND.ARM(3,IC).NE.0)THEN
c          CALL DSPXCRS
c     $         (ARM(1,IC)+NREC-WIDTH,
c     $         ARM(2,IC)+IYLEN-HEIGHT,
c     $         2,ARM(3,IC),ISIZE)
c        ENDIF
c      ENDDO 

      IF(DEBUG(80))THEN
        WRITE(IOUT,FMT=6080)RC,OC
        IF(ONLINE)WRITE(ITOUT,FMT=6080)RC,OC
 6080   FORMAT('hough says ',I2,' possible lines found from ',I5,
     $       ' points')
      ENDIF
      CALL CTIMER(TIMEA)
      TIMESTRING = 'Hough transform and analysis'
      write(iout,fmt=6070)
     $     timestring(1:lenstr(timestring)),timea-timeb
      if(online)write(itout,fmt=6070)
     $     timestring(1:lenstr(timestring)),timea-timeb
      TIMEB = timea
C
C---- on returning from Hough, armval .gt. 0 indicates a straight line; 
C     now group the points together and find the ends. 
C
      DO 1660 IC = 1,32,1
        NSEGMENTS(IC) = 0
        MSEGMENTS(IC) = 0
 1660 ENDDO
      DO 1670 IC = 1,OC,1
        WORK_ONE(ARM(1,IC),ARM(2,IC)) = ARM(3,IC)
        ISMOOTH(ARM(1,IC),ARM(2,IC)) =  WORK_ONE(ARM(1,IC),ARM(2,IC))
        IF(ARM(3,IC).NE.0.AND.ARM(3,IC).LE.32)THEN
          NSEGMENTS(ARM(3,IC)) = NSEGMENTS(ARM(3,IC)) + 1
        ENDIF
 1670 ENDDO
      IF(DEBUG(80))THEN
        print*,'nsegments = ',nsegments
      ENDIF
      SMOOTHFILE = 'canny_012.img'
      if(debug(80).and.ndebug(80).ne.0)
     $     CALL WRITEFILE(SMOOTHFILE,ISMOOTH,1,1,SIZEX,SIZEY)
C     ..
C     .. 
      DO 1675 IC = 1,64*WIDTH
        tmp1(ic) = 0
        tmp2(ic) = 0
        tmp3(ic) = 0
 1675 enddo
      JC = 0
      DO 1680 IC = 1,32,1
        if (nsegments(ic).gt.100)then
          if(debug(80))THEN
            write(iout,fmt=6090)ic,nsegments(ic),
     $           houghlines(1,ic),houghlines(2,ic)
            if(online)write(itout,fmt=6090)ic,nsegments(ic),
     $           houghlines(1,ic),houghlines(2,ic)
 6090       FORMAT('Line ',I3,' has ',I4,' points (radius = ',
     $           F7.1,', angle = ',F7.2,')')
          ENDIF
          JC = JC + 1
          MSEGMENTS(JC) = IC
          houghlines(1,jc) = houghlines(1,ic)
          houghlines(2,jc) = houghlines(2,ic)
        ENDIF
 1680 enddo
      IF(DEBUG(80))THEN
        print*,'After eliminating short lines, there are ',jc,
     $       ' lines remaining'
        print*,'Renumbering lines!'
      ENDIF
C     ..
C     .. go through each line, store points in tmp, then sort on 
C     .. largest dimension - first determine a sensible threshold for the 
C     .. point density
      LC = 0
      thisden = 0.0
      thatden = 0.0
      DO 1695 IC = 1,JC,1
        MINX = 99999
        MAXX = 0
        MINY = 99999
        MAXY = 0
        DO 1705 KC = 1,OC,1
          IF(MSEGMENTS(IC).EQ.ARM(3,KC))THEN
            LC = LC + 1
            TMP1(LC) = ARM(1,KC)
            TMP2(LC) = ARM(2,KC)
C     TMP3(LC) = ARM(3,KC)
            minx = min(minx,tmp1(lc))
            maxx = max(maxx,tmp1(lc))
            miny = min(miny,tmp2(lc))
            maxy = max(maxy,tmp2(lc))
            LENGTH = INT(SQRT(
     $           REAL(MINX - MAXX)**2 + 
     $           REAL(MINY - MAXY)**2))
            density = real(lc)/real(length)
          ENDIF
          
 1705   ENDDO
        LC = 0
        IF(DEBUG(80))THEN
          PRINT*,'Density = ',density
        ENDIF
        IF(DENSITY.GT.THISDEN)THISDEN = DENSITY
        IF(THISDEN.GT.THATDEN)THEN
          DENSITY = THATDEN
          THATDEN = THISDEN
          THISDEN = DENSITY
        ENDIF
        THRESHDEN = THISDEN -1E-4
        IF(DEBUG(80))THEN
          PRINT*,'Line ',ic,' First pass gives thisden = ',thisden,
     $         ', thatden = ',thatden
        ENDIF
 1695 ENDDO
      LC = 0
      PC = 0
      DO 1690 IC = 1,JC,1
        MINX = 99999
        MAXX = 0
        MINY = 99999
        MAXY = 0
        DO 1700 KC = 1,OC,1
          IF(MSEGMENTS(IC).EQ.ARM(3,KC))THEN
            LC = LC + 1
            TMP1(LC) = ARM(1,KC)
            TMP2(LC) = ARM(2,KC)
C     TMP3(LC) = ARM(3,KC)
            minx = min(minx,tmp1(lc))
            maxx = max(maxx,tmp1(lc))
            miny = min(miny,tmp2(lc))
            maxy = max(maxy,tmp2(lc))
            LENGTH = INT(SQRT(
     $           REAL(MINX - MAXX)**2 + 
     $           REAL(MINY - MAXY)**2))
            density = real(lc)/real(length)
          ENDIF
 1700   ENDDO
          IF(DEBUG(80))THEN

 6100       FORMAT(24('*'),/,'Line ',I3,' has ',I4,' points, ',
     $           'length = ',I4,' point density = ',F7.3,/,
     $           '(radius = ',F7.1,', angle = ',F7.2,')')
            write(iout,FMT=6100)ic,lc,length,density,
     $           houghlines(1,ic),houghlines(2,ic)
            if(online)write(itout,FMT=6100)ic,lc,length,
     $           density,
     $           houghlines(1,ic),houghlines(2,ic)
          ENDIF
        IF(DENSITY.GE.THRESHDEN.AND.
     $         (LENGTH*DENSITY.GT.(HEIGHT+WIDTH)/8))THEN
          PC = PC + 1
          FANGLE(PC) = HOUGHLINES(2,IC)
c     ..
c     .. 
C     .. 
          RANGEY = MAXY - MINY
          RANGEX = MAXX - MINX
          IF(RANGEX.GT.RANGEY)THEN
C     
C     .. sort on X
            IF(DEBUG(80))THEN
              print*,'sorting on X'
            ENDIF
            CALL SORTUP4(LC,TMP1,SORTVAL)
            SLOPEXY = REAL(RANGEY)/REAL(RANGEX)
          ELSE
C     ..
C     .. sort on Y
            
            IF(DEBUG(80))THEN
              print*,'sorting on Y'
            ENDIF
            CALL SORTUP4(LC,TMP2,SORTVAL)
            SLOPEXY = REAL(RANGEX)/REAL(RANGEY)
          ENDIF
C     ..
C     .. check for longest contig
          IF(DEBUG(80))THEN
            print*,'checking length of contigs for line ',ic
          ENDIF
          MC = 0
          NC = 1
          LENGTH = 0
          OLDLENGTH = 0
          PIXBEG = 1
          PIXEND = 1
          FDISTANCE = SQRT(REAL(
     $         (TMP1(SORTVAL(1))-TMP1(SORTVAL(LC)))**2 + 
     $         (TMP2(SORTVAL(1))-TMP2(SORTVAL(LC)))**2))
          THATDEN = FDIStance/real(lc)
          THISDEN = 0
          IF(DEBUG(80))THEN
            print*,'that distance, density etc is ',Fdistance,thatden
            print*,TMP1(SORTVAL(1)),TMP2(SORTVAL(1)),
     $           TMP1(SORTVAL(LC)),TMP2(SORTVAL(LC))
          ENDIF
          JC = 2
          length = lc
          notfound = .true.
          do 1730 while (jc.lt.lc.and.notfound)
          FDISTANCE = SQRT(REAL(
     $         (TMP1(SORTVAL(jc))-TMP1(SORTVAL(LC)))**2 + 
     $         (TMP2(SORTVAL(jc))-TMP2(SORTVAL(LC)))**2))
          thisden = fDIStance/real(length)
C            print*,'jc, thisden, thatden =',jc,thisden,thatden
          IF(THISDEN.Gt.thatden)THEN
c            print*,'assigning thisden to thatden'
            thatden = thisden
          else
c            print*,'shuffling'
            notfound = .false.
            mc = jc
          endif
C          print*,'loop: distance, density = ',fdistance,thisden,
C     $         thatden,jc,length
          JC = JC + 1
          length = length - 1
 1730     enddo
c          print*,'chopping from other end'
          notfound = .true.
          jc = lc
          do 1740 while (jc.gt.mc.and.notfound)
          FDISTANCE = SQRT(REAL(
     $         (TMP1(SORTVAL(jc))-TMP1(SORTVAL(mC)))**2 + 
     $         (TMP2(SORTVAL(jc))-TMP2(SORTVAL(mC)))**2))
          thisden = fDIStance/real(length)
C            print*,'jc, thisden, thatden =',jc,thisden,thatden
          IF(THISDEN.Gt.thatden)THEN
c            print*,'assigning thisden to thatden'
            thatden = thisden
          else
c            print*,'shuffling'
            notfound = .false.
            nc = jc
          endif
C          print*,'loop: distance, density = ',fdistance,thisden,
C     $         thatden,jc,length
          JC = JC - 1
          length = length - 1
 1740     enddo
          pixbeg = mc
          pixend = nc
C          print*,'pixbeg, pixend: ',pixbeg,pixend,' (lc = ',lc,')'
C          print*,'harry says '
          DO 1720 JC=1,LC,1
            if(JC.GE.PIXBEG.and.jc.le.pixend)then
C              print*,'harry says ',TMP1(SORTVAL(JC)),TMP2(SORTVAL(JC))
            else
C              print*,'HARRY SAYS ',TMP1(SORTVAL(JC)),TMP2(SORTVAL(JC)),
C     $             '*****'
            endif
chrp 01032011            DISTANCE = SQRT(REAL(
chrp 01032011     $           (TMP1(SORTVAL(JC))-TMP1(SORTVAL(JC+1)))**2 + 
chrp 01032011     $           (TMP2(SORTVAL(JC))-TMP2(SORTVAL(JC+1)))**2))
chrp 01032011            IF(DISTANCE.LE.5.and.JC.LT.LC-1)THEN
C     ..
C     .. continue this contig, increase length
chrp 01032011              MC = MC + 1
chrp 01032011            ELSE
C     ..
C     .. finish old contig, is it longer than previous one? start new contig
chrp 01032011              OLDLENGTH = LENGTH
chrp 01032011              LENGTH = SQRT(REAL(
chrp 01032011     $           (TMP1(SORTVAL(JC))-TMP1(SORTVAL(JC-MC)))**2 + 
chrp 01032011     $           (TMP2(SORTVAL(JC))-TMP2(SORTVAL(JC-MC)))**2))
chrp 01032011              density = real(Mc)/real(max(1,length))
chrp 01032011              IF(OLDLENGTH.LT.LENGTH)THEN
chrp 01032011                PIXBEG = JC
chrp 01032011                PIXEND = JC - MC
chrp 01032011                QC = MC
chrp 01032011              ENDIF
chrp 01032011              IF(JC.EQ.LC-1)PRINT*,'Final contig:'
chrp 01032011              PRINT*,NC,': ',MC,
chrp 01032011     $             ' break was ',distance,' length was ',length,
chrp 01032011     $             ' density = ',density
chrp 01032011              NC = NC + 1
chrp 01032011              MC = 0
chrp 01032011            ENDIF
 1720     ENDDO
c          print*,'harry says ',TMP1(SORTVAL(LC)),TMP2(SORTVAL(LC))
          LENGTH = SQRT(REAL(
     $         (TMP1(SORTVAL(PIXBEG))-TMP1(SORTVAL(PIXEND)))**2 + 
     $         (TMP2(SORTVAL(PIXBEG))-TMP2(SORTVAL(PIXEND)))**2))
          density = real(Qc)/real(max(1,length))
c          PRINT*,'BEST contig: length was ',length,
c     $         ' density = ',density
C     ..
C     .. avoid the two extreme ends of the lines in case of isolated points?
          MC = ((ICENTRE(1)-TMP1(SORTVAL(PIXEND)))**2) + 
     $         ((ICENTRE(2)-TMP2(SORTVAL(PIXEND)))**2)
c          print*,'distance^2 from first point to beam centre is ',
c     $         MC
          NC = ((ICENTRE(1)-TMP1(SORTVAL(PIXBEG)))**2) + 
     $         ((ICENTRE(2)-TMP2(SORTVAL(PIXBEG)))**2)
c          print*,'     "       " second   "    "   "     "    " ',
c     $         NC
C     ..
C     .. ILINES(PC,1&2) closest to beam centre
          IF(MC.LT.NC)THEN
            ILINES(PC,1) = TMP1(SORTVAL(PIXEND))
            ILINES(PC,2) = TMP2(SORTVAL(PIXEND))
            ILINES(PC,3) = TMP1(SORTVAL(PIXBEG))
            ILINES(PC,4) = TMP2(SORTVAL(PIXBEG))
          ELSE
            ILINES(PC,1) = TMP1(SORTVAL(PIXEND))
            ILINES(PC,2) = TMP2(SORTVAL(PIXEND))
            ILINES(PC,3) = TMP1(SORTVAL(PIXBEG))
            ILINES(PC,4) = TMP2(SORTVAL(PIXBEG))
          ENDIF
          ILINES(PC,1) = TMP1(SORTVAL(LC))
          ILINES(PC,2) = TMP2(SORTVAL(LC-1))
          ILINES(PC,3) = TMP1(SORTVAL(1))
          ILINES(PC,4) = TMP2(SORTVAL(2))
          IF(DEBUG(80))THEN
            WRITE(IOUT,FMT=6110)IC,(ILINES(PC,QC),QC=1,4)
            IF(ONLINE)WRITE(ITOUT,FMT=6110)IC,(ILINES(PC,QC),QC=1,4)
 6110       FORMAT('Line ',I2,' starts at ',I4,1X,I4,' and ends at ',
     $           I4,1X,I4)
          ENDIF
        ENDIF
        LC = 0
 1690 ENDDO
      IF(DEBUG(80))THEN
        PRINT*,'We have found ',pc,' line segments that look okay'
        print*,'angle of backstop arm is ',fangle(1),fangle(2)
      ENDIF
C     
C---- Simple case to get code working - if we have two edges.
C     
      IF(PC.EQ.2)THEN
C     ..
C     .. which two ends are closest?

        BESTFOUR(1) = INT(SQRT(
     $       REAL(ILINES(1,1) - ILINES(2,1))**2 + 
     $       REAL(ILINES(1,2) - ILINES(2,2))**2))
        
        BESTFOUR(2) = INT(SQRT(
     $       REAL(ILINES(1,1) - ILINES(2,3))**2 + 
     $       REAL(ILINES(1,2) - ILINES(2,4))**2))
        
        BESTFOUR(3) = INT(SQRT(
     $       REAL(ILINES(1,3) - ILINES(2,1))**2 + 
     $       REAL(ILINES(1,4) - ILINES(2,2))**2))
        
        BESTFOUR(4) = INT(SQRT(
     $       REAL(ILINES(1,3) - ILINES(2,3))**2 + 
     $       REAL(ILINES(1,4) - ILINES(2,4))**2))
        IF(DEBUG(80))THEN
          PRINT*,'distances are ',BESTFOUR
        ENDIF
        CALL SORTUP4(4,BESTFOUR,SORTVAL)
        IF(DEBUG(80))THEN
          print*,' sorting keys: ',sortval(1),sortval(2),
     $         sortval(3),sortval(4)
          print*,bestfour(sortval(1)),bestfour(sortval(2)),
     $         bestfour(sortval(3)),bestfour(sortval(4))
          print*,'invertx is ',invertx
          print*,'startx, y = ',startx,starty
          print*,'omegafd = ',omegafd,' fangle(1) = ',fangle(1)
        ENDIF
C     ..
C     .. which two points are closer to the beam/circular backstop?
        IF(ABS(FANGLE(1)).LT.30)THEN
          IF(DEBUG(80))THEN
            print*,'number 1'
          ENDIF
          IF(INVERTX) THEN
            CORNER(1,1) = (nrec - startx - ilines(1,1)) * 100 * rast
            CORNER(2,1) = (nrec - startx - ilines(1,3)) * 100 * rast
            CORNER(3,1) = (nrec - startx - ilines(2,3)) * 100 * rast
            CORNER(4,1) = (nrec - startx - ilines(2,1)) * 100 * rast
          ELSE
            CORNER(1,1) = (startx + ilines(1,1)) * 100 * rast
            CORNER(2,1) = (startx + ilines(1,3)) * 100 * rast
            CORNER(3,1) = (startx + ilines(2,3)) * 100 * rast
            CORNER(4,1) = (startx + ilines(2,1)) * 100 * rast
          ENDIF
          CORNER(1,2) = (starty + ilines(1,2)) * 100 * rast
          CORNER(2,2) = (starty + ilines(1,4)) * 100 * rast
          CORNER(3,2) = (starty + ilines(2,4)) * 100 * rast
          CORNER(4,2) = (starty + ilines(2,2)) * 100 * rast
        ELSE
          IF(DEBUG(80))THEN
            print*,'number 2'
          ENDIF
          IF(INVERTX) THEN
            CORNER(1,1) = (nrec - startx - ilines(1,1)) * 100 * rast
            CORNER(2,1) = (nrec - startx - ilines(1,3)) * 100 * rast
            CORNER(3,1) = (nrec - startx - ilines(2,3)) * 100 * rast
            CORNER(4,1) = (nrec - startx - ilines(2,1)) * 100 * rast
          ELSE
            CORNER(2,1) = (startx + ilines(1,3)) * 100 * rast
            CORNER(3,1) = (startx + ilines(2,3)) * 100 * rast
            CORNER(1,1) = (startx + ilines(1,1)) * 100 * rast
            CORNER(4,1) = (startx + ilines(2,1)) * 100 * rast
          ENDIF
          CORNER(1,2) = (starty + ilines(1,2)) * 100 * rast
          CORNER(2,2) = (starty + ilines(1,4)) * 100 * rast
          CORNER(3,2) = (starty + ilines(2,4)) * 100 * rast
          CORNER(4,2) = (starty + ilines(2,2)) * 100 * rast
        ENDIF
        IF(DEBUG(80))THEN
          print*,'beam   at ',xbeam,ybeam
          print*,'corner at ',ilines(1,1),ilines(1,2)
          print*,'corner at ',ilines(1,3),ilines(1,4)
          print*,'corner at ',ilines(2,3),ilines(2,4)
          print*,'corner at ',ilines(2,1),ilines(2,2)
        ENDIF
        IC = 1
        CNREXC(1,IC) = CORNER(1,1)
        CNREXC(2,IC) = CORNER(1,2)
        CNREXC(3,IC) = CORNER(2,1)
        CNREXC(4,IC) = CORNER(2,2)
        CNREXC(5,IC) = CORNER(3,1)
        CNREXC(6,IC) = CORNER(3,2)
        CNREXC(7,IC) = CORNER(4,1)
        CNREXC(8,IC) = CORNER(4,2)
        IQUADNO = 1
        
        CALL QUADTL(1,IQUADNO,CORNER,0.0,0.0,IERR) 
        IF(WINOPEN)THEN
C     .. draw quadrilateral in red
          CALL DRAWMASK(4,0)
          CALL MXDCIO(1,0,0,0,0)
        ENDIF
 6140   FORMAT(/,1X,'Use these keywords to include the backstop arm ',
     $       'in a command file: ',//,6X,
     $       'LIMITS QUADRILATERAL ',8F8.1)
        WRITE(IOUT,FMT=6140)(CNREXC(JC,IC)/100.0,JC=1,8)
        IF(ONLINE)WRITE(ITOUT,FMT=6140)
     $       (CNREXC(JC,IC)/100.0,JC=1,8)
        IF(SOCKLO)THEN
          WRITE(XMLLINE,FMT=8020)(CNREXC(JC,IC)/100.0,JC=1,8)
          CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(XMLLINE),
     $         XMLLINE)
 8020     FORMAT('<?xml version="1.0"?>',
     $         '<!DOCTYPE backstop_response>',
     $         '<backstop_response>',
     $         '<type>auto</type>',
     $         '<quadrilateral_x_1>',F8.2,'</quadrilateral_x_1>',
     $         '<quadrilateral_y_1>',F8.2,'</quadrilateral_y_1>',
     $         '<quadrilateral_x_2>',F8.2,'</quadrilateral_x_2>',
     $         '<quadrilateral_y_2>',F8.2,'</quadrilateral_y_2>',
     $         '<quadrilateral_x_3>',F8.2,'</quadrilateral_x_3>',
     $         '<quadrilateral_y_3>',F8.2,'</quadrilateral_y_3>',
     $         '<quadrilateral_x_4>',F8.2,'</quadrilateral_x_4>',
     $         '<quadrilateral_y_4>',F8.2,'</quadrilateral_y_4>',
     $         '</backstop_response>')
        ENDIF
      ELSEIF (PC.LT.2) THEN
        IF(WINOPEN)THEN
C     .. draw quadrilateral in red
          CALL DRAWMASK(4,0)
          CALL MXDCIO(1,0,0,0,0)
        ENDIF
 6160   FORMAT(/,1X,'No backstop arm found')
        WRITE(IOUT,FMT=6160)
        IF(ONLINE)WRITE(ITOUT,FMT=6160)
        IF(SOCKLO)THEN
          WRITE(XMLLINE,FMT=8040)
          CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(XMLLINE),
     $         XMLLINE)
 8040     FORMAT('<?xml version="1.0"?>',
     $         '<!DOCTYPE backstop_response>',
     $         '<backstop_response>',
     $         '<type>auto</type>',
     $         '<message>no backstop arm found</message>',
     $         '</backstop_response>')
        ENDIF
        
      ELSE
        IF(DEBUG(80))THEN
          print*,' there are more than two lines - I''m confused'
        ENDIF
      ENDIF
      
      CALL CTIMER(TIMEA)
chrp 29.03.2011      IF(DEBUG(80))THEN
        TIMESTRING = 'Rejecting outliers'
        WRITE(IOUT,FMT=6070)
     $       TIMESTRING(1:LENSTR(TIMESTRING)),TIMEA-TIMEB
        IF(ONLINE)WRITE(ITOUT,FMT=6070)
     $       TIMESTRING(1:LENSTR(TIMESTRING)),TIMEA-TIMEB
        TIMESTRING = 'The whole thing'
        WRITE(IOUT,FMT=6070)
     $       TIMESTRING(1:LENSTR(TIMESTRING)),TIMEA-TIMEC
        IF(ONLINE)WRITE(ITOUT,FMT=6070)
     $       TIMESTRING(1:LENSTR(TIMESTRING)),TIMEA-TIMEC
chrp 29.03.2011      ENDIF
C
C---- Formats
C
 6070 format(A,' took ',F6.3,' seconds')
      LACTIVE = SLACTIVE
      LACTIVEMASK = SLACTIVEMASK
      FORCEREAD = SFORCEREAD
      REALLYFORCEREAD = SREALLYFORCEREAD
      RETURN
      
      END
C
C---- writing new headerless image file for viewing
C
      SUBROUTINE WRITEFILE(SMOOTHFILE,ISMOOTH,STARTX,STARTY,SIZEX,SIZEY)
C           Common block PARAMETER
C     .. Include files ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
      CHARACTER SMOOTHFILE*80
      INTEGER SIZEX,SIZEY
      INTEGER*2 ISMOOTH(SIZEX,SIZEY)
      INTEGER STARTX,STARTY
C&&*&& include  ../inc/debug.f
C
C $Id: debug.f,v 1.8 2021/06/03 09:41:34 andrew Exp $
C
C--- awk generated include file  debug.h
C---- START of include file debug.h
C
C
C
C     .. Arrays in common /DEBUG/ ..
      REAL XWARN
      INTEGER NDEBUG,IWARN,IARRDUMP
      LOGICAL DEBUG,LPRINT,DUMP,WARN
C
C     .. Scalars in common /DEBUG/ ..
      REAL BGRLIM
      INTEGER NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,IERRLEVEL
      LOGICAL SPOT
      CHARACTER MESSAGE*512
C     
C     ..
C     .. Common Block /DEBUG/..
      COMMON /DEBUG/XWARN(MAXIWARN,100),BGRLIM,NDEBUG(200),
     +       IWARN(MAXIWARN,100),
     $       NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,DEBUG(200),LPRINT(20),
     +       DUMP(30),WARN(100),SPOT,IARRDUMP(30),IERRLEVEL

      COMMON /CDEBUG/ MESSAGE
C     ..
C
C&&*&& end_include  ../inc/debug.f
      IF(DEBUG(80))THEN
        print*,'writing image file for ',smoothfile
      ENDIF
      OPEN(21,FILE=SMOOTHFILE,FORM='UNFORMATTED')
      WRITE(21)ISMOOTH
      CLOSE(21)
      RETURN
      END
C
C---- following can be used to plot Xs on image 
C
