     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C     ..
      SAVE
