     +        IR,ISDBSI,IBEST,NRMIN,ICYC,NCMAX,ISIGN,IB,NBREJ,NTOT,
     +        IL,NP,NL,NCYCLES,NBADPIX,NBADMAX,IBLAST,HX,HY,
     +        IBESTST,MAXPIX,NPASS,NPIXREJ,NBADBLOCK,NBADBOX,
     +        LASTBADBLOCK,INDEX,NXY,NPK,NBADLIMIT,NTOTBADPIX,
     +        IMIDPIX,IPROFPK,IPROFBADMAX,IDMP,IPEXT,IQEXT,IPQEXT,
     +        IPROFEXTMAX,ISTEP

      LOGICAL FULL,EQUAL,BADBKG,BADPIXELS,BADPROF
      REAL TBGND,TPEAK,SPOTW,BGND,RMSBG,DELX,DELY,AX,BGFRACSAVE,
     +      SIGFAC,SIGFACMAX,FRAC,SPOTWMAX,BGSIGP,PX,RMSBGN,BGSIGL,
     +      BADRATIO,DIST,DISTMIN
      CHARACTER CALLEDFROM*80
