C
C $Id: myprof.f,v 1.3 2011/07/19 11:18:20 andrew Exp $
C
C--- awk generated include file  myprof.h
C---- START of include file myprof.h
C
C
C     .. Arrays in Common Block /MYPROF/ ..
      REAL PRSCALE,XPMAX,YPMAX,XLINE,YLINE,WPROFL,WPRSUMS,PRCUT
      INTEGER ISIZE,NRFBOX,IPROFL,IBOX,IXBOX,IYBOX,NPFIRST
      LOGICAL BOX
C     ..
C     .. Scalars in Common Block /MYPROF/
      REAL TOL,BGPKRAT,FRACREJ,BADTOL,TOLMIN,RECLEVEL
      INTEGER NXLINE,NYLINE,NUMBOX,IBOUND,ITRIM,NOVERLAP,MINPKSIZ
      LOGICAL HIGHRES,LOWRES,PRSET,OFFDET,PROPT,FIXBOX,LINESET,
     +        PROPTCEN,RECOVER,NOFIXBOX,PREXICE
C     ..
C     .. Common Block /MYPROF/ ..
      COMMON /MYPROF/PRSCALE(NMASKS,2),XPMAX(NMASKS),YPMAX(NMASKS),
     $       XLINE(NNLINE),YLINE(NNLINE),
     +       WPROFL(MAXBOX,NMASKS),WPRSUMS(MAXBOX,NMASKS),TOL,
     +       BGPKRAT,FRACREJ,BADTOL,TOLMIN,RECLEVEL,
     $       ISIZE(NMASKS,2),NRFBOX(NMASKS),
     +       IPROFL(MAXBOX,NMASKS+1),IBOX(0:NNLINE,0:NNLINE),
     +       IXBOX(NMASKS,2),IYBOX(NMASKS,2),
     +       NPFIRST(NNLINE-1),NXLINE,NYLINE,NUMBOX,IBOUND,ITRIM,
     $       NOVERLAP,MINPKSIZ,BOX(NMASKS),HIGHRES,LOWRES,PRSET,
     +       OFFDET,PROPT,FIXBOX,LINESET,PROPTCEN,RECOVER,NOFIXBOX,
     +       PREXICE,PRCUT
C     ..
C
C
C&&*&& end_include  ../inc/myprof.f
C&&*&& include  ../inc/ras.f
C
C $Id: ras.f,v 1.1 2002/05/02 10:47:10 harry Exp $
C
C--- awk generated include file  ras.h
C---- START of include file ras.h
C
C
C     .. Scalars in common block /RAS/ ..
      INTEGER NEWRAS,MINT
C     ..
C     .. Arrays in common block /RAS/ ..
      INTEGER IRAS
      REAL VARAS
C     ..
C     .. Common Block /RAS/ ..
      COMMON /RAS/VARAS(5),IRAS(5),NEWRAS,MINT
C     ..
C
C
C&&*&& end_include  ../inc/ras.f
C&&*&& include  ../inc/sums.f
C
C $Id: sums.f,v 1.1 2002/05/02 10:47:21 harry Exp $
C
C--- awk generated include file  sums.h
C---- START of include file sums.h
C
C
C     Elements of ASPOT
C     1 = Summation integration intensity
C     2 = Total background counts under peak assuming peak has mm symmetry
C     3 = Rms variation in background, after rejecting background points.
C         This is evaluated in BGSOLVE called from EVAL.
C     4 = Centre of gravity in X direction (in pixels)
C     5 = Centre of gravity in Y direction (in pixels)
C         These are wrt an origin at the centre of the measurement box
C     6 = sum p*iod for background pixels
C     7 = sum q*iod for background pixels
C     8 = sum iod for background pixels
C     9 = Background plane constant a (gradient in X direction)
C    10 = Background plane constant b (gradient in Y direction)
C    11 = Background plane constant c 
C    12 = Largest deviation from background plane, excluding rejected pixels
C    13 = Profile fitted intensity
C    14 = Variance of profile fitted intensity = sum (deltasq) for peak
C         pixels only. Used to calculate PKRATIO and also profile fitted
C         sigma(I) in unweighted case only.
C    15 = Number of rejected background pixels
C    16 = Variance of profile fitted intensity in weighted case (default)
C    17 = sum W*DELTA**2 for profile fit
C    18   unused
C     .. Arrays in common block /SUMS/ ..
      REAL ASPOT
C     ..
C     .. Common Block /SUMS/ ..
      COMMON /SUMS/ASPOT(18)
C     ..
C
C
C&&*&& end_include  ../inc/sums.f
C       
C     .. Equivalences ..
      EQUIVALENCE (ASPOT(1),SPOTW), (ASPOT(2),BGND),
     +            (ASPOT(3),RMSBG)
      EQUIVALENCE (ASPOT(4),DELX), (ASPOT(5),DELY)
C
      SAVE
C                       
      DATA STR/'NRX','NRY','NC '/
      CALLEDFROM = 'BESTMASK'
      BADBKG = .FALSE.
      IDMP = 0
      NPASS = 0
      LLMASKREJ(1) = 0
C
C----- Save the input raster parameters
C
      DO 2 I=1,5
        LRASSAVE(I) = LRAS(I)
 2    CONTINUE
C
C---- First vary the X rim, then do the same for the Y rim.
C
C---- Set corner cutoff to one (effectively no corner cutoff because
C     either NRX or NRY is always at least 1. Code in setmask/setmask2
C     DOES NOT WORK for NC = 0
C
      NXX = LRAS(1)
      NYY = LRAS(2)
C
C---- If calling from BGREJECT (ie called from process to handle the standard
C     profiles), set the maximum number of allowed "bad"
C     pixels as a function of number of peak pixels of the starting
C     raster parameters. "Bad" pixels are those which lie in the peak
C     of both the active spot and of a neighbouring spot. This is
C     calculated for each combination of raster parameters below in
C     a call to CHECKMASK, and those combinations which produce too
C     many "bad" pixels are excluded from the optimisation
C
      IF (MODE.EQ.1) THEN
        CALL SETMASK2(MASK,LRAS,MASKREJ)
        CALL SETSM2(MASK,LRAS,PQVAL,PQSUMS,PQSUMINV)
        NBADMAX = BADTOL*PQVAL(5)
        NBADMAX = MAX(NBADMAX,1)
      END IF
      NBREJ = MASKREJ(1)
      LRAS(3) = 1
C
C---- BGKSIG negative flags background subtracted spots
C
      ISIGN = 1
      IF (BGKSIG.LT.0.0) ISIGN = -1
      BGKSIG = ABS(BGKSIG)
C                       
C---- Set maximum rim MINPKSIZ is minimum peak size in pixels
C
      NRXMAX = (NXX-MINPKSIZ)/2
      NRYMAX = (NYY-MINPKSIZ)/2                   
      NCMAX = MIN(NXX,NYY) - 2
      FULL = .TRUE.
      IDR = 1
      NREF = 1
      BGSIGL = BGKSIG
C
C
      IF (DEBUG(42)) THEN
        WRITE(IOUT,FMT=6007) NRXMIN,NRYMIN,NCMIN,(LRASSAVE(I),I=1,5)
        IF (ONLINE) WRITE(ITOUT,FMT=6007) NRXMIN,NRYMIN,NCMIN,
     +                                     (LRASSAVE(I),I=1,5)
 6007   FORMAT(/,1X,'Entering BESTMASK, NRXMIN=',I3,' NRYMIN=',I3,
     +          ' NCMIN=',I3,/,1X,'Starting raster parameters',5I4)
      END IF
C
 4    NPASS = NPASS + 1
      NCYCLES = 2
      IF ((MODE.EQ.0).AND.(NPASS.EQ.1)) NCYCLES = 4
      IF (DEBUG(42)) THEN
        NBREJ = MASKREJ(1)
        WRITE(IOUT,FMT=6000) NPASS,NPBOX,MODE,LRAS,NBADMAX,
     +       NINT(PQVAL(5)),NINT(PQVAL(6))
        IF (ONLINE) WRITE(ITOUT,FMT=6000) NPBOX,MODE,LRAS,NBADMAX,
     +       NINT(PQVAL(5)),NINT(PQVAL(6))
        IF (MODE.EQ.0) THEN
          WRITE(IOUT,FMT=6001) LLMASKREJ(1),(LLMASKREJ(I),I=2,11)
          IF (ONLINE) WRITE(ITOUT,FMT=6001) LLMASKREJ(1),
     +                    (LLMASKREJ(I),I=2,11)
        ELSE 
          WRITE(IOUT,FMT=6003) NBREJ,(MASKREJ(I),I=2,11)
          IF (ONLINE) WRITE(ITOUT,FMT=6003) NBREJ,(MASKREJ(I),I=2,11)
        END IF
C
 6000 FORMAT(//1X,'BESTMASK now in pass',I2,/,1X,
     +            'Debug output from BESTMASK for box',I3,' MODE=',I3,
     +            /,1X,'Starting raster',5I3,/,1X,'Max number of bad',
     +            ' pixels',I4,'  number of pixels in peak',I5,' in',
     +            ' background',I5)
 6001 FORMAT(/,1X,'Number of rejected pixels now',I5,
     +            '  First ten are:',10I4)
 6003 FORMAT(/,1X,'Number rejected background pixels',I4,
     +            '  First ten are:',10I4)
        MAXPIX = 0
        IF (SPOT.AND.DEBUG(42).AND.(NPASS.EQ.1)) 
     +                 CALL ODPLOT4(OD(1),NXX,NYY,1,MAXPIX)
      END IF
C
C---- Save current value of BGFRAC
C
      BGFRACSAVE = BGFRAC

      DO 40 ICYC = 1,NCYCLES
C
C---- Set BGSIG depending on MODE and cycle number
C
      IF ((MODE.EQ.0).AND.(ICYC.LE.2).AND.(NPASS.EQ.1)) THEN
        BGSIGP = 10000.0
      ELSE
        BGSIGP = BGSIGL
      END IF
C
C---- If MODE=0 (called from CHECKRAS, no knowledge about adjacent spots)
C     for cycles 3 and 4, set BGFRAC to 0.7 to ensure pixels belonging
C     to adjacent spots do not interfere with the determination of the
C     optimal mask parameters. This is particularly important for Pilatus
C     where the default BGFRAC is 1.0
C
C
      IF ((MODE.EQ.0).AND.(ICYC.GE.3)) BGFRAC = 0.7
C
 10   IF (DEBUG(42)) THEN
        WRITE(IOUT,FMT=6002) ICYC,BGSIGP,BGFRAC
        IF (ONLINE) WRITE(ITOUT,FMT=6002) ICYC,BGSIGP,BGFRAC
      END IF
 6002 FORMAT(/1X,'CYCLE',I3,' For this cycle BGSIG=',F8.1,
     +       ' BGFRAC=',f3.1)
C
C---- Vary first Xrim, then Yrim then corner cutoff
C
      DO 30 J = 1,3
       IF (J.EQ.1) THEN
         NRMAX = NRXMAX
         NRMIN = NRXMIN
         IPT = 4
       ELSE IF (J.EQ.2) THEN
         NRMAX = NRYMAX
         NRMIN = NRYMIN
         IPT = 5
       ELSE
         NRMAX = NCMAX
         NRMIN = MAX(NCMIN,1)
C
C---- In cases where the measurement box is much larger in one
C     dimension than the other, and the spot is poorly defined
C     it can happen that NCMIN (from PKRIM) is larger than NCMAX.
C     Trap this below, so at least one cycle is performed
C 
         IF (NRMIN.GE.NRMAX) NRMIN = NRMAX - 2
         IPT = 3
       END IF
      IF (DEBUG(42)) THEN
        WRITE(IOUT,FMT=6004) STR(J),NRMIN,NRMAX
        IF (ONLINE) WRITE(ITOUT,FMT=6004) STR(J),NRMIN,NRMAX
      END IF
 6004 FORMAT(/1X,'Optimising ',A,' Range',I3,' to',I3,/,1X,' NC RX RY ',
     +'NBG NPK REJ      I           C          BKG       sigma I/sigma',
     +  ' IBEST')
C
C---- Set SIGFACMAX (largest value for I/sig(I)) negative initially because 
C     otherwise if all intensities are -ve (possible if there really is not
C     diffraction) IBEST does not get assigned a value
C     AGWL 25/6/07
C
      SIGFACMAX = -1000.0
      SPOTWMAX = -1000000.0
      DO 20 IR = NRMIN,NRMAX
        BADPIXELS = .FALSE.
        LRAS(IPT) = IR
C          ************************
C---- Use SETMASK2,SETSM2 which allows for rejected pixels
C
        IF (NPASS.EQ.1) THEN
          CALL SETMASK2(MASK,LRAS,MASKREJ)
        ELSE
          CALL SETMASK2(MASK,LRAS,LLMASKREJ)
        END IF
        CALL SETSM2(MASK,LRAS,PQVAL,PQSUMS,PQSUMINV)
C
C---- Check, using known spot separations calculated in MASKIT, that
C     the current set of parameters does not result in too many peak
C     pixels common to this and neighbouring spots being closer to the
C     centre of the neighbouring spot than to this one.
C
        IF (MODE.EQ.1) THEN
CAL          IF (DEBUG(42)) THEN
CAL            CALL RASPLOT4(OD,LRAS(1),LRAS(2),MASK,MASKREJ,1,1,.FALSE.,
CAL     +                    .FALSE.)
CAL          END IF
          CALL CHECKMASK(MASK,LRAS,NPBOX,NBADPIX,NTOTBADPIX,IBADPQ,IDMP)
          IF (NBADPIX.GT.NBADMAX) THEN
            IF (DEBUG(42)) THEN
              WRITE(IOUT,FMT=6005) IR,NBADPIX,NBADMAX
              IF (ONLINE) WRITE(ITOUT,FMT=6005) IR,NBADPIX,NBADMAX
 6005         FORMAT(1X,'IR=',I2,' rejected because of',I6,
     +               ' bad pixels (closer to an adjacent spot',
     +               ' than the current spot (limit is',I4,')')
            END IF
C
C---- If this is the first cycle and the rim parameter is getting
C     unreasonably large it is probably because the corner rim has been
C     set to one, so set IBEST to the input starting and go on to test
C     the next rim parameter
C
            IF ((ICYC.EQ.1).AND.((IR - LRASSAVE(IPT).GT.2))) THEN
              IBEST = LRASSAVE(IPT)
              GOTO 26
            END IF
            SPOTI(IR) = 0.0
            BADPIXELS = .TRUE.
            GOTO 20
          END IF
        END IF
C                  **********************************************
        CALL INTEG3(OD(1),LRAS,MASK,PQVAL,PQSUMS,PQSUMINV,NBREJ,
     +              LMASKREJ,ISIGN*BGSIGP,DEBUG(42))
C                  **********************************************
        TPEAK = PQVAL(5)
        TBGND = PQVAL(6)
C
C---- Get integrated intensity, sigma and I/sigma
C     Need TBGND and TPEAK
        NREJ = NINT(ASPOT(15))
C
C---- Must update number of background points to allow for rejected 
C     pixels. 
C
       TBGND = TBGND - NREJ
C
C                       
C                       
C---- Test that it has not rejected an unacceptable number of
C     background points, there must be NBGMIN points left (set by
C     subkeyword MINB under keyword REJECTION. If too many rejected
C     reflection is flagged with ASPOT(1)=-9999
C
        IF (ASPOT(1).EQ.-9999.0) THEN
          SPOTI(IR) = 0.0
          GOTO 20
        END IF
C
C---- Give debug output if no background pixels and not trapped by above test
C
CAL       IF (TBGND.LE.0.0) WRITE(6,*),'****** tbgnd,nrej,tpeak,LRAS,aspot',
CAL     +          TBGND,
CAL     +          NREJ,TPEAK,LRAS,ASPOT
C
C---- Calculate standard deviation of intensity
C
C                        
C
C---- This sigma does not include instrument error correction
C     BGND is the total background under the peak, ie 
C     (number of peak pixels)*c
C     If this is an averaged profile (ISIGN.eq.-1), the background has 
C     been subtracted so need to add it back in.
C
        IF (ISIGN.EQ.-1) BGND = TPEAK*CTOT
        AX = GAIN*(ABS(SPOTW)+BGND+BGND*TPEAK/TBGND)
        ISDBSI=SQRT(AX) + 0.5
        ISDBSI = MAX(ISDBSI,1)
        SIGFAC = SPOTW/FLOAT(ISDBSI)
        IF (SPOTW.GT.SPOTWMAX) SPOTWMAX = SPOTW
        SPOTI(IR) = SPOTW
        IF (SIGFAC.GE.SIGFACMAX) THEN
          IBEST = IR
          SIGFACMAX = SIGFAC
        END IF
        IF (DEBUG(42)) THEN
          WRITE(IOUT,FMT=6008)(LRAS(K),K=3,5),NINT(TBGND),NINT(TPEAK),
     +                NREJ,SPOTW,ASPOT(11),BGND,ISDBSI,SIGFAC,IBEST
          IF (ONLINE) WRITE(ITOUT,FMT=6008) (LRAS(K),K=3,5),
     +      NINT(TBGND),NINT(TPEAK),NREJ,SPOTW,ASPOT(11),BGND,
     +      ISDBSI,SIGFAC,IBEST
 6008     FORMAT(1X,3I3,3I4,F12.0,F10.0,F12.0,I8,F8.0,I6)
        END IF
C
 20   CONTINUE
C
C---- Now check if all possible values have been rejected because there
C     were too many "bad" pixels in all cases. BADPIXELS will only
C     be TRUE now if there were too many even for the maximum value of
C     the rim parameter, which is when the number should be smallest.
C
      IF ((SPOTWMAX.LT.0.0).AND.(BADPIXELS)) THEN
        NBADMAX = 2*NBADMAX
        IF (DEBUG(42)) THEN
          WRITE(IOUT,FMT=6016) NBADMAX
          IF (ONLINE) WRITE(ITOUT,FMT=6016) NBADMAX
 6016     FORMAT(/,1X,'All values rejected, increase maximum ',
     +      'number of allowed "bad" pixels to',I5)
        END IF
        GOTO 10
      END IF
C
C---- If max intensity is -ve, suggests that there are outliers in
C     background that are not being correctly rejected (because BGSIG
C     is too high). Reduce BGSIG to 5 and try again (once only)
C     This can happen if diffraction is very weak and there are ice 
C     rings/spots. AL 28nov05
C
      IF ((.NOT.BADBKG).AND.(SPOTWMAX.LT.0.0)) THEN
        BADBKG = .TRUE.
        BGSIGP = 5.0
        BGSIGL = BGSIGP
        IF (DEBUG(42)) THEN
          WRITE(IOUT,FMT=6014) BGSIGP
          IF (ONLINE) WRITE(ITOUT,FMT=6014) BGSIGP
 6014     FORMAT(/,1X,'Best I is -ve, reduce BGSIG to',F5.2,' and ',
     +          'try again')
        END IF
        GOTO 10
      END IF
        
C
C---- Check that it has not rejected all possible raster values
C     because too many background points are rejected. This can happen
C     if the initial overall dimensions of the measurement box are too
C     small. If this is the first cycle then NC will be zero, so just set
C     the rim to the smallest value (NRMIN) and keep going
C
cdms10.2002   Changed .EQ. in following statement to .LE.
CAL 28nov05 This change caused problems. Fix:
CAL   25 Jul 2011. Why has this been changed back to "EQ", this is not
C     save.
CAL      IF (SPOTWMAX.EQ.-1000000.0) THEN
C
      IF (SPOTWMAX.LT.-99999.0) THEN
        IF (ICYC.EQ.1) THEN
          IBEST = NRMIN
          GOTO 26
        END IF
C
C---- If not the first cycle, increase BGSIGP and try again
C
        BGSIGP = 2.0*BGSIGL
        BGSIGL = BGSIGP
        IF (BGSIGL.GT.200) THEN
          WRITE(IOUT,FMT=6013)
          IF (ONLINE) WRITE(ITOUT,FMT=6013)
 6013     FORMAT(1X,'***** FATAL ERROR *****',/,1X,
     +     'BGSIG too large, check prediction is OK.')
          call dna_error('BGSIG too large, check predictions')
          NSHUTERR = 1
          CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
        END IF
C
        WRITE(IOUT,FMT=6015) BGSIGP
        IF (ONLINE) WRITE(ITOUT,FMT=6015) BGSIGP
 6015   FORMAT(/,1X,'*** WARNING ***',/,1X,'Too many background ',
     +         'points rejected as outliers to allow',/,1X,
     +         'optimisation. Increasing BGSIG to',F7.1,'(see',
     +         ' BACKGROUND keyword in "Help" library.',/,1X,
     +         'BGSIG will be reset to original value when ',
     +         'integrating images.')
        GOTO 10
C
CAL        WRITE(IOUT,FMT=6009) LRAS
CAL        IF (ONLINE) WRITE(ITOUT,FMT=6009) LRAS
 6009   FORMAT(//1X,'***** ERROR *****',/,1X,'With the given raster',
     +  ' (measurement box) parameters (',5I3,')',/,1X,'too many ',
     +  'background pixels are being rejected to permit optimisation.',
     +  /,1X,'Try increasing the overall box size (NXS,NYS) and rerun',
     +  ','/,1X,'but first check (using the graphics option) that the',
     +   ' pattern is being',/,1X,'correctly predicted')
CAL        CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
      END IF
C
C---- Check loss in intensity wrt max for the "best" value. If more
C     than "TOL" go up to IBOUND pixels further out in NRX,NRY,or NC
C     Initialise IBLAST to 1, so no extrapolation for IBEST occurs
C
      IBESTST = IBEST
      IBLAST = 0
      DO 22 IB = 1,IBOUND
        FRAC = ( SPOTWMAX - SPOTI(IBEST) )/SPOTWMAX
        FRACA(IB) = FRAC
        IF (DEBUG(42)) THEN
          WRITE(IOUT,FMT=6012) IB,FRAC,IBEST
          IF (ONLINE) WRITE(ITOUT,FMT=6012) IB,FRAC,IBEST
        END IF
 6012   FORMAT(1X,'Cycle',I2,' Frac=',F6.3,' IBEST=',I2)
        IF (FRAC.GT.LTOL) THEN
          IBEST = MAX(IBEST-1,1)
        ELSE
          IBLAST = IB
          GOTO 24
        END IF
 22   CONTINUE
C
C---- Interpolate between last two values of IB to get the "best" value
C
 24   IF (IBLAST.GE.2) THEN
        PX = 0.0
        IF (FRACA(IBLAST).LT.FRACA(IBLAST-1))
     +    PX = (LTOL - FRACA(IBLAST))/(FRACA(IBLAST-1)-FRACA(IBLAST))
        IBEST = NINT(REAL(IBEST) + PX)
C
C---- Do not allow IBEST to go beyond IBOUND
C
        IF ((IBESTST-IBEST).GT.(IBOUND-1)) IBEST = IBEST + 1
      ELSE IF (IBLAST.EQ.1) THEN
C
C---- The BEST value also has frac < tol so just choose it
C     IBEST should be incremented by one.
C
        CONTINUE
      ELSE IF (IBLAST.EQ.0) THEN
C
C---- All possible values have given frac > tol. See if
C     IBEST should be incremented by one.
C
        PX = (FRACA(IBOUND-1) - FRACA(IBOUND))
        IF (ABS((FRACA(IBOUND) - PX) - LTOL) .GT. 
     +      ABS(FRACA(IBOUND) - LTOL)) IBEST = IBEST + 1
      END IF
C
C
C---- If this is the first cycle, decrease IBEST for NC by one, otherwise
C     can get  poor discrimination in NX and NY in next cycle
C     if NC is overestimated. However, only do this if frac was < tol
C
      IF (DEBUG(42)) THEN
        WRITE(IOUT,FMT=6011) LTOL,IBEST
        IF (ONLINE) WRITE(ITOUT,FMT=6011) LTOL,IBEST
 6011   FORMAT(1X,'After interpolation, final IBEST for TOL=',F5.3,
     +         ' is',I3)
      END IF
CAL      IF ((J.EQ.3).AND.(ICYC.EQ.1).AND.(IBLAST.GT.0)) THEN
CAL        IBEST = IBEST - 1
CAL        IF (DEBUG(42)) THEN
CAL          WRITE(IOUT,FMT=6013) IBEST
CAL          IF (ONLINE) WRITE(ITOUT,FMT=6013) IBEST
CAL 6013   FORMAT(1X,'Because this is NC and first cycle, IBEST',
CAL     +         ' reset to',I3)
CAL        END IF
CAL      END IF
 
C
 26   LRAS(IPT) = IBEST
 30   CONTINUE
C
      IF (DEBUG(42)) THEN
        WRITE(IOUT,FMT=6010) ICYC,LRAS,FRAC
        IF (ONLINE) WRITE(ITOUT,FMT=6010) ICYC,LRAS,FRAC
      END IF            
 6010 FORMAT(1X,'Final raster parameters for cycle',I3,' are',5I4,
     +        '   Frac was',F6.3)
 40   CONTINUE
C
C---- End of NCYCLES of optimisation of raster parameters, new values in LRAS
C
C
C---- To get a whole lot of extra debug from INTEG3, uncomment the following 5 lines
C
CAL      IF (DEBUG(42)) THEN
CAL        DEBUG(33) = .TRUE.
CAL        DEBUG(34) = .TRUE.
CAL        SPOT = .TRUE.
CAL      END IF
C
C
C---- Make final call to INTEG with optimum parameters so that MASKREJ,
C     PQSUMS are correctly set up
C
C          ************************
C---- Use SETMASK2,SETSM2 which allows for rejected pixels
C
        CALL SETMASK2(MASK,LRAS,MASKREJ)
        CALL SETSM2(MASK,LRAS,PQVAL,PQSUMS,PQSUMINV)
        CALL INTEG3(OD(1),LRAS,MASK,PQVAL,PQSUMS,PQSUMINV,NBREJ,
     +              LMASKREJ,ISIGN*BGSIGP,DEBUG(42))
C          **********************************************
C
      IF (DEBUG(42).OR.DEBUG(109)) THEN
        WRITE(IOUT,FMT=6018) ASPOT,PQSUMS
        IF (ONLINE) WRITE(ITOUT,FMT=6018) ASPOT,PQSUMS
 6018   FORMAT(1X,'Final values in ASPOT',/,1X,9F12.0,/,1X,9F12.0,
     +         /,1X,'Current PQSUMS ',9F12.0)
CAL        DEBUG(33) = .FALSE.
CAL        DEBUG(34) = .FALSE.
CAL        SPOT = .FALSE.
          IF (SPOT.OR.DEBUG(109)) THEN
            WRITE(IOUT,FMT=6019)
            IF (ONLINE) WRITE(ITOUT,FMT=6019)
 6019       FORMAT(//,1X,'Dumping reflection from BESTMASK ** symbols',
     +        ' $,* etc are NOT correct here, but numbers are **')
            CALL PLOTSPOT(OD(1),LRAS,MASK,MASKREJ)
          END IF
      END IF
C                       
C---- Test that it has not rejected an unacceptable number of
C     background points, there must be NBGMIN points left (set by
C     subkeyword MINB under keyword REJECTION. If too many rejected
C     reflection is flagged with ASPOT(1)=-9999
C
      IF (ASPOT(1).EQ.-9999.0) THEN
        IF (BRIEF) WRITE(IBRIEF,6022) BGSIGP,NBGMIN
        WRITE(IOUT,6020) BGSIGP,NBGMIN
        IF (ONLINE) WRITE(ITOUT,6022) BGSIGP,NBGMIN
 6022     FORMAT(//1X,'With the current BGSIG factor of',F6.2,
     +     ' there are fewer than ',I3,' background pixels remaining',
     +     /,1X,'for this profile after rejecting outliers',/,1X,
     +     'Check if things are seriously wrong or rerun ',
     +     'with a larger value for BGSIG ',/,1X,
     +     'on BACKGROUND keyword')
        MAXPIX = 0
        CALL ODPLOT4(OD(1),NXX,NYY,1,MAXPIX)
        NSHUTERR = 2
         CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
      END IF
C
C---- Check for these final parameters that neighbouring spots do not intrude
C     in the peak region of the standard profiles.
C
      IF (MODE.EQ.1) THEN
C
C---- This is for standard profiles, not central average spot profile
C
        IDMP = 1
        CALL SETMASK(MASK2,LRAS)
        CALL CHECKMASK(MASK2,LRAS,NPBOX,NBADPIX,NTOTBADPIX,IBADPQ,IDMP)
        IF (DEBUG(42).OR.DEBUG(109)) THEN
          WRITE(IOUT,FMT=6040) NBADPIX,NTOTBADPIX
          IF (ONLINE) WRITE(ITOUT,FMT=6040) NBADPIX,NTOTBADPIX
        END IF
 6040   FORMAT(1X,'*** Final check, NBADPIX',I3,' NTOTBADPIX',I3,' ***')
C
C---- Note that NBADPIX is a weighted mean of number of bad pixels, as this
C     number differs for different adjacent spot separations, and different 
C     separations have different multiplicities, so this weighting takes
C     into account the multiplicity of each separation.
C     NTOTBADPIX is the total number of bad pixels that have different
C     coordinates (relative to the central pixel) for all separations.
C     It is these coordinates that are stored in IBADPQ, the P,Q coords in
C     the first two elements, the 1D array element in the third.
C
C---- Now have the coordinates of "bad" pixels (in peak region, but closer to an
C     adjacent spot) in IBADPQ. Now want to see that the actual profile values 
C     are at these pixels compared to the centre of the measurement box.
C
C
C---- If there are "bad" pixels detected by CHECKMASK, see what the profile
C     values are at these pixels. Note the profiles are not yet background
C     subtracted, so use the background plane parameters determined in INTEG3
C     NOTE: Not sufficient to just use the constant here, gradient can be
C     significant.
C
        IF (NTOTBADPIX.GT.0) THEN
          IMIDPIX = (LRAS(1)*LRAS(2))/2 + 1
          IPROFPK = NINT(OD(IMIDPIX)-ASPOT(11))
          IPROFBADMAX = 0
          IPROFEXTMAX = -9999
          BADPROF = .FALSE.
          BADRATIO = 0.0
          DO 44 I=1,NTOTBADPIX
C
C---- See what the closest bad pixel is, to determine how far away to go
C     for the "extended" pixel to check if there is another peak. Normally
C     use 2 steps, but if "bad" pixel is very close to central pixel,
C     eg coords (2,1),(1,2), (2,0) only use 1 step.
C
            DISTMIN = 999
            DO 42 J = 1,NTOTBADPIX
              DIST = IBADPQ(1,J)**2 + IBADPQ(2,J)**2
              DISTMIN = MIN(DIST,DISTMIN)
 42         CONTINUE
            IF (DISTMIN.GT.5) THEN
              ISTEP = 2
            ELSE
              ISTEP = 1
            END IF
C
            IPROFBAD(I) = NINT(OD(IBADPQ(3,I))-
     +        (IBADPQ(1,I)*ASPOT(9)+IBADPQ(2,I)*ASPOT(10)+ASPOT(11)))
C
C---- Now check profile values beyond the bad pixels, so see if they are
C     bigger (suggesting a real intruding spot) or smaller (suggesting no
C     serious intruding spot)
C
            IF (IBADPQ(1,I).GT.IABS(IBADPQ(2,I))) THEN
C
C---- Extend ISTEP steps in P
C
              IPEXT = MIN(LRAS(1)/2,IBADPQ(1,I)+ISTEP)
C
C---- Extend -1,0,+1 in Q depending on Q -ve, 0 +ve
C
              IF (IBADPQ(2,I).LT.0) THEN
                IQEXT = MAX(-LRAS(2)/2,IBADPQ(2,I)-1)
              ELSE IF (IBADPQ(2,I).GT.0) THEN
                IQEXT = MIN(LRAS(2)/2,IBADPQ(2,I)+1)
              ELSE
                IQEXT = IBADPQ(2,I)
              END IF
            ELSE IF (IBADPQ(1,I).LT.IABS(IBADPQ(2,I))) THEN
C
C---- Extend ISTEP steps in Q
C
              IF (IBADPQ(2,I).LT.0) THEN
                IQEXT = MAX(-LRAS(2)/2,IBADPQ(2,I)-ISTEP)
              ELSE IF (IBADPQ(2,I).GT.0) THEN
                IQEXT = MIN(LRAS(2)/2,IBADPQ(2,I)+ISTEP)
              ELSE 
                IQEXT = IBADPQ(2,I)+1
              END IF
C
C---- Extend 0,+1 in P depending on P is 0 +ve
C
              IF (IBADPQ(1,I).EQ.0) THEN
                IPEXT = 0
              ELSE IF (IBADPQ(1,I).GT.0) THEN
                IPEXT = MIN(LRAS(1)/2,IBADPQ(1,I)+1)
              END IF
            ELSE
C
C---- P and Q the same MAGNITUDE, add ISTEP to each
C
              IPEXT = IBADPQ(1,I) + ISTEP
              IF (IBADPQ(2,I).LT.0) THEN
                IQEXT = MAX(-LRAS(2)/2,IBADPQ(2,I)-ISTEP)
              ELSE IF (IBADPQ(2,I).GT.0) THEN
                IQEXT = MIN(LRAS(2)/2,IBADPQ(2,I)+ISTEP)
              ELSE 
                IQEXT = IBADPQ(2,I)+ISTEP
              END IF
            END IF       
C
C
            IPQEXT = (LRAS(1)/2+IPEXT)*LRAS(2) + (LRAS(2)/2+IQEXT+1)
            IPROFEXT(I) = NINT(OD(IPQEXT) - (IPEXT*ASPOT(9)+
     +                    IQEXT*ASPOT(10)+ ASPOT(11)))
            IF (DEBUG(109)) THEN
               WRITE(IOUT,FMT=9876) i,ibadpq(1,i),ibadpq(2,i),
     +         IPROFBAD(I),ipext,iqext,
     +         OD(IPQEXT),IPROFEXT(I)
               if (online) WRITE(ItOUT,FMT=9876) i,ibadpq(1,i),
     +         ibadpq(2,i),IPROFBAD(I),ipext,iqext,
     +         OD(IPQEXT),IPROFEXT(I)
 9876          format(1x,'I=',I2,' bad pix coords',2I3,
     +         ' bad pixel value',i8,' ext coords',2i6,
     +         ' orig and background subtr prof values',2i8)
            end if
            IPROFEXTMAX = MAX(IPROFEXTMAX,IPROFEXT(I))
C
C---- If profile value at extended position is less than at the bad pixel,
C---- then there is no significant adjacent peak so jump out of loop
C
            IF (IPROFEXT(I).LT.IPROFBAD(I)) GOTO 44
C
C---- Set flag for bad profile true
C
            BADPROF = .TRUE.
            IPROFBADMAX = MAX(IPROFBADMAX,IPROFBAD(I))
 44       CONTINUE
C
          IF (IPROFPK.GT.0) BADRATIO = REAL(IPROFBADMAX)/IPROFPK
C
C---- Only flag profiles where BADRATIO is > 10% as bad
C
          IF (BADRATIO.LT.0.1) BADPROF = .FALSE.
          IF (DEBUG(109)) THEN
            WRITE(IOUT,FMT=6020) IPROFPK,IPROFBADMAX,IPROFEXTMAX,IPEXT,
     +          IQEXT,BADPROF,(IPROFBAD(I),IPROFEXT(I),I=1,NTOTBADPIX)
            IF (ONLINE) WRITE(ITOUT,FMT=6020) IPROFPK,IPROFBADMAX,
     +         IPROFEXTMAX,IPEXT,IQEXT,BADPROF,(IPROFBAD(I),IPROFEXT(I),
     +         I=1,NTOTBADPIX)
 6020     FORMAT(1X,'Central pixel profile value',I10,'  Highest',
     +     ' bad pixel value',I10,' Highest extended pixel value',I10,
     +      ' Extended pixel coords',2I5,' badprof',l2,
     +     /,1X,'Profile values at bad and extended pixels',
     +     10(2i7,4x))
          END IF
        END IF
C
C---- Set limits for a warning. Whether this is serious or worrying is set
C     based on %age of all profiles that have this problem. The limit for
C     the number of bad pixels (the weighted mean) is currently set to 2.
C     Previously the statistics for serious and worrying profiles were kept
C     separately in elements 36 and 37 in XWARN and IWARN, now this decision
C     is only made after integration has finished, and all statistics are
C     stored in array element 36.
C
        NBADLIMIT = 2
        INDEX = 36
C
C---- Keep track of total number of profiles in XWARN(1,36), but don't include averaged
C     profiles (flagged with ISIGN = -1 as background has been subtracted)
C
        IF (ISIGN.GT.0) XWARN(1,INDEX) = XWARN(1,INDEX) +1
C
C---- Test if this profile should generate a warning message
C
CAL        IF ((NBADPIX.GE.NBADLIMIT).AND.BADPROF) THEN
        IF ((NTOTBADPIX.GE.NBADLIMIT).AND.BADPROF) THEN
C
C---- Keep track of number of profiles where neighbouring spots intrude
C
          XWARN(2,INDEX) = XWARN(2,INDEX) + 1
C
C---- Has there already been a bad profile for this block?
C
          IF (IWARN(1,INDEX).GE.1) THEN
            LASTBADBLOCK = IWARN(IWARN(1,INDEX)+1,INDEX)
            IF (NUMBLOCK.NE.LASTBADBLOCK) THEN
              NBADBLOCK = IWARN(1,INDEX)+ 1
              IWARN(1,INDEX) = NBADBLOCK
            ELSE
              NBADBLOCK = IWARN(1,INDEX)
            END IF
          ELSE
            NBADBLOCK = IWARN(1,INDEX)+ 1
            IWARN(1,INDEX) = NBADBLOCK
          END IF
          IF (NBADBLOCK.LE.19) THEN
            IWARN(NBADBLOCK+1,INDEX) = NUMBLOCK
C
C---- Store number of bad profiles for this block
C
            IWARN(10*NBADBLOCK+11,INDEX) =IWARN(10*NBADBLOCK+11,INDEX)+1
                NBADBOX = IWARN(10*NBADBLOCK+11,INDEX)
C
C---- Store the box number if LE 9
C
c
CAL          write(iout,fmt=9998) numblock,npbox,nbadpix,index,
CAL     +         iwarn(1,index),nbadblock,nbadbox
CAL          if (online) write(itout,fmt=9998) numblock,npbox,nbadpix,
CAL     +         index,iwarn(1,index),nbadblock,nbadbox
 9998     format(1x,'numblock',I3,' npbox',I2,' nbadpix',I2,
     +           ' index',i3,' iwarn(1,index',i3,' nbadblock',i3,
     +           ' nbadbox',I3)
c
            IF (NBADBOX.LE.9) THEN
              IWARN(10*NBADBLOCK+11+NBADBOX,INDEX) = NPBOX
              XWARN(10*NBADBLOCK+11+NBADBOX,INDEX) = BADRATIO
            END IF
          END IF
C
C---- Next line is end of  ((NTOTBADPIX.GE.NBADLIMIT).AND.BADPROF) line
C
        END IF
C
C---- Next line is end of IF (MODE.EQ.1) block
C
      END IF
C
C---- Now calculate a new RMSBG (used to test if standard profile needs
C     averaging) omitting background points next to peak pixels or next
C     to overlapped background pixels
C
      HX = LRAS(1)/2
      HY = LRAS(2)/2
      CALL NEWRMS(OD,HX,HY,MASK,LMASKREJ,RMSBGN)
      IF (RMSBGN.NE.0) RMSBG = RMSBGN
C
C---- Now have to merge the list of rejected pixels due to overlap of
C     neighbouring reflections (Stored in MASKREJ) with the list
C     of pixels which deviate from the best background plane (stored in
C     LMASKREJ)
C
      NBREJ = MASKREJ(1)
      NREJ = LMASKREJ(1)
      I = 0
      IL = 0
      NTOT = 0
C
C---- Set EQUAL true so that on first entry it assigns both I and IL
C
      EQUAL = .TRUE.
 50   I = I + 1
      IF (I.GT.NBREJ) GOTO 60
      NP = MASKREJ(I+1)
      IF (.NOT.EQUAL) GOTO 54
 52   IL = IL + 1
      IF (IL.GT.NREJ) GOTO 64
      EQUAL = .FALSE.
      NL = LMASKREJ(IL+1)
 54   NTOT = NTOT + 1
      IF (NL.LT.NP) THEN
       ISTORE(NTOT+1) = NL
       GOTO 52
      ELSE IF (NP.LT.NL) THEN
       ISTORE(NTOT+1) = NP
       GOTO 50
      ELSE 
       ISTORE(NTOT+1) = NL
       EQUAL = .TRUE.
       GOTO 50
      END IF
C
C----Gets here if list in MASKREJ is exhausted first
C    If the last two pixels had the same number, need to increment IL
C    by one before copying rest of list. Note this also deals with the
C    case when NBREJ=0, because EQUAL is initialised to be TRUE.
C
 60   IF (EQUAL) IL = IL + 1
      IF (IL.GT.NREJ) GOTO 68
      DO 62 J = IL,NREJ
        NTOT = NTOT + 1
        ISTORE(NTOT+1) = LMASKREJ(J+1)
 62   CONTINUE
      GOTO 68
C
C----Gets here if list in LMASKREJ is exhausted first
C
 64   DO 66 J = I,NBREJ
          NTOT = NTOT + 1
          ISTORE(NTOT+1) = MASKREJ(J+1)
 66   CONTINUE
C
 68   ISTORE(1) = NTOT
C
      IF (DEBUG(42)) THEN
        WRITE(IOUT,FMT=6030) NBREJ
        IF (NBREJ.NE.0) WRITE(IOUT,FMT=6031) (MASKREJ(I),I=2,NBREJ+1)
        WRITE(IOUT,FMT=6032) NREJ
        IF (NREJ.NE.0) WRITE(IOUT,FMT=6031) (LMASKREJ(I),I=2,NREJ+1)
        WRITE(IOUT,FMT=6034) NTOT
        IF (NTOT.NE.0) WRITE(IOUT,FMT=6031) (ISTORE(I),I=2,NTOT+1)
        IF (ONLINE) THEN
          WRITE(ITOUT,FMT=6030) NBREJ
          IF (NBREJ.NE.0) WRITE(ITOUT,FMT=6031)
     +                    (MASKREJ(I),I=2,NBREJ+1)
          WRITE(ITOUT,FMT=6032) NREJ
          IF (NREJ.NE.0) WRITE(ITOUT,FMT=6031)
     +                      (LMASKREJ(I),I=2,NREJ+1)
          WRITE(ITOUT,FMT=6034) NTOT
          IF (NTOT.NE.0) WRITE(ITOUT,FMT=6031)
     +                      (ISTORE(I),I=2,NTOT+1)
        END IF
      END IF
 6030 FORMAT(1X,'Number of rejected pixels in MASKREJ',I4)
 6031 FORMAT(1X,' Values:',
     +        /,(1X,30I4))
 6032 FORMAT(1X,'Number in LMASKREJ',I4)
 6034 FORMAT(1X,'Number after merging',I4)
C
C
C---- If this is called from CHKRAS (central profile, no list of
C     overlapped pixels) do a final round of optimisation if there
C     are any rejected pixels to avoid optimisatiomn being biased by
C     close spots. *** No longer need this, setting BGFRAC initially
C     to 0.7 avoids the need for this. save the code just in case. 
C     CHECKMASK2 has not been added to CVS. AGWL 23/1/12
C
CAL      IF ((MODE.EQ.0).AND.(NPASS.EQ.1)) THEN
CAL        CALL CHECKMASK2(OD,LRAS,MASK,MASKREJ)
CAL        IF (MASKREJ(1).GT.0) THEN
CAL          NPIXREJ = MASKREJ(1)
CAL          DO 70 I = 1,NPIXREJ+1
CAL            LLMASKREJ(I) = MASKREJ(I)
CAL 70       CONTINUE
CAL          GOTO 4
CAL        END IF
CAL      END IF
C
C
      DO 76 I = 1,NTOT+1
        MASKREJ(I) = ISTORE(I)
 76   CONTINUE
C
C---- Restore original value of BGFRAC
C
      BGFRAC = BGFRACSAVE
C
C---- Now need to set up PQSUMS to reflect the merged rejected pixel list
C     This is returned to BGREJECT.
C
      CALL SETMASK2(MASK,LRAS,MASKREJ)
      CALL SETSM2(MASK,LRAS,PQVAL,PQSUMS,PQSUMINV)
C      WRITE(6,*),'End of BESTMASK, number rej, PQSUMS',MASKREJ(1),PQSUMS
      RETURN
      END
C $Id: bexpan4.f,v 1.4 2006/08/29 14:58:34 harry Exp $
C== BEXPAN4 ==                           
C
      SUBROUTINE BEXPAN4(A,IA,NXY)
      IMPLICIT NONE
C     ===========================
C
C  This version for image plate data (I*2 pixel values)
C  It simply transfers values from array A to array IA (where A is
C  I*2 but IA is I*4). Note that this differs from BEXPAN only in that
C  the output array is I*4 rather than I*2. Two versions are required 
C  because subroutine CGFIND called from CENTRS does a sort on the pixel 
C  values and the sort routine expects I*2 arrays because it deals
C  primarily with the generate file data. However in CGFIT we want to use 
C  the BGTEST and BGSOLVE subroutines to eliminate bad background pixels 
C  and these require I*4 arrays.
C  If the dynamic range is extended to 16 bits we must cope
C  with the fact that values will be unsigned
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C
C     .. Scalar Arguments ..
      INTEGER NXY
C     ..
C     .. Array Arguments ..
      INTEGER*2 A(NXY)
      INTEGER  IA(NXY)
C     ..
C     .. Local Scalars ..
      INTEGER I
      INTEGER*2 IOD
C     ..
C     .. Extrinsic Functions ..
      INTEGER  INTPXL
      EXTERNAL  INTPXL
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/lmb.f
C
C $Id: lmb.f,v 1.17 2021/03/30 09:16:05 andrew Exp $
C
C--- awk generated include file  lmb.h
C---- START of include file lmb.h
C ODSCAL is to scale image numbers into the range 0-255 for plotting
C average profiles.
C  GAIN should be equal to the overall gain (image counts per X-ray photon)
C of the system, and is used to evaluate standard deviations based on
C counting statistics assuming independent pixels (ie point spread function
C less than pixel size).
C INVERTX true if image is inverted in the slow (X) direction when read in.
C ISCAL is to scale final integrated intensities and sigmas
C IDIVIDE is the adc offset
C ICONST is a constant to be added to all pixels (normally zero) to
C        allow processing of images with zero pixel values in the scanned
C        area.
C IMGP is true if working with image plate data
C SPIRAL is true for scanners with a spiral readout (Mar, DIP2000)
C ORTHOG is true for scanners with orthogonal scan (FUJI, RAXIS, MD)
C NULLPIX is the value of pixels within the image but not in the active
C area of the detector
C TILED is true if there are inactive areas of the detector within the
C       inscribing circle or square.
C
C NTILEX Number of tiles in X direction
C NTILEY Number of tiles in Y direction
C TILEX  X Coordinates of the midpoints of the null areas between tiles
C TILEY  Y Coordinates of the midpoints of the null areas between tiles
C TILEWX Width of the null areas between tiles in X
C TILEWY Width of the null areas between tiles in Y


C MACHINE and MODEL denote the type of detector.
C DECTRIS_TYPE can be PILATUS, EIGER1 or EIGER2. It is used when setting up
C the positions of the gaps between the tiles.
C
C MACHINE is used in the following subroutines:
C GETBLK, GETHDR, INTPXL, INTPXL2, MXDSPL, OPENODS, PROCESS, PUTPXL
C Currently coded types are:
C
C         MACHINE        MODEL               COMMENTS
C         =======        =====               ========
C         MAR            180, 300, 345
C         RAXI(S)        RAXISII, RAXISIV
C         MD
C         FUJI
C         CCD1           CCD1                Princetown CCD at CHESS,Tiff format
C         CCD2           CCD ?               ESRF CCD detector
C         ADSC           QUAD1               ADSC 2x2 CCD detector
C
C TRUSTED whether or not the image header information can be trusted for 
C         automatic processing
C MICROED indicates whether or not this is electron diffraction data,
C        base on the wavelength being less than 0.05A
C
C
C     .. Scalars in Common Block /LMB/ ..
        REAL ODSCAL,GAIN,LOGA,LOGB
        INTEGER ISCAL,IDIVIDE,ICONST,NULLPIX,NTILEX,NTILEY,
     $       RAXISCOMP,IIDIVIDE,COMPRESSION,GAPVAL,IINVERTX
        LOGICAL IMGP,INVERTX,SPIRAL,ORTHOG,CIRCULAR,TILED,SETADC,
     $       NEWRAXIS,BRUKNEW,TRUSTED,MINICBF,HDF5FILE,GAPMASK,
     $       WRONGGAPVALUE,MICROED
        CHARACTER MACHINE*4,MODEL*8,LDETECTOR*20,DECTRIS_TYPE*10,
     +       CMACHINE*40

C     ..
C     .. Arrays in common /LMB/
        INTEGER TILEX,TILEY,TILEWX,TILEWY
C
C     .. Common Block /LMB/ ..
        COMMON /LMB/ ODSCAL,GAIN,LOGA,LOGB,ISCAL,IDIVIDE,ICONST,
     $       NULLPIX,NTILEX,NTILEY,RAXISCOMP,IIDIVIDE,COMPRESSION,
     $       GAPVAL,IINVERTX,TILEX(20),TILEY(20),TILEWX(20),TILEWY(20),
     $       IMGP,INVERTX,SPIRAL,ORTHOG,CIRCULAR,
     $       TILED,SETADC,NEWRAXIS,BRUKNEW,TRUSTED,MINICBF,HDF5FILE,
     $       GAPMASK,WRONGGAPVALUE,MICROED
        COMMON /LMBC/ MACHINE,MODEL,LDETECTOR,DECTRIS_TYPE,CMACHINE

C&&*&& end_include  ../inc/lmb.f
C     ..
      SAVE
C
C
      DO 10 I = 1,NXY
        IOD = A(I)
        IA(I) = INTPXL(IOD)
   10 CONTINUE
      END
