     +     ICURR,NEXTRA,NHBYTE,BYTSWAP,LACTIVE,
     $     REALLYFORCEREAD
C&&*&& end_include  ../inc/scn.f
C&&*&& include  ../inc/sums.f
C
C $Id: sums.f,v 1.1 2002/05/02 10:47:21 harry Exp $
C
C--- awk generated include file  sums.h
C---- START of include file sums.h
C
C
C     Elements of ASPOT
C     1 = Summation integration intensity
C     2 = Total background counts under peak assuming peak has mm symmetry
C     3 = Rms variation in background, after rejecting background points.
C         This is evaluated in BGSOLVE called from EVAL.
C     4 = Centre of gravity in X direction (in pixels)
C     5 = Centre of gravity in Y direction (in pixels)
C         These are wrt an origin at the centre of the measurement box
C     6 = sum p*iod for background pixels
C     7 = sum q*iod for background pixels
C     8 = sum iod for background pixels
C     9 = Background plane constant a (gradient in X direction)
C    10 = Background plane constant b (gradient in Y direction)
C    11 = Background plane constant c 
C    12 = Largest deviation from background plane, excluding rejected pixels
C    13 = Profile fitted intensity
C    14 = Variance of profile fitted intensity = sum (deltasq) for peak
C         pixels only. Used to calculate PKRATIO and also profile fitted
C         sigma(I) in unweighted case only.
C    15 = Number of rejected background pixels
C    16 = Variance of profile fitted intensity in weighted case (default)
C    17 = sum W*DELTA**2 for profile fit
C    18   unused
C     .. Arrays in common block /SUMS/ ..
      REAL ASPOT
C     ..
C     .. Common Block /SUMS/ ..
      COMMON /SUMS/ASPOT(18)
C     ..
C
C
C&&*&& end_include  ../inc/sums.f
C     ..
C     .. Equivalences ..
      EQUIVALENCE (IRAS(1),NXS), (IRAS(2),NYS), (IRAS(3),NC)
      EQUIVALENCE (IRAS(4),NRX), (IRAS(5),NRY)
      EQUIVALENCE (ASPOT(1),SPOTW), (ASPOT(2),BGND),
     +            (ASPOT(3),RMSBG)
      EQUIVALENCE (ASPOT(4),DELX), (ASPOT(5),DELY)
C     ..
      SAVE                        
      DATA PASS2/.FALSE./,TOOBIG/.FALSE./,UPDATERIM/.FALSE./
     +     FIRSTTIME/.TRUE./
C
      LASTCHANGE = ' '
      NOTYET = .TRUE.
      CALLEDFROM = 'CHKRAS'
      NRFL = 1                      
      CTOT = 0.0
      NPBOX = 1
      LDENSE = .FALSE.
      ICYCLE = 0
      TOLSAVE = TOL
      TOLMINSAVE = TOLMIN
C
C---- If either background rim has just been expanded, keep track of
C     how many times this was done
C
      IF (UPDATERIM) THEN
        UPDATERIM = .FALSE.
      ELSE
        NTRY = 0
      END IF
C
      IF (DEBUG(15).AND.SPOT) THEN
        WRITE(IOUT,FMT=6032) NXS,NYS
        IF (ONLINE) WRITE(ITOUT,FMT=6032) NXS,NYS
        MAXPIX = 0
        CALL ODPLOT4(IODPROF(1),NXS,NYS,1,MAXPIX)
6032    FORMAT(/1X,'In CHKRAS, summed counts for average spot profile',
     +         ' box size',2I3,/)
      END IF
C
C
C---- PASS2 is TRUE if the best rim and corner parameters have already
C     been determined, but the overall box was too small to get a satisfactory
C     ratio of background to peak pixels. Under these circumstances CENTRS is
C     called again with a large box, and this box is used to determine the
C     best box size.
C
      IF (PASS2) GOTO 30
C
C
      NXY = NXS*NYS
      IF (NXY.LE.MAXBOX) GO TO 2
      NWRN = NWRN + 1
      IF (ONLINE) WRITE (ITOUT,FMT=6000) MAXBOX
      WRITE (IOUT,FMT=6000) MAXBOX
      GO TO 50
 2    CONTINUE
      NSIZ = (NXY+1)/2
C
C---- Find max od, scale raster sum
C                                                           
      MAXOD = 0
      MINOD = 100000000
C
C
      DO 4 I = 1,NXY
        MAXOD = MAX(MAXOD,IODPROF(I))
        MINOD = MIN(MINOD,IODPROF(I))
 4    CONTINUE
C
C
      SCALE = 255.0/ (MAXOD-MINOD)
C
C
      IF (DEBUG(15)) THEN
        IF (ONLINE) WRITE (ITOUT,6030) MINOD, MAXOD, SCALE
        WRITE (IOUT,6030) MINOD,MAXOD,SCALE
6030    FORMAT(/1X,' In CHKRAS, MINOD = ',I10,' MAXOD = ',I20,
     +         ' Initial SCALE using MINOD = ',F12.6)
      END IF
C                                         
C
C---- Find average spot shape and plot
C
      IF (BRIEF) WRITE (IBRIEF,FMT=6002)
      IF (ONLINE) WRITE (ITOUT,FMT=6002)
      WRITE (IOUT,FMT=6002)
C
C          ************************
      CALL SETMASK(MASK,IRAS)
      CALL SETSUMS(MASK,IRAS,PQVAL)
C          ************************
C
      TPEAK = PQVAL(5)
      TBGND = PQVAL(6)
      FULL = .TRUE.
      BGSIGL = BGSIG
      IF (FIRSTFILM) THEN
        BGFRACRESET = .FALSE.
        NBGFRACRESET = 0
      END IF
C
C---- If BGFRAC has been reset for the first image in this block
C     set BGFRAC to this modified value for all other images in the block.
C
C---- Set MODEBKG to 2, so that when INTEG calls EVAL it knows that
C     it is working with summed reflections, not single reflections.
C     This can affect the way it deals with low background values.
C
      MODEBKG = 2
C
      IF ((.NOT.FIRSTFILM).AND.(BGFRACRESET)) BGFRAC = BGFRACL
      IF (DEBUG(15)) THEN
        WRITE(IOUT,FMT=6036) FIRSTFILM,BGFRACRESET,BGFRAC,MODEBKG
        IF (ONLINE) WRITE(ItOUT,FMT=6036) FIRSTFILM,BGFRACRESET,BGFRAC,
     +   MODEBKG 
 6036   FORMAT(1X,'FIRSTFILM=',L2,' BGFRACRESET=',L2,' BGFRAC',F5.2,
     +         ' MODEBKG=',I2)
      END IF
C
C                  **********************************************
 6    CALL INTEG(IODPROF,IRAS,MASK,PQVAL,1,FULL,
     +                   BGSIGL,MASKREJ,PQSUMS,NRFL,MODEBKG)
C                  **********************************************
C
C---- Test if it is possible for neighbouring spots to intrude into the 
C     background region of the measurement box, based on the known cell
C     parameters (only considering the longest cell edge), the size of
C     the spots and the size of the measurement box. Test diagonal,
C     vertical and horizontal directions.
C     Test separately for each block of images as spot size could change.
c     Note that IXSEP, IYSEP are in 10 micron units, hence *50 (want half).x
C
      IF (FIRSTFILM) THEN
        CALL GETSEPN(DSEP)
        INTRUDE = (DSEP.LT.(0.5*RAST*IRAS(1)+ 0.005*IXSEP))
        INTRUDE = (INTRUDE.OR.(DSEP.LT.(0.5*RAST*IRAS(2)+ 0.005*IYSEP)))
        DIAG = 0.5*SQRT((RAST*IRAS(1))**2 + (RAST*IRAS(2))**2)
        DIAG = DIAG + SQRT((0.005*IXSEP)**2 + (0.005*IYSEP)**2)
        INTRUDE = (INTRUDE.OR.(DSEP.LT.DIAG))

        IF (DEBUG(15)) THEN
          WRITE(IOUT,FMT=6037) DSEP,ixsep,iysep,
     +        (0.5*RAST*IRAS(1)+0.005*IXSEP),
     +        (0.5*RAST*IRAS(2)+0.005*IYSEP),DIAG,INTRUDE     
          IF (ONLINE) WRITE(ITOUT,FMT=6037) DSEP,ixsep,iysep,
     +        (0.5*RAST*IRAS(1)+0.005*IXSEP),
     +        (0.5*RAST*IRAS(2)+0.005*IYSEP),DIAG,INTRUDE
 6037     FORMAT(1X,'DSEP',F5.2,'mm, ixsep',I5,' IYSEP',i5,
     +           ' distance test in X',F5.2,'mm',
     +         /,1X,'distance test in Y',F5.2,'mm' 
     +         /,1X,'distance test along diagonal',F5.2,'mm',
     +         /,1X,'INTRUDE=',L2) 
        END IF
      END IF

C---- For each image in a new block of images (FIRSTFILM), test to
C     see if, based on cell parameters and size of spot and and size
C     of measurement box whether adjacent reflections can intrude into
C     the background of the measurement box. If this is the case and
C     more than 75% of background pixels have been rejected as outliers
C     this could be because the background plane determination has failed.
C     Try reducing BGFRAC (fraction of background pixels used to determine
C     the background plane constants) in steps of 0.2, but with a minimum
C     value of 0.4, to see if this reduces the number of rejected background
C     pixels.
C
      IF (FIRSTFILM.AND.INTRUDE) THEN
        IF ((REAL(MASKREJ(1))/TBGND.GT.0.75).AND.(BGFRAC.GT.0.4)) THEN
          NBGFRACRESET = NBGFRACRESET + 1
          IF (NBGFRACRESET.EQ.1) BGFRACSAVE = BGFRAC
          BGFRACRESET = .TRUE.
          BGFRAC = MAX(BGFRAC-0.2,0.4)
          BGFRACL = BGFRAC
          IF (DEBUG(15)) THEN
            WRITE(IOUT,FMT=6038) MASKREJ(1),TBGND,BGFRAC
            IF (ONLINE) WRITE(ITOUT,FMT=6038) MASKREJ(1),TBGND,BGFRAC
 6038       FORMAT(1X,'Rejected background pixels',I5,' total number',
     +      F5.0,' BGFRAC reset to',F5.2,' and repeating')
          END IF
          GOTO 6
        END IF
      END IF
          
C                       
C---- Test that it has not rejected an unacceptable number of
C     background points, there must be NBGMIN points left (set by
C     subkeyword MINB under keyword REJECTION. If too many rejected
C     reflection is flagged with ASPOT(1)=-9999
C
        IF (ASPOT(1).EQ.-9999.0) THEN
          X = 2*BGSIGL
          IF (BRIEF) WRITE(IBRIEF,6020) BGSIGL,NBGMIN,X
          WRITE(IOUT,6020) BGSIGL,NBGMIN,X
          IF (ONLINE) WRITE(ITOUT,6020) BGSIGL,NBGMIN,X
 6020     FORMAT(//1X,'With the current BGSIG factor of',F6.2,
     +     ' there are fewer than ',I3,' background',/,1X,
     +     'pixels remaining ',
     +     'for this profile after rejecting outliers.',/,1X,
     +     'Increasing BGSIG to ',F6.2,' to allow determination ',
     +     'of average spot profile',/,1X,'and optimisation of',
     +     ' measurement box',/,1X,'BGSIG will be reset to its ',
     +     'original value for integration.')
           BGSIGL = X
           IF (BGSIGL.GT.100) THEN
             WRITE(IOUT,6021) BGSIGL
             IF (ONLINE) WRITE(ITOUT,6021) BGSIGL
             NSHUTERR = 1
             IERRLEVEL = 1
             WRITE(MESSAGE,FMT=6021)
 6021        FORMAT('Could not form average spot profile for centre',
     +              '__nl__of image, too many background points ',
     +              'rejected as outliers.__nl__Check prediction.')
             CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
           END IF
           GOTO 6
        END IF
C
C---- Get integrated intensity, sigma and I/sigma
C     Need TBGND and TPEAK
        NREJ = ASPOT(15)
C
C---- Must update number of background points to allow for rejected 
C     pixels. 
C
       TBGND = TBGND - NREJ
C                       
C---- Calculate standard deviation of intensity
C
        VSPOT = GAIN*SPOTW
        VBG = TPEAK*RMSBG*RMSBG
C                        
C
C---- This sigma does not include instrument error correction
C     (added later) unless the scanner error factor has been set explicitly
C
C *** Change this to counting statistics based value
C        ISDBSI = SQRT(2*VBG+ABS(VSPOT))*SCAI + 0.5
      AX = GAIN*(SPOTW+BGND+BGND*TPEAK/TBGND)
      ISDBSI=SQRT(AX) + 0.5
      IF (.NOT.PROPTCEN) THEN
        WRITE(IOUT,FMT=6100) TBGND,TPEAK,NREJ,SPOTW,BGND,ISDBSI,
     +                     SPOTW/FLOAT(ISDBSI)
        IF (ONLINE) WRITE(ITOUT,FMT=6100) TBGND,TPEAK,NREJ,SPOTW,BGND,
     +                     ISDBSI,SPOTW/FLOAT(ISDBSI)
      END IF
 6100 FORMAT(1X,'No backgnd points',F5.0,' Number peak pixels',F5.0,
     +      /,1X,'Number background rejected',I4,/,1X,'Intensity',
     +      f10.0,' BACKGROUND',F12.0,' sigma',I6,'  I/sig',F6.0)
C
 10   IF (PROPTCEN.AND.FIRSTFILM.AND.(FILM.EQ.1)) THEN
C
C---- First optimise the rim and corner parameters using the supplied
C     overall measurement box size. IRAS is updated by this call.
C     IFLAG is returned negative if BESTMASK fails, but this is not yet
C     coded.
C
C---- Set MASKREJ(1) to zero as this is now used by BESTMASK when setting
C     up the masks
C
        MASKREJ(1) = 0
        MODE = 0
C
C---- First see if neighbouring spots intrude
C
        IHX = NXS/2
        IHY = NYS/2
        IMODE = 0
        CALL PKRIM(IODPROF,CTOT,IHX,IHY,IMODE,NRXMIN,NRYMIN,NCMIN)
C
C---- Now test that the values of NRXMIN, NRYMIN, NCMIN are sensible...
C     if there is a very large error in the orientation, so the peak is
C     not in the centre of the box for the average spot profile,
C     the number returned can be meaningless. Ensure the resulting peak
C     is at least 5 pixels across.
C
        IF (NRXMIN.GT.IHX-2) NRXMIN = IHX - 2
        IF (NRYMIN.GT.IHY-2) NRYMIN = IHY - 2
        AX = NXS**2 + NYS**2
CAL        NCPKMIN = NINT(0.5*SQRT(AX) - 3)
C---- Subtracting 3 can give an unrealistically small value for NCPKMIN
C     that results in adjacent spots being included in peak area and was
C     not rigorous anyway. The following expression is correct, based on
C     the corner cutoff giving a diagonal peak size equivalent to two pixels
C     in X and Y.
C     
        NCPKMIN = IHX+IHY-NINT(2*(1+REAL(IHX)/REAL(IHY)))
        IF (NCMIN.GT.NCPKMIN) NCMIN = NCPKMIN
        CALL BESTMASK(IODPROF,IRAS,NPBOX,MODE,PQSUMS,MASKREJ,BGSIGL,
     +                IFLAG,CTOT,NRXMIN,NRYMIN,NCMIN,TOLMIN,NUMBLOCK)
C
C---- Now optimise the overall size to get the desired ratio of background
C     pixels to peak pixels (default 2), but ONLY for the first block
C     of images (otherwise small changes can make data quality worse).
C
        IF ((.NOT.FIXBOX).AND.(NUMBLOCK.EQ.1)) THEN    
C
C---- First get number of peak/background for current box
C
C         *****************************************
          CALL SETMASK(MASK,IRAS)
          CALL SETSUMS(MASK,IRAS,PQVAL)
 14       CALL INTEG(IODPROF,IRAS,MASK,PQVAL,1,FULL,
     +                   BGSIGL,MASKREJ,PQSUMS,NRFL,MODEBKG)
C         ******************************************
C                       
C---- Test that it has not rejected an unacceptable number of
C     background points, there must be NBGMIN points left (set by
C     subkeyword MINB under keyword REJECTION. If too many rejected
C     reflection is flagged with ASPOT(1)=-9999
C
          IF (ASPOT(1).EQ.-9999.0) THEN
            X = 2*BGSIGL
            IF (BRIEF) WRITE(IBRIEF,6020) BGSIGL,NBGMIN,X
            WRITE(IOUT,6020) BGSIGL,NBGMIN,X
            IF (ONLINE) WRITE(ITOUT,6020) BGSIGL,NBGMIN,X
           BGSIGL = X
           IF (BGSIGL.GT.100) THEN
             WRITE(IOUT,6023) BGSIGL
             IF (ONLINE) WRITE(ITOUT,6023) BGSIGL
 6023        FORMAT(/,/,1X,'***** FATAL ERROR *****',/,1X,
     +       'Value of ',F8.1,' for BGSIG is unreasonable.')
             NSHUTERR = 2
             IERRLEVEL = 1
             WRITE(MESSAGE,FMT=6021)
             CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
           END IF
           GOTO 14
          END IF
C
C---- fOLLOWING CODE NEEDS MORE CHECKS, DO NOT USE YET
C
          IF (NOTYET) GOTO 17
C
C---- Check that the background rims in X and Y are large enough, 
C     ie half the spot size or at least 3 pixels
C
          IRXMIN = (IRAS(1) - 2*IRAS(4))/2
          IRXMIN = MIN(IRXMIN,3)
          IRYMIN = (IRAS(2) - 2*IRAS(5))/2
          IRYMIN = MIN(IRYMIN,3)
          IF ((IRAS(4).LT.IRXMIN).OR.(IRAS(5).LT.IRYMIN)) THEN
C
C---- Increment number of attempts to update backgorund rim, give up
C     if more than 2 as this probably means spot shape is not well 
C     defined
C
            NTRY = NTRY + 1
            IF (NTRY.GT.2) GOTO 17
            IRXOLD = IRAS(4)
            IRYOLD = IRAS(5)
            IF (IRAS(4).LT.IRXMIN) THEN
C
C---- If X dimension has reached the limit, do not increase further
C
                IF ((IRAS(1) + 2*(IRXMIN-IRAS(4))).GT.MAXDIM) GOTO 17
                IRAS(1) = IRAS(1) + 2*(IRXMIN-IRAS(4))
                IRAS(3) = IRAS(3) + (IRXMIN-IRAS(4))/2
                IRAS(4) = IRXMIN
            END IF
            IF (IRAS(5).LT.IRYMIN) THEN
C
C---- If Y dimension has reached the limit, do not increase further
C
                IF ((IRAS(2) + 2*(IRYMIN-IRAS(5))).GT.MAXDIM) GOTO 17
                IRAS(2) = IRAS(2) + 2*(IRYMIN-IRAS(5))
                IRAS(3) = IRAS(3) + (IRYMIN-IRAS(5))/2
                IRAS(5) = IRYMIN
            END IF
            CHANGE = .FALSE.
 16         NXY = IRAS(1)*IRAS(2)
            IF (NXY.GT.MAXBOX) THEN
              CHANGE = .TRUE.
              IF (IRAS(1).GT.IRAS(2)) THEN
                IRAS(1) = IRAS(1) - 2
                GOTO 16
              ELSE
                IRAS(2) = IRAS(2) - 2
                GOTO 16
              END IF
            END IF
            IF (DEBUG(15)) THEN
              WRITE(IOUT,FMT=6034) NTRY,IRXOLD,IRXMIN,IRYOLD,IRYMIN,
     +                 IRAS
              IF (ONLINE) WRITE(ITOUT,FMT=6034) NTRY,IRXOLD,IRXMIN,
     +                               IRYOLD,IRYMIN,IRAS
 6034         FORMAT(1X,'NTRY=',i2,
     +               ' Either X or Y rim too small. X rim',I3,' min',
     +             ' is',I3,'  Y rim',I3,' min is',I3,/,1X,
     +             'Raster parameters updated to',5I5,/,1X,
     +             'Repeat formation of average spot profile.')
            END IF
C
C---- Do not repeat if the box has reached max size
C
            IF (CHANGE) GOTO 17
            UPDATERIM = .TRUE.
            RETURN
          END IF
C
C---- If background to peak pixel ratio too small, increase overall box size.
C
 17       NBGOLD = NINT(PQSUMS(6))
          RATIO = PQSUMS(6)/PQVAL(5)
          IF (DEBUG(15)) THEN
            NREJ = ASPOT(15) 
            WRITE(IOUT,FMT=6024) IRAS,RATIO,BGPKRAT,PQSUMS(6),
     +                           PQVAL(5),NREJ,BGFRAC
            IF (ONLINE) WRITE(ITOUT,FMT=6024) IRAS,RATIO,BGPKRAT,
     +                           PQSUMS(6),PQVAL(5),NREJ,BGFRAC
 6024       FORMAT(1X,'Current raster parameters:',5I5,/,1X,
     +             'Background/peak ratio actual, min',2F7.2,1X,
     +               ' numbers',2F5.0,' NREJ',I5,/,1X,'Current ',
     +              'BGFRAC',F5.2)
          END IF
          IF (RATIO.LT.BGPKRAT) THEN
C
C---- Need to determine how big a box will be needed to get desired ratio
C
            NSIZE = MIN(NXS,NYS)
            NBGEXTRA = BGPKRAT*PQVAL(5) - PQSUMS(6)
            NINC = NBGEXTRA/(NSIZE*2)
C
C---- Actually expand the box to get at least 1.5 times as many extra
C     background pixels as are required (to allow for rejection)
C     Change this, merely add 1
C            NINC = NINT(1.5*NINC) + 1
            NINC = NINC + 1
            IRAS(1) = IRAS(1) + 2*NINC
            IRAS(2) = IRAS(2) + 2*NINC
 18         NXY = IRAS(1)*IRAS(2)
            IF (NXY.GT.MAXBOX) THEN
              TOOBIG = .TRUE.
              IRAS(1) = IRAS(1) - 2
              IRAS(2) = IRAS(2) - 2
              NINC = NINC - 1
              GOTO 18
            END IF
C
C---- Now check that box size does not exceed MAXDIM. If it does, try
C     to increase the box size in the other direction, but check total size
C     does not exceed MAXBOX
C
            ICUTX = 0
            ICUTY = 0
 20         IF (IRAS(1).GT.MAXDIM) THEN
              IRAS(1) = IRAS(1) - 2
              IF (IRAS(2).LT.MAXDIM) THEN
                IRAS(2) = IRAS(2) + 2
                ICUTY = ICUTY - 1
                NXY = IRAS(1)*IRAS(2)
                IF (NXY.GT.MAXBOX) THEN
                  IRAS(2) = IRAS(2) - 2
                  ICUTY = ICUTY + 1
                END IF
              END IF
              ICUTX = ICUTX + 1
              GOTO 20
            END IF
 22         IF (IRAS(2).GT.MAXDIM) THEN
              IRAS(2) = IRAS(2) - 2
              IF (IRAS(1).LT.MAXDIM) THEN
                IRAS(1) = IRAS(1) + 2
                ICUTX = ICUTX - 1
                NXY = IRAS(1)*IRAS(2)
                IF (NXY.GT.MAXBOX) THEN
                  IRAS(1) = IRAS(1) - 2
                  ICUTX = ICUTX + 1
                END IF
              END IF
              ICUTY = ICUTY + 1
              GOTO 22
            END IF
C
C---- Increase corner cutoff and rims so peak size remains the same
C
            IF ((ICUTX.EQ.0).AND.(ICUTY.EQ.0)) THEN
              DO 24 I = 3,5
                IRAS(I) = IRAS(I) + NINC
 24          CONTINUE
            ELSE
              IRAS(3) = IRAS(3) + NINC - ICUTX
              IRAS(4) = IRAS(4) + NINC - ICUTX
              IRAS(5) = IRAS(5) + NINC - ICUTY
            END IF
C
            PASS2 = .TRUE.
            IF (DEBUG(15)) THEN
              WRITE(IOUT,FMT=6025) NBGEXTRA,2*NINC,IRAS
              IF (ONLINE) WRITE(ITOUT,FMT=6025) NBGEXTRA,2*NINC,IRAS
 6025         FORMAT(1X,I5,' Extra background points required, box',
     +               ' expanded by',I3,' pixels in X and Y',/,1X,
     +               'New raster parameters',5I5)
            END IF
C
C---- Give warning if desired background:peak ratio could not be achieved
C     because of limitations on the total box size.
C
            IF (TOOBIG) THEN
              WRITE(IOUT,FMT=6050) BGPKRAT,MAXBOX
              IF (ONLINE) WRITE(ITOUT,FMT=6050) BGPKRAT,MAXBOX
 6050   FORMAT(/,1X,' *** WARNING ***',/,1X,'Cannot achieve a ',
     +        'ratio of ',F4.0,' in the number of background',
     +        ' to peak',/,1X,'pixels because',
     +        ' the maximum boxsize (',I5,') is too small.',/,1X,
     +        'If you need this ratio, recompile the program after',
     +        ' increasing PARAMETER MAXBOX',/,1X,'with a global edit')
              TOOBIG = .FALSE.
            END IF
            RETURN
          END IF 
        END IF
      END IF
C
C---- Now go to display profile
C
      GOTO 46
C
C---- Only come this route if the average spot profile has been recollected
C     using an enlarged box (PASS2 true). Now find the best box size to
C     give desired background to peak ratio.
C
 30   PASS2 = .FALSE.
      IRBIG(1) = NXS
      IRBIG(2) = NYS
      NXY = NXS*NYS
C
C---- Reset IRAS to original values
C
      NXS = NXS - 2*NINC
      NYS = NYS - 2*NINC
              IRAS(3) = IRAS(3) - NINC + ICUTX
              IRAS(4) = IRAS(4) - NINC + ICUTX
              IRAS(5) = IRAS(5) - NINC + ICUTY
CAL      DO 32 I = 3,5
CAL        IRAS(I) = IRAS(I) - NINC
CAL 32   CONTINUE
C
C---- Transfer the enlarged box pixel values to IODBIG
C
      DO 34 I = 1,NXY
        IODBIG(I) = IODPROF(I)
 34   CONTINUE
C
C---- Find which direction (X or Y) gives greatest number of additional
C     background points (after allowing for rejections).
C     First try X, reset NXX, X rim, corner cutoff
 36   IRAS(1) = IRAS(1) + 2
      IRAS(3) = IRAS(3) + 1
      IRAS(4) = IRAS(4) + 1
C
C---- Must stop X expanding beyond maximum value
C
      IF (IRAS(1).GT.IRBIG(1)) THEN
        STOPX = .TRUE.
        GOTO 37
      END IF
C     *****************************************
      CALL SETMASK(MASK,IRAS)
      CALL SETSUMS(MASK,IRAS,PQVAL)
      CALL EXTRACT(IODBIG,IRBIG,IRAS,IODPROF)
      CALL INTEG(IODPROF,IRAS,MASK,PQVAL,1,FULL,
     +               BGSIGL,MASKREJ,PQSUMS,NRFL,MODEBKG)
C     ******************************************
C                       
C---- Test that it has not rejected an unacceptable number of
C     background points, there must be NBGMIN points left (set by
C     subkeyword MINB under keyword REJECTION. If too many rejected
C     reflection is flagged with ASPOT(1)=-9999
C
       IF (ASPOT(1).EQ.-9999.0) THEN
         STOPX = .TRUE.
         PREJX = 0.0
         GOTO 37
       END IF
C
C---- See what percentage of new background pixels were accepted
C
      NBGOLDX = NINT(PQSUMS(6))
      PREJX = (PQSUMS(6) - NBGOLD)/(2.0*NYS)
      RATIOX = PQSUMS(6)/PQVAL(5)
      STOPX = (PREJX.LT.FRACREJ)
C
      IF (DEBUG(15)) THEN
        NREJ = ASPOT(15)
        WRITE(IOUT,FMT=6022) IRAS,PREJX,RATIOX,NBGOLD,NREJ,STOPX
        IF (ONLINE) WRITE(ITOUT,FMT=6022) IRAS,PREJX,RATIOX,
     +                                    NBGOLD,NREJ,STOPX
 6022 FORMAT(1X,'Changing X, raster',5I4,' acceptance ratio, bk/pk',
     +       2F6.2,'  NBGOLD',I5,' NREJ',I5,' STOPX:',L2)
      END IF
C
C---- If the box is way too small, so there are fewer background points than
C     before, try just making it bigger
C
      IF (PREJX.LT.0) GOTO 36
C
C---- Now try Y, first reset NXX and X rim
C
 37   IRAS(1) = IRAS(1) - 2
      IRAS(4) = IRAS(4) - 1
C
C---- Increment NYY and Y rim
C
 38   IRAS(2) = IRAS(2) + 2
      IRAS(5) = IRAS(5) + 1
C
C---- Must stop Y expanding beyond maximum value
C
      IF (IRAS(2).GT.IRBIG(2)) THEN
        IF (.NOT.STOPX) THEN
          IRAS(2) = IRAS(2) - 2
          IRAS(5) = IRAS(5) - 1
        END IF
        STOPY = .TRUE.
        GOTO 39
      END IF
C     *****************************************
      CALL SETMASK(MASK,IRAS)
      CALL SETSUMS(MASK,IRAS,PQVAL)
      CALL EXTRACT(IODBIG,IRBIG,IRAS,IODPROF)
      CALL INTEG(IODPROF,IRAS,MASK,PQVAL,1,FULL,
     +         BGSIGL,MASKREJ,PQSUMS,NRFL,MODEBKG)
C     ******************************************
C                       
C---- Test that it has not rejected an unacceptable number of
C     background points, there must be NBGMIN points left (set by
C     subkeyword MINB under keyword REJECTION. If too many rejected
C     reflection is flagged with ASPOT(1)=-9999
C
       IF (ASPOT(1).EQ.-9999.0) THEN
         STOPY = .TRUE.
         PREJY = 0.0
         GOTO 39
       END IF
C
C---- See what percentage of new background pixels were accepted
C
      NBGOLDY = NINT(PQSUMS(6))
      PREJY = (PQSUMS(6) - NBGOLD)/(2.0*NXS)
      RATIOY = PQSUMS(6)/PQVAL(5)
      STOPY = (PREJY.LT.FRACREJ)
      IF (DEBUG(15)) THEN
        NREJ = ASPOT(15)
        WRITE(IOUT,FMT=6026) IRAS,PREJY,RATIOY,NBGOLD,NREJ,STOPY
        IF (ONLINE) WRITE(ITOUT,FMT=6026) IRAS,PREJY,RATIOY,
     +                                    NBGOLD,NREJ,STOPY
 6026 FORMAT(1X,'Changing Y, raster',5I4,' acceptance ratio, bk/pk',
     +       2F6.2,'  NBGOLD',I5,' NREJ',I5,' STOPY:',L2)
      END IF
C
C---- If the box is way too small, so there are fewer background points than
C     before, try just making it bigger
C
      IF (PREJY.LT.0) GOTO 37
C
C---- Give up if both fail FRACREJ limit. Need to reset Y parameters
C     and NC
C
 39   IF (STOPX.AND.STOPY) THEN
C
C---- Rather than giving up, want to decrease FRACREJ and try again
C     but don't reduce it beyond 0.1
C
        IRAS(2) = IRAS(2) -2
        IRAS(3) = IRAS(3) -1
        IRAS(5) = IRAS(5) -1
        IF (FRACREJ.GT.0.1) THEN
          FRACREJ = MAX(FRACREJ-0.1,0.100)
          IF (DEBUG(15)) THEN
            WRITE(IOUT,FMT=6027) FRACREJ,IRAS
            IF (ONLINE) WRITE(ITOUT,FMT=6027) FRACREJ,IRAS
 6027       FORMAT(1X,'Decrease FRACREJ to',F4.2,' IRAS',5I5)
          END IF
          GOTO 36
        ELSE
          GOTO 42
        END IF
      END IF
C                       
C---- IS X or Y better in terms of giving a better background to peak ratio ?
C     If this is not the first expansion, then use expansion in the other direction
C     this time unless it is much worse.
C
      IF ((LASTCHANGE.EQ.'X').AND.(.NOT.STOPY).AND.
     +                                       (PREJX/PREJY.LT.2)) THEN
C
C---- Change Y this time
C
C
C---- Jump out if ratio now OK, or too many points have
C     been rejected in Y
C
        IF (RATIOY.GT.BGPKRAT) GOTO 42
        NBGOLD = NBGOLDY
        LASTCHANGE = 'Y'
C
C---- Go back and try X again, unless too many points rejected in X
        IF (.NOT.STOPX) THEN
          GOTO 36
        ELSE
          GOTO 38
        END IF
      ELSE IF ((LASTCHANGE.EQ.'Y').AND.(.NOT.STOPX).AND.
     +                                       (PREJY/PREJX.LT.2)) THEN
C
C---- Change X this time
C
        IRAS(1) = IRAS(1) + 2
        IRAS(2) = IRAS(2) - 2
        IRAS(4) = IRAS(4) + 1
        IRAS(5) = IRAS(5) - 1
        NBGOLD = NBGOLDX
C
C---- Jump out if ratio now OK
C
        IF (RATIOX.GT.BGPKRAT) GOTO 42
        LASTCHANGE = 'X'
        GOTO 36
      END IF
C
C--- First time round, see if one is much better than the other
C 
      IF ((PREJX/PREJY.GT.2.0).AND.(.NOT.STOPX)) THEN
C
C--- X is better, set raster parameters to those used for expansion in X
C
        IRAS(1) = IRAS(1) + 2
        IRAS(2) = IRAS(2) - 2
        IRAS(4) = IRAS(4) + 1
        IRAS(5) = IRAS(5) - 1
        NBGOLD = NBGOLDX
C
C---- Jump out if ratio now OK
C
        IF (RATIOX.GT.BGPKRAT) GOTO 42
        LASTCHANGE = 'X'
        GOTO 36
      ELSE IF (PREJY/PREJX.GT.2.0) THEN
C
C---- Y is best, jump out if ratio now OK, or too many points have
C     been rejected in Y
C
        IF ((RATIOY.GT.BGPKRAT).OR.(STOPY)) GOTO 42
        NBGOLD = NBGOLDY
        LASTCHANGE = 'Y'
C
C---- Go back and try X again, unless too many points rejected in X
        IF (.NOT.STOPX) THEN
          GOTO 36
        ELSE
          GOTO 38
        END IF
      ELSE
C
C---- If neither is obviously better, choose the expansion that gives more
C     equal rim sizes in X and Y.
C
        IXRIMX = IRAS(4) + 1
        IXRIMY = IRAS(5) - 1
        IYRIMX = IRAS(4)
        IYRIMY = IRAS(5)
        IF (ABS(IXRIMX-IXRIMY).LT.ABS(IYRIMX-IYRIMY)) THEN
C
C---- X is best
C
          IRAS(1) = IRAS(1) + 2
          IRAS(2) = IRAS(2) - 2
          IRAS(4) = IRAS(4) + 1
          IRAS(5) = IRAS(5) - 1
          NBGOLD = NBGOLDX
C
C---- Jump out if ratio now OK
C
          IF (RATIOX.GT.BGPKRAT) GOTO 42
          LASTCHANGE = 'X'
          GOTO 36
        ELSE
C
C---- Y is best
C
          IF ((RATIOY.GT.BGPKRAT).OR.(STOPY)) GOTO 42
          NBGOLD = NBGOLDY
          LASTCHANGE = 'Y'
C
C---- Go back and try X again, unless too many points rejected in X
          IF (.NOT.STOPX) THEN
            GOTO 36
          ELSE
            GOTO 38
          END IF
        END IF
      END IF
C
C---- Call INTEG again so that the rejected background pixels in MASKREJ
C     are those for selected raster parameters
C
C     *****************************************
 42   CALL SETMASK(MASK,IRAS)
      CALL SETSUMS(MASK,IRAS,PQVAL)
      CALL EXTRACT(IODBIG,IRBIG,IRAS,IODPROF)
      CALL INTEG(IODPROF,IRAS,MASK,PQVAL,1,FULL,
     +         BGSIGL,MASKREJ,PQSUMS,NRFL,MODEBKG)
C     ******************************************
C
      IF (DEBUG(15)) THEN
        WRITE(IOUT,FMT=6040) IRAS,PQSUMS(6),MASKREJ(1)
        IF (ONLINE) WRITE(ITOUT,FMT=6040) IRAS,PQSUMS(6),MASKREJ(1)
 6040   FORMAT(1X,'Final raster parameters',5I4,/1X,'Number of ',
     +        'background points used',F5.0,' Number rejected',I4)
        IF (SPOT) THEN
          WRITE(IOUT,FMT=6042) NXS,NYS
          IF (ONLINE) WRITE(ITOUT,FMT=6042) NXS,NYS
          MAXPIX = 0
          CALL ODPLOT4(IODPROF(1),NXS,NYS,1,MAXPIX)
 6042   FORMAT(/1X,'In CHKRAS, summed counts for average spot profile',
     +         ' box size',2I3,/)
        END IF
      END IF
C                       
C---- Test that it has not rejected an unacceptable number of
C     background points, there must be NBGMIN points left (set by
C     subkeyword MINB under keyword REJECTION. If too many rejected
C     reflection is flagged with ASPOT(1)=-9999
C
        IF (ASPOT(1).EQ.-9999.0) THEN
          IF (BRIEF) WRITE(IBRIEF,6020) BGSIGL,NBGMIN,X
          WRITE(IOUT,6020) BGSIGL,NBGMIN,X
          IF (ONLINE) WRITE(ITOUT,6020) BGSIGL,NBGMIN,X
          NSHUTERR = 3
          IERRLEVEL = 1
          WRITE(MESSAGE,FMT=6021)
          CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
        END IF
C
C---- Need to rescale with new box. Find max od, scale raster sum
C                                                           
      MAXOD = 0
      MINOD = 100000000
C
C
      DO 44 I = 1,NXY
        MAXOD = MAX(MAXOD,IODPROF(I))
        MINOD = MIN(MINOD,IODPROF(I))
   44 CONTINUE
C
C---- Now use background plane constant ASPOT(11) rather than MINOD
C     to work out SCALE
C
      SCALE = 255.0/ (MAXOD-ASPOT(11))
C

C
C---- Now display the final profile with the best mask parameters and box size
C
 46   CONTINUE
C          ************************
      CALL SETMASK(MASK,IRAS)
      CALL SETSUMS(MASK,IRAS,PQVAL)
C          ************************
      DELX = (DELX+IXSHIFT)/FACT
      DELY = (DELY+IYSHIFT)/FACT
      IF (PROPTCEN.AND.FIRSTFILM.AND.(FILM.EQ.1)) THEN
        WRITE (IOUT,FMT=6003) IRAS,NINT(PQVAL(5)),NINT(PQSUMS(6))
        IF (ONLINE) WRITE (ITOUT,FMT=6003) IRAS,NINT(PQVAL(5)),
     +                                     NINT(PQSUMS(6))
        IF (BRIEF) WRITE (IBRIEF,FMT=6003) IRAS,NINT(PQVAL(5)),
     +                                     NINT(PQSUMS(6))
C
C---- Calculate spot size in X and Y in mm
C
        XWARN(1,1) = RAST*(IRAS(1)-2*IRAS(4))
        XWARN(2,1) = RAST*(IRAS(2)-2*IRAS(5))
C
C---- If a SEPARATION keyword was not given and the separation was
C     therefore worked out from the median spot size, update the 
C     separation parameters using this spot size. In this case,
C     do NOT add on the safety factor of 2 pixels
C
        IF (ISEP.NE.2) THEN
          IXSEP = 100.0*XWARN(1,1)
          IYSEP = 100.0*XWARN(2,1)
          MINDTX = NINT(ABS(IXSEP*COSOM0 + IYSEP*SINOM0))
          MINDTY = NINT(ABS(IYSEP*COSOM0 + IXSEP*SINOM0))
          WRITE(IOUT,FMT=6007) 0.01*IXSEP,0.01*IYSEP
          IF (ONLINE) WRITE(ITOUT,FMT=6007) 0.01*IXSEP,0.01*IYSEP
C
C---- Check if the spot size is smaller than the minimum spot separation
C     by a factor of 1.25. If not, increase the PROFILE TOLERANCE values
C     and repeat mask optimisation. Do this up to a maximum value of 0.06.
C     If this criterion is still not met, set the TOLERANCE to the minimum value
C     that gives the smallest spot size (in X or in Y), to avoid using
C     a larger TOLERANCE than necessary.
C
          CALL GETSEPN(DSEP)
          IF (DEBUG(15)) THEN
            WRITE(IOUT,FMT=6043) DSEP
            IF (ONLINE) WRITE(ITOUT,FMT=6043) DSEP
 6043       FORMAT(1X,'Minimum possible spot separation is',F6.2,'mm.')
          END IF
          IF (DSEP.LT.1.25*MAX(0.01*IXSEP,0.01*IYSEP)
     $         .AND.ITOL.NE.2) THEN
CAL            IF ((ITOL.EQ.0).AND.(TOL.LE.0.05)) THEN
            ICYCLE = ICYCLE + 1
C
C---- Store current tolerance values and minimum separation
C
            TOLCYCLE(ICYCLE) = TOL
            TOLMINCYCLE(ICYCLE) = TOLMIN
            SEPXCYCLE(ICYCLE) = 0.01*IXSEP
            SEPYCYCLE(ICYCLE) = 0.01*IYSEP
C
C---- do not allow TOLERANCE to go above 0.05 (watch for rounding errors)
C
            IF ((TOL.LT.0.05).AND.(ABS(TOL-0.05).GT.0.002)) THEN
              IF (ISYN.EQ.1) THEN
                TOLMIN = TOLMIN + 0.01
                TOL = TOL + 0.01
              ELSE 
                IF (FIRSTTIME) THEN
                  TOLMIN = TOLMIN + 0.02
                  TOL = TOL + 0.02
                ELSE
                  TOLMIN = TOLMIN + 0.01
                  TOL = TOL + 0.01
                END IF
              END IF
              FIRSTTIME = .FALSE.
              WRITE(IOUT,FMT=6044) DSEP,TOLMIN,TOL
              IF (ONLINE) WRITE(ITOUT,FMT=6044) DSEP,TOLMIN,TOL
 6044         FORMAT(1X,'Minimum possible spot separation',F6.2,'mm. ',
     +               'is less than 1.25 times spot size',/,1X,
     +               'Profile tolerances increased to',2F6.2,/)
              GOTO 10
            ELSE
C
C---- No further increase in TOL allowed, choose the best value, ie the minimum
C     tolerance that gives the same separation as higher values.
C
              DO 47 I = ICYCLE,2,-1
                IF ((SEPXCYCLE(I).LT.SEPXCYCLE(I-1)).OR.
     +              (SEPYCYCLE(I).LT.SEPYCYCLE(I-1))) THEN
                  TOL = TOLCYCLE(I)
                  TOLMIN = TOLMINCYCLE(I)
                  GOTO 48
                END IF
 47           CONTINUE
C
C---- If there has been no jump out of the DO 47 loop, assign the ICYCLE=1 values
C
              TOL = TOLCYCLE(1)
              TOLMIN = TOLMINCYCLE(1)
            END IF
          END IF
C
C---- Finally check that minimum spot separation is not greater than separation
C     of the closest reciprocal lattice points. The spot separation can
C     actually be smaller than that calculated from "precession" geometry
C     depending on inclination of longest axis to rotation axis. So reduce DSEP
C     to 90% of the precession geometry value for this test.
C     Note that there is no distinction made (at present) based on
C     the actual orientation of the longest axis, this needs to be
C     added.
C
 48       IF ((0.01*IXSEP.GT.0.9*DSEP).OR.(0.01*IYSEP.GT.0.9*DSEP))THEN
            IF (0.01*IXSEP.GT.0.9*DSEP) IXSEP = 90.0*DSEP
            IF (0.01*IYSEP.GT.0.9*DSEP) IYSEP = 90.0*DSEP
            MINDTX = NINT(ABS(IXSEP*COSOM0 + IYSEP*SINOM0))
            MINDTY = NINT(ABS(IYSEP*COSOM0 + IXSEP*SINOM0))
            WRITE(IOUT,FMT=6046) 0.01*IXSEP,0.01*IYSEP
            IF (ONLINE) WRITE(ITOUT,FMT=6046) 0.01*IXSEP,0.01*IYSEP
 6046       FORMAT(1X,'To avoid overlap of spots along the longest',
     +                ' axis, the separation has been updated to',2F6.2)
          END IF
        END IF
C
C---- Write back new values for RASTER and SEPARATION to new GUI
C     ***** want to write back updated tolerance values too ***
C
        IF (ICYCLE.GT.0) THEN
          WRITE(IOUT,FMT=6045) TOLMIN,TOL
          IF (ONLINE) WRITE(ITOUT,FMT=6045) TOLMIN,TOL
 6045     FORMAT(1X,'Final profile tolerances set to', 2F6.2,/)
C
C---- Set an INFO warning
C
          IF ((TOL.GT.TOLSAVE).OR.(TOLMIN.GT.TOLMINSAVE)) THEN
            WARN(38) = .TRUE.
          END IF
        END IF
C
        IF (SOCKLO) THEN
          WRITE(LONGLINE, FMT=6110) IRAS,0.01*IXSEP,0.01*IYSEP,
     $                              TOLMIN,TOL
          CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(LONGLINE),
     $         LONGLINE)
        END IF
 6110   FORMAT('<?xml version="1.0"?>',
     $     '<!DOCTYPE updated_raster_and_separation>',
     $     '<updated_raster_and_separation>',
     $     '<raster>',5I4,'</raster>',
     $     '<separation>',2F6.2,'</separation>',
     $     '<profile_tolerances>',2F6.2,'</profile_tolerances>',
     $     '</updated_raster_and_separation>')

      END IF
      WRITE (IOUT,FMT=6004) 0.01*DELX,0.01*DELY,RMSBG*SCALE
      IF (ONLINE)WRITE (ITOUT,FMT=6004) 0.01*DELX,0.01*DELY,RMSBG*SCALE
      IF (BRIEF)WRITE (IBRIEF,FMT=6004) 0.01*DELX,0.01*DELY,RMSBG*SCALE
C
      DO 49 I = 1,NXY
        IODPROF(I) = (IODPROF(I)-ASPOT(11))*SCALE + 0.5
CAL        IODPROF(I) = (IODPROF(I)-MINOD)*SCALE + 0.5
 49   CONTINUE

      ODSCALE = 1.0
C                                       
C          ***************************************
      CALL RASPLOT(ID,IODPROF,NXS,NYS,MASK,MASKREJ,1,ODSCALE,FINAL)
C          ***************************************
C
C---- See if it is possible to detect if the peak region has been made too large
C     and includes more than one spot. 
C
      CALL CLUSTER(IRAS,MASK,MASKREJ,NCLUSTER,DIST,NPREJ,REJECT)
C
C     Note that NPREJ is -ve if the cluster abuts a peak pixel, this is
C     used to select only clusters that about the peak in test below.
C
      IF (NCLUSTER.GT.0) THEN
        DISTMIN = 100.0
        DO 100 I = 1,NCLUSTER
          IF (NPREJ(I).LE.-4) THEN
            DISTMIN = MIN(DISTMIN,DIST(I))
          END IF
 100    CONTINUE
        DISTMIN2 = DISTMIN + 0.00001
        IF (NCLUSTER.GT.1) THEN
          DO 102 I = 1,NCLUSTER
            IF (NPREJ(I).LE.-4) THEN
              IF (DIST(I).GT.DISTMIN2) THEN
                DISTMIN2 = MIN(DISTMIN2,DIST(I))
              END IF 
            END IF 
 102      CONTINUE
          DISTMIN2 = DISTMIN2*RAST
        END IF 
        DISTMIN = DISTMIN*RAST
        CALL GETSEPN(DSEP)
C
C---- The following warning gives false positives and the test needs to be made
C     more sophisticated if it is going to be used. The original case was due 
C     to the limits for searching NC in BESTMASK not being set correctly and
C     this has been fixed, so it is quite possible this test is not required.
C     simply comment out for now. agwl April 2018
C
        IF (DISTMIN.LT.1.3*DSEP) THEN
CAL          WRITE(IOUT,FMT=6070) DISTMIN,DSEP
CAL          IF (ONLINE) WRITE(ITOUT,FMT=6070) DISTMIN,DSEP
 6070     FORMAT(/,1X,'The peak region of the average spot '
     +           'profile for the central region',/,1X,'appears to ',
     +           'include part of an adjacent spot.',/,1X,
     +           'Distance to adjacent spot is',F5.2,
     +           'mm compared to a minimum spot',/,1X,'separation of ',
     +           F5.2,'mm based on cell parameters.',/,1X,
     +           'This suggests that the optimisation of ',
     +           'the measurement box parameters',/,1X,'(NRX, NRY, NC)',
     +           ' has not worked correctly',/,1x,'See warning',
     +           ' messages at end of log file.')
CAL          WARN(35) = .TRUE.
CAL          XWARN(1,35) = DSEP
CAL          XWARN(2,35) = DISTMIN
CAL          XWARN(3,35) = DISTMIN2
CAL          IWARN(1,35) = NCLUSTER
        END IF
      END IF
C
      IF (PROPTCEN.AND.FIRSTFILM.AND.(FILM.EQ.1)) THEN
        WRITE(IOUT,FMT=6005)
        IF (ONLINE) WRITE(ITOUT,FMT=6005)
 6005 FORMAT(/,1X,'If the peak region is too large, supply two',
     +       ' values on the PROFILE TOLERANCE keyword.',/,1X,'The ',
     +       'first value is used for the centre of the image, and',
     +       ' the second for the',/,1X,'outermost profiles. See ',
     +       'the helpfile for details.')
      END IF
C
      IF (.NOT.ONLINE) THEN
        AVPROFILE = .FALSE.
        GO TO 999
      END IF
C
C                 *********
      IF (ONLINE.AND.LBELL) CALL BELL
C                 *********
C
      IF (PROPTCEN) THEN
        AVPROFILE = .FALSE.
        GO TO 80
      END IF
C
C---- If not optimising the profile, and running interactively, give the
C     opportunity to manually change the measurement box parameters
C     but ONLY for the first image in each block
C
C---- Do not do this if running with imosflm
C
      IF (SOCKLO) GOTO 80
C
      IF (.NOT.FIRSTFILM) GOTO 80
C
      IF (WINOPEN) THEN
          IXM = 200
          IYM = 200
          LINELEN = 75
          NUMLIN = 15
C     
C     Create IO window
C
          CALL MXDCIO(0,LINELEN, NUMLIN, IXM,IYM)

C---- Do you want to 
C
 52       LINE = ' '
          WRITE(LINE,FMT=6060)
 6060     FORMAT('Do you want to change the measurement box',
     +          ' parameters (N):')
          CALL MXDWIO(LINE, 1)
          CALL MXDRIO(LINE2)
C
C---- Parse reply
C
C                ******************************************
          CALL MPARSE(LINE2,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C                ******************************************
          IF (NTOK.EQ.0) THEN
            STR1 = 'N'
          ELSE
            STR1 = LINE2(IBEG(1):IEND(1))
            CALL CCPUPC(STR1)
          END IF
          IF (STR1.EQ.'Y') THEN
            WRITE(LINE,FMT=6062) IRAS
 6062       FORMAT('Current parameters are:',5I5)
            CALL MXDWIO(LINE, 1)
            WRITE(LINE,FMT=6064)
 6064       FORMAT('Give new parameters:')
            CALL MXDWIO(LINE,1)
            CALL MXDRIO(LINE2)
C
C---- Get numbers using PARSER
C
C                    ******************************************
            CALL MPARSE(LINE2,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C                    ******************************************
            IF (NTOK.EQ.0) THEN
               GOTO 54
            ELSE IF (NTOK.EQ.5) THEN
               CALL MKEYNM(2,1,LINE2,IBEG,IEND,ITYP,NTOK)
               IF (IOERR) GOTO 52
               NEWRAS = 1
               IRAS(1) = NINT(VALUE(1))
               IRAS(2) = NINT(VALUE(2))
               IRAS(3) = NINT(VALUE(3))
               IRAS(4) = NINT(VALUE(4))
               IRAS(5) = NINT(VALUE(5))
            ELSE
               GOTO 52
            END IF
C
C---- various tests on supplied parameters
C
            IF (((MOD(NXS,2).NE.1) .OR. (NXS.GT.MAXDIM)) .OR.
     +            ((MOD(NYS,2).NE.1) .OR. (NYS.GT.MAXDIM))) THEN
              WRITE(LINE,6066) MAXDIM
 6066        FORMAT('NXS, NYS (first two values) must be ODD and less',
     +             ' than',I3)
              CALL MXDWIO(LINE,1)
              GOTO 52
            END IF
            IF (NC.LE.0) THEN 
              WRITE(LINE,6067) 
 6067         FORMAT('NC (third value) must be > 0')
              CALL MXDWIO(LINE,1)
              GOTO 52
            END IF
            DO 56 I = 1,5
              IF (IRAS(I).LE.0) THEN
                WRITE(LINE,6068) 
 6068           FORMAT('All values must be > zero')
                CALL MXDWIO(LINE,1)
                GOTO 52
              END IF 
 56         CONTINUE
C
C---- Return to form new profile
C
            CALL MXDCIO(1,0,0,0,0)
C
C---- Reset BGFRAC
C
            IF (BGFRACRESET) BGFRAC = BGFRACSAVE
            RETURN
          END IF 
 54       CALL MXDCIO(1,0,0,0,0)
          GOTO 80
      END IF
C
C---- If window not open, direct question to terminal window
C
      IF (BRIEF) WRITE (IBRIEF,FMT=6006)
      WRITE (ITOUT,FMT=6006)
      READ (ITIN,FMT=6008,END=80) JUNK
C
C        ****************   
      CALL NOYES(JUNK,ISW2)
C        ****************
C ISW2 returned as 1 if Y or y, otherwise 0
C
      IF (ISW2.EQ.0) THEN
        AVPROFILE = .FALSE.
        GO TO 80
      END IF
   50 WRITE (IOUT,FMT=6010)
C
C                 *********
      IF (ONLINE.AND.LBELL) CALL BELL
C                 *********
C
      IF (BRIEF) WRITE (IBRIEF,FMT=6010)
      WRITE (ITOUT,FMT=6010)
      IF (BRIEF) WRITE (IBRIEF,FMT=6012) IRAS,IXSHIFT,IYSHIFT
      WRITE (ITOUT,FMT=6012) IRAS,IXSHIFT,IYSHIFT
      WRITE (IOUT,FMT=6012) IRAS,IXSHIFT,IYSHIFT
      READ (ITIN,FMT=6014) KRAS,KXSHIFT,KYSHIFT
      WRITE (IOUT,FMT=6015) KRAS,KXSHIFT,KYSHIFT
 6015 FORMAT(1X,7I5)
C
C
      DO 70 I = 1,5
        IF (KRAS(I).EQ.0) GO TO 60
        NEWRAS = 1
C
C---- A value of 99 is interpreted as zero
C
        IF (KRAS(I).EQ.99) THEN
          IRAS(I) = 0
        ELSE
          IRAS(I) = KRAS(I)
        END IF
C
C
   60     CONTINUE
   70   CONTINUE
C
      IF (KXSHIFT.NE.0) IXSHIFT = KXSHIFT
      IF (KXSHIFT.EQ.99) IXSHIFT = 0
      IF (KYSHIFT.NE.0) IYSHIFT = KYSHIFT
      IF (KYSHIFT.EQ.99) IYSHIFT = 0
C
      IF (((MOD(NXS,2).NE.1) .OR. (NXS.GT.MAXDIM))
     +   .OR.((MOD(NYS,2).NE.1) .OR. (NYS.GT.MAXDIM))) THEN
         WRITE (ITOUT,FMT=6016) MAXDIM
         IF (BRIEF) WRITE (IBRIEF,FMT=6016) MAXDIM
         GO TO 50
      END IF
C
C---- Reset BGFRAC
C
      IF (BGFRACRESET) BGFRAC = BGFRACSAVE
      RETURN
C
   80 CONTINUE
C
C---- Update maxr for precession photographs (done in s/r rmaxr for
C     oscillation films)
C
      IF (FIRSTFILM) MAXR = NXS*NYS
C
C
 999  AVPROFILE = .FALSE.
C
C---- Reset profile to original values but subtract background, then set
C     to zero at all background points, as this average
C     profile is used to provide the weights when deriving best standard
C     profiles over the whole detector in S/R PROCESS.
C     Note that it is subtracting the background constant (c) from
C     all pixel values, ie not allowing for a background plane. 
C     If this is the central profile, this is a good approximation as
C     the plane should average out (over summed spots) to be flat.
C
      NXY = NXS*NYS
      PRCENSUM = 0.0
      DO 92 I = 1,NXY
        IF (MASK(I).LT.0) THEN
          IODPROF(I) = 0
        ELSE
          IODPROF(I) = REAL(IODPROF(I))/SCALE + 0.5
CAL          IODPROF(I) = REAL(IODPROF(I))/SCALE + MINOD - ASPOT(11) + 0.5
          IF (MASK(I).GT.0) PRCENSUM = PRCENSUM + IODPROF(I)
        END IF
 92   CONTINUE
      IF (DEBUG(15).AND.SPOT) THEN
        WRITE(IOUT,FMT=6028)
        IF (ONLINE) WRITE(ITOUT,FMT=6028)
        MAXPIX = 0
        CALL ODPLOT4(IODPROF(1),NXS,NYS,1,MAXPIX)
6028    FORMAT(/1X,' Background subtracted, background zeroed average',
     +        ' spot profile for weighting',/)
      END IF
C
C---- Format statements
C
 6000 FORMAT (/' Measurement box dimensions too large to display avera',
     +       'ge spot profile',/1X,'NXS*NYS Must be less than or equal',
     +       ' to ',I5)
 6002 FORMAT (1X,'Average spot profile for central region.',/,1X,
     +     'Rejected background ',
     +     'pixels flagged by "*", true background by "-"')
 6003 FORMAT (1X,'Final optimised raster parameters:',5I5,/,1X,
     +        'This gives',I4,' pixels in the peak and',I4,
     +        ' in background after rejecting outliers.',/,1X,
     +        'Note that the number of background pixels rejected',
     +        ' on any individual spot',/,1X,'may be much smaller ',
     +        'than the number rejected here.')
 6004 FORMAT (1X,'C. of G. SHIFTS =',2F7.3,'mm  Background residual='
     +        ,F5.1,' (peak scaled to 255)')
 6006 FORMAT (/' Do you want to change the measurement box ?(y/n)')
 6007 FORMAT(/,1X,'Separation parameters updated to ',F6.2,'mm in X',
     +            ' and',F6.2,'mm in Y')
 6008 FORMAT (A1)
 6010 FORMAT (' Raster parameters and box shift:-',/2X,'NXS  NYS   NC ',
     +       ' NRX  NRY  XSH  YSH  (ENTER 99 TO GET 0)')
 6012 FORMAT (1X,I4,6I5,'      ?  Give new values in I5 format')
 6014 FORMAT (1X,I4,6I5)
 6016 FORMAT (' ***NXS and NYS MUST be ODD Integers < or = to ',I3)
C
C
C
C---- Reset BGFRAC
C
      IF (BGFRACRESET) BGFRAC = BGFRACSAVE
      END
C $Id: clcalc.f,v 1.3 2007/12/18 14:55:49 harry Exp $
C== CLCALC ==
C
C
C
      SUBROUTINE CLCALC(CELL,A)
C     ========================
      IMPLICIT NONE
C
C
C
C---- Calculate cell (real or reciprocal) from metric tensor A
C     Angles in degrees
C
C
C
C
C     .. Array Arguments ..
      REAL A(3,3),CELL(6)
C     ..
C     .. Local Scalars ..
      INTEGER I
      REAL X
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC SQRT,ACOS
C     ..
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C
C
      DO 10 I = 1,3
        CELL(I) = SQRT(A(I,I))
   10 CONTINUE
C
      X = A(2,3)/ (CELL(2)*CELL(3))
      IF (ABS(X).GT.1.0) X = SIGN(1.0,X)
      CELL(4) = ACOS(X)/DTOR
      X = A(1,3)/ (CELL(1)*CELL(3))
      IF (ABS(X).GT.1.0) X = SIGN(1.0,X)
      CELL(5) = ACOS(X)/DTOR
      X = A(1,2)/ (CELL(1)*CELL(2))
      IF (ABS(X).GT.1.0) X = SIGN(1.0,X)
      CELL(6) = ACOS(X)/DTOR
C
C
      END
C== CLEAR  ==
C $Id: clear.f,v 1.2 2006/08/29 14:58:34 harry Exp $
      SUBROUTINE CLEAR(A)
      IMPLICIT NONE
C     ==================
C
C     .. Array Arguments ..
      REAL A(9)
C     ..
C     .. Local Scalars ..
      INTEGER I
C     ..
C
C
      DO 10 I = 1,9
        A(I) = 0.0
   10 CONTINUE
C
C
      END
      SUBROUTINE CLUSTER(IRAS,MASK,MASKREJO,NCLUSTER,DIST,NPREJ,REJECT)
C     ================================================================
      IMPLICIT NONE
C
C---- Determines if rejected background pixels form one or more well
C     defined "clusters" which probably correspond to an adjacent 
C     (non-predicted) spot and tests if the cluster is adjacent to 
C     a peak pixel. Required especially for the multilattice case
C     where (at present) spots from another lattice are not predicted.
C     In these cases the summation integration intensity estimate
C     can be severely overestimated, so the profile fitted estimate should
C     be used instead
C
C     MASKREJO Array containing list of rejected background pixels
C              because they are outliers.
C
C     NCLUSTER Number of clusters found
C     DIST     Array storing distance of centroid of each cluster from
C              centre of measurement box (in pixels).
C     NPREJ    Array storing number of points in each cluster
C     
C
C     REJECT returned true if there are any clusters GE 5 pixels
C            that abut peak pixels.
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C
C     ..
C     .. Scalar Arguments ..
      LOGICAL REJECT
      INTEGER NCLUSTER
C
C     ..
C     .. Array Arguments ..
      INTEGER IRAS(5),MASK(MAXBOX),MASKREJO(NREJMAX),NPREJ(100)
      REAL DIST(100)
C     ..
C     .. Local Scalars ..
      INTEGER I,J,IJ,NXX,NYY,NHX,NHY,IYMIN,IYMAX,NREJ,NPT,
     +        NPIXELS,IYSTART,IX,IY,IX1,IY1,NPIXTOT,IREJ,IXMIN,IXMAX,
     +        NCL
C     ..
C     .. Local Arrays ..
      INTEGER MASK2D(-MAXDIM/2:MAXDIM/2,-MAXDIM/2:MAXDIM/2)
      REAL SUMI(100),SUMJ(100)
      LOGICAL ABUT(100)
C     ..
C     .. External Functions ..
C     ..
C     .. External Subroutines ..
C     ..
C     .. Intrinsic Functions ..
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/debug.f
C
C $Id: debug.f,v 1.8 2021/06/03 09:41:34 andrew Exp $
C
C--- awk generated include file  debug.h
C---- START of include file debug.h
C
C
C
C     .. Arrays in common /DEBUG/ ..
      REAL XWARN
      INTEGER NDEBUG,IWARN,IARRDUMP
      LOGICAL DEBUG,LPRINT,DUMP,WARN
C
C     .. Scalars in common /DEBUG/ ..
      REAL BGRLIM
      INTEGER NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,IERRLEVEL
      LOGICAL SPOT
      CHARACTER MESSAGE*512
C     
C     ..
C     .. Common Block /DEBUG/..
      COMMON /DEBUG/XWARN(MAXIWARN,100),BGRLIM,NDEBUG(200),
     +       IWARN(MAXIWARN,100),
     $       NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,DEBUG(200),LPRINT(20),
     +       DUMP(30),WARN(100),SPOT,IARRDUMP(30),IERRLEVEL

      COMMON /CDEBUG/ MESSAGE
C     ..
C
C&&*&& end_include  ../inc/debug.f
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C     ..
C     .. Equivalences ..
      SAVE
C     ..
C     .. Data ..
C     ..
C

C
C---- NPIXELS    Number of pixels in a cluster
C     NPT        Pointer into MASKREJO
C
      NXX = IRAS(1)
      NYY = IRAS(2)
      NHX = NXX/2
      NHY = NYY/2
      NCLUSTER = 0
      NREJ = MASKREJO(1)
      NPT = 2
      NPIXELS = 0
      IJ = MASKREJO(NPT)
      NPIXTOT = 0
C
C---- Convert IJ to coords IX,IY where these go +/-NHX, +/-NHY
C
      IX = -NHX + (IJ-1)/NYY
      IY = -NHY + (IJ - (IX+NHX)*NYY) - 1
      IX1 = IX
      IY1 = IY
      IJ = 0
      IREJ = 0
C
C---- Set up 2D mask
C
      DO 2 I = -NHX,NHX
        DO 4 J = -NHY,NHY
          IJ = IJ + 1
          MASK2D(I,J) = 0
          IF (MASK(IJ).EQ.1) MASK2D(I,J) = 1
          IF (IJ.EQ.MASKREJO(NPT)) THEN
            NPT = NPT + 1
            IREJ = IREJ + 1
            MASK2D(I,J) = -1
          END IF
 4      CONTINUE
 2    CONTINUE
      IF (DEBUG(91)) THEN
        WRITE(IOUT,FMT=1004) IX,IY,IREJ,NREJ
        IF (ONLINE) WRITE(ITOUT,FMT=1004) IX,IY,IREJ,NREJ
 1004   FORMAT(1X,'Coords of first rejected pixel are',2I4,/,1X,
     +     'number of points set up in MASK2D',I4,' NREJ=',I4)
      END IF
  
C
C---- Set start coord for search
C
      IYSTART = IY
C
C---- Set found rejected pixels to -1-(NCLUSTER+1) (the +1 needed 
C     because NCLUSTER is not incremented until cluster is finished
C
C
C---- Test pixels in the same stripe up to the end of this stripe
C
 6    DO 10 J = IY,NHY
        IF (DEBUG(98)) THEN
CAL          WRITE(IOUT,FMT=1006) IX,J,MASK2D(IX,J)
 1006     FORMAT(1X,'IX,IY',2I4,' MASK2D',I3)
        END IF
        IF (MASK2D(IX,J).EQ.-1) THEN
          NPIXELS = NPIXELS + 1
          MASK2D(IX,J) = -1-(NCLUSTER+1)
        ELSE
          GOTO 20
        END IF
 10   CONTINUE
C
C---- See if cluster extends to the next stripe. Only allow
C     situations where the pixels in the next row are within
C     one pixel (in Y) of the start point in the previous stripe
C
 20   IX = IX + 1
      IF (DEBUG(98)) THEN
        WRITE(IOUT,FMT=1010) IX-1,NPIXELS
        IF (ONLINE) WRITE(ITOUT,FMT=1010) IX-1,NPIXELS
 1010   FORMAT(1X,'finished stripe',I4,' total rej pixels',I4)
      END IF
      IF (IX.GT.NHX) THEN
C
C---- Last stripe dealt with, finish off
C
        NCLUSTER = NCLUSTER + 1
        IF (DEBUG(98)) THEN
          WRITE(IOUT,FMT=1020) IX,NCLUSTER,NPIXELS
          IF (ONLINE) WRITE(ITOUT,FMT=1020) IX,NCLUSTER,NPIXELS
        END IF
        NPREJ(NCLUSTER) = NPIXELS
        NPIXTOT = NPIXTOT + NPIXELS
        GOTO 70
      END IF
C
      IYMIN = MAX(-NHY,IYSTART-1)      
      IYMAX = MIN(NHY,IYSTART+1)
      DO 22 J = IYMIN,IYMAX
        IF (MASK2D(IX,J).EQ.-1) THEN
          IYSTART = J
          GOTO 30
        END IF
 22   CONTINUE
C
C---- No overlap with next stripe, deal with this cluster and go on 
C     to look for more providing there are at least 4 rejected background
C     pixels that are not accounted for. 
C
      NCLUSTER = NCLUSTER + 1
      IF (DEBUG(98)) THEN
        WRITE(IOUT,FMT=1020) IX,NCLUSTER,NPIXELS
        IF (ONLINE) WRITE(ITOUT,FMT=1020) IX,NCLUSTER,NPIXELS
 1020   FORMAT(1X,'at stripe',I3,' finished cluster',I3,' total',
     +         ' number of pixels',I4)
      END IF
      NPREJ(NCLUSTER) = NPIXELS
      NPIXTOT = NPIXTOT + NPIXELS
      IF ((NREJ-NPIXTOT).LT.4) GOTO 70
      NPIXELS = 0
C
C---- Find the first rejected pixel that has not been accounted for. Can start
C     on the same row as the very first rejected pixel
C
      IF (DEBUG(98)) THEN
        WRITE(IOUT,FMT=1024) IX1
        IF (ONLINE) WRITE(ITOUT,FMT=1024) IX1
 1024   FORMAT(1X,'Searching more rejected pixels starting stripe',I4)
      END IF
      DO 24 I = IX1,NHX
        DO 26 J = -NHY,NHY
          IF (MASK2D(I,J).EQ.-1) THEN
            IX = I
            IY = J
            IX1 = IX
            IYSTART = IY
            IF (DEBUG(98)) THEN
              WRITE(IOUT,FMT=1030) IX,IY
              IF (ONLINE) WRITE(ITOUT,FMT=1030) IX,IY
 1030         FORMAT(1X,'Going to find new cluster starting at',2I4)
            END IF
            GOTO 6
          END IF
 26     CONTINUE
 24   CONTINUE
C
C---- No more rejected pixels found, finish
C
      GOTO 70
C
C---- Have overlap, search down from start point, jump out as soon
C     as a non-rejected pixel is encountered.
C
 30   DO 32 J = IYSTART,-NHY,-1
        IF (MASK2D(IX,J).EQ.-1) THEN
          MASK2D(IX,J) = -1-(NCLUSTER+1)
          NPIXELS = NPIXELS + 1
          IYMIN = J
        ELSE
          GOTO 34
        END IF
 32   CONTINUE
C
C---- Now search in +ve direction
C
 34   IYMAX = IYSTART
      DO 36 J = IYSTART+1,NHY
        IF (MASK2D(IX,J).EQ.-1) THEN
          MASK2D(IX,J) = -1-(NCLUSTER+1)
          NPIXELS = NPIXELS + 1
          IYMAX = J
        ELSE
          GOTO 38
        END IF
 36   CONTINUE
C
C---- End of search this stripe, set start pixel for search in
C     next stripe to the midpoint
C
 38   IYSTART = (IYMIN+IYMAX)/2
      IF (DEBUG(98)) THEN
        WRITE(IOUT,FMT=1040) IYSTART
        IF (ONLINE) WRITE(ITOUT,FMT=1040) IYSTART
 1040   FORMAT(1X,'Start Y pixel for search in next stripe is',I4)
      END IF
      GOTO 20
C
C---- All clusters found. Now test if each cluster contains a pixel
C     adjacent to a peak pixel and also to find the centroid of
C     each cluster
C
 70   DO 72 I=1,NCLUSTER
        ABUT(I) = .FALSE.
        SUMI(I) = 0.0
        SUMJ(I) = 0.0
 72   CONTINUE
C
      DO 80 I = -NHX,NHX
        DO 82 J = -NHY,NHY
          IF (MASK2D(I,J).LT.-1) THEN
            NCL = -MASK2D(I,J) - 1
CAL            write(iout,999) i,j,ncl
CAL            if (online) write(itout,999) i,j,ncl
CAL 999        format(1x,'I,J,NCL ',3I5)
            SUMI(NCL) = SUMI(NCL) + I
            SUMJ(NCL) = SUMJ(NCL) + J
            IF (ABUT(NCL)) GOTO 82
            IXMIN = MAX(I-1,-NHX)
            IXMAX = MIN(I+1,NHX)
            IYMIN = MAX(J,-NHY)
            IYMAX = MIN(J+1,NHY)
            DO 84 IX = IXMIN,IXMAX
              DO 86 IY = IYMIN,IYMAX
                IF (MASK2D(IX,IY).EQ.1) THEN
                   ABUT(NCL) = .TRUE.
                   GOTO 82
                END IF
 86           CONTINUE
 84         CONTINUE
          END IF
 82     CONTINUE
 80   CONTINUE
      REJECT = .FALSE.
      DO 90 I = 1,NCLUSTER
        REJECT = (REJECT.OR.((NPREJ(I).GE.5).AND.ABUT(I)))
        SUMI(I) = SUMI(I)/NPREJ(I)
        SUMJ(I) = SUMJ(I)/NPREJ(I)
        DIST(I) = SQRT(SUMI(I)**2 + SUMJ(I)**2)
        IF (ABUT(I)) NPREJ(I) = -NPREJ(I) 
 90   CONTINUE
C
      IF (DEBUG(98)) THEN
        WRITE(IOUT,FMT=1000) REJECT, NCLUSTER,(NPREJ(I),I=1,NCLUSTER)
        WRITE(IOUT,FMT=1002) (ABUT(I),I=1,NCLUSTER)
        WRITE(IOUT,FMT=1008) (I,SUMI(I),SUMJ(I),DIST(I),I=1,NCLUSTER)
        IF (ONLINE) THEN
          WRITE(ITOUT,FMT=1000) REJECT,NCLUSTER,
     +                 (NPREJ(I),I=1,NCLUSTER)
          WRITE(ITOUT,FMT=1002) (ABUT(I),I=1,NCLUSTER)
          WRITE(ITOUT,FMT=1008) (I,SUMI(I),SUMJ(I),DIST(I),I=1,NCLUSTER)
        END IF
      END IF
 1000 FORMAT(1X,'Reject',L2,'; ',I3,' clusters found with number of',
     +        ' pixels:',10I5)
 1002 FORMAT(1X,'Abutting peak:',10L3)
 1008 FORMAT(1X,'Cluster  X Centroid   Y centroid  Dist',/,
     +       (1x,I4,3f11.2))
      
      RETURN
      END
      SUBROUTINE CNVPIX(IX,IY,ISTAT)
C     =====================================
C
c  Check that image pixel with coord IX,IY is within image.
c
c
c  Output
c     istat             = 1 if outside display, else = 0 (OK)
c

      IMPLICIT NONE
C
      INTEGER IX,IY,ISTAT
C&&*&& include  ../inc/mxdinc.f
C
C $Id: mxdinc.f,v 1.1 2002/05/02 10:47:00 harry Exp $
C
C--- awk generated include file  mxdinc.h
C---- START of include file mxdinc.h
C
C
c common block for mxd routines: various parameters for XDL routines
c
c     base_width    width of base frame
c     base_height   height of base frame
c     men_x,men_y   position of menu area
c     par_x,par_y   position of parameter area
C     

C     IORDER    (R)   Order of the data in the input image 
c                with respect to two local axes ax1, ax2 e.g.
c                (xf, yf) as a number from 1 to 8.
c                    1   +ax1 slow   +ax2 fast    (+xf, +yf)
c                    2   +ax1 slow   -ax2 fast    (+xf, -yf)
c                    3   -ax1 slow   +ax2 fast    (-xf, +yf)
c                    4   -ax1 slow   -ax2 fast    (-xf, -yf)
c                    5   +ax2 slow   +ax1 fast    (+yf, +xf)
c                    6   +ax2 slow   -ax1 fast    (+yf, -xf)
c                    7   -ax2 slow   +ax1 fast    (-yf, +xf)
c                    8   -ax2 slow   -ax1 fast    (-yf, -xf)
c
c
c     JORDER    (R)   Display order with respect to the two
c                local axes (1 to 8) along the X-windows
c                axes X horizontal (left to right), Y vertical 
c                (top to bottom ) with origin at top left
c                1  +ax1 X (horiz)   +ax2 Y (vert)   (+xf, +yf)
c                2  +ax1 X (horiz)   -ax2 Y (vert)   (+xf, -yf)
c                3  -ax1 X (horiz)   +ax2 Y (vert)   (-xf, +yf)
c                4  -ax1 X (horiz)   -ax2 Y (vert)   (-xf, -yf)
c                5  +ax2 X (horiz)   +ax1 Y (vert)   (+yf, +xf)
c                6  +ax2 X (horiz)   -ax1 Y (vert)   (+yf, -xf)
c                7  -ax2 X (horiz)   +ax1 Y (vert)   (-yf, +xf)
c                8  -ax2 X (horiz)   -ax1 Y (vert)   (-yf, -xf)
c                    
c                    (2 was standard for Laue programs)
c
c     nxp_cmp       number of pixels compressed to 1 in horizontal
c                   display direction
c     nyp_cmp       number of pixels compressed to 1 in vertical
c                   display direction
c     nxdpx         number of horizontal pixels in displayed image
c     nydpx         number of vertical pixels in displayed image
c     img_horiz     image direction for horizontal display (=1 fast, 2 slow)
c     img_vert      image direction for vertical display   (=1 fast, 2 slow)
c     img_map(4)    mapping of image to display
c                    imgmap(1)   1st point on fast axis (Yms)
c                    imgmap(2)   1st point on slow axis (Zms)
c                    imgmap(3)   increment on fast axis
c                    imgmap(4)   increment on slow
c     img_x,img_y   x, y position of image
c     men_x, men_y  x, y position of menu
c     par_x, par_y  x, y position of parameter table
c     io_x, io_y    x, y position of IO area
c     not_x, not_y    x, y position of notice area (parameter table
c                     with no values)
c     pmn_x, pmn_y  x, y position of popup abort menu
c     ppb_x, ppb_y  x, y position of popup progress bar
c     busy_x, busy_y x, y position of busy window
c     img_width,img_height   width, height of image window
c     men_width, men_height  width, height of menu window  
c     par_width, par_height  width, height of parameter window
c     io_width, io_height    width, height of IO window
c     not_width, not_height  width, height of notice area
c     pmn_width, pmn_height  width, height of Abort menu
c     ppb_width              width of progress bar
c     busy_width, busy_height  width, height of busy box
c     sub_process    .true. if program is sub-process of eg clips, .false.
c                    if standalone
c
C     IFTYPE      1 = unsigned byte data
C                 2 = unsigned two-byte data (i2)
C                 3 = signed integer data
C                 4 = 'squashed i2' data (if Intensity>32767 
C                    store as 65536-Intensity/8)
      INTEGER BASE_WIDTH,BASE_HEIGHT,
     $     IMAGE_ORDER,JIMAGE_ORDER,NXP_CMP,NYP_CMP,
     $     NXDPX,NYDPX,
     $     IMG_HORIZ,IMG_VERT,IMG_MAP(4),
     $     IMG_X,IMG_Y,MEN_X,MEN_Y,PAR_X,PAR_Y,IO_X,IO_Y,
     $     NOT_X,NOT_Y,PMN_X, PMN_Y,PPB_X, PPB_Y, BUSY_X, BUSY_Y,
     $     BUSY_Y2,IFTYPE
      INTEGER IMG_WIDTH, IMG_HEIGHT, MEN_WIDTH, MEN_HEIGHT,
     $     PAR_WIDTH, PAR_HEIGHT, IO_WIDTH, IO_HEIGHT,
     $     NOT_WIDTH, NOT_HEIGHT, PMN_WIDTH, PMN_HEIGHT,
     $     PPB_WIDTH, BUSY_WIDTH, BUSY_HEIGHT
      LOGICAL SUB_PROCESS, BLANK
C

c  DON'T forget to declare function xdlstr as integer
      INTEGER XDLSTR
      EXTERNAL XDLSTR

c
c     ivhbas        view object handle for base frame
c     ivhimg        view object handle for image
c     ivhpar        view object handle for parameter table
c     ivhmen        view object handle for menu
c     ivhio         view object handle for io area
c     ivhio2        view object handle for second io area (pick option)
c     ivhio3        view object handle for third io area (output)
c     ivhnot        view object handle for notice area (parameter table)
c     ivhpmn        view object handle for popup wait menu
c     ivhppb        view object handle for popup progress bar
c     ivhblank      view object handle for blank object
c     ivhbusy       view object handle for busy object
c     ivhbusy2      view object handle for second (2 line) busy object
      INTEGER IVHBAS, IVHIMG, IVHPAR, IVHMEN, IVHIO, IVHNOT, IVHPMN,
     $     IVHPPB, IVHBLANK, IVHBUSY, IVHIO2, IVHBUSY2, IVHIO3
      PARAMETER (IVHBAS=1, IVHIMG=2, IVHPAR=3, IVHMEN=4, IVHIO=5,
     $     IVHNOT=6, IVHPMN=7, IVHPPB=8, IVHBLANK=9, IVHBUSY=10,
     $     IVHIO2=11, IVHBUSY2=12, IVHIO3=13)

c  Border  boundary between windows
      INTEGER BORDER
      PARAMETER (BORDER = 4)

c     icset   colour set number
      INTEGER ICSET
      PARAMETER (ICSET=1)
c
c     iord    axis order of image
c             = 1  xf slow, yf fast
      INTEGER IORD
      PARAMETER (IORD = 1)
c
c     minw,minh   minimum width and height for image display object
      INTEGER MINW,MINH
      PARAMETER (MINW=0, MINH=0)
c
c     ixopix, iyopix      pixel origin of displayed part
      INTEGER IXOPIX,IYOPIX
      PARAMETER (IXOPIX=1, IYOPIX=1)
c
c     ibg     background menu, =0 for none
      INTEGER IBG
      PARAMETER (IBG=0)
c
c     iovly   overlay option
      INTEGER IOVLY
      PARAMETER (IOVLY=1)
c
c     max_pixel   maximum number of pixels to use for image display:
c                 this will be used to control possible compression
c                 of the image
      INTEGER MAX_PIXEL
      PARAMETER (MAX_PIXEL = 800)
c  Image stuff
c     disp_img        true if image has been displayed
c
      LOGICAL DISP_IMG
c
c     ifd     file descriptor, = -1 for no file
      INTEGER IFD
      PARAMETER (IFD=0)
c

c  Parameter table stuff
c     max_par_col     maximum number of parameter columns
c     max_par_rows    maximum number of parameter rows
c     max_par_name    maximum length of name
c     max_par_str     maximum value length
c     par_title       = -1 no title +1 title present
c     par_font        font (3=medium)
c     par_menu        = 1 if popup menus allowed
c     disp_par        true if parameter table hsa been displayed
c
      LOGICAL DISP_PAR
      INTEGER MAX_PAR_COL, MAX_PAR_ROWS, MAX_PAR_NAME, MAX_PAR_STR,
     $        PAR_TITLE, PAR_FONT, PAR_MENU
      PARAMETER (MAX_PAR_COL = 1, MAX_PAR_ROWS = 50,
     $           MAX_PAR_NAME = 17, MAX_PAR_STR = 7,
     $           PAR_TITLE = 1, PAR_FONT = 2, PAR_MENU = 0)
C
c  Menu stuff
c     max_men_itms    maximum number of menu items
c     max_men_name    maximum number of characters in menu item
c     men_font        menu font number (3=medium)
c     men_quit_flag   = 1 to allow for quit box
c     max_men_title   maximum length of menu title
c     disp_menu       true if menu displayed
      LOGICAL DISP_MENU
      INTEGER MAX_MEN_ITMS, MAX_MEN_NAME, MEN_FONT, MEN_QUIT_FLAG,
     $        MAX_MEN_TITLE 
      PARAMETER (MAX_MEN_ITMS = 19, MAX_MEN_NAME = 19, MEN_FONT = 4,
     $     MEN_QUIT_FLAG = 1, MAX_MEN_TITLE = 9)

c
c IO area stuff
c     io_font         font number
c     disp_io         true if io area displayed
c     disp_io2        true if SECOND io area displayed
c     disp_io3        true if THIRD io area displayed
C     NSCROLL         number of pages to hold for scrolling
      LOGICAL DISP_IO,DISP_IO2,DISP_IO3
      INTEGER IO_FONT,NSCROLL
      PARAMETER (IO_FONT=2)
      PARAMETER (NSCROLL=0)


c  Notice area stuff (notice area is a parameter table with no values)
c     max_not_col     maximum number of parameter columns
c     max_not_rows    maximum number of parameter rows
c     max_not_name    maximum length of name
c     max_not_str     maximum value length
c     not_title       = -1 no title +1 title present
c     not_font        font (3=medium)
c     not_menu        = 1 if popup menus allowed
c     disp_not       true if menu displayed
      LOGICAL DISP_NOT
      INTEGER MAX_NOT_COL, MAX_NOT_ROWS, MAX_NOT_NAME, MAX_NOT_STR,
     $        NOT_TITLE, NOT_FONT, NOT_MENU
      PARAMETER (MAX_NOT_COL = 1, MAX_NOT_ROWS = 18,
     $           MAX_NOT_NAME = 23,
     $           MAX_NOT_STR = 0,
     $           NOT_TITLE = +1, NOT_FONT = 2, NOT_MENU = 0)
c
c  Menu stuff for Abort menu
c     max_pmn_itms    maximum number of menu items
c     max_pmn_name    maximum number of characters in menu item
c     pmn_font        menu font number (3=medium)
c     pmn_quit_flag   = 1 to allow for quit box
c     max_pmn_title   maximum length of menu title
      INTEGER MAX_PMN_ITMS, MAX_PMN_NAME, PMN_FONT, PMN_QUIT_FLAG,
     $        MAX_PMN_TITLE 
      PARAMETER (MAX_PMN_ITMS = 0, MAX_PMN_NAME = 12, PMN_FONT = 4,
     $     PMN_QUIT_FLAG = 1, MAX_PMN_TITLE = 15)

c   Stuff for progress bar
c     ppb_font   font number (3=medium)
c     ppb_colr   colour
      INTEGER PPB_FONT, PPB_COLR
      PARAMETER (PPB_FONT = 4, PPB_COLR=3)

c   Busy box
      INTEGER BUSY_FONT
      PARAMETER (BUSY_FONT = 3)
c
c len_dialog    length of dialog box
      INTEGER LEN_DIALOG
      PARAMETER (LEN_DIALOG = 60)

c
c  Overlays
c
c  Circles
c     cir_ivec    vector set number for circles
c     cir_colr    colour for circles
c     cir_iovl    overlay number for circles
c     cir_symb   symbol for centre
      INTEGER CIR_IVEC, CIR_COLR, CIR_IOVL, CIR_SYMB
      PARAMETER (CIR_IVEC=3, CIR_COLR=6, CIR_IOVL=2, CIR_SYMB=4)

C
C---- Residual vectors
C     IRV_VEC Vector set number
C     IRV_COL Colour  (1 red, 2 yellow, 3 green)
C     IRV_OVL Overlay number
      INTEGER IRV_VEC, IRV_COL, IRV_OVL
      PARAMETER (IRV_VEC=4, IRV_COL=1, IRV_OVL=2)
c  Measure
c
c     mes_colr    colour for measure crosses
      INTEGER MES_COLR
      PARAMETER (MES_COLR=1)

c   Vertical Crosses
c     cross_iovl    overlay number for circles
c     cross_symb   symbol for centre
      INTEGER CROSS_IOVL, CROSS_SYMB
      PARAMETER (CROSS_IOVL=2, CROSS_SYMB=3)
c  Boxes
c     box_iovl    overlay number for boxes
c     box_symb   symbol for centre
      INTEGER BOX_IOVL, BOX_SYMB, BOX_VEC
      PARAMETER (BOX_VEC=2,BOX_IOVL=2, BOX_SYMB=13)
c  Circles
c     CIRC_iovl    overlay number for circles
c     CIRC_symb   symbol for centre
      INTEGER CIRC_IOVL, CIRC_VEC
      PARAMETER (CIRC_VEC=5,CIRC_IOVL=2)
c   Crosses
c     cross_iovl    overlay number for circles
c     cross_symb   symbol for centre
      INTEGER XCROSS_IOVL, XCROSS_SYMB
      PARAMETER (XCROSS_IOVL=2, XCROSS_SYMB=13)
C
C---- common block last of all
C
      COMMON /MXDCMI/ BASE_WIDTH,BASE_HEIGHT,
     $     IMAGE_ORDER,JIMAGE_ORDER,NXP_CMP,NYP_CMP,
     $     NXDPX,NYDPX,
     $     IMG_HORIZ,IMG_VERT,IMG_MAP,
     $     IMG_X,IMG_Y,MEN_X,MEN_Y,PAR_X,PAR_Y,IO_X,IO_Y,
     $     NOT_X,NOT_Y,PMN_X, PMN_Y,PPB_X, PPB_Y, BUSY_X, BUSY_Y,
     $     BUSY_Y2, IFTYPE,
     $     IMG_WIDTH, IMG_HEIGHT, MEN_WIDTH, MEN_HEIGHT,
     $     PAR_WIDTH, PAR_HEIGHT, IO_WIDTH, IO_HEIGHT,
     $     NOT_WIDTH, NOT_HEIGHT, PMN_WIDTH, PMN_HEIGHT,
     $     PPB_WIDTH, BUSY_WIDTH, BUSY_HEIGHT,
     $     SUB_PROCESS,BLANK,DISP_IMG,DISP_PAR,DISP_MENU,
     $     DISP_IO,DISP_IO2,DISP_IO3,DISP_NOT
  
C&&*&& end_include  ../inc/mxdinc.f
C
C check if in allowed display area
      ISTAT = 0
      IF (IX .LT. 1. OR. IX .GT. NXDPX .OR.
     $    IY .LT. 1. OR. IY .GT. NYDPX) ISTAT = 1
      RETURN
      END
C     
C     $Id: complete.f,v 1.65 2015/02/05 15:39:48 harry Exp $
C     
C==   COMPLETE ==
      SUBROUTINE COMPLETE(IHKLSTR,NTOTAL,IORDER)
C     
      IMPLICIT NONE
C     
C     LAST LABEL 470, FORMAT 6330
C     Program to compile statistics on completeness of a data set
C     
C     The reflection list is stored in memory. For each unique reflection
C     the following are stored:
C     
C     For each reflection: ADATA(6)
C     1-3       h,k,l
C     4          -999 (Identifier)
C     5         ICENT =0 centric
C     =1 acentric
C     6         zero (not used)
C     
C     For generated reflections:
C     ===========================
C     H,K,L,BATCH,PHI,IC
C     
C     "BATCH" is 9999 for generated data (-999 for unique reflections)
C     
C     "PHI" is the phi value for the reflection. This is stored as an integer,
C     and will be the truncated real phi (ie 4.8 will become 4)
C     
C     "IC" is modulo 2 of the number of the symmetry operation used
C     to generate the correct indices, plus 1. Friedel pairs will
C     therefore have values of 1 and 2. This is used to calculate the
C     number of Friedel pairs.
C     
C     
C     
C     Originally coded by A.G.W. LESLIE NOV 1984
C     
C     
C     
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
      INTEGER NPARM, istatus
      PARAMETER (NPARM=200)
C     IHKLSTR      Array containing the reflections
C     
C     Need to use IHKLSTR(1,NTOTAL) onwards are working array
C     ..
C     .. Scalar Arguments ..
      INTEGER NTOTAL
C     
C     ..
C     .. Array Arguments ..
      INTEGER*2 IHKLSTR(MCOLSTR,NREFSTR)
chrp28.04.2003 changed iorder to i*2 - NO. must be I*4
      INTEGER IORDER(NTOTAL)
C     ..      
C     ..
C     .. local scalars
      REAL MEANMULT,PCA,FPCUNIQUE
      INTEGER ICOMM,IERR,IC,JC,NSEGCNT
      CHARACTER LINE*400,KEY*4,SUBKEY*4,HLPMOS*400,POSVID*3,MULTCHAR*2
      character XMLLINE*1024, dnahs*80
      LOGICAL HARRY,DONETEST,DONESTATS
C     ..
C     .. External Functions ..
