C--- awk generated include file  test.h
C---- START of include file test.h
C
C    Detector limits, used in SPTEST. All are in 10 micron units.
C    In the virtual detector frame, Y is parallel to the rotation axis
C    and X is orthogonal to the rotation axis.
C
C    In the scanner frame, X is parallel to the slow direction in the
C    image, Y is the fast direction.
C
C    RSCANSQ      Radius**2 of the scanned region of the plate (Mar scanners)
C                 This is different to the other limits because it is
C                 applied to the actual scanner coordinates rather than
C                 the virtual detector coordinates. All other limits apply
C                 to virtual detector coordinates.
C    XSCAN        Maximum X coordinate in detector frame (10 micron units)
C    YSCAN        Maximum Y coordinate in detector frame (10 micron units)
C    RSCANX,RSCANY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RSCAN defining the
C                 useable area of the detector.
C    XSCAN,YSCAN,RSCAN are maximum coords relative to the physical centre of 
C                 the detector (ie the mid-point of the image), NOT wrt the 
C                 direct beam position.
C    RMINX,RMINY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RMIN defining the
C                 useable area of the detector.
C    RMXSQD       Maximum radius (squared) in virtual detector frame
C    RMNSQD       Minimum radius (squared) in virtual detector frame
C    XMIN         Minimum X coordinate in  detector frame
C    XMAX         Maximum X coordinate in  detector frame
C    YMIN         Minimum Y coordinate in  detector frame
C    YMAX         Maximum Y coordinate in  detector frame
C    NXYEXC       Number of excluded areas set by user (rectangles, arcs)
C    NXYEXCDET    Number of detector specific excluded rectangles (Pilatus)
C    NOTILES      If set true, ignore all tile boundaries in Pilatus images
C    ICEWIDTH     Width of the exclusion shells for ice, this fraction
C                 of the actual resolution is used as the half-width
C    ICEWIDTHPREF Width of the exclusion shells for ice for post
C                 refinement, this fraction
C                 of the actual resolution is used as the half-width
C    PREFEXICE    Logical, true if reflections in ice rings to be
C                 excluded from post-refinement
C
C     .. Scalars in common block /TEST/ ..
      REAL RMXSQD,RMNSQD,XMIN,XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,
     +     RMINX,RMINY,XSCAN,YSCAN,CIRRAD,ICEWIDTH,ICEWIDTHPREF
      INTEGER NEXCL,NXYEXC,NXYEXCDET,IQUADNO,IARCNO,NEXCL2
      LOGICAL PREFEXICE,NOTILES
C
C     .. Arrays in common block /TEST/
      REAL RESEXL,RESEXH,XYEXC,CNREXC,EXCARC,CIRCEN,PHILIM,RES2EXL,
     +     RES2EXH,RES3EXL,RES3EXH,XYEXCSP
      INTEGER IEXCARC
      LOGICAL LEXCARC
C     ..
C     .. Common Block /TEST/ ..
      COMMON /TEST/RESEXL(MAXEXCL),RESEXH(MAXEXCL),XYEXC(4,MAXEXCL),
     +     CNREXC(8,MAXEXCL),
     $     EXCARC(5,MAXEXCL),CIRCEN(2),PHILIM(2),RMXSQD,RMNSQD,XMIN,
     +     XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,RMINX,RMINY,XSCAN,
     $     YSCAN,CIRRAD,IEXCARC(6,MAXEXCL),NEXCL,NXYEXC,IQUADNO,
     $     IARCNO,LEXCARC(MAXEXCL),NXYEXCDET,RES2EXL(MAXEXCL),
     $     RES2EXH(MAXEXCL),NEXCL2,ICEWIDTH,ICEWIDTHPREF,PREFEXICE,
     +     RES3EXL(MAXEXCL),RES3EXH(MAXEXCL),NOTILES,XYEXCSP(4,MAXEXCL)
C     ..
C
C

C&&*&& end_include  ../inc/test.f
C&&*&& include  ../inc/xy.f
C
C $Id: xy.f,v 1.1 2002/05/02 10:47:25 harry Exp $
C
C--- awk generated include file  xy.h
C---- START of include file xy.h
C
C     .. Scalars in common block /XY/ ..
      REAL XTOFD,SINV,COSV,TANV,TWOTHETA
      INTEGER ICASS
C     ..
C     .. Common Block /XY/ ..
      COMMON /XY/XTOFD,SINV,COSV,TANV,TWOTHETA,ICASS
C     ..
C
C     XTOFD....  Crystal to detector distance in 10 micron units. Read from
C                keyworded input and never changed.
C
C                Spot positions are calculated in S/R XYSPOT (Called from
C                REEK) and are for an "ideal" detector at a distance of XTOFD.
C                These are converted into pixel positions in S/R MMTOPX
C                which applies the multiplicative factor XTOFRA to allow
C                for refinement of the distance. XTOFRA is the parameter
C                that is actually refined (in RDIST), rather than XTOFD.
C                The refined distance that is printed in the logfile is
C                actually XTOFRA*XTOFD
C
C     ICASS....  Indicates detector type:
C                0     Flat film
C                1     Vee shaped cassettes
C                2     FAST detector (only used in TESTGEN mode of OSCGEN)
C                3     Swung out FAST (ditto)
C                4     IP detector
C     TWOTHETA   Detector swing angle (degrees)
C&&*&& end_include  ../inc/xy.f
C     .. icolr = 1 (red)
      ICOLR = 1
      DISTANCE = XTOFD * 0.01
      RASTINVX = 1.0/(RAST*100)
      RASTINVY = YSCAL/(RAST*100)
      IF(MODE.EQ.3.OR.MODE.EQ.0)THEN
        IF(NMASK.EQ.0)THEN
          ISTART = 1
          IFINISH = NXYEXC
        ELSE
          ISTART  = NMASK
          IFINISH = NMASK
        ENDIF
        DO 100 IC = ISTART,IFINISH,1
          IX(1) = XYEXC(1,IC)*RASTINVX
          IY(1) = XYEXC(2,IC)*RASTINVY
          IX(2) = XYEXC(3,IC)*RASTINVX
          IY(2) = XYEXC(4,IC)*RASTINVY
          IF(INVERTX)THEN
            IX(1) = NREC - IX(1)
            IX(2) = NREC - IX(2)
          ENDIF
          CALL MXD_IMG_VEC(IVHIMG,IC + 10,IX(1),IY(1),IX(2),IY(1),
     $         ICOLR,IRV_OVL,1,IERR)
          CALL MXD_IMG_VEC(IVHIMG,IC + 10,IX(2),IY(1),IX(2),IY(2),
     $         ICOLR,IRV_OVL,1,IERR)
          CALL MXD_IMG_VEC(IVHIMG,IC + 10,IX(2),IY(2),IX(1),IY(2),
     $         ICOLR,IRV_OVL,1,IERR)
          CALL MXD_IMG_VEC(IVHIMG,IC + 10,IX(1),IY(2),IX(1),IY(1),
     $         ICOLR,IRV_OVL,1,IERR)
 100    ENDDO
      ENDIF
C
C---- general convex quadrilateral
C
      IF(MODE.EQ.4.OR.MODE.EQ.0)THEN
        IF(NMASK.EQ.0)THEN
          ISTART = 1
          IFINISH = IQUADNO
        ELSE
          ISTART  = NMASK
          IFINISH = NMASK
        ENDIF
        DO 200 IC = ISTART,IFINISH,1
          IX(1) = CNREXC(1,IC)*RASTINVX
          IY(1) = CNREXC(2,IC)*RASTINVY
          IX(2) = CNREXC(3,IC)*RASTINVX
          IY(2) = CNREXC(4,IC)*RASTINVY
          IX(3) = CNREXC(5,IC)*RASTINVX
          IY(3) = CNREXC(6,IC)*RASTINVY
          IX(4) = CNREXC(7,IC)*RASTINVX
          IY(4) = CNREXC(8,IC)*RASTINVY
          IF(INVERTX)THEN
            IX(1) = NREC - IX(1)
            IX(2) = NREC - IX(2)
            IX(3) = NREC - IX(3)
            IX(4) = NREC - IX(4)
          ENDIF
          CALL MXD_IMG_VEC(IVHIMG,IC + 20,IX(1),IY(1),IX(2),IY(2),
     $         ICOLR,IRV_OVL,1,IERR)
          CALL MXD_IMG_VEC(IVHIMG,IC + 20,IX(2),IY(2),IX(3),IY(3),
     $         ICOLR,IRV_OVL,1,IERR)
          CALL MXD_IMG_VEC(IVHIMG,IC + 20,IX(3),IY(3),IX(4),IY(4),
     $         ICOLR,IRV_OVL,1,IERR)
          CALL MXD_IMG_VEC(IVHIMG,IC + 20,IX(4),IY(4),IX(1),IY(1),
     $         ICOLR,IRV_OVL,1,IERR)
 200    ENDDO
      ENDIF
C
C---- exclude outside an arc (mode = 5) or inside an arc (dairylea, mode = 6)
C
      IF(MODE.EQ.5.OR.MODE.EQ.6.OR.MODE.EQ.0)THEN
        IF(NMASK.EQ.0)THEN
          ISTART = 1
          IFINISH = IARCNO
        ELSE
          ISTART  = NMASK
          IFINISH = NMASK
        ENDIF
        DO 300 IC = ISTART,IFINISH,1
          IF(IEXCARC(1,IC).EQ.-999)THEN
C     centre
            IEXCARC(5,IC) = EXCARC(1,IC)/RAST
            IF(INVERTX)IEXCARC(5,IC) = NREC - IEXCARC(5,IC)
            IEXCARC(6,IC) = EXCARC(2,IC)/(RAST*YSCAL)
C     
            ISWAP = 1
            IF(INVERTX)ISWAP = -1
C     arc, start
            IEXCARC(1,IC) = IEXCARC(5,IC) + 
     $           (ISWAP * EXCARC(3,IC) * COS(EXCARC(4,IC)))/RAST
            IEXCARC(2,IC) = IEXCARC(6,IC) + 
     $           (EXCARC(3,IC) * SIN(EXCARC(4,IC)))/
     $           (RAST*YSCAL)
C     arc, end
            IEXCARC(3,IC) = IEXCARC(5,IC) + 
     $           (ISWAP * EXCARC(3,IC) * COS(EXCARC(5,IC)))/RAST
            IEXCARC(4,IC) = IEXCARC(6,IC) + 
     $           (EXCARC(3,IC) * SIN(EXCARC(5,IC)))/
     $           (RAST*YSCAL)
          ENDIF
          IX(1) = IEXCARC(1,IC)
          IY(1) = IEXCARC(2,IC)
          IX(2) = IEXCARC(3,IC)
          IY(2) = IEXCARC(4,IC)
          IX(3) = IEXCARC(5,IC)
          IY(3) = IEXCARC(6,IC)
          CIRCEN(1) = EXCARC(1,IC)
          CIRCEN(2) = EXCARC(2,IC)
          CIRRAD = EXCARC(3,IC)
          PHILIM(1) = EXCARC(4,IC)
          PHILIM(2) = EXCARC(5,IC)
          IF(INVERTX)CIRCEN(1)=NREC*RAST-CIRCEN(1)
          CALL MXDARC(ICOLR,CIRCEN,CIRRAD,PHILIM)
          DO 250 I=1,2,1
C     .. LEXCARC(IC) - inside, .not. LEXCARC(IC) - outside
C     .. horizontal line
            IF(IY(I) .EQ. IY(3))THEN
              IY(I+3) = IY(I)
              IF(IX(I).LT.IX(3))THEN
                IF(LEXCARC(IC))THEN
                  IX(I+3) = NREC
                ELSE
                  IX(I+3) = 0
                ENDIF
              ELSE
                IF(LEXCARC(IC))THEN
                  IX(I+3) = 0
                ELSE
                  IX(I+3) = NREC
                ENDIF
              ENDIF
C     .. vertical line
            ELSEIF(IX(I).EQ.IX(3))THEN
              IX(I+3) = IX(I)
              IF(IY(I).LT.IY(3))THEN
                IF(LEXCARC(IC))THEN
                  IY(I+3) = IYLEN
                ELSE
                  IF(.NOT.LEXCARC(IC))IY(I+3) = 0
                ENDIF
              ELSE
                IF(LEXCARC(IC))THEN
                  IY(I+3) = 0
                ELSE
                  IY(I+3) = IYLEN
                ENDIF
              ENDIF
            ELSE
C     .. general slope
              SLOPE = FLOAT(IY(I) - IY(3))/FLOAT(IX(I) - IX(3))
C     .. 
              IF((IX(I).LT.IX(3).AND.LEXCARC(IC)).OR.
     $             (IX(I).GT.IX(3).AND..NOT.LEXCARC(IC)))THEN
                IX(I+3) = NREC
                IY(I+3) = IY(3) + (NREC-IX(3))*SLOPE
                IF(SLOPE.GT.0.AND.IY(I+3).GT.IYLEN)THEN
                  IX(I+3) = IX(3) + (IYLEN-IY(3))/SLOPE
                  IY(I+3) = IYLEN
                ELSEIF(SLOPE.LT.0.AND.IY(I+3).LT.0)THEN
                  IX(I+3) = IX(3) - IY(3)/SLOPE
                  IY(I+3) = 0
                ENDIF
              ELSE
                IX(I+3) = 0
                IY(I+3) = IY(3) - SLOPE * IX(3)
                IF(SLOPE.GT.0.AND.IY(I+3).LT.0)THEN
                  IX(I+3) = IX(3) - IY(3)/SLOPE
                  IY(I+3) = 0
                ELSEIF(SLOPE.LT.0.AND.IY(I+3).GT.IYLEN)THEN
                  IX(I+3) = IX(3) + (IYLEN-IY(3))/SLOPE
                  IY(I+3) = IYLEN
                ENDIF
              ENDIF
            ENDIF
C     ..
C     .. centre and two end points on screen
            IF((IX(3).LE.NREC).AND.(IX(3).GE.0).AND.
     $           (IY(3).LE.IYLEN).AND.(IY(3).GE.0).AND.LEXCARC(IC))THEN
              IX(I+3) = IX(3)
              IY(I+3) = IY(3)
            ENDIF
            CALL MXD_IMG_VEC(IVHIMG,IC+30,IX(I),IY(I),
     $           IX(I+3),IY(I+3),ICOLR,IRV_OVL,1,IERR)
 250      ENDDO
 300    ENDDO
      ENDIF
C     
C---- draw excluded resolution rings
C     
      IF((MODE.EQ.7).OR.(MODE.EQ.0))THEN
        IF(NMASK.EQ.0)THEN
          ISTART = 1
          IFINISH = NEXCL
        ELSE
          ISTART = NMASK
          IFINISH = NMASK
        ENDIF
        DO 400 IC=ISTART,IFINISH,1
           CALL MXDCIR(1,ICOLR,IC,RESEXL(IC),DISTANCE,TWOTHETA,
     $         WAVE,RESCIR)
           CALL MXDCIR(1,ICOLR,IC,RESEXH(IC),DISTANCE,TWOTHETA,
     $         WAVE,RESCIR)
 400    ENDDO
      ENDIF
      RETURN
      END
      SUBROUTINE DSPADJ(LHELP)
C
C---- Write instructions on how to adjust image
C
      IMPLICIT NONE
C     ..        
C     .. Scalar Arguments ..
      LOGICAL LHELP
C     ..
C     .. Local Scalars ..
      INTEGER IXW,IYW,LINELEN,NUMLIN
      CHARACTER LINE*80
      IXW = 200
      IYW = 200
      LINELEN = 58
      NUMLIN = 17
      IF (.NOT.LHELP) NUMLIN = 8
C     
C     Create IO window
C
      CALL MXDCIO(0,LINELEN, NUMLIN, IXW,IYW)
      IF (.NOT.LHELP) THEN
        WRITE(LINE,6040)
 6040   FORMAT(1X,'Adjusting fit between observed and calculated',
     +            ' pattern.')
        CALL MXDWIO(LINE, 2)
        RETURN
      END IF
      WRITE (LINE, 6000)
 6000 FORMAT(1X,'Adjust fit between observed and calculated pattern.')
      CALL MXDWIO(LINE, 2)
      LINE = '                                                       '
      WRITE (LINE, 6002)
 6002 FORMAT (1X, 'Use the mouse to click first on a calculated spot')
      CALL MXDWIO(LINE, 2)
      LINE = '                                                       '
      WRITE (LINE, 6004)
 6004 FORMAT (1X,'position and then on the actual spot position.')
      CALL MXDWIO(LINE, 2)
      LINE = '                                                       '
      WRITE (LINE, 6006)
 6006 FORMAT (1X, 'Repeat this for another pair of calculated and')
      CALL MXDWIO(LINE, 2)
      LINE = '                                                       '
      WRITE (LINE, 6008)
 6008 FORMAT (1X, 'observed spot positions')
      CALL MXDWIO(LINE, 2)
      LINE = '                                                       '
      WRITE (LINE, 6010)
 6010 FORMAT (1X, 'The transformation required to match up these')
      CALL MXDWIO(LINE, 2)
      LINE = '                                                       '
      WRITE (LINE, 6012)
 6012 FORMAT (1X, 'spots will be calculated and you will be given the')
      CALL MXDWIO(LINE, 2)
      LINE = '                                                       '
      WRITE (LINE, 6014)
 6014 FORMAT (1X, 'option of accepting or rejecting the transformation')
      CALL MXDWIO(LINE, 2)
      END
C $Id: dspavg.f,v 1.2 2006/08/29 14:58:33 harry Exp $
C
      SUBROUTINE DSPAVG(IMAGE,NYPIX,NXPIX,IX,IY,IX2,IY2,PXAVG,PXRMS,
     +                  NPX)
      IMPLICIT NONE
C     =================================================================
C     
c     Calculate mean & rms of selected region of image
c
c  Input
c     image(NYPIX,NXPIX)      image
c     IX,IY               1st corner of box
c     IX2,IY2             2nd corner of box
c
c  Output
c     pxavg               average value
c     pxrms               rms deviation
c     npx                 number of pixels
C     
C     
      INTEGER NYPIX,NXPIX, IY,IX, IY2,IX2, NPX
      INTEGER*2 IMAGE(NYPIX, NXPIX)
      REAL PXAVG,PXRMS
C     
C     
      INTEGER I, J, INCY, INCX
      REAL VAL
C
      INTEGER INTPXL
      EXTERNAL INTPXL
C     
      INCY = SIGN(+1,IY2-IY)
      INCX = SIGN(+1,IX2-IX)
      NPX = ABS((IY2-IY)*(IX2-IX))
      PXAVG = INTPXL(IMAGE(IY,IX))
      PXRMS = 0.0
      IF (NPX .EQ. 0) RETURN
      PXAVG = 0.0
C     
      NPX = 0
      DO 10, J = IX,IX2,INCX
         DO 20, I = IY,IY2,INCY
            VAL = INTPXL(IMAGE(I,J))
            PXAVG = PXAVG + VAL
            PXRMS = PXRMS + VAL*VAL
            NPX = NPX+1
 20      CONTINUE
 10   CONTINUE
C
      PXAVG = PXAVG/NPX
      PXRMS = PXRMS/NPX - PXAVG*PXAVG
      IF (PXRMS .GE. 0.0) THEN
         PXRMS = SQRT(PXRMS)
      ELSE
         PXRMS = 0.0
      ENDIF   
C     
C
      RETURN
      END
