      LOGICAL LDSPSG,WINOPEN,LPAUSE,LHELP
      COMMON /DSPLYC/ FTOTAL,AVERAG,IMAGERMS,IMGLOW, IMGHI, IMGMAX,
     *     IMGMIN,JDSPWD,MAXDEN, NZOOM, JYZOOM, JZZOOM, 
     $     PIXEL_INTENSITIES,LDSPSG,WINOPEN,LPAUSE,LHELP
