C                                                           
C
C*******************************************************************


C&&*&& end_include  ../inc/dsplyc.f
c
c Size of image
      INTEGER NXPIX, NYPIX
C
      LOGICAL FIRST
      DATA FIRST /.TRUE./
      SAVE
C
C INITIALIZE COMMON VARIABLES
      IF (FIRST) THEN
         IMGLOW = 0
         IMGHI  = 0
         JDSPWD = -1
         MAXDEN = 262143 ! 65535
         MAXDEN = 65535
         LDSPSG = .TRUE.
         FIRST = .FALSE.
      ENDIF
C
      CALL DSPTTL(TITLE,LACTIV)
C
      CALL MXDINI(NXPIX, NYPIX)
C
      RETURN
      END
