C               image, before rejections based on spot size
C     INSPOT... Intensities of all spots found on current
C               image, before rejections based on spot size
C     ISIGSP... Standard deviations of intensities
C     NOIMG     The pack or image number.
C     PHI..     Phi value of the mid-point of the image
C     NIMAG     Total number of images read in (for autoindexing)
C     NEWSPT    If TRUE, new format spot coordinate file, otherwise old
C               format.
C     MEDWXSPOT Median spot size in pixels in X determined in PICKSPOTS
C     MEDWYSPOT Median spot size in pixels in Y determined in PICKSPOTS
C     IRSTRT    Number of the image on which to restart after an abort
C
C     SPXMIN    Minimum X coord (relative to direct beam position) for
C               spots
C     SPYMIN    Minimum Y coord (relative to direct beam position) for
C               spots
C     NSPTD     Number of displayed spots
C     THRESH    Threshold for pixel to be considered part of a spot,
C               is (background + THRESH*sigma)
C     NSPK      Number of maxima in a spot
C     MAXPKS    Maximum number of local maxima in a spot
C     RMSFAC    For multiple peaks treated as a single spot, the rms
C               variation over the pixels in the spot must be more than
C               RMSFAC times the variation expected from counting statistics
C               if all pixels had the background value.
C     MAXYEXT   Maximum extent of a "spot" in Y direction.
C     ANISOMAX  Maximum allowed ratio of spot size in X and Y
C
C     The following are for local background determination
C
C     LOCBG     Logical, TRUE if using local background (default)
C     NXBOX     Size of box for local background determination in X
C     NYBOX     Size of box for local background determination in Y
C     BGLOCAL   Array dimension (MAXBGBOX,MAXBGBOX,4) square holding 
C               local background values.
C---- BGLOCAL(I,J,1) ...   Mean background for box I,J
C---- BGLOCAL(I,J,2) ...   Poissonian sigma (uses GAIN) for box I,J
C---- BGLOCAL(I,J,3) ...   Rms variation in counts for box I,J
C---- BGLOCAL(I,J,4) ...   Average +ve difference between mean background
C                          of box I,J and its neighbours, expressed as
C                          a multiple of the rms variation of box I,J
C                          Used to identify boxes in shadow.
C     IWTBG     Array dimension (MAXBGBOX,MAXBGBOX) holding weight for
C               each local background area.
C     EXCLDICE  True if spots in resolution shells of ice rings are to be 
C               excluded
C     AUTORESLN Set resolution limit to 4A if spots between 4-6 are much
C               weaker than those between 6A and infinity.
C     AUTORES1  The lower resolution bin boundary (default 6A) for AUTORESLN
C     AUTORES2  The higher resolution bin boundary (default 4A) for AUTORESLN
C     AUTOFAC1  The intensity factor (default 0.2) for AUTORESLN
C     AUTOFAC2  The reflection number factor (default 0.25) for AUTORESLN
C     AUTORING  Automatically exclude radial bins that have too many spots
C               eg due to ice rings.
C     RINGFACT  Rings with more than RINGFACT*(average number of spots) are
C               rejected as potential ice/powder rings. Default 4.0.
C     NUMICE    Number of spots rejected as potentailly being ice spots
C     NTOOFEWPIX Number of spots rejected as having too few pixels.
C     NIMGSUMSPOT Number of images to sum when searching for spots for indexing.
C     NRESOLU   Number of spots rejected by automatic resolution reduction to 4.5
C
C
C     .. Scalars in Common Block /SPOTS2/ and /SPOTS2C/ ..
      REAL CUTPIXMAX,CUTPIXMIN,CUTWXMAX,CUTWXMIN,CUTWYMAX,CUTWYMIN,
     +     XSPLIT,YSPLIT,YOFFSET,XOFFSET,THRESH,RMINSP,RMAXSP,
     +     RMINSRCH,RMAXSRCH,SCALSRCH,SPXMIN,SPYMIN,THRESHMIN,
     +     THRESHMAX,RMSFAC,ANISOMAX,AUTORES1,AUTORES2,AUTOFAC1,
     +     AUTOFAC2,RINGFACT,RES2SD
      INTEGER NBINR,NBINT,IBINLIM,NPIXMIN,NPIXMAX,IIMAG,NIMAG,
     +     MEDWXSPOT,MEDWYSPOT,NSEARCH,ITHSET,ISAFE,IRSTRT,
     +     NSPTD,MAXPKS,MAXYEXT,NXBOX,NYBOX,IPIXMIN,IRMSFAC,
     +     NUMICE,NTOOFEWPIX,NIMGSUMSPOT,NRESOLU
      LOGICAL RADX,RADY,NEWSPT,DOFIND,LOCBG,EXCLDICE,
     +     AUTORESLN,AUTORING,AUTOTHRESH,FOUND(20)
C     ..
C     .. Arrays in common /SPOTS2/  and /SPOTS2C/ ....
      INTEGER NPIX(MXSPOT),IWXSPOT(MXSPOT),IWYSPOT(MXSPOT),
     $     IORDER(MXSPOT),INSPOT(MXSPOT),NOIMG(MAXIMG),ISDSPOT(MXSPOT),
     $     NSPK(MXSPOT), IWTBG(MAXBGBOX,MAXBGBOX), AVBG(IXWDTH)
      REAL BGOD(IXWDTH),PHI(MAXIMG),PHISAVE(MAXIMG),
     $     XSPOT(MXSPOT),YSPOT(MXSPOT),RESOLU(MXSPOT),
     $     RSPOT(MXSPOT),PHISTIM(MAXIMG),PHIRNGA(MAXIMG),
     +     BGODA2(21,21,3)
C     ..
C     .. Common Block /SPOTS2/  and /SPOTS2C/ ....
      COMMON /SPOTS2/
C     .. real scalars
     $     CUTPIXMAX,CUTPIXMIN,CUTWXMAX,CUTWXMIN,CUTWYMAX,CUTWYMIN,
     +     XSPLIT,YSPLIT,YOFFSET,XOFFSET,THRESH,RMINSP,RMAXSP,
     +     RMINSRCH,RMAXSRCH,SCALSRCH,SPXMIN,SPYMIN,THRESHMIN,
     +     THRESHMAX,RMSFAC,ANISOMAX,AUTORES1,AUTORES2,AUTOFAC1,
     +     AUTOFAC2,RINGFACT,RES2SD,
C     .. integer scalars
     $     NBINR,NBINT,IBINLIM,NPIXMIN,NPIXMAX,IIMAG,NIMAG,
     +     MEDWXSPOT,MEDWYSPOT,NSEARCH,ITHSET,ISAFE,IRSTRT,
     +     NSPTD,MAXPKS,MAXYEXT,
     +     NXBOX,NYBOX,
     +     IPIXMIN,IRMSFAC,NUMICE,NTOOFEWPIX,NIMGSUMSPOT,NRESOLU,
C     -- logicals 
     $     RADX,RADY,NEWSPT,DOFIND,LOCBG,EXCLDICE,AUTORESLN,
     $     AUTORING,AUTOTHRESH,FOUND,
C     .. integer arrays
     $     NPIX,IWXSPOT,IWYSPOT,IORDER,INSPOT,NOIMG,ISDSPOT,NSPK,
     +        IWTBG,AVBG,
C     .. real arrays
     $     BGOD,PHI,XSPOT,YSPOT,RESOLU,RSPOT,PHISTIM,PHIRNGA,
     $     BGODA2,PHISAVE

      REAL BGLOCAL(MAXBGBOX,MAXBGBOX,4)
       
      COMMON /SPOTS3/BGLOCAL

      CHARACTER IMGTEMPL*100,IMGFN*100,IMGNUM*9
      COMMON /SPOTS2C/ IMGTEMPL,IMGFN,IMGNUM
C&&*&& end_include  ../inc/spots2.f
C&&*&& include  ../inc/test.f
C--- awk generated include file  test.h
C---- START of include file test.h
C
C    Detector limits, used in SPTEST. All are in 10 micron units.
C    In the virtual detector frame, Y is parallel to the rotation axis
C    and X is orthogonal to the rotation axis.
C
C    In the scanner frame, X is parallel to the slow direction in the
C    image, Y is the fast direction.
C
C    RSCANSQ      Radius**2 of the scanned region of the plate (Mar scanners)
C                 This is different to the other limits because it is
C                 applied to the actual scanner coordinates rather than
C                 the virtual detector coordinates. All other limits apply
C                 to virtual detector coordinates.
C    XSCAN        Maximum X coordinate in detector frame (10 micron units)
C    YSCAN        Maximum Y coordinate in detector frame (10 micron units)
C    RSCANX,RSCANY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RSCAN defining the
C                 useable area of the detector.
C    XSCAN,YSCAN,RSCAN are maximum coords relative to the physical centre of 
C                 the detector (ie the mid-point of the image), NOT wrt the 
C                 direct beam position.
C    RMINX,RMINY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RMIN defining the
C                 useable area of the detector.
C    RMXSQD       Maximum radius (squared) in virtual detector frame
C    RMNSQD       Minimum radius (squared) in virtual detector frame
C    XMIN         Minimum X coordinate in  detector frame
C    XMAX         Maximum X coordinate in  detector frame
C    YMIN         Minimum Y coordinate in  detector frame
C    YMAX         Maximum Y coordinate in  detector frame
C    NXYEXC       Number of excluded areas set by user (rectangles, arcs)
C    NXYEXCDET    Number of detector specific excluded rectangles (Pilatus)
C    NOTILES      If set true, ignore all tile boundaries in Pilatus images
C    ICEWIDTH     Width of the exclusion shells for ice, this fraction
C                 of the actual resolution is used as the half-width
C    ICEWIDTHPREF Width of the exclusion shells for ice for post
C                 refinement, this fraction
C                 of the actual resolution is used as the half-width
C    PREFEXICE    Logical, true if reflections in ice rings to be
C                 excluded from post-refinement
C
C     .. Scalars in common block /TEST/ ..
      REAL RMXSQD,RMNSQD,XMIN,XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,
     +     RMINX,RMINY,XSCAN,YSCAN,CIRRAD,ICEWIDTH,ICEWIDTHPREF
      INTEGER NEXCL,NXYEXC,NXYEXCDET,IQUADNO,IARCNO,NEXCL2
      LOGICAL PREFEXICE,NOTILES
C
C     .. Arrays in common block /TEST/
      REAL RESEXL,RESEXH,XYEXC,CNREXC,EXCARC,CIRCEN,PHILIM,RES2EXL,
     +     RES2EXH,RES3EXL,RES3EXH,XYEXCSP
      INTEGER IEXCARC
      LOGICAL LEXCARC
C     ..
C     .. Common Block /TEST/ ..
      COMMON /TEST/RESEXL(MAXEXCL),RESEXH(MAXEXCL),XYEXC(4,MAXEXCL),
     +     CNREXC(8,MAXEXCL),
     $     EXCARC(5,MAXEXCL),CIRCEN(2),PHILIM(2),RMXSQD,RMNSQD,XMIN,
     +     XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,RMINX,RMINY,XSCAN,
     $     YSCAN,CIRRAD,IEXCARC(6,MAXEXCL),NEXCL,NXYEXC,IQUADNO,
     $     IARCNO,LEXCARC(MAXEXCL),NXYEXCDET,RES2EXL(MAXEXCL),
     $     RES2EXH(MAXEXCL),NEXCL2,ICEWIDTH,ICEWIDTHPREF,PREFEXICE,
     +     RES3EXL(MAXEXCL),RES3EXH(MAXEXCL),NOTILES,XYEXCSP(4,MAXEXCL)
C     ..
C
C

C&&*&& end_include  ../inc/test.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C&&*&& include  ../inc/xy.f
C
C $Id: xy.f,v 1.1 2002/05/02 10:47:25 harry Exp $
C
C--- awk generated include file  xy.h
C---- START of include file xy.h
C
C     .. Scalars in common block /XY/ ..
      REAL XTOFD,SINV,COSV,TANV,TWOTHETA
      INTEGER ICASS
C     ..
C     .. Common Block /XY/ ..
      COMMON /XY/XTOFD,SINV,COSV,TANV,TWOTHETA,ICASS
C     ..
C
C     XTOFD....  Crystal to detector distance in 10 micron units. Read from
C                keyworded input and never changed.
C
C                Spot positions are calculated in S/R XYSPOT (Called from
C                REEK) and are for an "ideal" detector at a distance of XTOFD.
C                These are converted into pixel positions in S/R MMTOPX
C                which applies the multiplicative factor XTOFRA to allow
C                for refinement of the distance. XTOFRA is the parameter
C                that is actually refined (in RDIST), rather than XTOFD.
C                The refined distance that is printed in the logfile is
C                actually XTOFRA*XTOFD
C
C     ICASS....  Indicates detector type:
C                0     Flat film
C                1     Vee shaped cassettes
C                2     FAST detector (only used in TESTGEN mode of OSCGEN)
C                3     Swung out FAST (ditto)
C                4     IP detector
C     TWOTHETA   Detector swing angle (degrees)
C&&*&& end_include  ../inc/xy.f
      INTEGER LENSTR
      EXTERNAL LENSTR
C     ..
C     .. External subroutines
      EXTERNAL FROMHDF5,MPARSE,CCPUPC,WRITE_SOCKET_LENGTH,
     +         PRINTFLOW,SHUTDOWN
C     ..
C     .. integer arguments
      INTEGER IMAGENO,THISCHUNK,IERR,IMODE,NIMGSUM
C     ..
C     .. local scalars
      DOUBLE PRECISION MOSTIMEA,MOSTIMEB
      DOUBLE PRECISION PHIBEGVALS(64000),PHIENDVALS(64000)
      INTEGER IMGSIZ,FIRSTIMG,LASTIMG,NIMAGES,SNIMAGES,
     $     IC,LENGTH,IOFFSET,IOFFSETSP,STARTX,STARTXSP,STARTY,
     $     STARTYSP,STEPX,STEPY,WIDTHX,WIDTHXSP,WIDTHY,WIDTHYSP,
     $     LASTIMAGEREAD,STHISCHUNK,INDENT,II,IFILETYPE,ID,NCH,
     $     ICONTIG,IDEBUG,IERRGAP
      REAL X1,X2,Y1,Y2
      CHARACTER*4096 IMGOUTC,XMLLINE
      CHARACTER*7  PSEUDOSERIAL
      CHARACTER THIS*30,CALLED*30,COMMENT*100,STRING1*10,STRING2*10,
     +          MACHINEXML*5,BEAMLINE*15,SERIOUSCOLOUR*6,
     +          CALLEDFROM*80
      LOGICAL FILEONLY,DIREXIST,TRAILING,READALREADY,
     +        EIGER1,EIGER2,EIGEROK,CONTIG,DONE
      DATA READALREADY /.FALSE./, LASTIMAGEREAD /0/, IFILETYPE/0/,
     +        DONE/.FALSE./
C
C     .. For parser
      INTEGER IBEG(NPARM),IDEC(NPARM),IEND(NPARM),ITYP(NPARM),NTOK
      REAL VALUE(NPARM)
      CHARACTER STR*100      
      SAVE
      CALLEDFROM = 'EIGER'
C     See inc/cbfinc for key to contents of arrays (but N.B. these may well 
C     change before final implementation):
      ODFILE = TRIM(ODFILE)//CHAR(0)
      XODFILE = ODFILE
      IDEBUG = 0
      IF (DEBUG(101)) THEN
        WRITE(IOUT,FMT=6090) IMODE,READALREADY,STHISCHUNK,
     +                       CHUNK,THISCHUNK,NIMGSUM,IMAGENO
        IF (ONLINE) WRITE(ITOUT,FMT=6090) IMODE,READALREADY,STHISCHUNK,
     +                       CHUNK,THISCHUNK,NIMGSUM,IMAGENO
 6090   FORMAT(1X,'Entering EIGER, Imode=',I2,' READALREADY',L2,
     +     ' STHISCHUNK',I4,' CHUNK',I4,
     +     ' THISCHUNK:',I3,'  NIMGSUM',I3,'  IMAGENO',I8)
        IDEBUG = 1
      END IF
      IF(STHISCHUNK.NE.CHUNK)THEN
        READALREADY = .FALSE.
      ENDIF
C
C---- Do not reset STHISCHUNK if images are being summed for display, spot
C     finding or centroid determination, because otherwise when going back
C     to a single image READALREADY will be set FALSE and incorrect XML will
C     be sent "DOCTYPE header_response".
C
      IF (IMODE.NE.5) STHISCHUNK = THISCHUNK
C
C---- Following test seems unnecessary, EIGER is never called with a value
C     of zero for THISCHUNK. agwl 15/4/19
C
      IF(THISCHUNK.EQ.0)then
        THISCHUNK = CHUNK
      ENDIF
      THIS = 'EIGER'
      INDENT = 5
      IF (DEBUG(101)) THEN
        WRITE(IOUT,FMT=6091) IMODE,READALREADY,STHISCHUNK,
     +                       CHUNK,THISCHUNK,NIMGSUM
        IF (ONLINE) WRITE(ITOUT,FMT=6091) IMODE,READALREADY,STHISCHUNK,
     +                       CHUNK,THISCHUNK,NIMGSUM
 6091   FORMAT(1X,'After resetting READALREADY,STHISCHUNK, Imode=',
     +     I2,' READALREADY',L2,' STHISCHUNK',I4,' CHUNK',I4,
     +     ' THISCHUNK',I3,'  NIMGSUM',I3)
      END IF
C
C---- for Eiger ----
C     Only assign GAIN if not set by keyword
      IF (IGAIN.EQ.0) GAIN = 0.87
C     Only assign IDIVIDE (ADC OFFSET) if not set by keyword
      IF (IIDIVIDE.EQ.0) IDIVIDE = 0
C
C---- Assign radius of default backstop circule shadow
C
      RMINIP = 200
C     ..
C     .. create a directory name and a pseudo-template from this
C
C---- now strip off any directory from the front of the template and add it to the
C     first free slot in FDISK
        LENGTH = LENSTR(ODFILE)
        FILEONLY = .TRUE.
        DIREXIST = .FALSE.
        IC = LENGTH
        DO 1000 WHILE (FILEONLY)
          IF(IC.GT.0)THEN
            IF(ODFILE(IC:IC).EQ.'/')THEN
              FILEONLY = .FALSE.
              DIREXIST = .TRUE.
C     ..
C     .. need to increment so we don't have a leading "/"
              IC = IC + 1
            ELSE
              IF(IC.LE.1)FILEONLY = .FALSE.
            ENDIF
            IC = IC - 1
          ELSE
C     ..
C     .. special case where image ident starts with digits
            FILEONLY = .FALSE.
          ENDIF
 1000   ENDDO
C
C---- allow for files ending in either "_master.h5" or ".nxs"
C
        IF(DIREXIST)THEN
          NCH = LENGTH
          IF(NCH.GT.10)THEN
            IF(STR(NCH-9:NCH).EQ.'_master.h5')THEN
              FDISK(1) = ODFILE(1:IC)
              IDENT = ODFILE(IC+1:LENGTH-9)
c            ELSE
c              FDISK(1) = '.'
c              IDENT = ODFILE(IC:LENGTH-9)
            ENDIF
          ENDIF
          IF(NCH.GT.4)THEN
            IF(STR(NCH-3:NCH).EQ.'.nxs')THEN
              FDISK(1) = ODFILE(1:IC)
              IDENT = ODFILE(IC+1:LENGTH-3)
c            ELSE
c              FDISK(1) = '.'
c              IDENT = ODFILE(IC:LENGTH-3)
            ENDIF
          ENDIF
        ENDIF

        WAXFN = IDENT
        IC = LENSTR(IDENT)
C     ..
C     .. strip off any trailing '-','_'
        TRAILING = .TRUE.
        DO 1010 WHILE(TRAILING)
          if((IDENT(IC:IC).eq.'-').or.(IDENT(IC:IC).eq.'_'))THEN
            IDENT(IC:IC) = ''
          ELSE
            TRAILING = .FALSE.
          ENDIF
          IC = IC - 1
 1010   ENDDO
c        WRITE(PSEUDOSERIAL,FMT=6010)IMAGENO
c 6010   FORMAT('.',I0.6)
c        print*,PSEUDOSERIAL
c        PRINT*,'pseudoimage is ',TRIM(IDENT)//PSEUDOSERIAL
c      WRITE(*,6000,ADVANCE='NO')
 6000 FORMAT('Enter the number of images to combine into ',
     $     'each pseudo-image: ')
c      READ(*,*)CHUNK
      IERR = 0
C
C---- need to check if the image have already been chunked, in which case 
C     FIRSTIMG and LASTIMG will not be the Mosflm image numbers...
C
      IF(ABS(PHIEND - PHIBEG)-(PHIENDVALS(1) - PHIBEGVALS(1)).GT.1E-3)
     $     THEN
        FIRSTIMG = ((IMAGENO-1)*THISCHUNK)+1
      ELSE
        FIRSTIMG = IMAGENO
      ENDIF
      LASTIMG = FIRSTIMG + THISCHUNK + (NIMGSUM-1)*THISCHUNK - 1

      IMGSIZ = IYLENGTH * IXWDTH
      CALL CTIMER(MOSTIMEA)
C     ..
C     .. call to get header information & phi values 'BRIEF HEADER RESPONSE'
C     .. use PHI values stored from reading the header once already!
      IF(IMODE.EQ.3)THEN
        IF(SOCKLO.AND..NOT.NO_XML) THEN
C
C---- Change this code as it does not work if images are not abutting in phi, 
C     eg screening images at 0,90,180
C
C          HPHIS = HPHIE
C          HPHIE = HPHIE + HPHIR
          HPHIS = PHIBEGVALS(FIRSTIMG)
          HPHIE = PHIENDVALS(LASTIMG)
C
C---- Test for images being contiguous in phi
C
          ICONTIG = 0
          IF (FIRSTIMG.GT.1) THEN
            CONTIG = (ABS(HPHIS-PHIENDVALS(FIRSTIMG-1)).LT.0.001)
            IF (.NOT.CONTIG) ICONTIG = 1
          END IF
          WRITE(XMLLINE,FMT=7000)ODFILE(1:LENSTR(ODFILE)),
     $         TEMPLSAV(1:LENSTR(TEMPLSAV)),IMAGENO,
     $         HPHIS,HPHIE,GAIN,ICONTIG
          CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(XMLLINE),XMLLINE)
          IF(DEBUG(101))THEN
            WRITE(IOUT,FMT=7000)ODFILE(1:LENSTR(ODFILE)),
     $         TEMPLSAV(1:LENSTR(TEMPLSAV)),IMAGENO,
     $         HPHIS,HPHIE,GAIN,ICONTIG
            WRITE(ITOUT,FMT=7000)ODFILE(1:LENSTR(ODFILE)),
     $         TEMPLSAV(1:LENSTR(TEMPLSAV)),IMAGENO,
     $         HPHIS,HPHIE,GAIN,ICONTIG
          END IF
          THISCHUNK = STHISCHUNK
          RETURN
        ENDIF
      ENDIF
C     ..
C     .. full header information
C     .. only read the header once!
C     ..
      IF(IMODE.EQ.2.OR.IMODE.EQ.4)THEN
          IF(READALREADY)THEN
            IF(SOCKLO.AND.IMODE.EQ.2.AND..NOT.NO_XML) THEN
              WRITE(XMLLINE,FMT=7000)ODFILE(1:LENSTR(ODFILE)),
     $             TEMPLSAV(1:LENSTR(TEMPLSAV)),IMAGENO,
     $             PHIBEGVALS(IMAGENO),PHIBEGVALS(IMAGENO)+HPHIR,GAIN
C
C---- Not clear to me why it needs to send this XML. Previously it may
C     never have done this, because Indeed, now that 
cal              CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(XMLLINE),XMLLINE)
            ENDIF
          ELSE 
            READALREADY = .TRUE.
C     
C---- Print for program flow
C
            CALLED = 'FROMHDF5'
            IF (IMODE.EQ.2) THEN
              COMMENT = 'to read HDF5 metadata'
            ELSE
              IF (FIRSTIMG.EQ.LASTIMG) THEN
                WRITE (STRING1,FMT=6092) FIRSTIMG
                COMMENT = 'to read HDF5 image'//STRING1
              ELSE
                WRITE (STRING1,FMT=6092) FIRSTIMG
                WRITE (STRING2,FMT=6092) LASTIMG
 6092           FORMAT(I8)
                COMMENT = 'to read HDF5 images'//STRING1//' to'//STRING2
              END IF
            END IF
            IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
            CALL CTIMER(MOSTIMEA)
C
C---- Arguments for FROMHDF5
C
C           Input arguments:
C           ODFILE       name of mast h5 file
C           IMAGE        array storing pixel values for image
C           FIRSTIMG     number of first image to be read in hdf5 file, allowing for chunking and summing
C           LASTIMG      number of last image to be read in hdf5 file, allowing for chunking and summing
C
C           Returned arguments:
C           NIMAGES      number of images in mosflm job, allowing for chunking
C
            CALL FROMHDF5(ODFILE,IMAGE,FIRSTIMG,LASTIMG,
     $           NIMAGES,CBF_INT,CBF_INT4,CBF_DOUBLE,CBF_CHAR,
     $           PHIBEGVALS,PHIENDVALS,IMODE,IFILETYPE,IDEBUG,IERR)
            CALL CTIMER(MOSTIMEB)
C
C---- Check for errors in reading HDF5 file
C
            IF (IERR.GT.0) THEN
              IERRLEVEL = 10
              IF (IERR.EQ.10) THEN
                WRITE(MESSAGE,FMT=6060) FIRSTIMG
 6060  FORMAT('There was a problem opening the hdf5 data file for',
     +         ' image',I7,'.__nl__This suggests that',
     +           ' the file is missing or corrupted.__nl__',
     +           'Check that all data files are present and are',
     +           ' the correct length.')
                WRITE(IOUT,FMT=6064) FIRSTIMG
                IF (ONLINE) WRITE(ITOUT,FMT=6064) FIRSTIMG
 6064           FORMAT(1X,'*** FATAL ERROR ***',/,1X,'Could not open a',
     +          ' data file for image',I7,' the data file is either ',
     +          'missing or corrupted.',/,1X,'Check the file lengths',
     +          ' of the data files.')
              ELSE IF (IERR.EQ.20) THEN
                WRITE(MESSAGE,FMT=6066) FIRSTIMG
 6066           FORMAT('Could not read image',I7,' in the hdf5 data ',
     +         'file.__nl__This suggests that',
     +           ' the file is missing or corrupted.__nl__',
     +           'Check that all data files are present and are',
     +           ' the correct length.')
                WRITE(IOUT,FMT=6068) FIRSTIMG
                IF (ONLINE) WRITE(ITOUT,FMT=6068) FIRSTIMG
 6068           FORMAT(1X,'*** FATAL ERROR ***',/,1X,'Could not read',
     +         ' image',i7,' the data file is either ',
     +          'missing or corrupted.',/,1X,'Check the file lengths',
     +          ' of the data files.')
              END IF
C     
C---- Print for program flow
C
              CALLED = 'SHUTDOWN'
              COMMENT = 'error reading hdf5 file'
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
            END IF
            IF (IFILETYPE.EQ.1) THEN
              WRITE(IOUT,FMT=6094)
              IF (ONLINE) WRITE(ITOUT,FMT=6094)
 6094         FORMAT(1X,'Phi values are stored in ',
     +                  '/entry/sample/goniometer/phi')
            ELSE IF (IFILETYPE.EQ.2) THEN
              WRITE(IOUT,FMT=6096)
              IF (ONLINE) WRITE(ITOUT,FMT=6096)
 6096         FORMAT(1X,'Phi values are stored in ',
     +                  '/entry/sample/goniometer/omega')
            ELSE IF (IFILETYPE.EQ.3) THEN
              WRITE(IOUT,FMT=6098)
              IF (ONLINE) WRITE(ITOUT,FMT=6098)
 6098         FORMAT(1X,'Phi values are stored in ',
     +                  '/entry/sample/transformations/omega')
            ELSE
              WRITE(IOUT,FMT=6100)
              IF (ONLINE) WRITE(IOUT,FMT=6100)
 6100         FORMAT(1X,'*** WARNING ***',/,1x,'Phi values not',
     +           ' found in metadata.')
            END IF
            IF (DEBUG(99)) THEN
              WRITE(IOUT,FMT=6102) MOSTIMEB - MOSTIMEA
              IF (ONLINE) WRITE(ITOUT,FMT=6102) MOSTIMEB - MOSTIMEA
 6102         FORMAT(1X,'Call to FROMHDF5 took',F8.2,' seconds')
            END IF
C        PRINT*,'converting the whole dataset took ',mostimeb-mostimea,
C     $       ' seconds'
C     ..
C     .. copy from CBF_vals to Mosflm vals
            
            IYLEN =      CBF_INT(3)
            NREC =       CBF_INT(4)

            HWAVE =      CBF_DOUBLE(1)
            HDIST =      CBF_DOUBLE(2)
C
C---- Test for -ve value, indicating that this is not present in metdata
C
            IF (HDIST.LT.0) HDIST = 0.0
C
C---- Test for -ve value, indicating that this is not present in metdata.
C     Default to pixel size for Dectris Eiger
            HRAST =      CBF_DOUBLE(3)
            IF (HRAST.LT.0) HRAST = 0.075

C
C---- Need to assign a value to YSCAL, because the XML header response is 
C     written in this subroutine for HDF5 files and YSCAL has not yet been
C     assigned a value so it will have its initialised value of -999.0
C     (set in CONTROL) and this gives a bad XML as well as sending the
C     wrong value to iMosflm. 
C---- Only assign YSCAL if a value has not been specified by a keyword.
C     Ensure it is only set once by setting IYSCAL to 2.
C
            IF (IYSCAL.EQ.0) THEN
              YSCAL =      CBF_DOUBLE(4)/CBF_DOUBLE(3)
              IYSCAL = 2
            END IF 
C
            HPHIS =      CBF_DOUBLE(6)
            HPHIE =      CBF_DOUBLE(7)
            HPHIR =      HPHIE - HPHIS
            
            WAVELENGTH = HWAVE
            HBEAMX =     HRAST * REAL(CBF_INT(6))
            HBEAMY =     HRAST * REAL(CBF_INT(5))
C
C---- If beam coords are zero or negative, set to centre of image
C
            IF (HBEAMX.LE.0.0) HBEAMX = 0.5*NREC*HRAST
            IF (HBEAMY.LE.0.0) HBEAMY = 0.5*IYLEN*HRAST
            IF(IBEAM.EQ.0)IBEAM = 3
            
            HSERIAL = CBF_CHAR(8)
            CALL MPARSE(CBF_CHAR(6),IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
c            MACHINE = cbf_Char(6)(IBEG(2):IEND(2))
            MACHINE = 'HDF5'
            CALL CCPUPC(MACHINE)
            IF(NTOK.GE.3)THEN
              MODEL = cbf_Char(6)(IBEG(3):IEND(3))
            ELSE 
C---- from DLS
              MODEL = cbf_Char(6)(IBEG(2):IEND(2))
CAL              model = 'eiger'
            ENDIF
            CALL CCPUPC(MODEL)
            CMACHINE = cbf_Char(6)
C     
C---- I don't know if this is in the header...
C     
            IF(IOMEGAF.NE.1)THEN
              IF((NREC.EQ.2167).AND.(IYLEN.EQ.2070)) THEN
                IF(HSERIAL.EQ.'unknown')THEN
C---- DLS NXS format for 4M - omega incorrect in header?
                  OMEGAFD = 270.0
                ELSE 
                  OMEGAFD = 0.0
                ENDIF
C---- Dectris Quadro single module detector (as set up at Dectris)
              ELSE IF((NREC.EQ.514).AND.(IYLEN.EQ.514)) THEN
                  OMEGAFD = 90.0
              ELSE
C---- Conventional master file 
                OMEGAFD = 0.0
              ENDIF
              OMEGAF  = OMEGAFD * DTOR
            ENDIF
            IF(.NOT.IINULL)NULLPIX = -1
            EFAC = 0.000001
            IF(IBGSIG.EQ.0)BGSIG = 4.0
            IF (IBGSIG.EQ.0.AND.MACHINE.EQ.'RIPI')BGSIG = 6.0
            IF (IBGSIG.EQ.0.AND.MACHINE.EQ.'RIEI')BGSIG = 6.0
C
C---- Allow default BGFRAC to be overridden by keyword supplied value
C     13/12/19 AGWL
C
            IF (IBGFRAC.EQ.0) BGFRAC = 1.0
            IF(IGRADMAX.EQ.0)GRADMAX = 1.00
            IF(IGRADMAXR.EQ.0)GRADMAXR = 1.00
          
C     ..
C     .. set up detector limits
            XMAXIP = INT(NREC*HRAST)*50
            YMAXIP = INT(IYLEN*HRAST)*50
            RMAXIP = SQRT(XMAXIP**2+YMAXIP**2)
            XSCAN = XMAXIP
            YSCAN = YMAXIP
            RSCANIP = RMAXIP
            RMAX = SQRT(REAL(XMAXIP*XMAXIP+YMAXIP*YMAXIP))
            XMAX = XMAXIP
            YMAX = YMAXIP
            IF (ILIMIT.EQ.0) THEN
              XLIMIT = 0.01*(XMAXIP/2)
              LIMIT = NINT(100*XLIMIT)
            END IF
C     
C---  these are values determined from Pilatus, may be okay for Eiger
C     
            INVERTX = .TRUE.
            SPIRAL = .FALSE.
            CIRCULAR = .FALSE.
            ORTHOG = .TRUE.
            TILED = .TRUE.
            TRUSTED = .TRUE.
            HEADINFO = .FALSE.
            USEHDR = .TRUE.
C     
C---- mask the gaps between modules
C
            IF(.NOT.GAPMASK)THEN
C
C---- Now set up by calling GETGAPS
C     IOFFSET is the offset to be applied because of uncertainty between
C     mm coords and pixel numbers, ie to mm coords refer to middle of pixel
C     or the corner of the pixel. 
C     IOFFSETSP is the offset applied when spot finding, to avod finding
C     "false" spots at the tile boundaries.
C     Both IOFFSET and IOFFSETSP effectively increase the size of the gaps.
C
              IOFFSET = 1
              IOFFSETSP = 5
              IERRGAP = 0
              CALL GETGAPS(NREC,IYLEN,IOFFSET,IOFFSETSP,HRAST,IERRGAP)
              IF (IERRGAP.NE.0) THEN
                WRITE(IOUT,FMT=6080) NREC,IYLEN
                IF (ONLINE) WRITE(ITOUT,FMT=6080) NREC,IYLEN
 6080           FORMAT(1X,'*** WARNING ***',/,1X,
     +           'Based on the image size of',I6,' by',I6,
     +           ' the detector has not been recognised',/,1X,
     +           'as Pilatus, Eiger or Eiger2.'/,1X,'This means',
     +           ' that the gaps between tiles will not be marked',
     +           ' as',/,1X,'inactive areas.',/,1X,'This should not',
     +           ' affect integration providing these pixels have',
     +           ' values of -1.')
                NTILEX = 1
                NTILEY = 1
              END IF
              GAPMASK = .TRUE.
C
C---- the 5th character of MACHINEXML is used in Tcl code to distinguish 
C     Pilatus3 and Eiger2 detectors, although this only affects what is 
C     shown in the Detector tab of Settings->Experiment->Detector
C
              MACHINEXML = ' '
              MACHINEXML(1:4) = MACHINE
              IF (DECTRIS_TYPE(1:6).EQ.'EIGER2') MACHINEXML(5:5) = '2'
            ENDIF
C
C---- Check for reverse phi based on serial number
C
C     TAKANORI: this is EIGER 9M at SPring-8 BL32XU Serial no: E-18-0103
C
            IF (HSERIAL.EQ.'E-18-0103') THEN
              IF (.NOT.UPDATEOMEGA) THEN
                OMEGAFD = 180.0 
                OMEGAF = OMEGAFD * DTOR
                UPDATEOMEGA = .TRUE.
                WRITE(IOUT,FMT=6058) 
                IF (ONLINE) WRITE(ITOUT,FMT=6058)
 6058         FORMAT(/,1X,'*** Based on the detector serial number',
     +               ' this detector is believed to be    ***',/,1X,
     +               '*** at Spring-8 ',
     +               'on a beamline with a reversed phi. This',
     +               ' will automatically ***',/,1X,'*** be taken ',
     +               ' into account during processing ***')
              END IF
            END IF
C
C---- Check for vertical spindle, eg MD3 diffractometer as set up at P14 at Petra
C     E-32-0107 and the BIOMAX beamline at MAXIV E-32-0105 (ESRF ID23-2 is currently Pilatus)
C     and the VMXm beamline at DLS.
C
            IF ((HSERIAL(1:LENSTR(HSERIAL)).EQ.'E-32-0107')) THEN
C     this is Gleb's Eiger detector on Petra P14 (MD3 diffractometer
C     with vertical rotn axis)
              OMEGAFD = 270
              BEAMLINE = 'PETRAII P14'
              WRITE(IOUT,FMT=6012) HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
              IF (ONLINE) WRITE(ITOUT,FMT=6012) 
     +                 HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
 6012         FORMAT(/,1X,'*** IMPORTANT ***',/,1x,'From the detector',
     +          ' serial number ',A,' this has been identified',
     +          ' as an image from ',A,/,1X,'that has an MD3',
     +       ' diffractometer with an inverted vertical rotation axis.',
     +          /,1X,'The OMEGA angle has therefore been set to',F6.1,
     +          ' instead of the usual value of 0.0.',/,1X,'If this ',
     +          'is not correct, reset OMEGA to 0.0')
            ELSE IF (HSERIAL(1:LENSTR(HSERIAL)).EQ.'E-32-0105') THEN
              OMEGAFD = 270.0
C     this is the Eiger at BIOMAX beamline at MaxIV (MD3 diffractometer
C     with vertical rotn axis)
              OMEGAFD = 270
              BEAMLINE = 'MaxIV BIOMAX'
              WRITE(IOUT,FMT=6012) HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
              IF (ONLINE) WRITE(ITOUT,FMT=6012) 
     +                 HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
            ELSE IF (HSERIAL(1:9).EQ.'E-18-0118') THEN
C     this is Eiger on DLS VMXm, with a vertical rotn axis
              OMEGAFD = 90
              BEAMLINE = 'DLS VMXm'
              WRITE(IOUT,FMT=6012) HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
              IF (ONLINE) WRITE(ITOUT,FMT=6012) 
     +                 HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
            ENDIF
C
C---- Write a warning message
C
C
C---- Non-standard beamline setup (eg vertical rotation axis), OMEGA > 0
C
            IF ((ABS(OMEGAFD).GT.1.0).AND.(SOCKLO).AND.(.NOT.DONE)) THEN
              DONE = .TRUE.
              XMLLINE = ' '
              SERIOUSCOLOUR = 'RED'
              WRITE(XMLLINE,FMT=6016) SERIOUSCOLOUR
              CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
            END IF

 6016   FORMAT('<?xml version="1.0"?>',
     $         '<!DOCTYPE warnings>',
     $         '<warnings><process>indexing</process>'
     $         '<warning><type>warning</type>',
     $     '<colour>',A,'</colour>',
     +         '<message>Non standard experimental setup',
     +         '</message>',
     +     '<detail>From the detector serial number, the data',
     +     ' appears to come from a beamline with a vertical',
     +     ' rotation axis. See start of mosflm.lp file for more ',
     +     'details. If this is not the case, reset OMEGA',
     +     ' to 0.0 in Settings->Experiment settings',
     +     ' otherwise indexing will not work.',
     +          '</detail><hint>none</hint>',
     +      '</warning></warnings>')
 
C
            IF (DEBUG(101)) THEN
              WRITE(IOUT,FMT=6072) MACHINE(1:LENSTR(MACHINE)),
     +                           HSERIAL(1:LENSTR(HSERIAL)),
     +                           GAPVAL,OMEGAFD
              IF (ONLINE) WRITE(ITOUT,FMT=6072) 
     +           MACHINE(1:LENSTR(MACHINE)),HSERIAL(1:LENSTR(HSERIAL)),
     +         GAPVAL,OMEGAFD
 6072       FORMAT(1X,'Machine: ',A,'  Serial number:',A,'  Gapval',I8,
     +             '  Omega:',F8.2)
                WRITE(IOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +          BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
                IF (ONLINE) WRITE(ITOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +          BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
 6070   FORMAT(1X,'From header record in image',/,1X,
     +         'NREC= ',I5,' IYLEN= ',I5,' Pixel size ',F8.5,' mm',
     +         ' Beam polarisation ',F6.4,/,1X,'Byte-swapping ',L1,
     +         /,1X,'Distance: ',F8.2,'  Wavelength: ',F8.5,'  Phi',
     +         ' start ',F9.3,'  Phi end: ',F9.3,' Twotheta ',F7.3,
     +         '  Direct beam coords: ',2F8.2)
            END IF
C
            IF(DEBUG(101))THEN
              write(iout,*)'Machine is: ',machine
              write(iout,*)'Model is:   ',model
              write(iout,*)'CMachine is: ',Cmachine(1:lenstr(cmachine))
              write(iout,*)'BEAM: ',hbeamx,hbeamy
              write(iout,*)'Image Size: ',NREC,IYLEN
              write(iout,*)'angles for this image: ',HPHIS,HPHIE,HPHIR
              write(iout,*)'wavelength: ',wAVELEngth
              write(iout,*)'crystal to detector distance: ',hdist
              write(iout,*)'machine: ',machine
              write(iout,*)'serial number: ',HSERIAL(1:lenstr(hserial))
              IF(ONLINE)THEN
                write(itout,*)'Machine is: ',machine
                write(itout,*)'Model is:   ',model
                write(itout,*)'CMachine is: ',
     +                         Cmachine(1:lenstr(cmachine))
                write(itout,*)'BEAM: ',hbeamx,hbeamy
                write(itout,*)'Image Size: ',NREC,IYLEN
                write(itout,*)'angles for this image: ',HPHIS,HPHIE,
     $               HPHIR
                write(itout,*)'wavelength: ',wAVELEngth
                write(itout,*)'crystal to detector distance: ',hdist
                write(itout,*)'machine: ',machine
                write(itout,*)'serial number: ',
     +                         HSERIAL(1:lenstr(hserial))
              ENDIF
            ENDIF
            
           
C     ..
C     .. CBF_vals have just been copied to Mosflm vals
            ID = IMAGENO
            IF(SOCKLO.AND.IMODE.EQ.2.AND..NOT.NO_XML) THEN
C     ..
C     .. full header response
              IF (DEBUG(101)) THEN
                WRITE(IOUT,FMT=6030) YSCAL
                IF (ONLINE) WRITE(ITOUT,FMT=6030) YSCAL
 6030           FORMAT(1X,'write XML header response,YSCAL=',F12.4)
              END IF
              WRITE(XMLLINE,FMT=7020)MACHINEXML,MODEL,
     $             HSERIAL(1:LENSTR(HSERIAL)),TRUSTED,CUTOFF,
     $             PRCUTOFF,NULLPIX,
     $             PKRAT,BGRAT,GRADMAXR,GRADMAX,
     $             FLOAT(LIMIT/100),
     $             XODFILE(1:LENSTR(XODFILE)),
     $             TEMPLSAV(1:lenstr(templsav)),
     $             ID,THISCHUNK,NIMAGES,NHBYTE,NREC,IYLEN,HPHIS,HPHIE,
     $             HBEAMX,HBEAMY,RMINIP/100.0,HDIST,TWOTHETA,HWAVE,
     $             HRAST,YSCAL,GAIN,IDIVIDE,
     $             OMEGAFD-OMEGAREV,INVERTX,
     $             XMIN*0.01,XMAX*0.01,YMIN*0.01,YMAX*0.01,RMAX*0.01,
     $             XSCAN*0.01,YSCAN*0.01,
     $             RSCANX*0.01,RSCANX*0.01,RSCANY*0.01,
     $             NTILEX,STARTX,WIDTHX,NTILEY,STARTY,WIDTHY,
     $             RADX,NPIXBG*HRAST,
     $             SPOTFILEORIGIN,SPOTFILEAXISORDER,SWINGAXIS
              CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $             XMLLINE)
            ENDIF
          ENDIF
C     ..
C     .. end of "readalready" block
C     ..
C     
C---- End of reading the header information
C     End of IF(IMODE.EQ.2.OR.IMODE.EQ.4) block
C
      ENDIF
C
C----------------------------------------------------------------------
C
C---- Read the image data
C
      IF(IMODE.EQ.4)THEN
        IC = FIRSTIMG
        
C     ..
C     .. Call to get image data
        IF ((FIRSTIMG.LT.1).OR.
     $       (LASTIMG.GT.NIMAGES*THISCHUNK)) THEN
          IF(FIRSTIMG.EQ.LASTIMG)THEN
            IF(ONLINE)WRITE(ITOUT,FMT=6020)FIRSTIMG,NIMAGES
            WRITE(IOUT,FMT=6020)FIRSTIMG,NIMAGES
 6020       FORMAT(' **** ERROR **** ',/,'Image ',I6,' is not in ',
     $         'the dataset, which has ',I6,' images')
          ELSE
            IF(ONLINE)WRITE(ITOUT,FMT=6040)FIRSTIMG,LASTIMG,NIMAGES
            WRITE(IOUT,FMT=6040)FIRSTIMG,LASTIMG,NIMAGES
 6040       FORMAT(' **** ERROR **** ',/,'Images ',I6,' to ',I6,
     $         ' are not in ',
     $         'the dataset, which has ',I6,' images')
          
 7040       FORMAT('<?xml version="1.0"?>',
     $         '<!DOCTYPE header_response>',
     +         '<header_response>',
     +         '<status><code>error</code>',
     +         '<message>Check that image ',I6,' exists</message>',
     +         '</status>',
     $         '<image_filename>',A,'</image_filename>',
     $         '</header_response>')
            WRITE(XMLLINE,FMT=7040)LASTIMG,XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)

          ENDIF
          RETURN
        ENDIF
C
C---- okay, we know FIRSTIMG and LASTIMG are valid image numbers
C
C     
C---- Print for program flow
C
        CALLED = 'FROMHDF5'
        IF (FIRSTIMG.EQ.LASTIMG) THEN
          WRITE (STRING1,FMT=6092) FIRSTIMG
          COMMENT = 'in MODE=4 to read HDF5 image'//STRING1
        ELSE
          WRITE (STRING1,FMT=6092) FIRSTIMG
          WRITE (STRING2,FMT=6092) LASTIMG
      COMMENT = 'in MODE=4 to read HDF5 images'//STRING1//' to'//STRING2
        END IF
        IF (DEBUG(99)) 
     +              CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
        CALL CTIMER(MOSTIMEA)
        CALL FROMHDF5(ODFILE,IMAGE,FIRSTIMG,LASTIMG,
     $       NIMAGES,CBF_INT,CBF_INT4,CBF_DOUBLE,CBF_CHAR,
     $       PHIBEGVALS,PHIENDVALS,IMODE,IFILETYPE,IDEBUG)
        CALL CTIMER(MOSTIMEB)
        IF (DEBUG(99)) THEN
          WRITE(IOUT,FMT=6102) MOSTIMEB - MOSTIMEA
          IF (ONLINE) WRITE(ITOUT,FMT=6102) MOSTIMEB - MOSTIMEA
        END IF
        HPHIS =      CBF_DOUBLE(6)
        HPHIE =      CBF_DOUBLE(7)
        HPHIR =      HPHIE - HPHIS
        FIRSTIMG = FIRSTIMG + THISCHUNK
        LASTIMG = LASTIMG + THISCHUNK
C        PRINT*,'converting the whole dataset took ',mostimeb-mostimea,
C     $       ' seconds'
      ENDIF

C
C---- Add new IMODE=5 to sum images for image display or spotfinding into array IMAGE2
C
      IF (IMODE.EQ.5) THEN
C
C     
C---- Print for program flow
C
        CALLED = 'FROMHDF5'
        WRITE (STRING1,FMT=6092) FIRSTIMG
        WRITE (STRING2,FMT=6092) LASTIMG
        COMMENT = 'in MODE=5 to read HDF5 images'//
     +             STRING1//' to'//STRING2
        IF (DEBUG(99)) 
     +              CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
C---- In FROMHDF5, NIMAGES is divided by the number of images summed here
C     so save number and restore it after FROMHDF5
c
        SNIMAGES = NIMAGES
        write(iout,fmt=8000) nimages,FIRSTIMG,LASTIMG
        if (online) write(itout,fmt=8000) nimages,FIRSTIMG,LASTIMG
 8000   format(1x,'before fromhdf5,nimages,firstimg,lastimg',3I5)
        CALL CTIMER(MOSTIMEA)
        CALL FROMHDF5(ODFILE,IMAGE2,FIRSTIMG,LASTIMG,
     $       NIMAGES,CBF_INT,CBF_INT4,CBF_DOUBLE,CBF_CHAR,
     $       PHIBEGVALS,PHIENDVALS,IMODE,IFILETYPE,IDEBUG)
        NIMAGES = SNIMAGES
        CALL CTIMER(MOSTIMEB)
        IF (DEBUG(99)) THEN
          WRITE(IOUT,FMT=6102) MOSTIMEB - MOSTIMEA
          IF (ONLINE) WRITE(ITOUT,FMT=6102) MOSTIMEB - MOSTIMEA
        END IF
        write(iout,fmt=8002) nimages,FIRSTIMG,LASTIMG
        if (online) write(itout,fmt=8002) nimages,FIRSTIMG,LASTIMG
 8002   format(1x,'after fromhdf5,nimages,firstimg,lastimg',3I5)
      END IF
      RETURN
 7000 FORMAT('<?xml version=''1.0''?>',
     $     '<!DOCTYPE brief_header_response>',
     $     '<brief_header_response><status><code>ok</code>',
     $     '</status>',
     $     '<image_filename>',A,'</image_filename>',
     $     '<image_template>',A,'</image_template>',
     $     '<image_number>',I8,'</image_number>',
     $     '<phi_start>',F10.2,'</phi_start>',
     $     '<phi_end>',F10.2,'</phi_end>',
     $     '<gain>',F7.2,'</gain>','<contig>',I2,'</contig>',
     $     '</brief_header_response>')
 7020 FORMAT('<?xml version=''1.0''?>',
     $     '<!DOCTYPE header_response>',
     $     '<header_response><status><code>ok</code>',
     $     '</status>',
     $     '<detector_manufacturer>',A,'</detector_manufacturer>',
     $     '<detector_model>',A,'</detector_model>',
     $     '<detector_serial_number>',A,'</detector_serial_number>',
     $     '<trusted_detector>',L1,'</trusted_detector>',
     $     '<saturation_pixel_value>',I12,
     $     '</saturation_pixel_value>',
     $     '<maximum_pixel_value>',I12,'</maximum_pixel_value>',
     $     '<null_pixel_value>',I9,
     $     '</null_pixel_value>',
     $     '<maximum_peak_ratio>',F8.1,
     $     '</maximum_peak_ratio>',
     $     '<maximum_background_ratio>',F8.1,
