C&&*&& include  ../inc/reeke.f
C
C $Id: reeke.f,v 1.17 2015/05/11 14:19:27 andrew Exp $
C
C--- awk generated include file  reeke.h
C---- START of include file reeke.h
C
C     TOR     For synchrotron sources, degree of polarisation of the beam
C     IMONO   Collimation flag for polarisation.
C             = 0   Pinhole or mirrors
C             = 1   Graphite Monochromator
C             = 2   Synchrotron, use TOR
C     NWMAX   Maximum reflection width in images
C     DSTMAX  dimensionless rlu, = WAVE/RES where RES is the maximum
C             resolution in Angstrom.
C     DSTMIN  dimensionless rlu, = WAVE/DMAX where DMAX is the maximum
C              Bragg spacing
C     S0      radiation source vector (-1,0,0), may be modified by MU values
C     SOURCE  radiation source vector - basis for s0
C     GONIO_angle:  machine angles for generalized goniostats
C     GONIO_angle_SET: fixed offset angles for 3- and 4-circle goniostats
C                      i.e. currently 54.74 deg for Bruker CHI, 50.0deg for
C                      Nonius and Oxford KAPPA 
C     VERTICAL Logical set TRUE if rotation axis is vertical, only
C              affects polarization correction for synchrotron data
C     NSMOOTH  Number of images to use in smoothing refined values of
C              mosaic spread and missetting angles (if being smoothed).
C     ..
C     .. Arrays in common block /REEKE/ ..
      REAL RMC,AMAT,SCAXIS,S0,s0unit,CAMCON,BEAMMU
C     ..
C     .. Scalars in common block /REEKE/ ..
      REAL X1,X2,Y1,Y2,Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,
     +     DIVH,DIVV,DELAMB,ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,
     +     ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,
     +     BLKSIZE
      INTEGER ISYN,IMONO,NWMAX,IPAD,NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS
C     ..
C     .. logicals in common block /REEKE/ ..
      LOGICAL LOGETA,NUREEK,LCAMCON,GENGON,FOURCIRCLE,THREECIRCLE,
     +        VERTICAL
C     ..
C     .. Common Block /REEKE/ ..
      COMMON /REEKE/RMC(3,3),AMAT(3,3),SCAXIS(3),S0(3),s0unit(3),
     $     CAMCON(8),BEAMMU(2),X1,X2,Y1,Y2,
     +     Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,DIVH,DIVV,DELAMB,
     +     ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,ISYN,IMONO,
     $     NWMAX,IPAD,
     $     NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS,LOGETA,NUREEK,LCAMCON,
     $     GENGON,FOURCIRCLE,THREECIRCLE,
     +     BLKSIZE,VERTICAL
C     ..
C
C
C&&*&& end_include  ../inc/reeke.f
C&&*&& include  ../inc/reflist.f
C
C $Id: reflist.f,v 1.1 2002/05/02 10:47:12 harry Exp $
C
C--- awk generated include file  reflist.h
C---- START of include file reflist.h
C
C
C     .. Arrays in common block /REFLIST/ ..
      INTEGER XREF,YREF,INTREF,ISDREF
C     ..
C     .. Common Block /REFLIST/ ..
      COMMON /REFLIST/XREF(NREFLS),YREF(NREFLS),INTREF(NREFLS),
     +       ISDREF(NREFLS)
C     ..
C
C
C&&*&& end_include  ../inc/reflist.f
C&&*&& include  ../inc/rfs.f
C
C $Id: rfs.f,v 1.2 2007/07/12 13:25:57 andrew Exp $
C
C--- awk generated include file  rfs.h
C---- START of include file rfs.h
C
C
C
C     .. Scalars in common block /RFS/ ..
      REAL FDIST,ESTART,RMSRES,WRMSRES,WESTART
      INTEGER MAXREF,MAXX,MAXY,NRS,MAXR,NREJS,NCENTREF
C     ..
C     .. Arrays in common block /RFS/ ..
      REAL XRS,YRS,WXRS,WYRS
      INTEGER RRS,IHKLR
C     ..
C     .. Common Block /RFS/ ..
      COMMON /RFS/ XRS(NDETREF),YRS(NDETREF),WXRS(NDETREF),
     +       WYRS(NDETREF),FDIST,ESTART,RMSRES,WRMSRES,
     $       WESTART,RRS(NDETREF),IHKLR(3,NDETREF),MAXREF,MAXX,
     +       MAXY,NRS,MAXR,NREJS,NCENTREF
C     ..
C
C
C&&*&& end_include  ../inc/rfs.f
C&&*&& include  ../inc/saveit.f
C
C $Id: saveit.f,v 1.1 2002/05/02 10:47:16 harry Exp $
C
C--- awk generated include file  saveit.h
C---- START of include file saveit.h
C
C
C     .. Scalars in common block /SAVEIT/ ..
      REAL SETA,SDIVH,SDIVV
C     ..
C     .. Arrays in common block /SAVEIT/ ..
      REAL SDELPHI
C     .. Common Block /SAVEIT/ ..
      COMMON /SAVEIT/SDELPHI(3),SETA,SDIVH,SDIVV
C     ..
C
C
C&&*&& end_include  ../inc/saveit.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C     ..
C     .. Equivalences ..
      EQUIVALENCE (IRAS(1),NXS), (IRAS(2),NYS), (IRAS(3),NC)
      EQUIVALENCE (IRAS(4),NRX), (IRAS(5),NRY)
C     ..
      SAVE
C     .. Data statements ..
      DATA PSISTR/'PSIX','PSIY','PSIZ','DIV ','DIVH','DIVV'/
      DATA AWELIMIT/2.0/
C     ..
C     
C     
      IERR = 0
      IDDUM = 0
      DPOWDER = .FALSE.
      LPOSTREF = .FALSE.
      LLAST = .FALSE.
      MATCH = .TRUE.
      FAIL = .FALSE.
      FORCE = .FALSE.
      LIST = .FALSE.
      PRECESS = .FALSE.
      LPROFILE = .FALSE.
      INTERPOL = .FALSE.
      RESCAN = .TRUE.
      LMULTISEG = .FALSE.
      INTCHK = .FALSE.
C     
C---- initialize for mosaicity estimation
C     
      IF(MOSEST)THEN
        ETAMAX = 1.0
        IETAMAX = 1
        DELETA = 0.05
        SLOPEFAC = 0.1
      ENDIF
C     
C     
C---- Convert phi to psi
C     
      PHIAV = (PHIBEG+PHIEND)*0.5 + DELPHI(3)
C     
C     **************************
      CALL PHITOPSI(DELPHI,PSI,PHIAV)
C     **************************
C     
C---- Save these psi and starting delphi values
C     
      DO 10 ITMP = 1,3
        XDELPHI(ITMP) = DELPHI(ITMP)
        SDELPHI(ITMP) = DELPHI(ITMP)
        SPSI(ITMP) = PSI(ITMP)
 10   ENDDO
C     
C     
      SETA = ETA
C     
C     
      IF (DEBUG(30)) THEN
        IF (ONLINE) WRITE (ITOUT,FMT=6000) DELPHI,PSI,PHIAV,2*ETA/DTOR,
     +       2*DIVH/DTOR,2*DIVV/DTOR
 6000   FORMAT ('  Entering ESTIMATE',/1X,'DELPHI ',3F6.2,5X,'DELPSI ',
     +       3F6.2,5X,'PHIAV ',F6.2,' ETA ',F6.3,' DIVH,V ',2F6.3)
        WRITE (IOUT,FMT=6000) DELPHI,PSI,PHIAV,2*ETA/DTOR,
     +       2*DIVH/DTOR,2*DIVV/DTOR
      END IF
C     
C---- Do initial call to set up standard profiles and to RMAXR to
C     calculate box sizes, as these are needed by NEXT. For IP data,
C     only need to do this once, but for film data the position of
C     the direct beam in the digitised image can vary from one
C     pack to the next, so need to set it up for every pack.
C     (Same will be true for IP data from an offline scanner)
C     Here it is assumed that NUMBLOCK is 1 and it is not included
C     in the test along with FIRSTFILM, this is safe as
C     the mosaicity is never estimated during an integration run.
C     
      IF (.NOT.IMGP) THEN
        CALL PRSETUP
        IERR = 0
C     ***********************
        IF (FIRSTFILM) CALL RMAXR(LIMIT,THICK,IERR)
C     ***********************
      ELSE
        IF (FIRSTFILM) THEN
          CALL PRSETUP
          CALL RMAXR(LIMIT,THICK,IERR)
        END IF
      END IF
C     .. 
C     Go through this block again if we are repeating the refinement
C     for the beam divergence.
C     
      REPEST = .TRUE.
      DO 220 WHILE (REPEST)
C     
C---- If refining divergences, set appropriate ETANEW and IFLAG
C     If not refining orientation, start with divergence refinement
C     
        ETANEW = ETAMAX
        IFLAG = 4
C     
C---- Must set ETA to zero, so that total (beam divergence + mosaic
C     spread)
C     increases from zero
C     
        ETA = 0.0
C     
C     ************************************
 20     CALL NEWLIST(ETANEW,PSI,PHIAV,RESOL1,IFLAG,IERR)
C     ************************************
C     
        IF (DEBUG(31)) THEN
          NPR = MIN(NSPOT,30)
          IF (ONLINE) WRITE (ITOUT,FMT=6120) (ITMP,XG(ITMP),YG(ITMP),
     $         ITMP=1,NPR)
 6120     FORMAT (/,' Coordinates of reflections from REEKE',
     +         / (1X,I3,3X,2F7.1))
          WRITE (IOUT,FMT=6120) (ITMP,XG(ITMP),YG(ITMP),ITMP=1,NPR)
        END IF
C     
C---- Measure intensities of all reflections in the big list
C     first convert film coordinates to sorted scanner coordinates
C     
        MAXR = 1000
        MODE = 6
C     
C     *****************************************************
        CALL GENSORT(MODE,FORCE,LIMIT,VLIM,NRM,ADDPART,LPTMIN,LLAST)
C     *****************************************************
C     
        NBIG = NRM
        WRITE (IOUT,FMT=6130) SHPSI(1),TRUECCOM
 6130   FORMAT ('  PSIX changed by',F6.2,
     $       ' Degrees and CCOMEGA set to',F6.3)
        IF (ONLINE) WRITE (ITOUT,FMT=6130) SHPSI(1),TRUECCOM
C     
C     
        IF (DEBUG(30)) THEN
          IF (ONLINE) WRITE (ITOUT,FMT=6140) NSPOT,ETANEW,RESOL1,NRM
 6140     FORMAT (/1X,I5,' Spots generated in big list with ETA=',
     &         F5.2,' Out to',F5.1,' Angstroms',/1X,I5
     &         ,' of these selected by GENSORT')
          WRITE (IOUT,FMT=6140) NSPOT,ETANEW,RESOL1,NRM
        END IF
C
C---- For small unit cells, must use a larger mosaic spread increment to get a reasonable
C     number of reflections gained at each step. Mosaic spread increment is simply etamax
C     (set to 1.0) divided by 20. For 20 steps and 5 reflections per step, 
C     need at least 100 reflections. Increase etamax by linear scaling.
C     
        if (nspot.lt.100) then
          etanew = etanew*100.0/float(nspot)
          etamax = etanew
          goto 20
        end if
C     
C---- Now measure reflections
C     
C     *******************************************************
        IERR = 0
        CALL MEAS(MAXR,LPROFILE,INTERPOL,IXSHIFT,IYSHIFT,ADDPART,
     +       LPOSTREF,IDDUM,LMULTISEG,LASTREC,NEWPREF,NUSPOT,IERR)
C     *******************************************************
C     
        IF (DEBUG(31)) THEN
          NPR = MIN(NRM,30)
          IF (ONLINE) WRITE (ITOUT,FMT=6150) (ITMP,XREF(ITMP),
     $         YREF(ITMP),ITMP=1,NPR)
 6150     FORMAT (/,' Coordinates after storing in XREF,YREF',
     +         / (1X,I3,3X,2I6))
          WRITE (IOUT,FMT=6150) (ITMP,XREF(ITMP),YREF(ITMP),ITMP=1,NPR)
        END IF
C     
C---- Now the fun bit.
C     If refining mosaic spread, then increase divergence(s) from 0
C     to ETAMAX in (2*NSTEP+1) steps
C     
        ETANEW = 0.0
C     
C---- Set error limits for matching reflections to half box size
C     
C     
C---- Set number of passes to number of parameters being refined
C     
        IDELX = (IRAS(1)-2*IRAS(4))*0.5 + 1
        IDELY = (IRAS(2)-2*IRAS(5))*0.5 + 1
        DELETA = ETAMAX/(2*NSTEP)
C     
        DO 120 ITMP = 2,3
          SHPSI(ITMP) = 0.0
 120    ENDDO
        WRITE (IOUT,FMT=6160)
 6160   FORMAT (/1X,'Beam divergence refinement for ',
     $       'mosaicity estimation') 
        IF (ONLINE) WRITE (ITOUT,FMT=6160)
C     
C     
C     
C---- Only one parameter (IYZ) if only one beam divergence being refined
C     
        IYZ = 3
        INTMAX = 0
        JSTEP = 0
        ETANEW = -DELETA
C     
C     
        DO 140 ISTEP = -NSTEP,NSTEP
          JSTEP = JSTEP + 1
C     
C---- Divergence refinement
C     
          ETANEW = ETANEW + DELETA
          ETASTEP(JSTEP) = ETANEW
          IF(BLKEST)THEN
            BLKSIZE = 10000.0 * EXP ((FLOAT(ISTEP)/3.0) + 1.15)
            CALL NEWLIST(SETA,PSI,PHIAV,RESOL1,IFLAG,IERR)
          ELSE
C     
C     **************************************
            CALL NEWLIST(ETANEW,PSI,PHIAV,RESOL1,IFLAG,IERR)
C     **************************************
          ENDIF
C     
C     
C---- Match reflections in small list to those in big list
C     
C     ****************************************************
          CALL REFLMATCH(ITMP,FVAR,NBIG,NSPOT,NM,IDELX,IDELY
     $         ,FORCE,LIMIT,VLIM,JSTEP,INTGAIN,ISDGAIN,
     $         INTLOST,ISDLOST,NGAIN,NLOST,ADDPART,LPTMIN,
     $         IERR2)
C     ****************************************************
C---- Check if error return due to too many spots lost/gained, change
C     resolution limit and do it again from automatch, but only three
C     times. 
C     
          IF((IERR2.GE.1000).AND.(IERR2.LE.1002))THEN
            IERR = IERR2
            RETURN
          ENDIF
          NGL(ISTEP) = NGAIN + NLOST
          IGN(ISTEP) = INTGAIN
          ISDGN(ISTEP) = ISDGAIN
          ILO(ISTEP) = INTLOST
          ISDLO(ISTEP) = ISDLOST
          INTTOT(ISTEP,IYZ) = ITMP/100
          ISDTOT(ISTEP,IYZ) = SQRT(0.0001*FVAR)
          MEANINT = 0
          IF (NM.NE.0) MEANINT = ITMP/NM
C     
C     
          IF(SOCKLO)THEN
            WRITE(IOLINE,FMT=7000)
     $           ETASTEP(JSTEP),INTTOT(ISTEP,IYZ)
            CALL WRITE_SOCKET_LENGTH
     $           (SERVERFD,LENSTR(IOLINE),IOLINE)
 7000       FORMAT('<?xml version="1.0"?>',
     $           '<!DOCTYPE mosaicity_estimation_response>',
     $           '<mosaicity_estimation_response>',
     $           '<mosaicity_trial_value>',F5.2,
     $           '</mosaicity_trial_value>',
     $           '<total_intensity>',I8,
     $           '</total_intensity>',
     $           '</mosaicity_estimation_response>')
          ENDIF
          IF (DEBUG(30)) THEN
            IF (ONLINE) WRITE (ITOUT,FMT=6180) IYZ,ISTEP,PSI,
     $           NSPOT,RESOL1,NM,IDELX,IDELY,ITMP,MEANINT
 6180       FORMAT (1X,'VARY PSI',I2,' ISTEP',I3,/,1X,'PSI',
     &           3F8.2,' NSPOT',I5,' RESOL1',F5.1,' NMATCH',I5
     $           ,' DX,DY',2I5,/1X,'Total intensity',I12
     $           ,' Mean intensity per spot',I8)
            WRITE (IOUT,FMT=6180) IYZ,ISTEP,PSI,NSPOT,RESOL1
     $           ,NM,IDELX,IDELY,ITMP,MEANINT
          END IF
C     
C     
          IF (ITMP.GE.INTMAX)THEN
            INTMAX = ITMP
            IS = ISTEP
          ENDIF
 140    ENDDO
C     
C---- Scale INTTOT if necessary
C     
        SCALE = 1.0
        IF(INTMAX.NE.0)SCALE = 9999900/REAL(INTMAX)
C     
C---- Next bit for mosaicity estimation only 
C     
        IF(MOSEST)THEN
C     
C---- Work out gradient in a moving window of 5 points
C     
          DO 174 ISTART = 1,2*NSTEP-3       
C     
C---- work out slope etc here
C     
            SIGX = 0.0
            SIGY = 0.0
            SIGXY = 0.0
            SIGX2 = 0.0
C     
C---- average slope over the five points
C     
            DO 170 ISTEP = ISTART, ISTART+4
              SIGX = SIGX + ETASTEP(ISTEP)
              SIGY = SIGY + 
     +             NINT(SCALE*INTTOT(ISTEP-1-NSTEP,IYZ))
              SIGXY = SIGXY + (ETASTEP(ISTEP)*
     $             NINT(SCALE*INTTOT(ISTEP-1-NSTEP,IYZ)))
              SIGX2 = SIGX2 + (ETASTEP(ISTEP)*ETASTEP(ISTEP))
 170        ENDDO
            SLOPEA(ISTART) = MAX(0.0,((SIGX*SIGY)-(5*SIGXY))/
     $           ((SIGX*SIGX)-(5*SIGX2)))
 174      ENDDO
C     
C---- Now set mosaicity to value where the slope has dropped to one tenth
C     of the initial slope
C     
          SLOPE = SLOPEFAC*SLOPEA(1)
          KK = 1
          MOSNEW = 999
          DO 176 WHILE ( KK .LE.2*NSTEP-3.AND.MOSNEW.GT.100)
            IF (SLOPEA(KK).LT.SLOPE) THEN
              MOSNEW = ETASTEP(KK)
            END IF
            KK = KK + 1
 176      ENDDO
C
C---- MOSNEW not set above
C
          IF (MOSNEW.GT.100) THEN
            MOSNEW = ETASTEP(2*NSTEP+1)
C     
C---- Now set slope to slope for end of the graph, as this value
C     is used for various checks in ESTMOS
C     
            SLOPE = SLOPEA(2*NSTEP-3)
C     
C----  end of slope calculations
C     
C     
C----  Set a minimum intensity to be 1/8th of the intensity for
C     mosaicity = 0 plus 7/8ths of the maximum intensity
C     
            INTMIN = NINT((SCALE*INTTOT(-NSTEP,IYZ)/8.0)+
     $           (700000.0/8.0))
          ENDIF
          IF (DEBUG(30)) THEN
            WRITE(IOUT,FMT=6204) INTMIN, MOSNEW,SLOPEFAC,
     +           0.001*SLOPEFAC*SLOPEA(1),IETAMAX,
     +           (0.001*SLOPEA(KK),KK=1,20) 
            IF (ONLINE) WRITE(ITOUT,FMT=6204) INTMIN,
     +           MOSNEW,SLOPEFAC,0.001*SLOPEFAC*SLOPEA(1),
     +           IETAMAX,(0.001*SLOPEA(KK),KK=1,20)  
 6204       FORMAT(/,1X,'INTMIN',I8,' estimated mosaic',F9.4,
     +           ' slopefac',F6.2,' slope wanted',F6.1,
     +           ' IETAMAX',I3,'  SLOPE values',/,1X,20F6.1)
          END IF
        ENDIF
C     
C---- if the mosaicity is largish, we need to expand the range that we
C     test.
C     Only do this up to 4 degrees!
C     
        IF(ONLINE)THEN
          WRITE (ITOUT,FMT=6210) PSISTR(IFLAG),DELETA
          WRITE(ITOUT,FMT=6230) (ETASTEP(JSTEP),
     +         JSTEP=1,2*NSTEP+1)
          WRITE(ITOUT,FMT=6250) (NGL(ISTEP),ISTEP = -NSTEP
     $         ,NSTEP)
          WRITE(ITOUT,FMT=6260)  
     $         (NINT(SCALE*INTTOT(ISTEP,IYZ))
     $         ,ISTEP = -NSTEP,NSTEP)
          WRITE(ITOUT,FMT=6270)  
     $         (NINT(SCALE*ISDTOT(ISTEP,IYZ)),
     +         ISTEP = -NSTEP,NSTEP)
          write(itout,fmt=6275)scale
          
        ENDIF
        WRITE (IOUT,FMT=6210) PSISTR(IFLAG),DELETA
        WRITE(IOUT,FMT=6230) (ETASTEP(JSTEP),
     +       JSTEP=1,2*NSTEP+1)
        WRITE(IOUT,FMT=6250) (NGL(ISTEP),ISTEP = -NSTEP
     $       ,NSTEP)
        WRITE(IOUT,FMT=6260) (NINT(SCALE*INTTOT(ISTEP,IYZ))
     $       ,ISTEP = -NSTEP,NSTEP)
        WRITE(IOUT,FMT=6270) (NINT(SCALE*ISDTOT(ISTEP,IYZ)),
     +       ISTEP = -NSTEP,NSTEP)
        write(iout,fmt=6275)scale
 6210   FORMAT (/,' Refining ',A,' with stepsize',F6.2
     $       ,' Degrees')
 6220   FORMAT(1X,'Step number    ',19I6)
 6230   FORMAT(1X,'Divergence     ',19F6.3)
 6240   FORMAT(1X,'No gained/lost ',19I6)
 6250   FORMAT(1X,'No gained      ',19I6)
 6260   FORMAT(1X,'Total intensity',19I6)
 6270   FORMAT(1X,'SD of intensity',19I6)
 6275   FORMAT(1X,'Intensities scaled by ',F12.3)

        IF(MOSNEW.GT.0.9*ETAMAX.AND.MOSEST.AND.
     $       IETAMAX.LE.4)THEN
C     
C---- we want to cycle around again
C     
          ETAMAX = ETAMAX*2.0
          IETAMAX = IETAMAX * 2
          DELETA = DELETA*2.0
          INTCHK = .FALSE. 
          REPEST = .TRUE.
        ELSE
C     
C---- Want to avoid failure if we can, change the slope criterion, 
C     but not > 1
C     
          SLOPEFAC = SLOPEFAC*2.0
C     
C---- Finished...
C     
          IF(IETAMAX.GT.4)THEN
            ETAMAX = 1.0
            IETAMAX = 1
            DELETA = 0.05
            INTCHK = .FALSE. 
            REPEST = SLOPEFAC.LT.1
            MOSEST = SLOPEFAC.LT.1
            IF(.NOT.MOSEST)MOSNEW = 999.0
C     
C---- IETAMAX too big, so we say that it's failed
          ELSE
            MOSEST = .FALSE.
            REPEST = .FALSE.
          ENDIF
C     
C---- must set INTCHK anyway
C     
          INTCHK = .TRUE.
        ENDIF
        IF(DEBUG(30))THEN
          WRITE(IOUT,FMT=6280)(ETASTEP(ISTEP+NSTEP+1),
     +         NINT(SCALE*INTTOT(ISTEP,IYZ)), 
     +         ISTEP = -NSTEP,NSTEP)
 6280     FORMAT(F8.3,1X,I6)
        ENDIF
C     
C     
 6290   FORMAT (/,' Optimum step number is ',I3
     $       ,' Median shift',F5.1,/1X,A,' Old value ',
     $       F7.2,' New value ',F7.2,'  SHIFT',F6.2)
C     
C     
C---- End of loop over divergences
C     
 220  ENDDO
C     
C---- End of loop over passes
C     
C     
C---- reset resolution and mosaic spread and return
C     
      ETA = SETA
      DSTMAX = DSTMAXS
      RETURN
      END
C     
C---- $Id: estmos.f,v 1.47 2021/02/11 11:34:07 andrew Exp $
C     
      SUBROUTINE ESTMOS(MOSIMAG,IPACK_LOCAL,GENOPEN,IERR)
      IMPLICIT NONE
C     
C---- integer arguments
C     
      INTEGER MOSIMAG,IPACK_LOCAL,IERR
      LOGICAL GENOPEN
C     
C---- Estimates mosaicity based on current crystal and detector 
C     parameters, using code in AUTOMATCH.
C     
C---- include files
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C&&*&& include  ../inc/amatch.f
C
C $Id: amatch.f,v 1.2 2014/05/30 15:47:41 andrew Exp $
C
C--- awk generated include file  amatch.h
C---- START of include file amatch.h
C
C
C     .. Scalars in Common /AMATCH/ ..
C     ..
      REAL RCONV,OVRLAP,RESOL1,RESOL2,AELIMIT,ARMSLIM,
     +     SECANGLE,DAMP,TRUECCOM,ETAMAX,AWRMSLIM,MOSNEW,
     $     SLOPE,INTERCEPT
      INTEGER NSTEP,NCYCA,NPASS,N2,N3,N4,N5,N6,N7,N8,N9,N10,NBEAM,
     +        MINREFAUTO
      LOGICAL MATCH,NOCENT,NOREFINE,RMOSAIC
C     ..
C     .. Common block /AMATCH/  ..
      COMMON /AMATCH/RCONV,OVRLAP,RESOL1,RESOL2,AELIMIT,ARMSLIM,
     +     SECANGLE,DAMP,TRUECCOM,ETAMAX,AWRMSLIM,MOSNEW,
     $     SLOPE,INTERCEPT,NSTEP,NCYCA,NPASS,N2,N3,N4,N5,N6,N7,
     $     N8,N9,N10,NBEAM,MATCH,NOCENT,NOREFINE,RMOSAIC,
     +     MINREFAUTO
C     ..
C
C
