C
C $Id: lmb.f,v 1.17 2021/03/30 09:16:05 andrew Exp $
C
C--- awk generated include file  lmb.h
C---- START of include file lmb.h
C ODSCAL is to scale image numbers into the range 0-255 for plotting
C average profiles.
C  GAIN should be equal to the overall gain (image counts per X-ray photon)
C of the system, and is used to evaluate standard deviations based on
C counting statistics assuming independent pixels (ie point spread function
C less than pixel size).
C INVERTX true if image is inverted in the slow (X) direction when read in.
C ISCAL is to scale final integrated intensities and sigmas
C IDIVIDE is the adc offset
C ICONST is a constant to be added to all pixels (normally zero) to
C        allow processing of images with zero pixel values in the scanned
C        area.
C IMGP is true if working with image plate data
C SPIRAL is true for scanners with a spiral readout (Mar, DIP2000)
C ORTHOG is true for scanners with orthogonal scan (FUJI, RAXIS, MD)
C NULLPIX is the value of pixels within the image but not in the active
C area of the detector
C TILED is true if there are inactive areas of the detector within the
C       inscribing circle or square.
C
C NTILEX Number of tiles in X direction
C NTILEY Number of tiles in Y direction
C TILEX  X Coordinates of the midpoints of the null areas between tiles
C TILEY  Y Coordinates of the midpoints of the null areas between tiles
C TILEWX Width of the null areas between tiles in X
C TILEWY Width of the null areas between tiles in Y


C MACHINE and MODEL denote the type of detector.
C DECTRIS_TYPE can be PILATUS, EIGER1 or EIGER2. It is used when setting up
C the positions of the gaps between the tiles.
C
C MACHINE is used in the following subroutines:
C GETBLK, GETHDR, INTPXL, INTPXL2, MXDSPL, OPENODS, PROCESS, PUTPXL
C Currently coded types are:
C
C         MACHINE        MODEL               COMMENTS
C         =======        =====               ========
C         MAR            180, 300, 345
C         RAXI(S)        RAXISII, RAXISIV
C         MD
C         FUJI
C         CCD1           CCD1                Princetown CCD at CHESS,Tiff format
C         CCD2           CCD ?               ESRF CCD detector
C         ADSC           QUAD1               ADSC 2x2 CCD detector
C
C TRUSTED whether or not the image header information can be trusted for 
C         automatic processing
C MICROED indicates whether or not this is electron diffraction data,
C        base on the wavelength being less than 0.05A
C
C
C     .. Scalars in Common Block /LMB/ ..
        REAL ODSCAL,GAIN,LOGA,LOGB
        INTEGER ISCAL,IDIVIDE,ICONST,NULLPIX,NTILEX,NTILEY,
     $       RAXISCOMP,IIDIVIDE,COMPRESSION,GAPVAL,IINVERTX
        LOGICAL IMGP,INVERTX,SPIRAL,ORTHOG,CIRCULAR,TILED,SETADC,
     $       NEWRAXIS,BRUKNEW,TRUSTED,MINICBF,HDF5FILE,GAPMASK,
     $       WRONGGAPVALUE,MICROED
        CHARACTER MACHINE*4,MODEL*8,LDETECTOR*20,DECTRIS_TYPE*10,
     +       CMACHINE*40

C     ..
C     .. Arrays in common /LMB/
        INTEGER TILEX,TILEY,TILEWX,TILEWY
C
C     .. Common Block /LMB/ ..
        COMMON /LMB/ ODSCAL,GAIN,LOGA,LOGB,ISCAL,IDIVIDE,ICONST,
     $       NULLPIX,NTILEX,NTILEY,RAXISCOMP,IIDIVIDE,COMPRESSION,
     $       GAPVAL,IINVERTX,TILEX(20),TILEY(20),TILEWX(20),TILEWY(20),
     $       IMGP,INVERTX,SPIRAL,ORTHOG,CIRCULAR,
     $       TILED,SETADC,NEWRAXIS,BRUKNEW,TRUSTED,MINICBF,HDF5FILE,
     $       GAPMASK,WRONGGAPVALUE,MICROED
        COMMON /LMBC/ MACHINE,MODEL,LDETECTOR,DECTRIS_TYPE,CMACHINE

C&&*&& end_include  ../inc/lmb.f
C&&*&& include  ../inc/sums.f
C
C $Id: sums.f,v 1.1 2002/05/02 10:47:21 harry Exp $
C
C--- awk generated include file  sums.h
C---- START of include file sums.h
C
C
C     Elements of ASPOT
C     1 = Summation integration intensity
C     2 = Total background counts under peak assuming peak has mm symmetry
C     3 = Rms variation in background, after rejecting background points.
C         This is evaluated in BGSOLVE called from EVAL.
C     4 = Centre of gravity in X direction (in pixels)
C     5 = Centre of gravity in Y direction (in pixels)
C         These are wrt an origin at the centre of the measurement box
C     6 = sum p*iod for background pixels
C     7 = sum q*iod for background pixels
C     8 = sum iod for background pixels
C     9 = Background plane constant a (gradient in X direction)
C    10 = Background plane constant b (gradient in Y direction)
C    11 = Background plane constant c 
C    12 = Largest deviation from background plane, excluding rejected pixels
C    13 = Profile fitted intensity
C    14 = Variance of profile fitted intensity = sum (deltasq) for peak
C         pixels only. Used to calculate PKRATIO and also profile fitted
C         sigma(I) in unweighted case only.
C    15 = Number of rejected background pixels
C    16 = Variance of profile fitted intensity in weighted case (default)
C    17 = sum W*DELTA**2 for profile fit
C    18   unused
C     .. Arrays in common block /SUMS/ ..
      REAL ASPOT
C     ..
C     .. Common Block /SUMS/ ..
      COMMON /SUMS/ASPOT(18)
C     ..
C
C
C&&*&& end_include  ../inc/sums.f
      COMMON /XYSCAN/ IX,IY
C     ..
C     ..
C     .. Equivalences ..
      EQUIVALENCE (ASPOT(3),RMSBG)
      EQUIVALENCE (ASPOT(6),SPOD)
      EQUIVALENCE (ASPOT(7),SQOD), (ASPOT(8),SOD), (ASPOT(9),A)
      EQUIVALENCE (ASPOT(10),B), (ASPOT(11),C), (ASPOT(12),BGDEVMAX)
C
C     .. Data statements ..               
      DATA NDBG/0/
C
C---- EDGESPOT is true for a spot containing pixels with values LE NULLPIX
C
      EDGESPOT = .FALSE.
      MASKREJP(1) = 0
      LMASKREJP(1) = 0
      BGFRACL = BGFRAC
C
C  To avoid problems with adjacent spots entering background, determine
C  the background as the average of the NBKG lowest pixel values
C  but excluding those with values equal to or below NULLPIX (inactive
C  regions of the detector)
C
      NXX = IRAS(1)
      NYY = IRAS(2)
      NXY = NXX*NYY
      HX = NXX/2
      HY = NYY/2
      NBKG = NINT(PQSUMS(6))
C
C  Sort pixels into increasing order of pixel value
C
      CALL SORTUP4(NXY,OD,IS)
      IF (DEBUG(33).AND.CDEBUG.AND.(NDBG.LT.NDEBUG(33))) THEN
        WRITE(IOUT,FMT=6050) MODE,NBKG,(OD(IS(I)),I=1,NXY)
        IF (ONLINE) WRITE(ITOUT,FMT=6050)MODE,NBKG,(OD(IS(I)),I=1,NXY)
 6050   FORMAT(/,1X,'*** In EVAL ***',/,1X,'MODE=',I1,' NBKG:',I4,
     +         '  Sorted OD values (10 per line)',/,(1x,10I8))
      END IF
C
C---- Loop over bins to find mean background level
C
 4    N = 0
      NNUL = 0
C
C----  Choose a fraction BGFRAC of total number of background points
C
      NBKGP = NBKG*BGFRACL
CAL      IF (DEBUG(33)) THEN
CAL        WRITE(IOUT,FMT=6051) NBKG, BGFRACL, NBKGP
CAL        IF (ONLINE) WRITE(ITOUT,FMT=6051) NBKG, BGFRACL, NBKGP
CAL 6051   FORMAT(1X,'NBKG=',I5,' BGFRACL=',F4.2,' NBKGP=',I5)
CAL      END IF
C
C---- Normally exclude pixels outside scanned area (.le.NULLPIX) but
C     for averaged standard profiles (flagged by negative BGSIG)
C     allow negative values
C
      IODMIN = NULLPIX
      IF (BGSIG.LT.0) IODMIN = -999999
      DO 10 I = 1,NXY
        IOD = OD(IS(I))
        IF (MODE.EQ.0) THEN
          OKPIX = .TRUE.
        ELSE
          OKPIX = (MASK(IS(I)).LT.0)
        END IF
C
C---- Decrement number of pixels to be used to allow for inactive
C     pixels but only if this pixel would have been used. NNUL counts
C     number of flagged (inactive) pixels
C
        IF ((IOD.LE.IODMIN).AND.OKPIX) THEN
          NNUL = NNUL + 1
          NBKGP = NBKGP - 1
          EDGESPOT = .TRUE.
          IF (DEBUG(33).AND.CDEBUG.AND.(NDBG.LT.NDEBUG(33))) THEN
            WRITE(IOUT,FMT=6052) NBKGP
            IF (ONLINE) WRITE(ITOUT,FMT=6052)  NBKGP
 6052       FORMAT(1X,'NBGKP decreased, now:',I5)
          END IF
        END IF
C
C---- Check for pixel outside scanned area
C
        IF ((IOD.GT.IODMIN).AND.OKPIX) THEN
          N = N + 1
          IF (N.GT.NBKGP) GOTO 12
          IPNT = I
        END IF
   10 CONTINUE
      N = N + 1
C
 12   NBKGP = N - 1


C
C---- Set cutoff level for determination of plane fitting the lowest
C     (non-zero) pixels
C
      IF ((IPNT.LT.1).or.(ipnt.gt.nxy)) THEN
         WRITE(IOUT,FMT=4444) iodmin,nxy,nbkg,nint(NBKG*BGFRACL),
     +              nbkgp,n,ipnt
         IF (ONLINE) WRITE(ITOUT,FMT=4444) iodmin,nxy,nbkg,
     +              nint(NBKG*BGFRACL),nbkgp,n,ipnt
 4444    FORMAT(1X,'***** BAD BACKGROUND IPNT RESET ****',/,1X,
     +     'iodmin',I8,' nxy',I5,'  nbgk',I5,' bgfrac*nbgk',I6,
     +      ' nbkgp',I5,'  n',I5,' ipnt',I12)
         IPNT = 0.5*NBKG*BGFRACL
      END IF
      IBGCUT = OD(IS(IPNT))
C
C---- Calculate the median background value and its error. Must allow for presence
C     of NNUL pixels outside scanned area.
C
      IBGMED = MAX(1,OD(IS(NNUL+NBKGP/2)))
      IBGMEDSIG = MAX(1,NINT(SQRT(GAIN*IBGMED)))

      IF (DEBUG(33).AND.CDEBUG.AND.(NDBG.LT.NDEBUG(33))) THEN
        WRITE(IOUT,FMT=6054) NBKGP,IPNT,IBGCUT,IBGMED,IBGMEDSIG
        IF (ONLINE) WRITE(ITOUT,FMT=6054) NBKGP,IPNT,IBGCUT,
     +              IBGMED,IBGMEDSIG
 6054   FORMAT(1X,'Final value for NBKGP:',I5,'  IPNT=',I4,
     +              '  IBGCUT:',I7, '  Median background=',I5,
     +              ' with uncertainty',I5)
      END IF


C
C---- Now deal with special cases where the background is extremely low
C     and where MODE=0 so the whole measurement box has been used to
C     find the lowest pixel values. In such cases it is possible
C     to get IBGCUT of zero even when there are non-zero counts
C     in the background region.
C
      IF (MODE.EQ.0) THEN
        IBACK = MAX(NINT(C),1)
        IF (IBACK.LT.2) IBGCUT = IBACK + NINT(SQRT(GAIN*IBACK))
        IF (DEBUG(33).AND.CDEBUG.AND.(NDBG.LT.NDEBUG(33))) THEN
          WRITE(IOUT,FMT=6055) IBGCUT
          IF (ONLINE) WRITE(ITOUT,FMT=6054) IBGCUT
 6055     FORMAT(1X,'IBGCUT adjusted to: ',I5)
        END IF
      END IF
C
C---- Loop over pixels, form sums for lowest pixels to determine
C     new background plane constants
      SP = 0.0
      SPP = 0.0
      SQ = 0.0
      SQQ = 0.0
      SPQ = 0.0
      SPODH = 0.0
      SQODH = 0.0
      SODH = 0.0
      N = 0
      IJ = 0
      MINP = 999
      MINQ = 999
      MAXP = -999
      MAXQ = -999
C
      DO 20 P = -HX,HX
C
C
        DO 30 Q = -HY,HY
          IJ = IJ + 1
C
C
          IOD = OD(IJ)
          IF (MODE.EQ.0) THEN
            OKPIX = .TRUE.
          ELSE
            OKPIX = (MASK(IJ).LT.0)
          END IF
C
C---- Again, exclude pixels outside scanned area
C
          IF ((IOD.GT.IODMIN).AND.(IOD.LE.IBGCUT).AND.OKPIX) THEN
              N = N + 1
              SPP = P*P + SPP
              SP = P + SP
              SQQ = Q*Q + SQQ
              SQ = Q + SQ
              SPQ = P*Q + SPQ
              SPODH = P*IOD + SPODH
              SQODH = Q*IOD + SQODH
              SODH = SODH + IOD
              MINP = MIN(MINP,P)
              MAXP = MAX(MAXP,P)
              MINQ = MIN(MINQ,Q)
              MAXQ = MAX(MAXQ,Q)
          END IF
   30   CONTINUE
   20 CONTINUE
      SPQOD(1) = SPODH
      SPQOD(2) = SQODH
      SPQOD(3) = SODH
      PQ(1,1) = SPP
      PQ(2,2) = SQQ
      PQ(3,3) = N
      PQ(1,2) = SPQ
      PQ(2,1) = SPQ
      PQ(1,3) = SP
      PQ(3,1) = SP
      PQ(2,3) = SQ
      PQ(3,2) = SQ
C
C
C          ***********************
      CALL MINV33(PQINV,PQ,DET)
      CALL MATVEC(ABC,PQINV,SPQOD)
C          ***********************
C
      AH = ABC(1)
      BH = ABC(2)
      CH = ABC(3)
C
C---- If background has not been determined over a range of at least
C     3 pixels in Y and Y, do not use AH,BH,CH.
C     This caused problems, set range to 1 so this never takes effect for the time being
C
      PRANGE = (MAXP-MINP)
      QRANGE = (MAXQ-MINQ)
      IF ((PRANGE.LE.1).OR.(QRANGE.LE.1)) THEN
        AH = A
        BH = B
        CH = C 
      END IF
      IF ((DEBUG(33).AND.CDEBUG).AND.(NDBG.LT.NDEBUG(33))) THEN
        WRITE(IOUT,FMT=6010) IRAS,PQSUMS,(ASPOT(I),I=6,12),BGFRACL,
     +                 NBKGP,BGSIG,AH,BH,CH,IBGCUT,N,IPNT,PRANGE,QRANGE
        IF (ONLINE) WRITE(ITOUT,FMT=6010)IRAS,PQSUMS,
     +                 (ASPOT(I),I=6,12),BGFRACL,
     +                 NBKGP,BGSIG,AH,BH,CH,IBGCUT,N,IPNT,PRANGE,QRANGE
 6010   FORMAT(/,1X,'IRAS',5I5,/,
     +        1X,'PQSUMS',6F12.1,/,1X,
     +        'ASPOT(6-12): sum p*iod(bg)',F8.1,' sum q*iod(bg)',F8.1,
     +      ' sum iod(bg)',F8.1,/,1X,'Background plane a',F7.2,
     +      ' b',F7.2,' c',F9.2,' bgdevmax',F8.2,/,1X,'BGFRACL',F5.2,
     +          '  NBKGP',I6,'  BGSIG',
     +         F8.1,/,1X,'New  background AH,BH,CH:',3F10.2,
     +         ' IBGCUT',I6,
     +         ' N',I5,' IPNT',I5,/,1X,'PRANGE,QRANGE',2I3)
        MAXPIX = 0
        IF (SPOT) CALL ODPLOT4(OD,NXX,NYY,1,MAXPIX)
      END IF
C
C---- If BGFRAC is equal to (or very close to) 1.0, as it is for Pilatus/Eiger
C     detectors by default, check that the calculated background plane constant is
C     not significantly different to the median background value, in order to detect
C     outliers due to ice, unflagged hot pixels or other sources.
      IF ((MODE.EQ.1).AND.(BGFRAC.GE.0.95)) THEN
        IF ((CH - IBGMED).GT.4.0*IBGMEDSIG) THEN
          BGFRACL = BGFRACL - 0.05
          IF (DEBUG(33)) THEN
            WRITE(IOUT,FMT=6012) BGFRACL,CH,IBGMED,IBGMEDSIG
            IF (ONLINE) WRITE(ITOUT,FMT=6012) BGFRACL,CH,IBGMED,
     +                  IBGMEDSIG
 6012       FORMAT(1X,'reduce BFRAC to ',F4.2,' as background plane',
     +          ' constant',' of',F6.0,' differs from median ',
     +         'background of',I6,' by more',' than 4.0 times sigma of',
     +          I5)
            IF ((IBGMED.LE.5).AND.(BGFRACL.GT.0.94))
     +                 CALL ODPLOT4(OD,NXX,NYY,1,MAXPIX)

          END IF
          IF (BGFRACL.GE.0.50) GOTO 4
        END IF
      END IF
C
C  Inflate CH by FAC*sigma(CH) to allow for underestimation caused by
C  choosing the lowest pixels. This assumes a normal distribution of
C  background counts, which should be adequate except for VERY low
C  backgrounds. Note that when dealing with averaged profiles (flagged by
C  negative BGSIG) the background has already been subtracted so we cannot
C  meaningfully apply this correction.
      IF (BGSIG.GT.0.0) THEN
        IF (BGFRACL.GE.0.999) THEN
          FAC = 0.0
        ELSE IF (BGFRACL.GE.0.9) THEN
          FAC = 0.05
        ELSE IF (BGFRACL.GT.0.7) THEN
          FAC = 0.2
        ELSE IF (BGFRACL.GT.0.5) THEN
          FAC = 0.4
        ELSE IF (BGFRACL.GT.0.3) THEN
          FAC = 0.6
        ELSE
          FAC = 0.8
        END IF
C
C---- sometimes CH may be negative if a "spot" is measured in a region
C     behind a backstop shadow etc - we should catch this condition and
C     print a warning, but otherwise allow the program to continue
C
        IF(CH.LT.0.0)THEN
          WRITE(IOUT,1342)CH
          IF(ONLINE)WRITE(IOUT,1342)CH
 1342     FORMAT(72('*'),/,3(' **** WARNING'),' ****',/,
     $         ' CH is negative: ',F12.3,/,72('*'))
          CH = ABS(CH)
        ENDIF
        CHDEL = FAC*SQRT(GAIN*CH)
      ELSE
        CHDEL = 0.0
      END IF
      CH = CH + CHDEL
C
C  Background rejection
C
C
C---- Calculate rms. background residual after plane fitting and
C     maximum deviation
C     Also calculate the rms deviation for the subset of points used
C     in determining the new background plane constants from the lowest
C     pixels. Use this rms deviation for rejecting outliers in the case
C     of averaged profiles, where we cannot use counting statistics.
      SD = 0.0
      SDH = 0.0
      DIFFMAX = 0.0
      DIFFMP = 0.0
      IJ = 0
      N = 0
C
C
      DO 60 P = -HX,HX
        APC = A*P + C
        APCH = AH*P + CH
C
C
        DO 50 Q = -HY,HY
          IJ = IJ + 1
C
C
          IOD = OD(IJ)
          IF ((IOD.GT.IODMIN).AND.(IOD.LE.IBGCUT)) THEN
            N = N + 1
            DIFFH = IOD - (BH*Q+APCH)
            SDH = SDH + DIFFH*DIFFH
          END IF
          IF (MASK(IJ).LT.0) THEN
            DIFF = IOD - (B*Q+APC)
            DIFFMP = MAX(DIFFMP,ABS(DIFF))
            SD = DIFF*DIFF + SD
C
C  Calculate DIFFMAX as maximum difference from the new plane
            DIFF = IOD - (BH*Q+APCH)
            DIFFMAX = MAX(DIFFMAX,ABS(DIFF))
          END IF
C
C
   50   CONTINUE
   60 CONTINUE
C
C
C
C---- Test maximum deviation from this new plane,reject points and
C     recalculate background plane if necessary
C
C---- Must save original plane constants in case no points are rejected
      AS = A
      BS = B
      CS = C
C
C  Now set up the new plane for testing background
C
      A = AH
      B = BH
      C = CH
C
C---- When profiles have been averaged, the background has already been
C     subtracted, so we cannot use the above estimate of BGMAX. In this
C     case (which is signalled by a negative value for BGSIG) use the
C     rms deviation in the fit of the plane to the lowest pixels
C     This will not work quite as well.
C
      IF (BGSIG.LT.0.0) THEN
        BGSIG = -BGSIG
        IF (N.NE.0) BGMAX = BGSIG*SQRT(SDH/REAL(N))
      ELSE
C
C---- For extremely low backgrounds (pixel values 0 and 1) BGMAX can be less than 1
C     and all pixels with a value of 1 can be rejected. This seems wrong, so
C     assign a minimue value of 1.0 to BGMAX
C
        BGMAX = MAX(1.0,BGSIG*SQRT(GAIN*C))
      END IF
      BGMAXINIT = BGMAX
C
C---- Must reject pixels deviating by more than BGMAX both above and below
C     the background plane, or bias will be introduced. If the background
C     is very low, then (BGMAX below background) may be negative, so a bias
C     could be introduced. In these cases, need to increase the rejection 
C     level to be sure that only real outliers are rejected. Remember that
C     in 10,000,000 pixels with a mean background of 2, 1200 will have
C     values of 10 ( a BGSIG of 4 would give a rejection level of +7.6, to
C     allow pixels of value 10, BGSIG would have to be 5.65)
C
C     Only do this when working with single reflections (MODEBKG=1)
C     and not summed reflections (profiles)
C
      IF ((C.LT.BGSIG*SQRT(GAIN*C)).AND.(MODEBKG.EQ.1)) THEN
        BGMAX = MAX(1.0,5.5*SQRT(GAIN*C))
C
C---- Set BGMAX to greater of this ammended value and the value based on BGSIG only,
C     so that if BGSIG is deliberately set high, it will still have an effect.
C
        BGMAX = MAX(BGMAX,BGMAXINIT)
      END IF
C----  Initialise number of rejected background pixels
C
      NREJ = 0
      MASKREJ(1) = 0
      ASPOT(15) = 0.0
C
      IF ((DEBUG(33).AND.CDEBUG).AND.(NDBG.LT.NDEBUG(33))) THEN
        WRITE(IOUT,FMT=6011) CHDEL,CH,FAC,DIFFMAX,BGMAXINIT,BGMAX
        IF (ONLINE) WRITE(ITOUT,FMT=6011) CHDEL,CH,FAC,DIFFMAX,
     +              BGMAXINIT,BGMAX
 6011   FORMAT(1X,'Actual CHDEL=',F8.2,' so CH=',F8.2,' FAC=',F5.2,/,1x,
     +         'DIFFMAX is',F9.2,'  BGMAX initially',F10.2,
     +         '  BGMAX after possible update for low background',F10.2)
      END IF
C
      IF (DIFFMAX.GT.BGMAX) THEN
C
C---- Plane constants are passed to BGTEST via ASPOT in /SUMS/
C            ********************************************************
        CALL BGTEST(OD(1),MASK(1),IRAS,MASKREJ(1),PQSUMS(1),BGMAX,
     +              IODMIN,NBGOUTLIER)
C            ********************************************************
C
        NREJ = MASKREJ(1)
        ASPOT(15) = NREJ
        IF ((DEBUG(33).AND.CDEBUG).AND.(NDBG.LT.NDEBUG(33))) THEN
          WRITE(IOUT,FMT=6020) PQSUMS,ASPOT,AS,BS,CS,A,B,C,
     +            BGMAX,RMSBG,DIFFMAX,NREJ,NRMAX,
     +              (MASKREJ(JJ),JJ=2,NREJ+1)
          IF (ONLINE) WRITE(ITOUT,FMT=6020) PQSUMS,ASPOT,AS,BS,CS,A,B,
     +            C,BGMAX,RMSBG,DIFFMAX,NREJ,NRMAX,
     +              (MASKREJ(JJ),JJ=2,NREJ+1)
 6020     FORMAT(//,1X,'After BGTEST',/,1X,'PQSUMS',6F12.0,/,1X,
     +        'ASPOT',/,1X,9F12.1,/,1X,9F12.1,/,1X,'Old A,B,C',
     +        3F10.2,/,1X,'New A,B,C',3F10.2,/,1X,'BGMAX=',F10.2,
     +        '  RMSBG=',F10.2,
     +        '  DIFFMAX=',F10.2,/,1X,'NREJ',I5,' NRMAX',I5,/,1X,
     +        'MASKREJ values:',/,(1X,12I5))
        END IF
C
C  Flag this spots as rejected if too many rejected background points
        IF ((DEBUG(33)).AND.(NREJ.GT.100).AND.(CDEBUG)) THEN
          WRITE(6,*)'MORE THAN 100 BACKGROUND PIXELS REJECTED'
          WRITE(6,*)'PIXEL COORDS',IX,IY
          WRITE(6,*)'OLD  A,B,C, NEW A,B,C',AS,BS,CS,AH,BH,CH
          WRITE(6,*)'IBGCUT,N',IBGCUT,N
          WRITE(6,*)'NREJ=,NRMAX=,MASKREJ',NREJ,NRMAX,
     +              (MASKREJ(JJ),JJ=2,NREJ+1)
          MAXPIX = 0
          CALL ODPLOT4(OD,NXX,NYY,1,MAXPIX)
        END IF
        IF (NREJ.GT.NRMAX) THEN
          NRMAX = -999
          RETURN
        END IF
      END IF
C
C---- Check if too many points rejected to store in MASKREJ
C
      IF (NREJ.EQ.-999) THEN
          NWRN = NWRN + 1
CAL          WRITE (IOUT,FMT=6000) NREJMAX,BGSIG
CAL          IF (ONLINE) WRITE (ITOUT,FMT=6000) NREJMAX,BGSIG
 6000 FORMAT (//1X,'**** MORE THAN',I5,' BACKGROUND POINTS REJECTED ',
     +       ' AS DEVIATING BY MORE THAN',F3.1,'*SIGMA ****',
     +        /1X,'Increase BGSIG (keywords BACKGROUND BGSIG)')
          ASPOT(15) = 0
          NRMAX = -999
          RETURN
      ELSE IF (NREJ.GT.0) THEN
C
C---- Recalculate background plane
C     note that bgsolve updates aspot(3)=rmsbg and aspot(6 to 12)
C     (This includes the plane constants)
C              ***************************************************
          CALL BGSOLVE(OD(1),MASK(1),IRAS,MASKREJ(1),PQSUMS(1))
C              ***************************************************
C
C   No background points rejected, use original plane constants unless
C   this is an EDGESPOT, in which case use those determined here
C   as original values took no account of NULLPIX values
      ELSE
          ASPOT(3) = SQRT(SD/PQSUMS(6))
          IF (EDGESPOT) THEN
            ASPOT(9) = AH
            ASPOT(10) = BH
            ASPOT(11) = CH
          ELSE
            ASPOT(9) = AS
            ASPOT(10) = BS
            ASPOT(11) = CS
          END IF
          ASPOT(12) = DIFFMP
      END IF
C
      GRADX = ABS(ASPOT(9))/NRBX
      GRADY = ABS(ASPOT(10))/NRBX
      IF ((DEBUG(33)).AND.((GRADX.GT.10.0).OR.(GRADY.GT.10.0))
     +          .AND.CDEBUG) THEN
        WRITE(6,*)'GRADIENT GREATER THAN 10'
        WRITE(6,*)'PIXEL COORDS',IX,IY
        WRITE(6,*)'after bgsolve OLD  A,B,C, NEW A,B,C',AS,BS,CS,A,B,C
        WRITE(6,*)'NREJ=,NRMAX=,MASKREJ',NREJ,NRMAX,
     +              (MASKREJ(JJ),JJ=2,NREJ+1)
        MAXPIX = 0
        CALL ODPLOT4R(OD,NXX,NYY,1,MASK,MASKREJ,MASKREJP,LMASKREJP,
     +                MAXPIX)
      END IF
      IF ((DEBUG(33).AND.CDEBUG).AND.(NDBG.LT.NDEBUG(33))) THEN
        RMSBG = ASPOT(3)
        DIFFMAX = ASPOT(12)
        NDBG = NDBG + 1
        WRITE(IOUT,FMT=6030) AS,BS,CS,A,B,C,ASPOT,BGMAX,RMSBG,DIFFMAX
        IF (ONLINE) WRITE(ITOUT,FMT=6030) AS,BS,CS,A,B,ASPOT,BGMAX,
     +                                    RMSBG,DIFFMAX
 6030     FORMAT(//,1X,'After BGSOLVE',/,1X,'Old A,B,C',
     +      3F14.2,/,1X,'New A,B,C',3F14.2,/,1X,
     +      'ASPOT',/,1X,9F12.2,/,1X,9F12.2,/,1X,'BGMAX, RMSBG,',
     +      ' DIFFMAX',3F10.2)
      END IF
      END
C $Id: extract.f,v 1.3 2003/05/15 09:36:48 harry Exp $
C== EXTRACT ==
C
      SUBROUTINE EXTRACT(IODBIG,IRBIG,IRAS,IODPROF)
C     =============================================
      IMPLICIT NONE
C
C---- Extracts a measurement box of size specified by IRAS from a larger
C     box IODBOX size given by IRBIG
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     ..
C     .. Scalar Arguments ..
C     ..
C     .. Array Arguments ..
      INTEGER IODBIG(MAXBOX),IRBIG(2),IRAS(5),IODPROF(MAXBOX)
C     ..
C     .. Local Scalars ..
c      REAL A
      INTEGER I,J,IJ,IK,IHX,IHY,IHXB,IHYB
C     ..
C     .. Local Arrays ..
C     ..
C     .. External Subroutines ..
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC ABS
C     ..
C     .. Common blocks ..
C     ..
C     ..
C     .. Equivalences ..
C
C
      SAVE
C     .. Data statements ..
C
      IHXB = IRBIG(1)/2
      IHYB = IRBIG(2)/2
      IHX = IRAS(1)/2
      IHY = IRAS(2)/2
      IJ = 0
      IK = 0
C
      DO 10 I = -IHXB,IHXB
        DO 20 J = -IHYB,IHYB
          IJ = IJ + 1
          IF ((ABS(I).GT.IHX).OR.(ABS(J).GT.IHY)) GOTO 20
          IK = IK + 1
          IODPROF(IK) = IODBIG(IJ)
 20     CONTINUE
 10   CONTINUE
      END
C== FEDGE  ==
      SUBROUTINE FEDGE(IOD1,NP,IMODE,NEDGE)
C      ===================================
      IMPLICIT NONE
C           Common block PARAMETER
C     .. Include files ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C
C---- Find the position of the boundary between this peak and the neighbouring
C     one using pixel values in the 1D array IOD1.
C     IMODE = 0  Only need to find significant next peak on one side
C                of origin. This is used when called from CENTRS.
C           = 1  Need to find significant next peak on both sides
C                of origin. This is used when called for standard profiles.
C     ..
C     .. Scalar Arguments ..
      INTEGER NP,NEDGE,IMODE
C     ..
C     .. Array Arguments ..
      INTEGER IOD1(-NP:NP)
C     ..
C     .. Local Scalars ..    
      REAL FAC,SIGP,SIGN,DIFFP,DIFFN,X1,X2
      INTEGER I,J,IODMIN,IMIN,IODI,IODIM1,IODMI,IODMIP1
      LOGICAL POS,NEG
C     ..
C     .. Local Arrays ..
      INTEGER IOD(3)
C     ..
C     .. External Subroutines ..
      EXTERNAL PARAB
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC NINT
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/debug.f
C
C $Id: debug.f,v 1.8 2021/06/03 09:41:34 andrew Exp $
C
C--- awk generated include file  debug.h
C---- START of include file debug.h
C
C
C
C     .. Arrays in common /DEBUG/ ..
      REAL XWARN
      INTEGER NDEBUG,IWARN,IARRDUMP
      LOGICAL DEBUG,LPRINT,DUMP,WARN
C
C     .. Scalars in common /DEBUG/ ..
      REAL BGRLIM
      INTEGER NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,IERRLEVEL
      LOGICAL SPOT
      CHARACTER MESSAGE*512
C     
C     ..
C     .. Common Block /DEBUG/..
      COMMON /DEBUG/XWARN(MAXIWARN,100),BGRLIM,NDEBUG(200),
     +       IWARN(MAXIWARN,100),
     $       NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,DEBUG(200),LPRINT(20),
     +       DUMP(30),WARN(100),SPOT,IARRDUMP(30),IERRLEVEL

      COMMON /CDEBUG/ MESSAGE
C     ..
C
C&&*&& end_include  ../inc/debug.f
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C&&*&& include  ../inc/lmb.f
C
C $Id: lmb.f,v 1.17 2021/03/30 09:16:05 andrew Exp $
C
C--- awk generated include file  lmb.h
C---- START of include file lmb.h
C ODSCAL is to scale image numbers into the range 0-255 for plotting
C average profiles.
C  GAIN should be equal to the overall gain (image counts per X-ray photon)
C of the system, and is used to evaluate standard deviations based on
C counting statistics assuming independent pixels (ie point spread function
C less than pixel size).
C INVERTX true if image is inverted in the slow (X) direction when read in.
C ISCAL is to scale final integrated intensities and sigmas
C IDIVIDE is the adc offset
C ICONST is a constant to be added to all pixels (normally zero) to
C        allow processing of images with zero pixel values in the scanned
C        area.
C IMGP is true if working with image plate data
C SPIRAL is true for scanners with a spiral readout (Mar, DIP2000)
C ORTHOG is true for scanners with orthogonal scan (FUJI, RAXIS, MD)
C NULLPIX is the value of pixels within the image but not in the active
C area of the detector
C TILED is true if there are inactive areas of the detector within the
C       inscribing circle or square.
C
C NTILEX Number of tiles in X direction
C NTILEY Number of tiles in Y direction
C TILEX  X Coordinates of the midpoints of the null areas between tiles
C TILEY  Y Coordinates of the midpoints of the null areas between tiles
C TILEWX Width of the null areas between tiles in X
C TILEWY Width of the null areas between tiles in Y


C MACHINE and MODEL denote the type of detector.
C DECTRIS_TYPE can be PILATUS, EIGER1 or EIGER2. It is used when setting up
C the positions of the gaps between the tiles.
C
C MACHINE is used in the following subroutines:
C GETBLK, GETHDR, INTPXL, INTPXL2, MXDSPL, OPENODS, PROCESS, PUTPXL
C Currently coded types are:
C
C         MACHINE        MODEL               COMMENTS
C         =======        =====               ========
C         MAR            180, 300, 345
C         RAXI(S)        RAXISII, RAXISIV
C         MD
C         FUJI
C         CCD1           CCD1                Princetown CCD at CHESS,Tiff format
C         CCD2           CCD ?               ESRF CCD detector
C         ADSC           QUAD1               ADSC 2x2 CCD detector
C
C TRUSTED whether or not the image header information can be trusted for 
C         automatic processing
C MICROED indicates whether or not this is electron diffraction data,
C        base on the wavelength being less than 0.05A
C
C
C     .. Scalars in Common Block /LMB/ ..
        REAL ODSCAL,GAIN,LOGA,LOGB
        INTEGER ISCAL,IDIVIDE,ICONST,NULLPIX,NTILEX,NTILEY,
     $       RAXISCOMP,IIDIVIDE,COMPRESSION,GAPVAL,IINVERTX
        LOGICAL IMGP,INVERTX,SPIRAL,ORTHOG,CIRCULAR,TILED,SETADC,
     $       NEWRAXIS,BRUKNEW,TRUSTED,MINICBF,HDF5FILE,GAPMASK,
     $       WRONGGAPVALUE,MICROED
        CHARACTER MACHINE*4,MODEL*8,LDETECTOR*20,DECTRIS_TYPE*10,
     +       CMACHINE*40

C     ..
C     .. Arrays in common /LMB/
        INTEGER TILEX,TILEY,TILEWX,TILEWY
C
C     .. Common Block /LMB/ ..
        COMMON /LMB/ ODSCAL,GAIN,LOGA,LOGB,ISCAL,IDIVIDE,ICONST,
     $       NULLPIX,NTILEX,NTILEY,RAXISCOMP,IIDIVIDE,COMPRESSION,
     $       GAPVAL,IINVERTX,TILEX(20),TILEY(20),TILEWX(20),TILEWY(20),
     $       IMGP,INVERTX,SPIRAL,ORTHOG,CIRCULAR,
     $       TILED,SETADC,NEWRAXIS,BRUKNEW,TRUSTED,MINICBF,HDF5FILE,
     $       GAPMASK,WRONGGAPVALUE,MICROED
        COMMON /LMBC/ MACHINE,MODEL,LDETECTOR,DECTRIS_TYPE,CMACHINE

C&&*&& end_include  ../inc/lmb.f
C
C
      FAC = 5.0
      NEDGE = NP
      IF (DEBUG(47)) THEN
        WRITE(IOUT,FMT=6004) (IOD1(I),I=-NP,NP)
        IF (ONLINE) WRITE(ITOUT,FMT=6004) (IOD1(I),I=-NP,NP)
 6004   FORMAT(/,1X,'Subroutine FEDGE',/,1X,'Values in strip:',
     +          /,(1X,15I8,/))
      END IF

C
C---- Assume the next peak is at least 3 pixels away, so start search
C     by comparing pixel +3 with +2, -3 with -2 and work out.
C     Sometimes if the initial refinement is not good the centre of
C     the spot is not in the middle of the box and since from CENTRS 
C     a significant peak need only be found on one side this can
C     cause problems
C
      DO 30 I = 3,NP
        IODI = MAX(IOD1(I),0)
        IODIM1 = MAX(IOD1(I-1),0)
        IODMI = MAX(IOD1(-I),0)
        IODMIP1 = MAX(IOD1(-I+1),0)
        DIFFP = IODI - IODIM1
        DIFFN = IODMI - IODMIP1
        SIGP = FAC*0.5*(SQRT(GAIN*IODI)+SQRT(GAIN*IODIM1))
        SIGN = FAC*0.5*(SQRT(GAIN*IODMI)+SQRT(GAIN*IODMIP1))
        POS = (DIFFP.GT.SIGP)
        NEG = (DIFFN.GT.SIGN)
        IF (((IMODE.EQ.1).AND.(POS.AND.NEG)).OR.
     +      ((IMODE.EQ.0).AND.(POS.OR.NEG))) THEN

C
C---- Found a significant increase, assume this is next peak. Find the real
C     minimum using a parabolic 3 point interpolation centred on the minimum 
C     value.
C
C---- First find the minimum value on positive side
C
         IF ((IMODE.EQ.0).AND.(.NOT.POS)) GOTO 10
         IODMIN = IOD1(0)
         IMIN = 0
         DO 2 J = 1,NP
C
C---- Don't go beyond the significant increase point found above
C
           IF (J.GT.I) GOTO 2
           IF (IOD1(J).LT.IODMIN) THEN
             IODMIN = IOD1(J)
             IMIN = J
           END IF
 2       CONTINUE
C
         DO 4 J = 1,3
           IOD(J) = IOD1(IMIN-2+J)
 4      CONTINUE
         CALL PARAB(IOD,X1)
         IF (DEBUG(47)) THEN
           WRITE(IOUT,FMT=6000) IOD,IMIN,X1
           IF (ONLINE) WRITE(ITOUT,FMT=6000) IOD,IMIN,X1
 6000      FORMAT(1X,' Positive side pixel values',3I10,
     +           ' IMIN=',I2,' X1=',F5.2)
         END IF
         X1 = IMIN + X1
C
C---- Now the negative side
C
 10      IF ((IMODE.EQ.0).AND.(.NOT.NEG)) GOTO 16
         IODMIN = IOD1(0)
         IMIN = 0
         DO 12 J = -1,-NP,-1
C
C---- Don't go beyond the significant increase point found above
C
           IF (J.LT.-I) GOTO 12
           IF (IOD1(J).LT.IODMIN) THEN
             IODMIN = IOD1(J)
             IMIN = J
           END IF
 12      CONTINUE
C
         DO 14 J = 1,3
           IOD(J) = IOD1(IMIN+2-J)
 14     CONTINUE
         CALL PARAB(IOD,X2)
         IF (DEBUG(47)) THEN
           WRITE(IOUT,FMT=6002) IOD,IMIN,X2
           IF (ONLINE) WRITE(ITOUT,FMT=6002) IOD,IMIN,X2
 6002      FORMAT(1X,' Negative side pixel values',3I10,
     +           ' IMIN=',I2,' X2=',F5.2)
         END IF
         X2 = IMIN - X2
         X2 = ABS(X2)
C
 16      IF (IMODE.EQ.0) THEN
           IF (.NOT.NEG) THEN
             NEDGE = NINT(X1)
           ELSE IF (.NOT.POS) THEN
             NEDGE = NINT(X2)
           ELSE
             NEDGE = NINT(0.5*(X1+X2))
           END IF
         ELSE
             NEDGE = NINT(0.5*(X1+X2))
         END IF
         RETURN
        END IF
 30   CONTINUE
      END
C $Id: fidus.f,v 1.4 2007/09/18 12:22:31 harry Exp $
