C---- START of include file scn.h
C
C     SCNSZ   is pixel size (in microns) divided by 25
C     RAST    pixel size in slow direction in mm
C     FACT    multiplying by FACT converts from 10 micron units 
C             (the standard unit internal to the program) into pixels
C     IYLEN   The number of pixels in the Y (fastest changing) direction
C             in the digitised image.
C     NREC    The number of pixels in the X (slow) direction in the 
C             digitised image.
C     NWORD   The number of I*2 words in the Y direction.
C     NBYTE   The number of bytes in Y direction = NWORD/2
C     NHBYTE  Number of bytes in header
C
C     ICURR   When several images are stored in a single file, ICURR is the
C             pointer to the first record of the current image in the direct
C             access file (only implemented for film data)
C     NEXTRA  The number of additional (unused) bytes padding the end of
C             each record in image file
C     BYTSWAP True if the "endedness" (Big-endian/Little-endian) of the 
C             machine that MOSFLM is running on is different to that of the
C             machine on which the image was written. This is determined by
C             looking at the value of NXPIX in the header record of the
C             image file (subroutine GETHDR)
C
C     LACTIVE True if using Rigaku active mask, False if ignoring it
C     REALLYFORCEREAD True if we want to display an image where we have
C                     changed the activemask
C
C     ROWREADT Time in seconds that the detector takes to read a row of data,
C              required for rolling shutter mode readout of Tietz detector
C              used for microED.
C     ROTSPEED Spindle rotation rate (degrees per second),required for rolling
C              shutter mode readout of Tietz detector used for microED. 
C
C
C     .. Scalars in common block /SCN/ ..
      REAL FACT,SCNSZ,RAST,RASTY,ROWREADT,ROTSPEED
      INTEGER NBYTE,NREC,NWORD,IYLEN,ICURR,NEXTRA,NHBYTE
      LOGICAL BYTSWAP,LACTIVE,REALLYFORCEREAD
C     ..
C     .. Common Block /SCN/ ..
      COMMON /SCN/ FACT,SCNSZ,RAST,RASTY,ROWREADT,ROTSPEED,
     +     NBYTE,NREC,NWORD,IYLEN,
     +     ICURR,NEXTRA,NHBYTE,BYTSWAP,LACTIVE,
     $     REALLYFORCEREAD
C&&*&& end_include  ../inc/scn.f
C     ..
      SAVE
C
      IF (NFID.EQ.0) NFID = 1
      IF (DEBUG(4)) THEN
        WRITE(IOUT,FMT=6050) NFID,ITHRESH,MMDB,NOFID,READCC
        IF (ONLINE) WRITE(ITOUT,FMT=6050) NFID,ITHRESH,MMDB,NOFID,
     +              READCC
 6050   FORMAT(//,1X,'In FIDUS, NFID=',I3,'  ITHRESH=',I6,' MMDB=',
     +         I6,'  NOFID ',L1,' READCC ',L1)
      END IF
C
C---- Fiducial constants in scanner frame
C
      DIRECT_BEAM = .FALSE.
C
C
C---- Fiducial box size
C
      HFWY = MM*FACT + 0.5
      HFWX = HFWY
C
C---- Recording of fiducial spots
C     must set TXFAC to allow display of fiducials which will
C     have coordinates of up to 175mm for vee films, giving 3500
C     raster points at 50 micron scan.
C     TXFAC converts scanner pixels to graphics pixels
C
      NGMIN = MIN(NGX,NGY)
      TXFAC = REAL(NGMIN)/3500.0* (SCNSZ/2)
C
C---- If using NOFID option, go straight to finding direct beam
C
      IF (NFID.EQ.0) THEN
        COSOMF = COS(OMEGAF)
        SINOMF = SIN(OMEGAF)
        GO TO 200
      END IF
C
C---- Define centre of film (10 micron units)
C
      XCENF = NREC*2.5*SCNSZ/2
      YCENF = 2*NWORD*2.5*SCNSZ/2
      OMEGAF = 0.0
      IF (DEBUG(4)) THEN
        WRITE (IOUT,FMT=6000) XCENF,YCENF,XTOFRA,OMEGAF,
     +    TXFAC
        IF (ONLINE) WRITE (ITOUT,FMT=6000) XCENF,YCENF,XTOFRA,OMEGAF,
     +    TXFAC
 6000 FORMAT (/1X,'XCENF,YCENF Calculated from NREC, NWORD',2I6,/3X,
     +       'XTOFRA After updating for film number in PACK',F8.4,/1X,
     +       'Starting OMEGAF',F8.4,/3X,'TXFAC',F6.3)
      END IF
   10 CONTINUE
C
C
      DO 180 J = 1,NFID
        IF (DIRECT_BEAM) GO TO 20
        XF = (FSPOS(J,1)+XCENF)*FACT + 0.5
        YF = (FSPOS(J,2)+YCENF)*FACT + 0.5
C
C---- Box is always scanned towards centre of film
C
        ISX = -SIGN(1,FSPOS(J,1))
        FSTX = XF - HFWX*ISX
        LSTX = HFWX*ISX + XF
        ISY = -SIGN(1,FSPOS(J,2))
        FSTY = YF - HFWY*ISY
        LSTY = HFWY*ISY + YF
C
C---- Test limits to ensure they are on scanned image
C
        IFX = MIN(FSTX,LSTX)
        ILX = MAX(FSTX,LSTX)
        IFY = MIN(FSTY,LSTY)
        ILY = MAX(FSTY,LSTY)
C
C
        IF ((IFX.LT.1) .OR. (ILX.GT.NREC) .OR. (IFY.LT.1) .OR.
     +      (ILY.GT.IYLEN)) THEN
          NWRN = NWRN + 1
          IF (ONLINE) WRITE (ITOUT,FMT=6002) IFX,ILX,IFY,ILY
 6002 FORMAT (//1X,'Fiducial boxes extend outside scanned film area. P',
     +       'IXEL Coords are',4I6)
          WRITE (IOUT,FMT=6002) IFX,ILX,IFY,ILY
          STOP
        END IF
C
C---- Draw fiducial boxes
C
   20   CONTINUE
C
C
   30   ACTX = FSTX
        SOD = 0.0
        SXOD = 0.0
        SYOD = 0.0
        NOD = 0
        NODSUM = 0
        ODSUM = 0.0
        ODSUMSQ = 0.0
        SPOTL = .FALSE.
        IF (DEBUG(4)) THEN
          WRITE (IOUT,FMT=6004) FSTX,LSTX,FSTY,LSTY,ISX,
     +      ISY,ITHRESH
          IF (ONLINE) WRITE (ITOUT,FMT=6004) FSTX,LSTX,FSTY,LSTY,ISX,
     +      ISY,ITHRESH
 6004 FORMAT (1X,'FSTX,LSTX',2I6,5X,'FSTY,LSTY',2I6,'   ISX,ISY',2I5,
     +       ' ITHRESH',I5)
        END IF
C
C---- Search for line of densities above threshold
C
        DO 150 K = FSTX,LSTX,ISX
C
C          *************
           CALL RDBLK(K)
C          *************
C
       IF (DEBUG(4).AND.(J.EQ.3).AND.(K.EQ.FSTX)) THEN
       WRITE(IOUT,6041) J,K
 6041       FORMAT(///1X,'FID ',I3,' STRIPE OF ODS',I4)
        NN = 0
       DO 201 I=1,IYLEN
       CALL CBYTE(I)
        NN = NN+1
        IBIT(NN) = I
        IODSTOR(NN) = IBA
        IF (MOD(NN,5).EQ.0) THEN
          NN = 0
          WRITE(IOUT,6040) (IBIT(KK),IODSTOR(KK),KK=1,5)
 6040         FORMAT(1X,5('   I=',I5,' IBA=',I5))
        END IF
 201       CONTINUE
       END IF
          ACTX = ACTX + ISX
          LINE = .FALSE.
          LB = FSTY
          LF = LSTY
C
C
          DO 90 I = FSTY,LSTY,ISY
C
C                ********
            CALL CBYTE(I)
C                ********
C
            ODSUM = ODSUM + IBA
            ODSUMSQ = REAL(IBA)*REAL(IBA) + ODSUMSQ
            NODSUM = NODSUM + 1
            IF (IBA.LT.ITHRESH) GO TO 60
            IF (LINE) GO TO 80
C
C---- Start of line
C
            LINE = .TRUE.
            LB = I
            IB = LB*TXFAC
            JX = ACTX*TXFAC
C
            GO TO 80
C
C---- End of line
C
   60       IF (.NOT.LINE) GO TO 80
            LF = I - ISY
            IE = LF*TXFAC
C
C
C
C---- Tests for acceptable line
C
C---- Fid must lie completely within box
C
            IF (LB.EQ.FSTY) GO TO 70
C
C---- Max. line length is 7.5mm
C
            ILFLB = ABS(LF-LB)
            IF (ILFLB.GT.300/SCNSZ) GO TO 70
C
C---- Min. line length is 2 pixels
C
            IF (ILFLB.LT.2) GO TO 70
            IF (.NOT.SPOTL) GO TO 110
C
C---- Test for overlap with previous line
C
            IF (ABS((LBP+LFP)- (LB+LF)).LT.
     +          ABS((LF-LB)+ (LFP-LBP))) GO TO 110
   70       LINE = .FALSE.
   80       CONTINUE
   90     CONTINUE
          LINE = .FALSE.
C
C---- No line
C
          IF (.NOT.SPOTL) GO TO 140
C
C---- Tests for acceptable fid
C     fid must lie within box
C
          IF (IFSTX.EQ.FSTX) GO TO 100
C
C---- Fid must have area greater than .02mm*2  ie 8*50 micron pixels
C
          IF (NOD.LT. (32/ (SCNSZ*SCNSZ))) GO TO 100
          GO TO 160
C
C---- Fid rejected
C
  100     SPOTL = .FALSE.
          SOD = 0.0
          SXOD = 0.0
          SYOD = 0.0
          NOD = 0
          GO TO 140
C
C---- line
C
  110     LFP = LF
          LBP = LB
          IF (SPOTL) GO TO 120
          IFSTX = K
          SPOTL = .TRUE.
  120     CONTINUE
C
C
          DO 130 I = LB,LF,ISY
C
C                ********
            CALL CBYTE(I)
C                ********
C
            NOD = NOD + 1
            SOD = SOD + IBA
            IF (DEBUG(4)) THEN
              WRITE(IOUT,6030) J,K,I,NOD,IBA
              IF (ONLINE) WRITE(ITOUT,6030) J,K,I,NOD,IBA
 6030         FORMAT(1X,'FID',I2,'  IX=',I5,'  IY=',I5,' NOD=',I5,
     +           ' IBA=',I5)
            END IF
            SXOD = (ACTX-ISX)*IBA + SXOD
            SYOD = IBA*I + SYOD
  130     CONTINUE
C
C
  140     CONTINUE
  150   CONTINUE
C
C---- End of loop over stripes (X loop)
C
C---- Will only get to following code if a spot has NOT been found
C
C
C---- Course of action depends on whether this is a repeat scan already,
C
        IF (REPEAT) THEN
          REPEAT = .FALSE.
          ITHRESH = ITHSAVE
C
C
          IF (DIRECT_BEAM) THEN
            STRING = 'DIRECT BEAM'
            NCHAR = 11
          ELSE
            STRING = 'FIDUCIAL'
            NCHAR = 8
          END IF
C
C
          IF (ONLINE) WRITE (ITOUT,FMT=6006) STRING(1:NCHAR)
 6006 FORMAT (1X,A,' NOT FOUND with threshold at 5 sigma above meanod')
          WRITE (IOUT,FMT=6006) STRING(1:NCHAR)
          IF (DIRECT_BEAM) GO TO 999
          GO TO 170
        ELSE
C
C---- Change threshold to meanod+5*sigma and repeat search if this
C     is lower than current threshold.
C
          ODMEAN = ODSUM/NODSUM
C
C---- Beware !! rounding errors can give negative variance if (due to
C     scanning errors ?) all values are identical and g.t. 130
C
          ODSIG = (ODSUMSQ/NODSUM-ODMEAN*ODMEAN)
C
C
          IF (ODSIG.GT.0.0) THEN
            ODSIG = SQRT(ODSIG)
          ELSE
            ODSIG = 0.0
          END IF
C
C
          NTHRESH = 5.0*ODSIG + ODMEAN
C
C
          IF (NTHRESH.LT.ITHRESH) THEN
C
C---- 5*sigma threshold is lower than previous threshold, go and repeat
C     search
C
            REPEAT = .TRUE.
            ITHSAVE = ITHRESH
            ITHRESH = NTHRESH
C
C
            IF (DEBUG(4)) THEN
              IF (ONLINE) WRITE (ITOUT,FMT=6008) ODMEAN,ODSIG
 6008 FORMAT (/1X,'ODMEAN and SIGMA for repeat set to ',2F6.1)
              WRITE (IOUT,FMT=6008) ODMEAN,ODSIG
            END IF
C
C
            IF (DIRECT_BEAM) THEN
              IF (ONLINE) WRITE (ITOUT,FMT=6010) ITHRESH
 6010 FORMAT (/1X,'DIRECT BEAM NOT FOUND, Repeat search with threshold',
     +       ' at ',I4)
              WRITE (IOUT,FMT=6010) ITHRESH
            ELSE
              IF (ONLINE) WRITE (ITOUT,FMT=6012) J,ITHRESH
 6012 FORMAT (/1X,'** FIDUCIAL',I2,' NOT FOUND, Repeat search with thr',
     +       'eshold at ',I4)
              WRITE (IOUT,FMT=6012) J,ITHRESH
            END IF
C
C
            GO TO 30
          ELSE
C
C---- Threshold was already less than 5*sigma above mean
C     Go on to next fiducial, or return if direct beam
C
            IF (DIRECT_BEAM) THEN
              IF (ONLINE) WRITE (ITOUT,FMT=6014) ITHRESH,ODMEAN,ODSIG
 6014 FORMAT (/1X,'** DIRECT BEAM NOT FOUND Even though threshold of ',
     +       I4,/1X,'is less than 5 sigma above the mean od in search ',
     +       'BOX (MEAN=',F5.0,' SIGMA=',F4.1,')')
              WRITE (IOUT,FMT=6014) ITHRESH,ODMEAN,ODSIG
              GO TO 999
            ELSE
              IF (ONLINE) WRITE (ITOUT,FMT=6016) J,ITHRESH,ODMEAN,ODSIG
 6016 FORMAT (/1X,'** FIDUCIAL',I2,' NOT FOUND even though threshold of'
     +       ,I4,/1X,'is less than 5 sigma above the mean od in search',
     +       ' BOX (MEAN=',F5.0,' SIGMA=',F4.1,')')
              WRITE (IOUT,FMT=6016) J,ITHRESH,ODMEAN,ODSIG
              GO TO 170
            END IF
          END IF
        END IF
C
C
  160   IF (REPEAT) THEN
          REPEAT = .FALSE.
          ITHRESH = ITHSAVE
        END IF
C
C
        CTX = SXOD/SOD
        CTY = SYOD/SOD
        SOD = SOD/NOD
C
C
        IF (DIRECT_BEAM) THEN
          IXDB = CTX/FACT
          IYDB = CTY/FACT
          CCXS = IXDB - XCENF
          CCYS = IYDB - YCENF
C
C---- Need to convert ccxs,ccys which are w.r.t. scanner coordinate
C     frame back to ccx,ccy defined w.r.t. film coordinate frame
C     **** NOT ANY MORE ****
CAL          CCX = CCXS*COSOMF + CCYS*SINOMF
CAL          CCY = -CCXS*SINOMF + CCYS*COSOMF
           CCX = CCXS
           CCY = CCYS
C
C
          PXCEN = 0.01*IXDB
          PYCEN = 0.01*IYDB
          IF (INVERTX) PXCEN = NREC*RAST - PXCEN
          WRITE (IOUT,FMT=6018) PXCEN,PYCEN,0.01*CCX,0.01*CCY
 6018 FORMAT (/1X,'Direct beam position located by search: ',2F7.1,
     +       /,1X,'Camera constants CCX:',F5.2,' CCY=',F5.2)
            IF (ONLINE) WRITE (ITOUT,FMT=6018) PXCEN,PYCEN,
     +                         0.01*CCX,0.01*CCY
C
C
          GO TO 999
        END IF
C
C---- Centre of fiducial spot
C
        FPOS(J,1) = CTX/FACT + 0.5
        FPOS(J,2) = CTY/FACT + 0.5
C
C---- Shifts from expected positions
C
        DLT(J,1) = (CTX-XF)/FACT
        DLT(J,2) = (CTY-YF)/FACT
        NODD(J) = NOD
        NFOUND = NFOUND + 1
  170   CONTINUE
  180 CONTINUE
C
C---- End of loop over nfid fiducials
C
C
      IF (LPRINT(1)) THEN
        WRITE (IOUT,FMT=6020)
 6020 FORMAT (/'   FIDUS NO.  X       Y       DX      DY   NO. POINTS')
        IF (ONLINE) WRITE (ITOUT,FMT=6020)
C
C
        DO 190 II = 1,NFOUND
          WRITE (IOUT,FMT=6022) II,FPOS(II,1),FPOS(II,2),DLT(II,1),
     +      DLT(II,2),NODD(II)
 6022 FORMAT (6I8)
          IF (ONLINE) WRITE (ITOUT,FMT=6022) II,FPOS(II,1),FPOS(II,2),
     +        DLT(II,1),DLT(II,2),NODD(II)
  190   CONTINUE
C
C
      END IF
C
C---- Return unless all fiducials have been found
C
      IF (NFOUND.NE.NFID) GO TO 999
C
C---- Calculate film centre and tilting angle
C     both as determined from the measurement and
C     as corrected using the camera constants
C
      XCENF = (FPOS(1,1)+FPOS(3,1))/2.0 + 0.5
      YCENF = (FPOS(1,2)+FPOS(3,2))/2.0 + 0.5
C
C---- OMEGAF=FLOAT(FPOS(3,2)-FPOS(2,2))/(FPOS(3,1)-FPOS(2,1))
C     note change in definition of omegaf to enable films
C     to be put on scanner with osc axis horizontal rather than
C     vertical
C
      DELX = REAL(FPOS(3,1)-FPOS(2,1))
      DELY = REAL(FPOS(3,2)-FPOS(2,2))
      OMEGAF = ATAN2(DELY,DELX)
      COSOMF = COS(OMEGAF)
      SINOMF = SIN(OMEGAF)
C
C---- Now search for direct beam if required
C
  200 DIRECT_BEAM = (MMDB.NE.0)
C
C
      IF (DIRECT_BEAM) THEN
C
C---- Skip finding direct beam if READCC specified
C
        IF (READCC) THEN
          WRITE (IOUT,FMT=6024)
 6024 FORMAT (/1X,'** Because READCC has been given, camera constants ',
     +       'will not be estimated from the direct beam position ***')
          IF (ONLINE) WRITE (ITOUT,FMT=6024)
          GO TO 999
        END IF
C
C
        HFWX = MMDB*FACT + 0.5
        HFWY = HFWX
C
C---- Include input values of CCX,CCY in calculating position
C     of direct beam search box centre
C
CAL        XF = (CCX*COSOMF+XCENF-CCY*SINOMF)*FACT + 0.5
CAL        YF = (CCX*SINOMF+YCENF+CCY*COSOMF)*FACT + 0.5
        XF = (CCX + XCENF)*FACT + 0.5
        YF = (CCY + YCENF)*FACT + 0.5
        FSTX = XF - HFWX
        LSTX = XF + HFWX
        FSTY = YF - HFWY
        LSTY = YF + HFWY
        ISX = 1
        ISY = 1
        GO TO 10
      END IF
C
C
 999  CONTINUE
C
C
      RETURN
C
C---- Format statements
C
      END
      subroutine findlen(fftsq,np,npkmin,nmultmin,idebug,fit,len)
      implicit none
C
C---- Parameters
C
      integer maxbins
      parameter (maxbins=30)      
      integer nopoints
      parameter (nopoints=4096)
      integer nopeaks
      parameter (nopeaks=4096)
C
C---- scalar arguments
C
      real fit,len
      integer np,npkmin,nmultmin,idebug
C
C---- Array arguments
C
      real fftsq(*)

C     local arrays
      integer ipk(nopeaks),nbin(maxbins),irej(nopoints),nrej(maxbins)
      real xpk(nopeaks),valpk(nopeaks),rmsbin(maxbins),
     +   sumbin(maxbins),sumsqbin(maxbins),avgbin(maxbins),
     +   rmsdbin(maxbins),val(nopoints)
C     local scalars
      integer i,j,k,nporg,npk,npkmod,nsplit,ipt,itrue,nstart,
     +        npbin,ibin,npstart,ipass,nbins,nfft
      real vali,sum,sumsq,avg,rms,rmsd,pkmax,threshorg,threshpk,scal,
     +     valmax,sumx,lenx,sigfac
      logical last, found

C     .. Common blocks ..
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f

      data nfft/-1/
      nfft = nfft + 1
      nbins = 10
C
C---- find mean and rms overall and for different bins so that
C     the threshold can vary across the FFT (set lower for higher terms).
C
      npbin = (np-1)/nbins+1
C
C---- Initialise
C
      len = 0.0
      fit = 0.0
      sum = 0.0
      sumsq = 0.0
      val(1) = sqrt(fftsq(1))

C      type *,'in findlen, np, debug, npkmin, nmultmin',np,idebug,
C     +         npkmin,nmultmin
      if (np.le.1) return
C
      do 2 i = 1,nbins
        nbin(i) = 0
        nrej(i) = 0
        sumbin(i) = 0.0
        sumsqbin(i) = 0.0
 2    continue
C
C---- Find overall mean,rms, exclusing origin
C     
      do 10 i = 2,np
        val(i) = sqrt(fftsq(i))
        vali = val(i)
        sum = sum + vali
        sumsq = sumsq + vali*vali
 10   continue
C
      avg = sum/(np-1)
      rmsd = sqrt(sumsq/(np-1) - avg*avg)
      rms = sqrt(sumsq/(np-1))
C
C---- flag outliers (ie peaks) to get a better estimate of mean and rms.
C     because rmsd is inflated by peaks (if any), safe to use a factor
C     of 3 to reject outliers. This is to reject gross outliers so that
C     the rejection below works better.
C
      sigfac = 3.0
      do 14 i = 1,np
        irej(i) = 0
        if ((val(i)-avg).gt.sigfac*rmsd) irej(i) = 1
 14   continue
C
C---- find mean and rms for each bin and overall, rejecting outliers (peaks).
C     This will be better than rejection above because it uses bin averages
C     and rmsd rather than overall values.
C     It terms of getting an average and rmsd, safe to use a factor of 2 here.
C     Look at absolute difference to also reject very low values.
C     Do 3 passes, first uses overall rejections, 2nd and third use bin values.
C
      ipass = 0
      sigfac = 2.0
 15   ipass = ipass + 1
      do 16 i = 1,np
        ibin = 1 + i/npbin
        if (ibin.gt.nbins) ibin = nbins
        if (ipass.gt.1) then
          if (abs(val(i)-avgbin(ibin)).gt.sigfac*rmsdbin(ibin)) then
CAL              if (idebug.gt.0) write(iout,111) i,ibin,val(i)
 111          format(1x,'reject pixel, bin,value',2I5,F6.0)
                  irej(i) = 1
          end if
        end if
        if (irej(i).gt.0) then
          nrej(ibin) = nrej(ibin) + 1
          goto 16
        end if
        vali = val(i)
        nbin(ibin) = nbin(ibin) + 1
        sumbin(ibin) = sumbin(ibin) + vali
        sumsqbin(ibin) = sumsqbin(ibin) + vali*vali
 16   continue
      do 18 i = 1,nbins
        if (nbin(i).eq.0) goto 18
        avgbin(i) = sumbin(i)/nbin(i)
        rmsdbin(i) = sqrt(sumsqbin(i)/nbin(i) -
     +                       avgbin(i)*avgbin(i))
        if (ipass.lt.3) then
          nrej(i) = 0
          nbin(i) = 0
          sumbin(i) = 0
          sumsqbin(i) = 0
        end if
 18   continue
C
C
      if (ipass.lt.3) goto 15
C
C---- Set threshold for finding extent of origin peak and find
C     corresponding pixel number
C
      threshorg = avgbin(1) + 1.5*rmsdbin(1)
      do 20 I = 1,np-1
        if ((val(i).le.threshorg).and.(val(i+1).le.threshorg)) then
          nporg = i - 1
          goto 22
        end if
 20   continue
C
C---- Has not found extent of origin peak, return (len=fit=0)
C
      return
C
C---- Find maximum peak beyond this pixel
C
 22   pkmax = 0.0
      do 24 i = nporg+1,np
        if (val(i).gt.pkmax) then
          pkmax = val(i)
        end if
 24   continue
C
      if (idebug.gt.0) write(iout,110) nfft,np,avg,rmsd,rms,sigfac,
     + nporg+1,pkmax,val(1),(avgbin(i),rmsdbin(i),nrej(i),i=1,nbins)
 110  FORMAT(/,1X,'FFT number',I3,' has',
     +       I5,' points  Mean',F10.2,'  Rmsd',F8.2,'  Rms',F8.2,
     +       ' sigfac',F4.1,/,1X,'Origin peak boundary at pixel',I4,
     +       1X,'Max non-origin peak',F6.0,
     +       '  origin',F6.0,/,1X,'Average, rmsd and nrej in bins',/,
     +       (1x,5(F6.1,F6.1,I5)))
C
C---- Set threshold for finding peaks. Several (close to origin) peaks should
C     be very similar in height to the biggest peak (which may or may not be 
C     the first peak.
C     Need to modify threshold as a function of pixel, as rms gets lower
C     at high pixel values. Could use a variable rms to do this.
C
      scal = 0.75
      i = nporg
      npk = 0
C
 30   threshpk = avg + scal*(pkmax-avg)
      npkmod = 0
      if (idebug.gt.0) write(iout,114) scal, i+1
 114  format(//,1X,'Looking for peaks with scal=',F4.2,
     +              ' starting at pixel',I5)
C
C---- Find all peaks above this threshold
C
 32    i = i + 1
       ibin = 1 + i/npbin
       if (ibin.gt.nbins) ibin = nbins
       threshpk = avgbin(ibin) + scal*(pkmax-avg)
       threshpk = max(threshpk, (avgbin(ibin)+2.5*rmsdbin(ibin))) 
       if (val(i).gt.threshpk) then
         npk = npk + 1
C         type *,'found peak npk at pixel',npk,i
 34      j = i + 1
C
C---- Find max value for this peak
C
         if (j.le.np) then
           if (val(j).gt.val(i)) then
             i = i + 1
             goto 34
           else
             ipk(npk) = i
C
C---- Note that origin is at pixel 1, so decrement pixel number by 1
C
             xpk(npk) = float(i)-1.0
             valpk(npk) = val(i)
             goto 32
           end if
         else
           ipk(npk) = i
         end if
       else
         if (i.lt.np) goto 32
       end if

       if (idebug.gt.0) write(iout,120) scal, npk,
     +       (ipk(i),xpk(i),valpk(i),i=1,npk)
 120   format(1x,'scal=',F5.3,
     +    '  number of peaks',I5,/,1x,
     +    'values of pixel, x and peak height',
     +    /,(1x,4(i5,f7.1,f6.0,4x)))
C
C---- If FFT is very noisy, it is possible that it will not find even
C     the strongest peak
C
      if (npk.eq.0) goto 48
C
C---- Some peaks can be noisy, ie have more than one maximum. Merge these now
C     using the width of the origin peak as a marker.
C
      last = .false.
      i = 0
 40   i = i + 1
      if (i.lt.npk) then
        if (ipk(i+1)-ipk(i).lt.nporg) then
C
C---- Duplicate found, now find how many peaks are involved
C
          nsplit = 2
          do 42 j = i+1,npk-1
            if (ipk(j+1)-ipk(i).lt.nporg) then
              nsplit = nsplit + 1
            else
              goto 44
            end if
 42       continue
C
C---- Now find average of all points included, weighted by peak value
C
 44       sum = 0.0
          sumx = 0.0
          valmax = 0
          ibin = 1 + ipk(i)/npbin 
          if (ibin.gt.nbins) ibin = nbins
          avg = avgbin(ibin)
          do 46 j = 1,nsplit
            ipt = i + j -1
            valmax = max(valmax,valpk(ipt))
            sum = sum + valpk(ipt) - avg
            sumx = sumx + (valpk(ipt) - avg)*xpk(ipt)
 46       continue
          npkmod = npkmod + 1
          valpk(npkmod) = valmax
          if (sum.gt.0.0) then
            xpk(npkmod) = sumx/sum
          else
            xpk(npkmod) = xpk(i)
          end if
          ipk(npkmod) = ipk(i+nsplit-1)
          if (idebug.gt.0) write(iout,130) nsplit,i,valmax,xpk(npkmod),
     +                      ipk(npkmod),avg
 130      format(1x,'Merged',I3,' peaks starting at number',I3,'  max',
     +         ' peak height',F6.1,' weighted mean x',F6.1,
     +         ' pixel',I5,' avg',F6.0)
          i = i + nsplit - 1
C
C---- If the very last peak has been included, decrement npkmod or
C     it will be counted twice
          if (i.eq.npk) last = .true.
        else
          npkmod = npkmod + 1
          valpk(npkmod) = valpk(i)
          xpk(npkmod) = xpk(i)
          ipk(npkmod) = ipk(i)
        end if
C
C---- If not yet the last but one peak, got to next peak
C
        if (i.lt.npk-1) goto 40
      end if
C
C---- All peaks tested for multiples. Now Add in the last peak if not
C     already included as a merged peak
C
      if (.not.last) then
        npkmod = npkmod + 1
        valpk(npkmod) = valpk(npk)
        xpk(npkmod) = xpk(npk)
        ipk(npkmod) = ipk(npk)
      end if
      if (idebug.gt.0) write(iout,140) npkmod,
     +       (ipk(i),xpk(i),valpk(i),i=1,npkmod)
 140  format(1x,'After merging multiple peaks',/,1X,
     +    '  number of peaks',I5,/,1x,
     +    'values of pixel,x and peak height',
     +    /,(1x,4(I5,f7.1,f6.0,4x)))
C
C---- If a sufficient number of peaks found, proceed, otherwise lower
C     threshold, and search outwards
C     from the last peak found (plus 2x*origin width).
C
 48   if (npkmod.lt.npkmin) then
        if (scal.gt.0.51) then
          scal = scal - 0.25
        else
          scal = scal - 0.1
        end if
        npk = npkmod
C
C---- If scal is ge 0.25, repeat search from beginning
C     otherwise start at last found point. This avoids
C     picking up noise peaks near origin when scal is very low.
C
        if (scal.gt.0.249) then
          npk = 0
          npkmod = 0
          i = nporg
        else
          if (npkmod.gt.0) then
            i = ipk(npkmod) + 2*nporg
          else
            i = nporg
          end if
        end if
        if (scal.ge.0) goto 30
      end if
C
C---- Sufficient peaks now found. Now have to find the primitive repeat length
C     Starting with the shortest, search list for a peak which has at least 
C     nmultmin multiples
C
      do 50 i = 1,npkmod-nmultmin
        len = xpk(i)
        nstart = i + 1
C
C---- Loop over multiplicities
C
        do 52 j = 1,nmultmin
           lenx = (j+1)*len
           found = .false.
C
C---- Loop over unused peaks looking for this multiplicity
C
           do 54 k = nstart,npkmod
C             type *,'i,j,k,lenx,xpk(k)',i,j,k,lenx,xpk(k),orgwidth
             found = (abs(lenx-xpk(k)).lt.(nporg+(j+1)*0.5))
             if (found) then
               if (idebug.gt.0) write(iout,150) i,j+1,k
 150         format(1x,'For peak',I3,' found multiple',I3,
     +              ' at peak',I3)
               nstart = k + 1
               goto 52
             end if
 54        continue
           if (.not.found) goto 50
 52     continue
        if (found) then
          itrue = i
          goto 60
        end if
 50   continue
C
C---- NOT FOUND
C
      if (idebug.gt.0) write(iout,152)
 152  format(1x,'** FAILURE **, no suitable peaks found')
      len = 0.0
      return
C
 60   len = xpk(itrue)
      fit = valpk(itrue)
C
C---- Final check, peak height for primitive repeat length must be at least
C     0.75*(max non-origin peak height). This should prevent cases where it
C     selects a very short cell edge that is really just noise.
C
      if (fit.lt.0.75*pkmax) then
        len = 0.0
        fit = 0.0
        if (idebug.gt.1) write(iout,154) valpk(itrue)
 154    format(1x,'** FAILURE **, peaks found but rejected ',
     +              'because peak value of',F6.1,' too small')
        return
      end if
C
C---- Success
C
      if (idebug.gt.1) write(iout,156) itrue,nmultmin,len,fit
 156  format(//,1X,'** SUCCESS **Peak',I3,' has the required',I3,
     +          ' multiples, len=',F6.1,' fit=',F6.1)
      return
      end
C $Id: findpack.f,v 1.16 2021/06/03 09:42:13 andrew Exp $
C== FINDPACK ==
      SUBROUTINE FINDPACK(ID,FILMPLT,NFGEN,JPACK,FORCE,READCC,NOFID,
     +                    NPACK)
C     ==============================================================
C
      IMPLICIT NONE
C
