     $     NSPK(MXSPOT), IWTBG(MAXBGBOX,MAXBGBOX), AVBG(IXWDTH)
      REAL BGOD(IXWDTH),PHI(MAXIMG),PHISAVE(MAXIMG),
     $     XSPOT(MXSPOT),YSPOT(MXSPOT),RESOLU(MXSPOT),
     $     RSPOT(MXSPOT),PHISTIM(MAXIMG),PHIRNGA(MAXIMG),
     +     BGODA2(21,21,3)
C     ..
C     .. Common Block /SPOTS2/  and /SPOTS2C/ ....
      COMMON /SPOTS2/
C     .. real scalars
     $     CUTPIXMAX,CUTPIXMIN,CUTWXMAX,CUTWXMIN,CUTWYMAX,CUTWYMIN,
     +     XSPLIT,YSPLIT,YOFFSET,XOFFSET,THRESH,RMINSP,RMAXSP,
     +     RMINSRCH,RMAXSRCH,SCALSRCH,SPXMIN,SPYMIN,THRESHMIN,
     +     THRESHMAX,RMSFAC,ANISOMAX,AUTORES1,AUTORES2,AUTOFAC1,
     +     AUTOFAC2,RINGFACT,RES2SD,
C     .. integer scalars
     $     NBINR,NBINT,IBINLIM,NPIXMIN,NPIXMAX,IIMAG,NIMAG,
     +     MEDWXSPOT,MEDWYSPOT,NSEARCH,ITHSET,ISAFE,IRSTRT,
     +     NSPTD,MAXPKS,MAXYEXT,
     +     NXBOX,NYBOX,
     +     IPIXMIN,IRMSFAC,NUMICE,NTOOFEWPIX,NIMGSUMSPOT,NRESOLU,
C     -- logicals 
     $     RADX,RADY,NEWSPT,DOFIND,LOCBG,EXCLDICE,AUTORESLN,
     $     AUTORING,AUTOTHRESH,FOUND,
C     .. integer arrays
     $     NPIX,IWXSPOT,IWYSPOT,IORDER,INSPOT,NOIMG,ISDSPOT,NSPK,
     +        IWTBG,AVBG,
C     .. real arrays
     $     BGOD,PHI,XSPOT,YSPOT,RESOLU,RSPOT,PHISTIM,PHIRNGA,
     $     BGODA2,PHISAVE

      REAL BGLOCAL(MAXBGBOX,MAXBGBOX,4)
       
      COMMON /SPOTS3/BGLOCAL

      CHARACTER IMGTEMPL*100,IMGFN*100,IMGNUM*9
      COMMON /SPOTS2C/ IMGTEMPL,IMGFN,IMGNUM
C&&*&& end_include  ../inc/spots2.f
C&&*&& include  ../inc/test.f
C--- awk generated include file  test.h
C---- START of include file test.h
C
C    Detector limits, used in SPTEST. All are in 10 micron units.
C    In the virtual detector frame, Y is parallel to the rotation axis
C    and X is orthogonal to the rotation axis.
C
C    In the scanner frame, X is parallel to the slow direction in the
C    image, Y is the fast direction.
C
C    RSCANSQ      Radius**2 of the scanned region of the plate (Mar scanners)
C                 This is different to the other limits because it is
C                 applied to the actual scanner coordinates rather than
C                 the virtual detector coordinates. All other limits apply
C                 to virtual detector coordinates.
C    XSCAN        Maximum X coordinate in detector frame (10 micron units)
C    YSCAN        Maximum Y coordinate in detector frame (10 micron units)
C    RSCANX,RSCANY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RSCAN defining the
C                 useable area of the detector.
C    XSCAN,YSCAN,RSCAN are maximum coords relative to the physical centre of 
C                 the detector (ie the mid-point of the image), NOT wrt the 
C                 direct beam position.
C    RMINX,RMINY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RMIN defining the
C                 useable area of the detector.
C    RMXSQD       Maximum radius (squared) in virtual detector frame
C    RMNSQD       Minimum radius (squared) in virtual detector frame
C    XMIN         Minimum X coordinate in  detector frame
C    XMAX         Maximum X coordinate in  detector frame
C    YMIN         Minimum Y coordinate in  detector frame
C    YMAX         Maximum Y coordinate in  detector frame
C    NXYEXC       Number of excluded areas set by user (rectangles, arcs)
C    NXYEXCDET    Number of detector specific excluded rectangles (Pilatus)
C    NOTILES      If set true, ignore all tile boundaries in Pilatus images
C    ICEWIDTH     Width of the exclusion shells for ice, this fraction
C                 of the actual resolution is used as the half-width
C    ICEWIDTHPREF Width of the exclusion shells for ice for post
C                 refinement, this fraction
C                 of the actual resolution is used as the half-width
C    PREFEXICE    Logical, true if reflections in ice rings to be
C                 excluded from post-refinement
C
C     .. Scalars in common block /TEST/ ..
      REAL RMXSQD,RMNSQD,XMIN,XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,
     +     RMINX,RMINY,XSCAN,YSCAN,CIRRAD,ICEWIDTH,ICEWIDTHPREF
      INTEGER NEXCL,NXYEXC,NXYEXCDET,IQUADNO,IARCNO,NEXCL2
      LOGICAL PREFEXICE,NOTILES
C
C     .. Arrays in common block /TEST/
      REAL RESEXL,RESEXH,XYEXC,CNREXC,EXCARC,CIRCEN,PHILIM,RES2EXL,
     +     RES2EXH,RES3EXL,RES3EXH,XYEXCSP
      INTEGER IEXCARC
      LOGICAL LEXCARC
C     ..
C     .. Common Block /TEST/ ..
      COMMON /TEST/RESEXL(MAXEXCL),RESEXH(MAXEXCL),XYEXC(4,MAXEXCL),
     +     CNREXC(8,MAXEXCL),
     $     EXCARC(5,MAXEXCL),CIRCEN(2),PHILIM(2),RMXSQD,RMNSQD,XMIN,
     +     XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,RMINX,RMINY,XSCAN,
     $     YSCAN,CIRRAD,IEXCARC(6,MAXEXCL),NEXCL,NXYEXC,IQUADNO,
     $     IARCNO,LEXCARC(MAXEXCL),NXYEXCDET,RES2EXL(MAXEXCL),
     $     RES2EXH(MAXEXCL),NEXCL2,ICEWIDTH,ICEWIDTHPREF,PREFEXICE,
     +     RES3EXL(MAXEXCL),RES3EXH(MAXEXCL),NOTILES,XYEXCSP(4,MAXEXCL)
C     ..
C
C

C&&*&& end_include  ../inc/test.f
C&&*&& include  ../inc/xy.f
C
C $Id: xy.f,v 1.1 2002/05/02 10:47:25 harry Exp $
C
C--- awk generated include file  xy.h
C---- START of include file xy.h
C
C     .. Scalars in common block /XY/ ..
      REAL XTOFD,SINV,COSV,TANV,TWOTHETA
      INTEGER ICASS
C     ..
C     .. Common Block /XY/ ..
      COMMON /XY/XTOFD,SINV,COSV,TANV,TWOTHETA,ICASS
C     ..
C
C     XTOFD....  Crystal to detector distance in 10 micron units. Read from
C                keyworded input and never changed.
C
C                Spot positions are calculated in S/R XYSPOT (Called from
C                REEK) and are for an "ideal" detector at a distance of XTOFD.
C                These are converted into pixel positions in S/R MMTOPX
C                which applies the multiplicative factor XTOFRA to allow
C                for refinement of the distance. XTOFRA is the parameter
C                that is actually refined (in RDIST), rather than XTOFD.
C                The refined distance that is printed in the logfile is
C                actually XTOFRA*XTOFD
C
C     ICASS....  Indicates detector type:
C                0     Flat film
C                1     Vee shaped cassettes
C                2     FAST detector (only used in TESTGEN mode of OSCGEN)
C                3     Swung out FAST (ditto)
C                4     IP detector
C     TWOTHETA   Detector swing angle (degrees)
C&&*&& end_include  ../inc/xy.f

C     ..
      SAVE
C
      DISTANCE = 0.01*XTOFD
      IF (DEBUG(63)) THEN
        WRITE(IOUT,FMT=6004) DISTANCE, WAVE, TWOTHETA
        IF (ONLINE) WRITE(ITOUT,FMT=6004) DISTANCE, WAVE, TWOTHETA
 6004 FORMAT(1x,'In FINDSPOTS, distance:',F10.3,' wave',F10.5,
     +          ' twotheta',F10.5)
      END IF
      NUMICE = 0
      NREJRES = 0
      NMULTPKS = 0
      NTOOFEWPIX = 0
      NTOOWIDE = 0
      NANISO = 0
      DO 2 I = 1,50
        NXHIST(I) = 0
        NYHIST(I) = 0
        NPKSHIST(I) = 0
 2    CONTINUE
      IF (LOCBG) THEN
        NUMXBOX = NREC/NXBOX
        IF (NUMXBOX*NXBOX.LT.NREC) NUMXBOX = NUMXBOX + 1
        NUMYBOX = IYLEN/NYBOX
        IF (NUMYBOX*NYBOX.LT.IYLEN) NUMYBOX = NUMYBOX + 1
      END IF
      XMINDTX = MINDTX
      XMINDTY = MINDTY
C
C----  Zero array, used as flag
C
      IERRF = 0
      NDBG = 0
      DO 10 I = 1,MXCENT
        NPIXCENT(I) = 0
        NPEAKS(I) = 0
        IYBEGTMP(I) = 999999
        IYENDTMP(I) = 0
   10 CONTINUE
C
C----  Calculate limits in pixel units
C
      IX = NINT(XMM/RAST)
      IY = NINT(YMM/RAST)
C
C----  Limits on X
C
      IR = NINT(RMAXFND/RAST)
      IXL = MAX(1,IX-IR)
      IXH = MIN(NREC,IX+IR)
C
C----  Limits on spot dimensions for split spots
C
      IXSPLIT = NINT(WXMM/RAST)
      IYSPLIT = NINT(WYMM/RAST)
C
      NSPOT = 0
      NCENT = 0
      NEXCLD = 0
C
C----  Outer loop - Loop over stripes/rows
C
      IF (LPRNT) THEN
        WRITE(IOUT,FMT=6000)
        IF (ONLINE) WRITE(ITOUT,FMT=6000)
      END IF
 6000 FORMAT (/,1X,'Starting spot search...')
C
C
      IF (DEBUG(63)) THEN
        WRITE(IOUT,FMT=6080) IXL,IXH
        IF (ONLINE) WRITE(ITOUT,FMT=6080) IXL,IXH
 6080   FORMAT(/,1X,'Low and high X limits',2I5)
      END IF
C
      DO 100 IXCT = IXL,IXH
        JDX = IXCT - IX
        XSQ = JDX*JDX
C
C----  For local background, set up rows of pixels for previous,
C      current and next stripes of data.
C
        IF (LOCBG) THEN
          IF (IXCT.EQ.IXL) THEN
            IXP = MAX(IXL-1,1)
            IXP = (IXP-1)*IYLEN + ISTART
            DO 12 JY = 1,IYLEN
              IF (NIMGSUMSPOT.EQ.1) THEN
                PROW(JY) = IMAGE(IXP+JY)
              ELSE
                PROW(JY) = IMAGE2(IXP+JY)
              END IF
 12         CONTINUE
            IXP = (IXCT-1)*IYLEN + ISTART
            DO 14 JY = 1,IYLEN
              IF (NIMGSUMSPOT.EQ.1) THEN
                IROW(JY) = IMAGE(IXP+JY)
              ELSE
                IROW(JY) = IMAGE2(IXP+JY)
              END IF
 14         CONTINUE
            IXP = IXP + IYLEN
            DO 16 JY = 1,IYLEN
              IF (NIMGSUMSPOT.EQ.1) THEN
                NROW(JY) = IMAGE(IXP+JY)
              ELSE
                NROW(JY) = IMAGE2(IXP+JY)
              END IF
 16         CONTINUE
          ELSE
            IXP = MIN(IXCT,NREC-1)*IYLEN + ISTART
            DO 18 JY = 1,IYLEN
              PROW(JY) = IROW(JY)
              IROW(JY) = NROW(JY)
              IF (NIMGSUMSPOT.EQ.1) THEN
                NROW(JY) = IMAGE(IXP+JY)
              ELSE
                NROW(JY) = IMAGE2(IXP+JY)
              END IF
 18         CONTINUE
          END IF
        ELSE
        
C            ***********
          CALL RDBLK(IXCT)
C            ***********
        END IF

        FXL = REAL(IXCT)
C
C----  Determine limits of this stripe
C      Do not use NINT here or can go beyond radius for which background
C      has been calcualted
C
C        IDEL = NINT(SQRT(REAL(IR*IR-JDX*JDX)))
        IDEL = SQRT(REAL(IR*IR-JDX*JDX))
        IYL = MAX(1,IY-IDEL)
        IYH = MIN(IYLEN,IY+IDEL)
C
C
        LINE = .FALSE.
C
C----  Loop over pixels along stripe and
C      find lines of pixels above threshold
C      At end of line, add line into active spot or start a new spot
C
        NP = -1
C
        IF (DEBUG(63)) THEN
          WRITE(IOUT,FMT=6082) IXCT,IYL,IYH
          IF (ONLINE) WRITE(ITOUT,FMT=6082) IXCT,IYL,IYH
 6082     FORMAT(1X,'strip',I6,' Low and high Y limits',2I5)
        END IF
C
        DO 50 IYPT = IYL,IYH
          NP = NP + 1
C
C              ****************
          IF (LOCBG) THEN
            IBA = INTPXL(IROW(IYPT))
          ELSE
            CALL CBYTE(IYPT)
          END IF
C
CAL          CALL GETOD(IYPT,IBA)
C              ****************
C
          JDY = IYPT - IY
          YSQ = JDY*JDY
C
C---- Do NOT use NINT here, or can get an index one greater than BGOD was 
C     determined to, and hence a threshold of zero.
C
          R1 = SQRT(XSQ+YSQ)
C
C---- Set background for this pixel
C
          IF (R1.EQ.0) THEN
            ITHRESH = 0
          ELSEIF(NUBACK)THEN
            IBOX = (21 * IXCT / NREC) + 1
            JBOX = (21 * IYPT /IYLEN) + 1
            ITHRESH = BGODA2(IBOX,JBOX,3)
          ELSE
            ITHRESH = BGOD(R1)
            IF ((ITHRESH.EQ.0).AND.(R1.GT.1)) ITHRESH = BGOD(R1-1)
          END IF
C
C---- Local background, only used for real spot search (MODE<10) but not
C     for initial search in central region only.
C
          IF ((LOCBG).AND.(MODE.LT.10)) THEN
C
C---- Get pointers IXB1,IXB2 into correct boxes on either side of this pixel
C     in X
C
            IXB = (IXCT-1)/NXBOX + 1
            IF (IXCT.GT.((IXB-1)*NXBOX + NXBOX/2)) THEN
              IXB1 = IXB
            ELSE
              IXB1 = IXB - 1
            END IF
            IXB2 = IXB1 + 1
C            
C---- If point on X edge set NBX = 1, otherwise 2
C
            NBX = 2
            IF (IXB1.LT.1) THEN
              NBX = 1
              IXB1 = 1
            END IF
            IF (IXB2.GT.NUMXBOX) THEN
              NBX = 1
              IXB2 = IXB1
            END IF
C
C---- Get pointers IYB1,IYB2 into correct boxes on either side of this pixel
C     in Y
C
            IYB = (IYPT-1)/NYBOX + 1
            IF (IYPT.GT.((IYB-1)*NYBOX + NYBOX/2)) THEN
              IYB1 = IYB
            ELSE
              IYB1 = IYB - 1
            END IF
            IYB2 = IYB1 + 1
C            
C---- If point on Y edge set NBY = 1, otherwise 2
C
            NBY = 2
            IF (IYB1.LT.1) THEN
              NBY = 1
              IYB1 = 1
            END IF
            IF (IYB2.GT.NUMYBOX) THEN
              NBY = 1
              IYB2 = IYB1
            END IF

            NBGBOX = NBX*NBY
C
C---- Order of 4 points is shown below, IXB1<IXB2, IYB1<IYB2
C
C           2      4
C               X               X is current pixel
C           1      3
C

            IXCEN1 = (IXB1-1)*NXBOX + NXBOX/2
            IYCEN1 = (IYB1-1)*NYBOX + NYBOX/2
            XSIZ = FLOAT(NXBOX)
            DELX = FLOAT(IXCT-IXCEN1)/XSIZ
            BG1 = BGLOCAL(IXB1,IYB1,1)
            BG2 = BGLOCAL(IXB1,IYB2,1)
            BG3 = BGLOCAL(IXB2,IYB1,1)
            BG4 = BGLOCAL(IXB2,IYB2,1)
            USE1 = (IWTBG(IXB1,IYB1).GT.0)
            USE2 = (IWTBG(IXB1,IYB2).GT.0)
            USE3 = (IWTBG(IXB2,IYB1).GT.0)
            USE4 = (IWTBG(IXB2,IYB2).GT.0)
C
C---- Linear interpolation to get value at point X, allowing for the fact
C     that some boxes may be flagged as rejected (IWTBG=0 for rejected)
C
            USE13 = (USE1.OR.USE3)
            IF (USE1.AND.USE3) THEN
              BGA = BG1 + DELX*(BG3-BG1)
            ELSE IF (USE1) THEN
              BGA = BG1
            ELSE IF (USE3) THEN
              BGA = BG3
            END IF

            USE24 = (USE2.OR.USE4)
            IF (USE2.AND.USE4) THEN
              BGB = BG2 + DELX*(BG4-BG2)
            ELSE IF (USE2) THEN
              BGB = BG2
            ELSE IF (USE4) THEN
              BGB = BG4
            END IF
C
CAL            if ((IXCT.EQ.712).AND.(IYPT.EQ.1450)) THEN
CAL              write(iout,fmt=5555) BGA,bgb
CAL              if (online) write(itout,fmt=5555) BGA,bgb
CAL 5555         format(1x,'bga',F8.1,'  bgb',F8.1)
CAL            end if
CHRP 09.03.2015
CHRP 09.03.2015 add 1 to background helps stop finding "noise peaks"
CHRP 09.03.2015 with very low backgrounds
            IF (USE13.AND.USE24) THEN
              BGK = BGA + FLOAT(IYPT-IYCEN1)/FLOAT(NYBOX)*(BGB-BGA)
CAL            if ((IXCT.EQ.712).AND.(IYPT.EQ.1450)) THEN
CAL              write(iout,fmt=5556) IYPT,IYCEN1,BGK
CAL              if (online) write(itout,fmt=5556) IYPT,IYCEN1,BGK
CAL 5556         format(1x,'IYPT',i5,'  IYCEN1',i5,'  bgk',F8.1)
CAL            end if
            ELSE IF (USE13) THEN
              BGK = BGA
            ELSE IF (USE24) THEN
              BGK = BGB
            ELSE 
              BGK = 0.25*(BG1+BG2+BG3+BG4)
            END IF
            BGK = BGK + 1
C
C---- Could use BGLOCAL(IXB1,IYB1,2) here instead of BGK, which is best ?
C
            ITHRESH = NINT(BGK + THRESH*SQRT(BGK*GAIN))
            IF (DEBUG(78).AND.(NDBG.LT.3000).and.
     +           ((IXCT.EQ.781).AND.(IYPT.EQ.1224))) THEN
              WRITE(IOUT,FMT=6002) IXCT,IYPT,IXB1*NXBOX,
     +           IYB1*NYBOX,IXB2*NXBOX,IYB2*NYBOX,
     +           BG1,BG2,BG3,BG4,USE1,USE2,USE3,USE4,BGK
              IF (ONLINE) WRITE(ITOUT,FMT=6002) IXCT,IYPT,IXB1*NXBOX,
     +           IYB1*NYBOX,IXB2*NXBOX,IYB2*NYBOX,
     +           BG1,BG2,BG3,BG4,USE1,USE2,USE3,USE4,BGK
 6002         FORMAT(1X,'IX,IY',2I5,' BOX X1,Y1,X2,Y2',4I5,/,1X,
     +           'Backg',4F8.1,' Use ',4L2,' av bkg',F8.1)
              NDBG = NDBG + 1
            END IF
          END IF
C
C
          ITEMP = IBA
C
C
          IF (.NOT.LINE) THEN
C
C----  No line now or before
C
             IF (ITEMP.GT.ITHRESH) THEN
C
C----  (.not.line.and.itemp.gt.ithresh)  ! New line
C
                LINE = .TRUE.
                IB = IYPT
                FITEMP = REAL(ITEMP-ITHRESH)
                TSUMYI = REAL(IYPT)*FITEMP
                TSUMI = FITEMP
                TSUMISQ = FITEMP**2
                NMAXIMA = 0
                IF (DEBUG(63)) THEN
                   WRITE(IOUT,FMT=6010) IXCT,IYPT,ITEMP,ITHRESH,THRESH
                   IF (ONLINE) WRITE(ITOUT,FMT=6010) IXCT,IYPT,ITEMP,
     +                  ITHRESH,THRESH
 6010              FORMAT(1X,'Start a new line at IX=',I5,' IY=',I5,
     +                  ' Counts',I6,'  Threshold',I5,' THRESH',F4.1)
                END IF
             END IF
C     
C----!  (itemp.le.ithresh)
C
          ELSE
C
C----  !  (line)
C
            ENDSTRIPE = (IYPT.EQ.IYH)
C
C----  !  End of line
C
            IF (ITEMP.LE.ITHRESH .OR. ENDSTRIPE) THEN
               LINE = .FALSE.
               IE = IYPT - 1
               ILEN = IE - IB + 1
               IYMID = NINT(TSUMYI/TSUMI)
               IF (DEBUG(63)) THEN
                  WRITE(IOUT,FMT=6020) IXCT,IYPT,IYMID,ILEN,NCENT
                  IF (ONLINE) WRITE(ITOUT,FMT=6020) IXCT,IYPT,
     +                 IYMID,ILEN,NCENT
 6020             FORMAT(1X,'Line ended at IX=',I5,' IY=',I5,
     +                 ' Y Centroid',I5,'  Length',I5,'  NCENT is',I4)
               END IF
C     
C----  Inner loop - for this line loop over active spots/centroids
C      Complicated test to allow for split spots.
C
C  Line is considered to be part of spot if either
C  a)  current line overlaps with line from previous stripe
C  b)  or centroid of line (IYMID) lies
C      within IYSPLIT of current spot centroid
C
               LOVERLAP = .FALSE.
               DO 20 ICENT = 1,NCENT
                  IF(.NOT.LOVERLAP)THEN
                     J = IPT(ICENT)
C     AL                IF ((J.LE.0).OR.(J.GT.MXCENT)) WRITE(6,*),'J,NCENT',J,NCENT
C
C---- If the Yextent of a spot is considered to be too large, then do not
C     include line in this spot. Otherwise ice rings will give a spot that
C     extends from top to bottom of the circle !
C
CHRP 08.03.2006 - remove this line until I work out why it gives rise to the "long thin 
C     prediction box problem" - I haven't yet found an image where _not_ having this line
C     causes a problem...
C     Flag these extended "spots". If spots are not resolved, this may consist
C     of several real spots. However it could be due to an ice ring or just
C     the result of the threshold being too low.
C
                     IF ((IYEND(J)-IYBEG(J)).GT.MAXYEXT) THEN
                       IFLAG(J) = 2
                       IF (DEBUG(63)) THEN
                         WRITE(IOUT,FMT=6021) ICENT,J,MAXYEXT
                         IF (ONLINE) WRITE(ITOUT,FMT=6021) ICENT,J,
     +                                       MAXYEXT 
 6021                    FORMAT(1X,'Spot',I3,' in slot',I3,' flagged ',
     +                  ' as too long in Y (gt',I5,' pixels)')
                       END IF
                       GOTO 2000
                     END IF
                     IF (DEBUG(63)) THEN
                        WRITE(IOUT,FMT=6022) ICENT,J
                        IF (ONLINE) WRITE(ITOUT,FMT=6022) ICENT,J 
 6022                   FORMAT(1X,'Checking overlap with spot',I3,
     +                  ' in slot',I3)
                     END IF
C
                     ITMP = ABS(IYMID-IYCENT(J))
C     
C---- Skip if not overlapping and not within IYSPLIT
C
C
                     IF (ABS((IYEND(J)+IYBEG(J))- (IE+IB)).LE.
     +                    ABS((IYEND(J)-IYBEG(J))+ (IE-IB)) .OR.
     +                    ITMP.LE.IYSPLIT) THEN
C     
                        IF (DEBUG(63)) THEN
                           WRITE(IOUT,FMT=6030) ICENT,J,IYBEG(J),
     +                                          IYEND(J)
                           IF (ONLINE) WRITE(ITOUT,FMT=6030) ICENT,J,
     +                                  IYBEG(J),IYEND(J)
 6030                      FORMAT(1X,'Line belongs to spot',I3,
     $                          ' in slot',I4,'  IYBEG,END',2I6)
                        END IF
                       
C
C---- If a local maximum was found in this line, store the coords of that pixel
C     and the intensity (pixel value - threshold) in the appropriate slot
C
                        IF (NMAXIMA.GT.0) THEN
                          K = NPEAKS(J)
                          DO 19 I=1,NMAXIMA
                            IF ((I.GT.MAXNPEAKS).OR.
     +                           (K+I.GT.MAXNPEAKS)) GOTO 19
                            XLOCAL(K+I,J) = XPKSPLIT(I)
                            YLOCAL(K+I,J) = YPKSPLIT(I)
                            INTLOCAL(K+I,J) = INTSPLIT(I)
 19                       CONTINUE
C
C---- Store TOTAL number of local maxima in NPEAKS even if this is > MAXNPEAKS
C     because this may be used for rejection tests
C
                          NPEAKS(J) = NPEAKS(J) + NMAXIMA
                        END IF
                        SUMXI(J) = SUMXI(J) + TSUMI*FXL
                        SUMYI(J) = SUMYI(J) + TSUMYI
                        SUMI(J) = SUMI(J) + TSUMI
                        SUMISQ(J) = SUMISQ(J) + TSUMISQ
                        IXCENT(J) = NINT(SUMXI(J)/SUMI(J))
CAL                        IYCENT(J) = NINT(SUMYI(J)/SUMI(J))
                        NPIXCENT(J) = NPIXCENT(J) + ILEN
C
C---- Do not update IYBEG,IEND,IYCENT until this Y stripe has finished, otherwise if there
C     is a pixel above thresh on the edge of a spot, and the next pixel is below
C     thresh, updating IYBEG/IYEND will mean that the rest of the spot does not
C     get assigned to the correct slot by the test given above.

CAL                        IYBEG(J) = IB
CAL                        IYEND(J) = IE
                        IYBEGTMP(J) = MIN(IYBEGTMP(J),IB)
                        IYENDTMP(J) = MAX(IYENDTMP(J),IE)
                        IXMAX(J) = IXCT
                        IYMIN(J) = MIN(IB,IYMIN(J))
                        IYMAX(J) = MAX(IE,IYMAX(J))
C
C----  Flag spot if line overlaps search area limits
C
                        IF (IB.EQ.IYL .OR. ENDSTRIPE) IFLAG(J) = 1
C     
                        LOVERLAP = .TRUE.
C
C----  End of inner loop
C
                     ENDIF
                  ENDIF
 2000             CONTINUE
 20            ENDDO
               IF(.NOT.LOVERLAP)THEN
C
C----  No active spot for current line - start of new spot
C
                  NCENT = NCENT + 1
                  IF (NCENT.GT.MXCENT) THEN
                     WRITE(IOUT,FMT=6032) MXCENT
 6032                FORMAT(1X,'Too many active spots, Maximum is:',I6,
     +                    ' Increase threshold and rerun')
                     IF (ONLINE) WRITE(ITOUT,FMT=6032) MXCENT
                     IERRF = 1
                     RETURN
                  END IF
C
C---- Find empty slot in which to store info about this spot
C
                  DO 30 I = 1,MXCENT
                     IF (NPIXCENT(I).EQ.0) THEN
                        IPT(NCENT) = I
                        GOTO 40
                     END IF
 30               CONTINUE
C     
C
 40               CONTINUE
C     
                  IF (DEBUG(63)) THEN
                     WRITE(IOUT,FMT=6040) NCENT,IPT(NCENT),NMAXIMA
                     IF (ONLINE) WRITE(ITOUT,FMT=6040) NCENT,IPT(NCENT),
     +                   NMAXIMA
 6040                FORMAT(1X,'Starting new spot number',I5,
     $                    ' in slot',I4,' NMAXIMA',I3)
                  END IF
                  
C     
                  J = IPT(NCENT)
                  NPIXCENT(J) = ILEN
                  NPEAKS(J) = NMAXIMA
C
C---- If one (or more) local maxima have been found on this first line of
C     a spot, need to store the coords and intensity
C
                  IF (NMAXIMA.GT.0) THEN
                    DO 41 I = 1,NMAXIMA
                      XLOCAL(I,J) = XPKSPLIT(I)
                      YLOCAL(I,J) = YPKSPLIT(I)
                      INTLOCAL(I,J) = INTSPLIT(I)
 41                 CONTINUE
                  END IF
C
                  SUMXI(J) = TSUMI*FXL
                  SUMYI(J) = TSUMYI
                  SUMI(J) = TSUMI
                  SUMISQ(J) = TSUMISQ
                  IYBEG(J) = IB
                  IYEND(J) = IE
                  IXCENT(J) = NINT(SUMXI(J)/SUMI(J))
                  IYCENT(J) = NINT(SUMYI(J)/SUMI(J))
                  IYMIN(J) = IB
                  IYMAX(J) = IE
                  IXMIN(J) = IXCT
                  IXMAX(J) = IXCT
                  BKG(J) = ITHRESH
C
C----  Flag spot if strip overlaps search area
C
                  IF (IB.EQ.IYL .OR. IXCT.EQ.IXL) THEN
                     IFLAG(J) = 1
                  ELSE
                     IFLAG(J) = 0
                  END IF
               ENDIF
C
C---- (.not. loverlap)
C
C
C---- (line.and.itemp.gt.ithresh)  !  ongoing line
C
             ELSE
               FITEMP = REAL(ITEMP-ITHRESH)
               TSUMYI = REAL(IYPT)*FITEMP + TSUMYI
               TSUMI = TSUMI + FITEMP
               TSUMISQ = TSUMISQ + FITEMP**2
C
C---- Want to know if this pixel is a local maximum
C     Note use of LT in first test and LE in second, so that if there are two pixels
C     with the same maximum value, it still counts it as a local maximum. Ditto with
C     GE and GT tests applied to previous and next rows.
C     
               IF (LOCBG) THEN
                 ICUT = ITEMP
                 IF ((INTPXL(IROW(IYPT-1)).LT.ICUT).AND.
     +               (INTPXL(IROW(IYPT+1)).LE.ICUT)) THEN
                   DO 42 JY = -1,1
                     IOD1 = INTPXL(PROW(IYPT+JY))
                     IF (IOD1.GE.ICUT) GOTO 44
                     IOD2 = INTPXL(NROW(IYPT+JY))
                     IF (IOD2.GT.ICUT) GOTO 44
 42                CONTINUE
C
C---- This is a local maximum
C
                   NMAXIMA = NMAXIMA + 1
                   IF (NMAXIMA.LE.MAXNPEAKS) THEN
C
C---- Find centroid of 3x3 pixels centred on this local maximum
C
                     SX = 0.0
                     SY = 0.0
                     TSUM = 0.0
                     DO 43 JY = -1,1
                       IOD1 = INTPXL(PROW(IYPT+JY))
                       IOD2 = INTPXL(IROW(IYPT+JY))
                       IOD3 = INTPXL(NROW(IYPT+JY))
                       TSUM = TSUM + IOD1 + IOD2 + IOD3
                       SX = SX - IOD1 + IOD3
                       SY = SY + JY*(IOD1+IOD2+IOD3)
 43                  CONTINUE
                     IF (TSUM.NE.0) THEN
                       SX = SX/TSUM
                       SY = SY/TSUM
                     END IF
CAL                     XPKSPLIT(NMAXIMA) = IXCT
CAL                     YPKSPLIT(NMAXIMA) = IYPT
C
C---- Because of limited sampling of peak, multiply shift by factor 2
C
                     XPKSPLIT(NMAXIMA) = IXCT + 2.0*SX
                     YPKSPLIT(NMAXIMA) = IYPT + 2.0*SY
CAL                     INTSPLIT(NMAXIMA) = ITEMP - ITHRESH
                     ICUT = TSUM - 9.0*ITHRESH
                     ICUT = MAX(ICUT,1)
                     INTSPLIT(NMAXIMA) = ICUT
                   END IF
                   IF (DEBUG(63)) THEN
                     WRITE(IOUT,FMT=6070) ITEMP,IXCT,IYPT,IXCT+SX,
     +                   IYPT+SY,ITHRESH,INTSPLIT(NMAXIMA)
                     IF (ONLINE) WRITE(ITOUT,FMT=6070) ITEMP,IXCT,IYPT,
     +                IXCT+SX,IYPT+SY,ITHRESH,INTSPLIT(NMAXIMA)
 6070                FORMAT(1X,'Local maximum of',I6,' at pixel',2i5,
     +                     '  centroid',2F8.1,' threshold',I5,
     +                     ' total Int',I8)
                   END IF
 44                CONTINUE
                 END IF
               END IF
            END IF
C     
C----!  (itemp.le.ithresh)
C
          END IF
C
C----!  (.not.line)
C
 50     CONTINUE
C
C---- !  End of loop over pixels in this stripe
C
C
C
C  Loop over active spots and store those that have finished
C
C----  Skip if no active spots
C
        IF (NCENT.GT.0) THEN
          IF (DEBUG(63)) THEN
            WRITE(IOUT,FMT=6090) NCENT
            IF (ONLINE) WRITE(ITOUT,FMT=6090) NCENT
 6090        FORMAT(1X,'Checking the ',I3,' active spots for those ',
     $           'that are finished')
          END IF
          NFIN = 0
          DO 90 ICENT=1,NCENT
            IFINA(ICENT) = 0
            J = IPT(ICENT)
C
C---- Update IYBEG,IYEND using values in IYBEGTMP,IYENDTMP, and assign IYCENT
C
            IF (IYBEGTMP(J).NE.999999) IYBEG(J) = IYBEGTMP(J)
            IF (IYENDTMP(J).NE.0) IYEND(J) = IYENDTMP(J)
            IYCENT(J) = NINT(SUMYI(J)/SUMI(J))
C
C----  Spot is considered to be finished if
C  a) Current stripe is at least IXSPLIT from centroid and
C  b) No pixels for spot found on current stripe
C  c) Spot has been flagged as too wide in Y (ice ring, line of unresolved
C     spots, false spot due to low background, arcs from loops).
C
            IF ((IXCT-IXCENT(J).GT.IXSPLIT .AND. IXCT.GT.IXMAX(J)).OR.
     +           IFLAG(J).EQ.2)  THEN
C
C---- Check if spot is to be used. Exclude those overlapping edge of search
C     area (IFLAG=1), and if not using LOCBG, those that are flagged as having
C     the maximum Y extent (IFLAG=2)
C
              USESPOT = ((IFLAG(J).EQ.0).OR.
     +                             (LOCBG.AND.(IFLAG(J).EQ.2)))
C
C----   Check if spot contains at least MINPIX pixels and does not overlap
C       edge of search area.
C
              IF ((NPIXCENT(J).GE.MINPIX).AND.USESPOT) THEN
                FINT = SUMI(J)
C
C---- Transform to mm
C
                SX = SUMXI(J)*RAST/FINT
                SY = SUMYI(J)*RAST/FINT
C
C---- Check if spot is in an excluded area, note that for the detector
C     specific excluded areas (Pilatus/Eiger) these are the extended
C     areas XYEXCSP to avoid finding spots right next to tile boundaries.
C
                LXYEXC = .FALSE.
                IF (NXYEXC.GT.0) THEN
                  XTEMP=100.0*SX
                  IF (INVERTX) XTEMP=FLOAT(NREC)*RAST*100.0-XTEMP
                  YTEMP=100.0*SY
                  DO 60 I=1,NXYEXC
                   IF (I.GT.NXYEXCDET) THEN
                     IF (XTEMP.GE.XYEXC(1,I).AND.
     $                   XTEMP.LE.XYEXC(3,I).AND.
     $                   YTEMP.GE.XYEXC(2,I).AND. 
     $                   YTEMP.LE.XYEXC(4,I)) THEN
                       NEXCLD=NEXCLD+1
                       LXYEXC = .TRUE.
                     ENDIF
                   ELSE
                     IF (XTEMP.GE.XYEXCSP(1,I).AND.
     $                   XTEMP.LE.XYEXCSP(3,I).AND.
     $                   YTEMP.GE.XYEXCSP(2,I).AND. 
     $                   YTEMP.LE.XYEXCSP(4,I)) THEN
                       NEXCLD=NEXCLD+1
                       LXYEXC = .TRUE.
                     ENDIF
                   ENDIF
 60               CONTINUE
                ENDIF
C
C---- check excluded general quadrilaterals, arcs...
C
C     ..
C     .. LIMIts QUADrilateral
      IF(IQUADNO.GT.0)THEN
        XTEMP=100.0*SX
        IF (INVERTX) XTEMP=FLOAT(NREC)*RAST*100.0-XTEMP
        YTEMP=100.0*SY
c        XTEMP = SX
c        IF (INVERTX) XTEMP=FLOAT(NREC)*RAST-XTEMP
c        YTEMP=SY
        IFAIL = 0
        CALL QUADTL(2,IQUADNO,CORNER,XTEMP,YTEMP,IFAIL)
        IF(IFAIL.NE.0)THEN
          NEXCLD = NEXCLD + 1
          LXYEXC = .TRUE.
        ENDIF
      ENDIF
C     ..
C     .. LIMIts ARC - circen, cirrad in mm. XC,XTEMP,YC in 10 micron units
      IF(IARCNO.GT.0)THEN
        IFAIL = 0
        IERR = 0
        XTEMP = SX
        IF (INVERTX) XTEMP=FLOAT(NREC)*RAST-XTEMP
        YTEMP = SY
        DO 2030 I = 1,IARCNO,1
          CIRCEN(1) = EXCARC(1,I)
          CIRCEN(2) = EXCARC(2,I)
          CIRRAD    = EXCARC(3,I)
          PHILIM(1) = EXCARC(4,I)
          PHILIM(2) = EXCARC(5,I)
          LIOARC    = LEXCARC(I)
C
C---- need a call to modified CHKARC here ----
          CALL CHKARC(XTEMP,YTEMP,CIRCEN,CIRRAD,PHILIM,LIOARC,IERR)
          IF((IFAIL.EQ.1).OR.(IERR.EQ.1))IFAIL = 1
 2030     ENDDO
          IF(IFAIL.NE.0)LXYEXC = .TRUE.
      ENDIF

C
C---- end check of general areas
C                 

C
C---- Only include spot if not in an excluded area
C
                IF (.NOT.LXYEXC) THEN
C
C----  Store spot if centroid lies within RMAXFND of search box centre
C
                  R1 = SQRT((XMM-SX)**2+ (YMM-SY)**2)
                  IF ((R1.LE.RMAXFND).AND.(R1.GE.RMINFND)) THEN
                    NSPOT = NSPOT + 1
                    IF (NSPOT.GT.MXSPOT) THEN
                      IERRF = 1
                      WRITE(IOUT,FMT=6100) MXSPOT
 6100                 FORMAT(/,1X,'Too many spots, Maximum is:',
     +                     I6,'. Rerun with an increased ',
     +                        'threshold.')
                      IF (ONLINE) WRITE(ITOUT,FMT=6100) MXSPOT
                      NSPOT = NSPOT - 1
                      RETURN
                    END IF
C
C
                    NBITS = MIN(NPEAKS(J),MAXNPEAKS)
                    NBITS = MAX(NBITS,1)
                    BADSPOT = .FALSE.
                    RESREJ = .FALSE.
                    ICE = .FALSE.
C
C---- Check if in a powder (ice) ring
C
                    DO 70 I = 1,NBITS
                      IF (NBITS.GT.1) THEN
                        IX1 = NINT(XLOCAL(I,J))
                        IY1 = NINT(YLOCAL(I,J))
                      ELSE
                        IX1 = NINT(SX/RAST)
                        IY1 = NINT(SY/RAST)
                      END IF
c   Calculate resolution
                     CALL CRESOL(IX1,IY1,DISTANCE,TWOTHETA,WAVE,RESOL)
                     IF (RESOL.EQ.0) RESOL = 0.00001
C
C---- Unless FINDSPOTS NOICE has been specified, eliminate all spots
C     in resolution shells that match those of ice rings
C
                     IF((((RESOL.LE.3.940).and.(RESOL.GE.3.860)).OR.
     $                    ((RESOL.LE.3.705).and.(RESOL.GE.3.635)).OR.
     $                    ((RESOL.LE.3.465).and.(RESOL.GE.3.415)).OR.
     $                    ((RESOL.LE.2.690).and.(RESOL.GE.2.650)).OR.
     $                    ((RESOL.LE.2.265).and.(RESOL.GE.2.235)).OR.
     $                    ((RESOL.LE.2.090).and.(RESOL.GE.2.070)).OR.
     $                    ((RESOL.LE.1.960).and.(RESOL.GE.1.940)).OR.
     $                    ((RESOL.LE.1.925).and.(RESOL.GE.1.915)).OR.
     $                    ((RESOL.LE.1.895).and.(RESOL.GE.1.885)).OR.
     $                    ((RESOL.LE.1.730).and.(RESOL.GE.1.720)).OR.
     $                    ((RESOL.LE.1.532).and.(RESOL.GE.1.522)).OR.
     $                    ((RESOL.LE.1.480).and.(RESOL.GE.1.470)).OR.
     $                    ((RESOL.LE.1.450).and.(RESOL.GE.1.440)).OR.
     $                    ((RESOL.LE.1.380).and.(RESOL.GE.1.365)).OR.
     $                    ((RESOL.LE.1.305).and.(RESOL.GE.1.298)).OR.
     $                    ((RESOL.LE.1.267).and.(RESOL.GE.1.260)).OR.
     $                    ((RESOL.LE.1.228).and.(RESOL.GE.1.222)).OR.
     $                    ((RESOL.LE.1.175).and.(RESOL.GE.1.170)).OR.
     $                  ((RESOL.LE.1.128).and.(RESOL.GE.1.124))).AND.
     +                    (EXCLDICE))
     +                    ICE = .TRUE.
C
C---- Check if it is beyond current max resolution - only if resolution set by user 
C
                     IF ((DSTMAX.GT.0.0).AND.
     +                    (WAVE/RESOL.GT.DSTMAX).and.inres.ne.0) 
     $                    RESREJ = .TRUE.
C
C---- Check if it is excluded resolution rings
C
                      IF (NEXCL.GT.0) THEN
                        DO 72 IEXCL = 1,NEXCL
                          IF ((RESOL.LE.RESEXL(IEXCL)).AND.
     +                       (RESOL.GE.RESEXH(IEXCL))) ICE = .TRUE.
 72                     CONTINUE
                      END IF
 70                 CONTINUE
C
                    IF (DEBUG(63)) THEN
                      WRITE(IOUT,FMT=6050) ICENT,J,SX,SY,
     +                   IXMIN(J),IXMAX(J),IYMIN(J),IYMAX(J),
     +                   NPIXCENT(J),NPEAKS(J),RESOL,ICE
                      IF (ONLINE) WRITE(ITOUT,FMT=6050)  ICENT,
     +                     J,SX,SY,IXMIN(J),IXMAX(J),IYMIN(J),
     $                     IYMAX(J),NPIXCENT(J),NPEAKS(J),RESOL,ICE
 6050                 FORMAT(1X,'Spot',I3,' finished, slot ',
     +                        'number',I4,
     +                        ' centroid',2F8.2,' X pixel limits',
     +                        2I5,'  Y limits',2I5,
     $                        '  number of pixels',I6,' Npeaks',I3,
     +                        ' RESOL',F6.2,' ICE ',L1)
                    END IF
                    IF (ICE) THEN
                      NSPOT = NSPOT - 1
                      IF (NBITS.LE.MAXPKS) THEN
                        NUMICE = NUMICE + NBITS
                      ELSE
                        NMULTPKS = NMULTPKS + 1
                      END IF
                      GOTO 69
                    END IF
                    IF (RESREJ) THEN
                      NSPOT = NSPOT  - 1
                      IF (NBITS.LE.MAXPKS) THEN
                        NREJRES = NREJRES + NBITS
                      ELSE
                        NMULTPKS = NMULTPKS + 1
                      END IF
                      GOTO 69
                    END IF
C
C---- Any spots with more than MAXPKS parts is rejected outright. These can
C     occur in arcs from the cryo-loop (or ice rings, but these will
C     have been rejected above).
C
                    IF ((NBITS.GT.1).AND.(NBITS.LE.MAXPKS)) THEN
C
C---- Check if each individual peak is a reasonable separation from all
C     others. Remember MINDTX is in 10 micron units. Clearly this relies on
C     having reasonable value for MINDTX, MINDTY. If a SEPARATION keyword has
C     been given, these values are used, otherwise uses a separation based on
C     the estimated spot size (for central region).
C
 74                   DMIN = 0.70*0.01*SQRT(XMINDTX**2+XMINDTY**2)
                      DO 61 I=1,NBITS
                        BADPK(I) = .FALSE.
 61                   CONTINUE
C
                      DO 62 I = 1,NBITS-1
                        DO 64 K = I+1,NBITS
                          RSQ = (XLOCAL(I,J)-XLOCAL(K,J))**2 +
     +                            (YLOCAL(I,J)-YLOCAL(K,J))**2
                          DIST = SQRT(RSQ)*RAST
                          IF (DEBUG(63)) THEN
                            WRITE(IOUT,FMT=6051) I,K,INTLOCAL(I,J),
     +                          INTLOCAL(K,J),DMIN,DIST
                            IF (ONLINE) WRITE(ITOUT,FMT=6051) I,K,
     +                        INTLOCAL(I,J),INTLOCAL(K,J),DMIN,DIST
                          END IF
 6051                     FORMAT(1X,'Peaks ',I3,' and',I3,
     +                        '  Intensities',2I6,' dmin',F6.2,
     +                        ' dist',F6.2)
                          IF (DIST.LT.DMIN) THEN
C
C---- Try rejecting the weaker peak
C
                            IF (INTLOCAL(I,J).GT.INTLOCAL(K,J))THEN
                              BADPK(K) = .TRUE.
                            ELSE
                              BADPK(I) = .TRUE.
                            END IF
                          END IF
 64                     CONTINUE
 62                   CONTINUE
C
C---- Find the accepted peaks that are furthest apart
C
                      DMAX = 0.0
                      DO 80 I = 1,NBITS-1
                        IF (BADPK(I)) GOTO 80
                        DO 82 K = I+1,NBITS
                          IF (BADPK(K)) GOTO 82
                          RSQ = (XLOCAL(I,J)-XLOCAL(K,J))**2 +
     +                            (YLOCAL(I,J)-YLOCAL(K,J))**2
                          DIST = SQRT(RSQ)*RAST
                          IF (DIST.GT.DMAX) THEN
                            IMAX1 = I
                            IMAX2 = K
                            DMAX = DIST
                          END IF
 82                     CONTINUE
 80                   CONTINUE
C
C---- If only one peak is left after rejecting weaker peaks, then
C     find centroid of whole spot
C
                      NGOOD = 0
                      DO 67 I = 1,NBITS
                        IF (.NOT.BADPK(I)) NGOOD = NGOOD + 1
 67                   CONTINUE
                      IF (NGOOD.EQ.1) BADSPOT = .TRUE.
C
C     If DMIN is zero, as it will be for the first scan of the centre of the image
C     to determine spot size etc, don't allow any multiple spots
C
                      IF (DMIN.EQ.0.0) BADSPOT = .TRUE.
                      IF (BADSPOT) GOTO 68
C
                      TSUMI = 0.0
                      DO 63 I = 1,NBITS
                        TSUMI = TSUMI + INTLOCAL(I,J)
 63                   CONTINUE
                      TSUMI = MAX(TSUMI,1.0)
C
C---- Work out effective spot size for remaining good peaks
C
                      XDIFF = ABS(XLOCAL(IMAX1,J)-XLOCAL(IMAX2,J))
                      YDIFF = ABS(YLOCAL(IMAX1,J)-YLOCAL(IMAX2,J))
                      TH = ATAN2(YDIFF,XDIFF)
C
C---- All parts are assigned the same size (at present)
C
                      WXSIZE = (IXMAX(J)-IXMIN(J)+1)/
     +                                  (1+(NGOOD-1)*COS(TH))
                      WYSIZE = (IYMAX(J)-IYMIN(J)+1)/
     +                                  (1+(NGOOD-1)*SIN(TH))
C
C---- Test for anisotropy, can arise due to ice rings, reject if true.
C
                      ANISO = WXSIZE/WYSIZE
                      IF ((ANISO.GT.ANISOMAX).OR.
     +                     (ANISO.LT.(1.0/ANISOMAX))) THEN
                        NANISO = NANISO + 1
                        GOTO 88
                      END IF
                      NSPOT = NSPOT - 1
                      DO 66 I = 1,NBITS
                        IF (BADPK(I)) GOTO 66
C
                        NSPOT = NSPOT + 1
                        IF (NSPOT.GT.MXSPOT) THEN
                          IERRF = 1
                          WRITE(IOUT,FMT=6100) MXSPOT
                          IF (ONLINE) WRITE(ITOUT,FMT=6100) MXSPOT
                          NSPOT = NSPOT - 1
                          RETURN
                        END IF
                        XSPOT(NSPOT) = RAST*XLOCAL(I,J)
                        YSPOT(NSPOT) = RAST*YLOCAL(I,J)
                        IX1 = NINT(XLOCAL(I,J))
                        IY1 = NINT(YLOCAL(I,J))
c   Calculate resolution
                        CALL CRESOL(IX1,IY1,DISTANCE,TWOTHETA,
     +                              WAVE,RESOL)
                        RESOLU(NSPOT) = RESOL
C
C---- Divide total intensity between the individual bits
C
                        FRAC = FLOAT(INTLOCAL(I,J))/TSUMI
                        INTBIT = NINT(FINT*FRAC)
                        INSPOT(NSPOT) = INTBIT
C
C---- In calculation of SD, assume number of pixels is total number for
C     entire "spot" divided by number of individual real spots.
C     Factor 2 because INTBIT is already background subtracted
C
                        ISDSPOT(NSPOT) = NINT(SQRT(GAIN*(INTBIT +
     $                     2*NPIXCENT(J)*BKG(J)/FLOAT(NGOOD))))
C
C---- This radius is not strictly correct as all local maxima are assigned the
C     same radius but this is not used for anything crucial and error will not
C     be large
C
                        RSPOT(NSPOT) = R1
C
C---- Aportion the number of pixels on basis of intensity also.
C
                        NPIXSP = MAX(NINT(NPIXCENT(J)*FRAC),1)
                        NPIX(NSPOT) = NPIXSP
CAL                        IWXSPOT(NSPOT) = (IXMAX(J)-IXMIN(J)+1)
CAL                        IWYSPOT(NSPOT) = (IYMAX(J)-IYMIN(J)+1)
                        IWXSPOT(NSPOT) = MAX(WXSIZE,1.0)
                        IWYSPOT(NSPOT) = MAX(WYSIZE,1.0)
                        NSPK(NSPOT) = 1
                        IF (DEBUG(63)) THEN
                          WRITE(IOUT,FMT=6053) I,NSPOT,XSPOT(NSPOT),
     +                    YSPOT(NSPOT),INTBIT,ISDSPOT(NSPOT),
     +                    R1,NPIX(NSPOT),IWXSPOT(NSPOT),
     +                    IWYSPOT(NSPOT),NSPK(NSPOT),NGOOD,DMAX,
     +                    WXSIZE,WYSIZE
                          IF (ONLINE) WRITE(ITOUT,FMT=6053) I,NSPOT,
     +                    XSPOT(NSPOT),
     +                    YSPOT(NSPOT),INTBIT,ISDSPOT(NSPOT),
     +                    R1,NPIX(NSPOT),IWXSPOT(NSPOT),
     +                    IWYSPOT(NSPOT),NSPK(NSPOT),NGOOD,DMAX,
     +                    WXSIZE,WYSIZE
                        END IF
 6053                   FORMAT(1X,'Peak',I3,' stored as spot',I5,
     +                  ' centroid',
     +                  2F7.2,' Int and sd',2I7,' radius',I6,
     +                  ' pixels',I5,' width in X and Y (pix)',
     +                  2I4,' number of peaks',I4,' ngood',I3,
     +                  ' dmax',F6.1,'  x,y',2F5.1)
 66                   CONTINUE
                    END IF
C
C---- If only a single peak, or if multiple peaks have been rejected because
C     they are too close, store centroid etc
C
 68                 IF (BADSPOT.OR.(NBITS.EQ.1)) THEN
                      XSPOT(NSPOT) = SX
                      YSPOT(NSPOT) = SY
                      INSPOT(NSPOT) = NINT(FINT)
                      NPIXSP = NPIXCENT(J)
                      ISDSPOT(NSPOT) = NINT(SQRT(GAIN*(FINT + 
     $                       2*NPIXSP*BKG(J))))
C
C---- rms variation in spot
C
                      AVGSP = FINT/FLOAT(NPIXSP)
                      RMSSP = SQRT(SUMISQ(J)/FLOAT(NPIXSP) - AVGSP**2)
                      RSPOT(NSPOT) = R1
                      NPIX(NSPOT) = NPIXSP
                      IWXSPOT(NSPOT) = (IXMAX(J)-IXMIN(J)+1)
                      IWYSPOT(NSPOT) = (IYMAX(J)-IYMIN(J)+1)
                      NSPK(NSPOT) = MAX(NPEAKS(J),1)
                      RESOLU(NSPOT) = RESOL

                      IF (BADSPOT.AND.DEBUG(63)) THEN
                        WRITE(IOUT,FMT=6054)
                        IF (ONLINE) WRITE(ITOUT,FMT=6054)
                      END IF
 6054                 FORMAT(1X,'Multiple spot treated as single')
C
C---- If multiple spot treated a single, apply rms variation test. This is to
C     try to eliminate "spots" found on the arc due to the cryoloop.
C
                      IF (BADSPOT) THEN
                        IF (RMSSP.LT.RMSFAC*SQRT(GAIN*BKG(J))) THEN
                          IF (DEBUG(63)) THEN
                            WRITE(IOUT,FMT=6055) RMSSP
                            IF (ONLINE) WRITE(ITOUT,FMT=6055) RMSSP
 6055                       FORMAT(1X,'Rejected, rms only',F6.1)
                          END IF
                          NSPOT = NSPOT - 1
                          GOTO 69
                        END IF
                      END IF

                      IF (DEBUG(63)) THEN
                        WRITE(IOUT,FMT=6056) NSPOT,SX,SY,NINT(FINT),
     +                   ISDSPOT(NSPOT),R1,NPIXSP,IWXSPOT(NSPOT),
     +                   IWYSPOT(NSPOT),NSPK(NSPOT),RESOLU(NSPOT)
                        IF (ONLINE) WRITE(ITOUT,FMT=6056) NSPOT,
     +                   SX,SY,NINT(FINT),
     +                   ISDSPOT(NSPOT),R1,NPIXSP,IWXSPOT(NSPOT),
     +                   IWYSPOT(NSPOT),NSPK(NSPOT),RESOLU(NSPOT)
 6056                   FORMAT(1X,'Stored as spot',I5,' centroid',
     +                  2F7.2,' Int and sd',2I7,' radius',I6,
     +                  ' pixels',I5,' width in X and Y (pix)',
     +                  2I4,' number of peaks',I4,' resolution: ',F7.2)
                      END IF
                    END IF
C
C---- Count number of spots rejected because too many peaks
C
                    IF (NBITS.GT.MAXPKS) THEN
                      NMULTPKS = NMULTPKS + 1
                      IF (DEBUG(63)) THEN
                        WRITE(IOUT,FMT=6058) NBITS,MAXPKS
                        IF (ONLINE) WRITE(ITOUT,FMT=6058) NBITS,MAXPKS
 6058                   FORMAT(1X,'Rejected, number of peaks (',I3,')'
     +                  ,'greater than max allowed (',I4,')',
     +                  ' (Set by keyword FINDSPOTS MAXPEAKS)')
                      END IF
                      GOTO 69
                    END IF
C
C---- Calculate statistics on spot sizes and number of peaks
C
                    IBINX = MIN(IWXSPOT(NSPOT),50)
                    IBINY = MIN(IWYSPOT(NSPOT),50)
                    IBINPKS = MIN(NSPK(NSPOT),50)
                    NXHIST(IBINX) = NXHIST(IBINX) + 1
                    NYHIST(IBINY) = NYHIST(IBINY) + 1
                    NPKSHIST(IBINPKS) = NPKSHIST(IBINPKS) + 1
 69                 CONTINUE
                     ENDIF
                ELSE
                  IF (DEBUG(63)) THEN
                    WRITE(IOUT,FMT=6084) ICENT,J
                    IF (ONLINE) WRITE(ITOUT,FMT=6084) ICENT,J
 6084              FORMAT(1X,'Finished spot',I4,' slot',I4,
     +                    ' rejected  by area exclusion')
                  END IF
                ENDIF
              ELSE IF (NPIXCENT(J).LT.MINPIX) THEN
C
C---- Too few pixels, give error message if DEBUG on
C
                NTOOFEWPIX = NTOOFEWPIX + 1
                IF (DEBUG(63)) THEN
                  WRITE(IOUT,FMT=6086) ICENT,J,NPIXCENT(J),IFLAG(J)
                  IF (ONLINE) WRITE(ITOUT,FMT=6086) ICENT,J,
     +                         NPIXCENT(J),IFLAG(J)
 6086             FORMAT(1X,'Finished spot',I4,' slot',I4,
     +                    ' rejected, numpix',I4,'  flag',I2)
                END IF
C
C---- Spot too large in Y
C
              ELSE IF (IFLAG(J).EQ.2) THEN
                NTOOWIDE = NTOOWIDE + 1
                IF (DEBUG(63)) THEN
                  WRITE(IOUT,FMT=6087) ICENT,J,IFLAG(J),MAXYEXT
                  IF (ONLINE) WRITE(ITOUT,FMT=6087) ICENT,J,
     +                         IFLAG(J),MAXYEXT
 6087             FORMAT(1X,'Finished spot',I4,' slot',I4,
     +           '  flag',I2,'  rejected as wider than',I5,' pixels')
                END IF

              ENDIF

 88           NPIXCENT(J) = 0
              NPEAKS(J) = 0
              IFINA(ICENT) = 1
              NFIN = NFIN + 1
C     
C
C
           ENDIF
C
C---- End of loop over active spots
C
 90       ENDDO
C
C---- Need to reset pointers into slots to allow for spots that have finished
C     (Note in previous versions this code was wrong (AGWL 5/9/04)
C
          IF (NFIN.GT.0) THEN
            K = 0
            DO 92 I = 1,NCENT
              IF (IFINA(I).EQ.0) THEN
                K = K + 1
                IPT(K) = IPT(I)
              END IF
 92         CONTINUE
          END IF
C
C---- Update number of active spots
C
 98       NCENT = NCENT - NFIN
        ENDIF
C
C---- Reset IYBEGTMP,IYENDTMP
C
        DO 99 I = 1,MXCENT
          IYBEGTMP(I) = 999999
          IYENDTMP(I) = 0
 99     CONTINUE
C
C---- End of loop of IXCT (strips)
C
 100  ENDDO
C
C---- Print stats on spot sizes if PICKSPOTS debug is on
C
      IF (DEBUG(62)) THEN
        WRITE (IOUT,6120) (NXHIST(I),I=1,50)
        IF (ONLINE) WRITE (ITOUT,6120) (NXHIST(I),I=1,50)
 6120   FORMAT(/,/,1X,'Spot size in X',/,(15I5/))
        WRITE (IOUT,6122) (NYHIST(I),I=1,50)
        IF (ONLINE) WRITE (ITOUT,6122) (NYHIST(I),I=1,50)
 6122   FORMAT(/,1X,'Spot size in Y',/,(15I5/))
        WRITE (IOUT,6123) (NPKSHIST(I),I=1,50)
        IF (ONLINE) WRITE (ITOUT,6123) (NPKSHIST(I),I=1,50)
 6123   FORMAT(/,1X,'Number of spots with 1,2,3, etc peaks',/,(15I5/))
      END IF
C
C---- Get optimal spot size from histogram
C
      CALL HISTO(NXHIST,NPKSHIST,NSIZX)
      CALL HISTO(NYHIST,NPKSHIST,NSIZY)
      IF (NEXCLD.GT.0) THEN
        WRITE (IOUT,6060) NEXCLD
        IF (ONLINE) WRITE (ITOUT,6060) NEXCLD
 6060   FORMAT (1X,'Number of spots excluded from defined areas:',I8)
      ENDIF

      IF (NUMICE.GT.0) THEN
        WRITE (IOUT,6062) NUMICE
        IF (ONLINE) WRITE (ITOUT,6062) NUMICE
 6062   FORMAT(1X,'Number of spots excluded from possible ice rings:'
     +          ,I8)
      ENDIF
      IF (NMULTPKS.GT.0) THEN
        WRITE (IOUT,6064) MAXPKS,NMULTPKS
        IF (ONLINE) WRITE (ITOUT,6064) MAXPKS,NMULTPKS
 6064   FORMAT (1X,'Number of "spots" with more than',I3,
     +              ' distinct peaks:',I8)
      ENDIF
      IF (NREJRES.GT.0) THEN
        WRITE (IOUT,6066) NREJRES
        IF (ONLINE) WRITE (ITOUT,6066) NREJRES
 6066   FORMAT (1X,'Number of spots beyond resolution limit:',I8)
      ENDIF
      IF (NTOOFEWPIX.GT.0) THEN
        WRITE (IOUT,6068) MINPIX,NTOOFEWPIX
        IF (ONLINE) WRITE (ITOUT,6068) MINPIX,NTOOFEWPIX
 6068   FORMAT (1X,'Number of spots with fewer than',I4,' pixels:',I8)
      ENDIF
      IF (NTOOWIDE.GT.0) THEN
        WRITE (IOUT,6067) MAXYEXT,NTOOWIDE
        IF (ONLINE) WRITE (ITOUT,6067) MAXYEXT,NTOOWIDE
 6067   FORMAT (1X,'Number of spots more than',I5,' pixels wide:',I8)
      ENDIF
      IF (NANISO.GT.0) THEN
        WRITE (IOUT,6069) ANISOMAX,NANISO
        IF (ONLINE) WRITE (ITOUT,6069) ANISOMAX,NANISO
 6069   FORMAT (1X,'Number of spots with anisotropy of spot size ',
     +           'more than',F4.1,' :',I8)
      ENDIF
C
C---- sort list of resolutions and write to a file so we can look at them
C
      CALL SORTUP5(NSPOT,RESOLU,IRESOLU)
      ICOUNT = 0
      DO I = 1,NSPOT,1
        IF(RESOLU(IRESOLU(I)).LT.1E-3)ICOUNT = ICOUNT + 1 
      ENDDO
      ICOUNT = ICOUNT + 1
C
C---- only do this if we have some reflections
C
      IF(IRESOLU(ICOUNT).GT.0)THEN
        RESHIGH = RESOLU(IRESOLU(ICOUNT))
        IPTR = ICOUNT+INT(0.05*REAL(NSPOT-ICOUNT))
        RES2SD = RESOLU(IRESOLU(IPTR))
      ELSE
         RESHIGH = 999.9
         RES2SD  = 999.9
      ENDIF
C
C----  End of loop on stripes/rows/Y
C
C
      RETURN
      END
c $Id: fitcir.f,v 1.9 2009/04/29 10:49:48 harry Exp $
      subroutine fitcir(ncirpt, mcirpt, ixycpt, circen, cirrad,rmsres,
     $     mode)
c     =========================================================
c
c  Fit circle to set of points, no variation in yscale
c
c On entry:
c     ncirpt               number of points in list
c     mcirpt               number of accepted points in list (excluding
c                            deleted points)
c     ixycpt(2,ncirpt)     pixel coordinates of points: deleted points
c                            are flagged with ixycrd(1,) = -1000
c
c On exit:
c     circen(2)            coordinates of centre (mm in scanner coordinates)
c     cirrad               radius (mm)
c
c 1. Convert point coordinates from pixels (Yms, Zms) to scanner frame
c     in mm by multiplying by the pixel size & swapping Y,Z to y,x
c
c 2. Fit mm coordinates to circle, NOT allowing for a scale factor in the
c     y direction relative to x
c
c     If x, y are vectors of the measured x & y coordinates, then we can
c     fit a circle, centre (p,q), radius r, with a relative yscale v
c     (ie y*v is the corrected y coordinate in mm). The error vector Eps
c     is given by
c
c     eps = x**2 + y**2 - 2px - 2qy + p**2 + q**2 - r**2
c      ~    ~      ~        ~     ~
c         = Rcalc**2 - r**2
c           ~
c
c         = A s  +  b
c             ~     ~
c
c where   A  =  ( x  y  1 )        s  =    ( -2p                )    
c                 ~  ~  ~          ~       ( -2q                )
c                                          ( p**2 + q**2 - r**2 )
c         b  =  x**2  + y**2             
c         ~     ~
c                                                    ~
c The least squares solution is given by minimizing eps eps
c                                                    ~   ~
c This is a linear least squares in the 3 components of s
c             ~        ~
c     s  = - (AA)**-1  A b
c     ~                  ~
c    ~
c    AA  = ( Sum x**2    Sum x y   Sum x     )
c          ( Sum x y     Sum y**2  Sum y     )
c          ( Sum x       Sum y     Sum 1     )
c    ~
c    Ab  = ( Sum x*(x**2 + y**2)  )
c          ( Sum y*(x**2 + y**2)  )
c          ( Sum (x**2 + y**2)    )
c
      implicit none
c
      integer ncirpt, mcirpt, ixycpt(2,ncirpt)
      real circen(2),cirrad
c
      integer i,j
c
      integer MAXCPT
      parameter (MAXCPT = 1000)
      double precision aa(3,3), ab(3), det, param(3)
      real xc(MAXCPT), yc(MAXCPT),REALX,REALY
      real sumx, sumy, sumx2, sumy2, sumxy, 
     $     sumx2py2, sumxx2py2, sumyx2py2
      real x, y,  rmsres, eps,DELTATHETA,RTWOTHETA,DISTANCE,
     $     XCENMM,YCENMM,COSOME,SINOME
      INTEGER MODE
C     .. MODE = 0 (old-style, either beam or backstop)
C     ..      = 1 beam
C     ..      = 2 backstop 
C     ..      = 3 arc
C     ..      = 5 circle from command line or new GUI
C     ..      = 6 arc from command line or new GUI (may not be necessary)
      integer work1(3), work2(3)
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C&&*&& include  ../inc/fid.f
C
C $Id: fid.f,v 1.7 2016/04/22 14:23:39 andrew Exp $
C
C--- awk generated include file  fid.h
C---- START of include file fid.h
C
C     XCENF,YCENF  Coordinates (in 10 micron units) of the direct beam
C                  position relative to an origin at the position of the
C                  first pixel in the digitised image.(The SCANNER
C                  coordinate frame).
C                  For IP data this comes from the defined
C                  direct beam coordinates, for film data it is the
C                  midpoint of fiducials 1 and 3.
C
C     CCX,CCY      The difference (in 10 micron units) between the
C                  refined position of the direct beam (XCEN,YCEN) and
C                  the ideal direct beam coordinates (XCENF,YCENF),
C                  in the SCANNER coordinate frame.
C                  CCX,CCY are updated in RDIST. They are in "pixels"
C                  rather than mm (but expressed in 10micron units).
C
C     DTOFD        The distance (in 10 micron units) from the crystal
C                  to the detector along a normal to the detector.
C                  For flat, unswung detectors, or swung on a 2 theta arm,
C                  this is the same as CTOFD and XTOFD. It differs for
C                  Vee shaped cassettes. Assigned in START and never changed.
C                  Only actually used in RMAXR for calculating box sizes.
C
C     IOMEGAF      Whether OMEGAF has been set by user, by program, or 
C                  by reading header
C     .. Arrays in common /FID/ ..
      REAL CCOMABC
      INTEGER FSPOS,CCXABC,CCYABC
C     ..
C     .. Scalars in common /FID/ ..
      REAL OMEGAF,OMEGAFD,CCOM,DTOFD,XCENF,YCENF,OMEGAREV
      INTEGER MM,MMDB,NFID,CCX,CCY,IYOFF,LABVIEW,IOMEGAF
      LOGICAL UPDATEOMEGA
C     ..
C     .. Common block /FID/ ..
      COMMON /FID/CCOMABC(3),OMEGAF,OMEGAFD,CCOM,DTOFD,XCENF,YCENF,
     $     FSPOS(4,2),
     +     CCXABC(3),CCYABC(3),MM,MMDB,NFID,CCX,CCY,IYOFF,LABVIEW,
     $     IOMEGAF,OMEGAREV,UPDATEOMEGA
C     ..
C
C     .. Scalars in common /FIDC/ ..
C
      CHARACTER SPOTFILEORIGIN*2,SPOTFILEAXISORDER*2,SWINGAXIS*2
      COMMON /FIDC/ SPOTFILEORIGIN,SPOTFILEAXISORDER,SWINGAXIS
C&&*&& end_include  ../inc/fid.f
C&&*&& include  ../inc/mxdinc.f
C
C $Id: mxdinc.f,v 1.1 2002/05/02 10:47:00 harry Exp $
C
C--- awk generated include file  mxdinc.h
C---- START of include file mxdinc.h
C
C
c common block for mxd routines: various parameters for XDL routines
c
c     base_width    width of base frame
c     base_height   height of base frame
c     men_x,men_y   position of menu area
c     par_x,par_y   position of parameter area
C     

C     IORDER    (R)   Order of the data in the input image 
c                with respect to two local axes ax1, ax2 e.g.
c                (xf, yf) as a number from 1 to 8.
c                    1   +ax1 slow   +ax2 fast    (+xf, +yf)
c                    2   +ax1 slow   -ax2 fast    (+xf, -yf)
c                    3   -ax1 slow   +ax2 fast    (-xf, +yf)
c                    4   -ax1 slow   -ax2 fast    (-xf, -yf)
c                    5   +ax2 slow   +ax1 fast    (+yf, +xf)
c                    6   +ax2 slow   -ax1 fast    (+yf, -xf)
c                    7   -ax2 slow   +ax1 fast    (-yf, +xf)
c                    8   -ax2 slow   -ax1 fast    (-yf, -xf)
c
c
c     JORDER    (R)   Display order with respect to the two
c                local axes (1 to 8) along the X-windows
c                axes X horizontal (left to right), Y vertical 
c                (top to bottom ) with origin at top left
c                1  +ax1 X (horiz)   +ax2 Y (vert)   (+xf, +yf)
c                2  +ax1 X (horiz)   -ax2 Y (vert)   (+xf, -yf)
c                3  -ax1 X (horiz)   +ax2 Y (vert)   (-xf, +yf)
c                4  -ax1 X (horiz)   -ax2 Y (vert)   (-xf, -yf)
c                5  +ax2 X (horiz)   +ax1 Y (vert)   (+yf, +xf)
c                6  +ax2 X (horiz)   -ax1 Y (vert)   (+yf, -xf)
c                7  -ax2 X (horiz)   +ax1 Y (vert)   (-yf, +xf)
c                8  -ax2 X (horiz)   -ax1 Y (vert)   (-yf, -xf)
c                    
c                    (2 was standard for Laue programs)
c
c     nxp_cmp       number of pixels compressed to 1 in horizontal
c                   display direction
c     nyp_cmp       number of pixels compressed to 1 in vertical
c                   display direction
c     nxdpx         number of horizontal pixels in displayed image
c     nydpx         number of vertical pixels in displayed image
c     img_horiz     image direction for horizontal display (=1 fast, 2 slow)
c     img_vert      image direction for vertical display   (=1 fast, 2 slow)
c     img_map(4)    mapping of image to display
c                    imgmap(1)   1st point on fast axis (Yms)
c                    imgmap(2)   1st point on slow axis (Zms)
c                    imgmap(3)   increment on fast axis
c                    imgmap(4)   increment on slow
c     img_x,img_y   x, y position of image
c     men_x, men_y  x, y position of menu
c     par_x, par_y  x, y position of parameter table
c     io_x, io_y    x, y position of IO area
c     not_x, not_y    x, y position of notice area (parameter table
c                     with no values)
c     pmn_x, pmn_y  x, y position of popup abort menu
c     ppb_x, ppb_y  x, y position of popup progress bar
c     busy_x, busy_y x, y position of busy window
c     img_width,img_height   width, height of image window
c     men_width, men_height  width, height of menu window  
c     par_width, par_height  width, height of parameter window
c     io_width, io_height    width, height of IO window
c     not_width, not_height  width, height of notice area
c     pmn_width, pmn_height  width, height of Abort menu
c     ppb_width              width of progress bar
c     busy_width, busy_height  width, height of busy box
c     sub_process    .true. if program is sub-process of eg clips, .false.
c                    if standalone
c
C     IFTYPE      1 = unsigned byte data
C                 2 = unsigned two-byte data (i2)
C                 3 = signed integer data
C                 4 = 'squashed i2' data (if Intensity>32767 
C                    store as 65536-Intensity/8)
      INTEGER BASE_WIDTH,BASE_HEIGHT,
     $     IMAGE_ORDER,JIMAGE_ORDER,NXP_CMP,NYP_CMP,
     $     NXDPX,NYDPX,
     $     IMG_HORIZ,IMG_VERT,IMG_MAP(4),
     $     IMG_X,IMG_Y,MEN_X,MEN_Y,PAR_X,PAR_Y,IO_X,IO_Y,
     $     NOT_X,NOT_Y,PMN_X, PMN_Y,PPB_X, PPB_Y, BUSY_X, BUSY_Y,
     $     BUSY_Y2,IFTYPE
      INTEGER IMG_WIDTH, IMG_HEIGHT, MEN_WIDTH, MEN_HEIGHT,
     $     PAR_WIDTH, PAR_HEIGHT, IO_WIDTH, IO_HEIGHT,
     $     NOT_WIDTH, NOT_HEIGHT, PMN_WIDTH, PMN_HEIGHT,
     $     PPB_WIDTH, BUSY_WIDTH, BUSY_HEIGHT
      LOGICAL SUB_PROCESS, BLANK
C

c  DON'T forget to declare function xdlstr as integer
      INTEGER XDLSTR
      EXTERNAL XDLSTR

c
c     ivhbas        view object handle for base frame
c     ivhimg        view object handle for image
c     ivhpar        view object handle for parameter table
c     ivhmen        view object handle for menu
c     ivhio         view object handle for io area
c     ivhio2        view object handle for second io area (pick option)
c     ivhio3        view object handle for third io area (output)
c     ivhnot        view object handle for notice area (parameter table)
c     ivhpmn        view object handle for popup wait menu
c     ivhppb        view object handle for popup progress bar
c     ivhblank      view object handle for blank object
c     ivhbusy       view object handle for busy object
c     ivhbusy2      view object handle for second (2 line) busy object
      INTEGER IVHBAS, IVHIMG, IVHPAR, IVHMEN, IVHIO, IVHNOT, IVHPMN,
     $     IVHPPB, IVHBLANK, IVHBUSY, IVHIO2, IVHBUSY2, IVHIO3
      PARAMETER (IVHBAS=1, IVHIMG=2, IVHPAR=3, IVHMEN=4, IVHIO=5,
     $     IVHNOT=6, IVHPMN=7, IVHPPB=8, IVHBLANK=9, IVHBUSY=10,
     $     IVHIO2=11, IVHBUSY2=12, IVHIO3=13)

c  Border  boundary between windows
      INTEGER BORDER
      PARAMETER (BORDER = 4)

c     icset   colour set number
      INTEGER ICSET
      PARAMETER (ICSET=1)
c
c     iord    axis order of image
c             = 1  xf slow, yf fast
      INTEGER IORD
      PARAMETER (IORD = 1)
c
c     minw,minh   minimum width and height for image display object
      INTEGER MINW,MINH
      PARAMETER (MINW=0, MINH=0)
c
c     ixopix, iyopix      pixel origin of displayed part
      INTEGER IXOPIX,IYOPIX
      PARAMETER (IXOPIX=1, IYOPIX=1)
c
c     ibg     background menu, =0 for none
      INTEGER IBG
      PARAMETER (IBG=0)
c
c     iovly   overlay option
      INTEGER IOVLY
      PARAMETER (IOVLY=1)
c
c     max_pixel   maximum number of pixels to use for image display:
c                 this will be used to control possible compression
c                 of the image
      INTEGER MAX_PIXEL
      PARAMETER (MAX_PIXEL = 800)
c  Image stuff
