c
c     mes_colr    colour for measure crosses
      INTEGER MES_COLR
      PARAMETER (MES_COLR=1)

c   Vertical Crosses
c     cross_iovl    overlay number for circles
c     cross_symb   symbol for centre
      INTEGER CROSS_IOVL, CROSS_SYMB
      PARAMETER (CROSS_IOVL=2, CROSS_SYMB=3)
c  Boxes
c     box_iovl    overlay number for boxes
c     box_symb   symbol for centre
      INTEGER BOX_IOVL, BOX_SYMB, BOX_VEC
      PARAMETER (BOX_VEC=2,BOX_IOVL=2, BOX_SYMB=13)
c  Circles
c     CIRC_iovl    overlay number for circles
c     CIRC_symb   symbol for centre
      INTEGER CIRC_IOVL, CIRC_VEC
      PARAMETER (CIRC_VEC=5,CIRC_IOVL=2)
c   Crosses
c     cross_iovl    overlay number for circles
c     cross_symb   symbol for centre
      INTEGER XCROSS_IOVL, XCROSS_SYMB
      PARAMETER (XCROSS_IOVL=2, XCROSS_SYMB=13)
C
C---- common block last of all
C
      COMMON /MXDCMI/ BASE_WIDTH,BASE_HEIGHT,
     $     IMAGE_ORDER,JIMAGE_ORDER,NXP_CMP,NYP_CMP,
     $     NXDPX,NYDPX,
     $     IMG_HORIZ,IMG_VERT,IMG_MAP,
     $     IMG_X,IMG_Y,MEN_X,MEN_Y,PAR_X,PAR_Y,IO_X,IO_Y,
     $     NOT_X,NOT_Y,PMN_X, PMN_Y,PPB_X, PPB_Y, BUSY_X, BUSY_Y,
     $     BUSY_Y2, IFTYPE,
     $     IMG_WIDTH, IMG_HEIGHT, MEN_WIDTH, MEN_HEIGHT,
     $     PAR_WIDTH, PAR_HEIGHT, IO_WIDTH, IO_HEIGHT,
     $     NOT_WIDTH, NOT_HEIGHT, PMN_WIDTH, PMN_HEIGHT,
     $     PPB_WIDTH, BUSY_WIDTH, BUSY_HEIGHT,
     $     SUB_PROCESS,BLANK,DISP_IMG,DISP_PAR,DISP_MENU,
     $     DISP_IO,DISP_IO2,DISP_IO3,DISP_NOT
  
C&&*&& end_include  ../inc/mxdinc.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C     ..
C     .. Data
C     ..
C     .. Equivalences ..
      EQUIVALENCE (RBUFF,IBUFF)
      EQUIVALENCE (IBUFFP,RBUFFP)
CAL      EQUIVALENCE (RBUFFR(1),IBUFFR(7))
      EQUIVALENCE (RBUFFR(1),IBUFFR(7))
C     ..
      SAVE
C
C
      THIS = 'GENERATE'
      INDENT = 3
C
      XLIMIT = LIMIT
      IR1 = 2*IPAD + 1
      IR2 = 2*IPAD + 2
      IR2 = 30*IPAD + 30
C
      ALLFOUND = .FALSE.
C
C
      DO 10 I = 1,NDETREF
        FOUND(I) = .FALSE.
   10 CONTINUE
C
C
      DO 20 I = 7,18
        IBUFFR(I) = -9999
   20 CONTINUE
C
      IF (BRIEF) WRITE(IBRIEF,FMT=6019)
 6019 FORMAT(1X,'Generating reflection list for this image')
      IF (DEBUG(32)) THEN
        WRITE(IOUT,FMT=6020) MODE,POSTREF,IPACKHEAD,2.0*ETA/DTOR,
     +                   2.0*DIVH/DTOR,2.0*DIVV/DTOR,DELPHI,NRS,
     +                   MINDTX,MINDTY,PHIBEG,PHIEND,DSTMAX,DSTMAXS,
     +                   GWRITE,UPDATE,NLATTICE,ILATTICE,IOVWORK,
     +                   IRECMULT,XCEN,YCEN
        IF (ONLINE) WRITE(ITOUT,FMT=6020) MODE,POSTREF,IPACKHEAD,
     +          2.0*ETA/DTOR,2.0*DIVH/DTOR,2.0*DIVV/DTOR,DELPHI,NRS,
     +                   MINDTX,MINDTY,PHIBEG,PHIEND,DSTMAX,DSTMAXS,
     +                   GWRITE,UPDATE,NLATTICE,ILATTICE,IOVWORK,
     +                   IRECMULT,XCEN,YCEN
 6020   FORMAT(//1X,'In GENERATE, MODE=',I2,/,1X,
     +              'POSTREF=',L1,' IPACKHEAD',I6,
     +          ' ETA,DIVH,DIVV',3F7.3,' DELPHI',3F7.2,' NRS',I3,
     +          /,1X,'MINDTX,MINDTY',2I8,'  Phibeg,end',2F8.3,/,1X,
     +          'DSTMAX,DSTMAXS',2F12.6,/,1X,'GWRITE ',L1,
     +          '  UPDATE ',L1,' NLATTICE=',I2,' ILATTICE=',I2,
     +          ' IOVWORK',I2,' IRECMULT=',I2,/,1X,'Beam coords XCEN,',
     +          ' YCEN',2F12.2)
      END IF
C

        IPACKHEAD = IPACKREC
        IF (DEBUG(32)) THEN
          WRITE(IOUT,FMT=6024) IPACKHEAD,IPACKREC
 6024 FORMAT(1X,'Current IPACKHEAD, IPACKREC',2I6)
          IF (ONLINE) WRITE(ITOUT,FMT=6024) IPACKHEAD,IPACKREC
        END IF
C
        IF (MODE.EQ.2) GOTO 30
C
C
C---- Store AMAT, DELPHI, ETA, DIVH, DIVV for the
C     PACK header (not genfile header)
C
        IBUFFP(1) = ID
        RBUFFP(4) = PHIBEG
        RBUFFP(5) = PHIEND
        IBUFFP(6) = NFGEN
C
C---- Store AMAT in positions 25-33
        IPNT = 24
C
C
        DO 24 J = 1,3
          DO 22 I = 1,3
            IPNT = IPNT + 1
            RBUFFP(IPNT) = AMAT(I,J)
 22       CONTINUE
 24     CONTINUE
C
C---- Store DELPHI in positions 34-36
C
        DO 26 I = 1,3
          IPNT = IPNT + 1
          RBUFFP(IPNT) = DELPHI(I)
 26     CONTINUE
C
C---- Store ETA, DIVH, DIVV  (in degrees) in positions 37-39
C
         RBUFFP(37) = 2*ETA/DTOR
         RBUFFP(38) = 2*DIVH/DTOR
         RBUFFP(39) = 2*DIVV/DTOR
C
C---- Must write pack header even though we don't know number
C     of reflections because we want to write reflection records.
C
C---- Print for program flow
C
        CALLED = 'QWRITE'
        COMMENT = 'to write pack header '
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
        CALL QWRITE(IUNIT,IBUFFP,180)
        IPACKREC = IPACKHEAD + 5
C
C
C---- Update variables changed in CONVOLUTE option if flag set, or if
C     wavelength has been changed as this is ONLY stored in the file header
C     and not in the pack header
C
        IF (UPDATE) THEN
          IPNT = 22
C
C---- Print for program flow
C
          CALLED = 'QSEEK,QREAD,QWRITE'
          COMMENT = 'to update header for missets, diveregence, mosaic'
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
C---- Read generate file header
C
C          ***************************
          CALL QSEEK(IUNIT,1,1,36)
          CALL QREADI(IUNIT,IBUFF,180,IERR)
C          ***************************
C
C
C---- Convert to degrees for generate file
C
          RBUFF(51) = 2*DIVH/DTOR
          RBUFF(52) = 2*DIVV/DTOR
          RBUFF(63) = WAVE
          RBUFF(65) = 2*ETA/DTOR
C
C---- Always update missetting angles
C
          IPNT = 31
C
C
          DO 28 I = 1,3
            IPNT = IPNT + 1
            RBUFF(IPNT) = DELPHI(I)
 28       CONTINUE
C
C---- Write out new header
C
C            ***********************
          CALL QSEEK(IUNIT,1,1,36)
          CALL QWRITE(IUNIT,IBUFF,720)
C            ***********************
        END IF
C
C
 30     IF (.NOT.GWRITE) RETURN
C
C---- Headers (genfile or pack) dealt with, now do reflections
C
C---- Assign resolution limit, mosaic spread and divergence. If POSTREF
C     is being used, then use values from common block, which for the
C     first pack will be those from the genfile header, but for subsequent
C     packs will be those from the postrefinement. Otherwise use values
C     just written to genfile header
C
C
C---- Set DSTMAX to original value(as it can be changed by CONVOLUTE)
C
          DSTMAX = DSTMAXS
C
C---- Calculate the reciprocal sphere radius DSTPL - corresponding to
C     a slightly higher resolution to be used in checking overlaps
C     on the outside of the picture
C
          DELR = MAX(MINDTX,MINDTY)*2.0
          THETA = ASIN(DSTMAX/2.0)
          T = TAN(2.0*THETA)
C
C
C
          IF (VEE) THEN
C
C---- Vee cassette
C
            RPLUS = 2.0*XTOFD*T/ (SQRT(3.0)+T) + DELR
            THPLUS = ATAN(SQRT(3.0)/ (2.0*XTOFD/RPLUS-1.0))*0.5
          ELSE
C
C---- Flat cassette
C
            RPLUS = XTOFD*T + DELR
            THPLUS = ATAN(RPLUS/XTOFD)*0.5
          END IF
C
C
          DSTPL = SIN(THPLUS)*2.0
          DSTPL2 = DSTPL*DSTPL
C
C---- Initialise RMC matrix - for the X and Y missetting angles.
C     Rotation about x and then y
C      RMC = PHIY . PHIX
C
          SX = SIN(DELPHI(1)*DTOR)
          SY = SIN(DELPHI(2)*DTOR)
          CX = COS(DELPHI(1)*DTOR)
          CY = COS(DELPHI(2)*DTOR)
C
          RMC(1,1) = CY
          RMC(1,2) = SX*SY
          RMC(1,3) = CX*SY

          RMC(2,1) = 0.0
          RMC(2,2) = CX
          RMC(2,3) = -SX
          RMC(3,1) = -SY
          RMC(3,2) = SX*CY
          RMC(3,3) = CX*CY
          NSPOT = 0
C
C
          IF (DEBUG(32)) THEN
            X = 2.0/DTOR
            WRITE (IOUT,FMT=6000) ETA*X,DIVH*X,DIVV*X,XTOFD,WAVE,
     +        DELPHI,DSTMAX,DSTPL,ILATTICE
            IF (ONLINE) WRITE (ITOUT,FMT=6000) ETA*X,DIVH*X,DIVV*X,
     +          XTOFD,WAVE,DELPHI,DSTMAX,DSTPL,ILATTICE
          END IF
C
C---- Calculate reflections present
C
          MODERK = 0
C
C---- Print for program flow
C
          CALLED = 'REEK'
          COMMENT = 'with MODE=0'
          IF (DEBUG(99))  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C              ****
#ifdef MOSFLM_CPP_PREDICT
C---- Experimental GENERATE path: C++ osc PREDICT (PHASE_C_SPLICE.md).
          CALL PREDICT_CPP_FROM_COMMON(MODERK, NREFLS,
     +         IHG, IKG, ILG, XG, YG, PHIG, PHIWG, IMG, NSPOT)
#else
          CALL REEK(ITEMP,MODERK,ILATTICE)
#endif
C              ****
C
C---- Check for overlapping reflexions
C
          MODEOVLP = 0
C              *******
          IF (.NOT.LOVERLAP) THEN
C
C---- Print for program flow
C
            CALLED = 'OVERLAP'
            COMMENT = 'with MODE=0'
            IF (DEBUG(99))  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
            CALL OVERLAP(MODEOVLP)
          END IF
C              *******
C
C---- Save number of reflections in primary lattice
C
          NSPOTSAVE = NSPOT
C
C---- If allowing for multiple lattices, generate the reflection lists for
C     all the other lattices being considered now.
C
          IF (MODE.EQ.2) GOTO 56
          IF ((NLATTICE.LT.2).OR.(IOVWORK.LT.1)) GOTO 56
C
          IF (DEBUG(32)) THEN
            WRITE(IOUT,FMT=6026) IOVWORK,(IOVLATTICE(I),
     +                     ACTIVELATT(IOVLATTICE(I)),I=1,IOVWORK)
            IF (ONLINE) WRITE(ItOUT,FMT=6026) IOVWORK,(IOVLATTICE(I),
     +                     ACTIVELATT(IOVLATTICE(I)),I=1,IOVWORK)
 6026       FORMAT(/,1X,'Looping over ',I3,' lattices',/,1X,
     +              'Lattice number and active flag',5(I3,l2,4X))
          END IF
C
          DO 40 I = 1,IOVWORK
C
C---- First get the lattice number for this lattice
C
            ILATT = IOVLATTICE(I)
C
C---- Check that this lattice is still "active" (ie not deleted)
C
            IF (.NOT.ACTIVELATT(ILATT)) GOTO 40
C
C---- Now get the current "best" solution for this lattice
C
            ISOL = BESTSOLAR(ILATT)
C
C---- Must trap case of a batch job that does not include indexing,
c
C     so that ISOL has never been set
C
            IF (ISOL.EQ.0) ISOL = 1
C
C---- Now transfer the A matrix for this solution and lattice
C
            DO J =1,3
              DO K =1,3
                AMAT(J,K) = CRYSTALUBREF(J,K,ISOL,ILATT)
              ENDDO
            ENDDO
C
            IF (DEBUG(32)) THEN
              WRITE(IOUT,FMT=6003) ILATT,ISOL,NSPOT,NSPOTSAVE,
     +                             ((AMAT(K,J),J=1,3),K=1,3)
              IF (ONLINE) WRITE(ITOUT,FMT=6003) ILATT,ISOL,NSPOT,
     +                             NSPOTSAVE,((AMAT(K,J),J=1,3),K=1,3)
 6003         FORMAT(/,1X,'In GENERATE, calling REEK for lattice',I2,
     +        '  solution',I3,/,1X,'Current',
     +        ' total number of spots',I6,' number for first lattice',
     +        I6,/,1X,'AMAT:',/,3(3F12.8,/))
            END IF
C
C---- Now call REEK with MODE=3 so that only reflection indices
C     and coordinates are stored for this lattice
C
            MODERK = 3
C
C---- Print for program flow
C
            CALLED = 'REEK'
            COMMENT = 'with MODE=3, multiple lattices'
            IF (DEBUG(99))  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C           **************************
            CALL REEK(ITEMP,MODERK,ILATT)
C           **************************
C
 40       CONTINUE
C
C---- All lattices have been generated, now need to flag those
C     reflections in the main lattice that are overlapped by other
C     lattices
C
          MODEOVLP = 1
C              *******
C
C---- Print for program flow
C
          CALLED = 'OVERLAP'
          COMMENT = 'with MODE=1 multiple lattices'
          IF (DEBUG(99))  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL OVERLAP(MODEOVLP)
C              *******
C
C---- Restore the original AMAT
C
          ISOL = BESTSOLAR(ILATTICE)
          DO J =1,3
            DO K =1,3
              AMAT(J,K) = CRYSTALUBREF(J,K,ISOL,ILATTICE)
            ENDDO
          ENDDO
          IF (DEBUG(32)) THEN
            WRITE(IOUT,FMT=6005)((AMAT(K,J),J=1,3),K=1,3)
            IF (ONLINE) WRITE(ITOUT,FMT=6005)((AMAT(K,J),J=1,3),K=1,3)
 6005       FORMAT(/,1X,'In GENERATE, restored AMAT:',/,3(3F12.8,/))
          END IF


C
C---- Reset the number of spots to those for main lattice only
C

C
 56           NSPOT = NSPOTSAVE
              MSPOT = 0
              NFIRST = 1
              NFOUND = 0
              NFULLF = 0
              NPAR = 0
              NFULL = 0
              DO 58 I = 1,100
                NPART(I) = 0
 58           CONTINUE
              NWIDE = 0
              NOVRLAP = 0
              NLATTOVRLAP = 0
              NOUTSIDE = 0
              NBADRES = 0
              NINCUSP = 0
              IWMAX = 0
C
C---- Position generate file ready for writing reflection list
C

C                  ************************
              IF (MODE.NE.2) THEN
C
C---- Print for program flow
C
                CALLED = 'QSEEK'
                COMMENT = 'Position generate file for writing refls'
                IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                CALL QSEEK(IUNIT,IPACKREC,1,36)
              END IF
C                  ************************
C
C---- Don't need to check for refinement reflections if NRS=0 or if
C     MODE=3
C
              IF ((NRS.EQ.0).OR.(MODE.EQ.3)) 
     $             ALLFOUND = .TRUE.
C
C
C---- Set length of record depending on number of overlapping lattices
C     (IRECMULT assigned in START)
C
              NBYTES = 36*IRECMULT
C
              DO 130 I = 1,NSPOT
                IR = IRG(I)
                IM = IMG(I)
C
C---- Do not write reflections outside dstar or X,Y limits, or within cusp
C     (but with rlp still cutting sphere)
C
                IF(IR.EQ.1)NOUTSIDE = NOUTSIDE + 1
                IF(IR.EQ.4)NBADRES = NBADRES + 1
                IF(IR.EQ.10)NINCUSP = NINCUSP + 1
                IF (IR.NE.10 .AND. IR.NE.4 .AND. IR.NE.1) THEN
                  MSPOT = MSPOT + 1
                  IF (IM.EQ.0) NFULL = NFULL + 1
                  IF (IR.EQ.2) NOVRLAP = NOVRLAP + 1
                  IF (IR.EQ.5) NLATTOVRLAP = NLATTOVRLAP + 1
C
C---- Count number of reflections with various widths
C
                  IF (IR.GE.IR1) THEN
                    IWIDTH = IR/IPAD - 1
                    IF (IWIDTH.GT.IPAD) IWIDTH = IPAD
                    IWMAX = MAX(IWMAX,IWIDTH)
                    NPART(IWIDTH) = NPART(IWIDTH) + 1
                  END IF
C
C---- Too wide in phi
C
                  IF (IR.EQ.3) NWIDE = NWIDE + 1
C
                  JJH(1) = IHG(I)
                  JJH(2) = IKG(I)
                  JJH(3) = ILG(I)
                  DO 60 J = 1,3
                    IBUFFR(J) = JJH(J)
   60             CONTINUE
C
C---- Test this reflection against those used in CENTRS refinement,
C     and update generate file pointer RRS. Note that the reflections
C     will not necessarily be generated in the same order !
C
                  IF (.NOT.ALLFOUND) THEN
                    IF (ABS(XG(I)).LE.XLIMIT .AND.
     +                  ABS(YG(I)).LE.XLIMIT) THEN
C
C
                      DO 80 K = NFIRST,NRS
                        IF (.NOT.FOUND(K)) THEN
C
C
                          DO 70 J = 1,3
                            IF (JJH(J).NE.IHKLR(J,K)) GO TO 80
   70                     CONTINUE
C
C
                          GO TO 90
                        END IF
   80                 CONTINUE
                      GO TO 120
C
C---- This is a refinement reflection, update pointer
C
   90                 FOUND(K) = .TRUE.
                      NFOUND = NFOUND + 1
                      RRS(K) = MSPOT
C
C---- Count number of fulls found
C
                      IF (IM.EQ.0) NFULLF = NFULLF + 1
C
C---- Flag any partials with negative record number
C
                      IF (IM.NE.0) THEN
                        NPAR = NPAR + 1
                        RRS(K) = -RRS(K)
                      END IF
C
C---- Find first reflection in list not yet located
C
                      DO 100 IJ = NFIRST,NRS
                        IF (.NOT.FOUND(IJ)) GO TO 110
  100                 CONTINUE
C
C---- all  remaining reflections must have been found
C
                      ALLFOUND = .TRUE.
                      GO TO 120
  110                 NFIRST = IJ
                    END IF

                  END IF
C
C
  120             IBUFFR(4) = IMG(I)
C
C---- Following restricts IR to max value of 32767.
C
                  IBUFFR(5) = IRG(I)
                  RBUFFR(1) = XG(I)
                  RBUFFR(2) = YG(I)
                  RBUFFR(3) = PHIG(I)
                  RBUFFR(4) = PHIWG(I)
                  RBUFFR(5) = FRACG(I)
                  PHIG(MSPOT) = PHIG(I)
                  PHIWG(MSPOT) = PHIWG(I)
                  FRACG(MSPOT) = FRACG(I)
                  XG(MSPOT) = XG(I)
                  YG(MSPOT) = YG(I)
                  IRG(MSPOT) = IRG(I)
                  IMPARTG(MSPOT) = IMPARTG(I)
                  IMG(MSPOT) = IMG(I)
                  IHG(MSPOT) = IHG(I)
                  IKG(MSPOT) = IKG(I)
                  ILG(MSPOT) = ILG(I)
                  ILATTG(MSPOT) = ILATTG(I)
                  NLATT =  NLATTOVLP(I)
                  NLATTOVLP(MSPOT) =  NLATT
                  DO K = 1,NLATT
                    DO J = 1,4
                      HKLLATTOVLP(J,MSPOT,K) = HKLLATTOVLP(J,I,K)
                    ENDDO
                  ENDDO
                  DO J = 1,NLATT
                    IDXOVLP(MSPOT,J) = IDXOVLP(I,J)
                    IDYOVLP(MSPOT,J) = IDYOVLP(I,J)
                  ENDDO
                  IGFLAG(MSPOT) = 0
                  MISYMG(MSPOT) = 0
                  IBUFFR(18) = IMPARTG(MSPOT)
C
C---- Store the information about extra lattices starting at IBUFFR(19)
C     The following information is stored:
C     NLATT  number of overlapping lattices for this reflection
C
C     for each overlapping reflection
C     h,k,l indices and lattice number
C     vector displacement (in pixels) of overlapping reflection
C
                  IF (NLATTICE .GT.1) THEN
                    IJ = 19
                    IBUFFR(IJ) = NLATT
                    DO 124 ILATT = 1,NLATT
                      DO 122 J = 1,4
                        IJ = IJ + 1
                        IBUFFR(IJ) =  HKLLATTOVLP(J,MSPOT,ILATT)
 122                  CONTINUE
                      IJ = IJ + 1
                      IBUFFR(IJ) = IDXOVLP(MSPOT,ILATT)
                      IJ = IJ + 1
                      IBUFFR(IJ) = IDYOVLP(MSPOT,ILATT)
 124                CONTINUE
                  END IF                                       
C
C                      ***********************
                  IF (MODE.NE.2) CALL QWRITE(IUNIT,IBUFFR,NBYTES)
C                      ***********************
C
                  IF (DEBUG(32) .AND. (MSPOT.LT.NDEBUG(32))) THEN
                    IR = IRG(I)
                    IM = IMG(I)
                    WRITE (IOUT,FMT=6004) I,MSPOT,(IBUFFR(K),K=1,3),
     +                       IBUFFR(5),IBUFFR(4),(RBUFFR(K),K=1,5)
                    IF (ONLINE) WRITE (ITOUT,FMT=6004) I,MSPOT,
     +                       (IBUFFR(K),K=1,3),
     +                       IBUFFR(5),IBUFFR(4),(RBUFFR(K),K=1,5)
 6004 FORMAT (1X,'I',I5,' IRECG',I5,' Indices',3I4,' IR,IM',2I5,
     +        ' XG,YG',2F8.1,' PHI',F8.3,' WIDTH',F8.3,' FRAC',F8.3)
                  END IF
                END IF
  130         CONTINUE
C
C
              IF ((NRS.EQ.0).OR.(MODE.EQ.3)) GOTO 162
C
              IF (NFOUND.NE.NRS) THEN
                IF (ONLINE) WRITE (ITOUT,FMT=6006) NFOUND,NRS,NFULLF
                WRITE (IOUT,FMT=6006) NFOUND,NRS,NFULLF
C
C---- Set record flag negative for reflections not found, so they will
C     be eliminated below from the list.
C
                DO 140 I = 1,NRS
                  IF (.NOT.FOUND(I)) RRS(I) = -ABS(RRS(I))
  140           CONTINUE
C
C
              END IF
C
C
              IF (NPAR.NE.0) THEN
                IF (ONLINE) WRITE (ITOUT,FMT=6008) NPAR
                WRITE (IOUT,FMT=6008) NPAR
              END IF
C
C---- Now eliminate partials or unfound reflections from list
C
              DO 150 I = 1,NRS
                TXRS(I) = XRS(I)
                TYRS(I) = YRS(I)
                ITRRS(I) = RRS(I)
  150         CONTINUE
C
C
              M = 0
C
C
              DO 160 I = 1,NRS
                IF (ITRRS(I).GE.0) THEN
                  M = M + 1
                  XRS(M) = TXRS(I)
                  YRS(M) = TYRS(I)
                  RRS(M) = ITRRS(I)
                END IF
  160         CONTINUE
              NRS = M
C
C
 162          WRITE (IOUT,FMT=6010) MSPOT,NFULL,(MSPOT-NFULL),NOVRLAP,
     +             NWIDE,NLATTOVRLAP,NOUTSIDE,NBADRES,NINCUSP
              IF (ONLINE) WRITE (ITOUT,FMT=6010) MSPOT,NFULL,
     +                      (MSPOT-NFULL),NOVRLAP,NWIDE,NLATTOVRLAP,
     $             NOUTSIDE,NBADRES,NINCUSP
              IF (BRIEF) WRITE (IBRIEF,FMT=6010) MSPOT,NFULL,
     +                      (MSPOT-NFULL),NOVRLAP,NWIDE,NLATTOVRLAP,
     $             NOUTSIDE,NBADRES,NINCUSP

C
C---- Print for program flow
C
              CALLED = 'dna_output...'
              COMMENT = 'write output for DNA'
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              call dna_output_table_start('generated_reflections')
              call dna_output_list_start('number')
              call dna_output_integer_item('total', mspot)
              call dna_output_integer_item('full', nfull)
              call dna_output_integer_item('partial', mspot-nfull)
              call dna_output_integer_item('wide', nwide)
              call dna_output_integer_item('overlap', NOVRLAP)
              call dna_output_list_end
              call dna_output_table_end
              
              IF(SOCKLO)THEN
C
C---- Print for program flow
C
                CALLED = 'WRITE_SOCKET_LENGTH'
                COMMENT = 'write generate_response XML'
                IF (DEBUG(99)) 
     +                 CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                CALL BADTOGOOD(XODFILE,ODFILE,LENSTR(ODFILE))
                WRITE(XMLLINE,FMT=7000)XODFILE(1:LENSTR(XODFILE)),
     $               TEMPLSAV(1:lenstr(templsav)),ID,
     $             mspot,nfull,mspot-nfull,nwide,NOVRLAP,NLATTOVRLAP
                CALL WRITE_SOCKET_LENGTH
     $             (SERVERFD,LENSTR(XMLLINE),XMLLINE)
              ENDIF

 6010 FORMAT (1X,I6,' Reflections generated:',
     +   /,1X,I6,' Fully recorded',/,1X,I6,' Partials',
     $   /,8X,'-----------------',/,8X,'Rejected (reason):',/,1X,I6,
     +   ' Overlapped reflections',/,1X,I6,' Too wide in phi',/,1X,
     +   I6,' Overlapped by other lattices',/,1X,
     +   I6,' Outside detector area',/,1X,
     +   I6,' Outside resolution limits',/,1X,
     +   I6,' In cusp',/)
C
C---- Test for more than 10% of spots being overlapped
C
                WARN(32) = (WARN(32).OR.
     +                      (NOVRLAP.GT.NINT(0.1*MSPOT)))
                IF (MSPOT.GT.0) XWARN(1,32) = 
     +              MAX(XWARN(1,32),FLOAT(NOVRLAP)/FLOAT(MSPOT))
C
C---- Test for more than 5% of spots being too wide in phi
C
                WARN(39) = (WARN(39).OR.
     +                      (NWIDE.GT.NINT(0.05*MSPOT)))
                IF (MSPOT.GT.0) XWARN(1,39) = 
     +              MAX(XWARN(1,39),FLOAT(NWIDE)/FLOAT(MSPOT))
C
C---- Set warning if not many fully recorded reflections
C
              RFP = 1.0
              IF (MSPOT.GT.0) RFP = REAL(NFULL)/REAL(MSPOT)
              WARN(15) = (((RFP.LT.0.2).AND.(NFULL.LT.100))
     +                       .OR.(NFULL.LT.60))
C
              IS = 2
              CNT_NIVB = 0
              MED_NIVB = 0
              NHALFG = (MSPOT-NFULL-NOVRLAP-NWIDE)/2
              DO 170 I = 1,10
                IF (IS.GT.IWMAX) GOTO 180
                IE = IS + 9
                IF (I.EQ.1) IE = 10
                IE = MIN(IE,IWMAX)
                DO 165 J=IS,IE
                   CNT_NIVB = CNT_NIVB + NPART(J-1)

C
C---- Check for MEDIAN or twice MAGIC
CAL Eliminate the MAGIC test
C
                   IF (MED_NIVB.EQ.0)THEN
                     IF (CNT_NIVB.GE.NHALFG) MED_NIVB = J
CAL                      IF (CNT_NIVB.GE.2*MAGIC)THEN
CAL                         MED_NIVB = J
CAL                      ELSE 
CAL                         IF((CNT_NIVB.GE.(MSPOT-NFULL-NOVRLAP-NWIDE)/2)
CAL     $                        .AND.
CAL     $                        (CNT_NIVB.GE.MAGIC))MED_NIVB = J
CAL                      ENDIF
                   ENDIF
 165            ENDDO
                WRITE(IOUT,6011) IS,IE,(NPART(J-1),J=IS,IE)
              IF (ONLINE) WRITE(ITOUT,6011) IS,IE,(NPART(J-1),J=IS,IE)
              IF (BRIEF) WRITE(IBRIEF,6011) IS,IE,(NPART(J-1),J=IS,IE)
 6011 FORMAT (1X,'Number of partials extending over',I3,' to',I4,
     +        ' images',/,1X,10I6)
                IS = IS + 10
                IF (I.EQ.1) IS = 11
 170          CONTINUE
C
C---- Check for MEAN
C
 180         IF(CNT_NIVB.EQ.0)THEN
                IF(ONLINE)THEN
                   WRITE(ITOUT,*)'There are no reflections suitable',
     $                  ' for use in post-refinement! Check'
                   WRITE(ITOUT,*)'your ',
     $                  'mosaicity and oscillation width carefully!'
                ENDIF
                WRITE(IOUT,*)'There are no reflections suitable for',
     $               ' use in post-refinement! Check'
                WRITE(IOUT,*)'your ',
     $               'mosaicity and oscillation width carefully!'
             ENDIF
             IF(ONLINE)THEN
                WRITE(ITOUT,*)' THERE ARE ',NSPOT,' REFLECTIONS.'
                WRITE(ITOUT,*)'"MEDIAN" "   " "      "      ": ',
     $               MED_NIVB,'    "  '
                WRITE(ITOUT,*)'  NADD is currently.............',NADD
             ENDIF
             WRITE(IOUT,*)' THERE ARE ',NSPOT,' REFLECTIONS.'
             WRITE(IOUT,*)'"MEDIAN" "   " "      "      ": ',MED_NIVB,
     $            '    "  '
             WRITE(IOUT,*)'  NADD is currently.............',NADD
             IF (MED_NIVB.GT.NADD) THEN
 6210           FORMAT('Too few partials for postrefinement on ',I2,
     $               ' images. NADD increased to ',I2)
C---- Must not allow NADD to change during a run so comment this out
CAL                NADD = MED_NIVB-1
             END IF
CHRP 14.12.2006 double size of NIVB to give sufficient reflections for 
C     accurate cell parameter refinement
CAGWL 14/7/07  Do not do this here as it affects calculation of NVIRBAT
C              and NADDMISSET in MOSFLM. Double NIVB in SEGMENT or in MXDSPL
C              instead.
C
CAGWL             NIVB = 2 * MED_NIVB
             NIVB = MED_NIVB
             IF(ONLINE)WRITE(ITOUT,*)'  NIVB is now...................',
     $            NIVB
             WRITE(IOUT,*)'  NIVB is now...................',NIVB
                
C
C---- Set warning if not enough partials for post-refinement
C
          WARN(26) = (((NPART(1).LT.NPRMIN).OR.(WARN(26)))
     +                      .AND.POSTREF.AND..NOT.NEWPREF)
C
              IF (DEBUG(32)) THEN
                WRITE (IOUT,FMT=6012) NSPOT,MSPOT,NFULL,NFOUND,NRS
                IF (ONLINE) WRITE (ITOUT,FMT=6012) NSPOT,MSPOT,NFULL,
     +                        NFOUND,NRS
              END IF
C
C---- Write out updated pack header
C
              TOSPT = MSPOT
              NSPOT = MSPOT
              IBUFFP(2) = MSPOT
              IBUFFP(3) = NFULL
C
              IF (MODE.NE.2) THEN
C
C---- Print for program flow
C
                CALLED = 'QSEEK,QWRITE,QSEEK'
                COMMENT = 'to update header and reposition'
                IF (DEBUG(99)) 
     +                    CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C                  ************************
                CALL QSEEK(IUNIT,IPACKHEAD,1,36)
                CALL QWRITE(IUNIT,IBUFFP,180)
C                  ************************
C
C---- Now position file at the end of this pack (as WRGEN does after
C     writing back camera constants) so that if refinement of this pack
C     fails, the file is in the correct place for locating the next pack
C
                IPACKREC = IPACKHEAD + 5 + TOSPT*IRECMULT
C
C---- Store this position as IRECLAST 
C
                IRECLAST = IPACKREC
C
C                  ************************
                CALL QSEEK(IUNIT,IPACKREC,1,36)
C                  ************************
              END IF
              IF (MODE.EQ.2) IRECLAST = IPACKREC
C
             IF (DEBUG(32)) THEN
               WRITE(IOUT,FMT=6022) IPACKHEAD,IPACKREC,IRECLAST
 6022 FORMAT(1X,'Position generate file at IPACKHEAD=',I6,
     +    ' and WRITE UPDATED header ',/,1X,'Then position file ',
     +    ' to the end of this pack, IPACKREC=',I6,/,1X,
     +    'IRECLAST is now',I6)
            IF (ONLINE) WRITE(ITOUT,FMT=6022) IPACKHEAD,IPACKREC,
     +     IRECLAST
        END IF
C
        RETURN
C
C---- Format statements
C
 6000 FORMAT (/1X,'In GENERATE, ETA,DIVH,DIVV (DEG)',3F6.3,'  XTOFD,WA',
     +       'VE',F9.1,F7.4,/1X,'DELPHI ',3F8.3,'   DSTMAX',F8.5,
     +       '  DSTPL',F9.6,/,1X,'Doing predictions for lattice:',I2,
     +       ' by calling REEK.')
 6002 FORMAT (//1X,'*** FATAL ERROR ***',/1X,'First pack in GENERATE F',
     +       'ILE is not the pack being processed',/1X,'Only one pack ',
     +       'per generate file is allowed when pattern matching')
 6006 FORMAT (/1X,'Only',I4,' of the',I4,' reflections used in CENTRS ',
     +       'refinement located in new',/,1X,'generate file',/,1X,
     +       I3,' of these are fully recorded')
 6008 FORMAT (1X,I4,' Partials found in refinement list, they will be ',
     +       'eliminated')
 6012 FORMAT (1X,I6,' Reflections calculated in generate of which',I6,
     +       ' Written to GENERATE FILE',I6,' fulls',/1X,'NFOUND,NRS',
     +        2I5)
 7000 FORMAT ('<?xml version="1.0"?><!DOCTYPE generate_response>',
     $     '<generate_response><status><code>ok</code></status>',
     $     '<imagefile>',A,'</imagefile>',
     $     '<image_template>',A,'</image_template>',
     $     '<image_number>',I8,'</image_number>',
     $     '<reflections_generated>',
     $     '<total>',I8,'</total>',
     $     '<fully_recorded>',I8,'</fully_recorded>',
     $     '<partially_recorded>',I8,'</partially_recorded>',
     $     '<too_wide_in_phi>',I8,'</too_wide_in_phi>',
     $     '<spatially_overlapped>',I8,'</spatially_overlapped>',
     $     '<lattice_overlapped>',I8,'</lattice_overlapped>',
     $     '</reflections_generated>',
     $     '</generate_response>')
C
C
      END
C
C
C== GETBIN ==
      SUBROUTINE GETBIN(IRECG,ITHBIN,NBIN,DSTSQ)
C
      IMPLICIT NONE
C    Returns the sin(theta)/lambda bin ITHBIN and (d*)**2 (A**-2)
C    for reflection with generate file number IRECG.
C    To get real spacing D in angstroms, D = 1.0/sqrt(DSTSQ)
C    If IRECG is zero, sets up NBIN bins equally spaced in
C    4*sinsqth/lambdsq limits
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     ..
C     .. Scalar Arguments ..
      INTEGER IRECG,ITHBIN,NBIN
      REAL DSTSQ
C     ..
C     .. Local Scalars ..
      REAL DMAX,DMIN,STHLMIN,STHLMAX,STH,STHINC
      INTEGER IMAT,IUMAT,ICELL,I,IH,IK,IL,ICHECK
C     ..
C     .. Local Arrays ..
      INTEGER IHKL(7)
C     ..
C     .. External Functions ..
C     ..
C     .. External Subroutines ..
      EXTERNAL SETMAT,GETHKL
C     ..                                
C     .. Intrinsic Functions ..
      INTRINSIC SQRT,ATAN,COS
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/cell.f
C
C $Id: cell.f,v 1.4 2012/11/21 14:41:22 andrew Exp $
C
C--- awk generated include file  cell.h
C---- START of include file cell.h
C
C     CELL cell dimensions (real space)
C     RCELL reciprocal cell parameters in dimensionless rlu
C     LCELL indicator for cell parameters to be refined
C     
C     LCELL(I) = -1  parameter free
C              =  0  parameter fixed
C              >  0, = J  parameter I constrained to = parameter J
C
C     .. Arrays in Common /CELLCOM/ ..
      REAL UMAT,BMAT,GMAT,CELL,RCELL,UMATCELL,SOFTCELL,VOLUME
      INTEGER LCELL,ICRYST,NUMSPG,NLAUE
C     ..
C     .. Common Block /CELLCOM/ ..
      COMMON /CELLCOM/UMAT(3,3),BMAT(3,3),GMAT(3,3),CELL(6),RCELL(6),
     $       UMATCELL(6),SOFTCELL,VOLUME,LCELL(6),ICRYST,NUMSPG,NLAUE
C     ..
C
C
C&&*&& end_include  ../inc/cell.f
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
