     +       IWARN(MAXIWARN,100),
     $       NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,DEBUG(200),LPRINT(20),
     +       DUMP(30),WARN(100),SPOT,IARRDUMP(30),IERRLEVEL

      COMMON /CDEBUG/ MESSAGE
C     ..
C
C&&*&& end_include  ../inc/debug.f
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C     ..
C     .. Equivalences ..
      SAVE
C     ..
C     .. Data ..
C     ..
C
C
      IF (NIMAG.LE.10) THEN
        NBLOCK = NIMAG
C
C---- NPRUN can be zero in a STRATEGY run, must never return NBLOCK as zero.
C
        IF (NBLOCK.EQ.0) NBLOCK = 10
        IF (DEBUG(52)) THEN
          WRITE(IOUT,FMT=1000) NBLOCK
          IF (ONLINE) WRITE(ITOUT,FMT=1000) NBLOCK
 1000     FORMAT(1X,'From GETBLOCK, NBLOCK=',I4)
        END IF
        RETURN
      ELSE
C
C---- More than 10 images
C
        IF (PHIRNG.GT.0.0) THEN
C
C---- Set initial estimate to be 5 degrees of data
C
          IBLOCKSZ = NINT(5.0/PHIRNG)
        ELSE
C
C---- Oscillation angle not know, set to a value between 7 and 13
C
         ISTART = 7
         IEND = 13
         DO 10 IBLOCK = ISTART,IEND
           IF (MOD(NIMAG,IBLOCK).EQ.0) GOTO 40
 10      CONTINUE
         DO 20 IBLOCK = ISTART,IEND
           IF (MOD(NIMAG,IBLOCK).EQ.(IBLOCK-1)) GOTO 40
 20      CONTINUE
         DO 30 IBLOCK = ISTART,IEND
           IF (MOD(NIMAG,IBLOCK).EQ.(IBLOCK-2)) GOTO 40
 30      CONTINUE
C
         NBLOCK = 10
          IF (DEBUG(52)) THEN
            WRITE(IOUT,FMT=1000) NBLOCK
            IF (ONLINE) WRITE(ITOUT,FMT=1000) NBLOCK
          END IF
         RETURN
C
 40      NBLOCK = IBLOCK
         IF (DEBUG(52)) THEN
           WRITE(IOUT,FMT=1000) NBLOCK
           IF (ONLINE) WRITE(ITOUT,FMT=1000) NBLOCK
         END IF
         RETURN
        END IF
      END IF


      NBLOCKS = NIMAG/IBLOCKSZ
      IF (NBLOCKS.EQ.0) THEN
        NBLOCKS = 1
        IBLOCKSZ = NIMAG
        GOTO 70
      END IF
      IF (MOD(NIMAG,IBLOCKSZ).EQ.0) THEN
        GOTO 70
      ELSE
        NEXTRA = NIMAG - NBLOCKS*IBLOCKSZ
        IADD = 0
        IF ((NBLOCKS.GT.1).AND.MOD(NEXTRA,NBLOCKS).EQ.0) IADD = 1
        IBLOCKSZ = IBLOCKSZ + MAX(NEXTRA/NBLOCKS,1) + IADD
        NLAST = NIMAG - MAX(1,(NBLOCKS-1))*IBLOCKSZ
 50     IF (NLAST.GT.IBLOCKSZ) THEN
          NLAST = NLAST - IBLOCKSZ
          GOTO 50
        END IF
 60     CONTINUE
C        WRITE(6,102) NEXTRA,NBLOCKS,IBLOCKSZ,NLAST
 102    FORMAT(1X,'NEXTRA',I5,' NBLOCKS',I5,' IBLOCKSZ',I5,' NLAST',I5)
        IF ((NLAST.GT.IBLOCKSZ/2).OR.(NLAST.EQ.0))GOTO 70
        IBLOCKSZ = IBLOCKSZ + 1
        IADD = 1
        IF (MOD(NIMAG,IBLOCKSZ).EQ.0) IADD = 0
        NBLOCKS = NIMAG/IBLOCKSZ + IADD
        NLAST = NIMAG - (NBLOCKS-1)*IBLOCKSZ
 62     IF (NLAST.GT.IBLOCKSZ) THEN
          NLAST = NLAST - IBLOCKSZ
          GOTO 62
        END IF
        GOTO 60
      END IF
 70   NLAST = NIMAG - (NBLOCKS-1)*IBLOCKSZ
      IF (NLAST.EQ.IBLOCKSZ) NLAST = 0
      IF ((NLAST.GT.IBLOCKSZ).OR.((NLAST.GT.0).AND.
     +     (NLAST.LT.IBLOCKSZ/2))) THEN
        WRITE(IOUT,FMT=6010) NIMAG,NBLOCKS, IBLOCKSZ,NLAST
        IF (ONLINE) WRITE(ITOUT,FMT=6010) NIMAG,NBLOCKS, 
     +    IBLOCKSZ,NLAST
 6010   FORMAT(//,1X,'** ERROR **',/,1X,I5,
     +   ' images gives',I4,' blocks each of', I4,' images ',
     +   'leaving',I5, ' images in last block')
      END IF
      IF (DEBUG(52)) THEN
        WRITE(IOUT,1002) NIMAG,NBLOCKS, IBLOCKSZ,NLAST
        IF (ONLINE) WRITE(ITOUT,1002) NIMAG,NBLOCKS, IBLOCKSZ,NLAST
 1002   FORMAT(1X,' From GETBLOCK,',I5,' images gives',I4,
     +  ' blocks each of', I4,' images leaving',I5, 
     +  ' images in last block')
      END IF
      NBLOCK = IBLOCKSZ
      RETURN
      END

       
C== GETBOX ==
      SUBROUTINE GETBOX(IX,IY,NXX,NYY,NPBOX)
C
      IMPLICIT NONE
C---- Given reflection coordinates IX,IY in PIXELS in the scanner frame
