      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
      INTEGER NPARM,NHLMAX
      PARAMETER (NPARM = 200)
      PARAMETER (NHLMAX = 1000)
C
C     ..
C     .. Scalar Arguments ..
