      REAL FACT,SCNSZ,RAST,RASTY,ROWREADT,ROTSPEED
      INTEGER NBYTE,NREC,NWORD,IYLEN,ICURR,NEXTRA,NHBYTE
      LOGICAL BYTSWAP,LACTIVE,REALLYFORCEREAD
C     ..
C     .. Common Block /SCN/ ..
      COMMON /SCN/ FACT,SCNSZ,RAST,RASTY,ROWREADT,ROTSPEED,
     +     NBYTE,NREC,NWORD,IYLEN,
     +     ICURR,NEXTRA,NHBYTE,BYTSWAP,LACTIVE,
     $     REALLYFORCEREAD
C&&*&& end_include  ../inc/scn.f
C&&*&& include  ../inc/test.f
C--- awk generated include file  test.h
C---- START of include file test.h
C
C    Detector limits, used in SPTEST. All are in 10 micron units.
C    In the virtual detector frame, Y is parallel to the rotation axis
C    and X is orthogonal to the rotation axis.
C
C    In the scanner frame, X is parallel to the slow direction in the
C    image, Y is the fast direction.
C
C    RSCANSQ      Radius**2 of the scanned region of the plate (Mar scanners)
C                 This is different to the other limits because it is
C                 applied to the actual scanner coordinates rather than
C                 the virtual detector coordinates. All other limits apply
C                 to virtual detector coordinates.
C    XSCAN        Maximum X coordinate in detector frame (10 micron units)
C    YSCAN        Maximum Y coordinate in detector frame (10 micron units)
C    RSCANX,RSCANY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RSCAN defining the
C                 useable area of the detector.
C    XSCAN,YSCAN,RSCAN are maximum coords relative to the physical centre of 
C                 the detector (ie the mid-point of the image), NOT wrt the 
C                 direct beam position.
C    RMINX,RMINY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RMIN defining the
C                 useable area of the detector.
C    RMXSQD       Maximum radius (squared) in virtual detector frame
C    RMNSQD       Minimum radius (squared) in virtual detector frame
C    XMIN         Minimum X coordinate in  detector frame
C    XMAX         Maximum X coordinate in  detector frame
C    YMIN         Minimum Y coordinate in  detector frame
C    YMAX         Maximum Y coordinate in  detector frame
C    NXYEXC       Number of excluded areas set by user (rectangles, arcs)
C    NXYEXCDET    Number of detector specific excluded rectangles (Pilatus)
C    NOTILES      If set true, ignore all tile boundaries in Pilatus images
C    ICEWIDTH     Width of the exclusion shells for ice, this fraction
C                 of the actual resolution is used as the half-width
C    ICEWIDTHPREF Width of the exclusion shells for ice for post
C                 refinement, this fraction
C                 of the actual resolution is used as the half-width
C    PREFEXICE    Logical, true if reflections in ice rings to be
C                 excluded from post-refinement
C
C     .. Scalars in common block /TEST/ ..
      REAL RMXSQD,RMNSQD,XMIN,XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,
     +     RMINX,RMINY,XSCAN,YSCAN,CIRRAD,ICEWIDTH,ICEWIDTHPREF
      INTEGER NEXCL,NXYEXC,NXYEXCDET,IQUADNO,IARCNO,NEXCL2
      LOGICAL PREFEXICE,NOTILES
C
C     .. Arrays in common block /TEST/
      REAL RESEXL,RESEXH,XYEXC,CNREXC,EXCARC,CIRCEN,PHILIM,RES2EXL,
     +     RES2EXH,RES3EXL,RES3EXH,XYEXCSP
      INTEGER IEXCARC
      LOGICAL LEXCARC
C     ..
C     .. Common Block /TEST/ ..
      COMMON /TEST/RESEXL(MAXEXCL),RESEXH(MAXEXCL),XYEXC(4,MAXEXCL),
     +     CNREXC(8,MAXEXCL),
     $     EXCARC(5,MAXEXCL),CIRCEN(2),PHILIM(2),RMXSQD,RMNSQD,XMIN,
     +     XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,RMINX,RMINY,XSCAN,
     $     YSCAN,CIRRAD,IEXCARC(6,MAXEXCL),NEXCL,NXYEXC,IQUADNO,
     $     IARCNO,LEXCARC(MAXEXCL),NXYEXCDET,RES2EXL(MAXEXCL),
     $     RES2EXH(MAXEXCL),NEXCL2,ICEWIDTH,ICEWIDTHPREF,PREFEXICE,
     +     RES3EXL(MAXEXCL),RES3EXH(MAXEXCL),NOTILES,XYEXCSP(4,MAXEXCL)
C     ..
C
C

C&&*&& end_include  ../inc/test.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C     ..
C     .. Equivalences ..
      EQUIVALENCE (RHEAD(1),IHEAD(1))
      EQUIVALENCE (CHEAD(1),IHEAD(1))
      EQUIVALENCE (BHEAD(1),IHEAD(1))
      SAVE
C     ..
C     .. Data ..
C     ..
C
      DATA FIRSTTIME/.TRUE./
      INDENT = 4
      THIS = 'GETDETECT'
      IERR = 0
      MODE = 2
      ISTAT = 0
      INSIZE = 0
C
C---- These should not be initialised here, this is done in CONTROL. If reset here
C     then any attempt to overwite the OVERLOAD CUTOFF (or for profile formation) will
C     be ignored.  AGWL 18/12/06
CAL      ICUT = 0
CAL      IPRCUT = 0
C
C---- Turn off byte swapping in GETBLK
C
      ISWAP = 1
C
C---- Test if file exists
C
      INQUIRE (FILE=ODFILE,EXIST=EFILE,NAME=ODFILE)
C
      IF (.NOT.EFILE) THEN
        ISTAT = -999
        RETURN
      END IF
C
C---- HRP need C jiffy here since some fortrans don't have "access" function
C
      ierr = fileaccess(odfile,lenstr(odfile))
      IF (IERR.NE.0) THEN
        WRITE(IOUT,FMT=6004) 
        IF (ONLINE) WRITE(ITOUT,FMT=6004) 
        ISTAT = -998
        RETURN
      END IF
C
C---- only set IISCN if the file exists and can be read!!
C
      IISCN = .TRUE.

      CALL QOPEN(INOD,ODFILE,'READONLY')
      CALL QMODE (INOD,0,NCMITM)
      
      CALL QQINQ(INOD,ODFILE,ODFILE,IFILESIZE)
C
C---- Get first 512 bytes in the header (there may be more)
C
      NNBYTE = 512
 10   CALL GETBLK(BHEAD(1),NNBYTE,1,ISWAP,IERR)
C
C---- Trap error in read
C
      IF (IERR.NE.0) THEN
        WRITE(IOUT,FMT=6004) 
        IF (ONLINE) WRITE(ITOUT,FMT=6004) 
 6004   FORMAT(/,1X,'Read error trying to read image header.')
        ISTAT = -1
        RETURN
      END IF
      FWORD = CHEAD(1)//CHEAD(2)//CHEAD(3)//
     +                 CHEAD(4)//CHEAD(5)//CHEAD(6)
      DO IC = 1,19
        PWORD(IC:IC) = CHEAD(IC+37)
      ENDDO
      IWORD = IHEAD(1)
      IWORDSW = IWORD
      NITEM = 1
      CALL SWAPHDR(BWORDSW,NITEM)
      
      IF (DEBUG(110)) THEN
         WRITE(IOUT,FMT=6008) FWORD,IWORD,IWORDSW,CHEAD(1),
     +                        IFILESIZE,(IHEAD(I),I=1,10),
     +                        (RHEAD(I),I=11,25)
         IF (ONLINE) WRITE(ITOUT,FMT=6008) FWORD,IWORD,IWORDSW,
     +              CHEAD(1),IFILESIZE,(IHEAD(I),I=1,10),
     +                        (RHEAD(I),I=11,25)
 6008    FORMAT(1X,'From GETDETECT, FWORD: "',A,'"  IWORD',I12,
     +          '  IWORDSW',I12,'  CHEAD(1):',A,/,1X,'IFILESIZE',I12,
     +          /,1x,'First 10 integers',10I8,/,1x,'First 15 reals',
     +          15F7.3)
      END IF
C
C---- Decode the header information
C
      NCH = 0
      NCH = NCH + 1
        
      IF (FWORD.EQ.'RAXIS2') THEN
          MACHINE = 'RAXI'
          MODEL = 'RAXIS  '
          CMACHINE = 'Rigaku R-Axis II'
          COMPRESSION = 3
C
C---- Print for program flow
C
          CALLED = 'SETDETECT'
          COMMENT = 'Assign detector parameters for '//CMACHINE
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
          GOTO 20
        
      ELSE IF (FWORD.EQ.'RAXIS4') THEN
          MACHINE = 'RAXI'
          MODEL = 'RAXISIV'
          CMACHINE = 'Rigaku R-Axis IV'
          COMPRESSION = 3
C
C---- Print for program flow
C
          CALLED = 'SETDETECT'
          COMMENT = 'Assign detector parameters '//CMACHINE
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
          GOTO 20
        
      ELSE IF (FWORD.EQ.'R-AXIS') THEN
          MACHINE = 'RAXI'
          COMPRESSION = 3
          IF((IFILESIZE.EQ.7786496).OR.(IFILESIZE.EQ.2371496).OR.
     +        (IFILESIZE.EQ.1947648)) THEN
            MODEL = 'RAXIS  '
            CMACHINE = 'Rigaku R-Axis II'
          ELSE
            MODEL = 'RAXISIV'
            CMACHINE = 'Rigaku R-Axis IV'
          ENDIF
C
C---- Print for program flow
C
          CALLED = 'SETDETECT'
          COMMENT = 'Assign detector parameters '//CMACHINE
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
          GOTO 20

      ELSE IF (FWORD.EQ.'RAXIS') THEN
          MACHINE = 'RAXI'
          MODEL = 'RAXISHTC'
          CMACHINE = 'Rigaku R-Axis HTC'
          COMPRESSION = 3
C
C---- Print for program flow
C
          CALLED = 'SETDETECT'
          COMMENT = 'Assign detector parameters '//CMACHINE
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
          GOTO 20
        
      ELSE IF (FWORD(1:2).EQ.'II') THEN
          MACHINE = 'MARC'
C     .. this shouldn't be set here - also need model for MarMosaic
C          MODEL = 'MARCCD'
          CMACHINE = 'Mar CCD'
          COMPRESSION = 1
C
C---- Print for program flow
C
          CALLED = 'SETDETECT'
          COMMENT = 'Assign detector parameters '//CMACHINE
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
          GOTO 20
      ELSE IF (FWORD.EQ.'FORMAT') THEN
          MACHINE = 'BRUK'
          COMPRESSION = 1
          CALL MPARSE(CHEAD(9),IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
          IF(VALUE(1).LT.100)THEN
            MODEL = 'SMART'
          CMACHINE = 'Bruker SMART'
            ELSE
              MODEL='PROTEUM'
          CMACHINE = 'Bruker PROTEUM'
            ENDIF
C
C---- Print for program flow
C
          CALLED = 'SETDETECT'
          COMMENT = 'Assign detector parameters '//CMACHINE
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
          IF(HOSCAXIS.EQ.'OMEGA')THEN
            OMEGAFD = 270.0
          ELSE
            OMEGAFD = 90.0
          ENDIF
          OMEGAF = OMEGAFD * DTOR
          GOTO 20
        ELSE IF (FWORD.EQ.'###CBF') THEN
C     ..
C     .. could be a Pilatus or an Eiger or an ADSC PAD
C     ..
C     .. need to test for detector type in a line starting:# Detector
C     .. line
            IC = 0
            UNKNOWN = .TRUE.
            DO 110 WHILE (UNKNOWN.and.IC.le.512)
              IC = IC + 1
              IF (CHEAD(IC).EQ.'#')THEN
                PWORD = ''
                JC = 1
                DO 100 WHILE (CHEAD(IC+JC).NE.'#'.AND.JC.LE.60)
                  PWORD(JC:JC) = CHEAD(IC+JC-1)
                  JC = JC + 1
 100            ENDDO
C
C---- second line her to deal with incorrectly written TIMEPIX detector images
C
                IF ((PWORD(1:11).EQ.'# Detector:').OR.
     +              (PWORD(1:12).EQ.';# Detector:')) THEN
                
C
C---- Parse this line to extract detector type and serial number
C     Must exclude first character (#) otherwise line will not be parsed
C
                  LINE = ' '
                  IF (PWORD(1:1).EQ.'#') THEN
                    LINE(1:59) = PWORD(2:60)
                  ELSE IF (PWORD(1:2).EQ.';#') THEN
                    LINE(1:59) = PWORD(3:60)
                  END IF
                  CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
                  LDETECTOR = LINE(IBEG(2):IEND(2))
                  CALL CCPUPC(LDETECTOR)
C
C---- If LDETECTOR is DECTRIS, get the detector type (Eiger, Eiger2, EIGER)
C
                  IF (LDETECTOR(1:7).EQ.'DECTRIS') THEN
                    LDETECTOR = LINE(IBEG(3):IEND(3))
                    CALL CCPUPC(LDETECTOR)
                  END IF                  
C
C---- Search for string S/N which precedes serial number (Except Petra P14 CBF)
C
                  HSERIAL = 'Unknown'
                  DO 102 ITOK = 2,NTOK-1
                    IF (LINE(IBEG(ITOK):IEND(ITOK)).EQ.'S/N') THEN
                      HSERIAL = LINE(IBEG(ITOK+1):IEND(ITOK+1))
                      GOTO 104
                    END IF
 102              CONTINUE
C
 104              IF (DEBUG(110)) THEN
                    WRITE(IOUT,FMT=6009) IC,PWORD(1:LENSTR(PWORD))
     +                      ,LDETECTOR,HSERIAL(1:LENSTR(HSERIAL))
                    IF (ONLINE) WRITE(ITOUT,FMT=6009) IC,
     +                      PWORD(1:LENSTR(PWORD)),
     +                      LDETECTOR,HSERIAL(1:LENSTR(HSERIAL))
 6009               FORMAT(1X,'Line starting at character',I4,' is:',
     +         A,/,1X,'   Detector:',A,'  Serial number:',A)
                  END IF
C                  IF (HSERIAL.EQ.'       ')HSERIAL='Unknown'
                  UNKNOWN = .FALSE.
                ENDIF
              ENDIF
 110        ENDDO
C# Detector: PILATUS 6M, 60-0001, X06SA@SLS
C# Detector: PILATUS 6M, S/N 60-0104, ESRF ID29
C# Detector: PILATUS3 6M, S/N 60-0122     (APS)
C# Detector: PILATUS 6M, S/N 60-0101 SSRL
C# Detector: PILATUS 6M Prosport+, S/N 60-0100 Diamond
C# Detector: PILATUS3 2M, S/N 24-0118, ESRF ID23
C
C            IF (PWORD(13:19).EQ.'PILATUS')THEN
C
C---- Only test first 7 characters as could be a PILATUS3
C
            IF (LDETECTOR(1:7).EQ.'PILATUS')THEN
              MACHINE = 'PILA'
              MODEL = 'Unknown_'
              CMACHINE = 'SLS/Dectris Pilatus miniCBF'
              MINICBF = .TRUE.
              COMPRESSION = 6
C
C---- HSERIAL now obtained from parser
C              HSERIAL = PWORD(31:39)
C
C---- Print for program flow
C
              CALLED = 'SETDETECT'
              COMMENT = 'Assign detector parameters '//CMACHINE
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
C     ..
C     .. could it be an Eiger?
C# Detector: EIGER 1M
C# Detector: Dectris Eiger 1M, S/N E-02-PSI
C123456789012345678901234567890123456789012
C# Detector: Dectris Eiger 4M, S/N E-08-0106, ESRF ID30a3
C# Detector: Dectris Eiger 16M, E-32-0107   From Petra P14 CBF
C# Detector: Dectris Eiger2 9M, S/N E-18-0110 (Original on IMCA beamline)
C# Detector: Dectris EIGER2 Si 9M, S/N E-18-0110 (New on IMCA beamline)
C# Detector: Dectris Eiger 16M, S/N E-32-0100 (from SLS)
            ELSE IF (LDETECTOR(1:5).EQ.'EIGER')THEN
              MACHINE = 'EIGE'
C
C---- Extract the model, assume of form 1M, 4M, 6M, 300K etc and lies between
C     the third and last token
C
              DO 114 ITOK = 3,NTOK
                MODEL = LINE(IBEG(ITOK):IEND(ITOK))
                CALL CCPUPC(MODEL)
                DO 112 I = 1,LENSTR(MODEL)
                  IF ((MODEL(I:I).EQ.'M').OR.(MODEL(I:I).EQ.'K'))
     +                   GOTO 116
 112            CONTINUE
 114         CONTINUE
             MODEL = 'Unknown'

C
 116         CMACHINE = 'Dectris Eiger '//MODEL(1:LENSTR(MODEL))//
     $             ' miniCBF'
              MINICBF = .TRUE.
              COMPRESSION = 6
C
C---- If S/N was not found on Detector line, as in Petra P14 images,
C      assume the last token is the serial number
C
              IF (HSERIAL(1:7).EQ.'Unknown')
     +                HSERIAL = LINE(IBEG(NTOK):IEND(NTOK))

C
C---- Print for program flow
C
              CALLED = 'SETDETECT'
              COMMENT = 'Assign detector parameters '//CMACHINE
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
C     ..
C     .. could it be an ADSC PAD?
            ELSE IF(PWORD(13:16).EQ.'ADSC')THEN
              MACHINE = 'APAD'
              MODEL = PWORD(18:22)
              CMACHINE = 'ADSC '//MODEL(1:lenstr(model))//' miniCBF'
              MINICBF = .TRUE.
              COMPRESSION = 6
              HSERIAL = PWORD(29:32)
C
C---- Print for program flow
C
              CALLED = 'SETDETECT'
              COMMENT = 'Assign detector parameters '//CMACHINE
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
C
C---- TIMEPIX detector
C     ..
            ELSE IF (LDETECTOR(1:7).EQ.'TIMEPIX')THEN
              MACHINE = 'TIME'
              MODEL = 'Unknown'
              CMACHINE = 'Timepix'
              MINICBF = .TRUE.
C
C---- Print for program flow
C
              CALLED = 'SETDETECT'
              COMMENT = 'Assign detector parameters '//CMACHINE
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
C
C     .. 
            ELSE
              FULLCBF = .TRUE.
              MACHINE = 'CBF '
              CMACHINE = 'CBF (Crystallographic Binary File)'
              COMPRESSION = 1
C
C---- Call CBF_INFO which in turn will call CBFWRAP to set up the parameters
C     for whatever detector this is in the same way the SETDETECT does for
C     other detectors.
C
C---- Print for program flow
C
              CALLED = 'CBF_INFO'
              COMMENT = 'MODE=3 to set detector parameters for CBF file'
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              CALL CBF_INFO(ODFILE,3,0,IERR)
            ENDIF
            GOTO 20
C
C---- Test first character of header
C
        ELSE IF (CHEAD(NCH).EQ.'{') THEN
C
C---- This can be an ADSC, or new style MSC/Rigaku header (R-AxisIV or V,
C     Jupiter, Saturn, etc..) Westbrook NOIR or SBC1 Westbrook, or Westbrook
C     TAURus CMOS detector, OR Rigaku installed Pilatus or Eiger.
C
C     Read keywords to determine which it is.
C
C---- Start of header, skip to start of first line
C
           NCH = NCH + 2
           MACHINE = 'ADSC'
           CMACHINE = 'ADSC'
           COMPRESSION = 1
C
C---- Search for end of this line
C
           NSTART = NCH
 14        IF (CHEAD(NCH).EQ.'}') THEN
C
C---- Print for program flow
C
             CALLED = 'SETDETECT'
             COMMENT = 'Assign detector parameters '//CMACHINE
             IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
             CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
             GOTO 20
             RETURN
           ENDIF
C
           IF (CHEAD(NCH).EQ.';') GOTO 16
           NCH = NCH + 1
           IF (NCH.GT.NNBYTE) THEN
             WRITE(IOUT,FMT=6006)
             IF (ONLINE) WRITE(ITOUT,FMT=6006)
 6006        FORMAT(//,1X,'**** Cannot find end of header ****')
             ISTAT = -2
             RETURN
           END IF
           GOTO 14
C
 16        NEND = NCH - 1
           NCHAR = NEND-NSTART+1
           LINE = ' '
           IF (NCHAR.LT.133) 
     +              WRITE(LINE,FMT=6034) (CHEAD(IC),IC=NSTART,NEND)
 6034      FORMAT(132A1)
           IF (DEBUG(110)) THEN
             WRITE(IOUT,FMT=6036) LINE(1:LENSTR(LINE))
             IF (ONLINE) WRITE(ITOUT,FMT=6036) LINE(1:LENSTR(LINE))
 6036        FORMAT(1X,'LINE IS: ',A)
           END IF
C
C---- Decode keyword
C
C                ******************************************
           CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C                ******************************************
           KEY = LINE(IBEG(1) :IEND(1))
           CALL CCPUPC(KEY)
           IF (KEY.EQ.'HEADER_BYTES') THEN
             NHBYTES = NINT(VALUE(2))
             NNBYTE = NHBYTES
             IF (FIRSTTIME) THEN
               NHBYTES = NHBYTES - 512
               IF (NHBYTES.GT.0) THEN
                 CALL GETBLK(BHEAD(513),NHBYTES,1,ISWAP,IERR)
C
C---- Trap error in read
C
                 IF (IERR.NE.0) THEN
                   WRITE(IOUT,FMT=6004) MACHINE
                   IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
                   ISTAT = -3
                   RETURN
                 END IF
               END IF
               FIRSTTIME = .FALSE.
             END IF
           ELSE IF (KEY.EQ.'BYTE_ORDER') THEN
             BORDER = LINE(IBEG(2):IEND(2))
             CALL CCPUPC(BORDER)
             BYTSWAP = ((LITEND().AND.(BORDER.EQ.'BIG')).OR.
     +                  (.NOT.LITEND().AND.(BORDER.NE.'BIG')))
C
C---- Raxis 5 has "DETECTOR_TYPE" keyword set to RAXIS
C
           ELSE IF (KEY.EQ.'DETECTOR_TYPE') THEN
             NEWRAXIS = .TRUE. 
             MACHINE = LINE(IBEG(2):IEND(2))
             IF (IFILESIZE.EQ.18002048)THEN
               MODEL = 'RAXISIV'
               CMACHINE = 'R-Axis IV or HTC (d*Trek format image)'
               COMPRESSION = 3
             ELSE
               MODEL = 'RAXISV'
               CMACHINE = 'R-Axis V (d*Trek format image)'
               COMPRESSION = 3
             ENDIF
             CALL CCPUPC(MACHINE)
             IF (MACHINE.EQ.'PILA')THEN
               MACHINE = 'RIPI'
               MODEL = LINE(IBEG(3):IEND(3))
               CMACHINE = 'Pilatus (d*Trek format image)'
               COMPRESSION = 6
             ELSE IF (MACHINE.EQ.'EIGE')THEN
               MACHINE = 'RIEI'
               MODEL = LINE(IBEG(3):IEND(3))
               CMACHINE = 'Eiger (d*Trek format image)'
               COMPRESSION = 6
             ENDIF
C
C---- Print for program flow
C
             CALLED = 'SETDETECT'
             COMMENT = 'Assign detector parameters '//CMACHINE
             IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
             CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
             GOTO 20
           ELSE IF (KEY(1:3).EQ.'RX_') THEN
             NEWRAXIS = .TRUE.
             MACHINE = 'RAXI'
             COMPRESSION = 3
             IF (IFILESIZE.EQ.18002048)THEN
               MODEL = 'RAXISIV'
               CMACHINE = 'R-Axis IV or HTC (d*Trek format image)'
             ELSE
               MODEL = 'RAXISV'
               CMACHINE = 'R-Axis V (d*Trek format image)'
             ENDIF
C
C---- Print for program flow
C
             CALLED = 'SETDETECT'
             COMMENT = 'Assign detector parameters '//CMACHINE
             IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
             CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
             GOTO 20
           ELSE IF (KEY.EQ.'CCD_DETECTOR_DESCRIPTION') THEN
             MACHINE = LINE(IBEG(2):IBEG(2)+3)
             COMPRESSION = 3
             CALL CCPUPC(MACHINE)
             IF (MACHINE.EQ.'JUPI')THEN
                MODEL = 'JUPITER'
                CMACHINE = 'Rigaku Jupiter'
             ENDIF
             IF (MACHINE.EQ.'SATU')THEN
                MODEL = 'SATURN'
                CMACHINE = 'Rigaku Saturn'
             ENDIF
             IF (MACHINE.EQ.'MERC')THEN
                MODEL = 'MERCURY'
                CMACHINE = 'Rigaku Mercury'
             ENDIF
             IF (MACHINE.EQ.'A200')THEN
                MODEL = 'A200'
                CMACHINE = 'Rigaku A200'
             ENDIF
C
C---- Print for program flow
C
             CALLED = 'SETDETECT'
             COMMENT = 'Assign detector parameters '//CMACHINE
             IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
             CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
             GOTO 20
C           ELSE IF (KEY.EQ.'APS1_GONIO_VALUES') THEN
           ELSE IF (KEY.EQ.'DETECTOR_NAMES') THEN
             MACHINE = LINE(IBEG(2):IBEG(2)+3)
             CALL CCPUPC(MACHINE)
             IF (MACHINE(1:4).EQ.'APS1') THEN
               MACHINE = 'SBC1'
               CMACHINE = 'Westbrook on SBC'
               COMPRESSION = 1
C
C---- Print for program flow
C
               CALLED = 'SETDETECT'
               COMMENT = 'Assign detector parameters '//CMACHINE
               IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
               CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
               GOTO 20
C
C---- Ed Westbrook's 
C
             ELSE IF (MACHINE(1:2).EQ.'BS') THEN
               MACHINE = 'NOIR'
               CMACHINE = 'Westbrook NOIR lens-coupled CCD'
               COMPRESSION = 1
C
C---- Print for program flow
C
               CALLED = 'SETDETECT'
               COMMENT = 'Assign detector parameters '//CMACHINE
               IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
               CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
               GOTO 20
C
C---- Ed Westbrook's CMOS detector has detector name RDI1
C
             ELSE IF (MACHINE(1:3).EQ.'RDI') THEN
               MACHINE = 'TAUR'
               CMACHINE = 'Westbrook Taurus CMOS detector'
               COMPRESSION = 1
C
C---- Print for program flow
C
               CALLED = 'SETDETECT'
               COMMENT = 'Assign detector parameters '//CMACHINE
               IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
               CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
               GOTO 20
             ELSE IF (MACHINE(1:4).EQ.'NOIR') THEN
C
C---- Early TAURUS images had the DETECTOR_NAMES set to NOIR, so
C     to distinguish early TAURUS and NOIR1 we need to read
C     the NOIR1_DETECTOR_DESCRIPTION keyword which is CMOS1 for TAURUS 
C     and NOIR-1 for NOIR lens coupled CCD, so just drop out of this block
C     to go on and read next record of header.
C
             END IF         
           ELSE IF (KEY.EQ.'NOIR1_DETECTOR_DESCRIPTION') THEN
             MACHINE = LINE(IBEG(2):IBEG(2)+3)
             IF (MACHINE(1:4).EQ.'NOIR') THEN
               MACHINE = 'NOIR'
               CMACHINE = 'Westbrook NOIR lens-coupled CCD'
               COMPRESSION = 1
C
C---- Print for program flow
C
               CALLED = 'SETDETECT'
               COMMENT = 'Assign detector parameters '//CMACHINE
               IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
               CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
               GOTO 20
             ELSE IF (MACHINE(1:4).EQ.'CMOS') THEN
               MACHINE = 'TAUR'
               CMACHINE = 'Westbrook Taurus CMOS detector'
               COMPRESSION = 1
C
C---- Print for program flow
C
               CALLED = 'SETDETECT'
               COMMENT = 'Assign detector parameters '//CMACHINE
               IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
               CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
               GOTO 20
             END IF
           END IF
C
C---- Read next line of header
C
           NCH = NCH + 2
           NSTART = NCH
           GOTO 14
C
      ELSE IF ((IWORD.EQ.1234).OR.(IWORDSW.EQ.1234)) THEN
           MACHINE = 'MAR'
           CMACHINE = 'Mar Image Plate'
           COMPRESSION = 1
C
C---- distinguish Mar Flat Panel by the image size and shape
C
           IF (IWORDSW.EQ.1234)THEN
             CALL SWAPHDR(BHEAD(5),1)
             CALL SWAPHDR(BHEAD(21),1)
             BYTSWAP = .TRUE.
           ENDIF
           IF (IHEAD(2).NE.IHEAD(6)/IHEAD(2))THEN
             MACHINE = 'MARF'
             CMACHINE = 'Rectangular Mar Flat Panel'
             MODEL = 'M555'
             COMPRESSION = 2
           ENDIF
C
C---- Print for program flow
C
           CALLED = 'SETDETECT'
           COMMENT = 'Assign detector parameters '//CMACHINE
           IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
           CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
           GOTO 20
      ELSE IF ((IWORD.EQ.1200).OR.(IWORD.EQ.1600).OR.
     +      (IWORD.EQ.1800).OR.(IWORD.EQ.2000).OR.
     +      (IWORD.EQ.2300).OR.(IWORD.EQ.2400).OR.
     +      (IWORD.EQ.3000).OR.(IWORD.EQ.3450).OR.
     +      (IWORDSW.EQ.1200).OR.(IWORDSW.EQ.1600).OR.
     +      (IWORDSW.EQ.1800).OR.(IWORDSW.EQ.2000).OR.
     +      (IWORDSW.EQ.2300).OR.(IWORDSW.EQ.2400).OR.
     +      (IWORDSW.EQ.3000).OR.(IWORDSW.EQ.3450)) THEN
        MACHINE = 'MAR'
        CMACHINE = 'Mar Image Plate'
        COMPRESSION = 1
C
C---- Print for program flow
C
        CALLED = 'SETDETECT'
        COMMENT = 'Assign detector parameters '//CMACHINE
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
       GOTO 20
C
C---- check for Oxford Diffraction - start with 'OD '
C
      ELSE IF (FWORD(1:3).EQ.'OD ') THEN
        MACHINE = 'OXFO'
        MODEL = 'SAPPHIRE'
        CMACHINE = 'Oxford Diffraction CCD detector'
        COMPRESSION = 4
C
C---- Print for program flow
C
        CALLED = 'SETDETECT'
        COMMENT = 'Assign detector parameters '//CMACHINE
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
       GOTO 20
C
C---- check for HDF5 file
C
      ELSE IF (FWORD(2:4).EQ.'HDF') THEN
        MACHINE = 'HDF5'
        MODEL = ''
        CMACHINE = 'Dectris Eiger HDF5'
        COMPRESSION = 6
C
C---- Print for program flow
C
        CALLED = 'SETDETECT'
        COMMENT = 'Assign detector parameters '//CMACHINE
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
       GOTO 20
C     
C---- check for DIPs which have a tailer rather than a header; 
C
      ELSE IF ((IFILESIZE.EQ.18001024).OR.
     $       (IFILESIZE.EQ.12501024).OR.
     $       (IFILESIZE.EQ.32001024))THEN
        MACHINE = 'DIP2'
        COMPRESSION = 5
        IF (MODEL.EQ.'M300')MODEL = '16BIT'
        IF (IFILESIZE.EQ.18001024)THEN
          CMACHINE = 'DIP 2030'
        ELSEIF(IFILESIZE.EQ.32001024)THEN
          CMACHINE = 'DIP 2040'
        ELSEIF(IFILESIZE.EQ.12501024)THEN
          CMACHINE = 'DIP 2000'
        ENDIF
C
C---- Print for program flow
C
        CALLED = 'SETDETECT'
        COMMENT = 'Assign detector parameters '//CMACHINE
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
       GOTO 20
C
C---- CCP4 packed images, can be Oxford Diffraction Chrysalis or XDS pack format
C
      ELSE IF (IHEAD(1).EQ.IHEAD(2)) THEN
        IF ((IHEAD(1).EQ.1024).OR.(IHEAD(1).EQ.2048)) THEN
          MACHINE = 'OXPK'
          COMPRESSION = 1
          CMACHINE = 'Crysalis'
          MODEL = 'Crysalis'
        ELSE
          MACHINE = 'PACK'
          COMPRESSION = 1
          CMACHINE = 'unknown'
          MODEL = 'unknown'
        END IF
C
C---- Print for program flow
C
        CALLED = 'SETDETECT'
        COMMENT = 'Assign detector parameters '//CMACHINE
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
       GOTO 20
        
C     
C---- Header not recognised, default to Mar
C     
      ELSE
        ISTAT = 1
        IISCN = .FALSE.
        IF (DEBUG(110)) THEN
          WRITE(IOUT,FMT=6010) 
          IF (ONLINE) WRITE(ITOUT,FMT=6010) 
 6010     FORMAT(1X,'*** From GETDETECT, detector type not',
     +         ' recognised ***')
        END IF
        MACHINE = 'MAR'
        CMACHINE = 'Default type, i.e. Mar Image Plate'
        COMPRESSION = 1
C
C---- Print for program flow
C
        CALLED = 'SETDETECT'
        COMMENT = 'Assign detector parameters '//CMACHINE
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        CALL SETDETECT(MODE,INSIZE,IFILESIZE,IERR)
       GOTO 20
      END IF
C
C---- nothing except MACHINE and perhaps MODEL should be set above here
C
 20   CONTINUE
      IF (.NOT.PHIONLY)THEN
        IF (MODEL.EQ.'RAXISHTC') THEN
          WRITE(IOUT,FMT=6024)
          IF (ONLINE)WRITE(ITOUT,FMT=6024)
 6024     FORMAT(/,' From information in the image file, the detector',
     $       ' has been ',/,' recognised as: Rigaku R-Axis HTC or new',
     $       ' style R-axis II'/,' If this is inc',
     $       'orrect you must supply a DETECTOR keyword',/)
        ELSE
          IF (CMACHINE(1:LENSTR(CMACHINE)).EQ.'ADSC') THEN
            WRITE(IOUT,FMT=6025)CMACHINE(1:LENSTR(CMACHINE))
            IF (ONLINE)WRITE(ITOUT,FMT=6025)CMACHINE(1:LENSTR(CMACHINE))
 6025       FORMAT(/,' From information in the image file, the detector',
     $      ' has been ',/,' recognized as: ',A,' or posibly an electr',
     $      'on microscope detector.',/,1x,'The wavelength will be used'
     $      ,' to distinguish these, if less than 0.05A then an EM',
     $       ' detector will be assumed.',/,' If this is inc',
     $       'orrect you must supply a DETECTOR keyword',/)
          ELSE
            WRITE(IOUT,FMT=6026)CMACHINE(1:LENSTR(CMACHINE))
            IF (ONLINE)WRITE(ITOUT,FMT=6026)CMACHINE(1:LENSTR(CMACHINE))
 6026       FORMAT(/,' From information in the image file, the detector'
     $      ,' has been ',/,' recognized as: ',A,/,' If this is inc',
     $       'orrect you must supply a DETECTOR keyword',/)
          ENDIF
        ENDIF
      ENDIF
      IF (MACHINE.EQ.'RAXI')THEN
         SVSCN = MODEL
      ELSE
         SVSCN = MACHINE
      ENDIF
      IF (DEBUG(110)) THEN
         WRITE(IOUT,FMT=6020) MACHINE,MODEL,HSERIAL,MINICBF
         IF (ONLINE) WRITE(ITOUT,FMT=6020) MACHINE,MODEL,HSERIAL,
     +            MINICBF   
 6020    FORMAT(1X,'From GETDETECT, detector type is:',A,' Model:',
     +          A,' Serial no:',A,' MINICBF is',L2)
      END IF
      CALL QCLOSE(INOD)
      RETURN
      END
      SUBROUTINE GETGAPS(NREC,IYLEN,IOFFSET,IOFFSETSP,RAST,IERR)
C     ==========================================================
C
C---- Sets up the gaps between tile boundaries for the Dectris hybrid
C     pixel detectors Pilatus, Eiger and Eiger2.
C     Makes use of the known sizes of the modules and the gaps between them
C     (this is required for correct identification).
C     It should be easy to modify code for other module and gap sizes,
C     providing these do not give rise to ambiguities in working out
C     the detector type from the overall size.
C     If this is a problem, the detector identifier from the image header
C     will need to be used.
C     ADSC hybrid pixel detector has not been coded yet.
C
C     Currently coded are the following:
C     Detector  module size   gap size
C     Pilatus    195 x 487     17 x 7
C     Eiger      514 x 1030    37 x 10
C     Eiger2     512 x 1028    38 x 12
      IMPLICIT NONE
C
C
C     DEBUG(104) for this subroutine
C
C
C     .. Parameters ..
C       Common block PARAMETER
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C
