C     .. Equivalences ..
      EQUIVALENCE (RHEAD(1),IHEAD(1))
      EQUIVALENCE (CHEAD(1),IHEAD(1))
      EQUIVALENCE (BHEAD(1),IHEAD(1))
      DATA DUMPHEAD/.FALSE./,DONE/.FALSE./
      SAVE
      THIS = 'GETHDR'
      INDENT = 4
      ISTAT = 0
      IF (DEBUG(102)) THEN
        WRITE(IOUT,FMT=6003) MACHINE, MINICBF, HDF5FILE, HEADONLY,
     +                       FULLCBF
        IF (ONLINE) WRITE(ITOUT,FMT=6003) MACHINE,MINICBF,HDF5FILE,
     +              HEADONLY,FULLCBF
 6003   FORMAT(1X,'Entering GETHDR with MACHINE=',A,'  MINICBF',L2,
     +             '  HDF5FILE',L2,'  HEADONLY',L2, 'FULLCBF',L2)
      END IF
C
C---- Turn off byte swapping in GETBLK
C
      ISWAP = 1
      HSIZED = 0.0
      HSIZEC = 0.0
C
C---- some control codes for odd formats
      CTRLZ = CHAR(26)
      CTRLD = CHAR(4)
      CTRL0 = CHAR(0)
      CTRLL = CHAR(12)
      BACKSLR = CHAR(13)
      BACKSLN = CHAR(10)
C
C---- always start by assuming oscillation axis is PHI (unless it's been 
C     set in control), and R-Axis
C     compression ratio is set to -1; some Rigaku headers don't set 
C     RAXISCOMP and their data is just unsigned 16-bit.
C
      IF(IHOSCAXIS.EQ.0)HOSCAXIS = '      '
      HCOMPR = -1

C
C---- now for machine specific stuff
C
      IF ((MACHINE.EQ.'MAR ').OR.(MACHINE(1:3).EQ.'CCD')
     $     .OR.(MACHINE.EQ.'MARF')) THEN
C
C
C---- When we first come to read the header, we do not know the record length
C     (NBYTE will be zero) so only read the first 100 bytes (25 I*4 words) but
C     once the record length is known, read whole record
C
        IF (NBYTE.EQ.0) THEN
          NNBYTE = 100
        ELSE
          NNBYTE = NBYTE
        END IF
        IERR = 0
        CALL GETBLK(BHEAD(1),NNBYTE,1,ISWAP,IERR)
C
C---- Trap error in read
C
        IF (IERR.NE.0) THEN
          WRITE(IOUT,FMT=6004) MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
 6004     FORMAT(/,1X,'Error trying to read header record',
     +           ' in image file for scanner type:',A,/,1X,
     +           'Check that the file is',
     +             ' the correct length')
          IF(SOCKLO)THEN
 7000       FORMAT('<?xml version="1.0"?><!DOCTYPE header_response>',
     $           '<header_response>',
     $           '<status>',
     $           '<code>error</code>',
     $           '<message>Error reading image header for scanner ',
     $           ' type',A,'</message>',
     $           '</status>',
     $           '<image_filename>',A,'</image_filename>',
     $           '</header_response>')
            WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          ENDIF
          ISTAT = -1
          RETURN
        END IF
C
C---- Work out byte order by checking value of NREC
C     NITEM is number of words we want to use from header
        NITEM = 25
        BYTSWAP = .FALSE.
        NREC = IHEAD(1)
C
C---- Changes to allow for new Mar345 scanner. First word in header
C     is "1234" if this is a Mar345 new format image.
C
        IF ((NREC.NE.1200).AND.(NREC.NE.1600).AND.
     +      (NREC.NE.1800).AND.(NREC.NE.2000).AND.
     +      (NREC.NE.2300).AND.(NREC.NE.2400).AND.
     +      (NREC.NE.3000).AND.(NREC.NE.3450).AND.
     +      (NREC.NE.1234)) THEN
          NXPIXO = NREC
          CALL SWAPHDR(BHEAD(1),NITEM)
          BYTSWAP = .TRUE.
          NREC = IHEAD(1)
          IF ((NREC.NE.1200).AND.(NREC.NE.1600).AND.
     +      (NREC.NE.1800).AND.(NREC.NE.2000).AND.
     +      (NREC.NE.2300).AND.(NREC.NE.2400).AND.
     +      (NREC.NE.3000).AND.(NREC.NE.3450).AND.
     +      (NREC.NE.1234)) THEN
            WRITE(IOUT,FMT=6000) NXPIXO,NREC
            IF (ONLINE) WRITE(ITOUT,FMT=6000) NXPIXO,NREC
 6000       FORMAT(//1X,' **** SERIOUS ERROR ****',/,1X,'The number',
     +             ' of pixels in the X direction must be 1200, 1600',
     +             ', 1800, 2000, 2300, 2400, 3000 or 3450.',
     +             /,1X,'The number from the first word of the',
     +             ' header record is',I16,/,1X,'with original byte ',
     +             'order or',I16,/,1X,'with swapped byte order',/,1X,
     +           'This should be the number of pixels in X for Mar300',
     +             ' scanners or "1234" for Mar345 scanners.',/,1X,
     +             'If this is NOT an image from a Mar Scanner, have ',
     +             'you included the appropriate',/,1X,'SCANNER (or ',
     +             'SITE) keyword ??')
            IF(SOCKLO)THEN
 7010         FORMAT('<?xml version="1.0"?><!DOCTYPE header_response>',
     $             '<header_response>',
     $             '<status>',
     $             '<code>error</code>',
     $             '<message>Incorrect size of image for detector ',
     $             'type ',A,'</message>',
     $             '</status>',
     $             '<image_filename>',A,'</image_filename>',
     $             '</header_response>')
              WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $             XODFILE(1:LENSTR(XODFILE))
              CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $             XMLLINE)
            ENDIF
            ISTAT = -2
            RETURN
          END IF
          WRITE(IOUT,FMT=6001)
          IF (ONLINE.AND..NOT.SOCKLO) WRITE(ITOUT,FMT=6001)
 6001     FORMAT(1X,'Image will be byte swapped')
        END IF
        MAR345 = (NREC.EQ.1234)
        IF (MAR345) THEN
C
C---- flat panel first 'Mar 555'
C
          IF(IHEAD(2).EQ.2560)THEN
            MACHINE = 'MARF'
            COMPRESSION = 2
            MODEL = 'M555'
            IYLEN = IHEAD(2)
            NREC = IHEAD(6)/IYLEN
          ELSE
C
C---- IPs next
C
            MODEL = 'M345'
            NREC = IHEAD(2)
            IYLEN = IHEAD(6)/NREC
          ENDIF
          HRAST = 0.001*IHEAD(7)
          HRASTY = 0.001*IHEAD(8)
          HWAVE = 0.000001*IHEAD(9)
          HDIST = 0.001*IHEAD(10)
          HPHIS = 0.001*IHEAD(11)
          HPHIE = 0.001*IHEAD(12)
          IF((HPHIS.GT.HPHIE).AND.(HPHIS-360.0.LT.HPHIE))
     $         THEN 
            HPHIE = HPHIE + 360.0
          ENDIF
          HPHIR = HPHIE - HPHIS
          HTWOTHETA = 0.001 * IHEAD(16)
        ELSE
          IYLEN = IHEAD(2)
          ILRECL = IHEAD(3)
          NNREC = IHEAD(4)
          NOVFL = IHEAD(5)
C
C---- Because of a bug in some versions of xips, calculate NRECOVFL from NOVFL
C
          NVAL = NREC/4
          NRECOVFL = (NOVFL-1)/NVAL + 1
          IF (NOVFL.EQ.0) NRECOVFL = 0
C
C---- Check for NaN inheader
C
          HWAVE = 0.0
          HDIST = 0.0
          HPHIS = 0.0
          HPHIE = 0.0
          HPHIR = HPHIE - HPHIS
C
C---- Image which were collected on a scanner hosted by a VAX, and are then
C     processed on a Unix machine, have to be converted by a program 
C     supplied by Mar. Unfortunately the reals in the header are NOT
C     converted correctly and are NOT real numbers !!
C     This can be trapped on an Alpha and SGI machines by testing the magnitude
C     of HWAVE, which is about E+24 in this case, but has been 0.05 in others !
C
          IF (.NOT.QISNAN(RHEAD(20))) HWAVE = RHEAD(20)
          IF ((HWAVE.GT.0.2).AND.(HWAVE.LT.2.0)) THEN
            IF (.NOT.QISNAN(RHEAD(21))) HDIST = RHEAD(21)
            IF (.NOT.QISNAN(RHEAD(22))) HPHIS = RHEAD(22)
            IF (.NOT.QISNAN(RHEAD(23))) HPHIE = RHEAD(23)
            IF (.NOT.QISNAN(RHEAD(22)).AND..NOT.QISNAN(RHEAD(23)))
     $           HPHIR = HPHIE - HPHIS
          END IF
        END IF
C
C---- Set the pixel size based on image size for old "IMAGE" style
C     format for Mar345 scanners
C
        IF (.NOT.MAR345) THEN
           IF (NREC.EQ.3450) THEN
             HRAST = 0.10
           ELSE IF (NREC.EQ.3000) THEN
            HRAST = 0.10
           ELSE IF (NREC.EQ.2400) THEN
             HRAST = 0.10
           ELSE IF (NREC.EQ.2300) THEN
             HRAST = 0.15
           ELSE IF (NREC.EQ.2000) THEN
             HRAST = 0.15
           ELSE IF (NREC.EQ.1800) THEN
             HRAST = 0.10
           ELSE IF (NREC.EQ.1600) THEN
             HRAST = 0.15
           ELSE IF (NREC.EQ.1200) THEN
             HRAST = 0.15
           END IF
        END IF
C
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6010) NREC,IYLEN,ILRECL,
     +          NNREC,NOVFL,NRECOVFL,BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,
     +          HRAST
          IF (ONLINE) WRITE(ITOUT,FMT=6010) NREC,IYLEN,ILRECL,
     +          NNREC,NOVFL,NRECOVFL,BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,
     +          HRAST
 6010   FORMAT(1X,'In GETHDR',/,1X,'From header record in image',/,1X,
     +         'NREC=',I5,' IYLEN=',I5,' LREC=',I5,' NREC=',I5,
     +         ' NOVFL=',I5,' NRECOVFL=',I5,/,1X,'Byte-swapping ',L1,
     +         /,1X,'Distance:',F8.2,'  Wavelength:',F8.5,'  Phi',
     +         ' start',F9.3,'  Phi end:',F9.3,' Pixel size',F7.3,'mm')
          NROWS = NITEM/5 + 1
          I1 = 1
          I2 = I1 + 4
          DO 2 I = 1,NROWS
            WRITE(IOUT,FMT=6012) I1,I2,(IHEAD(JJ),JJ=I1,I2)
            IF (ONLINE) WRITE(ITOUT,FMT=6012) 
     +              I1,I2,(IHEAD(JJ),JJ=I1,I2)
            I1 = I1 + 5
            I2 = MIN(NITEM, I1+4)
 2        CONTINUE
          I1 = 1
          I2 = I1 + 4
          DO 4 I = 1,NROWS
            WRITE(IOUT,FMT=6014) I1,I2,(RHEAD(JJ),JJ=I1,I2)
            IF (ONLINE) WRITE(ITOUT,FMT=6014)
     +          I1,I2,(RHEAD(JJ),JJ=I1,I2)
            I1 = I1 + 5
            I2 = MIN(NITEM, I1+4)
 4        CONTINUE
CAL          NROWS = 20
          I1 = 1
          I2 = I1 + 4
          DO 6 I = 1,NROWS
            WRITE(IOUT,FMT=6016) I1,I2,(CHEAD(JJ),JJ=I1,I2)
            IF (ONLINE) WRITE(ITOUT,FMT=6016)
     +                I1,I2,(CHEAD(JJ),JJ=I1,I2)
            I1 = I1 + 5
            I2 = MIN(NITEM, I1+4)
 6          CONTINUE
        END IF


C
C     ********************************
      ELSE IF (MACHINE.EQ.'RAXI') THEN
C     ********************************
C
C---- When we first come to read the header, we do not know the record length
C     (NBYTE will be zero) so only read the first 1600 bytes (400 I*4 words) but
C     once the record length is known, read whole record
C
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6018) NBYTE,ISWAP
          IF (ONLINE) WRITE(ITOUT,FMT=6018) NBYTE,ISWAP
 6018     FORMAT(/,1X,'In GETHDR, NBYTE=',I6,'  ISWAP=',I3)
        END IF
        IERR = 0
        NNBYTE = 4
        SNEXTRA = NEXTRA
        NEXTRA = 0
        CALL GETBLK(BHEAD(1),NNBYTE,1,ISWAP,IERR)
        NEXTRA = SNEXTRA
C
C---- Trap error in read
C
        IF (IERR.NE.0) THEN
          WRITE(IOUT,FMT=6004) MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
          IF(SOCKLO)THEN
            WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          ENDIF

          ISTAT = -1
          RETURN
        END IF
        NCH = 1
        IF (CHEAD(NCH).EQ.'{'.OR.NEWRAXIS) THEN
chrp 20.08.2007 we shouldn't set INVERTX for newraxis!
          NEWRAXIS = .TRUE.
chrp 20.08.2007           INVERTX = .TRUE.
C
C---- start of new-style R-axis header
C
          NNBYTE = 2044
          IERR = 0
          CALL GETBLK(BHEAD(5),NNBYTE,1,ISWAP,IERR)
C
C---- Start of header, skip to start of first line
C
          NCH = NCH + 2
C     
C---- Search for end of this line
C
          NSTART = NCH
 3014     IF (CHEAD(NCH).EQ.'}')GOTO 3018
C
          IF (CHEAD(NCH).EQ.';')GOTO 3016
          NCH = NCH + 1
          IF (NCH.GT.NNBYTE) THEN
            WRITE(IOUT,FMT=6032)MACHINE
            IF (ONLINE) WRITE(ITOUT,FMT=6032)MACHINE
            IF(SOCKLO)THEN
              WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $             XODFILE(1:LENSTR(XODFILE))
              CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $             XMLLINE)
            ENDIF
            ISTAT = -2
            RETURN
          END IF
          GOTO 3014
C     
 3016     NEND = NCH - 1
          NCHAR = NEND-NSTART+1
          LINE = ' '
          IF (NCHAR.LE.240) 
     +         WRITE(LINE,FMT=6034) (CHEAD(I),I=NSTART,NEND)
c     hrp12032001 6034      FORMAT(132A1)
          IF (DEBUG(102)) THEN
            WRITE(IOUT,FMT=6036) LINE(1:LENSTR(LINE))
            IF (ONLINE) WRITE(ITOUT,FMT=6036) LINE(1:LENSTR(LINE))
chrp12032001 6036        FORMAT(1X,'LINE IS: ',A)
          END IF
C
C---- Decode keyword
C
C                ******************************************
          CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C                ******************************************
          KEY = LINE(IBEG(1) :IEND(1))
          CALL CCPUPC(KEY)
          IF (KEY.EQ.'HEADER_BYTES') THEN
            NHBYTES = NINT(VALUE(2))
            NNBYTE = NHBYTES
            HHEAD = NHBYTES
            IF (FIRSTTIME) THEN
              NHBYTES = NHBYTES - 512
              IF (NHBYTES.GT.0) THEN
                CALL GETBLK(BHEAD(513),NHBYTES,1,ISWAP,IERR)
C     
C---- Trap error in read
C
                IF (IERR.NE.0) THEN
                  WRITE(IOUT,FMT=6004) MACHINE
                  IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
                  IF(SOCKLO)THEN
                    WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $                   XODFILE(1:LENSTR(XODFILE))
                    CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $                   XMLLINE)
                  ENDIF
                  ISTAT = -1
                  RETURN
                END IF
              END IF
              FIRSTTIME = .FALSE.
            END IF
          ELSE IF (KEY.EQ.'BYTE_ORDER') THEN
            BORDER = LINE(IBEG(2):IEND(2))
            CALL CCPUPC(BORDER)
            BYTSWAP = ((LITEND().AND.(BORDER.EQ.'BIG')).OR.
     +           (.NOT.LITEND().AND.(BORDER.NE.'BIG')))
          ELSE IF (KEY.EQ.'SIZE1') THEN
            IYLEN = NINT(VALUE(2))
          ELSE IF (KEY.EQ.'SIZE2') THEN
            NREC = NINT(VALUE(2))
c
c---- pixel size isn't stored as such in the example I have, but it can 
c     be calculated from CCD_DETECTOR_SIZE/SIZE1
c
          ELSE IF (KEY.EQ.'RX_DETECTOR_SIZE') THEN
            HSIZED = VALUE(2)
          ELSE IF (KEY.EQ.'RAXIS_COMPRESSION_RATIO') THEN
            HCOMPR = VALUE(2)
          ELSE IF (KEY.EQ.'SOURCE_WAVELENGTH') THEN
            HWAVE = VALUE(3)
          ELSE IF (KEY.EQ.'ROTATION') THEN
            HPHIS = VALUE(2)
            HPHIE = VALUE(3)
            OSCRNG = VALUE(4)
            HPHIR = OSCRNG
C
C---- is distance always 6th on the GON_VALUES list, or do I need to
C     be more general?
C
          ELSE IF (KEY.EQ.'RX_GONIO_VALUES') THEN
            HDIST = VALUE(7)
          ELSE IF (KEY.EQ.'RX_SPATIAL_DISTORTION_TYPE') THEN
            IF(LINE(IBEG(2):IEND(2)).EQ.'Simple_spatial')
     $           SIMPLE = .TRUE.
          ELSE IF (KEY.EQ.'RX_SPATIAL_DISTORTION_INFO') THEN
            BEAMXD = VALUE(2)*VALUE(4)
            BEAMYD = VALUE(3)*VALUE(5)
            BEAMSET = .TRUE.
          ELSE IF (KEY.EQ.'RX_SPATIAL_DISTORTION_VECTORS') THEN
C     
C---- set omegafd and invertx here for Rigaku new-style headers. 
C     They are stored in a 2x2 matrix, first line is the Fast direction,
C     second line is the Slow direction.
C
C---- Note well: Rigaku CCDs and R-Axis detectors have different values!
C
C     ( 0  1  1  0) OMEGAFD 270, invertx = .false. 
C     ( 0  1 -1  0) OMEGAFD  90, invertx = .true. 
C     ( 1  0  0  1) OMEGAFD   0, invertx = .true. 
C     ( 1  0  0 -1) OMEGAFD 180, invertx = .false.
 
C     ( 0 -1  1  0) OMEGAFD 270, invertx = .true. 
C     ( 0 -1 -1  0) OMEGAFD  90, invertx = .false. 
C     (-1  0  0  1) OMEGAFD   0, invertx = .false. 
C     (-1  0  0 -1) OMEGAFD 180, invertx = .true.
C
            IF(IOMEGAF.EQ.0)THEN
              INVERTX = .TRUE.
              IF(VALUE(5).EQ.1)THEN
                OMEGAFD = 0.0
                IF(VALUE(2).EQ.-1)INVERTX = .FALSE.
              ELSEIF(VALUE(5).EQ.-1)THEN
                OMEGAFD = 180.0
                IF(VALUE(2).EQ.1)INVERTX = .FALSE.
              ELSEIF(VALUE(4).EQ.1)THEN
                OMEGAFD = 270.0
                IF(VALUE(3).EQ.1)INVERTX = .FALSE.
              ELSEIF(VALUE(4).EQ.-1)THEN
                OMEGAFD = 90.0
                IF(VALUE(3).EQ.-1.)INVERTX = .FALSE.
              ENDIF
              OMEGAF = OMEGAFD * DTOR
              IOMEGAF = 2
            ENDIF
            
C
          END IF
          NCH = NCH + 2
          NSTART = NCH
          GOTO 3014
        
 3018     HPHIE = HPHIS + OSCRNG
          IF((HSIZED.GT.0.0).AND.(IYLEN.GT.0))HRAST=HSIZED/FLOAT(IYLEN)
C        IF(SIMPLE.and.BEAMSET)THEN
          IF(BEAMSET)THEN
c     Calculate beam centre...
            HBEAMX = 
     $         ABS(BEAMXD * COS(OMEGAF) + BEAMYD * SIN(OMEGAF))
            HBEAMY = 
     $         ABS(BEAMXD * SIN(OMEGAF) + BEAMYD * COS(OMEGAF))
            IF(IBEAM.EQ.0)IBEAM = 3
C
C---- calculate pixel size
C
            HRAST = HSIZED/FLOAT(NREC)
          ENDIF
        ELSE
C
C--- end of new-style R-axis header; start for old-style header
C
C
C---- Work out byte order by checking value of NREC
C     NITEM is number of words we want to use from header - remember
C     that we've read 4 bytes at the start of the R-Axis block
C
        IF (NBYTE.EQ.0) THEN
          NNBYTE = 1596
        ELSE
          NNBYTE = NBYTE - 4
        END IF
        IERR = 0
        CALL GETBLK(BHEAD(5),NNBYTE,1,ISWAP,IERR)
C
C---- Trap error in read
C
        IF (IERR.NE.0) THEN
          WRITE(IOUT,FMT=6004) MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
          IF(SOCKLO)THEN
            WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          ENDIF
          ISTAT = -1
          RETURN
        END IF
c*        IF(NNBYTE.EQ.1596)NNBYTE = 1600
        NITEM = 400
        BYTSWAP = .FALSE.
cdms21.09.2004   Change to make reading R-axis headers more general.
        NREC = IHEAD(194)
        IF ((NREC.LT.500).OR.(NREC.GT.10000)) THEN
            NXPIXO = NREC
            CALL SWAPHDR(BHEAD(1),NITEM)
            BYTSWAP = .TRUE.
          NREC = IHEAD(194)
          IF ((NREC.LT.500).OR.(NREC.GT.10000)) THEN
            WRITE(IOUT,FMT=6002) NXPIXO,NREC
            IF (ONLINE) WRITE(ITOUT,FMT=6002) NXPIXO,NREC
 6002       FORMAT(//1X,' **** FATAL ERROR ****',/,1X,'The number',
     +           ' of pixels in the X direction is unreasonable.',
     +           /,1X,'The number from the first word of the',
     +           ' header record is',I16,/,1X,'with original byte ',
     +           'order or',I16,/,1X,'with swapped byte order')
c     
c     dms21.09.2004   End changed section.
c     
            IF(SOCKLO)THEN
              WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $             XODFILE(1:LENSTR(XODFILE))
              CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $             XMLLINE)
            ENDIF
            ISTAT = -2
            RETURN
          ENDIF
          WRITE(IOUT,FMT=6001)
          IF (ONLINE.AND..NOT.SOCKLO) WRITE(ITOUT,FMT=6001)
        END IF
        IYLEN = IHEAD(193)
C
C---- Distance, wavelength and phi values are only present in RaxisIV image
C     headers (as far as I can tell !!) Only set HRAST if this is NOT an
C     Raxis-II detector, as HRAST has been set to the correct value in
C     SETDETECT
C
        IF ((NREC.NE.1900).AND.(NREC.NE.950)) THEN
          HRAST = RHEAD(195)
        END IF
        IF ((NREC.EQ.1900).AND.(MODEL.EQ.'RAXISHTC')) THEN
C
C---- Deal with new format of Raxis II images. Set MODEL to RAXIS2NU
C     Also need to set CUTOFF (overload values)
C
           HRAST = RHEAD(195)
           MODEL = 'RAXIS2NU'
           IF (ICUT.EQ.0) CUTOFF = 250000
           IF (IPRCUT.EQ.0) PRCUTOFF = 128000
           YSCAL = 105.0/101.7
           GAIN = 5.0
           IGAIN = 1
C           WRITE(IOUT,FMT=8888) HRAST
C           IF (ONLINE) WRITE(ITOUT,FMT=8888) HRAST
 8888      FORMAT(1X,'In GETHDR, Hrast set from RHEAD(195)',F7.4)
        END IF
        HDIST = 0.0
        HWAVE = 0.0
        HPHIS = 0.0
        HPHIE = 0.0
        HPHIR = HPHIE - HPHIS
C
C---- Use header information to work out if there are "extra" bytes
C     at the end of each record. (Present on all but latest R-axis II images)
C
        IF ((MODEL.NE.'RAXISIV').AND.(MODEL.NE.'RAXISV')
     $       .AND.(MODEL.NE.'RAXISHTC').AND.(MODEL.NE.'RAXIS2NU')) 
     $       NEXTRA = IHEAD(197) - 2*IYLEN
C
        IF ((MODEL.EQ.'RAXISIV').or.(MODEL.EQ.'RAXISV')
     $       .or.(MODEL.EQ.'RAXISHTC').or.(MODEL.EQ.'RAXIS2NU')) THEN
          IF (.NOT.QISNAN(RHEAD(74))) HWAVE = RHEAD(74)
          IF (.NOT.QISNAN(RHEAD(87))) HDIST = RHEAD(87)
          IF (.NOT.QISNAN(RHEAD(132))) HPHIS = RHEAD(132)
          IF (.NOT.QISNAN(RHEAD(133))) HPHIE = RHEAD(133)
          IF (.NOT.QISNAN(RHEAD(132)).AND..NOT.QISNAN(RHEAD(133)))
     $         HPHIR = HPHIE - HPHIS
        END IF
c
c---- only read beam centre for HTC or new Raxis II - it's too unreliable mostly
c
        IF ((MODEL.EQ.'RAXISHTC').or.(MODEL.EQ.'RAXIS2NU')) THEN
          IF (.NOT.QISNAN(RHEAD(136))) BEAMXD = RHEAD(136)*0.1
          IF (.NOT.QISNAN(RHEAD(137))) BEAMYD = RHEAD(137)*0.1
          HBEAMX = 
     $         ABS(BEAMXD * COS(OMEGAF) + BEAMYD * SIN(OMEGAF))
          HBEAMY = 
     $         ABS(BEAMXD * SIN(OMEGAF) + BEAMYD * COS(OMEGAF))
          IF(IBEAM.EQ.0)IBEAM = 3

        END IF
        If (Debug(102)) Then
          Write(Iout,Fmt=6008) NREC,IYLEN,Nextra,
     +         Bytswap,Hdist,Hwave,Hphis,Hphie,HRAST
          If (Online) Write(Itout,Fmt=6008) NREC,IYLEN,Nextra,Bytswap,
     +         Hdist,Hwave,Hphis,Hphie,HRAST
 6008     Format(1x,'In GETHDR',/,1X,'From Header Record In Image',/,1x,
     +         'NREC=',I5,' IYLEN=',I5,' Nextra=',I5,
     +         /,1x,'Byte-Swapping ',L1,
     +         /,1x,'Distance:',F8.2,'  Wavelength:',F8.5,'  Phi',
     +         ' Start',F9.3,'  Phi End:',F9.3,' Pixel size',F7.3,'mm')
          IF ((MODEL.EQ.'RAXISHTC').or.(MODEL.EQ.'RAXIS2NU')) THEN
            WRITE(IOUT,FMT=6009)HBEAMX,HBEAMY,IBEAM
            IF(ONLINE)WRITE(ITOUT,FMT=6009)HBEAMX,HBEAMY,IBEAM
 6009       format(' Beam coordinates from image header are ',2F8.2,
     $           1X,I4)
          ENDIF
          NROWS = NITEM/5 + 1
          I1 = 1
          I2 = I1 + 4
          DO 7 I = 1,NROWS
            WRITE(IOUT,FMT=6012) I1,I2,(IHEAD(JJ),JJ=I1,I2)
            IF (ONLINE) WRITE(ITOUT,FMT=6012)
     +           I1,I2,(IHEAD(JJ),JJ=I1,I2)
            I1 = I1 + 5
            I2 = MIN(NITEM, I1+4)
 7        CONTINUE
 6012     FORMAT(//1X,'Header record as integers',/,
     +         (1X,'Items ',I4,' to ',I4,5X,5I12))
C     
          I1 = 1
          I2 = I1 + 4
          DO 8 I = 1,NROWS
            WRITE(IOUT,FMT=6014) I1,I2,(RHEAD(JJ),JJ=I1,I2)
            IF (ONLINE) WRITE(ITOUT,FMT=6014)
     +           I1,I2,(RHEAD(JJ),JJ=I1,I2)
            I1 = I1 + 5
            I2 = MIN(NITEM, I1+4)
 8        CONTINUE
 6014     FORMAT(//1X,'Header record as reals',/,
     +         (1X,'Items ',I4,' to ',I4,5X,5E12.3))
C     
C     AL          NROWS = 20
          I1 = 1
          I2 = I1 + 4
          DO 9 I = 1,NROWS
            WRITE(IOUT,FMT=6016) I1,I2,(CHEAD(JJ),JJ=I1,I2)
            IF (ONLINE) WRITE(ITOUT,FMT=6016)
     +           I1,I2,(CHEAD(JJ),JJ=I1,I2)
            I1 = I1 + 5
            I2 = MIN(NITEM, I1+4)
 9        CONTINUE
 6016     FORMAT(//1X,'Header record as characters',/,
     +         (1X,'Items ',I4,' to ',I4,5X,20A))
          
        END IF
      endif

C     ********************************
      ELSE IF (MACHINE.EQ.'ADSC') THEN
C     ********************************
C
C---- There are always at least 512 bytes in the header (there may be more)
C
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6018) NBYTE,ISWAP
          IF (ONLINE) WRITE(ITOUT,FMT=6018) NBYTE,ISWAP
        END IF
        IERR = 0
        NNBYTE = 512
        FIRSTTIME = .TRUE.
        OMEGASET = .FALSE.
 10     CALL GETBLK(BHEAD(1),NNBYTE,1,ISWAP,IERR)
C
C---- Trap error in read
C
        IF (IERR.NE.0) THEN
          WRITE(IOUT,FMT=6004) MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
          IF(SOCKLO)THEN
            WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          ENDIF
          ISTAT = -1
          RETURN
        END IF
C
        IF (DEBUG(102)) THEN       
            NITEM = NNBYTE/4
            WRITE(IOUT,FMT=6030) (CHEAD(I),I=1,NITEM)
            IF (ONLINE) WRITE(ITOUT,FMT=6030) (CHEAD(I),I=1,NITEM)
 6030       FORMAT(1X,20A1)
        END IF
C
C---- Decode the header information
C
        NCH = 0
        NCH = NCH + 1
        IF (CHEAD(NCH).EQ.'{') THEN
C
C---- Start of header, skip to start of first line
C
           NCH = NCH + 2
C
C---- Search for end of this line
C
           NSTART = NCH
 14        IF (CHEAD(NCH).EQ.'}') GOTO 18
C
           IF (CHEAD(NCH).EQ.';') GOTO 16
           NCH = NCH + 1
           IF (NCH.GT.NNBYTE) THEN
             WRITE(IOUT,FMT=6032)MACHINE
             IF (ONLINE) WRITE(ITOUT,FMT=6032)MACHINE
 6032        FORMAT(//,1X,'**** ERROR READING HEADER **** ',/,
     $            'For detected machine type ',A)
             IF(SOCKLO)THEN
               WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $              XODFILE(1:LENSTR(XODFILE))
               CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $              XMLLINE)
             ENDIF
             
             ISTAT = -2
             RETURN
           END IF
           GOTO 14
C
 16        NEND = NCH - 1
           NCHAR = NEND-NSTART+1
           LINE = ' '
           IF (NCHAR.LE.240) 
     +              WRITE(LINE,FMT=6034) (CHEAD(I),I=NSTART,NEND)
 6034      FORMAT(240A1)
           IF (DEBUG(102)) THEN
             WRITE(IOUT,FMT=6036) LINE(1:LENSTR(LINE))
             IF (ONLINE) WRITE(ITOUT,FMT=6036) LINE(1:LENSTR(LINE))
 6036        FORMAT(1X,'LINE IS: ',A)
           END IF
C
C---- Decode keyword
C
C                ******************************************
           CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C                ******************************************
           KEY = LINE(IBEG(1) :IEND(1))
           CALL CCPUPC(KEY)
           IF (KEY.EQ.'HEADER_BYTES') THEN
             NHBYTES = NINT(VALUE(2))
             NNBYTE = NHBYTES
             HHEAD = NHBYTES
             IF (FIRSTTIME) THEN
               NHBYTES = NHBYTES - 512
               IF (NHBYTES.GT.0) THEN
                 CALL GETBLK(BHEAD(513),NHBYTES,1,ISWAP,IERR)
C
C---- Trap error in read
C
                 IF (IERR.NE.0) THEN
                   WRITE(IOUT,FMT=6004) MACHINE
                   IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
                   IF(SOCKLO)THEN
                     WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $                    XODFILE(1:LENSTR(XODFILE))
                     CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $                    XMLLINE)
                   ENDIF
                   ISTAT = -1
                   RETURN
                 END IF
               END IF
               FIRSTTIME = .FALSE.
             END IF
           ELSE IF (KEY.EQ.'BYTE_ORDER') THEN
             BORDER = LINE(IBEG(2):IEND(2))
             CALL CCPUPC(BORDER)
             BYTSWAP = ((LITEND().AND.(BORDER.EQ.'BIG')).OR.
     +                  (.NOT.LITEND().AND.(BORDER.NE.'BIG')))
           ELSE IF (KEY.EQ.'SIZE1') THEN
             IYLEN = NINT(VALUE(2))
           ELSE IF (KEY.EQ.'SIZE2') THEN
             NREC = NINT(VALUE(2))
           ELSE IF (KEY.EQ.'PIXEL_SIZE') THEN
             HRAST = VALUE(2)
           ELSE IF (KEY.EQ.'DISTANCE') THEN
             HDIST = VALUE(2)
           ELSE IF (KEY.EQ.'WAVELENGTH') THEN
             HWAVE = VALUE(2)
           ELSE IF (KEY.EQ.'OSC_AXIS') THEN
             USEOSCAXIS = .TRUE.
             HOSCAXIS = LINE(IBEG(2):IEND(2))
           ELSE IF (KEY.EQ.'OSC_RANGE') THEN
             OSCRNG = VALUE(2)
           ELSE IF (KEY.EQ.'AXIS') THEN
             IF(IHOSCAXIS.EQ.0)HOSCAXIS = LINE(IBEG(2):IEND(2))
C---- Confusion exists about whether the phi start should be taken
C     from the PHI keyword or the OSC_START keyword. For the SSRL ADSC
C     detector OSC_START is always zero, so use PHI.
           ELSE IF (KEY.EQ.'OSC_START') THEN
             PHISTART = VALUE(2)
           ELSE IF (KEY.EQ.'PHI'.AND..NOT.USEOSCAXIS) THEN
             PHISTART = VALUE(2)
           ELSE IF (KEY.EQ.'OMEGA') THEN
             OMEGASET = .TRUE.
             OMEGASTART = VALUE(2)
           ELSE IF (KEY.EQ.'TWO_THETA') THEN
             HTWOTHETA = VALUE(2)
C
C---- add beam position read from image header
C
           ELSE IF (KEY.EQ.'BEAM_CENTER_X')THEN
              HBEAMX = VALUE(2)
           ELSE IF (KEY.EQ.'BEAM_CENTER_Y')THEN
              HBEAMY = VALUE(2)
           ELSE IF (KEY.EQ.'DETECTOR_SN')THEN
              HSERIAL = LINE(IBEG(2):IEND(2))

C 
C---- Deal with specific beamlines at Spring-8 with reversed phi
C
              IF (HSERIAL(1:3).EQ.'915')THEN
C     TAKANORI: this is Q315 in BL38B1 at Spring-8
                IF (.NOT.UPDATEOMEGA) THEN
                  OMEGAFD = 180.0 
                  OMEGAF = OMEGAFD * DTOR
                  UPDATEOMEGA = .TRUE.
                  WRITE(IOUT,FMT=6058) 
                  IF (ONLINE) WRITE(ITOUT,FMT=6058)
                ENDIF
              ENDIF

           ELSE IF (KEY.EQ.'DATE')THEN
              HMONTH = LINE(IBEG(3):IEND(3))
              HDATE = VALUE(4)
              HYEAR = VALUE(6)
C
C---- HDATEC is an 8 digit integer containing the image collection date.
C
              CALL HEADDATE(HDATEC,HMONTH,HDATE,HYEAR)
           END IF
           NCH = NCH + 2
           NSTART = NCH
           GOTO 14
        END IF
 18     CONTINUE
        IF((HBEAMX.GT.0.0).AND.(HBEAMY.GT.0.0).AND.(IBEAM.EQ.0))IBEAM=3
C
C---- now assign correct axis for oscillations
C
        CALL CCPUPC(HOSCAXIS)
        IF (HOSCAXIS.EQ.'OMEGA') THEN
          IF (OMEGASET) THEN
            HPHIS = OMEGASTART
          ELSE
            HPHIS = PHISTART
          END IF
        ELSE IF (HOSCAXIS.EQ.'PHI') THEN
          HPHIS = PHISTART
        ELSE
          HOSCAXIS = 'NOTSET'
          HPHIS = PHISTART
        ENDIF
        HPHIE = HPHIS + OSCRNG
        HPHIR = OSCRNG
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6037) HSERIAL(1:LENSTR(HSERIAL)),
     +                         NREC,IYLEN,HRAST,BYTSWAP,HDIST,HWAVE,
     +                         HOSCAXIS(1:LENSTR(HOSCAXIS)),
     +                         OSCRNG,PHISTART,OMEGASTART,HTWOTHETA,
     +                         HBEAMX,HBEAMY,OMEGAFD
          IF (ONLINE) WRITE(ITOUT,FMT=6037) HSERIAL(1:LENSTR(HSERIAL)),
     +                         NREC,IYLEN,HRAST,BYTSWAP,
     +                         HDIST,HWAVE,HOSCAXIS(1:LENSTR(HOSCAXIS)),
     +                         OSCRNG,PHISTART,OMEGASTART,HTWOTHETA,
     +                         HBEAMX,HBEAMY,OMEGAFD
 6037     FORMAT(1X,'In GETHDR',/,1X,'From header record in image',/,1X,
     +         'Serial number:',A,
     +         '  NREC=',I5,' IYLEN=',I5,' Pixel size',F6.3,
     +         1X,'Byte-swapping ',L1,
     +         /,1X,'Distance:',F8.2,'  Wavelength:',F8.5,' HOSCAXIS ',
     +         A,' OSCRNG',F5.3,' PHISTART',F9.3,' OMEGASTART',F9.3,
     +         /,1X,' HTWOTHETA',F6.3,' HBEAMX',F8.2,' HBEAMY',F8.2,
     +         ' OMEGA',F8.2)
        END IF
C
C---- Put in new code here to decode header information for other
C     types of scanner
C

C     ********************************
      ELSE IF (MACHINE.EQ.'LIPS') THEN
C     ********************************
        IERR = 0
C
C---- Header size is variable, so read in 2000 bytes and find the end
C     of the header, denoted by } and newline.
C
        NNBYTE = 2000
        FIRSTTIME = .TRUE.
 20     CALL GETBLK(BHEAD(1),NNBYTE,1,ISWAP,IERR)
C
C---- Trap error in read
C
        IF (IERR.NE.0) THEN
          WRITE(IOUT,FMT=6004) MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
          IF(SOCKLO)THEN
            WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
          ENDIF
          ISTAT = -1
          RETURN
        END IF
        IF (DEBUG(102)) THEN       
            NITEM = NNBYTE
            WRITE(IOUT,FMT=6030) (CHEAD(I),I=1,NITEM)
            IF (ONLINE) WRITE(ITOUT,FMT=6030) (CHEAD(I),I=1,NITEM)
        END IF      
C
C---- Find the terminator, also count number of newline characters
C     This assumes that the second character is a newline.
C
        NULINE = CHEAD(2)
        NHLINES = 0
        NSTART = 1
        DO 22 I = 1,NNBYTE
          IF (CHEAD(I).EQ.NULINE) THEN
            NHLINES = NHLINES + 1
            IF (NHLINES.GT.NHLMAX) THEN
              WRITE(IOUT,FMT=6052) NHLINES,NHLMAX
              IF (ONLINE) WRITE(ITOUT,FMT=6052) NHLINES,NHLMAX
 6052         FORMAT(/,1X,'***** FATAL ERROR *****',/,1X,'There are',
     +             I5,' lines in the header, but program is ',
     $             'dimensioned',/,1X,'for a maximum of',I5,
     $             '. Change parameter NHLMAX ',
     +             'in subroutine gethdr.')
              IF(SOCKLO)THEN
 7080           FORMAT('<?xml version="1.0"?>',
     $               '<!DOCTYPE header_response>',
     $               '<header_response>',
     $               '<status>',
     $               '<code>error</code>',
     $               '<message>Error reading image header for ',
     $               'detector type ',A,' - header too big, contact ',
     $               'program authors for advice</message>',
     $               '</status>',
     $               '<image_filename>',A,'</image_filename>',
     $               '</header_response>')
                WRITE(XMLLINE,FMT=7080)MACHINE(1:LENSTR(MACHINE)),
     $               XODFILE(1:LENSTR(XODFILE))
                CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $               XMLLINE)
              ENDIF
              ISTAT = -2
              RETURN
            END IF
            NCHAR = I - NSTART + 1
            DO 23 JJ = 1,NCHAR 
              HLINES(NHLINES)(JJ:JJ) = CHEAD(NSTART+JJ-1)
 23         CONTINUE
            NSTART = I + 1
          END IF
          IF (CHEAD(I).EQ.'}') THEN
            NTERM = I
            GOTO 24
          END IF
 22     CONTINUE
C
C---- ERROR, terminator not found
C
        WRITE(IOUT,FMT=6050) NNBYTE,MACHINE
        IF (ONLINE) WRITE(ITOUT,FMT=6050) NNBYTE,MACHINE
 6050   FORMAT(/,1X,'***** FATAL ERROR *****',/,1X,'Terminator ',
     +   ' "}" not found in first',I6,' bytes of header',/,1X,
     +   'for scanner type: ',A)
        IF(SOCKLO)THEN
 7100     FORMAT('<?xml version="1.0"?><!DOCTYPE header_response>',
     $         '<header_response>',
     $         '<status>',
     $         '<code>error</code>',
     $         '<message>No terminator found for header for ',
     $         'scanner type ',A,'</message>',
     $         '</status>',
     $         '<image_filename>',A,'</image_filename>',
     $         '</header_response>')
          WRITE(XMLLINE,FMT=7100)MACHINE(1:LENSTR(MACHINE)),
     $         XODFILE(1:LENSTR(XODFILE))
          CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        ENDIF
        ISTAT = -2
        RETURN
C
C---- Terminator found, transfer header info to separate lines into
C     array HLINES. Assumes there are not more than NHLMAX lines in header.
C
 24     NHBYTE = NTERM + 1
        IF (DEBUG(102)) THEN       
            WRITE(IOUT,FMT=6056) NHLINES,(HLINES(I),I=1,NHLINES)
            IF (ONLINE) WRITE(ITOUT,FMT=6056) NHLINES,
     +                      (HLINES(I),I=1,NHLINES)
 6056       FORMAT(1X,'In GETHDR',/,1X,
     +          'There are',I4,' lines in the header as follows',
     +             /,(1X,A))
        END IF      
C
C---- Now parse the lines to get image size
C
        DO 26 I = 1,NHLINES
C                ******************************************
           CALL MPARSE(HLINES(I),IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C                ******************************************
           KEY = HLINES(I)(IBEG(1) :IEND(1))
           CALL CCPUPC(KEY)
           IF (KEY.EQ.'DIM_1') THEN
             IYLEN = NINT(VALUE(2))
           ELSE IF (KEY.EQ.'DIM_2') THEN
             NREC = NINT(VALUE(2))
           ELSE IF (KEY.EQ.'PIXSIZE') THEN
             HRAST = 0.001*NINT(VALUE(2))
           ELSE IF (KEY.EQ.'BYTEORDER') THEN
             BORDER2 = HLINES(I)(IBEG(2):IEND(2))
             CALL CCPUPC(BORDER2)
             BYTSWAP = .NOT.((LITEND().AND.(BORDER.EQ.'HIGHBYTEFIRST'))
     +             .OR.(.NOT.LITEND().AND.(BORDER.NE.'HIGHBYTEFIRST')))
           END IF
 26     CONTINUE
C
C---- Now position file in correct place.
C
        CALL QBACK(INOD,NNBYTE)
        CALL GETBLK(BHEAD(1),NHBYTE,1,ISWAP,IERR)
C
C---- Mar CCD detector (type MARCCD)
C
C     ********************************
      ELSE IF (MACHINE.EQ.'MARC') THEN
C     ********************************
C
        IERR = 0
        CALL GETBLK(BHEAD(1),NHBYTE,1,ISWAP,IERR)
C
C---- Trap error in read
C
        IF (IERR.NE.0) THEN
          WRITE(IOUT,FMT=6004) MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
          IF(SOCKLO)THEN
            WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          ENDIF
          ISTAT = -1
          RETURN
        END IF

c     TAKANORI: Parse serial number, starting from 0x9a1 = 2465
c        print*, CHEAD(2465:2664)
        I1 = 2465
 27     WRITE(LINE,FMT=6034) (CHEAD(I),I=I1,I1+24)
        IF (LINE(1:25).EQ.'Detector Serial Number = ')THEN
           I2 = 1
           DO 28 WHILE (CHEAD(I1+24+I2).NE.BACKSLN.AND.I2.LE.12)
              HSERIAL(I2:I2) = CHEAD(I1+24+I2)
              I2 = I2 + 1
 28         ENDDO
C           print*, 'MarCCD HSERIAL = "', HSERIAL, '"'
        ELSE
           I1 = I1 + 1
           IF (I1.LE.NHBYTE-30)THEN
              GOTO 27
           ENDIF
        ENDIF
       
C
C---- Work out byte order
C     NITEM is number of words we want to use from header
C
        NITEM = 512
        BYTSWAP = .FALSE.
C
        IORD = IHEAD(264)
CAL 21JUN02 TO READ MARCCD IMAGES FROM APS
CAL        IF (IORD.NE.1234) THEN
        IF ((IORD.NE.1234).AND.(IORD.NE.1265))THEN
          IORDO = IORD
          CALL SWAPHDR(BHEAD(1),NITEM)
          BYTSWAP = .TRUE.
          IORD = IHEAD(264)
          IF (IORD.NE.1234) THEN
            WRITE(IOUT,FMT=6040) IORDO,IORD
            IF (ONLINE) WRITE(ITOUT,FMT=6040) IORDO,IORD
 6040       FORMAT(//1X,' **** FATAL ERROR ****',/,1X,'The byte order',
     +           ' flag must be 1234. With the original byte order',
     +           ' it is',I16,/,1X,'and with swapped byte order',
     +           ' it is',I16,/,1X,'Is this really a MAR CCD image ?')
            IF(SOCKLO)THEN
              WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $             XODFILE(1:LENSTR(XODFILE))
              CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $             XMLLINE)
            ENDIF
            ISTAT = -2
            RETURN
          END IF
          WRITE(IOUT,FMT=6001)
          IF (ONLINE.AND..NOT.SOCKLO) WRITE(ITOUT,FMT=6001)
        END IF
C
C---- DEBUG
C
        IF (DEBUG(102)) THEN
          NROWS = NITEM/5 + 1
          I1 = 1
          I2 = I1 + 4
          DO 50 I = 1,NROWS
            WRITE(IOUT,FMT=6012) I1,I2,(IHEAD(JJ),JJ=I1,I2)
            IF (ONLINE) WRITE(ITOUT,FMT=6012)
     +           I1,I2,(IHEAD(JJ),JJ=I1,I2)
            I1 = I1 + 5
            I2 = MIN(NITEM, I1+4)
 50      CONTINUE
C     
          I1 = 1
          I2 = I1 + 4
          DO 51 I = 1,NROWS
            WRITE(IOUT,FMT=6014) I1,I2,(RHEAD(JJ),JJ=I1,I2)
            IF (ONLINE) WRITE(ITOUT,FMT=6014)
     +           I1,I2,(RHEAD(JJ),JJ=I1,I2)
            I1 = I1 + 5
            I2 = MIN(NITEM, I1+4)
 51      CONTINUE
C     
C     AL          NROWS = 20
          I1 = 1
          I2 = I1 + 4
          DO 52 I = 1,NROWS
            WRITE(IOUT,FMT=6016) I1,I2,(CHEAD(JJ),JJ=I1,I2)
            IF (ONLINE) WRITE(ITOUT,FMT=6016)
     +           I1,I2,(CHEAD(JJ),JJ=I1,I2)
            I1 = I1 + 5
            I2 = MIN(NITEM, I1+4)
 52      CONTINUE
        END IF

        NREC = IHEAD(277)
        IYLEN = IHEAD(278)
        ILRECL = IYLEN*IHEAD(279)
        HIOVER = IHEAD(283)
        HRAST = 0.000001*IHEAD(450)
        HRASTY = 0.000001*IHEAD(451)
CAL        HNULLPIX = NINT(0.001*IHEAD(452))
        HWAVE = 0.00001*IHEAD(484)
        HDIST = 0.001*IHEAD(431)

C 
C       Deal with specific beamlines at Spring-8 with reversed phi
C       Need to check the model as well, using the number of pixels
C       and the pixel size.
C       MX225 is 3x3 CCDs and can be 6144x6144 37mu, 3072x3072 73mu
C                                    2046x2046 110mu 1536x1536 146mu
C       MX300 is 4x4 CCDs            8192x8192 37mu  4096x4096 73mu
C                                    2728x2728 110mu 2048x2048 146mu
C       Mar225 2x2 ?                 2048x2048  79mu
C
        MX225 = (((NREC.EQ.6144).AND.(ABS(HRAST-0.037).LT.0.01)).OR.
     +           ((NREC.EQ.3072).AND.(ABS(HRAST-0.073).LT.0.01)).OR.
     +           ((NREC.EQ.2046).AND.(ABS(HRAST-0.110).LT.0.01)).OR.
     +           ((NREC.EQ.1536).AND.(ABS(HRAST-0.146).LT.0.01)))
        MX300 = (((NREC.EQ.8192).AND.(ABS(HRAST-0.037).LT.0.01)).OR.
     +           ((NREC.EQ.4096).AND.(ABS(HRAST-0.073).LT.0.01)).OR.
     +           ((NREC.EQ.2728).AND.(ABS(HRAST-0.110).LT.0.01)).OR.
     +           ((NREC.EQ.2048).AND.(ABS(HRAST-0.146).LT.0.01)))
        MAR225 = ((NREC.EQ.2048).AND.(ABS(HRAST-0.079).LT.0.01))
C
        IF (((HSERIAL(1:2).EQ.'24').AND.MAR225).OR.
     +      ((HSERIAL(1:2).EQ.'31').AND.MX225).OR.
     $      ((HSERIAL(1:2).EQ.'38').AND.MX225).OR.
     +      ((HSERIAL(1:2).EQ.'40').AND.MX225).OR.
     $      ((HSERIAL(1:2).EQ.'42').AND.MX300).OR.
     +      ((HSERIAL(1:3).EQ.'106').AND.MX225)) THEN
c         TAKANORI: these are detectors at SPring-8
c           24: BL26B2 Mar225,  31: BL32XU MX225HE,  38: BL44XU MX225HE
c           42: BL44XU MX300HE, 40: BL41XU MX225HE, 106: BL32XU MX225HS
C
            IF (.NOT.UPDATEOMEGA) THEN
              OMEGAFD = 180.0 
              OMEGAF = OMEGAFD * DTOR
              UPDATEOMEGA = .TRUE.
              WRITE(IOUT,FMT=6058) 
              IF (ONLINE) WRITE(ITOUT,FMT=6058)
 6058         FORMAT(/,1X,'*** Based on the detector serial number',
     +               ' this detector is believed to be    ***',/,1X,
     +               '*** at Spring-8 ',
     +               'on a beamline with a reversed phi. This',
     +               ' will automatically ***',/,1X,'*** be taken ',
     +               ' into account during processing ***')
            END IF
        ENDIF



C only set beam centre if it's sensible to do so
        IF((IHEAD(450).GT.0).AND.(IHEAD(451).GT.1).AND.
     $       (IHEAD(418).GT.0).AND.(IHEAD(419).GT.0))THEN
          HBEAMX = 0.001*IHEAD(418)
          HBEAMY = 0.001*IHEAD(419)
          IF((HBEAMX.GT.NREC*HRAST).OR.(HBEAMY.GT.IYLEN*HRASTY).OR.
     $         (HBEAMX.LT.0).OR.(HBEAMY.LT.0))THEN
C     ..
C     .. beam is off the edge of the detector!
            BEAMXD = 0.0
            BEAMYD = 0.0
          ELSE
C     ..
C     .. need to check if it's already been converted to 1000*mm, eg ESRF
            BEAMXD = (((NREC * HRAST)/2.0) + HBEAMX)/(NREC * HRAST)
            IF(BEAMXD.GT.1.0)BEAMXD = 1.0/BEAMXD
            BEAMYD = (((IYLEN * HRASTY)/2.0) + HBEAMY)/
     $           (IYLEN * HRASTY)
            IF(BEAMYD.GT.1.0)BEAMYD = 1.0/BEAMYD
          ENDIF
          IF((BEAMXD.LT.0.5).AND.(BEAMYD.LT.0.5))THEN
C
C---- hrp 08.02.2008 - I think X and Y should be swapped for all except 
C     ESRF images. Also, other detectors record the value in pixels.
C
            HBEAMX = IHEAD(419) * 0.001 * HRAST
            HBEAMY = IHEAD(418) * 0.001 * HRASTY
C          ELSE
C            WRITE(IOUT,FMT=6048)HBEAMX,HBEAMY,HBEAMX*HRAST,
C     $           HBEAMY*HRASTY,HBEAMX/HRAST,
C     $           HBEAMY/HRASTY
C            IF(ONLINE)WRITE(ITOUT,FMT=6048)HBEAMX,HBEAMY,HBEAMX*HRAST,
C     $           HBEAMY*HRASTY,HBEAMX/HRAST,
C     $           HBEAMY/HRASTY
 6048       FORMAT(/,72('*'),/,' This appears to be a detector ',
     $           'located at the ESRF; you should check the',/,' b',
     $           'eam centre carefully, as the correction for',
     $           ' pixel size may have been',/,' applied twice (or ',
     $           'not at all!)',/,' Calculated:      ',F8.2,'mm',F8.2,
     $           'mm',/,' corrected twice: ',F8.2,'mm',F8.2,'mm',/,
     $           ' uncorrected:     ',F8.2,'mm',F8.2,'mm',/,72('='),/)
          ENDIF
          IF(IBEAM.EQ.0)IBEAM = 3
        ENDIF
        IAXIS = IHEAD(440)
        IF ((IAXIS.LT.1).OR.(IAXIS.GT.6)) THEN
           IAXIS = 4
           WRITE(IOUT,FMT=6046)
           IF (ONLINE) WRITE(ITOUT,FMT=6046)
 6046      FORMAT(1X,'***** WARNING *****',/,1X,
     +            'Unrecognised rotation axis in header, phi values',
     +            ' from header',/,1X,'may be incorrect.')
        END IF
        HTWOTHETA = 0.001*IHEAD(424)
        HPHIS = 0.001*IHEAD(424+IAXIS)
        HPHIE = 0.001*(IHEAD(424+IAXIS) + IHEAD(441))
        IF((HPHIS.GT.HPHIE).AND.(HPHIS-360.0.LT.HPHIE))
     $       THEN 
             HPHIE = HPHIE + 360.0
        ENDIF
C
C---- HRP special for stills from LCLS 31/07/2015
C
        IF(HSERIAL(1:2).EQ.'20')HPHIE = HPHIE + 0.05
        HPHIR = HPHIE - HPHIS
C
C---- Set MODEL for 3x3 or 4x4 mosaic
C
        IF (NREC.EQ.3072) MODEL = "MOSAIC3"
        IF (NREC.EQ.4096) MODEL = "MOSAIC4"

        WORK(1) = 0.001*IHEAD(424)
        WORK(2) = 0.001*IHEAD(425)
        WORK(3) = 0.001*IHEAD(426)
        WORK(4) = 0.001*IHEAD(427)
        WORK(5) = 0.001*IHEAD(428)
        WORK(6) = 0.001*IHEAD(429)
        WORK(7) = 0.001*IHEAD(430)
        WORK(8) = 0.001*IHEAD(431)
        WORK(9) = 0.001*IHEAD(432)
        WORK(10) = 0.001*IHEAD(433)
        WORK(11) = 0.001*IHEAD(434)
        WORK(12) = 0.001*IHEAD(435)
        WORK(13) = 0.001*IHEAD(436)
        WORK(14) = 0.001*IHEAD(437)
        WORK(15) = 0.001*IHEAD(438)
        WORK(16) = 0.001*IHEAD(439)
        WORK(17) = 0.001*IHEAD(440)
        WORK(18) = 0.001*IHEAD(441)
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6042) HSERIAL(1:LENSTR(HSERIAL)),NREC,
     +          IYLEN,ILRECL,BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,
     +          HRAST,HRASTY,HTWOTHETA,HNULLPIX,OMEGAFD,
     +          (WORK(I),I=1,18)
          IF (ONLINE) WRITE(ITOUT,FMT=6042) HSERIAL(1:LENSTR(HSERIAL)),
     +          NREC,IYLEN,ILRECL,BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,
     +          HRAST,HRASTY,HTWOTHETA,HNULLPIX,OMEGAFD,
     +          (WORK(I),I=1,18)
 6042     FORMAT(1X,'In GETHDR',/,1X,'From header record in image',/,1X,
     +         'Serial number: ',A,
     +         '  NREC=',I5,' IYLEN=',I5,' LREC=',I5,
     +         '  Byte-swapping ',L1,
     +         /,1X,'Distance:',F8.2,'  Wavelength:',F8.5,'  Phi',
     +         ' start',F9.3,'  Phi end:',F9.3,/,1x,'Pixel size in X',
     +         F7.3,'mm',' Pixel size in Y',F7.3,'mm.',/,1X,
     +         'Two theta',F8.3,'  Null pixel value',I5,
     +         '  Omega',F7.1,/,1X,'Values in WORK',/,(1X,8F10.2))
          WRITE(IOUT,FMT=6043) (IHEAD(I),I=200,450)
          IF (ONLINE) WRITE(ITOUT,FMT=6043) (IHEAD(I),I=200,450)
 6043     FORMAT(1X,15I6)
        END IF
C     HRP 09.11.2010
C     have to do here because (a) sometimes section isn't called
C     and (b) values cannot be set in setdetect, since they are 
C     only known after reading the header
C
C     
C     Set up detector limits based on pixel size,
C     nominally 80 um (for 165mm CCD) vs 64 microns for 133mm
C     
chrp 17.06.2014        IF (RAST.GT.0.070) THEN
chrp 17.06.2014          RMINIP = 300
chrp 17.06.2014          XMAXIP = 8100
chrp 17.06.2014          YMAXIP = 8100
chrp 17.06.2014          RMAXIP = 8100
chrp 17.06.2014        ELSE
chrp 17.06.2014          RMINIP = 300
chrp 17.06.2014          XMAXIP = 6600
chrp 17.06.2014          YMAXIP = 6600
chrp 17.06.2014          RMAXIP = 6600
chrp 17.06.2014        END IF
C     
C---- Mods for new tiled 3x3 ccd ("Mar Mosaic 225?") or new fast MX225HS
C     or MX300HS
C
C
        IF (NREC.EQ.3072.OR.NREC.EQ.2880.OR.NREC.EQ.3840) THEN
chrp 17.06.2014          RMINIP = 300
chrp 17.06.2014          XMAXIP = 11200
chrp 17.06.2014          YMAXIP = 11200
chrp 17.06.2014          RMAXIP = 15800
chrp 17.06.2014          IF (XSCAN.EQ.0) XSCAN = 11200
chrp 17.06.2014          IF (YSCA (<) N.EQ.0) YSCAN = 11200
          CIRCULAR = .FALSE.
          ORTHOG = .TRUE.
C     
C---- Mods for new tiled 4x4 ccd ("Mar Mosaic 325")
C
        ELSEIF (NREC.EQ.4096) THEN
chrp 17.06.2014          RMINIP = 300
chrp 17.06.2014          XMAXIP = 16250
chrp 17.06.2014          YMAXIP = 16250
chrp 17.06.2014          RMAXIP = 22980
chrp 17.06.2014          IF (XSCAN.EQ.0) XSCAN = 16250
chrp 17.06.2014          IF (YSCAN.EQ.0) YSCAN = 16250
          CIRCULAR = .FALSE.
          ORTHOG = .TRUE.
        END IF
        RSCANIP = RMAXIP
C
C---- HRP 16th June 2014 calculate XMAXIP etc from pixel size and NREC, IYLEN;
C     over-ride hard-coded values above; use HRAST here, RAST in control.f
C
        XMAXIP = INT(NREC*HRAST)*50
        YMAXIP = INT(IYLEN*HRAST)*50
        IF(CIRCULAR)THEN
          RMAXIP = XMAXIP
        ELSE
          RMAXIP = SQRT(XMAXIP**2+YMAXIP**2)
        ENDIF
        XSCAN = XMAXIP
        YSCAN = YMAXIP
        RSCANIP = RMAXIP
        IF (ILIMIT.EQ.0) THEN
          XLIMIT = 0.01*(XMAXIP/2)
          LIMIT = NINT(100*XLIMIT)
        END IF
C
C     ********************************
C---- Ed Westbrooks 3x3 detector SBC-1
C     ********************************
C

C     ********************************
      ELSE IF (MACHINE.EQ.'SBC1') THEN
C     ********************************
C
C---- There are always at least 512 bytes in the header (and usually many more)
C
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6018) NBYTE,ISWAP
          IF (ONLINE) WRITE(ITOUT,FMT=6018) NBYTE,ISWAP
        END IF
        IERR = 0
        NNBYTE = 512
        BLPHSTART = ' '
        BLPHEND = ' '
        BLPHINC = ' '
        DETNAME = ' '
        FIRSTTIME = .TRUE.
 30     CALL GETBLK(BHEAD(1),NNBYTE,1,ISWAP,IERR)
C
C---- Trap error in read
C
        IF (IERR.NE.0) THEN
          WRITE(IOUT,FMT=6004) MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
          IF(SOCKLO)THEN
            WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
          ENDIF
          ISTAT = -1
          RETURN
        END IF
C
        IF (DEBUG(102)) THEN       
            NITEM = NNBYTE/4
            WRITE(IOUT,FMT=6030) (CHEAD(I),I=1,NITEM)
            IF (ONLINE) WRITE(ITOUT,FMT=6030) (CHEAD(I),I=1,NITEM)
        END IF
C
C---- Decode the header information
C
        NCH = 0
        NCH = NCH + 1
        IF (CHEAD(NCH).EQ.'{') THEN
C
C---- Start of header, skip to start of first line
C
           NCH = NCH + 2
C
C---- Search for end of this line
C
           NSTART = NCH
 32        IF (CHEAD(NCH).EQ.'}') GOTO 36
C
           IF (CHEAD(NCH).EQ.';') GOTO 34
           NCH = NCH + 1
           IF (NCH.GT.NNBYTE) THEN
             WRITE(IOUT,FMT=6032)MACHINE
             IF (ONLINE) WRITE(ITOUT,FMT=6032)MACHINE
             IF(SOCKLO)THEN
               WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $              XODFILE(1:LENSTR(XODFILE))
               CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $              XMLLINE)
             ENDIF
             ISTAT = -2
             RETURN
           END IF
           GOTO 32
C
 34        NEND = NCH - 1
           NCHAR = NEND-NSTART+1
           LINE = ' '
           IF (NCHAR.LE.240) 
     +              WRITE(LINE,FMT=6034) (CHEAD(I),I=NSTART,NEND)
           IF (DEBUG(102)) THEN
             WRITE(IOUT,FMT=6036) LINE(1:LENSTR(LINE))
             IF (ONLINE) WRITE(ITOUT,FMT=6036) LINE(1:LENSTR(LINE))
           END IF
C
C---- Decode keyword
C
C                ******************************************
           CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C                ******************************************
           KEY = LINE(IBEG(1) :IEND(1))
           CALL CCPUPC(KEY)
           IF (KEY.EQ.'HEADER_BYTES') THEN
             NHBYTES = NINT(VALUE(2))
             NNBYTE = NHBYTES
             HHEAD = NHBYTES
             IF (FIRSTTIME) THEN
               NHBYTES = NHBYTES - 512
C
C---- Check if header is too long to store
C

               IF (NNBYTE.GT.MAXHEAD*4) THEN
                 WRITE(IOUT,FMT=6060) NNBYTE,MAXHEAD*4,NNBYTE/4+1
                 IF (ONLINE) WRITE(ITOUT,FMT=6060) NNBYTE,MAXHEAD,
     +             NNBYTE/4+1
 6060            FORMAT(//,1X,'***** ERROR *****',/,1X,'The image ',
     +            'header has ',I7,' bytes but the maximum allowed',
     +            ' is',I7,/,1X,'Change the parameter MAXHEAD to at',
     +            ' least',I7,' with a global edit and recompile.')
                 IF(SOCKLO)THEN
                   WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $                  XODFILE(1:LENSTR(XODFILE))
                   CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $                  XMLLINE)
                 ENDIF
                 ISTAT = -2
                 RETURN
               END IF
C
               IF (NHBYTES.GT.0) THEN
                 CALL GETBLK(BHEAD(513),NHBYTES,1,ISWAP,IERR)
C
C---- Trap error in read
C
                 IF (IERR.NE.0) THEN
                   WRITE(IOUT,FMT=6004) MACHINE
                   IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
                   IF(SOCKLO)THEN
                     WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $                    XODFILE(1:LENSTR(XODFILE))
                     CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $                    XMLLINE)
                   ENDIF
                   ISTAT = -1
                   RETURN
                 END IF
               END IF
               FIRSTTIME = .FALSE.
             END IF
           ELSE IF (KEY.EQ.'BYTE_ORDER') THEN
             BORDER = LINE(IBEG(2):IEND(2))
             CALL CCPUPC(BORDER)
             BYTSWAP = ((LITEND().AND.(BORDER.EQ.'BIG')).OR.
     +                  (.NOT.LITEND().AND.(BORDER.NE.'BIG')))
           ELSE IF (KEY.EQ.'SIZE1') THEN
             IYLEN = NINT(VALUE(2))
           ELSE IF (KEY.EQ.'SIZE2') THEN
             NREC = NINT(VALUE(2))
           ELSE IF (KEY.EQ.'SCAN_WAVELENGTH') THEN
             HWAVE = VALUE(2)
           ELSE IF (KEY.EQ.'SOURCE_POLARZ') THEN
             HTOR = VALUE(2)
           ELSE IF (KEY.EQ.'DIST') THEN
             HDIST = VALUE(2)
           ELSE IF (KEY.EQ.'PHIST') THEN
             HPHIS = VALUE(2)
           ELSE IF (KEY.EQ.'PHIINC') THEN
             OSCRNG = VALUE(2)
             HPHIR = OSCRNG
           ELSE IF (KEY.EQ.'BEAM_POSITION') THEN
            HBEAMX = VALUE(2)
            HBEAMY = VALUE(3)
           ELSE IF (KEY.EQ.'BEAMLINE_NAME') THEN
             BLNAME = LINE(IBEG(2):IEND(2))
             NCH2 = LENSTR(BLNAME)
             IF (DEBUG(102)) THEN
               WRITE(IOUT,FMT=6064) BLNAME
               IF (ONLINE) WRITE(ITOUT,FMT=6064) BLNAME
 6064          FORMAT(1X,'Beamline name: ',A)
             END IF
             IF (NCH2.GT.10) THEN
               WRITE(IOUT,FMT=6062) BLNAME
               IF (ONLINE) WRITE(ITOUT,FMT=6062) BLNAME
 6062          FORMAT(1X,'***** ERROR *****',/,1X,'The beamline',
     +          ' name (',A,') in the image header is more than 10',
     +          ' characters,',/,1X,'which means that the keywords',
     +          ' will not be identified correctly.',/,1X,'Make ',
     +          'changes to subroutine GETHDR.')
               IF(SOCKLO)THEN
                 WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $                XODFILE(1:LENSTR(XODFILE))
                 CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $                XMLLINE)
               ENDIF
               ISTAT = -2
               RETURN
             END IF
             BLPHSTART = BLNAME(1:NCH2)//'ROTATION_START'
             BLPHEND = BLNAME(1:NCH2)//'ROTATION_END'
             BLPHINC = BLNAME(1:NCH2)//'SCAN_INCREMENT'
           ELSE IF (KEY.EQ.'DETECTOR_NAMES') THEN
             DETNAME = LINE(IBEG(2):IEND(2))
             NCH2 = LENSTR(DETNAME)
             IF (DEBUG(102)) THEN
                WRITE(IOUT,FMT=6066) DETNAME
               IF (ONLINE) WRITE(ITOUT,FMT=6066) DETNAME
 6066          FORMAT(1X,'Detector name: ',A)
             END IF
             DETDIST = DETNAME(1:NCH2)//'GONIO_VALUES'
           ELSE IF (KEY.EQ.BLPHSTART) THEN
             HPHIS = VALUE(2)
           ELSE IF (KEY.EQ.BLPHEND) THEN
             HPHIE = VALUE(2)
           ELSE IF (KEY(1:LENSTR(KEY)).EQ.
     $            DETDIST(1:LENSTR(DETDIST))) THEN
             HDIST = VALUE(7)
             HTWOTHETA = VALUE(3)
           END IF
           NCH = NCH + 2
           NSTART = NCH
           GOTO 32
        END IF
 36     IF (NREC.EQ.3072) THEN
           HRAST = 0.06836
        ELSE IF (NREC.EQ.1536) THEN
           HRAST = 0.13672
        END IF
        HPHIR = HPHIE - HPHIS
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +     BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
          IF (ONLINE) WRITE(ITOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +     BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
 6070   FORMAT(1X,'From header record in image',/,1X,
     +         'NREC= ',I5,' IYLEN= ',I5,' Pixel size ',F8.5,' mm',
     +         ' Beam polarisation ',F6.4,/,1X,'Byte-swapping ',L1,
     +         /,1X,'Distance: ',F8.2,'  Wavelength: ',F8.5,'  Phi',
     +         ' start ',F9.3,'  Phi end: ',F9.3,' Twotheta ',F7.3,
     +         '  Direct beam coords: ',2F8.2)
        END IF



C     ***********************************
C---- Ed Westbrooks lens coupled CCD NOIR
C     ***********************************
C

C     ********************************
      ELSE IF (MACHINE.EQ.'NOIR') THEN
C     ********************************
C
C---- There are always at least 512 bytes in the header (and usually many more)
C
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6018) NBYTE,ISWAP
          IF (ONLINE) WRITE(ITOUT,FMT=6018) NBYTE,ISWAP
        END IF
        IERR = 0
        NNBYTE = 512
        BLPHSTART = ' '
        BLPHEND = ' '
        BLPHINC = ' '
        DETNAME = ' '
        FIRSTTIME = .TRUE.
 40     CALL GETBLK(BHEAD(1),NNBYTE,1,ISWAP,IERR)
C
C---- Trap error in read
C
        IF (IERR.NE.0) THEN
          WRITE(IOUT,FMT=6004) MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
          IF(SOCKLO)THEN
            WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
          ENDIF
          ISTAT = -1
          RETURN
        END IF
C
        IF (DEBUG(102)) THEN       
            NITEM = NNBYTE/4
            WRITE(IOUT,FMT=6030) (CHEAD(I),I=1,NITEM)
            IF (ONLINE) WRITE(ITOUT,FMT=6030) (CHEAD(I),I=1,NITEM)
        END IF
C
C---- Decode the header information
C
        NCH = 0
        NCH = NCH + 1
        IF (CHEAD(NCH).EQ.'{') THEN
C
C---- Start of header, skip to start of first line
C
           NCH = NCH + 2
C
C---- Search for end of this line
C
           NSTART = NCH
 42        IF (CHEAD(NCH).EQ.'}') GOTO 46
C
           IF (CHEAD(NCH).EQ.';') GOTO 44
           NCH = NCH + 1
           IF (NCH.GT.NNBYTE) THEN
             WRITE(IOUT,FMT=6032)MACHINE
             IF (ONLINE) WRITE(ITOUT,FMT=6032)MACHINE
             IF(SOCKLO)THEN
               WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $              XODFILE(1:LENSTR(XODFILE))
               CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $              XMLLINE)
             ENDIF
             ISTAT = -2
             RETURN
           END IF
           GOTO 42
C
 44        NEND = NCH - 1
           NCHAR = NEND-NSTART+1
           LINE = ' '
           IF (NCHAR.LE.240) 
     +              WRITE(LINE,FMT=6034) (CHEAD(I),I=NSTART,NEND)
           IF (DEBUG(102)) THEN
             WRITE(IOUT,FMT=6036) LINE(1:LENSTR(LINE))
             IF (ONLINE) WRITE(ITOUT,FMT=6036) LINE(1:LENSTR(LINE))
           END IF
C
C---- Decode keyword
C
C                ******************************************
           CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C                ******************************************
           KEY = LINE(IBEG(1) :IEND(1))
           CALL CCPUPC(KEY)
           IF (KEY.EQ.'HEADER_BYTES') THEN
             NHBYTES = NINT(VALUE(2))
             NNBYTE = NHBYTES
             HHEAD = NHBYTES
             IF (FIRSTTIME) THEN
               NHBYTES = NHBYTES - 512
C
C---- Check if header is too long to store
C

               IF (NNBYTE.GT.MAXHEAD*4) THEN
                 WRITE(IOUT,FMT=6060) NNBYTE,MAXHEAD*4,NNBYTE/4+1
                 IF (ONLINE) WRITE(ITOUT,FMT=6060) NNBYTE,MAXHEAD,
     +             NNBYTE/4+1
                 IF(SOCKLO)THEN
                   WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $                  XODFILE(1:LENSTR(XODFILE))
                   CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $                  XMLLINE)
                 ENDIF
                 ISTAT = -2
                 RETURN
               END IF
C
               IF (NHBYTES.GT.0) THEN
                 CALL GETBLK(BHEAD(513),NHBYTES,1,ISWAP,IERR)
C
C---- Trap error in read
C
                 IF (IERR.NE.0) THEN
                   WRITE(IOUT,FMT=6004) MACHINE
                   IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
                   IF(SOCKLO)THEN
                     WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $                    XODFILE(1:LENSTR(XODFILE))
                     CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $                    XMLLINE)
                   ENDIF
                   ISTAT = -1
                   RETURN
                 END IF
               END IF
               FIRSTTIME = .FALSE.
             END IF
           ELSE IF (KEY.EQ.'BYTE_ORDER') THEN
             BORDER = LINE(IBEG(2):IEND(2))
             CALL CCPUPC(BORDER)
             BYTSWAP = ((LITEND().AND.(BORDER.EQ.'BIG')).OR.
     +                  (.NOT.LITEND().AND.(BORDER.NE.'BIG')))
           ELSE IF (KEY.EQ.'SIZE1') THEN
             IYLEN = NINT(VALUE(2))
           ELSE IF (KEY.EQ.'SIZE2') THEN
             NREC = NINT(VALUE(2))
           ELSE IF (KEY.EQ.'SOURCE_WAVELENGTH') THEN
             HWAVE = VALUE(3)
           ELSE IF (KEY.EQ.'SOURCE_POLARZ') THEN
             HTOR = VALUE(2)
           ELSE IF (KEY.EQ.'DIST') THEN
             HDIST = VALUE(2)
           ELSE IF (KEY.EQ.'PHIST') THEN
             HPHIS = VALUE(2)
           ELSE IF (KEY.EQ.'PHIINC') THEN
             OSCRNG = VALUE(2)
             HPHIR = OSCRNG
           ELSE IF (KEY.EQ.'BEAM_POSITION') THEN
C
C---- Note, have to invert X and Y in header
C
            HBEAMY = VALUE(2)
            HBEAMX = VALUE(3)
           ELSE IF (KEY(1:LENSTR(KEY)).EQ.
     $            DETBEAM(1:LENSTR(DETBEAM))) THEN
C
C---- Note, have to invert X and Y in header
C
            HBEAMY = VALUE(2)
            HBEAMX = VALUE(3)
C
C---- Get detector name, this is used to make up keyword names
C
           ELSE IF (KEY.EQ.'DETECTOR_NAMES') THEN
             DETNAME = LINE(IBEG(2):IEND(2))
             NCH2 = LENSTR(DETNAME)
             IF (DEBUG(102)) THEN
                WRITE(IOUT,FMT=6066) DETNAME
               IF (ONLINE) WRITE(ITOUT,FMT=6066) DETNAME
             END IF
             DETDIST = DETNAME(1:NCH2)//'GONIO_VALUES'
C hrp 23.02.2009 can't do this as the line may appear twice with different values, 
C     (the first set of which don't refer to the same parameters) or might be there 
C     once only (with the wrong values).
C     DETPIXEL = DETNAME(1:NCH2)//'SPATIAL_DISTORTION_INFO'
             DETBEAM = DETNAME(1:NCH2)//'SPATIAL_BEAM_POSITION'
             DETSIZE = DETNAME(1:NCH2)//'DETECTOR_SIZE'
           ELSE IF (KEY.EQ.'ROTATION') THEN
             HPHIS = VALUE(2)
             HPHIE = VALUE(3)
             HPHIR = HPHIE - HPHIS
           ELSE IF (KEY(1:LENSTR(KEY)).EQ.
     $            DETDIST(1:LENSTR(DETDIST))) THEN
             HDIST = VALUE(7)
             HTWOTHETA = VALUE(3)
C hrp 23.02.2009           ELSE IF (KEY(1:LENSTR(KEY)).EQ.
C hrp 23.02.2009     $            DETPIXEL(1:LENSTR(DETPIXEL))) THEN
C hrp 23.02.2009             HRAST = VALUE(4)
           ELSE IF (KEY(1:LENSTR(KEY)).EQ.
     $            DETSIZE(1:LENSTR(DETSIZE))) THEN
             HSIZED = VALUE(2)
             IF(HSIZED .GT.1E-3.AND.NREC.GT.0)THEN
               HRAST = HSIZED/REAL(NREC)
             ELSE
C     ..
C     .. default value
               HRAST = 0.07767
             ENDIF
           END IF
           NCH = NCH + 2
           NSTART = NCH
           GOTO 42
        END IF
 46     CONTINUE
        HBEAMX = HBEAMX*HRAST
        HBEAMY = HBEAMY*HRAST
        IF((HBEAMX.GT.0.0).AND.(HBEAMY.GT.0.0).AND.(IBEAM.EQ.0))IBEAM=3
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +     BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
          IF (ONLINE) WRITE(ITOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +     BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
        END IF



C     ***********************************
C---- Ed Westbrooks TAURUS CMOS detector
C     ***********************************
C

C     ********************************
      ELSE IF (MACHINE.EQ.'TAUR') THEN
C     ********************************
C
C---- There are always at least 512 bytes in the header (and usually many more)
C
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6018) NBYTE,ISWAP
          IF (ONLINE) WRITE(ITOUT,FMT=6018) NBYTE,ISWAP
        END IF
        IERR = 0
        NNBYTE = 512
        BLPHSTART = ' '
        BLPHEND = ' '
        BLPHINC = ' '
        DETNAME = ' '
        FIRSTTIME = .TRUE.
 60     CALL GETBLK(BHEAD(1),NNBYTE,1,ISWAP,IERR)
C
C---- Trap error in read
C
        IF (IERR.NE.0) THEN
          WRITE(IOUT,FMT=6004) MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
          IF(SOCKLO)THEN
            WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
          ENDIF
          ISTAT = -1
          RETURN
        END IF
C
        IF (DEBUG(102)) THEN       
            NITEM = NNBYTE/4
            WRITE(IOUT,FMT=6030) (CHEAD(I),I=1,NITEM)
            IF (ONLINE) WRITE(ITOUT,FMT=6030) (CHEAD(I),I=1,NITEM)
        END IF
C
C---- Decode the header information
C
        NCH = 0
        NCH = NCH + 1
        IF (CHEAD(NCH).EQ.'{') THEN
C
C---- Start of header, skip to start of first line
C
           NCH = NCH + 2
C
C---- Search for end of this line
C
           NSTART = NCH
 62        IF (CHEAD(NCH).EQ.'}') GOTO 66
C
           IF (CHEAD(NCH).EQ.';') GOTO 64
           NCH = NCH + 1
           IF (NCH.GT.NNBYTE) THEN
             WRITE(IOUT,FMT=6032)MACHINE
             IF (ONLINE) WRITE(ITOUT,FMT=6032)MACHINE
             IF(SOCKLO)THEN
               WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $              XODFILE(1:LENSTR(XODFILE))
               CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $              XMLLINE)
             ENDIF
             ISTAT = -2
             RETURN
           END IF
           GOTO 62
C
 64        NEND = NCH - 1
           NCHAR = NEND-NSTART+1
           LINE = ' '
           IF (NCHAR.LE.240) 
     +              WRITE(LINE,FMT=6034) (CHEAD(I),I=NSTART,NEND)
           IF (DEBUG(102)) THEN
             WRITE(IOUT,FMT=6036) LINE(1:LENSTR(LINE))
             IF (ONLINE) WRITE(ITOUT,FMT=6036) LINE(1:LENSTR(LINE))
           END IF
C
C---- Decode keyword
C
C                ******************************************
           CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C                ******************************************
           KEY = LINE(IBEG(1) :IEND(1))
           CALL CCPUPC(KEY)
           IF (DEBUG(102)) THEN
             WRITE(IOUT,FMT=6038) LENSTR(KEY),KEY
             IF (ONLINE) WRITE(ITOUT,FMT=6038) LENSTR(KEY),KEY
 6038        FORMAT(1X,'Length of KEY is',I3,' KEY is ',A)
           END IF
           IF (KEY.EQ.'HEADER_BYTES') THEN
             NHBYTES = NINT(VALUE(2))
             NNBYTE = NHBYTES
             HHEAD = NHBYTES
             IF (FIRSTTIME) THEN
               NHBYTES = NHBYTES - 512
C
C---- Check if header is too long to store
C

               IF (NNBYTE.GT.MAXHEAD*4) THEN
                 WRITE(IOUT,FMT=6060) NNBYTE,MAXHEAD*4,NNBYTE/4+1
                 IF (ONLINE) WRITE(ITOUT,FMT=6060) NNBYTE,MAXHEAD,
     +             NNBYTE/4+1
                 IF(SOCKLO)THEN
                   WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $                  XODFILE(1:LENSTR(XODFILE))
                   CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $                  XMLLINE)
                 ENDIF
                 ISTAT = -2
                 RETURN
               END IF
C
               IF (NHBYTES.GT.0) THEN
                 CALL GETBLK(BHEAD(513),NHBYTES,1,ISWAP,IERR)
C
C---- Trap error in read
C
                 IF (IERR.NE.0) THEN
                   WRITE(IOUT,FMT=6004) MACHINE
                   IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
                   IF(SOCKLO)THEN
                     WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $                    XODFILE(1:LENSTR(XODFILE))
                     CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $                    XMLLINE)
                   ENDIF
                   ISTAT = -1
                   RETURN
                 END IF
               END IF
               FIRSTTIME = .FALSE.
             END IF
           ELSE IF (KEY.EQ.'BYTE_ORDER') THEN
             BORDER = LINE(IBEG(2):IEND(2))
             CALL CCPUPC(BORDER)
             BYTSWAP = ((LITEND().AND.(BORDER.EQ.'BIG')).OR.
     +                  (.NOT.LITEND().AND.(BORDER.NE.'BIG')))
           ELSE IF (KEY.EQ.'SIZE1') THEN
             IYLEN = NINT(VALUE(2))
           ELSE IF (KEY.EQ.'SIZE2') THEN
             NREC = NINT(VALUE(2))
           ELSE IF (KEY.EQ.'SOURCE_WAVELENGTH') THEN
             HWAVE = VALUE(3)
           ELSE IF (KEY.EQ.'SOURCE_POLARZ') THEN
             HTOR = VALUE(2)
           ELSE IF (KEY.EQ.'DIST') THEN
             HDIST = VALUE(2)
           ELSE IF (KEY.EQ.'PHIST') THEN
             HPHIS = VALUE(2)
           ELSE IF (KEY.EQ.'PHIINC') THEN
             OSCRNG = VALUE(2)
             HPHIR = OSCRNG
           ELSE IF (KEY.EQ.'BEAM_POSITION'.OR.
     $            KEY.EQ.'SPATIAL_BEAM_POSITION') THEN
C
C---- Note, have to invert X and Y in header
C
            HBEAMY = VALUE(2)
            HBEAMX = VALUE(3)
           ELSE IF (KEY(1:LENSTR(KEY)).EQ.
     $            DETBEAM(1:LENSTR(DETBEAM))) THEN
C
C---- Note, have to invert X and Y in header
C
            HBEAMY = VALUE(2)
            HBEAMX = VALUE(3)
C
C---- Get detector name, this is used to make up keyword names
C
           ELSE IF (KEY.EQ.'DETECTOR_NAMES') THEN
             DETNAME = LINE(IBEG(2):IEND(2))
             NCH2 = LENSTR(DETNAME)
             IF (DEBUG(102)) THEN
                WRITE(IOUT,FMT=6066) DETNAME
               IF (ONLINE) WRITE(ITOUT,FMT=6066) DETNAME
             END IF
             DETDIST = DETNAME(1:NCH2)//'GONIO_VALUES'
             DETPIXEL = DETNAME(1:NCH2)//'SPATIAL_DISTORTION_INFO'
             DETBEAM = DETNAME(1:NCH2)//'SPATIAL_BEAM_POSITION'
             DETSIZE = DETNAME(1:NCH2)//'DETECTOR_SIZE'

           ELSE IF (KEY.EQ.'ROTATION') THEN
             HPHIS = VALUE(2)
             HPHIE = VALUE(3)
             HPHIR = HPHIE - HPHIS
           ELSE IF (KEY(1:LENSTR(KEY)).EQ.
     $            DETDIST(1:LENSTR(DETDIST))) THEN
             HDIST = VALUE(7)
             HTWOTHETA = VALUE(3)
           ELSE IF (KEY(1:LENSTR(KEY)).EQ.
     $            DETPIXEL(1:LENSTR(DETPIXEL))) THEN
             HRAST = VALUE(4)
           ELSE IF (KEY(1:LENSTR(KEY)).EQ.
     $            DETSIZE(1:LENSTR(DETSIZE))) THEN
             HSIZED = VALUE(3)
             IF(HSIZED .GT.1E-3.AND.NREC.GT.0)THEN
               HRAST = HSIZED/REAL(NREC)
             ELSE
C     ..
C     .. default value
               HRAST = 0.1001
             ENDIF
           END IF
           NCH = NCH + 2
           NSTART = NCH
           GOTO 62
        END IF
 66     CONTINUE
        HBEAMX = HBEAMX*HRAST
        HBEAMY = HBEAMY*HRAST
        IF((HBEAMX.GT.0.0).AND.(HBEAMY.GT.0.0).AND.(IBEAM.EQ.0))IBEAM=3
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +     BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
          IF (ONLINE) WRITE(ITOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +     BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
        END IF



C     ********************************
      ELSE IF((MACHINE.EQ.'JUPI').OR.(MACHINE.EQ.'SATU').OR.
     $       (MACHINE.EQ.'MERC').OR.(MACHINE.EQ.'A200').OR.
     $       (MACHINE.EQ.'RIPI').OR.(MACHINE.EQ.'RIEI'))THEN
C     ********************************
C
C---- There are always at least 512 bytes in the header (there may be more)
C
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6018) NBYTE,ISWAP
          IF (ONLINE) WRITE(ITOUT,FMT=6018) NBYTE,ISWAP
        END IF
        IERR = 0
        NNBYTE = 512
        FIRSTTIME = .TRUE.
        IF (MACHINE.EQ.'RIPI') THEN
          DETNAME = 'PILT'
        ELSE IF (MACHINE.EQ.'RIEI') THEN
          DETNAME = 'EGR'
        END IF
C
C---- following added for beam centre from header stuff - Jupiter,
C     Saturn and Mercury
C
        SIMPLE = .FALSE.
        BEAMSET = .FALSE.
        HBEAMX = 0.0
        HBEAMY = 0.0
        CALL GETBLK(BHEAD(1),NNBYTE,1,ISWAP,IERR)
C
C---- Trap error in read
C
        IF (IERR.NE.0) THEN
          WRITE(IOUT,FMT=6004) MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
          IF(SOCKLO)THEN
            WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
          ENDIF
          ISTAT = -1
          RETURN
        END IF
C
        IF (DEBUG(102)) THEN       
            NITEM = NNBYTE/4
            WRITE(IOUT,FMT=6030) (CHEAD(I),I=1,NITEM)
            IF (ONLINE) WRITE(ITOUT,FMT=6030) (CHEAD(I),I=1,NITEM)
chrp12032001 6030       FORMAT(1X,20A1)
        END IF
C
C---- Decode the header information
C
        NCH = 0
        NCH = NCH + 1
        IF (CHEAD(NCH).EQ.'{') THEN
C
C---- Start of header, skip to start of first line
C
           NCH = NCH + 2
C
C---- Search for end of this line
C
           NSTART = NCH
 1014        IF (CHEAD(NCH).EQ.'}') GOTO 1018
C
           IF (CHEAD(NCH).EQ.';')GOTO 1016
           NCH = NCH + 1
           IF (NCH.GT.NNBYTE) THEN
             WRITE(IOUT,FMT=6032)MACHINE
             IF (ONLINE) WRITE(ITOUT,FMT=6032)MACHINE
chrp12032001 6032        FORMAT(//,1X,'**** ERROR READING HEADER ****')
             IF(SOCKLO)THEN
               WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $              XODFILE(1:LENSTR(XODFILE))
               CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $              XMLLINE)
             ENDIF
             ISTAT = -2
             RETURN
           END IF
           GOTO 1014
C
 1016        NEND = NCH - 1
           NCHAR = NEND-NSTART+1
           IF (DEBUG(102)) THEN
              WRITE(IOUT,FMT=6035) NSTART,NEND,NCHAR
              IF (ONLINE) WRITE(ITOUT,FMT=6035) NSTART,NEND,NCHAR
 6035         FORMAT(1X,'NSTART=',I6,' nend=',I6,' nchar',I4)
           END IF
           LINE = ' '
           IF (NCHAR.LE.240) 
     +          WRITE(LINE,FMT=6034) (CHEAD(I),I=NSTART,NEND)
chrp12032001 6034      FORMAT(132A1)
           IF (DEBUG(102)) THEN
             WRITE(IOUT,FMT=6036) LINE(1:LENSTR(LINE))
             IF (ONLINE) WRITE(ITOUT,FMT=6036) LINE(1:LENSTR(LINE))
chrp12032001 6036        FORMAT(1X,'LINE IS: ',A)
           END IF
C
C---- Decode keyword
C
C                ******************************************
           CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C                ******************************************
           KEY = LINE(IBEG(1) :IEND(1))
c not sure this is necessary hrp 10.01.2003           CALL CCPUPC(KEY)
           IF (KEY.EQ.'HEADER_BYTES') THEN
             NHBYTES = NINT(VALUE(2))
             NNBYTE = NHBYTES
             HHEAD = NHBYTES
             IF (FIRSTTIME) THEN
               NHBYTES = NHBYTES - 512
               IF (NHBYTES.GT.0) THEN
                 CALL GETBLK(BHEAD(513),NHBYTES,1,ISWAP,IERR)
C
C---- Trap error in read
C
                 IF (IERR.NE.0) THEN
                   WRITE(IOUT,FMT=6004) MACHINE
                   IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
                   IF(SOCKLO)THEN
                     WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $                    XODFILE(1:LENSTR(XODFILE))
                     CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $                    XMLLINE)
                   ENDIF
                   ISTAT = -1
                   RETURN
                 END IF
               END IF
               FIRSTTIME = .FALSE.
             END IF
           ELSE IF (KEY.EQ.'BYTE_ORDER') THEN
             BORDER = LINE(IBEG(2):IEND(2))
             CALL CCPUPC(BORDER)
             BYTSWAP = ((LITEND().AND.(BORDER.EQ.'BIG')).OR.
     +                  (.NOT.LITEND().AND.(BORDER.NE.'BIG')))
           ELSE IF (KEY.EQ.'SIZE1') THEN
             IYLEN = NINT(VALUE(2))
           ELSE IF (KEY.EQ.'SIZE2') THEN
             NREC = NINT(VALUE(2))
c
c---- pixel size isn't stored as such in the example I have, but it can 
c     be calculated from CCD_DETECTOR_SIZE/SIZE1
c
c           ELSE IF (KEY.EQ.'PIXEL_SIZE') THEN
c             HRAST = VALUE(2)
           ELSE IF (KEY.EQ.'CCD_DETECTOR_SIZE') THEN
             HSIZED = VALUE(2)
             HSIZEC = HSIZED
           ELSE IF (KEY.EQ.DETNAME(1:LENSTR(DETNAME))
     +                     //'_DETECTOR_SIZE') THEN
             HSIZEC = VALUE(2)
             HSIZED = VALUE(3)
           ELSE IF (KEY.EQ.DETNAME(1:LENSTR(DETNAME))
     +                     //'DETECTOR_DIMENSIONS') THEN
C     ..
C     .. horizontal gap is 17 pixels wide, vertical gap is 7 pixels wide, modules 
C     .. are 487 high x 195 wide
             NTILEX = 1
             DO WHILE (((NTILEX * 195) + ((NTILEX - 1) * 17))
     $            .LT.VALUE(3))
               NTILEX = NTILEX + 1
             ENDDO
             NTILEY = 1
             DO WHILE (((NTILEY * 487) + ((NTILEY - 1) * 7))
     $            .LT.VALUE(2))
               NTILEY = NTILEY + 1
             ENDDO
           ELSE IF (KEY.EQ.'SATURATED_VALUE') THEN
             HCUTOFF = VALUE(2)
             HPRCUTOFF = VALUE(2)
           ELSE IF (KEY.EQ.'SCAN_DET_RELZERO') THEN
             HDIST = VALUE(4)
           ELSE IF (KEY.EQ.'SOURCE_WAVELENGTH') THEN
             HWAVE = VALUE(3)
           ELSE IF (KEY.EQ.'ROTATION') THEN
              HPHIS = VALUE(2)
              HPHIE = VALUE(3)
             OSCRNG = VALUE(4)
             HPHIR = OSCRNG
c
c---- twotheta swing is stored in a general way; first CCD_GONIO_NAMES
C     has to be parsed to find which item is '2Theta', then CCD_GONIO_UNITS
c     to find the units ('deg'?) in that item's slot, then CCD_GONIO_VALUES
c     to pick up the value, then CCD_GONIO_VECTORS to find out which axis
c     two-theta is swung about. - but I think it might be the second item 
C     on CCD_GONIO_VALUES (HRP, 24.02.2006)
c
           ELSE IF (KEY.EQ.'CCD_GONIO_VALUES'.OR.
     $            KEY.EQ.DETNAME(1:LENSTR(DETNAME))
     +                   //'_GONIO_VALUES') THEN
             HTWOTHETA = VALUE(3)
           ELSE IF (KEY.EQ.'RAXIS_COMPRESSION_RATIO') THEN
             HCOMPR = VALUE(2)
           ELSE IF (KEY.EQ.'CCD_SPATIAL_DISTORTION_TYPE') THEN
             IF(LINE(IBEG(2):IEND(2)).EQ.'Simple_spatial')
     $            SIMPLE = .TRUE.
           ELSE IF (KEY.EQ.'CCD_SPATIAL_DISTORTION_INFO'.or.
     $            KEY.EQ.DETNAME(1:LENSTR(DETNAME))
     +                   //'_SPATIAL_DISTORTION_INFO') THEN
             BEAMXD = VALUE(2)*VALUE(4)
             BEAMYD = VALUE(3)*VALUE(5)
             BEAMSET = .TRUE.
             HRAST = VALUE(4)
           ELSE IF (KEY.EQ.'BitmapType')THEN
c     might need this later if a second type is used     BITMAPTYPE = VALUE(2)
             LACTIVEMASK = .TRUE.
           ELSE IF (KEY.EQ.'BitmapSize')THEN
             HACTIVEMASK = VALUE(2)
           ELSE IF (KEY.EQ.'CCD_SPATIAL_DISTORTION_VECTORS') THEN
C     
C---- set omegafd and invertx here for Rigaku new-style headers. 
C     They are stored in a 2x2 matrix, first line is the Fast direction,
C     second line is the Slow direction.
C
C---- Note well: Rigaku CCDs and R-Axis detectors have different values!
C
C     ( 0  1  1  0) OMEGAFD   0, invertx = .true. 
C     ( 0  1 -1  0) OMEGAFD 180, invertx = .false. 
C     ( 1  0  0  1) OMEGAFD  90, invertx = .false. 
C     ( 1  0  0 -1) OMEGAFD 270, invertx = .true.
 
C     ( 0 -1  1  0) OMEGAFD   0, invertx = .false. 
C     ( 0 -1 -1  0) OMEGAFD 180, invertx = .true. 
C     (-1  0  0  1) OMEGAFD  90, invertx = .true. 
C     (-1  0  0 -1) OMEGAFD 270, invertx = .false.
             IF(IOMEGAF.EQ.0)THEN
               INVERTX = .TRUE.
               IF(VALUE(5).EQ.1)THEN
                 OMEGAFD = 0.0
                 IF(VALUE(2).EQ.1)INVERTX = .FALSE.
               ELSEIF(VALUE(5).EQ.-1)THEN
                 OMEGAFD = 180.0
                 IF(VALUE(2).EQ.-1)INVERTX = .FALSE.
               ELSEIF(VALUE(4).EQ.1)THEN
                 OMEGAFD = 270.0
                 IF(VALUE(3).EQ.-1)INVERTX = .FALSE.
               ELSEIF(VALUE(4).EQ.-1)THEN
                 OMEGAFD = 90.0
                 IF(VALUE(3).EQ.1.)INVERTX = .TRUE.
               ENDIF
               OMEGAF = OMEGAFD * DTOR
               IOMEGAF = 2
             ENDIF
             
           ELSE IF (KEY.EQ.DETNAME(1:LENSTR(DETNAME))
     +                     //'_SPATIAL_DISTORTION_VECTORS') THEN
C     
C---- set omegafd and invertx here for Rigaku new-style headers. 
C     They are stored in a 2x2 matrix, first line is the Fast direction,
C     second line is the Slow direction.
C
C---- Note well: Rigaku CCDs, R-Axis and Pilatus detectors have different values!
C     PILATUS should be INVERTX = .TRUE.
C
C     ( 0 -1  1  0) OMEGAFD  90, invertx = .false. OK
C     ( 0  1  1  0) OMEGAFD  90, invertx = .true. OK
C 
C     ( 0  1 -1  0) OMEGAFD 270, invertx = .true. check
C     ( 0 -1 -1  0) OMEGAFD 270, invertx = .false. check
C
C     ( 1  0  0 -1) OMEGAFD   0, invertx = .true. OK
C     (-1  0  0 -1) OMEGAFD   0, invertx = .false. OK
C
C     (-1  0  0  1) OMEGAFD 180, invertx = .true. check
C     ( 1  0  0  1) OMEGAFD 180, invertx = .false. check
C
             IF(IOMEGAF.EQ.0)THEN
               INVERTX = .TRUE.
               IF(VALUE(5).EQ.1)THEN
                 OMEGAFD = 180.0
                 IF(VALUE(2).EQ.1)INVERTX = .FALSE.
chrp 30.09.2013 (1 0 0 -1) checked against 300K Pilatus, ok.
               ELSEIF(VALUE(5).EQ.-1)THEN
                 OMEGAFD = 0.0
                 IF(VALUE(2).EQ.-1)INVERTX = .FALSE.
chrp 30.09.2013 (0 1 1 0) checked against 200K Pilatus, ok.
               ELSEIF(VALUE(4).EQ.1)THEN
                 OMEGAFD = 90.0
                 IF(VALUE(3).EQ.-1)INVERTX = .FALSE.
               ELSEIF(VALUE(4).EQ.-1)THEN
                 OMEGAFD = 270.0
                 IF(VALUE(3).EQ.-1.)INVERTX = .FALSE.
               ENDIF
               OMEGAF = OMEGAFD * DTOR
               IOMEGAF = 2
             ENDIF
             
C     
           END IF
           NCH = NCH + 2
           NSTART = NCH
           GOTO 1014
         END IF
         
 1018    HPHIE = HPHIS + OSCRNG
         IF(HSIZED.GT.0.0)THEN
c     IF(NREC.GT.0)HRAST=HSIZED/FLOAT(NREC)
C
C---- set XSCAN, YSCAN, XMAX, YMAX etc
C     HRP 02.01.2009
C     don't do here as this will over-ride values from section.f
C     HRP 12.08.2009
C     have to do here because (a) sometimes section isn't called
C     and (b) values cannot be set in setdetect, since they are 
C     only known after reading the header
C
          IF (XSCAN.EQ.0) XSCAN = HSIZEd*50.0
          IF (YSCAN.EQ.0) YSCAN = HSIZEc*50.0
          IF (XMAXIP.EQ.0) XMAXIP = HSIZEd*50.0
          IF (YMAXIP.EQ.0) YMAXIP = HSIZEc*50.0
          IF (RMAXIP.EQ.0) RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
        ENDIF
C        IF(SIMPLE.and.BEAMSET)THEN
        IF(BEAMSET)THEN
c     Calculate beam centre... 
c           HBEAMX = 
c     $          ABS(BEAMXD * COS(OMEGAF) + BEAMYD * SIN(OMEGAF))
c           HBEAMY = 
c     $          ABS(BEAMXD * SIN(OMEGAF) + BEAMYD * COS(OMEGAF))
          HBEAMX = BEAMYD
          HBEAMY = BEAMXD
          IF(IBEAM.EQ.0)IBEAM = 3
        ENDIF
        XDMID = 0.5 * NREC * HRAST * 100.0
        YDMID = 0.5 * IYLEN * HRAST * 100.0
        IF (HTWOTHETA.NE.0.0.AND.ISWUNG.EQ.0)THEN
c     Calculate beam centre... 
          XTRUE = HBEAMX +
     +         COS(OMEGAF)*HDIST*TAN(HTWOTHETA*DTOR)
          YTRUE = HBEAMY + 
     +         SIN(OMEGAF)*HDIST*TAN(HTWOTHETA*DTOR)
          IF (XOFFL.EQ.0.0) XOFFL = XDMID - 100.0*XTRUE
          IF (YOFFL.EQ.0.0) YOFFL = YDMID - 100.0*YTRUE
          ISWUNG = 1
        ENDIF
        
C     ..
C     .. special for A200
        IF(MACHINE.EQ.'A200')THEN
          TILED = .TRUE.
C     ..
C     .. gap is 2 pixels wide for both binned and unbinned?
          NTILEX = 2
          NTILEY = 2
          TILEWX(1) = 2
          TILEWY(1) = 2
          IF(NREC.EQ.2048)THEN
C     ..
C     .. 2x2 binned
            TILEX(1) = 1024
            TILEY(1) = 1024
          ELSE
C     ..
C     .. unbinned
            TILEX(1) = 2048
            TILEY(1) = 2048
          ENDIF
        ENDIF
C     ..
C     .. special for Rigaku Pilatus
        IF(MACHINE.EQ.'RIPI')THEN
CAL          RMINIP = 200
          TILED = .TRUE.
C     ..
C     .. horizontal gap is 17 pixels wide, vertical gap is 7 pixels wide
          TILEX(1) = 195
          TILEY(1) = 487
          TILEWX(1) = 17
          TILEWY(1) = 7
C
C---- For spot finding, extend the "excluded area" by 4 pixels
C
          IF(.NOT.GAPMASK)THEN
            GAPMASK = .TRUE.
            IOFFSET = 1
            IOFFSETSP = 5

            CALL GETGAPS(NREC,IYLEN,IOFFSET,IOFFSETSP,HRAST,IERR)
            IF (IERR.NE.0) THEN
              WRITE(IOUT,FMT=6210) NREC,IYLEN
              IF (ONLINE) WRITE(ITOUT,FMT=6210) NREC,IYLEN
              STOP
            END IF

            NXYEXC = NXYEXCDET
            IF (DEBUG(102)) THEN
              WRITE(IOUT,FMT=6080) NXYEXC,MACHINE
              IF (ONLINE) WRITE(ITOUT,FMT=6080) NXYEXC,MACHINE
            END IF
          END IF
        ENDIF
C
C---- Need to add gap definitions for Eiger ****
C
C     ..
C     
        IF(MACHINE.EQ.'RIEI')THEN
CAL          RMINIP = 200
          TILED = .TRUE.
C
C---- For spot finding, extend the "excluded area" by 4 pixels
C
          IF(.NOT.GAPMASK)THEN
            GAPMASK = .TRUE.
            IOFFSET = 1
            IOFFSETSP = 5

            CALL GETGAPS(NREC,IYLEN,IOFFSET,IOFFSETSP,HRAST,IERR)
            IF (IERR.NE.0) THEN
              WRITE(IOUT,FMT=6210) NREC,IYLEN
              IF (ONLINE) WRITE(ITOUT,FMT=6210) NREC,IYLEN
              STOP
            END IF

            NXYEXC = NXYEXCDET
            IF (DEBUG(102)) THEN
              WRITE(IOUT,FMT=6080) NXYEXC,MACHINE
              IF (ONLINE) WRITE(ITOUT,FMT=6080) NXYEXC,MACHINE
            END IF
          END IF
        END IF
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +     BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
          IF (ONLINE) WRITE(ITOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +     BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
        END IF

C     ********************************
      ELSE IF (MACHINE.EQ.'BRUK') THEN
C     ********************************
C     
C---- Bruker images have a multiple of 512 bytes in the image header, but
C     each record is 80 bytes
C     
         IF (DEBUG(102)) THEN
            WRITE(IOUT,FMT=6018) NBYTE,ISWAP
            IF (ONLINE) WRITE(ITOUT,FMT=6018) NBYTE,ISWAP
         END IF
         IERR = 0
         NNBYTE = 80
         SUMBYTES = 0
         KEY = '        '
         ENDLINE0 = CTRLZ//CTRLD//CTRL0//'.....'
         ENDLINE = CTRLZ//CTRLD//'......'
         ENDLINE2 = CTRLZ//CTRLD
         DOTLINE = '........'
C
C---- loop over header items
C
c         DO 2010 WHILE(KEY.NE.'ENDING2:')
         DO 2010 WHILE(KEY(1:2).NE.ENDLINE2)
           CALL GETBLK(BHEAD(1),NNBYTE,1,ISWAP,IERR)
           SUMBYTES = SUMBYTES + 80
C     
C---- Trap error in read
C     
           IF (IERR.NE.0) THEN
             WRITE(IOUT,FMT=6004) MACHINE
             IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
             IF(SOCKLO)THEN
               WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $              XODFILE(1:LENSTR(XODFILE))
               CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $              XMLLINE)
             ENDIF
             ISTAT = -1
             RETURN
           END IF
C     
           IF (DEBUG(102)) THEN       
             WRITE(IOUT,FMT=6030) (CHEAD(I),I=1,NNBYTE)
             IF (ONLINE) WRITE(ITOUT,FMT=6030) (CHEAD(I),I=1,NNBYTE)
           END IF
C     
C---- Decode the header information
C     
           NCH = 0
           NCH = NCH + 1
C     
C---- Search for end of this line
C     
           NSTART = NCH
C
C---- end of header ----
C
C 2014      IF (CHEAD(NCH).NE.'ENDING2')THEN
 2014      IF (CHEAD(NCH).NE.ENDLINE)THEN
C 
C---- end of line
C
             IF (NCH.LT.nnbyte)THEN
               NCH = NCH + 1
               IF (NCH.GT.NNBYTE) THEN
                 WRITE(IOUT,FMT=6032)MACHINE
                 IF (ONLINE) WRITE(ITOUT,FMT=6032)MACHINE
                 IF(SOCKLO)THEN
                   WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $                  XODFILE(1:LENSTR(XODFILE))
                   CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $                  XMLLINE)
                 ENDIF
                 ISTAT = -2
                 RETURN
               END IF
               GOTO 2014
C     
             ELSE
               NEND = NCH - 1
               NCHAR = NEND-NSTART+1
               LINE = ' '
               IF (NCHAR.LE.240) 
     +              WRITE(LINE,FMT=6034) (CHEAD(I),I=NSTART,NEND)
               IF (DEBUG(102)) THEN
                 WRITE(IOUT,FMT=6036) LINE(1:LENSTR(LINE))
                 IF (ONLINE) WRITE(ITOUT,FMT=6036) LINE(1:LENSTR(LINE))
               END IF
C     
C---- Decode keyword
C     
C     ******************************************
               CALL MPARSE(LINE(9:80),IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C     ******************************************
               KEY = LINE(1:8)
               CALL CCPUPC(KEY)
C
C---- new or old-style image? 
C
               IF (KEY.EQ.'FORMAT :') THEN
                 IF(VALUE(1).LT.100)THEN
                   BRUKNEW = .FALSE.
c
c----- harry breaks things, 20th NOvember 2007
c
                   bruknew = .true.
                 ELSE
                   BRUKNEW = .TRUE.
                 ENDIF
C
C---- start checking against known contents of header
C
               ELSE IF (KEY.EQ.'NROWS  :') THEN
                 IYLEN = NINT(VALUE(1))
               ELSE IF (KEY.EQ.'NCOLS  :') THEN
                 NREC = NINT(VALUE(1))
               ELSE IF (KEY.EQ.'DISTANC:') THEN
C     
C--- distance in CM on Bruker images
C
C
C---- this is a bit of a kludge - the active surface is 4 - 7mm behind the 
C     front of the detector on Brukers, but it's the crystal - detector front 
C     surface which is recorded in the header. Images converted with frm2frm 
C     have a distance which may be correct (VALUE(2)), but if it isn't there
C     it may be approximated by adding a small delta.
C
                 IF(VALUE(2).GT.1E-3)THEN
                   HDIST = VALUE(2)*10.0
                 ELSE
                   HDIST = (VALUE(1)*10.0) + 6.6
                 ENDIF
               ELSE IF (KEY.EQ.'WAVELEN:') THEN
                 HWAVE = VALUE(1)
               ELSE IF (KEY.EQ.'START  :') THEN
                 HPHIS = VALUE(1)
               ELSE IF (KEY.EQ.'RANGE  :') THEN
                 OSCRNG = VALUE(1)
               ELSE IF (KEY.EQ.'ANGLES :') THEN
C     
C---- Bruker header has angles (1) twotheta, (2) omega, (3) phi, (4) chi
C     .. (a) sometimes 0 is written as 360 in the header...
C     .. (b) twotheta is written in the header according to the Mosflm 
C     ..     convention, except for when we have an omega scan.
C     .. (c) omega runs in the opposite direction to phi!?
                 HTWOTHETA = VALUE(1)
                 HOMEGAS = VALUE(2)
                 HOMEGAS = MOD(HOMEGAS,360.0)
                 HPHIS = VALUE(3)
                 HPHIS = MOD(HPHIS,360.0)
                 HCHI = VALUE(4)
               ELSE IF (KEY.EQ.'ENDING :') THEN
C     
C---- Bruker header has angles (1) twotheta, (2) omega, (3) phi, (4) chi -
C     but moving twotheta or chi doesn't make sense during a scan.
                 HOMEGAE = VALUE(2)
                 HOMEGAE = MOD(HOMEGAE,360.0)
                 HPHIE = VALUE(3)
                 HPHIE = MOD(HPHIE,360.0)
C     
C---- add beam position read from image header; Bruker images have this 
C     in Pixels, so we need to convert. Third and fourth values are for 
C     unwarped images. Also need to correct for two-theta swing just before 
C     returning.
C     
               ELSE IF (KEY.EQ.'CENTER :')THEN
                 HBEAMY = VALUE(3) * RAST
                 HBEAMX = (REAL(IYLEN) - VALUE(4)) * RAST
                 IF(IBEAM.EQ.0)IBEAM = 3
C     
               ELSE IF (KEY.EQ.'AXIS   :')THEN
C
C---- 1 for 2-theta scan, 2 for omega scan, 3 for phi scan, 4 for chi
C     scan) - if omega scan, we can assume that it's just like a PHI
C     scan on a normal detector, If it's PHI scan, however, we need to
C     set GONIO_CHI to its correct value; use HCHI because we may 
C     have a 4-circle with chi circle.
C
                 HOSCAXIS = ' '
                 IF(IHOSCAXIS.EQ.0)THEN
                   IF(VALUE(1).EQ.2)THEN
                     GON_CHI_SET = 0.0
                     HOSCAXIS = 'OMEGA'
                     OMEGAFD = 270.0
                     OMEGAF = OMEGAFD * DTOR
                   ELSEIF(VALUE(1).EQ.3)THEN
                     HTWOTHETA = -HTWOTHETA
                     GON_CHI_SET = HCHI
                     HOSCAXIS = 'PHI'
                     OMEGAFD = 90.0
                     OMEGAF = OMEGAFD * DTOR
                   ENDIF
                 ENDIF
C
C---- how many pixels per data point? Just check for underflow table at
C     the moment...
C
               ELSE IF (KEY.EQ.'NPIXELB:')THEN
                 HUNDER = INT(VALUE(2))
C
C---- check for over/underflows
C
               ELSE IF (KEY.EQ.'NOVERFL:')THEN
                 IF(BRUKNEW)THEN
                   HOVER(1) = INT(VALUE(1))
                   ADDALL = (HOVER(1).NE.-1)
                   HOVER(2) = INT(VALUE(2))
                   HOVER(3) = INT(VALUE(3))
                 ELSE
                   NOVFL = INT(VALUE(1))
                   NRECOVFL = 16*NOVFL
                 ENDIF
C
C---- exposure bias table
C
               ELSE IF (KEY.EQ.'NEXP   :')THEN
                 HBIAS = INT(VALUE(3))
C
C---- pixel size always, apparently for 512x512 detector, so we need to 
C     modify for NREC, IYLEN...
C
               ELSE IF (KEY.EQ.'DETTYPE:')THEN
                 IF(NREC.GT.0.AND.NTOK.GE.2)THEN
                   HRAST = 10.0 * 512 / (NREC*VALUE(2))
                   HRASTY = 10.0 * 512 / (IYLEN*VALUE(2))
                 ELSE
                   HRAST = 0.08999
                   HRASTY = 0.08999
                 ENDIF
               ENDIF
             ENDIF
             NCH = NCH + 2
             NSTART = NCH
           ENDIF

 2010    ENDDO
         IF(HOSCAXIS.EQ.'OMEGA')THEN
c hrp 10.04.2006 - treat omega scan as phi scan here! N.B. Bruker goniostats seem to 
C     have PHI and OMEGA running in opposite directions...
           HPHIS = HOMEGAS
           HPHIE = HOMEGAE
           HPHIR = HPHIE - HPHIS
           GENGON = .FALSE.
           THREECIRCLE=.FALSE.
           FOURCIRCLE=.FALSE.
         ELSEIF(HOSCAXIS.EQ.'PHI')THEN
           GENGON = .true.
           THREECIRCLE=.TRUE.
           FOURCIRCLE=.FALSE.
         ENDIF
c hrp 10.04.2006 not sure we need this conversion         HPHIE = HPHIS + OSCRNG
         IF((HBEAMX.GT.0.0).AND.(HBEAMY.GT.0.0).AND.(IBEAM.EQ.0))IBEAM=3
C
C---- now check for and read to the end of the header block
C
           CHECKSUM = MOD(512-MOD(SUMBYTES,512),512)
           IF (CHECKSUM.NE.0)THEN
             SUMBYTES = SUMBYTES + CHECKSUM
             CALL GETBLK(BHEAD(1),CHECKSUM,1,ISWAP,IERR)
           ENDIF
C
C---- finally, calculate how many bytes are in over/underflow table for
C     new format images - each field is a multiple of 16 bytes
C
         IF(BRUKNEW)THEN
           IF((HOVER(1).NE.-1).OR.(HOVER(2).NE.0)
     $          .OR.(HOVER(3).NE.0))THEN
             I = 0
             NRECOVFL = I
             IF((HUNDER.GT.0).AND.(HOVER(1).GT.0))
     $            I = (16/((HUNDER-1)*HOVER(1)))+16
             NRECOVFL = I
             IF(HOVER(2).GT.0)I = (16*(INT(2*(HOVER(2)-1)/16))) + 16
             NRECOVFL = NRECOVFL + I
             IF(HOVER(3).GT.0)I = (16*(INT(4*(HOVER(3)-1)/16))) + 16
             NRECOVFL = NRECOVFL + I
             NOVFL = HOVER(1) + HOVER(2) + HOVER(3)
           ELSE
             NOVFL = 0
           ENDIF
           IF(ADDALL)ICONST = HBIAS
         ELSE
C... placeholder for old-style images           
         ENDIF
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +     BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
          IF (ONLINE) WRITE(ITOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +     BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
        END IF

C     ********************************
      ELSE IF (MACHINE.EQ.'OXFO') THEN
C     ********************************
        CALL READOXHEADER(ISWAP)
C     .. check for omega scans
        IF(HOSCAXIS.EQ.'OMEGA')THEN
          HPHIS = HOMEGAS
          HPHIE = HOMEGAE
          HPHIR = HPHIE - HPHIS
        ENDIF
C     ********************************
      ELSE IF (MACHINE.EQ.'OXFM') THEN
C     ********************************
C     
C---- New Oxford small (512x512) CCD detector (OXFM) is currently written
C      in Mar IPformat (Mar 345), but I expect this will change (01.10.2002 )
C
C
C---- Oxford native format has an ASCII header of 256 bytes; in this
C     header, it has the size of the total header - the rest is in binary.
C
        IF (NBYTE.EQ.0) THEN
          IF (DEBUG(102)) THEN
            WRITE(IOUT,FMT=6018) NBYTE,ISWAP
            IF (ONLINE) WRITE(ITOUT,FMT=6018) NBYTE,ISWAP
          END IF
          NNBYTE = 256
        ELSE
          NNBYTE = NHBYTES
        END IF
        IERR = 0
        CALL GETBLK(BHEAD(1),NNBYTE,1,ISWAP,IERR)
C     
C---- Trap error in read
C
        IF (IERR.NE.0) THEN
          WRITE(IOUT,FMT=6004) MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
          IF(SOCKLO)THEN
            WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
          ENDIF
          ISTAT = -1
          RETURN
        END IF
C
C---- pseudo MAR345 Oxford CCD
C
C---- Work out byte order by checking value of NREC
C     NITEM is number of words we want to use from header
        MODEL = 'OXM345'
        NITEM = 25
        BYTSWAP = .FALSE.
        NREC = IHEAD(1)
        IF (NREC.NE.1234) THEN
          NXPIXO = NREC
          CALL SWAPHDR(BHEAD(1),NITEM)
          BYTSWAP = .TRUE.
          NREC = IHEAD(1)
          IF(NREC.NE.1234)THEN
            WRITE(IOUT,FMT=6100)NXPIXO,NREC
            IF (ONLINE) WRITE(ITOUT,FMT=6100) NXPIXO,NREC
 6100       FORMAT(//1X,' **** FATAL ERROR ****',/,1X,'The first',
     $           ' record in the header must be "1234" for Oxfor',
     $           'd CCD images written in pseudo-MAR format',/,1X,
     +           'The number from the first word of the header r',
     $           'ecord is',I16,/,1X,'with original byte order o',
     $           'r',I16,/,1X,'with swapped byte order',/,1X,'If',
     $           ' this is NOT an image from an Oxford CCD, have',
     +           ' you included the appropriate',/,1X,'SCANNER (',
     $           'or SITE) keyword ??')
            IF(SOCKLO)THEN
              WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $             XODFILE(1:LENSTR(XODFILE))
              CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $             XMLLINE)
            ENDIF
            ISTAT = -2
            RETURN
          END IF
          WRITE(IOUT,FMT=6001)
          IF (ONLINE.AND..NOT.SOCKLO) WRITE(ITOUT,FMT=6001)
        ENDIF
        NREC = IHEAD(2)
        IYLEN = NREC
        HRAST = 0.001*IHEAD(7)
        HRASTY = 0.001*IHEAD(8)
        HWAVE = 0.000001*IHEAD(9)
        HDIST = 0.001*IHEAD(10)
        HPHIS = 0.001*IHEAD(11)
        HPHIE = 0.001*IHEAD(12)
        IF((HPHIS.GT.HPHIE).AND.(HPHIS-360.0.LT.HPHIE))
     $       THEN 
          HPHIE = HPHIE + 360.0
        ENDIF
        HPHIR = HPHIE - HPHIS
C     
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6010) NREC,IYLEN,ILRECL,
     +         NNREC,NOVFL,NRECOVFL,BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,
     +         HRAST
          IF (ONLINE) WRITE(ITOUT,FMT=6010) NREC,IYLEN,ILRECL,
     +         NNREC,NOVFL,NRECOVFL,BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,
     +         HRAST
          NROWS = NITEM/5 + 1
          I1 = 1
          I2 = I1 + 4
          DO 102 I = 1,NROWS
            WRITE(IOUT,FMT=6012) I1,I2,(IHEAD(JJ),JJ=I1,I2)
            IF (ONLINE) WRITE(ITOUT,FMT=6012) 
     +           I1,I2,(IHEAD(JJ),JJ=I1,I2)
            I1 = I1 + 5
            I2 = MIN(NITEM, I1+4)
 102      CONTINUE
          I1 = 1
          I2 = I1 + 4
          DO 104 I = 1,NROWS
            WRITE(IOUT,FMT=6014) I1,I2,(RHEAD(JJ),JJ=I1,I2)
            IF (ONLINE) WRITE(ITOUT,FMT=6014)
     +           I1,I2,(RHEAD(JJ),JJ=I1,I2)
            I1 = I1 + 5
            I2 = MIN(NITEM, I1+4)
 104      CONTINUE
C     AL          NROWS = 20
          I1 = 1
          I2 = I1 + 4
          DO 106 I = 1,NROWS
            WRITE(IOUT,FMT=6016) I1,I2,(CHEAD(JJ),JJ=I1,I2)
            IF (ONLINE) WRITE(ITOUT,FMT=6016)
     +           I1,I2,(CHEAD(JJ),JJ=I1,I2)
            I1 = I1 + 5
            I2 = MIN(NITEM, I1+4)
 106      CONTINUE
C     
C---- end of pseudo-MAR345 Oxford CCD block
C     
        ENDIF
C
C---- end small Oxford CCD (512x512)
C     ********************************
      ELSE IF (MACHINE.EQ.'OXPK') THEN
C     ********************************
C     
C     Oxford Crysalis packed images (PCK), OXPK code added 14/6/21
C     Images can be 1024x1024 (2x2 binned) or 2048x2048
C
C     Need to open the image file
C
        CALL QOPEN(INOD,ODFILE,'READONLY')
        CALL QMODE (INOD,0,NCMITM)
C
C---- 10 integers and 15 reals in header contain useful information, so
C     read 100 bytes
C
        NBYTE = 100
        IERR = 0
        CALL GETBLK(BHEAD(1),NBYTE,1,ISWAP,IERR)
        CALL QCLOSE(INOD)
C     
C---- Trap error in read
C
        IF (IERR.NE.0) THEN
          WRITE(IOUT,FMT=6004) MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
          IF(SOCKLO)THEN
            WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
          ENDIF
          ISTAT = -1
          RETURN
        END IF
C
C---- Work out byte order by checking value of NREC
C     NITEM is number of words we want to use from header
        NITEM = 25
        BYTSWAP = .FALSE.
        NREC = IHEAD(1)
        IF ((NREC.NE.1024).AND.(NREC.NE.2048)) THEN
          NXPIXO = NREC
          CALL SWAPHDR(BHEAD(1),NITEM)
          BYTSWAP = .TRUE.
          NREC = IHEAD(1)
          IF ((NREC.NE.1024).AND.(NREC.NE.2048)) THEN
            WRITE(IOUT,FMT=6101)NXPIXO,NREC
            IF (ONLINE) WRITE(ITOUT,FMT=6101) NXPIXO,NREC
 6101       FORMAT(//1X,' **** FATAL ERROR ****',/,1X,'The first',
     $           ' record in the header must be 1024 OR 2048 for Oxfor',
     $           'd CCD images written as packed fileS',/,1X,
     +           'The number from the first word of the header r',
     $           'ecord is',I16,/,1X,'with original byte order o',
     $           'r',I16,/,1X,'with swapped byte order')
            IF(SOCKLO)THEN
              WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $             XODFILE(1:LENSTR(XODFILE))
              CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $             XMLLINE)
            ENDIF
            ISTAT = -2
            RETURN
          END IF
          WRITE(IOUT,FMT=6001)
          IF (ONLINE.AND..NOT.SOCKLO) WRITE(ITOUT,FMT=6001)
        ENDIF
        NREC = IHEAD(2)
        IYLEN = NREC
C
C---- Set pixel size appropriate for binning
C
        IF (NREC.EQ.1024) THEN
          HRAST = 0.12309
        ELSE
          HRAST = 0.06155
        END IF
        HWAVE = RHEAD(20)
        HDIST = RHEAD(21)
        HPHIS = RHEAD(22)
        HPHIE = RHEAD(23)
        IF((HPHIS.GT.HPHIE).AND.(HPHIS-360.0.LT.HPHIE))
     $       THEN 
          HPHIE = HPHIE + 360.0
        ENDIF
        HPHIR = HPHIE - HPHIS
C     
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6010) NREC,IYLEN,ILRECL,
     +         NNREC,NOVFL,NRECOVFL,BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,
     +         HRAST
          IF (ONLINE) WRITE(ITOUT,FMT=6010) NREC,IYLEN,ILRECL,
     +         NNREC,NOVFL,NRECOVFL,BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,
     +         HRAST
C     
C---- end of packed OXFORD CRYSALIS
C     
        ENDIF
C
C---- Note that there is no test in this S/R for (MACHINE.EQ.'PILA') or 
C     (MACHINE.EQ.'EIGE') both these detectors are dealt with by the test 
C     on MINICBF that follows.
C     I think above comment is wrong, there are tests below for MACHINE
C     being 'PILA' or 'EIGI' or 'APAD', when MODEL is assigned and the 
C     tile gap regins are set up.
C     However, for reading the header, are these are all initially handled
C     as being MINICBF image files. AGWL 15/3/19
C
C     ********************************
      ELSE IF (MINICBF) THEN
C     ********************************
C     header information is delimited by '_array_data.header_contents' and
C     '_array_data.data'.
C     read until we find a # in the first column (i.e. preceded by \r\n), 
C     only reading mincbfs at the moment; 
C     there is an undefined number of characters in the header, but a few 
C     examples seem to have 900+.
C
C     Following the bit where we read the comment-style header, we need 
C     to read the "--CIF-BINARY-FORMAT-SECTION--" up to the point where we
C     find NREC & IYLEN.
C
        MINICBFL = BACKSLR//BACKSLN//CTRLL
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6019) NBYTE,ISWAP
          IF (ONLINE) WRITE(ITOUT,FMT=6019) NBYTE,ISWAP
 6019     FORMAT(/,1X,'In minicbf IN GETHDR, NBYTE=',I6,'  ISWAP=',I3)
        END IF
        IERR = 0
        NNBYTE = 8000
        FIRSTTIME = .TRUE.
        CALL GETBLK(BHEAD(1),NNBYTE,1,ISWAP,IERR)
C
C---- Trap error in read
C
        IF (IERR.NE.0) THEN
          WRITE(IOUT,FMT=6004) MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
          IF(SOCKLO)THEN
            WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
          ENDIF
          ISTAT = -1
          RETURN
        END IF
C
C---- Only dump header once
C
        IF (DEBUG(102).AND.(.NOT.DUMPHEAD)) THEN       
            DUMPHEAD = .TRUE.
            NITEM = NNBYTE
            WRITE(IOUT,FMT=6030) (CHEAD(I),I=1,NITEM)
            IF (ONLINE) WRITE(ITOUT,FMT=6030) (CHEAD(I),I=1,NITEM)
        END IF      
C
C---- Start of header, skip to start of first line
C
        NCH = 1
C     
C---- find out the start and end of the header section
C
        NSTART = 0
        NEND = 0
        DO 300 WHILE (NSTART.EQ.0.AND.NCH.LE.NNBYTE)
          WRITE(LINE,FMT=6034) (CHEAD(I),I=NCH,NCH+26)
          IF(LINE(1:LENSTR(LINE)).EQ.'_array_data.header_contents')THEN
            NSTART = NCH + 32
            NCH = NSTART
          ENDIF
          NCH = NCH + 1
 300    ENDDO

        DO 320 WHILE (NEND.EQ.0.AND.NCH.LE.NNBYTE)
          NCH = NCH + 1
          WRITE(LINE,FMT=6034) (CHEAD(I),I=NCH,NCH+15)
          IF(LINE(1:LENSTR(LINE)).EQ.'_array_data.data')THEN
            NEND = NCH - 3
          ENDIF
 320    ENDDO
C
C----return if too many characters
C
        IF (NCH.GT.NNBYTE) THEN
          WRITE(IOUT,FMT=6032)MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6032)MACHINE
          IF(SOCKLO)THEN
            WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          ENDIF
          ISTAT = -2
          RETURN
        END IF
C     ..
C     .. read to the next #, then this line is delimited by the \r\n
        JJ = NSTART + 1
        DO 340 WHILE (JJ.LT.NEND)
C     ..
C     .. if first character on line is semicolon, then we have reached the 
C     .. end of the miniCBF header block so we stop parsing it!
          IF(CHEAD(NSTART).EQ.';')THEN
            JJ = NEND
          ELSE
            IF(CHEAD(JJ).EQ.BACKSLN)THEN
              NCH = JJ - 2
              WRITE(LINE,FMT=6034) (CHEAD(I),I=NSTART+2,NCH)
              NSTART = NCH + 3
C---- Decode keyword
C     
C     ******************************************
              CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C     ******************************************
              KEY = LINE(IBEG(1):IEND(1))
              IF (KEY(1:2).EQ.'20') THEN
C
C---- Decode date, used for detectors transferred to non-standard setup (vertical
C     rotation axis), only currently for DLS VMXm transferred on 17/4/19. The logical
C     TESTDATE is set in SETDETECT.
C
                IF (TESTDATE.AND.(.NOT.DONE)) THEN
                  DONE = .TRUE.
                  LINE = KEY(1:4)//' '//KEY(6:7)//' '//KEY(9:10)//'  '
                  CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
                  IYEAR = VALUE(1)
                  IMONTH = VALUE(2)
                  IDAY = VALUE(3)
                  IDATE = IYEAR*10000+IMONTH*100+IDAY
                  IF (IDATE.GT.2019*10000+4*100+17) THEN
                    OMEGAFD = 90
                    BEAMLINE = 'DLS VMXm'
                    WRITE(IOUT,FMT=6021) HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
                    IF (ONLINE) WRITE(ITOUT,FMT=6021) 
     +                 HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
 6021               FORMAT(/,1X,'*** IMPORTANT ***',/,1x,
     +              'From the detector',
     +              ' serial number ',A,' this has been identified',
     +              ' as an image from ',A,/,1X,'that has ',
     +              'a vertical rotation axis.',/,1X,
     +              'The OMEGA angle has therefore been set to',F6.1,
     +              ' instead of the usual value of 0.0.',/,1X,'If ',
     +              'this is not correct, reset OMEGA to 0.0')
C
C---- Non-standard beamline setup (eg vertical rotation axis), OMEGA > 0
C
                  XMLLINE = ' '
                  SERIOUSCOLOUR = 'RED'
                  WRITE(XMLLINE,FMT=6023) SERIOUSCOLOUR
                  CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $                 XMLLINE)

 6023              FORMAT('<?xml version="1.0"?>',
     $             '<!DOCTYPE warnings>',
     $             '<warnings><process>indexing</process>'
     $             '<warning><type>warning</type>',
     $             '<colour>',A,'</colour>',
     +             '<message>Non standard experimental setup',
     +             '</message>',
     +             '<detail>From the detector serial number, the data',
     +             ' appears to come from a beamline with a vertical',
     +             ' rotation axis. See start of mosflm.lp file for ',
     +             'more details. If this is not the case, reset ',
     +             'OMEGA to 0.0 in Settings->Experiment settings',
     +             ' otherwise indexing will not work.',
     +             '</detail><hint>none</hint>',
     +             '</warning></warnings>')
 


                    TESTDATE = .FALSE.
                  END IF
                END IF
              ELSEIF(KEY.EQ.'Pixel_size')THEN
C              Need to CCPUPC here because Pilatus header use "e-6"
                call ccpupc(line)
                CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
                HRAST = VALUE(2) * 1000.0
                HRASTY = VALUE(5) * 1000.0
              elseIF(KEY.EQ.'Wavelength')THEN
                HWAVE = VALUE(2)
              ELSEIF(KEY.EQ.'Start_angle')THEN
                HPHIS = VALUE(2)
              ELSEIF(KEY.EQ.'Angle_increment')THEN
                HPHIR = VALUE(2)
              ELSEIF(KEY.EQ.'Detector_distance')THEN
                IF(VALUE(2).LE.10)THEN
                  HDIST = 1000.0 * VALUE(2)
                ELSE
                  HDIST = VALUE(2)
                ENDIF
              ELSEIF(KEY.EQ.'Beam_xy')THEN
C     X & Y are swapped compared to Mosflm, and are already corrected for 
C     INVERTX except on 4M where it doesn't look like it.

                HBEAMY = VALUE(2)
                HBEAMX = VALUE(3)
                IF(IBEAM.EQ.0)IBEAM = 3
              ELSEIF(KEY.EQ.'Polarization')THEN
                HTOR = VALUE(2)
              ELSEIF(KEY.EQ.'Alpha')THEN
                IF(IGON_KAPPA_SET.EQ.0)GON_KAPPA_SET = VALUE(2)
              ELSEIF(KEY.EQ.'Kappa')THEN
                HKAPPA = VALUE(2)
              ELSEIF(KEY.EQ.'Detector_2theta')THEN
                HTWOTHETA = VALUE(2)
C
C---- next is only for detector on I24 at DLS, which may use vertical goniostat 
C     normally or horizontal for in situ... I don't know if these are the right values!
C
              ELSEIF(KEY.EQ.'Oscillation_axis')THEN
                IF(NTOK.GE.3)THEN
                  KEY = LINE(IBEG(3):IEND(3))
                  IF(KEY.EQ.'+SLOW')THEN
                    OMEGAFD = 270
                    VERTICAL = .TRUE.
                  ELSEIF(KEY.EQ.'+FAST')THEN
                    OMEGAFD = 0
                    VERTICAL = .FALSE.
                  ENDIF
                  OMEGAF = OMEGAFD * DTOR
                ENDIF
C
C---- read saturation value for Eiger/Pilatus
C
              ELSEIF(KEY.EQ.'Count_cutoff')THEN
                HCUTOFF = VALUE(2)
                HPRCUTOFF = VALUE(2)
              ELSEIF(KEY.EQ.'Detector:')THEN
C
C---- Some Pilatus images do not have serial number, so check this
C     *** HSERIAL is now assigned in a general way in GETDETECT, so comment out
CAL                IF (((IBEG(6).GE.1).AND.(IEND(6).GE.1)).AND.
CAL     +               ((IBEG(6).LE.240).AND.(IEND(6).LE.240)))
CAL     +               HSERIAL = LINE(IBEG(6):IEND(6))
C
C---- Eiger: temporary code for gaps that are not right
C            This is for the 1M at SLS and the 4M at ESRF in early
C            2015. 
C            Note that the 4M at ESRF on ID30 in 2016 has a different serial number
C            (E-08-0104).
C
                IF (HSERIAL.EQ.'E-08-0106')THEN
                  GAPVAL = -32766
                ELSEIF (HSERIAL.EQ.'E-02-PSI')THEN
                  GAPVAL = -2051
                ELSE
                  GAPVAL = 0
                ENDIF
              ENDIF
            ENDIF
            JJ = JJ + 1
          ENDIF
 340    ENDDO
C
C do this conversion when we should have both HRAST and HBEAM values.
C
        HBEAMX = HBEAMX * HRAST
        HBEAMY = HBEAMY * HRASTY
        RAST = HRAST
        HPHIE = HPHIS + HPHIR
C
C now for the CIF-BINARY-FORMAT-SECTION stuff
        NSTART = NEND
        DO 360 WHILE (NEND.EQ.NSTART.AND.NCH.LE.NNBYTE)
          NCH = NCH + 1
          WRITE(LINE,FMT=6034) (CHEAD(I),I=NCH,NCH+21)
          IF(LINE(1:3).EQ.MINICBFL)THEN
            NEND = NCH
          ENDIF
 360    ENDDO
C
C----return if too many characters
C
        IF (NCH.GT.NNBYTE) THEN
          WRITE(IOUT,FMT=6032)MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6032)MACHINE
          IF(SOCKLO)THEN
            WRITE(XMLLINE,FMT=7010)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          ENDIF
          ISTAT = -2
          RETURN
        END IF
C     ..
C     .. read to the next #, then this line is delimited by the \r\n
        JJ = NSTART + 1
        DO 380 WHILE (JJ.LT.NEND)
          IF(CHEAD(JJ).EQ.BACKSLN)THEN
            NCH = JJ - 2
            WRITE(LINE,FMT=6034) (CHEAD(I),I=NSTART,NCH)
C---- Decode keyword
C     
C     ******************************************
            CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
            IF(LINE(1:1).EQ.';'.OR.LENSTR(LINE).LT.1)THEN
              IBEG(1) = 1
              IEND(1) = 1
            ENDIF
C     ******************************************
            KEY = LINE(IBEG(1):IEND(1))
            IF(KEY.EQ.'X-Binary-Size-Fastest-Dimension:')THEN
              IYLEN = VALUE(2)
            ELSEIF(KEY.EQ.'X-Binary-Size-Second-Dimension:')THEN
              NREC = VALUE(2)
            ENDIF
            NSTART = NCH + 3
          ENDIF
          JJ = JJ + 1
 380    ENDDO
C
C---- now code explicitly for PILATUS detetors
C
        IF (MACHINE.EQ.'PILA') THEN
C     .. gaps are 17 pixels wide and 7 high, modules are 195 x 487. 
C     .. following code will only work up to 6M!
C     ..

          IF((NREC.EQ.(INT(NREC/195)*195) + (INT(NREC/195)-1)*17).AND.
     $       (IYLEN.EQ.(INT(IYLEN/487)*487) + (INT(IYLEN/487)-1)*7))
     $         THEN
            IF(XSCAN.EQ.0)XSCAN = 50 * RAST * NREC
            IF(YSCAN.EQ.0)YSCAN = 50 * RAST * IYLEN
            XMAXIP = XSCAN
            YMAXIP = YSCAN
            RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
            IF (ILIMIT.EQ.0) THEN
              XLIMIT = 0.01*(XMAXIP/2)
              LIMIT = NINT(100*XLIMIT)
            END IF
            NTILEX = INT(NREC/195)
            NTILEY = INT(IYLEN/487)
          ELSE
            IF(MODEL.EQ.'Unknown_')THEN
              IF(XSCAN.EQ.0)XSCAN = INT(NREC * 50 * RAST)
              IF(YSCAN.EQ.0)YSCAN = INT(IYLEN * 50 * RAST)
              XMAXIP = XSCAN
              YMAXIP = YSCAN
              RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
              IF (ILIMIT.EQ.0) THEN
                XLIMIT = 0.01*(XMAXIP/2)
                LIMIT = NINT(100*XLIMIT)
              END IF
C     .. 6M, 12x5
              IF(NREC.EQ.2527.AND.IYLEN.EQ.2463)THEN
                MODEL = '6M'
                NTILEX = 12
                NTILEY = 5
              ENDIF
              
C     ..
C     .. 2M, 8x3
              IF(NREC.EQ.1679.AND.IYLEN.EQ.1475)THEN
                MODEL = '2M'
                NTILEX = 8
                NTILEY = 3
              ENDIF
C     ..
C     .. 1M, 5x2
              IF(NREC.EQ.1043.AND.IYLEN.EQ.981)THEN
                MODEL = '1M'
                NTILEX = 5
                NTILEY = 2
              ENDIF
C     ..
C     .. 300K, 3x1
              IF(NREC.EQ.619.AND.IYLEN.EQ.487)THEN
                MODEL = '300K'
                NTILEX = 3
                NTILEY = 1
              ENDIF
C     ..
C     .. 100K, 1x1
              IF(NREC.EQ.195.AND.IYLEN.EQ.487)THEN
                MODEL = '100K'
                NTILEX = 1
                NTILEY = 1
              ENDIF
            ENDIF
          ENDIF
          STARTX = 195
          STEPX = 212
          WIDTHX = 17
C
C---- For proper exclusion, set start point IOFFSET pixels earlier
C     and extend width by 2*IOFFSET pixels. This is because of uncertainty
C     about conversion of pixels to mm, for example, are coords of
C     first pixel 0,0 or 0.5*rast,0.5*rast etc. 
C
C---- For spot finding, extend the "excluded area" by 4 pixels
C
          IF(.NOT.GAPMASK)THEN
            GAPMASK = .TRUE.
            IOFFSET = 1
            IOFFSETSP = 5

            CALL GETGAPS(NREC,IYLEN,IOFFSET,IOFFSETSP,HRAST,IERR)
            IF (IERR.NE.0) THEN
              WRITE(IOUT,FMT=6210) NREC,IYLEN
              IF (ONLINE) WRITE(ITOUT,FMT=6210) NREC,IYLEN
              STOP
            END IF

            NXYEXC = NXYEXCDET
C
            IF (DEBUG(102)) THEN
              WRITE(IOUT,FMT=6080) NXYEXC,MACHINE
              IF (ONLINE) WRITE(ITOUT,FMT=6080) NXYEXC,MACHINE
 6080         FORMAT(1X,'Set up',i3,' excluded areas (gaps) for ',A)
            END IF
          ENDIF
          IF(MODEL.EQ.'Unknown_')THEN
C     .. 6M, 12x5
            IF(NREC.EQ.2527.AND.IYLEN.EQ.2463)THEN
              MODEL = '6M'       
C     ..
C     .. 2M, 8x3
            ELSEIF(NREC.EQ.1679.AND.IYLEN.EQ.1475)THEN
              MODEL = '2M'
C     ..
C     .. 1M, 5x2
              IF(NREC.EQ.1043.AND.IYLEN.EQ.981)THEN
                MODEL = '1M'
              ENDIF
C     ..
C     .. 300K, 3x1 - Rigaku or Stoe?
            ELSEIF(NREC.EQ.619.AND.IYLEN.EQ.487)THEN
              MODEL = '300K'
              OMEGAFD = 270
              OMEGAF = OMEGAFD * DTOR
C     ..
C     .. 100K, 1x1 - Stoe?
            ELSEIF(NREC.EQ.195.AND.IYLEN.EQ.487)THEN
              MODEL = '100K'
              OMEGAFD = 270
              OMEGAF = OMEGAFD * DTOR
            ENDIF
          ENDIF
C
C---- Check for reverse phi based on serial number
C
C     TAKANORI: this is PILATUS3 6M on SPring-8 BL41XU. SN: 60-0125
C
          IF (HSERIAL.EQ.'60-0125') THEN
            IF (.NOT.UPDATEOMEGA) THEN
              OMEGAFD = 180.0 
              OMEGAF = OMEGAFD * DTOR
              UPDATEOMEGA = .TRUE.
              WRITE(IOUT,FMT=6058) 
              IF (ONLINE) WRITE(ITOUT,FMT=6058)
            END IF
          END IF
          IF (DEBUG(102)) THEN
            WRITE(IOUT,FMT=6072) MACHINE(1:LENSTR(MACHINE)),
     +                           HSERIAL(1:LENSTR(HSERIAL)),
     +                           GAPVAL,OMEGAFD
            IF (ONLINE) WRITE(ITOUT,FMT=6072) 
     +         MACHINE(1:LENSTR(MACHINE)),HSERIAL(1:LENSTR(HSERIAL)),
     +         GAPVAL,OMEGAFD
 6072       FORMAT(1X,'Machine: ',A,'  Serial number:',A,'  Gapval',I8,
     +             '  Omega:',F8.2)
            WRITE(IOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +           BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
            IF (ONLINE) WRITE(ITOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +           BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
          END IF

C     
C---- end of Pilatus miniCBF
C
C
C---- Now deal with Eiger files read as CBFs (not HDF5)
C
        ELSE IF (MACHINE.EQ.'EIGE')THEN

C---- ** NOTE ** Module sizes are different for Eiger and Eiger2 detectors
C
C
          EIGEROK = .TRUE.
          IF(EIGEROK)THEN
            IF(XSCAN.EQ.0)XSCAN = 50 * RAST * NREC
            IF(YSCAN.EQ.0)YSCAN = 50 * RAST * IYLEN
            XMAXIP = XSCAN
            YMAXIP = YSCAN
            RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
            IF (ILIMIT.EQ.0) THEN
              XLIMIT = 0.01*(XMAXIP/2)
              LIMIT = NINT(100*XLIMIT)
            END IF
C
C---- ESRF 4M has beam Y inverted, but only for very early versions of
C     beamline software, by 3rd April 2016 Y coord was correct.
C     The inversion led to incorrect YBEAM for Photon factory Eiger.
C
CAL            IF(NTILEX.EQ.4.AND.NTILEY.EQ.2)THEN
CAL              HBEAMY = (IYLEN * HRASTY) - HBEAMY
CAL            ENDIF
C
            IF(.NOT.GAPMASK)THEN
C
C---- Now set up by calling GETGAPS
C     IOFFSET is the offset to be applied because of uncertainty between
C     mm coords and pixel numbers, ie do mm coords refer to middle of pixel
C     or the corner of the pixel. 
C     IOFFSETSP is the offset applied when spot finding, to avoid finding
C     "false" spots at the tile boundaries.
C     Both IOFFSET and IOFFSETSP effectively increase the size of the gaps.
C
              GAPMASK = .TRUE.
              IOFFSET = 1
              IOFFSETSP = 5
              CALL GETGAPS(NREC,IYLEN,IOFFSET,IOFFSETSP,HRAST,IERR)
              IF (IERR.NE.0) THEN
                WRITE(IOUT,FMT=6210) NREC,IYLEN
                IF (ONLINE) WRITE(ITOUT,FMT=6210) NREC,IYLEN
 6210           FORMAT(1X,'*** WARNING ***',/,1X,
     +           'Based on the image size of',I6,' by',I6,
     +           ' the detector has not been recognised',/,1X,
     +           'as Pilatus, Eiger or Eiger2.'/,1X,'This means',
     +           ' that the gaps between tiles will not be marked',
     +           ' as',/,1X,'inactive areas.',/,1X,'This should not',
     +           ' affect integration providing these pixels have',
     +           ' values of -1.')
              END IF
              NXYEXC = NXYEXCDET
              IF (DEBUG(102)) THEN
                WRITE(IOUT,FMT=6080) NXYEXC,MACHINE
                IF (ONLINE) WRITE(ITOUT,FMT=6080) NXYEXC,MACHINE
              END IF
            ENDIF
C
C---- Check for reverse phi based on serial number
C
C     TAKANORI: this is EIGER 9M at SPring-8 BL32XU Serial no: E-18-0103
C
            IF (HSERIAL.EQ.'E-18-0103') THEN
              IF (.NOT.UPDATEOMEGA) THEN
                OMEGAFD = 180.0 
                OMEGAF = OMEGAFD * DTOR
                UPDATEOMEGA = .TRUE.
                WRITE(IOUT,FMT=6058) 
                IF (ONLINE) WRITE(ITOUT,FMT=6058)
              END IF
            END IF
            IF (DEBUG(102)) THEN
              WRITE(IOUT,FMT=6072) MACHINE(1:LENSTR(MACHINE)),
     +                           HSERIAL(1:LENSTR(HSERIAL)),
     +                           GAPVAL,OMEGAFD
              IF (ONLINE) WRITE(ITOUT,FMT=6072) 
     +         MACHINE(1:LENSTR(MACHINE)),HSERIAL(1:LENSTR(HSERIAL)),
     +         GAPVAL,OMEGAFD
              WRITE(IOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +          BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
              IF (ONLINE) WRITE(ITOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +          BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
            END IF
C     
C---- Next ENDIF is end of EIGEROK block
C
          ENDIF
C
C---- Now deal with ADSC hybrid pixel
C
        ELSEIF(MACHINE.EQ.'APAD')THEN
          IF(.NOT.GAPMASK)THEN
            GAPMASK = .TRUE.
C     .. large gaps are 28±1 pixels wide, small gaps 5±1 wide and 7±1 high, 
C     .. modules are 128 x 518
            IF(XSCAN.EQ.0)XSCAN = 50 * RAST * NREC
            IF(YSCAN.EQ.0)YSCAN = 50 * RAST * IYLEN
            XMAXIP = XSCAN
            YMAXIP = YSCAN
            RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
            IF (ILIMIT.EQ.0) THEN
              XLIMIT = 0.01*(XMAXIP/2)
              LIMIT = NINT(100*XLIMIT)
            END IF
C     ..
C     .. only for (2x1)x8 X 4 detector
            IOFFSET = 1
            NTILEX = 8
            NTILEY = 4
C     ..
C     .. big gaps first
            WIDTHX = 28
            STARTX = 264
            STARTX = STARTX - IOFFSET
            WIDTHX = WIDTHX + 2*IOFFSET
            STEPX = 289
            DO 530 II = 1,NTILEX-1
              NXYEXCDET = NXYEXCDET + 1
              XYEXC(1,NXYEXCDET) = 100.0*RAST*(STARTX + (II-1)*STEPX)
              XYEXC(2,NXYEXCDET) = 0.0
              XYEXC(3,NXYEXCDET) = 
     +             100.0*RAST*(STARTX + (II-1)*STEPX + WIDTHX)
              XYEXC(4,NXYEXCDET) = 100.0*RAST*IYLEN
 530        ENDDO
C     ..
C     .. little gaps - note we calculate NTILEX gaps, not NTILEX -1.
            WIDTHX = 5
            STARTX = 130
            STARTX = STARTX - IOFFSET
            WIDTHX = WIDTHX + 2*IOFFSET
            STEPX = 289
            DO 540 II = 1,NTILEX
              NXYEXCDET = NXYEXCDET + 1
              XYEXC(1,NXYEXCDET) = 100.0*RAST*(STARTX + (II-1)*STEPX)
              XYEXC(2,NXYEXCDET) = 0.0
              XYEXC(3,NXYEXCDET) = 
     +             100.0*RAST*(STARTX + (II-1)*STEPX + WIDTHX)
              XYEXC(4,NXYEXCDET) = 100.0*RAST*IYLEN
 540        ENDDO
C     
C---- Now lines parallel to X
C     
            STARTY = 521
            STEPY = 525
            WIDTHY = 7
            STARTY = STARTY - IOFFSET
            WIDTHY = WIDTHY + 2*IOFFSET
            DO 550 II = 1,NTILEY-1
              NXYEXCDET = NXYEXCDET + 1
              XYEXC(1,NXYEXCDET) = 0.0
              XYEXC(2,NXYEXCDET) = 100.0*RAST*(STARTY + (II-1)*STEPY)
              XYEXC(3,NXYEXCDET) = 100.0*RAST*NREC
              XYEXC(4,NXYEXCDET) = 
     +             100.0*RAST*(STARTY + (II-1)*STEPY + WIDTHY)
 550        ENDDO
            NXYEXC = NXYEXCDET
            IF (DEBUG(102)) THEN
              WRITE(IOUT,FMT=6080) NXYEXC,MACHINE
              IF (ONLINE) WRITE(ITOUT,FMT=6080) NXYEXC,MACHINE
            END IF
          ENDIF
            
          IF (DEBUG(102)) THEN
            WRITE(IOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +           BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
            IF (ONLINE) WRITE(ITOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +           BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
          END IF
        

C
C---- Now deal with Eiger files read as CBFs (not HDF5)
C
        ELSE IF (MACHINE.EQ.'TIME')THEN

C---- 
C
C
          IF(XSCAN.EQ.0)XSCAN = 50 * RAST * NREC
          IF(YSCAN.EQ.0)YSCAN = 50 * RAST * IYLEN
          XMAXIP = XSCAN
          YMAXIP = YSCAN
          RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
          IF (ILIMIT.EQ.0) THEN
            XLIMIT = 0.01*(XMAXIP/2)
            LIMIT = NINT(100*XLIMIT)
          END IF
          IF (DEBUG(102)) THEN
            WRITE(IOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +           BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
            IF (ONLINE) WRITE(ITOUT,FMT=6070) NREC,IYLEN,HRAST,HTOR,
     +           BYTSWAP,HDIST,HWAVE,HPHIS,HPHIE,HTWOTHETA,HBEAMX,HBEAMY
          END IF
        ENDIF
C
C---- If LIMITS REMOVE EVERYTHING has been specified, then set NXYEXCDET to zero
C
        IF (NOTILES) THEN
          NXYEXCDET = 0
          NXYEXC = 0
          WRITE(IOUT,FMT=6220)
          IF (ONLINE) WRITE(ITOUT,FMT=6220)
 6220     FORMAT(1X,' **** ALL EXCLUDED AREAS REMOVED ***')
        END IF
C     ********************************
      ELSE IF (FULLCBF) THEN
C     ********************************
C
C---- Set MODE=3 to read machine specific code for CBF files
C
C     
C---- Print for program flow
C
        CALLED = 'CBF_INFO'
        WRITE(COMMENT, FMT=6222) MODE,XODFILE(1:LENSTR(XODFILE))
 6222   FORMAT('MODE=',I3,' and filename:',A)
        IF (DEBUG(99)) 
     +                CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        MODE = 3
        CALL CBF_INFO(XODFILE,MODE,0,IERR)
C
C---- Change here, add test on HDF5FILE, if it is TRUE then don't use
C     following code to skip header records.11/3/19
C
C     ********************************
      ELSE IF (.NOT.HDF5FILE) THEN
C     ********************************
C
C---- Header records not to be used, just skip them
C
        IF (NHBYTE.EQ.0) NHBYTE = NBYTE
        IF (DEBUG(102)) THEN
          WRITE(IOUT,FMT=6020) NHBYTE,NHEAD
          IF (ONLINE) WRITE(ITOUT,FMT=6020) NHBYTE,NHEAD
 6020     FORMAT(1X,'Skipping',I6,' bytes in',I3,' header records')
        END IF
        IERR = 0
        DO 90 K = 1,NHEAD
          CALL GETBLK(BHEAD(1),NHBYTE,1,ISWAP,IERR)
          IF (DEBUG(102)) THEN
            NITEM = NHBYTE/4
            NROWS = NITEM/5 + 1
            I1 = 1
            I2 = I1 + 4
            DO 92 I = 1,NROWS
              WRITE(IOUT,FMT=6012) I1,I2,(IHEAD(JJ),JJ=I1,I2)
              IF (ONLINE) WRITE(ITOUT,FMT=6012) 
     +                    I1,I2,(IHEAD(JJ),JJ=I1,I2)
              I1 = I1 + 5
              I2 = MIN(NITEM, I1+4)
 92         CONTINUE
            I1 = 1
            I2 = I1 + 4
            DO 94 I = 1,NROWS
              WRITE(IOUT,FMT=6014) I1,I2,(RHEAD(JJ),JJ=I1,I2)
              IF (ONLINE) WRITE(ITOUT,FMT=6014)
     +                I1,I2,(RHEAD(JJ),JJ=I1,I2)
              I1 = I1 + 5
              I2 = MIN(NITEM, I1+4)
 94         CONTINUE
CAL            NROWS = 20
            I1 = 1
            I2 = I1 + 4
            DO 96 I = 1,NROWS
              WRITE(IOUT,FMT=6016) I1,I2,(CHEAD(JJ),JJ=I1,I2)
              IF (ONLINE) WRITE(ITOUT,FMT=6016)
     +                  I1,I2,(CHEAD(JJ),JJ=I1,I2)
              I1 = I1 + 5
              I2 = MIN(NITEM, I1+4)
 96         CONTINUE
          END IF
C
C---- Trap error in read
C
        IF (IERR.NE.0) THEN
          WRITE(IOUT,FMT=6004) MACHINE
          IF (ONLINE) WRITE(ITOUT,FMT=6004) MACHINE
          IF(SOCKLO)THEN
            WRITE(XMLLINE,FMT=7000)MACHINE(1:LENSTR(MACHINE)),
     $           XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
          ENDIF
          ISTAT = -1
          RETURN
        END IF
C
 90     CONTINUE
      END IF
C
C---- start of block for Eiger HDF5 files
C
C     ********************************
      IF (HDF5FILE) THEN
C     ********************************
        
        IF(HEADONLY)THEN
C     
C---- CHUNK is used for IMODE 2 to get the start phi and end phi if chunking images
C
C---- now in condata.f,           CHUNK = 1
          IERR = 0
          IF (PHIONLY) THEN
            IMODE = 3
          ELSE
            IMODE = 2
          ENDIF
          THISCHUNK = CHUNK
C     
C---- Print for program flow
C
          CALLED = 'EIGER'
          NIMGSUM = 1
          WRITE(COMMENT, FMT=6200) IMODE,NIMGSUM
 6200     FORMAT('with HEADONLY TRUE and IMODE=',I3,' NIMGSUM',I3)
          IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL EIGER(IERR,IMODE,THISIMG,THISCHUNK,NIMGSUM)
        ENDIF
      ENDIF
C
C---- end of block for Eiger HDF5 files
C

      if(debug(102))then
        write(iout,fmt=1111) nxyexc,nxyexcdet
        if (online) write(itout,fmt=1111) nxyexc,nxyexcdet
 1111   format(1x,'Exiting GETHDR nxyexc=',I3,
     +         '  nxyexcdet=',I3)
      endif
      RETURN
      END
C $Id: gethkl.f,v 1.5 2006/08/29 14:58:32 harry Exp $
C== GETHKL ==
C
      SUBROUTINE GETHKL(JREC,IH)
      IMPLICIT NONE
C     ==========================
C
C
C
C---- Find indices m,x and y for jrec'th reflection
C     in generate file
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     ..
C     .. Scalar Arguments ..
      INTEGER JREC
C     ..
C     .. Array Arguments ..
      INTEGER IH(7)
C     ..
C     .. Local Scalars ..
      INTEGER IR,IM
C     ..
C     .. Local Arrays ..
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/gendata.f
C
C $Id: gendata.f,v 1.6 2021/08/19 10:53:54 andrew Exp $
C
C--- awk generated include file  gendata.h
C---- START of include file gendata.h
C
C     IMG       Partiality indicator. 0 for full reflections, 1 to 100
C                   for partials. Negative for partials at the start of the
C                   rotation range, +ve for partials at the end of the 
C                   rotation. Set in subroutine REEK using DELEPS calculated
C                   in subroutine DSTAR
C
C     IRG       Reflection flag  (Set by SPTEST called from DSTAR)
C               =  0  Spot can be measured
C               =  1  Outside R, X, Y limits
C               =  2  Overlapping spot (set later)
C               =  3  Too wide in phi (more than NWMAX images)
C               =  4  DST .GT. DSTMAX  Not included in final film list -
C                       used only to check for overlaps at edge of film.
C               =  5  Overlapping spot from another lattice
C               = 10  Spot is within cusp, but will be observed...not included
C                     in final spot list but must be included in predicted
C                      pattern
C
C               =  21  Spot present on 2 images, this is 1st
C               =  22  Spot present on 2 images, this is 2nd
C
C               =  31  Spot present on 3 images, this is 1st
C               =  32  Spot present on 3 images, this is 2nd
C               =  33  Spot present on 3 images, this is 3rd
C
C               =  41  Spot present on 4 images, this is 1st
C               =  42  Spot present on 4 images, this is 2nd
C               =  43  Spot present on 3 images, this is 3rd
C               =  44  Spot present on 4 images, this is 4th
C
C                 etc etc
C
C     XG        Virtual detector X coordinate in 10 micron units, relative to
C               an origin at the direct beam position. X is parallel to the
C               Y axis in the laboratory frame, ie orthogonal to the rotation
C               axis.
C
C     YG        Virtual detector Y coordinate in 10 micron units, relative to
C               an origin at the direct beam position. Y is parallel to the
C               Z axis in the laboratory frame, ie  the rotation axis.
C
C     IX,IY     are the coordinates of the reflection in pixels
C               (integers) wrt the first pixel in the image (lower left corner
C               cameramans view). For testing for spot overlap, these
C               coordinates are in 10 micron units. Also used for display
C               pixel coordinates when displaying predicted pattern.
C
C     IREC      Pointer to the record number of a particular spot in the
C               list of generated reflections.
C
C     IRECMULT  Record length of reflection records of generate file is
C               36*IRECMULT bytes. For a single lattice IRECMULT=1, for up
C               to 4 lattices IRECMULT=2.
C
c     NXG,NYG,NCG,NRXG,NRYG Measurement box parameters (for external 
C                           third party integration) written to MTZ
C
C     ILATTG        Lattice number 
C     NLATTOVLP     Number of overlaps from other lattices
C     HKLLATTOVLP   h,k,l indices and lattice number of the overlapping 
C                   spot from another lattice
C         HKLLATTOVLP(h,k,l,lattice_number:record_number:overlap_number)
C     ..
C     .. Arrays in common /GENDATA/ ..
      REAL FRACG,PHIG,PHIWG,XG,YG,GOODFIT,PHIOFFSET
      INTEGER INTG,ISDG,IPRO,ISDPRO,IX,IY,IREC,IRECMULT
      INTEGER*2 IRG,IMG,IGFLAG,IHG,IKG,ILG,IMPARTG,
     +          MISYMG,NXG,NYG,NCG,NRXG,NRYG,ILATTG,HKLLATTOVLP,
     +          NLATTOVLP,IDXOVLP,IDYOVLP
C     .. Scalars in common /GENDATA/ ..
      INTEGER IPACKREC,IPACKHEAD,IRECLAST
C     ..
C     .. Common block /GENDATA/ ..
C
C---- Be sure to preserve order of variables to avoid boundary issues
C     as some are I*2
C
      COMMON /GENDATA/FRACG(NREFLS),PHIG(NREFLS),PHIWG(NREFLS),
     $       XG(NREFLS),YG(NREFLS),GOODFIT(NREFLS),PHIOFFSET(NREFLS),
     $       INTG(NREFLS),ISDG(NREFLS),IPRO(NREFLS),ISDPRO(NREFLS),
     +       IX(NREFLS),IY(NREFLS),
     +       IREC(NREFLS),IPACKREC,IPACKHEAD,IRECLAST,IRECMULT,
     +       IRG(NREFLS),IMG(NREFLS),IGFLAG(NREFLS),
     +       IHG(NREFLS),IKG(NREFLS),ILG(NREFLS),
     +       IMPARTG(NREFLS),MISYMG(NREFLS),NXG(NREFLS),NYG(NREFLS),
     +       NCG(NREFLS),NRXG(NREFLS),NRYG(NREFLS),
     +       ILATTG(NREFLS),HKLLATTOVLP(4,NREFLS,MAXLATT),
     +       NLATTOVLP(NREFLS),IDXOVLP(NREFLS,MAXLATT),
     +       IDYOVLP(NREFLS,MAXLATT)
C     ..
C
C

C&&*&& end_include  ../inc/gendata.f
C     ..
C     .. Equivalences ..
C     ..
      SAVE
C
C---- Extract indices from /GENDATA/
C
      IH(1) = IHG(JREC)
      IH(2) = IKG(JREC)
      IH(3) = ILG(JREC)
C
      IR = IRG(JREC)
      IM = IMG(JREC)
      IH(4) = IM
      IH(5) = IR
      IH(6) = NINT(XG(JREC))
      IH(7) = NINT(YG(JREC))
C
      END
C== GETINDX ==
C
      SUBROUTINE GETINDX(NDISP,IXP,IYP,IHKL,IRECG)
C
C---- Finds indices of reflection at display coordinates IXP,IYP 
C
C     Returns IHKL with h,k,l in 1-3, IM in 4, IR in 5.
C             IRECG is the record number, but -1 if no reflection found
C                   within 4 pixels
C
      IMPLICIT NONE
C     ..
C     .. Scalar Arguments ..
      INTEGER NDISP,IXP,IYP,IRECG
C     ..
C     .. Array Arguments ..
      INTEGER IHKL(5)
C
C&&*&& include  ../inc/parameter.f
C
