     +     Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,DIVH,DIVV,DELAMB,
     +     ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,ISYN,IMONO,
     $     NWMAX,IPAD,
     $     NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS,LOGETA,NUREEK,LCAMCON,
     $     GENGON,FOURCIRCLE,THREECIRCLE,
     +     BLKSIZE,VERTICAL
C     ..
C
C
C&&*&& end_include  ../inc/reeke.f
C     ..
C     .. Equivalences ..
      SAVE
C     ..
C     .. Data ..
C     ..
C
       IF (DEBUG(90)) THEN
         WRITE(IOUT,FMT=1002) ((AMAT(I,J),J=1,3),I=1,3),
     +                 ((TMAT(I,J),J=1,3),I=1,3)
         IF (ONLINE) WRITE(ITOUT,FMT=1002) ((AMAT(I,J),J=1,3),I=1,3),
     +                 ((TMAT(I,J),J=1,3),I=1,3)
 1002    FORMAT(1X,'In GETSPLIT, Current AMAT:',3(/,1x,3f10.4),/,1X,
     +       'TMAT:',3(/,1x,3f10.4))
       END IF    
C
C---- First save the current AMAT 
C
       CALL MATCOPF(SAVAMAT,AMAT,3,3)
C
C---- In case the current UMAT does not match the AMAT passed in, extract
C     UMAT now
C
       IMAT = 1
       IUMAT = 0
       ICELL = 1
       ICHECK = 0
       CALL SETMAT(IMAT,IUMAT,ICELL,ICHECK)
C
C---- Save UMAT
C
       CALL MATCOPF(SAVUMAT,UMAT,3,3)
C
C---- Transfer this UMAT to UMATCURR
C
       CALL MATCOPF(UMATCURR,UMAT,3,3)
C
C---- Now transfer the reference TMAT into AMAT so we can extract its UMAT
C     via a call to SETMAT
C
       CALL MATCOPF(AMAT,TMAT,3,3)
       CALL SETMAT(IMAT,IUMAT,ICELL,ICHECK)
C
C---- Transfer this reference UMAT to UMATREF
C
       CALL MATCOPF(UMATREF,UMAT,3,3)
C
C---- Now have UMATs in UMATCURR and UMATREF, first transfer
C     saved  AMAT and UMAT back into AMAT, UMAT 
C
      CALL MATCOPF(AMAT,SAVAMAT,3,3)
      CALL MATCOPF(UMAT,SAVUMAT,3,3)
C
C---- Now calculate the angle
C
       IF (DEBUG(90)) THEN
         WRITE(IOUT,FMT=1000) ((UMATCURR(I,J),J=1,3),I=1,3),
     +                 ((UMATREF(I,J),J=1,3),I=1,3)
         IF (ONLINE) WRITE(ITOUT,FMT=1000)((UMATCURR(I,J),J=1,3),I=1,3)
     +                 ,((UMATREF(I,J),J=1,3),I=1,3)
 1000    FORMAT(1X,'Current Umatrix 1:',3(/,1x,3f10.4),/,1X,
     +       'Reference Umatrix:',3(/,1x,3f10.4))
       END IF
C
C---- We want R = U2.(U1)-1 where U1 and U2 are the two Umatrices.
C     For rotation matrices (U)-1 = (U)T  (transpose)
C     
      CALL TRNSPM(UMATCURR)
      CALL MATMUL3(WORK,UMATREF,UMATCURR)
      CALL DECMAT(WORK,DIRCOS,KAPPA)
      CALL DECDRC(DIRCOS,KAPPA,POLANG)
      SPLIT = POLANG(3,1)
      RETURN
      END
C
C
      SUBROUTINE DECMAT(AMAT,DIRCOS,KAPPA)
C     ===========================================
C
C Decompose matrix AMAT into Eulerian angles EULANG, direction cosines
C  DIRCOS, angle KAPPA
C
      IMPLICIT NONE
      REAL AMAT(3,3),DIRCOS(3),KAPPA
C
      INTEGER I,J
C
      WRITE(6,60071) ((AMAT(I,J),J=1,3),I=1,3)
60071 FORMAT(' Normalised Matrix:'/3(1X,3F10.5/))
      CALL DCOSFD(AMAT,DIRCOS,KAPPA)
C
      RETURN
      END
C
C
      SUBROUTINE DCOSFD(RSYM,DIRCOS,KAPPA)
C     ===================================
C******************************************************
C       Given a rotation matrix ROTN, expressing a rotation
C       through an angle KAPPA right-handedly about an axis
C       with direction cosines DIRCOS(I),
C       DCOSFD determines DIRCOS() and KAPPA
C       KAPPA is returned in degrees in the range 0 to 180
C
C       Expression for rotation matrix is (see J & J, "Mathl.
C               Phys.", p. 122):-
C
C  cw + n(1)n(1)(1-cw)    n(1)n(2)(1-cw)-n(3)sw  n(1)n(3)(1-cw)+n(3)sw
C  n(1)n(2)(1-cw)+n(3)sw  cw + n(2)n(2)(1-cw)    n(2)n(3)(1-cw)-n(1)sw
C  n(3)n(1)(1-cw)-n(2)sw  n(3)n(2)(1-cw)+n(1)sw  cw + n(3)n(3)(1-cw)
C
C       where cw = cos(KAPPA), sw = sin(KAPPA),
C       & n(1), n(2), n(3) are the direction cosines.
C
C*******************************************************}
C
      IMPLICIT NONE
      DOUBLE PRECISION PI
      PARAMETER (PI=3.141592653589793D00)
        REAL RSYM(3,3),DIRCOS(3),UNIT(3,3),DEL(3),S(3),P(3),D(3)
        REAL OMEGA,PHI,KAPPA,OM,PH,KP,OM1,PH1,KP1,OM2,PH2,KP2
      REAL DIFF,TRACE,R2,R3,SINKAP,COSKAP
        INTEGER NS(3),NP(3),NCS(3),ND(3),KNTRL,J,JMX
        LOGICAL SAME,DCSET
C
C
          DIFF=1.0E-04
          KNTRL=0
C       Trace = 1 + 2.cos w
          TRACE=RSYM(1,1)+RSYM(2,2)+RSYM(3,3)
C       S(1)=2.n(1).sin w
C       S(2)=2.n(2).sin w
C       S(3)=2.n(3).sin w
          S(1)=RSYM(3,2)-RSYM(2,3)
          S(2)=RSYM(1,3)-RSYM(3,1)
          S(3)=RSYM(2,1)-RSYM(1,2)
          CALL ORDR3(KNTRL,S,NS)
C--Is biggest S() zero (i.e. is sin w = 0)?
          IF (ABS(S(NS(1))).GT.DIFF) THEN
            R2=S(NS(2))/S(NS(1))
            R3=S(NS(3))/S(NS(1))
            DIRCOS(NS(1))=1.0/SQRT(1 + R2**2 + R3**2)
            DIRCOS(NS(2))=R2*DIRCOS(NS(1))
            DIRCOS(NS(3))=R3*DIRCOS(NS(1))
            GO TO 123
          END IF
C--Calculation when sin w = 0 (esp. when w = 180').
C       P(1)=n(2).n(3).{0(W=0)or2(w=180)}
C       P(2)=n(3).n(1).{0(W=0)or2(w=180)}
C       P(3)=n(1).n(2).{0(W=0)or2(w=180)}
          P(1)=RSYM(3,2)
          P(2)=RSYM(1,3)
          P(3)=RSYM(2,1)
          CALL ORDR3(KNTRL,P,NP)
C--Is biggest P() zero (i.e. are all off-diag. terms zero)?
          IF (ABS(P(NP(1))).LT.DIFF) THEN
            IF (TRACE.GT.0.0) THEN
C--Matrix is unit matrix.
                KAPPA=0.0
                DIRCOS(1)=0.0
                DIRCOS(2)=0.0
                DIRCOS(3)=1.0
                RETURN
            END IF
C
C---- Trace -ve, so dyad about x,y or z.
C           
            KAPPA=180.0
C
C
            DO 40 J=1,3
 40           D(J)=RSYM(J,J)+1.0
            CALL ORDR3(KNTRL,D,ND)
            DIRCOS(ND(1))=1.0
            DIRCOS(ND(2))=0.0
            DIRCOS(ND(3))=0.0
            RETURN
          END IF
        IF (ABS(P(NP(2))).LT.DIFF) THEN
C--One d.c. is zero.
          DIRCOS(NP(1))=0.0
          DIRCOS(NP(2))=SQRT(MAX(.5+.5*RSYM(NP(2),NP(2)),0.))
          DIRCOS(NP(3))=SQRT(MAX(.5+.5*RSYM(NP(3),NP(3)),0.))
          IF (P(NP(1)).LT.0.0) DIRCOS(NP(2))=-DIRCOS(NP(2))
          GO TO 123
        END IF
C--All d.c's are nonzero.
C       R2=n(NP(1))/n(NP(2))
C       R3=n(NP(1))/n(NP(3))
          R2=P(NP(2))/P(NP(1))
          R3=P(NP(3))/P(NP(1))
          DIRCOS(NP(2))=1.0/SQRT(1 + R2**2 + (R2/R3)**2)
          DIRCOS(NP(3))=1.0/SQRT(1 + R3**2 + (R3/R2)**2)
          DIRCOS(NP(1))=SQRT(1.0-DIRCOS(NP(2))**2-DIRCOS(NP(3))**2)
C--Adjust signs of DIRCOS().
          JMX=0
          DO 20 J=1,3
            IF (P(J).GT.0.0) THEN
              IF (JMX.GT.0) JMX=-1
              IF (JMX.EQ.0) JMX=J
            END IF
 20       CONTINUE
          IF (JMX.GT.0) DIRCOS(JMX)=-DIRCOS(JMX)
          IF (JMX.EQ.0) WRITE(*,1358)
 1358     FORMAT(' All P()s. are negative or zero')
C
C---- Given d.c's, calculate KAPPA.
C
123       KNTRL=1
          CALL ORDR3(KNTRL,DIRCOS,NCS)
C
C----  Find KAPPA.
C
          SINKAP=RSYM(NCS(3),NCS(2))-RSYM(NCS(2),NCS(3))
          SINKAP=0.5*SINKAP/DIRCOS(NCS(1))
          COSKAP=0.5*(TRACE-1.0)
          KAPPA=ATAN2(SINKAP,COSKAP)
          KAPPA=KAPPA*( REAL (180.0D00/PI) )
C
C----  If kappa negative, negate kappa and invert DIRCOS
C
          IF (KAPPA .LT. 0.0) THEN
             KAPPA = -KAPPA
             DIRCOS(1) = -DIRCOS(1)
             DIRCOS(2) = -DIRCOS(2)
             DIRCOS(3) = -DIRCOS(3)
          ENDIF
        RETURN
        END
C
      SUBROUTINE ORDR3(KNTRL,Q,NQ)
C
C*************************************************************
C       Find NQ(1) so that |Q(NQ(1)| is biggest Q.
C       If KNTRL=1, make NQ(1),NQ(2),NQ(3) a positive permutn.
C       If KNTRL= anything else,
C       find nos. NQ() so that|Q(NQ(1)|>|Q(NQ(2))|>|Q(NQ(3))|
C
C*************************************************************
      IMPLICIT NONE
        REAL Q(3)
        INTEGER NQ(3),KNTRL,J
C
C       Find no. NQ(1) of Q() with largest |Q()|.
          NQ(1)=1
          IF (ABS(Q(2)).GT.ABS(Q(1))) NQ(1)=2
          IF (ABS(Q(3)).GT.ABS(Q(NQ(1)))) NQ(1)=3
C       Find nos. for other two Q()'s & order so |Q(NQ(2))|>|Q(NQ(3))|
          NQ(2)=MOD(NQ(1),3)+1
          NQ(3)=MOD(NQ(2),3)+1
          IF (KNTRL.EQ.1) GO TO 100
            IF (ABS(Q(NQ(3))).GT.ABS(Q(NQ(2)))) THEN
                J=NQ(3)
                NQ(3)=NQ(2)
                NQ(2)=J
            END IF
 100    RETURN
        END
      SUBROUTINE DECDRC(DIRCOS,KAPPA,POLANG)
C     ===========================================
C
C  Print DIRCOS, KAPPA as polar angles, also with permutation
C
      IMPLICIT NONE
      REAL DIRCOS(3),KAPPA,POLANG(3,2)
C
      REAL V(3)
C
      CALL GETANGLES(DIRCOS,KAPPA,
     .   POLANG(1,1),POLANG(2,1),POLANG(3,1),
     .   POLANG(1,2),POLANG(2,2),POLANG(3,2))
CAL      WRITE(6,60060) DIRCOS,POLANG
60060 FORMAT(' Direction cosines : ',3F9.5/
     .  ' Polar angles  omega, phi, kappa = ',3F8.2/
     .  '                 or                ',3F8.2)
C Now permuted to crystal orthogonal frame
CAL      CALL MATVEC(V,PERM,DIRCOS)
CAL      CALL GETANGLES(V,KAPPA,
CAL     .   POLANG(1,1),POLANG(2,1),POLANG(3,1),
CAL     .   POLANG(1,2),POLANG(2,2),POLANG(3,2))
CAL      WRITE(6,60061) V,POLANG
CAL60061 FORMAT(' Permuted direction cosines : ',3F9.5/
CAL     .  ' Polar angles  omega, phi, kappa = ',3F8.2/
CAL     .  '                 or                ',3F8.2)
      RETURN
      END
C
C
C
      SUBROUTINE GETANGLES(DIRCOS,KAPPA,OM1,PH1,KP1,OM2,PH2,KP2)
C     ==========================================================
C
C--Calculate polar angles from d.c.'s, for +/- d.c.'s
C       (i.e. rotn. axis pointing both directions).
C
C Input:
C   DIRCOS(3)    direction cosines
C   KAPPA        angle (degrees)
C
C Output:
C   OM1,PH1,KP1  polar angles, positive direction cosine (degrees)
C   OM2,PH2,KP2  polar angles, negative direction cosine
C
C
C***************************************************************
      IMPLICIT NONE
      REAL SINA1,COSA1,SINB1,COSB1,SING1,COSG1
        REAL DIRCOS(3)
        REAL OMEGA,PHI,KAPPA,OM,PH,KP,OM1,PH1,KP1,OM2,PH2,KP2,PI
      REAL DIFF,SOM
      INTEGER K,L
C
	DIFF=1.0E-04
        PI=4.*ATAN(1.)
        KP1=KAPPA
      KAPPA=KAPPA*PI/180.0
C
        DO 300 L=1,2
          DO 240 K=1,3
            DIRCOS(K)=-DIRCOS(K)
 240      CONTINUE
C       If axis directn. reversed, rotn. angle must chge sign.
          KAPPA=-KAPPA
C       Test if cos(OMEGA) is v. small
          IF (ABS(DIRCOS(3)).GE.DIFF) GO TO 250
C       Z-component v. small
            OM=0.5*PI-DIRCOS(3)
            GO TO 260
 250      SOM=SQRT(DIRCOS(1)**2+DIRCOS(2)**2)
          OM=ABS(ATAN2(SOM,DIRCOS(3)))
C--Find phi.
 260      CONTINUE
          IF ((OM.GT.DIFF).AND.((PI-OM).GT.DIFF))  GO TO 270
C       When OMEGA nr. zero or 180', phi is indeterminate.
            PH=0.0
            GO TO 290
 270      IF (ABS(DIRCOS(1)).GE.DIFF) GO TO 280
C       Cos(phi) v. small
            PH=0.5*PI-(DIRCOS(1)/SIN(OM))
            GO TO 290
 280      PH=ATAN2(DIRCOS(2),DIRCOS(1))
C       Setting 2 groups of possible angles OM,PH,KP
 290      CONTINUE
C          IF (PH.LT.0.0) PH=2.0*PI+PH
          IF (L.EQ.1) OM1=OM
          IF (L.EQ.1) PH1=PH
          IF (L.EQ.1) KP1=KAPPA
C          IF (KP1.LT.0.0) KP1=2.0*PI+KP1
          IF (L.EQ.2) OM2=OM
          IF (L.EQ.2) PH2=PH
          IF (L.EQ.2) KP2=KAPPA
C          IF (KP2.LT.0.0) KP2=2.0*PI+KP2
 300    CONTINUE
 400    CONTINUE
          OM1=OM1*180.0/PI
          PH1=PH1*180.0/PI
          KP1=KP1*180.0/PI
C          IF (KP1.LT.0.0) KP1=360.0+KP1
          OM2=OM2*180.0/PI
          PH2=PH2*180.0/PI
          KP2=KP2*180.0/PI
C          IF (KP2.LT.0.0) KP2=360.0+KP2
          KAPPA=KAPPA*180.0/PI
        RETURN
        END
C
      SUBROUTINE TRNSPM(A)
C       ====================
C
C       TRANSPOSE A 3X3 MATRIX
C
C       A=AT
C
C
      IMPLICIT NONE
      REAL A(3,3),C
      INTEGER I,J
C
      DO 1 I=1,3
      DO 1 J=I,3
      C=A(I,J)
      A(I,J)=A(J,I)
      A(J,I)=C
1     CONTINUE
      RETURN
      END
C
C
C---- $Id: getspots.f,v 1.26 2018/05/09 14:50:18 andrew Exp $
C
C== GETSPOTS ==
      SUBROUTINE GETSPOTS(MODE,ID,COUNT,LPRNT,BOXOPEN2,IREVERSE,IERR)
      IMPLICIT NONE
C
C
C     MODE   = 0  Determine background and find spots.
C            = 1  Don't repeat background determination, just reset using
C                 new threshold
C            = 2  Don't repeat spot search, just apply new limits
C            = 10 Prelim search to determine best threshold for
C                 subsequent spot search
C            = 20 Prelim search to determine best threshold, separation
C                 and raster box size, do not go on to search for spots
C                 on whole image.
C            = 30 Used when getting separation and raster box params 
C                 using supplied threshold. Only find spots in central
C                 area.
C
C
C     ID          Image number
C
C     LPRNT  = TRUE   Print radial background and stats on found spots
C              FALSE  No printing
C
C     IREVERSE    Set in SUMIMG to -1 if preceeding images have been summed
C                 for spot finding, because image specified was the last image.
C                 This affects calculation of the phi value for the summed images.
C
C     IERR        Error flag (returned)
C            = 0      No error
C            > 0  Error in background determination in stripe IERR
C            = -1 Not enough spots found to determine raster and
C                 separation parameters. (Only set when MODE=20)
C            = -2 Too many spots found (threshold too low)
C            = -3 Too many spots to store
C            = -4 No spots found at all
C            = -5 too many cycles of changing threshold 
C            = -6 calling mode > 20. Not sure this is right, because 
C                 mode = 30 is valid (vide supra)
C
C
C
C****** DEBUG(81) FOR THIS SUBROUTINE ******
C

C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
