c-harvest
      SAVE
C     ..
C     .. Data statements ..
      DATA (LABOUT(J),J=1,MCOLSTR)/'H','K','L','BATCH','PHI','IC'/
      DATA (CTYPEO(J),J=1,MCOLSTR)/'H','H','H','B','R','I'/   
C     ..                            
C
      MTZOUT = 1
C
C          ***********************************************
      IF(LENSTR(MTZDIR).GT.0)THEN
        MTZFILE = MTZDIR(1:LENSTR(MTZDIR))//MTZNAM(1:LENSTR(MTZNAM))
      ELSE
        MTZFILE = MTZNAM(1:LENSTR(MTZNAM))
      ENDIF
      CALL LWOPEN(MTZOUT,MTZFILE(1:LENSTR(MTZFILE)))
      IF(LBEST.AND..NOT.BESTOPEN)THEN
        CALL CCPOPN(-BESTHKL,BSTHKL,1,1,80,IFAIL)
        BESTOPEN = .TRUE.
      ENDIF
      CALL LWTITL(MTZOUT,GTITLE,0)
      CALL LWCELL(MTZOUT,CELL)
c-harvest
c-old      CALL LWCLAB(MTZOUT,LABOUT,MCOLSTR,CTYPEO,0)
C
C---- Store the project name and dataset name in the mtz header:
C     Subroutine to add dataset information to the output MTZ file header.
C     Datasets identified by the PROTEIN_NAME/DATASET_NAME pair are 
C     appended to the MTZ header one at a time.
C     Checks to see if the PROTEIN_NAME/DATASET_NAME pair is already
C     included; if so, the dataset is not appended.
C     Redundant datasets are removed in LWCLOS.
C
chrp18102000      CALL LWID(MTZOUT,PROJECTNAME,DATASETNAME)
CVER5 CALL LWIDC(MTZOUT,PROJECTNAME,DATASETNAME,CELL,WAVE)
C - uncomment after CCP4 v5.0 - comment out previous line
CVER4 CALL LWIDX(MTZOUT,PROJECTNAME,CRYSTALNAME,DATASETNAME,CELL,WAVE)
      CALL LWCLAB(MTZOUT,LABOUT,MCOLSTR,CTYPEO,0)
C
C---- Subroutine to associate dataset entry with each column for
C     the output MTZ file. 
C
CVER5      CALL LWIDAS(MTZOUT,MCOLSTR,PNAME_COLS,DNAME_COLS,0)
C - uncomment after CCP4 v5.0 - comment out previous line
CMDW Do not use. Batches are assigned to datasets but not columns.
CMDW      CALL LWIDASX(MTZOUT,MCOLSTR,XNAME_COLS,DNAME_COLS,0)
c-harvest
c
      LATTYP = SPGNAM(1:1)
      CALL LWSYMM(MTZOUT,NSYM,NSYMP,RSYM,LATTYP,NUMSPG,SPGNAM,
     +                  PGNAME)
C
C---- Need EPSILON for unique option
C
      IPRINT = 0
      CALL EPSLN(NSYM,NSYMP,RSYM,IPRINT)
      CALL CENTRIC(NSYM,RSYM,IPRINT)
C          ***********************************************
C
C---- DNA stuff from Graeme
      call dna_output_table_start('integration_output')
      call dna_output_list_start('output_files')
      call dna_output_character_item('hklout', mtznam(1:lenstr(mtznam)))
      call dna_output_list_end
      call dna_output_table_end

      RETURN
      END
