      INTEGER NSIZE
C
C     ..
C     .. Array Arguments ..
      INTEGER NHIST(50),NPKSHIST(50)
C     ..
C     .. Local Scalars ..
      REAL X
      INTEGER I,J,NPEAK,NMULT,NSING,NCUT,IBEST
C     ..
C     .. Local Arrays ..
      INTEGER IPK(50)
      REAL PROF(5),SCORE(50)
C     ..
C     .. External Functions ..
C     ..
C     .. External Subroutines ..
C     ..
C     .. Intrinsic Functions ..
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/ioo.f
C
