C&&*&& end_include  ../inc/ioo.f
C&&*&& include  ../inc/debug.f
C
C $Id: debug.f,v 1.8 2021/06/03 09:41:34 andrew Exp $
C
C--- awk generated include file  debug.h
C---- START of include file debug.h
C
C
C
C     .. Arrays in common /DEBUG/ ..
      REAL XWARN
      INTEGER NDEBUG,IWARN,IARRDUMP
      LOGICAL DEBUG,LPRINT,DUMP,WARN
C
C     .. Scalars in common /DEBUG/ ..
      REAL BGRLIM
      INTEGER NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,IERRLEVEL
      LOGICAL SPOT
      CHARACTER MESSAGE*512
C     
C     ..
C     .. Common Block /DEBUG/..
      COMMON /DEBUG/XWARN(MAXIWARN,100),BGRLIM,NDEBUG(200),
     +       IWARN(MAXIWARN,100),
     $       NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,DEBUG(200),LPRINT(20),
     +       DUMP(30),WARN(100),SPOT,IARRDUMP(30),IERRLEVEL

      COMMON /CDEBUG/ MESSAGE
C     ..
C
C&&*&& end_include  ../inc/debug.f
C     ..
C     .. Equivalences ..
      SAVE
C     ..
C     .. Data ..
      DATA PROF /0.2,0.4,1.0,0.4,0.2/
C     ..
      NSING = NPKSHIST(1)
      NMULT = NPKSHIST(2)
      SCORE(1) = 0
      SCORE (2) = PROF(3)*NHIST(2) + 
     +            PROF(4)*NHIST(3) + PROF(5)*NHIST(4)
      SCORE(49) = PROF(1)*NHIST(48) + 
     $     PROF(2)*NHIST(49) + PROF(3)*NHIST(50)
      SCORE(50) = PROF(1)*NHIST(49) + 
     $     PROF(2)*NHIST(50)
C
C---- First, calculate weighted sums for each bin of histogram
C     Must never use NHIST(1) as these are probably spurious spots
C     and there can be a very large number of them.
C
      DO 10 I = 3,48
        X = 0.0
        DO 20 J = 1,5
          IF ((I-3+J.EQ.1)) GOTO 20
          X = X + PROF(J)*NHIST(I-3+J)
 20     CONTINUE
        SCORE(I) = X
        NMULT = NMULT + NPKSHIST(I)
 10   CONTINUE
C
C---- Now find the local maxima in SCORE. At present, assume that
C     distinct maxima have to be 3 or more pixels apart
C
      NPEAK = 0
      DO 30 I = 2,49
        IF ((SCORE(I).GE.SCORE(I-1)).AND.(SCORE(I).GE.SCORE(I+1))) THEN
C
C---- check next score
C
          IF (I.LT.49)THEN
            IF(SCORE(I).GT.SCORE(I+2)) THEN
C
C---- Local peak found, store it
C
              NPEAK = NPEAK + 1
              IPK(NPEAK) = I
            END IF
          ENDIF
        END IF
 30   CONTINUE
C
C---- Now decide if the first or second peak should be used. If there are more
C     than 20% of spots with 2 or more peaks, use first bin, otherwise second. 
C     This is based on assumption that for unresolved spots, where we want
C     to take the first peak, there will be a reasonable fraction of spots
C     which are made up of multiple peaks. The fraction used (0.2) has to be
C     verified.
C
      IF (NPEAK.GT.1) THEN
        NCUT = 0.2*NSING
        IF (NMULT.GT.NCUT) THEN
C
C---- A lot of multiple peaks, probably unresolved spots, choose first peak
C
          IBEST = 1
        ELSE
C
C---- Need to check that second peak is well populated before choosing it
C
          IF (SCORE(IPK(2)).GT.0.5*SCORE(IPK(1))) THEN
            IBEST = 2
          ELSE
            IBEST = 1
          END IF
        END IF
      ELSE
        IBEST = 1
      END IF
C
      NSIZE =  IPK(IBEST)
C
C---- Use debug flag for PICKSPOTS here
C
      IF (DEBUG(62)) THEN
        WRITE(IOUT,FMT=6000) (SCORE(I),I=1,30), NPEAK, IBEST,
     +               (IPK(I),I=1,NPEAK)
        IF (ONLINE) WRITE(ITOUT,FMT=6000) (SCORE(I),I=1,30), NPEAK,
     +                IBEST, (IPK(I),I=1,NPEAK)
      END IF
 6000 FORMAT(/,' Debug from histo.f',/,
     $     1x,'Scores',/,3(1x,10F6.0/),/,1X,'number of peaks',I3,
     +       ', peak chosen is number',I3,' list of peak bins:',/,
     +       (1x,10I5))
      RETURN
      END
