     +     BLKSIZE
      INTEGER ISYN,IMONO,NWMAX,IPAD,NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS
C     ..
C     .. logicals in common block /REEKE/ ..
      LOGICAL LOGETA,NUREEK,LCAMCON,GENGON,FOURCIRCLE,THREECIRCLE,
     +        VERTICAL
C     ..
C     .. Common Block /REEKE/ ..
      COMMON /REEKE/RMC(3,3),AMAT(3,3),SCAXIS(3),S0(3),s0unit(3),
     $     CAMCON(8),BEAMMU(2),X1,X2,Y1,Y2,
     +     Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,DIVH,DIVV,DELAMB,
     +     ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,ISYN,IMONO,
     $     NWMAX,IPAD,
     $     NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS,LOGETA,NUREEK,LCAMCON,
     $     GENGON,FOURCIRCLE,THREECIRCLE,
     +     BLKSIZE,VERTICAL
C     ..
C
C
C&&*&& end_include  ../inc/reeke.f
C     ..
C     .. Save statement ..
      SAVE
C     ..
C
C
      IF (NLAUE.LT.1 .OR. NLAUE.GT.16) GO TO 10
C
C---- otherwise set them from resolution command
C
C  Note this IS CORRECT !
      DMAX = WAVE/DSTMAX
      IF (DEBUG(54)) THEN
        WRITE(IOUT,FMT=6000) DMAX,WAVE,DSTMAX
        IF (ONLINE) WRITE(ITOUT,FMT=6000) DMAX,WAVE,DSTMAX
 6000   FORMAT(1X,'DMAX=',F6.3,' WAVE=',F8.5,' DSTMAX=',F8.6)
      END IF
C
      HMAX = INT(CELL(1)/DMAX)
      KMAX = INT(CELL(2)/DMAX)
      LMAX = INT(CELL(3)/DMAX)
C
      HMIN = 0
      KMIN = 0
      LMIN = 0
C
C
      IF (NLAUE.EQ.1) THEN
C
C---- LAUE = 1, 1bar,  hkl:h>=0   0kl:k>=0   00l:l>=0
C*C Not used by ASUSET
C
        KMIN = -KMAX
        LMIN = -LMAX
        RETURN
C
C---- LAUE = 2, 1bar,  hkl:k>=0   h0l:l>=0   h00:h>=0
C*C Not used by ASUSET
C
      ELSE IF (NLAUE.EQ.2) THEN
        HMIN = -HMAX
        LMIN = -LMAX
        RETURN
C
C---- LAUE = 3, 1bar,  hkl:l>=0   hk0:h>=0   0k0:k>=0
C
      ELSE IF (NLAUE.EQ.3) THEN
        HMIN = -HMAX
        KMIN = -KMAX
        RETURN
C
C---- LAUE = 4, 2/m,   hkl:k>=0, l>=0     hk0:h>=0
C
      ELSE IF (NLAUE.EQ.4) THEN
        HMIN = -HMAX
        RETURN
C
C---- LAUE = 5, 2/m,   hkl:h>=0, l>=0     0kl:k>=0   (2-nd sett.)
C*C Not used by ASUSET
C
      ELSE IF (NLAUE.EQ.5) THEN
        KMIN = -KMAX
        RETURN
C
C---- LAUE = 6, mmm,   hkl:h>=0, k>=0, l>=0
C
      ELSE IF (NLAUE.EQ.6) THEN
        RETURN
C
C---- LAUE = 7, 4/m,   hkl:h>=0, k>0, l>=0 with  k>=0 for h=0
C
      ELSE IF (NLAUE.EQ.7) THEN
        RETURN
C
C---- LAUE = 8, 4/mmm,   hkl:h>=0, h>=k>=0, l>=0
C
      ELSE IF (NLAUE.EQ.8) THEN
        RETURN
C
C---- LAUE = 9, 3bar,   hkl:h>=0, k>0  including  00l:l>0
C
      ELSE IF (NLAUE.EQ.9) THEN
        KMAX = HMAX
        LMIN = -LMAX
C*** This is wrong !
CAL       KMIN = 1

        RETURN
C
C---- LAUE = 10, 312,    hkl:h>=0, k>=0 with k<=h  and l>=0 if h = 0
C
      ELSE IF (NLAUE.EQ.10) THEN
        KMAX = HMAX
        LMIN = -LMAX
        RETURN
C
C---- LAUE = 11, 321,    hkl:h>=0, k>=0 with k<=h  and l>=0 if h = k
C
      ELSE IF (NLAUE.EQ.11) THEN
        KMAX = HMAX
        LMIN = -LMAX
        RETURN
C
C---- LAUE = 12, 6/m,   hkl:h>=0, k>0, l>=0  with  k>=0 for h=0
C
      ELSE IF (NLAUE.EQ.12) THEN
        KMAX = HMAX
        RETURN
C
C---- LAUE = 13, 6/mmm,   hkl:h>=0, h>=k>=0, l>=0
C
      ELSE IF (NLAUE.EQ.13) THEN
        KMAX = HMAX
        RETURN
C
C---- LAUE = 14, m3,  hkl:h>=0, k>=0, l>=0 with l>=h, k>=h for l=h
C                                                and  k>h for l>h
C
      ELSE IF (NLAUE.EQ.14) THEN
        RETURN
C
C---- LAUE = 15, m3m,   hkl:k>=l>=h>=0
C
      ELSE IF (NLAUE.EQ.15) THEN
        RETURN
C
C---- LAUE = 16, m3m,   hkl:h>=k>=l>=0
C*C Not used by ASUSET
C
      ELSE IF (NLAUE.EQ.16) THEN
        RETURN
      END IF
C
C
   10 WRITE (IOUT,FMT=6010) NLAUE
      IF (ONLINE) WRITE (ITOUT,FMT=6010) NLAUE
 6010 FORMAT (//1X,'**** WRONG LAUE GROUP = ',I6,' ****',/)
      STOP
C
      END
C
C     $Id: hough.f,v 1.4 2011/07/08 11:55:30 harry Exp $
      SUBROUTINE HOUGH(ARM,houghlines,NPOINTS,NLINESFOUND)
      IMPLICIT NONE
C
C     takes an image reduced to edges by Canny, etc, then applies a
C     Hough transform to identify straight edges.
C      
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     ..
C     .. Scalar arguments

      Integer NPOINTS,NLINESFOUND
C     ..
C     .. parameters
      Integer SIZEX,SIZEY,HOUGHSIZE
      PARAMETER (SIZEX=1024)
      PARAMETER (SIZEY=1024)
      PARAMETER (HOUGHSIZE=4096)
C     ..
C     .. Array arguments
      Integer arm(3,64*sizex),sortval(64*sizex)
      Real houghlines(2,maxexcl*4),adistance(64*sizex)
C     ..
C     .. Local scalars
      Real RIC,RJC,RKC,Radius,Theta,Mean,distavg,distrms,distance
      Integer IC,JC,KC,LC,Idistance,IRadius,ITheta,IJ,ILINES,
     $     ITHETAMIN,ITHETAMAX,IRADIUSMIN,IRADIUSMAX,HOUGHMIN,
     $     HOUGHCNT,imean,isum,distdiv,IPOINTS
      Character*80 Smoothfile
      Logical ADDED
C     ..
C     .. Local arrays
      INTEGER HOUGHARRAY(HOUGHSIZE,360),LINES(MAXEXCL*4,4),
     $     histogram(10),localarmval(64*SIZEX),linesfound(maxexcl)
      INTEGER*2 HOUGHARRAY2(HOUGHsize,360)
C     ..
C     .. includes
C&&*&& include  ../inc/debug.f
C
C $Id: debug.f,v 1.8 2021/06/03 09:41:34 andrew Exp $
C
C--- awk generated include file  debug.h
C---- START of include file debug.h
C
C
C
C     .. Arrays in common /DEBUG/ ..
      REAL XWARN
      INTEGER NDEBUG,IWARN,IARRDUMP
      LOGICAL DEBUG,LPRINT,DUMP,WARN
C
C     .. Scalars in common /DEBUG/ ..
      REAL BGRLIM
      INTEGER NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,IERRLEVEL
      LOGICAL SPOT
      CHARACTER MESSAGE*512
C     
C     ..
C     .. Common Block /DEBUG/..
      COMMON /DEBUG/XWARN(MAXIWARN,100),BGRLIM,NDEBUG(200),
     +       IWARN(MAXIWARN,100),
     $       NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,DEBUG(200),LPRINT(20),
     +       DUMP(30),WARN(100),SPOT,IARRDUMP(30),IERRLEVEL

      COMMON /CDEBUG/ MESSAGE
C     ..
C
C&&*&& end_include  ../inc/debug.f
C&&*&& include  ../inc/dsplyc.f
C
C $Id: dsplyc.f,v 1.7 2015/05/27 10:36:13 harry Exp $
C
C--- awk generated include file  dsplyc.h
C---- START of include file dsplyc.h
C
C*******************************************************************
C
C  COMMON  /DSPLYC/
C
C       IMGLOW, IMGHI   low & high values of 16-bit image for scaling
C                       integer*2 to byte: IMGLOW maps to  0; 
C                       IMGHI to maximum. Note that these are not
C                       necessarily the actual limits of the data
C       IMGMAX          maximum value recorded on the image. Necessary for 
C                       iMosflm.
C       IMGMIN          Minimum value recorded on image - gaps on PADs, 
C                       necessary for iMosflm
C       JDSPWD          .LT. 0  before image window has been created
C                       = +-1 for image display that can be panned
C                       = +-2 for non-interactive image display
C       MAXDEN          highest level in colour table to fill up to
C                       must be less than ~240 - number of overlay colours
C       LDSPSG          if .true., treat image as signed, ie after dark
C                          subtraction
C                       if .false., treat image as unsigned
C       NZOOM           zoom factor for image, = 0 if no zoom
C       JYZOOM, JZZOOM  1st pixel in zoomed image
C
C----   WINOPEN Flag for whether or not window is open. Do not
C               confuse with DISPMENU (/CONDATA/)which is true if the run was
C               started with a IMAGE keyword.
C
C
C       CDSPTL          banner title
C
      REAL FTOTAL,AVERAG,IMAGERMS
      INTEGER IMGLOW, IMGHI, IMGMAX,IMGMIN,JDSPWD, MAXDEN,
     $     NZOOM, JYZOOM, JZZOOM
      INTEGER PIXEL_INTENSITIES(514)
      LOGICAL LDSPSG,WINOPEN,LPAUSE,LHELP
      COMMON /DSPLYC/ FTOTAL,AVERAG,IMAGERMS,IMGLOW, IMGHI, IMGMAX,
     *     IMGMIN,JDSPWD,MAXDEN, NZOOM, JYZOOM, JZZOOM, 
     $     PIXEL_INTENSITIES,LDSPSG,WINOPEN,LPAUSE,LHELP
C
      CHARACTER  CDSPTL*200,SHORTFN*200
      COMMON /DSPLCC/  CDSPTL,SHORTFN
C                                                           
C
C*******************************************************************


C&&*&& end_include  ../inc/dsplyc.f
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C     ..
C     .. External subroutines
      EXTERNAL WRITEFILE

C     ..
C     .. initialise LOCALARMVAL
      DO 100 IC = 1,64*SIZEX
        LOCALARMVAL(IC) = 0
 100  ENDDO
C     .. zero HOUGHARRAY array
      DO 130 JC = 1,HOUGHSIZE
        DO 120 IC = 1,360
          HOUGHARRAY(JC,IC) = 0
          HOUGHARRAY2(JC,IC) = 0
 120    ENDDO
 130  ENDDO
C     ..
C     .. loop through points in ARM
      Ithetamin = 360
      ITHETAMAX = 0
      IRADIUSMIN = 99999
      IRADIUSMAX = 0
      IJ = NPOINTS
      DO 160 IC=1,NPOINTS
        RIC = REAL(ARM(1,IC))
        RJC = REAL(ARM(2,IC))
        IF(ARM(3,IC).NE.0)THEN
            DO 140 Itheta = 1,360
              DO 135 KC = -1,0,1
              Theta = REAL(Itheta+KC) * DTOR * 0.5
              Radius = RIC * COS(Theta) + RJC * SIN(Theta)
              Iradius = INT(Radius) + (SIZEX + 1)
              IRADIUSMIN = MIN(IRADIUSMIN,IRADIUS)
              IRADIUSMAX = MAX(IRADIUSMAX,IRADIUS)
              ITHETAMAX = MAX(ITHETAMAX,ITHETA)
              ITHETAMIN = MIN(ITHETAMIN,ITHETA)
c              print*,'iradius = ',iradius
c              print*,IRADIUS,ITHETA
              HOUGHARRAY(IRADIUS,ITHETA) = 
     $             HOUGHARRAY(IRADIUS,ITHETA) + 1
              HOUGHARRAY2(IRADIUS,ITHETA) = 
     $             HOUGHARRAY2(IRADIUS,ITHETA) + 1
 135        enddo
 140        ENDDO
c            stop
          ENDIF
 160  ENDDO
      IF(DEBUG(80))THEN
        print*,'number of points contributing to lines: ',ij
        PRINT*,'Iradius (min, max) = ',iradiusmin,iradiusmax
        PRINT*,'Itheta (min, max) = ',ithetamin,ithetamax
      ENDIF
      Smoothfile = 'hough_001.img'
      IF(debug(80).and.ndebug(80).ne.0)
     $     CALL WRITEFILE(SMOOTHFILE,HOUGHARRAY2,1,1,HOUGHSIZE,360)
C
C---- go through Hough transform and find maxima - we can have a maximum
C     of MAXEXCL (see ../inc/parameter.f) quadrilaterals, so 4*MAXEXCL 
C     peaks to find 
C
C
C---- initialize LINES
C
      DO 280 IC=1,4*MAXEXCL
        LINES(IC,1) = 0
        LINES(IC,2) = 0
        LINES(IC,3) = 0
        LINES(IC,4) = 0
 280  enddo
      DO 285 IC=1,MAXEXCL
        LINESFOUND(IC) = 0
 285  enddo
      KC = 0
      LC = 0
      ILINES = 1
      HOUGHMIN = 0
      HOUGHCNT = 0
      isum = 0
      imean = 0
      DO 300 JC = 1,360
        DO 290 IC = 1,HOUGHSIZE
          IF(HOUGHARRAY(IC,JC).GT.HOUGHMIN)THEN
            isum = isum + 1
            imean = imean + hougharray(ic,jc)
            HOUGHCNT = MIN(MAXEXCL*4,HOUGHCNT + 1)
            HOUGHMIN = LINES(HOUGHCNT,1)
            ADDED = .FALSE.
            DO 310 KC = 1,HOUGHCNT
              IF(HOUGHARRAY(IC,JC).GT.LINES(KC,1).AND..NOT.ADDED)THEN
C
C---- shuffle down following entries
C
                DO 320 LC = HOUGHCNT,KC+1,-1
                  LINES(LC,1) = LINES(LC-1,1)
                  LINES(LC,2) = LINES(LC-1,2)
                  LINES(LC,3) = LINES(LC-1,3)
 320            ENDDO
                LINES(KC,1) = HOUGHARRAY(IC,JC)
                LINES(KC,2) = IC
                LINES(KC,3) = JC
                ADDED = .TRUE.
              ENDIF
 310        ENDDO
          ENDIF
 290    ENDDO
 300  ENDDO
      imean = imean/(isum + 1)
      IF(DEBUG(80))THEN
        print*,'mean value of ',isum,' non-zero points = ',imean
      ENDIF
C
C---- go through top HOUGHCNT points to pick out the maxima; it's 
C     conceivable that we have maxima separated by a single pixel, but
C     it should be okay to consider adjacent pixels as belonging to the 
C     same peak
C
      HOUGHMIN = HOUGHCNT
      DO 500 IC = 1,HOUGHCNT
        LINES(IC,4) = 1
        DO 510 JC=-1,1,1
          DO 520 KC=-1,1,1
            IF((LINES(IC,2)+JC.Gt.0.AND.LINES(IC,2)+JC.LT.HOUGHSIZE)
     $           .AND.(LINES(IC,3)+KC.Gt.0.AND.LINES(IC,3)+KC.LT.360)
     $           .AND.LINES(IC,4).EQ.1)
     $           THEN
              IF(LINES(IC,1).LT.
     $             HOUGHARRAY(LINES(IC,2)+JC,LINES(IC,3)+KC))THEN
                LINES(IC,4) = 0
                HOUGHMIN = HOUGHMIN - 1
              ENDIF
            ENDIF
 520      ENDDO
 510    ENDDO
 500  ENDDO

c            print*,'final list containing ',houghmin,' peaks'
c      DO 400 IC = 1,HOUGHCNT
c        if(lines(ic,4).gt.0)
c     $       print*,ic,lines(ic,1),lines(ic,2),lines(ic,3),lines(ic,4)
c 400  enddo
C
C---- now go through each line to work out how many points in the image are
C     contiguous
C
      isum = ij
      KC = 0
      LC = 0
      NLINESFOUND = 0
      DO 600 WHILE (KC.LT.HOUGHCNT .AND. ISUM. GT. 0)
        KC = KC + 1
        if(lines(Kc,4).gt.0) THEN
          LC = LC + 1
          do 605 ic = 1,10
            histogram(ic) = 0
 605      enddo
          distavg = 0.0
          distrms = 0.0
          distdiv = 0
          DO 710 IC = 1,npoints
            RIC = REAL(ARM(1,IC))
            RJC = REAL(ARM(2,IC))
              IF(ARM(3,IC).NE.0)THEN
C
C---- is this point in this line?
C
                Theta = REAL(lines(kc,3)) * DTOR * 0.5
                Radius = RIC * COS(Theta) + RJC * SIN(Theta)
                distance = abs(radius-real((lines(kc,2)-(sizex + 1))))
c                print*,'Hough distance = ',kc,distance,radius,
c     $               lines(kc,2),lines(kc,2)-(sizex + 1)
                distavg = distavg + distance
                distrms = distrms + (distance * distance)
                distdiv = distdiv + 1
                adistance(distdiv) = distance
              ENDIF
 710      enddo
          if (distdiv.gt.0)then
            distavg = distavg/distdiv
            distrms = distrms/distdiv - (distavg * distavg)
            if (distrms .gt. 0) then
              distrms = sqrt(distrms)
            else
              distrms = 0.0
            endif
          else
            distavg = 0.0
            distrms = 0.0
          endif
          call sortup5(distdiv,adistance,sortval)

          IF(DEBUG(80))THEN
            print*,'Hough mean, median,, rms = ',distavg,
     $           adistance(sortval(distdiv/2)),distrms
          ENDIF
          RIC = adistance(sortval(1))
          RJC = adistance(sortval(2))
          IC = 3
          DISTAVG = 0.0
          do 715 WHILE (DISTAVG.LT.2.AND.IC.LE.DISTDIV)
            RKC = adistance(sortval(ic))
            DISTAVG = sqrt(((ric-rjc)*(ric-rjc)) + 
     $           ((ric-rkc)*(ric-rkc)))
            RIC = RJC
            RJC = RKC
            ic = ic + 1
 715      enddo
          distance = 2 * adistance(sortval(IC/2))
C          print*,'Hough distance = ',distance
          DO 610 IC = 1,npoints
            RIC = REAL(ARM(1,IC))
            RJC = REAL(ARM(2,IC))
              IF(ARM(3,IC).NE.0)THEN
C
C---- is this point in this line?
C
                Theta = REAL(lines(kc,3)) * DTOR * 0.5
                Radius = RIC * COS(Theta) + RJC * SIN(Theta)
                if(abs(radius-real((lines(kc,2)-(sizex + 1)))).lt.
     $               10.0)
     $               then
                  histogram(int(abs(radius-real
     $                 ((lines(kc,2)-(sizex + 1)))))+1) = 
     $                 histogram(int(abs(radius-real
     $                 ((lines(kc,2)-(sizex + 1)))))+1) + 1
                  
                  if(abs(radius-real((lines(kc,2)-(sizex + 1))))
     $                 .le.distance.and.
     $                 LOCALARMVAL(IC).EQ.0)LOCALARMVAL(IC) = KC

                else
                  histogram(10) = histogram(10) + 1
                endif
              ENDIF
 610      enddo
        isum = isum - histogram(1)
        NLINESFOUND = NLINESFOUND + 1
        HOUGHLINES(1,NLINESFOUND) = REAL(LINES(KC,2) - (SIZEX + 1))
        HOUGHLINES(2,NLINESFOUND) = REAL(LINES(KC,3)) * 0.5

        IF(DEBUG(80))THEN
          write(IOUT,fmt=9999)kc,lines(kc,2)-(sizex + 1),
     $         (REAL(lines(kc,3)) * 0.5),
     $         (histogram(ic),ic=1,10)
          IF(ONLINE)write(ITOUT,fmt=9999)kc,lines(kc,2)-(sizex + 1),
     $         (REAL(lines(kc,3)) * 0.5),
     $         (histogram(ic),ic=1,10)
 9999     format('Line ',I3,': radius = ',I4,', angle = ',F7.3,10I5)
        ENDIF
        ENDIF
 600  ENDDO
C
C---- initialise & increment line counter
C
      NLINESFOUND = 1
      do 720 ic=1,npoints
        ADDED = .FALSE.
        IF(LOCALARMVAL(IC).NE.0)THEN
          DO 700 JC = 1,NLINESFOUND
            IF(LOCALARMVAL(IC).EQ.LINESFOUND(JC))THEN
              ARM(3,IC) = JC
              ADDED = .TRUE.
            ENDIF
 700      ENDDO
          IF(.NOT.ADDED.and.nlinesfound.lt.maxexcl)THEN
            LINESFOUND(NLINESFOUND) = LOCALARMVAL(IC)
            IF(DEBUG(80))THEN
              print*,'Line(',nlinesfound,') = ',linesfound(nlinesfound)
            ENDIF
            NLINESFOUND = NLINESFOUND + 1
          ENDIF
        ELSE
          ARM(3,IC) = 0
        ENDIF
 720  enddo
      NLINESFOUND = NLINESFOUND - 1
      return
      end
C== IBYTE ==
C $Id: ibyte.f,v 1.3 2006/08/29 14:58:32 harry Exp $
      INTEGER FUNCTION IBYTE(IJBA,N)
      IMPLICIT NONE
C     ==============================
C
C
C---- Un pack bytes
C
C
C     .. Scalar Arguments ..
      INTEGER N
C     ..
C     .. Array Arguments ..
      INTEGER*2 IJBA(*)
C     ..
C     .. Local Scalars ..
      INTEGER I,JUNK,KJBA,M,MASKA,MASKB
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC MOD,IAND,ISHFT
C     ..
C
C        DATA MASKA,MASKB/'377'O,'177400'O/
      DATA MASKA,MASKB/255,65280/
C
C
      M = MOD(N,2)
      I = (N-1)/2 + 1
      KJBA = IJBA(I)
C
C
      IF (M.EQ.0) THEN
C
C---- Even byte
C
        JUNK = IAND(KJBA,MASKB)
        IBYTE = ISHFT(JUNK,-8)
      ELSE
C
C---- Odd byte
C
        IBYTE = IAND(KJBA,MASKA)
      END IF
C
C
      END
C== ICMP ==
      INTEGER FUNCTION ICMP(IARR1,I1,IARR2,I2,NKEY)
C     =============================================
C
C
C
        implicit none
C
C
C
C---- This function is used to compare the values of the sort keys
C     for 2 reflections
C
C
C---- Parameters
C
C        IARR1 (I)   ARRAY CONTAINING 1ST SET OF KEYS (INTEGER)
C           I1 (I)   POINTER TO FIRST KEY IN IARR1
C        IARR2 (I)   ARRAY CONTAINING 2ND SET OF KEYS (INTEGER)
C           I2 (I)   POINTER TO FIRST KEY IN IARR2
C         NKEY (I)   NO. OF KEYS
C
C FUNCTION RETURN VALUES  -1  REFLN 1 LT REFLN 2
C                          0  REFLN 1 EQ REFLN 2
C                          1  REFLN 1 GT REFLN 2
C
C---- Specification statements
C
C
C---- Compare keys
C
C     .. Scalar Arguments ..
      INTEGER               I1,I2,NKEY
C     ..
C     .. Array Arguments ..
      INTEGER*2               IARR1(*),IARR2(*)
C     ..
C     .. Local Scalars ..
      INTEGER               I,J1,J2
C     ..
C
C
      J1 = (I1-1)*NKEY
      J2 = (I2-1)*NKEY
C
C
      DO 10 I = 1,NKEY
          J1 = J1 + 1
          J2 = J2 + 1
          IF (IARR1(J1)-IARR2(J2)) 30,10,20
   10     CONTINUE
C
C
      ICMP = 0
      RETURN
C
   20 ICMP = 1
      RETURN
C
   30 ICMP = -1
C
C
      END
C $Id: idnmat.f,v 1.2 2006/08/29 14:58:32 harry Exp $
      SUBROUTINE IDNMAT(A)
      IMPLICIT NONE
C       ====================
C
C  Set matrix A(3,3) to identity
C
      REAL A(3,3)
C
      CALL CLEAR(A)
      A(1,1)=1.0
      A(2,2)=1.0
      A(3,3)=1.0
      RETURN
      END
C==   IDXREF ==
C     
      SUBROUTINE IDXREF(ID,NADDL,FIXED,NIMAG,NPOINT,NOREFCELL,NEWPREF,
     $     ISTAT)
C     ===========================================================
C     
      IMPLICIT NONE
C---- Set up for post-refinement of missetting angles and cell parameters
C     DEBUG(39) this S/R
C     
C     NADDL....  For old-style post refinement:
C     Number of images to be added together for use in 
C     post-refinement. Note than when NADD>1 but NIMAG<NADD
C     then the value passed into idxref from postrefl is 1
C     rather than the true NADD.
C     For new-style post refinement (NEWPREF):
C     The number of parameters sets to be refined.
C     FIXED...   TRUE if all images are assumed to have same missetting
C     angles (calls REFORT).
C     FALSE if each image has its own missetting angles (calls
C     REFRT1).
C     NIMAG...   Number of images currently available for post-refinement. It
C     is not used in this s/r except to pass to REFRT1.
C     NPOINT...  Pointer to the first reflection to be used in this refinement
C     in the reflection arrays. This is only anything other
C     than 1 when NADD>1 but NIMAG<NADD with traditional
C     post-refinement. With new style post-refinement it is 1.
C     NOREFCELL  Do not allow refinement of cell at this point. Used in new
C     style post refinement when NIMAG is less than NADD.
C     ISTAT zero on entry, returned as -1 if refinement fails, 1 if a
C           refinement has been carried out 
C     ..
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     ..
C     .. Scalar arguments
      INTEGER ID,NADDL,NIMAG,NPOINT,ISTAT
      LOGICAL FIXED,NOREFCELL,NEWPREF
C     ..           
C     .. Local Scalars ..
      INTEGER I,J,IMAT,IUMAT,ICELL,ICHECK
      REAL PHIX,PHIY,PHIZ
      REAL DETERM
C     ..
C     .. Local Arrays ..
      REAL CELLREF(6),SUMAT(3,3),RMAT(3,3),WORK(3,3),UMATIN(3,3),
     +     DELPHIR(3),DELPHIIM(3),DELPHIIMP(3),UMATINP(3,3),
     +     SPARM(6+NIMAX*3+2),WORK2(3,3)
C     ..
C     ..
C     .. External Subroutines ..
      EXTERNAL REFORT,REFRT1,MPAUSE,SETMAT,MINV33,
     +     ROTMAT,MATMUL3,RTOMISSET,MATSET,RECCEL
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/cell.f
C
C $Id: cell.f,v 1.4 2012/11/21 14:41:22 andrew Exp $
C
