C--- awk generated include file  test.h
C---- START of include file test.h
C
C    Detector limits, used in SPTEST. All are in 10 micron units.
C    In the virtual detector frame, Y is parallel to the rotation axis
C    and X is orthogonal to the rotation axis.
C
C    In the scanner frame, X is parallel to the slow direction in the
C    image, Y is the fast direction.
C
C    RSCANSQ      Radius**2 of the scanned region of the plate (Mar scanners)
C                 This is different to the other limits because it is
C                 applied to the actual scanner coordinates rather than
C                 the virtual detector coordinates. All other limits apply
C                 to virtual detector coordinates.
C    XSCAN        Maximum X coordinate in detector frame (10 micron units)
C    YSCAN        Maximum Y coordinate in detector frame (10 micron units)
C    RSCANX,RSCANY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RSCAN defining the
C                 useable area of the detector.
C    XSCAN,YSCAN,RSCAN are maximum coords relative to the physical centre of 
C                 the detector (ie the mid-point of the image), NOT wrt the 
C                 direct beam position.
C    RMINX,RMINY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RMIN defining the
C                 useable area of the detector.
C    RMXSQD       Maximum radius (squared) in virtual detector frame
C    RMNSQD       Minimum radius (squared) in virtual detector frame
C    XMIN         Minimum X coordinate in  detector frame
C    XMAX         Maximum X coordinate in  detector frame
C    YMIN         Minimum Y coordinate in  detector frame
C    YMAX         Maximum Y coordinate in  detector frame
C    NXYEXC       Number of excluded areas set by user (rectangles, arcs)
C    NXYEXCDET    Number of detector specific excluded rectangles (Pilatus)
C    NOTILES      If set true, ignore all tile boundaries in Pilatus images
C    ICEWIDTH     Width of the exclusion shells for ice, this fraction
C                 of the actual resolution is used as the half-width
C    ICEWIDTHPREF Width of the exclusion shells for ice for post
C                 refinement, this fraction
C                 of the actual resolution is used as the half-width
C    PREFEXICE    Logical, true if reflections in ice rings to be
C                 excluded from post-refinement
C
C     .. Scalars in common block /TEST/ ..
      REAL RMXSQD,RMNSQD,XMIN,XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,
     +     RMINX,RMINY,XSCAN,YSCAN,CIRRAD,ICEWIDTH,ICEWIDTHPREF
      INTEGER NEXCL,NXYEXC,NXYEXCDET,IQUADNO,IARCNO,NEXCL2
      LOGICAL PREFEXICE,NOTILES
C
C     .. Arrays in common block /TEST/
      REAL RESEXL,RESEXH,XYEXC,CNREXC,EXCARC,CIRCEN,PHILIM,RES2EXL,
     +     RES2EXH,RES3EXL,RES3EXH,XYEXCSP
      INTEGER IEXCARC
      LOGICAL LEXCARC
C     ..
C     .. Common Block /TEST/ ..
      COMMON /TEST/RESEXL(MAXEXCL),RESEXH(MAXEXCL),XYEXC(4,MAXEXCL),
     +     CNREXC(8,MAXEXCL),
     $     EXCARC(5,MAXEXCL),CIRCEN(2),PHILIM(2),RMXSQD,RMNSQD,XMIN,
     +     XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,RMINX,RMINY,XSCAN,
     $     YSCAN,CIRRAD,IEXCARC(6,MAXEXCL),NEXCL,NXYEXC,IQUADNO,
     $     IARCNO,LEXCARC(MAXEXCL),NXYEXCDET,RES2EXL(MAXEXCL),
     $     RES2EXH(MAXEXCL),NEXCL2,ICEWIDTH,ICEWIDTHPREF,PREFEXICE,
     +     RES3EXL(MAXEXCL),RES3EXH(MAXEXCL),NOTILES,XYEXCSP(4,MAXEXCL)
C     ..
C
C

C&&*&& end_include  ../inc/test.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C&&*&& include  ../inc/xy.f
C
C $Id: xy.f,v 1.1 2002/05/02 10:47:25 harry Exp $
C
C--- awk generated include file  xy.h
C---- START of include file xy.h
C
C     .. Scalars in common block /XY/ ..
      REAL XTOFD,SINV,COSV,TANV,TWOTHETA
      INTEGER ICASS
C     ..
C     .. Common Block /XY/ ..
      COMMON /XY/XTOFD,SINV,COSV,TANV,TWOTHETA,ICASS
C     ..
C
C     XTOFD....  Crystal to detector distance in 10 micron units. Read from
C                keyworded input and never changed.
C
C                Spot positions are calculated in S/R XYSPOT (Called from
C                REEK) and are for an "ideal" detector at a distance of XTOFD.
C                These are converted into pixel positions in S/R MMTOPX
C                which applies the multiplicative factor XTOFRA to allow
C                for refinement of the distance. XTOFRA is the parameter
C                that is actually refined (in RDIST), rather than XTOFD.
C                The refined distance that is printed in the logfile is
C                actually XTOFRA*XTOFD
C
C     ICASS....  Indicates detector type:
C                0     Flat film
C                1     Vee shaped cassettes
C                2     FAST detector (only used in TESTGEN mode of OSCGEN)
C                3     Swung out FAST (ditto)
C                4     IP detector
C     TWOTHETA   Detector swing angle (degrees)
C&&*&& end_include  ../inc/xy.f
C
      CALLEDFROM = 'IFPWDR'
      THIS = 'IFPWDR'
      INDENT = 2
      IERR = 0
      NEEDMAT = .TRUE.
      IF(PICKLOG)NEEDMAT = .FALSE.
C
C---- Debug output
C
      IF (DEBUG(79)) THEN
        WRITE(IOUT,FMT=6000) LSOL,NSOL,SOLN,NAUTO,
     +      (NOIMG(I),I=1,5),(FOUND(I),I=1,5), DPSINDEX,DPSDONE,
     +      NODISPLAY,USERSPOT,DOFIND,AUTOINDX,POSTREF
        IF (ONLINE) WRITE(ITOUT,FMT=6000) LSOL,NSOL,SOLN,NAUTO,
     +      (NOIMG(I),I=1,5),(FOUND(I),I=1,5), DPSINDEX,DPSDONE,
     +      NODISPLAY,USERSPOT,DOFIND,AUTOINDX,POSTREF
 6000   FORMAT(/,/,1X,'From start IFPWDR',/,1X,'LSOL=',L1,' NSOL=',I4,
     +        '  SOLN=',I4,' NAUTO=',I2,' NOIMG(1-5)',5I5,
     +        ' FOUND(1-5)',5(1X,L1),/,1X,'DPSINDEX=',L1,' DPSDONE=',
     +        L1,' NODISPLAY=',L1,' USERSPOT=',L1,' DOFIND=',L1,
     +        ' AUTOINDX=',L1,' POSTREF=',L1)
      END IF
C---- Save values of ADDPART,SUMPART,POSTREF
C     
      SADDPART = ADDPART
      SSUMPART = SUMPART
      SPOSTREF = POSTREF
C     
      ADDPART = .FALSE.
      SUMPART = .FALSE.
      POSTREF = .FALSE.
C     
C---- Set up default extension
C     
C     ***** machine specific code follows *****
C     
      IF (ODEXT(1:1).EQ.' ') THEN
         IF (MACHINE.EQ.'MAR ') THEN
            ODEXT = 'image'
         ELSE IF (MACHINE.EQ.'LMB') THEN 
            ODEXT = 'pck'
         ELSE IF (MACHINE.EQ.'RAXI') THEN 
            ODEXT = 'osc'
         ELSE IF (MACHINE.EQ.'DIP2') THEN
            ODEXT = 'ipf'
         ELSE IF (MACHINE.EQ.'FUJI') THEN
            ODEXT = 'img'
         ELSE IF (MACHINE.EQ.'CCD2') THEN
            ODEXT = 'cor'
         ELSE
            ODEXT = 'image'
         END IF
      END IF
C     
C---- Check ident is non-blank (if using AUTOINDEX keyword with no 
C     IMAGE keyword)
C     
      IF ((IDENT(1:1).EQ.' ').AND.(.NOT.TEMPLATE).and.
     $     (.not.HDF5FILE)) THEN
         WRITE (IOUT,FMT=6716)
         IF (ONLINE) THEN
            WRITE (ITOUT,FMT=6716)
         END IF
         STOP
      END IF

C     
C---- Open first image file to get image size and also to
C     determine if byte swapping is required (only SOME scanners)
C     
      IF (IMGP.AND.HDRSIZE) THEN
         ISCAN = 1
         MODEOP = 2
         ID1 = IDPACK(IFIRSTPACK)
C     
C---- Need to allow for AUTOINDEXING in batch mode without a PROCESS
C     keyword
C     
c         IF ((NSER.EQ.0).AND.(NAUTO.GT.0)) ID1 = IDAUTO(1)
CHRP 15.05.2013         IF ((NSER.EQ.0).AND.autoindx) ID1 = IDAUTO(1)
         IF ((NSER.EQ.0).AND.autoindx) ID1 = NOIMG(1)
         NFIRSTF = 1
C     
C-----OPENODS in POWDER mode to get image size and header information.
C     
C     ********************************************************
         IF(.NOT.(AUTOINDX.AND.FOUND(IFIRSTPACK)))THEN
           IF (DEBUG(79)) THEN
             WRITE(IOUT,FMT=6002) ID1,MODEOP
             IF (ONLINE) WRITE(ITOUT,FMT=6002) ID1,MODEOP
 6002        FORMAT(/,1X,'Calling OPENODS for image ID=',I7,' in ',
     +            ' mode=',I2)
           END IF
C
C---- Print for program flow
C  
          CALLED = 'OPENODS'
          COMMENT = 'get image size and header information'
          LIPROCESS = 0
          WRITE(STRING,FMT=6005) ID1,MODEOP
 6005     FORMAT(': Image',I8,'  MODEOP=',I3,' LIPROCESS=0' )
          COMMENT = COMMENT(1:LENSTR(COMMENT))//STRING(1:LENSTR(STRING))
          IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
         CALL OPENODS(IDENT,ID1,NFIRSTF,ODEXT,FDISK,MODEOP,
     +        PACK,ODFILE,SEPCHAR,FORCEREAD,IPACK,
     +        TEMPLSTART,TEMPLEND,LIPROCESS,IERR)
         ENDIF
C     *******************************************************
C     
C---- If file does not exist, jump out. Also need to reset NIMAGES to
C     zero
C     since it always uses the first image here
C  
         IF (ID1.EQ.-999) THEN
            IF (ONLINE) THEN
               IF (COMREAD) THEN
                  COMREAD = .FALSE.
                  ITIN = ITINS
                  CLOSE (UNIT=ICOMM)
               END IF
               NIMAGES = 0
               NIMAG = 0
               GOTO 50
            END IF
            STOP
         ELSE
C
C---- If there isn't an error at this point, we need to make sure 
C     NIMAGES .NE. 0  so that header information is read & used correctly
C
            NIMAGES = 1
         END IF
C     
C---- Check wavelength and distance for consistency with values in
C     header
C
C---- Print for program flow
C  
         CALLED = 'SECTION'
         COMMENT = ' '
         WRITE(COMMENT,FMT=6003) HEADONLY, NO_XML
 6003    FORMAT(1X,'HEADONLY=',L1,'  NO_XML=',L1)
         IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
         CALL SECTION(RSCAN,RSCANRED,RMINXINP,NIMAGES,ID,IPIXY,
     $        IXOFFSET,IYOFFSET,DISPSET,ICCX,CCXRESET,SITE,SCANNER)
      ENDIF
C
C---- Should know wavelength by now. If lab source (CuKalpha) reset
C     some spot finding parameters if not explicitly specified on
C     keywords
C
      IF ((ABS(WAVE-1.5418).LT.0.0019).OR.
     +   (ABS(WAVE-0.7107).LT.0.0002)) THEN
          IF (ITHSET.EQ.0) THRESH = 3.5
          IF (IPIXMIN.EQ.0) then
            IF ((MACHINE.NE.'RIPI').AND.(MACHINE.NE.'RIEI').AND.
     +          (MACHINE.NE.'PHOT')) THEN
              NPIXMIN = 30
              IF (IRMSFAC.EQ.0) RMSFAC = 1.0
            ELSE
              NPIXMIN = 6
            ENDIF
          ENDIF
          IF (DEBUG(79)) THEN
            WRITE(IOUT,FMT=6004) WAVE,THRESH,NPIXMIN,RMSFAC
            IF (ONLINE) WRITE(ITOUT,FMT=6004)WAVE,THRESH,NPIXMIN,
     +               RMSFAC
 6004       FORMAT(1X,'Because wavelength of',f7.4,' suggests this is',
     +            ' lab data, spot finding parameters',/,1X,'may have',
     +            ' been reset (if not set by keywords.)',/,1X,
     +            'Threshold now',F5.2,' Minimum number of pixels',I3,
     +            ' Spot rms variation',F4.1)
          END IF
      END IF
      
C     
C---- If a MATRIX or CELL and UMAT have been supplied, call SETMAT to
C     extract cell from A matrix.
C     
      IF (.NOT.LSOL.AND.((IMAT.NE.0).OR.((ICELL.NE.0).AND.(IUMAT.NE.0)
     $     ))) THEN 
         ICHECK = 0
C     ************************
         CALL SETMAT(IMAT,IUMAT,ICELL,ICHECK)
C     ************************
      END IF
C     
C---- Convert spot separations (IXSEP,IYSEP) into "ideal detector"
C     coordinate
C     frame, as the spot coordinates (generate file coords) are in this
C     frame
C     
      MINDTX = NINT(ABS(IXSEP*COSOM0 + IYSEP*SINOM0))
      MINDTY = NINT(ABS(IYSEP*COSOM0 + IXSEP*SINOM0))
C     
C---- If running in batch, or if NODISPLAY has been specified on
C     IMAGE keyword, then do spot finding/autoindexing now.
C     
      IF ((.NOT.ONLINE).OR.(NODISPLAY)) THEN
C
C---- some things require us to have a matrix already, some don't
C
        IF(NEEDMAT)THEN
C     
C---- Must have supplied cell parameters (or a MATRIX)
C     
          IF ((ICELL.EQ.0).AND.(IMAT.EQ.0).and..not.
     $         (dpsindex.or.dofind)) THEN
            WRITE(IOUT,FMT=7214)
            IF (ONLINE) WRITE(ITOUT,FMT=7214)
 7214       FORMAT(/,1X,'***** ERROR *****',/,1X,
     +           'Must supply a unit cell (or an initial matrix)')
            STOP
          END IF
C     
C---- Must have supplied symmetry
C     
          IF (LSYMM.EQ.0.and..not.(dpsindex.or.dofind)) THEN
            WRITE(IOUT,FMT=7216)
            IF (ONLINE) WRITE(ITOUT,FMT=7216)
 7216       FORMAT(/,1X,'***** ERROR *****',/,1X,
     +           'Must supply symmetry if autoindexing in ',
     $           'batch mode with old-style REFIX code')
            STOP
          END IF
        ENDIF
C     
C---- Loop over images finding spots. If no images given with AUTO
C     keywords, use first image from PROCESS keyword and set up the PHI
C     value accordingly.
C     
C
C---- must not update PHIBEG and PHIEND if we are doing mosaicity 
C     estimation, because PHIBEGA etc may not have been set.
C     Add test on HDF5FILE otherwise if PHI values are specified on an IMAGE
C     keyword it will not set a value for NIMAGP
            IF ((IANGLE.EQ.0).OR.(ISTRT.EQ.0).OR.HDF5FILE) THEN
              IF (NAUTO.EQ.0) THEN
                NIMAGP = 1
                PHIBEG = PHIBEGA(IFIRSTPACK)
                PHIEND = PHIENDA(IFIRSTPACK)
                PHI(1) = 0.5*(PHIBEG + PHIEND)
                PHISTIM(1) = PHIBEG
                NOIMG(1) = IDPACK(IFIRSTPACK)
                IDIMG(1) = IPACK1A(IFIRSTPACK)
CHRP 15.05.2013            IDAUTO(1) = IDIMG(1)
              ELSE
                NIMAGP = NAUTO
                PHIBEG = PHIBEGA(IFIRSTPACK)
                PHIEND = PHIENDA(IFIRSTPACK)
              END IF
            ENDIF
C     
         XCEN = 100.0*XCENMM(1,1) + CCX
         YCEN = 100.0*YCENMM(1,1) + CCY
c          write(iout,fmt=9876) xcen
c          if (online) write(itout,fmt=9876) xcen
c 9876     format(1x,'xcen set in ifpwdr from xcenmm, now;',F8.2)
C     
C---- Start of Autoindex only stuff
C     

c     gw
         loop_count = 0
         nspt_old = 0

         IF(AUTOINDX)THEN
            IF (NIMAGP.EQ.1) THEN
              IF(IDIMG(1).GT.0)THEN
                  WRITE(IOUT,FMT=7210) NOIMG(1)
                  IF (ONLINE) WRITE(ITOUT,FMT=7210) NOIMG(1)
               ELSEIF(NOIMG(1).EQ.0)THEN
                  WRITE(IOUT,FMT=7215)
                  IF(ONLINE)WRITE(ITOUT,FMT=7215)
               ENDIF
            ELSE
               WRITE(IOUT,FMT=7212) NIMAGP,(NOIMG(I),I=1,NIMAGP)
               IF (ONLINE) WRITE(ITOUT,FMT=7212) NIMAGP,
     +              (NOIMG(I),I=1,NIMAGP)
            END IF
 7210       FORMAT(/,1X,'Autoindexing image',I7,/,1X,
     +           '=======================',/)
 7212       FORMAT(/,1X,'Autoindexing using',I3,' images',/,1X,
     +           'Image numbers: ',20(I7,1X))
 7215       FORMAT(/,1X,'Autoindexing from a previously obtained ',
     $           'spot list',/,1X,'==============================',
     $           '===================',/)
C     
            IF (RFIXCELL) THEN
               WRITE(IOUT,FMT=7218)
               IF (ONLINE) WRITE(ITOUT,FMT=7218)
            END IF
 7218       FORMAT(1X,'*** Cell parameters will NOT be refined',
     +           ' (FIXCELL) ***',/)
            IF (.NOT.RFIXDIST) THEN
               WRITE(IOUT,FMT=7219)
               IF (ONLINE) WRITE(ITOUT,FMT=7219)
               IF (.NOT.RFIXCELL) THEN
                  WRITE(IOUT,FMT=7221)
                  IF (ONLINE) WRITE(ITOUT,FMT=7221)
               END IF
            END IF
 7219       FORMAT(1X,'*** Detector distance will be refined ',
     +           '(UNFIXDIST) ***')
 7221       FORMAT(/,1X,'*** This is NOT recommended unless the cell',
     +           ' is fixed (FIXCELL) ***',/)
C     
C---- end of Autoindex only stuff
C     
         ENDIF
C     
C---- Save original identifier
C     
         SIDENT = IDENT
C     
C---- for DPS indexing always start with a clean spot list
C     
         IF(DPSDONE)THEN
            DO 901 I = 1,MAXIMG
               SELECT(I) = .FALSE.
               SPOTFND(I) = .FALSE.
 901        ENDDO
         ENDIF
         DO 900 I = 1,NIMAGP
           IF(.NOT.FOUND(I))THEN
CHRP 15.05.2013            ID = IDAUTO(I)
             ID = NOIMG(I)
C     
C---- Set up phi value for this image
C     
            IF (.NOT.PHISET(I)) 
     +           PHI(I) = (ID - IDPACK(IFIRSTPACK))*(PHIEND - PHIBEG)
     +           + 0.5*(PHIEND+PHIBEG)
C     
C---- set up NIMAG passed via common /spots/ to pickspots
C     
            NIMAG = I
            MODEOP = 0
            IF (IDENTAUTO(I).NE.' ') IDENT = IDENTAUTO(I)
            IF (TEMPLAUTO(I).NE.' ') THEN
               CALL TEMPLREAD(TEMPLAUTO(I),TEMPLSTART,TEMPLEND,NTDIG)
               TEMPLATE = .TRUE.
            ENDIF
C     
C---- Read in image (IN POWDER MODE) for batch autoindexing
C     
C     ********************************************************
            IF(.NOT.(AUTOINDX.AND.FOUND(I)))THEN
              IF (DEBUG(79)) THEN
                WRITE(IOUT,FMT=6002) ID,MODEOP
                IF (ONLINE) WRITE(ITOUT,FMT=6002) ID,MODEOP
              END IF
C
C---- Print for program flow
C  
              CALLED = 'OPENODS'
              COMMENT = 'to read image for batch autoindexing'
     +                   //' LIPROCESS=5'
              WRITE(STRING,FMT=6005) ID,MODEOP
              COMMENT = COMMENT(1:LENSTR(COMMENT))//
     +                STRING(1:LENSTR(STRING))
              IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              LIPROCESS = 5
              CALL OPENODS(IDENT,ID,FILM,ODEXT,FDISK,MODEOP,
     +             PACK,ODFILE,SEPCHAR,FORCEREAD,IPACK,
     +             TEMPLSTART,TEMPLEND,LIPROCESS,IERR)
C
C---- Sum images if requested
C
              IF (NIMGSUMSPOT.GT.1) THEN
                IDOLD = 0
                NIMGSUMOLDSPOT = 0
                SUMIMGFORSPOTS = .TRUE.
C
C---- Zero out array IMAGE2
C
                NPIXTOT = NREC*IYLEN
                DO 90 K = 1,NPIXTOT
                  IMAGE2(K) = 0
 90             CONTINUE
                COMMENT = ' '
                WRITE(COMMENT,FMT=6010) NIMGSUMSPOT
 6010           FORMAT('to sum',i3,' images for spotfinding')
C
                IF (HDF5FILE) THEN
C
C---- Print for program flow
C  
                  CALLED = 'EIGER'
                  IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
C---- Call EIGER with MODE=5 to sum images
C
                  CALL EIGER(IERR,5,ID,CHUNK,NIMGSUMSPOT)

                  IF (INVERTX) THEN
C     
C---- Print for program flow
C
                    CALLED = 'IMGINV'
                    COMMENT = 'because INVERTX is TRUE'
                    IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                    CALL IMGINV(IMAGE2,NREC,IYLEN,0)
                  END IF
                ELSE
C
C---- Print for program flow
C  
                  CALLED = 'SUMIMG'
                  IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL SUMIMG(ID,IDOLD,NIMGSUMSPOT,NIMGSUMOLDSPOT,
     +                      INTPIXMIN,INTPIXMAX,IREVERSE)
                END IF
              END IF

C---- For Pilatus detectors, need to check what value has been assigned to
C     pixles in the gaps between tiles. This should be -1, but this value is
C     assigned by the beamline software and in some cases it has been assigned
C     a value of zero (eg Campinas 2M, Pilatus 1M for lab testing). agwl 12/4/16
C     Note that NULLPIXTEST is reset FALSE after every call to CONTROL, so
C     NULLPIX will be reset (if necessary) for every task
C     (cell refinement, integration) because iMosflm will always be
C     sending a value of -1. However, if doing repeated spot finding,
C     this is all done from within CONTROL so NULLPIXTEST is not
C     reset FALSE so NULLPIX will not be reset, so remove the test
C     on NULLPIXTEST here.
C
          IF (((MACHINE.EQ.'PILA').OR.(MACHINE.EQ.'EIGE')).AND.
     +         (.NOT.KEEPNULLPIX)) THEN
CAL     +         (.NOT.NULLPIXTEST).AND.(.NOT.KEEPNULLPIX)) THEN
C
C     For Pilatus, first gap between tiles extends from X=195-211, so
C     calculate index of a pixel half way along the middle stripe of the
C     gap, for Eiger gaps if from X=514 to 550 
C  
                IF (MACHINE.EQ.'PILA') THEN
                  II = 203*IYLEN + IYLEN/2
                ELSE IF (MACHINE.EQ.'EIGE') THEN
                  II = 532*IYLEN + IYLEN/2
                END IF
                K = INTPXL(IMAGE(II))
                IF (K.NE.NULLPIX) THEN
                  WRITE(IOUT,FMT=7222) II,K,NULLPIX,K
                  IF (ONLINE) WRITE(ITOUT,FMT=7222) II,K,NULLPIX,K
 7222             FORMAT(/,/,1X,'***** WARNING *****',/,1X,
     +            'Pixel value',
     +            ' in the gap between the tiles (element',I8,') is',
     +            I5,' but NULLPIX is',I5,/,1X,'Reflections in which'
     +            ' two adjacent rows or columns at any of the edges',
     +            /,1X,'of the measurement box have zero values will ',
     +            ' be treated as "edge" reflections which should then',
     +            ' be integrated correctly')
C
C---- No longer reassign NULLPIX, this will be done in PROCESS on a reflection
C     by reflection basis
C
CAL                  NULLPIX = K
CAL                  IINULL = .TRUE.
                  WRONGGAPVALUE = .TRUE.
                END IF
                NULLPIXTEST = .TRUE.
             END IF
            ENDIF
C     *******************************************************
C     
C---- If file does not exist, jump out
C     
            IF (ID.EQ.-999) GOTO 9000
C     
C---- If oscillation angles not given on PROCESS keyword OR on
C     AUTOINDEX keyword, set up PHI using header info
C     
C     
            IF (((IANGLE.EQ.0).OR.(ISTRT.EQ.0)).AND.
     +           (.NOT.PHISET(I))) THEN
               PHIBEG = HPHIS
               PHIEND = HPHIE
               PHI(I) = 0.5*(HPHIS+HPHIE)
C     
C---- Trap zero phi range from header info
C     
               IF (ABS(PHIEND-PHIBEG).LT.0.001.AND.DOFIND) THEN
                  WRITE(IOUT,FMT=7384)
                  IF (ONLINE) WRITE(ITOUT,FMT=7384)
 7384             FORMAT(/,1X,'***** ERROR *****',/,1X,
     +                 'Phi values have not been specified on',
     +                 ' AUTOINDEX keyword, and oscillation range',
     $                 /,1X,'from image header is zero. Supply ',
     $                 'phi values on AUTOINDEX keyword')
                  NSHUTERR = 1
                  CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
               END IF
            END IF
C
C---- Save the PHI values in case they are reset for summed images
C
            IF (NIMGSUMSPOT.GT.1) THEN
              DO 100 K = 1,MAXIMG
                PHISAVE(I) = PHI(I)
 100          CONTINUE
            END IF
            IF((AUTOINDX).OR.
     $           (DOFIND.and..not.autoindx))THEN
               IF (PHISET(I)) THEN
                  PHIBEG = PHI(I) - 0.5*PHIRNGA(I)
                  PHIEND = PHIBEG + PHIRNGA(I)
               END IF
               MODESP = 0
               IIMAG = I
               LPRNT = .TRUE.
               IF (ITHSET.EQ.0) THEN
                  MODESP = 10
               END IF
               BOXOPEN = .FALSE.
C
C---- Jumps (back) to this point if threshold is changed (increased or
C     decreased) to repeat spot search
C
 902           CONTINUE
               IF(DOFIND)THEN
C     
C---- If minimum spot separation not set, get a value now as it helps
C     discriminate good spots from bad. Also do this if SEPARATION UPDATE
C     given (ISEP=3).
C     
                  IF ((ISEP.EQ.0).OR.(ISEP.EQ.3)) THEN
                     MODEGSR = 1
                     IF (DEBUG(79)) THEN
                       WRITE(IOUT,FMT=6100) I,MODEGSR
                       IF (ONLINE) WRITE(ITOUT,FMT=6100) I,MODEGSR
 6100                  FORMAT(/,1X,'Calling GETSEPRAS for image',I7,
     +                        ' with MODEGSR=',I3)
                     END IF
                     IERR = 0
C
C---- Print for program flow
C  
                     CALLED = 'GETSEPRAS'
                     COMMENT = 'Get a value for separation'
                     IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                     CALL GETSEPRAS(IRAST,ISEP,IRAS,IDPACK(NIMAG),
     +                    MINDTX,MINDTY,IXSEP,IYSEP,MODEGSR,IERR)
                  END IF
                  
                  IF (DEBUG(79)) THEN
                    WRITE(IOUT,FMT=6110) I
                    IF (ONLINE) WRITE(ITOUT,FMT=6110) I
 6110               FORMAT(/,1X,'Calling GETSPOTS from IFPWDR ',
     +                          'for image',I7)
                  END IF
chrp 09.02.06                  IF(.NOT.MOSEST)
                  IERR = 0
C
C---- Print for program flow
C  
                  CALLED = 'GETSPOTS'
                  COMMENT = ' '
                  IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL GETSPOTS(MODESP,ID,I,LPRNT,BOXOPEN,IREVERSE,IERR)
                  IF (DEBUG(79)) THEN
                    WRITE(IOUT,FMT=6112) IERR,THRESH,NSPT_OLD,NSPT,
     +                        LOOP_COUNT
                    IF (ONLINE) WRITE(ITOUT,FMT=6112) IERR,THRESH,
     +                        NSPT_OLD,NSPT,LOOP_COUNT
 6112               FORMAT(/,1X,'Returned from GETSPOTS, IERR=',I3,
     +                          '  Thresh:',F6.2,'  NSPT_OLD',I5,
     +                          '  NSPT',I5,'  LOOP_COUNT',I3)
                  END IF
C     
C---- Trap error in background determination
C     
                  IF (IERR.GT.0) THEN
                     RAD = IERR*RAST
                     WRITE(LINE,7200) RAD
 7200                FORMAT(1X,'Too few pixels with non-zero values at',
     +                    ' radius',F6.1,'mm, change Rmin or Rmax')
                     NSHUTERR = 2
                     CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
                  END IF
C     
C---- Trap too many spots found (threshold too low)
C     
C     HRP 25.06.2003 - this was IERR.EQ.-3, which seems to be too many
C     spots to store; changed to -2 which might be right...
C     HRP 09.10.2010 - change to IERR .EQ. -3 .or. IERR .EQ. -2
c                  IF (IERR.EQ.-2.AND.THRESH.NE.4.AND.ITHRESH.NE.20) THEN
                  IF (IERR.EQ.-2.OR.IERR.EQ.-3) THEN
                    IERR = -5
                     THRESH = THRESH + 0.5*THRESH
                     WRITE(IOUT,FMT=7202) THRESH
                     IF (ONLINE) WRITE(ITOUT,FMT=7202) THRESH
                     THRESHMIN = THRESH
                     IF (THRESH.LT.1000) GOTO 902
                  END IF
 7202             FORMAT(/,1X,'Threshold increased to:',F8.1)
C     
C---- Trap too few or no spots found (threshold too high)
C     
                  IF (IERR.EQ.-4.OR.IERR.EQ.-1) THEN
 7201               format('<?xml version="1.0"?><!DOCTYPE ',
     +                   'spot_search_response>',
     &                   '<spot_search_response>',
     $                   '<status><code>error</code>',
     &                   '<message>Blank image? Check image ',
     $                   'carefully</message></status>',
     $           '<image_template>',A,'</image_template>',
     $           '<image_number>',I8,'</image_number>',
     &                   '</spot_search_response>')
                    IF((NREC .GT. 0) .AND. (IYLEN .GT. 0)) THEN
                      IF (NSPT_OLD .EQ. NSPT) THEN
                        LOOP_COUNT = LOOP_COUNT + 1
C     
C---- Only allow 4 tries at decreasing threshold
C     
                        IF(LOOP_COUNT .GT. 4.OR.THRESH.LT.2.0) THEN
C     ..
C     .. No spots at all
                          IF(IERR.EQ.-4)THEN
                            write(IOUT,7204)ID
                            IF(ONLINE)write(ITOUT,7204)ID
 7204                       FORMAT('NO SPOTS have been found on ',
     $                           'image ',I7,'! You should check',
     $                           ' this image carefully')
                            if(socklo) then
                              xmlline = ' '
                              write(xmlline, fmt=7201)
     $                             templsav(1:lenstr(templsav)),
     $           id
                              call write_socket_length(serverfd, 
     +                             lenstr(xmlline), xmlline)
                            end if
C
C---- Previously it would exit from spot finding at this point, even if there were other
C     images to be used in indexing. Comment out the "GOTO 50" so that it will continue.
C     Need to goto 900 to try the next image.
CAL                            goto 50
                            goto 900
                          ELSEIF(IERR.EQ.-1)THEN
C     
C---- Only allow 4 tries at decreasing threshold
C     
                            write(IOUT,7205)ID
                            IF(ONLINE)write(ITOUT,7205)ID
 7205                       FORMAT('Too few spots have been found on ',
     $                           'image ',I7,' to determine spot ',
     $                           'finding parameters! You should',
     $                           ' check this image carefully')
                            if(socklo) then
                              xmlline = ' '
                              write(xmlline, fmt=7201)
     $                             templsav(1:lenstr(templsav)),
     $           id
                              call write_socket_length(serverfd, 
     +                             lenstr(xmlline), xmlline)
                            END IF
                            GOTO 50
                          END IF
                        ELSE
                          NSPT_OLD = NSPT
                        END IF
                      ENDIF
                    THRESH = THRESH * 0.5
                    WRITE(IOUT,FMT=7203) THRESH
                    IF (ONLINE) WRITE(ITOUT,FMT=7203) THRESH
                    IF (THRESH.GT.1) GOTO 902
                  ELSE
C
C---- apparently no image loaded!
C
                    IF(SOCKLO) THEN
                      WRITE(XMLLINE, 1235) 
     $                     templsav(1:lenstr(templsav)),
     $                     id
                      CALL WRITE_SOCKET_LENGTH(SERVERFD, 
     +                     LENSTR(XMLLINE), XMLLINE)
                    END IF
                    GOTO 50
                  END IF
 1235             format('<?xml version="1.0"?><!DOCTYPE ',
     +                 'spot_search_response>',
     &                 '<spot_search_response>',
     $                 '<status><code>error</code>',
     &                 '<message>No image (dimension 0)',
     +                 '</message></status>',
     $           '<image_template>',A,'</image_template>',
     $           '<image_number>',I8,'</image_number>',
     &                 '</spot_search_response>')
                END IF
 7203           FORMAT(/,1X,'Threshold decreased to:',F8.1)
C     
C---- okay, reasonable number found?
C     
                  FOUND(I) = .TRUE.
                  IF (I.EQ.1) THEN
                     IF ((ISEP.EQ.0).OR.(ISEP.EQ.3).OR.
     +                                         (IRAST.EQ.0)) THEN
                        MODEGSR = 0
                        IF (DEBUG(79)) THEN
                          WRITE(IOUT,FMT=6120) I,MODEGSR
                          IF (ONLINE) WRITE(ITOUT,FMT=6120) I,MODEGSR
 6120                     FORMAT(/,1X,'Calling GETSEPRAS for image',I5,
     +                        ' with MODEGSR=',I3)
                        END IF
C
C---- Print for program flow
C  
                        CALLED = 'GETSEPRAS'
                        COMMENT = ' '
                        IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                        CALL GETSEPRAS(IRAST,ISEP,IRAS,ID,MINDTX,MINDTY,
     +                       IXSEP,IYSEP,MODEGSR,IERR)
                        
                        IF (IERR.NE.0) THEN
                           NSHUTERR = 3
                           CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
                        END IF
                     END IF
                  END IF
C     
                  SELECT(I) = .TRUE.
               ENDIF
            ENDIF
 9000       CONTINUE
            FOUND(I) = .TRUE.
          ENDIF
 900      ENDDO
C     
C---- Restore original identifier
C     
         IDENT = SIDENT
C     
C---- Now save spots in new format for autoindexing
C     
         IF(DOFIND.AND..NOT.AUTOINDX)THEN
            IFLAG = 1
            NCH = LENSTR(IDENT)
            IF (NCH.GT.0) THEN
               IF(.NOT.USERSPOT)SPTNAM = IDENT(1:LENSTR(IDENT))//'.spt'
            END IF
C     
C---- Need new style spots list
C     
c     hrp 20.10.2004            IF(.NOT.USERSPOT)THEN
            NEWSPT = .TRUE.
            ISPOT = 10
            IF (DEBUG(79)) THEN
              WRITE(IOUT,FMT=6200)
              IF (ONLINE) WRITE(ITOUT,FMT=6200)
 6200         FORMAT(/,1X,'Writing spots file')
            END IF
C
C---- Set soft fail for CCPDPN if using new GUI, otherwsie hard fail.
C
            IF (SOCKLO) THEN
              IFAIL = 1
            ELSE
              IFAIL = 0
            END IF
            CALL CCPDPN (ISPOT,SPTNAM,'UNKNOWN','F',80,IFAIL)
C
C---- Trap file open error for new GUI
C
            IF (IFAIL.LT.0) THEN
              RETURN
            ELSE
              IFAIL = 0
            END IF
C
C---- Print for program flow
C  
            CALLED = 'WSPOT'
            COMMENT = 'write spots to file, when not autoindex'
            IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
            CALL WSPOT(IFLAG)
            NSOL = 0
            IERRFLG = 0
c     hrp 20.10.2004            ENDIF
         ENDIF
C     
C---- Now save spots in new format for autoindexing
C     
         IF(AUTOINDX)THEN
               IFLAG = 1
               NCH = LENSTR(IDENT)
               IF (NCH.GT.0) THEN
                  IF(.NOT.USERSPOT)
     $                 SPTNAM = IDENT(1:LENSTR(IDENT))//'.spt'
               END IF
C     
C---- Need new style spots list
C     
               IF(DOFIND)THEN
                  NEWSPT = .TRUE.
                  ISPOT = 10
                  IF (DEBUG(79)) THEN
                    WRITE(IOUT,FMT=6200)
                    IF (ONLINE) WRITE(ITOUT,FMT=6200)
                  END IF
C
C---- Set soft fail for CCPDPN if using new GUI, otherwise hard fail.
C
                  IF (SOCKLO) THEN
                    IFAIL = 1
                  ELSE
                    IFAIL = 0
                  END IF
                  CALL CCPDPN (ISPOT,SPTNAM,'UNKNOWN','F',80,IFAIL)
C
C---- Trap file open error for new GUI
C
                  IF (IFAIL.LT.0) THEN
                    RETURN
                  ELSE
                    IFAIL = 0
                  END IF
C
C---- Print for program flow
C  
                  CALLED = 'WSPOT'
                  COMMENT = 'Save spots in new format for indexing'
                  IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL WSPOT(IFLAG)
C
C---- Trap case wheN no spots have been written to file (IFLAG.EQ.-1)
C
                  IF (IFLAG.EQ.-1) GOTO 50
                  NSOL = 0
                  IERRFLG = 0
c               ENDIF
            ENDIF
C     
C---- If a cell has been given and need to be kept, save it here.
C     
            IF (CELLKEEP) THEN
               DO 910 I = 1,6
                  SAVECELL(I) = CELL(I)
 910           CONTINUE
            END IF
C     
            BOXOPEN = .FALSE.
            IF(DPSINDEX)THEN
               IERRFLG = 0
               IF(NSOL.NE.-999)THEN
                  NSOL = -999
                  IF (DEBUG(79)) THEN
                    WRITE(IOUT,FMT=6210) LSOL,NSOL,SOLN
                    IF (ONLINE) WRITE(ITOUT,FMT=6210) LSOL,NSOL,SOLN
 6210               FORMAT(/,1X,'Calling DPSIND, LSOL=',L1,
     +                      ' NSOL=',I4,' SOLN=',I4)
                  END IF
C
C---- Print for program flow
C  
                  CALLED = 'DSPIND'
                  COMMENT = 'to do indexing'
                  IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL DPSIND(NSOL,MAXCELL,MINCELL)
                  if(lsol.and.soln.eq.0)then
                     nsol = -999
                     autoindx = .false.
                     DOFIND = .FALSE.
                     goto 50
                  endif
               endif
               IF(IERRFLG.EQ.0)THEN
                  IF(SOLN.NE.0)NSOL = SOLN+100
                  IF (DEBUG(79)) THEN
                    WRITE(IOUT,FMT=6212) LSOL,NSOL,SOLN
                    IF (ONLINE) WRITE(ITOUT,FMT=6212) LSOL,NSOL,SOLN
 6212               FORMAT(/,1X,'Calling DPSCHOOSE, LSOL=',L1,
     +                      ' NSOL=',I4,' SOLN=',I4)
                  END IF
C
C---- Print for program flow
C  
                  CALLED = 'DSPCHOOSE'
                  COMMENT = ' '
                  IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
                  CALL DPSCHOOSE(NSOL,MAXCELL,MINCELL)
                  SAVMATSTR = 'autoindexing'
                  SAVMATNAM = NEWMATNAM
C     
C---- save everything now
C     
                  IF(SAVIND)CALL SAVEINP
C     
C---- if we called TO_DPS_INDEX with an unknown space group, and the
C     indexing 
C     has been successful, we need to store a SYMM line in the list of
C     stored 
C     lines of input. SYMMIN should be changed to reflect the fact that
C     a 
C     spacegroup has now been supplied, but this is only to prevent a
C     duplicate 
C     SYMM line appearing in the list.
C     
                  IF(.NOT.SYMMIN)THEN
                     J = 1
                     K = 1
                     DO 915 I=1,NTLINE - 1,1
                        LINE = INLINE(J)
                        CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,
     $                       IDEC,NTOK)
                        KEY6 = LINE(IBEG(1):IEND(1))
                        CALL CCPUPC(KEY6)
                        IF(KEY6.EQ.'AUTOIN')THEN
                           WRITE(IOUT,FMT=6712)SPGNAM,NUMSPG
                           IF(ONLINE)WRITE(ITOUT,FMT=6712)SPGNAM,NUMSPG
                        ELSE
                           INLINE(K) = INLINE(J)
                           K = K + 1
                        ENDIF
                        J = J + 1
 915                 ENDDO
                     IF(K.NE.0)THEN
                        WRITE(INLINE(K),FMT=6708)SPGNAM
                        NTLINE = NTLINE + 1
                     ENDIF
 6708                FORMAT('SYMM ',A)
 6712                FORMAT('Storing space group from DPS autoind',
     $                    'exing: ',A,' number ',I3)
                     SYMMIN = .TRUE.
                  ENDIF
               ENDIF
c     hrp19122001
               AUTOINDX = .FALSE.
c     gw16may02
c     NODISPLAY = .FALSE.
            ELSE
C
C---- Print for program flow
C  
               CALLED = 'REFIX'
               COMMENT = ' '
               IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
               CALL TOREFIX(NSOL,BOXOPEN,RFIXCELL,RFIXDIST)
            END IF
C     
C---- *** IMPORTANT *** ICELL is set to zero after calling TOREFIX
C     
C---- Trap failure
C     
            IF (IERRFLG.EQ.1) THEN
c     this should not be the case - a warning about a blank image should
c     be issued and the mosflm job should return to it's inital state.

c     CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))

               write(*, *) 'An error occurred while indexing - read',
     $             ' the warning messages and take appropriate action'

c               if(socklo) then
c                  write(xmlline, 1234) 
c                  call write_socket_length(serverfd, 
c     +                 lenstr(xmlline), xmlline)
c               end if
c 1234          format('<?xml version="1.0"?><!DOCTYPE status><status>',
c     +              '<code>error</code><message>Possible blank image',
c     +              '</message></status>')
               

               goto 50

            END IF
C     
C---- Restore cell if required
C     
            IF (CELLKEEP) THEN
               DO 912 I = 1,6
                  CELL(I) = SAVECELL(I)
 912           CONTINUE
C     
C---- Need to set ICELL flag so cell is kept when SETMAT is called
C     
               ICELL = 1
            END IF
C     
C---- Set missetting angles to zero, in case a MATRIX has been supplied
C     which has non-zero missets
C     
            DO 914 I = 1,3
               DELPHI(I) = 0.0
 914        CONTINUE
         ENDIF
C
C---- having found spots, explicitly set DOFIND = .FALSE.                  
C
         DOFIND = .FALSE.
C     
C---- Mosaicity estimation
C     
         IF(MOSEST)THEN
           IF(WINOPEN)THEN
             MOSIMAG = 1
           ELSE
            IF(MOSIMAG.EQ.0)MOSIMAG = NOIMG(1)
           ENDIF
           
            IF (DEBUG(79)) THEN
              WRITE(IOUT,FMT=6230) MOSIMAG,id,nimag,
     $             phibeg,phiend,phirng
              IF (ONLINE) WRITE(ITOUT,FMT=6230) MOSIMAG,id,nimag,
     $             phibeg,phiend,phirng
 6230         FORMAT(/,1X,'Calling MOSEST for image',3I7,3f8.2)
            END IF
C
C---- Print for program flow
C  
            CALLED = 'ESTMOS'
            COMMENT = ' '
            IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
            CALL ESTMOS(MOSIMAG,IPACK,GENOPEN,IERR)
C     .. return if too few spots
            IF(IERR.EQ.-2)RETURN
            NLINE = NLINE + 1
         ENDIF
C
C---- PICK command (for new GUI)
C
         IF(PICKLOG)THEN
C
C---- If a summed image is displayed, need to look in IMAGE2 even if
C     this is an HDF5 file, as summed HDF5 images are now stored in IMAGE2
C
CAL           IF ((NIMGSUMDISP.GT.1).AND.(.NOT.HDF5FILE)) THEN
           IF (NIMGSUMDISP.GT.1) THEN
C
C---- Print for program flow
C  
            CALLED = 'PICKIT'
            COMMENT = 'using IMAGE2 summed image array '
            IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
             CALL PICKIT(PICKER,IMAGE2,NREC,IYLEN,IERR)
           ELSE
C     
C---- need to make sure the right image is open
C     
C
C---- Print for program flow
C  
            CALLED = 'OPENODS'
            COMMENT = ' need to make sure right image is open'
          WRITE(STRING,FMT=6005) ID,MODEOP
          COMMENT = COMMENT(1:LENSTR(COMMENT))//
     +              STRING(1:LENSTR(STRING))//' LIPROCESS=5'
            IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
             LIPROCESS = 5
             CALL OPENODS(IDENT,ID,FILM,ODEXT,FDISK,MODEOP,
     +          PACK,ODFILE,SEPCHAR,FORCEREAD,IPACK,
     +          TEMPLSTART,TEMPLEND,LIPROCESS,IERR)
            CALLED = 'PICKIT'
            COMMENT = 'using IMAGE array '
            IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
             CALL PICKIT(PICKER,IMAGE,NREC,IYLEN,IERR)
           END IF
           PICKLOG = .FALSE.
C     ..
C     .. unset NSER
           NSER = 0
           IERR = 50
           RETURN
         ENDIF
C     
C         IF(.NOT.DOFIND)IMAT = 1
         IF(DPSDONE)IMAT = 1
         POWDER = .FALSE.
         NIMAGES = 0
         NIMAG = 0
         DONERUN = .TRUE.
C     
C---- Restore saved values of ADDPART,SUMPART,POSTREF
C     
         ADDPART = SADDPART
         SUMPART = SSUMPART
         POSTREF = SPOSTREF

C     
C---- If no images to be processed, return for further input
C     
         IF (NSER.EQ.0)THEN
            GOTO 50
         ENDIF
C     
         IERR = 920
C     
C---- End of  "IF ((.NOT.ONLINE).OR.(NODISPLAY)) THEN"
C     
      END IF
C     ..
C     .. return to control.f
C     
C---- Restore saved values of ADDPART,SUMPART,POSTREF
C     
       ADDPART = SADDPART
       SUMPART = SSUMPART
       POSTREF = SPOSTREF
      IF (DEBUG(79)) THEN
        WRITE(IOUT,FMT=6240) IERR,POWDER,NODISPLAY,AUTOINDX,POSTREF
        IF (ONLINE) WRITE(ITOUT,FMT=6240) IERR,POWDER,NODISPLAY,
     +              AUTOINDX,POSTREF
 6240   FORMAT(/,1X,'Exiting from IFPWDR, IERR=',I4,' POWDER=',L1,
     +     ' NODISPLAY=',L1,' AUTOINDX=',L1,' POSTREF=',L1)
      END IF
      RETURN
 50   CONTINUE
C     
C---- we want to set a flag here so we go to further input when we
C     return to control.f
      IERR = 50
C     
C---- Restore saved values of ADDPART,SUMPART,POSTREF
C     
       ADDPART = SADDPART
       SUMPART = SSUMPART
       POSTREF = SPOSTREF
      IF (DEBUG(79)) THEN
        WRITE(IOUT,FMT=6242) IERR,POWDER,NODISPLAY,AUTOINDX,POSTREF
        IF (ONLINE) WRITE(ITOUT,FMT=6242) IERR,POWDER,NODISPLAY,
     +              AUTOINDX,POSTREF
 6242   FORMAT(/,1X,'Exiting from IFPWDR after GOTO 50',
     +         '  IERR=',I4,' POWDER=',L1,
     +     ' NODISPLAY=',L1,' AUTOINDX=',L1,' POSTREF=',L1)
      END IF
      RETURN
C     
 6716 FORMAT(/,1X,'****** ERROR ******',/,1X,'No IDENT or TEMPLATE',
     +     ' keywords have been given.',/,1X,
     +     '(used as a template to form image file names.)',/,/) 
      END
C== IMGINV ==
      SUBROUTINE IMGINV(IMAGE,NXPIX,NYPIX,ICONST)
C
      IMPLICIT NONE
C     Invert image left to right (that is mirror in the slow direction)
C     and at the same time add the constant value ICONST to all pixel
C     values. This is called for packed MAR images (machine MAR345)
C     and also for Rigaku Pilatus and Eiger images (machine RIPI, RIEI).
C
C     ..
C     .. Scalar Arguments ..
      INTEGER NXPIX,NYPIX,ICONST
C     ..
C     .. Array Arguments ..
      INTEGER*2 IMAGE(NYPIX,NXPIX)
C     ..
C     .. Local Scalars ..
      INTEGER I,J,IOD,NXPIXD2,NXP,IOD2
      LOGICAL ADDALL
C
C     .. Common blocks ..
C
C      WRITE(6,FMT=1000)
C      WRITE(8,FMT=1000)
 1000 FORMAT(/,1X,'*** imginv called ***')
      ADDALL = (ICONST.NE.0)
      NXPIXD2 = NXPIX/2
      DO 10 I = 1,NXPIXD2
        NXP = NXPIX - I + 1
        DO 20 J = 1,NYPIX
          IF (ADDALL) THEN
            IOD = IMAGE(J,I)
            IF (IOD.GE.0) THEN
              IOD = IOD  + ICONST
            ELSE
              IOD = -(-IOD*8 + ICONST)/8
            END IF
            IOD2 = IMAGE(J,NXP)
            IF (IOD2.GE.0) THEN
              IOD2 = IOD2  + ICONST
            ELSE
              IOD2 = -(-IOD2*8 + ICONST)/8
            END IF
            IMAGE(J,I) = IOD2
            IMAGE(J,NXP) = IOD
          ELSE
            IOD = IMAGE(J,I)
            IMAGE(J,I) = IMAGE(J,NXP)
            IMAGE(J,NXP) = IOD
          END IF
 20     CONTINUE
 10   CONTINUE
      RETURN
      END
C $Id: imgmake.f,v 1.3 2003/05/15 09:36:47 harry Exp $
      SUBROUTINE IMGMAKE(NTDIG,ID,IMGNUM)
C     ===================================
C
C---- set up image number as a string
C     
C     NTDIG        Number of digits in image number (input)
C     ID           Image number (input)
C
      IMPLICIT NONE
C
C
C     .. Parameters ..
C&&*&& include  ../inc/mxdinc.f
C
C $Id: mxdinc.f,v 1.1 2002/05/02 10:47:00 harry Exp $
C
C--- awk generated include file  mxdinc.h
C---- START of include file mxdinc.h
C
C
c common block for mxd routines: various parameters for XDL routines
c
c     base_width    width of base frame
c     base_height   height of base frame
c     men_x,men_y   position of menu area
c     par_x,par_y   position of parameter area
C     

C     IORDER    (R)   Order of the data in the input image 
c                with respect to two local axes ax1, ax2 e.g.
c                (xf, yf) as a number from 1 to 8.
c                    1   +ax1 slow   +ax2 fast    (+xf, +yf)
c                    2   +ax1 slow   -ax2 fast    (+xf, -yf)
c                    3   -ax1 slow   +ax2 fast    (-xf, +yf)
c                    4   -ax1 slow   -ax2 fast    (-xf, -yf)
c                    5   +ax2 slow   +ax1 fast    (+yf, +xf)
c                    6   +ax2 slow   -ax1 fast    (+yf, -xf)
c                    7   -ax2 slow   +ax1 fast    (-yf, +xf)
c                    8   -ax2 slow   -ax1 fast    (-yf, -xf)
c
c
c     JORDER    (R)   Display order with respect to the two
c                local axes (1 to 8) along the X-windows
c                axes X horizontal (left to right), Y vertical 
c                (top to bottom ) with origin at top left
c                1  +ax1 X (horiz)   +ax2 Y (vert)   (+xf, +yf)
c                2  +ax1 X (horiz)   -ax2 Y (vert)   (+xf, -yf)
c                3  -ax1 X (horiz)   +ax2 Y (vert)   (-xf, +yf)
c                4  -ax1 X (horiz)   -ax2 Y (vert)   (-xf, -yf)
c                5  +ax2 X (horiz)   +ax1 Y (vert)   (+yf, +xf)
c                6  +ax2 X (horiz)   -ax1 Y (vert)   (+yf, -xf)
c                7  -ax2 X (horiz)   +ax1 Y (vert)   (-yf, +xf)
c                8  -ax2 X (horiz)   -ax1 Y (vert)   (-yf, -xf)
c                    
c                    (2 was standard for Laue programs)
c
c     nxp_cmp       number of pixels compressed to 1 in horizontal
c                   display direction
c     nyp_cmp       number of pixels compressed to 1 in vertical
c                   display direction
c     nxdpx         number of horizontal pixels in displayed image
c     nydpx         number of vertical pixels in displayed image
c     img_horiz     image direction for horizontal display (=1 fast, 2 slow)
c     img_vert      image direction for vertical display   (=1 fast, 2 slow)
c     img_map(4)    mapping of image to display
c                    imgmap(1)   1st point on fast axis (Yms)
c                    imgmap(2)   1st point on slow axis (Zms)
c                    imgmap(3)   increment on fast axis
c                    imgmap(4)   increment on slow
c     img_x,img_y   x, y position of image
c     men_x, men_y  x, y position of menu
c     par_x, par_y  x, y position of parameter table
c     io_x, io_y    x, y position of IO area
c     not_x, not_y    x, y position of notice area (parameter table
c                     with no values)
c     pmn_x, pmn_y  x, y position of popup abort menu
c     ppb_x, ppb_y  x, y position of popup progress bar
c     busy_x, busy_y x, y position of busy window
c     img_width,img_height   width, height of image window
c     men_width, men_height  width, height of menu window  
c     par_width, par_height  width, height of parameter window
c     io_width, io_height    width, height of IO window
c     not_width, not_height  width, height of notice area
c     pmn_width, pmn_height  width, height of Abort menu
c     ppb_width              width of progress bar
c     busy_width, busy_height  width, height of busy box
c     sub_process    .true. if program is sub-process of eg clips, .false.
c                    if standalone
c
C     IFTYPE      1 = unsigned byte data
C                 2 = unsigned two-byte data (i2)
C                 3 = signed integer data
C                 4 = 'squashed i2' data (if Intensity>32767 
C                    store as 65536-Intensity/8)
      INTEGER BASE_WIDTH,BASE_HEIGHT,
     $     IMAGE_ORDER,JIMAGE_ORDER,NXP_CMP,NYP_CMP,
     $     NXDPX,NYDPX,
     $     IMG_HORIZ,IMG_VERT,IMG_MAP(4),
     $     IMG_X,IMG_Y,MEN_X,MEN_Y,PAR_X,PAR_Y,IO_X,IO_Y,
     $     NOT_X,NOT_Y,PMN_X, PMN_Y,PPB_X, PPB_Y, BUSY_X, BUSY_Y,
     $     BUSY_Y2,IFTYPE
      INTEGER IMG_WIDTH, IMG_HEIGHT, MEN_WIDTH, MEN_HEIGHT,
     $     PAR_WIDTH, PAR_HEIGHT, IO_WIDTH, IO_HEIGHT,
     $     NOT_WIDTH, NOT_HEIGHT, PMN_WIDTH, PMN_HEIGHT,
     $     PPB_WIDTH, BUSY_WIDTH, BUSY_HEIGHT
      LOGICAL SUB_PROCESS, BLANK
C

c  DON'T forget to declare function xdlstr as integer
      INTEGER XDLSTR
      EXTERNAL XDLSTR

c
c     ivhbas        view object handle for base frame
c     ivhimg        view object handle for image
c     ivhpar        view object handle for parameter table
c     ivhmen        view object handle for menu
c     ivhio         view object handle for io area
c     ivhio2        view object handle for second io area (pick option)
c     ivhio3        view object handle for third io area (output)
c     ivhnot        view object handle for notice area (parameter table)
c     ivhpmn        view object handle for popup wait menu
c     ivhppb        view object handle for popup progress bar
c     ivhblank      view object handle for blank object
c     ivhbusy       view object handle for busy object
c     ivhbusy2      view object handle for second (2 line) busy object
      INTEGER IVHBAS, IVHIMG, IVHPAR, IVHMEN, IVHIO, IVHNOT, IVHPMN,
     $     IVHPPB, IVHBLANK, IVHBUSY, IVHIO2, IVHBUSY2, IVHIO3
      PARAMETER (IVHBAS=1, IVHIMG=2, IVHPAR=3, IVHMEN=4, IVHIO=5,
     $     IVHNOT=6, IVHPMN=7, IVHPPB=8, IVHBLANK=9, IVHBUSY=10,
     $     IVHIO2=11, IVHBUSY2=12, IVHIO3=13)

c  Border  boundary between windows
      INTEGER BORDER
      PARAMETER (BORDER = 4)

c     icset   colour set number
      INTEGER ICSET
      PARAMETER (ICSET=1)
c
c     iord    axis order of image
c             = 1  xf slow, yf fast
      INTEGER IORD
      PARAMETER (IORD = 1)
c
c     minw,minh   minimum width and height for image display object
      INTEGER MINW,MINH
      PARAMETER (MINW=0, MINH=0)
c
c     ixopix, iyopix      pixel origin of displayed part
      INTEGER IXOPIX,IYOPIX
      PARAMETER (IXOPIX=1, IYOPIX=1)
c
c     ibg     background menu, =0 for none
      INTEGER IBG
      PARAMETER (IBG=0)
c
c     iovly   overlay option
      INTEGER IOVLY
      PARAMETER (IOVLY=1)
c
c     max_pixel   maximum number of pixels to use for image display:
c                 this will be used to control possible compression
c                 of the image
      INTEGER MAX_PIXEL
      PARAMETER (MAX_PIXEL = 800)
c  Image stuff
c     disp_img        true if image has been displayed
c
      LOGICAL DISP_IMG
c
c     ifd     file descriptor, = -1 for no file
      INTEGER IFD
      PARAMETER (IFD=0)
c

c  Parameter table stuff
c     max_par_col     maximum number of parameter columns
c     max_par_rows    maximum number of parameter rows
c     max_par_name    maximum length of name
c     max_par_str     maximum value length
c     par_title       = -1 no title +1 title present
c     par_font        font (3=medium)
c     par_menu        = 1 if popup menus allowed
c     disp_par        true if parameter table hsa been displayed
c
      LOGICAL DISP_PAR
      INTEGER MAX_PAR_COL, MAX_PAR_ROWS, MAX_PAR_NAME, MAX_PAR_STR,
     $        PAR_TITLE, PAR_FONT, PAR_MENU
      PARAMETER (MAX_PAR_COL = 1, MAX_PAR_ROWS = 50,
     $           MAX_PAR_NAME = 17, MAX_PAR_STR = 7,
     $           PAR_TITLE = 1, PAR_FONT = 2, PAR_MENU = 0)
C
c  Menu stuff
c     max_men_itms    maximum number of menu items
c     max_men_name    maximum number of characters in menu item
c     men_font        menu font number (3=medium)
c     men_quit_flag   = 1 to allow for quit box
c     max_men_title   maximum length of menu title
c     disp_menu       true if menu displayed
      LOGICAL DISP_MENU
      INTEGER MAX_MEN_ITMS, MAX_MEN_NAME, MEN_FONT, MEN_QUIT_FLAG,
     $        MAX_MEN_TITLE 
      PARAMETER (MAX_MEN_ITMS = 19, MAX_MEN_NAME = 19, MEN_FONT = 4,
     $     MEN_QUIT_FLAG = 1, MAX_MEN_TITLE = 9)

c
c IO area stuff
c     io_font         font number
c     disp_io         true if io area displayed
c     disp_io2        true if SECOND io area displayed
c     disp_io3        true if THIRD io area displayed
C     NSCROLL         number of pages to hold for scrolling
      LOGICAL DISP_IO,DISP_IO2,DISP_IO3
      INTEGER IO_FONT,NSCROLL
      PARAMETER (IO_FONT=2)
      PARAMETER (NSCROLL=0)


c  Notice area stuff (notice area is a parameter table with no values)
c     max_not_col     maximum number of parameter columns
c     max_not_rows    maximum number of parameter rows
c     max_not_name    maximum length of name
c     max_not_str     maximum value length
c     not_title       = -1 no title +1 title present
c     not_font        font (3=medium)
c     not_menu        = 1 if popup menus allowed
c     disp_not       true if menu displayed
      LOGICAL DISP_NOT
      INTEGER MAX_NOT_COL, MAX_NOT_ROWS, MAX_NOT_NAME, MAX_NOT_STR,
     $        NOT_TITLE, NOT_FONT, NOT_MENU
      PARAMETER (MAX_NOT_COL = 1, MAX_NOT_ROWS = 18,
     $           MAX_NOT_NAME = 23,
     $           MAX_NOT_STR = 0,
     $           NOT_TITLE = +1, NOT_FONT = 2, NOT_MENU = 0)
c
c  Menu stuff for Abort menu
c     max_pmn_itms    maximum number of menu items
c     max_pmn_name    maximum number of characters in menu item
c     pmn_font        menu font number (3=medium)
