C     ivhlist(1)  menu
C     ivhlist(2)  parameters
C     ivhlist(3)  image
      INTEGER NUMVH, IVHLIST,IVH, NUMVH2, IVHLIST2
c  npx     number of points in box
      INTEGER NPX
      INTEGER IVECB, IVECC
C    .. local scalars ..
      INTEGER IMXD,JMXD,IQUIT,ISTAT,MEASUR,ITEM,IX,IY,L,M,JY,JZ,NSOL,
     $     NADDS,MODEG,NFULLF,MASKMODE,IMASKRING
      INTEGER IX1,IY1,IX2,IY2,IX3,IY3,IX4,IY4,IX5,IY5,
     $     JY2,JZ2, IZOOM, MEASPT, 
     +     NORDER,IXM, IYM, IXP, IYP, KFLAG, IBUTTON,IFLAG, IISIZE,
     +     NDISPP,IRECG,IJUNK,IFAIL,NCH,NCH2,MODEOP,ID,NFIRSTI,MODESP,
     +     MODECTRL,IPACKF,IPACKL,NSERLOC,LINELEN,NUMLIN,IPAUSE,
