C TILEX  X Coordinates of the midpoints of the null areas between tiles
C TILEY  Y Coordinates of the midpoints of the null areas between tiles
C TILEWX Width of the null areas between tiles in X
C TILEWY Width of the null areas between tiles in Y


C MACHINE and MODEL denote the type of detector.
C DECTRIS_TYPE can be PILATUS, EIGER1 or EIGER2. It is used when setting up
C the positions of the gaps between the tiles.
C
C MACHINE is used in the following subroutines:
C GETBLK, GETHDR, INTPXL, INTPXL2, MXDSPL, OPENODS, PROCESS, PUTPXL
C Currently coded types are:
C
C         MACHINE        MODEL               COMMENTS
C         =======        =====               ========
C         MAR            180, 300, 345
C         RAXI(S)        RAXISII, RAXISIV
C         MD
C         FUJI
C         CCD1           CCD1                Princetown CCD at CHESS,Tiff format
C         CCD2           CCD ?               ESRF CCD detector
C         ADSC           QUAD1               ADSC 2x2 CCD detector
C
C TRUSTED whether or not the image header information can be trusted for 
C         automatic processing
C MICROED indicates whether or not this is electron diffraction data,
C        base on the wavelength being less than 0.05A
C
C
C     .. Scalars in Common Block /LMB/ ..
        REAL ODSCAL,GAIN,LOGA,LOGB
        INTEGER ISCAL,IDIVIDE,ICONST,NULLPIX,NTILEX,NTILEY,
     $       RAXISCOMP,IIDIVIDE,COMPRESSION,GAPVAL,IINVERTX
        LOGICAL IMGP,INVERTX,SPIRAL,ORTHOG,CIRCULAR,TILED,SETADC,
     $       NEWRAXIS,BRUKNEW,TRUSTED,MINICBF,HDF5FILE,GAPMASK,
     $       WRONGGAPVALUE,MICROED
        CHARACTER MACHINE*4,MODEL*8,LDETECTOR*20,DECTRIS_TYPE*10,
     +       CMACHINE*40

C     ..
C     .. Arrays in common /LMB/
        INTEGER TILEX,TILEY,TILEWX,TILEWY
C
C     .. Common Block /LMB/ ..
        COMMON /LMB/ ODSCAL,GAIN,LOGA,LOGB,ISCAL,IDIVIDE,ICONST,
     $       NULLPIX,NTILEX,NTILEY,RAXISCOMP,IIDIVIDE,COMPRESSION,
     $       GAPVAL,IINVERTX,TILEX(20),TILEY(20),TILEWX(20),TILEWY(20),
     $       IMGP,INVERTX,SPIRAL,ORTHOG,CIRCULAR,
     $       TILED,SETADC,NEWRAXIS,BRUKNEW,TRUSTED,MINICBF,HDF5FILE,
     $       GAPMASK,WRONGGAPVALUE,MICROED
        COMMON /LMBC/ MACHINE,MODEL,LDETECTOR,DECTRIS_TYPE,CMACHINE

C&&*&& end_include  ../inc/lmb.f
C
      INTEGER IBA
C
      IBA = IPIXEL

      IF (IBA.LT.0) THEN
C
C---- Pilatus detectors have many pixels that need to be decoded (e.g. the 
C     gaps between tiles), so it makes sense to test for them first. 
C
        IF (COMPRESSION .EQ. 6) THEN
          IF(IBA.EQ.GAPVAL)THEN
            IBA = -1
          ELSEIF (IBA .GT. -3 ) THEN 
            IBA = IBA
          ELSE IF (IBA .GT. -6148) THEN
            IBA = -(IBA - 2045) * 16
          ELSE IF (IBA. GT. -32765) THEN
            IBA = -(IBA + 5124) * 128
          ELSE
            IBA = 3538100
          ENDIF
        ELSEIF (COMPRESSION .EQ. 1) THEN
          IBA = -IBA*8
        ELSEIF (COMPRESSION .EQ. 2) THEN
          IBA = -IBA*32
        ELSEIF (COMPRESSION .EQ. 3) THEN
          IF (MACHINE.EQ.'RAXI') THEN
            IF(.NOT.NEWRAXIS)THEN
C     ..
C     .. old-style Rigaku R-AXIS (but allow for new Raxis II header)
              IF ((MODEL.EQ.'RAXIS  ').OR.(MODEL.EQ.'RAXIS2NU')) THEN
                IBA = (32768+IBA)*8
              ELSE IF ((MODEL.EQ.'RAXISIV').OR.(MODEL.EQ.'RAXISV')
     $               .OR.(MODEL.EQ.'RAXISHTC')) THEN
                IBA = (32768+IBA)*32
              ELSE
                WRITE(IOUT,FMT=6010) MODEL
                IF (ONLINE) WRITE(ITOUT,FMT=6010) MODEL
 6010           FORMAT(1X,'***** unknown model for RAXIS scanners:',A)
                STOP
              END IF
            ELSE
C     ..
C     .. new-style Rigaku R-AXIS
              IF(RAXISCOMP.NE.-1)THEN
                IBA = (32768+IBA)*RAXISCOMP
              ELSE
                IBA = IBA + 65536
              ENDIF
            ENDIF
          ELSE
C     ..
C     .. Jupiter, Saturn, Mercury, A200
              IF(RAXISCOMP.NE.-1)THEN
                IBA = (32768+IBA)*RAXISCOMP
              ELSE
                IBA = IBA + 65536
              ENDIF
          ENDIF
        ELSEIF (COMPRESSION .EQ. 4) THEN
          IBA = IBA + 65536
        ELSEIF (COMPRESSION .EQ. 5) THEN
          IF (MODEL.EQ.'16BIT') THEN
            IBA = -(IBA+1)*32
          ELSE IF (MODEL.EQ.'12BIT') THEN
            IBA = -(IBA+1)*256 + 32768
          ELSE IF(MODEL.EQ.'16BITD') THEN
            IBA = -(IBA+1)*32
          ELSE
            IBA = IBA+65536
          END IF
C
C
C===============================================================
C HRP - 18.12.2008 - nothing after here should be relevant any more - 
C                    we should plan on deleting this code!
C
        ELSE IF ((MACHINE.EQ.'MAR ').OR.(MACHINE.EQ.'FUJI')
     $         .OR.(MACHINE.EQ.'BRUK')) THEN
          IBA = -IBA*8
        ELSE IF (MACHINE.EQ.'RAXI') THEN
          IF(.NOT.NEWRAXIS)THEN
C     ..
C     .. old-style Rigaku R-AXIS
            IF (MODEL.EQ.'RAXIS  ') THEN
              IBA = (32768+IBA)*8
            ELSE IF ((MODEL.EQ.'RAXISIV').OR.(MODEL.EQ.'RAXISV')
     $             .OR.(MODEL.EQ.'RAXISHTC')) THEN
              IBA = (32768+IBA)*32
            ELSE
              WRITE(IOUT,FMT=6010) MODEL
              IF (ONLINE) WRITE(ITOUT,FMT=6010) MODEL
              STOP
            END IF
          ELSE
C     ..
C     .. new-style Rigaku R-AXIS
              IF(RAXISCOMP.NE.-1)THEN
                IBA = (32768+IBA)*RAXISCOMP
              ELSE
                IBA = IBA + 65536
              ENDIF
          ENDIF
        ELSE IF (MACHINE.EQ.'MD') THEN
          IBA = IBA + 65536
        ELSE IF (MACHINE.EQ.'DIP2') THEN
          IF (MODEL.EQ.'16BIT') THEN
            IBA = -(IBA+1)*32
          ELSE IF (MODEL.EQ.'12BIT') THEN
            IBA = -(IBA+1)*256 + 32768
          ELSE IF(MODEL.EQ.'16BITD') THEN
            IBA = -(IBA+1)*32
          ELSE
            IBA = IBA+65536
          END IF
        ELSE IF (MACHINE.EQ.'CCD1') THEN
          IBA = -IBA*8
        ELSE IF (MACHINE.EQ.'CCD2') THEN
          IBA = -IBA*8
        ELSE IF (MACHINE.EQ.'LMB') THEN
          IBA = -IBA*8
        ELSE IF (MACHINE.EQ.'ADSC') THEN
          IBA = -IBA*8
        ELSE IF (MACHINE.EQ.'SBC1') THEN
          IBA = -IBA*8
        ELSE IF (MACHINE.EQ.'NOIR') THEN
          IBA = -IBA*8
        ELSE IF (MACHINE.EQ.'TAUR') THEN
          IBA = -IBA*8
        ELSE IF (MACHINE.EQ.'MARC') THEN
          IBA = -IBA*8
        ELSE IF (MACHINE.EQ.'MARF') THEN
          IBA = -IBA*32
        ELSE IF (MACHINE.EQ.'LIPS') THEN
          IBA = -IBA*8
        ELSE IF ((MACHINE.EQ.'JUPI').OR.(MACHINE.EQ.'SATU').OR.
     $         (MACHINE.EQ.'MERC').OR.(MACHINE.EQ.'A200')) THEN
          IF(RAXISCOMP.NE.-1)THEN
            IBA = (32768+IBA)*RAXISCOMP
          ELSE
            IBA = IBA + 65536
          ENDIF
        ELSE IF (MACHINE.EQ.'CBF ')THEN
          IBA = -IBA*8
        ELSE IF (MINICBF)THEN
          if (iba .gt. -3 ) then 
            iba = iba
          else if (iba .gt. -6148) then
            iba = -(iba - 2045) * 16
          else if (iba. gt. -32765) then
            iba = -(iba + 5124) * 128
          else
            iba = 3538100
          endif
        ELSE IF (MACHINE.EQ.'OXFO') THEN
          IBA = IBA + 65536
C     
C---- "UNKNOWN" scanner type, stored as -I/8
C     
        ELSE IF (MACHINE.EQ.'UNK') THEN
          IBA = -IBA*8
        ELSE
C     
C---- Put decoding for new scanner types here, MACHINE is assigned using
C     SCANNER TYPE keywords
C     
        END IF
      END IF
      INTPXL = IBA
      RETURN
      END
