          ELSE IF (MODEL.EQ.'12BIT') THEN
            IBA = -(IBA+1)*256 + 32768
          ELSE IF(MODEL.EQ.'16BITD') THEN
            IBA = -(IBA+1)*32
          ELSE
            IBA = IBA+65536
          END IF
        ELSEIF (COMPRESSION .EQ. 6) THEN
          IF (IBA .GT. -3 ) THEN 
