C&&*&& end_include  ../inc/spots2.f
C     ..
C     .. External Functions ..
      INTEGER LENSTR
      EXTERNAL LENSTR
      DATA IRMSTOLER / 0 /,IHKLDEV/0/,IPRUNE/0/
C     ..
      IERR = 0
      CALLEDFROM = 'KWAUTOIN'
      OVERRIDE = .FALSE.
      MULTILATT = .FALSE.
      PRUNE = .FALSE.
C     ***** Redundant parameter ? ****
c     This variable never used, keyword HKLDEV
C     sets parameter HKLDEV which seems to be used for this. AGWL 27/8/12
      MAXDEV = 0.25
C
      MAXTHRESH = 32767
C     
C---- decode this line again
C     
c      CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C     
C---- Not allowed if inputting keywords via menu
C     
c
c ---- TAKANORI: unset PRIOR CELL
      DO 999 II = 1,6
         PRIORCELL(II) = 0
 999  CONTINUE
c ---- set default centering from SYMM keyword
c ---    P centering (H)
c     print*, 'isys=', ISYS, 'ksys=', KSYS
      CENTERING = 0
      IF (ISYS.EQ.4) THEN
c ----   F centering
         CENTERING = 4
      ELSE IF (ISYS.EQ.2) THEN
c ----   A, B, C or I centering
        IF (KSYS(1).EQ.0) THEN
           CENTERING = 1
         ELSE IF (KSYS(2).EQ.0) THEN
            CENTERING = 2
         ELSE IF (KSYS(3).EQ.0) THEN
            CENTERING = 3
         ELSE
c ----    I centering
            CENTERING = 5
         ENDIF
      ELSE IF (ISYS.EQ.3) THEN
c ----    H centering
         CENTERING = 6
      ENDIF
      IF (MODE.EQ.3) THEN
        WRITE(IOUT,FMT=6100)
        WRITE(ITOUT,FMT=6100)
        LINE = ' '
        WRITE(LINE,FMT=6600)
        CALL MXDWIO(LINE,2)
        RETURN
      END IF
      AUTOINDX = .TRUE.
      POWDER = .TRUE.
      USERSPOT = .FALSE.
C     .. always initialize this every time
      MAXNREF = NSPOTS
C      IF(.NOT.FOUND.AND.DOFIND)DOFIND = .FALSE.
      IF(.NOT.SDPSINDEX)THEN 
        DPSINDEX = .FALSE.
        MAXCELL = 0.0
        MINCELL = 0.0
      ENDIF
      IF(DPSDONE.AND.NSOL.NE.-999)THEN
C     
C---- zero image counters etc
C     
        NRUN = 0
        NAUTO = 0
        DO 1000 ICOUNT=1,MAXIMG,1
CHRP 15.05.2013          IDAUTO(ICOUNT) = 0
          NOIMG(ICOUNT) = 0
 1000   ENDDO
        DPSDONE = .FALSE.
      ENDIF
      IF(LSOL)THEN
        NSOL = -999
        DO 1005 ICOUNT=1,20,1
CHRP 15.05.2013           IF(.NOT.FOUND(ICOUNT).and.idauto(icount).ne.0)DOFIND = .TRUE.
           IF(.NOT.FOUND(ICOUNT).and.NOIMG(icount).ne.0)DOFIND = .TRUE.
 1005   ENDDO
      ENDIF
C      DOFIND = .TRUE.
      LSOL = .FALSE.
      RFIXCELL = .FALSE.
      RFIXDIST = .TRUE.
      NMULTI = 0
      SOLN = 0
C     
      ICOUNT = 1
      DO 1200 WHILE(ICOUNT.LT.NTOK)
        ICOUNT = ICOUNT + 1
        KEY8 = LINE(IBEG(ICOUNT):IEND(ICOUNT))
C     **************
        CALL CCPUPC(KEY8)
C     **************
        SUBKEY = KEY8
C     
C---- Background REFIX indexing (default)
C     
        IF (SUBKEY.EQ.'RFX ') THEN
          DPSINDEX = .FALSE.
          SDPSINDEX = DPSINDEX
C     
C---- Background DPS (FFT) indexing
C     
        ELSE IF (SUBKEY.EQ.'DPS ') THEN
C     
C---- only allow this without display!
C     
          NODISPLAY = .TRUE.
          DPSINDEX = .TRUE.
          SDPSINDEX = DPSINDEX
c     hrp er - this should allow resetting the cell between 
c     indexing runs in the same job - we'll see
          IF(LSOL)NSOL = 0
          LSOL = .FALSE.
          SIGMOID = .FALSE.
C     
C---- store the user cell in KCELL if we are DPS indexing in background
C  
          IF(NSOL.NE.-999)THEN
            IF((CELL(1).GT.1E-3).AND.(CELL(2).GT.1E-3).AND.
     $           (CELL(3).GT.1E-3).AND.(CELL(4).GT.1E-3).AND.
     $           (CELL(5).GT.1E-3).AND.(CELL(6).GT.1E-3))THEN
              KCELL(1) = CELL(1)
              KCELL(2) = CELL(2)
              KCELL(3) = CELL(3)
              KCELL(4) = CELL(4)
              KCELL(5) = CELL(5)
              KCELL(6) = CELL(6)
              MAXCELL = MAX(CELL(1),CELL(2))
              MAXCELL = MAX(MAXCELL,CELL(3))
              KWDCELL = .TRUE.
            ELSE
              MAXCELL = 0.0
              KWDCELL = .FALSE.
            ENDIF  
            WRITE(IOUT,6800)
            IF(ONLINE)WRITE(ITOUT,6800)
          ENDIF
C     
C---- IMAGES...specifies which images to use
C     
        ELSE IF (SUBKEY.EQ.'IMAG') THEN
C          IF(DOFIND.AND.NSOL.NE.-999)THEN
C            NAUTO = 0
c            DOFIND = .FALSE.
C          ENDIF
          DO 1100 WHILE ((ICOUNT.LT.NTOK).AND.(ITYP(ICOUNT+1).EQ.2))
            NAUTO = NAUTO + 1
            ICOUNT = ICOUNT + 1
C     *******************************************
            CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
            IF (NAUTO.LE.MAXIMG) THEN
C     ..
C     .. need to check that this image hasn't already been given
              IF(NAUTO.GT.1)THEN
                ICHECK = 0
                DO 1050 IC=1,NAUTO-1
CHRP 15.05.2013                  IF(IDAUTO(IC).EQ.NINT(VALUE(ICOUNT)))ICHECK = 1
                  IF(NOIMG(IC).EQ.NINT(VALUE(ICOUNT)))ICHECK = 1
 1050           ENDDO
                IF(ICHECK.EQ.0)THEN
CHRP 15.05.2013                  IDAUTO(NAUTO) = NINT(VALUE(ICOUNT))
                  NOIMG(NAUTO) = NINT(VALUE(ICOUNT))
                ELSE
                  NAUTO = NAUTO - 1
                END IF
              ELSE
CHRP 15.05.2013                IDAUTO(NAUTO) = NINT(VALUE(ICOUNT))
                NOIMG(NAUTO) =  NINT(VALUE(ICOUNT))
              ENDIF
            ENDIF
            IF ((ICOUNT.LT.NTOK).AND.(ITYP(ICOUNT+1).EQ.2))NMULTI = 1
 1100     ENDDO
C     
C---- IDENT...Specifies identifier for this image
C     
        ELSE IF (SUBKEY.EQ.'IDEN') THEN
C     
C---- Can only give one image number per IMAGE subkeyword if IDENT
C     is being supplied
C     
          IF (NMULTI.GT.0) THEN
            WRITE(IOUT,FMT=6200)
            IF (ONLINE) WRITE(ITOUT,FMT=6200)
            NSHUTERR = 1
            CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
          END IF
          ICOUNT = ICOUNT + 1
          IDENTAUTO(NAUTO) = LINE(IBEG(ICOUNT):IEND(ICOUNT))
C     
C---- TEMPLATE...Specifies identifier for this image
C     
        ELSE IF (SUBKEY.EQ.'TEMP') THEN
C     
C---- Can only give one image number per IMAGE subkeyword if TEMPLATE
C     is being supplied
C     
          IF (NMULTI.GT.0) THEN
            WRITE(IOUT,FMT=6300)
            IF (ONLINE) WRITE(ITOUT,FMT=6300)
            NSHUTERR = 2
            CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
          END IF
          ICOUNT = ICOUNT + 1
          TEMPLAUTO(NAUTO) = LINE(IBEG(ICOUNT):IEND(ICOUNT))
C     
C---- PHI...gives phi range for this image
C     
        ELSE IF (SUBKEY.EQ.'PHI') THEN
          IF (NMULTI.GT.0) THEN
            WRITE(IOUT,FMT=6400)
            IF (ONLINE) WRITE(ITOUT,FMT=6400)
            NSHUTERR = 3
            CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
          END IF
          
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(2,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
          PHI1 = VALUE(ICOUNT)
          ICOUNT = ICOUNT + 1
          PHI2 = VALUE(ICOUNT)
          phibeg = phi1
          phiend = phi2
          PHISET(NAUTO) = .TRUE.
          PHI(NAUTO) = 0.5*(PHI1+PHI2)
          PHIRNGA(NAUTO) = ABS(PHI2-PHI1)
          phistim(nauto) = phi1
Chrp 25.07.2005 needed for estmos...
chrp10.02.2009          ISTRT = 1
chrp10.02.2009          IANGLE = 1
C
C---- I/sigma(I) threshold - have to make sure autothresh is off
C
        ELSE IF (SUBKEY.EQ.'THRE') THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          ITHRESH = NINT(VALUE(ICOUNT))
          AUTOTHRESH = .FALSE.
C
C---- Maximum I/sigma(I) threshold - for picking weak spots among strong - 
C
        ELSE IF (SUBKEY.EQ.'MAXT') THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          MAXTHRESH = NINT(VALUE(ICOUNT))
chrp 25.03.2010 do we need this?          AUTOTHRESH = .FALSE.
C
C---- maximum number of reflections per image
C
        ELSE IF (SUBKEY.EQ.'MAXN') THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          MAXNREF = NINT(VALUE(ICOUNT))
C     
C---- NODISPLAY to simulate batch job when running online
C     
        ELSE IF (SUBKEY.EQ.'NODI') THEN
          NODISPLAY = .TRUE.
C     
C---- Fix cell parameters - but do the refinement anyway to get values
C     for shifts
C     
        ELSE IF (SUBKEY.EQ.'FIXC') THEN
          RFIXCELL = .TRUE.
C     
C---- Refine detector distance
C     
        ELSE IF (SUBKEY.EQ.'UNFI') THEN
          RFIXDIST = .FALSE.
C     
C---- Fix cell parameters; don't refine anything - this is currently a toggle
C     
        ELSE IF (SUBKEY.EQ.'NORE') THEN
          INDNOREF = .NOT.INDNOREF
          WRITE(IOUT,6700).NOT.INDNOREF
          IF(ONLINE)WRITE(ITOUT,6700).NOT.INDNOREF
C     
C---- Allow user to pre-refine all DPS solutions with penalty <= 100 in
C     background 
C     
        ELSE IF (SUBKEY.EQ.'REFI')THEN
          PREREF = .TRUE.
          NODISPLAY = .TRUE.
          DPSINDEX = .TRUE.
          WRITE(IOUT,7300)
          IF(ONLINE)WRITE(ITOUT,7300)
C     
C---- only use the RMS residual in choosing the 'best' solution - implies 
C     'REFINE'
C     
        ELSE IF (SUBKEY.EQ.'RMSO')THEN
          RMSONLY = .TRUE.
          PREREF = .TRUE.
          NODISPLAY = .TRUE.
          DPSINDEX = .TRUE.
          WRITE(IOUT,7300)
          IF(ONLINE)WRITE(ITOUT,7300)
C
C---- allow threshold for the above - 
C
        ELSE IF (SUBKEY.EQ.'RMST')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          IF(ITYP(ICOUNT).EQ.2)RMSTOLER = VALUE(ICOUNT)
C     
C---- Allow user to pre-refine the triclinic basis  solution before 
C     applying Bravais lattice symmmetry, only for DPS
C     
        ELSE IF (SUBKEY.EQ.'PRER')THEN
          ICOUNT = ICOUNT + 1
          SUBKEY = LINE(IBEG(ICOUNT):IEND(ICOUNT))
          CALL CCPUPC(SUBKEY)
          IF(SUBKEY.EQ.'ON')THEN
            TRIREF = .TRUE.
            WRITE(IOUT,7600)
            IF(ONLINE)WRITE(ITOUT,7600)
          ELSEIF(SUBKEY.EQ.'OFF')THEN
            TRIREF = .FALSE.
            WRITE(IOUT,7650)
            IF(ONLINE)WRITE(ITOUT,7650)
          ELSE
            WRITE(IOUT,7660)TRIREF
            IF(ONLINE)WRITE(ITOUT,7660)TRIREF
          ENDIF
          NODISPLAY = .TRUE.
          DPSINDEX = .TRUE.
C     
C---- Extra output including distortion index, only for DPS
C     
        ELSE IF (SUBKEY.EQ.'EXTR')THEN
           ICOUNT = ICOUNT + 1
            SUBKEY = LINE(IBEG(ICOUNT):IEND(ICOUNT))
            CALL CCPUPC(SUBKEY)
            IF(SUBKEY.EQ.'ON  ')THEN
               DODEN = .TRUE.
               WRITE(IOUT,7700)
               IF(ONLINE)WRITE(ITOUT,7700)
            ELSE
               DODEN = .FALSE.
               WRITE(IOUT,7750)
               IF(ONLINE)WRITE(ITOUT,7750)
            ENDIF
            NODISPLAY = .TRUE.
            DPSINDEX = .TRUE.
C     
C---- Maximum cell edge for FFT indexing
C     
        ELSE IF (SUBKEY.EQ.'MAXC')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          MAXCELL = VALUE(ICOUNT)
          NODISPLAY = .TRUE.
          DPSINDEX = .TRUE.
          IF(MAXCELL.GT.1E-2)THEN
            WRITE(IOUT,6900)INT(MAXCELL)
            IF(ONLINE)WRITE(ITOUT,6900)INT(MAXCELL)
          ELSE
            WRITE(IOUT,6910)
            IF(ONLINE)WRITE(ITOUT,6910)
          ENDIF

C     
C---- Minimum cell edge for FFT indexing
C     
        ELSE IF (SUBKEY.EQ.'MINC')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          MINCELL = VALUE(ICOUNT)
          IF(MINCELL.LE.MAXCELL)MAXCELL = 1.2 * MINCELL
          NODISPLAY = .TRUE.
          DPSINDEX = .TRUE.
          IF(MINCELL.GT.1E-2)THEN
            WRITE(IOUT,6920)INT(MINCELL)
            IF(ONLINE)WRITE(ITOUT,6920)INT(MINCELL)
          ELSE
            WRITE(IOUT,6930)
            IF(ONLINE)WRITE(ITOUT,6930)
          ENDIF

C     
C---- Allow user to pick a solution from the list - only valid for DPS
C     indexing
C     
        ELSE IF (SUBKEY.EQ.'SOLU')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          SOLN = VALUE(ICOUNT)
          NODISPLAY = .TRUE.
          DPSINDEX = .TRUE.
          LSOL = .TRUE.
          IF(SOLN.EQ.0)THEN
            NSOL = 0
            EXPLICIT_CELL = .FALSE.
            DO II=1,6
              CELL(II) = KCELL(II)
            ENDDO
            IF(CELL(1).GT.0.0)EXPLICIT_CELL = .TRUE.
          ENDIF
C     
C---- external spot file for use in autoindexing (DPS only)
C     
        ELSE IF (SUBKEY.EQ.'FILE')THEN
          ICOUNT = ICOUNT + 1
          SPTNAM = LINE(IBEG(ICOUNT):IEND(ICOUNT))
          USERSPOT = .TRUE.
          DOFIND = .FALSE.
C     
C---- Save results from background indexing in a file
C     
        ELSE IF (SUBKEY.EQ.'SAVE') THEN
          SAVIND = .TRUE.
C     
C---- turn on ice (and other) ring exclusion from autoindexing - doesn't
C     affect what's done in spotfinding
C     
        ELSE IF (SUBKEY.EQ.'EXCL')THEN
          ICOUNT = ICOUNT + 1
C     
C---- initially we will allow four modes - 'NONE', 'ICE', 'AUTO' and
C     explicit ranges - RINGTEST = 5 is reserved for use in MXDSPL
          IF(ITYP(ICOUNT).EQ.1)THEN
            SUBKEY = LINE(IBEG(ICOUNT):IEND(ICOUNT))
            CALL CCPUPC(SUBKEY)
            IF(SUBKEY.EQ.'NONE')THEN
              RINGTEST = 0
              DPSEXCL = 0
            ELSEIF(SUBKEY.EQ.'ICE ')THEN
              RINGTEST = 1
            ELSEIF(SUBKEY.EQ.'AUTO')THEN
              RINGTEST = 2
            ENDIF
          ELSEIF(ITYP(ICOUNT).EQ.2)THEN
            IF(ITYP(ICOUNT+1).EQ.2)THEN
              RINGTEST = 3
              DPSEXCL = DPSEXCL + 1
              IF (DPSEXCL.GT.10) THEN
                WRITE(IOUT,FMT=7500)
                IF (ONLINE) WRITE(ITOUT,FMT=7500)
              ELSE
                IF(VALUE(ICOUNT).GT.VALUE(ICOUNT+1))THEN
                  DPSXLO(DPSEXCL) = VALUE(ICOUNT)
                  DPSXHI(DPSEXCL) = VALUE(ICOUNT+1)
                ELSE
                  DPSXLO(DPSEXCL) = VALUE(ICOUNT+1)
                  DPSXHI(DPSEXCL) = VALUE(ICOUNT)
                ENDIF
              ENDIF
              ICOUNT = ICOUNT + 1
            ENDIF
          ENDIF
C
C---- add an optional SD cutoff for spots when refining a solution -
C     required for new GUI
        ELSE IF (SUBKEY.EQ.'SDCU')THEN
          ICOUNT = ICOUNT + 1
          IF(ITYP(ICOUNT).EQ.2)THEN
            SDCUTOFF = VALUE(ICOUNT)
          ENDIF
C
C---- toggle multiple lattices on
C
        ELSE IF (SUBKEY.EQ.'MULT')THEN
          MULTILATT = .TRUE.
          IF(IHKLDEV.EQ.0)THEN
            HKLDEV = 0.20
          ENDIF
          IF(IPRUNE.EQ.0)PRUNE = .TRUE.
          SOLN = 0
          NODISPLAY = .TRUE.
          DPSINDEX = .TRUE.
          LSOL = .TRUE.
          NSOL = 0
          EXPLICIT_CELL = .FALSE.
          CELL(1) = 0.0
          CELL(2) = 0.0
          CELL(3) = 0.0
C
C---- toggle multiple lattices off
C
        ELSE IF (SUBKEY.EQ.'NOMU')THEN
          MULTILATT = .FALSE.
C
C---- Choose which lattice DPS MULTI has found that we want to look at -
C     required for new GUI
        ELSE IF (SUBKEY.EQ.'LATT')THEN
          ICOUNT = ICOUNT + 1
          IF(ITYP(ICOUNT).EQ.2)THEN
            NLATTICE = VALUE(ICOUNT)
          ENDIF
C
C---- choose cutoff based on error in HKL or error in image XY
C     default = HKL
C
          
        ELSE IF (SUBKEY.EQ.'CHOO')THEN
           ICOUNT = ICOUNT + 1
            SUBKEY = LINE(IBEG(ICOUNT):IEND(ICOUNT))
            CALL CCPUPC(SUBKEY)
            IF(SUBKEY(1:3).EQ.'HKL')THEN
               CHOOSEHKL = .TRUE.
               WRITE(IOUT,7900)
               IF(ONLINE)WRITE(ITOUT,7900)
            ELSEIF(SUBKEY(1:2).EQ.'XY')THEN
               CHOOSEHKL = .FALSE.
               WRITE(IOUT,7950)
               IF(ONLINE)WRITE(ITOUT,7950)
             ELSE
               CHOOSEHKL = .TRUE.
               WRITE(IOUT,7900)
               IF(ONLINE)WRITE(ITOUT,7900)
            ENDIF
C     
C---- Recycle reflections from the "clean" list that now have a large 
C     error
C     
        ELSE IF (SUBKEY.EQ.'RECY')THEN
           ICOUNT = ICOUNT + 1
            SUBKEY = LINE(IBEG(ICOUNT):IEND(ICOUNT))
            CALL CCPUPC(SUBKEY)
            IF(SUBKEY(1:2).EQ.'ON')THEN
               RECYCLE = .TRUE.
               WRITE(IOUT,7800)
               IF(ONLINE)WRITE(ITOUT,7800)
            ELSEIF(SUBKEY(1:3).EQ.'OFF')THEN
               RECYCLE = .FALSE.
               WRITE(IOUT,7850)
               IF(ONLINE)WRITE(ITOUT,7850)
             ELSE
               RECYCLE = .FALSE.
               WRITE(IOUT,7850)
               IF(ONLINE)WRITE(ITOUT,7850)
            ENDIF

C
C---- Upper threshold for indexing error for a reflection before adding 
C     it to a new list for multiple lattice indexing.
C     ***** Redundant keyword ? ****
c     This variable never used, keyword HKLDEV
C     sets parameter HKLDEV which seems to be used for this. AGWL 27/8/12
C
        ELSE IF (SUBKEY.EQ.'MAXD')THEN
          ICOUNT = ICOUNT + 1
          IF(ITYP(ICOUNT).EQ.2)THEN
            MAXDEV = VALUE(ICOUNT)
          ENDIF
C
C---- Percentage of the starting list of spots unindexed for use in 
C     multiple lattice indexing. "UNINDEXED"
        ELSE IF (SUBKEY.EQ.'UNIN')THEN
          ICOUNT = ICOUNT + 1
          UNINDEXED = NINT(VALUE(ICOUNT))
C
C---- "enhanced" discrimination of low penalty solutions from high
C
        ELSE IF (SUBKEY.EQ.'SIGM')THEN
           SIGMOID = .TRUE.
C
C---- prune out reflections which have a large rmsd from observed
C
         ELSE IF (SUBKEY.EQ.'PRUN')THEN
           PRUNE = .TRUE.
           IPRUNE = 1
         ELSE IF (SUBKEY.EQ.'NOPR')THEN
           PRUNE = .FALSE.
           IPRUNE = 1
C     
C---- use threshold determined by PICKSPOTS (to get a minimum number
C     of spots)
C     
        ELSE IF (KEY8.EQ.'AUTOTHRE')THEN
           AUTOTHRESH = .TRUE.
        ELSE IF (KEY8.EQ.'NOAUTOTH')THEN
           AUTOTHRESH = .FALSE.

C
C---- Additional parameters used in DPS indexing:
C     OVERRIDE   allow these parameters to be set using old GUI interactively
C     Parameters affecting selection and refinement of vectors
C     NVECT      Number of vectors to be selected from grid search for refinement (30)
C     NVREF      After initial refinement, number of vectors to be refined further (30)
C     CONV       Minimum step size to be used in refinement (radians) (0.0004)
C     MAXCycle   Maximum number of cycles for refinement (10)
C     INICycle   Number of initial cycles of refinement before selecting NVREF (3)
C     NMAT
C     STEPSCAL   Scalar multiplier for calculated step size in refinement (1.0)
C     DMAXSCAL   Scalar multiplier for calculated dmax (used to set step size) (1.5)
C     MAXRLPS    numrlp .. does not seem to be used (2000)
C     MAXSPOTS   numsptdps.. does not seem to be used (2000)
C     FFTPEAKS   In FFTs, minimum number of peaks to be found before looking for
C                multiples.(6)
C     PKMULT     In FFTs, minimum number of orders for a "real" peak, eg if 
C                this has a value of 2, then peaks at d, 2d,3d must all be found (2)
C     THETAS  Theta1 theta2  Calc an FFT for the explicit theta1,theta2
C
C     Parameters affecting the choice of three basis vectors
C     SINTHMIN    Min value of triple sin product as fraction of max value (0.5)
C     VOLMIN      Min value of cell volume as fraction of product of cell edges (0.5)
C     HKLDEV      Max deviation from integer for indices (0.3)
C     HKLMIN      Min number of indexeed reflections as fraction of max. (0.6)
C
C     Debug flags
C     DUMPFFT1    Write FFTs at an early stage
C     DUMPFFT2    Write FFTs at an intermediate stage
C     DUMPFFT3    Most useful one, write out FFTs after final refinement
C     NODUMPFFT   Turn off all writing of FFTs
C
C     DUMPGEN     Write debug output during grid search
C     DUMPVEC     Write debug output of vector lists
C     DUMPREF     Write debug ouput for refinement of vectors
C     NODUMPGEN,NODUMPVEC,NODUMPREF   Turn off above debug output
C
C     DUMPCH      Write debug output from ind_choose
C
        ELSE IF (SUBKEY.EQ.'OVER')THEN
          OVERRIDE = .TRUE.
        ELSE IF (SUBKEY.EQ.'NVEC')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          NUMVECT = VALUE(ICOUNT)
C
C---- Max number of vectors allowed is set by  N_TVECTOR which is set
C     by a #DEFINE statement in dps code, index_def.h, currently 150
C
          IF (NUMVECT.GT.150) NUMVECT = 150
        ELSE IF (SUBKEY.EQ.'NVRE')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          NUMVECTREF = VALUE(ICOUNT)
        ELSE IF (SUBKEY.EQ.'CONV')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          CONVRG = VALUE(ICOUNT)
c
c     TAKANORI: prior cell
c     CELL a b c alpha beta gamma
c---- Harry suggests using current CELL and SYMM keywords to set up values,
C     then something like 'PRIOR', 'USER', 'KNOWN', to trigger Takanori's code
        ELSE IF (SUBKEY.EQ.'TAKA')THEN
          do 124 II=1,6
            PRIORCELL(II) = KCELL(II)
 124      ENDDO

        ELSE IF (SUBKEY.EQ.'CELL')THEN
C     *******************************************
          CALL MKEYNM(6,ICOUNT + 1,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
        DO 123 II = 1,6
           ICOUNT = ICOUNT + 1
           PRIORCELL(II) = VALUE(ICOUNT)
 123    CONTINUE
c     TAKANORI: prior cell centering
c     CENTERED A (A, B, C, I, F, P, R, H are accepted) 
        ELSE IF (SUBKEY.EQ.'CENT')THEN
           ICOUNT = ICOUNT + 1
           SUBKEY = LINE(IBEG(ICOUNT):IEND(ICOUNT))
           IF (SUBKEY.EQ.'A' .OR. SUBKEY.EQ.'a')THEN
              CENTERING = 1
           ELSE IF (SUBKEY.EQ.'B' .OR. SUBKEY.EQ.'b')THEN
              CENTERING = 2
           ELSE IF (SUBKEY.EQ.'C' .OR. SUBKEY.EQ.'c')THEN
              CENTERING = 3
           ELSE IF (SUBKEY.EQ.'F' .OR. SUBKEY.EQ.'f')THEN
              CENTERING = 4
           ELSE IF (SUBKEY.EQ.'I' .OR. SUBKEY.EQ.'i')THEN
              CENTERING = 5
           ELSE IF (SUBKEY.EQ.'P' .OR. SUBKEY.EQ.'p' .OR. 
     $              SUBKEY.EQ.'R' .OR. SUBKEY.EQ.'r') THEN
              CENTERING = 0
           ELSE IF (SUBKEY.EQ.'H' .OR. SUBKEY.EQ.'h')THEN
              CENTERING = 6
           ELSE
              WRITE(IOUT,FMT=8000)
           END IF

        ELSE IF (SUBKEY.EQ.'MAXC')THEN
C
C---- HRP 01.08.2014 This is NEVER run - 'MAXC' is a keyword above for maximum
C     cell edge (since 2001...)!
C
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          MAXCYC = VALUE(ICOUNT)
        ELSE IF (SUBKEY.EQ.'INIC')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          INICYC = VALUE(ICOUNT)
        ELSE IF (SUBKEY.EQ.'STEP')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          STEPSCAL = VALUE(ICOUNT)
        ELSE IF (SUBKEY.EQ.'DMAX')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          DMAXSCAL = VALUE(ICOUNT)
        ELSE IF (SUBKEY.EQ.'MAXR')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          NUMRLP = VALUE(ICOUNT)
        ELSE IF (SUBKEY.EQ.'MAXS')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          NUMSPTDPS = VALUE(ICOUNT)
        ELSE IF (SUBKEY.EQ.'FFTP')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          NPKFFTMIN = VALUE(ICOUNT)
        ELSE IF (SUBKEY.EQ.'PKMU')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          NMULTFFT = VALUE(ICOUNT)
        ELSE IF (SUBKEY.EQ.'THET')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(2,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          THETA1D = VALUE(ICOUNT)
          THETA2D = VALUE(ICOUNT+1)
          THETADMP = .TRUE.
        ELSE IF (SUBKEY.EQ.'SINT')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          SINTHMIN = VALUE(ICOUNT)
        ELSE IF (SUBKEY.EQ.'VOLM')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          VOLMIN = VALUE(ICOUNT)
        ELSE IF (SUBKEY.EQ.'HKLD')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          HKLDEV = VALUE(ICOUNT)
          IHKLDEV = 1
        ELSE IF (SUBKEY.EQ.'HKLM')THEN
          ICOUNT = ICOUNT + 1
C     *******************************************
          CALL MKEYNM(1,ICOUNT,LINE,IBEG,IEND,ITYP,NTOK)
C     *******************************************
C     
          HKLMIN = VALUE(ICOUNT)

        ELSE IF (KEY8.EQ.'DUMPFFT1')THEN
          DUMPFFT(1) = .TRUE.
        ELSE IF (KEY8.EQ.'DUMPFFT2')THEN
          DUMPFFT(2) = .TRUE.
        ELSE IF (KEY8.EQ.'DUMPFFT3')THEN
          DUMPFFT(3) = .TRUE.
        ELSE IF (KEY8.EQ.'NODUMPFF')THEN
          DO 1120 II = 1,3
            DUMPFFT(II) = .FALSE.
 1120     CONTINUE
        ELSE IF (KEY8.EQ.'DUMPVEC')THEN
          DUMPVEC = .TRUE.
        ELSE IF (KEY8.EQ.'NODUMPVE')THEN
          DUMPVEC = .FALSE.
        ELSE IF (KEY8.EQ.'DUMPREF')THEN
          DUMPREF = .TRUE.
        ELSE IF (KEY8.EQ.'NODUMPRE')THEN
          DUMPREF = .FALSE.
        ELSE IF (KEY8.EQ.'DUMPGEN')THEN
          DUMPGEN = .TRUE.
        ELSE IF (KEY8.EQ.'NODUMPGE')THEN
          DUMPGEN = .FALSE.
        ELSE IF (KEY8.EQ.'DUMPCH')THEN
          DUMPCHOOSE = .TRUE.

C     Not recognised
C     
        ELSE
          IF (TRAPERR) INPERR = .TRUE.
          IERR = 1
          WRITE (IOUT,FMT=7400) SUBKEY
          IF (ONLINE) WRITE (ITOUT,FMT=7400) SUBKEY
        END IF
 1200 ENDDO
C     
C---- If running interactively the AUTOINDEX keyword must NOT be used, 
C     (unless NODISPLAY or NOREFINE is also given).
C     This is no longer true, the 'DPS' keyword can be used in
C     interactive runs.

      IF (ONLINE.AND.(.NOT.OVERRIDE).AND.
     +                (.NOT.(NODISPLAY.OR.(SUBKEY.EQ.'NORE')))) THEN
        AUTOINDX = .FALSE.
        IF (NIMAGES.EQ.0) POWDER = .FALSE.
        WRITE(IOUT,FMT=6500)
        IF (ONLINE) WRITE(ITOUT,FMT=6500)
C     
C---- FORMATS
C     

 6100   FORMAT(1X,'**** ILLEGAL INPUT ***',/,1X,'Use the',
     +       ' "Integrate" menu option')
        
 6200   FORMAT(1X,'***** ERROR *****',/,1X,'You must only give',
     +       ' one image number on the IMAGE subkeyword if an ',/,1X
     &       ,'IDENT subkeyword is given...see Help library.')
        
 6300   FORMAT(1X,'***** ERROR *****',/,1X,'You must only give',
     +       ' one image number on the TEMPLATE subkeyword if a ',
     &       /,1X,'TEMPLATE subkeyword is given...',
     $       ' see Help library.')
        
 6400   FORMAT(1X,'***** ERROR *****',/,1X,'You must only give',
     +       ' one image number on the IMAGE subkeyword if a ',/,1X
     &       ,'PHI subkeyword is given...see Help library.')
 6500   FORMAT(/,1X,'***** ERROR *****',/,1X,'The AUTOINDEX ',
     +       'keyword should ONLY be used for backgrounded jobs.',/,1X
     &       ,'Use the IMAGE keyword and select "Autoindex" from'
     &       ,' the menu when running',/,1X,'interactively.',/,1X
     &       ,'Alternatively use keywords "AUTOINDEX NODISPLAY".')
 6600   FORMAT('Cannot use this keyword from menu.')
 6700   FORMAT('Refinement after DPS indexing has been switched',
     +       ' to ',L1)
        
 6800   FORMAT('Using DPS code for background indexing')
        
 6900   FORMAT('Using DPS code for background indexing ',
     $       'with maximum cell edge for search set to ',I4)
        
 6910   FORMAT('Using DPS code for background indexing ',
     $       'with maximum cell edge reset to program''s choice')
        
 6920   FORMAT('Using DPS code for background indexing ',
     $       'with minimum cell edge for search set to ',I4)
        
 6930   FORMAT('Using DPS code for background indexing ',
     $       'with minimum cell edge reset to zero')
        
 7000   FORMAT('Choosing solution ',i2,' from list of ',
     $       'DPS solutions')
        
 7100   FORMAT(3('**** WARNING ****',/),'IF YOU ARE CHOOSING',
     $       ' A SOLUTION YOU SHOULD ALSO CHOOSE A SPACE ',
     $       'GROUP         !',/,'The space group with the minimum ',
     $       'extra symmetry for the characteristic lattice',
     $       /,'will be used !',/,3('**** WARNING ****',/))
 7200   FORMAT(' Autoindexing from an unknown')
 7300   FORMAT('Pre-refining solutions better than penalty',
     $       ' of 200 prior to choosing a DPS solution')
 7400   FORMAT (//,1X,'********** Sub-keyword NOT Recognised:',A)
 7500   FORMAT(1X,'*** ERROR ***',/,1X,'A maximum of 10 ',
     +       'resolution ranges can be excluded.',/,1X,'The ',
     +       'remainder will be ignored')
 7600   FORMAT('Pre-refining triclinic solution before trying to',
     $       ' fit Bravais lattices')
 7650   FORMAT('NOT Pre-refining triclinic solution before trying to',
     $       ' fit Bravais lattices')
 7660   FORMAT(1X,'*** ERROR ***',/,' Subkey ''PREREFINE'' ',
     $       'requires either ''ON'' or ''OFF'' argument.',/,
     $       ' Value will remain as ',L1)
 7700   FORMAT('Printing extra distortion information')
 7750   FORMAT('NOT Printing extra distortion information')
 7800   FORMAT('Recycling deviant reflections from the clean list')
 7850   FORMAT('NOT recycling deviant reflections from the clean list')
 7900   FORMAT('Rejecting reflections based on error in HKL')
 7950   FORMAT('Rejecting reflections based on error in XY on detector')
 8000   FORMAT(1X,'*** ERROR ***',/,' Subkey ''CENTERING'' ',
     $       'requires one of A, B, C, F, H, I, P and R.')
      END IF
      RETURN
      END
      SUBROUTINE KWBEAM(LINE,MODE,COMREAD,ICOMM,IDFILM,IPROKWD,ITINS,
     $     OMEGAF,IERR)
      IMPLICIT NONE
C     
C---- routine to read BEAM keyword - replaces code in control.f
C     
C---- BEAM <nimage> [SWUNG_OUT, MU <angle>] XBEAM YBEAM 
C     <nimage> = pack number
C     SWUNG_OUT = actual position on detector swung out on two-theta arm
C     MU = angle beam differs from plane perpendicular to spindle axis
C     XBEAM, YBEAM = coordinates in mm from bottom left-hand corner in Mosflm 
C     display.
C     ..
C     .. parameters
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
      INTEGER NPARM
      PARAMETER (NPARM=200)
C     ..
C     .. includes
C&&*&& include  ../inc/condata.f
C
C $Id: condata.f,v 1.49 2021/02/11 11:30:48 andrew Exp $
C
C--- awk generated include file condata.h 
C---- START of include file condata.h 
C 
C
C     FIXSWAP     Forces reversal of normal byte-swapping choice.
C
C---- SUMPART True if two images are to be stored in memory at the
C               same time. This will be the case if post-refinement
C               (other than POSTHOC post-refinement for off-line
C               scanners) is being performed. Note that SUMPART is NOT
C               used to determine if partials should be added across
C               images (this is ADDPART)
C
C---- NEWPREF True if allowing partials over multiple images in post-
C             refinement.
C
C---- ADDPART True if partials are to be summed across images. This is
C               only appropriate for fixed origin (ie on-line)
C               scanners where the X-ray dose is identical for
C               each image.
C     Direct beam coordinates
C             These are read into XMM(3), YMM(3) where (3) is for A,B,C packs
C             Immediately on reading in, these values are transferred
C             into XCENMM, YCENMM, XCENMMIN(J,3) where J=1->MAXPAX.
C
C             If an IMAGE keyword has been given, XCENMM(1,1)=XMM(1) and
C             YCENMM(1)=YSCAL*YMM(1). If swung out, YCENMM(1,1) is updated.
C             If a BEAM keyword has not been given, XMM,YMM, XCENMM,YCENMM,
C             XCENMMIN are all set to the middle of the image.


C             Then, when reflecting input to logfile, it AGAIN sets up
C             XCENMM,YCENMM for all images using XMM,YMM, this time
C             using YSCAL to set up YCENMM, and updating YCENMM if the
C             detctor is swung out. (label 708), DO loop 710. If image
C             is "inverted", corrects XCENMM for all images.


C             XCEN,YCEN are set in "mosflm" to XCENF, YCENF plus
C             camera constants, and XCENF,YCENF are in turn set from
C             XCENMM,YCENMM. Thus XCENMM,YCENMM are what is actually
C             used to define the beam position.

C
C     LPREF   If TRUE, return to display after refinement over entire
C             image. Only active when integrating interactively. Set by
C             toggle button in Parameter window.
C

C     LOVERLAP  If TRUE, do not call the OVERLAP subroutine

C     ALLOUT  If TRUE, all reflections (whether measured or not, or
C             classified as BADSPOTS or not, will be written to the
C             output MTZ file.
C
C     NTDIG   Number of digits in image number, returned as zero if
C             there is an error in the template. Only used if TEMPLATE
C             keyword given.
C
C     TEMPLATE is TRUE if a TEMPLATE keyword has been given.
C
C     NOLP    If TRUE, do NOT apply the Lorentz Polarisation corrections
C
C     MULTIMTZ True if writing each "block" of images to a separate MTZ file
C
C     DISPMENU True if the run was started with a IMAGE keyword. Not to be
C              confused with WINOPEN which is true if the X-window display
C              is being used, but this is not necessarily starting with
C              a "IMAGE" keyword.
c     newgui - this means that we're talking through the new GUI.
c              except that we can't have it here because the prsummary 
c              subroutine, where we REALLY want it, clashes with this common
C
C     HACTIVEMASK,LACTIVEMASK,LACTIVE - only for Rigaku images which 
C     contain a compressed "active mask" (size=HACTIVEMASK bytes)
C     at the end of the image. Compression uses a modified run length encoding
C     at present (10.01.2003).
C
C     MINBATCH Minimum allowed batch number to be written to an open
C              MTZ file (MTZ library imposes that batch numbers must 
C              increase as file is written).
c
c     MERGELATT If true, prediction lists for multiple lattices will
C               be merged for output to iMosflm
C
C     NIMGSUMREF Number of images to be summed when determining spot
C                centroids for detector parameter refinement. Only
C                works for Pilatus detectors at present.
C     ..
C     .. Arrays in common /CONDATA/ ..
      REAL XCENMM,YCENMM,THFOIL,PHIBEGA,PHIENDA,RSYM,XMM,YMM,
     +     XCENMMIN,YCENMMIN
C     ..
C     .. Arrays in common /CONDATA/ ..
      INTEGER IDPACK,NFPACK,NFIRST,ICASSET
      INTEGER IPACK1A,IPACK2A,ISERAR,PICKER
      LOGICAL AVPROF,FILMPLOT,FORCEB,FORCEC,CONTROLM,CONTROLS
C
C     .. Scalars in common /CONDATA/ ..
C     ..
      REAL RMSLIM,WRMSLIM,VLIM,XMID,SEP,THICK,PTMIN,REFREJ,
     +     YSCALIN,FULLFRAC,WTIME,OVERLAPMAX
      INTEGER NPACK,NCYC,MAXNX,MAXNY,ITHRESHF,NSIG,IRFMIN,
     +        IRFINC,IXSHIFT,IYSHIFT,LIMIT,NBLOCK,INOGEN,NFGEN,MINREF,
     +        ISERADD,NSEG,NSYM,NSYMP,NRUN,NSERTOT,IWAVE,ISWUNG,
     $        IBEAMMU,ITILT,ITWIST,IPIX,IRMINXY,ICUT,IPRCUT,ILIMIT
      INTEGER IMAT,ICELL,IUMAT,LSYMM,IDIST,IBEAM,ISCAN,NLINE,NRLINE,
     +     NTLINE,NTOTLINE,ISTARTP,IRAST,INEWMAT,ISEP,NSAVELINE,IPTIME,
     +     ISTRT,IANGLE,IBACKS,IPOLAR,IDIVH,IDIVV,IGAIN,IBLOCK,
     +     IHKLOUT,IGENF,INRES,NTDIG,DELAY,IMULTI,IMISS,IMISSMAT,
     +     IIDENT,HACTIVEMASK,ITWOTHETA,MINBATCH,ILABVIEW,INVVIEW,
     $     IINVVIEW,IHKLDIR,IBGSIG,NRLEFT,WAIT,IPARTITION,ISIGSET,
     +     NSIGSAVE,ITOL,NIMGSUMREF,IBGFRAC,THISIMG,CHUNK,ICHUNK,
     $     IPTMINSET,IYSCAL
      LOGICAL FINDCC,READCC,NOFID,INTERPOL,CONVOL,NOMEAS,
     +     USEPAR,USEOVR,SUMPART,USEBOX,POSTREF,ADDPART,
     +     FIXED,POWDER,RWEIGHT,NOREF,MULTISEG,FIXSWAP,POSTHOC,
     +     LPREF,LPINTG,DISPMENU,PRMODE,PRCELL,TEMPLATE,
     +     LOVERLAP,ALLOUT,NOLP,NEWPREF,NOBACK,MOSEST,BLKEST,NUSPOT,
     $     NUBACK,NUFIND,HARVESTREADY,HEADINFO,MULTIMTZ,ANDREW, 
     +     spostref,newgui,LACTIVEMASK,USERSPOT,HEADONLY,PHIONLY,
     $     NO_XML,TESTSOCK,PICKLOG,EXPLICIT_CELL,LSIMULATE,
     $     LONGERNAME,TIMER,MERGELATT,NULLPIXTEST,KEEPNULLPIX,CCHUNK,
     +     INVXFORCEREAD
C     ..
C real arrays, then scalars, integer arrays, scalars, logicals
      COMMON /CONDATA/
     $     XCENMM(MAXPAX,3),
     +     YCENMM(MAXPAX,3), THFOIL(3),PHIBEGA(MAXPAX),
     $     PHIENDA(MAXPAX),RSYM(4,4,96),XMM(3),YMM(3),
     $     XCENMMIN(MAXPAX),YCENMMIN(MAXPAX),
     $     RMSLIM,WRMSLIM,VLIM,XMID,SEP,THICK,PTMIN,REFREJ,
     +     YSCALIN,FULLFRAC,WTIME,OVERLAPMAX,
     $     IDPACK(MAXPAX),NFPACK(MAXPAX),NFIRST(MAXPAX),
     +     ICASSET(MAXPAX),IPACK1A(50),
     +     IPACK2A(50),ISERAR(50),PICKER(4),
     $     AVPROF(MAXPAX),FILMPLOT(MAXPAX),FORCEB(MAXPAX),
     +     FORCEC(MAXPAX),
     $     NPACK,NCYC,MAXNX,MAXNY,ITHRESHF,NSIG,IRFMIN,
     +     IRFINC,IXSHIFT,IYSHIFT,LIMIT,NBLOCK,INOGEN,NFGEN,MINREF,
     +     ISERADD,NSEG,NSYM,NSYMP,NRUN,NSERTOT,IWAVE,ISWUNG,
     $     IBEAMMU,ITILT,ITWIST,IPIX,IRMINXY,ICUT,IPRCUT,ILIMIT,
     $     IMAT,ICELL,IUMAT,LSYMM,IDIST,IBEAM,ISCAN,NLINE,NRLINE,
     +     NTLINE,NTOTLINE,ISTARTP,IRAST,INEWMAT,ISEP,NSAVELINE,
     +     IPTIME,ISTRT,IANGLE,IBACKS,IPOLAR,IDIVH,IDIVV,IGAIN,IBLOCK,
     +     IHKLOUT,IGENF,INRES,NTDIG,DELAY,IMULTI,IMISS,IMISSMAT,
     +     IIDENT,HACTIVEMASK,ITWOTHETA,MINBATCH,ILABVIEW,INVVIEW,
     $     IINVVIEW,IHKLDIR,IBGSIG,NRLEFT,WAIT,IYSCAL,
     +     FINDCC,READCC,NOFID,
     +     INTERPOL,CONVOL,NOMEAS,USEPAR,USEOVR,SUMPART,USEBOX,
     +     POSTREF,spostref, ADDPART,FIXED,POWDER,RWEIGHT,NOREF,
     +     MULTISEG,FIXSWAP,POSTHOC,LPREF,LPINTG,DISPMENU,PRMODE,
