     +     CRYSTALUBREF(3,3,44,MAXLATT),CRYSTALCELL(6,44,MAXLATT),
     $     SUGGCELL(6,MAXLATT)
      INTEGER IOVLATTICE(MAXLATT),NUMSOL(MAXLATT),TOPSOLAR(MAXLATT),
     +        BESTSOLAR(MAXLATT)
