C&&*&& include  ../inc/sys.f
C
C $Id: sys.f,v 1.1 2002/05/02 10:47:21 harry Exp $
C
C--- awk generated include file  sys.h
C---- START of include file sys.h
C
C
C     .. Scalars in Common Block /SYS/ ..
      INTEGER ISYS
C     ..
C     .. Arrays in Common Block /SYS/  ..
      INTEGER KSYS
C     ..
C     ..  Common Block /SYS/ ..
      COMMON /SYS/ISYS,KSYS(3)
C     ..
C
C
C&&*&& end_include  ../inc/sys.f
C     ..
C     .. Equivalences ..
      SAVE
C     ..
C     .. Data ..
C     ..
C
      INERR = .FALSE.
C     
C---- Must trap a "null" filename
C     
        IF (NTOK.EQ.1) THEN
          WRITE(IOUT,FMT=6000) LINE(IBEG(1):IEND(1))
          IF (ONLINE) WRITE(ITOUT,FMT=6000) LINE(IBEG(1):IEND(1))
 6000     FORMAT(/,1X,'*** ERROR ***',/,1X,'Must supply a parameter',
     +         ' for keyword: ',A)
          INERR = .TRUE.
          RETURN
        END IF
C     
C---- Check if second token is alphanumeric, if so it should
C     be the file written by IDXREF containing AMAT and missetting
C     angles
C     
        IMAT = 1
        IF (ITYP(2).EQ.1) THEN
C
C---- Matrix is given as a file name
C
          IDXFILE = LINE(IBEG(2) :IEND(NTOK))
          IFAIL = 1  
C     
C     **************************************
          IF (BRIEF) THEN
            CALL CCPDPN (-3,IDXFILE,'OLD','F',80,IFAIL)
          ELSE
            CALL CCPDPN (3,IDXFILE,'OLD','F',80,IFAIL)
          END IF
C     **************************************
C     
C---- Trap file open failure
C     
          IF (IFAIL.LT.0) THEN
            WRITE(IOUT,FMT=6002)
            IF (ONLINE) WRITE(ITOUT,FMT=6002)
 6002       FORMAT(1X,'**** ERROR ****',/,1X,
     +           'Cannot open MATRIX file.')
            IMAT = 0
            INERR = .TRUE.
            RETURN
          END IF
C     
C---- If this is a new matrix for a multiple segment post-refinement,
C     need to refer the new matrix to the original one.
C     
          IF ((.NOT.FIRSTTIME).AND.(NSEG.GT.0)) THEN
C     
C---- Save original AMAT, UMAT and BMAT
C     
            DO 12 I = 1,3
              DO 10 J= 1,3
                SAMAT(I,J) = AMAT(I,J)
                SUMAT(I,J) = UMAT(I,J)
                SBMAT(I,J) = BMAT(I,J)
 10           CONTINUE
              SDELPHI(I) = DELPHI(I)
 12         CONTINUE
C     
            READ (3,FMT=6004,END=60) ((AMAT(I,J),J=1,3),I=1,3),
     +           (TDELPHI(I),I=1,3),((TJUNK(I,J),J=1,3),I=1,3),
     +           (UMATCELL(I),I=1,6)
            CLOSE (UNIT=3)
 6004       FORMAT (3F12.6)
C     
C---- Set up UMAT from new AMAT, but do not update cell parameters
C     
            IMAT = 1
            IUMAT = 0
            ICELL = 1
            ICHECK = 0
C     
C---- Call SETMAT for a new matrix of multiple segment run
C     
C     **************************
            CALL SETMAT(IMAT,IUMAT,ICELL,ICHECK)
C     **************************
            CALL MINV33(UINV,SUMAT,DET)
            CALL MATMUL3(WORK,UMAT,UINV)
            CALL ROTMAT(TDELPHI,WORK2,1)
            CALL MATMUL3(WORK3,WORK2,WORK)
            CALL RTOMISSET(WORK3,DELPHI,1)
C     
C---- Copy back original AMAT,UMAT,BMAT
C     
            DO 22 I = 1,3
              DO 20 J= 1,3
                AMAT(I,J) = SAMAT(I,J)
                UMAT(I,J) = SUMAT(I,J)
                BMAT(I,J) = SBMAT(I,J)
 20           CONTINUE
 22         CONTINUE
            WRITE(IOUT,FMT=6006) (DELPHI(I),I=1,3)
            IF (ONLINE) WRITE(ITOUT,FMT=6006) (DELPHI(I),I=1,3)
 6006       FORMAT(1X,'Missets wrt original AMAT',3F8.2)
C     
C---- Check that the new missets are within 20 degrees of the old ones,
C     because if not the post-refinement procedure will not work
C     correctly
C     because of the assumptions involved in not refining PSIX.
C     
            DET = 0.0
            DO 30 I = 1,3
              DET = MAX(DET,ABS(DELPHI(I)-SDELPHI(I)))
 30         CONTINUE
            IF (DET.GT.20.0) THEN
              WRITE(IOUT,FMT=6008) SDELPHI, DELPHI
              IF (ONLINE) WRITE(ITOUT,FMT=6008) SDELPHI, DELPHI
 6008         FORMAT(//,1X,'**** ERROR ****',/,1X,'The difference ',
     +             'between the misseting angles for the current ',
     +             'segment',/,1X,'after converting them to apply ',
     +             'to the orientation of the first segment',/,1X,
     +             'is greater than 20 degrees. Under these ',
     +             'conditions the post-refinement',/,1X,
     $             'will no longer work',/,1X,
     +             'Original missets',13X,3F12.3,/,1X,'New missets',
     +             '(after conversion)',3F12.3,/,1X,'If you have ',
     +             'used REFIX to get the orientation matrices,',
     $             ' it is possible that',
     +             /,1X,'it has selected an alternative setting fo',
     +             'rthe current segment',/,1X,'Use the UMAT keywo',
     +             'rd in REFIX to force selection of an equivalen',
     +             't setting',/,1X,'(See REFIX documentation)',/,
     $             1X,'Also make sure that the different',
     +             ' segments are relative to the SAME ',
     +             /,1X,'origin in phi (spindle setting)')
              STOP
            END IF
C     
C---- Read missets into TDELPHI in case other values have been specified
C     on a MISSETT keyword
C     
          ELSE
            SYMMLINE = ''
            READ (3,FMT=6010,END=60) ((AMAT(I,J),J=1,3),I=1,3),
     +           (TDELPHI(I),I=1,3),((TJUNK(I,J),J=1,3),I=1,3),
     +           (UMATCELL(I),I=1,6),(TDELPHI(I),I=1,3)
 6010       FORMAT (7(3F12.6,/),6F12.6,/,
     $           3F12.6)
            READ (3,FMT=6050,END=70)SYMMLINE
 6050       FORMAT(A)
C
C---- assign space group if it's there
C            
            IF(SYMMLINE .NE. ' ')THEN
              CALL MPARSE(SYMMLINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
              SYMMIN = .TRUE.
              LSYMM = 1
              CALL MRDSYMM(2,SYMMLINE,IBEG,IEND,ITYP,VALUE,NTOK,
     +             SPGNAM,NUMSPG,PGNAME,NSYM,NSYMP,RSYM,INERR)
              LATTYP = SPGNAM(1:1)

              CALL SETREFFLAGS(ICRYST,ICS,NUMSPG,LATTYP,LCELL,KSYS,ISYS) 
            ENDIF
 70         CONTINUE
            IF (IMISS.EQ.0) THEN
              DO 40 I=1,3
                DELPHI(I) = TDELPHI(I)
                IF (DELPHI(I).GT.180.00) 
     $               DELPHI(I) = DELPHI(I)-360.0
 40           CONTINUE
            END IF
C     
C     Check if cell parameters have already been specified
            IF ((ICELL.EQ.1).AND.(.NOT.RPTFIRST)) THEN
              WRITE(IOUT,FMT=6020) 
              IF (ONLINE) WRITE(ITOUT,FMT=6020) 
 6020       FORMAT (' ** BEWARE ** Cell parameters read from CELL',
     +           ' card will overwrite those read',/,1X,
     $           'from file')
            END IF
C     
C     Check if missetts have been read from MISSET card
C     
            IF (IMISS.EQ.1) THEN
              WRITE(IOUT,FMT=6030) 
              IF (ONLINE) WRITE(ITOUT,FMT=6030) 
 6030       FORMAT (' ** BEWARE ** missetting angles read from ',
     +           'MISSET  card will overwrite those read',/,1X,
     $           'from the file')
            END IF
            IMISSMAT = 1
            CLOSE (UNIT=3)
          END IF
        ELSE
C
C---- MATRIX is given as 9 numbers 
C     
C     ************************************
          CALL MKEYNM(9,2,LINE,IBEG,IEND,ITYP,NTOK)
C     ************************************
C     
          N = 1
C     
C     
          DO 50 I = 1,3
            DO 52 J = 1,3
              N = N + 1
              AMAT(I,J) = VALUE(N)
 52         CONTINUE
 50       CONTINUE
        END IF
C
C---- If this is a batch job and no indexing has been done, CRYSTALUBREF will
C     not have been set up. If this is a multilattice processing, then using 
C     the lattice number specified on the LATTICE keyword and arbitrarily assigning
C     a solution number of 1 for this lattice, set up CRYSTALUBREF for this lattice
C
        IF ((NLATTICE.GT.1).AND.(.NOT.UBREFSET)) THEN
          ISOL = 1
          BESTSOLAR(ILATTICE) = ISOL
          DO J =1,3
            DO K =1,3
              CRYSTALUBREF(J,K,ISOL,ILATTICE) = AMAT(J,K)
            ENDDO
          ENDDO
        END IF

C      

C
        RETURN
C     
 60     CONTINUE
        WRITE(IOUT,FMT=6040) IDXFILE
        IF (ONLINE) WRITE(ITOUT,FMT=6040) IDXFILE
 6040   FORMAT (//,1X,'******* End of file when reading matrix and ',
     +       'missetting angles from ',A,'  *******')
        IMAT = 0
        INERR = .TRUE.


      RETURN
      END
