C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C     ..
C     .. External Subroutines
      EXTERNAL CCPUPC
C     ..
C     .. External functions
      EXTERNAL LENSTR
      INTEGER LENSTR
C     ..
C     ..
        IF(IMAT.EQ.0)THEN
          WRITE(IOUT,FMT=7388)
          IF(ONLINE)WRITE(ITOUT,FMT=7388)
 7388     FORMAT(/,1X,5(' ***** ERROR'),' *****',/,' The SIMULATE ',
     $         'keyword can only be used once Mosflm has a matrix ',
     $         'in memory.',/,' You must read a matrix in (MATRIX ',
     $         'keyword) or autoindex before trying',/,' to produc',
     $         'e a simulated spot list',/,1X,65('*'))
        ELSE
          
          ICOUNT = 2
          SUBKEY = LINE(IBEG(ICOUNT):IEND(ICOUNT))
          CALL CCPUPC(SUBKEY)
          SPTNAM = 'simulated.spt'
C     
C---- FILE - allow the user to specify the spot filename
C     
          IF (SUBKEY.EQ.'FILE') THEN
            ICOUNT = ICOUNT + 1
C     .. allow numeric names...
c     IF(ITYP(ICOUNT).EQ.1)THEN
            SPTNAM = LINE(IBEG(ICOUNT):IEND(ICOUNT))
            USERSPOT = .TRUE.
          ENDIF
          ISPOT = 10
          CALL CCPDPN (ISPOT,SPTNAM,'UNKNOWN','F',80,IFAIL)
          LSIMULATE = .TRUE.
          DO IC = 1,5
            SIRAS(IC) = IRAS(IC)
            IRAS(IC) = 3
          ENDDO
          SIXSEP = IXSEP
          SIYSEP = IYSEP
          SISEP = ISEP
          ISEP = 2
          IXSEP = 5
          IYSEP = 5
          SIISEP = IISEP
          IISEP = .TRUE.
          IF(ABS(XCEN).LT.1E-3.AND.ABS(YCEN).LT.1E-3)THEN
            XCEN = XMM(1) * 100.0
            YCEN = YMM(1) * 100.0
            IF (INVERTX) XCEN = 100.0*NREC*RAST - XCEN
c          write(iout,fmt=9876) xcen
c          if (online) write(itout,fmt=9876) xcen
c 9876     format(1x,'xcen set in kwsimu from xmm, now;',F8.2)
          ENDIF
          CALL PREDICT_SPOTS(0,ARGVL,ITYPL,VALUEL,0,IERR)
          LSIMULATE = .FALSE.
          CLOSE (UNIT= ISPOT)
          DO 1000 IC = 1,5
            IRAS(IC) = SIRAS(IC)
 1000     ENDDO
          IXSEP = SIXSEP
          IYSEP = SIYSEP
          ISEP = SISEP
          IISEP = SIISEP
          WRITE(IOUT,FMT=7389)sptnam(1:lenstr(sptnam)),phibeg,phiend,
     $         ETA*RTOD*2.0
          IF(ONLINE)WRITE(ITOUT,FMT=7389)sptnam(1:lenstr(sptnam)),
     $         phibeg,phiend,ETA*RTOD*2.0
 7389     FORMAT(/,1X,' Writing spot file (',A,
     $         ') for an image with ',
     $         'phi(start) = ',F7.2,' and phi(end) = ',F7.2,/,
     $         ' and mosaic spread = ',F5.2)
          ENDIF
          RETURN
          END
