C-----READ IMAGE: readoximage
C-----FUNCTION READS IMAGE
C     DEBUG(105) THIS S/R
      subroutine readoximage(ISWAP,ODFILE)
      implicit none
C     .. scalar arguments
      INTEGER ISWAP
C     ..
C     .. character arguments
      CHARACTER ODFILE*200
C     ..
C     .. mosflm parameters
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     ..
C     .. mosflm includes
C&&*&& include  ../inc/debug.f
C
C $Id: debug.f,v 1.8 2021/06/03 09:41:34 andrew Exp $
C
C--- awk generated include file  debug.h
C---- START of include file debug.h
C
C
C
C     .. Arrays in common /DEBUG/ ..
      REAL XWARN
      INTEGER NDEBUG,IWARN,IARRDUMP
      LOGICAL DEBUG,LPRINT,DUMP,WARN
C
C     .. Scalars in common /DEBUG/ ..
      REAL BGRLIM
      INTEGER NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,IERRLEVEL
      LOGICAL SPOT
      CHARACTER MESSAGE*512
C     
C     ..
C     .. Common Block /DEBUG/..
      COMMON /DEBUG/XWARN(MAXIWARN,100),BGRLIM,NDEBUG(200),
     +       IWARN(MAXIWARN,100),
     $       NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,DEBUG(200),LPRINT(20),
     +       DUMP(30),WARN(100),SPOT,IARRDUMP(30),IERRLEVEL

      COMMON /CDEBUG/ MESSAGE
C     ..
C
C&&*&& end_include  ../inc/debug.f
C&&*&& include  ../inc/detector.f
C
C $Id: detector.f,v 1.3 2007/11/13 17:21:01 harry Exp $
C
C
C---- START of include file detector.f
C
      REAL RMINIP,RMAXIP,XMAXIP,YMAXIP,XLIMIT,RSCANIP
      COMMON /DETECTOR/RMINIP,RMAXIP,XMAXIP,YMAXIP,XLIMIT,
     $     RSCANIP
C&&*&& end_include  ../inc/detector.f
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C&&*&& include  ../inc/pel.f
C     **** This is the IMAGE PLATE version of this common block ****
C
C
C---- START of include file pel.h
C
C
C     .. Scalars in common blocks /PEL/ and /PELC/ ..
      INTEGER IBA,IPOINT,ISTART
      LOGICAL INCORE
C     ..
C     .. Arrays in common blocks /PEL/ and /PELC/ ..
      LOGICAL RDSTRIP
      INTEGER*2 BOXOD,IMAGE,IMAGE2
C     ..
C     .. Common Blocks /PEL/ and /PELC/ ..
      COMMON /PEL/IBA,IPOINT,INCORE,RDSTRIP(IXWDTH),BOXOD(MAXBOX),
     +            ISTART
      COMMON /PELC/ IMAGE(IYLENGTH*IXWDTH),IMAGE2(4400*4400)
C     ..
C
C
C---- END of include file pel.h
C
C&&*&& end_include  ../inc/pel.f
C     ..
C     .. Mathias' code
C&&*&& include  ../inc/harinf.fi
C     1) HARRY INFO

C     dddmm = detector distance mm (ddistanceinmm)
C     dstartdeg = oscillation start deg
C     denddeg = oscillation end deg
C     domegadeg = omega angle in deg
C     ddetectordeg = theta/detector angle in deg
C     dkappadeg = kappa angle in deg

	REAL*8 DDDMM,DSTARTDEG,DENDDEG,DOMEGADEG,DDETECTORDEG,DKAPPADEG

C     dphideg = phi angle in deg
C     dalpha1ang = wavelength al1 in Ang (dalpha1 in swavelength)
C     dorix = detector origin in x dir (dxorigininpix)
C     doriy = detector origin in y dir (dyorigininpix)
C     dadrotdeg(3) = detector rotations 1-3 in deg (dadetectorrotindeg)
C     dsysgain = system gain (dsystemgain)

      REAL*8 DPHIDEG,DALPHA1ANG,DORIX,DORIY,DALPHA,DADROTDEG(3),DSYSGAIN

C     dexpsec = exposure time in sec (dexposuretimeinsec)
C     doversec = overflow exposure time in sec (doverflowtimeinsec)

      REAL*8 DEXPSEC,DOVERSEC,DACONV(10),DB2DEG,DB3DEG

C     iscantype = scantype code number
C     ibx,iby = binning in x and y
C     ixw,iyw = width of image device in x and y
C     inx,iny = number of pixel in image in x and y
C     ioverff = overflow flag (ioverflowflag)

      INTEGER*2 ISCANTYPE,IBX,IBY,IXW,IYW,INX,INY,IOVERFF

C     ioverfarf = overflow flag after remeas. (ioverflowafterremeasureflag)
C     ierror = error flag 0 = ok, 1 = error
C     iiscomp = compression flag 0 = no, 1 = compression type 1
C     ihnx = header nx -> should be the same as inx
C     ihny = header ny -> should be the same as iny
C     id1 = dummy

      INTEGER*2 IOVERFARF,IERROR,IISCOMP,IHNX,IHNY,ID1

C     dwpts = number of points in image inx*iny
C     loverthr = (loverflowthreshold)
C     lastart = (lastartanglesinsteps_qq)
C     laend = (laendanglesinsteps_qq)
C     lnoi = number of short overflows
C     lnol = number of long overflows

	INTEGER*4 DWPTS,LOVERTHR,LASTART(10),LAEND(10),LNOI,LNOL
	INTEGER NHBYTES

      COMMON /HARRYINF/ 
     &        DDDMM,DSTARTDEG,DENDDEG,DOMEGADEG,DDETECTORDEG,DKAPPADEG,
     &	      DPHIDEG,DALPHA1ANG,DORIX,DORIY,DADROTDEG,DSYSGAIN,
     &	      DEXPSEC,DOVERSEC,DACONV,DB2DEG,DB3DEG,
     &        ISCANTYPE,IBX,IBY,IXW,IYW,INX,INY,IOVERFF,
     &        IOVERFARF,IERROR,IISCOMP,IHNX,IHNY,ID1,
     &        DWPTS,LOVERTHR,LASTART,LAEND,LNOI,LNOL,NHBYTES  

C&&*&& end_include  ../inc/harinf.fi
C&&*&& include  ../inc/crysalis.fi
C     2) CRYSALIS IMAGE

C     lmaxnx = max number of pixels in x for image reading
C     lmaxny = max number of pixels in y for image reading
C     lmaxpts = max number of pts for image reading
C	cpixel2 and cpixel4 are for byte swapping if necessary
      INTEGER LMAXNX,LMAXNY,LMAXPTS
      PARAMETER (LMAXNX=2048)                        
      PARAMETER (LMAXNY=2048)                        
      PARAMETER (LMAXPTS=LMAXNX*LMAXNY)                        
	INTEGER*1 CPIXEL(LMAXPTS),CPIXEL2(LMAXPTS*2),CPIXEL4(LMAXPTS*4)
	INTEGER*2 IPIXEL(LMAXPTS)
	INTEGER*4 LPIXEL(LMAXPTS),LOVERPIXEL(LMAXPTS)
	EQUIVALENCE(CPIXEL2(1),IPIXEL(1))
	EQUIVALENCE(CPIXEL4(1),LOVERPIXEL(1))
      COMMON /CRYSALIS/ 
     &           CPIXEL,IPIXEL,LPIXEL,LOVERPIXEL   

C&&*&& end_include  ../inc/crysalis.fi
C-----LOCAL VARS
        LOGICAL LOCALBYTESWAP
       integer*2 ivalue
       integer*4 li,loffset,lvalue
        INTEGER IERR,I
C     ..
C     .. external functions
      LOGICAL LITEND
      EXTERNAL LITEND
      LOCALBYTESWAP = LITEND()
      IF (DEBUG(45)) THEN
        write(iout,fmt=6004) ierror,inx,lmaxnx,iny,lmaxny,LOCALBYTESWAP
        if (online) write(itout,fmt=6004) ierror,inx,lmaxnx,iny,lmaxny,
     +            LOCALBYTESWAP
      endif
 6004 format(1x,'Entering readoximage, ierror:',I5,' inx:',I5,
     +       '  lmaxnx:',i5,'  iny:',i5,' lmaxny:',i5,'  byteswap',l2)

C-----ERROR CHECK
       if(ierror.eq.1) then
              return
       end if
C-----FIXED ARRAY SIZE CHECK
       if(inx.gt.lmaxnx) then
              return
       end if
C-----FIXED ARRAY SIZE CHECK
       if(iny.gt.lmaxny) then
              return
       end if

C-----ZERO MEMORY
        DO 100 LI=1,LMAXPTS
          CPIXEL(LI)=0
          IPIXEL(LI)=0
          LPIXEL(LI)=0
          LOVERPIXEL(LI)=0
 100    END DO

C-----READ IMAGE IN OD FORMAT
       if(iiscomp.eq.0) then
              if (DEBUG(105)) then
                write(iout,fmt=6000) iiscomp
                if (online) write(itout,fmt=6000) iiscomp
              endif
 6000         format(1x,'IISCOMP:',I6,'  Calling readoximagenc')
              call readoximagenc(ISWAP,ODFILE)
       else
              if (DEBUG(105)) then
                write(iout,fmt=6002) iiscomp
                if (online) write(itout,fmt=6002)iiscomp
              endif
 6002         format(1x,'IISCOMP:',I6,'   Calling readoximagecomp')
CAL              call readoximagenc(ISWAP,ODFILE)
              call readoximagecomp(ISWAP,ODFILE)
       end if
C-----TRANSFORM TO MOSFLM 16BIT FORMAT
C     POTENTIAL PROBLEMS
C-----CCD IMAGES MAY HAVE NEGATIVE VALUES...
C-----AT THE MOMENT DUMMY OFFSET
       LOFFSET=0
        DO 200 LI=1,DWPTS
          LVALUE=LPIXEL(LI)+LOFFSET
          IF(LVALUE.LT.0) THEN
            IVALUE=0
          ELSE
            IF(LVALUE.GT.65535) THEN
              IVALUE=-32768
            ELSEIF(LVALUE.GT.32767) THEN
              IVALUE = -65535 + LVALUE
            ELSE
              IVALUE = LVALUE
            END IF
          END IF
          IF(IVALUE.LT.0)THEN
            IMAGE(LI) = IVALUE + 65535
          ELSE
            IMAGE(LI)=IVALUE
          ENDIF
 200    END DO
        if (debug(105)) then
          write(iout,fmt=6005)
          if (online) write(itout,fmt=6005)
 6005     format(/,/,'Final IMAGE array:')
          DO 210 LI = 1,DWPTS
            IF ((LI.EQ.1).OR.(LI.EQ.100).OR.(LI.EQ.200)
     +         .OR.(LI.EQ.4000).OR.(LI.EQ.5000).OR.(LI.EQ.6000)
     +         .OR.(LI.EQ.70000).OR.(LI.EQ.80000).OR.(LI.EQ.90000)
     +         .OR.(LI.EQ.100000).OR.(LI.EQ.150000).OR.(LI.EQ.200000))
     +         THEN
              WRITE(IOUT,FMT=6006) li,(IMAGE(I),I=LI,LI+99)
              IF (ONLINE) WRITE(ITOUT,FMT=6006) li,(IMAGE(I),I=LI,LI+99)
 6006         FORMAT(/,1x,'i=',i6,/,(1X,20I6))
            END IF
 210      CONTINUE
        end if
        RETURN
       END

C-----READ IMAGE: readoximagecomp
C-----FUNCTION READS COMPRESSED IMAGE
      subroutine readoximagecomp(ISWAP,odfile)
      implicit none
C     ..
C     .. scalar arguments
      INTEGER ISWAP
C     ..
C     .. character arguments
      CHARACTER ODFILE*200
C     ..
C     .. mosflm parameters
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
