     +     NBYTE,NREC,NWORD,IYLEN,
     +     ICURR,NEXTRA,NHBYTE,BYTSWAP,LACTIVE,
     $     REALLYFORCEREAD
C&&*&& end_include  ../inc/scn.f
C&&*&& include  ../inc/harinf.fi
C     1) HARRY INFO

C     dddmm = detector distance mm (ddistanceinmm)
C     dstartdeg = oscillation start deg
C     denddeg = oscillation end deg
C     domegadeg = omega angle in deg
C     ddetectordeg = theta/detector angle in deg
C     dkappadeg = kappa angle in deg

	REAL*8 DDDMM,DSTARTDEG,DENDDEG,DOMEGADEG,DDETECTORDEG,DKAPPADEG

C     dphideg = phi angle in deg
C     dalpha1ang = wavelength al1 in Ang (dalpha1 in swavelength)
C     dorix = detector origin in x dir (dxorigininpix)
C     doriy = detector origin in y dir (dyorigininpix)
C     dadrotdeg(3) = detector rotations 1-3 in deg (dadetectorrotindeg)
C     dsysgain = system gain (dsystemgain)

      REAL*8 DPHIDEG,DALPHA1ANG,DORIX,DORIY,DALPHA,DADROTDEG(3),DSYSGAIN

C     dexpsec = exposure time in sec (dexposuretimeinsec)
C     doversec = overflow exposure time in sec (doverflowtimeinsec)

      REAL*8 DEXPSEC,DOVERSEC,DACONV(10),DB2DEG,DB3DEG

C     iscantype = scantype code number
C     ibx,iby = binning in x and y
C     ixw,iyw = width of image device in x and y
C     inx,iny = number of pixel in image in x and y
C     ioverff = overflow flag (ioverflowflag)

      INTEGER*2 ISCANTYPE,IBX,IBY,IXW,IYW,INX,INY,IOVERFF

C     ioverfarf = overflow flag after remeas. (ioverflowafterremeasureflag)
C     ierror = error flag 0 = ok, 1 = error
C     iiscomp = compression flag 0 = no, 1 = compression type 1
C     ihnx = header nx -> should be the same as inx
C     ihny = header ny -> should be the same as iny
C     id1 = dummy

      INTEGER*2 IOVERFARF,IERROR,IISCOMP,IHNX,IHNY,ID1

C     dwpts = number of points in image inx*iny
C     loverthr = (loverflowthreshold)
C     lastart = (lastartanglesinsteps_qq)
C     laend = (laendanglesinsteps_qq)
C     lnoi = number of short overflows
C     lnol = number of long overflows

	INTEGER*4 DWPTS,LOVERTHR,LASTART(10),LAEND(10),LNOI,LNOL
	INTEGER NHBYTES

      COMMON /HARRYINF/ 
     &        DDDMM,DSTARTDEG,DENDDEG,DOMEGADEG,DDETECTORDEG,DKAPPADEG,
     &	      DPHIDEG,DALPHA1ANG,DORIX,DORIY,DADROTDEG,DSYSGAIN,
     &	      DEXPSEC,DOVERSEC,DACONV,DB2DEG,DB3DEG,
     &        ISCANTYPE,IBX,IBY,IXW,IYW,INX,INY,IOVERFF,
     &        IOVERFARF,IERROR,IISCOMP,IHNX,IHNY,ID1,
     &        DWPTS,LOVERTHR,LASTART,LAEND,LNOI,LNOL,NHBYTES  

C&&*&& end_include  ../inc/harinf.fi
C&&*&& include  ../inc/crysalis.fi
C     2) CRYSALIS IMAGE

C     lmaxnx = max number of pixels in x for image reading
C     lmaxny = max number of pixels in y for image reading
C     lmaxpts = max number of pts for image reading
C	cpixel2 and cpixel4 are for byte swapping if necessary
      INTEGER LMAXNX,LMAXNY,LMAXPTS
      PARAMETER (LMAXNX=2048)                        
      PARAMETER (LMAXNY=2048)                        
      PARAMETER (LMAXPTS=LMAXNX*LMAXNY)                        
	INTEGER*1 CPIXEL(LMAXPTS),CPIXEL2(LMAXPTS*2),CPIXEL4(LMAXPTS*4)
	INTEGER*2 IPIXEL(LMAXPTS)
	INTEGER*4 LPIXEL(LMAXPTS),LOVERPIXEL(LMAXPTS)
	EQUIVALENCE(CPIXEL2(1),IPIXEL(1))
	EQUIVALENCE(CPIXEL4(1),LOVERPIXEL(1))
      COMMON /CRYSALIS/ 
     &           CPIXEL,IPIXEL,LPIXEL,LOVERPIXEL   

C&&*&& end_include  ../inc/crysalis.fi
C-----LOCAL VARS
C      integer*2 ivalue
      integer*4 li,lvalue,lcoi,lcol,lim1,lim2
      LOGICAL LOCALBYTESWAP
      INTEGER*1 clongo,cshorto,CTEMP
      INTEGER IERR,I,J,NCMITM
C     ..
C     .. external functions
      LOGICAL LITEND
      EXTERNAL LITEND

c      parameter (clongo=255)                        
c      parameter (cshorto=254)                        
      parameter (clongo=-1)                        
      parameter (cshorto=-2)                        
      LOCALBYTESWAP = LITEND()
      WRITE(IOUT,FMT=6000) NREC,IYLEN,LOCALBYTESWAP
      IF(ONLINE)write(ITOUT,FMT=6000) NREC,IYLEN,LOCALBYTESWAP
 6000 FORMAT(1X,'Reading an compressed Oxford Image',
     +        ' NREC=',I5,' IYLEN=',I5,' btyeswap',l2)
      CALL QOPEN(INOD,ODFILE,'READONLY')
C     ..
C     .. read the header cleanly this time
      CALL QMODE(INOD,0,NCMITM)
      CALL QREAD(INOD,CPIXEL,NHBYTES,IERR)
C
C-----READ IN THE CHAR ARRAY
      CALL QMODE(INOD,0,NCMITM)
      DO 100 I = 0,NREC-1,1
        CALL QREAD(INOD,CPIXEL(1+I*IYLEN),IYLEN,IERR)
        RDSTRIP(I+1) = .TRUE.
 100  ENDDO

      if (DEBUG(105)) then
        do 101 i = 1,nrec*iylen
          if ((i.eq.1).or.(i.eq.100).or.(i.eq.200)
     +         .or.(i.eq.4000).or.(i.eq.5000).or.(i.eq.6000)
     +         .or.(i.eq.70000).or.(i.eq.80000).or.(i.eq.90000)
     +         .or.(i.eq.100000).or.(i.eq.150000).or.(i.eq.200000))
     +         then
            write(iout,fmt=6006) i,(cpixel(j),j=i,i+99)
            if (online) write(itout,fmt=6006) i,(cpixel(j),j=i,i+99)
 6006       format(/,'i=',i8,/,(1x,20i6))
          end if
 101    continue
      end if
             
C-----READ IN THE SHORT OVERFLOWS ARRAY
      I = LNOI
c---old ccp4 libs
chrp 07.05.2004      CALL QREADI(INOD,ipixel,i*2,IERR)
c---new ccp4 libs
      CALL QREADI2(INOD,ipixel,i,IERR)
      IF(.NOT.LOCALBYTESWAP)then
         DO 200 I=1,LNOI*2,2
           CTEMP = CPIXEL2(I)
           CPIXEL2(I) = CPIXEL2(I+1)
           CPIXEL2(I+1) = CTEMP
 200     ENDDO
       endif
       if (debug(105)) then
         write(iout,fmt=6008) lnoi,(ipixel(i),i=1,100)
         if (online) write(itout,fmt=6008) lnoi,(ipixel(i),i=1,100)
 6008  format(/,1x,'There are',I5,' short overflows, first 100',/,
     +        (1x,20i7,/))
       end if
C-----READ IN THE LONG OVERFLOWS ARRAY
      I = LNOL
      CALL QMODE(INOD,2,NCMITM)
      CALL QREADI(INOD,loverpixel,I,IERR)
      IF(.NOT.LOCALBYTESWAP)then
         DO 300 I=1,LNOL*4,4
            CTEMP = CPIXEL4(I)
            CPIXEL4(I) = CPIXEL4(I+3)
            CPIXEL4(I+3) = CTEMP
            CTEMP = CPIXEL4(I+1)
            CPIXEL4(I+1) = CPIXEL4(I+2)
            CPIXEL4(I+2) = CTEMP
 300      ENDDO
      ENDIF
      if (debug(105)) then
        write(iout,fmt=6010) lnol,(loverpixel(i),i=1,10)
        if (online) write(itout,fmt=6010) lnol,(loverpixel(i),i=1,10)
 6010  format(/,1x,'There are',I5,' long overflows, first 10',/,
     +        (1x,20i10,/))
      end if
      lcoi=1
      lcol=1
      lim1=1
      lim2=2
C-----PIXEL 0
       if(cpixel(1).eq.clongo) then
              lpixel(1)=loverpixel(lcol)
              lcol=lcol+1
       else
              if(cpixel(1).eq.cshorto) then
                     lpixel(1)=ipixel(lcoi)
                     lcoi=lcoi+1
              else
               if(cpixel(1).lt.0) then
                            lvalue=128+(128+cpixel(1))
                     else
                            lvalue=cpixel(1)
                     end if
                     lpixel(1)=lvalue-127
              end if
       end if

        DO 400 LI=2,DWPTS
          IF(CPIXEL(LI).EQ.CLONGO) THEN
            LPIXEL(LIM2)=LOVERPIXEL(LCOL)+LPIXEL(LIM1)
            LCOL=LCOL+1
          ELSE
            IF(CPIXEL(LI).EQ.CSHORTO) THEN
              LPIXEL(LIM2)=IPIXEL(LCOI)+LPIXEL(LIM1)
              LCOI=LCOI+1
            ELSE
              IF(CPIXEL(LI).LT.0) THEN
                LVALUE=128+(128+CPIXEL(LI))
              ELSE
                LVALUE=CPIXEL(LI)
              END IF
              LPIXEL(LIM2)=LVALUE-127+LPIXEL(LIM1)
            END IF
          END IF
          LIM1=LIM1+1
          LIM2=LIM2+1
 400    END DO
        CALL QCLOSE(INOD)
      if (debug(105)) then
        write(iout,fmt=6012)
        if (online) write(itout,fmt=6012)
 6012 format(/,/,1x,'After transferring to I*4 array:')
        do 401 i = 1,nrec*iylen
          if ((i.eq.1).or.(i.eq.100).or.(i.eq.200)
     +         .or.(i.eq.4000).or.(i.eq.5000).or.(i.eq.6000)
     +         .or.(i.eq.70000).or.(i.eq.80000).or.(i.eq.90000)
     +         .or.(i.eq.100000).or.(i.eq.150000).or.(i.eq.200000))
     +         then
            write(iout,fmt=6014) i,(lpixel(j),j=i,i+99)
            if (online) write(itout,fmt=6014) i,(lpixel(j),j=i,i+99)
 6014       format(/,'i=',i8,/,(1x,20i6))
          end if
 401    continue
      end if


        RETURN
       END


C-----READ IMAGE: readoximagenc
C-----FUNCTION READS NON-COMPRESSED IMAGE
      subroutine readoximagenc(iswap,odfile)
      implicit none
C     ..
C     .. scalar arguments
      INTEGER ISWAP
C     ..
C     .. character arguments
      CHARACTER ODFILE*200
C     ..
C     .. mosflm parameters
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
