C&&*&& include  ../inc/scn.f
C
C $Id: scn.f,v 1.5 2014/11/18 14:05:40 andrew Exp $
C
C--- awk generated include file  scn.h
C---- START of include file scn.h
C
C     SCNSZ   is pixel size (in microns) divided by 25
C     RAST    pixel size in slow direction in mm
C     FACT    multiplying by FACT converts from 10 micron units 
C             (the standard unit internal to the program) into pixels
C     IYLEN   The number of pixels in the Y (fastest changing) direction
C             in the digitised image.
C     NREC    The number of pixels in the X (slow) direction in the 
C             digitised image.
C     NWORD   The number of I*2 words in the Y direction.
C     NBYTE   The number of bytes in Y direction = NWORD/2
C     NHBYTE  Number of bytes in header
C
C     ICURR   When several images are stored in a single file, ICURR is the
C             pointer to the first record of the current image in the direct
C             access file (only implemented for film data)
C     NEXTRA  The number of additional (unused) bytes padding the end of
C             each record in image file
C     BYTSWAP True if the "endedness" (Big-endian/Little-endian) of the 
C             machine that MOSFLM is running on is different to that of the
C             machine on which the image was written. This is determined by
C             looking at the value of NXPIX in the header record of the
C             image file (subroutine GETHDR)
C
C     LACTIVE True if using Rigaku active mask, False if ignoring it
C     REALLYFORCEREAD True if we want to display an image where we have
C                     changed the activemask
C
C     ROWREADT Time in seconds that the detector takes to read a row of data,
C              required for rolling shutter mode readout of Tietz detector
C              used for microED.
C     ROTSPEED Spindle rotation rate (degrees per second),required for rolling
C              shutter mode readout of Tietz detector used for microED. 
C
C
C     .. Scalars in common block /SCN/ ..
      REAL FACT,SCNSZ,RAST,RASTY,ROWREADT,ROTSPEED
      INTEGER NBYTE,NREC,NWORD,IYLEN,ICURR,NEXTRA,NHBYTE
      LOGICAL BYTSWAP,LACTIVE,REALLYFORCEREAD
C     ..
C     .. Common Block /SCN/ ..
      COMMON /SCN/ FACT,SCNSZ,RAST,RASTY,ROWREADT,ROTSPEED,
     +     NBYTE,NREC,NWORD,IYLEN,
     +     ICURR,NEXTRA,NHBYTE,BYTSWAP,LACTIVE,
     $     REALLYFORCEREAD
C&&*&& end_include  ../inc/scn.f
C&&*&& include  ../inc/test.f
C--- awk generated include file  test.h
C---- START of include file test.h
C
C    Detector limits, used in SPTEST. All are in 10 micron units.
C    In the virtual detector frame, Y is parallel to the rotation axis
C    and X is orthogonal to the rotation axis.
C
C    In the scanner frame, X is parallel to the slow direction in the
C    image, Y is the fast direction.
C
C    RSCANSQ      Radius**2 of the scanned region of the plate (Mar scanners)
C                 This is different to the other limits because it is
C                 applied to the actual scanner coordinates rather than
C                 the virtual detector coordinates. All other limits apply
C                 to virtual detector coordinates.
C    XSCAN        Maximum X coordinate in detector frame (10 micron units)
C    YSCAN        Maximum Y coordinate in detector frame (10 micron units)
C    RSCANX,RSCANY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RSCAN defining the
C                 useable area of the detector.
C    XSCAN,YSCAN,RSCAN are maximum coords relative to the physical centre of 
C                 the detector (ie the mid-point of the image), NOT wrt the 
C                 direct beam position.
C    RMINX,RMINY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RMIN defining the
C                 useable area of the detector.
C    RMXSQD       Maximum radius (squared) in virtual detector frame
C    RMNSQD       Minimum radius (squared) in virtual detector frame
C    XMIN         Minimum X coordinate in  detector frame
C    XMAX         Maximum X coordinate in  detector frame
C    YMIN         Minimum Y coordinate in  detector frame
C    YMAX         Maximum Y coordinate in  detector frame
C    NXYEXC       Number of excluded areas set by user (rectangles, arcs)
C    NXYEXCDET    Number of detector specific excluded rectangles (Pilatus)
C    NOTILES      If set true, ignore all tile boundaries in Pilatus images
C    ICEWIDTH     Width of the exclusion shells for ice, this fraction
C                 of the actual resolution is used as the half-width
C    ICEWIDTHPREF Width of the exclusion shells for ice for post
C                 refinement, this fraction
C                 of the actual resolution is used as the half-width
C    PREFEXICE    Logical, true if reflections in ice rings to be
C                 excluded from post-refinement
C
C     .. Scalars in common block /TEST/ ..
      REAL RMXSQD,RMNSQD,XMIN,XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,
     +     RMINX,RMINY,XSCAN,YSCAN,CIRRAD,ICEWIDTH,ICEWIDTHPREF
      INTEGER NEXCL,NXYEXC,NXYEXCDET,IQUADNO,IARCNO,NEXCL2
      LOGICAL PREFEXICE,NOTILES
C
C     .. Arrays in common block /TEST/
      REAL RESEXL,RESEXH,XYEXC,CNREXC,EXCARC,CIRCEN,PHILIM,RES2EXL,
     +     RES2EXH,RES3EXL,RES3EXH,XYEXCSP
      INTEGER IEXCARC
      LOGICAL LEXCARC
C     ..
C     .. Common Block /TEST/ ..
      COMMON /TEST/RESEXL(MAXEXCL),RESEXH(MAXEXCL),XYEXC(4,MAXEXCL),
     +     CNREXC(8,MAXEXCL),
     $     EXCARC(5,MAXEXCL),CIRCEN(2),PHILIM(2),RMXSQD,RMNSQD,XMIN,
     +     XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,RMINX,RMINY,XSCAN,
     $     YSCAN,CIRRAD,IEXCARC(6,MAXEXCL),NEXCL,NXYEXC,IQUADNO,
     $     IARCNO,LEXCARC(MAXEXCL),NXYEXCDET,RES2EXL(MAXEXCL),
     $     RES2EXH(MAXEXCL),NEXCL2,ICEWIDTH,ICEWIDTHPREF,PREFEXICE,
     +     RES3EXL(MAXEXCL),RES3EXH(MAXEXCL),NOTILES,XYEXCSP(4,MAXEXCL)
C     ..
C
C

C&&*&& end_include  ../inc/test.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C&&*&& include  ../inc/xy.f
C
C $Id: xy.f,v 1.1 2002/05/02 10:47:25 harry Exp $
C
C--- awk generated include file  xy.h
C---- START of include file xy.h
C
C     .. Scalars in common block /XY/ ..
      REAL XTOFD,SINV,COSV,TANV,TWOTHETA
      INTEGER ICASS
C     ..
C     .. Common Block /XY/ ..
      COMMON /XY/XTOFD,SINV,COSV,TANV,TWOTHETA,ICASS
C     ..
C
C     XTOFD....  Crystal to detector distance in 10 micron units. Read from
C                keyworded input and never changed.
C
C                Spot positions are calculated in S/R XYSPOT (Called from
C                REEK) and are for an "ideal" detector at a distance of XTOFD.
C                These are converted into pixel positions in S/R MMTOPX
C                which applies the multiplicative factor XTOFRA to allow
C                for refinement of the distance. XTOFRA is the parameter
C                that is actually refined (in RDIST), rather than XTOFD.
C                The refined distance that is printed in the logfile is
C                actually XTOFRA*XTOFD
C
C     ICASS....  Indicates detector type:
C                0     Flat film
C                1     Vee shaped cassettes
C                2     FAST detector (only used in TESTGEN mode of OSCGEN)
C                3     Swung out FAST (ditto)
C                4     IP detector
C     TWOTHETA   Detector swing angle (degrees)
C&&*&& end_include  ../inc/xy.f
C     ..
C     .. intrinsics
        INTRINSIC ATAN
C     ..
C     .. external functions
        LOGICAL LITEND
        INTEGER LENSTR
        EXTERNAL LENSTR,LITEND
C     ..
C     .. Equivalences ..
        EQUIVALENCE (RHEAD(1),IHEAD(1))
        EQUIVALENCE (CHEAD(1),IHEAD(1))
        EQUIVALENCE (BHEAD(1),IHEAD(1))
        EQUIVALENCE (IHEADI2(1),IHEAD(1))
        EQUIVALENCE (CSHORT,ISHORT),(CLONG,ILONG),(CDOUBLE,IDOUBLE)
        EQUIVALENCE (CLONG,FLONG),(CDOUBLE,FDOUBLE)
        LOCALBYTESWAP = LITEND()
        CALLEDFROM = 'READOXHEADER'
C
C---- BASERAST is the 1x1 binned size of the SAPPHIRE detector in mm
C     hard-coded for now, this will later appear in the image header
C      BASERAST = 0.0310
      CTRLM = CHAR(13)
      CTRLJ = CHAR(10)
      NHBYTES = 0
C      ISWAP = 0
      NBYTE = 0
      IF (NBYTE.EQ.0) THEN
        IF (DEBUG(45)) THEN
          WRITE(IOUT,FMT=6000) NBYTE,ISWAP
          IF (ONLINE) WRITE(ITOUT,FMT=6000) NBYTE,ISWAP
 6000     FORMAT(/,1X,'In READOXHDR, NBYTE=',I6,'  ISWAP=',I3)
 6020     FORMAT(1X,'LINE IS: ',A)
        END IF
        NNBYTE = 256
      ELSE
        NNBYTE = NHBYTES
      END IF
      IERR = 0
      CALL QOPEN(INOD,ODFILE,'READONLY')
      CALL GETBLK(BHEAD(1),NNBYTE,1,ISWAP,IERR)
C
C---- Trap error in read
C
      IF (IERR.NE.0) THEN
        WRITE(IOUT,FMT=6040) MACHINE
        IF (ONLINE) WRITE(ITOUT,FMT=6040) MACHINE
 6040   FORMAT(/,1X,'Error trying to read header record',
     +       ' in image file for scanner type:',A,/,1X,
     +       'Check that the file is',
     +       ' the correct length')
        ISTAT = -1
        RETURN
      END IF
C
C---- First check to see if it's a pseudo MAR345 or a native KM4CCD image
C
        IF((CHEAD(1).EQ.'K').or.(CHEAD(1).EQ.'O'))THEN
          MODEL = 'SAPPHIRE'
C     
C---- Search for end of this line
C     
           LINE = ' '
           DO 100 ICOUNT = 1,256,1
             IF(CHEAD(ICOUNT).EQ.CTRLJ)CHEAD(ICOUNT) = ' '
             IF(CHEAD(ICOUNT).EQ.CTRLM)CHEAD(ICOUNT) = ' '
 100       ENDDO
           WRITE(LINE,FMT=6060) (CHEAD(ICOUNT),ICOUNT=1,256)
 6060      FORMAT(256A1)
           IF (DEBUG(45)) THEN
             WRITE(IOUT,FMT=6020) LINE(1:LENSTR(LINE))
             IF (ONLINE) WRITE(ITOUT,FMT=6020)
     $            LINE(1:LENSTR(LINE))
           END IF
         ENDIF
C
C---- COMPRESSION - bytes 
C
         HCOMPRESS = LINE(31:33)
         IF((HCOMPRESS.EQ.'TY1').OR.(HCOMPRESS.EQ.'TY5'))THEN
           IISCOMP = 1
         ELSEIF(HCOMPRESS.EQ.' NO')THEN
CAL           IISCOMP = 1          ! is this right?
           IISCOMP = 0          ! is this right?
         ELSE
           IERROR = 1
         ENDIF
C     
C---- NX = NREC
C
         CALL CHAR2INT(NREC,LINE(47:50),4)
         IHNX = NREC
C     
C---- NY = IYLEN
C
         CALL CHAR2INT(IYLEN,LINE(55:58),4)
         IF(DEBUG(45))THEN
           WRITE(IOUT,FMT=6080)NREC,IYLEN
           IF(ONLINE)WRITE(ITOUT,FMT=6080)NREC,IYLEN
 6080      FORMAT('NREC = ',I5,' IYLEN = ',I5)
         ENDIF
         IHNY = IYLEN
C     ..
C     .. OI = short overloads
         CALL CHAR2INT(lnoi,LINE(63:69),7)
C     ..
C     .. OL = long overloads
         CALL CHAR2INT(lnol,LINE(74:80),7)
         IF(DEBUG(45))THEN
           WRITE(IOUT,FMT=6100)LNOI,LNOL
           IF(ONLINE)WRITE(ITOUT,FMT=6100)LNOI,LNOL
 6100      FORMAT('Overloads: ',I6,' (short) ',I6,' (long)')
         ENDIF
C     ..
C     .. NHEADER is the total number of bytes in the Header, including the
C        256 in the ASCII part.
         CALL CHAR2INT(nhbytes,LINE(93:99),7)
C     ..
C     .. NG is the number of bytes in the General Header
         CALL CHAR2INT(NG,LINE(103:109),7)
C     ..
C     .. NS is the number of bytes in the Special Header - NS appears twice
C        in the SAPPHIRE header; we only use it the first time!
         CALL CHAR2INT(NSPECIAL,LINE(114:120),7)
         IF(DEBUG(45))THEN
           WRITE(IOUT,FMT=6120)NHBYTES,NG,
     $        nspecial
           IF(ONLINE)WRITE(ITOUT,FMT=6120)NHBYTES,NG,
     $        nspecial
 6120      FORMAT('HEADER BYTES: ',I4,' General header size: ',I4,
     $          'Special header size: ',I4)
         ENDIF
C
C---- NK is KM4 goniostat section
C
         CALL CHAR2INT(NK,LINE(125:131),7)
C     
C---- NH is the history section
C
         CALL CHAR2INT(NH,LINE(147:153),7)
C
C---- NSUPPLEMENT is the unused (May 2003) section
C
         CALL CHAR2INT(NSUPPLEMENT,LINE(168:174),7)
C
C---- TIME is when the frame was collected?
C               
         HTIME = LINE(182:215)
         IF(DEBUG(45))THEN
           WRITE(IOUT,FMT=6140)NK,NH,NSUPPLEMENT,HTIME(1:34)
           IF(ONLINE)WRITE(ITOUT,FMT=6140)NK,NH,NSUPPLEMENT,HTIME(1:34)
 6140      FORMAT('NK = ',I5,' NH = ',I5,' NSUPPLEMENT = ',I5,'TIME = ',
     $          A)
         ENDIF
C     
C---- now for the binary header parts 
C
         CALL GETBLK(BHEAD(1025),NHBYTES-256,1,ISWAP,IERR)
C---- NG
         IOFFSET = 257
C     ..
C     .. binning in X
         IPT = IOFFSET
         IF(LOCALBYTESWAP)THEN
            CSHORT = CHEAD(IPT)//CHEAD(IPT+1)
         ELSE
            CSHORT = CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
         IBX = ISHORT
C     ..
C     .. binning in Y
         IPT = IOFFSET + 2
         IF(LOCALBYTESWAP)THEN
            CSHORT = CHEAD(IPT)//CHEAD(IPT+1)
         ELSE
            CSHORT = CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
         IBY = ISHORT
C     ..
C     .. physical image width in X
         IPT = IOFFSET + 22
         IF(LOCALBYTESWAP)THEN
            CSHORT = CHEAD(IPT)//CHEAD(IPT+1)
         ELSE
            CSHORT = CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
         IXW = ISHORT
C     ..
C     .. physical image width in Y
         IPT = IOFFSET + 24
         IF(LOCALBYTESWAP)THEN
            CSHORT = CHEAD(IPT)//CHEAD(IPT+1)
         ELSE
            CSHORT = CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
         IYW = ISHORT
C     ..
C     .. number of image points in X = IXW/IBX
         IPT = IOFFSET + 26
         IF(LOCALBYTESWAP)THEN
            CSHORT = CHEAD(IPT)//CHEAD(IPT+1)
         ELSE
            CSHORT = CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
         INX = ISHORT
C     ..
C     .. number of image points in Y = IYW/IBY
         IPT = IOFFSET + 28
         IF(LOCALBYTESWAP)THEN
            CSHORT = CHEAD(IPT)//CHEAD(IPT+1)
         ELSE
            CSHORT = CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
         INY = ISHORT
C     ..
C     .. cross check should = INX * INY
         IPT = IOFFSET + 36
         IF(LOCALBYTESWAP)THEN
            CLONG = CHEAD(IPT)//CHEAD(IPT+1)//
     $           CHEAD(IPT+2)//CHEAD(IPT+3)
         ELSE
            CLONG = CHEAD(IPT+3)//CHEAD(IPT+2)//
     $           CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
         DWPTS = ILONG
         IF(DEBUG(45))THEN
           WRITE(IOUT,FMT=6160)IBX,IBY,IXW,IYW,INX,INY,DWPTS
           IF(ONLINE)WRITE(ITOUT,FMT=6160)IBX,IBY,IXW,IYW,INX,INY,DWPTS
 6160      FORMAT('Binning: ',2(1X,I4),/,'Physical image width: ',I4,1X,
     $          I4,/,'Number of image points: ',I4,1X,I4,/,
     $          'Crosscheck (INX*INY): ',I9)
         ENDIF
C
C---- NS
C
C     ..
C     .. system gain
         IOFFSET = 257 + NG + 56
         IPT = IOFFSET
         IF(LOCALBYTESWAP)THEN
            CDOUBLE = CHEAD(IPT)//CHEAD(IPT+1)//CHEAD(IPT+2)//
     $           CHEAD(IPT+3)//CHEAD(IPT+4)//CHEAD(IPT+5)//
     $           CHEAD(IPT+6)//CHEAD(IPT+7)
         ELSE
            CDOUBLE = CHEAD(IPT+7)//CHEAD(IPT+6)//CHEAD(IPT+5)//
     $           CHEAD(IPT+4)//CHEAD(IPT+3)//CHEAD(IPT+2)//
     $           CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
         DSYSGAIN = FDOUBLE
         IF(DEBUG(45))THEN
           WRITE(IOUT,FMT=6180)dsysgain
           IF(ONLINE)WRITE(ITOUT,6180)dsysgain
 6180      FORMAT('System gain (Oxford units): ',F8.2)
         ENDIF
C     GAIN seems to be huge - 60 is typical. My guess is it's not
C     expressed in the same way as Mosflm expects - integrating some 
C     test datasets suggests it should be ~1.5 - 2
         IF(IGAIN.EQ.0)GAIN = 2
C     ..
C     .. image contains IOVERFF values >= LOVERTHR
         IPT = IOFFSET + 408
         IF(LOCALBYTESWAP)THEN
            CSHORT = CHEAD(IPT)//CHEAD(IPT+1)
         ELSE
            CSHORT = CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
         IOVERFF = ISHORT
C     ..
C     .. image contains IOVERFARF values >= LOVERTHR _after_
C     .. remeasuring with filter or faster
C     
         IPT = IOFFSET + 410
         IF(LOCALBYTESWAP)THEN
            CSHORT = CHEAD(IPT)//CHEAD(IPT+1)
         ELSE
            CSHORT = CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
         IOVERFARF = ISHORT
C     ..
C     .. overflow threshold
         IPT = IOFFSET + 416
         IF(LOCALBYTESWAP)THEN
            CLONG = CHEAD(IPT)//CHEAD(IPT+1)//
     $           CHEAD(IPT+2)//CHEAD(IPT+3)
         ELSE
            CLONG = CHEAD(IPT+3)//CHEAD(IPT+2)//
     $           CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
         LOVERTHR = ILONG
         IF(DEBUG(45))THEN
           WRITE(IOUT,FMT=6200)IOVERFF,IOVERFARF,LOVERTHR
           IF(ONLINE)WRITE(ITOUT,FMT=6200)IOVERFF,IOVERFARF,LOVERTHR
 6200      FORMAT('Number of overflows: little: ',I4,' big: ',I4,/,
     $          'Overflow threshold: ',I9)
         ENDIF
C     ..
C     .. exposure time in seconds
         IPT = IOFFSET + 424
         IF(LOCALBYTESWAP)THEN
            CDOUBLE = CHEAD(IPT)//CHEAD(IPT+1)//CHEAD(IPT+2)//
     $           CHEAD(IPT+3)//CHEAD(IPT+4)//CHEAD(IPT+5)//
     $           CHEAD(IPT+6)//CHEAD(IPT+7)
         ELSE
            CDOUBLE = CHEAD(IPT+7)//CHEAD(IPT+6)//CHEAD(IPT+5)//
     $           CHEAD(IPT+4)//CHEAD(IPT+3)//CHEAD(IPT+2)//
     $           CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
         DEXPSEC = FDOUBLE
C     ..
C     .. re-measurement exposure time in seconds
         IPT = IOFFSET + 432
         IF(LOCALBYTESWAP)THEN
            CDOUBLE = CHEAD(IPT)//CHEAD(IPT+1)//CHEAD(IPT+2)//
     $           CHEAD(IPT+3)//CHEAD(IPT+4)//CHEAD(IPT+5)//
     $           CHEAD(IPT+6)//CHEAD(IPT+7)
         ELSE
            CDOUBLE = CHEAD(IPT+7)//CHEAD(IPT+6)//CHEAD(IPT+5)//
     $           CHEAD(IPT+4)//CHEAD(IPT+3)//CHEAD(IPT+2)//
     $           CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF

         DOVERSEC = FDOUBLE
         IF(DEBUG(45))THEN
           WRITE(IOUT,FMT=6220)DEXPSEC,DOVERSEC
           IF(ONLINE)WRITE(ITOUT,FMT=6220)DEXPSEC,DOVERSEC
 6220      FORMAT('Exposure time (secs): ',D8.2,
     $          ' remeasure time (secs): ',D8.2)
         ENDIF
C     ..
C     .. pixel size in X (mm)
         IPT = IOFFSET + 512
         IF(LOCALBYTESWAP)THEN
            CDOUBLE = CHEAD(IPT)//CHEAD(IPT+1)//CHEAD(IPT+2)//
     $           CHEAD(IPT+3)//CHEAD(IPT+4)//CHEAD(IPT+5)//
     $           CHEAD(IPT+6)//CHEAD(IPT+7)
         ELSE
            CDOUBLE = CHEAD(IPT+7)//CHEAD(IPT+6)//CHEAD(IPT+5)//
     $           CHEAD(IPT+4)//CHEAD(IPT+3)//CHEAD(IPT+2)//
     $           CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
         BASERASTX = FDOUBLE
         HRAST = BASERASTX
C     ..
C     .. assume that BASERASTX = BASERASTY for the moment...
         IF(.NOT.IIPIX)RAST = BASERASTX
         IF(RAST.LT.1E-3)THEN
            IF(BASERASTX.LT.1E-3)THEN
               WRITE(IOUT,FMT=6260)BASERASTX
               IF(ONLINE)WRITE(ITOUT,FMT=6260)BASERASTX
            ENDIF
            WRITE(IOUT,FMT=6280)
            IF(ONLINE)WRITE(ITOUT,FMT=6280)
            NSHUTERR = 1
            CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
         ENDIF
 6260    FORMAT(/,48('-'),/,' The image does not contain a cred', 
     $        'ible pixel size (',F6.4,'mm',/,' You probably ne',
     $        'ed to unwarp the images with the Crysalis program.')
 6280    FORMAT(/,' You may be able to provide a pixel size ',
     $        'with the RAST keyword (in Mosflm), but this is',
     $        'unlikely to be sufficient',/,48('='))
C     ..
C     .. pixel size in Y (mm) - not used in Mosflm at present
         IPT = IOFFSET + 520
         IF(LOCALBYTESWAP)THEN
            CDOUBLE = CHEAD(IPT)//CHEAD(IPT+1)//CHEAD(IPT+2)//
     $           CHEAD(IPT+3)//CHEAD(IPT+4)//CHEAD(IPT+5)//
     $           CHEAD(IPT+6)//CHEAD(IPT+7)
         ELSE
            CDOUBLE = CHEAD(IPT+7)//CHEAD(IPT+6)//CHEAD(IPT+5)//
     $           CHEAD(IPT+4)//CHEAD(IPT+3)//CHEAD(IPT+2)//
     $           CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
         BASERASTY = FDOUBLE
         XSCAN = INT(NREC*BASERASTX*100/2)
         YSCAN = INT(IYLEN*BASERASTY*100/2)
         XMAXIP = INT(NREC*BASERASTX*100/2)
         YMAXIP = INT(IYLEN*BASERASTY*100/2)
         RMAXIP = SQRT((XMAXIP*XMAXIP)+(YMAXIP*YMAXIP))
         IF(DEBUG(45))THEN
           WRITE(IOUT,FMT=6300)XMAXIP,YMAXIP,RMAXIP,BASERASTX,BASERASTY
           IF(ONLINE)WRITE(ITOUT,FMT=6300)XMAXIP,YMAXIP,RMAXIP,
     $          BASERASTX,BASERASTY
 6300      FORMAT('X, Y, RMAXIP ',3F9.3,/,'Pixel size (X,Y) in mm: ',
     $          F8.6,1X,F8.6)
         ENDIF
C
C---- NK
C
         IOFFSET = 257 + NG + NSPECIAL + 284
C     ..
C     .. start values for 10 goniostat angles
         IPT = IOFFSET
         DO 200 I = 1,10,1
           IF(LOCALBYTESWAP)THEN
            CLONG = CHEAD(IPT)//CHEAD(IPT+1)//
     $           CHEAD(IPT+2)//CHEAD(IPT+3)
         ELSE
            CLONG = CHEAD(IPT+3)//CHEAD(IPT+2)//
     $           CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
           LASTART(I) = ILONG
           IPT = IPT + 4
 200     ENDDO
C     ..
C     .. end values for 10 goniostat angles
         IPT = IOFFSET + 40
         DO 300 I = 1,10,1
           IF(LOCALBYTESWAP)THEN
             CLONG = CHEAD(IPT)//CHEAD(IPT+1)//
     $            CHEAD(IPT+2)//CHEAD(IPT+3)
           ELSE
             CLONG = CHEAD(IPT+3)//CHEAD(IPT+2)//
     $            CHEAD(IPT+1)//CHEAD(IPT)
           ENDIF
           LAEND(I) = ILONG
           IPT = IPT + 4
 300     ENDDO
C     ..
C     .. conversion factors to degrees for 10 goniostat angles
         IPT = IOFFSET + 84
         DO 400 I = 1,10,1
           IF(LOCALBYTESWAP)THEN
             CDOUBLE = CHEAD(IPT)//CHEAD(IPT+1)//CHEAD(IPT+2)//
     $           CHEAD(IPT+3)//CHEAD(IPT+4)//CHEAD(IPT+5)//
     $            CHEAD(IPT+6)//CHEAD(IPT+7)
           ELSE
             CDOUBLE = CHEAD(IPT+7)//CHEAD(IPT+6)//CHEAD(IPT+5)//
     $            CHEAD(IPT+4)//CHEAD(IPT+3)//CHEAD(IPT+2)//
     $            CHEAD(IPT+1)//CHEAD(IPT)
           ENDIF
           DACONV(I) = FDOUBLE
           IPT = IPT + 8
 400     ENDDO
C     ..
C     .. convert to degrees
         DO 500 I=1,10,1
           IF((DACONV(I).LE.1.0).AND.(DACONV(I).GE.0.0))THEN
             SANGLE(I) = LASTART(I) * DACONV(I) * RTOD
             FANGLE(I) = LAEND(I) * DACONV(I) * RTOD
           ELSE
             SANGLE(I) = 0.0
             FANGLE(I) = 0.0
           ENDIF
 500     ENDDO
         IF(DEBUG(45))THEN
           WRITE(IOUT,FMT=6320)(SANGLE(I),FANGLE(I),I=1,10,1)
           IF(ONLINE)WRITE(ITOUT,FMT=6320)(SANGLE(I),I=1,10,1),
     $          (FANGLE(I),I=1,10,1)
 6320      FORMAT('Goniostat angles',/,8X,'   Omega  2-theta  kappa',
     $          '    phi ',6('   spare'),
     $          /,'start:  ',10F8.3,/,'finish: ',10F8.3)
         ENDIF
C     
C---- Oxford header has angles (1) omega, (2) twotheta, (3) kappa, (4)
C     phi; set GON_* values here as well
         HOMEGAS = SANGLE(1)
         HTWOTHETA = SANGLE(2)
         HKAPPA = SANGLE(3)
         HPHIS = SANGLE(4)
         HOMEGAE = FANGLE(1)
         HPHIE = FANGLE(4)
         IF(IGON_OMEGA.EQ.0)GON_OMEGAS = HOMEGAS
         IF(IGON_PHI.EQ.0)GON_PHIS = HPHIS
         IF(IGON_KAPPA.EQ.0)GON_KAPPA = HKAPPA
C     ..
C     .. need to work out which axis we're oscillating about - it
C     should be safe to assume that we're only doing single axis scans
C     - or should it??? 
C 
         IF((FANGLE(1)-SANGLE(1)).GT.1E-3)THEN
           HOSCAXIS = 'OMEGA'
C           HPHIS = SANGLE(1)
C           HPHIE = FANGLE(1)
         ELSEIF((FANGLE(4)-SANGLE(4)).GT.1E-3)THEN
           HOSCAXIS = 'PHI'
C           HPHIS = SANGLE(4)
C           HPHIE = FANGLE(4)
C
C---- we should never have either of the two following cases happening!!
C
         ELSEIF((FANGLE(2)-SANGLE(2)).GT.1E-3)THEN
           HOSCAXIS = '2THETA'
C           HPHIS = SANGLE(2)
C           HPHIE = FANGLE(2)
         ELSEIF((FANGLE(3)-SANGLE(3)).GT.1E-3)THEN
           HOSCAXIS = 'KAPPA'
C           HPHIS = SANGLE(3)
C           HPHIE = FANGLE(3)
         ELSE
           HOSCAXIS = 'NOTSET'
           WRITE(IOUT,FMT=8020)
           IF(ONLINE)WRITE(ITOUT,FMT=8020)
C           HPHIS = SANGLE(1)
C           HPHIE = FANGLE(1)
         ENDIF
         CALL CCPUPC(HOSCAXIS)
c         IF(OLDHOSCAXIS.NE.HOSCAXIS)THEN
c           WRITE(IOUT,FMT=8000)HOSCAXIS(1:LENSTR(HOSCAXIS))
c           IF(ONLINE)WRITE(ITOUT,FMT=8000)HOSCAXIS(1:LENSTR(HOSCAXIS))
c         ENDIF
c         OLDHOSCAXIS = HOSCAXIS
C         OSCRNG = HPHIE - HPHIS
C---- Comment out next line (wrong) 5 sep 08
C
CAL         IANGLE = 0
 8000    FORMAT(/,' Oscillation axis set as ',A,' from ',
     $               'image header',/,1X,45('='))
 8020    FORMAT(/,'Oscillation axis not specified in image ',
     $               'header - set to OMEGA',/,1X,45('='))
                    
C     ..
C     .. beam rotation around E2 - what's this in Mosflm convention?
         IPT = IOFFSET + 268
         IF(LOCALBYTESWAP)THEN
            CDOUBLE = CHEAD(IPT)//CHEAD(IPT+1)//CHEAD(IPT+2)//
     $           CHEAD(IPT+3)//CHEAD(IPT+4)//CHEAD(IPT+5)//
     $           CHEAD(IPT+6)//CHEAD(IPT+7)
         ELSE
            CDOUBLE = CHEAD(IPT+7)//CHEAD(IPT+6)//CHEAD(IPT+5)//
     $           CHEAD(IPT+4)//CHEAD(IPT+3)//CHEAD(IPT+2)//
     $           CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF

         DB2DEG = FDOUBLE
C     ..
C     .. beam rotation around E3 - what's this in Mosflm convention?
         IPT = IOFFSET + 276
         IF(LOCALBYTESWAP)THEN
            CDOUBLE = CHEAD(IPT)//CHEAD(IPT+1)//CHEAD(IPT+2)//
     $           CHEAD(IPT+3)//CHEAD(IPT+4)//CHEAD(IPT+5)//
     $           CHEAD(IPT+6)//CHEAD(IPT+7)
         ELSE
            CDOUBLE = CHEAD(IPT+7)//CHEAD(IPT+6)//CHEAD(IPT+5)//
     $           CHEAD(IPT+4)//CHEAD(IPT+3)//CHEAD(IPT+2)//
     $           CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF

         DB3DEG = FDOUBLE
C     ..
C     .. alpha1 of the wavelength
         IPT = IOFFSET + 284
         IF(LOCALBYTESWAP)THEN
            CDOUBLE = CHEAD(IPT)//CHEAD(IPT+1)//CHEAD(IPT+2)//
     $           CHEAD(IPT+3)//CHEAD(IPT+4)//CHEAD(IPT+5)//
     $           CHEAD(IPT+6)//CHEAD(IPT+7)
         ELSE
            CDOUBLE = CHEAD(IPT+7)//CHEAD(IPT+6)//CHEAD(IPT+5)//
     $           CHEAD(IPT+4)//CHEAD(IPT+3)//CHEAD(IPT+2)//
     $           CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF

         DALPHA1ANG = FDOUBLE
         IF(DEBUG(45))THEN
           WRITE(IOUT,FMT=8040)DB2DEG,DB3DEG,DALPHA1ANG
           IF(ONLINE)WRITE(ITOUT,FMT=8040)DB2DEG,DB3DEG,DALPHA1ANG
 8040      FORMAT('Beam rotations about E2 & E3: ',2F8.3,/,
     $          'Wavelength: ',F9.6)
         ENDIF
         HWAVE = DALPHA1ANG
         IF(IWAVE.EQ.0)THEN
           WAVE = HWAVE
           IWAVE = 1
         ENDIF

C     ..
C     .. detector rotations about E1, E2, E3 (TILT, TWIST, CCOMEGA, but
C     .. which order?)
         IPT = IOFFSET + 356
         DO 600 I = 1,3,1
           IF(LOCALBYTESWAP)THEN
             CDOUBLE = CHEAD(IPT)//CHEAD(IPT+1)//CHEAD(IPT+2)//
     $            CHEAD(IPT+3)//CHEAD(IPT+4)//CHEAD(IPT+5)//
     $            CHEAD(IPT+6)//CHEAD(IPT+7)
           ELSE
             CDOUBLE = CHEAD(IPT+7)//CHEAD(IPT+6)//CHEAD(IPT+5)//
     $            CHEAD(IPT+4)//CHEAD(IPT+3)//CHEAD(IPT+2)//
     $            CHEAD(IPT+1)//CHEAD(IPT)
           ENDIF
           DADROTDEG(I) = FDOUBLE
           IPT = IPT + 8
 600     ENDDO
         IF(DEBUG(45))THEN
           WRITE(IOUT,FMT=8060)DADROTDEG
           IF(ONLINE)WRITE(ITOUT,8060)DADROTDEG
 8060      FORMAT('Detector rotations E1, E2, E3',3F8.4)
         ENDIF
C     ..
C     .. X origin
         IPT = IOFFSET + 380
         IF(LOCALBYTESWAP)THEN
            CDOUBLE = CHEAD(IPT)//CHEAD(IPT+1)//CHEAD(IPT+2)//
     $           CHEAD(IPT+3)//CHEAD(IPT+4)//CHEAD(IPT+5)//
     $           CHEAD(IPT+6)//CHEAD(IPT+7)
         ELSE
            CDOUBLE = CHEAD(IPT+7)//CHEAD(IPT+6)//CHEAD(IPT+5)//
     $           CHEAD(IPT+4)//CHEAD(IPT+3)//CHEAD(IPT+2)//
     $           CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF

         DORIX = FDOUBLE
C     ..
C     .. Y origin
         IPT = IOFFSET + 388
         IF(LOCALBYTESWAP)THEN
            CDOUBLE = CHEAD(IPT)//CHEAD(IPT+1)//CHEAD(IPT+2)//
     $           CHEAD(IPT+3)//CHEAD(IPT+4)//CHEAD(IPT+5)//
     $           CHEAD(IPT+6)//CHEAD(IPT+7)
         ELSE
            CDOUBLE = CHEAD(IPT+7)//CHEAD(IPT+6)//CHEAD(IPT+5)//
     $           CHEAD(IPT+4)//CHEAD(IPT+3)//CHEAD(IPT+2)//
     $           CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF

         DORIY = FDOUBLE
         IF(IBEAM.EQ.0)THEN
           IBEAM = 3
C     ..
C     .. note X and Y swapped - or are they hrp 15.11.2011?
           HBEAMy = DORIX * BASERASTY/FLOAT(INT(IBY))
           HBEAMx = (float(INT(iYW)) - DORIY) * 
     $          BASERASTX/FLOAT(INT(IBX))
         ENDIF
         IF(DEBUG(45))THEN
           WRITE(IOUT,FMT=8080)HBEAMX,HBEAMY,dorix,doriy
           IF(ONLINE)WRITE(ITOUT,FMT=8080)HBEAMX,HBEAMY,dorix,doriy
 8080      FORMAT('HBEAMX: ',F8.2,' HBEAMY: ',F8.2,' X & Y origins: ',
     $          2F9.3)
         ENDIF
C     ..
C     .. Alpha angle ( = kappa_gon_set)
         IPT = IOFFSET + 396
         IF(LOCALBYTESWAP)THEN
            CDOUBLE = CHEAD(IPT)//CHEAD(IPT+1)//CHEAD(IPT+2)//
     $           CHEAD(IPT+3)//CHEAD(IPT+4)//CHEAD(IPT+5)//
     $           CHEAD(IPT+6)//CHEAD(IPT+7)
         ELSE
            CDOUBLE = CHEAD(IPT+7)//CHEAD(IPT+6)//CHEAD(IPT+5)//
     $           CHEAD(IPT+4)//CHEAD(IPT+3)//CHEAD(IPT+2)//
     $           CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF
         DALPHA = FDOUBLE
         IF(IGON_KAPPA_SET.EQ.0)GON_KAPPA_SET = DALPHA
         IF(DEBUG(45))THEN
           WRITE(IOUT,FMT=8100)GON_KAPPA_SET
           IF(ONLINE)WRITE(ITOUT,FMT=8100)GON_KAPPA_SET
 8100      FORMAT('Setting angle of kappa block (alpha) is :',F7.3)
         ENDIF
C     ..
C     .. crystal to detector distance in mm
         IPT = IOFFSET + 428
         IF(LOCALBYTESWAP)THEN
            CDOUBLE = CHEAD(IPT)//CHEAD(IPT+1)//CHEAD(IPT+2)//
     $           CHEAD(IPT+3)//CHEAD(IPT+4)//CHEAD(IPT+5)//
     $           CHEAD(IPT+6)//CHEAD(IPT+7)
         ELSE
            CDOUBLE = CHEAD(IPT+7)//CHEAD(IPT+6)//CHEAD(IPT+5)//
     $           CHEAD(IPT+4)//CHEAD(IPT+3)//CHEAD(IPT+2)//
     $           CHEAD(IPT+1)//CHEAD(IPT)
         ENDIF

         DDDMM = FDOUBLE
         IF(DEBUG(45))THEN
           WRITE(IOUT,FMT=8120)DDDMM
           IF(ONLINE)WRITE(ITOUT,FMT=8120)DDDMM
 8120      FORMAT('Distance (mm): ',F8.2)
         ENDIF
         HDIST = DDDMM
         IF(IDIST.EQ.0)THEN
           XTOFD = 100 * HDIST
           CAMCON(3) = HDIST
           IDIST = 1
         ENDIF
         CALL QCLOSE(INOD)
         RETURN
         END

C $Id: matmul3.f,v 1.2 2006/02/06 18:01:16 harry Exp $
C== MATMUL3 ==
C
C
      SUBROUTINE MATMUL3(A,B,C)
C     =========================
      IMPLICIT NONE
C
C---- Multiply 2 3x3 matrices
C
C      A=BC
C
C     .. Array Arguments ..
      REAL A(3,3),B(3,3),C(3,3)
C     ..
C     .. Local Arrays ..
      DOUBLE PRECISION AD(3,3)
C     ..
C     .. Local Scalars ..
      INTEGER I,J,K
C     ..
C
C
      DO 30 I = 1,3
        DO 20 J = 1,3
          AD(I,J) = 0.0D0
          DO 10 K = 1,3
            AD(I,J) = DBLE(B(I,K))*DBLE(C(K,J)) + AD(I,J)
   10     CONTINUE
          A(I,J) = REAL(AD(I,J))
   20   CONTINUE
   30 CONTINUE
C
C
      END
C     $Id: matmulsq.f,v 1.3 2018/07/18 12:31:06 andrew Exp $
      SUBROUTINE MATMULSQ(RESULT,A,B,RANK)
      IMPLICIT NONE
C
C     multiplies two square matrices  A and B of size RANK and
C     returns result in square matrix RESULT
C
C     ..
C     .. parameters
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     ..
C     .. Scalar arguments
      INTEGER RANK
C     ..
C     .. Array arguments
      REAL RESULT(RANK*RANK),A(RANK*RANK),B(RANK*RANK)
C     ..
C     .. Local scalars
      REAL FTEMP
      INTEGER IC,JC,KC,MC
C     ..
C     .. Local arrays
      REAL RESULTD(RANK,RANK),AD(RANK,RANK),BD(RANK,RANK)
        JC = 0
C     ..
C     .. zero RESULTD
      DO 1020 IC=1,RANK
        KC = (IC - 1) * RANK
        DO 1000 JC=1,RANK
          RESULTD(IC,JC) = 0.0
          AD(IC,JC) = A(KC + JC)
          BD(IC,JC) = B(KC + JC)
 1000   ENDDO
 1020 ENDDO
      DO 1080 IC=1,RANK
        MC = (IC - 1) * RANK
        DO 1060 JC=1,RANK
            RESULTD(IC,JC) = 0.0
          DO 1040 KC=1,RANK
            RESULTD(IC,JC) =  AD(IC,KC) * BD(KC,JC) + RESULTD(IC,JC)
 1040     ENDDO
          RESULT(MC + JC) = RESULTD(IC,JC)
 1060   ENDDO
 1080 ENDDO
      RETURN
      END
C== MATSET ==
C $Id: matset.f,v 1.5 2012/02/23 14:50:01 andrew Exp $
C
C
      SUBROUTINE MATSET(UCELL,NRCELL,IPRINT)
      IMPLICIT NONE
C     =====================================
C
C
C---- Calculates A = U x B matrix and its derivatives
C     wrt. cell parameters
C     The UMAT is passed in through /CELL/ but BMAT must be calculated
C     using the latest (refined) cell parameters
C---- Cell dimension matrices and derivatives in common CELL
C     Angles in radians, real cell edges in Angstrom
C
C     Input:
C     UCELL      The unique refinable/refined cell parameters
C     NRCELL     Number of refined parameters
C     IPRINT     Print flag, gives debug output if .ge.2
C
C
C     .. Scalar Arguments ..
      INTEGER IPRINT,NRCELL
C     ..
C     .. Array Arguments ..
      REAL UCELL(6)
C     ..
C     .. Local Scalars ..
      REAL A,AA,B,BA,C,CA,CB,CCC,CG,CTT,FAC,GA,SA,SB,SG,STEMP
      INTEGER I,J,K,L,LC,N
C     ..
C     .. Local Arrays ..
      REAL TMAT(3,3)
C     ..
C     .. External Subroutines ..
      EXTERNAL CLEAR,MATMUL3
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC ATAN,COS,SIN,SQRT
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/cell.f
C
C $Id: cell.f,v 1.4 2012/11/21 14:41:22 andrew Exp $
C
C--- awk generated include file  cell.h
C---- START of include file cell.h
C
C     CELL cell dimensions (real space)
C     RCELL reciprocal cell parameters in dimensionless rlu
C     LCELL indicator for cell parameters to be refined
C     
C     LCELL(I) = -1  parameter free
C              =  0  parameter fixed
C              >  0, = J  parameter I constrained to = parameter J
C
C     .. Arrays in Common /CELLCOM/ ..
      REAL UMAT,BMAT,GMAT,CELL,RCELL,UMATCELL,SOFTCELL,VOLUME
      INTEGER LCELL,ICRYST,NUMSPG,NLAUE
C     ..
C     .. Common Block /CELLCOM/ ..
      COMMON /CELLCOM/UMAT(3,3),BMAT(3,3),GMAT(3,3),CELL(6),RCELL(6),
     $       UMATCELL(6),SOFTCELL,VOLUME,LCELL(6),ICRYST,NUMSPG,NLAUE
C     ..
C
C
C&&*&& end_include  ../inc/cell.f
C&&*&& include  ../inc/idxcell.f
C
C $Id: idxcell.f,v 1.1 2002/05/02 10:46:51 harry Exp $
C
C--- awk generated include file  idxcell.h
C---- START of include file idxcell.h
C
C     ..
C     ..
C     .. Arrays in Common /IDXCELL/  ..
      REAL DUBDCC
C     ..
C     .. Common blocks ..
       COMMON /IDXCELL/ DUBDCC(3,3,6)
C     ..
C
C
C&&*&& end_include  ../inc/idxcell.f
C&&*&& include  ../inc/ioo.f
C
