C     
C---- Scalar arguments
C     
      INTEGER IRECG,LASTREC,IMODE
      REAL BGRAT
C     ..
C     .. Array Arguments ..
      INTEGER INTPOST(2),SIGPOST(2)
C     
C---- Local scalars
C     
      INTEGER ICOUNT,JCOUNT,NCOUNT,NCOL,SAME_ID,JMAX,KTEMP
CHRP 10.08.2015      INTEGER ICOUNT,NCOUNT,NCOL,SAME_ID,JMAX,KTEMP
      INTEGER IDUM,JDUM,KDUM,NDBG,ICHK,NHKL
      INTEGER I,II,J,K,L,IREASON,CURRENT_ID,NCOMPLETE,NREJECT,IHGR,
     +     IKGR,ILGR,NTOOWIDE,NNONSEQ,NNEWNOTFP,NLAST,NPRINT,
     +     IPART,istored(3),FREESLOTS,IBIT,IXPIX,IYPIX,NPREFEXCL,
     +     EXCLUDERING,maxrock,IBEG,IEND,IDIR
      REAL SUMINT,CHKPOST1,CHKPOST2,CHKPOST3,FRCCALC(2),FRCOBS(2),
     +      FSIGPOST(2),XC,YC,XCAL,YCAL,RESOL

      LOGICAL LASTPART,NOTWARN,ICHECK
      CHARACTER CALLEDFROM*80,XMLLINE*1024,IOLINE*1024
C     ..
C     .. LOCAL ARRAYS
      INTEGER   IPARTS(4,MGRA,NGRA),IXYHKL(3,MGRA),NPARTS(MGRA),
     $     NROCKING(NGRA)
      REAL      FPARTS(MGRA,NGRA),FXYHKL(5,MGRA),FRACTOT(MGRA),
     $     ROCKING(NGRA,NGRA),SDROCKING(NGRA,NGRA),SPLIT(2,NGRA)
C     ..
C     .. External Functions ..
      INTEGER LENSTR
      EXTERNAL LENSTR
C     ..
C     .. External Subroutines ..
      EXTERNAL CRESOL,SETUPICE,SHUTDOWN,SORTPART,MMTOPX
C     ..
      SAVE
C     
C     .. Data statements ..
      DATA NOTWARN/.TRUE./,istored/0,0,0/,IDIR/0/
      CALLEDFROM = 'MODARRAY'
C     
C---- First check to see if IMODE is in the allowed range, else print
C     error message and return with error
C     
      IERRFLG = 0
      IF ((IMODE .LT. 0) .OR. (IMODE .GT. 4)) THEN
        WRITE(IOUT,7000)
        IF (ONLINE) WRITE(ITOUT,FMT=7000)
        IERRFLG = 1
        RETURN
      ENDIF
 7000 FORMAT(1X,'IMODE is an invalid value - check the FORTRAN source')
C     
C-----------------------------------------------------------------------
C     
C     ---- Initialize HKL array; if we find a large and negative value,
C     we can
C     put a new reflection in this location. Otherwise we have to look
C     at 
C     the next location. Once a reflection has been passed for post
C     -refinement,
C     we reset this value to a larger negative number, e.g. -9999. 
C     
      IF (IMODE.EQ.0) THEN
C     
        IF (DEBUG(68))THEN
          WRITE(IOUT,FMT=7010) IMODE
          IF (ONLINE) WRITE(ITOUT,FMT=7010) IMODE
 7010     FORMAT('MODARRAY initializing array for partials, MODE = ',
     $         I1)
        ENDIF
C     
        II = 0
        K = 0
        DO 105 I=1,NGRA
          NROCKING(I) = 0
          SPLIT(1,I) = 0.0
          SPLIT(2,I) = 0.0
          DO 106 J=1,NGRA
            ROCKING(I,J) = 0.0
            SDROCKING(I,J) = 0.0
 106      ENDDO
 105    ENDDO
        DO 110 I=1,MGRA
C     
C---- only need to reset those elements which have changed
C     
          IF(IXYHKL(1,I).NE.9999)THEN
            IXYHKL(1,I) = 9999
            II = II + 1
            DO 100  J=1,NGRA
              IF(IPARTS(1,I,J).NE.0)THEN
                IPARTS(1,I,J) = 0
                K = K + 1
              ENDIF
 100        CONTINUE
          ENDIF
 110    CONTINUE
        NHKL = 0
        NLAST = 0
        JMAX = 0
        NCOMPLETE = 0
        NREJECT = 0
        NNONSEQ = 0
        NNEWNOTFP = 0
        NPREFEXCL = 0
        IF(DEBUG(68))THEN
          IF(ONLINE)WRITE(ITOUT,FMT=7015)II,K
          WRITE(IOUT,FMT=7015)II,K
        ENDIF
 7011   FORMAT(/,'IXYHKL(1,',I5,') was ',I5)
 7012   FORMAT('   and it''s now..........',I5)
 7013   FORMAT('IPARTS(',I5,',',I2,') was ',I5)
 7014   FORMAT('   and it is now............',I5)
 7015   FORMAT(132('*'),/,I5,' locations of the big array have been ',
     $       'zeroed including ',I5,' locations previously containing',
     $       ' reflections',/,132('*'))

C
C---- Set up ice resolution shells
C
        IF (PREFEXICE) THEN
          EXCLUDERING = 13
          NEXCL2 = 0
          IF (DEBUG(68)) THEN
            WRITE(IOUT,FMT=6006) EXCLUDERING
            IF (ONLINE) WRITE(ITOUT,FMT=6006) EXCLUDERING
 6006       FORMAT(1X,'Set up the',I3,' ice exclusion bins')
          END IF
          CALL SETUPICE(RES3EXL,RES3EXH,EXCLUDERING,NEXCL2,ICEWIDTHPREF)
        END IF
        RETURN
C
C----   end of IMODE = 0
C
      ENDIF                     


C     
C-----------------------------------------------------------------------
C     
C     Check which reflections have been passed for post-refinement,
C     push up the next active reflection into its place. This is called at 
C     the end of every image.
C     
C     
      IF (IMODE.EQ.1) THEN
        IF (DEBUG(68))THEN
          WRITE(IOUT,FMT=7020) CURRENT_ID,PHIPROF
          IF (ONLINE) WRITE(ITOUT,FMT=7020) CURRENT_ID,PHIPROF
 7020     FORMAT('MODARRAY Checking which reflections have been sent',
     $         /,'for post-refinement, and pushing up next ',
     $         'active reflection.'/,1X,'Current ID',I5,'  PHIPROF',L2)
          NPRINT = MIN(NDEBUG(68),JMAX)
          WRITE(IOUT,FMT=7244) NPRINT,((IXYHKL(I,J),I=1,3),
     +         (IPARTS(1,J,L),IPARTS(2,J,L),L=1,10),J=1,NPRINT)
          IF (ONLINE) WRITE(ITOUT,FMT=7244) NPRINT,((IXYHKL(I,J),I=1,3)
     +         ,(IPARTS(1,J,L),IPARTS(2,J,L),L=1,10),J=1,NPRINT)
 7244     FORMAT(1X,'Before elimination, list of the KHF and ID for',
     +           ' up to 10 parts of the first',I5,' reflections',
     +           /,1X,'   H   K   L     ','KHF  ID',4X,'KHF  ID',4X,
     +           'KHF  ID',4X,'KHF  ID',4X,'KHF  ID',4X,'KHF  ID',4X,
     +           'KHF  ID',4X,'KHF  ID',4X,'KHF  ID',4X,'KHF  ID',
     +          /,(1X,3I4,3X,10(I5,I4,2X)))
        ENDIF
C     
        ICOUNT = 1
        JCOUNT = 1
        IF (PHIPROF) THEN
C
C---- Simply count the number of reflections entered so far. Do not remove
C     finished reflections when calculating phi profiles.
C
          DO 126 WHILE ((IXYHKL(1,ICOUNT).NE.9999).and.(icount.le.mgra))
            ICOUNT = ICOUNT + 1
 126      CONTINUE
          JCOUNT = ICOUNT
          GOTO 128
        END IF
C     
C---- the first unfilled record will have IXYHKL(1,ICOUNT) .eq. 9999, so
C     ...
C     
        DO 121 WHILE ((IXYHKL(1,ICOUNT) .NE. 9999).and.(icount.le.mgra))
C     
C---- i.e. this record isn't empty
C     
C     
C---- tidy up stray unfinished reflections. Check if current 
C     image is more than (reflection width in images) away
C     from image number on which it started.
C     
cdms21.09.2004   Change ABS to IABS for integer argument.
          IF (CURRENT_ID-INT(IABS(IPARTS(1,ICOUNT,1)/IPAD))
     $         .GT.IPARTS(2,ICOUNT,1)) THEN
            IPARTS(1,ICOUNT,1) = -IABS(IPARTS(1,ICOUNT,1))
            IF (DEBUG(68)) THEN
              WRITE(IOUT,FMT=7210) (IXYHKL(I,ICOUNT),I=1,3),
     +             FXYHKL(3,ICOUNT),ICOUNT,JCOUNT,
     +             (IPARTS(1,ICOUNT,J), IPARTS(2,ICOUNT,J),J=1,6)
              IF (ONLINE) WRITE(ITOUT,FMT=7210) 
     +             (IXYHKL(I,ICOUNT),I=1,3),FXYHKL(3,ICOUNT),
     +             ICOUNT,JCOUNT,
     +             (IPARTS(1,ICOUNT,J), IPARTS(2,ICOUNT,J),J=1,6)
            END IF
 7210       FORMAT(1X,' *** reflection ',3I4,' at phi=',F7.2,
     +           ' rejected as finished, ICOUNT,JCOUNT ',I6,1X,I6,/,1X,
     +           'KHF, ID for first 6 parts  ',6(I5,I4,3X))
cdms21.09.2004  JCOUNT = JCOUNT - 1     Causes halt when first reflection
c                                       is rejected.
          END IF
          IF(JCOUNT.GT.MGRA)THEN
            WRITE(IOUT,FMT=7220)JCOUNT - 1 
            IF(ONLINE)WRITE(ITOUT,FMT=7220)JCOUNT - 1
            NSHUTERR = 1
            CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
 7220 FORMAT(/,1X,64('*'),/
     $     ,' The big array (which is used for postrefinement) ',
     $     'now contains',/,' information for ',I5,' spots - this is',
     $     ' a huge number. If you',/,' really need to use so many, ',
     $     ' you will have to rebuild Mosflm',/,' after',
     $     ' changing the parameter MGRA to a larger value.'/,1X,
     $     64('*'))
          ENDIF
          IF(JCOUNT.LE.0)THEN
            WRITE(IOUT,FMT=7225)JCOUNT
            IF(ONLINE)WRITE(ITOUT,FMT=7225)JCOUNT
 7225       FORMAT(/,64('*'),/,' The counter for locations in the bi',
     $           'g array has reached a value of ',I5,'; you should',
     $           /,' consult the authors of the program for advice o',
     $           'n how to proceed if Mosflm shuts down at this point')
C            NSHUTERR = 2
C            CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
          ENDIF
C     
C----  
C     
C
          IF (IPARTS(1,ICOUNT,1) .LT. 0) THEN
C     
C---- i.e. this record contains information about a reflection that has
C     been used already for post-refinement, so it can be overwritten with
C     the next record
C
 120        ICOUNT = ICOUNT + 1 
C     
C---- Need to check that this reflection is OK before storing it.
C     
cdms21.09.2004   Add check for end of list reached.
            IF (IXYHKL(1,ICOUNT).EQ.9999) GO TO 1210
C
            IF (IPARTS(1,ICOUNT,1) .LT. 0) GOTO 120
          ENDIF
C     
C---- this has to be kept for adding more parts, so push it up the stack
C     
          IXYHKL(1,JCOUNT) = IXYHKL(1,ICOUNT)
          IXYHKL(2,JCOUNT) = IXYHKL(2,ICOUNT)
          IXYHKL(3,JCOUNT) = IXYHKL(3,ICOUNT)
          FXYHKL(1,JCOUNT) = FXYHKL(1,ICOUNT)
          FXYHKL(2,JCOUNT) = FXYHKL(2,ICOUNT)
          FXYHKL(3,JCOUNT) = FXYHKL(3,ICOUNT)
          FXYHKL(4,JCOUNT) = FXYHKL(4,ICOUNT)
          FRACTOT(JCOUNT) = FRACTOT(ICOUNT)
          NPARTS(JCOUNT) = NPARTS(ICOUNT)
C     
C---- Start looping across the parts of each reflection. Need to
C     transfer all NGRA parts to overwrite any non-zero parts from
C     the reflection that used to be stored at this position.
C     
          DO 125 NCOUNT=1,NGRA
            IPARTS(1,JCOUNT,NCOUNT) = IPARTS(1,ICOUNT,NCOUNT)
            IPARTS(2,JCOUNT,NCOUNT) = IPARTS(2,ICOUNT,NCOUNT)
            IPARTS(3,JCOUNT,NCOUNT) = IPARTS(3,ICOUNT,NCOUNT)
            IPARTS(4,JCOUNT,NCOUNT) = IPARTS(4,ICOUNT,NCOUNT)
            FPARTS(JCOUNT,NCOUNT) = FPARTS(ICOUNT,NCOUNT)
 125      ENDDO

C     WRITE(IOUT,FMT=7246) JCOUNT,ICOUNT,(IXYHKL(I,JCOUNT),
C     +      I=1,3), (IPARTS(1,JCOUNT,I),IPARTS(2,JCOUNT,I),I=1,10)
C     7246       FORMAT(1X,'JC=',I4,'  IC=',I4,2x,3I4,10(2I4,3X))
C     
          ICOUNT = ICOUNT + 1
          JCOUNT = JCOUNT + 1
 1210     CONTINUE
 121    ENDDO 
C     
C---- More debug
C     
 128    NHKL = JCOUNT - 1
        NLAST = NHKL
        IF (DEBUG(68)) THEN
          WRITE(IOUT,FMT=7200) ICOUNT,JCOUNT,ICOUNT-JCOUNT
          IF (ONLINE) WRITE(ITOUT,FMT=7200) ICOUNT,JCOUNT,
     +         ICOUNT-JCOUNT
 7200     FORMAT(/,/,1X,'After eliminating finished reflections',
     +         ' ICOUNT,JCOUNT',2I6,'  Number rejected',I5,/)
          NPRINT = MIN(NDEBUG(68),NHKL)
          WRITE(IOUT,FMT=7245) NPRINT,
     +         ((IXYHKL(I,J),I=1,3),(IPARTS(1,J,L),
     +         IPARTS(2,J,L),FXYHKL(3,J),FPARTS(J,L),L=1,4),J=1,NPRINT)
          IF (ONLINE) WRITE(ITOUT,FMT=7245) NPRINT,
     +         ((IXYHKL(I,J),I=1,3),
     +         (IPARTS(1,J,L),IPARTS(2,J,L),FXYHKL(3,J),
     +         FPARTS(J,L),L=1,4),J=1,NPRINT)
 7245     FORMAT(1X,'After elimination, list of the first',I5,
     +           ' reflections',/,1X,'   H   K   L     ',
     +          'KHF  ID   PHI FRAC',4X,'KHF  ID   PHI FRAC',4X,
     +          'KHF  ID   PHI FRAC',4X,'KHF  ID   PHI FRAC',/,
     +          (1X,3I4,3X,4(I5,I4,F6.1,F5.2,2X)))
        END IF
C     
C---  Sort array on H,K,L indices
C     
        CALL SORTPART(NHKL,FXYHKL,IXYHKL,FPARTS,IPARTS,NPARTS,FRACTOT)
        IF (DEBUG(68)) THEN
          WRITE(IOUT,FMT=7240) NHKL
          IF (ONLINE) WRITE(ITOUT,FMT=7240) NHKL
 7240     FORMAT(1X,'Sorting',I5,' reflections on h,k,l in MODE=1')
C     WRITE(IOUT,FMT=7242) ((IXYHKL(I,J),I=1,3),(IPARTS(1,J,L),
C     +         IPARTS(2,J,L),FXYHKL(3,J),FPARTS(J,L),L=1,4),J=1,NHKL)
C     7242      FORMAT((1X,3I4,3X,4(I5,I4,F6.1,F5.2,2X)))
        END IF
C     
C---- and now we reset values of IXYHKL(1,*) to 9999 ready for re
C     -filling, 
C     and IPARTS(1,*,*)  to 0.
C     
        DO 140 I=JCOUNT,MGRA
          IXYHKL(1,I) = 9999
          DO 130 J=1,NGRA
            IPARTS(1,I,J) = 0
 130      ENDDO
 140    ENDDO
        NDBG = 1
        IF (DEBUG(68))THEN
          IF(ONLINE)WRITE(ITOUT,7040)JCOUNT-1,NCOMPLETE,NREJECT,
     +         NTOOWIDE,NGRA,NNONSEQ,NNEWNOTFP
          WRITE(IOUT,7040)JCOUNT-1,NCOMPLETE,NREJECT,NTOOWIDE,NGRA,
     +         NNONSEQ,NNEWNOTFP
 7040     FORMAT(/,/,1X,80('*'),/,/,11X,I6,' locations of the big',
     $         ' array contain reflection data',/,11X,I6,
     $         ' reflections have been completed this image',/,
     $         11X,I6,' reflections have been rejected this cycle',
     +         /,1X,I5,' reflections too wide (more than ',I2,' parts)',
     +         /,1X,I5,' reflections with non-sequential IDs',
     +         /,1X,I5,' reflections where first occurrence does not',
     +         ' have first part present',
     $         /,1X,80('*'),/,/)
          do 2191 idum = 2,NGRA
            if (NROCKING(IDUM).GT.0)MAXROCK = IDUM
 2191     ENDDO
        DO 219 IDUM=2,NGRA ! MAXROCK
          IF(NROCKING(IDUM).GT.0)THEN
            WRITE(IOUT,7045)IDUM,
     $         NROCKING(IDUM),
     $           (ROCKING(IDUM,JDUM)/NROCKING(IDUM),JDUM=1,IDUM)
            WRITE(IOUT,7046)
     $           (SQRT((SDROCKING(IDUM,JDUM)**2)/NROCKING(IDUM)),
     $           JDUM=1,IDUM)
            WRITE(IOUT,7048)IDUM,
     $           SPLIT(1,IDUM)/NROCKING(IDUM),
     $           SPLIT(2,IDUM)/NROCKING(IDUM)
          ELSE
            WRITE(IOUT,7045)IDUM,
     $         NROCKING(IDUM),
     $           (ROCKING(IDUM,JDUM),JDUM=1,IDUM)
            WRITE(IOUT,7046)
     $           ((SDROCKING(IDUM,JDUM)**2),
     $           JDUM=1,IDUM)
            WRITE(IOUT,7048)IDUM,
     $           SPLIT(1,IDUM),
     $           SPLIT(2,IDUM)
          ENDIF
          IF(ONLINE)THEN
            IF(NROCKING(IDUM).GT.0)THEN
              WRITE(ITOUT,7045)IDUM,
     $         NROCKING(IDUM),
     $             (ROCKING(IDUM,JDUM)/NROCKING(IDUM),JDUM=1,IDUM)
              WRITE(ITOUT,7046)
     $             (SQRT((SDROCKING(IDUM,JDUM)**2)/NROCKING(IDUM)),
     $             JDUM=1,IDUM)
              WRITE(ITOUT,7048)IDUM,
     $           SPLIT(1,IDUM)/NROCKING(IDUM),
     $           SPLIT(2,IDUM)/NROCKING(IDUM)
            ELSE
              WRITE(ITOUT,7045)IDUM,
     $         NROCKING(IDUM),
     $             (ROCKING(IDUM,JDUM),JDUM=1,IDUM)
              WRITE(ITOUT,7046)
     $             ((SDROCKING(IDUM,JDUM)**2),
     $             JDUM=1,IDUM)
              WRITE(ITOUT,7048)IDUM,
     $           SPLIT(1,IDUM),
     $           SPLIT(2,IDUM)
            ENDIF
          ENDIF
          NROCKING(IDUM) = 0
          DO 2190 JDUM = 1,IDUM
            ROCKING(IDUM,JDUM) = 0.0
            SDROCKING(IDUM,JDUM) = 0.0
 2190     ENDDO
          
          SPLIT(1,IDUM) = 0.0
          SPLIT(2,IDUM) = 0.0
 219    ENDDO
 7045   format('Reflection with ',I3,' parts has this spread: ',
     $       i3,': ',50(1X,F4.0))
 7046   format(48X,50(1X,F4.0))
 7048   format(' Fraction OBS',I2,': ',F8.3,
     $       ', CALC: ',F8.3)
 7047   format('                                  average:      ',
     $       50(1X,F4.0))
        ENDIF
        WRITE(IOUT,FMT=7050) NPREFEXCL
        IF (ONLINE) WRITE(ITOUT,FMT=7050) NPREFEXCL
 7050   FORMAT(/,1X,I5,' reflections excluded from within ',
     +           'ice rings.')
        NPREFEXCL = 0
        NTOOWIDE = 0
        NREJECT = 0
        NCOMPLETE = 0
        NNONSEQ = 0
        NNEWNOTFP = 0
        FREESLOTS = MGRA - JCOUNT
        RETURN
C     
C---- end of IMODE = 1
C     
      ENDIF                     
C     
C-----------------------------------------------------------------------
C     
C---- Add a part of a reflection to the list. This should be called for
C     every partial reflection. If new, it is placed in a vacant slot, 
C     if already in the list then this part is added to the existing ones.
C     
      IF (IMODE.EQ.2) THEN
        KHF = IRG(IRECG)
        LASTPART = .FALSE.
        LASTREC = 0
C     
        IF (KHF.EQ.0) THEN
          WRITE(IOUT,FMT=7230)
          IF (ONLINE) WRITE(ITOUT,FMT=7230)
 7230     FORMAT(1X,'*** modarray CALLED WITH KHF=0 (i.e. this is ',
     $         'not a valid part of a reflection!!!')
          RETURN
        ENDIF
        NCOL = INT(KHF/IPAD)
        IPART = KHF - IPAD*NCOL
C     hrp18072000
C     if partial spread over too many images...
C     This is better done by checking NCOL, there is no point storing
C     any part of the reflection if it is known to be too wide. AGWL 16/6/11
C
CAL        IF (IPART.GT.NGRA) THEN
        IF (NCOL.GT.NGRA) THEN
          NTOOWIDE = NTOOWIDE +1
          RETURN
        END IF
C
C---- Test if this is the final part of this reflection (based on the
C     KHF flag. If it is, then this reflection will not be present on
C     the next image and needs to be dealt with now, flagged by
C     setting LASTPART true.
C
        IF (NCOL.EQ.IPART) LASTPART = .TRUE.
C     
C---- reset reflection counter and sort array if new image
C     
        IF (SAME_ID .NE. ID) THEN
          CURRENT_ID = ID
          NDBG = 1
          SAME_ID = ID
        ENDIF
        JCOUNT = 1
        IHGR = IHG(IRECG)         
        IKGR = IKG(IRECG)         
        ILGR = ILG(IRECG) 
C     
C---- We have to count through the array until we find EITHER 
C     (1) 9999 in an H field (reflection unused so far) OR
C     (2) 0 in a KHF field (this part of the reflection not used yet)
C     
 150    IF (JCOUNT.GT.MGRA) THEN
          IF (NOTWARN) THEN
            WRITE(IOUT,FMT=7260) MGRA
            IF (ONLINE) WRITE(ITOUT,FMT=7260) MGRA
            NOTWARN = .FALSE.
          END IF
          NSHUTERR = 3
          CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
        END IF
 7260   FORMAT(///,1X,'***** SERIOUS PROBLEM *****',
     +       /,1X,'Number of reflections to be stored for',
     +       ' postrefinement exceeds limit of',I6,/,1X,
     +       'Need to recompile program increasing parameter',
     +       ' MGRA.')
C     
        IF (JCOUNT.GT.NHKL) GOTO 180
C     
C---- this reflection is already in the array
C     
C---- check for exact match to HKL, i.e. this reflection has already had
C     parts put into the array.
C     
C-----For first NHKL reflections, which have already been sorted, can
C     implement a stricter test, but for reflections beyond that
C     
C---- Do first check on h, as array is sorted on this index
C     
        IF (IXYHKL(1,JCOUNT).LT.IHGR) THEN
          JCOUNT = JCOUNT + 1
          GOTO 150
        END IF
C     
C---- If next test true, must be a new reflection
C     
        IF (IXYHKL(1,JCOUNT).GT.IHGR) GOTO 180
C     
        IF (IXYHKL(2,JCOUNT).NE.IKGR) THEN
          JCOUNT = JCOUNT + 1
          GOTO 150
        END IF
        IF (IXYHKL(3,JCOUNT).NE.ILGR) THEN
          JCOUNT = JCOUNT + 1
          GOTO 150
        END IF
C     
C---- all indices match     
C     
C---- checks on validity of KHF
C     

C     Can no longer use IPART to determine which element this goes
C     in. Keep track of the number of parts stored already for this
C     reflection in NPARTS. Cannot simply increment the number of parts
C     either, because this will no deal with the case where an image has
C     been repeated. The pointer should be based on the image number as
C     this is the only absolute parameter. This may mean that some
C     elements are empty, as a part of a reflection may be rejected as
C     an overload or badspot or spatial overlap but NPARTS will keep
C     track of total possible number of parts.

CAL        IBIT = NPARTS(JCOUNT) + 1     
        IBIT = ID - IPARTS(2,JCOUNT,1) + 1
C
C---- Check for too many parts, if so just return
C
        IF (IBIT.GT.NGRA) RETURN
C
C---- this part of the reflection is already here. This could happen if
C     the change in missets has resulted in a change in the sequence
C     of KHF flags, but now we use IBIT (based on image number) rather
C     than IPART (based on KHF flag) as the pointer in the arrays this
C     should never happen except for a repeated image, so this should
C     now never happen (but leave the test in for now).
C     note that it cheks that the ID is not the same.
C     
        IF ((IPARTS(1,JCOUNT,IBIT) .GT. 0)
     $       .AND. (IPARTS(1,JCOUNT,1).GT.0)
     +       .AND.(IPARTS(2,JCOUNT,IBIT).NE.ID)) THEN
          IF (DEBUG(68)) THEN
            WRITE(IOUT,FMT=7250) IHGR,IKGR,ILGR,KHF,
     +           (IPARTS(1,JCOUNT,K),IPARTS(2,JCOUNT,K),K=1,10)
            IF (ONLINE) WRITE(ITOUT,FMT=7250) IHGR,IKGR,ILGR,KHF, 
     +           (IPARTS(1,JCOUNT,K),IPARTS(2,JCOUNT,K),K=1,10)
 7250       FORMAT(1X,'This part of reflection',3I4,' KHF=',I5, 
     +           '  already present',', KHF,ID..',10(I4,I4,3X))
          END IF
C     
C---- Set flag to show that this location in arrays in no longer needed.
C     
          IPARTS(1,JCOUNT,1) = -IABS(IPARTS(1,JCOUNT,1))
          RETURN       
        ENDIF
C     
C---- CHRP 13-Apr-2000 Don't add parts if the new bit isn't strictly
C     sequential in image number. This can happen if a previous part
C     was an overload, rejected as a badspot, off edge
C     of detector, or overlapped.
C     
        IF (IBIT.GT.1) THEN
          IF ((ID-IPARTS(2,JCOUNT,IBIT-1)).NE.1) THEN
            NNONSEQ = NNONSEQ + 1
            IF (DEBUG(68)) THEN
              WRITE(IOUT,FMT=7252) IHGR,IKGR,ILGR,KHF,
     +             ID,IPARTS(2,JCOUNT,IBIT-1)
              IF (ONLINE) WRITE(ITOUT,FMT=7252) IHGR,IKGR,ILGR,KHF,
     +             ID,IPARTS(2,JCOUNT,IBIT-1)
 7252         FORMAT(1X,'Non-sequential parts for reflection',
     +             3I4,' with KHF',I5,'  Current ID',I4,
     +             ' ID previous part',I4) 
            END IF
C     
C---- Set flag to show that this location in arrays in no longer needed.
C     
            IPARTS(1,JCOUNT,1) = -IABS(IPARTS(1,JCOUNT,1))
            RETURN
          ENDIF
        ENDIF
C     
C---- Check -ve SD...should never happen
C     
        IF (SIGPOST(1).LT.0) THEN
          WRITE(IOUT,FMT=7068) IHGR,IKGR,ILGR,
     +         INTPOST(1),SIGPOST(1)
          IF (ONLINE) WRITE(ITOUT,FMT=7068) IHGR,IKGR,ILGR,
     +         INTPOST(1),SIGPOST(1)
 7068     FORMAT(1X,'***** Serious error, reflection',3I5,
     +         'has negative SD. I,sd: ',2I8)
          RETURN
        END IF
        
C     
C---- JUST IN CASE A COUNTER HAS GONE AWRY
C     
        IF (IPART .GT. NGRA) THEN
          WRITE(IOUT,FMT=7060)IPART,NGRA
          IF (ONLINE) WRITE(ITOUT,FMT=7060)IPART,NGRA
 7060     FORMAT('Programmer Error! Counter I reaches ',
     $         'impossible value!',/,'I = ',I5,
     $         ' and NGRA = ',I5)
          IERRFLG = 1
          RETURN
        ENDIF
C     
C---- put it in the right location, remembering that the first free slot
C     will be for I=2. 
C
C
        IPARTS(1,JCOUNT,IBIT) = IRG(IRECG)
        IPARTS(2,JCOUNT,IBIT) = ID
        IPARTS(3,JCOUNT,IBIT) = INTPOST(1)
        IPARTS(4,JCOUNT,IBIT) = SIGPOST(1)
        FPARTS(JCOUNT,IBIT) = FRACG(IRECG)
        NPARTS(JCOUNT) = IBIT
C
C---- Need to calculate total fraction as sum of all parts here,
C     because otherwise if integration of an image is repeated
C     because of a big shift, the contribution from that image
C     will be counted twice.
C
        FRACTOT(JCOUNT) = 0.0
        DO 152 IDUM = 1,IBIT
          FRACTOT(JCOUNT) = FRACTOT(JCOUNT) + ABS(FPARTS(JCOUNT,IDUM))
 152    CONTINUE

C
C---- New test for LASTPART based on total fraction if
C     this reflection spans 8 or more images. This is needed for
C     fine sliced data where the number of parts can change due to
C     small changes in orientation.
C
CHRP 30112015 NOT SURE IF THIS IS RIGHT! WHY DID I CHANGE IT?
        IF ((IBIT.GE.8).OR.(IBIT * PHIRNG.GE.2.5*ETA)) THEN
chrp 25092015
CHRP 30112015         IF (IBIT.GE.8) THEN
          LASTPART = (LASTPART.OR.((FRACTOT(JCOUNT).GT.0.95)))
chrp 25092015
        END IF
C-----------------------------------------------------------------------
        IF ((DEBUG(68)).AND.(NDEBUG(68).GE.NDBG))THEN
          WRITE(IOUT,FMT=7070)(IXYHKL(II,JCOUNT),II=1,3),
     $         (FXYHKL(II,JCOUNT),II=3,4),FPARTS(JCOUNT,1),
     $         (IPARTS(II,JCOUNT,1),II=1,4),JCOUNT,IBIT,
     $          FRACTOT(JCOUNT),LASTPART
          IF (ONLINE)
     $       WRITE(ITOUT,FMT=7070)(IXYHKL(II,JCOUNT),II=1,3),
     $           (FXYHKL(II,JCOUNT),II=3,4),FPARTS(JCOUNT,1),
     $           (IPARTS(II,JCOUNT,1),II=1,4),JCOUNT,IBIT,
     $           FRACTOT(JCOUNT),LASTPART
          DO 160 IDUM=2,IBIT,1
            WRITE(IOUT,FMT=7072)(IXYHKL(II,JCOUNT),II=1,3),
     $           (FXYHKL(II,JCOUNT),II=3,4),FPARTS(JCOUNT,IDUM),
     $           (IPARTS(II,JCOUNT,IDUM),II=1,4),JCOUNT
            IF (ONLINE)
     $         WRITE(ITOUT,FMT=7072)(IXYHKL(II,JCOUNT),II=1,3),
     $             (FXYHKL(II,JCOUNT),II=3,4),FPARTS(JCOUNT,IDUM),
     $             (IPARTS(II,JCOUNT,IDUM),II=1,4),JCOUNT
 160      ENDDO
 7070     FORMAT(1X,'HKL',3(I4),' Phi,W ',f7.2,1x,f6.2,
     +         ' Frc',
     +         f5.2,' KHF ',I4,' Img ',I4,1X,'I,sig',
     +         I6,I5,' slot',I5,' BIT',I3,' FrcT ',F4.2,' LAST',L2)
 7072     FORMAT('    ',3(I4),'       ',f7.2,1x,f6.2,
     +         '    ',
     +         f5.2,'     ',I4,'     ',I4,4X,I8,I5,5X,I5)
        ENDIF
C-----------------------------------------------------------------------
        NDBG = NDBG + 1
        GOTO 200
C     
C---- This is a new reflection {(IXYHKL(1,JCOUNT).EQ.9999)}
C---- checks on validity of KHF; if this isn't the first or second part of a
C     partial, we return here. Allow the second part because there may have
C     been an orientation change.
C---- ** If doing a phi profile, do not return ***
C     
 180    IF (((NCOL.LE.4).AND.(IPART .GT. 1)).OR.
     +       ((NCOL.GT.4).AND.(IPART.GT.2))) THEN
          NNEWNOTFP = NNEWNOTFP + 1
          IF (DEBUG(68)) THEN
            WRITE(IOUT,FMT=7082) IHGR,IKGR,ILGR,KHF,IPART
            IF (ONLINE) WRITE(ITOUT,FMT=7082) IHGR,IKGR,ILGR,
     $           KHF,IPART
 7082       FORMAT(1X,'New reflection',
     $           3I4,' does not have first',
     +           ' or second part, KHF=',I5,'  IPART=',I3)
          END IF
          IF (.NOT.PHIPROF) RETURN
        ENDIF
C     
C---- okay, we can add it in the first free slot as this location is
C     empty
C     
        JCOUNT = NLAST + 1
        NLAST = JCOUNT
        IF(JCOUNT.GT.MGRA)THEN
          WRITE(IOUT,FMT=7220)JCOUNT - 1
          IF(ONLINE)WRITE(ITOUT,FMT=7220)JCOUNT - 1 
          NSHUTERR = 4
          CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
        ENDIF
        FXYHKL(1,JCOUNT) = XG(IRECG)
        FXYHKL(2,JCOUNT) = YG(IRECG)
        FXYHKL(3,JCOUNT) = PHIG(IRECG)
        FXYHKL(4,JCOUNT) = PHIWG(IRECG)
        IXYHKL(1,JCOUNT) = IHG(IRECG)
        IXYHKL(2,JCOUNT) = IKG(IRECG)
        IXYHKL(3,JCOUNT) = ILG(IRECG)
        IPARTS(1,JCOUNT,1) = IRG(IRECG)
        IPARTS(2,JCOUNT,1) = ID
        IPARTS(3,JCOUNT,1) = INTPOST(1)
        IPARTS(4,JCOUNT,1) = SIGPOST(1)
        FPARTS(JCOUNT,1) = FRACG(IRECG)
        FRACTOT(JCOUNT) = ABS(FRACG(IRECG))
        NPARTS(JCOUNT) = 1
C     
C---- 08062000
C---- now make sure all the other parts of this reflection location
C     are zeroed.
C     
        DO 190 I=2,NGRA
          IPARTS(1,JCOUNT,I) = 0
          IPARTS(2,JCOUNT,I) = 0
          IPARTS(3,JCOUNT,I) = 0
          IPARTS(4,JCOUNT,I) = 0
          FPARTS(JCOUNT,I) = 0.0
 190    ENDDO
        IF ((DEBUG(68)).AND.(NDEBUG(68).GE.NDBG))THEN
          WRITE(IOUT,FMT=7080)(IXYHKL(II,JCOUNT),II=1,3),
     $         (FXYHKL(II,JCOUNT),II=3,4),FPARTS(JCOUNT,1),
     $         (IPARTS(II,JCOUNT,1),II=1,4),JCOUNT
          IF (ONLINE)
     $       WRITE(ITOUT,FMT=7080)(IXYHKL(II,JCOUNT),II=1,3),
     $           (FXYHKL(II,JCOUNT),II=3,4),FPARTS(JCOUNT,1),
     $           (IPARTS(II,JCOUNT,1),II=1,4),JCOUNT
 7080     FORMAT(1X,'New',3(I4),' Phi,W ',f7.2,1x,f6.2,
     +         ' Frc',
     +         f5.2,' KHF ',I4,' Img ',I4,1X,'I,sig',
     +         I6,I5,' slot',I5)
        ENDIF
        JMAX = JCOUNT
        RETURN
chrp10102002      ENDIF                     
C     
C---- Check to see if this reflection should be passed to post
C     -refinement
C     
 200    IF (LASTPART) THEN
C     
C---- Set flag to show that this location in arrays is no longer needed.
C     
          IPARTS(1,JCOUNT,1) = -IABS(IPARTS(1,JCOUNT,1))
          IREASON = 0
C     
C     Check that all parts of the reflection are present if it spans
C     4 or fewer images.
C
          IF (NCOL.LE.4) THEN
            IF (IBIT.LT.NCOL) THEN
C
C---- Do not have all the parts, do we have an (almost) complete
C     reflection ?
C
              IF (FRACTOT(JCOUNT).LT.0.98) THEN
                IREASON = IREASON + 2
              END IF
            END IF
          END IF
C
          SUMINT = 0
          DO 204 IDUM = 1,IBIT
            SUMINT = SUMINT + FPARTS(JCOUNT,IDUM)
 204      ENDDO

CAL          KTEMP = ID
CAL          IREASON = 0
CAL          DO 204 IDUM = IBIT-1,1,-1
CAL            KTEMP = KTEMP - 1
CAL            SUMINT = SUMINT + FPARTS(JCOUNT,IDUM)
CAL            IF (KTEMP .NE. IPARTS(2,JCOUNT,IDUM))
CAL     +           IREASON = IREASON + 2
CAL 204      ENDDO
C     
C     
C     
C---- Reflection is spread over > 2 images, so have to check that the
C     intensity
C     for each part and for the total is not zero, to prevent a DBZ
C     later...
C     
C---- CHKPOST1 is summed I for first NCOL/PARTITION parts divided by total I
C---- CHKPOST2 is summed I for first (NCOL/(PARTITION+1)) parts divided by total
C     I
C---- CHKPOST3 is summed intensity for all parts

          CHKPOST1 = 0.0
          CHKPOST2 = 0.0
          CHKPOST3 = 0.0
C
C---- change NCOL to IBIT below in case
C     this reflection is selected on FRACTIONCALC and may not have all
C     NCOL parts actually present.
C     
C
C---- make sure ICHK is at least 1.
C
CAL          ICHK = MAX(1,INT(NCOL * PARTITION))
          ICHK = MAX(1,INT(IBIT * PARTITION))
          IF(IDIR.EQ.0)THEN
            IDIR = -1
          ELSE
            IDIR = 0
          ENDIF
          ICHK = MAX(1,ICHK)
          DO 210 JDUM=1,ICHK
            CHKPOST1 = CHKPOST1 + IPARTS(3,JCOUNT,JDUM)
 210      ENDDO
          CHKPOST3 = CHKPOST1
          DO 215 JDUM=ICHK+1,IBIT
            CHKPOST3 = CHKPOST3 + IPARTS(3,JCOUNT,JDUM)
 215      ENDDO
C     
          IF(CHKPOST3.GT.0.0)THEN
            CHKPOST1 = CHKPOST1/CHKPOST3
            CHKPOST2 = CHKPOST1 
     $           + FLOAT(IPARTS(3,JCOUNT,ICHK+1))/CHKPOST3
          ELSE
            IREASON = IREASON + 1
          ENDIF
C
C---- Test resolution if ice rings to be excluded
C        
          IF (PREFEXICE) THEN
C
C---- Calculate resolution
C
            XC = FXYHKL(1,JCOUNT)
            YC = FXYHKL(2,JCOUNT)
            CALL MMTOPX(XCAL,YCAL,XC,YC)
            IXPIX = NINT(XCAL*FACT)
            IYPIX = NINT(YCAL*FACT)
            CALL CRESOL(IXPIX,IYPIX,0.01*XTOFD,TWOTHETA,WAVE,RESOL)
            DO 216 K = 1,NEXCL2
              IF ((RESOL.LE.RES3EXL(K)).AND.(RESOL.GE.RES3EXH(K))) THEN
                IF (DEBUG(68).AND.(NDEBUG(68).GE.NDBG)) THEN
                  WRITE(IOUT,FMT=6033) RESOL
                  IF (ONLINE) WRITE(ITOUT,FMT=6033) RESOL
 6033           FORMAT(1X,'Reflection excluded at resolution',F5.2)
                END IF
                NPREFEXCL = NPREFEXCL + 1 
                IREASON = 1000
              END IF
 216       CONTINUE
          END IF
C     
C---- Set flag for bad reflection and write out warning messages if 
C     IREASON .NE. 0
C     
          IF (IREASON.GT.0)THEN
            NREJECT = NREJECT + 1
            IF ((IREASON.EQ.1000).AND.
     +        ((DEBUG(68)).AND.(NDEBUG(68).GE.NDBG))) THEN
              WRITE(IOUT,7090)(IXYHKL(IDUM,JCOUNT),
     $             IDUM=1,3)
              IF (ONLINE) WRITE(ITOUT,7090)(IXYHKL(IDUM,JCOUNT),
     $             IDUM=1,3)
 7090         FORMAT(1X,'Reflection ',3i4,' has been rejected because',
     $           ' it is within an ice ring')

            ELSE IF ((DEBUG(68)).AND.(NDEBUG(68).GE.NDBG)) THEN
              WRITE(IOUT,7092)(IXYHKL(IDUM,JCOUNT),
     $             IDUM=1,3),IREASON
              IF (ONLINE) WRITE(ITOUT,7092)(IXYHKL(IDUM,JCOUNT),
     $             IDUM=1,3),IREASON
            ENDIF
 7092       FORMAT(1X,'Reflection ',3i4,' has been rejected because',
     $           ' IREASON is ',I4)
C
            IF (IREASON.NE.1000) THEN     
              IF (IREASON.GE.2) THEN
                IF ((DEBUG(68)).AND.(NDEBUG(68).GE.NDBG)) THEN
                  WRITE(IOUT,7110)(IPARTS(2,JCOUNT,IDUM),IDUM=1,10)
                  IF (ONLINE) WRITE(ITOUT,7110)(IPARTS(2,JCOUNT,IDUM),
     $               IDUM=1,10)
                ENDIF
 7110           FORMAT(10X,'The images are not strictly sequential: ',
     $             10I4)
              ENDIF
C     
              IF (MOD(IREASON,2).NE.0) THEN
                IF ((DEBUG(68)).AND.(NDEBUG(68).GE.NDBG)) THEN
                WRITE(IOUT,7120)CHKPOST1,CHKPOST2,CHKPOST3
                IF (ONLINE) WRITE(ITOUT,7120)CHKPOST1,CHKPOST2,CHKPOST3
                ENDIF
 7120           FORMAT(1X,'The total intensity is Zero or Negative.',
     $             ' First and second halves and total intensity are:',
     +              3F12.2,/)
              ENDIF
            ENDIF
            
          ELSE
C     
            IF(IXYHKL(1,JCOUNT).EQ.9999) THEN
              WRITE(IOUT,FMT=7270)
              IF (ONLINE) WRITE(ITOUT,FMT=7270)
 7270         FORMAT(1X,'***** Serious programming error, have got',
     +             ' a stored reflection with h=9999')
            END IF
            NROCKING(IBIT) = NROCKING(IBIT) + 1
            DO 218 IDUM=1,IBIT
              ROCKING(IBIT,IDUM) = ROCKING(IBIT,IDUM) + 
     $             IPARTS(3,JCOUNT,IDUM)
              SDROCKING(IBIT,IDUM) = SDROCKING(IBIT,IDUM) + 
     $             (IPARTS(4,JCOUNT,IDUM)**2)
 218        ENDDO
            DO 2180 IDUM=1,IBIT
              SDROCKING(IBIT,IDUM) = SQRT(SDROCKING(IBIT,IDUM))
 2180       ENDDO
C     
C---- Now test to see which parts go into which half of the reflection
C     for passing to POSTREFL 
C     
            IF (KHF.EQ.202) THEN
C     
C---- Reflection is spread over two images only; this is the trivial
C     case
C     
              INTPOST(1) = IPARTS(3,JCOUNT,1)
              SIGPOST(1) = IPARTS(4,JCOUNT,1)
              FRCCALC(1) = FPARTS(JCOUNT,1)
              INTPOST(2) = IPARTS(3,JCOUNT,2)
              SIGPOST(2) = IPARTS(4,JCOUNT,2)
              FRCCALC(2) = FPARTS(JCOUNT,2)
              PHIPOST    = PHIBEG
              IF (INTPOST(1)+INTPOST(2).NE.0) THEN
                FRCOBS(1) = FLOAT(INTPOST(1))/
     $               FLOAT(INTPOST(1)+INTPOST(2))
                FRCOBS(2) = 1.0 - FRCOBS(1)
              END IF
              split(1,2) = split(1,2) + frcobs(1)
              split(2,2) = split(2,2) + frccalc(1)
            ELSE               
C     
C---- Reflection is spread over > 2 images (vide supra for checks)
C     Need to change NCOL here to IBIT AGWL 21/6/11
C     
              IF (ABS(CHKPOST1-PARTITION) .GT. 
     $             ABS(CHKPOST2-(1-PARTITION)))
     $             ICHK=ICHK+1
CAL              PHIPOST = PHIBEG -(NCOL - ICHK -1)*(PHIEND-PHIBEG)
              PHIPOST = PHIBEG -(IBIT - ICHK -1)*(PHIEND-PHIBEG)
C     
C---- Now loop round adding up the parts of the reflections into two
C     components - need to have FSIGPOST (REAL) here since some newer
C     detectors can have much bigger sigmas (HRP 08.09.06).
C     
              INTPOST(1) = 0
              FSIGPOST(1) = 0.0
              FRCOBS(1) = 0.0
              FRCCALC(1) = 0.0
              INTPOST(2) = 0
              FSIGPOST(2) = 0.0
              FRCOBS(2) = 0.0

              DO 220 IDUM=1,ICHK
                INTPOST(1) = INTPOST(1) + IPARTS(3,JCOUNT,IDUM)
                FSIGPOST(1) = FSIGPOST(1) + 
     $               FLOAT(IPARTS(4,JCOUNT,IDUM))**2
                FRCCALC(1) = FRCCALC(1) + FPARTS(JCOUNT,IDUM)
 220          ENDDO
              FRCCALC(2) = 1.0-FRCCALC(1)
              SIGPOST(1) = NINT(SQRT(FSIGPOST(1)))
              DO 230 IDUM = ICHK+1,IBIT
                INTPOST(2) = INTPOST(2) + IPARTS(3,JCOUNT,IDUM)
                FSIGPOST(2) = FSIGPOST(2) + 
     $               FLOAT(IPARTS(4,JCOUNT,IDUM))**2
 230          ENDDO
              SIGPOST(2) = NINT(SQRT(FSIGPOST(2)))
chrp 01.15.2014:           chkpost3 !=    INTPOST(1)+INTPOST(2)
chrp 01.15.2014:           IF (CHKPOST3.NE.0) FRCOBS(1) = INTPOST(1)/CHKPOST3
              IF (INTPOST(1)+INTPOST(2).NE.0) THEN
                FRCOBS(1) = FLOAT(INTPOST(1))/
     $               FLOAT(INTPOST(1)+INTPOST(2))
                FRCOBS(2) = 1.0 - FRCOBS(1)
              ENDIF
              split(1,ibit) = split(1,ibit) + frcobs(1)
              split(2,ibit) = split(2,ibit) + frccalc(1)
            ENDIF
            IF ((DEBUG(68)).AND.(NDEBUG(68).GE.NDBG))THEN
              WRITE(IOUT,FMT=7150)
     $             IBIT,ICHK,PARTITION,PHIPOST,(INTPOST(II),
     $             SIGPOST(II),FRCCALC(II),FRCOBS(II),II=1,2)
              IF(ONLINE)WRITE(ITOUT,FMT=7150)
     $             IBIT,ICHK,PARTITION,PHIPOST,(INTPOST(II),
     $             SIGPOST(II),FRCCALC(II),FRCOBS(II),II=1,2)
            ENDIF
 7150       FORMAT(1X,'Reflection is spread over ',I2,
     $           ' images, partition chosen at image',I3,
     $           ' for partition ',F4.2,/,1X,
     $           'Phipost = ',F8.4,' I,sig(I),',2I6,
     $           ' FracCalc, Obs: ',2F7.3,1X,' I,sig(I),',2I6,
     $           ' FracCalc, Obs: ',2F7.3)
C
C---- Test for fraction between 0 and 1, as very weak reflections can 
C     give rise to values outside this range.
C
CAL            IF ((FRCPOST(1).GE.0.0).AND.(FRCPOST(1).LE.1.0)) THEN           
C     
C---- FLAG the reflection as ready for postrefinement for SPROCESS....
C     
              LASTREC = IRECG
              IF ((DEBUG(68)).AND.(NDEBUG(68).GE.NDBG))THEN
                WRITE(IOUT,7130)(IXYHKL(IDUM,JCOUNT),
     $             IDUM=1,3),FXYHKL(1,JCOUNT)*0.01,
     $               FXYHKL(2,JCOUNT)*0.01
                IF(ONLINE)WRITE(ITOUT,7130)(IXYHKL(IDUM,JCOUNT),
     $             IDUM=1,3),FXYHKL(1,JCOUNT)*0.01,
     $               FXYHKL(2,JCOUNT)*0.01
              ENDIF
 7130       FORMAT(1X,'Reflection ',3I4,' with virtual detector ',
     $             'coordinates ',F6.1,1X,F6.1,' (mm) has been passed',
     $           ' as OKAY for post-refinement',/)
              NCOMPLETE = NCOMPLETE + 1
CAL            ELSE
CAL              IF ((DEBUG(68)).AND.(NDEBUG(68).GE.NDBG))THEN
CAL                WRITE(IOUT,7131) FRCPOST(1)
CAL                IF (ONLINE) WRITE(ITOUT,7131) FRCPOST(1)
CAL              ENDIF
 7131         FORMAT(1X,'Reflection rejected fraction of',
     +                  ' total intensity in first half is',F6.2)
CAL            ENDIF
          ENDIF
          NDBG = NDBG + 1
          PARTITION = 1.0 - PARTITION
          RETURN
        ENDIF
C     
C---- end of IMODE = 2
C     
      ENDIF
C
C---- IMODE = 3, used to sort the list of reflections, then remove
C     duplicate entries; this is only needed when we have a repeat refinement
C     ** Query ** Is this ever needed. I cannot find a case where a 
C                 reflection does get duplicated even after repeats induced
C                 by using the ERROR keyword. However, leave for now. 
C                 AGWL 19/3/12
C
      IF (IMODE.EQ.3) THEN
        IF (DEBUG(68))THEN
          WRITE(IOUT,FMT=8020) CURRENT_ID
          IF (ONLINE) WRITE(ITOUT,FMT=8020) CURRENT_ID
 8020     FORMAT('MODARRAY sorting list and removing duplicates ',
     $         'due to BIGSHIFT',/,1X,'Current ID',I5)
        ENDIF
C
C---- count total number of reflections stored
C
        NHKL = 1
        DO WHILE (IXYHKL(1,NHKL) .NE. 9999)
          NHKL = NHKL + 1
        ENDDO
        NHKL = NHKL - 1
        IF (DEBUG(68)) THEN
          WRITE(IOUT,FMT=8240) NHKL,JMAX
          IF (ONLINE) WRITE(ITOUT,FMT=8240) NHKL,JMAX
 8240     FORMAT(1X,'Sorting',I5,' reflections on h,k,l in MODE=3, ',
     $         'current JMAX value is ',I5)
        ENDIF
C
        CALL SORTPART(NHKL,FXYHKL,IXYHKL,FPARTS,IPARTS,NPARTS,FRACTOT)
C

        IF (DEBUG(68)) THEN
          WRITE(IOUT,FMT=7300) ((IXYHKL(I,J),I=1,3),FRACTOT(J),
     +        NPARTS(J),(IPARTS(1,J,L),IPARTS(2,J,L),L=1,9),J=1,NHKL)
          IF (ONLINE) WRITE(ITOUT,FMT=7300) ((IXYHKL(I,J),I=1,3),
     +         FRACTOT(J),NPARTS(J),
     +          (IPARTS(1,J,L),IPARTS(2,J,L),L=1,9),J=1,NHKL)
 7300     FORMAT(1X,'Before removing duplicates',/,
     +             (1X,3I4,F5.2,I3,3X,9(I5,I4,2X)))
        END IF
C
C---- now go through the list to remove duplicate entries caused by
C     repeat refinements. Leave the last copy in as this will have the
C     newest information.
C
        ICOUNT = 0
        DO 1752 JCOUNT = 1,NHKL
          ICOUNT = ICOUNT + 1
          IF(ICOUNT.LE.NHKL)THEN
c
c----do h,k,l match?
c
            DO 1753 WHILE ((IXYHKL(1,ICOUNT).EQ.IXYHKL(1,JCOUNT))
     $           .AND.(IXYHKL(2,ICOUNT).EQ.IXYHKL(2,JCOUNT)).AND.
     $           (IXYHKL(3,ICOUNT).EQ.IXYHKL(3,JCOUNT)))
              ICHECK = .TRUE.
              ICOUNT = ICOUNT + 1
 1753       ENDDO
            IF(ICHECK)ICOUNT = ICOUNT - 1
C
C---- these indices are the same, shuffle up the JCOUNT'th reflection
C
            IXYHKL(1,JCOUNT) = IXYHKL(1,ICOUNT)
            IXYHKL(2,JCOUNT) = IXYHKL(2,ICOUNT)
            IXYHKL(3,JCOUNT) = IXYHKL(3,ICOUNT)
            FXYHKL(1,JCOUNT) = FXYHKL(1,ICOUNT)
            FXYHKL(2,JCOUNT) = FXYHKL(2,ICOUNT)
            FXYHKL(3,JCOUNT) = FXYHKL(3,ICOUNT)
            FXYHKL(4,JCOUNT) = FXYHKL(4,ICOUNT)
            DO 1754 NCOUNT=1,NGRA-1
              IPARTS(1,JCOUNT,NCOUNT) = IPARTS(1,ICOUNT,NCOUNT)
              IPARTS(2,JCOUNT,NCOUNT) = IPARTS(2,ICOUNT,NCOUNT)
              IPARTS(3,JCOUNT,NCOUNT) = IPARTS(3,ICOUNT,NCOUNT)
              IPARTS(4,JCOUNT,NCOUNT) = IPARTS(4,ICOUNT,NCOUNT)
              FPARTS(JCOUNT,NCOUNT) = FPARTS(ICOUNT,NCOUNT)
 1754       ENDDO
          ELSE
C
C---- zero these last elements
C
            IXYHKL(1,JCOUNT) = 9999
            DO 1755  J=1,NGRA
              IF(IPARTS(1,JCOUNT,J).NE.0)THEN
                IPARTS(1,JCOUNT,J) = 0
              ENDIF
 1755       ENDDO
          ENDIF
 1752   ENDDO

        IF (DEBUG(68)) THEN
          WRITE(IOUT,FMT=7310) ICOUNT-JCOUNT+1,
     +        ((IXYHKL(I,J),I=1,3),FRACTOT(J),
     +        NPARTS(J),(IPARTS(1,J,L),IPARTS(2,J,L),L=1,9),J=1,NHKL)
          IF (ONLINE) WRITE(ITOUT,FMT=7310)  ICOUNT-JCOUNT+1,
     +         ((IXYHKL(I,J),I=1,3),FRACTOT(J),NPARTS(J),
     +          (IPARTS(1,J,L),IPARTS(2,J,L),L=1,9),J=1,NHKL)
 7310     FORMAT(1X,'After removing',I5,'  duplicates',/,
     +             (1X,3I4,F5.2,I3,3X,9(I5,I4,2X)))
        END IF
c
c---- next bit dumps the big array which might be sorted at the moment
c
      if(debug(68))then
        write(iout,*)'BIG DUMP OF REFLECTIONS STORED'
        if(online)write(itout,*)'BIG DUMP OF REFLECTIONS STORED'
        do 1667 i=1,nhkl
          if (i.gt.ndebug(68)) goto 1667
          if((istored(1).eq.ixyhkl(1,i)).and.
     $         (istored(2).eq.ixyhkl(2,i)).and.
     $         (istored(3).eq.ixyhkl(3,i)))then
            write(iout,*)'DUPLICATE ENTRY!'
            if(online)write(itout,*)'DUPLICATE ENTRY!'
          endif
          WRITE(IOUT,FMT=7070)(IXYHKL(II,I),II=1,3),
     $         (FXYHKL(II,I),II=3,4),FPARTS(I,1),
     $         (IPARTS(II,I,1),II=1,4),I
          IF (ONLINE) THEN
            WRITE(ITOUT,FMT=7070)(IXYHKL(II,I),II=1,3),
     $           (FXYHKL(II,I),II=3,4),FPARTS(I,1),
     $           (IPARTS(II,I,1),II=1,4),I
          ENDIF
          istored(1) = ixyhkl(1,i)
          istored(2) = ixyhkl(2,i)
          istored(3) = ixyhkl(3,i)
          DO 1666 IDUM=2,IPART
            WRITE(IOUT,FMT=7080)(IXYHKL(II,I),II=1,3),
     $           (FXYHKL(II,I),II=3,4),FPARTS(I,IDUM),
     $           (IPARTS(II,I,IDUM),II=1,4),I
            IF (ONLINE) THEN
              WRITE(ITOUT,FMT=7080)(IXYHKL(II,I),II=1,3),
     $             (FXYHKL(II,I),II=3,4),FPARTS(I,IDUM),
     $             (IPARTS(II,I,IDUM),II=1,4),I
            ENDIF
 1666     ENDDO
 1667   enddo
      endif
        RETURN
      ENDIF
      IF (IMODE.EQ.4) THEN
        ICOUNT = 1
        DO 320 WHILE ((IXYHKL(1,ICOUNT) .NE. 9999).AND.(ICOUNT.LE.MGRA))
          IF (IXYHKL(1,ICOUNT).LT.IHPROF) GOTO 310
          IF (IXYHKL(2,ICOUNT).NE.IKPROF) GOTO 310
          IF (IXYHKL(3,ICOUNT).NE.ILPROF) GOTO 310
C
C---- All indices match
C
          GOTO 330    
 310    ICOUNT = ICOUNT + 1
 320  CONTINUE
C
C---- Reflection not found
C
        IERRFLG = 1
        RETURN
C
 330    NBITPROF = NPARTS(ICOUNT)
        DO 340 I = 1,NBITPROF
          IDPROFILE(I) = IPARTS(2,ICOUNT,I)
          INTPROFILE(I) = IPARTS(3,ICOUNT,I)
          FRACPROFILE(I) = FPARTS(ICOUNT,I)
 340    CONTINUE

      END IF
      RETURN
      END                       
C $Id: mosdata.f,v 1.93 2021/08/19 10:54:21 andrew Exp $
C== MOSDATA ==                           
C
      BLOCK DATA MOSDATA
C     ==================
      IMPLICIT NONE
C
C---- Errors this contains type conversions in data statements
C     Real to Integer (eg CUTOFF)  made integer
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
