chrp 21.07.2005      DATA CUTPIXMIN/0.5/,CUTPIXMAX/6.0/,CUTWXMIN/0.2/,CUTWXMAX/5.0/
chrp 21.07.2005      DATA CUTWYMIN/0.2/,CUTWYMAX/5.0/,XOFFSET/0.0/,YOFFSET/0.0/
