      LOGICAL RDSTRIP
      INTEGER*2 BOXOD,IMAGE,IMAGE2
C     ..
C     .. Common Blocks /PEL/ and /PELC/ ..
      COMMON /PEL/IBA,IPOINT,INCORE,RDSTRIP(IXWDTH),BOXOD(MAXBOX),
     +            ISTART
      COMMON /PELC/ IMAGE(IYLENGTH*IXWDTH),IMAGE2(4400*4400)
C     ..
C
C
C---- END of include file pel.h
C
C&&*&& end_include  ../inc/pel.f
C&&*&& include  ../inc/postchk.f
C
C $Id: postchk.f,v 1.5 2015/05/11 14:19:27 andrew Exp $
C
C--- awk generated include file  postchk.h
C---- START of include file postchk.h
C
C     DELPHIV   stores the missets for the first NADD images only,
C               so that once NADD images have been processed their
C               refined missets can be saved for writing to the
C               summary file.
C
C     NREFMOS   Minimum number of reflections for mosaicity refinement
C               to be carrid out (default 100)
C
C     .. Arrays in Common /POSTCHK/
      REAL SDBEAM,SDCELL,SDDELPHI,DELPHIV,SHIFT
      LOGICAL FCELL,VALSET
C
C     .. Scalars in Common /POSTCHK/ ..
C     ..
      REAL PRRES1,PRRES2,RESIDMAX,SDFAC,SHIFTMAX,SHIFTFAC,
     +     ANGWIDTH,CELLSHIFT,FRACMIN,FRACMAX,FRCSHIFT
      INTEGER PRNS,NREFPR,NADD,NRPT,IPRINTP,NPRMIN,NREFMOS
      LOGICAL USEBEAM,REFCELL,RESCALE,SMOOTHPHI
C     ..
C     .. Common block /POSTCHK/  ..
      COMMON /POSTCHK/ SDBEAM(6),SDCELL(6),SDDELPHI(2*NIMAX),
     +             DELPHIV(3*NIMAX),SHIFT(3),PRRES1,PRRES2,RESIDMAX,
     +             SDFAC,SHIFTMAX,SHIFTFAC,ANGWIDTH,CELLSHIFT, 
     $             FRACMIN,FRACMAX,FRCSHIFT,
     +             PRNS,NREFPR,NADD,NRPT,IPRINTP,
     +             NPRMIN,FCELL(6),USEBEAM,REFCELL,RESCALE,
     +             VALSET(MAXPAX),NREFMOS,SMOOTHPHI
C     ..
C
C
C&&*&& end_include  ../inc/postchk.f
C&&*&& include  ../inc/praccum.f
C
C $Id: praccum.f,v 1.1 2002/05/02 10:47:08 harry Exp $
C
C--- awk generated include file  praccum.h
C---- START of include file praccum.h
C
C
C     ..
C     .. Arrays in common block /PRACCUM/ ..
      REAL PRDATA
C
C     .. Scalars in common block /PRACCUM/ ..
      LOGICAL ACCUMULATE,FIRSTPASS,SECONDPASS,THIRDPASS,FIRSTFILM,
     +        NOTREAD
C     ..
C     .. Common Block /PRACCUM/ ..
      COMMON /PRACCUM/PRDATA(4,50),ACCUMULATE,FIRSTPASS,SECONDPASS,
     +       THIRDPASS,FIRSTFILM,NOTREAD
C     ..
C
C
C&&*&& end_include  ../inc/praccum.f
C
C     ..
C     .. Scalar Arguments ..
      INTEGER ISEG
      LOGICAL RPTFIRST,GENOPEN,COORDOPN
C
C     ..
C     .. Array Arguments ..
      REAL PRFSUM(25,MAXPAX)
      INTEGER PRFSUMI(MAXPAX)
C     ..
C     .. Local Scalars ..

      INTEGER MTZPRT,ITOG,IPAUSE,IERR,I,J,INDENT
      CHARACTER LINE*80,VALUESTR*80,LONGLINE*1024,THIS*30,CALLED*30,
     +          COMMENT*100
C     ..
C     .. Local Arrays ..
C     ..
C     .. External Functions ..
      INTEGER LENSTR
      EXTERNAL LENSTR
C     .. External Subroutines ..
      EXTERNAL LWCLOS,QCLOSE,MXDCIO,MXDPVL
C     ..
C     .. Intrinsic Functions ..
C     ..
C     .. Common blocks ..
C     ..
C     .. Equivalences ..
      SAVE
C     ..
C     .. Data ..
C     ..
C
C
C---- Reset all parameters, so a new run can start
C
      THIS = 'MRESET'
      INDENT = 2
      TOSPT = 0
      NSPOT = 0
      ISTART = 0
      NSERTOT = 0
      NSEG = 0
      ISEG = 0
      NPACK = 0
      NPACKS = 0
      ISTARTP = 1
      RPTFIRST = .FALSE.
      NTLINE = NSAVELINE
C
C---- reset all warnings
C
      DO 20 I = 1,100
        WARN(I) = .FALSE.
        DO 10 J = 1,MAXIWARN
          IWARN(J,I) = 0
          IF (J.GT.20) GOTO 10
          XWARN(J,I) = 0.0
 10     CONTINUE
 20   CONTINUE
C
      DO 30 I = 1,6
        SDCELL(I) = 0.0
 30   CONTINUE
C
      DO 42 I = 1,MAXPAX
        PRFSUMI(I) = 0
        DO 40 J = 1,25
          PRFSUM(J,I) = 0.0
 40     CONTINUE
        DO 41 J = 1,3
          RMISSETS(I,J) = 0.0
          IF (J.EQ.3) GOTO 41
          SDMISSETS(I,J) = 0.0
 41     CONTINUE
 42   CONTINUE
C
C---- Added to deal with aborts at integration step from new gui
C
      SECONDPASS = .FALSE.
      THIRDPASS = .FALSE.
      PROCES = .FALSE.
      IF (SOCKLO) THEN
C
C---- End cell refinement or integration task
C
        WRITE(LONGLINE,FMT=6000)
 6000   FORMAT('<?xml version="1.0"?>',
     +  '<!DOCTYPE processing_task_end>',
     +  '<processing_task_end><status><code>ok</code>',
     +  '</status></processing_task_end>')
C
C---- Print for program flow
C

        CALLED = 'WRITE_SOCKET_LENGTH'
        COMMENT = 'Send processing_task_end XML'
        IF (DEBUG(99)) 
     +           CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(LONGLINE),LONGLINE) 
      END IF

      IF (MTZOPEN) THEN
C
C---- Suppress output from MTZ closure, as this causes a divide by zero
C     if there are no reflections in the file. This will be fixed in CCP4 6.0
C
        MTZPRT = 0
C                 *********************
C
C---- Print for program flow
C

        CALLED = 'LWCLOS'
        COMMENT = 'close MTZ file'
        IF (DEBUG(99)) 
     +           CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        CALL LWCLOS(MTZOUT,MTZPRT)
        IF(LBEST.AND.BESTOPEN)THEN
C
C---- Print for program flow
C

        CALLED = 'CLOSE'
        COMMENT = 'to close BEST file'
        IF (DEBUG(99)) 
     +           CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CLOSE(BESTHKL)
          BESTOPEN = .FALSE.
        ENDIF
C                 *********************
        MINBATCH = -999
        MTZOPEN = .FALSE.
      END IF
      IF(.NOT.MULTISEG)THEN
        IF(NUSPOT)THEN
          IF (INMOOPEN) THEN
C
C---- Print for program flow
C

            CALLED = 'QCLOSE'
            COMMENT = 'to close SPOTOD (inmo) file'
            IF (DEBUG(99)) 
     +           CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
            CALL QCLOSE(INMO)
            INMOOPEN = .FALSE.
          END IF
        ELSE
C
C---- Print for program flow
C

          CALLED = ''
          COMMENT = 'Close SPOTOD (inmo) file'
          IF (DEBUG(99)) 
     +           CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CLOSE (UNIT=INMO)
        ENDIF
      ENDIF
      MULTISEG = .FALSE.
      IF (GENOPEN) THEN
C
C---- Print for program flow
C

        CALLED = 'QCLOSE'
        COMMENT = 'to close generate file'
        IF (DEBUG(99)) 
     +           CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        CALL QCLOSE(IUNIT)
        GENOPEN = .FALSE.
      END IF
      IF (COORDOPN) THEN
C
C---- Print for program flow
C

        CALLED = ''
        COMMENT = 'Close COORDS (icoord) file'
        IF (DEBUG(99)) 
     +           CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        CLOSE(ICOORD)
        COORDOPN = .FALSE.
      END IF
      IF (DISPMENU) THEN
        ADDPART = .FALSE.
        SUMPART = .FALSE.
        POWDER = .TRUE.
        NBLOCK = 10
C
C---- Turn off Timeout mode if set
C
        IF(WINOPEN)THEN
          IF (LPAUSE) THEN
            LPAUSE = .FALSE.
            LINE = 'Timeout mode'
            VALUESTR = ' '
            ITOG = 2
            IPAUSE = 48
            CALL MXDPVL(IVHPAR, .TRUE., ITOG,LINE,IPAUSE,VALUESTR,IERR)
          END IF
C
C---- If third display window open, close it
C
          IF (DISP_IO3) CALL MXDCIO(21,0,0,0,0)
        END IF
      END IF
      END

      subroutine gettransform(theta, invert)

      implicit none
      integer theta, invert

C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
