C
C     .. Scalars in common /FIDC/ ..
C
      CHARACTER SPOTFILEORIGIN*2,SPOTFILEAXISORDER*2,SWINGAXIS*2
      COMMON /FIDC/ SPOTFILEORIGIN,SPOTFILEAXISORDER,SWINGAXIS
C&&*&& end_include  ../inc/fid.f

      write(*, *) 'gettransform rolling:'
      write(*, *) 'cosom0 = ', cosom0, 'sinom0 = ', sinom0
      write(*, *) 'omegaf = ', omegaf

      if(invertx) then
         invert = 1
      else
         invert = 0
      end if
      if(cosom0 .eq. 1) then
         theta = 0
      else if(cosom0 .eq. -1) then
         theta = 180
      else
         if(sinom0 .eq. 1) then
            theta = 270
         else
            theta = 90
         end if
      end if

      end
