C== MSYSABS ==
C $Id: msysabs.f,v 1.3 2006/08/29 14:58:29 harry Exp $
C
C
      SUBROUTINE MSYSABS(H,ABSNT)
      IMPLICIT NONE
C     ==========================
C
C
C
C
C
C     .. Scalar Arguments ..
      LOGICAL ABSNT
C     ..
C     .. Array Arguments ..
      INTEGER H(3)
C     ..
C     .. Local Scalars ..
      INTEGER I,J
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC MOD
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/sys.f
C
C $Id: sys.f,v 1.1 2002/05/02 10:47:21 harry Exp $
C
C--- awk generated include file  sys.h
C---- START of include file sys.h
C
C
C     .. Scalars in Common Block /SYS/ ..
      INTEGER ISYS
C     ..
C     .. Arrays in Common Block /SYS/  ..
      INTEGER KSYS
C     ..
C     ..  Common Block /SYS/ ..
      COMMON /SYS/ISYS,KSYS(3)
C     ..
C
C
C&&*&& end_include  ../inc/sys.f
      SAVE
C     ..
C
C
      IF (ISYS.EQ.4) THEN
C
C---- Face centred lattice
C
        ABSNT = .TRUE.
C
C
        DO 10 I = 1,2
          IF (MOD(H(I)+H(I+1),2).NE.0) RETURN
   10   CONTINUE
C
C
        ABSNT = .FALSE.
      ELSE
C
C---- This version for A,B,C,R,I & F lattice absences
C
        ABSNT = .FALSE.
        J = 0
C
C
        DO 20 I = 1,3
          J = H(I)*KSYS(I) + J
   20   CONTINUE
C
C
        IF (MOD(J,ISYS).NE.0) ABSNT = .TRUE.
      END IF
C
C
      END
