c     cir_symb   symbol for centre
      INTEGER CIR_IVEC, CIR_COLR, CIR_IOVL, CIR_SYMB
      PARAMETER (CIR_IVEC=3, CIR_COLR=6, CIR_IOVL=2, CIR_SYMB=4)

C
C---- Residual vectors
C     IRV_VEC Vector set number
C     IRV_COL Colour  (1 red, 2 yellow, 3 green)
C     IRV_OVL Overlay number
      INTEGER IRV_VEC, IRV_COL, IRV_OVL
      PARAMETER (IRV_VEC=4, IRV_COL=1, IRV_OVL=2)
c  Measure
c
c     mes_colr    colour for measure crosses
      INTEGER MES_COLR
      PARAMETER (MES_COLR=1)

c   Vertical Crosses
c     cross_iovl    overlay number for circles
c     cross_symb   symbol for centre
      INTEGER CROSS_IOVL, CROSS_SYMB
      PARAMETER (CROSS_IOVL=2, CROSS_SYMB=3)
c  Boxes
c     box_iovl    overlay number for boxes
c     box_symb   symbol for centre
      INTEGER BOX_IOVL, BOX_SYMB, BOX_VEC
      PARAMETER (BOX_VEC=2,BOX_IOVL=2, BOX_SYMB=13)
c  Circles
c     CIRC_iovl    overlay number for circles
c     CIRC_symb   symbol for centre
      INTEGER CIRC_IOVL, CIRC_VEC
      PARAMETER (CIRC_VEC=5,CIRC_IOVL=2)
c   Crosses
c     cross_iovl    overlay number for circles
c     cross_symb   symbol for centre
      INTEGER XCROSS_IOVL, XCROSS_SYMB
      PARAMETER (XCROSS_IOVL=2, XCROSS_SYMB=13)
C
C---- common block last of all
C
      COMMON /MXDCMI/ BASE_WIDTH,BASE_HEIGHT,
     $     IMAGE_ORDER,JIMAGE_ORDER,NXP_CMP,NYP_CMP,
     $     NXDPX,NYDPX,
     $     IMG_HORIZ,IMG_VERT,IMG_MAP,
     $     IMG_X,IMG_Y,MEN_X,MEN_Y,PAR_X,PAR_Y,IO_X,IO_Y,
     $     NOT_X,NOT_Y,PMN_X, PMN_Y,PPB_X, PPB_Y, BUSY_X, BUSY_Y,
     $     BUSY_Y2, IFTYPE,
     $     IMG_WIDTH, IMG_HEIGHT, MEN_WIDTH, MEN_HEIGHT,
     $     PAR_WIDTH, PAR_HEIGHT, IO_WIDTH, IO_HEIGHT,
     $     NOT_WIDTH, NOT_HEIGHT, PMN_WIDTH, PMN_HEIGHT,
     $     PPB_WIDTH, BUSY_WIDTH, BUSY_HEIGHT,
     $     SUB_PROCESS,BLANK,DISP_IMG,DISP_PAR,DISP_MENU,
     $     DISP_IO,DISP_IO2,DISP_IO3,DISP_NOT
  
C&&*&& end_include  ../inc/mxdinc.f
C&&*&& include  ../inc/test.f
C--- awk generated include file  test.h
C---- START of include file test.h
C
C    Detector limits, used in SPTEST. All are in 10 micron units.
C    In the virtual detector frame, Y is parallel to the rotation axis
C    and X is orthogonal to the rotation axis.
C
C    In the scanner frame, X is parallel to the slow direction in the
C    image, Y is the fast direction.
C
C    RSCANSQ      Radius**2 of the scanned region of the plate (Mar scanners)
C                 This is different to the other limits because it is
C                 applied to the actual scanner coordinates rather than
C                 the virtual detector coordinates. All other limits apply
C                 to virtual detector coordinates.
C    XSCAN        Maximum X coordinate in detector frame (10 micron units)
C    YSCAN        Maximum Y coordinate in detector frame (10 micron units)
C    RSCANX,RSCANY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RSCAN defining the
C                 useable area of the detector.
C    XSCAN,YSCAN,RSCAN are maximum coords relative to the physical centre of 
C                 the detector (ie the mid-point of the image), NOT wrt the 
C                 direct beam position.
C    RMINX,RMINY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RMIN defining the
C                 useable area of the detector.
C    RMXSQD       Maximum radius (squared) in virtual detector frame
C    RMNSQD       Minimum radius (squared) in virtual detector frame
C    XMIN         Minimum X coordinate in  detector frame
C    XMAX         Maximum X coordinate in  detector frame
C    YMIN         Minimum Y coordinate in  detector frame
C    YMAX         Maximum Y coordinate in  detector frame
C    NXYEXC       Number of excluded areas set by user (rectangles, arcs)
C    NXYEXCDET    Number of detector specific excluded rectangles (Pilatus)
C    NOTILES      If set true, ignore all tile boundaries in Pilatus images
C    ICEWIDTH     Width of the exclusion shells for ice, this fraction
C                 of the actual resolution is used as the half-width
C    ICEWIDTHPREF Width of the exclusion shells for ice for post
C                 refinement, this fraction
C                 of the actual resolution is used as the half-width
C    PREFEXICE    Logical, true if reflections in ice rings to be
C                 excluded from post-refinement
C
C     .. Scalars in common block /TEST/ ..
      REAL RMXSQD,RMNSQD,XMIN,XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,
     +     RMINX,RMINY,XSCAN,YSCAN,CIRRAD,ICEWIDTH,ICEWIDTHPREF
      INTEGER NEXCL,NXYEXC,NXYEXCDET,IQUADNO,IARCNO,NEXCL2
      LOGICAL PREFEXICE,NOTILES
C
C     .. Arrays in common block /TEST/
      REAL RESEXL,RESEXH,XYEXC,CNREXC,EXCARC,CIRCEN,PHILIM,RES2EXL,
     +     RES2EXH,RES3EXL,RES3EXH,XYEXCSP
      INTEGER IEXCARC
      LOGICAL LEXCARC
C     ..
C     .. Common Block /TEST/ ..
      COMMON /TEST/RESEXL(MAXEXCL),RESEXH(MAXEXCL),XYEXC(4,MAXEXCL),
     +     CNREXC(8,MAXEXCL),
     $     EXCARC(5,MAXEXCL),CIRCEN(2),PHILIM(2),RMXSQD,RMNSQD,XMIN,
     +     XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,RMINX,RMINY,XSCAN,
     $     YSCAN,CIRRAD,IEXCARC(6,MAXEXCL),NEXCL,NXYEXC,IQUADNO,
     $     IARCNO,LEXCARC(MAXEXCL),NXYEXCDET,RES2EXL(MAXEXCL),
     $     RES2EXH(MAXEXCL),NEXCL2,ICEWIDTH,ICEWIDTHPREF,PREFEXICE,
     +     RES3EXL(MAXEXCL),RES3EXH(MAXEXCL),NOTILES,XYEXCSP(4,MAXEXCL)
C     ..
C
C

C&&*&& end_include  ../inc/test.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C     .. local arrays
      REAL VALUE(200),CORNER(4,2)
      INTEGER IBEG(200),IEND(200),IDEC(200),ITYP(200)
      LOGICAL EMPTY(10)
C     ..
C     .. local scalars
      INTEGER MBEAMS,MBEAMC,MBACCIR,MRING,MRINGE,MRECT,MQUAD,MARCO,
     $     MARCI,MRETURN,IQUIT,ITEM,NUMVH,IVH,IVHLIST(3),MRECTE,MQUADE,
     $     MARCE,mauto,IXM,IYM,LINELEN,NUMLIN,I,J,IJ,K,NTOK,IERR
      CHARACTER*(MAX_MEN_NAME) MENU_ITEMS(MAX_MEN_ITMS),EXIT_NAME
      CHARACTER LINE*90,LINE2*90,INOUT*7,LINE80*80
      LOGICAL NULINE
C     ..
C     .. Extrinsic Functions ..
      INTEGER  LENSTR
      EXTERNAL  LENSTR

C     ..
C     .. put the new menu items here, not in mxdspl
      DATA MENU_ITEMS/
     +     'Beam (single point)',
     +     'Beam (from circle)',
     +     ' ',
     +     'Circular backstop',
     +     ' ',
     +     'Rings',
     +     'Edit rings',
     +     ' ',
     +     'Rectangle',
     +     'Edit rectangles',
     +     ' ',
     +     'Quadrilateral',
     +     'Edit Quadrilaterals',
     +     ' ',
     +     'Exclude outside arc',
     +     'Exclude inside arc',
     +     'Edit Arcs ',
     +     ' ',
     +     'Return '/
      DATA MBEAMS,MBEAMC,MBACCIR,MRING,MRINGE,MRECT,MRECTE,MQUAD,
     $     MQUADE,MARCO,MARCI,MARCE,MRETURN,mauto
     $     /201,202,204,206,207,209,210,212,213,215,216,217,219,218/
C     ..
C     .. set up variables
      EXIT_NAME = 'Save/Exit'
      IVHLIST(1) = IVHMEN
      IVHLIST(2) = IVHPAR
      IVHLIST(3) = IVHIMG
      NUMVH = 3
      IXM = 200
      IYM = 200
      LINELEN = 90
      NUMLIN = 32
      DO 990 I = 1,10
        EMPTY(I) = .FALSE.
 990  ENDDO
      CALL MXDMNU(MENU_ITEMS, EXIT_NAME)
      CALL MXDBSY(1,'Waiting for input')
      CALL MXD_GET_EVENTS(NUMVH,IVHLIST,IVH)
      CALL MXD_MENU_AREA_GETITEM(IVHMEN, ITEM, IQUIT)
      ITEM = ITEM + 200
      LINE = '   '
      LINE2 = 'Then click on "fit points"'
C     ..
      IF (ITEM .EQ. MBEAMS)THEN
        MODE = 0
C     ..
      ELSEIF (ITEM .EQ. MBEAMC)THEN
        MODE = 1
C     ..
      ELSEIF (ITEM .EQ. MBACCIR)THEN
        MODE = 2
      elseif (Item .eq. mauto)then
        ierr = 1
        call backstop(pack,ID,ierr)
        mode = 100
        CALL MXDCIO(1,0,0,0,0)
C     ..
      ELSEIF (ITEM .EQ. MRECT)THEN
        MODE = 3
        CALL MXDCIO(0,LINELEN,8,IXM,IYM)
        WRITE(LINE,FMT=7980)
 7980   FORMAT('Exclude Rectangle')
        CALL MXDWIO(LINE,2)
 8000   FORMAT(' Click on two points which ',
     $       'are the opposite corners of a rectangular area to',/,
     $       ' be excluded. ',/,/,
     $       ' Click on a previously chosen point to delete it.')
        WRITE(IOLINE,8000)
        CALL WINDIO(NULINE)
        LINE = ' '
C        CALL MXDWIO(LINE,0)
        CALL MXDWIO(LINE2,3)
C     ..
      ELSEIF (ITEM .EQ. MQUAD)THEN
        MODE = 4
        CALL MXDCIO(0,LINELEN,8,IXM,IYM)
        LINE = 'Exclude quadrilateral'
        CALL MXDWIO(LINE,2)
 8010   FORMAT(' Click on four points which define a convex ',
     $       'quadrilateral to be excluded. ',/,/,
     $       ' Click on a previously chosen point to delete it.')
        WRITE(IOLINE,8010)
        CALL WINDIO(NULINE)
        LINE = ' '
        CALL MXDWIO(LINE2,3)
C     ..
      ELSEIF (ITEM .EQ. MARCO)THEN
        MODE = 5
        CALL MXDCIO(0,LINELEN,8,IXM,IYM)
        LINE = 'Exclude external arc'
        CALL MXDWIO(LINE,2)
 8020   FORMAT(' Click on at least three points on an arc to exclude',
     $       ' the area OUTSIDE the arc.',/,' The first two points',
     $       ' must define the start and finish',/,/,' Click on a ',
     $       'previously chosen point to delete it.')
        WRITE(IOLINE,8020)
        CALL WINDIO(NULINE)
        LINE = ' '
        CALL MXDWIO(LINE2,3)
C     ..
      ELSEIF (ITEM .EQ. MARCI)THEN
        MODE = 6
        CALL MXDCIO(0,LINELEN,8,IXM,IYM)
        LINE = 'Exclude external arc'
        CALL MXDWIO(LINE,2)
 8030   FORMAT(' Click on at least three points on an arc to exclude',
     $       ' the area INSIDE the arc.',/,' The first two points',
     $       ' must define the start and finish',/,/,' Click on a ',
     $       'previously chosen point to delete it.')
        WRITE(IOLINE,8030)
        CALL WINDIO(NULINE)
        LINE = ' '
        CALL MXDWIO(LINE2,3)
C     ..
      ELSEIF (ITEM .EQ. MRING)THEN
        MODE = 7
        CALL MXDCIO(0,LINELEN,8,IXM,IYM)
        LINE = 'Exclude resolution ring'
        CALL MXDWIO(LINE,2)
 8040   FORMAT(' Click on two points, one inside the ring, one',
     $       ' outside.',/,/,' Click on a ',
     $       'previously chosen point to delete it.')
        WRITE(IOLINE,8040)
        CALL WINDIO(NULINE)
        LINE = ' '
        CALL MXDWIO(LINE2,3)
C     ..
      ELSEIF(ITEM .EQ. MRECTE)THEN
        MODE = 100
C     .. edit list of rectangles

        LINE = ' '
        LINE2 = 'rectangles'
        DO 5980 I = 1,10,1
          IF(I.LE.NXYEXC)THEN
            EMPTY(I) = .FALSE.
          ELSE
            EMPTY(I) = .TRUE.
          ENDIF
 5980   ENDDO
        CALL MXDCIO(0,LINELEN,NUMLIN,IXM,IYM)
        IF(NXYEXC.GT.0)THEN
          WRITE(IOLINE,FMT=6000)LINE2(1:LENSTR(LINE2))
 6000     FORMAT('Edit list of excluded ',A,/,/,'Choose the slots to',
     $         ' remove from the list (<Return> will keep all): ',/)
          CALL WINDIO(NULINE)
 6020     FORMAT('Enter list: ')
          DO 1000 I = 1,NXYEXC,1
            WRITE(LINE,FMT=6040)I,(XYEXC(J,I)*0.01,J=1,4)
 6040       FORMAT('Slot ',I2,': corners (',F6.1,',',F6.1,'), (',
     $           F6.1,',',F6.1,')')
            IF(I.EQ.1)THEN
              CALL MXDWIO(LINE,3)
            ELSE
              CALL MXDWIO(LINE,2)
            ENDIF
 1000     ENDDO
          WRITE(LINE,FMT=6020)
          CALL MXDWIO(LINE,1)
          LINE80 = ' '
          CALL MXDRIO(LINE80)
C                    ******************************************
          CALL MPARSE(LINE80,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C                    ******************************************
          IF(NTOK.EQ.0)THEN
C     .. no slots selected
            WRITE(LINE,FMT=6045)
 6045       FORMAT(' No slots have been chosen')
            CALL MXDWIO(LINE,2)
C     .. too many slots selected
          ELSEIF(NTOK.GT.NXYEXC)THEN
            WRITE(LINE,FMT=6046)NTOK,NXYEXC
 6046       FORMAT(' Too many slots (',I2,' have been chosen - ',
     $           'only ',I4,' are available')
            CALL MXDWIO(LINE,2)
          ELSE
            WRITE(LINE,FMT=6050)NTOK
 6050       FORMAT(1X,I2,' slots selected for deletion')
            CALL MXDWIO(LINE,2)
C     .. flag chosen slots
            DO 1020 I=1,NTOK,1
              EMPTY(NINT(VALUE(I))) = .TRUE.
 1020       ENDDO
C
C     .. shuffle filled slots along
            K = 1
            DO 1040 I=1,NXYEXC,1
              DO 1035 WHILE (EMPTY(K).AND.(K.LT.NXYEXC))
                K = K + 1
 1035         ENDDO
              DO 1025 IJ=1,4,1
                XYEXC(IJ,I) = XYEXC(IJ,K)
 1025         ENDDO
              EMPTY(I) = .FALSE.
              EMPTY(K) = .TRUE.
              K = K + 1
 1040       ENDDO
C
C     .. zero slots at end
            J = NXYEXC - NTOK + 1
            DO 1050 I=J,NXYEXC,1
              DO 1045 IJ=1,4,1
                XYEXC(IJ,I) = 0.0
 1045         ENDDO
              EMPTY(I) = .TRUE.
 1050       ENDDO
C
C---- redraw rectangles
C
            DO 1055 J = 1,NXYEXC,1
              CALL MXDDVN(J+10)
 1055       ENDDO
            CALL MXDDSY
C     ..
            NXYEXC = NXYEXC - NTOK
            CALL DRAWMASK(3,0)
            WRITE(LINE,FMT=6070)NXYEXC
            CALL MXDWIO(LINE,2)
 6070       FORMAT('Remaining ',I2,' (renumbered) slots contain: ')
            DO 1060 I = 1,NXYEXC,1
              WRITE(LINE,FMT=6040)I,(XYEXC(J,I)*0.01,J=1,4)
              CALL MXDWIO(LINE,2)
 1060       ENDDO
          ENDIF
          WRITE(LINE,FMT=6080)
          CALL MXDWIO(LINE,2)
          CALL MXDRIO(LINE80)
          CALL MXDCIO(1,0,0,0,0)
        ELSE
          WRITE(LINE,FMT=6060)LINE2(1:LENSTR(LINE2))
 6060     FORMAT(' You have no ',A,' in the list to edit')
          CALL MXDWIO(LINE,2)
          WRITE(LINE,FMT=6080)
 6080     FORMAT(' PRESS Return to continue')
          CALL MXDWIO(LINE,2)
          CALL MXDRIO(LINE80)
          CALL MXDCIO(1,0,0,0,0)
          ENDIF
C     ..
      ELSEIF(ITEM.EQ.MQUADE)THEN
        MODE = 100
C     .. edit list of quadrilaterals

        LINE = ' '
        LINE2 = 'quadrilaterals'
        DO 6120 I = 1,10,1
          IF(I.LE.IQUADNO)THEN
            EMPTY(I) = .FALSE.
          ELSE
            EMPTY(I) = .TRUE.
          ENDIF
 6120   ENDDO
        CALL MXDCIO(0,LINELEN,NUMLIN,IXM,IYM)
        IF(IQUADNO.GT.0)THEN
          WRITE(IOLINE,FMT=6000)LINE2(1:LENSTR(LINE2))
          CALL WINDIO(NULINE)
          DO 1100 I = 1,IQUADNO,1
            WRITE(LINE,FMT=6140)I,(CNREXC(J,I)*0.01,J=1,8)
 6140       FORMAT('Slot ',I2,': corners ',3('(',F6.1,',',F6.1,'), '),
     $           '(',F6.1,',',F6.1,')')
            IF(I.EQ.1)THEN
              CALL MXDWIO(LINE,3)
            ELSE
              CALL MXDWIO(LINE,2)
            ENDIF
 1100     ENDDO
          WRITE(LINE,FMT=6020)
          CALL MXDWIO(LINE,1)
          LINE = ' '
          CALL MXDRIO(LINE80)
C                    ******************************************
          CALL MPARSE(LINE80,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C                    ******************************************
          IF(NTOK.EQ.0)THEN
C     .. no slots selected
            WRITE(LINE,FMT=6045)
            CALL MXDWIO(LINE,2)
          ELSEIF(NTOK.GT.IQUADNO)THEN
C     .. too many slots selected
            WRITE(LINE,FMT=6046)NTOK,IQUADNO
            CALL MXDWIO(LINE,2)
          ELSE
            WRITE(LINE,FMT=6050)NTOK
            CALL MXDWIO(LINE,2)
C     .. flag chosen slots
            DO 1120 I=1,NTOK,1
              EMPTY(NINT(VALUE(I))) = .TRUE.
 1120       ENDDO
C     .. shuffle filled slots along
            K = 1
            DO 1140 I= 1,IQUADNO,1
              DO 1125 WHILE (EMPTY(K).AND.(K.LT.IQUADNO))
                K = K + 1
 1125         ENDDO
              DO 1130 IJ=1,8,1
                CNREXC(IJ,I) = CNREXC(IJ,K)
 1130         ENDDO
              EMPTY(I) = .FALSE.
              EMPTY(K) = .TRUE.
              K = K + 1
 1140       ENDDO
C            
C     .. zero slots at end
            J = IQUADNO - NTOK + 1
            DO 1150 I=J,IQUADNO,1
              DO 1145 IJ = 1,8,1
                CNREXC(IJ,I) = 0.0
 1145         ENDDO
              EMPTY(I) = .TRUE.
 1150       ENDDO
C
C---- redraw quadrilaterals & reset exclusion areas
C
            DO 1155 J=1,IQUADNO,1
              CALL MXDDVN(J+20)
              CORNER(1,1) = CNREXC(1,J)
              CORNER(1,2) = CNREXC(2,J)
              CORNER(2,1) = CNREXC(3,J)
              CORNER(2,2) = CNREXC(4,J)
              CORNER(3,1) = CNREXC(5,J)
              CORNER(3,2) = CNREXC(6,J)
              CORNER(4,1) = CNREXC(7,J)
              CORNER(4,2) = CNREXC(8,J)
              CALL QUADTL(1,J,CORNER,0.0,0.0,IERR)
 1155       ENDDO
            CALL MXDDSY
C     ..
            IQUADNO = IQUADNO - NTOK
            CALL DRAWMASK(4,0)
            WRITE(LINE,FMT=6070)IQUADNO
            CALL MXDWIO(LINE,2)
            DO 1160 I = 1,IQUADNO,1
              WRITE(LINE,FMT=6140)I,(CNREXC(J,I)*0.01,J=1,8)
              CALL MXDWIO(LINE,2)
 1160       ENDDO
          ENDIF
          WRITE(LINE,FMT=6080)
          CALL MXDWIO(LINE,2)
          CALL MXDRIO(LINE80)
          CALL MXDCIO(1,0,0,0,0)
        ELSE
          WRITE(LINE,FMT=6060)LINE2(1:LENSTR(LINE2))
          CALL MXDWIO(LINE,2)
          WRITE(LINE,FMT=6080)
          CALL MXDWIO(LINE,2)
          CALL MXDRIO(LINE80)
          CALL MXDCIO(1,0,0,0,0)
          ENDIF
C     ..
      ELSEIF(ITEM.EQ.MARCE)THEN
        MODE = 100
C     .. edit list of arcs

        LINE = ' '
        LINE2 = 'arcs'
        CALL MXDCIO(0,LINELEN,NUMLIN,IXM,IYM)
        IF(IARCNO.GT.0)THEN
          WRITE(IOLINE,FMT=6000)LINE2(1:LENSTR(LINE2))
          CALL WINDIO(NULINE)
          DO 1200 I = 1,IARCNO,1
            IF(LEXCARC(I))THEN
              INOUT = 'Inside'
            ELSE
              INOUT = 'Outside'
            ENDIF
            WRITE(LINE,FMT=6240)I,(EXCARC(J,I),J=1,3),
     $           (EXCARC(J,I)*RTOD,J=4,5),INOUT(1:LENSTR(INOUT))
 6240       FORMAT('Slot ',I2,': centre (',F6.1,',',F6.1,'),',
     $           ' radius ',F6.1,' angular limits ',2F6.1,1X,A)
            IF(I.EQ.1)THEN
              CALL MXDWIO(LINE,3)
            ELSE
              CALL MXDWIO(LINE,2)
            ENDIF
 1200     ENDDO
          WRITE(LINE,FMT=6020)
          CALL MXDWIO(LINE,1)
          LINE = ' '
          CALL MXDRIO(LINE2)
C                    ******************************************
          CALL MPARSE(LINE2,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C                    ******************************************
          IF(NTOK.EQ.0)THEN
C     .. no slots selected
            WRITE(LINE,FMT=6045)
            CALL MXDWIO(LINE,2)
          ELSEIF(NTOK.GT.IARCNO)THEN
C     .. too many slots selected
            WRITE(LINE,FMT=6046)NTOK,IARCNO
            CALL MXDWIO(LINE,2)
          ELSE
            WRITE(LINE,FMT=6050)NTOK
            CALL MXDWIO(LINE,2)
C     .. flag chosen slots
            DO 1220 I=1,NTOK,1
              EMPTY(NINT(VALUE(I))) = .TRUE.
 1220       ENDDO
C     .. shuffle filled slots along
            K = 1
            DO 1240 I=1,IARCNO,1
              DO 1225 WHILE (EMPTY(K).AND.(K.LT.IARCNO))
                K = K + 1
 1225         ENDDO
              DO 1230 IJ = 1,5
                EXCARC(IJ,I) = EXCARC(IJ,K)
                IEXCARC(IJ,I) = IEXCARC(IJ,K)
 1230         ENDDO
              IEXCARC(6,I) = IEXCARC(6,K)
              LEXCARC(I) = LEXCARC(K)
              EMPTY(I) = .FALSE.
              EMPTY(K) = .TRUE.
              K = K + 1
 1240       ENDDO
C     .. zero slots at end
            J = IARCNO - NTOK + 1
            DO 1250 I=J,IARCNO,1
              DO 1245 IJ = 1,5,1
                EXCARC(IJ,I) = 0.0
                IEXCARC(IJ,I) = 0
 1245         ENDDO
              IEXCARC(6,I) = 0
              EMPTY(I) = .TRUE.
 1250       ENDDO
C
C---- redraw arcs
C
            DO 1255 J=1,IARCNO,1
              CALL MXDDVN(J+30)
 1255       ENDDO
            CALL MXDDSY
C     ..
            IARCNO = IARCNO - NTOK
            CALL DRAWMASK(5,0)
            WRITE(LINE,FMT=6070)IARCNO
            CALL MXDWIO(LINE,2)
C
C---- loop round slots
C
            DO 1260 I = 1,IARCNO,1
              IF(LEXCARC(I))THEN
                INOUT = 'Inside'
              ELSE
                INOUT = 'Outside'
              ENDIF
              WRITE(LINE,FMT=6240)I,(EXCARC(J,I),J=1,3),
     $             (EXCARC(J,I)*RTOD,J=4,5),INOUT(1:LENSTR(INOUT))
              CALL MXDWIO(LINE,2)
 1260       ENDDO
          ENDIF
          WRITE(LINE,FMT=6080)
          CALL MXDWIO(LINE,2)
          CALL MXDRIO(LINE80)
          CALL MXDCIO(1,0,0,0,0)
        ELSE
          WRITE(LINE,FMT=6060)LINE2(1:LENSTR(LINE2))
          CALL MXDWIO(LINE,2)
          WRITE(LINE,FMT=6080)
          CALL MXDWIO(LINE,2)
          CALL MXDRIO(LINE80)
          CALL MXDCIO(1,0,0,0,0)
        ENDIF
C     ..
      ELSEIF(ITEM.EQ.MRINGE)THEN
        MODE = 100
C     .. edit list of RINGS 
        
        LINE = ' '
        LINE2 = 'rings'
        CALL MXDCIO(0,LINELEN,NUMLIN,IXM,IYM)
        IF(NEXCL.GT.0)THEN
          WRITE(IOLINE,FMT=6000)LINE2(1:LENSTR(LINE2))
          CALL WINDIO(NULINE)
          DO 1280 I = 1,NEXCL,1
            WRITE(LINE,FMT=6260)I,RESEXL(I),RESEXH(I)
 6260       FORMAT('Slot ',I2,': resolution range ',F6.2,' to ',F6.2)
            IF(I.EQ.1)THEN
              CALL MXDWIO(LINE,3)
            ELSE
              CALL MXDWIO(LINE,2)
            ENDIF
 1280     ENDDO
          WRITE(LINE,FMT=6020)
          CALL MXDWIO(LINE,1)
          CALL MXDRIO(LINE2)
C     ******************************************
          CALL MPARSE(LINE2,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C     ******************************************
          IF(NTOK.EQ.0)THEN
C     .. no slots selected
            WRITE(LINE,FMT=6045)
            CALL MXDWIO(LINE,2)
          ELSEIF(NTOK.GT.NEXCL)THEN
C     .. too many slots selected
            WRITE(LINE,FMT=6046)NTOK,NEXCL
            CALL MXDWIO(LINE,2)
          ELSE
            WRITE(LINE,FMT=6050)NTOK
            CALL MXDWIO(LINE,2)
            DO 1300 I=1,NTOK,1
C     .. zero chosen slots
              J = NINT(VALUE(I))
              RESEXL(J) = 0.0
              RESEXH(J) = 0.0
              EMPTY(J) = .TRUE.
              CALL MXDDVN(40 + J)
 1300       ENDDO
            CALL MXDDSY
            K = 1
            DO 1320 I=1,NEXCL,1
              DO 1310 WHILE (EMPTY(K).AND.(K.LT.NEXCL))
                K = K + 1
 1310         ENDDO
              RESEXL(I) = RESEXL(K)
              RESEXH(I) = RESEXH(K)
              EMPTY(I) = .FALSE.
              EMPTY(K) = .TRUE.
              K = K + 1
 1320       ENDDO
            DO 1340 I=K,NEXCL,1
C     .. zero slots at end
              RESEXL(I) = 0.0
              RESEXH(I) = 0.0
              EMPTY(I) = .TRUE.
 1340       ENDDO
            NEXCL = NEXCL - NTOK
            WRITE(LINE,FMT=6070)NEXCL
            CALL MXDWIO(LINE,2)
C     
C---- loop round slots
C     
            DO 1360 I = 1,NEXCL,1
              WRITE(LINE,FMT=6260)I,RESEXL(I),RESEXH(I)
              CALL MXDWIO(LINE,2)
 1360       ENDDO
          ENDIF
          WRITE(LINE,FMT=6080)
          CALL MXDWIO(LINE,2)
          CALL MXDRIO(LINE80)
          CALL MXDCIO(1,0,0,0,0)
        ELSE
          WRITE(LINE,FMT=6060)LINE2(1:LENSTR(LINE2))
          CALL MXDWIO(LINE,2)
          WRITE(LINE,FMT=6080)
          CALL MXDWIO(LINE,2)
          CALL MXDRIO(LINE80)
          CALL MXDCIO(1,0,0,0,0)
        ENDIF
C     ..
      ELSEIF (ITEM .EQ. MRETURN)THEN
        MODE = -999
        CALL MXDCIO(1,0,0,0,0)
      ENDIF
      RETURN
      END
