C---- BGLOCAL(I,J,4) ...   Average +ve difference between mean background
C                          of box I,J and its neighbours, expressed as
C                          a multiple of the rms variation of box I,J
C                          Used to identify boxes in shadow.
C     IWTBG     Array dimension (MAXBGBOX,MAXBGBOX) holding weight for
C               each local background area.
C     EXCLDICE  True if spots in resolution shells of ice rings are to be 
C               excluded
C     AUTORESLN Set resolution limit to 4A if spots between 4-6 are much
C               weaker than those between 6A and infinity.
C     AUTORES1  The lower resolution bin boundary (default 6A) for AUTORESLN
C     AUTORES2  The higher resolution bin boundary (default 4A) for AUTORESLN
C     AUTOFAC1  The intensity factor (default 0.2) for AUTORESLN
C     AUTOFAC2  The reflection number factor (default 0.25) for AUTORESLN
C     AUTORING  Automatically exclude radial bins that have too many spots
C               eg due to ice rings.
C     RINGFACT  Rings with more than RINGFACT*(average number of spots) are
C               rejected as potential ice/powder rings. Default 4.0.
C     NUMICE    Number of spots rejected as potentailly being ice spots
C     NTOOFEWPIX Number of spots rejected as having too few pixels.
C     NIMGSUMSPOT Number of images to sum when searching for spots for indexing.
C     NRESOLU   Number of spots rejected by automatic resolution reduction to 4.5
C
C
C     .. Scalars in Common Block /SPOTS2/ and /SPOTS2C/ ..
      REAL CUTPIXMAX,CUTPIXMIN,CUTWXMAX,CUTWXMIN,CUTWYMAX,CUTWYMIN,
     +     XSPLIT,YSPLIT,YOFFSET,XOFFSET,THRESH,RMINSP,RMAXSP,
     +     RMINSRCH,RMAXSRCH,SCALSRCH,SPXMIN,SPYMIN,THRESHMIN,
     +     THRESHMAX,RMSFAC,ANISOMAX,AUTORES1,AUTORES2,AUTOFAC1,
     +     AUTOFAC2,RINGFACT,RES2SD
      INTEGER NBINR,NBINT,IBINLIM,NPIXMIN,NPIXMAX,IIMAG,NIMAG,
     +     MEDWXSPOT,MEDWYSPOT,NSEARCH,ITHSET,ISAFE,IRSTRT,
     +     NSPTD,MAXPKS,MAXYEXT,NXBOX,NYBOX,IPIXMIN,IRMSFAC,
     +     NUMICE,NTOOFEWPIX,NIMGSUMSPOT,NRESOLU
      LOGICAL RADX,RADY,NEWSPT,DOFIND,LOCBG,EXCLDICE,
     +     AUTORESLN,AUTORING,AUTOTHRESH,FOUND(20)
C     ..
C     .. Arrays in common /SPOTS2/  and /SPOTS2C/ ....
      INTEGER NPIX(MXSPOT),IWXSPOT(MXSPOT),IWYSPOT(MXSPOT),
     $     IORDER(MXSPOT),INSPOT(MXSPOT),NOIMG(MAXIMG),ISDSPOT(MXSPOT),
     $     NSPK(MXSPOT), IWTBG(MAXBGBOX,MAXBGBOX), AVBG(IXWDTH)
      REAL BGOD(IXWDTH),PHI(MAXIMG),PHISAVE(MAXIMG),
     $     XSPOT(MXSPOT),YSPOT(MXSPOT),RESOLU(MXSPOT),
     $     RSPOT(MXSPOT),PHISTIM(MAXIMG),PHIRNGA(MAXIMG),
     +     BGODA2(21,21,3)
C     ..
C     .. Common Block /SPOTS2/  and /SPOTS2C/ ....
      COMMON /SPOTS2/
C     .. real scalars
     $     CUTPIXMAX,CUTPIXMIN,CUTWXMAX,CUTWXMIN,CUTWYMAX,CUTWYMIN,
     +     XSPLIT,YSPLIT,YOFFSET,XOFFSET,THRESH,RMINSP,RMAXSP,
     +     RMINSRCH,RMAXSRCH,SCALSRCH,SPXMIN,SPYMIN,THRESHMIN,
     +     THRESHMAX,RMSFAC,ANISOMAX,AUTORES1,AUTORES2,AUTOFAC1,
     +     AUTOFAC2,RINGFACT,RES2SD,
C     .. integer scalars
     $     NBINR,NBINT,IBINLIM,NPIXMIN,NPIXMAX,IIMAG,NIMAG,
     +     MEDWXSPOT,MEDWYSPOT,NSEARCH,ITHSET,ISAFE,IRSTRT,
     +     NSPTD,MAXPKS,MAXYEXT,
     +     NXBOX,NYBOX,
     +     IPIXMIN,IRMSFAC,NUMICE,NTOOFEWPIX,NIMGSUMSPOT,NRESOLU,
C     -- logicals 
     $     RADX,RADY,NEWSPT,DOFIND,LOCBG,EXCLDICE,AUTORESLN,
     $     AUTORING,AUTOTHRESH,FOUND,
C     .. integer arrays
     $     NPIX,IWXSPOT,IWYSPOT,IORDER,INSPOT,NOIMG,ISDSPOT,NSPK,
     +        IWTBG,AVBG,
C     .. real arrays
     $     BGOD,PHI,XSPOT,YSPOT,RESOLU,RSPOT,PHISTIM,PHIRNGA,
     $     BGODA2,PHISAVE

      REAL BGLOCAL(MAXBGBOX,MAXBGBOX,4)
       
      COMMON /SPOTS3/BGLOCAL

      CHARACTER IMGTEMPL*100,IMGFN*100,IMGNUM*9
      COMMON /SPOTS2C/ IMGTEMPL,IMGFN,IMGNUM
C&&*&& end_include  ../inc/spots2.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C&&*&& include  ../inc/xy.f
C
C $Id: xy.f,v 1.1 2002/05/02 10:47:25 harry Exp $
C
C--- awk generated include file  xy.h
C---- START of include file xy.h
C
C     .. Scalars in common block /XY/ ..
      REAL XTOFD,SINV,COSV,TANV,TWOTHETA
      INTEGER ICASS
C     ..
C     .. Common Block /XY/ ..
      COMMON /XY/XTOFD,SINV,COSV,TANV,TWOTHETA,ICASS
C     ..
C
C     XTOFD....  Crystal to detector distance in 10 micron units. Read from
C                keyworded input and never changed.
C
C                Spot positions are calculated in S/R XYSPOT (Called from
C                REEK) and are for an "ideal" detector at a distance of XTOFD.
C                These are converted into pixel positions in S/R MMTOPX
C                which applies the multiplicative factor XTOFRA to allow
C                for refinement of the distance. XTOFRA is the parameter
C                that is actually refined (in RDIST), rather than XTOFD.
C                The refined distance that is printed in the logfile is
C                actually XTOFRA*XTOFD
C
C     ICASS....  Indicates detector type:
C                0     Flat film
C                1     Vee shaped cassettes
C                2     FAST detector (only used in TESTGEN mode of OSCGEN)
C                3     Swung out FAST (ditto)
C                4     IP detector
C     TWOTHETA   Detector swing angle (degrees)
C&&*&& end_include  ../inc/xy.f
C
C---- stuff from Mathias Meyer
C
C&&*&& include  ../inc/harinf.fi
C     1) HARRY INFO

C     dddmm = detector distance mm (ddistanceinmm)
C     dstartdeg = oscillation start deg
C     denddeg = oscillation end deg
C     domegadeg = omega angle in deg
C     ddetectordeg = theta/detector angle in deg
C     dkappadeg = kappa angle in deg

	REAL*8 DDDMM,DSTARTDEG,DENDDEG,DOMEGADEG,DDETECTORDEG,DKAPPADEG

C     dphideg = phi angle in deg
C     dalpha1ang = wavelength al1 in Ang (dalpha1 in swavelength)
C     dorix = detector origin in x dir (dxorigininpix)
C     doriy = detector origin in y dir (dyorigininpix)
C     dadrotdeg(3) = detector rotations 1-3 in deg (dadetectorrotindeg)
C     dsysgain = system gain (dsystemgain)

      REAL*8 DPHIDEG,DALPHA1ANG,DORIX,DORIY,DALPHA,DADROTDEG(3),DSYSGAIN

C     dexpsec = exposure time in sec (dexposuretimeinsec)
C     doversec = overflow exposure time in sec (doverflowtimeinsec)

      REAL*8 DEXPSEC,DOVERSEC,DACONV(10),DB2DEG,DB3DEG

C     iscantype = scantype code number
C     ibx,iby = binning in x and y
C     ixw,iyw = width of image device in x and y
C     inx,iny = number of pixel in image in x and y
C     ioverff = overflow flag (ioverflowflag)

      INTEGER*2 ISCANTYPE,IBX,IBY,IXW,IYW,INX,INY,IOVERFF

C     ioverfarf = overflow flag after remeas. (ioverflowafterremeasureflag)
C     ierror = error flag 0 = ok, 1 = error
C     iiscomp = compression flag 0 = no, 1 = compression type 1
C     ihnx = header nx -> should be the same as inx
C     ihny = header ny -> should be the same as iny
C     id1 = dummy

      INTEGER*2 IOVERFARF,IERROR,IISCOMP,IHNX,IHNY,ID1

C     dwpts = number of points in image inx*iny
C     loverthr = (loverflowthreshold)
C     lastart = (lastartanglesinsteps_qq)
C     laend = (laendanglesinsteps_qq)
C     lnoi = number of short overflows
C     lnol = number of long overflows

	INTEGER*4 DWPTS,LOVERTHR,LASTART(10),LAEND(10),LNOI,LNOL
	INTEGER NHBYTES

      COMMON /HARRYINF/ 
     &        DDDMM,DSTARTDEG,DENDDEG,DOMEGADEG,DDETECTORDEG,DKAPPADEG,
     &	      DPHIDEG,DALPHA1ANG,DORIX,DORIY,DADROTDEG,DSYSGAIN,
     &	      DEXPSEC,DOVERSEC,DACONV,DB2DEG,DB3DEG,
     &        ISCANTYPE,IBX,IBY,IXW,IYW,INX,INY,IOVERFF,
     &        IOVERFARF,IERROR,IISCOMP,IHNX,IHNY,ID1,
     &        DWPTS,LOVERTHR,LASTART,LAEND,LNOI,LNOL,NHBYTES  

C&&*&& end_include  ../inc/harinf.fi
C&&*&& include  ../inc/crysalis.fi
C     2) CRYSALIS IMAGE

C     lmaxnx = max number of pixels in x for image reading
C     lmaxny = max number of pixels in y for image reading
C     lmaxpts = max number of pts for image reading
C	cpixel2 and cpixel4 are for byte swapping if necessary
      INTEGER LMAXNX,LMAXNY,LMAXPTS
      PARAMETER (LMAXNX=2048)                        
      PARAMETER (LMAXNY=2048)                        
      PARAMETER (LMAXPTS=LMAXNX*LMAXNY)                        
	INTEGER*1 CPIXEL(LMAXPTS),CPIXEL2(LMAXPTS*2),CPIXEL4(LMAXPTS*4)
	INTEGER*2 IPIXEL(LMAXPTS)
	INTEGER*4 LPIXEL(LMAXPTS),LOVERPIXEL(LMAXPTS)
	EQUIVALENCE(CPIXEL2(1),IPIXEL(1))
	EQUIVALENCE(CPIXEL4(1),LOVERPIXEL(1))
      COMMON /CRYSALIS/ 
     &           CPIXEL,IPIXEL,LPIXEL,LOVERPIXEL   

C&&*&& end_include  ../inc/crysalis.fi
C
C---- end of stuff from Mathias Meyer
C
      EQUIVALENCE (ITEMPA(1),BTEMPA(1))
      SAVE
C     ..                                            
C     .. Data statements ..Move ISTART to MOSDATA
      DATA ABC/'a','b','c'/
      DATA FIRSTONE/.TRUE./,SAVETIT/.FALSE./,NOTFIRSTOPEN/.FALSE./,
     $     SIMPLE/.FALSE./
      DATA STORIMG/' ',' '/
      CALLEDFROM = 'OPENODS'
c     store the image number for DNA purposes
      IERR = 0
      THIS = 'OPENODS'
      INDENT = 3
      write(dna_image, *) id

C     ..
C     .. zero Bruker underflow & overflow arrays & counter
      IBRUKC = 1
      DO 330 I=1,256,1
        IBRUK(I) = 0
 330  ENDDO

C     ..
C
C---- Set flag if a constant is to be added to all pixel values
C

      ADDALL = (ICONST.NE.0)
C
C---- Allow byte swapping in GETBLK
C
      ISWAP = 0
      NTRY = 0
      NNDIR = 1
C
C---- Assign FIRST_TIME on basis of MODEOP
C
      FIRST_TIME = ((MODEOP.EQ.1).OR.(MODEOP.EQ.2))
      IF (FIRST_TIME) IADD = 0
C---- Get Film area disk storage area
C
      LOGDSK = .FALSE.
      FIRSTSWAP = .TRUE.
C
       IF (FDISK(1).EQ.' ') THEN
C
C---- files must be in current working directory
C
         LOGDSK = .FALSE.
       ELSE
         LOGDSK = .TRUE.
         LNDSK = LENSTR(FDISK(NNDIR))
       END IF
C
C---- Find how many non-blank characters in ident
C          
      IF (.NOT.TEMPLATE) THEN
        NCH = LENSTR(IDENT)
        IDENTT = IDENT(1:NCH)//SEPCHAR
        NCH = NCH +1
        NCH2 = LENSTR(ODEXT)
      END IF
C
      IDTMP = ID
C
C---- Initialise ISTART...has to be set to NREC because on reading the
C     second image it will be reset to 0.
C
      IF (SUMPART.AND.FIRST_TIME) ISTART = NREC
C
C----  Return to this point if reading second image 
C      in order to add partials
C
 10   IF (SUMPART.AND.(.NOT.FIRST_TIME)) THEN
C
C---- set display filename to the PREVIOUS image that was read in.
C
        CDSPTL = ODFILE
        IF ((MODEOP.EQ.3).AND.(FIRSTONE)) THEN
          FIRSTONE = .FALSE.
          STITLE = ODFILE
          SAVETIT = .TRUE.
        END IF
        IF ((MODEOP.NE.3).AND.(SAVETIT)) THEN
          CDSPTL = STITLE
          SAVETIT = .FALSE.
        END IF
C
        IDTMP = ID + 1
C
C---- If displaying after integration, do NOT update ISTART
C
        IF (MODEOP.NE.3) THEN
          IF (ISTART.EQ.0) THEN
            ISTART = NREC
          ELSE IF (ISTART.EQ.NREC) THEN
            ISTART = 0
          END IF
        END IF
      END IF
C
      WRITE (STR,FMT=6000) IDTMP
C
      IF (DEBUG(45)) THEN
        WRITE(IOUT,FMT=6040) ID,IDTMP,NFIRSTI,MODEOP,FORCEREAD,
     +                       IPACK,IPROCESS,ISTART,IISCN,
     +                       GENERICDET,WAIT,NPHIPROFIMG,HDF5FILE,
     +                       INCORE
        IF (ONLINE) WRITE(ITOUT,FMT=6040) ID,IDTMP,NFIRSTI,MODEOP,
     +                    FORCEREAD,IPACK,IPROCESS,ISTART,IISCN,
     +                    GENERICDET,WAIT,NPHIPROFIMG,HDF5FILE,
     +                       INCORE
 6040   FORMAT(1X,'In OPENODS',/,1X,'ID=',I7,' IDTMP=',I7,
     +            ' NFIRSTI=',I4,' MODEOP=',I3,' FORCEREAD',L2,
     +            /,1X,'IPACK=',I3,' IPROCESS=',I3,' ISTART=',I6,
     +            ' IISCN',L2,' GENERICDET',L2, ' WAIT',I6,
     +            '  NPHIPROFIMG=',I3,/,1X,'HDF5FILE',L2,' INCORE',L2)
      END IF
 12   CONTINUE

      IF(HDF5FILE)THEN
        ODFILE = FDISK(NNDIR)(1:LNDSK)//TEMPLSTART
        SHORTFN = TEMPLSTART
      ELSE
C        
        IF (ONEFILE) THEN
C                                       
C---- If only one image/film per file (eg DLAB or LMB or image plate)
C           
          IF (IMGP) THEN
C
C----   No pack identifier for image plate data
C
            IF (LOGDSK) THEN
              IF (TEMPLATE) THEN
                CALL TEMPLMAKE(TEMPLSTART,TEMPLEND,NTDIG,IDTMP,ODFILE,
     +                         IFLAG)
                SHORTFN = ODFILE
                IF (IFLAG.NE.0) THEN
                  WRITE(IOUT,FMT=6030) IDTMP
                  IF (ONLINE) WRITE(ITOUT,FMT=6030) IDTMP
 6030             FORMAT(1X,'***** ERROR *****',/,1X,'Image number ',
     +            I8,' is not compatible with supplied TEMPLATE',/,1X,
     +            'which only allows',I3,' digits.')
                  ID = -999
                  RETURN
                END IF
                ODFILE = FDISK(NNDIR)(1:LNDSK)//ODFILE(1:LENSTR(ODFILE))
              ELSE
                ODFILE = FDISK(NNDIR)(1:LNDSK)//IDENTT(1:NCH)//STR//
     +               '.'//ODEXT(1:NCH2)
              END IF
            ELSE
              IF (TEMPLATE) THEN
                CALL TEMPLMAKE(TEMPLSTART,TEMPLEND,NTDIG,IDTMP,ODFILE,
     +                         IFLAG)
                IF (IFLAG.NE.0) THEN
                  WRITE(IOUT,FMT=6030) IDTMP
                  IF (ONLINE) WRITE(ITOUT,FMT=6030) IDTMP
                  ID = -999
                  RETURN
                END IF
              ELSE
                ODFILE = IDENTT(1:NCH)//STR//'.'//
     +          ODEXT(1:NCH2)
              END IF
            END IF
          ELSE            
C
C----  For films include pack identifier
C
              IF (LOGDSK) THEN
                ODFILE = FDISK(NNDIR)(1:LNDSK)//IDENTT(1:NCH)//STR//
     +               ABC(NFIRSTI)//'.'//ODEXT(1:NCH2)
              ELSE
                ODFILE = IDENTT(1:NCH)//STR//
     +               ABC(NFIRSTI)//'.'//ODEXT(1:NCH2)
              END IF
          END IF
C
C---- 3 film pack in one file (Imperial)
C
        ELSE 
C
C
          IF (LOGDSK) THEN
            ODFILE = FDISK(NNDIR)(1:LNDSK)//IDENTT(1:NCH)//
     +                STR//'.'//ODEXT(1:NCH2)
          ELSE
            ODFILE = IDENTT(1:NCH)//STR//'.'//ODEXT(1:NCH2)
          END IF
C
C
        END IF
      ENDIF
      CALL BADTOGOOD(XODFILE,ODFILE,LENSTR(ODFILE))
C
C---- Test if file exists
C
      INQUIRE (FILE=ODFILE,EXIST=EFILE,NAME=FULLFN)
C
C---- If file does not exist, try another file directory (if more than one
C     has been given)
C
      IF (.NOT.EFILE) THEN
        NNDIR = NNDIR + 1
        IF (FDISK(NNDIR).NE.' ') THEN
          LNDSK = LENSTR(FDISK(NNDIR))
          GOTO 12
        ELSE
          NNDIR = NNDIR - 1
        END IF
      END IF
C
C---- Determine detector type
C
c     Only do this if DETECTOR, SCANNER or MACHINE keyword has not been
C     given! - always with new GUI
C     Add a test on GENERICDET, this defaults to FALSE so will normally have
C     no effect, but it is set TRUE if a generic detector definition
C     is given (ROTATION, ORIGIN, FAST and RECTANGULAR/CIRCULAR) as it is 
C     assumed that if this is genven we do NOT want OMEGA/INVERTX to be reset
C     by the call to GETDETECT (assuming this does recognise the image type).
C     If other parameters (eg image size, header info, packing of data)
C     conform to a known detector type, this can be specified by giving
C     two DETECTOR keywords, the first specifying the detector type (that
C     has the same size/header info etc) and the second giving the generic
C     description that sets INVERTX/OMEGA. GETDETECT will not be called in
C     this case. AGWL 8/5/18
C
      IF ((.NOT.IISCN).AND.(.NOT.GENERICDET)) THEN
        SMACHINE = MACHINE
        SMODEL = MODEL
C
C---- Print for program flow
C
        CALLED = 'GETDETECT'
        COMMENT = 'determine detector type'
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        CALL GETDETECT(ODFILE,ISTAT)
        IF(ISTAT.EQ.-998.AND.SOCKLO)THEN
C
C---- need to send a brief header response, indicating there's a read
C     problem with the image - -998 indicates a permission error
C     
 1711     FORMAT('<?xml version=''1.0''?>',
     $         '<!DOCTYPE brief_header_response>',
     $         '<brief_header_response><status>',
     $         '<code>error</code>',
     $         '</status>',
     $         '<image_filename>',A,'</image_filename>',
     $         '<message>problem reading image - ',
     $         'check file permissions</message>',
     $         '</brief_header_response>')
          WRITE(OUTLINE,FMT=1711)XODFILE(1:LENSTR(XODFILE))
          CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(OUTLINE),
     $         OUTLINE)

          IERR = -1
          RETURN
        ENDIF
        SETADC = .TRUE.
        IISCN = .TRUE.
        IF ((ODFILE.NE.STORIMG(1)).AND.NOTFIRSTOPEN.AND.
     $       ((SMACHINE.NE.MACHINE).OR.(SMODEL.NE.MODEL)))THEN
          IERR = -1
          IF(SOCKLO.AND.IERR.NE.0)THEN
            RETURN
          ENDIF
        ENDIF
        NOTFIRSTOPEN = .TRUE.
      ENDIF
C
C---- Set up title for X-windows display
C
      IF ((.NOT.SUMPART).OR.FIRST_TIME.OR.(MODEOP.EQ.3))
     +                 CDSPTL = ODFILE
C
C---- Find how many non-blank characters in fullfn
C
      NCHFULL = LENSTR(FULLFN)
      IF (MODEOP.NE.2) THEN
        WRITE (IOUT,FMT=6002) FULLFN(1:NCHFULL)
        IF (ONLINE) WRITE (ITOUT,FMT=6002) FULLFN(1:NCHFULL)
      END IF
C
      IF (DEBUG(45)) THEN
        WRITE(IOUT,FMT=60021) ODFILE(1:LENSTR(ODFILE)),ODEXT 
        IF (ONLINE) WRITE(ITOUT,FMT=60021)ODFILE(1:LENSTR(ODFILE)),ODEXT
60021   FORMAT(1X,'odfile:',a,'  odext:',A)
      END IF

C
C---- Test if this is a packed file
C
      NCHAR = LENSTR(ODEXT)
C
C---- only set PACK true if extension is "pck" and not "pck1200" etc
C        
      PACK = (((ODEXT(1:3).EQ.'PCK').OR.(ODEXT(1:3).EQ.'pck')).AND.
     +             (NCHAR.EQ.3))
      IF (PACK) THEN
        IF (MODEOP.NE.2) THEN
          WRITE(IOUT,FMT=6006)
          IF (ONLINE) WRITE(ITOUT,FMT=6006)
        END IF
      END IF
C
C
C---- If a non zero wait time has been given, wait for an interval
C     determined from the wait period, then try again; for compatibility 
C     with previous version, actually do this for twice the waiting period
C
      IF (.NOT.EFILE.AND.(WAIT.NE.0)) THEN
        ITIME = MIN(5,MAX(1,WAIT/10))
        
        NTIMES = 2*(WAIT/ITIME)
        WRITE(IOUT,FMT=6020)
        IF (ONLINE ) WRITE(ITOUT,FMT=6020)
 6020   FORMAT(/,1X,'Waiting for image to be ready')
        I = 1
        DO 13 WHILE ((I.LE.NTIMES).AND.(.NOT.EFILE))
           INQUIRE (FILE=ODFILE,EXIST=EFILE,NAME=FULLFN)
           IF(.NOT.EFILE)THEN
             NOTEFILE = .TRUE.
              CALL MSLEEP(ITIME)
              IF (WINOPEN) CALL MXD_FLU(J)
              IF(SOCKLO)THEN
C
C---- need to send a brief header response, indicating the image doesn't exist yet
C
 1707           FORMAT('<?xml version=''1.0''?>',
     $               '<!DOCTYPE brief_header_response>',
     $               '<brief_header_response><status>',
     $               '<code>notification</code>',
     $               '</status>',
     $               '<image_filename>',A,'</image_filename>',
     $               '<message>image does not exist yet</message>',
     $               '</brief_header_response>')
                WRITE(OUTLINE,FMT=1707)XODFILE(1:LENSTR(XODFILE))
                CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(OUTLINE),
     $               OUTLINE)
              ENDIF
              I = I + 1
           ELSE
              I = NTIMES + 1
              NTRY = 2
           ENDIF
           IF(I.EQ.NTIMES/2)THEN
              WRITE(IOUT,FMT=6020)
              IF (ONLINE ) WRITE(ITOUT,FMT=6020)
           ENDIF
 13     ENDDO
C
C---- give the file time to finish being written if it's appeared just before 
C     above INQUIRE
C
        CALL MSLEEP(MAX(DELAY,ITIME*2))
      END IF
C
C
      IF(SOCKLO.AND.(WAIT.NE.0.0))THEN
          IF(EFILE)THEN
C
C---- need to send a brief header response, indicating the image now exists
C     
 1708       FORMAT('<?xml version=''1.0''?>',
     $           '<!DOCTYPE brief_header_response>',
     $           '<brief_header_response><status>',
     $           '<code>notification</code>',
     $           '</status>',
     $           '<image_filename>',A,'</image_filename>',
     $           '<message>image exists now</message>',
     $           '</brief_header_response>')
            WRITE(OUTLINE,FMT=1708)XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(OUTLINE),
     $           OUTLINE)
          ELSE
C     
C---- need to send a brief header response, indicating the image still doesn't
C     
 1709      FORMAT('<?xml version=''1.0''?>',
     $           '<!DOCTYPE brief_header_response>',
     $           '<brief_header_response><status>',
     $           '<code>notification</code>',
     $           '</status>',
     $           '<image_filename>',A,'</image_filename>',
     $           '<message>image does not exist after wait</message>',
     $           '</brief_header_response>')
            WRITE(OUTLINE,FMT=1709)XODFILE(1:LENSTR(XODFILE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(OUTLINE),
     $           OUTLINE)
            
          ENDIF
      ENDIF
C     
      IF (.NOT. EFILE) THEN
C
C---- If doing a phi profile, and some images are missing, it can be that the
C     first image(s) are not present, so just increment the image number and
C     try again providing no images have yet been integrated.
C
        IF (PHIPROF.AND.(NPHIPROFIMG.EQ.0)) THEN
          WRITE(IOUT,FMT=1710) IDTMP
          IF (ONLINE) WRITE(ITOUT,FMT=1710) IDTMP
 1710     FORMAT(1X,'Image ', I6,' not found, skipping to next image')
          IDTMP = IDTMP + 1
          GOTO 12
        END IF
        FULLFN = ODFILE
        IF (SUMPART.AND.(.NOT.FIRST_TIME)) THEN
C
C----  If the second image for summing partials doesn't exist, set
C      SUMPART false and return
C
          WRITE(IOUT,6003) FULLFN(1:NCHFULL)
          IF (ONLINE) WRITE(ITOUT,6003) FULLFN(1:NCHFULL)
          SUMPART = .FALSE.
          FORCEREAD = .FALSE.
C
C---- This is fatal if doing a multiseg post refinement
C
          IF (MULTISEG) ID = -999
          RETURN
        ELSE
          IF (MODEOP.EQ.2) THEN
            WRITE (IOUT,FMT=6005) FULLFN(1:NCHFULL)
            IF (ONLINE) WRITE (ITOUT,FMT=6005) FULLFN(1:NCHFULL)
            call dna_output_table_start('error')
            call dna_output_list_start('opening_file')
            call dna_output_character_item('filename', 
     +           fullfn(1:nchfull))
            call dna_output_list_end
            call dna_output_table_end
          ELSE 
            WRITE (IOUT,FMT=6004) FULLFN(1:NCHFULL)
            IF (ONLINE) WRITE (ITOUT,FMT=6004) FULLFN(1:NCHFULL)
          END IF
          ID = -999
          FORCEREAD = .FALSE.
          RETURN
        END IF
      END IF

C
C---- Now open the file. Film images are stored as direct access files,
C     but image plate images are sequential unformatted files, so need
C     different OPEN statements
C
C---- if the file was part written we jump back to here to repeat the read.
 3000 CONTINUE
C
C     DO NOT open the file yet if it is a packed file.
C
      IF (PACK.OR.(MACHINE.EQ.'OXFO')) GOTO 16
C
C---- If this is a "tif" format file, read it with a separate routine
C
      IF (MACHINE.EQ.'CCD1') THEN
C
C----  If summing partials, two images are held in memory at any 
C      one time and we must set a pointer to read the next image 
C      into the appropriate part of image.
        IF (SUMPART.AND.(.NOT.FIRST_TIME)) THEN
           IF (MODEOP.NE.3) THEN
             IF (ISTART.EQ.0) IADD = NREC
             IF (ISTART.EQ.NREC) IADD = 0
           ELSE
             IADD = ISTART
          END IF
        END IF
        IF (DEBUG(45)) THEN
          I1 = LENSTR(STORIMG(1))
          IF (I1.EQ.0) I1 = 1
          I2 = LENSTR(STORIMG(2))
          IF (I2.EQ.0) I2 = 1
          WRITE(IOUT,FMT=6010) IDTMP,NREC,ISTART,IYLEN,IADD,NBYTE,
     +            MACHINE,PACK,
     +            XODFILE(1:LENSTR(XODFILE)),
     +            STORIMG(1)(1:I1),STORIMG(2)(1:I2)
          IF (ONLINE) WRITE(ITOUT,FMT=6010) IDTMP,NREC,ISTART,IYLEN,
     +             IADD,NBYTE,MACHINE,PACK,XODFILE(1:LENSTR(XODFILE)),
     +            STORIMG(1)(1:I1),STORIMG(2)(1:I2)
        END IF
C
C---- See if image already in memory
C
        IF (((IADD.EQ.0).AND.((ODFILE.EQ.STORIMG(1)).AND.
     +       (.NOT.FORCEREAD))) .OR.
     +       ((IADD.NE.0).AND.((ODFILE.EQ.STORIMG(2)).AND.
     +       (.NOT.FORCEREAD))))
     +       THEN
C HRP 11.12.2009 not needed?          filestatus = access(odfile,'r')

          CALL QOPEN(INOD,ODFILE,'READONLY')
          GOTO 17
        ENDIF
        IF (WINOPEN) CALL MXDBSY(0,'Reading image')
C
C---- Print for program flow
C
        CALLED = 'TIFF'
        COMMENT = 'to read tiff format image'
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        CALL TIFF(ODFILE,IMAGE(1+IADD*IYLEN),NREC,IYLEN,IERR)
        IF (WINOPEN) CALL MXDBSY(-1, ' ')
C
C---- Set "strip read" flag true for all strips
C
 17     DO 15 IBLK = 1,NREC
          RDSTRIP(IBLK) = .TRUE.
 15     CONTINUE
        GOTO 40
      END IF
C
      IF (IMGP) THEN
        IF (VAXVMS()) THEN
C
C---- Use a large blocksize to speed up data transfer.
C
          OPEN(UNIT=INOD,FILE=ODFILE,STATUS='OLD',FORM='UNFORMATTED')
        ELSE
          IF (FULLCBF) THEN
            IF(MODEL(1:7).NE.'PILATUS')THEN
C
C---- Print for program flow *** does not need to do this if MODEOP=1
C
              CALLED = 'CBF_INFO'
              COMMENT = 'MODE=2 read header full CBF for non-Pilatus'
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              CALL CBF_INFO(ODFILE,MODEOP,0,IERR)
            ENDIF
          ELSE
C HRP 11.12.2009 not needed?          filestatus = access(odfile,'r')
            CALL QOPEN(INOD,ODFILE,'READONLY')
            IF(MACHINE.EQ.'DIP2'.AND.IFILESIZE.EQ.0)THEN
              CALL QQINQ(INOD,ODFILE,ODFILE,IFILESIZE)
C
C---- Print for program flow
C
              CALLED = 'SETDETECT'
              COMMENT = 'MODE=2 for DIP2 images'
              IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              CALL SETDETECT(2,0,IFILESIZE,IERR)
            ENDIF
            CALL QMODE (INOD,0,NCMITM)
          ENDIF
        END IF
      ELSE
        IF (VAXVMS()) THEN
C
C---- Long words for Vax
C
          IREC = NWORD/2
C
C---- Use a large blocksize to speed up data transfer.
C
          OPEN (UNIT=INOD,FILE=ODFILE,
     +       ACCESS='DIRECT',RECL=IREC,FORM='UNFORMATTED',STATUS='OLD')
        ELSE
C HRP 11.12.2009 not needed?          filestatus = access(odfile,'r')
          CALL QOPEN(INOD,ODFILE,'READONLY')
          CALL QMODE (INOD,0,NCMITM)
        END IF
      END IF
C
C---- Work out record number in file of the first strip of
C     ods for the first film to be processed in this pack
C     this information is passed to rdblk via common /scn/
C     NREC, NBYTE are set up in site-specific code in CONTROL, or
C     via keyword SIZE
C         
 16   ICURR = 0
C
      IF (.NOT.ONEFILE) THEN
        ICURR=(NFIRSTI-1)*NREC*NBYTE
        FORCEREAD = .FALSE.
        RETURN
      END IF
C     
C        
C---- if INCORE = .TRUE. then read all image into memory NOW!
C
      IF (.NOT.INCORE) RETURN
C
C----  If summing partials, two images are held in memory at any 
C      one time and we must set a pointer to read the next image 
C      into the appropriate part of image.
C
C----  Read image into memory    
C 
      IF (SUMPART.AND.(.NOT.FIRST_TIME)) THEN
         IF (MODEOP.NE.3) THEN
           IF (ISTART.EQ.0) IADD = NREC
           IF (ISTART.EQ.NREC) IADD = 0
         ELSE
           IADD = ISTART
        END IF
      END IF
C

      IF (DEBUG(45)) THEN
        I1 = LENSTR(STORIMG(1))
        IF (I1.EQ.0) I1 = 1
        I2 = LENSTR(STORIMG(2))
        IF (I2.EQ.0) I2 = 1
        WRITE(IOUT,FMT=6010) IDTMP,NREC,ISTART,IYLEN,IADD,NBYTE,
     +            MACHINE,PACK,
     +            XODFILE(1:LENSTR(XODFILE)),
     +            STORIMG(1)(1:I1),STORIMG(2)(1:I2)
        IF (ONLINE) WRITE(ITOUT,FMT=6010) IDTMP,NREC,ISTART,IYLEN,
     +             IADD,NBYTE,MACHINE,PACK,XODFILE(1:LENSTR(XODFILE)),
     +            STORIMG(1)(1:I1),STORIMG(2)(1:I2)
 6010   FORMAT(1X,'About to store image, idtmp=',I8,/,1X,
     +         'NREC=',I5,' ISTART=',I5,' IYLEN=',I5,' IADD=',I5,
     +         ' NBYTE=',I6,' MACHINE ',A,' PACK',L2,            
     +         /,1X,'IMAGE filename: ',A,/,1X,
     +         'File stored in first slot : ',A,/,1X,
     +         'File stored in second slot: ',A)
      END IF
C
C---- Read for a packed image file
C
      IF (PACK) THEN
        IF (MACHINE.EQ.'OXPK') THEN
C
C---- Print for program flow
C
          CALLED = 'GETHDR'
          COMMENT = 'To get image header information for PCK file'
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL GETHDR(NOVFL,NRECOVFL,ISTAT) 
        END IF
        IF (MODEOP.EQ.2) THEN
          CALL IMSIZ(ODFILE,NREC,IYLEN)
          RETURN
        END IF
C
C---- See if image already in memory
C
        IF (((IADD.EQ.0).AND.((ODFILE.EQ.STORIMG(1)).AND.
     +                                          (.NOT.FORCEREAD))) .OR.
     +      ((IADD.NE.0).AND.((ODFILE.EQ.STORIMG(2)).AND.
     +                                          (.NOT.FORCEREAD))))
     +         GOTO 19
C
        IF (WINOPEN) CALL MXDBSY(0,'Reading image')
C
C---- Print for program flow
C
        CALLED = 'READPACK_WORD'
        COMMENT = 'to read packed image'
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        CALL READPACK_WORD(IMAGE(1+IADD*IYLEN),ODFILE)
C
C
        IF (INVERTX) THEN 
C
C---- Print for program flow
C
          CALLED = 'IMGINV'
          COMMENT = 'to invert image (INVERTX)'
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL IMGINV(IMAGE(1+IADD*IYLEN),NREC,IYLEN,ICONST)
        END IF
C
        IF (DEBUG(45)) THEN
          DO 18 I = 1,NREC
            IF ((I.GE.NREC/2).AND.(I.LE.NREC/2+5)) THEN
              IBEG = (I-1)*IYLEN + IADD*IYLEN
              IEND = IBEG + NDEBUG(45) - 1
              IND1 = 1
              IND2 = NDEBUG(45)
              WRITE(IOUT,FMT=6012) IND1,IND2,I,
     +                 (IMAGE(K),K=IBEG,IEND)
              IF (ONLINE) WRITE(ITOUT,FMT=6012) IND1,IND2,
     +                    I,(IMAGE(K),K=IBEG,IEND)
 6012         FORMAT(1X,'Pixel values for pixels',I5,' to',I5,
     +              ' in stripe',I5,' in the ',
     +               'inverted image'/,(1X,20I6))
            END IF
 18        CONTINUE
        END IF
 19     DO 20 IBLK = 1,NREC
          RDSTRIP(IBLK) = .TRUE.
 20     CONTINUE
        IF (WINOPEN) CALL MXDBSY(-1, ' ')
        GOTO 40
      END IF
C
C---- CBF block
C
      IF (FULLCBF) THEN 
        IF(MODEL(1:7).NE.'PILATUS')THEN
C     
C---- If phi START angle not specified in keyword input, get them from header
C     
          IF ((ISTRT.EQ.0).AND.(IPACK.NE.0)) THEN
            PHIBEGA(IPACK+(IDTMP-ID)) = HPHIS
            PHIENDA(IPACK+(IDTMP-ID)) = HPHIE
          END IF
C     
C---- go through entire list up to now to check that we haven't straddled 360/0
C     and have an apparent discontinuity where none exists
          DO 80 I = 1,IPACK+(IDTMP-ID)-1
            J = I + 1
            IF(PHIBEGA(J).LT.PHIBEGA(I))THEN
              IF((ABS(PHIBEGA(J)+360.0)-ABS(PHIBEGA(I)+HPHIE-HPHIS))
     $               .LT.1E-3)THEN
                PHIBEGA(J) = PHIBEGA(I) + HPHIE - HPHIS
                PHIENDA(J) = PHIBEGA(J) + HPHIE - HPHIS
              ENDIF
            ENDIF
 80       ENDDO

C     
C---- also for other goniostat angles. The sign of twotheta is correct fro Bruker
C     Photon III detectors (but not for others possibly.
C
          IF(ITWOTHETA.EQ.0)THEN
            IF(HTWOTHETA.NE.0.0)TWOTHETA = HTWOTHETA
            CAMCON(5) = TWOTHETA
          ENDIF
        
C
C---- If this call is only to get image size then return
C
          IF (MODEOP.EQ.2)RETURN
C     
C---- See if image already in memory
C
          IF (((IADD.EQ.0).AND.((ODFILE.EQ.STORIMG(1)).AND.
     +         (.NOT.FORCEREAD))) .OR.
     +         ((IADD.NE.0).AND.((ODFILE.EQ.STORIMG(2)).AND.
     +         (.NOT.FORCEREAD))))
     +         GOTO 40
C     
          IF (WINOPEN) CALL MXDBSY(0,'Reading image')
C     
          IERR = 1
          DO WHILE (IERR.NE.0)
C
C---- Print for program flow
C
            CALLED = 'CBF_INFO'
            WRITE(STRING,FMT=6013) MODEOP
            COMMENT = 'with mode='//STRING
            IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
            CALL CBF_INFO(ODFILE,MODEOP,IADD*IYLEN,IERR)
            IF (DEBUG(99)) THEN
              WRITE(IOUT,FMT=6018) MODEOP,IERR
              IF (ONLINE) WRITE(ITOUT,FMT=6018) MODEOP,IERR
 6018         FORMAT(1X,'Returned from CBF_INFO, MODOP=',I3,' IERR=',I5)
            END IF
C
C---- if IERR is < 0, then ADC offset needs to be increased, for time being, just STOP
C
            IF (IERR.LT.0) STOP
C     
C---- if there's an error, first check to see if the file has finished 
C     being written
C
            IF(IERR.NE.0)THEN
C HRP 11.12.2009 not needed?          filestatus = access(odfile,'r')
              CALL QOPEN(INOD,ODFILE,'READONLY')
              CALL QQINQ(INOD,ODFILE,ODFILE,IFILESIZE)
c     WRITE(IOUT,FMT=7000)IFILESIZE
              IF(ONLINE)WRITE(ITOUT,FMT=7000)IFILESIZE
              CALL MSLEEP(1)
              CALL QQINQ(INOD,ODFILE,ODFILE,NEWIFILESIZE)
              IF(IFILESIZE.EQ.NEWIFILESIZE)THEN
                IERR = 0
              END IF
              call qclose(inod)
            ENDIF
          ENDDO
C     
          IF (WINOPEN) CALL MXDBSY(-1, ' ')
C     
C---- end of block for proper CBF type images
C
        ENDIF
        GOTO 40
      ENDIF
C     
C---- Read in header records (if any). The need for byte swapping is
C     determined by looking at the image size in the header record.
C     If it is not 1200,1600,2000 or 2300 for Mar images or 950/1900 for R-axis
C     then the byte order is swapped, if still not 1200,1600,2000,2300 for Mar
C     or 950/1900 for R-axis an error is given. This is done in GETHDR
C
      IF (NHEAD.NE.0) THEN
C
C---- Set a default BYTSWAP in case header records are just going to be
C     skipped.
C
        BYTSWAP = (.NOT.LITEND())
C
C
C---- Print for program flow
C
        CALLED = 'GETHDR'
        write(string,fmt=6013) nhead
        COMMENT = 'to read '//STRING//' header records'
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
        CALL GETHDR(NOVFL,NRECOVFL,ISTAT) 
        IF(ISTAT.NE.0)IERR = -1
        IF(SOCKLO.AND.IERR.NE.0)THEN
 9040     FORMAT('<?xml version="1.0"?>',
     $         '<!DOCTYPE header_response>',
     +         '<header_response>',
     +         '<status><code>error</code>',
     +         '<message>error in reading number of header bytes',
     $         '</message>',
     +         '</status></header_response>')
c          WRITE(OUTLINE,FMT=9040)
c          CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(OUTLINE),OUTLINE)
          IF (VAXVMS()) THEN
C               *************
            CLOSE (UNIT=INOD)
C              *************
          ELSE
C              *************
            CALL QCLOSE(INOD)
C              *************
          END IF
          RETURN
        ENDIF
C
C---- start of block for SLS Pilatus or Eiger images or ADSC PAD
C
        IF(MINICBF)THEN
C
C---- Print for program flow
C
            CALLED = 'PILATUS_F'
            WRITE(STRING,FMT=6013) MODEOP
 6013       FORMAT(I4)
            COMMENT = 'with mode='//STRING
            IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
            CALL PILATUS_F(ODFILE,MODEOP,IERR)
            IF (DEBUG(45)) THEN
              WRITE(IOUT,FMT=6015) (IMAGE(I),I=1,30)
              IF (ONLINE) WRITE(ITOUT,FMT=6015) (IMAGE(I),I=1,30)
            END IF
 6015       FORMAT(1X,'First 30 values in IMAGE array',/,(1x,10I8))
C
C---- If phi START angle not specified in keyword input, get them from header
C
CCCCCCCCCCCCC            IF(NHEAD.GT.4722)THEN
            IF ((ISTRT.EQ.0).AND.(IPACK.NE.0)) THEN
              PHIBEGA(IPACK+(IDTMP-ID)) = HPHIS
              PHIENDA(IPACK+(IDTMP-ID)) = HPHIE
            END IF
C     
C---- go through entire list up to now to check that we haven't straddled 360/0
C     and have an apparent discontinuity where none exists
            DO 90 I = 1,IPACK+(IDTMP-ID)-1
              J = I + 1
              IF(PHIBEGA(J).LT.PHIBEGA(I)) THEN
                IF((ABS(PHIBEGA(J)+360.0)-ABS(PHIBEGA(I)+HPHIE-HPHIS))
     $                 .LT.1E-3) THEN
                  PHIBEGA(J) = PHIBEGA(I) + HPHIE - HPHIS
                  PHIENDA(J) = PHIBEGA(J) + HPHIE - HPHIS
                ENDIF
              ENDIF
 90         ENDDO
C
            IF(ITWOTHETA.EQ.0)THEN
              IF(HTWOTHETA.NE.0.0)TWOTHETA = -HTWOTHETA
              CAMCON(5) = TWOTHETA
            ENDIF
            GOTO 40
        ENDIF
C
C---- END of MINICBF block for SLS Pilatus or Eiger images or ADSC PAD
C

C
C---- start of block for Eiger HDF5 files
C
        IF (HDF5FILE) THEN
          IF(.NOT.HEADONLY)THEN
            IERR = 0
            thisCHUNK = CHUNK
            IMODE = 4
C
C---- If MODEOP=2 (get header info only) set IMODE=2. Otherwise
C     it always reads the image and this is time consuming for 16M 
C     AGWL 23/4/19
C
            IF (MODEOP.EQ.2) IMODE = 2 
CAL 15/4/19            THISCHUNK= 0
C     
C---- Print for program flow
C
            CALLED = 'EIGER'
            WRITE(COMMENT,FMT=6100) IMODE
 6100       FORMAT('with HEADONLY FALSE and IMODE=',I3)
            IF (IMODE.EQ.4) THEN
              STRING2 = ' '
              WRITE(STRING2,FMT=6102) THISCHUNK
 6102          FORMAT(' read the image data for',I3,' images') 
              COMMENT = COMMENT(1:LENSTR(COMMENT))//STRING2
            END IF
cal            IF (IPROCESS.EQ.2) THEN
cal              NIMGSUM = NIMGSUMSPOT
cal            ELSE
cal              NIMGSUM = 1
cal            END IF
            NIMGSUM = 1
            IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
            CALL EIGER(IERR,IMODE,ID,THISCHUNK,NIMGSUM)
            IF ((INVERTX).AND.IMODE.EQ.4) THEN
C     
C---- Print for program flow
C
              CALLED = 'IMGINV'
              COMMENT = 'because INVERTX is TRUE'
              IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
              CALL IMGINV(IMAGE(1+IADD*IYLEN),NREC,IYLEN,ICONST)
            ENDIF
          ENDIF
C
C---- If phi START angle not specified in keyword input, get them from header
C
          IF ((ISTRT.EQ.0).AND.(IPACK.NE.0)) THEN
            PHIBEGA(IPACK+(IDTMP-ID)) = HPHIS
            PHIENDA(IPACK+(IDTMP-ID)) = HPHIE
          END IF
C     
C---- go through entire list up to now to check that we haven't straddled 360/0
C     and have an apparent discontinuity where none exists
          DO 85 I = 1,IPACK+(IDTMP-ID)-1
            J = I + 1
            IF(PHIBEGA(J).LT.PHIBEGA(I))THEN
              IF((ABS(PHIBEGA(J)+360.0)-ABS(PHIBEGA(I)+HPHIE-HPHIS))
     $               .LT.1E-3)THEN
                PHIBEGA(J) = PHIBEGA(I) + HPHIE - HPHIS
                PHIENDA(J) = PHIBEGA(J) + HPHIE - HPHIS
              ENDIF
            ENDIF
 85       ENDDO
        ENDIF
C
C---- end of block for Eiger HDF5 files
C
C     
C---- if goniostat angles have been set in the image header, they should be 
C     set here - two-theta swing, Chi or Kappa.
C
        IF(ITWOTHETA.EQ.0)THEN
          IF(HTWOTHETA.NE.0.0)TWOTHETA = -HTWOTHETA
          CAMCON(5) = TWOTHETA
        ENDIF
C     
C---- machine specific code ---- assign CUTOFF for images where this is
C     specified in image header, if not provided by keyword.
C     
        IF((MACHINE.EQ.'JUPI').OR.(MACHINE.EQ.'SATU').OR.
     $     (MACHINE.EQ.'MERC').OR.(MACHINE.EQ.'A200').OR.
     $     (MACHINE.EQ.'RIPI').OR.(MACHINE.EQ.'RIEI')) THEN
          IF(ICUT.EQ.0)CUTOFF = HCUTOFF
          IF(IPRCUT.EQ.0)PRCUTOFF = HPRCUTOFF
        ENDIF


C ISWUNG should only be set if subkeyword SWUNG_OUT is used!        IF(ABS(TWOTHETA).GT.1E-3)ISWUNG = 1
        GON_CHI = HCHI
        GON_KAPPA = HKAPPA
C
C---- Check for error in read
C
        IF (ISTAT.LT.0) THEN
          IF (ONLINE.AND.WINOPEN) THEN
            IF (ISTAT.EQ.-1) ID = -1001
            IF (ISTAT.EQ.-2) ID = -1002
            RETURN
          ELSEIF(SOCKLO)THEN
          IERR = -1
 9000       FORMAT('<?xml version="1.0"?>',
     $           '<!DOCTYPE header_response>',
     +           '<header_response>',
     +           '<status><code>error</code>',
     +           '<message>different image type</message>',
     +           '</status></header_response>')
C            WRITE(OUTLINE,FMT=9000)
C            CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(OUTLINE),OUTLINE)
            RETURN
          ELSE
            NSHUTERR = 1
            CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
          END IF
        END IF
C
C---- If phi START angle not specified in keyword input, get them from header
C
        IF ((ISTRT.EQ.0).AND.(IPACK.NE.0)) THEN
          PHIBEGA(IPACK+(IDTMP-ID)) = HPHIS
          PHIENDA(IPACK+(IDTMP-ID)) = HPHIE
        END IF
C     
C---- go through entire list up to now to check that we haven't straddled 360/0
C     and have an apparent discontinuity where none exists
        DO 60 I = 1,IPACK+(IDTMP-ID)-1
          J = I + 1
          IF(PHIBEGA(J).LT.PHIBEGA(I))THEN
            IF((ABS(PHIBEGA(J)+360.0)-ABS(PHIBEGA(I)+HPHIE-HPHIS))
     $               .LT.1E-3)THEN
              PHIBEGA(J) = PHIBEGA(I) + HPHIE - HPHIS
              PHIENDA(J) = PHIBEGA(J) + HPHIE - HPHIS
            ENDIF
          ENDIF
 60     ENDDO

      ELSE
C
C---- Following block is for NHEAD.eq.0
C
C---- Prototype Mar (no header) always written on Vaxes so just need to
C     determine byte order on this machine to know if byte swapping
C     is needed.
C
C     Corrected MD images are supposed to be written as little endian
C     so the same holds true
C
        BYTSWAP = (.NOT.LITEND())
C
C---- For Fuji images from CHESS they are written by Suns so opposite is true.
C
        IF (MACHINE.EQ.'FUJI') BYTSWAP = (LITEND())
C
C---- For DIP2000 images are also written by Suns
C
        IF (MACHINE.EQ.'DIP2') BYTSWAP = (LITEND())
      END IF
C
C---- Allow possibility of reversing choice with keyword BSWAP (sets FIXSWAP)
C
      IF (FIXSWAP.AND.FIRSTSWAP) THEN
        BYTSWAP = (.NOT.BYTSWAP)
        FIRSTSWAP = .FALSE.
      END IF
C
C---- If this call is only to get image size, close OD file and return unless
C     this is a Mac Science scanner, in which case need to read whole image
C     in order to get the tail record information
C
      IF ((MODEOP.EQ.2).AND.(MACHINE.NE.'DIP2').AND.
     $     (MACHINE.NE.'OXFO')) THEN
          IF (VAXVMS()) THEN
C              *************
            CLOSE (UNIT=INOD)
C              *************
          ELSE
C
C---- If A Mar 133/165 CCD detector, read first line of image to get
C     the NULLPIX value
C
            IF (MACHINE.EQ.'MARC') THEN
C
C---- check for 3x3, 4x4 Mar Mosaic detectors
C
              IF ((MODEL.NE.'MOSAIC3').AND.(MODEL.NE.'MOSAIC4')) THEN
                 IBLK = 1
                 CALL GETBLK(BTEMPA,4,IBLK,ISWAP,IERR)
C
C---- Trap error in read
C
                 IF (IERR.NE.0) THEN
                   WRITE(IOUT,FMT=6014) IBLK
                   IF (ONLINE) WRITE(ITOUT,FMT=6014) IBLK
                   IF (ONLINE.AND.WINOPEN) THEN
                     ID = -1001
                     RETURN
                   ELSEIF(SOCKLO)THEN
                     ID = -1001
                     IERR = -1
 9020                FORMAT('<?xml version="1.0"?>',
     $                    '<!DOCTYPE header_response>',
     +                    '<header_response>',
     +                    '<status><code>error</code>',
     +                    '<message>error reading record ',I8,
     $                    ': check image is correct size</message>',
     +                    '</status>',
     $                    '<image_filename>',A,'</image_filename>',
     $                    '</header_response>')
C                     WRITE(OUTLINE,FMT=9020)IBLK
C                     CALL WRITE_SOCKET_LENGTH(SERVERFD,
C     $                    LENSTR(OUTLINE),OUTLINE)
                     RETURN
                   ELSE
                     NSHUTERR = 2
                     CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
                   END IF
                 END IF
                 HNULLPIX = ITEMPA(1)
              END IF
            END IF
C              *************
            CALL QCLOSE(INOD)
C            *************
          END IF
          RETURN
      END IF
C
C
C---- Special subroutine to read packed Mar345 images. The MODEL has
C     been assigned to "345" in GETHDR on basis of the first word in the
C     image header; Oxford images can also be written as M345 format
C     Mar flat panel detector is M555
C
      IF ((MODEL.EQ.'M345').or.(MODEL.EQ.'M555')
     $       .or.(MODEL.EQ.'OXM345').or.(MODEL.EQ.'OXFORD')) THEN
C
C---- See if image already in memory
C
          IF (((IADD.EQ.0).AND.((ODFILE.EQ.STORIMG(1)).AND.
     +                                          (.NOT.FORCEREAD))) .OR.
     +      ((IADD.NE.0).AND.((ODFILE.EQ.STORIMG(2)).AND.
     +                                          (.NOT.FORCEREAD))))
     +         GOTO 40
C
          IF (WINOPEN) CALL MXDBSY(0,'Reading image')
C
          INFO(3) = IADD
          NCHAR = LENSTR(ODFILE)
          DO 22 I = 1,NCHAR
            IFILENAM(I) = ICHAR(ODFILE(I:I))
 22       CONTINUE
          IFILENAM(NCHAR+1) = 0
C
C     
C---- Print for program flow
C
          CALLED = 'OPENFILE'
          COMMENT = ' '
          IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL OPENFILE(IFILENAM,IMAGE(1+IADD*IYLEN))
C     
C---- Print for program flow
C
          CALLED = 'IMGINV'
          COMMENT = 'because INVERTX is TRUE'
          IF (INVERTX) 
     +             CALL IMGINV(IMAGE(1+IADD*IYLEN),NREC,IYLEN,ICONST)
          DO 24 IBLK = 1,NREC
            RDSTRIP(IBLK) = .TRUE.
 24        CONTINUE
          IF (WINOPEN) CALL MXDBSY(-1, ' ')
          GOTO 40
      END IF

C
C---- See if image already in memory
C
      IF (((IADD.EQ.0).AND.((ODFILE.EQ.STORIMG(1)).AND.
     +                                          (.NOT.FORCEREAD))) .OR.
     +      ((IADD.NE.0).AND.((ODFILE.EQ.STORIMG(2)).AND.
     +                                          (.NOT.FORCEREAD))))
     +         GOTO 40
C
      IF (WINOPEN) CALL MXDBSY(0,'Reading image')
C
C
C---- start of block for Rigaku Pilatus images
C     Previously, did not test for INVERTX and so always inverted the image!
C     Corrected 14/11/16 AGWL
C
      IF ((MACHINE.EQ.'RIPI').OR.(MACHINE.EQ.'RIEI')) THEN
C
C---- Print for program flow
C
          CALLED = 'byteoffset'
          COMMENT = ' special read for Rigaku Pilatus/Eiger'
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          INVERT =0
          IF (INVERTX) INVERT = 1
          write(iout,fmt=3333) invert
          if (online) write(itout,fmt=3333) invert
 3333     format(1x,'invert is:',i3)
C
C---- Note that image inversion is done within BYTEOFFSET if it is required
C
          call byteoffset(IERR,HHEAD,MODEOP,nrec,iylen,invert,image,
     $         odfile)
          GOTO 40
      ENDIF
        
        
      IF(MACHINE.NE.'OXFO'.and..not.hdf5file)THEN
          RAXISCOMP = HCOMPR
c CANNOT HAVE IFTYPE = 8 UNLESS WE HAVE NEWEST SHINY XDL_VIEW LIBS!
          IF(RAXISCOMP.GT.32)IFTYPE = 8
c          IF(RAXISCOMP.GE.32)IFTYPE = 6
        DO 30 IBLK = 1,NREC            
C
C---- Some scanners put out the image inverted left to right compared with
C     what MOSFLM expects, so correct for that by reading the image
C     inverted here (Mar and Fuji at Chess)
C
          IF (IMGP.AND.(INVERTX)) THEN
            IPOINT = (NREC-IBLK)*IYLEN + 1 + IADD*IYLEN
          ELSE
            IPOINT = (IBLK-1)*IYLEN + 1 + IADD*IYLEN
          END IF
          RDSTRIP(IBLK) = .TRUE.
C
          IERR = 0
C            **********************************************
          CALL GETBLK(IMAGE(IPOINT),NBYTE,IBLK+NHEAD,ISWAP,IERR)
          IF(IERR.NE.0)THEN
C
C---- Wait a short period (currently hard-coded to 1 second, which should be ample) 
C     to see if the file size changes; if it changes, read the
C     current image again; GOTO target reopens file at start.
C
            CALL QQINQ(INOD,ODFILE,ODFILE,IFILESIZE)
c            WRITE(IOUT,FMT=7000)IFILESIZE
            IF(ONLINE)WRITE(ITOUT,FMT=7000)IFILESIZE
 7000       FORMAT(/,' Image does not appear to be complete; since it',
     $           ' is still increasing ',/,' in size (it is now ',I9,
     $           ' bytes), Mosflm will ', 
     $           'wait for a second',/,' for the write to finish',
     $           //,' If there is a ''CCP4 library ',
     $           'signal'' message above, it can be safely ignored',
     $           ' if ',/,
     $           ' Mosflm continues to run',/)
            CALL MSLEEP(1)
            CALL QQINQ(INOD,ODFILE,ODFILE,NEWIFILESIZE)
            IF(IFILESIZE.NE.NEWIFILESIZE)THEN
              IF (VAXVMS()) THEN
C     *************
                CLOSE (UNIT=INOD)
C     *************
              ELSE
C     *************
                CALL QCLOSE(INOD)
C     *************
              END IF
              GOTO 3000
            ENDIF
          ENDIF
C            **********************************************
C
C---- Trap error in read
C
          IF (IERR.NE.0) THEN
            WRITE(IOUT,FMT=6014) IBLK
            IF (ONLINE) WRITE(ITOUT,FMT=6014) IBLK
 6014       FORMAT(/,1X,'Error trying to read record number',I6,
     +             ' in image file.',/,1X,'Check that the file is',
     +             ' the correct length')
            IF (ONLINE.AND.WINOPEN) THEN
              ID = -1001
              RETURN
            ELSEIF(SOCKLO)THEN
              IERR = -1
              ID = -1001
              WRITE(OUTLINE,FMT=9020)IBLK,XODFILE(1:LENSTR(XODFILE))
              CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $             LENSTR(OUTLINE),OUTLINE)
              RETURN
            ELSE
            NSHUTERR = 3
              CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
            END IF
          END IF
C
C---- Print pixel values for first and second stripes
C
          IF (DEBUG(45).AND.(IBLK.LE.2)) THEN
            WRITE(IOUT,FMT=6016) IBLK,(IMAGE(K),K=IPOINT,IPOINT+49)
            IF (ONLINE) WRITE(ITOUT,FMT=6016) IBLK,
     +                       (IMAGE(K),K=IPOINT,IPOINT+49)
 6016       FORMAT(/,1X,'Pixel values for first 50 pixels in stripe',
     +             I3,/,(1X,20I6))
          END IF
C
C---- Now deal with pixel values gt 32767 for Mar scanner and convert from
C     log to linear scale for Fuji scanner.
C     For MAR,CCD,FUJI and UNKNOWN scanners values greater than 32767 
C     are stored as -(true value)/8; Rigaku values gt 32767 are dealt
C     within intpxl.f and intpxl2.f
C
          IF ((MACHINE.EQ.'MAR ').OR.(MACHINE.EQ.'FUJI').OR.
     +        (MACHINE.EQ.'DIP2').OR.(MACHINE.EQ.'CCD1').OR.
     +        (MACHINE.EQ.'CCD2').OR.(MACHINE.EQ.'UNK').OR.
     +        (MACHINE.EQ.'ADSC').OR.(MACHINE.EQ.'MARC').OR.
     +        (MACHINE.EQ.'LIPS').OR.(MACHINE.EQ.'SBC1').OR.
     $        (MACHINE.EQ.'OXFM').OR.(MACHINE.EQ.'BRUK').OR.
     +        (MACHINE.EQ.'NOIR').OR.(MACHINE.EQ.'MARF').OR.
     +        (MACHINE.EQ.'TAUR')) THEN

            DO 32 I = 1,IYLEN
              IOD = IMAGE(IPOINT+I-1)
              IF(.NOT.SIMPLE)THEN
                IF ((MACHINE.EQ.'MAR ').OR.(MACHINE.EQ.'CCD1').OR.
     +               (MACHINE.EQ.'CCD2').OR.(MACHINE.EQ.'UNK').OR.
     +               (MACHINE.EQ.'ADSC').OR.(MACHINE.EQ.'MARC').OR.
     +               (MACHINE.EQ.'LIPS').OR.(MACHINE.EQ.'SBC1').OR.
     $               (MACHINE.EQ.'OXFM').OR.(MACHINE.EQ.'NOIR').OR.
     $               (MACHINE.EQ.'MARF').OR.(MACHINE.EQ.'TAUR'))
     $               SIMPLE = .TRUE.
              ENDIF
              IF(SIMPLE)THEN
                IF (IOD.LT.0) IMAGE(IPOINT+I-1) = -(IOD+65536+4)/8
              ELSE IF (MACHINE.EQ.'FUJI') THEN
                IOD = NINT(10.0**(FLOAT(IOD)*LOGA/LOGB))
                IF (IOD.GT.32767) IOD = -(IOD+4)/8
                IMAGE(IPOINT+I-1) = IOD
              ELSE IF (MACHINE.EQ.'DIP2') THEN
                CONTINUE
              ELSE IF (MACHINE.EQ.'BRUK') THEN
C
C---- for Bruker we just compress the pixel value > 32767 unless it's
C     65535 (= -1), in which case we look in the overflow table. 
C
                IF(IOD.LT.-1)THEN
                  IMAGE(IPOINT+I-1) = -(IOD+65536+4)/8
                ENDIF
                IF(BRUKNEW.AND.IOD.EQ.-1)THEN
                  IBRUK(IBRUKC) = IPOINT+I-1
                  IBRUKC = IBRUKC + 1
                ENDIF
              END IF
C
C---- If requested, add ICONST to all pixel values.For DIP2 it will only
C     be added to pixels with values less than 32767, since values above
C     this are multiples of 128, so assuming ICONST is small it will have
C     no real effect.
C
              IF (ADDALL) THEN
                IF (MACHINE.EQ.'DIP2') THEN
                  IF (IOD.GE.0) IOD = IOD + ICONST
                  IF (IOD.GT.32767) IOD = 32767
                ELSE
                  IF ((IOD.LT.(32766-ICONST)).AND.(IOD.GE.0)) THEN
                    IOD = IOD + ICONST
                  ELSE IF (IOD.LT.0) THEN
                    IOD =  -(IOD+65536+4+ICONST)/8
                  END IF
                END IF
                IMAGE(IPOINT+I-1) = IOD
              END IF
 32         CONTINUE
          END IF
C     
         IF (DEBUG(45).AND.((IBLK.GE.NREC/2).AND.
     +                        (IBLK.LE.NREC/2+5))) THEN
            IBEG = IPOINT
            IEND = IBEG + NDEBUG(45) - 1
            IF (IMGP.AND.(INVERTX)) THEN
              NSTRIPE = NREC-IBLK+1
            ELSE
              NSTRIPE = IBLK
            END IF
            IND1 = 1
            IND2 = NDEBUG(45)
            WRITE(IOUT,FMT=6012) IND1,IND2,
     +            NSTRIPE,(IMAGE(K),K=IBEG,IEND)
            IF (ONLINE) WRITE(ITOUT,FMT=6012) IND1,IND2,
     +          NSTRIPE,(IMAGE(K),K=IBEG,IEND)
          END IF
C
 30    CONTINUE
      ELSE
        IF (.NOT.HDF5FILE) THEN
C
C---- Print for program flow
C
          CALLED = 'READOXIMAGE'
          COMMENT = ' special read for Oxford Detectors'
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL READOXIMAGE(ISWAP,ODFILE)
        ENDIF
      ENDIF
C
C---- Read tail record for DIP2000 images
C
       IF (MACHINE.EQ.'DIP2') THEN
C
C---- Print for program flow
C
         CALLED = 'GETTAIL'
         COMMENT = ' special read for DIP2 detectors'
         IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
         CALL GETTAIL(NREC,IYLEN,IWAVE,IDIST)
C
C---- If phi START angle not specified in keyword input, get them from header
C
         IF (ISTRT.EQ.0)THEN
           IF(IPACK.NE.0) THEN
             PHIBEGA(IPACK+(IDTMP-ID)) = HPHIS
             PHIENDA(IPACK+(IDTMP-ID)) = HPHIE
           ELSE
C
C---- do we need this for the first time round?
C
             PHIBEGA(1) = HPHIS
             PHIENDA(1) = HPHIE
           ENDIF
C     
C---- go through entire list up to now to check that we haven't straddled 360/0
C     and have an apparent discontinuity where none exists
            DO 70 I = 1,IPACK+(IDTMP-ID)-1
              J = I + 1
              IF(PHIBEGA(J).LT.PHIBEGA(I))THEN
                IF((ABS(PHIBEGA(J)+360.0)-ABS(PHIBEGA(I)+HPHIE-HPHIS))
     $               .LT.1E-3)THEN
                  PHIBEGA(J) = PHIBEGA(I) + HPHIE - HPHIS
                  PHIENDA(J) = PHIBEGA(J) + HPHIE - HPHIS
                ENDIF
              ENDIF
 70         ENDDO
         END IF

       ENDIF

C
C---- Now deal with overload records from end of scan - always in the
C     order UNDERFLOW, OVERFLOW*2, OVERFLOW*4, but any or all may be
C     absent. 
C
       IF (((MACHINE.EQ.'MAR ').OR.(MACHINE.EQ.'MARF'))
     $      .AND.(NHEAD.NE.0)) 
     +    CALL GETOVR(IMAGE(1+IADD*IYLEN),NREC,IYLEN,NOVFL,NRECOVFL)
C
C---- Bruker under/overflow tables...
C
       IF ((MACHINE.EQ.'BRUK').AND.(NOVFL.NE.0))
     $      CALL GETBRU(NOVFL,NRECOVFL,IERR)
C
C---- Now deal with Active Mask for Rigaku images - sets values to zero
C
       IF((MACHINE.EQ.'JUPI').OR.(MACHINE.EQ.'SATU').OR.
     $      (MACHINE.EQ.'MERC'))THEN
         IF(LACTIVEMASK)CALL GETMASK(IMAGE,NREC,IYLEN,HACTIVEMASK)
         
       ENDIF
C     
       IF (WINOPEN) CALL MXDBSY(-1, ' ')
C
C----  If adding in partials from second image and this is the first
C      image to be read, read the second one now.
C
C
C---- Save the complete filename of image 
C
 40    IF (IADD.EQ.0) THEN
         STORIMG(1) = ODFILE
       ELSE
         STORIMG(2) = ODFILE
       END IF
C
C---- Return if Mac Science scanner and MODEOP=2
C
CHRP (from Atsushi Nakagawa)
       IF ((MODEOP.EQ.2).AND.(MACHINE.EQ.'DIP2'))THEN
         CALL QCLOSE(INOD)
         RETURN
       ENDIF
C
       IF (SUMPART) THEN
          IF (.NOT.FIRST_TIME) THEN
            FORCEREAD = .FALSE.
CAL            RETURN
            GOTO 50
          END IF 
          FIRST_TIME = .FALSE.
          MODEOP = 0
C
C---- Close the image file of first image. Note it is opened with DISKIO
C     under Unix, Fortran under VMS.
C
          IF (.NOT.PACK.and.(.NOT.FULLCBF).AND.
     $     (MACHINE.NE.'OXFO')) THEN
            IF (VAXVMS()) THEN
C               *************
              CLOSE (UNIT=INOD)
C              *************
            ELSE
C              *************
              CALL QCLOSE(INOD)
C              *************
            END IF
          END IF
          GOTO 10 
        END IF
 50     IF (.NOT.PACK.and.(.NOT.FULLCBF).AND.
     $     (MACHINE.NE.'OXFO')) THEN
          IF (VAXVMS()) THEN
C               *************
            CLOSE (UNIT=INOD)
C              *************
          ELSE
C              *************
            CALL QCLOSE(INOD)
C              *************
          END IF
        END IF
C
C     add for jpeg output - this implementation does not allow for zooming here,
C     although WRITE_JPEG has this ability
C
        PIXMIN = 0
        PIXMAX = 32767
C
C---- TLC , BRC, bottom right and top left corners of image.
C
        BRC(1) = NREC
        BRC(2) = IYLEN
        TLC(1) = 0
        TLC(2) = 0
        ZOOM = 1
        pixmin = imghi
        pixmax = imglow
        BINARY = 0
        IMAGETYPE = 1
        IF(JPGOUT)THEN
C
C---- Print for program flow
C
          CALLED = 'WRITE_COLOUR_JPEG'
          COMMENT = ' '
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL WRITE_COLOUR_JPEG(SERVERFD, NREC, IYLEN, IMAGE, 
     +        PIXMIN, PIXMAX, IMGMAX, 1, TLC, BRC, 0, 0, 0, 
     $        BINARY,IMAGETYPE,SPOT_POSITION,0,PRED_POSITION, 
     +        PRED_TYPE, IRAS(1),IRAS(2),PIXEL_INTENSITIES)
        END IF

      RETURN        

C
C---- Format statements
C
 6000 FORMAT (I3.3)
 6002 FORMAT (/,1X,'image FILENAME: ',A)
 6003 FORMAT (//1X,'**** WARNING ***',/1X,'Image FILE ',A,/,1X,
     +       'Required for adding partials does not exist, so',
     +       ' partial summation has been turned off')
 6004 FORMAT (//1X,'**** ERROR ****',/1X,'Image FILE ',A,
     +       ' DOES NOT EXIST')
 6005 FORMAT (//1X,'**** ERROR ****',/1X,'Trying to open image file to'
     +       ,' get image size but image FILE ',/,1X,A,
     +       ' DOES NOT EXIST')
 6006 FORMAT(1X,'This is a packed image file')
C
      END
C $Id: overlap.f,v 1.10 2012/11/21 14:44:43 andrew Exp $
C== OVERLAP ==
C
      SUBROUTINE OVERLAP(MODE)
C     ========================
C
      IMPLICIT NONE
C
C---- Tests for overlapping reflexions.
C     This routine first sorts on X to speed up the calculation.
C
c     MODE
C          =0 Normal overlap tests
C          =1 Special overlap tests checking overlap of multiple lattices
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
