      COMMON /SPOTS2/
C     .. real scalars
     $     CUTPIXMAX,CUTPIXMIN,CUTWXMAX,CUTWXMIN,CUTWYMAX,CUTWYMIN,
     +     XSPLIT,YSPLIT,YOFFSET,XOFFSET,THRESH,RMINSP,RMAXSP,
     +     RMINSRCH,RMAXSRCH,SCALSRCH,SPXMIN,SPYMIN,THRESHMIN,
     +     THRESHMAX,RMSFAC,ANISOMAX,AUTORES1,AUTORES2,AUTOFAC1,
     +     AUTOFAC2,RINGFACT,RES2SD,
C     .. integer scalars
     $     NBINR,NBINT,IBINLIM,NPIXMIN,NPIXMAX,IIMAG,NIMAG,
     +     MEDWXSPOT,MEDWYSPOT,NSEARCH,ITHSET,ISAFE,IRSTRT,
     +     NSPTD,MAXPKS,MAXYEXT,
     +     NXBOX,NYBOX,
     +     IPIXMIN,IRMSFAC,NUMICE,NTOOFEWPIX,NIMGSUMSPOT,NRESOLU,
C     -- logicals 
     $     RADX,RADY,NEWSPT,DOFIND,LOCBG,EXCLDICE,AUTORESLN,
     $     AUTORING,AUTOTHRESH,FOUND,
C     .. integer arrays
     $     NPIX,IWXSPOT,IWYSPOT,IORDER,INSPOT,NOIMG,ISDSPOT,NSPK,
     +        IWTBG,AVBG,
C     .. real arrays
     $     BGOD,PHI,XSPOT,YSPOT,RESOLU,RSPOT,PHISTIM,PHIRNGA,
     $     BGODA2,PHISAVE

      REAL BGLOCAL(MAXBGBOX,MAXBGBOX,4)
       
      COMMON /SPOTS3/BGLOCAL

      CHARACTER IMGTEMPL*100,IMGFN*100,IMGNUM*9
      COMMON /SPOTS2C/ IMGTEMPL,IMGFN,IMGNUM
C&&*&& end_include  ../inc/spots2.f
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C&&*&& include  ../inc/findspots.f
c     findspots.f header (include) file
c     to pass information about the number of spots found about
c     and to store the default parameters...
c     
c     $Id: findspots.f,v 1.3 2004/08/24 12:00:00 harry Exp $
c

c     values used to pass the spot finding results

      INTEGER FS_FOUND, FS_USED, FS_REJECTED, FS_XMIN, FS_XMAX,
     $     FS_YMIN, FS_YMAX, FS_SEPAR, 
     $     FS_FOUNDTOT, FS_USEDTOT, FS_REJECTEDTOT, FS_XMINTOT, 
     $     FS_XMAXTOT,FS_YMINTOT, FS_YMAXTOT, FS_CLOSETOT

C     VALUES USED TO STORE THE DEFAULT PARAMETER SET

      INTEGER FS_THRESH, FS_RMINSP, FS_RMAXSP, FS_XSPLIT,
     $     FS_YSPLIT, FS_CUTWXMIN, FS_CUTWXMAX, FS_CUTWYMIN,
     $     FS_CUTWYMAX, FS_NPIXMIN, FS_XOFFSET, FS_YOFFSET,FS_CLOSE
      LOGICAL FS_RADX, FS_RADY

      COMMON /FNDSPTS/ FS_FOUND, FS_USED, FS_REJECTED, FS_XMIN, 
     $     FS_XMAX, FS_YMIN, FS_YMAX, FS_SEPAR, 
     $     FS_FOUNDTOT, FS_USEDTOT, FS_REJECTEDTOT, FS_XMINTOT, 
     $     FS_XMAXTOT,FS_YMINTOT, FS_YMAXTOT, FS_CLOSETOT, 
     $     FS_THRESH, FS_RMINSP, FS_RMAXSP, FS_XSPLIT,
     $     FS_YSPLIT, FS_CUTWXMIN, FS_CUTWXMAX, FS_CUTWYMIN,
     $     FS_CUTWYMAX, FS_NPIXMIN, FS_XOFFSET, FS_YOFFSET,FS_CLOSE,
     $     FS_RADX, FS_RADY
C&&*&& end_include  ../inc/findspots.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C     ..
      SAVE
C     ..
C
      OMEGAFD = OMEGAF/DTOR
      SPRESBIN(1) = AUTORES1
      SPRESBIN(2) = AUTORES2
      NEW = .TRUE.
      THRESHLOWSET = .FALSE.
      LIST = DEBUG(62)
      IF(NDEBUG(62).EQ.0)THEN
        DRAW = .FALSE.
      ELSE
        DRAW = .TRUE.
      ENDIF
      IF(ISTAT.NE.-5)ISTAT = 0
      INCRAD = .FALSE.
      MAXARMAXSP = NREC * RAST * 0.50
C
C---- zero counters for rejection/acceptance criteria if this is the
C     first time around
C
 2    IF(COUNT.EQ.1)THEN
        FS_FOUNDTOT = 0
        FS_USEDTOT = 0
        FS_REJECTEDTOT = 0
        FS_XMINTOT = 0
        FS_XMAXTOT = 0
        FS_YMINTOT = 0
        FS_YMAXTOT = 0
        FS_CLOSETOT = 0
      ENDIF
C
C----  Zero counter for spots in each bin
C


      DO 6 I = 1,NBINR
        DO 5 J = 1,NBINT
          ICOUNT(J,I) = 0
 5      CONTINUE
 6    CONTINUE
      DO 8 I = 1,100
        NRBIN(I) = 0
        IF (I.GT.4) GOTO 8
        NIOVERSIG(I) = 0
        IF (I.GT.2) GOTO 8
        NSPRESBIN(I) = 0
        ISPRESBIN(I) = 0
 8    CONTINUE
C
C---- Assign NPREV, pointer to last stored spot, but not if MODE.>= 10
C     as spot coords are not stored in this case.
C
      IF (MODE.LT.10) THEN
        IF (NIMAG.EQ.1) THEN
          NPREV = 0
        ELSE
          NPREV = IENDIMG(NIMAG-1)
        END IF
      END IF
      WXMM = XSPLIT
      WYMM = YSPLIT
      XMM = 0.01*XCEN
      YMM = 0.01*YCEN
      MINPIX = NPIXMIN
      ARMAXSP = ABS(RMAXSP)
      ARMINSP = ABS(RMINSP)
      INFLATION = 5
 10   IF (MODE.GE.10) THEN
        IF(INCRAD)THEN
          ARMAXSP = MIN(ARMAXSP*1.25,MAXARMAXSP)
        ELSE
          ARMAXSP = ABS(RMAXSRCH)
        ENDIF
        ARMINSP = ABS(RMINSRCH)
      END IF

      if((nrec .eq. 0) .or. 
     +     (iylen .eq. 0)) then
         istat = -4
         return
      end if




      IF (DEBUG(62)) THEN
        WRITE(IOUT,FMT=6020) MODE,XMM,YMM,ARMINSP,ARMAXSP,NPREV,
     +                    THRESH,INFLATION,MINPIX
        IF (ONLINE) WRITE(ITOUT,FMT=6020) MODE,XMM,YMM,ARMINSP,ARMAXSP,
     +                                    NPREV,THRESH,INFLATION,MINPIX
 6020   FORMAT(1X,'In PICKSPOTS',/,1X,'MODE=',I3,' spot search ',
     +  'centred on',2F8.2,'mm, inner, outer radii',2F8.2,'mm',/,1X,
     +  'NPREV=',I5,' THRESH',F4.1,' PICKSPOTS INFLATION',I3,
     +  '  MINPIX',I3)
      END IF
      IF (MODE.EQ.2) GOTO 24
C
C
C---- Note that in QUADTL called from FINDSPOTS, it uses IRAS(1) and IRAS(2) 
C     in testing if spot is within an excluded quadrilateral. To artificially
C     extend the qudrilateral for spot finding, increase IRAS(1) and IRAS(2)
C
      IRAS1 = IRAS(1)
      IRAS2 = IRAS(2)
      IRAS(1) = 50
      IRAS(2) = 50

C          ***********************************************************
 11   CALL FINDSPOTS(XMM,YMM,ARMINSP,ARMAXSP,RESHIGH,
     +     WXMM,WYMM,MINPIX,NSPOT,LPRNT,NUBACK,
     $     IERRF,MODE,NSIZX,NSIZY,INRES)
C      call dpssearch(xmm,ymm,ARMINSP,ARMAXSP,nspot,ierrf)
C          ***********************************************************
C
      IRAS(1) = IRAS1
      IRAS(2) = IRAS2
      IF (WINOPEN) CALL MXD_FLU(I)
C
C---- Debug output
C
      IF (DEBUG(62)) THEN
        WRITE(IOUT,FMT=6022) IERRF,MODE,NSPOT,NSEARCH,INFLATION,
     +                       NSIZX,NSIZY
        IF (ONLINE) WRITE(ITOUT,FMT=6022) IERRF,MODE,NSPOT,NSEARCH,
     +               INFLATION,NSIZX,NSIZY
 6022   FORMAT(/,1X,'After FINDSPOTS, IEERF=',I2,' MODE=',I3,
     +        ' NSPOT=',I6,' NSEARCH=',I5,' PICKSPOTS INFLATION=',I3,
     +         /,1X,'NSIZX=',I3,'  NSIZY=',I3)
      END IF
C
C---- too many spots
C
      IF (IERRF.EQ.1) THEN
C
C---- To avoid looping, if the threshold has been reduced because there were
C     only a few spots and spots are small, reset the threshold to its
C     original value and repeat search.
C
        IF (THRESHLOWSET) THEN
          THRESH = SAVETHRESH
          GOTO 2
        END IF
        ISTAT = -2
        RETURN
      END IF
C
C---- if too few spots, increase radius for search up 'till edge of
C     detector (assume symmetric setting); only do this for MODE=20
C     runs at the moment. Also, only do this if INFLATION=1, if it
C     is higher (starts at 5), first try reducing INFLATION.
C
      IF(NSPOT.LT.NSEARCH.AND.MODE.GE.20.AND.
     $     ((MAXARMAXSP-ARMAXSP).GT.1.0)) THEN
C
C---- If this is a hybrid pixel detector, then as a first option decrease the
C     minimum number of pixels. 
C
CAL        HYBRID = ((MACHINE.EQ.'PILA').OR.(MACHINE.EQ.'CBF').OR.
        HYBRID = ((MACHINE.EQ.'PILA').OR.(MACHINE.EQ.'PHOT').OR.
     +            (MACHINE.EQ.'EIGE').OR.(MACHINE.EQ.'HDF5').OR.
     +            (MACHINE.EQ.'RIPI').OR.(MACHINE.EQ.'RIEI').OR.
     +            (MACHINE.EQ.'APAD'))
        IF (HYBRID.AND.(MINPIX.GT.2)) THEN
          MINPIX = MINPIX - 2
          NPIXMIN = MINPIX
          WRITE(IOUT,FMT=6025) MINPIX
          IF (ONLINE) WRITE(ITOUT,FMT=6025) MINPIX
 6025     FORMAT(1X,'Too few spots found, as this is a hybrid pixel,',
     +           ' detector, reduce minimum number of pixels to',I3)
          GOTO 10
        END IF
C
        IF(INFLATION.GE.3)THEN
          INCRAD = .FALSE.
          INFLATION = INFLATION - 2
        ELSE
          INCRAD = .TRUE.
          WRITE(IOUT,6045)ARMAXSP,MIN(ARMAXSP*1.25,MAXARMAXSP)
        
          call dna_output_table_start('warning')
          call dna_output_list_start('spot_finding')
          call dna_output_integer_item('spots_found', nspot)
          call dna_output_real_item('old_search_radius', armaxsp)
          call dna_output_real_item('new_search_radius', armaxsp*1.25)
          call dna_output_list_end
          call dna_output_table_end
          
          
 6045     FORMAT(//,1X,' ** Too few spots found on image!! ',
     $         'increasing radius from ',F8.3,' to ',F8.3)
          IF (ONLINE) WRITE(ITOUT,FMT=6045)ARMAXSP,
     +                       MIN(ARMAXSP*1.25,MAXARMAXSP)
C
C---- Complex expression below necessary because RMAXSRCH can be -ve
C
          RMAXSRCH = SIGN(MIN(ABS(1.25*RMAXSRCH),MAXARMAXSP),RMAXSRCH)
        ENDIF
        IF (DEBUG(62)) THEN
          WRITE(IOUT,FMT=6046) INFLATION,RMAXSRCH
          IF (ONLINE) WRITE(ITOUT,FMT=6046) INFLATION,RMAXSRCH
 6046     FORMAT(1X,'Calling RADBG with PICKSPOTS INFLATION',I3,
     +           ' RMAXSRCH',F8.1)
        END IF
C
C---- Call RADBG again, because INFLATION is lower than on previous
C     call (it was reduced within RADBG) so the threshold will be lower
C     to improve chances of finding spots
C
        IF(RADX)THEN 
          CALL RADBG(MODE,LPRNT,SIGAVG,INFLATION,IERR)
        ELSE
          CALL RADBGY(MODE,LPRNT,SIGAVG,INFLATION,IERR)
        END IF
        GOTO 10
      ELSE
        INCRAD = .FALSE.
      ENDIF
      IF (NSPOT.EQ.0) THEN

        WRITE(IOUT,FMT=6040)
 6040   FORMAT(//,1X,' ** No spots found on image !!')
        call dna_output_table_start('error')
        call dna_output_list_start('spot_finding')
        call dna_output_integer_item('spots_found', nspot)
        call dna_output_list_end
        call dna_output_table_end

        IF (ONLINE) WRITE(ITOUT,FMT=6040)
          ISTAT = -4
          RETURN
      END IF
C
C---- Ensure enough spots found for threshold determination.
C     However, need to check spot size here, especially if detector
C     is a Pilatus, because it is possible that spots have been rejected
C     primarily by MINPIX criterion.
C

      IF (NSPOT.LT.NSEARCH) THEN
        IF ((NSIZX.LE.3).AND.(NSIZY.LE.3).AND.(MINPIX.GE.2)) THEN
          NXY = NSIZX*NSIZY
          IF (NXY.GE.6) THEN
            MINPIX = MINPIX -2
          ELSE
            MINPIX = MINPIX - 1
          END IF
          WRITE(IOUT,FMT=6023) MINPIX
          IF (ONLINE) WRITE(ITOUT,FMT=6023) MINPIX
 6023     FORMAT(1X,'Too few spots found, reduce minimum number',
     +      ' of pixels to',I3)
          GOTO 11
        END IF
        ISTAT = -1
        RETURN
      END IF
C
C---- New style spots file follows
C
      IF (NEW) THEN
        IF (INVERTX) THEN
          XCP = NREC*RAST - XMM
        ELSE
          XCP = XMM
        END IF
      ELSE
C
C----   Write out "pseudo fiducials" for image plates
C       First the camera constants (zero), then give fiducials 1 and 3
C       the direct beam coordinates as specified by XC,YC
C
        XF = 0.0
        YF = 0.0
C
C-----  Note that for the direct beam coordinates we
C       need to transform the input XC,YC to the MOSFLM detector frame
C       which has X parallel to scanner Y and Y antiparallel to scanner X.
C       The coordinates written out are wrt an origin NOT at the direct beam
C       position, but at 2*XC,0 in the scanner frame. In REFIX or IDXREF
C       an origin shift is applied by subtracting the coordinates of the
C       direct beam position (midpoint of fiducials 1 and 3) from all
C       spot coordinates.
C
        XADD = 0.0
        YADD = 0.0
        IF (ABS(OMEGAFD-90.0).LT.0.1) THEN
          YADD = 2*XMM
        ELSE IF (ABS(OMEGAFD-180.0).LT.0.1) THEN
          XADD = 2*XMM
          YADD = 2*YMM
        ELSE IF (ABS(OMEGAFD-270.0).LT.0.1) THEN
          XADD = 2*YMM
        END IF
C 
        COMEGAF = COS(OMEGAF)
        SOMEGAF = SIN(OMEGAF)
        XF1 = XADD + XMM*COMEGAF + YMM*SOMEGAF
        YF1 = YADD - XMM*SOMEGAF + YMM*COMEGAF
C
      END IF
C
      
C
C  Test for acceptable spots
C
C---- If requested, do an analysis of spots
C

      DO 12 I = 1,MAXWXY
        NWXHIST(I) = 0
        NWYHIST(I) = 0
 12   CONTINUE
      DO 13 I = 1,MAXNMAX
        NPKHIST(I) = 0
 13   CONTINUE
C
C---- Build up a histogram of spot sizes to determine statistics
C     on the spot size.
C     This is currently only used to work out the MODE
C     size which is printed but not actually used. The spot
C     size that is used comes from an analysis in FINDSPOTS.
C
      DO 14 I = 1,NSPOT
        IWX = IWXSPOT(I)
        IF (IWX.LT.1) IWX = 1
        IWX = MIN(MAXWXY,IWX)
        NWXHIST(IWX) = NWXHIST(IWX) + 1
        IWY = IWYSPOT(I)
        IF (IWY.LT.1) IWY = 1
        IWY = MIN(MAXWXY,IWY)
        NWYHIST(IWY) = NWYHIST(IWY) + 1
        NMAXIMA = NSPK(I)
        IF (NMAXIMA.LT.1) NMAXIMA = 1
        NMAXIMA = MIN(MAXNMAX,NMAXIMA)
        NPKHIST(NMAXIMA) = NPKHIST(NMAXIMA) + 1
 14   CONTINUE
      IF (DEBUG(62)) THEN
        WRITE(IOUT,FMT=6070) NSPOT,(I,NWXHIST(I),
     +                           I=1,MAXWXY)
        IF (ONLINE) WRITE(ITOUT,FMT=6070) NSPOT,(I,NWXHIST(I),
     +                           I=1,MAXWXY)
 6070   FORMAT(/,1X,' Analysis of distribution of spot sizes in X',
     +         /,1X,'Total number of spots',I5,
     +         /,1X,'Size Number',/,(1X,I4,I6))
        WRITE(IOUT,FMT=6072) (I,NWYHIST(I),
     +                           I=1,MAXWXY)
        IF (ONLINE) WRITE(ITOUT,FMT=6072) (I,NWYHIST(I),
     +                           I=1,MAXWXY)
 6072   FORMAT(/,1X,' Analysis of distribution of spot sizes in Y',
     +         /,1X,'Size Number',/,(1X,I4,I6))
        WRITE(IOUT,FMT=6074) (I,NPKHIST(I),I=1,MAXWXY)
        IF (ONLINE) WRITE(ITOUT,FMT=6074) (I,NPKHIST(I),I=1,MAXWXY)
 6074   FORMAT(/,1X,'Analysis of number of maxima in spots',/,1X,
     +         'Number of maxima   Number',/,(1X,I8,8X,I7))
      END IF
C
C---- Now work out the mode of the distributions in X and Y
C
      MODEX = 0
      MODEY = 0
      MAXNUMX = 0
      MAXNUMY = 0
      DO 16 I = 1,MAXWXY
c      DO 16 I = 2,MAXWXY-1
        IF (NWXHIST(I).GT.MAXNUMX) THEN
          MAXNUMX = NWXHIST(I)
          MODEX = I
        END IF
        IF (NWYHIST(I).GT.MAXNUMY) THEN
          MAXNUMY = NWYHIST(I)
          MODEY = I
        END IF
 16   CONTINUE
C
C---- Note that this uses ALL found spots, and does not impose the RMIN
C     test. This is NOT good !
C
C----  Sort spots on width in x
C

C      write(iout,*)'sorting ',nspot,' spots'
C          ********************************
      CALL SORTUP4(NSPOT,IWXSPOT,IORDER)
C          ********************************
C
C----  Determine median x width (not strictly the median because
C      of the factor 0.6 rather than 0.5). This is not used anymore
C
      I = INT(NSPOT*0.6)
      IF (I.LT.1) I = 1
      MEDWXSPOT = IWXSPOT(IORDER(I))
C
C---- Now use value from "hist.f" rather than the median value AGWL
C
      MEDWXSPOT = MAX(1,NSIZX)
C
C----  Sort spots on width in Y
C
C          ********************************
      CALL SORTUP4(NSPOT,IWYSPOT,IORDER)
C          ********************************
C
C----  Determine median Y width (not strictly the median because
C      of the factor 0.6 rather than 0.5). This is not used anymore
C
      I = INT(NSPOT*0.6)
      IF (I.LT.1) I = 1
      MEDWYSPOT = IWYSPOT(IORDER(I))
C
C
C---- Now use the spot sizes that come from analysis in FINDSPOTS
C     than the median value. AGWL
C
      MEDWYSPOT = MAX(1,NSIZY)
C
      IF (LPRNT.OR.(DEBUG(62))) WRITE(IOUT,FMT=6000)MODEX,MODEY
      IF (ONLINE.AND.(LPRNT.OR.(DEBUG(62)))) WRITE(ITOUT,FMT=6000) 
     +                      MODEX,MODEY
 6000 FORMAT (/2X,'Mode spot size is',I4,' x',I4,' pixels,')
C
      if(lprnt) then
c     write out the size of the average spot


         call dna_output_table_start('spot_size')
         call dna_output_list_start('spot_size')
         call dna_output_integer_item('x', medwxspot)
         call dna_output_integer_item('y', medwyspot)
         call dna_output_list_end
         call dna_output_table_end
         
      end if

C
C---- Check for "overlapping" spots. Intensities of overlapping spots
C     are set -ve.
C
      CALL OVERLAPSP(NSPOT,NREJOV)
      IF (DEBUG(62)) THEN
        WRITE(IOUT,FMT=6003) NREJOV
        IF (ONLINE) WRITE(ItOUT,FMT=6003) NREJOV
 6003   FORMAT(1X,'Number of spots rejected as overlapping:',I5)
      END IF
C
C----  Sort all spots on intensity
C
C          **************************
      CALL SORTUP4(NSPOT,INSPOT,IORDER)
C          **************************
C
C---- Start here if just repeating selection
C     Set min and max spots sizes in X and Y based on observed size
C
 24   WXMIN = MEDWXSPOT*CUTWXMIN
      WXMAX = MEDWXSPOT*CUTWXMAX
C
      WYMIN = MEDWYSPOT*CUTWYMIN
      WYMAX = MEDWYSPOT*CUTWYMAX
      WXYMAX = SQRT((WXMAX**2)+(WYMAX**2))
C
      NREJBIGX = 0
      NREJSMALLX = 0
C
      NREJBIGY = 0
      NREJSMALLY = 0
      NREJBIGXY = 0
      NXLIM = 0
      NYLIM = 0
C
C----  Find actual maximum radius for binning purposes
C
      RSPOTMAX = 0.0
C
C
      DO 30 I = 1,NSPOT
        IF (IWXSPOT(I).LT.WXMIN) GO TO 30
        IF (IWXSPOT(I).GT.WXMAX) GO TO 30
        IF (IWYSPOT(I).LT.WYMIN) GO TO 30
        IF (IWYSPOT(I).GT.WYMAX) GO TO 30
        RSPOTMAX = MAX(RSPOTMAX,RSPOT(I))
   30 CONTINUE
C
C----  Calculate widths of bins
C
      IF (DEBUG(62)) THEN
        WRITE(IOUT,FMT=6030) RSPOTMAX,NBINR,NBINT,WXMIN,
     +                       WXMAX,WYMIN,WYMAX
        IF (ONLINE) WRITE(ITOUT,FMT=6030) RSPOTMAX,NBINR,NBINT,WXMIN,
     +                       WXMAX,WYMIN,WYMAX
 6030   FORMAT(1X,'RSPOTMAX',F12.1,'  NBINR',I3,'  NBINT',I3,' WXMIN',
     +         F6.1,' WXMAX',F6.1,' WYMIN',F6.1,' WYMAX',F6.1)
      END IF
      WBINR2 = (RSPOTMAX**2)/NBINR
      WBINT = 2*PI/NBINT
      NWRITE = 0
      IF (LIST) WRITE(IOUT,FMT=6002)
 6002 FORMAT (/6X,'X',7X,'Y',8X,'R',4X,'Intensity',2X,'Pixels     WX  ',
     +       '  WY')
C
C----   Loop over spots starting with the strongest
C       Write out the strongest IBINLIM spots in each bin
C
      INTTOT = 0
      NPXTOT = 0
      BKGTOT = 0.0
      NUSED = 0
C
      IF(WINOPEN.AND.DEBUG(62))THEN
        WRITE(ITOUT,FMT=8000)
        WRITE(IOUT,FMT=8000)
 8000   FORMAT(/,' KEY to rejections: ',
     $           'RED -    too small in X',/,
     $       20X,'YELLOW - too small in Y',/,
     $       20X,'GREEN -  too big in X',/,
     $       20X,'CYAN  -  too big in Y',/)
      ENDIF
      RWIDTH = ARMAXSP - ARMINSP
      DO 40 I = NSPOT,1,-1
        J = IORDER(I)
C
C---- Do fine sample radial binning for detection of rings of spots
C     Do this before rjecting spots as too small, close etc as it will
C     make it easier to pick up rings
C
        IRBIN = NINT(100.0*(RSPOT(J)-ARMINSP)/RWIDTH)
        IRBIN = MAX(1,IRBIN)
        IRBIN = MIN(100,IRBIN)
        NRBIN(IRBIN) = NRBIN(IRBIN) + 1
        IFLAG(J) = 0
        IX(1) = INT(XSPOT(J)/RAST)
        IY(1) = INT(YSPOT(J)/RAST)
        RATIO1 = 0.0
        RATIO2 = 0.0
        XSPSIZ = IWXSPOT(J)
        YSPSIZ = IWYSPOT(J)
C
C     .. draw a green box around each of the unfiltered spots
C
        IF(WINOPEN.AND.DRAW.AND.DEBUG(62))call dspbox(IX,IY,1,3,4,4)
        IF (DEBUG(62).AND.((NSPOT-I).LE.500)) THEN
          WRITE(IOUT,FMT=6032) I,J,XSPOT(J),YSPOT(J),RSPOT(J),
     +        INSPOT(J),NPIX(J),IWXSPOT(J),IWYSPOT(J)
          IF (ONLINE) WRITE(ITOUT,FMT=6032) I,J,XSPOT(J),YSPOT(J),
     +        RSPOT(J),INSPOT(J),NPIX(J),IWXSPOT(J),IWYSPOT(J)
        END IF
 6032   FORMAT(1X,2I5,3F6.1,I10,I5,2I3)
        IF (RSPOT(J).LT.RMINSP) GO TO 40
        IF (IWXSPOT(J).LT.WXMIN) THEN
          NREJSMALLX = NREJSMALLX + 1
          IF (LIST) WRITE(ITOUT,FMT=6004)(XSPOT(J)-XMM),(YSPOT(J)-YMM),
     +        RSPOT(J),INSPOT(J),NPIX(J),IWXSPOT(J),IWYSPOT(J)
c     red - too small in X
          IF(WINOPEN.AND.DRAW.AND.DEBUG(62))CALL DSPXCRS(IX,IY,1,1,6)
          IF (LIST) WRITE(IOUT,FMT=6004)(XSPOT(J)-XMM),(YSPOT(J)-YMM),
     +         RSPOT(J),INSPOT(J),NPIX(J),IWXSPOT(J),IWYSPOT(J)
 6004     FORMAT (1X,2F8.2,2X,F7.2,2X,I7,2X,I6,2X,2I6,'  REJECTED',
     $         ' - too small in X')
          GO TO 40
        ELSE IF (IWYSPOT(J).LT.WYMIN) THEN
          NREJSMALLY = NREJSMALLY + 1
          IF (LIST) WRITE(ITOUT,FMT=6014)(XSPOT(J)-XMM),(YSPOT(J)-YMM),
     +         RSPOT(J),INSPOT(J),NPIX(J),IWXSPOT(J),IWYSPOT(J)
 6014     FORMAT (1X,2F8.2,2X,F7.2,2X,I7,2X,I6,2X,2I6,'  REJECTED',
     $         ' - too small in Y')
c yellow - too small in Y
          IF(WINOPEN.AND.DRAW.AND.DEBUG(62))CALL DSPXCRS(IX,IY,1,2,6)

          GO TO 40
        ELSE IF (IWXSPOT(J).GT.WXMAX) THEN
          NREJBIGX = NREJBIGX + 1
          IF (LIST) WRITE(ITOUT,FMT=6024)(XSPOT(J)-XMM),(YSPOT(J)-YMM),
     +        RSPOT(J),INSPOT(J),NPIX(J),IWXSPOT(J),IWYSPOT(J)
 6024     FORMAT (1X,2F8.2,2X,F7.2,2X,I7,2X,I6,2X,2I6,'  REJECTED',
     $         ' - too big in X')
c green - too big in X
          IF(WINOPEN.AND.DRAW.AND.DEBUG(62))CALL DSPXCRS(IX,IY,1,3,6)
          GO TO 40
        ELSE IF (IWYSPOT(J).GT.WYMAX) THEN
          NREJBIGY = NREJBIGY + 1
          IF (LIST) WRITE(ITOUT,FMT=6034)(XSPOT(J)-XMM),(YSPOT(J)-YMM),
     +        RSPOT(J),INSPOT(J),NPIX(J),IWXSPOT(J),IWYSPOT(J)
 6034     FORMAT (1X,2F8.2,2X,F7.2,2X,I7,2X,I6,2X,2I6,'  REJECTED',
     $         ' - too big in Y')
c cyan - too big in Y
          IF(WINOPEN.AND.DRAW.AND.DEBUG(62))CALL DSPXCRS(IX,IY,1,4,6)
          GO TO 40
        ELSE IF (ABS(XSPOT(J)-XMM).LT.SPXMIN) THEN
          NXLIM = NXLIM + 1
          IF (LIST) WRITE(ITOUT,FMT=6036)(XSPOT(J)-XMM),(YSPOT(J)-YMM),
     +        RSPOT(J),INSPOT(J),NPIX(J),IWXSPOT(J),IWYSPOT(J)
 6036     FORMAT (1X,2F8.2,2X,F7.2,2X,I7,2X,I6,2X,2I6,'  REJECTED',
     $         ' - X coordinate less than minimum (XMIN)')
c blue - less than XMIN in X
          IF(WINOPEN.AND.DRAW.AND.DEBUG(62))CALL DSPXCRS(IX,IY,1,5,6)
          GOTO 40
        ELSE IF (ABS(YSPOT(J)-YMM).LT.SPYMIN) THEN
          NYLIM = NYLIM + 1
          IF (LIST) WRITE(ITOUT,FMT=6038)(XSPOT(J)-XMM),(YSPOT(J)-YMM),
     +        RSPOT(J),INSPOT(J),NPIX(J),IWXSPOT(J),IWYSPOT(J)
 6038     FORMAT (1X,2F8.2,2X,F7.2,2X,I7,2X,I6,2X,2I6,'  REJECTED',
     $         ' - X coordinate less than minimum (YMIN)')
c magenta - less than YMIN in Y
C
          IF(WINOPEN.AND.DRAW.AND.DEBUG(62))CALL DSPXCRS(IX,IY,1,6,6)
          GOTO 40
        END IF
C
C---- Do sums to work out best threshold
C
        IF (MODE.GE.10) THEN
C  Not clear what the next line is supposed to be doing, comment out
C  AGWL 21/8/12
CAL           if (npix(j).le.0)npix(j)=49
CAL          IF (DEBUG(62)) WRITE(6,*)'INSPOT,NPIX',INSPOT(J),NPIX(J)
          IF (NPIX(J).LE.0) GOTO 40
          INTTOT = INTTOT + INSPOT(J)
          NPXTOT = NPXTOT + NPIX(J)
          BKG = ((REAL(ISDSPOT(J)))**2 - 
     +                   GAIN*INSPOT(J))/(NPIX(J)*GAIN)
          BKGTOT = BKGTOT + BKG
          NUSED = NUSED + 1
          IF (NUSED.EQ.NSEARCH) GOTO 44
          GOTO 40
        END IF
C
C----  Find radial bin
C
        IR = MIN(NBINR,INT(RSPOT(J)**2/WBINR2+1.0))
C
C----  Find theta bin
C
        XS = XSPOT(J) - XMM
        YS = YSPOT(J) - YMM
        THETA = ATAN2(YS,XS)
        IT = MIN(NBINT,INT((THETA+PI)/WBINT+1.0))
C
C----  Increment counter
C
        ICOUNT(IT,IR) = ICOUNT(IT,IR) + 1
C
        IF (ICOUNT(IT,IR).LE.IBINLIM) THEN
C
          IF (NEW) THEN
            IF (INVERTX) THEN
              XF = NREC*RAST - XSPOT(J)
            ELSE
              XF = XSPOT(J)
            END IF
            YF = YSPOT(J)/YSCAL
C
C---- Transfer spot coordinates and intensities in arrays XSPT,YSPT,ISPT
C     Test for negative intensity of "overlapped" spots
C     Note that XSPT,YSPT are in true mm, not "pixel mm", ie Y coordinates
C     have been corrected by YSCAL
C
            IF (INSPOT(J).GT.0) THEN
C
C---- Spot finally accepted as OK. Do statistics here on coarse resolution bins.
              IFLAG(J) = 1
C
C---- Count the number of spots in pre-defined resolution bins and the total
C     intensity in each bin, in preparation for rejcting reflections beyond
C     one of the bin resolution limits. This is to reject possible ice etc 
C     spots from samples that only diffract to low resolution.
C
              RESOL = RESOLU(J)
              IOVERSIG = INSPOT(J)/MAX(ISDSPOT(J),1)
              IF (IOVERSIG.GE.5) THEN
                IF (RESOL.GE.SPRESBIN(1)) THEN
                  NSPRESBIN(1) = NSPRESBIN(1) + 1
                  ISPRESBIN(1) = ISPRESBIN(1) + INSPOT(J)
                ELSE IF (RESOL.GE.SPRESBIN(2)) THEN
                  NSPRESBIN(2) = NSPRESBIN(2) + 1
                  ISPRESBIN(2) = ISPRESBIN(2) + INSPOT(J)
                END IF
              END IF
            END IF
          ELSE
            XF = XADD + XSPOT(J)*COMEGAF + YSPOT(J)*SOMEGAF/YSCAL
            YF = YADD - XSPOT(J)*SOMEGAF + YSPOT(J)*COMEGAF/YSCAL
          END IF
C
          IF (LIST) WRITE(ITOUT,FMT=6006)(XSPOT(J)-XMM),(YSPOT(J)-YMM),
     +        RSPOT(J),INSPOT(J),NPIX(J),IWXSPOT(J),IWYSPOT(J)
 6006     FORMAT (1X,2F8.2,2X,F7.2,2X,I7,2X,I6,2X,2I6)
        END IF           
   40 CONTINUE
 44   CONTINUE
C
C---- If threshold supplied, do not recalculate it
C
      IF (MODE.EQ.30) RETURN
C
C--- Calculate an optimum threshold based on statistics from above
C    This does not actually seem to work reliably, THRESH is simply set to 5
C    in the code below so all this can probably be eliminated !
C
      IF (MODE.GE.10) THEN
CAL        INTTOT = INTTOT/NPXTOT
         if(nused.eq.0)nused=1
        INTTOT = INTTOT/(NUSED*MEDWXSPOT*MEDWYSPOT)
        BKG = BKGTOT/REAL(NUSED)
        IF (DEBUG(62)) 
     +   WRITE(6,*)'nsearch,mean I per pix, mean bkg',NUSED,INTTOT,BKG
        X = SCALSRCH*INTTOT
        X = GAIN*(X/SIGAVG)*0.001*(BKG-THRESH*SIGAVG)
C
C---- Ensure THRESH is always 4 or more
C
        X = MAX(X,0.0)
        THRESH = MAX(THRESH,(X + 4.0))

C
C---- Set THRESH to 5, as calcualtion above now makes it too high
C
        THRESH = 5.0
C
C---- Make sure that this is above the minimum threshold set if there
C     were too many spots found
C
        THRESH = MAX(THRESH,THRESHMIN)
        RETURN
      END IF
C
C---- statistics on radial bin distribution
C
      NBIN = 0
      NTOT = 0
      SUM = 0.0
      AVG = 0.0
      RMSD = 0.0
      DO 46 I = 1,100
        N = NRBIN(I)
        IF (N.GT.0) THEN
          NBIN = NBIN + 1
          NTOT = NTOT + N
          SUM = SUM + N*N
        END IF
 46   CONTINUE
      IF (NBIN.GT.0) THEN
        AVG = NTOT/NBIN
        RMSD = SQRT(SUM/NBIN - AVG*AVG)
      END IF
C
C---- Flag bins with more than RINGFACT(Default 4.0)*average number of spots
C
      NBADBIN = 0
      DO 48 I = 1,100
        IFLGBIN(I) = 0
        N = NRBIN(I)
        IF (N.GT.NINT(RINGFACT*AVG)) THEN
          IFLGBIN(I) = 1
          NBADBIN = NBADBIN + 1
        END IF
 48   CONTINUE
C
C---- Loop over spots rejecting those in bad bins
C
      NBADBINREF = 0
      DO 49 I = 1,NSPOT
        IRBIN = NINT(100.0*(RSPOT(I)-ARMINSP)/RWIDTH)
        IRBIN = MAX(1,IRBIN)
        IRBIN = MIN(100,IRBIN)
        IF ((IFLGBIN(IRBIN).GT.0).AND.AUTORING) THEN
          INSPOT(I) = -ABS(INSPOT(I))
          NBADBINREF = NBADBINREF + 1
        END IF
 49   CONTINUE

      IF (DEBUG(62)) THEN
        WRITE(IOUT,FMT=6090) AVG,RMSD,(NRBIN(I),I=1,100)
        IF (ONLINE) WRITE(ITOUT,FMT=6090) AVG,RMSD,(NRBIN(I),I=1,100)

 6090   FORMAT(1X,'Radial spot distribution, average and rmsd of',
     +          ' occupied bins',2F6.0,/,10(1X,10I6/))
      END IF
      IF (AUTORING) THEN
        WRITE(IOUT,FMT=6092) NBADBINREF,NBADBIN
        IF (ONLINE) WRITE(ITOUT,FMT=6092) NBADBINREF,NBADBIN
 6092 FORMAT(/,1X,'A total of ',I5,' spots have been rejected as',
     +      ' lying on rings in',I3,' radial bins.',/,1X,
     +      'Some of these may also',
     +      ' have been rejected by the criteria below.')
      ELSE
        WRITE(IOUT,FMT=6094) NBADBINREF,NBADBIN
        IF (ONLINE) WRITE(ITOUT,FMT=6094) NBADBINREF,NBADBIN
 6094   FORMAT(/,1X,'A total of ',I5,' spots ',
     +      ' lying on or close to rings in',I3,' radial bins',/,1X,
     +      'have been detected but not rejected (use FINDSPOTS',
     +      ' AUTORING to reject them).')
      END IF
C
C---- Try to detect cases where there is only low resolution diffraction but
C     ice or noise spots at higher resolution.
C     Compare number of spots found and mean intensity in the 6-1000 and 4-6A
C     bins.
      IBIN1 = 0
      IBIN2 = 0
      NBIN1 = NSPRESBIN(1) 
      NBIN2 = NSPRESBIN(2) 
      IF (NBIN1.GT.0) IBIN1 = ISPRESBIN(1)/FLOAT(NBIN1)
      IF (NBIN2.GT.0) IBIN2 = ISPRESBIN(2)/FLOAT(NBIN2)
C
C---- If number of spots between 6.5A(AUTORES1) and 4.5A(,AUTORES2) are 
C     fewer than 0.25(AUTOFAC2)* no. of spots between infinity and 6.5A(AUTORES1), 
C     OR if mean intensity is less than 0.2(AUTOFAC1)* mean intensity, 
C     set resolution limit to 4.5A(AUTORES2).
C     Only do this when doing proper spot search
C
      RESOL = 0.0
      IF (DEBUG(62)) THEN
        WRITE(IOUT,FMT=6082) AUTORES1,AUTORES1,AUTORES2,NBIN1,NBIN2,
     +                       IBIN1,IBIN2
        IF (ONLINE) WRITE(ITOUT,FMT=6082) AUTORES1,AUTORES1,AUTORES2,
     +                       NBIN1,NBIN2,IBIN1,IBIN2
 6082   FORMAT(/,1X,'Numbers of reflections in inf-',F4.1,' and ',
     +         F4.1,'-',F4.1,' bins:',
     +         2I5,/,1X,'Mean intensity in these bins',2I8)
      END IF
C
C---- Modify the test against intensity to test against the smaller
C     of AUTOFAC1*IBIN1 or 500, because if there are many overloaded
C     spots at low resolution, IBIN1 is so high that the test fails
C     even for strong high resolution images.
C     AGWL 21Sep11
C
      NRESOLU = 0
      IF ((MODE.LT.10).AND.AUTORESLN.AND.
     +         ((NBIN2.LT.NINT(AUTOFAC2*NBIN1)).OR.
     +         (IBIN2.LT.MIN(NINT(AUTOFAC1*IBIN1),500)))) THEN 
         RESOL = AUTORES2
        WRITE(IOUT,FMT=6080) NBIN1,AUTORES1,IBIN1,NBIN2,
     +          AUTORES1,AUTORES2,IBIN2,RESOL
        IF (ONLINE) WRITE(ITOUT,FMT=6080) NBIN1,AUTORES1,IBIN1,
     +          NBIN2,AUTORES1,AUTORES2,IBIN2,RESOL
 6080   FORMAT(/,1X,'** WARNING **',/,1X,I5,' spots found between',
     +      ' infinity and ',F4.1,'A with mean intensity',I6,/,1X,
     +      'but only',I5,' spots found between ',F4.1,'A and ',F4.1,
     +      'A with mean intensity',I5,/,1X,'so resolution limit ',
     +      'has been set to ',F4.1,'A to avoid including noise')
C
C---- Reject spots by setting intensity negative. Note that ABS is required as
C     intensity may already have been set -ve by other rejection tests above.
C
        DO 54 I = 1,NSPOT
          IF (RESOLU(I).LT.RESOL) THEN
            INSPOT(I) = -ABS(INSPOT(I))
            NRESOLU = NRESOLU + 1
          END IF
 54    CONTINUE
      END IF
C
C---- Now finally transfer coords, I and SD for accepted spots
C     While doing this, bin reflections in i/sig(I) bins to allow
C     selection of an threshold.
C
      DO 60 I = NSPOT,1,-1
        J = IORDER(I)
        IF ((IFLAG(J).EQ.0).OR.(INSPOT(J).LT.0)) GOTO 60
        IF (NWRITE+NPREV.LT.NSPOTS) THEN
          YF = YSPOT(J)/YSCAL
          NWRITE = NWRITE + 1
          XSPT(NWRITE+NPREV) = XSPOT(J)
          YSPT(NWRITE+NPREV) = YF
          ISPT(NWRITE+NPREV) = INSPOT(J)
          ISDSPT(NWRITE+NPREV) = MAX(ISDSPOT(J),1)
          IOVERSIG = ISPT(NWRITE+NPREV)/ISDSPT(NWRITE+NPREV)
          IF (IOVERSIG.GT.20) THEN
            IOVERSIGB = 1
          ELSE IF (IOVERSIG.GT.10) THEN
            IOVERSIGB = 2
          ELSE IF (IOVERSIG.GT.5) THEN
            IOVERSIGB = 3
          ELSE 
            IOVERSIGB = 4
          END IF
          NIOVERSIG(IOVERSIGB) = NIOVERSIG(IOVERSIGB) + 1
        ELSE
C
C---- Set error flag, too many spots to store
C
          ISTAT = -3
        END IF
 60   CONTINUE
C
C---- Get cumulative totals
C
      NIOVERSIG(2) = NIOVERSIG(2) + NIOVERSIG(1)
      NIOVERSIG(3) = NIOVERSIG(3) + NIOVERSIG(2)
      NIOVERSIG(4) = NIOVERSIG(4) + NIOVERSIG(3)
C
C---- test for small spots (le 3x3 pixels) and <75 spots and minpix>4, 
C     if so, reduce spot finding threshold to 4,reduce minpix by 2 (but
C     with a minimum of 2) and repeat search
C
      IF (DEBUG(62)) THEN
        WRITE(IOUT,FMT=6101) THRESH,NSIZX,NSIZY,NIOVERSIG(3),
     +                       NPIXMIN,ISTAT
        IF (ONLINE) WRITE(ITOUT,FMT=6101) THRESH,NSIZX,NSIZY,
     +     NIOVERSIG(3),NPIXMIN,ISTAT
      END IF
 6101 FORMAT(1X,'thresh',F5.1,' nsizx,y:',2i5,' No gt 5sig:',I5,
     +        ' NPIXMIN',I3,'  ISTAT',I4)

      IF ((THRESH.GE.5.0).AND.(NSIZX.LE.3).AND.(NSIZY.LE.3).AND.
     +    (NIOVERSIG(3).LT.75).AND.(ISTAT.NE.-5)
     +     .AND.(NPIXMIN.NE.2)) THEN
C
C---- Reset threshold only if it has not already been set to 4,
c     because setting to 4 might have given too many spots, and so
C     the threshold may have had to be increased. This avoids infinite
C     looping.
C
         IF (.NOT.THRESHLOWSET) THEN
           SAVETHRESH = THRESH
           THRESH = 4.0
         END IF
C
C---- Test for NPIXMIN.ne.1 is because if user has entered a value
C     of one, do not want to reset it here
C
         IF (NPIXMIN.NE.1) NPIXMIN = MAX(2,NPIXMIN-2)
         WRITE(IOUT,FMT=6100)THRESH,NPIXMIN
         IF (ONLINE) WRITE(ITOUT,FMT=6100) THRESH,NPIXMIN
 6100     FORMAT(/,/,1X,'Spot size is small and there are fewer',
     +          ' than 75 spots with I/sig(I)>5',/,1X,'so spot ',
     +          'search will be repeated with threshold set to ',F4.1,
     +          ' and minpix set to',I4)
          THRESHLOWSET = .TRUE.
         GOTO 2
      END IF
C
C---- Now set threshold for indexing based on using more than 100
C     spots. Never go lower than 5.
C
      IF (AUTOTHRESH) THEN
        ITHRESH = 5
        DO 62 I = 1,2
          IF (NIOVERSIG(I).GT.100) THEN
            IF (I.EQ.1) THEN
              ITHRESH = 20
            ELSE IF (I.EQ.2) THEN
              ITHRESH = 10
            END IF
            GOTO 64
          END IF
 62     CONTINUE
      END IF
c
c     save the values for the spot search, so that they can be returned
 64   fs_found = NSPOT
      fs_xmin = NREJSMALLX
      fs_xmax = NREJBIGX
      fs_ymin = NREJSMALLY
      fs_ymax = NREJBIGY
C     ..
C     .. FS_XSPLIT and FS_YSPLIT are not the same as NREJOV (which is 
C     .. determined from SEPARATION keyword)
      FS_XSPLIT = NXLIM
      FS_YSPLIT = NYLIM
      FS_CLOSE = NREJOV
      FS_USED = NWRITE
C     ..
C     .. totals...
      FS_FOUNDTOT = FS_FOUNDTOT + FS_FOUND
      FS_XMINTOT = FS_XMINTOT  + FS_XMIN 
      FS_XMAXTOT = FS_XMAXTOT + FS_XMAX
      FS_YMINTOT = FS_YMINTOT + FS_YMIN
      FS_YMAXTOT = FS_YMAXTOT + FS_YMAX
      FS_USEDTOT = FS_USEDTOT + FS_USED
      FS_CLOSETOT = FS_CLOSETOT + FS_CLOSE

      IF (DEBUG(62)) THEN
        WRITE(IOUT,FMT=6001) (NIOVERSIG(I),I=1,4)
        IF (ONLINE) WRITE(ItOUT,FMT=6001) (NIOVERSIG(I),I=1,4)
 6001   FORMAT(/,1X,'Number of reflections with I/sigI greater than',
     +          ' 20,10,5,0:',4I5)
      END IF
      IF (BRIEF) THEN
        WRITE (IBRIEF,FMT=6000) MEDWXSPOT,MEDWYSPOT,MODEX,MODEY
        WRITE (IBRIEF,FMT=6008) NSPOT,NREJSMALLX,NREJSMALLY,NREJBIGX,
     +    NREJBIGY,NREJOV,0.01*IXSEP,0.01*IYSEP,
     $     NRESOLU,NWRITE,reshigh,res2sd
      END IF
      IF (LPRNT) WRITE(IOUT,FMT=6008) NSPOT,NREJSMALLX,NREJSMALLY,
     +  NREJBIGX,NREJBIGY,NREJOV,0.01*IXSEP,0.01*IYSEP,
     $     NRESOLU,NWRITE,reshigh,res2sd
      IF (ONLINE.AND.LPRNT) WRITE(ITOUT,FMT=6008) NSPOT,NREJSMALLX,
     +    NREJSMALLY,NREJBIGX,NREJBIGY,NREJOV,0.01*IXSEP,0.01*IYSEP,
     $     NRESOLU,NWRITE,reshigh,
     $     res2sd
 6008 FORMAT (/2X,
     + 'Total number of spots found:',I4,/,2X,
     + 'Number rejected as too small on X:',I4,/,2X,
     + 'Number rejected as too small on Y:',I4,/,2X,
     + 'Number rejected as too big on X:',I4,/,2X,
     + 'Number rejected as too big on Y:',I4,/,2X,
     + 'Number too close (SEPARATION keyword):',I4,/,2X,
     $ '(currently SEPARATION ',2F6.2,')',/,2X,
     + 'Number rejected by resolution limit:',I4,/,2X,
     + 'Number stored as OK:',I4,/,2X,
     $     'highest resolution is ',F8.2,' Angstrom',/,2X,
     $     '99% have resolution less than ',F8.2,
     $     ' Angstrom')
C
C----
C
      IF (AUTOTHRESH) THEN
        WRITE(IOUT,FMT=6009) ITHRESH
        IF (ONLINE) WRITE(ITOUT,FMT=6009) ITHRESH
 6009   FORMAT(/,1X,'I/sig(I) threshold for autoindexing set to:',I3//)
      END IF
C
C---- Now output to window (if open) MOVED TO WSPOT.F 20.04.2005
C
      if(lprnt) then
c     then write out some information about the numbers of
c     spots which were found

         call dna_output_table_start('spot_finding')
         call dna_output_list_start('spots_found')
         call dna_output_integer_item('total', nspot)
         call dna_output_integer_item('rejected_small_x', nrejsmallx)
         call dna_output_integer_item('rejected_small_y', nrejsmally)
         call dna_output_integer_item('rejected_big_x', nrejbigx)
         call dna_output_integer_item('rejected_big_y', nrejbigy)
         call dna_output_integer_item('rejected_overlap', nrejov)
         call dna_output_integer_item('kept', nwrite)
         call dna_output_real_item('resolution_hi', reshigh)
         call dna_output_real_item('resolution_95', res2sd)
         call dna_output_list_end
         call dna_output_table_end

      end if

      IF (WINOPEN.AND.LHELP) THEN
        IF (.NOT.BOXOPEN2) THEN
C     
C     Create IO window
C
          IXW = 200
          IYW = 200
          LINELEN = 56
          NUMLIN = 10
          CALL MXDCIO(0,LINELEN, NUMLIN, IXW,IYW)
          BOXOPEN2 = .TRUE.
        END IF


        LINE = ' '
        WRITE(LINE,FMT=6048) THRESH
 6048   FORMAT('Threshold for spot finding set to',F6.1)
        CALL MXDWIO(LINE,3)
        LINE = ' '
        WRITE(LINE,FMT=6050) NSPOT
        CALL MXDWIO(LINE, 3)
 6050   FORMAT('Total number of spots found:',I4)
        LINE = ' '
        WRITE(LINE,FMT=6052) NREJSMALLX
        CALL MXDWIO(LINE, 2)
 6052    FORMAT('Number rejected as too small on X:',I4)
        LINE = ' '
        WRITE(LINE,FMT=6054) NREJSMALLY 
        CALL MXDWIO(LINE, 2)
 6054   FORMAT('Number rejected as too small on Y:',I4)
        LINE = ' '
        WRITE(LINE,FMT=6056) NREJBIGX
        CALL MXDWIO(LINE, 2)
 6056   FORMAT('Number rejected as too big on X:',I4)
        LINE = ' '
        WRITE(LINE,FMT=6058) NREJBIGY
        CALL MXDWIO(LINE, 2)
 6058   FORMAT('Number rejected as too big on Y:',I4)
        LINE = ' '
        WRITE(LINE,FMT=6060) 0.01*IXSEP,0.01*IYSEP,NREJOV
        CALL MXDWIO(LINE, 2)
 6060   FORMAT('Number too close (SEPARATION keyword, now',2F4.1,'):',
     +          I4)
        LINE = ' '
        WRITE(LINE,FMT=6062) NWRITE
        CALL MXDWIO(LINE, 2)
 6062   FORMAT('Number stored as OK:',I4)
        LINE = ' '
        WRITE(LINE,FMT=6064) ITHRESH
        CALL MXDWIO(LINE, 2)
 6064   FORMAT('I/sig(I) threshold for indexing set to:',I4)
C
C....Try displaying spots here
        NSPT = MIN(NWRITE,NSPOTS)
        ISTIMG(NIMAG) = NPREV + 1
        IENDIMG(NIMAG) = MIN(NPREV +NWRITE ,NSPOTS)
C
C---- Display all spots
C
        MODEDISP = 0
        CALL DSPSPT(MODEDISP)
C
      ELSE
C
C---- If not LHELP
C....Try displaying spots here
        NSPT = MIN(NWRITE,NSPOTS)
        ISTIMG(NIMAG) = NPREV + 1
        IENDIMG(NIMAG) = MIN(NPREV +NWRITE ,NSPOTS)
        MODEDISP = 0
        CALL DSPSPT(MODEDISP)
      END IF
C
C---- Skip this if online
C
      IF (ONLINE) RETURN
C
      IF (LPRNT) WRITE(IOUT,FMT=6010)
      IF (ONLINE.AND.LPRNT) WRITE(ITOUT,FMT=6010)
 6010 FORMAT (/13X,'Number of spots found in each bin')
C
C
      DO 70 J = 1,NBINR
        IF (LPRNT) WRITE(IOUT,FMT='(12X,12I4)') (ICOUNT(I,J),I=1,NBINT)
        IF (ONLINE.AND.LPRNT) WRITE(ITOUT,FMT='(12X,12I4)')
     +                                 (ICOUNT(I,J),I=1,NBINT)
   70 CONTINUE
C
C
      RETURN
      END
C $Id: pilatus_f.f,v 1.19 2021/03/30 09:17:24 andrew Exp $
      SUBROUTINE PILATUS_F(ODFILE,MODE,IERR)
C
C---- Reads header data from a Pilatus CBF file and
C     puts them into a form that FORTRAN programs can deal with. 
C
C     DEBUG(69) this routine
C
      IMPLICIT NONE
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C
C---- arguments
C
      INTEGER MODE
C
C---- Local scalars
C
      INTEGER ICOUNT,IERR,IST1,IST2,I,INDENT
      CHARACTER DETECTOR_CHARACTER
      CHARACTER DETECTOR_ID(64)
      CHARACTER ASL_INDEX(2)
      CHARACTER*200 ODFILE
      CHARACTER THIS*30,CALLED*30,COMMENT*100,STRING*4
      REAL TOL
      INTEGER OFFSET
      DOUBLE PRECISION MOSTIMEA,MOSTIMEB
      INTEGER LENSTR
      EXTERNAL LENSTR
C     
C---- The following is used for transferring values between the C stuff
C     and Fortran for CBF images
C
C&&*&& include  ../inc/cbfinc.f
C
C---- The following are used for transferring values between the C stuff
C     and Fortran for CBF images (see cbf_info.f for assignments)
C
       DOUBLE PRECISION CBF_DOUBLE(16)
       INTEGER*4 CBF_INT4(16)
       INTEGER CBF_INT(16)
       CHARACTER*24 CBF_CHAR(16)
       LOGICAL CBF_LOG(16)
       LOGICAL FULLCBF,CBFSETUP
       COMMON /CBF_PAR/ CBF_DOUBLE,CBF_INT4,CBF_INT,CBF_CHAR,CBF_LOG,
     +                  FULLCBF,CBFSETUP
C&&*&& end_include  ../inc/cbfinc.f
C&&*&& include  ../inc/condata.f
C
C $Id: condata.f,v 1.49 2021/02/11 11:30:48 andrew Exp $
C
C--- awk generated include file condata.h 
C---- START of include file condata.h 
C 
C
C     FIXSWAP     Forces reversal of normal byte-swapping choice.
C
C---- SUMPART True if two images are to be stored in memory at the
C               same time. This will be the case if post-refinement
C               (other than POSTHOC post-refinement for off-line
C               scanners) is being performed. Note that SUMPART is NOT
C               used to determine if partials should be added across
C               images (this is ADDPART)
C
C---- NEWPREF True if allowing partials over multiple images in post-
C             refinement.
C
C---- ADDPART True if partials are to be summed across images. This is
C               only appropriate for fixed origin (ie on-line)
C               scanners where the X-ray dose is identical for
C               each image.
C     Direct beam coordinates
C             These are read into XMM(3), YMM(3) where (3) is for A,B,C packs
C             Immediately on reading in, these values are transferred
C             into XCENMM, YCENMM, XCENMMIN(J,3) where J=1->MAXPAX.
C
C             If an IMAGE keyword has been given, XCENMM(1,1)=XMM(1) and
C             YCENMM(1)=YSCAL*YMM(1). If swung out, YCENMM(1,1) is updated.
C             If a BEAM keyword has not been given, XMM,YMM, XCENMM,YCENMM,
C             XCENMMIN are all set to the middle of the image.


C             Then, when reflecting input to logfile, it AGAIN sets up
C             XCENMM,YCENMM for all images using XMM,YMM, this time
C             using YSCAL to set up YCENMM, and updating YCENMM if the
C             detctor is swung out. (label 708), DO loop 710. If image
C             is "inverted", corrects XCENMM for all images.


C             XCEN,YCEN are set in "mosflm" to XCENF, YCENF plus
C             camera constants, and XCENF,YCENF are in turn set from
C             XCENMM,YCENMM. Thus XCENMM,YCENMM are what is actually
C             used to define the beam position.

C
C     LPREF   If TRUE, return to display after refinement over entire
C             image. Only active when integrating interactively. Set by
C             toggle button in Parameter window.
C

C     LOVERLAP  If TRUE, do not call the OVERLAP subroutine

C     ALLOUT  If TRUE, all reflections (whether measured or not, or
C             classified as BADSPOTS or not, will be written to the
C             output MTZ file.
C
C     NTDIG   Number of digits in image number, returned as zero if
C             there is an error in the template. Only used if TEMPLATE
C             keyword given.
C
C     TEMPLATE is TRUE if a TEMPLATE keyword has been given.
C
C     NOLP    If TRUE, do NOT apply the Lorentz Polarisation corrections
C
C     MULTIMTZ True if writing each "block" of images to a separate MTZ file
C
C     DISPMENU True if the run was started with a IMAGE keyword. Not to be
C              confused with WINOPEN which is true if the X-window display
C              is being used, but this is not necessarily starting with
C              a "IMAGE" keyword.
c     newgui - this means that we're talking through the new GUI.
c              except that we can't have it here because the prsummary 
c              subroutine, where we REALLY want it, clashes with this common
C
C     HACTIVEMASK,LACTIVEMASK,LACTIVE - only for Rigaku images which 
C     contain a compressed "active mask" (size=HACTIVEMASK bytes)
C     at the end of the image. Compression uses a modified run length encoding
C     at present (10.01.2003).
C
C     MINBATCH Minimum allowed batch number to be written to an open
C              MTZ file (MTZ library imposes that batch numbers must 
C              increase as file is written).
c
c     MERGELATT If true, prediction lists for multiple lattices will
C               be merged for output to iMosflm
C
C     NIMGSUMREF Number of images to be summed when determining spot
C                centroids for detector parameter refinement. Only
C                works for Pilatus detectors at present.
C     ..
C     .. Arrays in common /CONDATA/ ..
      REAL XCENMM,YCENMM,THFOIL,PHIBEGA,PHIENDA,RSYM,XMM,YMM,
     +     XCENMMIN,YCENMMIN
C     ..
C     .. Arrays in common /CONDATA/ ..
      INTEGER IDPACK,NFPACK,NFIRST,ICASSET
      INTEGER IPACK1A,IPACK2A,ISERAR,PICKER
      LOGICAL AVPROF,FILMPLOT,FORCEB,FORCEC,CONTROLM,CONTROLS
C
C     .. Scalars in common /CONDATA/ ..
C     ..
      REAL RMSLIM,WRMSLIM,VLIM,XMID,SEP,THICK,PTMIN,REFREJ,
     +     YSCALIN,FULLFRAC,WTIME,OVERLAPMAX
      INTEGER NPACK,NCYC,MAXNX,MAXNY,ITHRESHF,NSIG,IRFMIN,
     +        IRFINC,IXSHIFT,IYSHIFT,LIMIT,NBLOCK,INOGEN,NFGEN,MINREF,
     +        ISERADD,NSEG,NSYM,NSYMP,NRUN,NSERTOT,IWAVE,ISWUNG,
     $        IBEAMMU,ITILT,ITWIST,IPIX,IRMINXY,ICUT,IPRCUT,ILIMIT
      INTEGER IMAT,ICELL,IUMAT,LSYMM,IDIST,IBEAM,ISCAN,NLINE,NRLINE,
     +     NTLINE,NTOTLINE,ISTARTP,IRAST,INEWMAT,ISEP,NSAVELINE,IPTIME,
     +     ISTRT,IANGLE,IBACKS,IPOLAR,IDIVH,IDIVV,IGAIN,IBLOCK,
     +     IHKLOUT,IGENF,INRES,NTDIG,DELAY,IMULTI,IMISS,IMISSMAT,
     +     IIDENT,HACTIVEMASK,ITWOTHETA,MINBATCH,ILABVIEW,INVVIEW,
     $     IINVVIEW,IHKLDIR,IBGSIG,NRLEFT,WAIT,IPARTITION,ISIGSET,
     +     NSIGSAVE,ITOL,NIMGSUMREF,IBGFRAC,THISIMG,CHUNK,ICHUNK,
     $     IPTMINSET,IYSCAL
      LOGICAL FINDCC,READCC,NOFID,INTERPOL,CONVOL,NOMEAS,
     +     USEPAR,USEOVR,SUMPART,USEBOX,POSTREF,ADDPART,
     +     FIXED,POWDER,RWEIGHT,NOREF,MULTISEG,FIXSWAP,POSTHOC,
     +     LPREF,LPINTG,DISPMENU,PRMODE,PRCELL,TEMPLATE,
     +     LOVERLAP,ALLOUT,NOLP,NEWPREF,NOBACK,MOSEST,BLKEST,NUSPOT,
     $     NUBACK,NUFIND,HARVESTREADY,HEADINFO,MULTIMTZ,ANDREW, 
     +     spostref,newgui,LACTIVEMASK,USERSPOT,HEADONLY,PHIONLY,
     $     NO_XML,TESTSOCK,PICKLOG,EXPLICIT_CELL,LSIMULATE,
     $     LONGERNAME,TIMER,MERGELATT,NULLPIXTEST,KEEPNULLPIX,CCHUNK,
     +     INVXFORCEREAD
C     ..
C real arrays, then scalars, integer arrays, scalars, logicals
      COMMON /CONDATA/
     $     XCENMM(MAXPAX,3),
     +     YCENMM(MAXPAX,3), THFOIL(3),PHIBEGA(MAXPAX),
     $     PHIENDA(MAXPAX),RSYM(4,4,96),XMM(3),YMM(3),
     $     XCENMMIN(MAXPAX),YCENMMIN(MAXPAX),
     $     RMSLIM,WRMSLIM,VLIM,XMID,SEP,THICK,PTMIN,REFREJ,
     +     YSCALIN,FULLFRAC,WTIME,OVERLAPMAX,
     $     IDPACK(MAXPAX),NFPACK(MAXPAX),NFIRST(MAXPAX),
     +     ICASSET(MAXPAX),IPACK1A(50),
     +     IPACK2A(50),ISERAR(50),PICKER(4),
     $     AVPROF(MAXPAX),FILMPLOT(MAXPAX),FORCEB(MAXPAX),
     +     FORCEC(MAXPAX),
     $     NPACK,NCYC,MAXNX,MAXNY,ITHRESHF,NSIG,IRFMIN,
     +     IRFINC,IXSHIFT,IYSHIFT,LIMIT,NBLOCK,INOGEN,NFGEN,MINREF,
     +     ISERADD,NSEG,NSYM,NSYMP,NRUN,NSERTOT,IWAVE,ISWUNG,
     $     IBEAMMU,ITILT,ITWIST,IPIX,IRMINXY,ICUT,IPRCUT,ILIMIT,
     $     IMAT,ICELL,IUMAT,LSYMM,IDIST,IBEAM,ISCAN,NLINE,NRLINE,
     +     NTLINE,NTOTLINE,ISTARTP,IRAST,INEWMAT,ISEP,NSAVELINE,
     +     IPTIME,ISTRT,IANGLE,IBACKS,IPOLAR,IDIVH,IDIVV,IGAIN,IBLOCK,
     +     IHKLOUT,IGENF,INRES,NTDIG,DELAY,IMULTI,IMISS,IMISSMAT,
     +     IIDENT,HACTIVEMASK,ITWOTHETA,MINBATCH,ILABVIEW,INVVIEW,
     $     IINVVIEW,IHKLDIR,IBGSIG,NRLEFT,WAIT,IYSCAL,
     +     FINDCC,READCC,NOFID,
     +     INTERPOL,CONVOL,NOMEAS,USEPAR,USEOVR,SUMPART,USEBOX,
     +     POSTREF,spostref, ADDPART,FIXED,POWDER,RWEIGHT,NOREF,
     +     MULTISEG,FIXSWAP,POSTHOC,LPREF,LPINTG,DISPMENU,PRMODE,
     $     PRCELL,TEMPLATE,
     +     LOVERLAP,ALLOUT,NOLP,NEWPREF,NOBACK,MOSEST,BLKEST,NUSPOT,
     $     NUBACK,NUFIND,HARVESTREADY,HEADINFO,MULTIMTZ,ANDREW,
     $     newgui,LACTIVEMASK,USERSPOT,HEADONLY,PHIONLY,NO_XML,
     $     TESTSOCK,PICKLOG,EXPLICIT_CELL,LSIMULATE,
     $     LONGERNAME,TIMER,CONTROLM,CONTROLS,IPARTITION,ISIGSET,
     +     NSIGSAVE,ITOL,MERGELATT,NIMGSUMREF,NULLPIXTEST,
     +     KEEPNULLPIX,IBGFRAC,THISIMG,CHUNK,ICHUNK,CCHUNK,IPTMINSET,
     +     INVXFORCEREAD


C&&*&& end_include  ../inc/condata.f
C&&*&& include  ../inc/debug.f
C
C $Id: debug.f,v 1.8 2021/06/03 09:41:34 andrew Exp $
C
C--- awk generated include file  debug.h
C---- START of include file debug.h
C
C
C
C     .. Arrays in common /DEBUG/ ..
      REAL XWARN
      INTEGER NDEBUG,IWARN,IARRDUMP
      LOGICAL DEBUG,LPRINT,DUMP,WARN
C
C     .. Scalars in common /DEBUG/ ..
      REAL BGRLIM
      INTEGER NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,IERRLEVEL
      LOGICAL SPOT
      CHARACTER MESSAGE*512
C     
C     ..
C     .. Common Block /DEBUG/..
      COMMON /DEBUG/XWARN(MAXIWARN,100),BGRLIM,NDEBUG(200),
     +       IWARN(MAXIWARN,100),
     $       NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,DEBUG(200),LPRINT(20),
     +       DUMP(30),WARN(100),SPOT,IARRDUMP(30),IERRLEVEL

      COMMON /CDEBUG/ MESSAGE
C     ..
C
C&&*&& end_include  ../inc/debug.f
C&&*&& include  ../inc/detector.f
C
C $Id: detector.f,v 1.3 2007/11/13 17:21:01 harry Exp $
C
C
C---- START of include file detector.f
C
      REAL RMINIP,RMAXIP,XMAXIP,YMAXIP,XLIMIT,RSCANIP
      COMMON /DETECTOR/RMINIP,RMAXIP,XMAXIP,YMAXIP,XLIMIT,
     $     RSCANIP
