C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C&&*&& include  ../inc/virbat.f
C
C $Id: virbat.f,v 1.2 2003/11/28 12:34:49 harry Exp $
C
C
C----  include file header  for virtual batches in post-refinement
C
       INTEGER NIVB,NVIRBAT,NADDMISSET,IVIRBAT
       LOGICAL NUPR_INT
       COMMON /VIRBAT/ NIVB,NVIRBAT,NADDMISSET,
     +                 IVIRBAT,NUPR_INT
C&&*&& end_include  ../inc/virbat.f
C     
      real error
      common /fudge/ error(3)
      PARAMETER (TOL = 1.0D-3)
C     ..
      SAVE
C     .. Data statements ..
      DATA NIMAG/0/,WARNED/.FALSE./,FIRSTPR/.TRUE./,
     $     LHKL/MREF*.FALSE./
      CALLEDFROM = 'POSTREFL'
C
C---- Special case. If the first images of the second or subsequent segment
C     of a multisegment run are being re-integrated because of a large shift
C     then NIMAG, IDLAST and PHIIM need to be reset.
C
      IF (IRECG.EQ.-9999) THEN
        J = ISPOT(1)
        NIMAG = NIMAG - J
        NDONE = NDONE - J
        IDLAST = -999
        ISEGLAST = -999
        DO 5 I = 1,NADD-J
          PHIIM(I) = PHIIM(I+J)
 5      CONTINUE
        IF (DEBUG(37)) THEN
            WRITE(IOUT,FMT=6005) NIMAG,ISEG,J,(PHIIM(I),I=1,NADD)
            IF (ONLINE) WRITE(ITOUT,FMT=6005) NIMAG,ISEG,J,
     +                                (PHIIM(I),I=1,NADD)
 6005       FORMAT(1X,'Resetting NIMAG in POSTREFL to',I3,' and ',
     +                 'IDLAST to -999: ISEG = ',I3,/,1X,'J=',I2,
     +                 ' Reset PHIIM values:',/,(1X,10F8.2))
        END IF
        RETURN
      END IF
C     
C---- initializations necessary every frame
C     
      IF ((IRECG.EQ.0).OR.(IRECG.EQ.-1)) THEN
         NDBG = 0         
         NS = PRNS  
         CELLSHIFT = 0.0
         NREJSD = 0
         NREJF1 = 0
         IF (DEBUG(37)) THEN
            WRITE(IOUT,FMT=6004) IRECG,FRACMIN,FRACMAX,NS
            IF (ONLINE) WRITE(ITOUT,FMT=6004) IRECG,FRACMIN,FRACMAX,NS
 6004       FORMAT(1X,'Initialising variables in POSTREFL, IRECG=',I4,
     +           ' Fracmin is',F6.3,' Fracmax is',F6.3,'  NS=',I4)
         END IF
C     
C---- Initialisation of NIMAG, and array F() (stores I ratio's)
C     
         IF (IRECG.EQ.-1) THEN
            NIMAG = 0
            NDONE = 0
            IDLAST = -999
            ISEGLAST = -999
CAL            IF(.NOT.NEWPREF)THEN
               DO 1 I = 1,MREF
                  F(I) = 0.0
 1             CONTINUE
CAL            END IF
            DO 7 I = 1,NIMAX
               ISTARTA(I) = 0
               PHIIM(I) = -999.0
 7          CONTINUE
            DO 3 I = 1, 6+NIMAX*3+2
              PARM(I) = 0.0
 3          CONTINUE
            NR = 0
            NRSEG = 0
         END IF
C     
C---- Store starting missets
C     
         IF (FIRSTPR) THEN
            FIRSTPR = .FALSE.
            DO 2 I = 1,3
               SDELPHI(I) = DELPHI(I)
 2          CONTINUE
         END IF
C     
C---- Pass print option from IPRINTP in /POSTCHK/ to IPRINT in /IDXALL/
C     
         IPRINT = IPRINTP
         NRL = 0
C     
C---- Save initial missets and cell
C     
         DO 4 I = 1,6
            SRCELL(I) = RCELL(I)
 4       CONTINUE
C     
C---- Initialise local arrays
C     
         DO 6 I = 1,NRLMAX
            IHL(I) = 0
            IKL(I) = 0
            ILL(I) = 0
            FL(I) = 0.0
            PHIL(I) = -999.0
            WWL(I) = 0.0
            INT1(I) = 0
            INT2(I) = 0
            BKGRATIO(I) = 0.0
 6       CONTINUE
C     
         ISYNL = .FALSE.
         IF (ISYN.EQ.1) ISYNL = .TRUE.
C     
C---- Reflection passed from SPROCESS
C     
      ELSE IF (IRECG.GT.0) THEN  
C     
C     
C---- See if this is the second measurement of a pair, meaning that it
C     is the summed partial
C     
         IF (IRECG.EQ.LASTREC) THEN
C
C---- Note that in original style post-refinement, the intensity of
C     the first half of the partial is stored in ISAVE and the full
C     intensity in ISPOT(1), while with NEWPREF the two halves of the
C     intensity are in ISPOT(1) and ISPOT(2).
C
            BKGRAT = 0.0
            IF (BKGSAVE.NE.0) BKGRAT = (BKGSP-2*IDIVIDE-BKGSAVE)/BKGSAVE
C---- Don't attempt background checks for NEWPREF yet
CAL            IF (NEWPREF.AND.(BKGSP-2*IDIVIDE-BKGSAVE.NE.0)) 
CAL     +           BKGRAT = BKGSAVE/(BKGSP-2*IDIVIDE-BKGSAVE)
C
            F1 = 0.0
            IF(NEWPREF)THEN
              IF ((ISPOT(1)+ISPOT(2)).GT.0)
     $         F1 = FLOAT(ISPOT(1))/(FLOAT(ISPOT(1))+ FLOAT(ISPOT(2)))
            ELSE
              IF (ISPOT(1).GT.0) F1 = FLOAT(ISAVE)/FLOAT(ISPOT(1))
            END IF
C     
C     
C---- Get indices for this reflection
C     
C     ***************
            CALL GETHKL(IRECG,IHKL)
C     ***************
C     
C---- Apply sigma tests
C
            REJSIG = .FALSE.     
            IF (NEWPREF) THEN
C
C---- sometimes happens with R-Axis images...
              IF(ISDBSI(1).GT.32767.OR.ISDBSI(2).GT.32767)THEN
                ISDTOT = MIN(32767,
     $               INT(SQRT(FLOAT(ISDBSI(1))**2 + 
     $               FLOAT(ISDBSI(2))**2)))
                REJSIG = .TRUE.
              ELSE
                ISDTOT = INT(SQRT(FLOAT(ISDBSI(1))**2 + 
     $               FLOAT(ISDBSI(2))**2))
C
C---- Change the test so that the two individual parts are tested
C     against SDFAC rather than the first part and the sum. Required 
C     because if the second part is essentially zero it contains no
C     information. Both parts have to be OK. AGWL 24/2/2012
C
                REJSIG = ( (ISPOT(1).LT.SDFAC*ISDBSI(1)) .OR.
     +                     (ISPOT(2).LT.SDFAC*ISDBSI(2)))
CAL old code     +               ((ISPOT(1)+ISPOT(2)).LT.SDFAC*ISDTOT) )
              ENDIF
            ELSE
               REJSIG = ( (ISPOT(1).LT.SDFAC*ISDBSI(1)) .OR.            
     $                    (ISAVE.LT.SDFAC*ISDSAVE) )
            END IF
            IF (REJSIG) THEN
               NREJSD = NREJSD + 1
               IF (DEBUG(37).AND.(NDBG.LT.NDEBUG(37)))THEN
                  WRITE(IOUT,FMT=6007)IRECG,(IHKL(K),K=1,3),F1,NRL,
     $                 PHIPOST
                  IF (ONLINE) WRITE(ITOUT,FMT=6007) IRECG,
     +                 (IHKL(K),K=1,3),F1,NRL,PHIPOST
 6007             FORMAT(1X,'Postref has rejected reflection with ',
     $                 'IRECG = ',I5,' indices',3I4,' frac',F6.3,
     $                 '  index',I5,', Phipost',F7.2,
     $                 ' failed sigma test!')
                  NDBG = NDBG + 1
               END IF
               RETURN
            END IF
C     
C---- Reject for output if ratio too small
C     
            IF (F1.LT.FRACMIN.OR.F1.GT.FRACMAX) THEN
               NREJF1 = NREJF1 + 1
               IF (DEBUG(37).AND.(NDBG.LT.NDEBUG(37)))THEN
                  WRITE(IOUT,FMT=6008)IRECG,(IHKL(K),K=1,3),F1,NRL,
     $                 PHIPOST,fracmin,fracmax
                  IF (ONLINE) WRITE(ITOUT,FMT=6008) IRECG,
     +                 (IHKL(K),K=1,3),F1,NRL,PHIPOST,fracmin,fracmax
 6008             FORMAT(1X,'Postref has rejected reflection with ',
     $                 'IRECG = ',I5,' indices',3I4,' fraction',F6.3,
     $                 ' local array index is ',I5,', Phipost is ',F7.2,
     $                 ' RATIO TOO SMALL! (',F5.3,1X,F5.3,')')
                  NDBG = NDBG + 1
               END IF
               RETURN
            END IF
C
C---- increment counter for accepted spots
C
            NRL = NRL + 1
C
            IF (DEBUG(37).AND.(NDBG.LT.NDEBUG(37)))THEN
               WRITE(IOUT,FMT=6006) IRECG,(IHKL(K),K=1,3),F1,NRL,
     $              PHIPOST,PHIOFFSET(IRECG)
               IF (ONLINE) WRITE(ITOUT,FMT=6006) IRECG,
     +              (IHKL(K),K=1,3),F1,NRL,PHIPOST,PHIOFFSET(IRECG)
 6006          FORMAT(1x,'Postref storing reflection with IRECG=',I5,
     +              ' indices',3I4,' fraction',F6.3,' local array',
     $              ' index is ',I5,', Phipost is ',F7.2,
     +              ' phioffset',f6.2)
                  NDBG = NDBG + 1
            END IF
            IF (NRL.GT.NRLMAX) THEN
               NRL = NRL - 1
               IF (.NOT.WARNED) THEN
                  WRITE(IOUT,FMT=6010) NRLMAX
                  IF (ONLINE) WRITE(ITOUT,FMT=6010) NRLMAX
                  IF (BRIEF) WRITE(IBRIEF,FMT=6010) NRLMAX
 6010             FORMAT(//1X,'** WARNING **',/,1X,'Number of ',
     +                 'reflections available for post-refinement ',
     +                 'exceeds the total number',
     +                 /,1X,'that can be stored (',I6,').')
               END IF
               WARNED = .TRUE.
               RETURN
            END IF
C     
            IHL(NRL) = IHKL(1)
            IKL(NRL) = IHKL(2)
            ILL(NRL) = IHKL(3)
            FL(NRL) = F1
            WWL(NRL) = 1.0
            IF(NEWPREF)THEN
               PHIL(NRL) = PHIPOST
C
C---- Assign phi offset for this reflection
C
               PHIOFFL(NRL) = PHIOFFSET(IRECG)
            ELSE
               PHIL(NRL) = PHIEND
               INT1(NRL) = ISAVE
               INT2(NRL) = ISPOT(1)
            END IF
            BKGRATIO(NRL) = BKGRAT
         ELSE
            IF(.NOT.NEWPREF)THEN
               LASTREC = IRECG
               ISAVE = ISPOT(1)
               ISDSAVE = ISDBSI(1)
C     
C---- Must subtract scanner adc offset from background
C     
               BKGSAVE = BKGSP - IDIVIDE
            END IF
         END IF
C
C     ***********************************************************
C---- All reflections read for this image, prepare for refinement
C     ***********************************************************
C     
      ELSE IF (IRECG.EQ.-999) THEN
C 
C     
C---- Set the pack number for current image
C     
         IDPACK = ISPOT(1)
         IPACK = ISPOT(2)
         IF (DEBUG(37)) THEN
           WRITE(IOUT,FMT=6120) IPACK
           IF (ONLINE) WRITE(ITOUT,FMT=6120) IPACK
 6120      FORMAT(//,1X,'In POSTREFL for pack',I4)
         END IF

C     
C---- Now move reflections over from local arrays into appropriate
C     part of global arrays used to store data from several pairs
C     of images. 
C     
C---- Increment NIMAG only if this is a new pack (refinement may be
C     repeated for first NADD-1 images if there has been a large shift)
C     
 11      CONTINUE
         IF ((IDPACK.NE.IDLAST).OR.(ISEG.NE.ISEGLAST)) THEN
           NIMAG = NIMAG + 1
           IF (DEBUG(37).OR.DEBUG(1)) THEN
             WRITE(IOUT,FMT=6121) NIMAG,NADD
             IF (ONLINE) WRITE(ITOUT,FMT=6121) NIMAG,NADD
 6121        FORMAT(1X,'In POSTREFL, NIMAG has been incremented to',I4,
     +               '  NADD=',I4)
           END IF
         END IF
C     
C---- Set max number of reflections per image (NRMAX) to store in global array
C     (MREF is set in parameter common block.)
C
C---- *** If using POSTREF MULTI and doing an integration (with cell fixed)
C         must ensure a suitable value for NADD is worked out.
C
         NRMAX = MREF/NADD
         NRMAX = MIN(NRMAX,NRLMAX)
C     
C---- Assign pointer for slot in global array where reflections assigned
C     to current image will go. NSLOT runs from 1 to NADD. NPOINT is
C     the first location in the big array for this image.
C     
         NSLOT = NIMAG - ((NIMAG-1)/NADD)*NADD
         NPOINT = NRMAX*(NSLOT-1) + 1
C
C---- If NEWPREF, clear all entries from this slot in global array
C     and set pointer to the first free location in this slot (ISTARTA)
C     and the phi value for this slot.
C
         IF (NEWPREF) THEN
           DO 60 I = NPOINT, NPOINT+NRMAX-1
             F(I) = 0.0
 60        CONTINUE
           ISTARTA(NSLOT) = NPOINT
           PHISLOT(NSLOT) = PHIBEG
           IDSLOT(NSLOT) = IPACK
         END IF
C
C---- If repeating an image, reset all the pointers to the saved values.
C
         IF (NEWPREF.AND.(IDPACK.EQ.IDLAST).AND.(ISEG.EQ.ISEGLAST))THEN
           IF (DEBUG(37)) THEN
             WRITE(IOUT,FMT=6040) (ISTARTA(I),ISTSAVE(I),I=1,NADD)
             IF (ONLINE) WRITE(ITOUT,FMT=6040) 
     +              (ISTARTA(I),ISTSAVE(I),I=1,NADD)
 6040        FORMAT(1X,'Because this is a repeat restore pointers',
     +               ' to values for',
     +               ' previous run of this image, new/orig values',
     +               /,(1X,20I6/))
           END IF
           DO 61 I = 1,NADD
             ISTARTA(I) = ISTSAVE(I)
 61        CONTINUE
         ELSE
C
C---- Save all current pointers for the NADD slots, so that they can
C     be restored in the event of repeating an image after a big shift
C     in missets
C
           DO 62 I = 1, NADD
             ISTSAVE(I) = ISTARTA(I)
 62        CONTINUE
         END IF
C
         ISKP = NRL/NRMAX + 1
         IF (ISKP.NE.1) THEN
            WRITE(IOUT,FMT=6012) ISKP
            IF (ONLINE) WRITE(ITOUT,FMT=6012) ISKP
            IF (BRIEF) WRITE(IBRIEF,FMT=6012) ISKP
 6012       FORMAT(//1X,'** WARNING **',/,1X,'Too many reflections ',
     +           'available for post-refinement',/,1X,
     +           'Only one in every',I2,' will be used')
         END IF
C
         NRADD = 0
         NDEL = 0
         IF (DEBUG(37)) THEN
            IF (ONLINE) WRITE(ITOUT,6013)NIMAG,NADD,NADDMISSET,
     +              NEWPREF,NRL,
     $              NRMAX,NSLOT,NPOINT,ISKP,(ISTSAVE(I),I=1,NADD)
            WRITE(IOUT,6013)NIMAG,NADD,NADDMISSET,NEWPREF,NRL,
     $           NRMAX,NSLOT,NPOINT,ISKP,(ISTSAVE(I),I=1,NADD)
 6013       FORMAT(1X,'NIMAG=',I4,' NADD=',I3,' NADDMISSET=',I3,
     +            ' LOGICAL NEWPREF is ',L1,/,
     $           1X,'NRL (no this image)',I5,' NRMAX',I5,' NSLOT ',
     +           '(slot number)',I3,'  NPOINT (pointer into global',
     +           ' array)',I6,'   ISKIP',I2,/,1X,'Pointers into',
     +           ' the slots (not the start but where the next ',
     +           'reflection will be stored):',(/,1X,10I7))
         END IF
C
         DO 12 I = 1,NRMAX
            K = 1 + (I-1)*ISKP
C     
C---- determine J differently for new and  old-style postrefinement
C     
            IF (NEWPREF) THEN
C
C---- work out which slot this reflection has to go in.
C
               PHIREFL = PHIL(K)
C
C---- Check for end of reflections
C
               IF (PHIREFL.LT.-990) GOTO 17
C
               DO 13 M = 1,NADD
                 IF (ABS(PHIREFL-PHISLOT(M)).LT.0.005) THEN
                   KSLOT = M
                   GOTO 15
                 END IF
 13            CONTINUE
C
C---- Bin not found
C              
               IF (DEBUG(37)) THEN
                 WRITE(IOUT,FMT=6020) IHL(K),IKL(K),ILL(K),
     +                     PHIREFL,(PHISLOT(M),M=1,NADD)
                 IF (ONLINE) WRITE(IOUT,FMT=6020)IHL(K),IKL(K),ILL(K),
     +                      PHIREFL,(PHISLOT(M),M=1,NADD)
 6020            FORMAT(1X,'Reflection',3I4,' phi',F8.2,' cannot find',
     +                  ' correct slot, phislot values',12F8.2)
               END IF
               GOTO 12
C
C---- Need to check if this slot is full
C
 15            IF (ISTARTA(KSLOT).GT.KSLOT*NRMAX) THEN
                 IF (DEBUG(37)) THEN
                   WRITE(IOUT,FMT=6021) KSLOT,K,ISTARTA(KSLOT)
                   IF (ONLINE) WRITE(IOUT,FMT=6020) KSLOT,K,
     +                ISTARTA(KSLOT)
 6021              FORMAT(1X,'Slot ',I3,' is now full for reflection',
     +               I5,' ISTARTA is',I6)
                 END IF
                 GOTO 12
               END IF
C
C---- Assign location pointer for this slot
C
             J = ISTARTA(KSLOT)
               ISTARTA(KSLOT) = ISTARTA(KSLOT) + 1
               IH(J) = IHL(K)
               IK(J) = IKL(K)
               IL(J) = ILL(K)
               F(J) = FL(K)
               PHI(J) = PHIL(K)
               PHIOFF(J) = PHIOFFL(K)
CAL               write(6,*) 'j,k,phioffl',j,k,phioffl(k)
               WW(J) = WWL(K)
               LHKL(J) = .TRUE.
            ELSE
               J = NPOINT + I - 1
C     
C---- NDEL number of deleted reflections previously in list
C     
               IF (F(J).GT.0.0) NDEL = NDEL + 1
               IH(J) = IHL(K)
               IK(J) = IKL(K)
               IL(J) = ILL(K)
               F(J) = FL(K)
C     
C---- NRADD number of new reflections in list from this image
C     
               IF (F(J).GT.0.0) NRADD = NRADD + 1
               PHI(J) = PHIL(K)
               WW(J) = WWL(K)
            END IF               
C
C---- End of loop over reflections 
C
 12      CONTINUE
C
 17      IF (NEWPREF) THEN
C
C---- Count the number of reflections stored in each slot, NREFSTOR,
C     where NREFSTOR(1) is current image, (2) is previous image etc
C     NR counts the number of reflections to be used in refinement this time,
C     NRSTORE stores the total number stored.
C
            NR = 0
            NRSTORE = 0
            DO 70 I = 1,NADD
C
C---- Start with the slot for current image
C
              J = NSLOT - I + 1
              IF (J.LT.1) J = J + NADD
              NREFSTOR(I) = 0
C---- Must trap empty slots at start
C
              IF (ISTARTA(J).NE.0) 
     +              NREFSTOR(I) = ISTARTA(J) - (NRMAX*(J-1)+1)
              NRSTORE = NRSTORE + NREFSTOR(I)
 70         CONTINUE
C
C---- Now decide how many virtual batches there will be. Normally there
C     will be NVIRBAT images in each virtual batch (NVIRBAT is assigned
C     in mosflm.f at the start of a run). However, we need to enforce
C     a new virtual batch when we come to an image from a different segment
C     (ie not contiguous in PHI) as when refining cell parameters.
C     NUMB(NBAT) gives the number of images in virtual batch number NBAT
C     CONTIG(NBAT) is true if virtual batch NBAT contains images that are
C     contiguous in phi with batch NBAT-1.
C     (Note that batch 1 is the latest image to be worked with (not the
C     first image in the series)).
C
            NBAT = 1
            NUMI = 0
            DO 76 I = 1,NADD
C
C---- Start with the slot for current image
C
              IF (I.GT.NIMAG) GOTO 76
              J = NSLOT - I + 1
C
C---- In a cell refinement (POSTREF SEGMENT) J will never be
C     LT 1 and JP1 will never be > NADD, but in an integration run
C     the global array is used as a circular buffer, each successive 
C     image is stored in the next location, going back to the start 
C     when the end of the array is encountered.
C
              IF (J.LT.1) J = J + NADD
              JP1 = J + 1
              IF (JP1.GT.NADD) JP1 = JP1 - NADD
              IF ((NIMAG.GT.1).AND.(I.GE.2)) THEN
                IF ((ABS(PHISLOT(J)-PHISLOT(JP1)) - 
     +             ABS(PHIEND-PHIBEG)).GT. 0.009) THEN
C
C---- Slots are not contiguous in phi, force a new batch
C
                  IF (DEBUG(37)) THEN
                    WRITE (IOUT,FMT=6140) I,J,JP1,PHISLOT(J),
     +                                    PHISLOT(JP1)
                    IF (ONLINE) WRITE (ITOUT,FMT=6140) I,J,JP1,
     +                 PHISLOT(J),PHISLOT(JP1) 
 6140               FORMAT(1X,'Forcing new batch at I=',I3,' slot',I4,
     +                    ' previous slot',I3,' phi values:',2F9.3)
                  END IF
                  CONTIG(NBAT) = .FALSE.
                  NBAT = NBAT + 1
                  NUMB(NBAT) = 1
                  NUMI = 1
                  CONTIG(NBAT) = .TRUE.
                  GOTO 76
                END IF
              END IF
              NUMI = NUMI + 1
              CONTIG(NBAT) = .TRUE.
              IF (NUMI.GT.NVIRBAT) THEN
                NUMB(NBAT) = NVIRBAT
                NBAT = NBAT + 1
                NUMB(NBAT) = 1
                NUMI = 1
                CONTIG(NBAT) = .TRUE.
              ELSE
                NUMB(NBAT) = NUMI
              END IF
 76         CONTINUE
C
            IF (DEBUG(37)) THEN
              WRITE(IOUT,FMT=6130) NBAT,(NUMB(I),I=1,NBAT)
              IF (ONLINE) WRITE(ITOUT,FMT=6130) NBAT,
     +                                       (NUMB(I),I=1,NBAT)
 6130         FORMAT(1X,'Number of batches is:',I3,' Numbers of',
     +               ' images in each batch:',/,(1X,10I4))
            END IF
C
C---- Set up an array to say which segment each virtual batch belongs to
C     using the CONTIG flags.
C     ISEGBAT(batch_number) = segment number for that batch
C     GOODSEGBAT(segment_number) is TRUE if there is a refineable batch in
C     segment segment_number
C
            NSB = 1
            DO 75 I = NBAT,1,-1
              IF (.NOT.CONTIG(I)) NSB = NSB + 1
              ISEGBAT(I) = NSB
 75         CONTINUE
C
C---- Now map images onto "virtual batches" which may correspond to one
C     or several images. NVIRBAT is set up at start of run. Count number
C     of reflections in each virtual batch, decide which are to be refined,
C     and count number of virtual batches to be refined (NADDL)
C
            K = 0
            NADDL = 0
            NTOTIMG = 0
            ISB = ISEGBAT(1)
            DO 74 I = 1,NBAT
              NREFVBAT(I) = 0
              NUMI = NUMB(I)
              DO 72 J = 1,NUMI
                K = K + 1
                NREFVBAT(I) = NREFVBAT(I) + NREFSTOR(K)
 72           CONTINUE
              NTOTIMG = NTOTIMG + NUMI
              SAMESEG = (ISEGBAT(I).EQ.ISB)
C
C---- Now decide which images are going to be used. If doing a postref segment
C     and not all images have been processed (NIMAG<NADD) only want to
C     use the last NADDMISSET images for refining missetting angles.
C     Remember that USEBAT(1) is for current virtual batch, USEBAT(2) is
C     previous virtual batch etc
C     Only allow batches that are in the same segment as batch 1 
C     (ie that for the current image)
C
              IF (NIMAG.LT.NADD) THEN
                IF (NIMAG.LE.NADDMISSET) THEN
                  USEBAT(I) = ((NREFVBAT(I).GT.NPRMIN).AND.SAMESEG)
                ELSE
                  USEBAT(I) = ((NREFVBAT(I).GT.NPRMIN).AND.
     +                         (NTOTIMG.LE.NADDMISSET).AND.SAMESEG)
                END IF
              ELSE
                USEBAT(I) = (NREFVBAT(I).GT.NPRMIN)
              END IF
C
              IF (USEBAT(I)) THEN
                NADDL = NADDL + 1
                NR = NR + NREFVBAT(I)
              END IF
 74         CONTINUE
C
C---- Now see if there are any useable batches in each segment
C              
            DO 77 I = 1,NSEGMAXPR
              GOODSEG(I) = .FALSE.
 77         CONTINUE

            DO 78 I = 1,NBAT
              IF (USEBAT(I)) GOODSEG(ISEGBAT(I)) = .TRUE.
 78         CONTINUE
C
C---- Now need to assign the last useable batch in each segment
C     (remember this is inverse order, in terms of phi, this would
C      the first useable batch)
C     LASTBATCH(segment_number) = batch_number
C
            DO 80 I = 1,NBAT
              ISB = ISEGBAT(I)
              IF (USEBAT(I)) LASTBATCH(ISB) = I
 80         CONTINUE
            IF (DEBUG(37)) THEN
              WRITE(IOUT,FMT=6132) NSB,(GOODSEG(I),I=1,NSB)
              WRITE(IOUT,FMT=6134) (ISEGBAT(I),I=1,NBAT)
              WRITE(IOUT,FMT=6136) (I,LASTBATCH(I),I=1,NSB)
              IF (ONLINE) THEN
                WRITE(ITOUT,FMT=6132) NSB,(GOODSEG(I),I=1,NSB)
                WRITE(ITOUT,FMT=6134) (ISEGBAT(I),I=1,NBAT)
                WRITE(ITOUT,FMT=6136) (I,LASTBATCH(I),I=1,NSB)
              END IF
 6132         FORMAT(1X,'Number of segments based on CONTIG flags',
     +             I3,/,1X,'Flags for useable batches in each segment',
     +             30L2)
 6134         FORMAT(1X,'Segment number for the different batches:',/,
     +              (1X,20I4))
 6136         FORMAT(1X,'Last useable batch in each segment:',/,
     +               (1X,5('segment',I2,' batch',I4,3X)))
            END IF
C
C---- Now set up the pointers between images and refined parameters sets
C     (a set is normally PSIY,PSIZ). Note that if an image belongs to a
C     virtual batch that is not going to be refined, its pointer is set to
C     the first virtual batch that IS going to be refined.
C
C     IPARPOINT(image_number)=parameter_set_number
C
C     where image_number is 1 for current image, 2 for previous image etc.
C     This array is used in REFRT1 to assign a particular reflection to
C     a particular parameter set based on its phi value and the phi values
C     stored in PHIIM (which has current image in element 1, previous in
C     element 2 etc).
C
            K = 0
            NIMGUSE = 0
            NPAR = 1
C
C---- If NADD is not a multiple of NVIRBAT, then when the number
C     of images is NVIRBAT+1, NVIRBAT+2 etc, NBAT may still be 1.
C     To include reflections from images NVIRBAT+1, NVIRBAT+2 etc
C     we must go over this DO 84 loop one extra time, hence limit
C     is NBAT+1 rather than NBAT
C
            DO 84 I = 1,NBAT+1
              IF (I.GT.1) THEN
                IF (USEBAT(I-1)) NPAR = NPAR + 1
                NPAR = MIN(NPAR,NADDL)
              END IF
              IF (I.LE.NBAT) THEN
                NUMI = NUMB(I)
              ELSE
                NUMI = NVIRBAT
              END IF
              DO 82 J = 1,NUMI
                K = K + 1
                IF (K.GT.NIMAG) GOTO 82
                IF (K.GT.NADD) GOTO 82
                IF ((K.GT.NADDMISSET).AND.(NIMAG.LT.NADD)) GOTO 82
C
C---- Need to be careful about assignment of first (and 2nd..) images.
C     Normally they can be assigned to the first parameter to be refined
C     even if they are actually in a different batch (which may not yet
C     have enough reflections to be refined). However this must not be
C     done if the next batch is not contiguous in phi with the first
C     batch (set by logical CONTIG). In this case, IPARPOINT is set
C     to -1 to flag that these reflections CANNOT be used.
C     CONTIG(I) is TRUE if batch I is contiguous in phi with batch I+1
C
C     There are two distinct cases here if there is more than one segment
C     of data. The first case is that described above, where there are not
C     enough reflections in the current batch to warrant refinement, but 
C     there are enough reflections in a previous batch, in which case assign
C     the pointer to the parameters of this previous batch.
C
C     The second case is where there are more than one segment, and the
C     first one (or more) batches do not have enough reflections for 
C     refinement. When the current batch in this second segment does have
C     enough reflections for refinement, and one is working through the 
C     batches (remember they are stored with the current batch first, 
C     previous second etc) and get to the batches that do not have enough 
C     reflections, they need to be assigned to an EARLIER batch in that
C     segment (ie later in phi) that does have enough refections.
C
                IF (.NOT.USEBAT(I)) THEN
C
C---- Is this past the last useable batch this segment
C
                  IF (I.GT.LASTBATCH(ISEGBAT(I))) THEN
                    IPARPOINT(K) = -1
CAL                    NIMGUSE = NIMGUSE - 1
                  ELSE IF (CONTIG(I)) THEN
                    IPARPOINT(K) = NPAR
                  ELSE
                    IPARPOINT(K) = -1
CAL                    NIMGUSE = NIMGUSE - 1
                  END IF
                ELSE
                  IPARPOINT(K) = NPAR
                  LASTPAR = NPAR
                END IF
                NIMGUSE = NIMGUSE + 1

C
                IF (DEBUG(37)) THEN
                  WRITE(IOUT,FMT=6018) I,J,K,NPAR,IPARPOINT(K),
     +                                 NIMGUSE
                  IF (ONLINE) WRITE(IOUT,FMT=6018) I,J,K,NPAR,
     +                   IPARPOINT(K),NIMGUSE
 6018             FORMAT(1X,'i=',i2,' J=',i2,' K=',i2,' NPAR=',i2,
     +                   ' IPARPOINT(K)',I3,'  NIMGUSE',I3)
                END IF
C
 82           CONTINUE
 84         CONTINUE

C
C---- Now set up the inverse mapping from parameter sets to image numbers.
C     Note that a single parameter set may map to several images, so a start
C     and end image point are stored.
C     IMPOINT(parameter_number,1) = first image
C     IMPOINT(parameter_number,2) = last image
C
C     Here, first image is the current image, 2nd is the previous image etc.
C     Want to loop over all images actually being used in refinement
C
            IPOLD = -1
            NPAR = 0
            IMGSTART = 1
            IF (NIMAG.LT.NADD) THEN
              IEND2 = NIMGUSE
            ELSE
              IEND2 = NADD
            END IF
C
            LASTGOOD = 1
            
C
            DO 94 I = 1,IEND2
              IF (DEBUG(37)) THEN
                WRITE(IOUT,FMT=6023) I,IPARPOINT(I),NPAR,IPOLD,LASTGOOD
                IF (ONLINE) WRITE(ITOUT,FMT=6023) I,IPARPOINT(I),NPAR,
     +                  IPOLD,LASTGOOD
 6023           FORMAT(1X,'I=',I2,' IPARPOINT(I)',I3,' NPAR',I3,
     +                 '  IPOLD',I3,' LASTGOOD',I3)
              END IF
              IPNEW = IPARPOINT(I)
C
C---- If not to be used, skip
C
              IF (IPNEW.EQ.-1) GOTO 94
C
C---- Trap images which cannot be used (eg not contiguous)
C
              IF (IPNEW.LT.0) THEN
                IF (NPAR.EQ.0) IMGSTART = IMGSTART + 1
                GOTO 94
              END IF
              IF (IPNEW.NE.IPOLD) THEN
                NPAR = NPAR + 1
                IMPOINT(NPAR,1) = I
                IF (NPAR.GT.1) IMPOINT(NPAR-1,2) = LASTGOOD
                IPOLD = IPNEW
              END IF
              LASTGOOD = I
 94         CONTINUE
C
C---- Set up final pointer. Need to trap situation where there is not
C     enough data to do any refinement so NPAR ends up as zero
C
            NPAR = MAX(NPAR,1)
            IMPOINT(NPAR,2) = IEND2
C
C---- Need one more test, on the pointers for the final parameter,
C     to make sure that all the images assigned to that parameter are
C     contiguous in phi.
C
            ISTART = IMPOINT(NPAR,1)
            IEND = IMPOINT(NPAR,2)
            IF (IEND.GT.ISTART) THEN
C
              J = NSLOT-ISTART+1
              IF (J.LT.1) J = J + NADD
              M = 0
              DO 96 I = ISTART+1,IEND
                M = M + 1
                K = NSLOT -I + 1
                IF (K.LT.1) K = K + NADD
                IF ((ABS(PHISLOT(J)-PHISLOT(K))-
     +                     M*ABS(PHIEND-PHIBEG)).GT.0.02) THEN
                  NIMGUSE = NIMGUSE - (IEND-I+1)
                  IMPOINT(NPAR,2) = NIMGUSE
                  IF (DEBUG(37)) THEN
                    WRITE(IOUT,FMT=6022) I,PHISLOT(J),PHISLOT(K),
     +                      NIMGUSE
                    IF (ONLINE) WRITE(ITOUT,FMT=6022) I,PHISLOT(J),
     +                      PHISLOT(K),NIMGUSE
 6022               FORMAT(/,1X,'Discontinuity on phi values in ',
     +               'images in final set at image',I3,'  phi values',
     +               2F7.2,' NIMGUSE reset to:',I3)
                  END IF
                  GOTO 98
                END IF
 96           CONTINUE
            END IF
C
C
C---- now modify NIMGUSE to reflect any of the first, second etc images
C     rejected because that batch is not being refined (not enough refls)
C     and they are not contiguous in phi
C
            NIMGUSE = NIMGUSE - IMGSTART + 1
C
C
C---- Set up NPOINT, pointer into global array for first reflection to be
C     used. Have to use NIMGUSE rather than NADDMISSET in case an image
C     has been rejected as discontinous in phi (above).
C
 98         IF (NIMAG.LT.NADD) THEN
              IF ((NIMAG.LE.NADDMISSET).AND.(NSB.EQ.1)) THEN
                NPOINT = 1
              ELSE
                NPOINT = NRMAX*(NIMAG-NIMGUSE) + 1
CAL                NPOINT = NRMAX*(NIMAG-NADDMISSET) + 1
              END IF
            ELSE
              NPOINT = 1
            END IF
            IF (DEBUG(37)) THEN
               WRITE(IOUT,FMT=6024) NADD,NVIRBAT,NSLOT,NIMGUSE,
     +            IMGSTART,(PHISLOT(I),I=1,NADD)
               IF (ONLINE) WRITE(ITOUT,FMT=6024) NADD,NVIRBAT,NSLOT,
     +            NIMGUSE,IMGSTART,(PHISLOT(I),I=1,NADD)
 6024          FORMAT(1X,'NADD =',I3,' Number of images in a virtual',
     +               ' batch NVIRBAT',I3,/,1X,
     +               'Number of slot for current image NSLOT=',
     +               I3,'  number of images to be used NIMGUSE',I3,
     +               /,1X,'starting at image',I7,
     +               /,1X,'Phi values for slots (before permutation):',
     +              (/,1X,10F7.2))
               WRITE(IOUT,FMT=6026) NRSTORE,
     +            (NREFSTOR(I),I=1,NADD)
               IF (ONLINE) WRITE(ITOUT,FMT=6026) NRSTORE,
     +            (NREFSTOR(I),I=1,NADD)
 6026          FORMAT(/,1X,'total number of reflections stored',I6,
     +               /,1X,'Number of reflections for current, ',
     +             'previous etc images:',(/,1X,10I7))
               WRITE(IOUT,FMT=6028) NBAT,
     +            (USEBAT(I),I=1,NBAT)
               IF (ONLINE) WRITE(ITOUT,FMT=6028) NBAT,
     +            (USEBAT(I),I=1,NBAT)
 6028          FORMAT(/,1X,'Number of virtual batches',I3,/,1X,'Flags',
     +             ' for using each virtual batch',(1X,30L1,1X))
               WRITE(IOUT,FMT=6029) (CONTIG(I),I=1,NBAT)
               IF (ONLINE) WRITE(ITOUT,FMT=6029) (CONTIG(I),I=1,NBAT)
 6029          FORMAT(1X,'CONTIG in phi flag ',30L1)
               WRITE(IOUT,FMT=6030) (NREFVBAT(I),I=1,NBAT)
               IF (ONLINE) WRITE(ITOUT,FMT=6030) (NREFVBAT(I),I=1,NBAT)
 6030          FORMAT(/,1X,'Number of reflections in virtual batches:',
     +           (/,1X,10I7))  
               WRITE(IOUT,FMT=6032) 
CAL     +                         (I,IPARPOINT(I),I=1,NIMGUSE+IMGSTART-1)
     +                         (I,IPARPOINT(I),I=1,IEND2)
               IF (ONLINE) WRITE(ITOUT,FMT=6032) 
CAL     +                         (I,IPARPOINT(I),I=1,NIMGUSE+IMGSTART-1)
     +                         (I,IPARPOINT(I),I=1,IEND2)
 6032          FORMAT(/,1X,'List of image number, pointer into ',
     +           'parameter set. Image number is 1 for current image,',
     +           ' 2 for previous image etc.',/,(1X,10(I3,I3,3X)))
               WRITE(IOUT,FMT=6034) NADDL, 
     +                  (I,IMPOINT(I,1),IMPOINT(I,2),I=1,NADDL)
               IF (ONLINE) WRITE(ITOUT,FMT=6034)  NADDL,
     +                  (I,IMPOINT(I,1),IMPOINT(I,2),I=1,NADDL)
 6034          FORMAT(/,1X,'Total number of parameter sets ',I3,
     +                /,1X,'Parameter number, first and last',
     +           ' image numbers',/,(1X,10('par ',I3,' img',I4,' to ',
     +           I4,3X),/))
               WRITE(IOUT,FMT=6036) NPOINT
               IF (ONLINE) WRITE(ITOUT,FMT=6036) NPOINT
 6036          FORMAT(1X,'NPOINT passed to REFRT1',I6)
            END IF
C
         ELSE
C
C---- Old style post-refinement
C
            NR = NR + (NRADD - NDEL)
            NRSEG = NRSEG + (NRADD - NDEL)
            IF (DEBUG(37))THEN
               IF(ONLINE)WRITE(ITOUT,6014)NRADD,NDEL,
     $              NR
               WRITE(IOUT,6014)NRADD,NDEL,NR
 6014          FORMAT('NRADD, NDEL, NR: ',3I4)
            END IF
         END IF
C     
C---- If working with several images in REFRT1 mode, ie independent
C     missets, move around the missets in PARM and the phi values in PHIIM
C     at this point.
C     First need the number of refined cell parameters for pointer in PARM
C     
         IF ((NADD.GT.1).AND.(.NOT.FIXED)) THEN
C     
C---- If NC has not yet been set up, calculate it now
C     
            IF (NC.EQ.0) THEN
               DO 14 I=1,6
                  IF ((.NOT.FCELL(I)).AND.(LCELL(I).LT.0)) NC = NC + 1
 14            CONTINUE 
            END IF

            IF (.NOT.NEWPREF) THEN
C     
C---- Move the phi values around in PARM, but not if this is a repeat
C     measurement of an image (because of large slip)
C     
              IF ((IDPACK.EQ.IDLAST).OR.(ISEG.EQ.ISEGLAST)) GOTO 23
C     
              IF (NADD.GE.3) THEN
                 DO 16 I = NADD-1,2,-1
                      DO 18 K = 1,3
                       PARM(NC+3*I+K) = PARM(NC+3*(I-1)+K)
 18                 CONTINUE
 16              CONTINUE
              END IF
              DO 19 K=1,3
                 PARM(NC+3+K) = PARM(K)
                 PARM(K) = DELPHI(K)
 19           CONTINUE
C     
C---- Now move phi values around
C     
              DO 21 I=NADD,2,-1
                 PHIIM(I) = PHIIM(I-1)
 21           CONTINUE
              PHIIM(1) = PHIEND
            ELSE
C
C---- in NEWPREF, need to set up PARM explicitly for each image
C     as number of parameters to be refined may have changed.
C
              DO 100 I = 1,3
                PARM(I) = DELPHI(I)
 100          CONTINUE
C
C---- Now extra parameters. DELPHIV stores missets in "normal"
C     order, ie DELPHIV(1-3) contain missets for image 1 of the 
C     current "block" of images
C
              IF (NADDL.GT.1) THEN
                DO 112 I = 1,NADDL-1
                  N = IMPOINT(I+1,1)
C
C---- This N is 1 for current image, 2 for previous etc.
C     Now convert this to the slot number
C
                  N = NSLOT - N + 1
                  IF (N.LT.1) N = N + NADD
                  J = IDSLOT(N)
                  DO 110 K = 1,3
                    IF ((NIMAG.LT.NADD).OR.(.NOT.MULTISEG)) THEN
C
C---- No cell parameters are being refined
C
                      PARM(3*I+K) = RMISSETS(J,K)
                    ELSE
C
C---- Cell parameters now being refined
C
                      PARM(NC+3*I+K) = RMISSETS(J,K)
                    END IF
 110              CONTINUE
 112            CONTINUE
              END IF
C     
C---- Now move phi values around and set phi for current image
C     (unless this is a repeat). Note that we must permute ALL phi values,
C     not just the NIMGUSE ones, because if this is a multi seg
C     post-refinement NIMGUSE may be smaller than the number of slots,
C     but the phi values of ALL images are required when NIMAG=NADD
C
              IF ((IDPACK.NE.IDLAST).OR.(ISEG.NE.ISEGLAST)) THEN
                DO 114 I=NADD,2,-1
                   PHIIM(I) = PHIIM(I-1)
 114            CONTINUE
                PHIIM(1) = PHIBEG
              END IF
            END IF

            IF (DEBUG(37)) THEN
               WRITE(IOUT,FMT=6000) PHIBEG,PHIEND,NIMGUSE,
     $            IMGSTART,(PHIIM(I),I=IMGSTART,NIMGUSE+IMGSTART-1)
               IF (ONLINE) WRITE(ITOUT,FMT=6000) PHIBEG,PHIEND,
     +       NIMGUSE,IMGSTART,(PHIIM(I),I=IMGSTART,NIMGUSE+IMGSTART-1)
 6000          FORMAT(1x,'Phibeg = ',F7.2, ' Phiend = ',F7.2,/,
     $              1X,'Phi values for the NIMGUSE=',I3,' images',
     +              ' AFTER permutation starting at image',I7,/,
     +              (1X,10F8.2))
C
C---- Values in PARM depend on whether cell parameters are being refined 
C     in this cycle or not. 
C     If not, then missets alone are stored. If they are, then
C     array elements 4 to 4+NC-1 are not used for missets (but will not be
C     zero as they will have had missets stored in them from a previous image
C
               IF ((NIMAG.LT.NADD).OR.(.NOT.MULTISEG)) THEN
C
C---- No cell parameters are being refined
C
                 WRITE(IOUT,FMT=6002)(PARM(I),I=1,3*NADDL)
                 IF (ONLINE) WRITE(ITOUT,FMT=6002)(PARM(I),I=1,3*NADDL)
 6002            FORMAT(1X,'Missetts as stored in PARM:',/,(1X,3F10.3))
               ELSE
C
C---- NC Cell parameters are being refined
C
                 WRITE(IOUT,FMT=6002)(PARM(I),I=1,3)
                 IF (ONLINE) WRITE(ITOUT,FMT=6002)(PARM(I),I=1,3)
                 WRITE(IOUT,FMT=6003)(PARM(I),I=4+NC,4+NC+3*(NADDL-1))
                 IF (ONLINE) WRITE(ITOUT,FMT=6003)
     +                               (PARM(I),I=4+NC,4+NC+3*(NADDL-1))
 6003            FORMAT((1X,3F10.3))
               END IF
            END IF
         ELSE
C     
C---- Assign PHIIM(1) and move DELPHI into PARM (this may have been 
C     done by code above if NADD.GT.1)
C     
           IF (NEWPREF) THEN
             PHIIM(1) = PHIBEG
           ELSE
             PHIIM(1) = PHIEND
           END IF
           DO 22 I = 1,3
              PARM(I) = DELPHI(I)
 22        CONTINUE
         END IF

C     
       
C
C---- now check that there is enough data to do a refinement
C     This will not necessarily be the case when starting on a new segment
C     Must use NSB rather than ISEG here, because ISEG does not
C     get reset to 1 if two blocks of images are integrated separately in
C     the same job, use NSB instead.
C     Do the test on whether there are ANY good batches in the current 
C     segment, rather than just in the latest batch.
C
CAL 23      IF ((ISEG.GT.1).AND.(.NOT.USEBAT(1))) THEN
 23      IF ((NSB.GT.1).AND.(.NOT.GOODSEG(ISEG))) THEN
           IF (DEBUG(37)) THEN
             WRITE(IOUT,FMT=6019) NSB,NPAR
             IF (ONLINE) WRITE(ITOUT,FMT=6019) NSB,NPAR
CAL 6019        FORMAT(1X,'ISEG=',I2,' NPAR=',I2,' but USEBAT',
CAL     +          ' is not true for first virtual batch so'
CAL     +          ' no refinement.')
 6019        FORMAT(1X,'ISEG=',I2,' NPAR=',I2,' but no',
     +          ' useable batches in this segment so',
     +          ' no refinement.')
           END IF
           RETURN
         END IF
         DIVHS = DIVH
         DIVVS = DIVV
         ETAS = ETA
         DO 26 I = 1,3
            DO 24 J = 1,3
               SAMAT(J,I) = AMAT(J,I)
 24         CONTINUE
 26      CONTINUE
C     
C---- IDXREF uses LCELL as indicator for cell parameters to be
C     refined, so save LCELL and then reset it using FCELL
C     Cell parameter refinement flags LCELL(I),I=1,6
C     
C     LCELL(I) = -1  parameter free
C     =  0  parameter fixed
C     .gt. 0, = J  parameter I constrained to = parameter J
C     
         DO 27 I=1,6
            LCELLS(I) = LCELL(I)
            IF (FCELL(I).AND.(LCELL(I).LT.0)) LCELL(I) = 0
 27      CONTINUE
C     
C     
C---- If not enough images accumulated, then still allow orientation
C     refinement in "single" mode, but don't allow cell refinement
C     Also save the number of refined beam parameters and set it to zero
C     Also set NADDP (passed to IDXREF rather than NADD) to 1
C     Also reset IRECG to -990 as flag to main program (mosflm) that the
C     test for a "single image" shift should be applied
C     
         NADDP = NADD
         NOREFCELL = .FALSE.
C
C---- Need to initialise SHIFT to zero now, in case refinment is not
C     actually carried out.
C
         SHIFT(1) = 0.0
         SHIFT(2) = 0.0
         SHIFT(3) = 0.0
C
C---- Initialise flag for setting CCOMEGA to zero in REFRT1
C
         RESETCCOM = .FALSE.
C
         IF (NEWPREF) THEN
           NADDP = NADDL
           IF (NADDP.LT.1) THEN
C     
C---- Restore original values of LCELL
C     
             DO 50 I = 1,6
               LCELL(I) = LCELLS(I)
 50          CONTINUE
             RETURN
           ENDIF
C
C---- Do not do refinement if this is a new segment and there are not
C     yet enough reflections to refine missets
C
           IF ((.NOT.CONTIG(1)).AND.(.NOT.USEBAT(1))) THEN
             IF (DEBUG(37)) THEN
               WRITE(IOUT,FMT=6041) 
               IF (ONLINE) WRITE(ITOUT,FMT=6041) 
 6041          FORMAT(1X,'*** This is a new segment but there',
     +                ' are not enough reflections for refinement',
     +           /,1X,' of images in this segment so skip refinement')
             END IF
             RETURN
           END IF
C
C---- Send XML to GUI to say postrefinement is being started
C
           IF(SOCKLO)THEN
 6042         FORMAT('<?xml version="1.0"?>',
     $        '<!DOCTYPE integration_postrefinement_begin SYSTEM "">',
     $             '<integration_postrefinement_begin>',
     $             '<status>',
     $             '<code>ok</code>',
     $             '</status>',
     $             '<image_name>',A,'</image_name>',
     $            '<image_template>',A,'</image_template>',
     $            '<image_number>',I8,'</image_number>',
     $             '</integration_postrefinement_begin>')
              WRITE(XMLLINE,FMT=6042) SHORTFN(1:LENSTR(SHORTFN)),
     $             TEMPLSAV(1:lenstr(templsav)),ID
              CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $             LENSTR(XMLLINE),XMLLINE)
           ENDIF

           NSSAVE = NS
           NS = 0
CAL           NPOINT = 1
           IRECG = -990
C     
C---- If new style post-refinement, then use all available images. Do
C     not reset LCELL, but pass another flag to make sure cell is not
C     refined.
           IF (NIMAG.LT.NADD) THEN
             DO 29 I=1,6
                LCELL(I) = 0
 29          CONTINUE
             NOREFCELL = .TRUE.
CAL             NIMGUSE = NADDMISSET
           ELSE
             NIMGUSE = 0
             NOREFCELL = .FALSE.
CAL             DO 25 I = 1,NADD
CAL               IF (USEBAT(I)) NIMGUSE = NIMGUSE + 1
CAL 25          CONTINUE
             NIMGUSE = NADD
           END IF
C     
C---- Only refine mosaic spread when we have sufficient reflections if integration
C     run in NEWPREF mode
C     
           IF (NR.GT.NREFMOS) NS = NSSAVE
         ELSE
           IF (NIMAG.LT.NADD) THEN
              NSSAVE = NS
              NS = 0
              NADDP = 1
              NIMGUSE = 1
              IRECG = -990
              DO 28 I=1,6
                 LCELL(I) = 0
 28           CONTINUE
           END IF
C
C---- NIMGUSE may not have been set for old style post-refinement
C
           IF (NIMGUSE.EQ.0) NIMGUSE = 1
         END IF
C
         IF (DEBUG(37)) THEN
            IF(ONLINE)WRITE(ITOUT,6015)NRL,AMAT,DELPHI,DIVH,DIVV,ETA,
     $           LCELL,NS,IDPACK
            WRITE(IOUT,6015)NRL,AMAT,DELPHI,DIVH,DIVV,ETA,
     $           LCELL,NS,IDPACK
 6015       FORMAT('NRL = ',I4,/,'AMAT =  ',3F9.5,/,2(8X,3F9.5,/),
     $           'DELPHI = ',3F7.3,/,'DIVH = ',F8.4,', DIVV = ',
     $           F8.4,', ETA = ',F8.4,/,'LCELL = ',6(I5),/,
     $           'NS = ',I4,/,1X,'IDLAST reset to',I5)
         END IF
C     
C---- Reassign IDLAST, ISEGLAST
C     
         IDLAST = IDPACK
         ISEGLAST = ISEG
C
C---- NNIMGUSE is used in REFRT1 to know how many elements of PHIIM to
C     search when finding how to assign a particular reflection. Must
C     extend this search if the first image (or more) are not going to
C     be used because they belong to a different segment.
C
         NNIMGUSE = NIMGUSE + IMGSTART - 1

C     
C----    *************************************************************     
         CALL IDXREF(ID,NADDP,FIXED,NNIMGUSE,NPOINT,NOREFCELL,
     +               NEWPREF,ISTAT)
C----    *************************************************************     
C
C---- Note ISTAT returned as 1 if a refinement has been carried out
C
         IF (ISTAT.EQ.-1) THEN
            RETURN
         END IF
         IF (DEBUG(37)) THEN
           IF ((NIMAG.LT.NADD).OR.(.NOT.MULTISEG)) THEN
C
C---- No cell parameters are being refined
C
             WRITE(IOUT,FMT=6002)(PARM(I),I=1,3*NADDL)
             IF (ONLINE) WRITE(ITOUT,FMT=6002)(PARM(I),I=1,3*NADDL)
           ELSE
C
C---- NC Cell parameters are being refined
C
             WRITE(IOUT,FMT=6002)(PARM(I),I=1,3)
             IF (ONLINE) WRITE(ITOUT,FMT=6002)(PARM(I),I=1,3)
             WRITE(IOUT,FMT=6003)(PARM(I),I=4+NC,4+NC+3*(NADDL-1))
             IF (ONLINE) WRITE(ITOUT,FMT=6003)
     +                               (PARM(I),I=4+NC,4+NC+3*(NADDL-1))
           END IF
         END IF
C     
C---- Transfer refined parameters back into MOSFLM common blocks
C     
         DO 31 I = 1,3
            SDBEAM(I) = 0.0
            SDDELPHI(I) = SIG(I)
            SHIFT(I) = (PARM(I)-DELPHI(I))
C     
C---- ERROR here is for testing purposes only, introduce an error in refined
C     values
C     
            DELPHI(I) = PARM(I) + ERROR(I)
 31      CONTINUE
C     
C---- If NADD gt 1 but we have not yet processed NADD images, then
C     only the orientation will have been refined above. Can now
C     skip moving around angles and sd's.
C     However, this does not apply if doing new-style post-refinement
C     
         IF ((NIMAG.LT.NADD).AND.(.NOT.NEWPREF)) THEN
            NS = NSSAVE
            GOTO 39
         END IF
C     
C---- Deal with case where NADD.GT.1 but each image has its own
C     missetting angles (and sd's). After the first post-refinement,
C     must move the angles and sd's into arrays so they can be written
C     to the summary file.
C     
         IF (((NADD.GT.1).AND.(NADD.EQ.NIMAG).AND.(.NOT.FIXED)).AND.
     +             (.NOT.NEWPREF)) THEN
            IPT = 0
            IPTR = 0
C     
C---- First store the missets (3) and sd's (2) for the previous images
C     note we want to invert the order relative to that in PARM and SIG
C     because we want the first image first in the arrays etc
C     

            DO 32 I = 1,NADD-1
               DO 30 K = 1,3
                  IPTR = IPTR + 1
                  DELPHIV(IPTR) = PARM(3*(NADD-I)+NC+K)
                  IF (K.GT.2) GOTO 30
                  IPT = IPT + 1
                  SDDELPHI(IPT) = SIG(2*(NADD-I)+NC+K)
 30            CONTINUE
 32         CONTINUE
C     
C---- Now the sd's and missets for the current image (stored last in
C     the array)
C     
            SDDELPHI(2*NADD-1) = SIG(1)
            SDDELPHI(2*NADD) = SIG(2)
            DELPHIV(3*NADD-2) = PARM(1)
            DELPHIV(3*NADD-1) = PARM(2)
            DELPHIV(3*NADD) = PARM(3)
         END IF
C
C---- Now deal with NEWPREF case
C
         IF (NEWPREF) THEN
           IPT = 0
C
C---- Loop over parameter sets
C
           DO 37 I = 1,NADDP
             ISTART = IMPOINT(I,1)
             IEND = IMPOINT(I,2)
C
C---- Need to convert these to slot numbers, to get image ID (which
C     run from IFIRSTPACK to NPACK
C
             ISTART = NSLOT - ISTART + 1
             IF (ISTART.LT.1) ISTART = ISTART + NADD
             IEND = NSLOT - IEND + 1
             IF (IEND.LT.1) IEND = IEND + NADD
             IPACKST = IDSLOT(IEND)
             IPACKEND = IDSLOT(ISTART)
             IF (I.EQ.1) IPACKSTSV = IPACKST
             IF (I.EQ.1) ILASTPACK = IPACKEND
             IF (DEBUG(37)) THEN
               WRITE(IOUT,FMT=6060) I,IMPOINT(I,1),IMPOINT(I,2),
     +                  ISTART,IEND,IPACKST,IPACKEND
               IF (ONLINE) WRITE(ITOUT,FMT=6060) I,IMPOINT(I,1),
     +               IMPOINT(I,2),ISTART,IEND,IPACKST,IPACKEND
 6060          FORMAT(1X,'Parameter',I3,' Impoint values',2I3,
     +                ' ISTART=',I3,'  IEND=',I3,' IPACKST=',I4,
     +                ' IPACKEND=',I4)
             END IF
C
C---- Loop over all images in this virtual batch
C
             DO 36 IMGID = IPACKST,IPACKEND
C
C---- Flag those images that have been assigned a value
C
                 VALSET(IMGID) = .TRUE.
                 IF (I.EQ.1) THEN
                   IPTR = 1
                   IPTRSD = 1
                 ELSE
                   IPTR = 3*(I-1)+NC+1
                   IPTRSD = 2*(I-1)+NC+1
                 END IF
                 IF (DEBUG(37)) THEN
                   WRITE(IOUT,FMT=6050) IMGID,IPTR,NC,
     +                                 NADDP,ISTART,IEND
                   IF (ONLINE) WRITE(ITOUT,FMT=6050) IMGID,IPTR,NC,
     +                                 NADDP,ISTART,IEND
 6050              FORMAT(1X,'Storing parameters for pack',I4,' from',
     +                  ' PARM array starting at element',I3,
     +              ' NC=',I3,' NADDP=',I3,' ISTART=',I3,' IEND=',I3)
                 END IF
                 DO 34 K = 1,3
                   RMISSETS(IMGID,K) = PARM(IPTR+K-1)
                   IF (K.GT.2) GOTO 34
                   SDMISSETS(IMGID,K) = SIG(IPTRSD+K-1)
 34              CONTINUE
 36          CONTINUE
 37        CONTINUE
C
C----
C
           IF (DEBUG(37)) THEN
             WRITE(IOUT,FMT=6052) ILASTPACK,(VALSET(I),I=1,ILASTPACK)
             IF (ONLINE) WRITE(ITOUT,FMT=6052) ILASTPACK,
     +             (VALSET(I),I=1,ILASTPACK)
 6052        FORMAT(/,1X,'number of packs is',I5,' and flags for',
     +       ' having been assigned missets are:',/,(1X,20L1))
           END IF
C
C---- Check those images that have not been assigned missets
C     (because they are the first image(s) of a new segment)
C     and assign them now.
c
           ISTA = 0
           DO 45 I = 1,ILASTPACK
              IF (I.LE.ISTA) GOTO 45
C
C---- Find first image that has been assigned
C
             IF (.NOT.VALSET(I)) THEN
               DO 41 J = I+1, ILASTPACK
                 IF (VALSET(J)) THEN
                   IPOINT = J
                   GOTO 42
                 END IF
 41            CONTINUE
C
 42            IF (DEBUG(37)) THEN
                 WRITE(IOUT,FMT=6056) I, IPOINT-1, IPOINT
                 IF (ONLINE) WRITE(ITOUT,FMT=6056) I, IPOINT-1, IPOINT
 6056            FORMAT(1X,'Assigning missets for images',I7,' to',I7,
     +                   ' to those of image',I7)
               END IF
               DO 43 J = I,IPOINT-1
                 DO 44 K = 1,3
                   RMISSETS(J,K) = RMISSETS(IPOINT,K)
                   IF (K.GT.2) GOTO 44
                   SDMISSETS(J,K) = SDMISSETS(IPOINT,K)
 44              CONTINUE
 43            CONTINUE
               ISTA = IPOINT
             END IF
 45        CONTINUE
         END IF
C
         IF (DEBUG(37)) THEN
           WRITE(IOUT,FMT=6080) ((RMISSETS(I,K),K=1,3),
     +                          (SDMISSETS(I,K),K=1,2),I=1,NIMAG+ISEG)
           IF (ONLINE) WRITE(ITOUT,FMT=6080) 
     +                          ((RMISSETS(I,K),K=1,3),
     +                          (SDMISSETS(I,K),K=1,2),I=1,NIMAG+ISEG)
 6080      FORMAT(/,1X,'Missets and sds',/,(1X,3F10.3,10X,2F10.3))
         END IF
C     
C---- Special case of multiseg refinement using only two images (ie NADD=1)
C     need to transfer shifts into DELPHIV or else missets won't be updated
C     when repeating a run from scratch
C     
         IF ((NADD.EQ.1).AND.(NADD.EQ.NIMAG)) THEN
            DELPHIV(3*NADD-2) = PARM(1)
            DELPHIV(3*NADD-1) = PARM(2)
            DELPHIV(3*NADD) = PARM(3)
         END IF
C     
C---- Get shifts in reciprocal cell as a multiple of sds. New values are in
C     PARM()...,old values are in SRCELL.
C     
         NNC = 0
         CELLSHIFT = 0.0
         FRCSHIFT = 0.0
C     
C---- IADDR is number of missetting angles being refined, 2 for single image
C     and multiple images unless FIXED option is being used in which case all
C     3 missetting angles are refined
C     
         IADD = 3
         IADDR = 2
         IF ((NADD.GT.1).AND.FIXED) IADDR = 3
         DO 38 I = 1,6
            SDCELL(I) = 0.0
            IF (LCELL(I).EQ.-1) THEN
               NNC = NNC + 1
               IF (SIG(IADDR+NNC).NE.0.0) THEN
C
C---- For very high resolution data, sigmas can calculate to be
C     unrealistically small, so set a minimum sigma of 1 part if 10000
C     for determining if cell shift is too large
C
                  SDMIN = MAX(0.0001*SRCELL(I),SIG(IADDR+NNC))
                  SDRAT = ABS(PARM(IADD+NNC) - SRCELL(I))/SDMIN
                  ABSRAT = ABS(PARM(IADD+NNC) - SRCELL(I))/SRCELL(I)
               ELSE
                  SDRAT = 0.0
                  ABSRAT = 0.0
               END IF
               CELLSHIFT = MAX(CELLSHIFT,SDRAT)
               IF (DEBUG(37)) THEN
                 WRITE(IOUT,7777) SIG(IADDR+NNC), SRCELL(I), SDMIN,
     +               PARM(IADD+NNC),SDRAT,CELLSHIFT
                 IF (ONLINE) WRITE(ITOUT,7777) SIG(IADDR+NNC),
     +               SRCELL(I),SDMIN,PARM(IADD+NNC),SDRAT,CELLSHIFT
 7777          FORMAT(1X,'SIGMA',f10.7,'  CELL',F10.7,'  SDMIN',
     +              f10.7,'  REFCELL',F10.7,'  SDRAT',F10.5,
     +             '  CELLSHIFT',F10.5)
               END IF
               FRCSHIFT = MAX(FRCSHIFT,ABSRAT)
C     
C---- Store sd's, as a fraction of reciprocal cell for cell edges,
C     in degrees for cell angles.
               IF (I.LE.3) THEN
                  SDCELL(I) = SIG(IADDR+NNC)/PARM(IADD+NNC)
               ELSE
                  SDCELL(I) = SIG(IADDR+NNC)
               END IF
            ELSE IF ((LCELL(I).EQ.1).AND.(I.GT.1)) THEN
               SDCELL(I) = SDCELL(I-1)
            END IF
            IF (DEBUG(37)) THEN
               WRITE(IOUT,FMT=6150)I,SDCELL(I),NNC,
     $              SDRAT,PARM(IADD+NNC),SRCELL(I),SIG(IADDR+NNC)
               IF (ONLINE) WRITE(ITOUT,FMT=6150)I,SDCELL(I),NNC,
     $              SDRAT,PARM(IADD+NNC),SRCELL(I),SIG(IADDR+NNC)
 6150          FORMAT(1X,'I=',I2,' SDCELL(I)',F7.3,' NNC',I2,
     +           ' SDRAT',F7.3,' PARM',F8.3,' SRCELL',F8.3,' SIG',
     +            F8.4)
            END IF
 38      CONTINUE  
C     
C---- Sds of beam parameters
C     
         IADD2 = (NADD-1)*2
         IF ((NADD.GT.1).AND.FIXED) IADD2 = 0
         IF (ISYNL.AND.(NS.EQ.1)) THEN
            SDBEAM(1) = SIG(IADDR+NNC+IADD2+1)
            SDMOS = SDBEAM(1)
         ELSE
            SDBEAM(2) = SIG(IADDR+NNC+IADD2+1)
            SDBEAM(3) = SIG(IADDR+NNC+IADD2+2)
            SDMOS = SDBEAM(2)
            IF (NS.EQ.1) SDBEAM(3) = SDBEAM(2)
         END IF
C     
C---- Restore original values of LCELL
C     
 39      DO 40 I = 1,6
            LCELL(I) = LCELLS(I)
 40      CONTINUE
         IF (DEBUG(37)) THEN
            WRITE(IOUT,FMT=6100) (SDBEAM(I),I=1,3),(SHIFT(I),I=1,3),
     +        AMAT 
            IF (ONLINE) WRITE(ITOUT,FMT=6100) (SDBEAM(I),I=1,3),
     +        (SHIFT(I),I=1,3),AMAT 
 6100       FORMAT(1X,'Refined SDBEAM',3F10.4,/,1X,'Shifts in missets',
     +             3F10.3,/,1X,'AMAT',/,(1X,3F10.7))
            WRITE(IOUT,FMT=6110) DELPHI,DIVH,DIVV,ETA
            IF (ONLINE) WRITE(ITOUT,FMT=6110) DELPHI,DIVH,DIVV,ETA
 6110       FORMAT(1X,'Refined missets',3F10.3,/,1X,'DIVH,DIVV,ETA',
     +        3F10.4,/,/)
         END IF
C
C---- Save missets and sds for summary
C
         DO 46 I = 1,3
           SAVEDELPHI(I) = DELPHI(I)
 46      CONTINUE
         
C
C---- If required, smooth the missets
C
         IF (SMOOTHPHI) THEN
           CALL SMOOTHDELPHI(NIMAG,NDONE,DELPHI,DELPHISM)
           IF (DEBUG(37)) THEN
             WRITE(IOUT,FMT=6114) DELPHI, DELPHISM,(PARM(I),I=1,3)
             IF (ONLINE) WRITE(ITOUT,FMT=6114) DELPHI, DELPHISM,
     +          (PARM(I),I=1,3)
 6114        FORMAT(1X,'Missets: ',3F10.3,/,
     +              1X,'Smoothed missets',3F10.3,
     +              1X,'PARM(1-3)',3F10.3)
           END IF
           DO 48 I = 1,3
             DELPHI(I) = DELPHISM(I)
             PARM(I) = DELPHISM(I)
             SAVEDELPHI(I) = DELPHISM(I)
 48        CONTINUE
           WRITE(IOUT,FMT=6116) DELPHISM 
           IF (ONLINE) WRITE(ITOUT,FMT=6116) DELPHISM 
 6116      FORMAT(1X,'Smoothed refined orientation angles',
     +            /10X,'PHIX       PHIY ', '      PHIZ',/,
     +            7X,3F10.3)
         END IF

C     
C---- Restore saved beam parameters unless USEBEAM set
C     but also keep refined values for output to summary file
C     Note these values are FULL widths in radians
C     First save the refined values for summary file.
         RDIVH = DIVH
         RDIVV = DIVV
         RETA = ETA
         IF (NS.EQ.1) THEN
           CALL SMOOTHETA(NIMAG,NDONE)
         ELSE
           ETASM = ETA
         END IF
         IF (USEBEAM) THEN
           IF (DEBUG(37)) THEN
             WRITE(IOUT,FMT=6160) NIMAG,NDONE,ETA/DTOR,
     +                           ETASM/DTOR
             IF (ONLINE) WRITE(ITOUT,FMT=6160) NIMAG,NDONE,
     +                           ETA/DTOR,ETASM/DTOR
 6160        FORMAT(1X,'NIMAG=',I4,' NDONE=',I4,' REFINED ETA',F7.2,
     +              ' Smoothed eta',F7.4)
           END IF
           IF (NS.EQ.1) THEN
             WRITE(IOUT,FMT=6170) ETASM/DTOR
             IF (ONLINE) WRITE(ITOUT,FMT=6170) ETASM/DTOR
           END IF
 6170      FORMAT(/,1X,'Smoothed value for refined mosaic spread',
     +             ' (including safety factor):',F7.2,/)
C     
C---- Convert refined values back to half-widths in radians
C     
           DIVH = 0.5*DIVH
           DIVV = 0.5*DIVV
           ETA = 0.5*ETASM
           RETA = 2.0*ETA
C     
C---- If the mosaic spread was reduced earlier to avoid overlap,
C     set the mosaic spread to the smaller of the reduced and refined values.
C
           IF (DEBUG(1)) THEN
             WRITE(IOUT,FMT=6172) RESETETA,2*ETA/DTOR,2*ETAMOD/DTOR
             IF (ONLINE) WRITE(ITOUT,FMT=6172) RESETETA,2*ETA/DTOR,
     +             2*ETAMOD/DTOR
 6172        FORMAT(1X,'In POSTREFL, RESETETA',L2,'  eta',F7.3,
     +              '  etamod',F7.3)
           END IF
           IF (RESETETA) THEN
             IF (ETA.GT.ETAMOD) THEN
               ETA = MIN(ETA,ETAMOD)
               RETA = 2.0*ETA
               WRITE(IOUT,FMT=6180) 2.0*ETA/DTOR
               IF (ONLINE) WRITE(ITOUT,FMT=6180) 2.0*ETA/DTOR
 6180          FORMAT(1X,'Mosaic spread reset to',f6.2,' to avoid',
     +          ' overlap')
             ELSE
               RESETETA = .FALSE.
             END IF
           END IF
         ELSE
C     
C---- Restore stored values
C     
            DIVH = DIVHS
            DIVV = DIVVS
            ETA = ETAS
         END IF
         RESID = RMSR
         NREFPR = NR

C     ..
C     .. stuff for GUI
         IF(SOCKLO)THEN
            SD1 = 0.0
            SD2 = 0.0
            IF (NEWPREF) THEN
              IF (IPACKST.GT.0) THEN
                SD1 = SDMISSETS(IPACKST,1)
                SD2 = SDMISSETS(IPACKST,2)
              END IF
            ELSE
              SD1 = SDDELPHI(2*NADD-1)
              SD2 = SDDELPHI(2*NADD)
            END IF
            WRITE(XMLLINE,FMT=6200)
            CALL WRITE_SOCKET_SECTION(SERVERFD,LENSTR(XMLLINE),XMLLINE)
C
C---- need to avoid any possibility of format errors in XML for refined
C     cell parameters and sd's. This can happen, eg for electron diffraction data
C     must also trap large -ve values for cell !
C
            DO 90 I = 1,6
              IF (CELL(I).GT.0) THEN
                XMLCELL(I) = MIN(CELL(I),9999.0)
              ELSE
                XMLCELL(I) = MAX(CELL(I),-9999.0)
              END IF
              IF (I.LE.3) THEN
                XMLSDCELL(I) = MIN(SDCELL(I)*CELL(I),9999.0)
              ELSE
                XMLSDCELL(I) = MIN(SDCELL(I),9999.0)
              END IF
 90         CONTINUE
            WRITE(XMLLINE,FMT=6210)SHORTFN(1:LENSTR(SHORTFN)),
     $           TEMPLSAV(1:lenstr(templsav)),ID,NR,RESID,
     +           PARM(1),PARM(2),PARM(3),
     +           SD1,SD2,(XMLCELL(I),XMLSDCELL(I),I=1,3),
     +           (XMLCELL(I),XMLSDCELL(I),I=4,6),
     $           ((AMAT(I,K),K=1,3),I=1,3),
     +           2.0*ETA/DTOR,SDMOS/DTOR
            print*,'LENSTR(XMLLINE) is ',LENSTR(XMLLINE)
            CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(XMLLINE),XMLLINE)
         ENDIF
 6200    FORMAT ('<?xml version="1.0"?>',
     $        '<!DOCTYPE integration_postrefinement>',
     $        '<integration_postrefinement><status><code>ok</code>',
     $        '</status>')
 6210    FORMAT (
     $        '<image_name>',A,'</image_name>',
     $        '<image_template>',A,'</image_template>',
     $        '<image_number>',I8,'</image_number>',
     +        '<number_of_reflections>',I7,'</number_of_reflections>',
     +        '<final_residual>',F7.3,'</final_residual>',
     $        '<phi_x>',F8.3,'</phi_x><phi_y>',F8.3,'</phi_y>',
     $        '<phi_z>',F8.3,'</phi_z><psi_y_sd>',F7.3,'</psi_y_sd>',
     $        '<psi_z_sd>',F7.3,'</psi_z_sd>',
     $        '<cell_a>',F9.3,'</cell_a>',
     $        '<cell_a_sd>',F9.3,'</cell_a_sd>',
     +        '<cell_b>',F9.3,'</cell_b>',
     +        '<cell_b_sd>',F9.3,'</cell_b_sd>',
     $        '<cell_c>',F9.3,'</cell_c>',
     $        '<cell_c_sd>',F9.3,'</cell_c_sd>',
     +        '<cell_alpha>',F8.3,'</cell_alpha>',
     +        '<cell_alpha_sd>',F8.3,'</cell_alpha_sd>',
     $        '<cell_beta>',F8.3,'</cell_beta>',
     $        '<cell_beta_sd>',F8.3,'</cell_beta_sd>',
     $        '<cell_gamma>',F9.3,'</cell_gamma>',
     $        '<cell_gamma_sd>',F9.3,'</cell_gamma_sd>',
     $        '<a_matrix>',
     $        '<a11>',F11.8,'</a11>',
     $        '<a12>',F11.8,'</a12>',
     $        '<a13>',F11.8,'</a13>',
     $        '<a21>',F11.8,'</a21>',
     $        '<a22>',F11.8,'</a22>',
     $        '<a23>',F11.8,'</a23>',
     $        '<a31>',F11.8,'</a31>',
     $        '<a32>',F11.8,'</a32>',
     $        '<a33>',F11.8,'</a33>',
     $        '</a_matrix>',
     +        '<mosaicity>',F7.3,'</mosaicity>',
     +        '<mosaicity_sd>',F7.3,'</mosaicity_sd>',
     $        '</integration_postrefinement>')
         


      END IF
      RETURN
      END
C== PQINV ==
C $Id: pqinv.f,v 1.2 2006/08/29 14:58:28 harry Exp $
C
C
      SUBROUTINE PQINV(PQSUMS,PQSUMINV)
      IMPLICIT NONE
C     =================================
C
C
C---- Form the inverse matrix from pqsums to solve for background
C
C
C
C
C     .. Array Arguments ..
      REAL PQSUMINV(9),PQSUMS(6)
C     ..
C     .. Local Scalars ..
      REAL DET,SP,SPQ,SQ
C     ..
C     .. Local Arrays ..
      REAL PQ(3,3)
C     ..
C     .. External Subroutines ..
      EXTERNAL MINV33
C     ..
C
C
      SPQ = PQSUMS(3)
      SP = PQSUMS(4)
      SQ = PQSUMS(5)
C
      PQ(1,1) = PQSUMS(1)
      PQ(2,2) = PQSUMS(2)
      PQ(3,3) = PQSUMS(6)
      PQ(1,2) = SPQ
      PQ(2,1) = SPQ
      PQ(1,3) = SP
      PQ(3,1) = SP
      PQ(2,3) = SQ
      PQ(3,2) = SQ
C
C          ***********************
      CALL MINV33(PQSUMINV,PQ,DET)
C
C
      END
C
C $Id: prddet.f,v 1.11 2008/07/31 11:56:39 harry Exp $
C
      SUBROUTINE PRDDET(XT, YT, IERR)
      IMPLICIT NONE
C
C     This S/R adapted from PRDDET in MADNES to fit with MOSFLM conventions
C     Harry Powell 24.01.2001
C!
C!  Calculates spot coordinates on the detector and tests
C!  whether spot is within detector limits.
C!  Error flag IER set on failure
C!
C!  This subroutine created using code written by Albrecht
C!  Messerschmidt.    November 1987
C!
C!  Dummy Arguments
C!  Read
C!    XR(3)    Dimensionless reciprocal lattice coordinate of this
C!        reflection in the laboratory frame.
C!    DN    Vector defining detector normal in lab frame.
C!    DDINV    Matrix used in calculation of detector coords
C!  Write
C!    XT, YT   Detector coordinates (real, pixels)
C!    IERR    Error flag, .eq. 0 = good reflection
C!                .ne. 0 = rejected reflection
C!
C!
C!    7-Mar-1988  Marty Stanton   Brandeis University
C!          Remove detector dimensions - this is done in MMTOPX
C!          Remove check of NUF - created a function to do this.
C!              I think this test shouldn't be in MMTOPX as
C!              it has nothing to do with that conversion
C!          I'm not sure about the check on the distance from the
C!              detector center - the origin of coordinates does
C!              not have to be at the center of the detector
C!
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
