C     ..
C     .. Common Block /XY/ ..
      COMMON /XY/XTOFD,SINV,COSV,TANV,TWOTHETA,ICASS
C     ..
C
C     XTOFD....  Crystal to detector distance in 10 micron units. Read from
C                keyworded input and never changed.
C
C                Spot positions are calculated in S/R XYSPOT (Called from
C                REEK) and are for an "ideal" detector at a distance of XTOFD.
C                These are converted into pixel positions in S/R MMTOPX
C                which applies the multiplicative factor XTOFRA to allow
C                for refinement of the distance. XTOFRA is the parameter
C                that is actually refined (in RDIST), rather than XTOFD.
C                The refined distance that is printed in the logfile is
C                actually XTOFRA*XTOFD
C
C     ICASS....  Indicates detector type:
C                0     Flat film
C                1     Vee shaped cassettes
C                2     FAST detector (only used in TESTGEN mode of OSCGEN)
C                3     Swung out FAST (ditto)
C                4     IP detector
C     TWOTHETA   Detector swing angle (degrees)
C&&*&& end_include  ../inc/xy.f
C
C---- external functions
C
      REAL DOT
      EXTERNAL DOT
C
C---- external subroutines
C
      EXTERNAL CROSS,VDIFF,ROTMAT
C
      DATA SCAMCON/8*0.0/,FIRSTTIME/.TRUE./
      save
      PARAMETER (QDIST = 3)
C
C  Convert the coordinates of the vector XR in reflection
C  position in diffractometer coordinate system into
C  mm-detector-coordinates.
C
C  VDCC - calculated detector coordinates on inclined
C  detector.
C
C  Now we need  TS = (XR - S0) * DIST**2 / (XR.DN - S0.DN)
C               --    --   --               -- --   -- --
C
C  Set error flag off
C
      IERR = 0
C
C---- conversions between lab axes
C
      XR(1) = x1
      XR(2) = Y1
      XR(3) = z1
C
C---- CAMCON(1) = CCX     }             { beam error in X (mm)
C           (2) = CCY     } distortions {   "    "    " Y (mm)
C           (3) = crystal to detector distance (mm)
C           (4) = CCOMEGA in degrees about axis // to X (X-ray beam)
C           (5) = TWIST in degrees about "vertical" axis // to Y (~PHI)
C           (6) = TILT in degrees about "horizontal" axis // to Z, _|_ to Y
C                                 and X-ray                              
C           (7) = inclination angle of primary beam - ONLY used to calculate s0
C           (8) = inclination angle of primary beam -   "   "    "     "      "
C
C---- these values should be set in calling routines!
C
c         CAMCON(1) = 0.0
c         CAMCON(2) = 0.0 
c         CAMCON(3) = XTOFD * 0.01 
c         CAMCON(4) = 0.0
c         CAMCON(5) = -TWOTHETA 
c         CAMCON(6) = 0.0
c         CAMCON(7) = 0.0 } both used only in s/r KWBEAM to set s0. 
c         CAMCON(8) = 0.0 } 
c         LCAMCON = .TRUE.
      ICOUNT = 0
      DO 10 I=1,8
         IF(SCAMCON(I).NE.CAMCON(I))ICOUNT = ICOUNT + 1
 10   END DO
      IF(ICOUNT.GT.0)THEN
         DO 20 I=1,8
            SCAMCON(I) = CAMCON(I)
 20      END DO
         FIRSTTIME = .TRUE.
      ELSE
         FIRSTTIME = .FALSE.
      END IF
      IF(FIRSTTIME.AND.DEBUG(71))THEN
         WRITE(IOUT,FMT=1000)CAMCON
         IF(ONLINE)WRITE(ITOUT,FMT=1000)CAMCON
      END IF
 1000 FORMAT(/,1X,'CCX = ',F8.3,' CCY = ',F8.3,' XTOFD = ',F12.2,
     $     ' CCOMEGA = ',F7.2,/,1X,'TWIST (TWO-THETA swing) = ',F8.4,
     $     ' TILT = ',F8.4,/,1X,'INCLINATION ANGLES OF DIRECT BEAM = ',
     $     2F8.4)
      IF(FIRSTTIME)THEN
         CALL DDDN(CAMCON,DD,DN)
         CALL MINV33(DDINV,DD,DET)
         IF(DEBUG(29))THEN
            WRITE(IOUT,FMT=1067)DD,DDINV,DN
            IF(ONLINE)WRITE(ITOUT,FMT=1067)DD,DDINV,DN
 1067       FORMAT('DD    in PRDDET: ',9F10.5,/,'DDINV in PRDDET: ',
     $           9F10.5,/,'DN   in PRDDET: ',3F10.5)
         ENDIF
      ENDIF
C
C---- back to "original" code
C
C
C  Now we need  TS = (XR - S0) * DIST**2 / (XR.DN - S0.DN)
C               --    --   --               -- --   -- --
c
c---- scalar products of XR & DN and S0 & DN
C
      SCV1 = DOT(XR, DN)
      SCV2 = DOT(s0, DN)
C
C---- vector from S0 to XR
C
      CALL VDIFF(VSTOR1, XR, S0)
C
C---- scale it to distance
C
      RMFAC = 0.01*(XTOFD**2) / (SCV1 - SCV2)
      CALL VMSCAL(TS, VSTOR1, rmfac)
C
C  The virtual detector calculated coordinates VDCC are derived
C  by    VDCC = DDINV * TS (P. 62, 1986 LURE workshop)
C        ----   =====   --
C
      CALL MATVEC(VDCC, DDINV, TS)
c      write(iout,fmt=1066)vdcc(1),vdcc(2)
c 1066 format(2(F12.4,1X))
C
      YT = VDCC(1) + (XTOFD*TAN(BEAMMU(2))/COS(TWOTHETA*DTOR))
      XT = VDCC(2) - (XTOFD*TAN(TWOTHETA*DTOR))
C  Check if the reflection is too far from detector center:
C
         
c      TOM1 = SQRT (XT**2  +  YT**2)
c      IF (TOM1 .LE. RMAX) THEN
c         YMS = YT
c         ZMS = XT
c      ENDIF
C
C
C  See if the predicted position falls in a bad nonunformity region,
C  when non-uniformity correction is turned on,
C  If so then skip this reflection.
C
c         IF ( CHKNUF(YMS, ZMS) .NE. 0 ) IERR = 1
c      ELSE
C
c 200     IER = 1
c      endif
      RETURN
      END
