     +     NBYTE,NREC,NWORD,IYLEN,
     +     ICURR,NEXTRA,NHBYTE,BYTSWAP,LACTIVE,
     $     REALLYFORCEREAD
C&&*&& end_include  ../inc/scn.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C&&*&& include  ../inc/xy.f
C
C $Id: xy.f,v 1.1 2002/05/02 10:47:25 harry Exp $
C
C--- awk generated include file  xy.h
C---- START of include file xy.h
C
C     .. Scalars in common block /XY/ ..
      REAL XTOFD,SINV,COSV,TANV,TWOTHETA
      INTEGER ICASS
C     ..
C     .. Common Block /XY/ ..
      COMMON /XY/XTOFD,SINV,COSV,TANV,TWOTHETA,ICASS
C     ..
C
C     XTOFD....  Crystal to detector distance in 10 micron units. Read from
C                keyworded input and never changed.
C
C                Spot positions are calculated in S/R XYSPOT (Called from
C                REEK) and are for an "ideal" detector at a distance of XTOFD.
C                These are converted into pixel positions in S/R MMTOPX
C                which applies the multiplicative factor XTOFRA to allow
C                for refinement of the distance. XTOFRA is the parameter
C                that is actually refined (in RDIST), rather than XTOFD.
C                The refined distance that is printed in the logfile is
C                actually XTOFRA*XTOFD
C
C     ICASS....  Indicates detector type:
C                0     Flat film
C                1     Vee shaped cassettes
C                2     FAST detector (only used in TESTGEN mode of OSCGEN)
C                3     Swung out FAST (ditto)
C                4     IP detector
C     TWOTHETA   Detector swing angle (degrees)
C&&*&& end_include  ../inc/xy.f
C     ..
C     .. Equivalences ..
C     ..
      SAVE
      THIS = 'PREDICT'
      INDENT = 4
C
C
C---- Convert missetting angles  PsiX,Y,Z PhiX,Y,Z
C
C---- Why is this done ? If SDELPHIZ is saved from the first call, but 
C     then PHIZ is
C     changed by a large angle, this will not give the correct conversion from
C     PSI to PHI. Try using DELPHI(3)
C
CAL      IF (FIRST) THEN
CAL        SDELPHIZ = DELPHI(3)
CAL        FIRST = .FALSE.
CAL      END IF
CAL      PHIAV = (PHIBEG+PHIEND)*0.5 + SDELPHIZ
C
C---- Do NOT have to convert PSI to PHI as this has already been done in 
C     MXDSPL. If it is done again here it will give different answers,
CAL   because the first call might have changed DELPHI(3) !!
C
CAL        PHIAV = (PHIBEG+PHIEND)*0.5 + DELPHI(3)
C
C          **************************
CAL        CALL PSITOPHI(PSI,DELPHI,PHIAV)
C          **************************
C
C---- Update amat and gmat if cell params changed
C
        IMATL = 0
        IUMATL = 1
        ICELLL = 1
        ICHECK = 0
C
C            ************************
        CALL SETMAT(IMATL,IUMATL,ICELLL,ICHECK)
C            ************************
C
C
C---- Initialise RMC matrix - for the X and Y missetting angles.
C     Rotation about x and then y
C         RMC = PHIY . PHIX
C
        SX = SIN(DELPHI(1)*DTOR)
        SY = SIN(DELPHI(2)*DTOR)
        CX = COS(DELPHI(1)*DTOR)
        CY = COS(DELPHI(2)*DTOR)
C
        RMC(1,1) = CY
        RMC(1,2) = SX*SY
        RMC(1,3) = CX*SY
        RMC(2,1) = 0.0
        RMC(2,2) = CX
        RMC(2,3) = -SX
        RMC(3,1) = -SY
        RMC(3,2) = SX*CY
        RMC(3,3) = CX*CY
C
C---- Set resolution limit to the edge of the displayed area, so
C     that if working with a zoomed image it does not generate more
C     than necessary
C     Size of 
C
C---- Set distance, wavelength, theta
C
        DISTANCE = 0.01*XTOFD
        WAVELENGTH = WAVE
        THETA = TWOTHETA
        I = 0
        CALL CRESOL(I,I,DISTANCE,THETA,WAVELENGTH,RESMX1)
        CALL CRESOL(I,NYDPX,DISTANCE,THETA,WAVELENGTH,RESMX2)
        CALL CRESOL(NXDPX,I,DISTANCE,THETA,WAVELENGTH,RESMX3)
        CALL CRESOL(NXDPX,NYDPX,DISTANCE,THETA,WAVELENGTH,RESMX4)
        RESMX1 = MIN(RESMX1,RESMX2,RESMX3,RESMX4)
        RESMX1 = WAVE/RESMX1
        DSTPL = MIN(DSTMAX,RESMX1)
        DSTPL2 = DSTPL*DSTPL
        NSPOT = 0
        IF (DEBUG(86)) THEN
          WRITE(IOUT,FMT=6006) NLATTICE,IOVWORK
          IF (ONLINE) WRITE(ItOUT,FMT=6006) NLATTICE,IOVWORK
 6006     FORMAT(1X,'In PREDICT, NLATTICE=',I3,' IOVWORK=',I3)
        END IF
C
C---- If running from iMosflm, write current detector parameters
C
        IF (SOCKLO) THEN
          CALL SETDIS(ITILT,ITWIST,2)
          PXCEN = 0.01*XCEN
          PYCEN = 0.01*YCEN/YSCAL
          IF (INVERTX) PXCEN = NREC*RAST - PXCEN
          WRITE(IOUT,FMT=6008) PXCEN,PYCEN,0.01*XTOFD,YSCAL,ITILT,
     +                         ITWIST,2.0*ETA*RTOD,DELPHI,OMEGAFD
          IF (ONLINE) WRITE(ITOUT,FMT=6008) PXCEN,PYCEN,0.01*XTOFD,
     +                   YSCAL,ITILT,ITWIST,2.0*ETA*RTOD,DELPHI,OMEGAFD
 6008     FORMAT(1X,'XCEN',F7.2,' YCEN',F7.2,' Distance',F8.2,
     +           ' YSCAL',F7.4,' TILT',I3,' TWIST',I3,/,1X,' Mosaic',
     +           F5.2,' Missets',3F6.2,'  Omega',F7.1)
        END IF
C
C---- Calculate reflections present for working lattice
C
        MODERK = 1
C            ****
C
C---- Print for program flow
C
        CALLED = 'REEK'
        WRITE(COMMENT,FMT=6010) MODERK,ILATTICE
 6010   FORMAT('MODERK=',I2,' ILATTICE=',I2,' Generate spot list')
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
        CALL REEK(ITEMP,MODERK,ILATTICE)
C            ****
C
C---- Check for too many reflections predicted
C
        IF (MODERK.EQ.-1) THEN
          IFLAGPR = -1
          RETURN
        END IF
C
C---- Check for overlapping reflexions within same lattice
C
        MODEOVLP = 0
C
C---- Print for program flow
C
        CALLED = 'OVERLAP'
        WRITE(COMMENT,FMT=6012) MODEOVLP
 6012   FORMAT('MODEOVLP=',I2,' Test overlaps with this lattice')
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C              *******
        CALL OVERLAP(MODEOVLP)
C              *******
C
C
C---- Save number of reflections in primary lattice
C
          NSPOTSAVE = NSPOT
C
C---- If allowing for multiple lattices, generate the reflection lists for
C     all the other lattices being considered now.
C
          IF ((NLATTICE.LT.2).OR.(IOVWORK.LT.1)) GOTO 50
C
          DO 40 I = 1,IOVWORK
C
C---- First transfer the A matrix for this lattice
C
            ILATT = IOVLATTICE(I)
C
C---- Check that this lattice is still "active" (ie not deleted)
C
            IF (.NOT.ACTIVELATT(ILATT)) GOTO 40
C
C---- Now get the current "best" solution for this lattice
C
            ISOL = BESTSOLAR(ILATT)
            DO J =1,3
              DO K =1,3
                AMAT(J,K) = CRYSTALUBREF(J,K,ISOL,ILATT)
              ENDDO
            ENDDO
            IF (DEBUG(32)) THEN
              WRITE(IOUT,FMT=6003) ILATT,ISOL,NSPOT,NSPOTSAVE,
     +                             ((AMAT(K,J),J=1,3),K=1,3)
              IF (ONLINE) WRITE(ITOUT,FMT=6003) ILATT,ISOL,NSPOT,
     +                             NSPOTSAVE,((AMAT(K,J),J=1,3),K=1,3)
 6003         FORMAT(/,1X,'In PREDICT, calling REEK for lattice',I2,
     +        '  solution',I3,/,1X,'Current',
     +        ' total number of spots',I6,' number for first lattice',
     +        I6,/,1X,'AMAT:',/,3(3F12.8,/))
            END IF
C
C---- Now call REEK with MODE=3 so that only reflection indices
C     and coordinates are stored for this lattice
C
            MODERK = 3
C
C---- Print for program flow
C
            CALLED = 'REEK'
            WRITE(COMMENT,FMT=6014) MODERK,ILATT
 6014       FORMAT('MODERK=',I2,' Generate reflections for lattice',I2)
            IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C           **************************
            CALL REEK(ITEMP,MODERK,ILATT)
C           **************************
C
 40       CONTINUE
C
C---- All lattices have been generated, now need to flag those
C     reflections in the main lattice that are overlapped by other
C     lattices
C
          MODEOVLP = 1
C
C---- Print for program flow
C
          CALLED = 'OVERLAP'
          WRITE(COMMENT,FMT=6016) MODEOVLP
 6016     FORMAT('MODEOVLP',I2,' Test overlaps with all lattices')
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C              *******
          CALL OVERLAP(MODEOVLP)
C              *******
C
C---- Restore the original AMAT
C
C
          ISOL = BESTSOLAR(ILATTICE)
          DO J =1,3
            DO K =1,3
              AMAT(J,K) = CRYSTALUBREF(J,K,ISOL,ILATTICE)
            ENDDO
          ENDDO
          IF (DEBUG(32)) THEN
            WRITE(IOUT,FMT=6005)((AMAT(K,J),J=1,3),K=1,3)
            IF (ONLINE) WRITE(ITOUT,FMT=6005)((AMAT(K,J),J=1,3),K=1,3)
 6005       FORMAT(/,1X,'In PREDICT, restored AMAT:',/,3(3F12.8,/))
          END IF
C
C---- Reset the number of spots to those for main lattice only
C

C
 50       NSPOT = NSPOTSAVE
C
        END
c     
c     $Id: predict_spots.f,v 1.38 2019/02/28 15:35:23 andrew Exp $
c     
c     predict_spots.f
c     originally by G.Winter
c     15th May 2002
c     
c     This is a subroutine to implement the spot prediction function, so
c     that the lists of predictions can be returned to the GUI.
c     
c     Changes to allow several predictions for different lattices
c     (for multi-lattice processing) AGWL August 2012  
C
C---- PRDFLAG   If .NE.1 then CONTROL and PREDICT are called to generate
C               a new reflection list. 
C               If .EQ.1 it uses the existing reflection list but updates 
C               the spot positions using the latest refined detector parameters.
C               This is used when this S/R is called from MOSFLM after
C               detector parameter refinement, if (and only if) iMosflm sends
C               a "predict" keyword through the socket instead of "continue".
C                  
c     

      SUBROUTINE PREDICT_SPOTS(ARGC, ARGV, TYPES,VALUES,PRDFLAG,IERR)
      IMPLICIT NONE

C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
