C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C&&*&& include  ../inc/xy.f
C
C $Id: xy.f,v 1.1 2002/05/02 10:47:25 harry Exp $
C
C--- awk generated include file  xy.h
C---- START of include file xy.h
C
C     .. Scalars in common block /XY/ ..
      REAL XTOFD,SINV,COSV,TANV,TWOTHETA
      INTEGER ICASS
C     ..
C     .. Common Block /XY/ ..
      COMMON /XY/XTOFD,SINV,COSV,TANV,TWOTHETA,ICASS
C     ..
C
C     XTOFD....  Crystal to detector distance in 10 micron units. Read from
C                keyworded input and never changed.
C
C                Spot positions are calculated in S/R XYSPOT (Called from
C                REEK) and are for an "ideal" detector at a distance of XTOFD.
C                These are converted into pixel positions in S/R MMTOPX
C                which applies the multiplicative factor XTOFRA to allow
C                for refinement of the distance. XTOFRA is the parameter
C                that is actually refined (in RDIST), rather than XTOFD.
C                The refined distance that is printed in the logfile is
C                actually XTOFRA*XTOFD
C
C     ICASS....  Indicates detector type:
C                0     Flat film
C                1     Vee shaped cassettes
C                2     FAST detector (only used in TESTGEN mode of OSCGEN)
C                3     Swung out FAST (ditto)
C                4     IP detector
C     TWOTHETA   Detector swing angle (degrees)
C&&*&& end_include  ../inc/xy.f

      external predict, phitopsi, ccplwc, lenstr, setmat, printflow,
     +         control, getsepras, write_socket_length, mmtopx,
     +         write_socket_section,setdis
      integer argc, types(nargs), lenstr, PRDFLAG,IERR
      character*80 argv(nargs)
      character*1024 outline
      real values(nargs), xc, yc, xcal, ycal,XDUM
      integer  i,J,k, n_full, n_partial, n_wide, n_overlap, 
     $     MODEGSR, ixsize, iysize, IXTEMP,IYTEMP,iclose,
     $     n_latt_overlap
      real psi(3), localphiav
      integer nlat,isol,ilat,ilmat,ilumat,ilcell,ilcheck

c     things for control
      integer modectrl
      logical newgenf, genopen, firsttime, rptfirst
      integer ifirstpack
      character*80 cellstr
      character THIS*30,CALLED*30,COMMENT*100
      INTEGER INDENT,ISTEP
      REAL SIG,XINT
      INTEGER IXL(NREFLS),IYL(NREFLS)
      integer*2 full_pos(5 * nrefls)
      integer*2 partial_pos(5 * nrefls)
      integer*2 wide_pos(5 * nrefls)
      integer*2 overlap_pos(5 * nrefls)
      integer*2 latt_overlap_pos(5 * nrefls)
      
      THIS = 'PREDICT_SPOTS'
      INDENT = 3
      IERR = 0
      INVFLAG = 0
      IF(INVERTX)INVFLAG = 1
      nlat = 0
      ilat = 1
      localphiav = 0.5 * (phibeg + phiend)
      phirng = phiend - phibeg

      n_full = 0
      n_partial = 0
      n_wide = 0
      n_overlap = 0
      n_latt_overlap = 0

      call phitopsi(delphi, psi, localphiav)

c     call control to set up detector limits etc.

      modectrl = 1
C     ..
C     .. HRP 06.04.2006
C     .. I think we only need do the following if this hasn't been called 
C     .. from mosflm
C
C---- MERGELATT is TRUE if the predictions for all found lattices are to
C     be displayed superposed. This is set by keyword MERGE ON.
C     In this case, start with the prediction for the best solution for
C     the first "active" (ie not deleted) lattice. 
C     Also set IOVWORK=0, so that it does not do predictions for 
C     other lattices within PREDICT.
C
      if (mergelatt) then
        iovwork = 0
        ilat = 1
        do 1 i = 1,nlattice
          if (activelatt(I)) then
            ilat = i
            goto 3
          end if
 1      enddo
 3      isol = bestsolar(ilat)
        do 4 k=1,3,1
          do 2 j=1,3,1
            amat(j,k) = crystalubref(j,k,isol,ilat)
 2        enddo
 4      enddo
        if (debug(86)) then
          write(iout,fmt=6000) isol,ilat,nlattice,
     +             ((amat(i,j),j=1,3),i=1,3),cell,
     +             crystalubref(1,1,3,2)
          if (online) write(itout,fmt=6000)  isol,ilat,nlattice,
     +                       ((amat(i,j),j=1,3),i=1,3), cell,
     +             crystalubref(1,1,3,2)
 6000     format(/,1x,'In PREDICT_SPOTS, set up AMAT for solution',
     +           i3,' and lattice',
     +           i3,' of',I3,/,3(3f12.8,/),/,1X,'Cell:',6F10.3,
     +           /,1X,'crystalubref(1,1) for lattice 2')
        end if
C
C---- the call to CONTROL (below) uses UMAT and CELL to reconstruct
C     AMAT, so need to derive UMAT and CELL from the current AMAT first
C
        ilmat = 1
        ilumat = 0
        ilcell = 0
        ilcheck = 1
        call setmat(ilmat,ilumat,ilcell,ilcheck)
        if (debug(86)) then
          write(iout,fmt=6002) cell
          if (online) write(itout,fmt=6002) cell
 6002     format(/,1x,'After calling SETMAT in predict_spots, cell',
     +            6F10.3)
        end if
      end if

      if (debug(86)) then
        write(iout,fmt=6030) prdflag
        if (online) write(itout,fmt=6030) prdflag
 6030   format(1x,'In PREDICT_SPOTS, PRDFLAG=',I2)
      end if


      IF(PRDFLAG.NE.1)THEN
        MODECTRL = -1
        newgenf = .false.
        genopen = .false.
        firsttime = .false.
        rptfirst = .false.
        ifirstpack = 1
        cellstr = ' '
C
C---- Print for program flow
C
        CALLED = 'CONTROL'
        COMMENT = ' '
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
        call control(firsttime, ifirstpack, newgenf, genopen,
     +       rptfirst, cellstr, modectrl)
        ierr = 0
C
C---- Print for program flow
C
        CALLED = 'PREDICT'
        COMMENT = ' '
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
        call predict(psi, ierr)
        if (debug(86)) then
          write(iout,fmt=6020) ilat, nspot,
     +             crystalubref(1,1,3,2)
          if (online) write(itout,fmt=6020) ilat, nspot,
     +             crystalubref(1,1,3,2)
        end if
        IF (ISEP.EQ.0) THEN
          MODEGSR = 1
          CALL GETSEPRAS(IRAST,ISEP,IRAS,IDPACK(NIMAG),
     +         MINDTX,MINDTY,IXSEP,IYSEP,MODEGSR,IERR)
C     .. return if too many spots found
          IF(IERR.EQ.-2)RETURN
        END IF
      ENDIF
C
C---- allow any separation for simulation
C
      IF(LSIMULATE)ierr = 0
      ixsize = iras(1) - 2 * iras(4)
      iysize = iras(2) - 2 * iras(5)
      if(ixsize .eq. 0) ixsize = 5
      if(iysize .eq. 0) iysize = 5

      if(ierr .lt. 0) then
 6010    format('<?xml version="1.0"?><!DOCTYPE prediction_response>',
     $        '<prediction_response><status><code>error</code>',
     $        '<message>Prediction failed with ', i6, '</message>',
     $        '</status></prediction_response>')
         outline = ' '
         write(outline, fmt = 6010) ierr
         call write_socket_length(serverfd, lenstr(outline), outline)
         return
      end if
      if (debug(86)) then
        call setdis(ITILT,ITWIST,2)
        write(iout,fmt=6031) prdflag,nspot,mergelatt,xcor,ycor,
     +      labview,invertx,xcen,ycen,itilt,itwist,xtofra,roff,toff,
     +      ccx,ccy,yscal   
        if (online) write(itout,fmt=6031) prdflag, nspot, mergelatt,
     +      xcor,ycor,labview,invertx,xcen,ycen,itilt,itwist,xtofra,
     +      roff,toff,
     +         ccx,ccy,yscal    
 6031   format(1x,'In PREDICT_SPOTS, PRDFLAG=',I2,' nspot=',I6,
     +        '  mergelatt',L2,/,1X,'Parameters affecting simulated',
     +        ' spots file:',/,1X,'XCOR',F6.2,' YCOR',F6.2,' LABVIEW',
     +        I6,' INVERTX',L2,/,1X,' XCEN',F8.1,' YCEN',F8.1,
     +        ' TILT',I6,' TWIST',I6,' XTOFRA',F8.4,' ROFF',F6.2,
     +        ' TOFF',F6.2,/,1X,' CCX',I6,' CCY',I6,
     +        ' YSCAL ',F8.4)
      end if


C---- Compute the positions in sensible coordinates
C     xcor,ycor are set in DPSIND or DPSCHOOSE and are the shifts in 
C     direct beam coords. In a simple spot simulation run, no indexing 
C     will not have been done so they will be zero.
C
      IF (LSIMULATE)THEN
         write(ispot,fmt=7060)nrec,iylen,rast,yscal,omegafd,invflag
 7060    FORMAT(2I12,1X,F10.8,1X,2(F11.6,1X),/,I12,'           1')
         write(ispot,fmt=7080)xmm(1),ymm(1)
 7080    FORMAT(2F11.5)
         IF(SOCKLO)THEN
           ICLOSE = 0
           IF (DENSE) ICLOSE = 1
           WRITE(OUTLINE,FMT=7140)XODFILE(1:LENSTR(XODFILE)),
     $          SPTNAM(1:lenstr(sptnam)),
     $          nspot, nspot, 
     +          (IRAS(I),I=1,5)
           CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(OUTLINE),
     $          OUTLINE)
           OUTLINE = ' '
           IF (ISEP.EQ.1) WRITE(OUTLINE,FMT=7160) 0.01*IXSEP,0.01*IYSEP
           CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(OUTLINE),
     $          OUTLINE)
           OUTLINE = ' '
           WRITE(OUTLINE,FMT=7180) ICLOSE
           CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(OUTLINE),
     $          OUTLINE)
C
C---- output for new GUI, gives number of spots and location of spot file
C
C other routines send template and image number, this sends imagefile?
C
 7140    format('<?xml version="1.0"?><!DOCTYPE spot_search_response>',
     $        '<spot_search_response><status><code>ok</code></status>',
     $        '<imagefile>', a, '</imagefile>',
     $        '<spotfile>', a, '</spotfile>',
     $        '<found>',i5,'</found><used>', i5, '</used>',
     $        '<reject_xmin>    0</reject_xmin>',
     $        '<reject_xmax>    0</reject_xmax>',
     $        '<reject_ymin>    0</reject_ymin>',
     $        '<reject_ymax>    0</reject_ymax>',
     $        '<reject_separation>    0</reject_separation>',
     +        '<spot_parameter_updates>',
     +        '<raster>',5I5,'</raster>')
 7160    FORMAT('<separation>',2F5.2,'</separation>')
 7180    FORMAT('<close>',I2,'</close>',
     +        '</spot_parameter_updates>',
     $        '</spot_search_response>')
         ENDIF
      ENDIF
C
C
 10    do 1020 i = 1, nspot
         xc = xg(i) - xcor
         yc = yg(i) - ycor
         call mmtopx(xcal, ycal, xc, yc)
         ixTEMP = nint(xcal * fact)
         iyTEMP = nint(ycal * fact)
C
C---- HRP 15.02.2006 - I think these are all redundant apart from LABVIEW = 90.
C
         IF(LABVIEW.EQ.0)THEN
           IXL(I) = IXTEMP
           IYL(I) = IYTEMP
         ELSEIF(LABVIEW.EQ.270)THEN
           IXL(I) = IYLEN - IYTEMP
           IYL(I) = IXTEMP
c           print*,iytemp,ixtemp,ix(i),iy(i)
         ELSEIF(LABVIEW.EQ.180)THEN
           IXL(I) = NREC - IXTEMP
           IYL(I) = IYLEN - IYTEMP
         ELSEIF(LABVIEW.EQ.90)THEN
           IXL(I) = IYTEMP
           IYL(I) = NREC - IXTEMP
         ENDIF
         IF(.NOT.INVERTX)IYL(I) = NREC - IYL(I)
         IF(LSIMULATE)THEN
C
C---- Vary intensities from 5 to 50 sigma to allow threshold
C     tests to be applied in iMosflm
C
           SIG = 100
           ISTEP = I - (I/10)*10
           IF (ISTEP.EQ.0) ISTEP = 10
           XINT = 5*ISTEP*SIG
           write(ispot,fmt=7040)
     $          real(iyl(i))*rast,real(ixl(i))*rast,
     $          localphiav,XINT,SIG
 7040      FORMAT(1X,2F10.2,'    0.500',F9.3,F12.1,F10.1)
         ENDIF
C
C---- For merged prediction of all lattices, set all reflections for one
C     lattice to the same type: 
C     full, partial, overlap and wide for lattices 1-4
C     ie blue, yellow, red, green, magenta
C
         if (mergelatt) then
           if (ilat.eq.1) then
             irg(i) = 0
           else if (ilat.eq.2) then
             irg(i) = 100
           else if (ilat.eq.3) then
             irg(i) = 2
           else if (ilat.eq.4) then
             irg(i) = 3
           else if (ilat.eq.5) then
             irg(i) = 5
           end if
         end if
         if (irg(i) .gt. 20) then
            partial_pos(5 * n_partial + 1) = iyl(i)
            partial_pos(5 * n_partial + 2) = ixl(i)
            PARTIAL_POS(5 * N_PARTIAL + 3) = IHG(I)
            PARTIAL_POS(5 * N_PARTIAL + 4) = IKG(I)
            PARTIAL_POS(5 * N_PARTIAL + 5) = ILG(I)
            n_partial = n_partial + 1
         else if(irg(i) .eq. 0) then
            full_pos(5 * n_full + 1) = iyl(i)
            full_pos(5 * n_full + 2) = ixl(i)
            FULL_POS(5 * N_FULL + 3) = IHG(I)
            FULL_POS(5 * N_FULL + 4) = IKG(I)
            FULL_POS(5 * N_FULL + 5) = ILG(I)
            n_full = n_full + 1
C
C---- Overlaps
C
         else if(irg(i) .eq. 2) then
            overlap_pos(5 * n_overlap + 1) = iyl(i)
            overlap_pos(5 * n_overlap + 2) = ixl(i)
            OVERLAP_POS(5 * N_OVERLAP + 3) = IHG(I)
            OVERLAP_POS(5 * N_OVERLAP + 4) = IKG(I)
            OVERLAP_POS(5 * N_OVERLAP + 5) = ILG(I)
            n_overlap = n_overlap + 1
C
C---- Overlapped by another lattice
C
         else if(irg(i) .eq. 5) then
            latt_overlap_pos(5 * n_latt_overlap + 1) = iyl(i)
            latt_overlap_pos(5 * n_latt_overlap + 2) = ixl(i)
            latt_OVERLAP_POS(5 * N_latt_OVERLAP + 3) = IHG(I)
            latt_OVERLAP_POS(5 * N_latt_OVERLAP + 4) = IKG(I)
            latt_OVERLAP_POS(5 * N_latt_OVERLAP + 5) = ILG(I)
            n_latt_overlap = n_latt_overlap + 1
         else if(irg(i) .eq. 3) then
            wide_pos(5 * n_wide + 1) = iyl(i)
            wide_pos(5 * n_wide + 2) = ixl(i)
            WIDE_POS(5 * N_WIDE + 3) = IHG(I)
            WIDE_POS(5 * N_WIDE + 4) = IKG(I)
            WIDE_POS(5 * N_WIDE + 5) = ILG(I)
            n_wide = n_wide + 1
         end if
 1020  end do
C
C---- If merging lattices, return to predict next lattice if not last.
C
C
C---- If merging predictions for several lattices, 
C     to generate reflection list for the next lattice. 
C     First set up the required AMAT for the next "active" lattice
C
 11   if ((mergelatt).and.(ilat.lt.nlattice)) then
        ilat = ilat + 1
        if (activelatt(ilat)) then
          isol = bestsolar(ilat)
          ierr = 0
          do 14 k=1,3,1
            do 12 j=1,3,1
              amat(j,k) = crystalubref(j,k,isol,ilat)
 12          enddo
 14       enddo
          if (debug(86)) then
            write(iout,fmt=6004) isol,ilat,nlattice,
     +             ((amat(i,j),j=1,3),i=1,3)
            if (online) write(itout,fmt=6004)  isol,ilat,nlattice,
     +                       ((amat(i,j),j=1,3),i=1,3)
 6004       format(/,1x,'In PREDICT_SPOTS, about to generate the next',
     +           ' lattice as MERGE is on.',/,1X,
     +           'Set up AMAT for solution',i3,' and lattice',
     +           i3,' of',I3,/,3(3f12.8,/))
          end if
C
C---- the call to PREDICT (below) uses UMAT and CELL to reconstruct
C     AMAT, so need to derive UMAT and CELL from the current AMAT first
C
          ilmat = 1
          ilumat = 0
          ilcell = 0
          ilcheck = 1
          call setmat(ilmat,ilumat,ilcell,ilcheck)
          if (debug(86)) then
            write(iout,fmt=6002) cell
            if (online) write(itout,fmt=6002) cell
          end if
C
C---- Print for program flow
C
          CALLED = 'PREDICT'
          COMMENT = ' '
          IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
          call predict(psi, ierr)
C
          if (debug(86)) then
            write(iout,fmt=6020) ilat, nspot,
     +             crystalubref(1,1,3,2)
            if (online) write(itout,fmt=6020) ilat, nspot,
     +             crystalubref(1,1,3,2)
 6020       format(/,1X,'In predict_spots,for lattice',I3,' NSPOT=',I5,
     +             /,1X,'crystalubref(1,1) for lattice 2',F10.8)
          end if
          goto 10
        else
          ilat = ilat + 1
          if (debug(86)) then
            write(iout,fmt=6022) ilat-1, ilat
            if (online) write(itout,fmt=6022) ilat-1,ilat
 6022       format(/,1X,'In predict_spots, lattice',I3,' not active',
     +             ' so try lattice',I3)
          end if
          goto 11
        end if
      end if

C----Write terminator for spots file
C
      IF (LSIMULATE)THEN
         XDUM = -999.0
         write(ispot,fmt=7100)XDUM,XDUM,XDUM,XDUM,XDUM,XDUM
 7100     FORMAT(1X,2F10.2,F9.3,F9.3,F12.1,F10.1)
         write(ispot,fmt=7120)nrec,iylen,rast,invflag
 7120    FORMAT(1X,2I6,f10.4,i5)
         
      ENDIF
      WRITE(IOUT,FMT=6100) n_full,n_partial,n_wide,n_overlap
      IF (ONLINE) WRITE(ITOUT,FMT=6100) n_full,n_partial,n_wide,
     +                                  n_overlap
 6100 format(1x,'Predicted reflections',/,1X,'Fulls    ',I6,/,1X,
     +       'Partials',I6,/,1X,'Too wide',I6,/,1X,'Overlaps',I6)
      IF (SOCKLO.AND.(.NOT.LSIMULATE)) THEN
         outline = ' '
         write(outline, fmt = 6040) ixsize, iysize
         call write_socket_section(serverfd, lenstr(outline),outline)
 6040    format('<?xml version="1.0"?><!DOCTYPE prediction_response>',
     $        '<prediction_response><status><code>ok</code>',
     $        '</status><prediction_size><width>', i4, 
     $        '</width><height>', i4, '</height></prediction_size>',
     $        '<boxes>')
C     ..
C     .. write fulls
         WRITE(OUTLINE,FMT=6060)
 6060    FORMAT('<fulls>')
         CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(OUTLINE), OUTLINE)
         DO 200 I = 1,N_FULL-1,1
           WRITE(OUTLINE,FMT=6080)
     $          (FULL_POS(J),J=((I-1)*5)+1,((I-1)*5)+5)
           CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(OUTLINE), OUTLINE)
 200     ENDDO
C     ..
C     .. write partials
 6080    FORMAT(2I8,3I6)
         WRITE(OUTLINE,FMT=6082)
         CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(OUTLINE), OUTLINE)
 6082    FORMAT('</fulls><partials>')
         DO 220 I = 1,N_PARTIAL-1,1
           WRITE(OUTLINE,FMT=6080)
     $          (PARTIAL_POS(J),J=((I-1)*5)+1,((I-1)*5)+5)
           CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(OUTLINE), OUTLINE)
 220     ENDDO
C     ..
C     .. write too wides
         WRITE(OUTLINE,FMT=6084)
         CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(OUTLINE), OUTLINE)
 6084    FORMAT('</partials><wide>')
         DO 240 I = 1,N_WIDE-1,1
           WRITE(OUTLINE,FMT=6080)
     $          (WIDE_POS(J),J=((I-1)*5)+1,((I-1)*5)+5)
           CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(OUTLINE), OUTLINE)
 240     ENDDO
C     ..
C     .. write overlaps
         WRITE(OUTLINE,FMT=6086)
         CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(OUTLINE), OUTLINE)
 6086    FORMAT('</wide><overlaps>')
         DO 260 I = 1,N_OVERLAP-1,1
           WRITE(OUTLINE,FMT=6080)
     $          (OVERLAP_POS(J),J=((I-1)*5)+1,((I-1)*5)+5)
           CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(OUTLINE), OUTLINE)
 260     ENDDO
C     ..
C     .. write lattice overlaps
         WRITE(OUTLINE,FMT=6088)
         CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(OUTLINE), OUTLINE)
 6088    FORMAT('</overlaps><lattice_overlaps>')
         DO 280 I = 1,N_LATT_OVERLAP-1,1
           WRITE(OUTLINE,FMT=6080)
     $          (LATT_OVERLAP_POS(J),J=((I-1)*5)+1,((I-1)*5)+5)
           CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(OUTLINE), OUTLINE)
 280     ENDDO
         WRITE(OUTLINE,FMT=6090)
         CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(OUTLINE), OUTLINE)
 6090    FORMAT('</lattice_overlaps></boxes></prediction_response>')
         
      END IF

      RETURN

      END
      SUBROUTINE PRINTFLOW(CALLINGSR,CALLEDSR,COMMENT,INDENT)
C     =======================================================
C
      IMPLICIT NONE
C
C---- Print out statements to help follow program flow
C
C     .. Parameters ..
C
C     ..
C     .. Scalar Arguments ..
      CHARACTER CALLINGSR*30,CALLEDSR*30,COMMENT*100
      INTEGER INDENT
C     ..
C     .. Array Arguments ..
C     ..
C     .. Local Scalars ..
      CHARACTER STR*40, STR2*20, LINE*120
C     ..
C     .. Local Arrays ..
C     ..
C     .. External Functions ..
      INTEGER LENSTR
      EXTERNAL LENSTR
C     ..
C     .. External Subroutines ..
C     ..
C     .. Intrinsic Functions ..
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C     ..
C     .. Equivalences ..
      SAVE
C     ..
C     .. Data ..
C     ..
C
      STR = ' '
      IF (INDENT.EQ.1) THEN
        STR = '-----'
      ELSE IF (INDENT.EQ.2) THEN
        STR = '----------'
      ELSE IF (INDENT.EQ.3) THEN
        STR = '---------------'
      ELSE IF (INDENT.EQ.4) THEN
        STR = '--------------------'
      ELSE IF (INDENT.GE.5) THEN
        STR = '-------------------------'
      ENDIF
C
C---- Decide whether this is a comment or a call to a S/R. The former
C     is denoted by the string "***" as the first 3 characters of COMMENT
C
      IF (COMMENT(1:3).EQ.'***') THEN
        STR2 = 'Comment is:'
      ELSE
        STR2 = 'Calling'
      END IF
      LINE = STR(1:LENSTR(STR))//'FLOW: From '//
     +          CALLINGSR(1:LENSTR(CALLINGSR))//' '//
     +  STR2(1:LENSTR(STR2))//' '//CALLEDSR(1:LENSTR(CALLEDSR))//
     +  ' '//COMMENT(1:LENSTR(COMMENT))
      WRITE(IOUT,FMT=1000) LINE(1:LENSTR(LINE))
      IF (ONLINE) WRITE(ITOUT,FMT=1000) LINE(1:LENSTR(LINE))
 1000 FORMAT(/,1X,A)
      RETURN
      END
C== PRINTSTATS ==
C
      SUBROUTINE PRINTSTATS(IPACK)
C     ============================
C
      IMPLICIT NONE
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
