C&&*&& end_include  ../inc/ioo.f
C&&*&& include  ../inc/lmb.f
C
C $Id: lmb.f,v 1.17 2021/03/30 09:16:05 andrew Exp $
C
C--- awk generated include file  lmb.h
C---- START of include file lmb.h
C ODSCAL is to scale image numbers into the range 0-255 for plotting
C average profiles.
C  GAIN should be equal to the overall gain (image counts per X-ray photon)
C of the system, and is used to evaluate standard deviations based on
C counting statistics assuming independent pixels (ie point spread function
C less than pixel size).
C INVERTX true if image is inverted in the slow (X) direction when read in.
C ISCAL is to scale final integrated intensities and sigmas
C IDIVIDE is the adc offset
C ICONST is a constant to be added to all pixels (normally zero) to
C        allow processing of images with zero pixel values in the scanned
C        area.
C IMGP is true if working with image plate data
C SPIRAL is true for scanners with a spiral readout (Mar, DIP2000)
C ORTHOG is true for scanners with orthogonal scan (FUJI, RAXIS, MD)
C NULLPIX is the value of pixels within the image but not in the active
C area of the detector
C TILED is true if there are inactive areas of the detector within the
C       inscribing circle or square.
C
C NTILEX Number of tiles in X direction
C NTILEY Number of tiles in Y direction
C TILEX  X Coordinates of the midpoints of the null areas between tiles
C TILEY  Y Coordinates of the midpoints of the null areas between tiles
C TILEWX Width of the null areas between tiles in X
C TILEWY Width of the null areas between tiles in Y


C MACHINE and MODEL denote the type of detector.
C DECTRIS_TYPE can be PILATUS, EIGER1 or EIGER2. It is used when setting up
C the positions of the gaps between the tiles.
C
C MACHINE is used in the following subroutines:
C GETBLK, GETHDR, INTPXL, INTPXL2, MXDSPL, OPENODS, PROCESS, PUTPXL
C Currently coded types are:
C
C         MACHINE        MODEL               COMMENTS
C         =======        =====               ========
C         MAR            180, 300, 345
C         RAXI(S)        RAXISII, RAXISIV
C         MD
C         FUJI
C         CCD1           CCD1                Princetown CCD at CHESS,Tiff format
C         CCD2           CCD ?               ESRF CCD detector
C         ADSC           QUAD1               ADSC 2x2 CCD detector
C
C TRUSTED whether or not the image header information can be trusted for 
C         automatic processing
C MICROED indicates whether or not this is electron diffraction data,
C        base on the wavelength being less than 0.05A
C
C
C     .. Scalars in Common Block /LMB/ ..
        REAL ODSCAL,GAIN,LOGA,LOGB
        INTEGER ISCAL,IDIVIDE,ICONST,NULLPIX,NTILEX,NTILEY,
     $       RAXISCOMP,IIDIVIDE,COMPRESSION,GAPVAL,IINVERTX
        LOGICAL IMGP,INVERTX,SPIRAL,ORTHOG,CIRCULAR,TILED,SETADC,
     $       NEWRAXIS,BRUKNEW,TRUSTED,MINICBF,HDF5FILE,GAPMASK,
     $       WRONGGAPVALUE,MICROED
        CHARACTER MACHINE*4,MODEL*8,LDETECTOR*20,DECTRIS_TYPE*10,
     +       CMACHINE*40

C     ..
C     .. Arrays in common /LMB/
        INTEGER TILEX,TILEY,TILEWX,TILEWY
C
C     .. Common Block /LMB/ ..
        COMMON /LMB/ ODSCAL,GAIN,LOGA,LOGB,ISCAL,IDIVIDE,ICONST,
     $       NULLPIX,NTILEX,NTILEY,RAXISCOMP,IIDIVIDE,COMPRESSION,
     $       GAPVAL,IINVERTX,TILEX(20),TILEY(20),TILEWX(20),TILEWY(20),
     $       IMGP,INVERTX,SPIRAL,ORTHOG,CIRCULAR,
     $       TILED,SETADC,NEWRAXIS,BRUKNEW,TRUSTED,MINICBF,HDF5FILE,
     $       GAPMASK,WRONGGAPVALUE,MICROED
        COMMON /LMBC/ MACHINE,MODEL,LDETECTOR,DECTRIS_TYPE,CMACHINE

C&&*&& end_include  ../inc/lmb.f
C
C     .. Equivalences ..
C
      SAVE            
C     ..
C
C                                         
      NXX = LRAS(1)
      NYY = LRAS(2)
      NXY = NXX*NYY                         
      HX = NXX/2
      HY = NYY/2
C
C---- Set up mask which allows for rejected background points
C
C
      DO 2 I = 1,NXY
        LMASK(I) = MASK(I)
 2    CONTINUE
C
      NBREJ = MASKREJ(1)
      DO 4 N = 1,NBREJ
        IJ = MASKREJ(N+1)
        LMASK(IJ) = 0
 4    CONTINUE
C
C---- Now find average value of profile in the background
C
      IJ = 0
      N = 0
      WSUMB = 0.0
      DO 8 P = -HX,HX
        DO 6 Q = -HY,HY
          IJ = IJ + 1
C
C---- Form sums for whole box except rejected background pixels
C
          IF (LMASK(IJ).LT.0) THEN
            IOD = IPROFL(IJ)
            WSUMB = WSUMB + IOD
            N = N + 1
          END IF
 6      CONTINUE
   8  CONTINUE
C
C
      IF (N.NE.0) WSUMB = WSUMB/REAL(N)
      ISUMB = NINT(WSUMB)
C      WRITE(6,*),'Mean value over background pixels',ISUMB
C      WRITE(6,*),'NUMBER OF BACKGROUND PIXELS',N
C
C---- Subtract this average value from all pixels
C 
      DO 9 I = 1,NXY
        IPROFL(I) = IPROFL(I)
 9    CONTINUE
C
C---- Set up mask where only rejected background pixels are flagged for 
C     rejection
C
C
      DO 10 I = 1,NXY
        LMASK(I) = 1
 10   CONTINUE
C
      NBREJ = MASKREJ(1)
      DO 20 N = 1,NBREJ
        IJ = MASKREJ(N+1)
        LMASK(IJ) = 0
  20  CONTINUE
C
      IJ = 0
      SUMPP = 0.
      SUMQP = 0.
      SUMP = 0.
      SUMPSQ = 0.
      WSUMPP = 0.
      WSUMQP = 0.
      WSUMP = 0.
      WSUMPSQ = 0.
      NLOWPK = 0
      DO 40 P = -HX,HX
        DO 30 Q = -HY,HY
          IJ = IJ + 1
C
C---- Form sums for peak area whole box except rejected background pixels
C
          IF (MASK(IJ).GT.0) THEN
            IOD = IPROFL(IJ)
            SUMP = SUMP + IOD
            SUMPSQ = IOD*IOD + SUMPSQ
            SUMPP = P*IOD + SUMPP
            SUMQP = Q*IOD + SUMQP
C
C---- Count number of peak pixels with a profile value less than
C     5% of maximum value (10000)
C
            IF (IOD.LT.500) NLOWPK = NLOWPK + 1
          END IF
          IF (LMASK(IJ).GT.0) THEN
            IOD = IPROFL(IJ)
            WSUMP = WSUMP + IOD
            WSUMPSQ = IOD*IOD + WSUMPSQ
            WSUMPP = P*IOD + WSUMPP
            WSUMQP = Q*IOD + WSUMQP
          END IF
   30   CONTINUE
   40 CONTINUE
C
      PROFSUMS(1) = SUMPP
      PROFSUMS(2) = SUMQP
      PROFSUMS(3) = SUMP
      PROFSUMS(4) = SUMPSQ
      WPROFSUMS(1) = WSUMPP
      WPROFSUMS(2) = WSUMQP
      WPROFSUMS(3) = WSUMP
      WPROFSUMS(4) = WSUMPSQ
C
      RETURN
      END
C $Id: prweight.f,v 1.7 2007/09/18 12:22:31 harry Exp $
C== PRWEIGHT ==
      SUBROUTINE PRWEIGHT(NVBOX,IPRNUM,XYR,XCV,YCV,WTPR)
      IMPLICIT NONE
C
C---- Determines the weights WTPR for the NVBOX contributing profiles for
C     reflection with coordinates XYR. XCV,YCV are coordinates of the
C     vertices.
C     ..
C     .. Scalar Arguments ..
      INTEGER NVBOX
C     ..
C     .. Array Arguments ..
      INTEGER IPRNUM(9)
      REAL XYR(2),XCV(4),YCV(4),WTPR(9)
C     ..           
C     .. Local Scalars ..
      INTEGER IMISS,IV,I1,I2,I3,II1,MULT
      REAL XR,YR,DELX4R,DELXR1,DELX3R,DELXR2,DELX41,DELX32,RX1,RX2,
     +     RX3,RX4,YA,YB,DELYBA,DELYBR,DELYRA,RY1,RY2,WI1,WI2,WI3,RX,RY,
     +     DELX21,DELY21,DELYR1,DELY31
      CHARACTER CALLEDFROM*80
C     ..
C     .. Local Arrays ..
      INTEGER INDEX(3,4)
C     ..
C     .. External Functions ..
      INTEGER LENSTR
      EXTERNAL LENSTR
C     ..                            
C     .. External Subroutines ..
      EXTERNAL SHUTDOWN
C     ..
C     .. Intrinsic Functions ..
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C     ..
C     .. Data statements
C
       DATA INDEX/3,2,4,4,1,3,1,4,2,2,3,1/
        CALLEDFROM = 'PRWEIGHT'
      XR = XYR(1)
      YR = XYR(2)
      IF (NVBOX.EQ.3) GOTO 20
      IF (NVBOX.EQ.2) GOTO 40
      IF (NVBOX.EQ.1) GOTO 60
C
C---- General case, all four profiles are real
C
      DELX4R = XCV(4) - XR
      DELXR1 = XR - XCV(1)
      DELX3R = XCV(3) - XR
      DELXR2 = XR - XCV(2)
      DELX41 = XCV(4) - XCV(1)      
      DELX32 = XCV(3) - XCV(2)
C
C--- When one of the profiles is the central one, its coordinates are
C    variable and can end up the same as the adjacent profile !
C
      IF (ABS(DELX41).GT.0.01) THEN
        RX1 = DELX4R/DELX41
        RX2 = DELXR1/DELX41
      ELSE
        RX1 = 0.5
        RX2 = 0.5
      END IF
      IF (ABS(DELX32).GT.0.01) THEN
        RX3 = DELX3R/DELX32
        RX4 = DELXR2/DELX32
      ELSE
        RX3 = 0.5
        RX4 = 0.5
      END IF
      YA = YCV(1)*RX1 + YCV(4)*RX2
      YB = YCV(2)*RX3+ YCV(3)*RX4
      DELYBA = YB - YA      
      DELYBR = YB - YR
      DELYRA = YR - YA 
      IF (ABS(DELYBA).GT.0.01) THEN
        RY1 = DELYBR/DELYBA
        RY2 = DELYRA/DELYBA
      ELSE
        RY1 = 0.5
        RY2 = 0.5
      END IF
      WTPR(1) = RX1*RY1
      WTPR(2) = RX3*RY2
      WTPR(3) = RX4*RY2
      WTPR(4) = RX2*RY1
      RETURN
C
C---- Now deal with 3 profile case
C
C
C---- First find which profile is missing
C
 20   IMISS = 0
      DO 25 IV = 1,4
        IF (IPRNUM(IV).LT.0) IMISS = IV
 25   CONTINUE
C       WRITE(6,*),'MISSING BOX',IMISS
      IF (IMISS.EQ.0) THEN
      WRITE(6,*)'ERROR, CANT FIND MISSING BOX'
      NSHUTERR = 1
      CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
      END IF
C
C---- Set up for this box missing
C
      I1 = INDEX(1,IMISS)
      I2 = INDEX(2,IMISS)
      I3 = INDEX(3,IMISS)
C       WRITE(6,*),'I1,I2,I3',I1,I2,I3
      DELXR1 = XR - XCV(I1)
      DELX21 = XCV(I2) - XCV(I1)
      DELYR1 = YR - YCV(I1)
      DELY31 = YCV(I3) - YCV(I1)
      RX = DELXR1/DELX21
      RY = DELYR1/DELY31
      WI1 = 1 - RX - RY
      WI2 = RX
      WI3 = RY
C
C---- Now given IMISS, need to know which number is WI1      
C
      WTPR(INDEX(1,IMISS)) = WI1
      WTPR(INDEX(2,IMISS)) = WI2
      WTPR(INDEX(3,IMISS)) = WI3
      WTPR(IMISS) = 0.0
      RETURN
C---- Now deal with 2 profile case
C     Possible combinations are 1+2, 2+3, 3+4, 4+1. Find which we have
C     I1 and I2 are the two vertices present
C
 40   MULT = 1
      DO 42 IV = 1,4
        IF(IPRNUM(IV).GT.0) MULT = MULT*IV
        WTPR(IV) = 0.0
 42   CONTINUE
C
      IF (MULT.EQ.2) THEN
        I1 = 1
      ELSE IF (MULT.EQ.6) THEN
        I1 = 2
      ELSE IF (MULT.EQ.12) THEN
        I1 = 3
      ELSE
        I1 = 4
      END IF
C
      I2 = I1 + 1
      IF (I2.GT.4) I2 = 1
      II1 = MOD(I1,2) - 1
      DELXR1 = XR - XCV(I1)
      DELX21 = XCV(I2) - XCV(I1)
      DELYR1 = YR - YCV(I1)
      DELY21 = YCV(I2) - YCV(I1)
      RX = 0.0
      RY = 0.0
C
C---- Test II1 to avoid divide by zero
C
      IF (II1.NE.0) THEN
        RX = DELXR1/DELX21
      ELSE
        RY = DELYR1/DELY21
      END IF
      WTPR(I1) = 1.0 - RX - RY
      WTPR(I2) = RX + RY
      RETURN
C
C---- Now the one profile case...find which one is present
C
 60   DO 62 IV = 1,4
        IF (IPRNUM(IV).GT.0) THEN
          WTPR(IV) = 1.0
        ELSE
          WTPR(IV) = 0.0
        END IF
 62   CONTINUE
      END
C $Id: psitophi.f,v 1.4 2007/12/18 14:55:49 harry Exp $
C== PSITOPHI ==
C
C
C
      SUBROUTINE PSITOPHI(PSI,PHI,PH)
      IMPLICIT NONE
C     ===============================
C
C
C---- Convert PSIX,PSIY,PSIZ to PHIX,PHIY,PHIZ at angle PH
C      Angles in degrees
C
C
C
C     .. Scalar Arguments ..
      REAL PH
C     ..
C     .. Array Arguments ..
      REAL PHI(3),PSI(3)
C     ..
C     .. Local Scalars ..
      DOUBLE PRECISION CP,CP1,CP2,CP3,CPX,CPY,CPZ,P11,P21,PHIX,PHIY,
     $     PHIZ,SP,SP1,SP2,
     +     SP3,SPX,SPY,SPZ
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC ATAN2,COS,SIN
C     ..
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C
C
      CPX = COS(DTOR_DOUBLE * DBLE(PSI(1)))
      CPY = COS(DTOR_DOUBLE * DBLE(PSI(2)))
      CPZ = COS(DTOR_DOUBLE * DBLE(PSI(3)))
      SPX = SIN(DTOR_DOUBLE * DBLE(PSI(1)))
      SPY = SIN(DTOR_DOUBLE * DBLE(PSI(2)))
      SPZ = SIN(DTOR_DOUBLE * DBLE(PSI(3)))
      CP = COS(DTOR_DOUBLE * DBLE(PH))
      SP = SIN(DTOR_DOUBLE * DBLE(PH))
C
C---- Calculate phix
C
C      SP1 = CPY*SPX*CP + SPY*SP
C      CP1 = CPY*CPX
      PHIX = ATAN2((CPY*SPX*CP + SPY*SP),(CPY*CPX))
C
C---- Calculate phiy
C
C      SP2 = -CPY*SPX*SP + SPY*CP
C      CP2 = CPY*CPX/COS(PHIX)
      PHIY = ATAN2((-CPY*SPX*SP + SPY*CP),(CPY*CPX/COS(PHIX)))
C
C---- Calculate phiz
C
      P11 = (CPZ*SPY*SPX-SPZ*CPX)*SP + CPZ*CPY*CP
      P21 = (SPZ*SPY*SPX+CPZ*CPX)*SP + SPZ*CPY*CP
      SP3 = -SP*P11 + CP*P21
      CP3 = CP*P11 + SP*P21
      PHIZ = ATAN2(SP3,CP3)
C
      PHI(1) = REAL(PHIX * RTOD_DOUBLE)
      PHI(2) = REAL(PHIY * RTOD_DOUBLE)
      PHI(3) = REAL(PHIZ * RTOD_DOUBLE)
C
C
      RETURN
      END
