      IF ((MODE.GT.0).AND.(MODE.LT.10)) THEN
        DO 2 I = IYCEN + IRMIN,IYCEN + IRMAX,ISTEP
          II = ABS(I - IYCEN)
          BGOD(II) = NINT((SIGAV(II)*LTHRESH)+AVBG(II))
 2      CONTINUE
        RETURN
      END IF
