        N = 0
        SUM = 0
        NRJ = 0
   10   CONTINUE
C
C---- Loop over NPIXBG pixels
C
        DO 20 J = 1,NPIXBG
C
          IBA = INTPXL(IVAL(J))
CAL          IF (J.LT.60) WRITE(6,*),'I,J,IBA',I,J,IBA
C
          IF (FIRST) THEN
            N = N + 1
            PIX(N) = IBA
          ELSE
Cal              if (iba.le.(AVBG(ii)+sigav(ii)*2))then
C
C---- Check if too big, ie probably spot
C
            IF ((IBA.LE.(AVBG(II)+SIGAV(II)*1.5)).AND.
