C     because all the new lower values are rejected !
C
C     To try to deal with the original problem, compare with the average
C     for the current strip rather than the previous one.
C
CAL              IF((AVBG(II-1).GT.0).and.(SIGAV(II-1).GT.0).AND.
CAL     $             (IBA.LT.(AVBG(II-1)-SIGAV(II-1)*6)))THEN
CAL                IBA = AVBG(II-1)
CAL              ENDIF
              IF((AVBG(II).GT.0).and.(SIGAV(II).GT.0).AND.
     $             (IBA.LT.(AVBG(II)-SIGAV(II)*6)))THEN
                IBA = AVBG(II)
              ENDIF
              SUM = SUM + IBA
              N = N + 1
            ELSE
              NRJ = NRJ + 1
            END IF
          END IF
   20   CONTINUE
C
C
        IF (FIRST) THEN
C
C---- Sort pixel values into ascending order
C
C              ********************
          CALL SORTUP4(NPIXBG,PIX,IS)
C              ********************
C
C---- Set the background to the mean of the NPIXBG/3 smallest values,
C     excluding zeros
C
          NBACK = 0
          SUM = 0.0
C
C
          DO 30 J = 1,NPIXBG
            IBA = PIX(IS(J))
            IF (IBA.LE.NULLPIX) GO TO 30
            NBACK = NBACK + 1
            SUM = SUM + IBA
            IF (NBACK.GE.NPIXBG/3) GO TO 40
   30     CONTINUE
C
C
          IF (LPRNT) WRITE (IOUT,FMT=6002) NPIXBG/3,NULLPIX,II*RAST
          IF (ONLINE.AND.LPRNT) WRITE (ITOUT,FMT=6002) NPIXBG/3,NULLPIX,
     +                          II*RAST
 6002     FORMAT (1X,'** WARNING **',/1X,'Fewer than',I3,' pixels with',
     +           ' values greater than',I5,' (keyword NULLPIX) at a ',
     +           'radius of',F6.2,'mm')
CAL          IERR = II
CAL          RETURN
          IF (NBACK.EQ.0) THEN
            SUM = 1.0
            NBACK = 1
          END IF
C
   40     AVBG(II) = SUM/NBACK
CAL          WRITE(6,*),'average of first',AVBG(ii)
        ELSE
CAL          WRITE(6,*),'n,sum',n,sum
          IF (N.EQ.0) THEN
C
C---- When no accepted pixels, set AV to value from previous stripe
C
            IF (II.GT.1) AVBG(II) = AVBG(II-1)
          ELSE
C
C---- Average background
C
            AVBG(II) = SUM/N
          END IF
        END IF
        DEL = (REAL(AVBG(II))-IDIVIDE)
        IF (DEL.LE.0) DEL = 1.0
        SIGAV(II) = SQRT(GAIN*DEL)
        SIGAV(II) = MAX(SIGAV(II),1.0)
C
        IF (DEBUG(61)) THEN
          WRITE(IOUT,FMT=6003) II,AVBG(II),SIGAV(II)
          IF (ONLINE) WRITE(ITOUT,FMT=6003) II,AVBG(II),SIGAV(II)
 6003     FORMAT(1X,'Strip',I5,' average',I7,' sigma',F7.0)
        END IF
C           WRITE(6,*),'ii,av,sig',ii,AVBG(ii),sigav(ii)
C
C
        IF (FIRST) THEN
C             WRITE(IOUT,2222) PIX
 6004     FORMAT (1X,11I6)
          FIRST = .FALSE.
          SUM = 0
          N = 0
          NRJ = 0
          NRJLAST = 0
          GO TO 10
        ELSE
C
C---- At end, calculate threshold for plot
C
          IF (NRJ.EQ.NRJLAST) THEN
C
C                WRITE(6,*),'ii, final av,sig',ii,AVBG(ii),sigav(ii)
C
            BGOD(II) = NINT((SIGAV(II)*LTHRESH)+AVBG(II))
            NREJ(II) = NRJ
C             WRITE(6,*),'II,LTHRESH,NREJ',ii,bgod(ii),nrej(ii)
          ELSE
            SUM = 0.0
            N = 0
            NRJLAST = NRJ
            NRJ = 0
            GO TO 10
          END IF
        END IF
      MEANBG = MEANBG + BGOD(II)
   50 CONTINUE
      IF (LLPRNT) WRITE (IOUT,FMT=6006)
 6006 FORMAT (1X,'Radial Background calculation complete')

      MEANBG = MEANBG/II
      DO 52 I = 1,IIMIN-1
         BGOD(I) = BGOD(IIMIN)
 52   CONTINUE
C      IF (PRINT) THEN
C
C---- Find average over 4 pixels at a time
C
      NPT = 0
      SIGAVG = 0.0
C
C---- Loop over strips
C
      ISTEP = 4
      IF (IRMAX.LT.0) ISTEP = -4
      DO 60 I = IYCEN + IRMIN,IYCEN + IRMAX,ISTEP
        NPT = NPT + 1
        II =ABS(I - IYCEN)
        IBGAV(NPT) = (AVBG(II+1)+AVBG(II)+AVBG(II+2)+AVBG(II+3))*0.25
        FBGAV(NPT) = (REAL(AVBG(II+1)+AVBG(II)+AVBG(II+2)+AVBG(II+3)))
     $       * 0.25
        ISIGBGAV(NPT) = (SIGAV(II+1)+SIGAV(II)+SIGAV(II+2)+SIGAV(II+3))*
     +                  0.25
        FSIGBGAV(NPT) = (SIGAV(II+1)+SIGAV(II)+SIGAV(II+2)+SIGAV(II+3))*
     +                  0.25
        SIGAVG = SIGAVG + FSIGBGAV(NPT)
C
C---- Note, minimum value of SIGMA for background is set to 2
C
        ISIGBGAV(NPT) = MAX(ISIGBGAV(NPT),2)
        RAD(NPT) = II*RAST
C
C---- calculate resolution for BEST ---- only for twotheta swing = 0 at
C     the moment
C
        RESRAD(NPT) = WAVE/(2.0*SIN(0.5*ATAN2(RAD(NPT)*100.0,XTOFD)))
        NREJAV(NPT) = (NREJ(II+1)+NREJ(II)+NREJ(II+2)+NREJ(II+3))*0.25
   60 CONTINUE
C
      IF (NPT.GT.0) SIGAVG = SIGAVG/NPT
C
      NLI = NPT/12 + 1
      I1 = -11
C
C
      DO 70 I = 1,NLI
        I1 = I1 + 12
        I2 = I1 + 11
        I2 = MIN(I2,NPT)
        IF (LLPRNT) WRITE (IOUT,FMT=6008) (RAD(J),J=I1,I2)
        IF (LLPRNT) WRITE (IOUT,FMT=6010) (IBGAV(J),J=I1,I2)
        IF (LLPRNT) WRITE (IOUT,FMT=6012) (ISIGBGAV(J),J=I1,I2)
        IF (LLPRNT) WRITE (IOUT,FMT=6014) (NREJAV(J),J=I1,I2)
        IF (ONLINE.AND.LLPRNT) THEN
          WRITE (ITOUT,FMT=6008) (RAD(J),J=I1,I2)
          WRITE (ITOUT,FMT=6010) (IBGAV(J),J=I1,I2)
          WRITE (ITOUT,FMT=6012) (ISIGBGAV(J),J=I1,I2)
          WRITE (ITOUT,FMT=6014) (NREJAV(J),J=I1,I2)
        END IF
   70 CONTINUE

C
C
 6008 FORMAT (1X,'RADIUS',12F6.1)
 6010 FORMAT (1X,'BACKG ',12I6)
 6012 FORMAT (1X,'SIGMA ',12I6)
 6014 FORMAT (1X,'NREJ  ',12I6)
C
C---- stuff for BEST
C
      IF(MODE.EQ.-1)THEN
        IBEST = 21
        IFAIL = 1
        LDUM = 80
        CALL CCPOPN(-IBEST,BESTFILE,1,1,LDUM,IFAIL)
        DO 80 I = 1,NPT
          IF(IBGAV(I).GT.0)THEN
            WRITE(IBEST,FMT=6018)RESRAD(I),FBGAV(I),FSIGBGAV(I)
          ELSE
C     .. 
C     .. if the strip starts in the gap between tiles only!
            WRITE(IBEST,FMT=6018)RESRAD(I),FBGAV(I+1),FSIGBGAV(I+1)
          ENDIF
 80     ENDDO
        CLOSE(UNIT=IBEST)
        RMAXSP = SRMAXSP
C
C---- zero local and global arrays
C
        DO 90 I = 1,IXWDTH
          BGOD(I) = 0
          RAD(I) = 0.0
          SIGAV(I) = 0.0
          RESRAD(I)= 0.0
          AVBG(I) = 0
          IBGAV(I) = 0
          ISIGBGAV(I) = 0
          NREJ(I) = 0
          NREJAV(I) = 0
 90     ENDDO
      ENDIF
 6018 FORMAT(F10.4,1X,F10.2,1X,F10.2)
C
C
      RETURN
      END
C
C $Id: rasplot.f,v 1.11 2018/04/09 17:02:02 rtkit Exp $
C
C== RASPLOT ==
C
      SUBROUTINE RASPLOT(ID,BB,IWX,IWY,MASK,MASKREJ,IDR,ODSCAL,FINAL)
C     ======================================================
C
      IMPLICIT NONE
C
C
C---- To plot an average spot profile, stored in an integer*4 array bb
C     assuming it is scaled to a maximum of 255. 
C     Called by CHKRAS
C
C     Values are printed as 0-9, A-Z, preceeded with a "-" for
C     background, "*" for rejected background.
C
C
C
C
C     .. Scalar Arguments ..
      REAL ODSCAL
      INTEGER ID,IDR,IWX,IWY
      LOGICAL FINAL
C     ..                                                    
C     .. Array Arguments ..
      INTEGER BB(*),MASK(*),MASKREJ(*)
C     ..
C     .. Local Scalars ..
      INTEGER I,I2WX,IJ,J,JJ,K,N,NUM,NXY,NBREJ,NBREJP1,MASKIJ,NR,
     +        LINELEN,NUMLIN,IXW,IYW,NCH,NCHAR,TOP
      CHARACTER KSYMB*1,LINE*120,IMGNAM*100,LONGLINE*10100,
     $     charstring*6
C     ..
C     .. Local Arrays ..
      CHARACTER IA(84)*1,ICHAR(0:36)*1,ISYMB(-1:1)*1
C     ..
C     .. External Subroutines ..
C     ..
C     .. Extrinsic Functions ..
      INTEGER  LENSTR
      EXTERNAL  LENSTR
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
