     $       ((UMAT(I,J),J=1,3),I=1,3),
     $       ((UMATREF(I,J),J=1,3),I=1,3),RCELL,CELL,
     $       SDU,SDCELL,SDPHI,SDXY,SDCUTOFF,IERR
        WRITE(IOUT,6200)NCYCLE,REIDX0,NREF,ACHSE,IC,ICS,
     $       RAST,ORGX,ORGY,XTD,S0L,
     $       ((EDLAB(I,J),J=1,3),I=1,3),
     $       ((UMAT(I,J),J=1,3),I=1,3),
     $       ((UMATREF(I,J),J=1,3),I=1,3),RCELL,CELL,
     $       SDU,SDCELL,SDPHI,SDXY,SDCUTOFF,IERR
 6200   FORMAT(72('-'),/,'NCYCLE = ',I2,/,'REIDX0 = ',4I2,
     $       2(/,9X,4I2),/,'NREF = ',I5,/,'ACHSE = ',3F5.2,/,
     $       'IC = ',I2,'   ICS = ',I2,'   RAST = ',F8.4,/,
     $       'ORGX = ',F8.2,'  ORGY = ',F8.2,'    XTD = ',
     $       F8.2,/,'S0L = ',3F12.6,/,'ED = ',3F5.2,2(/,
     $       5X,3F5.2),/,'UMAT = ',3F10.6,2(/,7X,3F10.6),/,
     $       'UMAT (RFX) = ',3F10.6,2(/,12X,3F10.6),/,
     $       'RCELL = ',3(F9.7,1X),3(F9.4,1X),/,'CELL =  ',
     $       6(F9.4,1X),/,'SDU = ',F10.6,/,'SDCELL = ',
     $       6F10.4,/,'SDPHI = ',F10.6,'    SDXY = ',F10.6,
     $       '    SDCUTOFF = ',F6.2,'  IERR = ',I4,/,
     $       72('='),/)
      ENDIF
      RETURN
      END
c     refine_segment_store
c     this subroutine originally written by G. Winter
c     22nd October 2002
c     
C     05.08.2008
c     Everything removed from this except "get_segment_phi", which might
c     still be relevant to s/r "CELREFSET"
c     
c     $Id: refine_segment_store.f,v 1.5 2008/08/05 15:07:41 harry Exp $
c     
c     Notes: these are called like:
c     
c     call save_segment(template, start_image, end_image,
c          + save_template, save_start, save_end, segment_no)
c     
c     character *80 template
c     integer start_image, end_image, segment_no
c     logical save_template, save_start, save_end
c     
c     
c     call query_segment(set_template, set_start, set_end, semgent_no)
c     
c     All data are stored in ../inc/refine_segment_store.f common block.
c     This is all that is needed.
c
c     Need to add start and range phi values for each segment, as these
c     might be set independantly -> have a separate group of subroutines
c     for storing this information? probably best, since this will generally
c     not be used very often. => append _phi to the SR name ->
c     
c     get_segment_phi(phi_start, phi_range, get_start, get_range, segment)
c     subroutine get_segment - works like save_segment but backwards. this
c     is to allow the information saved above to be retrieved.

      subroutine get_segment(template, start_image, end_image,
     +     get_template, get_start, get_end, segment_number)

      implicit none

C&&*&& include  ../inc/refine_segment_store.f
c     refine_segment_store.f
c     maintained by G.Winter
c     22nd October 2002
c     
c     The common block in which all of the data for storing the 
c     segment information are kept.
c     
c     This is in fact two common blocks, one which will contain the 
c     phi value information.
c     
c     $Id: refine_segment_store.f,v 1.2 2002/10/24 14:45:26 graeme Exp $
c     

      integer maximum_segments 
      parameter (maximum_segments = 10)

      integer segment_start(maximum_segments)
      integer segment_end(maximum_segments)
      character*80 segment_template(maximum_segments)
      
      logical set_template(maximum_segments)
      logical set_start(maximum_segments)
      logical set_end(maximum_segments)
      
      common /saved_segments/ segment_start, segment_end, 
     +     segment_template, set_template, set_start,
     +     set_end

      real segment_phi_start(maximum_segments)
      real segment_phi_range(maximum_segments)

      logical set_phi_start(maximum_segments)
      logical set_phi_range(maximum_segments)
      
      common /saved_phi_values/ segment_phi_start, segment_phi_range,
     +     set_phi_start, set_phi_range
C&&*&& end_include  ../inc/refine_segment_store.f

c     the input variables

      character*80 template
      integer start_image, end_image, segment_number
      logical get_template, get_start, get_end

      if(segment_number .gt. maximum_segments) then
         return
      end if

      if(get_template .and. set_template(segment_number)) then
         template = segment_template(segment_number)
      end if

      if(get_start .and. set_start(segment_number)) then
         start_image = segment_start(segment_number)
      end if

      if(get_end .and. set_end(segment_number)) then
         end_image = segment_end(segment_number)
      end if

      return
      end


c     subroutine get_segment_phi
c     get the phi values for a segment, having set them using the 
c     previous subroutine
c     
c     

      subroutine get_segment_phi(phi_start, phi_range,
     +     get_start, get_range, segment)

      implicit none

C&&*&& include  ../inc/refine_segment_store.f
c     refine_segment_store.f
c     maintained by G.Winter
c     22nd October 2002
c     
c     The common block in which all of the data for storing the 
c     segment information are kept.
c     
c     This is in fact two common blocks, one which will contain the 
c     phi value information.
c     
c     $Id: refine_segment_store.f,v 1.2 2002/10/24 14:45:26 graeme Exp $
c     

      integer maximum_segments 
      parameter (maximum_segments = 10)

      integer segment_start(maximum_segments)
      integer segment_end(maximum_segments)
      character*80 segment_template(maximum_segments)
      
      logical set_template(maximum_segments)
      logical set_start(maximum_segments)
      logical set_end(maximum_segments)
      
      common /saved_segments/ segment_start, segment_end, 
     +     segment_template, set_template, set_start,
     +     set_end

      real segment_phi_start(maximum_segments)
      real segment_phi_range(maximum_segments)

      logical set_phi_start(maximum_segments)
      logical set_phi_range(maximum_segments)
      
      common /saved_phi_values/ segment_phi_start, segment_phi_range,
     +     set_phi_start, set_phi_range
C&&*&& end_include  ../inc/refine_segment_store.f

      real phi_start, phi_range
      logical get_start, get_range
      integer segment

      if(segment .gt. maximum_segments) then
         return 
      end if

      if(get_start .and. set_phi_start(segment)) then
         phi_start = segment_phi_start(segment)
      end if

      if(get_range .and. set_phi_range(segment)) then
         phi_range = segment_phi_range(segment)
      end if

      return
      end


c     subroutine query_segment
c     determine which properties of this segment have been stored, so that
c     error checking is possible

      subroutine query_segment(query_template, query_start, query_end, 
     +     segment_number)

      implicit none

C&&*&& include  ../inc/refine_segment_store.f
c     refine_segment_store.f
c     maintained by G.Winter
c     22nd October 2002
c     
c     The common block in which all of the data for storing the 
c     segment information are kept.
c     
c     This is in fact two common blocks, one which will contain the 
c     phi value information.
c     
c     $Id: refine_segment_store.f,v 1.2 2002/10/24 14:45:26 graeme Exp $
c     

      integer maximum_segments 
      parameter (maximum_segments = 10)

      integer segment_start(maximum_segments)
      integer segment_end(maximum_segments)
      character*80 segment_template(maximum_segments)
      
      logical set_template(maximum_segments)
      logical set_start(maximum_segments)
      logical set_end(maximum_segments)
      
      common /saved_segments/ segment_start, segment_end, 
     +     segment_template, set_template, set_start,
     +     set_end

      real segment_phi_start(maximum_segments)
      real segment_phi_range(maximum_segments)

      logical set_phi_start(maximum_segments)
      logical set_phi_range(maximum_segments)
      
      common /saved_phi_values/ segment_phi_start, segment_phi_range,
     +     set_phi_start, set_phi_range
C&&*&& end_include  ../inc/refine_segment_store.f

      integer segment_number
      logical query_template, query_start, query_end

c     if this is true, we can't have stored any of the values!

      if(segment_number .gt. maximum_segments) then
         query_template = .false.
         query_start = .false.
         query_end = .false.
         return
      end if

c     copy the storage flags into the returning variables

      query_template = set_template(segment_number)
      query_start = set_start(segment_number)
      query_end = set_end(segment_number)

      return
      end

c     subroutine query_segment_phi
c     determine which parameters have been set (phi-wise) for
c     this segment, and return all .false. if segment is out
c     of bounds
c     

      subroutine query_segment_phi(set_start_phi, set_range_phi, 
     +     segment)

      implicit none

C&&*&& include  ../inc/refine_segment_store.f
c     refine_segment_store.f
c     maintained by G.Winter
c     22nd October 2002
c     
c     The common block in which all of the data for storing the 
c     segment information are kept.
c     
c     This is in fact two common blocks, one which will contain the 
c     phi value information.
c     
c     $Id: refine_segment_store.f,v 1.2 2002/10/24 14:45:26 graeme Exp $
c     

      integer maximum_segments 
      parameter (maximum_segments = 10)

      integer segment_start(maximum_segments)
      integer segment_end(maximum_segments)
      character*80 segment_template(maximum_segments)
      
      logical set_template(maximum_segments)
      logical set_start(maximum_segments)
      logical set_end(maximum_segments)
      
      common /saved_segments/ segment_start, segment_end, 
     +     segment_template, set_template, set_start,
     +     set_end

      real segment_phi_start(maximum_segments)
      real segment_phi_range(maximum_segments)

      logical set_phi_start(maximum_segments)
      logical set_phi_range(maximum_segments)
      
      common /saved_phi_values/ segment_phi_start, segment_phi_range,
     +     set_phi_start, set_phi_range
C&&*&& end_include  ../inc/refine_segment_store.f

      integer segment
      logical set_range_phi, set_start_phi

      if(segment .gt. maximum_segments) then
         set_start_phi = .false.
         set_range_phi = .false.
         return
      end if

      set_start_phi = set_phi_start(segment)
      set_range_phi = set_phi_range(segment)

      return
      end
      SUBROUTINE REFLFIND(IXPIX,IYPIX,IMOSFLMIMG,PROFPHIS,PROFPHIE,
     +         IMOSFIRSTIMG,IMOSLASTIMG,PROFWIDTH,
     +         PHIREF,PHIWREF,IPACKF,IPACKL,NSER,NSERRUN,IFIRSTPACK,
     +         MODE,IERR)
C     ===============================================================
C
      IMPLICIT NONE
C
C---- Find the reflection with pixel coords IXPIX,IYPIX on currently
C     displayed image IMOSFLMIMG with start and end phi values PROFPHIS,
C     PROFPHIE. First and last images in dataset are IMOSFIRSTIMG and
C     IMOSLASTIMG. PROFWIDTH is the desired width of the phi profile, if
C     not set then a value is worked out based on PHIWREF.
C     Return indices
C     IHPROF,IKPROF,ILPROF in common /PHIPROFILE/, phi value PHIREF and 
c     reflection width PHIWREF, also return IPACKF,IPACKL,NSER,NSERRUN
c     and IFIRSTPACK
C
C     DEBUG(107)  this S/R
C
C     MODE     = 1 find the reflction from pixel coordinates and set
C                  up an integration run with SOCKLO FALSE
C
C              = 2 Following integration, extract the phi profile for the
C                  reflection selected and write XML to iMosflm
C
C              = 3 If images required for this phi profile have already been
C                  integrated, MODE = 1 gets reset to MODE = 3 so integration
C                  is not repeated.
C
C     IERR     = -1 if reflection is not found in MODE = 1
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
