C---- START of include file savall.h
C
C      NSAVIMG      Number of images used in autoindexing
C      ISAVIMG      Array storing image numbers used in last autoindexing
C      NSAVSEG      Number of segments used in last postref run
C      ISFIRST      Array storing image number of the first image
C                   in all segments of last postref run.
C      SAVMATSR     Indicates whether last matrix was determined by
C                   autoindexing (Autoindexing) or by postref (Post refinement)
C      SAVMATNAM    Name of the matrix file
C      SAVENAM      Name of savefile
C      SVSCN        SCANNER keyword
C      SVSITE       SITE keyword
C      RES          High resolution limit given on RESOL keyword
C      RESLOW       Low resolution limit given on RESOL keyword
C      RES2SD       estimate of high resolution limit from spot finding
C      IISCN        Set TRUE if a DETECTOR keyword has been read that specifies
C                   a particular detector type.
C      GENERICDET   Set TRUE if a generic detector specification (ROTATION,
C                   ORIGIN, FAST and RECTANGULAR/CIRCULAR) has been given.
C
C
C     .. Scalars in common block /SAVALL/ ..
      REAL RES,RESLOW
      INTEGER NSAVIMG,NDIR,NSAVSEG
      CHARACTER SAVMATSTR*80,SAVMATNAM*80,SAVENAM*80,SVSCN*80,
     +          SVSITE*80
      LOGICAL IISCN,IISITE,IIWAVE,IIDIV,IIDISP,IINULL,IIRAST,IISEP,
     +        IIOVER,IIPIX,IIBACK,IIRES,GENERICDET
C     ..
C     .. Arrays in common block /SAVALL/ ..
C
      INTEGER ISAVIMG(MAXIMG),ISFIRST(100)
C     .. Common Block /SAVALL/ ..
      COMMON /SAVALL/ RES,RESLOW,
     +       ISAVIMG,ISFIRST,NSAVIMG,NDIR,NSAVSEG,
     +       IISCN,IISITE,IIWAVE,IIDIV,IIDISP,IINULL,IIRAST,IISEP,
     +        IIOVER,IIPIX,IIBACK,IIRES,GENERICDET
C
C
      COMMON /SAVALLC/ SAVMATSTR,SAVMATNAM,SAVENAM,SVSCN,SVSITE
C     ..
C
C
C&&*&& end_include  ../inc/savall.f
C&&*&& include  ../inc/scn.f
C
C $Id: scn.f,v 1.5 2014/11/18 14:05:40 andrew Exp $
C
C--- awk generated include file  scn.h
C---- START of include file scn.h
C
C     SCNSZ   is pixel size (in microns) divided by 25
C     RAST    pixel size in slow direction in mm
C     FACT    multiplying by FACT converts from 10 micron units 
C             (the standard unit internal to the program) into pixels
C     IYLEN   The number of pixels in the Y (fastest changing) direction
C             in the digitised image.
C     NREC    The number of pixels in the X (slow) direction in the 
C             digitised image.
C     NWORD   The number of I*2 words in the Y direction.
C     NBYTE   The number of bytes in Y direction = NWORD/2
C     NHBYTE  Number of bytes in header
C
C     ICURR   When several images are stored in a single file, ICURR is the
C             pointer to the first record of the current image in the direct
C             access file (only implemented for film data)
C     NEXTRA  The number of additional (unused) bytes padding the end of
C             each record in image file
C     BYTSWAP True if the "endedness" (Big-endian/Little-endian) of the 
C             machine that MOSFLM is running on is different to that of the
C             machine on which the image was written. This is determined by
C             looking at the value of NXPIX in the header record of the
C             image file (subroutine GETHDR)
C
C     LACTIVE True if using Rigaku active mask, False if ignoring it
C     REALLYFORCEREAD True if we want to display an image where we have
C                     changed the activemask
C
C     ROWREADT Time in seconds that the detector takes to read a row of data,
C              required for rolling shutter mode readout of Tietz detector
C              used for microED.
C     ROTSPEED Spindle rotation rate (degrees per second),required for rolling
C              shutter mode readout of Tietz detector used for microED. 
C
C
C     .. Scalars in common block /SCN/ ..
      REAL FACT,SCNSZ,RAST,RASTY,ROWREADT,ROTSPEED
      INTEGER NBYTE,NREC,NWORD,IYLEN,ICURR,NEXTRA,NHBYTE
      LOGICAL BYTSWAP,LACTIVE,REALLYFORCEREAD
C     ..
C     .. Common Block /SCN/ ..
      COMMON /SCN/ FACT,SCNSZ,RAST,RASTY,ROWREADT,ROTSPEED,
     +     NBYTE,NREC,NWORD,IYLEN,
     +     ICURR,NEXTRA,NHBYTE,BYTSWAP,LACTIVE,
     $     REALLYFORCEREAD
C&&*&& end_include  ../inc/scn.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C     ..
C     .. Equivalences ..
      SAVE
C     ..
C     .. Data ..
      DATA IPLOT/0/
C     ..
C
      THIS = 'REFLFIND'
      INDENT = 3
      IERR = 0
      REDO = .FALSE.
      IF ((DEBUG(107)).AND.(MODE.EQ.1)) THEN
        WRITE(IOUT,FMT=6000) MODE,PROFPHIS,PROFPHIE,PHIBEG,PHIEND,
     +                       DELPHI,IMOSFIRSTIMG,IMOSLASTIMG,
     +                    ISTARTLAST,IENDLAST,PROFWIDTH,NWMAX,RESTRESL
        IF (ONLINE) WRITE(ITOUT,FMT=6000) MODE,PROFPHIS,PROFPHIE,
     +                  PHIBEG,PHIEND,DELPHI,IMOSFIRSTIMG,IMOSLASTIMG,
     +                    ISTARTLAST,IENDLAST,PROFWIDTH,NWMAX,RESTRESL
 6000   FORMAT(//,1x,'Entering REFLFIND with MODE=',I2,/,1X,'Phi start',
     +         ' and end for displayed image',2F8.2,' Current PHIBEG',
     +     'and PHIEND',2F8.2,/,1X,'DELPHI missets',3F6.2,'  First ',
     +     'and last images in dataset',2I8,/,1X,'First and last ',
     +     'images of previous phiprofile integration run',2I8,
     +     '  PROFWIDTH',F5.2,' NWMAX',I4,' RESTRESL',L2)
      END IF
C
      IF (MODE.EQ.2) GOTO 100
C
C---- Sleep to allow imosflm to catch up handling XML
C
      CALL MSLEEP(1)
C
C---- If the current PHIBEG and PHIEND do not match those of the displayed image
C     then need to reset them and then re-predict the displayed image so that K
C     the reflection will be found
C
      IF (ABS(PHIBEG-PROFPHIS).GT.0.1*(ABS(PROFPHIS-PROFPHIE))) THEN
C
C---- Repeat prediction. Strictly need to ensure detector parameters and crystal
C     parameters (mosaic spread, orientation) are the same as when the image was
C     originally displayed, but missets should not have changed during the integration
C     to get phiprofile data for a previous reflection as minimum number of reflections
C     for post-refinement has been set very high. Detector parameters are 
C     not refined.
C
        IF (DEBUG(107)) THEN
          WRITE(IOUT,FMT=6002)
          IF (ONLINE) WRITE(ITOUT,FMT=6002)
 6002     FORMAT(1X,'Repeating prediction as phi values do not match')
        END IF
          
        PHIBEG = PROFPHIS
        PHIEND = PROFPHIE
        LOCALPHIAVG = 0.5*(PHIBEG+PHIEND)
        CALL PHITOPSI(DELPHI, PSI, LOCALPHIAVG)
        COMMENT = 'to re-predict displayed image'
        REDO = .TRUE.
      END IF
C
C
      IF (REPREDICT) THEN
        COMMENT = 'to re-predict all reflections'
        REDO = .TRUE.
      END IF
c
      IF (REDO) THEN     
C
C---- Print for program flow
C
        CALLED = 'PREDICT'
        IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
C
        IFLAGPR = 0
C
C---- Need to assign DSTMIN2PHIP,DSTMAX2PHIP using current DSTMIN, DSTMAX
C     as these are used in SPTEST in generation of relfection list.
C
        DSTMIN2PHIP = DSTMIN**2
        DSTMAX2PHIP = DSTMAX**2
#ifdef MOSFLM_CPP_PREDICT
C---- Experimental PREDICT via mosflm-cpp (PHASE_C_SPLICE.md).
        CALL PREDICT_CPP_FROM_COMMON(IFLAGPR, NREFLS,
     +       IHG, IKG, ILG, XG, YG, PHIG, PHIWG, IMG, NSPOT)
#else
        CALL PREDICT(PSI, IFLAGPR)
#endif
        REDO = .FALSE.
      END IF
       
C
C---- Loop over reflections, calculating pixel coords as sent in XML to iMosflm
C     and test against input coords find closest reflection within 10 pixels
C
      DSQMIN = 200
      DO 10 I = 1,NSPOT
         XC = XG(I) - XCOR
         YC = YG(I) - YCOR
         CALL MMTOPX(XCAL, YCAL, XC, YC)
         IYREF = NINT(YCAL * FACT)
         IF (ABS(IYPIX-IYREF).GT.10) GOTO 10
         IXREF = NREC - NINT(XCAL * FACT)
         IF(.NOT.INVERTX) IXREF = NREC - IXREF
         IF (ABS(IXPIX-IXREF).GT.10) GOTO 10
         DSQ = (IXPIX-IXREF)**2 + (IYPIX-IYREF)**2
         IF (DSQ.LT.DSQMIN) THEN
           DSQMIN = DSQ
C
C---- Reflection found, extract indices, phi value and phi width
C
           IHPROF = IHG(I)         
           IKPROF = IKG(I)         
           ILPROF = ILG(I)         
           PHIREF = PHIG(I)
           PHIWREF = PHIWG(I)
           XGEN = XG(I)
           YGEN = YG(I)
           FRACGEN = FRACG(I)
           IRECG = I
         END IF
 10   CONTINUE
      IF (DSQMIN.LT.200) GOTO 20
C
C---- Reflection not found
C
      IERR = -1
      WRITE(IOUT,FMT=6004) IXPIX,IYPIX
      IF (ONLINE) WRITE(ITOUT,FMT=6004) IXPIX,IYPIX
 6004 FORMAT(/,/,1X,'*** Reflection with pixel coordinates',2I6,
     +        ' not found! ***',/,/)
      WARNING = 'not_found'
      WRITE(IOLINE,FMT=6006) 2*ETA/DTOR,2*ETA/DTOR,
     +                      WARNING(1:LENSTR(WARNING))
 6006   FORMAT('<?xml version="1.0"?>',
     $           '<!DOCTYPE phiprofile_final>',
     $           '<phiprofile_final>',
     +            '<status><code>ok</code></status>',
     +           '<mosaicity>',F7.3,'</mosaicity>',
     +           '<mosaic_block_size>',F8.2,'</mosaic_block_size>'
     +           '<warning>',A,'</warning>',
     +           '</phiprofile_final>')
            CALL WRITE_SOCKET_LENGTH
     $           (SERVERFD,LENSTR(IOLINE),IOLINE)
      RETURN
 20   NBIN = 10
      CALL GETBIN(IRECG,ITHBIN,NBIN,DSTSQ)
      IF (DSTSQ.GT.0.0) RESL = 1.0/SQRT(DSTSQ)

      IF (DEBUG(107)) THEN
        WRITE(IOUT,FMT=6010) IXPIX,IYPIX,IHPROF,IKPROF,ILPROF,PHIREF,
     +                    PHIWREF,RESL,FRACGEN,XGEN,YGEN,SQRT(DSQMIN)
        IF (ONLINE) WRITE(ITOUT,FMT=6010) IXPIX,IYPIX,IHPROF,IKPROF,
     +       ILPROF,PHIREF,PHIWREF,RESL,FRACGEN,XGEN,YGEN,SQRT(DSQMIN)
 6010   FORMAT(/,1X,'Reflection with pixel coords',2I5,' has indices',
     +   3I4,' phi value',F8.3,' width',F6.2' degrees, resolution',
     +   F7.2,/,1x,
     +   'Fraction recorded',F5.2,' Virtual detector coords (10mu)',
     +    2F8.1,'  Error in pixel coords',F5.1)
      END IF
C
C---- Set up parameters for the integration
C
C
C---- Number of images required, add number of images corresponding to half
C     the mosaicity as a buffer, set minimum value to 3
C
      IF (PHIRNG.EQ.0) PHIRNG = MAX(PHIEND-PHIBEG,HPHIE-HPHIS)
      IF (PROFWIDTH.GT.0.0) THEN
        NPACK = NINT(PROFWIDTH/PHIRNG)
      ELSE
        NPACK = PHIWREF/PHIRNG + 0.5*(2*ETA/DTOR)/PHIRNG + 1
      END IF
      NPACK = MAX(NPACK,3)
      NWMAXSAVE = NWMAX
      NWMAX = MAX(NPACK,NWMAX) + 3
C
C---- MODARRAY arrays only allow NGRA (currently 100, a parameter set in /PARAMETERS/) 
C     parts to a reflection, if NWMAX is more than this give an error message.
C
      IF (NWMAX.GT.NGRA) THEN
        IERR = -2
C
C---- Write the XML
C
        IF (SOCKLO) THEN
          WRITE(IOLINE,FMT=6011) NWMAX,NGRA
 6011     FORMAT('<?xml version="1.0"?>',
     +         '<!DOCTYPE phiprofile_setup>',
     +         '<phiprofile_setup>',
     +         '<status><code>error</code><message>Profile for this',
     +         ' reflection extends over',I4,' images which is more',
     +         ' than allowed maximum of',I4,'</message></status>',
     +         '</phiprofile_setup>')
           CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(IOLINE),IOLINE)
         END IF
        NWMAX = NWMAXSAVE
        RETURN       
      END IF
C
C---- Need to inflate mosaic spread so that reflection will be predicted on all these images
C
      ETASAVE = ETA
      ETA = ETA*NPACK*PHIRNG/PHIWREF
C
C---- Which image contains the phi value for this reflection?
C
      if (phiref.gt.phibeg) then
        iadd = (phiref-phibeg)/phirng
      else
        iadd = (phiref-phibeg)/phirng -1
      end if
      imidimg = imosflmimg + iadd
      istartp = 1
      ifirstpack = 1
C
C---- NPHIPROFIMG keeps track of images read during determination of phi profile,
C     only needed to be bale to deal with cases where images are missing in the dataset
C
      NPHIPROFIMG = 0
C
C---- Ensure images requested are within range of images in dataset
C
      STARTTRUNC = ((IMIDIMG - NPACK/2).LT.IMOSFIRSTIMG)
      ENDTRUNC = ((IMIDIMG + NPACK/2).GT.IMOSLASTIMG)
      
      IPACKF = MAX(IMOSFIRSTIMG,IMIDIMG - IMGPAD - NPACK/2)
      IF (IMOSFIRSTIMG.LT.(IMIDIMG-IMGPAD-NPACK/2)) THEN
        IPACKL = MIN(IPACKF + 2*IMGPAD + NPACK - 1,IMOSLASTIMG)
      ELSE
CAL        IPACKL = MAX(IMIDIMG + IMGPAD + NPACK/2,IMOSFIRSTIMG)
        IPACKL = MAX(IMIDIMG + IMGPAD + NPACK/2,IMOSFIRSTIMG)
        IPACKL = MIN(IPACKL,IMOSLASTIMG)
      END IF 
C
C---- Reset NPACK in case of truncation
C
      NPACK = IPACKL - IPACKF + 1
C
C---- Need NPACK to be GT 1 so adjust as necessary, different cases for start of dataset
c     and end of dataset.
C
      IF (NPACK.EQ.1) THEN
        IF (IPACKF.EQ.IMOSFIRSTIMG) IPACKL = IPACKL + 1
        IF (IPACKL.EQ.IMOSLASTIMG) IPACKF = IPACKF - 1
        NPACK = 2
      END IF
C
      IPACK1A(1) = IPACKF
      IPACK2A(1) = IPACKL
      NSER = 1
      NSERRUN = 1
C     
C---- Note that IDPACK, PHIBEGA, PHIENDA are used in MAIN to set up
C     start and end oscillation angles for image IDPACK
C     
      J = 0
      DO 30  I = ISTARTP,NPACK
         J = J + 1
         IF (I.EQ.ISTARTP) THEN
           IDPACK(I) = IPACKF
           PHIBEGA(I) = PHIBEG - (IMOSFLMIMG-IPACKF)*PHIRNG
           PHIENDA(I) = PHIBEGA(I) + PHIRNG
         ELSE
           IDPACK(I) = IPACKF + J - 1
           PHIBEGA(I) = PHIENDA(I-1)
           PHIENDA(I) = PHIBEGA(I) + PHIRNG
         END IF
         NFPACK(I) = 1
         NFIRST(I) = 1
 30   CONTINUE
      ISTRT = 1
      IANGLE = 1
C
C---- Turn off all XML by setting SOCKLO false.. do this in CONTROL after the GO keyword from
C     iMosflm has been read. set logical PHIPROF TRUE
C
CAL      SOCKLO = .FALSE.
      PHIPROF = .TRUE.
C
C---- Write the XML
C
      IF (SOCKLO) THEN
        WRITE(IOLINE,FMT=6012) IHPROF,IKPROF,ILPROF,PHIREF,PHIWREF,RESL
 6012   FORMAT('<?xml version="1.0"?>',
     +         '<!DOCTYPE phiprofile_setup>',
     +         '<phiprofile_setup>',
     +         '<status><code>ok</code></status>',
     +         '<index_h>',I4,'</index_h><index_k>',I4,'</index_k>',
     +         '<index_l>',I4,'</index_l><phi>',f9.2,'</phi>',
     +         '<phi_width>',f8.2,'</phi_width>'
     +         '<resolution>',F8.2,'</resolution>',
     +         '</phiprofile_setup>')
         CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(IOLINE),IOLINE)
       END IF
C
C---- Turn off detector parameter refinement and reflection overlap testing
C
      NOREF = .TRUE.
      LOVERLAP = .TRUE.
C
C---- Set NBLOCK to NPACK so that there is only a single block, otherwise integration stops
C     and set IBLOCK to 1 so this is not changed by call to GETBLOCK in CONTROL
C
      NBLOCK = NPACK
      IBLOCK = 1     
C
      IF (DEBUG(107)) THEN
         WRITE(IOUT,FMT=6020) PHIBEG,PHIEND,PHIRNG,HPHIS,HPHIE,IMGPAD,
     +    NPACK,IPACKF,IPACKL,PHIBEGA(1),PHIENDA(1),NBLOCK,2*ETA/DTOR,
     +    NWMAX
         IF (ONLINE) WRITE(ITOUT,FMT=6020) PHIBEG,PHIEND,PHIRNG,
     +          HPHIS,HPHIE,IMGPAD,NPACK,IPACKF,IPACKL,PHIBEGA(1),
     +          PHIENDA(1),NBLOCK,2*ETA/DTOR,NWMAX
 6020    FORMAT(1X,'PHIBEG,PHIE',2f8.2,'  PHIRNG',F6.2,'  HPHIS,HPHIE',
     +          2f8.2,' IMGPAD',i3,' NPACK',i3,'  IPACKF',I5,'  IPACKL',
     +          I5,/,1X,'Start and end phi for first pack',2F8.2,
     +          '  NBLOCK is',I5,/,1X,'Mosaic',
     +          ' spread increased to',F6.2,' for integration, maximum',
     +          ' reflection width now',I5,' images')
      END IF
      WRITE(IOUT,FMT=6021) IHPROF,IKPROF,ILPROF,PHIREF,PHIWREF,RESL
      IF (ONLINE) WRITE(ITOUT,FMT=6021) IHPROF,IKPROF,ILPROF,PHIREF,
     +          PHIWREF,RESL
 6021 FORMAT(/,1x,'Getting phi profile for reflection',3I4,' predicted',
     +             ' phi',F8.2,' phi width',F7.2,' resolution',F7.2)
C
C---- If restricting resolution, reset resolution limits
C
      IF (RESTRESL) THEN
CAL        RES = RESL - 0.1
CAL        RESLOW = RESL + 0.1
        reswidth = 0.5
C
C---- Test this calculation for RESWIDTH
C
        RESWIDTH = 100.0*(1.0/RES)**3/(NSPOT*(1/RESL)**2)
        WRITE(IOUT,FMT=6022) RESL+ RESWIDTH, RESL-RESWIDTH
        IF (ONLINE) WRITE(ITOUT,FMT=6022) RESL+ RESWIDTH, RESL-RESWIDTH
 6022   FORMAT(1X,'Integration will be limited to reflections in ',
     +             'resolution range',F7.2,' to',F7.2)
        DSTMIN2PHIP = (WAVE/(RESL+RESWIDTH))**2
        DSTMAX2PHIP = (WAVE/(RESL-RESWIDTH))**2
      END IF
C
C---- See if these images have already been integrated, but without restricted resolution
C
      IF (((IPACKF+IMGPAD.GE.ISTARTLAST).AND.
     +     (IPACKL-IMGPAD.LE.IENDLAST)).AND.(.NOT.REPREDICT)) THEN
        WRITE(IOUT,FMT=6024) IPACKF+IMGPAD,IPACKL-IMGPAD,ISTARTLAST,
     +                       IENDLAST
        IF (ONLINE) WRITE(ITOUT,FMT=6024) IPACKF+IMGPAD,IPACKL-IMGPAD,
     +            ISTARTLAST,IENDLAST
 6024   FORMAT(//,1X,'Images',I7,' to',I7,' have already been ',
     +        'integrated in a previous run',/,1X,
     +         'with images',I7,' to',I7)
        IF (DEBUG(107)) THEN
          WRITE(IOUT,FMT=6026)
          IF (ONLINE) WRITE(ITOUT,FMT=6026)
 6026     FORMAT(1X,'Going straight into MODE=2 to recover profile')
        END IF
        MODE = 3
        GOTO 100
      ELSE
        ISTARTLAST = IPACKF
        IENDLAST = IPACKL
      END IF
      WRITE(IOUT,FMT=6028) IPACKF,IPACKL
      IF (ONLINE) WRITE(ITOUT,FMT=6028) IPACKF,IPACKL
 6028 FORMAT(1X,'Integrating images ',I6,' to', I6,/,1X,'During',
     +       ' integration no parameter refinement will be done.')
      RETURN
C
C**********************************************************************************
C---- Start for MODE=2, extract phi profile information built up in MODARRAY arrays
C     or for MODE=3 if images have already been integrated
C**********************************************************************************
C
 100  CONTINUE
C
C---- First check if any images are missing, and if that affects the current profile
C
      IF (NPHIPROFMISS.GT.0) THEN
        DO 102 I = IPACKF,IPACKL
          DO 104 J = 1,NPHIPROFMISS
            IF (I.EQ.IMGMISSING(J)) THEN
               IF (I.EQ.IPACKF) STARTTRUNC = .TRUE.
               IF (.NOT.STARTTRUNC) ENDTRUNC = .TRUE.
            END IF
 104      CONTINUE
 102    CONTINUE
        IF (DEBUG(107)) THEN
          WRITE(IOUT,FMT=6029) NPHIPROFMISS,STARTTRUNC,ENDTRUNC,
     +            (IMGMISSING(I),I=1,NPHIPROFMISS)
          IF (ONLINE) WRITE(ITOUT,FMT=6029) NPHIPROFMISS,STARTTRUNC,
     +            ENDTRUNC,(IMGMISSING(I),I=1,NPHIPROFMISS)
 6029     FORMAT(1X,'Number of missing images:',I3,' STARTTRUNC',L2,
     +            ' ENDTRUNC',L2,/,1X,'Missing images:',/,(1x,10I8))
        END IF
      END IF


C
C---- Reflections have been sorted on H
C
      IF (DEBUG(107)) THEN
        WRITE(IOUT,FMT=6030) IHPROF, IKPROF, ILPROF
        IF (ONLINE) WRITE(ITOUT,FMT=6030) IHPROF, IKPROF, ILPROF
 6030   FORMAT(1X,'In REFLFIND mode=2 searching for reflection',3i4)
      END IF
      IMODE = 4
C
C---- Call MODARRAY to extract the intensity values, image numbers and 
C     fraction_recorded values for this reflection, stored in /PHIPROFILE/
c     in INTPROFILE,IDPROFILE,FRACPROFILE
C
      CALL MODARRAY(IMODE,LBGRAT,LIRECG,LLASTREC,LINTPOST,
     +              LSIGPOST)
C
C---- Scale the FRACPROFILE values so that they are on the same scale as 
C     the intensities. Initialise INTMAX as large negative because especially if profile
C     is truncated, the largest INTPROFILE(I) can be negative.
C
      INTMAX = -99999
      FRACMAX = 0.0
      SUMFRAC = 0.0
      DO 110 I = 1,NBITPROF
        INTMAX = MAX(INTMAX,INTPROFILE(I))
        FRACMAX = MAX(FRACMAX,FRACPROFILE(I))
        SUMFRAC = SUMFRAC + FRACPROFILE(I)
 110  CONTINUE
      SCALE = REAL(INTMAX)/FRACMAX
      IF (SCALE.LT.0.0) SCALE = 0.0
C      DO 112 I = 1,NBITPROF
C        FRACPROFILE(I) = SCALE*FRACPROFILE(I)
C 112  CONTINUE
C
C---- Write the XML to plot the phi profile, after testing error flag from MODARRAY
C     which is passed via /MISC/, which is set to 1 if reflection is not found.
C
      IF (IERRFLG.EQ.0) THEN
C
C---- Write XML 
C
        DO 120 I = 1,NBITPROF
            WRITE(IOLINE,FMT=6032)
     $           IDPROFILE(I),INTPROFILE(I),SCALE*FRACPROFILE(I)
            CALL WRITE_SOCKET_LENGTH
     $           (SERVERFD,LENSTR(IOLINE),IOLINE)
 6032       FORMAT('<?xml version="1.0"?>',
     $           '<!DOCTYPE phiprofile_response>',
     $           '<phiprofile_response>',
     +            '<status><code>ok</code></status>',
     $           '<image_number>', i7,
     $           '</image_number><intensity>',I9,
     $           '</intensity><fraction_recorded>',F10.0,
     $           '</fraction_recorded>',
     $           '</phiprofile_response>')
 120    CONTINUE
C
        WARNING = ''
        IF (STARTTRUNC) WARNING = 'truncated_start'
        IF (ENDTRUNC) WARNING = 'truncated_end'
        IF (STARTTRUNC.AND.ENDTRUNC) WARNING = 'truncated_both'
        WRITE(IOLINE,FMT=6034) 2*ETA/DTOR,2*ETA/DTOR,
     +                      WARNING(1:LENSTR(WARNING))
            CALL WRITE_SOCKET_LENGTH
     $           (SERVERFD,LENSTR(IOLINE),IOLINE)
 6034       FORMAT('<?xml version="1.0"?>',
     $           '<!DOCTYPE phiprofile_final>',
     $           '<phiprofile_final>',
     +            '<status><code>ok</code></status>',
     +           '<mosaicity>',F7.3,'</mosaicity>',
     +           '<mosaic_block_size>',F8.2,'</mosaic_block_size>'
     +           '<warning>',A,'</warning>',
     +           '</phiprofile_final>')
C

        WRITE(IOUT,FMT=6040) IHPROF,IKPROF,ILPROF,NBITPROF,
     +      SUMFRAC,(IDPROFILE(I),INTPROFILE(I),
     +       FRACPROFILE(I),I=1,NBITPROF)
        IF (ONLINE) WRITE(ITOUT,FMT=6040) IHPROF,IKPROF,ILPROF,
     +         NBITPROF,SUMFRAC,(IDPROFILE(I),INTPROFILE(I),
     +         FRACPROFILE(I),I=1,NBITPROF)
 6040     FORMAT(/,1X,'Profile for reflection ',3i4,
     +     '  (Number of parts',I3,', sum of fraction recorded',F5.2,
     +     ')',/,1X,'Image numbers, intensities and fraction recorded',
     +     ' are shown below:',/,(1x,5(I3,I8,F5.2,5X)))
C
        IF (STARTTRUNC) THEN
          WRITE(IOUT,FMT=6046)
          IF (ONLINE) WRITE(ITOUT,FMT=6046)
 6046     FORMAT(/,1X,'Note that the phi profile is truncated at the',
     +      ' start as the reflection starts before the first image.')
        END IF
        IF (ENDTRUNC) THEN
          WRITE(IOUT,FMT=6048)
          IF (ONLINE) WRITE(ITOUT,FMT=6048)
 6048     FORMAT(/,1X,'Note that the phi profile is truncated at the',
     +       ' end as the reflection extends beyond the last image.')
        END IF
C
C---- Write to a file for plotting
C
        if (debug(107)) then
          iplot = iplot + 1
          if (iplot.le.9) then
            write(str,fmt=6041) iplot
          else if (iplot.le.99) then
            write(str,fmt=6042) iplot
          else if (iplot.le.999) then
            write(str,fmt=6043) iplot
          else
            iplot = iplot - 999
            write(str,fmt=6041) iplot
          end if
 6041     format(i1)
 6042     format(i2)
 6043     format(i3)
          filenam = 'plotfile'//str(1:lenstr(str))//'.dat'
          CALL CCPDPN (IPROFILE,FILENAM,'UNKNOWN','F',80,IFAIL)
          WRITE(IPROFILE,FMT=6044)
     +        (IDPROFILE(I),INTPROFILE(I),I=1,NBITPROF)
 6044       format(2i6)
          close(iprofile)
        end if

      ELSE
C
C---- write error message, also need to set an error flag in XML
C
        WRITE(IOUT,FMT=6050) IHPROF,IKPROF,ILPROF
        IF (ONLINE) write(iTout,fmt=6050) IHPROF,IKPROF,ILPROF
 6050   FORMAT(1X,'*** Error ***',/1X,'Profile for reflection (',3I4,
     +        ') could not be determined (reflection rejected ',
     +        'during integration.)')
        WARNING = 'rejected'
        WRITE(IOLINE,FMT=6052) 2*ETA/DTOR,2*ETA/DTOR,
     +                      WARNING(1:LENSTR(WARNING))
 6052   FORMAT('<?xml version="1.0"?>',
     $           '<!DOCTYPE phiprofile_final>',
     $           '<phiprofile_final>',
     +            '<status><code>ok</code></status>',
     +           '<mosaicity>',F7.3,'</mosaicity>',
     +           '<mosaic_block_size>',F8.2,'</mosaic_block_size>'
     +           '<warning>',A,'</warning>',
     +           '</phiprofile_final>')
            CALL WRITE_SOCKET_LENGTH
     $           (SERVERFD,LENSTR(IOLINE),IOLINE)
      END IF
C
C---- Reset integration, socket and phi profile flags. SOCKLOPHIPROF is to write
C     XML for reflection intensity for each image as it is integrated, but at present
C     the XML is written after all images have been integrated.
C
      ETA = ETASAVE
      NWMAX = NWMAXSAVE
      SOCKLO = .TRUE.
      SOCKLOPHIPROF = .FALSE.
      PHIPROF = .FALSE.
      NOREF = .FALSE.
      LOVERLAP = .FALSE.
      IF (RESTRESL) REPREDICT = .TRUE.
      RESTRESL = .FALSE.
      STARTTRUNC = .FALSE.
      ENDTRUNC = .FALSE.
      RETURN
      END
C 
C $Id: reflmatch.f,v 1.14 2014/06/10 14:41:44 harry Exp $
C
C== REFLMATCH ==
C
      SUBROUTINE REFLMATCH(INT,FVAR,NBIG,NSPOT,NM,IDELX,IDELY,FORCE,
     +                     LIMIT,VLIM,JSTEP,INTGAIN,ISDGAIN,INTLOST,
     +                     ISDLOST,NGAIN,NLOST,ADDPART,PTMIN,IERR)
      IMPLICIT NONE
C       ===========================================================
C
C
C---- Find the intensities of reflections in the small list
C     from the corresponding reflections in the big list stored
C     in /REFLIST/
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     ..
C     .. Scalar Arguments ..
      REAL VLIM,PTMIN,FVAR
      INTEGER IDELX,IDELY,INT,INTGAIN,INTLOST,ISDGAIN,ISDLOST,
     +        JSTEP,LIMIT,NBIG,NGAIN,NLOST,NM,NSPOT,IERR
      LOGICAL FORCE,ADDPART
C     ..
C     .. Local Scalars ..
      REAL VAR,VGAIN,VLOST,XIOVSUM
      INTEGER I,IB,IBF,IBMIN,IP1,IP2,IS,IXB,IXS,IYB,IYS,MODE,NPR,NRM,
     +        NSUM,MEANINT
      LOGICAL LAST,NOW,LLAST
      CHARACTER CALLEDFROM*80
C     ..
C     .. Local Arrays ..
      INTEGER*2 IFLAG(NREFLS,2),IREFG(1000),IREFL(1000)
      REAL XIOVSIG(1000)
C     ..
C     .. External Subroutines ..
      EXTERNAL GENSORT,SHUTDOWN
C     ..
C     .. External Functions ..
      INTEGER LENSTR
      EXTERNAL LENSTR
C     .. Intrinsic Functions ..
      INTRINSIC ABS,MIN,MOD,SQRT
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/debug.f
C
C $Id: debug.f,v 1.8 2021/06/03 09:41:34 andrew Exp $
C
C--- awk generated include file  debug.h
C---- START of include file debug.h
C
C
C
C     .. Arrays in common /DEBUG/ ..
      REAL XWARN
      INTEGER NDEBUG,IWARN,IARRDUMP
      LOGICAL DEBUG,LPRINT,DUMP,WARN
C
C     .. Scalars in common /DEBUG/ ..
      REAL BGRLIM
      INTEGER NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,IERRLEVEL
      LOGICAL SPOT
      CHARACTER MESSAGE*512
C     
C     ..
C     .. Common Block /DEBUG/..
      COMMON /DEBUG/XWARN(MAXIWARN,100),BGRLIM,NDEBUG(200),
     +       IWARN(MAXIWARN,100),
     $       NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,DEBUG(200),LPRINT(20),
     +       DUMP(30),WARN(100),SPOT,IARRDUMP(30),IERRLEVEL

      COMMON /CDEBUG/ MESSAGE
C     ..
C
C&&*&& end_include  ../inc/debug.f
C&&*&& include  ../inc/gendata.f
C
C $Id: gendata.f,v 1.6 2021/08/19 10:53:54 andrew Exp $
C
C--- awk generated include file  gendata.h
C---- START of include file gendata.h
C
C     IMG       Partiality indicator. 0 for full reflections, 1 to 100
C                   for partials. Negative for partials at the start of the
C                   rotation range, +ve for partials at the end of the 
C                   rotation. Set in subroutine REEK using DELEPS calculated
C                   in subroutine DSTAR
C
C     IRG       Reflection flag  (Set by SPTEST called from DSTAR)
C               =  0  Spot can be measured
C               =  1  Outside R, X, Y limits
C               =  2  Overlapping spot (set later)
C               =  3  Too wide in phi (more than NWMAX images)
C               =  4  DST .GT. DSTMAX  Not included in final film list -
C                       used only to check for overlaps at edge of film.
C               =  5  Overlapping spot from another lattice
C               = 10  Spot is within cusp, but will be observed...not included
C                     in final spot list but must be included in predicted
C                      pattern
C
C               =  21  Spot present on 2 images, this is 1st
C               =  22  Spot present on 2 images, this is 2nd
C
C               =  31  Spot present on 3 images, this is 1st
C               =  32  Spot present on 3 images, this is 2nd
C               =  33  Spot present on 3 images, this is 3rd
C
C               =  41  Spot present on 4 images, this is 1st
C               =  42  Spot present on 4 images, this is 2nd
C               =  43  Spot present on 3 images, this is 3rd
C               =  44  Spot present on 4 images, this is 4th
C
C                 etc etc
C
C     XG        Virtual detector X coordinate in 10 micron units, relative to
C               an origin at the direct beam position. X is parallel to the
C               Y axis in the laboratory frame, ie orthogonal to the rotation
C               axis.
C
C     YG        Virtual detector Y coordinate in 10 micron units, relative to
C               an origin at the direct beam position. Y is parallel to the
C               Z axis in the laboratory frame, ie  the rotation axis.
C
C     IX,IY     are the coordinates of the reflection in pixels
C               (integers) wrt the first pixel in the image (lower left corner
C               cameramans view). For testing for spot overlap, these
C               coordinates are in 10 micron units. Also used for display
C               pixel coordinates when displaying predicted pattern.
C
C     IREC      Pointer to the record number of a particular spot in the
C               list of generated reflections.
C
C     IRECMULT  Record length of reflection records of generate file is
C               36*IRECMULT bytes. For a single lattice IRECMULT=1, for up
C               to 4 lattices IRECMULT=2.
C
c     NXG,NYG,NCG,NRXG,NRYG Measurement box parameters (for external 
C                           third party integration) written to MTZ
C
C     ILATTG        Lattice number 
C     NLATTOVLP     Number of overlaps from other lattices
C     HKLLATTOVLP   h,k,l indices and lattice number of the overlapping 
C                   spot from another lattice
C         HKLLATTOVLP(h,k,l,lattice_number:record_number:overlap_number)
C     ..
C     .. Arrays in common /GENDATA/ ..
      REAL FRACG,PHIG,PHIWG,XG,YG,GOODFIT,PHIOFFSET
      INTEGER INTG,ISDG,IPRO,ISDPRO,IX,IY,IREC,IRECMULT
      INTEGER*2 IRG,IMG,IGFLAG,IHG,IKG,ILG,IMPARTG,
     +          MISYMG,NXG,NYG,NCG,NRXG,NRYG,ILATTG,HKLLATTOVLP,
     +          NLATTOVLP,IDXOVLP,IDYOVLP
C     .. Scalars in common /GENDATA/ ..
      INTEGER IPACKREC,IPACKHEAD,IRECLAST
C     ..
C     .. Common block /GENDATA/ ..
C
C---- Be sure to preserve order of variables to avoid boundary issues
C     as some are I*2
C
      COMMON /GENDATA/FRACG(NREFLS),PHIG(NREFLS),PHIWG(NREFLS),
     $       XG(NREFLS),YG(NREFLS),GOODFIT(NREFLS),PHIOFFSET(NREFLS),
     $       INTG(NREFLS),ISDG(NREFLS),IPRO(NREFLS),ISDPRO(NREFLS),
     +       IX(NREFLS),IY(NREFLS),
     +       IREC(NREFLS),IPACKREC,IPACKHEAD,IRECLAST,IRECMULT,
     +       IRG(NREFLS),IMG(NREFLS),IGFLAG(NREFLS),
     +       IHG(NREFLS),IKG(NREFLS),ILG(NREFLS),
     +       IMPARTG(NREFLS),MISYMG(NREFLS),NXG(NREFLS),NYG(NREFLS),
     +       NCG(NREFLS),NRXG(NREFLS),NRYG(NREFLS),
     +       ILATTG(NREFLS),HKLLATTOVLP(4,NREFLS,MAXLATT),
     +       NLATTOVLP(NREFLS),IDXOVLP(NREFLS,MAXLATT),
     +       IDYOVLP(NREFLS,MAXLATT)
C     ..
C
C

C&&*&& end_include  ../inc/gendata.f
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C&&*&& include  ../inc/pro.f
C
C $Id: pro.f,v 1.1 2002/05/02 10:47:09 harry Exp $
C
C--- awk generated include file  pro.h
C---- START of include file pro.h
C
C
C     .. Arrays in common block /PRO/ ..
      INTEGER*2 IDUM
C     ..
C     .. Common Block /PRO/ ..
      COMMON /PRO/IDUM(MAXBUFF)
C     ..
C
C
C&&*&& end_include  ../inc/pro.f
C&&*&& include  ../inc/reflist.f
C
C $Id: reflist.f,v 1.1 2002/05/02 10:47:12 harry Exp $
C
C--- awk generated include file  reflist.h
C---- START of include file reflist.h
C
C
C     .. Arrays in common block /REFLIST/ ..
      INTEGER XREF,YREF,INTREF,ISDREF
C     ..
C     .. Common Block /REFLIST/ ..
      COMMON /REFLIST/XREF(NREFLS),YREF(NREFLS),INTREF(NREFLS),
     +       ISDREF(NREFLS)
C     ..
C
C
C&&*&& end_include  ../inc/reflist.f
C     ..
C     .. Equivalences ..
C     ..
      SAVE
C
      CALLEDFROM = 'REFLMATCH'
      LLAST = .FALSE.
C
C---- Set pointers for tagging reflections
C
C
      IP1 = MOD(JSTEP,2) + 1
      IP2 = MOD(JSTEP+1,2) + 1
C
C

      DO 10 IB = 1,NBIG
        IFLAG(IB,IP1) = 0
        IF(JSTEP.EQ.1)IFLAG(IB,IP2) = 0
   10 CONTINUE
C
C---- First convert to sorted scanner coordinates
C
      MODE = 6
C
C          *****************************************************
      CALL GENSORT(MODE,FORCE,LIMIT,VLIM,NRM,ADDPART,PTMIN,LLAST)
C          *****************************************************
C
      IF (DEBUG(30)) THEN
        IF (ONLINE) WRITE (ITOUT,FMT=6000) NRM,NSPOT
        WRITE (IOUT,FMT=6000) NRM,NSPOT
      END IF
C
C
      IF (DEBUG(31)) THEN
        NPR = MIN(NRM,20)
        IF (ONLINE) WRITE (ITOUT,FMT=6002) (I,IX(I),IY(I),I=1,NPR)
        WRITE (IOUT,FMT=6002) (I,IX(I),IY(I),I=1,NPR)
      END IF
C
C---- Find matching reflections
C
      IBMIN = 1
      INT = 0
      FVAR = 0.0
      NM = 0
C
C
      DO 50 IS = 1,NRM
        IXS = IX(IS)
        IYS = IY(IS)
C
C---- Set start point for search in big list
C
        IBF = IBMIN
C
C
        DO 20 IB = IBF,NBIG
          IXB = XREF(IB)
C
C---- not far enough in big list
C
          IF ((IXS-IXB).GT.IDELX) THEN
            IBMIN = IB
C
C---- gone too far, no match
C
          ELSE IF ((IXB-IXS).GT.IDELX) THEN
            GO TO 40
          ELSE
            IYB = YREF(IB)
            IF (ABS(IYB-IYS).LE.IDELY) GO TO 30
          END IF
   20   CONTINUE
        GO TO 50
C
C---- Reflection matched
C
   30   NM = NM + 1
        IFLAG(IB,IP1) = 1
C
C
        IF (ISDREF(IB).GT.0) THEN
c     write(iout, *) 'Matched reflection number ', ib, 
c     +          ' intensity ', intref(ib)
          INT = INTREF(IB) + INT
          VAR = ISDREF(IB)
          FVAR = VAR*VAR + FVAR
        END IF
C
C
        IF (DEBUG(31) .AND. NM.LT.NDEBUG(31)) THEN
          IF (ONLINE) WRITE (ITOUT,FMT=6006) IS,IB,IXS,IYS,IXB,IYB,
     +        INTREF(IB),ISDREF(IB)
          WRITE (IOUT,FMT=6006) IS,IB,IXS,IYS,IXB,IYB,INTREF(IB),
     +      ISDREF(IB)
        END IF
C
C
        GO TO 50
C
C
   40   IF (DEBUG(31)) THEN
          IF (ONLINE) WRITE (ITOUT,FMT=6004) IS,IXS,IYS,IB
          WRITE (IOUT,FMT=6004) IS,IXS,IYS,IB
        END IF
C
C
   50 CONTINUE
C
C
      IF (JSTEP.NE.1) THEN
C
C---- Find which reflections are lost and gained in this step
C     relative to previous step
C
        NGAIN = 0
        NLOST = 0
        INTGAIN = 0
        VGAIN = 0
        ISDGAIN = 0
        ISDLOST = 0
        INTLOST = 0
        VLOST = 0
        XIOVSUM = 0.0
        MEANINT = 0
        NSUM = 0
C
C
        DO 60 IB = 1,NBIG
          NOW = (IFLAG(IB,IP1).EQ.1)
          LAST = (IFLAG(IB,IP2).EQ.1)
C
C
          IF (NOW .AND. (.NOT.LAST)) THEN
            NGAIN = NGAIN + 1
C
C
            IF (NGAIN.GT.1000)THEN
              IF (IERR.LT.1002) THEN
                IERR = MAX(IERR+1,1000)
                RETURN
              ELSE
                IERR = 0
                GO TO 80
              ENDIF
            ELSE
              IERR = 0
              IREFG(NGAIN) = IB
              VAR = ISDREF(IB)
C
C
              IF (VAR.GT.0.0) THEN
                INTGAIN = INTREF(IB) + INTGAIN
                VGAIN = VAR*VAR + VGAIN
                XIOVSIG(NGAIN) = REAL(INTREF(IB))/VAR
                XIOVSUM = XIOVSUM + XIOVSIG(NGAIN)
                NSUM = NSUM + 1
              END IF
C
C
            END IF
          ELSE IF (LAST .AND. (.NOT.NOW)) THEN
            NLOST = NLOST + 1
C
C
            IF (NLOST.GT.1000) THEN
              IF (IERR.LT.1002) THEN
                IERR = MAX(IERR+1,1000)
                RETURN
              ELSE
                IERR = 0
                GO TO 70
              ENDIF
            ELSE
              IREFL(NLOST) = IB
              VAR = ISDREF(IB)
C
C
              IF (VAR.GT.0.0) THEN
                INTLOST = INTREF(IB) + INTLOST
                VLOST = VAR*VAR + VLOST
              END IF
            END IF
          END IF
   60   CONTINUE
C
C
        IF (VGAIN.NE.0) ISDGAIN = SQRT(VGAIN)
        IF (VLOST.NE.0) ISDLOST = SQRT(VLOST)
        IF (NSUM.NE.0)  THEN
           XIOVSUM = XIOVSUM/NSUM
           MEANINT = INTGAIN/NSUM
        END IF
C
C
        IF (DEBUG(31)) THEN
          IF (NGAIN.GT.0) THEN
            WRITE (IOUT,FMT=6010) JSTEP,NGAIN,INTGAIN,ISDGAIN,XIOVSUM,
     +        MEANINT,
     +      (I,IREFG(I),XREF(IREFG(I)),YREF(IREFG(I)),
     +         INTREF(IREFG(I)),ISDREF(IREFG(I)),XIOVSIG(I),I=1,NGAIN)
            IF (ONLINE) WRITE (ITOUT,FMT=6010) JSTEP,NGAIN,INTGAIN,
     +          ISDGAIN, XIOVSUM,MEANINT,
     +          (I,IREFG(I),XREF(IREFG(I)),YREF(IREFG(I)),
     +           INTREF(IREFG(I)),ISDREF(IREFG(I)),
     +          XIOVSIG(I),I=1,NGAIN)
          ELSE
            IF (ONLINE) WRITE (ITOUT,FMT=6012) JSTEP,NGAIN
            WRITE (IOUT,FMT=6012) JSTEP,NGAIN
          END IF
C
C
          IF (NLOST.GT.0) THEN
            WRITE (IOUT,FMT=6014) JSTEP,NLOST,INTLOST,ISDLOST,
     +        (I,IREFL(I),INTREF(IREFL(I)),ISDREF(IREFL(I)),I=1,NLOST)
            IF (ONLINE) WRITE (ITOUT,FMT=6014) JSTEP,NLOST,INTLOST,
     +          ISDLOST, (I,IREFL(I),INTREF(IREFL(I)),ISDREF(IREFL(I)),
     +          I=1,NLOST)
          ELSE
            IF (ONLINE) WRITE (ITOUT,FMT=6016) JSTEP,NLOST
            WRITE (IOUT,FMT=6016) JSTEP,NLOST
          END IF
        END IF
C
C
        RETURN
   70   IF (ONLINE) WRITE (ITOUT,FMT=6008)
        WRITE (IOUT,FMT=6008)
        NSHUTERR = 1
        CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
   80   IF (ONLINE) WRITE (ITOUT,FMT=6008)
        WRITE (IOUT,FMT=6008)
        NSHUTERR = 2
        CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
      ELSE 
        IERR = 0
      END IF
C
C---- Format statements
C
 6000 FORMAT (/1X,'REFLMATCH',I6,' Reflections selected by GENSORT out',
     +       ' of',I5,' Generated')
 6002 FORMAT (/1X,'Coordinates',/ (1X,I3,3X,2I6))
 6004 FORMAT (1X,'*** ERROR ***  No match for Refl',I4,' at Coords',
     +       2I6,'  after searching to',I4,' in BIGLIST')
 6006 FORMAT (1X,'Match IS=',I4,' to IB=',I4,' coords',2I5,' and',2I5,
     +       '  INT,SD',2I6)
 6008 FORMAT (//1X,'More than 1000 Reflections LOST/GAINED per STEP',
     +       /,1X,'RERUN with smaller STEP SIZE')
 6010 FORMAT (/1X,'STEP',I3,5X,I4,' Reflections gained,',
     +        ' Total Intensity',
     +        I8,' SD',I6,/,1X,'Mean I/sig(I)',F6.2,'  Mean intensity',
     +        ' per spot',I8,/,1X,'  I   IB    IX    IY        INT',
     +        '    SD  I/SD',/, (1X,I3,I5,2I6,5X,2I6,F6.1))
 6012 FORMAT (/1X,'STEP',I3,5X,I4,' Reflections gained')
 6014 FORMAT (/1X,'STEP',I3,5X,I4,' Reflections lost, Total intensity',
     +       I6,' SD',I6,/ (1X,I3,I5,2I6))
 6016 FORMAT (/1X,'STEP',I3,5X,I4,' Reflections lost')
C
C
      END
C $Id: refort.f,v 1.12 2021/06/03 09:42:13 andrew Exp $
C
C== REFORT ==
C
      SUBROUTINE REFORT(ISTAT)
      IMPLICIT NONE
C     =======================
C
C---- Refines orientation and cell parameters
C
C
C     ..
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
