     +     ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,
     +     BLKSIZE
      INTEGER ISYN,IMONO,NWMAX,IPAD,NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS
C     ..
C     .. logicals in common block /REEKE/ ..
      LOGICAL LOGETA,NUREEK,LCAMCON,GENGON,FOURCIRCLE,THREECIRCLE,
     +        VERTICAL
C     ..
C     .. Common Block /REEKE/ ..
      COMMON /REEKE/RMC(3,3),AMAT(3,3),SCAXIS(3),S0(3),s0unit(3),
     $     CAMCON(8),BEAMMU(2),X1,X2,Y1,Y2,
     +     Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,DIVH,DIVV,DELAMB,
     +     ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,ISYN,IMONO,
     $     NWMAX,IPAD,
     $     NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS,LOGETA,NUREEK,LCAMCON,
     $     GENGON,FOURCIRCLE,THREECIRCLE,
     +     BLKSIZE,VERTICAL
C     ..
C
C
C&&*&& end_include  ../inc/reeke.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C     ..
      SAVE
C     .. Equivalences ..
      EQUIVALENCE (PARM(1),PHIX), (PARM(2),PHIY), (PARM(3),PHIZ)
      EQUIVALENCE (PARM(4),CELLX(1))
C     ..
C
C
C
      CALLEDFROM = 'REFORT'
      LAST = .FALSE.
C
C---- NC is number of cell parameters
C
      NP = NC + 3
      NPSTOR = NP
C
C---- On first cycle refine only orientation
C
      IF (IC.EQ.1) NP = 3
      NPP = NP + 1
C
      IF (IPRINT.GT.0 .OR. IC.EQ.ICMAX) THEN
        WRITE (IOUT,FMT=6000) IC
        IF (ONLINE) WRITE (ITOUT,FMT=6000) IC
      END IF
C
C---- Start cycle
C
      NCYC = 0
   10 CONTINUE
      NCYC = NCYC + 1
C
      IJ = 0
      NPS = NP + NS
C
C
      DO 30 I = 1,NPS
        S(I) = 0.0
        DO 20 J = 1,NPS
          IJ = IJ + 1
          Q(IJ) = 0.0
   20   CONTINUE
   30 CONTINUE
C
C---- Set up matrices
C
      DO 50 I = 1,3
        DO 40 J = 1,3
          AMAT(J,I) = 0.0
          DO 38 K=1,6
            DUBDCC(J,I,K) = 0.0
   38     CONTINUE
   40   CONTINUE
   50 CONTINUE
C
C          **********************
      CALL MATSET(CELLX,NC,IPRINT)
C          **********************
C
      SIGRSQ = 0.0
      NANG = 0
C
C
      IF (IPRINT.GT.0 .OR. LAST) THEN
        WRITE (IOUT,FMT=6002) ANGLIM
        IF (ONLINE) WRITE (ITOUT,FMT=6002) ANGLIM
      END IF
C
      IF (IPRINT.GT.0) THEN
        WRITE (IOUT,FMT=6004)
        IF (ONLINE) WRITE (ITOUT,FMT=6004)
      END IF
C
      KREJ = 0
C
      CPX = COS(DTOR*PHIX)
      SPX = SIN(DTOR*PHIX)
      CPY = COS(DTOR*PHIY)
      SPY = SIN(DTOR*PHIY)
C
C---- Loop over each reflection. Must loop over entire array, discarding
C     reflections with zero F, because data for each pack is assigned the
C     same amount of space in array, and there will (in general) be
C     gaps between the data from adjacent packs, which can be detected by
C     zero F values, as POSTREFL has a hardwired limit of 0.05 for F
C
      DO 110 K = 1,MREF
        IF (F(K).LT.0.001) GOTO 110
        PHIP = (PHI(K)+PHIZ)
        CP = COS(DTOR*PHIP)
        SP = SIN(DTOR*PHIP)
C
C---- Loop over each parameter
C
        DO 70 I = 1,NPP
C
C              *********
          CALL CLEAR(P)
          CALL CLEAR(CX)
          CALL CLEAR(CY)
C              *********
C
C---- Set up rotation matrices
C       
          CX(1,1) = 1.0
          CX(2,2) = CPX
          CX(2,3) = -SPX
          CX(3,2) = SPX
          CX(3,3) = CPX
          CY(1,1) = CPY
          CY(1,3) = SPY
          CY(2,2) = 1.0
          CY(3,1) = -SPY
          CY(3,3) = CPY
          P(1,1) = CP
          P(2,1) = SP
          P(1,2) = -SP
          P(2,2) = CP
          P(3,3) = 1.00
          IM = I
          IF (I.LE.4) IM = 1
C
C
          IF (I.EQ.2) THEN
C
C---- Set up derivatives
C
C                *********
            CALL CLEAR(CX)
C                *********
C
            CX(2,2) = -SPX
            CX(2,3) = -CPX
            CX(3,2) = CPX
            CX(3,3) = -SPX
          ELSE IF (I.EQ.3) THEN
C
C                *********
            CALL CLEAR(CY)
C                *********
C
            CY(1,1) = -SPY
            CY(1,3) = CPY
            CY(3,1) = -CPY
            CY(3,3) = -SPY
          ELSE IF (I.EQ.4) THEN
C
C                ********
            CALL CLEAR(P)
C                ********
C
            P(1,1) = -SP
            P(2,1) = CP
            P(1,2) = -CP
            P(2,2) = -SP
          END IF
C
C              ****************
          CALL MATMUL3(C,CY,CX)
          CALL MATMUL3(PC,P,C)
C              ****************
C
          IF (IM.GE.5) IM = IM - 3
C
          IF (IM.EQ.1) THEN
C              ************************
            CALL MATMUL3(PCA,PC,AMAT(1,1))
C              ************************
          ELSE
C              ************************
            CALL MATMUL3(PCA,PC,DUBDCC(1,1,IM-1))
C              ************************
          END IF
C
          DO 60 J = 1,3
            X(J) = PCA(J,1)*IH(K) + PCA(J,2)*IK(K) + PCA(J,3)*IL(K)
   60     CONTINUE
C
C---- Skip if calculating derivatives
C
          IF (I.NE.1) THEN
C
C---- Deriv of RC w.r. to relevant ptr
C
            DR(I-1) = (X(1)*XX+X(1)+X(2)*YY+X(3)*ZZ)/ (RC)/DST*WW(K)
          ELSE
            XX = X(1)
            YY = X(2)
            ZZ = X(3)
            XSQ = XX*XX
            YSQ = YY*YY
            ZSQ = ZZ*ZZ
            DSTSQ = XSQ + YSQ + ZSQ
            STEMP = 1.0 - DSTSQ*0.25
            IF (STEMP.LT.0.0) WRITE(6,8888) STEMP
8888        FORMAT(' COSTH FROM REFORT = ',F20.10)
            COSTH = SQRT(STEMP)
            STEMP = DSTSQ
            IF (STEMP.LT.0.0) WRITE(6,8889) STEMP
8889        FORMAT(' DST FROM REFORT = ',F20.10)
            DST = SQRT(STEMP)
C
C---- Note change in next lines. If refining one beam parameter, then
C     it should be the mosaic spread, if two, then it is the beam
C     divergences. This does NOT depend on whether or not the data is from
C     a synchrotron.
C
            IF (NS.EQ.1) THEN
              PARM(10) = ETA
            ELSE
              PARM(10) = DIVH
              PARM(11) = DIVV
            END IF
            EH = DIVH*ZZ
            EV = DIVV*YY
C
C---- Include the beam-divergence contribution from DELCOR
C
            EH = EH + DELCOR*DSTSQ
            STEMP = (EH*EH + EV*EV)/ (YSQ + ZSQ)
            IF (STEMP.LT.0.0) WRITE(6,8877) STEMP
8877        FORMAT(' DIVERG FROM REFORT = ',F20.10)
            DIVERG = SQRT(STEMP)
C
            TWOEPS = ((DIVERG+ETA)*COSTH+DELAMB*DST*0.5)*DST
C
C---- Calculate radius of point H,K,L from centre of sphere
C
            STEMP = 2.0*XX + 1.0 + DSTSQ
            IF (STEMP.LT.0.0) WRITE(6,8866) STEMP
8866        FORMAT(' RC FROM REFORT = ',F20.10)
            RC = SQRT(STEMP)
C
C---- Correct for fraction recorded of spot
C     -ve frac denotes phi-start, +ve phi-end.
C     After making all fracs +ve, obsd radius of
C     refln (sphere-origin) is 1-(.5-f)*eps*2 for y-ve phi-end
C     or y+ve phi-start;  or 1+(.5+f)*eps*2 for the other
C     situations.
C
            IF (YY.LT.0.0) THEN
              IF (F(K).LT.0.0) THEN
                AM = -F(K)
              ELSE
                AM = 1.0 - F(K)
              END IF
            ELSE IF (F(K).LT.0.0) THEN
              AM = F(K) + 1.0
            ELSE
              AM = F(K)
            END IF
C
C---- Observed radius
C     Assume rocking curve is a COS function (-PI/2,+PI/2)
C
C---- Observed radius set to 1.0 for extra ref
C     Put eps term in rc, assume d(rc)/dx remains the same
C
            FM = 1.0 - 2.0*AM
            IF (ABS(FM).GT.1.0) FM = SIGN(1.0,FM)
            RO = 1.0
            RC = RC - ASIN(FM)*TWOEPS/PI
C
            DANG(K) = (RO-RC)/DST
            ANG = DANG(K)*RTOD
            IF (ABS(ANG).LT.ANGLIM) THEN
              NANG = NANG + 1
              SIGRSQ = DANG(K)*DANG(K) + SIGRSQ
C
C---- Skip to end of parameter loop
C
            ELSE
              GO TO 100
            END IF
          END IF
   70   CONTINUE
C
C---- End of parameter loop
C
C
C---- Form least squares matrix
C
C---- Extra refinement only on second pass (IC>1)
C     Set NP to NNP for ref
C
        NNP = NP
        IF (IC.GT.1 .AND. NS.GT.0) THEN
          NNP = NP + NS
C
C---- Derivs for ETA and divergence
C
          TERM = -ASIN(FM)/PI
C
C---- ETA or DIVH=DIVV
C
          DR(NP+1) = TERM*COSTH*WW(K)
C
C---- DIVH and DIVV
C      sqrt(GH*GH*cos*cos + GV*GV*sin*sin)d*costh where
C      alpha = tan-1 yy/zz
C
          IF (NS.EQ.2) THEN
            DR(NP+1) = TERM*COSTH*DIVH*ZSQ/ (YSQ+ZSQ)/DIVERG*WW(K)
            DR(NP+2) = TERM*COSTH*DIVV*YSQ/ (YSQ+ZSQ)/DIVERG*WW(K)
          END IF
        END IF
C
C
        DO 90 I = 1,NNP
          S(I) = DANG(K)*DR(I)*WW(K) + S(I)
C
C
          DO 80 J = 1,NNP
            IJ = (I-1)*NNP + J
            Q(IJ) = DR(I)*DR(J) + Q(IJ)
   80     CONTINUE
   90   CONTINUE
C
C
        GO TO 110
  100   IF (IPRINT.GT.0) THEN
          WRITE (IOUT,FMT=6006) IH(K),IK(K),IL(K),ANG
          IF (ONLINE) WRITE (ITOUT,FMT=6006)
     +                IH(K),IK(K),IL(K),ANG
        END IF
C
C
        KREJ = KREJ + 1
C
C---- Skip to end of reflection loop
C
  110 CONTINUE
C
C---- Check no. of observations
C
      IF (NANG.LE.NNP) THEN
        GO TO 210
      ELSE
C
C---- Solve least squares equations
C
C            ***************************
        CALL MINV(Q,NNP,DET,IWRK1,IWRK2)
C            ***************************
C
        IF (DET.EQ.0.0) THEN
          GO TO 200
        ELSE
          IJ = 0
C
C
          DO 130 I = 1,NNP
            R(I) = 0
C
C
            DO 120 J = 1,NNP
              IJ = IJ + 1
              R(I) = Q(IJ)*S(J) + R(I)
  120       CONTINUE
  130     CONTINUE
C
C
          JJ = 1
C
C---- Reset angle limit to 3*rms deviation
C
          STEMP = SIGRSQ/REAL(NANG)
            IF (STEMP.LT.0.0) THEN
              WRITE(IOUT,FMT=6007)
              IF (ONLINE) WRITE(ITOUT,FMT=6007)
              GOTO 215
            END IF
C          IF (STEMP.LT.0.0) WRITE (6,8855) STEMP
8855      FORMAT(' RMSR FROM REFORT = ',F20.10)
          RMSR = SQRT(STEMP)
          RMSR = RMSR*RTOD
          IF (3.0*RMSR.LT.ANGLIM) ANGLIM = 3.0*RMSR
C
C---- Calculate standard deviations
C
          DO 140 J = 1,NNP
C
C---- Test for negative diagonal element
C     (can occur due to rounding errors)
C
            IF (Q(JJ).LE.0.0) Q(JJ) = 0.0000001
            STEMP = Q(JJ)*SIGRSQ/ (NANG-NNP)
            IF (STEMP.LT.0.0) THEN
              WRITE(IOUT,FMT=6007)
              IF (ONLINE) WRITE(ITOUT,FMT=6007)
              GOTO 215
            END IF
C            IF (STEMP.LT.0.0) WRITE(6,8833) STEMP
8833        FORMAT(' SIG(J) FROM REFORT = ',F20.10)
            SIG(J) = SQRT(STEMP)
            JJ = JJ + NNP + 1
  140     CONTINUE
C
          IF (IPRINT.GT.0 .OR. LAST) THEN
            WRITE (IOUT,FMT=6012) KREJ
            IF (ONLINE) WRITE (ITOUT,FMT=6012) KREJ
            IF (BRIEF) WRITE (IBRIEF,FMT=6012) KREJ
            WRITE (IOUT,FMT=6014) SIGRSQ,RMSR
            IF (ONLINE) WRITE (ITOUT,FMT=6014) SIGRSQ,RMSR
            IF (BRIEF) WRITE (IBRIEF,FMT=6014) SIGRSQ,RMSR
          END IF
C
C---- Convert angle parameters to degrees
C
          JJ = NC + 3
C
C
          DO 150 I = 1,NP
            IF ((I.LE.3) .OR. I.GT. (JJ-NA)) THEN
              R(I) = R(I)*RTOD
              SIG(I) = SIG(I)*RTOD
            END IF
  150     CONTINUE
C
C---- First do phi + cell only
C
          IF (LAST .OR. IPRINT.GT.0) THEN
            WRITE (IOUT,FMT=6016) PHIX,PHIY,PHIZ, (PARM(I),I=4,JJ)
            IF (ONLINE) WRITE (ITOUT,FMT=6016) PHIX,PHIY,PHIZ,
     +          (PARM(I),I=4,JJ)
            IF (BRIEF) WRITE (IBRIEF,FMT=6016) PHIX,PHIY,PHIZ,
     +          (PARM(I),I=4,JJ)
            WRITE (IOUT,FMT=6018) (R(I),I=1,NP)
            IF (ONLINE) WRITE (ITOUT,FMT=6018) (R(I),I=1,NP)
            IF (BRIEF) WRITE (IBRIEF,FMT=6018) (R(I),I=1,NP)
          END IF
C
C---- Add parameter shifts
C
          DO 160 I = 1,NP
            PARM(I) = PARM(I) + R(I)
  160     CONTINUE
C
C
          IF (LAST .OR. IPRINT.GT.0) THEN
            WRITE (IOUT,FMT=6020) PHIX,PHIY,PHIZ, (CELLX(I),I=1,NC)
            IF (ONLINE) WRITE (ITOUT,FMT=6020) PHIX,PHIY,PHIZ,
     +          (CELLX(I),I=1,NC)
            IF (BRIEF) WRITE (IBRIEF,FMT=6020) PHIX,PHIY,PHIZ,
     +          (CELLX(I),I=1,NC)
            WRITE (IOUT,FMT=6022) (SIG(J),J=1,NP)
            IF (ONLINE) WRITE (ITOUT,FMT=6022) (SIG(J),J=1,NP)
            IF (BRIEF) WRITE (IBRIEF,FMT=6022) (SIG(J),J=1,NP)
          END IF
C
C---- Extra ref output after second pass
C
          IF (NS.GT.0 .AND. IC.GT.1) THEN
C
            IF (LAST .OR. IPRINT.GT.0) THEN
C
C---- Write out old params
C
              IF (NS.EQ.1) THEN
                WRITE (IOUT,FMT=6024)
                IF (ONLINE) WRITE (ITOUT,FMT=6024)
                IF (BRIEF) WRITE (IBRIEF,FMT=6024)
              ELSE
                WRITE (IOUT,FMT=6028)
                IF (ONLINE) WRITE (ITOUT,FMT=6028)
                IF (BRIEF) WRITE (IBRIEF,FMT=6028)
              END IF
C
              WRITE (IOUT,FMT=6030) (PARM(I+9)*RTOD,I=1,NS)
              IF (ONLINE) WRITE (ITOUT,FMT=6030)
     +           (PARM(I+9)*RTOD,I=1,NS)
              IF (BRIEF) WRITE (IBRIEF,FMT=6030)
     +           (PARM(I+9)*RTOD,I=1,NS)
              WRITE (IOUT,FMT=6032) (R(I)*RTOD,I=NP+1,NP+NS)
              IF (ONLINE) WRITE (ITOUT,FMT=6032)
     +            (R(I)*RTOD,I=NP+1,NP+NS)
              IF (BRIEF) WRITE (IBRIEF,FMT=6032)
     +            (R(I)*RTOD,I=NP+1,NP+NS)
            END IF                               
C
C---- Add parameter shifts
C
            DO 170 I = 1,NS
              PARM(I+9) = PARM(I+9) + R(NP+I)
  170       CONTINUE
C
C
            IF (NS.EQ.1) THEN
              ETA = PARM(10)
            ELSE
              DIVH = PARM(10)
              DIVV = PARM(11)
            END IF
C
C---- Now write out new extra params
C
            IF (LAST .OR. IPRINT.GT.0) THEN
              WRITE (IOUT,FMT=6034) (PARM(I+9)*RTOD,I=1,NS)
              IF (ONLINE) WRITE (ITOUT,FMT=6034)
     +           (PARM(I+9)*RTOD,I=1,NS)
              IF (BRIEF) WRITE (IBRIEF,FMT=6034)
     +           (PARM(I+9)*RTOD,I=1,NS)
              WRITE (IOUT,FMT=6036) (SIG(J)*RTOD,J=NP+1,NP+NS)
              IF (ONLINE) WRITE (ITOUT,FMT=6036)
     +           (SIG(J)*RTOD,J=NP+1,NP+NS)
              IF (BRIEF) WRITE (IBRIEF,FMT=6036)
     +           (SIG(J)*RTOD,J=NP+1,NP+NS)
            END IF
C
C---- end of extra output after second pass
C
          END IF
C
C---- Here if no extra refinement
C
          IF (LAST) THEN
            GO TO 190
          ELSE
C
C---- If after first cycle of refinement too many reflexions
C     are rejected return to re-index
C
            IF (HKL .OR. NCYC.LE.1 .OR. KREJ.LE.NR/5) THEN
C
C---- Maximum of 5 cycles of REFORT - return to re-index
C
              IF (NCYC.NE.5) THEN
C
C---- Test size of shifts
C
                DO 180 I = 1,NNP
                  IF (ABS(R(I)/SIG(I)).GT.0.1) GO TO 10
  180           CONTINUE
              END IF
            END IF
C
C---- If last full cycle then repeat refinement printing stats
C
            IF (IC.EQ.ICMAX) THEN
              LAST = .TRUE.
              GO TO 10
            END IF
          END IF
        END IF
      END IF
      NP = NPSTOR
      RETURN
C
C---- Finish, prepare for print
C     First deal with normal params
C
  190 JJ = NC + 3
      WRITE (IOUT,FMT=6038)
      IF (ONLINE) WRITE (ITOUT,FMT=6038)
      IF (BRIEF) WRITE (IBRIEF,FMT=6038)
      WRITE (IOUT,FMT=6040) (PARM(I),I=1,3)
      IF (ONLINE) WRITE (ITOUT,FMT=6040) (PARM(I),I=1,3)
      IF (BRIEF) WRITE (IBRIEF,FMT=6040) (PARM(I),I=1,3)
C
C---- Now extras if present
C
      IF (NS.GT.0) THEN
        IF (NS.EQ.1) THEN
          WRITE (IOUT,FMT=6024)
          IF (ONLINE) WRITE (ITOUT,FMT=6024)
          IF (BRIEF) WRITE (IBRIEF,FMT=6024)
        ELSE
          WRITE (IOUT,FMT=6028)
          IF (ONLINE) WRITE (ITOUT,FMT=6028)
          IF (BRIEF) WRITE (IBRIEF,FMT=6028)
        END IF
C
        WRITE (IOUT,FMT=6034) (PARM(I+9)*RTOD,I=1,NS)
        IF (ONLINE) WRITE (ITOUT,FMT=6034) (PARM(I+9)*RTOD,I=1,NS)
        IF (BRIEF) WRITE (IBRIEF,FMT=6034) (PARM(I+9)*RTOD,I=1,NS)
        WRITE (IOUT,FMT=6036) (SIG(J)*RTOD,J=NP+1,NP+NS)
        IF (ONLINE) WRITE (ITOUT,FMT=6036)
     +        (SIG(J)*RTOD,J=NP+1,NP+NS)
        IF (BRIEF) WRITE (IBRIEF,FMT=6036)
     +        (SIG(J)*RTOD,J=NP+1,NP+NS)
C
C---- End of extras
C
      END IF
C
C---- Call MATSET to calculate new AMAT using refined cell parameters.
C     This also moves the refined cell parameters back into RCELL
C
C          **********************
      CALL MATSET(CELLX,NC,IPRINT)
C          **********************
C
      WRITE (IOUT,FMT=6042) (RCELL(I),I=1,6)
      IF (ONLINE) WRITE (ITOUT,FMT=6042) (RCELL(I),I=1,6)
      IF (BRIEF) WRITE (IBRIEF,FMT=6042) (RCELL(I),I=1,6)
C
C---- Real cell parameters
C
C          ************************
      CALL RECCEL(CELL,RCELL,WAVE)
C          ************************
C
      WRITE (IOUT,FMT=6044) CELL
      IF (ONLINE) WRITE (ITOUT,FMT=6044) CELL
      IF (BRIEF) WRITE (IBRIEF,FMT=6044) CELL
C
C---- [A] OR [UB] Matrix
C

c     write out DNA things....

      call dna_output_table_start('parameter_refinement_pass')
      call dna_output_list_start('a_matrix')
      call dna_output_real_item('11', amat(1, 1))
      call dna_output_real_item('12', amat(1, 2))
      call dna_output_real_item('13', amat(1, 3))
      call dna_output_real_item('21', amat(2, 1))
      call dna_output_real_item('22', amat(2, 2))
      call dna_output_real_item('23', amat(2, 3))
      call dna_output_real_item('31', amat(3, 1))
      call dna_output_real_item('32', amat(3, 2))
      call dna_output_real_item('33', amat(3, 3))
      call dna_output_list_end
      call dna_output_list_start('u_matrix')
      call dna_output_real_item('11', umat(1, 1))
      call dna_output_real_item('12', umat(1, 2))
      call dna_output_real_item('13', umat(1, 3))
      call dna_output_real_item('21', umat(2, 1))
      call dna_output_real_item('22', umat(2, 2))
      call dna_output_real_item('23', umat(2, 3))
      call dna_output_real_item('31', umat(3, 1))
      call dna_output_real_item('32', umat(3, 2))
      call dna_output_real_item('33', umat(3, 3))
      call dna_output_list_end
      call dna_output_list_start('cell')
      call dna_output_real_item('a', cell(1))
      call dna_output_real_item('b', cell(2))
      call dna_output_real_item('c', cell(3))
      call dna_output_real_item('alpha', cell(4))
      call dna_output_real_item('beta', cell(5))
      call dna_output_real_item('gamma', cell(6))
      call dna_output_list_end
      call dna_output_list_start('reciprocal_cell')
      call dna_output_real_item('a_star', rcell(1))
      call dna_output_real_item('b_star', rcell(2))
      call dna_output_real_item('c_star', rcell(3))
      call dna_output_real_item('alpha_star', rcell(4))
      call dna_output_real_item('beta_star', rcell(5))
      call dna_output_real_item('gamma_star', rcell(6))
      call dna_output_list_end
      call dna_output_list_start('missetting_angles')
      call dna_output_real_item('phi_x', phix)
      call dna_output_real_item('phi_y', phiy)
      call dna_output_real_item('phi_z', phiz)
      call dna_output_list_end
      call dna_output_list_start('beam_spread_angles')
      call dna_output_real_item('mosaicity', 2.0*ETA*RTOD )
      call dna_output_real_item('divergence_horizontal', 2.0*DIVH*RTOD)
      call dna_output_real_item('divergence_vertical', 2.0*DIVV*RTOD)
      call dna_output_list_end
      call dna_output_table_end



      WRITE (IOUT,FMT=6046) ((AMAT(I,J),J=1,3),
     +      (UMAT(I,J),J=1,3),I=1,3)
      IF (ONLINE) WRITE (ITOUT,FMT=6046) ((AMAT(I,J),J=1,3),
     +    (UMAT(I,J),J=1,3),I=1,3)
      RETURN
  200 WRITE (IOUT,FMT=6010)
      IF (ONLINE) WRITE (ITOUT,FMT=6010)
      IF (BRIEF) WRITE (IBRIEF,FMT=6010)
      GOTO 215
  210 WRITE (IOUT,FMT=6008)
      IF (ONLINE) WRITE (ITOUT,FMT=6008)
      IF (BRIEF) WRITE (IBRIEF,FMT=6008)
 215  WRITE (IOUT,FMT=6011)
      IF (ONLINE) WRITE (ITOUT,FMT=6011)
      NSHUTERR = 1
      WRITE(MESSAGE,FMT=60111)
      CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
C
C---- Format statements
C
 6000 FORMAT (1X,16 ('+++++'),//10X,'PARAMETER REFINEMENT PASS',I3)
 6002 FORMAT (/' Reflections rejected if angular error >',F6.2,' deg.',
     +       /)
 6004 FORMAT (/7X,'H   K   L   ANGERR(degrees)  ')
 6006 FORMAT (4X,3I4,F7.2)
 6007 FORMAT (/,1X,'*** Ill determined normal matrix ***')
 6008 FORMAT ('***  Fewer data than parameters ***')
 6010 FORMAT (/6X,'Singular equations ')
 6011 FORMAT (/,1X,'There is insufficient',
     +        ' data to refine all the parameters',/,1X,
     +        'This can happen if you are using far too small a value',
     +        ' for the mosaic spread.',/,1X,
     +        'If you are using the refined beam parameters (USEBEAM) ',
     +        'first check that the',/,1X,'divergence (or mosaicity) ',
     +         'has not refined to either too large or ',
     +        'too small a value. If not the case',/,1X,'Try using ',
     +        ' more images by increasing WIDTH or NADD (POSTREF',
     +        ' keyword)',/,1X,'or FIX some or ALL  cell parameters.')
60111 FORMAT('Too few data to refine all parameters.__nl__This can ',
     +       'happen if the mosaic spread is too small.__nl__',
     +       'See mosflm.lp file for suggestions.')
 6012 FORMAT (' Number of reflections rejected: ',I5)
 6014 FORMAT (' Sum of (RO-RC)/D*)SQD = ',F12.8,' Rms residual = ',F8.3,
     +       ' degrees')
 6016 FORMAT (/11X,'PHIX      PHIY      PHIZ    Refined ,reciprocal ce',
     +       'll parameters',/'   Old ',3F10.3,3F10.6,3F10.4)
 6018 FORMAT (' Shifts',3F10.3,3F10.6,3F10.4)
 6020 FORMAT ('   New ',3F10.3,3F10.6,3F10.4)
 6022 FORMAT ('  S.D. ',3F10.3,3F10.6,3F10.4)
 6024 FORMAT (/10X,'Mosaic spread')
 6028 FORMAT (/10X,'DIVH     DIVV (Horizontal and vertical beam',
     +        ' divergences)')
 6030 FORMAT ('   Old ',2F8.3)
 6032 FORMAT (' Shifts',2F8.3)
 6034 FORMAT ('   New ',2F8.3)
 6036 FORMAT ('  S.D. ',2F8.3)
 6038 FORMAT (/12X,'Refined Orientation Angles',/10X,'PHIX       PHIY ',
     +       '      PHIZ')
 6040 FORMAT (7X,3F10.3)
 6042 FORMAT (/10X,'Reciprocal cell parameters',/5X,
     $     3F10.6,3F10.3)
 6044 FORMAT (/10X,'Real cell parameters',/5X,6F10.3)
 6046 FORMAT (//5X,'Orientation Matrix [A] or [UB]',15X,'Matrix [U]',
     +       3 (/5X,3F10.6,5X,3F10.6))
C
C
      END
      SUBROUTINE REFPREP(KCELL,CELL,RCELL,CELLS,AMAT,BMAT,
     $     UMAT,TAN2TH,TANMU2,WAVE,XTD,RAST,ORGX,ORGY,NCYCLE,IC,
     $    RFIXDIST,RFIXCELL,LSOL,IERR)
      IMPLICIT NONE
C     .. routine to prepare CELREF refinement parameters
C     .. array arguments
      REAL KCELL(6),CELL(6),RCELL(6),CELLS(3),AMAT(3,3),BMAT(3,3),
     $     UMAT(3,3)
C     .. scalar arguments
      DOUBLE PRECISION TAN2TH,TANMU2
      REAL WAVE,XTD,RAST,ORGX,ORGY
      INTEGER NCYCLE,COUNT,IC,IERR,I,J
      LOGICAL RFIXDIST,RFIXCELL,LSOL
C     ..
C     .. local arrays
      REAL BMATINV(3,3)
C     ..
C     .. local scalars
C
      REAL DET
C      
            NCYCLE = 6
            IERR =   0
C
C---- following was *10, but /RAST seems to be right in some cases at least -
C     should investigate
C
            ORGX = TAN2TH * XTD /RAST ! 0.0
            ORGY = -TANMU2 * XTD /RAST ! 0.0
C     
C     set parameters for refinement 
C     
            IF (RFIXDIST)THEN
              IC = 5
            ELSE
              IC = 4
            ENDIF
C     
C---- save original cell edges for the chosen symmetry
C     
            IF(.NOT.LSOL.AND.(KCELL(1).GT.0.0).and..not.RFIXcell
     $           .and.(KCELL(2).GT.0.0).and.(KCELL(3).GT.0.0))THEN
              CELLS(1) = KCELL(1)
              CELLS(2) = KCELL(2)
              CELLS(3) = KCELL(3)
            ELSE
              CELLS(1) = CELL(1)
              CELLS(2) = CELL(2)
              CELLS(3) = CELL(3)
            ENDIF
C     
C---  use dimensionless reciprocal cell
C     
            CALL RECCEL(RCELL,CELL,wave)
C     
C---  need BMAT according to REFIX orthogonalization
C 
c            WRITE(*,FMT=6000)CELL
c            WRITE(*,FMT=6020)((UMAT(I,J),J=1,3),(BMAT(I,J),J=1,3),
c     $           (AMAT(I,J),J=1,3),I=1,3)
c try dimensionless 26.06.2006
            CALL RFBMAT(BMAT,RCELL,1.0)
            CALL MINV33(BMATINV,BMAT,DET)
            CALL MATMUL3(UMAT,AMAT,BMATINV)
            CALL CHECKU(UMAT)
c            WRITE(*,FMT=6040)((UMAT(I,J),J=1,3),(BMAT(I,J),J=1,3),
c     $           (AMAT(I,J),J=1,3),I=1,3)
            RETURN
 6000       format(/,' Cell: ',3F9.3,3F8.3)
 6020       format(/,'Mosflm:',/,'   UMAT: ',3F9.5,'    BMAT: ',3F9.5,
     $           '    AMAT: ',3F9.5,2(/,9X,3(3F9.5,10X)))
 6040       format(/,'Refix:',/,'   UMAT: ',3F9.5,'    BMAT: ',3F9.5,
     $           '    AMAT: ',3F9.5,2(/,9X,3(3F9.5,10X)))
            END
C $Id: refsor.f,v 1.4 2018/08/30 15:31:27 rtkit Exp $
C== REFSOR ==
      SUBROUTINE REFSOR(IA,NREF,NKEY,IDIM)
C     ====================================
C
        implicit none
C
C
C This subroutine is used to sort the reflection data held in core. It
C is a modified version of the subroutine 'AHVSOR' from eleanor dodson's
C version of the program 'CAD'
C
C
C---- Parameters
C
C         IA (I/O)  INTEGER ARRAY CONTAINING THE REFLECTION DATA KEYS
C                   NKEY KEYS FOR REFLN 1 FOLLOWED BY NKEY KEYS FOR EACH
C                   REFLECTION UP TO NREF REFLECTIONS  (MAX OF 10 )
C       NREF (I)    THE NO. OF REFLECTIONS TO BE SORTED
C       NKEY (I)    NUMBER OF SORT KEYS (INCLUDING THE POSITION INDEX AS
C                   THE LAST KEY
C       IDIM (I)    THE NUMBER OF ELEMENTS IN THE ARRAY IA
C
C---- Specification statements
C
C     .. Scalar Arguments ..
      INTEGER IDIM,NKEY,NREF
C     ..
C     .. Array Arguments ..
      INTEGER*2 IA(IDIM)
C     ..
C     .. Local Scalars ..
      INTEGER BOTTOM,THISCHUNK,CUTOFF,DOWN,HIGH,I,ITEMP,J,J1,J2,
     +        LOW,M,MIDDLE,MIN,MM,MMM,N,STACK,TOP,UP,MAXSTACK
      CHARACTER*40 LINE40
      parameter (MAXSTACK = 32)
C     ..
C     .. Local Arrays ..
      INTEGER*2 CUT(10)
      INTEGER SAVE(2,MAXSTACK)
C     ..
C     .. External Functions ..
      INTEGER ICMP
      EXTERNAL ICMP
C     ..
C     .. Data statements ..
      DATA    CUTOFF/20/
C     ..
C
C---- Sort data
C
      STACK = 0
      LOW = 1
      HIGH = NREF
   10 CONTINUE
      THISCHUNK = HIGH - LOW
C
C
      IF (THISCHUNK.GT.CUTOFF) THEN
          MIDDLE = (LOW+HIGH)/2
C
C             ***************************
          IF (ICMP(IA,LOW,IA,MIDDLE,NKEY).GT.0) THEN
C             ***************************
C
              J1 = (LOW-1)*NKEY
              J2 = (MIDDLE-1)*NKEY
C
C
              DO 20 I = 1,NKEY
                  J1 = J1 + 1
                  J2 = J2 + 1
                  ITEMP = IA(J1)
                  IA(J1) = IA(J2)
                  IA(J2) = ITEMP
   20             CONTINUE
C
C
          END IF
C
C             ***************************
          IF (ICMP(IA,MIDDLE,IA,HIGH,NKEY).GT.0) THEN
C             ***************************
C
              J1 = (MIDDLE-1)*NKEY
              J2 = (HIGH-1)*NKEY
C
C
              DO 30 I = 1,NKEY
                  J1 = J1 + 1
                  J2 = J2 + 1
                  ITEMP = IA(J1)
                  IA(J1) = IA(J2)
                  IA(J2) = ITEMP
   30             CONTINUE
C
C                 **************************
              IF (ICMP(IA,LOW,IA,MIDDLE,NKEY).GT.0) THEN
C                 **************************
C
                  J1 = (LOW-1)*NKEY
                  J2 = (MIDDLE-1)*NKEY
C
C
                  DO 40 I = 1,NKEY
                      J1 = J1 + 1
                      J2 = J2 + 1
                      ITEMP = IA(J1)
                      IA(J1) = IA(J2)
                      IA(J2) = ITEMP
   40                 CONTINUE
C
C
              END IF
          END IF
C
          J = (MIDDLE-1)*NKEY
C
C
          DO 50 I = 1,NKEY
              J = J + 1
              CUT(I) = IA(J)
   50         CONTINUE
C
C
          UP = LOW
          DOWN = HIGH
   60     CONTINUE
          DOWN = DOWN - 1
C
C             ***********************
          IF (ICMP(CUT,1,IA,DOWN,NKEY).LT.0) THEN
C             ***********************
C
              GO TO 60
          ELSE
   70         CONTINUE
              UP = UP + 1
C
C                 **********************
              IF (ICMP(CUT,1,IA,UP,NKEY).GT.0) GO TO 70
C                 **********************
C
              IF (UP-DOWN) 80,100,110
   80         J1 = (UP-1)*NKEY
              J2 = (DOWN-1)*NKEY
C
C
              DO 90 I = 1,NKEY
                  J1 = J1 + 1
                  J2 = J2 + 1
                  ITEMP = IA(J1)
                  IA(J1) = IA(J2)
                  IA(J2) = ITEMP
   90             CONTINUE
C
C
              GO TO 60
          END IF
C
C
  100     DOWN = DOWN - 1
          UP = UP + 1
  110     STACK = STACK + 1
C
C
          IF (STACK.LE.MAXSTACK) THEN
              BOTTOM = DOWN - LOW
              TOP = HIGH - UP
              IF (BOTTOM.GT.TOP) THEN
                  SAVE(1,STACK) = LOW
                  SAVE(2,STACK) = DOWN
                  LOW = UP
              ELSE
                  SAVE(1,STACK) = UP
                  SAVE(2,STACK) = HIGH
                  HIGH = DOWN
              END IF
C
              GO TO 10
          END IF
      ELSE
          IF (THISCHUNK.GE.2) THEN
              MM = HIGH - 1
C
C
              DO 140 M = LOW,MM
                  MIN = M
                  MMM = M + 1
C
C
                  DO 120 N = MMM,HIGH
C
C                         *********************
                      IF (ICMP(IA,MIN,IA,N,NKEY).GT.0) MIN = N
C                         *********************
C
  120                 CONTINUE
C
C
                  IF (MIN.NE.M) THEN
                      J1 = (M-1)*NKEY
                      J2 = (MIN-1)*NKEY
C
C
                      DO 130 I = 1,NKEY
                          J1 = J1 + 1
                          J2 = J2 + 1
                          ITEMP = IA(J1)
                          IA(J1) = IA(J2)
                          IA(J2) = ITEMP
  130                     CONTINUE
C
C
                  END IF
  140             CONTINUE
          END IF
C
C
          IF (STACK.EQ.0) THEN
              RETURN
          ELSE
              LOW = SAVE(1,STACK)
              HIGH = SAVE(2,STACK)
              STACK = STACK - 1
              GO TO 10
          END IF
      END IF
C
C---- Error condition
C
      WRITE(LINE40,FMT=6000)maxstack
 6000 format('**STACK LIMIT OF ',i2,' EXCEEDED IN REFSOR**')
C          ****************************************************          
      CALL CCPERR(1,line40)
C          ****************************************************          
C
      END
C
C     $Id: replytf.f,v 1.4 2006/08/29 14:58:23 harry Exp $
      SUBROUTINE REPLYTF(LINE,LINELEN,DEFAULT,FLAG)
      IMPLICIT NONE
C     ..
C     .. scalar arguments
      INTEGER LINELEN
      CHARACTER*1 DEFAULT
      CHARACTER LINE*80
      LOGICAL FLAG     
C     ..
C     .. local scalars
      CHARACTER*1 ANSWER
      CHARACTER LINE2*80
      INTEGER NPARM
      PARAMETER (NPARM = 200)
      REAL VALUE(NPARM)
      INTEGER IBEG(NPARM),IEND(NPARM),ITYP(NPARM),IDEC(NPARM)
      INTEGER NTOK
      EXTERNAL MXDWIO,MXDRIO,MPARSE,CCPUPC
      CALL MXDWIO(LINE(1:LINELEN),1)
      CALL MXDRIO(LINE2)
      CALL MPARSE(LINE2,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
      IF (NTOK.EQ.0) THEN
         ANSWER = DEFAULT
      ELSE
         ANSWER = LINE2(IBEG(1):IEND(1))
         CALL CCPUPC(ANSWER)
      END IF
      IF(ANSWER.EQ.'Y')THEN
         FLAG = .TRUE.
      ELSE
         FLAG = .FALSE.
      ENDIF
      RETURN
      END
C $Id: report.f,v 1.33 2021/04/22 14:50:21 andrew Exp $
C
C== REPORT ==
      SUBROUTINE REPORT(ID,NBOXES,USEOVRLD)
C     ==================================
C
      IMPLICIT NONE
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
