     +     DIVH,DIVV,DELAMB,ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,
     +     ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,
     +     BLKSIZE
      INTEGER ISYN,IMONO,NWMAX,IPAD,NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS
C     ..
C     .. logicals in common block /REEKE/ ..
      LOGICAL LOGETA,NUREEK,LCAMCON,GENGON,FOURCIRCLE,THREECIRCLE,
     +        VERTICAL
C     ..
C     .. Common Block /REEKE/ ..
      COMMON /REEKE/RMC(3,3),AMAT(3,3),SCAXIS(3),S0(3),s0unit(3),
     $     CAMCON(8),BEAMMU(2),X1,X2,Y1,Y2,
     +     Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,DIVH,DIVV,DELAMB,
     +     ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,ISYN,IMONO,
     $     NWMAX,IPAD,
     $     NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS,LOGETA,NUREEK,LCAMCON,
     $     GENGON,FOURCIRCLE,THREECIRCLE,
     +     BLKSIZE,VERTICAL
C     ..
C
C
C&&*&& end_include  ../inc/reeke.f

c     locally used variables

      integer i, j, ICHECK
      real samat(3, 3), sumat(3, 3), sbmat(3, 3), sdelphi(3),
     +     tdelphi(3)
      real uinv(3, 3), det, work(3, 3), work2(3, 3), work3(3, 3)
      logical get_amat, get_umat, get_cell, get_misset
      logical check_amat, check_umat, check_cell, check_misset

c     check to see if this is the first segment, and if not, read the
c     matrix and `relate' it to the first one. 

      if((.not. firsttime) .and. (nseg .gt. 0)) then
c     save the matrices -> save arrays
c     and save the missettings angles
         do j = 1, 3
            do i = 1, 3
               samat(i, j) = amat(i, j)
               sumat(i, j) = umat(i, j)
               sbmat(i, j) = bmat(i, j)
            end do
            sdelphi(j) = delphi(j)
         end do
         
c     pull in the matrices - we only want the a matrix then we'll perform
c     spells to get the u matrix back again. 

         call query_matrix(segment, check_amat, check_umat, check_cell,
     +        check_misset)

c     is the output from this subroutine a problem? -> report an error if
c     this is the case -> now don't worry about the missetting angles, 
c     since these may be null (0) anyway.

         if(.not. check_amat) then
            ierr = -1
            return
         end if

         get_amat = .true.
         get_umat = .false.
         get_cell = .false.
         get_misset = .true.

         call get_matrix(amat, umat, cell, tdelphi,
     +        get_amat, get_umat, get_cell, get_misset,
     +        segment)

 98      format('A Matrix',/,3f12.6, /, 3f12.6, /, 3f12.6)

         write(iout, 98) amat(1, 1), amat(1, 2), amat(1, 3),
     +        amat(2, 1), amat(2, 2), amat(2, 3),
     +        amat(3, 1), amat(3, 2), amat(3, 3)

         if(online) then
            write(itout, 98) amat(1, 1), amat(1, 2), amat(1, 3),
     +        amat(2, 1), amat(2, 2), amat(2, 3),
     +        amat(3, 1), amat(3, 2), amat(3, 3)
         end if

         imat = 1
         iumat = 0
         icell = 1
         icheck = 0

c     perform some spells with this new matrix to get the information
c     where we'd really like it.

         call setmat(imat, iumat, icell, icheck)

         call minv33(uinv, sumat, det)
         call matmul3(work, umat, uinv)
         call rotmat(tdelphi, work2, 1)
         call matmul3(work3, work2, work)
         call rtomisset(work3, delphi, 1)

c     next copy this information back into amat, umat, bmat

         do i = 1, 3
            do j = 1, 3
               amat(i, j) = samat(i, j)
               umat(i, j) = sumat(i, j)
               bmat(i, j) = sbmat(i, j)
            end do
         end do

 99      format('Del phi = ', 3f10.3)

         write(iout, 99) (delphi(i), i = 1, 3)
         if(online) then
            write(itout, 99) (delphi(i), i = 1, 3)
         end if

c     next check that the new values for the missetting angles are 
c     reasonable (within 20 degrees of the old ones) otherwise the
c     postrefinement will break down.

         det = 0.0
         do i = 1, 3
            det = max(det, abs(delphi(i) - sdelphi(i)))
         end do

         if(det .gt. 20.0) then
c     we have an error, because one of the missetting angles is too 
c     far from the others - write an error then abort! in fact, do
c     not write an error.
            
            ierr = -2
            return
         end if

      else

c     this is the first time or some such.... :o)

c     pull in the matrices
         
         call query_matrix(segment, check_amat, check_umat, check_cell,
     +        check_misset)
         
c     is the output from this subroutine a problem? -> report an error if
c     this is the case
         
         if((.not. check_amat) .or. 
     +        (.not. check_misset) .or.
     +        (.not. check_umat) .or. 
     +        (.not. check_cell)) then
            ierr = -1
            return
         end if
         
         get_amat = .true.
         get_umat = .true.
         get_cell = .true.
         get_misset = .true.
         
c     put the missetting angles into delphi as opposed to tdelphi
c     since we know that there will be no misset keywords!

         call get_matrix(amat, umat, umatcell, delphi,
     +        get_amat, get_umat, get_cell, get_misset,
     +        segment)

c     set the missets to within -180 to 180 degrees

         do i = 1, 3
            if(delphi(i) .gt. 180) then
               delphi(i) = delphi(i) - 380
            end if
         end do

      end if

c     come this stage all should be satisfactory!

      return
      end

c     retrieve_segment
c     get all of the segment information back and perform a very similar
c     role to the kwproc subroutine - ie setting everything up! :o)
c     this will return an error code:
c     
c     ierr = 0 everything was peachy
c     ierr = -1 failed to read template
c     ierr = -2 no segment information was saved
c     ierr = -3 start not set
c     ierr = -4 end not set
c     ierr = -5 one of phi start/range was set but not the other
      

      subroutine retrieve_segment(segment, ipackf, ipackl, ierr)

      implicit none
      integer segment, ierr, ipackf, ipackl

