C&&*&& include  ../inc/reeke.f
C
C $Id: reeke.f,v 1.17 2015/05/11 14:19:27 andrew Exp $
C
C--- awk generated include file  reeke.h
C---- START of include file reeke.h
C
C     TOR     For synchrotron sources, degree of polarisation of the beam
C     IMONO   Collimation flag for polarisation.
C             = 0   Pinhole or mirrors
C             = 1   Graphite Monochromator
C             = 2   Synchrotron, use TOR
C     NWMAX   Maximum reflection width in images
C     DSTMAX  dimensionless rlu, = WAVE/RES where RES is the maximum
C             resolution in Angstrom.
C     DSTMIN  dimensionless rlu, = WAVE/DMAX where DMAX is the maximum
C              Bragg spacing
C     S0      radiation source vector (-1,0,0), may be modified by MU values
C     SOURCE  radiation source vector - basis for s0
C     GONIO_angle:  machine angles for generalized goniostats
C     GONIO_angle_SET: fixed offset angles for 3- and 4-circle goniostats
C                      i.e. currently 54.74 deg for Bruker CHI, 50.0deg for
C                      Nonius and Oxford KAPPA 
C     VERTICAL Logical set TRUE if rotation axis is vertical, only
C              affects polarization correction for synchrotron data
C     NSMOOTH  Number of images to use in smoothing refined values of
C              mosaic spread and missetting angles (if being smoothed).
C     ..
C     .. Arrays in common block /REEKE/ ..
      REAL RMC,AMAT,SCAXIS,S0,s0unit,CAMCON,BEAMMU
C     ..
C     .. Scalars in common block /REEKE/ ..
      REAL X1,X2,Y1,Y2,Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,
     +     DIVH,DIVV,DELAMB,ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,
     +     ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,
     +     BLKSIZE
      INTEGER ISYN,IMONO,NWMAX,IPAD,NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS
C     ..
C     .. logicals in common block /REEKE/ ..
      LOGICAL LOGETA,NUREEK,LCAMCON,GENGON,FOURCIRCLE,THREECIRCLE,
     +        VERTICAL
C     ..
C     .. Common Block /REEKE/ ..
      COMMON /REEKE/RMC(3,3),AMAT(3,3),SCAXIS(3),S0(3),s0unit(3),
     $     CAMCON(8),BEAMMU(2),X1,X2,Y1,Y2,
     +     Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,DIVH,DIVV,DELAMB,
     +     ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,ISYN,IMONO,
     $     NWMAX,IPAD,
     $     NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS,LOGETA,NUREEK,LCAMCON,
     $     GENGON,FOURCIRCLE,THREECIRCLE,
     +     BLKSIZE,VERTICAL
C     ..
C
C
C&&*&& end_include  ../inc/reeke.f
C
C---- Include reeke because we need to pass the amatrix into SETMAT
C
      SAVE

C
C---- Move TMAT into AMAT so that it gets passed via /REEKE/ to SETMAT
C     which is called from GETSPLIT
C
      DO 4 I = 1,3
        DO 2 J = 1,3
          AMAT(I,J) = TMAT(I,J)
 2     CONTINUE
 4    CONTINUE
C
C---- Reassign the "best" solution for this lattice to the selected one
C
      BESTSOLAR(ILATT) = ILATTSOL
C
C---- Assign the Bravis lattice type for this solution in this lattice
C
      BESTBRAV = BRAVAIS(ILATTSOL,ILATT)
C
C
C----- Loop over lattices testing the Bravais lattice type of the "best"
C      solution for each one
C
      DO 100 JLATT = 1,NLATTICE
C
C---- Do not test the current lattice
C
        SPLIT = -999.0
        IF (JLATT.EQ.ILATT) GOTO 90
C
C---- do not try to calculate a SPLIT angle for a deleted lattice
C
        IF (.NOT.ACTIVELATT(JLATT)) GOTO 100
C
C---- See if the Bravais lattice type for the best solution of this lattice
C     matches that of the solution chosen by the user
C
        JBEST = BESTSOLAR(JLATT)
        IF (DEBUG(90)) THEN
          WRITE(IOUT,FMT=6000) JLATT,JBEST,
     +           BRAVAIS(JBEST,JLATT),BESTBRAV
          IF (ONLINE) WRITE(ITOUT,FMT=6000) JLATT,JBEST,
     +           BRAVAIS(JBEST,JLATT),BESTBRAV
 6000     FORMAT(1X,'In REVAMAT, testing lattice ',I2,' best solution',
     +           I3,' Bravais lattice ',A,
     +           ' (Bravais for user selected lattice is ',A,')')
        END IF
        IF (BRAVAIS(JBEST,JLATT).EQ.BESTBRAV) THEN
C
C---- Best solution for this lattice is the same, target the amatrix
C
C---- extract AMAT for this solution this lattice
C
          DO 12 K = 1,3
            DO 10 J = 1,3
              AMATLATT(J,K) = CRYSTALUBREF(J,K,JBEST,JLATT)
 10         ENDDO
 12       ENDDO
C
C---- Extract the cell for this solution this lattice
C
          DO 14 K = 1,6
            CELLLATT(K) = CRYSTALCELL(K,JBEST,JLATT)
 14       ENDDO
C
          IF (DEBUG(90)) THEN
             WRITE(IOUT,FMT=6010) ((AMATLATT(I,J),J=1,3),I=1,3)
             IF (ONLINE) WRITE(ITOUT,FMT=6010)
     +                               ((AMATLATT(I,J),J=1,3),I=1,3)
 6010        FORMAT(1X,'Calling TARGMAT with AMAT',/,3(1X,3F10.6,/))
          END IF
C
C---- Call TARGMAT to permute this matrix to be as close as
C     possible to TMAT
C
          CALL TARGMAT(AMATLATT,TMAT,CELLLATT)
C
          IF (DEBUG(90)) THEN
             WRITE(IOUT,FMT=6020) ((AMATLATT(I,J),J=1,3),I=1,3)
             IF (ONLINE) WRITE(ITOUT,FMT=6020)
     +                               ((AMATLATT(I,J),J=1,3),I=1,3)
 6020        FORMAT(//,1X,'After TARGMAT AMAT is ',/,3(1X,3F10.6,/))
          END IF
          IF (SOCKLO) THEN
C
C---- Write XML header (separate document for each lattice)
C
            IF (DEBUG(90)) THEN
              WRITE(IOUT,FMT=6030) JLATT, JBEST,
     $           ((AMATLATT(I,J),J=1,3),I=1,3)
              IF (ONLINE) WRITE(ITOUT,FMT=6030) JLATT, JBEST,
     $           ((AMATLATT(I,J),J=1,3),I=1,3)
            END IF
C
            WRITE(IOLINE2,FMT=6030) JLATT, JBEST,
     $           ((AMATLATT(I,J),J=1,3),I=1,3)
 6030       FORMAT('<?xml version="1.0"?>',
     $         '<!DOCTYPE updated_amatrix_response>',
     $         '<updated_amatrix_response>',
     $         '<status>',
     $         '<code>ok</code>',
     $         '</status>',
     $         '<lattice_number>',I3,'</lattice_number>',
     $         '<solution><number>',I2,'</number>',
     $           '<a_matrix>',
     $           '<a11>',F11.8,'</a11>',
     $           '<a12>',F11.8,'</a12>',
     $           '<a13>',F11.8,'</a13>',
     $           '<a21>',F11.8,'</a21>',
     $           '<a22>',F11.8,'</a22>',
     $           '<a23>',F11.8,'</a23>',
     $           '<a31>',F11.8,'</a31>',
     $           '<a32>',F11.8,'</a32>',
     $           '<a33>',F11.8,'</a33>',
     $           '</a_matrix>','</solution>',
     $          '</updated_amatrix_response>')
            CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(IOLINE2),
     $           IOLINE2)
C
C---- Now compute the SPLIT angle
C
            CALL GETSPLIT(AMATLATT,SPLIT)
            SPLIT = ABS(SPLIT)
C
          END IF
        ELSE
          WRITE(IOUT,FMT=6040) JLATT
          IF (ONLINE) WRITE(ITOUT,FMT=6040) JLATT
 6040     FORMAT(1X,'No SPLIT angle calculation for lattice',I3,
     +           ' as the best solution has a different Bravais',
     +           ' lattice type.')
        END IF
C
 90     IF (DEBUG(90)) THEN
          WRITE(IOUT,FMT=6050) SPLIT,JLATT
          IF (ONLINE) WRITE(ITOUT,FMT=6050) SPLIT,JLATT
 6050     FORMAT(1X,'Writing SPLIT angle ',F8.2,' for lattice',I3,
     +           ' to XML')
          WRITE(IOUT,FMT=6060) JLATT,SPLIT
          IF (ONLINE) WRITE(ITOUT,FMT=6060) JLATT,SPLIT
        END IF
C
C---- Write the SPLIT angle (can be null, ie -999)
C
        IF (SOCKLO) THEN
          WRITE(IOLINE2,FMT=6060) JLATT,SPLIT
 6060     FORMAT('<?xml version="1.0"?>',
     $         '<!DOCTYPE split_angle_response>',
     $         '<split_angle_response>',
     $         '<status>',
     $         '<code>ok</code>',
     $         '</status>',
     $         '<lattice_number>',I3,'</lattice_number>',
     $         '<split_angle>',F9.3,'</split_angle>',
     $         '</split_angle_response>')
          CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(IOLINE2),
     $         IOLINE2)
        END IF
 100  CONTINUE
      RETURN
      END

C
C $Id: rfbmat.f,v 1.3 2010/04/21 14:54:51 harry Exp $
C
C     ==========================
      SUBROUTINE RFBMAT(BMATREF,RCELL,WAVE)
C     ==========================
      IMPLICIT NONE
C
C
C
C----  calculate setting matrix from reciprocal unit cell; NOTE WELL; this
C      is _NOT_ the same BMAT as derived from BMATRX.F (it _IS_ the same as
C      Wolfgang's definition).
C
C RCELL  - RECIPROCAL UNIT CELL PARAMETERS                       (GIVEN)
C          IN RECIPROCAL ANGSTROEM AND DEGREES.
C
C WAVE   - WAVELENGTH in Angstroems because MOSFLM wants AMAT in 
C          dimensionless units  
C
C BMATREF    - SETTING MATRIX IN STANDARD ORIENTATION               (RESULT)
C
C
C
C
C
      INTEGER I
      REAL    RCELL(6),BMATREF(3,3),RC(3),RS(3),ARG,WAVE
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
      DO 10 I=1,3
         ARG=RCELL(I+3)*DTOR
         RC(I)=COS(ARG)
         RS(I)=SIN(ARG)
 10   ENDDO
      BMATREF(1,1)=RCELL(1)*RS(2)*WAVE
      BMATREF(1,2)=RCELL(2)*(RC(3)-RC(1)*RC(2))/RS(2)*WAVE
      BMATREF(1,3)=0.0
      BMATREF(2,1)=0.0
      BMATREF(2,2)=SQRT((RCELL(2)*WAVE*RS(1))**2-BMATREF(1,2)**2)
      BMATREF(2,3)=0.0
      BMATREF(3,1)=RCELL(1)*RC(2)*WAVE
      BMATREF(3,2)=RCELL(2)*RC(1)*WAVE
      BMATREF(3,3)=RCELL(3)*WAVE
      RETURN
      END
C $Id: rhsset.f,v 1.8 2018/09/19 13:50:20 andrew Exp $
C== RHSSET ==
      SUBROUTINE RHSSET
C     ==========================================
C     checks that UMAT is right handed, if not, swaps its hand. derived from 
C     SETMAT
      IMPLICIT NONE
C           Common block PARAMETER
C     .. Include files ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C
C     .. Scalar Arguments ..
      INTEGER ICHECK
C     ..
C     .. Local Scalars ..
      REAL DET,WAVSCAL
      INTEGER I,J,ii,jj
      LOGICAL CELLSCAL
      CHARACTER CALLEDFROM*80
C     ..
C     .. Local Arrays ..
      REAL XMAT(3,3),TCELL(6),TRCELL(6),WORK(3,3)
C     ..
C     .. External Functions ..
      INTEGER LENSTR
      EXTERNAL LENSTR
C     ..
C     .. External Subroutines ..
      EXTERNAL BMATRX,CHECKU,CLCALC,MATMUL3,MINV33,RECCEL,TRANSP,
     +         SHUTDOWN,CELLFIX
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/cell.f
C
C $Id: cell.f,v 1.4 2012/11/21 14:41:22 andrew Exp $
C
C--- awk generated include file  cell.h
C---- START of include file cell.h
C
C     CELL cell dimensions (real space)
C     RCELL reciprocal cell parameters in dimensionless rlu
C     LCELL indicator for cell parameters to be refined
C     
C     LCELL(I) = -1  parameter free
C              =  0  parameter fixed
C              >  0, = J  parameter I constrained to = parameter J
C
C     .. Arrays in Common /CELLCOM/ ..
      REAL UMAT,BMAT,GMAT,CELL,RCELL,UMATCELL,SOFTCELL,VOLUME
      INTEGER LCELL,ICRYST,NUMSPG,NLAUE
C     ..
C     .. Common Block /CELLCOM/ ..
      COMMON /CELLCOM/UMAT(3,3),BMAT(3,3),GMAT(3,3),CELL(6),RCELL(6),
     $       UMATCELL(6),SOFTCELL,VOLUME,LCELL(6),ICRYST,NUMSPG,NLAUE
C     ..
C
C
C&&*&& end_include  ../inc/cell.f
C&&*&& include  ../inc/debug.f
C
C $Id: debug.f,v 1.8 2021/06/03 09:41:34 andrew Exp $
C
C--- awk generated include file  debug.h
C---- START of include file debug.h
C
C
C
C     .. Arrays in common /DEBUG/ ..
      REAL XWARN
      INTEGER NDEBUG,IWARN,IARRDUMP
      LOGICAL DEBUG,LPRINT,DUMP,WARN
C
C     .. Scalars in common /DEBUG/ ..
      REAL BGRLIM
      INTEGER NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,IERRLEVEL
      LOGICAL SPOT
      CHARACTER MESSAGE*512
C     
C     ..
C     .. Common Block /DEBUG/..
      COMMON /DEBUG/XWARN(MAXIWARN,100),BGRLIM,NDEBUG(200),
     +       IWARN(MAXIWARN,100),
     $       NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,DEBUG(200),LPRINT(20),
     +       DUMP(30),WARN(100),SPOT,IARRDUMP(30),IERRLEVEL

      COMMON /CDEBUG/ MESSAGE
C     ..
C
C&&*&& end_include  ../inc/debug.f
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C&&*&& include  ../inc/misc.f
C
C $Id: misc.f,v 1.3 2012/03/23 12:02:50 harry Exp $
C
C--- awk generated include file  misc.h
C---- START of include file misc.h
C
C
C
C     .. Scalars in common /MISC/ ..
      DOUBLE PRECISION STARTTIME,ENDTIME
      REAL PHIBEG,PHIEND,PHIRNG,RMIN,RMAX,WAVE
      INTEGER IPACKID,MININT,IERRFLG
C     ..
C     .. Arrays in common /MISC/ ..
      REAL DELPHI,RESANI
      INTEGER IAX
C     ..
C     .. LOGICAL
      LOGICAL ANITES

C     ..
C     .. Common Block /MISC/ ..
      COMMON /MISC/DELPHI(3),RESANI(3),STARTTIME,ENDTIME,
     $     PHIBEG,PHIEND,PHIRNG,RMIN,RMAX,
     $     WAVE,IAX(3),IPACKID,MININT,IERRFLG,ANITES
C     ..
C
C
C&&*&& end_include  ../inc/misc.f
C&&*&& include  ../inc/reeke.f
C
C $Id: reeke.f,v 1.17 2015/05/11 14:19:27 andrew Exp $
C
C--- awk generated include file  reeke.h
C---- START of include file reeke.h
C
C     TOR     For synchrotron sources, degree of polarisation of the beam
C     IMONO   Collimation flag for polarisation.
C             = 0   Pinhole or mirrors
C             = 1   Graphite Monochromator
C             = 2   Synchrotron, use TOR
C     NWMAX   Maximum reflection width in images
C     DSTMAX  dimensionless rlu, = WAVE/RES where RES is the maximum
C             resolution in Angstrom.
C     DSTMIN  dimensionless rlu, = WAVE/DMAX where DMAX is the maximum
C              Bragg spacing
C     S0      radiation source vector (-1,0,0), may be modified by MU values
C     SOURCE  radiation source vector - basis for s0
C     GONIO_angle:  machine angles for generalized goniostats
C     GONIO_angle_SET: fixed offset angles for 3- and 4-circle goniostats
C                      i.e. currently 54.74 deg for Bruker CHI, 50.0deg for
C                      Nonius and Oxford KAPPA 
C     VERTICAL Logical set TRUE if rotation axis is vertical, only
C              affects polarization correction for synchrotron data
C     NSMOOTH  Number of images to use in smoothing refined values of
C              mosaic spread and missetting angles (if being smoothed).
C     ..
C     .. Arrays in common block /REEKE/ ..
      REAL RMC,AMAT,SCAXIS,S0,s0unit,CAMCON,BEAMMU
C     ..
C     .. Scalars in common block /REEKE/ ..
      REAL X1,X2,Y1,Y2,Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,
     +     DIVH,DIVV,DELAMB,ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,
     +     ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,
     +     BLKSIZE
      INTEGER ISYN,IMONO,NWMAX,IPAD,NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS
C     ..
C     .. logicals in common block /REEKE/ ..
      LOGICAL LOGETA,NUREEK,LCAMCON,GENGON,FOURCIRCLE,THREECIRCLE,
     +        VERTICAL
C     ..
C     .. Common Block /REEKE/ ..
      COMMON /REEKE/RMC(3,3),AMAT(3,3),SCAXIS(3),S0(3),s0unit(3),
     $     CAMCON(8),BEAMMU(2),X1,X2,Y1,Y2,
     +     Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,DIVH,DIVV,DELAMB,
     +     ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,ISYN,IMONO,
     $     NWMAX,IPAD,
     $     NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS,LOGETA,NUREEK,LCAMCON,
     $     GENGON,FOURCIRCLE,THREECIRCLE,
     +     BLKSIZE,VERTICAL
C     ..
C
C
C&&*&& end_include  ../inc/reeke.f
C
C
       SAVE
C     ..
       CALLEDFROM = 'RHSSET'
       IF (DEBUG(70)) THEN
         WRITE(IOUT,FMT=6010) AMAT
         IF (ONLINE) WRITE(ITOUT,FMT=6010) AMAT
 6010    FORMAT(1X,'In RHSSET, AMAT',/,3(12X,3(F10.7,1X),/))
       END IF
C
C---- Set WORK to (UB)transpose
C
C            *****************
       CALL TRANSP(WORK,AMAT)
C            *****************
C
C---- Get reciprocal metric tensor G**-1 in GMAT, = (UB)T.(UB)
C
C            **********************
        CALL MATMUL3(GMAT,WORK,AMAT)
C            **********************
C
C---- Get reciprocal cell dimensions TRCELL
C
C            ******************
        CALL CLCALC(TRCELL,GMAT)
C            ******************
C---- Invert to get real metric tensor G in WORK
C
C            *******************
        CALL MINV33(WORK,GMAT,DET)
C            *******************
C
        IF (DET.EQ.0.0) THEN
           WRITE (IOUT,FMT=6004)
           IF (ONLINE) WRITE (ITOUT,FMT=6004)
           NSHUTERR = 1
          CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
        ELSE
C
C---- Get real cell dimensions from metric tensor
C
C              *****************
          CALL CLCALC(TCELL,WORK)
C              *****************
C
          DO 10 I = 1,3
            TCELL(I) = TCELL(I)*WAVE
   10     CONTINUE
C            ******************
C
C---- Rebuild cell orthogonalization matrix B in BMAT
C
C          ****************************
          CALL BMATRX(BMAT,TRCELL,TCELL,WAVE)
C              ****************************
C
C---- Get matrix U = (UB).(B**-1) to UMAT
C
C              ***********************
          CALL MINV33(XMAT,BMAT,DET)
          CALL MATMUL3(UMAT,AMAT,XMAT)
C          CALL CHECKU(UMAT)
          CALL MINV33(WORK,UMAT,DET)
          IF(DET.LT.-1E-2)THEN
c            WRITE(IOUT,FMT=6000)
c            if(online) WRITE(ItOUT,FMT=6000)
C invert hand of UMAT if determinant negative
            DO 30 I=1,3
              DO 20 J=1,3
                UMAT(I,J) = -UMAT(I,J)
 20           ENDDO
 30         ENDDO
            CALL MATMUL3(AMAT,UMAT,BMAT)
          ENDIF
        ENDIF
c        WRITE (IOUT,FMT=6000) DET
c        WRITE (IOUT,FMT=6002) ((UMAT(II,JJ),JJ=1,3),II=1,3)
c        IF(ONLINE)THEN
c          WRITE (ITOUT,FMT=6000) DET
c          WRITE (ITOUT,FMT=6002) ((UMAT(II,JJ),JJ=1,3),II=1,3)
c        ENDIF

          RETURN
 6000     FORMAT(//,'****** inverting UMAT ********',/,
     $         'Determinant = ',F12.8/)
 6002     FORMAT (/' The matrix U defining the standard setting is:',
     +         /,3 (15X,3(F9.5),/))
 6004     FORMAT (//,1X,'!!! Zero reciprocal cell volume from ',
     +       'orientation matrix !!! (in RHSSET)',//)
          END
C $Id: ringring.f,v 1.2 2011/12/20 11:29:34 harry Exp $
      SUBROUTINE RINGRING(MODE,COUNT,BADSPOTS,SPOTRES,X,Y,
     $     MINRESX,MAXRESX)
      IMPLICIT NONE
C
C     Routine to: 
C     MODE = 1: build up list of spots and their resolutions
C     MODE = 2: sort this list into resolution bins
C     see if there are any spikes in the resolution bins which might
C     look like ice (or other) rings, then exclude spots close to rings
C     MODE = 3: calculate ring diameter & centre, work out distance
C     from centre for each spot...
C     MODE = n; anything else that looks sensible...
C     ..
C     .. scalar arguments
      INTEGER MODE,COUNT,BADSPOTS
      REAL SPOTRES,X,Y,MINRESX(10),MAXRESX(10)
C     ..
C     .. local parameters
      INTEGER BINS
      PARAMETER (BINS=50)
C     ..
C     .. local arrays
      REAL SPOTARRAY(3,5000),REALSPOT(2,BINS)
      INTEGER BINSPOT(BINS)
C     ..
C     .. local scalars
      REAL MAXRES,MINRES,RANGE,INTERVAL,MEAN,SDMEAN,RMSVAR,NSQUARED,
     $     PSDMEAN
      INTEGER I,J,ZEROORONE,THREESIGMA
      SAVE
      IF(MODE.EQ.1)THEN
          SPOTARRAY(1,COUNT) = 1.0/SPOTRES**3
          SPOTARRAY(2,COUNT) = X
          SPOTARRAY(3,COUNT) = Y
      ELSEIF(MODE.EQ.2)THEN
        ZEROORONE = 0
        threesigma = 0
        MAXRES = 999999.99
        MINRES = 0.0
        DO 90 I = 1,10,1
          MINRESX(I) = 0.0
          MAXRESX(I) = 0.0
 90     ENDDO
        DO 100 I=1,COUNT,1
          IF(SPOTARRAY(1,I).LT.MAXRES)MAXRES = SPOTARRAY(1,I)
          IF(SPOTARRAY(1,I).GT.MINRES)MINRES = SPOTARRAY(1,I)
 100    ENDDO
        DO 200 I= 1,BINS,1
          BINSPOT(I) = 0
 200    ENDDO
        RANGE = MINRES - MAXRES
        INTERVAL = RANGE/FLOAT(BINS-1)
        DO 400 I=1,COUNT,1
          DO 300 J=1,BINS,1
            IF((SPOTARRAY(1,I).GE.MAXRES+((J-1)*INTERVAL)).AND.
     $           (SPOTARRAY(1,I).LT.MAXRES+((J)*INTERVAL)))
     $           BINSPOT(J) = BINSPOT(J) + 1
 300      ENDDO
 400    ENDDO
        BINSPOT(BINS) = BINSPOT(BINS)+1
C
C---- now calculate mean number of spots in each bin
C     
        MEAN = FLOAT(COUNT)/FLOAT(BINS)
        PSDMEAN = SQRT(MEAN)
        DO 500 J= 1,BINS,1
          REALSPOT(1,J) = 1.0/(MAXRES+((J-1)*INTERVAL))**0.333
          REALSPOT(2,J) = 1.0/(MAXRES+(J*INTERVAL))**0.333
 500    ENDDO
C
C---- now calculate SD of number of spots in each bin
C 
        BADSPOTS = 0
        SDMEAN = 0.0
        RMSVAR = 0.0
        DO 600 I=1,BINS,1
          SDMEAN = SDMEAN + ((MEAN - BINSPOT(I))*(MEAN - BINSPOT(I)))
          IF(I.LT.BINS)RMSVAR = RMSVAR + (BINSPOT(I)-BINSPOT(I+1))**2
 600    ENDDO
        SDMEAN = SQRT(SDMEAN/FLOAT(BINS-1))
        RMSVAR = SQRT(RMSVAR/(BINS-1))
        J = 1
        DO 700 I = 1,BINS,1
C
C---- 1.4 chosen fairly arbitrarily from a small sample, and only
C     consider resolutions lower than 6.0A
C
          IF((mean*SDMEAN)/(RMSVAR**2).LT.1.4)THEN
            IF((BINSPOT(I).LT.MEAN+3.0*PSDMEAN).OR.
     $           (REALSPOT(2,I).GT.6.0))THEN
c              write(*,'(I4,''  '',1X,F7.3,1X,F7.3,1X,F7.3)')
c     $             BINSPOT(I),FLOAT(BINSPOT(I)) / FLOAT(COUNT),
c     $             REALSPOT(1,I),REALSPOT(2,I)
            ELSE
c              write(*,'(I4,'' *'',1X,F7.3,1X,F7.3,1X,F7.3)')
c     $             BINSPOT(I),FLOAT(BINSPOT(I)) / FLOAT(COUNT),
c     $             REALSPOT(1,I),REALSPOT(2,I)
              BADSPOTS = BADSPOTS + BINSPOT(I)
              MINRES = ((REALSPOT(1,I)+REALSPOT(2,I))/2.0) + 0.05
              MAXRES = ((REALSPOT(1,I)+REALSPOT(2,I))/2.0) - 0.05
              IF(J.GT.1)THEN
                IF(MINRES.GT.MAXRESX(J-1))THEN
                  MAXRESX(J-1) = MAXRES
                ELSE
                  MAXRESX(J) = MAXRES
                  MINRESX(J) = MINRES
                  J = J + 1
                ENDIF
              ELSE
                MAXRESX(J) = MAXRES
                MINRESX(J) = MINRES
                J = J + 1
              ENDIF
            ENDIF
          ELSE
c              write(*,'(I4,''  '',1X,F7.3,1X,F7.3,1X,F7.3)')
c     $             BINSPOT(I),FLOAT(BINSPOT(I)) / FLOAT(COUNT),
c     $             REALSPOT(1,I),REALSPOT(2,I)
          ENDIF
 700    ENDDO
        IF(FLOAT(BADSPOTS)/FLOAT(COUNT).GT.0.75)THEN
          PRINT*,'Too many spots in ice-ring - abandon now!'
c          STOP
        ENDIF
      ENDIF
      RETURN
      END
      
C $Id: rmaxr.f,v 1.5 2015/06/05 14:12:58 harry Exp $
C== RMAXR ==
      SUBROUTINE RMAXR(LIMIT,THICK,IERR)
C     =======================================
      IMPLICIT NONE
C
C
C---- Determines the sizes of all the standard profiles using
C     the maximum coordinate limits of each area (determined in
C     PRSETUP) and the raster parameters. These are stored in ISIZE.
C     Check against maximum allowed box dimensions and total number
C     of pixels.
C
C      LIMIT     Limit for selection of refinement spots from central
C                region of image used to form average spot profile.
C                Spots lie within LIMIT (in 10 miocron units) of direct
C                beam position (in X and Y)
C
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     ..
C     .. Scalar Arguments ..
      REAL THICK
      INTEGER LIMIT,IERR
C     ..
C     .. Local Scalars ..
      REAL A1,A2,CHGHT,CWIDTH,PKHGHT,PKWIDTH,VVAR,
     +     XC,XTOFDPX,YC,XMID
      INTEGER I,NC,NRX,NRY,NX,NXS,NY,NYS,
     +     NXXSAVE,NYYSAVE,NXMIN,NYMIN,NXX,NYY,NFBOX,NXMBOX,NYMBOX,
     +     ISTRIP,J,JSTART,NXRIM,NYRIM
      LOGICAL SHRINK,SAMESIZE
C     ..
C     .. Local Arrays ..
C     SISIZE saves values of ISIZE from one cycle to the next
      INTEGER SISIZE(NMASKS,2)
C     ..
C     .. External Subroutines ..
      EXTERNAL SHUTDOWN
C     ..
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC ABS,MAX
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/debug.f
C
C $Id: debug.f,v 1.8 2021/06/03 09:41:34 andrew Exp $
C
C--- awk generated include file  debug.h
C---- START of include file debug.h
C
C
C
C     .. Arrays in common /DEBUG/ ..
      REAL XWARN
      INTEGER NDEBUG,IWARN,IARRDUMP
      LOGICAL DEBUG,LPRINT,DUMP,WARN
C
C     .. Scalars in common /DEBUG/ ..
      REAL BGRLIM
      INTEGER NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,IERRLEVEL
      LOGICAL SPOT
      CHARACTER MESSAGE*512
C     
C     ..
C     .. Common Block /DEBUG/..
      COMMON /DEBUG/XWARN(MAXIWARN,100),BGRLIM,NDEBUG(200),
     +       IWARN(MAXIWARN,100),
     $       NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,DEBUG(200),LPRINT(20),
     +       DUMP(30),WARN(100),SPOT,IARRDUMP(30),IERRLEVEL

      COMMON /CDEBUG/ MESSAGE
C     ..
C
C&&*&& end_include  ../inc/debug.f
C&&*&& include  ../inc/fid.f
C
C $Id: fid.f,v 1.7 2016/04/22 14:23:39 andrew Exp $
