C
C $Id: xy.f,v 1.1 2002/05/02 10:47:25 harry Exp $
C
C--- awk generated include file  xy.h
C---- START of include file xy.h
C
C     .. Scalars in common block /XY/ ..
      REAL XTOFD,SINV,COSV,TANV,TWOTHETA
      INTEGER ICASS
C     ..
C     .. Common Block /XY/ ..
      COMMON /XY/XTOFD,SINV,COSV,TANV,TWOTHETA,ICASS
C     ..
C
C     XTOFD....  Crystal to detector distance in 10 micron units. Read from
C                keyworded input and never changed.
C
C                Spot positions are calculated in S/R XYSPOT (Called from
C                REEK) and are for an "ideal" detector at a distance of XTOFD.
C                These are converted into pixel positions in S/R MMTOPX
C                which applies the multiplicative factor XTOFRA to allow
C                for refinement of the distance. XTOFRA is the parameter
C                that is actually refined (in RDIST), rather than XTOFD.
C                The refined distance that is printed in the logfile is
C                actually XTOFRA*XTOFD
C
C     ICASS....  Indicates detector type:
C                0     Flat film
C                1     Vee shaped cassettes
C                2     FAST detector (only used in TESTGEN mode of OSCGEN)
C                3     Swung out FAST (ditto)
C                4     IP detector
C     TWOTHETA   Detector swing angle (degrees)
C&&*&& end_include  ../inc/xy.f
C     ..
C     .. Equivalences ..
      SAVE
C     ..
C     .. Data ..
C     ..
C
      ISAVE = 12
      IFAIL = 0
      NOUT = 0
      IF(.NOT.LBEST)THEN
        DO 2 I = 1,200
          IFLAG(I) = 0
 2      CONTINUE
C
        CALL CCPDPN (ISAVE,SAVENAM,'UNKNOWN','F',80,IFAIL)
        IF (IFAIL.NE.0) THEN
          WRITE(IOUT,FMT=1001) SAVENAM
          IF (ONLINE) WRITE(ITOUT,FMT=1001) SAVENAM
 1001     FORMAT(//,1X,'***** ERROR *****',/,1X,'Cannot open savefile ',
     +         A)
          RETURN
        END IF
C
        NOUT = NOUT + 1
        WRITE(SAVED(NOUT),FMT=1000)
 1000   FORMAT('! This input created from an interactive session')
C
C---- First write out all input lines, excluding IMAGE and PROCESS
C
        DO 10 I = 1,NTLINE-1
          LINE = INLINE(I)
C     ******************************************
          CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C     ******************************************
          IF (NTOK.EQ.0) GOTO 10
          KEY = LINE(IBEG(1):IEND(1))
          CALL CCPUPC(KEY)
          IF(NTOK.GT.1)THEN
            KEY2 = LINE(IBEG(2):IEND(2))
            CALL CCPUPC(KEY2)
          ENDIF
          IF ((KEY.EQ.'IMAG').OR.(KEY(1:3).EQ.'RUN')
     +         .OR.(KEY.EQ.'END').OR.(KEY.EQ.'GO')
     +         .OR.(KEY.EQ.'PROC').OR.(KEY.EQ.'SERI')
     +         .OR.(KEY.EQ.'CELL').OR.(KEY.EQ.'MISS')
     +         .OR.(KEY.EQ.'SYMM').OR.(KEY.EQ.'STRA')
     +         .OR.(KEY.EQ.'POST').OR.(KEY.EQ.'MOSA')
     +         .OR.(KEY.EQ.'BEAM').OR.(KEY.EQ.'DIST')
     +         .OR.(KEY.EQ.'SAVE').OR.(KEY.EQ.'WMAT')) THEN
            CONTINUE
C     
C     .. don't store if LIMIts EXCLude, QUAD, ARC...
          ELSEIF((KEY.EQ.'LIMI').AND.((KEY2(1:4).EQ.'EXCL').OR.
     $           (KEY2(1:4).EQ.'QUAD').OR.(KEY2(1:3).EQ.'ARC')))THEN
            CONTINUE
          ELSE
            NCH = LENSTR(LINE)
            IF (NCH.GT.0) THEN
              NOUT = NOUT + 1
              WRITE(SAVED(NOUT),FMT=1003) LINE(1:LENSTR(LINE))
            END IF
          END IF
 10     CONTINUE
 1003   FORMAT(A)
C
C
C---- Detector or SITE parameters
C
C
        IF (IISCN) THEN
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1010) SVSCN(1:LENSTR(SVSCN))
        END IF
 1010   FORMAT('DETECTOR ',A)
        IF (IISITE) THEN
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1012) SVSITE(1:LENSTR(SVSITE))
        END IF
 1012   FORMAT('SITE ',A)
        IF (IIWAVE) THEN
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1014) WAVE
        END IF
 1014   FORMAT('WAVELENGTH',F9.5)
        IF (IIDIV) THEN
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1016) 2.0*DIVH*RTOD,2.0*DIVV*RTOD
        END IF
 1016   FORMAT('DIVERGENCE',2F9.3)
        IF (IIDISP) THEN
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1018) DELAMB
        END IF
 1018   FORMAT('DISPERSION',F9.5)
        IF(ISYN.NE.0) THEN
          NOUT = NOUT + 1
          STR = 'SYNCHROTRON '
          IF (IPOLAR.NE.0)THEN
            WRITE(BEAMSAV,FMT=1180)TOR
            STR = STR(1:LENSTR(STR))//BEAMSAV(1:LENSTR(BEAMSAV))
          ENDIF
          WRITE(SAVED(NOUT),FMT=1182)STR(1:LENSTR(STR))
 1180     FORMAT(' POLARISATION ',F4.2)
 1182     FORMAT(A)
C     11.10.2007 don't worry about delcor for the moment
        ENDIF

C
C---- Detector parameters (1020)
C
        XTRUE = 0.01*XCEN
        IF (INVERTX) XTRUE = NREC*RAST - XTRUE
        NOUT = NOUT + 1
        IF(ISWUNG.GT.0)THEN
          BEAMSAV = 'BEAM SWUNG_OUT'
        ELSE
          BEAMSAV = 'BEAM'
        ENDIF
        IF(IBEAMMU.GT.0)THEN
          WRITE(STR,FMT=1025)BEAMSAV(1:lenstr(beamsav)),BEAMMU(1)*RTOD,
     $         BEAMMU(2)*RTOD
 1025     FORMAT(A,' MU1 ',F5.2,' MU2 ',F5.2)
          BEAMSAV = STR
        ENDIF
        WRITE(STR,FMT=1019)BEAMSAV(1:lenstr(beamsav)),
     $       XTRUE,0.01*YCEN/YSCAL
 1019   FORMAT(A,2F8.2)
        BEAMSAV = STR
        WRITE(SAVED(NOUT),FMT=1020) BEAMSAV(1:LENSTR(BEAMSAV))
 1020   FORMAT(A)
C     
C---- only write out GAIN if it was set by a command or in control 
C     for a prototype. setdetect sets IGAIN to 2.
C
        IF(IGAIN.EQ.1)THEN
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1022) GAIN
        ENDIF
 1022   FORMAT('GAIN',F5.2)
        NOUT = NOUT + 1
        WRITE(SAVED(NOUT),FMT=1023) IDIVIDE
 1023   FORMAT('ADCOFFSET',I4)
C     
        IF (IINULL) THEN
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1024) NULLPIX
        END IF
 1024   FORMAT('NULLPIX',I6)
C     
        NOUT = NOUT + 1
        WRITE(SAVED(NOUT),FMT=1026) XTOFD*XTOFRA*0.01
 1026   FORMAT('DISTANCE',F9.3)
C     
        NOUT = NOUT + 1
C     ITILT = 0
C     ITWIST = 0
        IF (FDIST.GT.0.0) THEN
C     ITILT = TILT/FDIST
C     ITWIST = TWIST/FDIST
          CALL SETDIS(ITILT,ITWIST,2)
        END IF
        IF (SPIRAL) THEN
          IF (.NOT.FIXPAR(10)) THEN
            WRITE(SAVED(NOUT),FMT=1070) YSCAL,0.01*ROFF,0.01*TOFF,
     +           0.01*RDROFF,0.01*RDTOFF,ITILT,ITWIST
 1070       FORMAT('DISTORTION YSCALE ',F9.4,' ROFF',F7.2,' TOFF',F7.2,
     +           ' RDROFF',F7.2,' RDTOFF',F7.2,' TILT',I5,' TWIST',I5)
          ELSE
            WRITE(SAVED(NOUT),FMT=1072) YSCAL,0.01*ROFF,0.01*TOFF,
     +           ITILT,ITWIST
 1072       FORMAT('DISTORTION YSCALE ',F9.4,' ROFF',F7.2,' TOFF',F7.2,
     +           ' TILT',I5,' TWIST',I5)
          END IF
        ELSE
          WRITE(SAVED(NOUT),FMT=1074) YSCAL,ITILT,ITWIST
 1074     FORMAT('DISTORTION YSCALE ',F9.4,' TILT',I5,' TWIST',I5)
        END IF
        IF (IIPIX) THEN
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1030) RAST
        END IF
 1030   FORMAT('PIXEL ',F8.5)
C     
C
C---- Crystal parameters (1040)
C
        IF (SAVMATSTR(1:7).NE.'Not set') THEN
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1040) SAVMATNAM(1:LENSTR(SAVMATNAM))
 1040     FORMAT('MATRIX ',A)
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1042) SAVMATSTR(1:LENSTR(SAVMATSTR))
 1042     FORMAT('!This matrix was obtained from ',A)
          IF (SAVMATSTR(1:1).EQ.'a') THEN
            NOUT = NOUT + 1
            WRITE(SAVED(NOUT),FMT=1044) (ISAVIMG(I),I=1,NSAVIMG)
 1044       FORMAT('! The following images were used:',15I7)
          ELSE IF (SAVMATSTR(1:1).EQ.'p') THEN
            NOUT = NOUT + 1
            WRITE(SAVED(NOUT),FMT=1046) NSAVSEG,(ISFIRST(I),I=1,NSAVSEG)
 1046       FORMAT('!using ',I2,' segments starting with images',10I7)
          END IF
        END IF
C
      NOUT = NOUT + 1
      WRITE(SAVED(NOUT),FMT=1048) NUMSPG
 1048 FORMAT('SYMMETRY',I5)
      NOUT = NOUT + 1
      WRITE(SAVED(NOUT),FMT=1049) 2.0*ETA*RTOD
 1049 FORMAT('MOSAIC ',F5.2)
C
C---- Image parameters
C     
        NOUT = NOUT + 1
        IF(TEMPLATE)THEN
          WRITE(SAVED(NOUT),FMT=1061) TEMPLSAV(1:lenstr(templsav))
 1061     FORMAT('TEMPLATE ',A)
        ELSE
          TEMPLSAV = IDENT(1:LENSTR(IDENT))//SEPCHAR//'###.'//
     $         ODEXT(1:LENSTR(ODEXT))
          WRITE(SAVED(NOUT),FMT=1061) TEMPLSAV(1:LENSTR(TEMPLSAV))
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1063)
 1063     FORMAT('! this TEMPLATE was created from these IDENT',
     $         ' and EXTENSION lines')
          NOUT = NOUT + 1
c     
c---- changed so that ident and extension are saved but commented out
c
          WRITE(SAVED(NOUT),FMT=1060) IDENT
 1060     FORMAT('! IDENT ',A)
        ENDIF
        NCHTOT = 10
        STR = ' '
        DO 30 I = 1,NDIR
          IF (LENSTR(FDISK(I)).GT.0) THEN
            NCH = LENSTR(FDISK(I))
            IF ((NCHTOT+NCH).GT.80) THEN
              NOUT = NOUT + 1
              WRITE(SAVED(NOUT),FMT=1062) STR(1:LENSTR(STR))
              STR = FDISK(I)(1:NCH)
              NCHTOT = 10 + NCH
            ELSE
              IF (I.EQ.1) THEN
                STR = FDISK(I)(1:NCH)
              ELSE
                STR = STR(1:LENSTR(STR))//FDISK(I)(1:NCH)
              END IF
              NCHTOT = NCHTOT + NCH
            END IF
          END IF
 30     CONTINUE
c     
c---- changed so that ident and extension are saved but commented out
c
        IF(.NOT.TEMPLATE)THEN
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1064) ODEXT
 1064     FORMAT('! EXTENSION ',A)
        ENDIF
C
        IF (NCHTOT.GT.10) THEN
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1062) STR(1:LENSTR(STR))
        END IF
 1062   FORMAT('DIRECTORY ',A)
C
C---- Processing options
C
CAL      IF (IIRAST) THEN
        NOUT = NOUT + 1
        WRITE(SAVED(NOUT),FMT=1080) IRAS
CAL      END IF
 1080   FORMAT('RASTER ',5I5)
C
CAL      IF (IISEP) THEN
        NOUT = NOUT + 1
        IF (DENSE) THEN
          WRITE(SAVED(NOUT),FMT=1082) 0.01*IXSEP,0.01*IYSEP
        ELSE
          WRITE(SAVED(NOUT),FMT=1084) 0.01*IXSEP,0.01*IYSEP
        END IF
CAL      END IF
 1082   FORMAT('SEPARATION ',2F5.2,' CLOSE')
 1084   FORMAT('SEPARATION ',2F5.2)
C
CAL      IF (IIOVER) THEN
        NOUT = NOUT + 1
        WRITE(SAVED(NOUT),FMT=1086) CUTOFF
C     AL      END IF
 1086   FORMAT('OVERLOAD CUTOFF ',I7)
C     
        RMINXP = 0.01*RMINX
        IF (INVERTX) RMINXP = NREC*RAST - 0.01*RMINX
        IF(IIBACK) THEN
          NOUT = NOUT + 1
C     ..
C     .. always write both beam and radius if one has been set
CHRP 15.10.2007        IF (IRMINXY.NE.0) THEN
          WRITE(SAVED(NOUT),FMT=1088) RMINXP,0.01*RMINY,0.01*RMIN
CHRP 15.10.2007        ELSE
CHRP 15.10.2007           WRITE(SAVED(NOUT),FMT=1089)0.01*RMIN
CHRP 15.10.2007         ENDIF
        END IF
 1088   FORMAT('BACKSTOP CENTRE',2F8.2,' RADIUS',F6.2)
C     HRP 15.10.2007 1089 FORMAT('BACKSTOP RADIUS',F6.2)
C     
chrp24062005      NOUT = NOUT + 1
chrp24062005      WRITE(SAVED(NOUT),FMT=1090) TOLMIN,TOL
 1090   FORMAT('PROFILE TOLERANCE ',2F8.3)
        IF ((IIRES).AND.DSTMAX.GT.0.0)THEN
          IF(RESLOW.EQ.0.0) THEN
C
C---- RES will be > 0 if set by keyword, but not if input from menu.
C     hrp 21.04.2005 - changed so that only high res is written if low 
C     res wasn't set, otherwise write both
            NOUT = NOUT + 1
            WRITE(SAVED(NOUT),FMT=1092) WAVE/DSTMAX
          ELSEIF(RESLOW.GT.0.0)THEN
            NOUT = NOUT + 1
            WRITE(SAVED(NOUT),FMT=1094) WAVE/DSTMAX,RESLOW
          ENDIF
        END IF
 1092   FORMAT('RESOLUTION ',F6.2)
 1094   FORMAT('RESOLUTION ',F6.2,1X,F6.2)
C
C---- LIMIT  EXCLUDE, QUAD & ARC can now be entered via the GUI, so 
C     need to be saved 
        DO 1815 I = 1,NXYEXC
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1120)(XYEXC(J,I)*0.01,J=1,4)
 1815   ENDDO
 1120   FORMAT('LIMITS EXCLUDE ',4F6.1)
        DO 1805 I = 1,IQUADNO
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1140)(CNREXC(J,I)*0.01,J=1,8)
 1805   ENDDO
 1140   FORMAT('LIMITS QUADRILATERAL ',8F6.1)
        DO 1825 I = 1,IARCNO
          KEY3 = 'OUTSIDE'
          IF(LEXCARC(I))KEY3 = 'INSIDE'
          NOUT = NOUT + 1
          WRITE(SAVED(NOUT),FMT=1160)(EXCARC(J,I),J=1,3),
     $         (EXCARC(J,I)*RTOD,J=4,5),KEY3(1:LENSTR(KEY3))
 1825   ENDDO
 1160   FORMAT('LIMITS ARC ',5(F7.1,1X),A)

C
C---- Now go though the lines and eliminate duplicates.
C
        DO 50 I = NOUT,2,-1
C     
C---- Is this line still a valid one? replace 'SCANNER' by 'DETECTOR',
C     allow multiple 'PROFILES' or 'LIMITS' keywords
C
          IF (IFLAG(I).EQ.0) THEN
            LINE = SAVED(I)
C     ******************************************
            CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C     ******************************************
            IF (NTOK.EQ.0) GOTO 50
            KEY3 = LINE(IBEG(1):IEND(1))
            CALL CCPUPC(KEY3)
            DO 40 J = I-1,1,-1
              LINE = SAVED(J)
C          ******************************************
              CALL MPARSE(LINE,IBEG,IEND,ITYP,VALUE,IDEC,NTOK)
C          ******************************************
              IF (NTOK.EQ.0) GOTO 40
              KEY2 = LINE(IBEG(1):IEND(1))
              CALL CCPUPC(KEY2)
              IF(KEY2(1:4).EQ.'SCAN')KEY2 = 'DETECTOR'
              IF (KEY2.EQ.KEY3) IFLAG(J) = 1
              IF((KEY2(1:4).EQ.'PROF').OR.(KEY2(1:4).EQ.'LIMI'))
     $             IFLAG(j) = 0
 40         CONTINUE
          END IF
 50     CONTINUE
C     
C---- Now write out wanted lines
C
        DO 60 I = 1,NOUT
          IF(IFLAG(I).EQ.0)
     $         WRITE(ISAVE,FMT=1100)SAVED(I)(1:LENSTR(SAVED(I)))
 60     CONTINUE
 1100   FORMAT(A)
        CLOSE(UNIT=ISAVE)
      ELSE
        BESTFILE = 'bestfile.par'
        IBEST = 21
        IFAIL = 1
        LDUM = 80
C     ..
C     .. to tell BEST which axis is which (compared to the rotation axis)
        IF(ABS(OMEGAFD).LE.1E-3)THEN
          ROTAXIS = 'FAST'
        ELSE
          ROTAXIS = 'SLOW'
        ENDIF
        XTRUE = 0.01*XCEN
        IF (INVERTX) XTRUE = NREC*RAST - XTRUE
        CALL CCPOPN(-IBEST,BESTFILE,1,1,LDUM,IFAIL)
        WRITE(IBEST,FMT=1980)
        WRITE(IBEST,FMT=2000)GTITLE(1:LENSTR(GTITLE))
        WRITE(IBEST,FMT=2020)MACHINE(1:LENSTR(MACHINE))
        WRITE(IBEST,FMT=2040)SVSITE(1:LENSTR(SVSITE))
        WRITE(IBEST,FMT=2060)NREC*RAST
        WRITE(IBEST,FMT=2080)RAST
        WRITE(IBEST,FMT=2100)ROTAXIS
        WRITE(IBEST,FMT=2120)
        WRITE(IBEST,FMT=2140)GAIN
        WRITE(IBEST,FMT=2160)(ETA+DIVH)*2.0*RTOD
        WRITE(IBEST,FMT=2460)PHIBEG
        WRITE(IBEST,FMT=2180)PHIEND-PHIBEG
        WRITE(IBEST,FMT=2200)XTOFD*0.01*XTOFRA
        WRITE(IBEST,FMT=2220)WAVE
        WRITE(IBEST,FMT=2240)TOR
        WRITE(IBEST,FMT=2260)SPGNAM(1:LENSTR(SPGNAM))
        WRITE(IBEST,FMT=2280)AMAT
        WRITE(IBEST,FMT=2300)CELL
        WRITE(IBEST,FMT=2320)(IRAS(I),I=1,5,1)
        WRITE(IBEST,FMT=2340)FLOAT(IXSEP)*0.01,FLOAT(IYSEP)*0.01
        IF(ISWUNG.EQ.0)THEN
          WRITE(IBEST,FMT=2360) XTRUE,0.01*YCEN/YSCAL
        ELSE
          WRITE(IBEST,FMT=2380) XTRUE,0.01*YCEN/YSCAL
        ENDIF
        CLOSE(UNIT=IBEST)
 1980   FORMAT('# parameter file for BEST ')
 2000   FORMAT('TITLE          ',A)
 2020   FORMAT('DETECTOR       ',A)
 2040   FORMAT('SITE           ',A)
 2060   FORMAT('DIAMETER       ',F8.2)
 2080   FORMAT('PIXEL          ',F9.7)
C     not sure about these axes - I'm assuming that the rotation axis is
C     the Y axis and is horizontal, and the polarization axis is also
C     horizontal.
 2100   FORMAT('ROTAXIS        ','0.00 0.00 1.00',1X,A)
 2120   FORMAT('POLAXIS        ','0.00 0.00 1.00')
 2140   FORMAT('GAIN           ',F8.2)
 2160   FORMAT('CMOSAIC        ',F8.2)
 2460   FORMAT('PHISTART       ',F8.2)
 2180   FORMAT('PHIWIDTH       ',F8.2)
 2200   FORMAT('DISTANCE       ',F8.2)
 2220   FORMAT('WAVELENGTH     ',F8.5)
 2240   FORMAT('POLARISATION   ',F8.5)
 2260   FORMAT('SYMMETRY       ',A)
 2280   FORMAT('UB             ',3(F9.6,1X),2(/,15X,3(F9.6,1X)))
 2300   FORMAT('CELL           ',3(F8.2,1X),3(F6.2,1X))
 2320   FORMAT('RASTER         ',5I4)
 2340   FORMAT('SEPARATION     ',F6.3,1X,F6.3)
 2360   FORMAT('BEAM           ',F8.3,1X,F8.3,/,
     $       '# end of parameter file for BEST')
 2380   FORMAT('BEAM SWUNG_OUT ',F8.3,1X,F8.3,/,
     $       '# end of parameter file for BEST')
      ENDIF
      RETURN
      END

C== SCALEPROF ==
C
      SUBROUTINE SCALEPROF(IPROFL,IRAS,MASK,MASKREJ,SCALE,ODMIN,
     +                     PROFSUMS,WPROFSUMS)
      IMPLICIT NONE
C     ===========================================================
C
C
C---- Remove the offset in profile so that mean background would
C     be zero. rescale to a maximum of 10000.
C     Evaluate and store sums for this profile
C
C
C
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
