C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C&&*&& include  ../inc/xy.f
C
C $Id: xy.f,v 1.1 2002/05/02 10:47:25 harry Exp $
C
C--- awk generated include file  xy.h
C---- START of include file xy.h
C
C     .. Scalars in common block /XY/ ..
      REAL XTOFD,SINV,COSV,TANV,TWOTHETA
      INTEGER ICASS
C     ..
C     .. Common Block /XY/ ..
      COMMON /XY/XTOFD,SINV,COSV,TANV,TWOTHETA,ICASS
C     ..
C
C     XTOFD....  Crystal to detector distance in 10 micron units. Read from
C                keyworded input and never changed.
C
C                Spot positions are calculated in S/R XYSPOT (Called from
C                REEK) and are for an "ideal" detector at a distance of XTOFD.
C                These are converted into pixel positions in S/R MMTOPX
C                which applies the multiplicative factor XTOFRA to allow
C                for refinement of the distance. XTOFRA is the parameter
C                that is actually refined (in RDIST), rather than XTOFD.
C                The refined distance that is printed in the logfile is
C                actually XTOFRA*XTOFD
C
C     ICASS....  Indicates detector type:
C                0     Flat film
C                1     Vee shaped cassettes
C                2     FAST detector (only used in TESTGEN mode of OSCGEN)
C                3     Swung out FAST (ditto)
C                4     IP detector
C     TWOTHETA   Detector swing angle (degrees)
C&&*&& end_include  ../inc/xy.f
C     ..
C     .. Scalar Arguments ..
      REAL RSCAN,RSCANRED,RMINXINP
      INTEGER NIMAGES,ID,IPIXY,ICCX,IXOFFSET,IYOFFSET,
     +        INDENT
      LOGICAL DISPSET,CCXRESET
      CHARACTER SITE*4,SCANNER*4
C     ..
C     .. Local Scalars ..
C     
C     EMBL
C     LOGICAL VERS1,VERS2,VERS3
C     EMBL
C     
      REAL OMEGA0,YCOR
      INTEGER I,J,II,IMODE,ITOR,IDTMP,IERR,IBOT,ITOP,IST,IEND,NOFF,
     $     IXCEN,IYCEN,IXOFF,IYOFFL,BGBOXOFFSET,IOFFSET,STARTX,
     $     STARTY,STEPX,STEPY,WIDTHX,WIDTHY
      LOGICAL ROTATED,FINE,SONLINE,NOTDONEOFFSET,DONERIPI,OSCWARN,
     +        DETPARMWARN
      CHARACTER CALLEDFROM*80,IOLINE2*4096,OLDHOSCAXIS*6,THIS*30,
     +          CALLED*30,COMMENT*100,MACHINEXML*5,TEXT1*80,TEXT2*80,
     +          TEXT3*80
C     ..
C     .. Local Arrays ..
C     ..
C     .. External Functions ..
      INTEGER LENSTR
      EXTERNAL LENSTR
C     ..
C     .. External Subroutines ..
      EXTERNAL BADTOGOOD,PRINTFLOW,SHUTDOWN,WRITE_SOCKET_SECTION,
     +         WRITE_SOCKET_LENGTH,dna_output_table_start,
     +         dna_output_list_start,dna_output_real_item,
     +         dna_output_list_end,dna_output_table_end
C     ..
C     .. Intrinsic Functions ..
      
C---- Check wavelength and distance for consistency with values in
C     header
C     ONLY does this for MAR and RaxisIV (and R-Axis 5) and JUPITER,
C     SATURN, MERCURY, A200,
C     images at present. Also check overload value (JUPITER etc only at the
C     moment).
C     Separate checks are done for DIP2 images in subroutine GETTAIL
C     
      DATA ITOR /0/,OLDHOSCAXIS/'      '/,DONERIPI/.FALSE./
     +     OSCWARN/.FALSE./, DETPARMWARN/.FALSE./
      BGBOXOFFSET = 0
      CALLEDFROM = 'SECTION'
      NOTDONEOFFSET = .TRUE.
      THIS = 'SECTION'  
      INDENT = 2
C
C---- the 5th character of MACHINEXML is used in Tcl code (SESSION) to distinguish 
C     Pilatus3 and Eiger2 detectors, and also "pseudo ADSC" (SMV) MicroED detectors
C     although this only affects what is shown in the Detector tab of
C     Settings->Experiment->Detector
C
      MACHINEXML = ' '
      MACHINEXML(1:4) = MACHINE
      IF (LDETECTOR(1:8).EQ.'PILATUS3') MACHINEXML(5:5) = '3'
      IF (DECTRIS_TYPE(1:6).EQ.'EIGER2') MACHINEXML(5:5) = '2'
C     
C---- turn off output to screen if PHIONLY
      IF(PHIONLY)THEN
        SONLINE = ONLINE
        ONLINE = .FALSE.
      ENDIF
      IF (DEBUG(103)) THEN
        WRITE(IOUT,FMT=6000) PHIONLY, YSCAL, MACHINE,WAVE,HWAVE,
     +                      RAST, HRAST 
        IF (ONLINE) WRITE(ITOUT,FMT=6000) PHIONLY, YSCAL, MACHINE, 
     +               WAVE, HWAVE, RAST, HRAST 
 6000   FORMAT(1X,'Entering SECTION, PHIONLY is ',L2,' YSCAL',f12.4,
     +         ' MACHINE is:',A,/,1X,'Wavelength',F8.5,' Header ',
     +          'wavelength ',F8.5,' Pixel ',F6.4,' header pixel',F6.4)
      END IF
C     
      ISCAN = 1
C     ***** machine specific code follows *****
C     AL            IF ((MACHINE.EQ.'MAR '.AND.(.NOT.PACK)).OR.
C     AL     +                             (MODEL.EQ.'RAXISIV')) THEN
C     ..
C     .. first bit if IMGP and HDRSIZE have been set
      IF(IMGP.AND.HDRSIZE)THEN
        IF (USEHDR.OR.USETAIL) THEN
          IF ((IDIST.GT.0).AND.(ABS(0.01*XTOFD - HDIST).GT.0.01))
     +         THEN
            call dna_output_table_start('warning')
            call dna_output_list_start('reading_header')
            call dna_output_real_item('xtofd_differs_by',
     +           0.01*xtofd - hdist)
            call dna_output_list_end
            call dna_output_table_end
            WRITE(IOUT,FMT=6713) 0.01*XTOFD, HDIST
            IF (ONLINE) WRITE(ITOUT,FMT=6713) 0.01*XTOFD, HDIST
          END IF
 6713     FORMAT(4(1X,'***** WARNING *****',/),
     +         1X,'Input crystal to detector distance (',F7.2,
     +         'mm) does NOT agree with value in the image ',
     +         'header (',F7.2,'mm)',/,1X,'The input distance',
     +         ' will be used.')
C     
C---- If distance not specified, set to value from header
C     
          IF ((IDIST.EQ.0).AND.(HDIST.NE.0)) THEN
            XTOFD = 100.0*HDIST
            CAMCON(3) = HDIST
            IDIST = 1
            WRITE(IOUT,FMT=6717) HDIST
            IF (ONLINE) WRITE(ITOUT,FMT=6717) HDIST
 6717       FORMAT(/,1X,'Crystal to detector distance of',F8.2,
     +           'mm taken from image header')
            call dna_output_table_start('autoindexing_parameters')
            call dna_output_list_start('experiment_parameters')
            call dna_output_real_item('crystal_to_detector_distance',
     +           hdist)
            call dna_output_list_end
            call dna_output_table_end
          END IF
C     
C---- Check wavelength against input value (if given)
C     
          IF ((IWAVE.EQ.2).AND.(ABS(WAVE - HWAVE).GT.0.001)) THEN
            WRITE(IOUT,FMT=6715) WAVE,HWAVE
            IF (ONLINE) WRITE(ITOUT,FMT=6715) WAVE,HWAVE
          END IF
 6715     FORMAT(4(1X,'***** WARNING *****',/),
     +         1X,'Input wavelength (',F6.4,
     +         'A) does NOT agree with value in the image ',
     +         'header (',F6.4,'A)',/,1X,'The input wavelength',
     +         ' will be used.')
C     
C---- If wavelength not specified, set to value from header if non-zero
C     
          IF ((IWAVE.EQ.0).AND.(HWAVE.NE.0)) THEN
            WRITE(IOUT,FMT=6719) HWAVE
            IF (ONLINE) WRITE(ITOUT,FMT=6719) HWAVE
 6719       FORMAT(/,1X,'Wavelength of',F8.5,'A taken',
     +           ' from image header')
            WAVE = HWAVE
            IWAVE = 1
          END IF
C     
C---- If twotheta not specified by a keyword, it will ahve been set to value from header
C     (if non-zero) in OPENODS, but give a message here.
C     
          IF ((ITWOTHETA.EQ.0).AND.(HTWOTHETA.NE.0)) THEN
            WRITE(IOUT,FMT=67191) TWOTHETA
            IF (ONLINE) WRITE(ITOUT,FMT=67191) TWOTHETA
67191       FORMAT(/,1X,'Twotheta angle of',F8.2,'taken',
     +           ' from image header')
            ITWOTHETA = 1
          END IF
C     
C---- Check header pixel size
C     
          IF ((IPIX.EQ.0).AND.(HRAST.NE.0)) THEN
            RAST = HRAST
            IPIX = 1
            IF(MACHINE.NE.'JUPI'.AND.MACHINE.NE.'SATU'.AND.
     $           MACHINE.NE.'MERC'.AND.MACHINE.NE.'A200')THEN
              WRITE(IOUT,FMT=6726) HRAST
              IF (ONLINE) WRITE(ITOUT,FMT=6726) HRAST
            ELSE
              WRITE(IOUT,FMT=67261) HRAST
              IF (ONLINE) WRITE(ITOUT,FMT=67261) HRAST
            END IF
 6726       FORMAT(/,1X,'Pixel size of ',F6.4,'mm taken',
     +           ' from image header.')
67261       FORMAT(/,1X,'Pixel size of ',F6.4,'mm calculated',
     +           ' from image header.')
          END IF
C     
C---- IF POLARISATION NOT SPECIFIED, use value from header (SBC1 only)
C     
          IF ((MACHINE.EQ.'SBC1').AND.(ITOR.EQ.0)) THEN
            WRITE(IOUT,FMT=6727) HTOR
            IF (ONLINE) WRITE(ITOUT,FMT=6727) HTOR
 6727       FORMAT(/,1X,'Beam polarisation of ',F6.4,' taken',
     +           ' from image header.')
            TOR = HTOR
            ITOR = 1
          END IF
C     
C---- Check pixel size  against input value (if given)
C     
          IF ((IPIX.EQ.1).AND.(ABS(RAST - HRAST).GT.0.001)) THEN
            WRITE(IOUT,FMT=6729) RAST,HRAST
            IF (ONLINE) WRITE(ITOUT,FMT=6729) RAST,HRAST
          END IF
 6729     FORMAT(4(1X,'***** WARNING *****',/),
     +         1X,'Input pixel size (',F6.4,
     +         'mm) does NOT agree with value in the image ',
     +         'header (',F6.4,'mm)',/,1X,'The input value',
     +         ' will be used.')
C     
C---- If NULLPIX set in header (Mar CCD) and not set by keyword, use
C     the  value from header
C     
          IF ((.NOT.IINULL).AND.(HNULLPIX.GT.0)) THEN
            NULLPIX = HNULLPIX
            WRITE(IOUT,FMT=6728) NULLPIX
            IF (ONLINE) WRITE(ITOUT,FMT=6728) NULLPIX
 6728       FORMAT(1X,'Nullpix value from header:',I5)
          END IF        
C     
C---- Set start,end phi if not assigned on IMAGE keyword. Note that we
C     may be doing autoindexing without specifying an IMAGE keyword, so
C     must check this.
C     
          IF (NIMAGES.GT.0) THEN
            IF (IANGLE.EQ.0) THEN
              PHIBEG = HPHIS
              PHIEND = HPHIE
              PHI(1) = 0.5*(PHIBEG+PHIEND)
              PHISTIM(1) = PHIBEG
              WRITE(IOUT,FMT=6724) ID,HPHIS,HPHIE
              IF (ONLINE) WRITE(ITOUT,FMT=6724) ID,
     $             HPHIS,HPHIE
 6724         FORMAT(/,1X,'Start and end phi values for ',
     +             'image ',I7,' from image header are ',F8.2,
     +             ' and',F8.2,' degrees.')
C     
C---- If the oscillation axis has been set in the image header, report
C     it now - set in gethdr.f
C     
              IF (HOSCAXIS.NE.'      '.AND.HOSCAXIS.NE.OLDHOSCAXIS)THEN
                IF(HOSCAXIS.NE.'NOTSET')THEN
                  WRITE(IOUT,FMT=1752)HOSCAXIS(1:LENSTR(HOSCAXIS))
                  IF(ONLINE)WRITE(ITOUT,FMT=1752)
     $                 HOSCAXIS(1:LENSTR(HOSCAXIS))
                ELSE
                  WRITE(IOUT,FMT=1753)
                  IF(ONLINE)WRITE(ITOUT,FMT=1753)
                ENDIF
              ENDIF
              OLDHOSCAXIS = HOSCAXIS
 1752         FORMAT(/,' Oscillation axis set as ',A,' from ',
     $             'image header')
 1753         FORMAT(/,'Oscillation axis not specified in image ',
     $             'header - set to PHI')
              
C     
C---- Check that oscillation angle from header is non-zero, if not give
C     a warning, but only once!!
C     
              IF (((PHIEND-PHIBEG).EQ.0.0).AND.(.NOT.OSCWARN)) THEN
                WRITE(IOUT,FMT=6725)
                IF (ONLINE) WRITE(ITOUT,FMT=6725)
 6725           FORMAT(/,4(1X,'***** WARNING *****',/),1X,
     +               'Oscillation angle derived from image ',
     +               'header is zero. If this is an oscillation',
     $               /,1X,' image, then the header information',
     $               ' is not correct. The phi values must be',
     $               /,1X,'given on the IMAGE',
     +               ' (or PROCESS) keyword.',/,/)
                OSCWARN = .TRUE.
              END IF
            ELSE
C     
C---- Check that oscillation angle agrees
C     
              IF (ABS(2.0*(PHI(1)-PHISTIM(1)) -
     +             (HPHIE-HPHIS)).GT.0.01) THEN
                WRITE(IOUT,FMT=6722)
     +               2.0*(PHI(1)-PHISTIM(1)),(HPHIE-HPHIS)
                IF (ONLINE) WRITE(ITOUT,FMT=6722)
     +               2.0*(PHI(1)-PHISTIM(1)),(HPHIE-HPHIS)
 6722           FORMAT(4(1X,'***** WARNING *****',/),1X,
     =               'Input oscillation angle of ',F8.3,' deg',
     +               'rees does not agree with value from ima',
     +               'ge header',/,1X,'which gives',F8.3,
     +               ' degrees',/,1X,'The input values will b',
     $               'e used',/,/)
              END IF
            END IF
          END IF
        END IF
        IF ((MODEL.EQ.'RAXISIV').OR.(MODEL.EQ.'RAXISHTC')) THEN
          IF (NREC.EQ.1500) THEN
            RAST = 0.2
          ELSE IF (NREC.EQ.3000) THEN
            RAST = 0.1
          ELSE IF (NREC.EQ.6000) THEN
            RAST = 0.05
          END IF
        END IF
        IF (MODEL.EQ.'RAXISV') THEN
          IF (NREC.EQ.2000) THEN
            RAST = 0.2
          ELSE IF (NREC.EQ.4000) THEN
            RAST = 0.1
          ELSE IF (NREC.EQ.8000) THEN
            RAST = 0.05
          END IF
        END IF
      END IF
C     
C     ***** Next line specific for Mar scanner radius ***********
      IF (.NOT.DISPSET) DISPLAY = 90.0
c     hrp09.02.2005        IF (ONLINE) FILMPLOT(1) = .TRUE.
      ONEFILE = .TRUE.
      FHEADER = .FALSE.
C     
C     Do the NOFID stuff. Remember to add CCOM to OMEGA0
C     
c      IF(MACHINE.NE.'CBF ')
      OMEGAF = OMEGAFD*DTOR
c     write(*, *) 'OMEGAF = ', omegaf
      OMEGA0 = OMEGAF + CCOM*DTOR
      COSOM0 = COS(OMEGA0)
      SINOM0 = SIN(OMEGA0)
      NOFID = .TRUE.
      ROTATED = .FALSE.
      SCNSZ = 40.0*RAST
      FACT = 0.4/SCNSZ
      IF (IGAIN.EQ.0) THEN
        IGAIN = 1
        GAIN = 1.0
      ENDIF
      IF (YSCAL.LT.0) YSCAL = 1.0
      IF (XTOFRA.LT.0) XTOFRA = 1.0
C     AL          IF (NHEAD.EQ.-999) NHEAD = 1
C     
C     ***** machine specific code follows *****
C     
      IF (MACHINE .EQ. 'ADSC')THEN
        MODEL = 'QUAD'
C     
C---- Quantum 4 in binned mode
C     
        IF (abs(RAST-0.1632).le.1e-5)THEN
          nrec = 1152
          iylen = 1152
          TILEX(1) = 577
          TILEY(1) = 577
          TILEWX(1) = 2
          TILEWY(1) = 2
C     
C---- Quantum 210 unbinned
C     
        ELSEIF ((NREC.EQ.4096).AND.(IYLEN.EQ.4096))THEN
          MODEL = 'Q210'
          TILEX(1) = 2049
          TILEY(1) = 2049
          IF (XSCAN.EQ.9400) XSCAN = 10500
          IF (YSCAN.EQ.9400) YSCAN = 10500
          XMAXIP = 10500
          YMAXIP = 10500
          TILEWX(1) = 8
          TILEWY(1) = 8
C     
C---- Quantum 210 binned
C     
        ELSEIF ((NREC.EQ.2048).AND.(IYLEN.EQ.2048))THEN
          MODEL = 'Q210'
          TILEX(1) = 1025
          TILEY(1) = 1025
          IF (XSCAN.EQ.9400) XSCAN = 10500
          IF (YSCAN.EQ.9400) YSCAN = 10500
          XMAXIP = 10500
          YMAXIP = 10500
          TILEWX(1) = 4
          TILEWY(1) = 4
C     
C---- Quantum 315 unbinned
C     
        ELSEIF ((NREC.EQ.6144).AND.(IYLEN.EQ.6144))THEN
          IF((IYLENGTH.LT.6144).OR.(IXWDTH.LT.12288))THEN
            WRITE(IOUT,FMT=6650)
            IF(ONLINE)WRITE(ITOUT,FMT=6650)
 6650       FORMAT(76('*'),/,6(' FATAL ERROR'),/,6X,
     $           'You must change all occurrences',
     $           ' of the lines ',/,/,12X,'PARAMETER (IXWDTH=8192)',
     $           /,6X,'and',/,12X,'PARAMETER (IYLENGTH=4096)',/,6X,
     $           'to',/,12X,'PARAMETER (IXWDTH=12288)',/,
     $           6X,'and',/,12X,'PARAMETER (IYLENGTH=6144)',/,/,6X,
     $           'and rebuild the program in order to process ',
     $           'Quantum 315 unbinned images.',/,6X,'These lines ',
     $           'occur in the files:',/,/,12X,
     $           'mosflm_all_ip_inc.for',
     $           /,12X,'control.f',/,12X,'celref.f',/,8X,
     $           'and reek.f.',/,/,6X,'You may also need to increa',
     $           'se the swap space on your machine',/,6X,
     $           '(it must be more than ~150Mb)',/,/,76('*'))
            NSHUTERR = 1
            CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
          ENDIF
          MODEL = 'Q315'
          TILEX(1) = 2049
          TILEY(1) = 2049
          IF (XSCAN.EQ.9400) XSCAN = 15750
          IF (YSCAN.EQ.9400) YSCAN = 15750
          XMAXIP = 15750
          YMAXIP = 15750
          TILEWX(1) = 8
          TILEWY(1) = 8
          NTILEX = 3
          NTILEY = 3
C     
C---- Quantum 315 binned
C     
        ELSEIF ((NREC.EQ.3072).AND.(IYLEN.EQ.3072))THEN
          MODEL = 'Q315'
          TILEX(1) = 1025
          TILEY(1) = 1025
          IF (XSCAN.EQ.9400) XSCAN = 15750
          IF (YSCAN.EQ.9400) YSCAN = 15750
          XMAXIP = 15750
          YMAXIP = 15750
          TILEWX(1) = 4
          TILEWY(1) = 4
          NTILEX = 3
          NTILEY = 3
C     
C---- Quantum 270 unbinned
C     
        ELSEIF ((NREC.EQ.4168).AND.(IYLEN.EQ.4168))THEN
          MODEL = 'Q270'
          XSCAN = 13500
          YSCAN = 13500
          XMAXIP = 13500
          YMAXIP = 13500
          RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
          NTILEX = 2
          NTILEY = 2
          TILEX(1) = 2080
          TILEY(1) = 2080
          TILEWX(1) = 8
          TILEWY(1) = 8
C     
C---- Quantum 270 binned
C     
        ELSEIF ((NREC.EQ.2084).AND.(IYLEN.EQ.2084))THEN
          MODEL = 'Q270'
          XSCAN = 13500
          YSCAN = 13500
          XMAXIP = 13500
          YMAXIP = 13500
          RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
          NTILEX = 2
          NTILEY = 2
          TILEX(1) = 1040
          TILEY(1) = 1040
          TILEWX(1) = 4
          TILEWY(1) = 4
          
        END IF
C
C---- Set defaults for MicroED images that have been converted from original detector format to
C     an SMV file. These CMOS detectors normally have a much higher GAIN and zero ADCOFFSET.
C     Only way to distinguish this is a wavelength <0.05A (typically 0.025 for 200KeV)
C     The default polarisation, dispersion, divergence are set in CONTROL also based on wavelength < 0.05
c     but if working with iMosflm, the defaults are set up in session.tcl
C
C
        IF (((WAVE.LT.0.050).OR.(HWAVE.LT.0.05))) THEN
          text1 = ' '
          text2 = ' '
          text3 = ' '
          MICROED = .TRUE.
          IF (IGAIN.EQ.2) THEN
            GAIN = 2.0
            text1 = 'the detector gain has been set to 2.0'
          END IF
C
C---- ADC offset
C
          IF (IIDIVIDE.EQ.0) THEN
            IDIVIDE = 0
            text2 = ' the adcoffset has been set to 0'
          END IF
C
C---- Set NULLPIX to -1 
C
          NULLPIX = -1
C
C----  MACHINEXML sent as <detector_manufacturer> to iMosflm , the U here allows it to be
C      identified as an ADSC style image but from an unknown detector
C
          MACHINEXML(5:5) = 'U'
          TRUSTED = .TRUE.
          WARN(43) = .TRUE.
C
C---- Set up detector limits (10 micron units!)
C
          NTILEX = 1
          NTILEY = 1
          MODEL = 'SMV'
          RMINIP = 100
          XSCAN = NREC*RAST*50
          YSCAN = IYLEN*RAST*50
          XMAXIP = NREC*RAST*50
          YMAXIP = IYLEN*RAST*50
          RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
C
C---- For MicroED, the Bragg angles are very small, best to use the entire
C     image as the "central region", so do NOT divide XMAXIP by 2.
C
          IF (ILIMIT.EQ.0) THEN 
            XLIMIT = 0.01*(XMAXIP)
            LIMIT = NINT(100*XLIMIT)
          END IF
          IF (DEBUG(103)) THEN
            WRITE(IOUT,FMT=6102) NREC,IYLEN,RAST,XMAXIP,YMAXIP,LIMIT
            IF (ONLINE) WRITE(ITOUT,FMT=6102) NREC,IYLEN,RAST,XMAXIP,
     +                   YMAXIP,LIMIT
 6102       FORMAT(1X,'NREC',I6,' IYLEN',I6,' RAST',F6.4,' XMAXIP',
     +                  F8.0,'  YMAXIP',F8.0,'  LIMIT',I8)
          END IF
          TEXT1 = TEXT1(1:LENSTR(TEXT1))//text2
          IF ((LENSTR(TEXT1).GT.2).AND.(.NOT.DETPARMWARN)) THEN
            WRITE(IOUT,FMT=6100) TEXT1(1:LENSTR(TEXT1))
            IF (ONLINE) WRITE(ITOUT,FMT=6100) TEXT1(1:LENSTR(TEXT1))
          END IF
 6100     FORMAT(/,1x,'*** As wavelength is < 0.05, these are assumed',
     +          ' to be electron diffraction images written',/,1X,
     +          'in SMV format rather than ADSC CCD images.',/,1X,
     +          'These detectors have different characteristics so:',/,
     +          1X,A,/,1X,'Null pixel threshold (NULLPIX) has been set',
     +          ' to -1',/,1X,'To override these values use the ',
     +          'sitefile option: imosflm --site sitefile.dat')
          DETPARMWARN = .TRUE.
C
C---- Cannot call WARNINGS here, the Tcl code is not set up to deal with this
C
C          CALL WARNINGS
        END IF
      ENDIF
C
      IF ((SITE(1:3).EQ.'LMB').OR.((SITE.EQ.'EMBL').AND.
     +     (SCANNER(1:3).EQ.'SCR'))) THEN
        NHEAD = 0
        IF (NREC.EQ.0) NREC = 1187
        IF (IYLEN.EQ.0) IYLEN = 1187
        IF (RSCAN.EQ.0.0) RSCAN = 8887
        IF (SCANNER.EQ.'SCR3') THEN
C     
C---- Set defaults for Red scanner
C     
          IF (RSCAN.EQ.0.0) RSCAN = RSCANRED
          IF (XLIMIT.EQ.0.0) THEN
            XLIMIT = 60.0
            LIMIT = 100* NINT(XLIMIT)
          END IF
          IF (IPIX.EQ.0) RAST = 0.187
          SCNSZ = 7.48
          FACT = 0.4/SCNSZ
        END IF
      END IF
C     
      IF (MACHINE.EQ.'RAXI') THEN
        IF ((MODEL.EQ.'RAXISIV').OR.(MODEL.EQ.'RAXISV')
     $       .OR.(MODEL.EQ.'RAXISHTC')) THEN
C     AL              IF ((IYSCAL.EQ.0).AND.(IPIXY.EQ.0)) YSCAL = 1.0
          IF (IGAIN.EQ.0) THEN
            IGAIN = 1
            GAIN = 1.0
CAL---- Fix for Montevideo Raxis images .. should not be needed now
CAL            IF (NREC.EQ.1900) GAIN = 5.0
          ENDIF
          IF ((MODEL.EQ.'RAXISHTC').AND.(IYSCAL.EQ.0).AND.
     +              (IPIXY.EQ.0)) THEN
                 YSCAL = 0.995
CAL---- Fix for Montevideo Raxis images .. should not be needed now
CAL                 IF (NREC.EQ.1900) YSCAL = 105.0/101.7
                 YSCALIN = YSCAL
          END IF
C     
C---- Set default ADC offset to 4
C     
          IF (IDIVIDE.EQ.8.AND.IIDIVIDE.EQ.0) IDIVIDE = 4
        ELSE
          FINE = (NREC.EQ.1900)
C     
C---- YSCAL based on pixel sizes of 101.7mu in fast direction, 105mu in 
C     slow.
          IF ((IYSCAL.EQ.0).AND.(IPIXY.EQ.0)) YSCAL = 105.0/101.7
          YSCALIN = YSCAL
          IF (IGAIN.EQ.0)THEN
            IGAIN = 1
            GAIN = 5.0
          ENDIF
        END IF
      ELSE IF (MACHINE.EQ.'MAR ') THEN
        IF (NREC.EQ.0) NREC = 1200
        IF (IYLEN.EQ.0) IYLEN = 1200
C     
C---- Fuji scanners at CHESS
C     
      ELSE IF (MACHINE.EQ.'FUJI') THEN
        IF (NREC.EQ.0) NREC = 2560
        IF (IYLEN.EQ.0) IYLEN = 2048
C     
C---- Mac Science DIP2000
C     
      ELSE IF (MACHINE.EQ.'DIP2') THEN
        IF (NREC.EQ.0) NREC = 2500
        IF (IYLEN.EQ.0) IYLEN = 2500
C     
C---- LMB scanner (image assigned from header so no code needed)
C     
      ELSE IF (MACHINE.EQ.'LMB') THEN
        CONTINUE
C     
C---- ESRF CCD (image assigned from header so no code needed)
C     
      ELSE IF (MACHINE.EQ.'LMB') THEN
        CONTINUE
      END IF
C     
      NWORD = IYLEN
      NBYTE = IYLEN*2
C     
C---- Correct beam coordinates for swing angle if necessary
C     NOTE : This code only executed when an IMAGE keyword has been
C     given, so only need to consider one image
C     AL not necessary          XCENMM(1,1)=XMM(1)
C     
C     AL change to YCENMM          YCENMM(1,1)=YSCAL*YMM(1)
C     HRP watch for beam set from image header - IBEAM = 3
      IF(IBEAM.NE.3)YCENMM(1,1)=YSCAL*YCENMMIN(1)
      IF ((TWOTHETA.NE.0.0).AND.(ISWUNG.EQ.0)) THEN
C     AL             XCENMM(1,1) = XCENMM(1,1) + 
C     AL     +                COS(OMEGAF)*0.01*XTOFD*TAN(TWOTHETA*DTOR)
C     AL             YCENMM(1,1) = YCENMM(1,1) + 
C     AL     +                SIN(OMEGAF)*YSCAL*0.01*XTOFD*TAN(TWOTHETA
C     *DTOR)
        XCENMM(1,1) = XCENMMIN(1) + 
     +       COS(OMEGAF)*0.01*XTOFD*TAN(TWOTHETA*DTOR)
        YCENMM(1,1) = YCENMMIN(1) + 
     +       SIN(OMEGAF)*YSCAL*0.01*XTOFD*TAN(TWOTHETA*DTOR)
      END IF
C     
C---- machine specific code ---- overload values from header, two theta correction
C 
      IF((MACHINE.EQ.'JUPI').OR.(MACHINE.EQ.'SATU').OR.
     $     (MACHINE.EQ.'MERC').OR.(MACHINE.EQ.'A200')
     $     .OR.(MACHINE.EQ.'RIPI').OR.(MACHINE.EQ.'RIEI')
     +     .OR.(MACHINE.EQ.'EIGE').OR.(MACHINE.EQ.'PILA')) THEN
        IF ((ICUT.EQ.0).AND.(HCUTOFF.GT.0)) CUTOFF = HCUTOFF
        IF ((IPRCUT.EQ.0).AND.(HPRCUTOFF.GT.0)) PRCUTOFF = HPRCUTOFF
      ENDIF
C     
C---- machine specific code ---- having read beam position from header; CBF is
C     handled elsewhere
C 
      IF((MACHINE.EQ.'JUPI').OR.(MACHINE.EQ.'SATU').OR.
     $     (MACHINE.EQ.'MERC').OR.(MACHINE.EQ.'A200').OR.
     $     (MACHINE.EQ.'ADSC').OR.
     $     (MACHINE.EQ.'MARC').OR.(MACHINE.EQ.'BRUK').OR.
     $     (MACHINE.EQ.'OXFO').OR.(MACHINE.EQ.'NOIR').OR.
     $     (MODEL.EQ.'RAXISHTC').OR.(MACHINE.EQ.'PILA').OR.
     $     (MODEL.EQ.'RAXIS2NU').OR.(MACHINE.EQ.'RIPI').OR.
     $     (MACHINE.EQ.'RIEI').OR.(MACHINE.EQ.'APAD').OR.
     $     (MACHINE.EQ.'EIGE').OR.(MACHINE.EQ.'TAUR').OR.
     $     (MACHINE.EQ.'TIME').OR.HDF5FILE)THEN
C     .. hrp 16.02.2015
C     .. placeholder until Stoe Pilatus includes beam centre in header
C     .. AGWL 7/11/2016
C     .. This breaks images from Campinas, which are Pilatus 300K,
C     -- the direct beam is set to centre of image and if updated, when 
C     .. "Index" is activated in iMosflm it resets beam to image centre
C     .. so indexing always fails. Change test to explicitly test for
C     .. MACHINE = STOE (which at the moment is not coded at all
C
CAGWL        if(MACHINE.NE.'RIPI'.and.model(1:4).eq.'300K')then
        if(MACHINE.EQ.'STOE'.and.model(1:4).eq.'300K')then
          hbeamx = rast*nrec/2
          hbeamy = rast * yscal * iylen/2
          ibeam = 3
        endif
        IF(IBEAM.EQ.3)THEN
C     
C---- HRP15112001 ADSC images are inverted left to right? 
C     hrp 09.01.2003. It seems that 
C     although Jupiter images are also inverted, the beam position in the 
C     header isn't - though I may be wrong on this. ESRF ADSCs have the
C     beam position already in the Mosflm frame, but as far as I know,
C     all other ADSCs have it in the original ADSC frame of reference;
C     however, since Mosflm inverts it anyway, the guys at the ESRF are
C     being too helpful!
C     
C     As of 04.04.2003, the ESRF has four ADSC detectors, SN 413, 420,
C     428 and 444; when they are changed,, we need to uncomment the
C     following code
C     
          DO 520 I = 1,3
            XMM(I) = HBEAMX
            IF((MACHINE.EQ.'ADSC').AND.((HSERIAL(1:3).EQ.'413').OR.
     &           (HSERIAL(1:3).EQ.'420').OR.(HSERIAL(1:3).EQ.'428').OR.
     $           (HSERIAL(1:3).EQ.'444')))THEN
              IF(HDATEC.LT.20030807)THEN
                IF(I.EQ.1) THEN
                  WRITE(IOUT,1492)HSERIAL(1:3)
                  IF(ONLINE)WRITE(ITOUT,1492)HSERIAL(1:3)
 1492             FORMAT(/,72('*'),/,' This appears to be a detector ',
     $                 'located at the ESRF (SN ',A3,'); the ',/' X-c',
     $                 'o-ordinate of the direct beam as recorded in ',
     $                 'the header is probably',/,' inverted; Mosflm ',
     $                 'has re-inverted it, so you should check the b',
     $                 'eam',/,' centre carefully.',/,72('='),/) 
C     remove to correct header  
                ENDIF
                XMM(I) = (RAST*NREC)-HBEAMX
              ENDIF
            ENDIF
            IF((MACHINE.EQ.'BRUK'.AND.HOSCAXIS.EQ.'PHI').OR.
     $           MACHINE.EQ.'OXFO')THEN
              YMM(I) = HBEAMY + TAN(DTOR*TWOTHETA) * XTOFD/100.0
C
C---- Need to check that this is actually correct for Rigaku Eiger (RIEI)
C     23/8/18
C
            ELSEIF((MACHINE.EQ.'RIPI').OR.(MACHINE.EQ.'RIEI'))THEN
              XMM(I) = HBEAMX - TAN(DTOR*TWOTHETA) * XTOFD/100.0
              YMM(I) = HBEAMY
            ELSE
              YMM(I) = HBEAMY - TAN(DTOR*TWOTHETA) * XTOFD/100.0
            ENDIF
            DO 510 J = 1,MAXPAX
              XCENMM(J,I) = XMM(I)
              YCENMM(J,I) = YMM(I)
              XCENMMIN(J) = XMM(I)
              YCENMMIN(J) = YMM(I)
 510        ENDDO
 520      ENDDO
C
C only write this out if it's changed...
C
          IF(ABS(XCEN - (XMM(1) * 0.01)).GT.1e-3.and.
     $         ABS(YCEN - (YMM(1) * 0.01)).GT.1e-3)THEN
            WRITE(IOUT,FMT=6080)XMM(1),YMM(1)
            IF(ONLINE)WRITE(ITOUT,FMT=6080)XMM(1),YMM(1)
          ENDIF
          XCEN = XMM(1) * 0.01
          YCEN = YMM(1) * 0.01
c          write(iout,fmt=9876) xcen
c          if (online) write(itout,fmt=9876) xcen
c 9876     format(1x,'xcen set in section from xmm, now;',F8.2)
        ELSE IF(IBEAM.EQ.2)THEN
          YCOR = HBEAMY - TAN(DTOR*TWOTHETA) * XTOFD/100.0
          IF((ABS(HBEAMX-XMM(1)).GT.1E-2).or.
     $         (ABS(YCOR-YMM(1)).GT.1E-2))THEN
            WRITE(IOUT,FMT=6082)XMM(1),YMM(1),
     $           HBEAMX,YCOR
            IF(ONLINE)WRITE(ITOUT,FMT=6082)XMM(1),YMM(1),
     $           HBEAMX,YCOR
          ELSE
            WRITE(IOUT,FMT=6084)XMM(1),YMM(1)
            IF(ONLINE)WRITE(ITOUT,FMT=6084)XMM(1),YMM(1)
          END IF
 6080     FORMAT(/,' Main beam position has been calculated as ',
     $         F7.2,'mm ',F7.2,'mm ', 
     $         'from parameters',/,' in the image header. ',
     $         'You should check ',
     $         'these values carefully as they may',/,
     $         ' be in error!',/)
 6082     FORMAT(4(/,'***** WARNING *****'),/,
     $         ' Input beam coordinates ',F7.2,'mm ',F7.2,
     $         'mm DO NOT agree with ',/,' those calcula',
     $         'ted from the image header (',F7.2,'mm ',
     $         F7.2,'mm)',/)
 6083     FORMAT(/,' **** Information ****',/,
     $         ' Input beam coordinates ',F7.2,'mm ',F7.2,
     $         'mm correspond to ',/,' those calcula',
     $         'ted from the image header (',F7.2,'mm ',
     $         F7.2,'mm)',/)
 6084     FORMAT(/,' Input beam coordinates ',F7.2,'mm ',
     $         F7.2,'mm will be used',/)
        END IF
      END IF
C     
C---- Machine specific code ---- R-Axis with quarter chi circle
C     (Jupiter format images) 
C     
      IF (MACHINE.EQ.'RAXI'.and.newraxis)THEN
chrp 20.08.2007        INVERTX = .TRUE.
chrp 30.04.2010 - set in gethdr.f for newraxis        OMEGAFD = 90.0
chrp 30.04.2010 - set in gethdr.f for newraxis        OMEGAF = OMEGAFD * DTOR
        nullpix = 0
        IDIVIDE = 0
        IF(IBEAM.EQ.3)THEN
          XMM(1) = (RAST*NREC)-HBEAMX
          YMM(1) = HBEAMY
          XCENMM(1,1) = XMM(1)
          YCENMM(1,1) = YMM(1)
          XCENMMIN(1) = XMM(1)
          YCENMMIN(1) = YMM(1)
          WRITE(IOUT,FMT=6080)XMM(1),YMM(1)
          IF(ONLINE)WRITE(ITOUT,FMT=6080)XMM(1),YMM(1)
        ELSE IF(IBEAM.EQ.2)THEN
          IF((ABS(HBEAMX-XMM(1)).GT.1E-2).or.
     $         (ABS(HBEAMY-YMM(1)).GT.1E-2))THEN
            WRITE(IOUT,FMT=6082)XMM(1),YMM(1),
     $           HBEAMX,HBEAMY
            IF(ONLINE)WRITE(ITOUT,FMT=6082)XMM(1),YMM(1),
     $           HBEAMX,HBEAMY
          ELSE
            WRITE(IOUT,FMT=6084)XMM(1),YMM(1)
            IF(ONLINE)WRITE(ITOUT,FMT=6084)XMM(1),YMM(1)
          ENDIF
        END IF
      ENDIF
C
C---- Machine specific code - ADSC at Australian synchrotron has 
C     reversephi - I think Taiwan device also has this.
C
c      IF(MACHINE.EQ.'ADSC'.AND.HSERIAL.EQ.'457')THEN
c        PRINT*,'this is at the Australian synchrotron'
c        OMEGAFD = OMEGAFD + 180.0
c      ENDIF
C     

C     
C     
C---- Set direct beam coordinates to middle of image if not supplied on
C     a BEAM keyword
C     
      IF (IBEAM.EQ.0) THEN
        XCENMM(1,1) = 0.5*NREC*RAST
        YCENMM(1,1) = 0.5*IYLEN*RAST*YSCAL
        XCENMMIN(1) = 0.5*NREC*RAST
        YCENMMIN(1) = 0.5*IYLEN*RAST*YSCAL
        XMM(1) = 0.5*NREC*RAST
        YMM(1) = 0.5*IYLEN*RAST*YSCAL
        IF((ABS(TWOTHETA).GT.1E-3).AND.ISWUNG.EQ.0)THEN
          ISWUNG = 1
          TRUSTED = .TRUE.
          DO 540 I = 1,3
            YMM(I) = YMM(I) + TAN(DTOR*TWOTHETA) * XTOFD/100.0
            DO 530 J = 1,MAXPAX
              XCENMM(J,I) = XMM(I)
              YCENMM(J,I) = YMM(I)
              XCENMMIN(J) = XMM(I)
              YCENMMIN(J) = YMM(I)
 530        ENDDO
 540      ENDDO
        ENDIF
      END IF
C
C---- want to use whole image as central region for MicroED data because
C     diffraction angles are so small.
C     Note there is no test on the detector here, so this overrides
C     values of XLIMIT and LIMIT set in machine specific code .. this should
C     really be removed!
C
      IF((ILIMIT.EQ.0).AND.(.NOT.MICROED)) THEN
        XLIMIT = 0.25 * NREC * RAST
        LIMIT = NINT(100*XLIMIT)
      ENDIF

C     
C---- For Mar, Fuji (at chess) etc image plate data, correct direct beam
C     X coordinate for inversion of image.
C     Raster size is RAST mm
C     
      
      IF (INVERTX) THEN
        DO 698 I = 1,MAXPAX
          XCENMM(I,1) = NREC*RAST - XCENMMIN(I)
C     
C---- Because we have to use XCENMMIN here, must apply correction
C     for swung detectors
C     
          IF ((TWOTHETA.NE.0.0).AND.(ISWUNG.EQ.0)) THEN
            XCENMM(I,1) = XCENMM(I,1) + 
     +           COS(OMEGAF)*0.01*XTOFD*TAN(TWOTHETA*DTOR)
          END IF
 698    CONTINUE
        IF (RSCANX.NE.0.0) RSCANX = 100.0*NREC*RAST - RSCANX
        IF (RMINXINP.NE.0.0) RMINX = 100.0*NREC*RAST - RMINXINP
C     
C---- Only change CCX if it was read in from input. It may have been
C     passed from the previous round of a multi-segment post refinement
C     in which case it MUST NOT be reset.
C     
        IF ((ICCX.EQ.1).AND.(.NOT.CCXRESET)) THEN
          CCX = -CCX
          CCXRESET = .TRUE.
        END IF
      END IF
C     
C---- If detector is swung out, correct direct beam coordinates
C     (if keyword SWUNG_OUT is given the beam coordinates are assumed
C     to be those with the detector set at the given two-theta angle.
C     
      IF (ISWUNG.EQ.1) THEN
        XCEN0 = NINT(100.0*XCENMM(1,1) - 
     +       COS(OMEGAF)*XTOFD*TAN(TWOTHETA*DTOR))
        YCEN0 = NINT(100.0*YCENMM(1,1) - 
     +       SIN(OMEGAF)*XTOFD*TAN(TWOTHETA*DTOR))
      ELSE
C     AL            XCEN0 = NINT(100.0*XMM(1))
        XCEN0 = NINT(100.0*XCENMMIN(1))
        IF (INVERTX) XCEN0 = NINT(100.0*(NREC*RAST-XCENMMIN(1)))
C     AL            YCEN0 = NINT(100.0*YMM(1))
        YCEN0 = NINT(100.0*YCENMMIN(1))
      END IF
C     
C---- Find spots if requested
C     
C     
C---- Set up default radial background direction
C     
      ROTATED = ((ABS(OMEGAF/DTOR).LT.1.0).OR.
     +     ((ABS(OMEGAF/DTOR-180.0)).LT.1.0))
C     
      IF ((IXOFFSET.EQ.0).AND.(IYOFFSET.EQ.0)) THEN
        RADX = ROTATED
        RADY = (.NOT.RADX)
      END IF
C     
C---- Assign a RMIN, RMAX if not defaulted, to 0.05 and 0.45 of image
C     size
C     
      IF (ROTATED) THEN
        IF (RMINSP.EQ.0) RMINSP = SIGN(NREC*RAST*0.05,RMAXSP)
        IF (RMAXSP.EQ.0) RMAXSP = SIGN(NREC*RAST*0.45,RMINSP)
      ELSE
        IF (RMINSP.EQ.0) RMINSP = SIGN(IYLEN*RAST*0.05,RMAXSP)
        IF (RMAXSP.EQ.0) RMAXSP = SIGN(IYLEN*RAST*0.45,RMINSP)
      END IF
C     
C---- make the same as in mxdspl.f ---- hrp 21.09.2004
C     
      RMINSP = RAST*NINT(RMINSP/RAST)
      RMAXSP = RAST*NINT(RMAXSP/RAST)
C     
C---- Check for an offset detector, and if necessary, change the
C     direction
C     that the background strip is measured in.
C     
      IF ((ABS(XCENMM(1,1)-NREC*RAST*0.5).GT.0.045*NREC*RAST).AND.
     +     (ROTATED)) THEN
        RMINSP = SIGN(RMINSP,(NREC*RAST*0.5-XCENMM(1,1)))
        RMAXSP = SIGN(RMAXSP,(NREC*RAST*0.5-XCENMM(1,1)))
      END IF
      IF ((ABS(YCENMM(1,1)-IYLEN*RAST*0.5).GT.0.045*IYLEN*RAST).AND.
     +     (.NOT.ROTATED)) THEN
        RMINSP = SIGN(RMINSP,(IYLEN*RAST*0.5-YCENMM(1,1)))
        RMAXSP = SIGN(RMAXSP,(IYLEN*RAST*0.5-YCENMM(1,1)))
      END IF
C
C---- check for a 2N x 2N tiled detector, and tell XML about the offset b/g box
C
      IXCEN = 0.01*XCEN/RAST
      IYCEN = 0.01*YCEN/RAST
      IF(RADX)THEN
        NOFF = NPIXBG/2
        IXOFF = XOFFSET/RAST
        IST =  IYCEN - NOFF + IXOFF   
        IEND =  IYCEN + NOFF + IXOFF 
        DO 6 I = 1,NTILEX-1
          ITOP = IEND + TILEWX(I)/2 + 1
          IBOT = IST - TILEWX(I)/2 - 1
          IF ((TILEX(I).GE.IBOT).AND.(TILEX(I).LE.ITOP)) THEN
C     
C---- Strip lies within gap, apply offset if even number of tiles only
C
            IF(MOD(NTILEX,2).EQ.0.AND.NOTDONEOFFSET)THEN
              NOTDONEOFFSET = .FALSE.
              XOFFSET = XOFFSET + (NPIXBG + 2*TILEWX(I)+ 2)*RAST
              WRITE(IOUT,FMT=6024) NPIXBG*RAST
              IF (ONLINE) WRITE(ITOUT,FMT=6024) NPIXBG*RAST
 6024         FORMAT(/,1X,'Background strip overlaps gap between ',
     +             'detector tiles, so XOFFSET changed to',F6.1,'mm')
            END IF
          ENDIF
          BGBOXOFFSET = NPIXBG
 6      ENDDO
      ELSE
C
        NOFF = NPIXBG/2
        IYOFFL = YOFFSET/RAST
        IST =  IYCEN - NOFF + IYOFFL  
        IEND =  IYCEN + NOFF + IYOFFL
        DO 7 I = 1,NTILEY-1
          ITOP = IEND + TILEWY(I)/2 + 1
          IBOT = IST - TILEWY(I)/2 - 1
          IF ((TILEY(I).GE.IBOT).AND.(TILEY(I).LE.ITOP)) THEN
C     
C---- Strip lies within gap, apply offset if even number of tiles only
C     
            IF(MOD(NTILEY,2).EQ.0.AND.NOTDONEOFFSET)THEN
              NOTDONEOFFSET = .FALSE.
              YOFFSET = YOFFSET + (NPIXBG+TILEWY(I)+ 2)*RAST
              WRITE(IOUT,FMT=6025) NPIXBG*RAST
              IF (ONLINE) WRITE(ITOUT,FMT=6025) NPIXBG*RAST
 6025         FORMAT(/,1X,'Background strip overlaps gap between ',
     +             'detector tiles, so YOFFSET changed to',F6.1,'mm')
            END IF
          ENDIF
          BGBOXOFFSET = NPIXBG
 7      CONTINUE
      ENDIF
C
C---- Need to add code for this for Rigaku Eiger 23/8/18
C
      IF(MACHINE.EQ.'RIPI'.AND..NOT.DONERIPI)THEN
        DONERIPI = .TRUE.
        STARTX = 195
        WIDTHX = 17
        STEPX = STARTX + WIDTHX
C     
C---- For proper exclusion, set start point IOFFSET pixels earlier
C     and extend width by 2*IOFFSET pixels. This is because of uncertainty
C     about conversion of pixels to mm, for example, are coords of
C     first pixel 0,0 or 0.5*rast,0.5*rast etc. 
C
        IOFFSET = 1
        STARTX = STARTX - IOFFSET
        WIDTHX = WIDTHX + 2 * IOFFSET
        DO 5100 II = 0,NTILEX-2
          NXYEXCDET = NXYEXCDET + 1
          XYEXC(1,NXYEXCDET) = 100.0*rast*(startx + (ii*stepx))
          XYEXC(2,NXYEXCDET) = 0.0
          XYEXC(3,NXYEXCDET) = 
     +         100.0*rast*(startx + (ii*stepx) + widthx)
          XYEXC(4,NXYEXCDET) = 100.0*rast*IYLEN
 5100   ENDDO
C     
C---- Now lines parallel to X
C     
        STARTY = 487
        WIDTHY = 7
        STEPY = STARTY + WIDTHY
        STARTY = STARTY - IOFFSET
        WIDTHY = WIDTHY + 2 * IOFFSET
        DO 5200 II = 0,NTILEY-2
          NXYEXCDET = NXYEXCDET + 1
          XYEXC(1,NXYEXCDET) = 0.0
          XYEXC(2,NXYEXCDET) = 100.0*rast*(starty + (ii*stepy))
          XYEXC(3,NXYEXCDET) = 100.0*rast*nrec
          XYEXC(4,NXYEXCDET) = 
     +         100.0*rast*(starty + (ii*stepy) + widthy)
 5200   ENDDO
        
        NXYEXC = NXYEXCDET
      endif
C     
C---- XML output
C
C---- first set TRUSTED flag for trusted detectors
C
      IF((MODEL.EQ.'QUAD').OR.(MODEL.EQ.'Q210').OR.(MODEL.EQ.'Q315')
     $     .OR.(MODEL.EQ.'Q420').OR.(MODEL.EQ.'SAPPHIRE').OR.
     $     (MODEL.EQ.'Q270').OR.
     $     (MODEL.EQ.'JUPITER').OR.(MODEL.EQ.'SATURN').OR.
     $     (MODEL.EQ.'MERCURY').OR.(MODEL.EQ.'A200').OR.
     $     (MODEL.EQ.'200K').OR.(MODEL.EQ.'MARCCD').OR.
     $     (MODEL.EQ.'MARMOSAIC').OR.(MODEL.EQ.'MOSAIC3').OR.
CAL     $     (MACHINE.EQ.'CBF').OR.(MACHINE.EQ.'APAD').OR.
     $     (MACHINE.EQ.'PHOT').OR.(MACHINE.EQ.'APAD').OR.
     $     (MODEL.EQ.'MOSAIC4').OR.(MACHINE.EQ.'PILA').or.
     $     (MODEL.EQ.'MARF').OR.(MACHINE.EQ.'RIPI'.or.
     +     (MACHINE.EQ.'RIEI').or.(MACHINE.EQ.'TIME').or.
     $     (MODEL.EQ.'EIGE').OR.(MACHINE.EQ.'HDF5')))
     $     TRUSTED = .TRUE.

        CALL BADTOGOOD(XODFILE,ODFILE,LENSTR(ODFILE))
C     ..
C
      IF(SOCKLO.AND.HEADONLY.AND..NOT.NO_XML)THEN
        IF(MACHINE.NE.'HDF5')THEN
          IF(PHIONLY)THEN
C     
C---- Print for program flow
C  
            CALLED = 'WRITE_SOCKET'
            COMMENT ='write XML block brief_header_response for PHIONLY'
            IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
 1707       FORMAT('<?xml version=''1.0''?>',
     $         '<!DOCTYPE brief_header_response>',
     $         '<brief_header_response><status><code>ok</code>',
     $         '</status>',
     $         '<image_filename>',A,'</image_filename>',
     $         '<image_template>',A,'</image_template>',
     $         '<image_number>',I8,'</image_number>',
     $         '<phi_start>',F10.2,'</phi_start>',
     $         '<phi_end>',F10.2,'</phi_end>',
     $         '<gain>',F7.2,'</gain>',
     $         '</brief_header_response>')
            WRITE(IOLINE2,FMT=1707)XODFILE(1:LENSTR(XODFILE)),
     $         TEMPLSAV(1:lenstr(templsav)),ID,
     $         HPHIS,HPHIE,GAIN
          ELSE
 1684       FORMAT('<?xml version=''1.0''?>',
     $         '<!DOCTYPE header_response>',
     $         '<header_response><status><code>ok</code>',
     $         '</status>',
     $         '<detector_manufacturer>',A,'</detector_manufacturer>',
     $         '<detector_model>',A,'</detector_model>',
     $         '<detector_serial_number>',A,'</detector_serial_number>',
     $         '<trusted_detector>',L1,'</trusted_detector>',
     $         '<saturation_pixel_value>',I12,
     $         '</saturation_pixel_value>',
     $         '<maximum_pixel_value>',I12,'</maximum_pixel_value>',
     $         '<null_pixel_value>',I9,
     $         '</null_pixel_value>',
     $         '<maximum_peak_ratio>',F8.1,
     $         '</maximum_peak_ratio>',
     $         '<maximum_background_ratio>',F8.1,
     $         '</maximum_background_ratio>',
     $         '<maximum_refinement_gradient>',F8.4,
     $         '</maximum_refinement_gradient>',
     $         '<maximum_integration_gradient>',F8.4,
     $         '</maximum_integration_gradient>',
     $         '<central_region_size>',F7.2,'</central_region_size>',
     $         '<image_filename>',A,'</image_filename>',
     $         '<image_template>',A,'</image_template>',
     $         '<image_number>',I8,'</image_number>',
     $         '<header_size>',I5,'</header_size>',
     $         '<image_width>',I5,'</image_width>',
     $         '<image_height>',I5,'</image_height>',
     $         '<phi_start>',F10.2,'</phi_start>',
     $         '<phi_end>',F10.2,'</phi_end>',
     $         '<beam_x>',F12.2,'</beam_x><beam_y>',F12.2,'</beam_y>',
     $         '<beamstop_radius>',F7.2,'</beamstop_radius>',
     $         '<distance>',F7.2,'</distance>',
     $         '<two_theta>',F8.2,'</two_theta>',
     $         '<wavelength>',F8.6,'</wavelength>',
     $         '<pixel_size>',F7.5,'</pixel_size>',
     $         '<yscale>',F8.4,'</yscale>',
     $         '<gain>',F7.2,'</gain>',
     $         '<adc_offset>',I3,'</adc_offset>',
     $         '<omegafd>',F7.3,'</omegafd>',
     $         '<invertx>',L1,'</invertx>',
     $         '<detector_limits>',
     $         '<minimum_x>',F10.2,'</minimum_x>',
     $         '<maximum_x>',F10.2,'</maximum_x>',
     $         '<minimum_y>',F10.2,'</minimum_y>',
     $         '<maximum_y>',F10.2,'</maximum_y>',
     $         '<maximum_radius>',F10.2,'</maximum_radius>',
     $         '</detector_limits>',
     $         '<scanning_limits>',
     $         '<maximum_x>',F10.2,'</maximum_x>',
     $         '<maximum_y>',F10.2,'</maximum_y>',
     $         '<maximum_radius>',F10.2,'</maximum_radius>',
     $         '<centre_x>',F10.2,'</centre_x>',
     $         '<centre_y>',F10.2,'</centre_y>',
     $         '</scanning_limits>',
     $         '<number_of_tiles_x>',I2,'</number_of_tiles_x>',
     $         '<tile_width>',I6,'</tile_width>',
     $         '<tile_gap_x>',I2,'</tile_gap_x>',
     $         '<number_of_tiles_y>',I2,'</number_of_tiles_y>',
     $         '<tile_height>',I6,'</tile_height>',
     $         '<tile_gap_y>',I2,'</tile_gap_y>',
     $         '<background_box_direction>',L1,
     $         '</background_box_direction>',
     $         '<background_box_offset>',F6.1,
     $         '</background_box_offset>',
     $         '<spotfile_origin>',A,'</spotfile_origin>',
     $         '<spotfile_axis_order>',A,'</spotfile_axis_order>',
     $         '<twotheta_swing_axis>',A,'</twotheta_swing_axis>')
 1686       FORMAT('</header_response>')
C
C---- Define swingaxis as the direct beam coordinate in the detector frame
C     that changes if twotheta is non zero. For ADSC and RAXIS IV images
C     that I have tested twotheta has to be given as a negative number.
C     SWINGAXIS +X means that the X beam coord gets larger for increasing -ve
C     twotheta, -Y means that the Y coord gets smaller for increasingly large
C     -ve two theta.
C
C---- First case is ADSC
C
            IF ((NINT(OMEGAFD).EQ.0).AND.(INVERTX)) THEN
              SWINGAXIS = "+X"
C
C---- Raxis IV
C
            ELSE IF ((NINT(OMEGAFD).EQ.90).AND.(.NOT.INVERTX)) THEN
              SWINGAXIS = "-Y"
            END IF
c
C---- assume for now that tilex(1) = tilex(2) = ... etc, also for tiley()
C
            WRITE(IOLINE2,FMT=1684)MACHINEXML,MODEL,
     $           HSERIAL(1:LENSTR(HSERIAL)),TRUSTED,CUTOFF,
     $           PRCUTOFF,NULLPIX,
     $           PKRAT,BGRAT,GRADMAXR,GRADMAX,
     $           FLOAT(LIMIT/100),
     $           XODFILE(1:LENSTR(XODFILE)),
     $           TEMPLSAV(1:lenstr(templsav)),
     $           ID,NHBYTE,NREC,IYLEN,HPHIS,HPHIE,
     $           XMM(1),YMM(1)/YSCAL,RMINIP/100.0,HDIST,TWOTHETA,HWAVE,
     $           HRAST,YSCAL,GAIN,IDIVIDE,
     $           OMEGAFD-OMEGAREV,INVERTX,
     $           XMIN*0.01,XMAX*0.01,YMIN*0.01,YMAX*0.01,RMAX*0.01,
     $           XSCAN*0.01,YSCAN*0.01,
     $           RSCAN*0.01,RSCANX*0.01,RSCANY*0.01,
     $           NTILEX,TILEX(1),TILEWX(1),NTILEY,TILEY(1),
     $           TILEWY(1),
     $           RADX,BGBOXOFFSET*RAST,
     $           SPOTFILEORIGIN,SPOTFILEAXISORDER,SWINGAXIS
C     
C---- Print for program flow
C  
            IF (DEBUG(101)) THEN
              WRITE(IOUT,FMT=6004) YSCAL
              IF (ONLINE) WRITE(ITOUT,FMT=6004) YSCAL
 6004         FORMAT(1X,'YSCAL',f16.4)
            END IF
            CALLED = 'WRITE_SOCKET'
            COMMENT ='write XML block header_response'
            IF (DEBUG(99)) 
     +                  CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(IOLINE2),
     $           IOLINE2)
C     WRITE(IOLINE2,FMT=1685)GAIN
C     WRITE(*,*)IOLINE2(1:LENSTR(IOLINE2))
C     CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(IOLINE2),
C     $       IOLINE2)
            WRITE(IOLINE2,FMT=1686)
          ENDIF
C
C---- Print for program flow
C  
          CALLED = 'WRITE_SOCKET'
          COMMENT = 'write XML block header_response'
          IF (DEBUG(99)) 
     +           CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
          CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(IOLINE2),
     $         IOLINE2)
        ENDIF
      ENDIF
C     
C---- turn on output to screen if PHIONLY
C
      IF(PHIONLY)THEN
        ONLINE = SONLINE
      ENDIF
      IF (DEBUG(103)) THEN
        WRITE(IOUT,6002)      
        IF (ONLINE) WRITE(ITOUT,6002)      
 6002   FORMAT(1X,'Exiting SECTION')
      END IF
      RETURN
      END
C== SECTOR ==
C $Id: sector.f,v 1.4 2007/12/18 14:55:49 harry Exp $
C
C
      SUBROUTINE SECTOR(PSI,PHI,NSPOT,NRJ)
      IMPLICIT NONE
C     ===================================
C
C
C
C---- Flags reflections lying outside a sector with half-angle
C     phi centred at angle psi (must be 0 or 90).
C
C
C
C
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     ..
C     .. Scalar Arguments ..
      REAL PHI,PSI
      INTEGER NRJ,NSPOT
C     ..
C     .. Local Scalars ..
      REAL ACHI,CHI,X,Y
      INTEGER I
C     ..
C     .. Local Arrays ..
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC ABS,ATAN
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/gendata.f
C
C $Id: gendata.f,v 1.6 2021/08/19 10:53:54 andrew Exp $
C
C--- awk generated include file  gendata.h
C---- START of include file gendata.h
C
C     IMG       Partiality indicator. 0 for full reflections, 1 to 100
C                   for partials. Negative for partials at the start of the
C                   rotation range, +ve for partials at the end of the 
C                   rotation. Set in subroutine REEK using DELEPS calculated
C                   in subroutine DSTAR
C
C     IRG       Reflection flag  (Set by SPTEST called from DSTAR)
C               =  0  Spot can be measured
C               =  1  Outside R, X, Y limits
C               =  2  Overlapping spot (set later)
C               =  3  Too wide in phi (more than NWMAX images)
C               =  4  DST .GT. DSTMAX  Not included in final film list -
C                       used only to check for overlaps at edge of film.
C               =  5  Overlapping spot from another lattice
C               = 10  Spot is within cusp, but will be observed...not included
C                     in final spot list but must be included in predicted
C                      pattern
C
C               =  21  Spot present on 2 images, this is 1st
C               =  22  Spot present on 2 images, this is 2nd
C
C               =  31  Spot present on 3 images, this is 1st
C               =  32  Spot present on 3 images, this is 2nd
C               =  33  Spot present on 3 images, this is 3rd
C
C               =  41  Spot present on 4 images, this is 1st
C               =  42  Spot present on 4 images, this is 2nd
C               =  43  Spot present on 3 images, this is 3rd
C               =  44  Spot present on 4 images, this is 4th
C
C                 etc etc
C
C     XG        Virtual detector X coordinate in 10 micron units, relative to
C               an origin at the direct beam position. X is parallel to the
C               Y axis in the laboratory frame, ie orthogonal to the rotation
C               axis.
C
C     YG        Virtual detector Y coordinate in 10 micron units, relative to
C               an origin at the direct beam position. Y is parallel to the
C               Z axis in the laboratory frame, ie  the rotation axis.
C
C     IX,IY     are the coordinates of the reflection in pixels
C               (integers) wrt the first pixel in the image (lower left corner
C               cameramans view). For testing for spot overlap, these
C               coordinates are in 10 micron units. Also used for display
C               pixel coordinates when displaying predicted pattern.
C
C     IREC      Pointer to the record number of a particular spot in the
C               list of generated reflections.
C
C     IRECMULT  Record length of reflection records of generate file is
C               36*IRECMULT bytes. For a single lattice IRECMULT=1, for up
C               to 4 lattices IRECMULT=2.
C
c     NXG,NYG,NCG,NRXG,NRYG Measurement box parameters (for external 
C                           third party integration) written to MTZ
C
C     ILATTG        Lattice number 
C     NLATTOVLP     Number of overlaps from other lattices
C     HKLLATTOVLP   h,k,l indices and lattice number of the overlapping 
C                   spot from another lattice
C         HKLLATTOVLP(h,k,l,lattice_number:record_number:overlap_number)
C     ..
C     .. Arrays in common /GENDATA/ ..
      REAL FRACG,PHIG,PHIWG,XG,YG,GOODFIT,PHIOFFSET
      INTEGER INTG,ISDG,IPRO,ISDPRO,IX,IY,IREC,IRECMULT
      INTEGER*2 IRG,IMG,IGFLAG,IHG,IKG,ILG,IMPARTG,
     +          MISYMG,NXG,NYG,NCG,NRXG,NRYG,ILATTG,HKLLATTOVLP,
     +          NLATTOVLP,IDXOVLP,IDYOVLP
C     .. Scalars in common /GENDATA/ ..
      INTEGER IPACKREC,IPACKHEAD,IRECLAST
C     ..
C     .. Common block /GENDATA/ ..
C
C---- Be sure to preserve order of variables to avoid boundary issues
C     as some are I*2
C
      COMMON /GENDATA/FRACG(NREFLS),PHIG(NREFLS),PHIWG(NREFLS),
     $       XG(NREFLS),YG(NREFLS),GOODFIT(NREFLS),PHIOFFSET(NREFLS),
     $       INTG(NREFLS),ISDG(NREFLS),IPRO(NREFLS),ISDPRO(NREFLS),
     +       IX(NREFLS),IY(NREFLS),
     +       IREC(NREFLS),IPACKREC,IPACKHEAD,IRECLAST,IRECMULT,
     +       IRG(NREFLS),IMG(NREFLS),IGFLAG(NREFLS),
     +       IHG(NREFLS),IKG(NREFLS),ILG(NREFLS),
     +       IMPARTG(NREFLS),MISYMG(NREFLS),NXG(NREFLS),NYG(NREFLS),
     +       NCG(NREFLS),NRXG(NREFLS),NRYG(NREFLS),
     +       ILATTG(NREFLS),HKLLATTOVLP(4,NREFLS,MAXLATT),
     +       NLATTOVLP(NREFLS),IDXOVLP(NREFLS,MAXLATT),
     +       IDYOVLP(NREFLS,MAXLATT)
C     ..
C
C

C&&*&& end_include  ../inc/gendata.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C     ..
C     .. Equivalences ..
      SAVE
C     ..
C
C
      NRJ = 0
C
C
      DO 10 I = 1,NSPOT
        X = XG(I)
        Y = YG(I)
C
C
        IF (ABS(X).LT.0.001) THEN
          ACHI = 90.0
        ELSE
          CHI = ATAN(Y/X)/DTOR
          ACHI = ABS(CHI)
        END IF
C
C
        IF (ABS(ACHI-PSI).GE.PHI) THEN
          NRJ = NRJ + 1
          IRG(I) = 5
        END IF
C
C
   10 CONTINUE
C
C
      END
C
C $Id: seekrs.f,v 1.8 2014/11/21 14:15:46 andrew Exp $
C
C== SEEKRS ==                           
      SUBROUTINE SEEKRS(IRFMIN,IRFINC,IXSHIFT,IYSHIFT,OVRLDS,
     +                  ADDPART,NIMGSUMREF)
C     ======================================================
C
      IMPLICIT NONE
C
C
C---- Searches outside of film for refinement spots.
C     Image is divided into sectors (8) within which
C     a fixed no. of spots (LBIN = 10 )should be found.
C     The selection criterion is that I/sigma(I)
C     must be .GE. SDFAC, where SDFAC is IRFMIN for the outermost
C     bins and is incremented by IRFINC working inwards.
C     Once LBIN spots have been found in a bin, the next bin
C     is searched. IRFMIN should not be set too low, or only
C     weak spots will be found even if strong ones are present.
C     The coordinates of the spots are supplied by gensort
C     and stored in arrays IREC,IX,IY in common /GENDATA/
C     measures stripes from scanner into array BA.
C     selects data for particular spots into array BB.
C     Completed spots are tested for integrated intensity
C     and separation.
C     All spots are assumed to have maximum box size when allocating
C     space in running buffer BB
C
C       NIMGSUMREF Number of images summed for determinijg centroids. Only
C                  used to decide if BSWAP3 needs to be called.
C
C  Last changed 10/7/89 to allow use of overloaded reflections
C  Last changed 14/3/89 to allow for very few (or zero) reflections in
C  outer bins which may occur when using BASA or CASA options
C
C
C
C  DEBUG(5) for this S/R
C
C
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     ..
C     .. Scalar Arguments ..
      INTEGER IRFINC,IRFMIN,IXSHIFT,IYSHIFT,NIMGSUMREF
      LOGICAL OVRLDS,ADDPART
C     ..
C     .. Local Scalars ..
      REAL DELX,DELY,SOD,C,BGND,SDIFAC,SDIINC,SDI,VARTOT,SDELX,SDELY
      INTEGER HFWX,HFWY,I,IADDR,IBIN,IBLK,IFRST,
     +        ILAST,IND,INDF,INDL,IPNT,ISEPN,J,KMN,KMX,LASTX,
     +        LASTY,LBIN,MAXB,MAXN,MAXW,MINDL,MJ,NB,NBGND,NBIN,NC,
     +        NECX,NECY,NJ,NOSPT,NPEAK,NRX,NRY,NSIZ,NXS,NXX,NXY,NYS,NYY,
     +        RC,SBIN,SHX,SHY,XC,YC,NBGBAD,NBGBADG,NRSAVE,IIXX,IIYY,
     +        IRFMINO,IRFINCO,NPBOX,IPART,II,IFLAG,NZPBAD,IADD
      LOGICAL FULL,VALONGY
C     ..                       
C     .. Local Arrays ..
      INTEGER INF1(200),INF2(200),INF3(200),LRAS(5),PNTR(120),REC(200),
     +        X(200),Y(200)
      INTEGER*2 BB(MAXBUFF)
C     ..
C     .. External Subroutines ..
      EXTERNAL BSWAP,CGFIT,ODPLOT,RDBLK,SIZRAS,GETBOX,BSWAP2,
     +         MXD_FLU,BSWAP3
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC ABS,MOD
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/debug.f
C
C $Id: debug.f,v 1.8 2021/06/03 09:41:34 andrew Exp $
