C     .. Arrays in common block /SAVALL/ ..
C
      INTEGER ISAVIMG(MAXIMG),ISFIRST(100)
C     .. Common Block /SAVALL/ ..
      COMMON /SAVALL/ RES,RESLOW,
     +       ISAVIMG,ISFIRST,NSAVIMG,NDIR,NSAVSEG,
     +       IISCN,IISITE,IIWAVE,IIDIV,IIDISP,IINULL,IIRAST,IISEP,
     +        IIOVER,IIPIX,IIBACK,IIRES,GENERICDET
C
C
      COMMON /SAVALLC/ SAVMATSTR,SAVMATNAM,SAVENAM,SVSCN,SVSITE
C     ..
C
C
C&&*&& end_include  ../inc/savall.f
C&&*&& include  ../inc/scn.f
C
C $Id: scn.f,v 1.5 2014/11/18 14:05:40 andrew Exp $
C
C--- awk generated include file  scn.h
C---- START of include file scn.h
C
C     SCNSZ   is pixel size (in microns) divided by 25
C     RAST    pixel size in slow direction in mm
C     FACT    multiplying by FACT converts from 10 micron units 
C             (the standard unit internal to the program) into pixels
C     IYLEN   The number of pixels in the Y (fastest changing) direction
C             in the digitised image.
C     NREC    The number of pixels in the X (slow) direction in the 
C             digitised image.
C     NWORD   The number of I*2 words in the Y direction.
C     NBYTE   The number of bytes in Y direction = NWORD/2
C     NHBYTE  Number of bytes in header
C
C     ICURR   When several images are stored in a single file, ICURR is the
C             pointer to the first record of the current image in the direct
C             access file (only implemented for film data)
C     NEXTRA  The number of additional (unused) bytes padding the end of
C             each record in image file
C     BYTSWAP True if the "endedness" (Big-endian/Little-endian) of the 
C             machine that MOSFLM is running on is different to that of the
C             machine on which the image was written. This is determined by
C             looking at the value of NXPIX in the header record of the
C             image file (subroutine GETHDR)
C
C     LACTIVE True if using Rigaku active mask, False if ignoring it
C     REALLYFORCEREAD True if we want to display an image where we have
C                     changed the activemask
C
C     ROWREADT Time in seconds that the detector takes to read a row of data,
C              required for rolling shutter mode readout of Tietz detector
C              used for microED.
C     ROTSPEED Spindle rotation rate (degrees per second),required for rolling
C              shutter mode readout of Tietz detector used for microED. 
C
C
C     .. Scalars in common block /SCN/ ..
      REAL FACT,SCNSZ,RAST,RASTY,ROWREADT,ROTSPEED
      INTEGER NBYTE,NREC,NWORD,IYLEN,ICURR,NEXTRA,NHBYTE
      LOGICAL BYTSWAP,LACTIVE,REALLYFORCEREAD
C     ..
C     .. Common Block /SCN/ ..
      COMMON /SCN/ FACT,SCNSZ,RAST,RASTY,ROWREADT,ROTSPEED,
     +     NBYTE,NREC,NWORD,IYLEN,
     +     ICURR,NEXTRA,NHBYTE,BYTSWAP,LACTIVE,
     $     REALLYFORCEREAD
C&&*&& end_include  ../inc/scn.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C&&*&& include  ../inc/virbat.f
C
C $Id: virbat.f,v 1.2 2003/11/28 12:34:49 harry Exp $
C
C
C----  include file header  for virtual batches in post-refinement
C
       INTEGER NIVB,NVIRBAT,NADDMISSET,IVIRBAT
       LOGICAL NUPR_INT
       COMMON /VIRBAT/ NIVB,NVIRBAT,NADDMISSET,
     +                 IVIRBAT,NUPR_INT
C&&*&& end_include  ../inc/virbat.f
C     ..
C     .. external functions
      INTEGER LENSTR
      EXTERNAL LENSTR

C     ..                      
C     .. External Subroutines ..
      EXTERNAL BADTOGOOD,WRITE_SOCKET_LENGTH,WRITE_SOCKET_SECTION,
     +         CONTROL,GENERATE,TEMPLMAKE,OPENODS
C
      IERR = 0
      NFIRSTF = 1
      FORCEREAD = .TRUE.
      IPACK = 0
      CELLSTR = ' '
      NNDIR = 1
      highresln = res

      IF (DEBUG(106)) THEN
        WRITE(IOUT,FMT=6110) JSEG,NUMSPG,FIRSTIMG,LASTIMG,IERR,
     +                     ETA,DSTMAX,WAVE,NUMSPG,HIGHRESLN
        IF (ONLINE) WRITE(ITOUT,FMT=6110) JSEG,NUMSPG,FIRSTIMG,LASTIMG,
     +                     IERR,ETA,DSTMAX,WAVE,NUMSPG,HIGHRESLN
 6110 FORMAT(//,1X,'In SEGMENT, JSEG=',I3,' NUMSPG=',I4,' FIRSTIMG=',
     +             I8,' LASTIMG=',I8,' IERR=',I3,/,1X,' ETA ',F8.6,
     +             '  DTSMAX ',F8.6,'  WAVE ',F8.6,'  NUMSPG',I4,
     +             '  High resln ',F6.3)
      END IF
C
C---- trap any attempt to refine cell with only a single image
C
      IF (FIRSTIMG.EQ.LASTIMG) THEN
        IF(SOCKLO)THEN
          OUTLINE = ' '
          MESSAGE = ' '
          WRITE(MESSAGE,FMT=6120)
 6120     FORMAT('Must have more than one image in a sector to',
     +               ' do cell refinement')
          WRITE(OUTLINE,FMT=6060)MESSAGE(1:LENSTR(MESSAGE))
          CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(OUTLINE),OUTLINE)
        END IF
        RETURN
      END IF

C
C---- Ensure mosaic spread is not zero
C
      IF (ETA.LT.1.0E-5) THEN
        ETAD = 2.0*ETA/DTOR
        WRITE(IOUT,FMT=6130) ETAD
        IF (ONLINE) WRITE(ITOUT,FMT=6130) ETAD
 6130   FORMAT(1X,'mosaic too small:',F12.8)
        IF(SOCKLO)THEN
          OUTLINE = ' '
          MESSAGE = ' '
          WRITE(MESSAGE,FMT=6132) ETAD
 6132     FORMAT('Mosaic spread is too small (',F7.5,'), please',
     +               ' estimate or enter a value in Images pane')
          WRITE(OUTLINE,FMT=6060)MESSAGE(1:LENSTR(MESSAGE))
          CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(OUTLINE),OUTLINE)
        END IF
        RETURN
      END IF
C
C---- Give a warning message if resolution is low
C
C      IF (DSTMAX.GT.0) HIGHRESLN = WAVE/DSTMAX
      IF (HIGHRESLN.GT.3.5) THEN
        IF(SOCKLO)THEN
          OUTLINE = ' '
          MESSAGE = ' '
          WRITE(MESSAGE,FMT=6140)
 6140     FORMAT('WARNING: Refinement is likely to be unstable ',
     +            'when resolution is less than 3.5A, consider using',
     +            ' cell from autoindexing with multiple images')
          WRITE(OUTLINE,FMT=6070)MESSAGE(1:LENSTR(MESSAGE))
          CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(OUTLINE),OUTLINE)
        END IF
      ELSE IF (HIGHRESLN.GT.3.0) THEN
        IF(SOCKLO)THEN
          OUTLINE = ' '
          MESSAGE = ' '
          WRITE(MESSAGE,FMT=6150)
 6150     FORMAT('WARNING: Cell refinement can be unstable when ',
     +           'resolution is less than 3.0A. Check that std dev',
     +           ' values are less than 0.1A after refinement.')
          WRITE(OUTLINE,FMT=6070)MESSAGE(1:LENSTR(MESSAGE))
          CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(OUTLINE),OUTLINE)
        END IF
      END IF

C     ..
C     .. set up number of segments, default 2 but change according to
C     .. symmetry
C
      JSEG = 2
      SINGLE = .FALSE.
      IF(NUMSPG.LE.2)THEN
        JSEG = 4
      ELSEIF(NUMSPG.LT.16)THEN
        JSEG = 3
      ENDIF
C     ..
C     .. check that a template has been given first
      IF(.NOT.TEMPLATE)THEN
        IERR = -1
        WRITE(IOUT,FMT=4000)
        IF(ONLINE)WRITE(ITOUT,FMT=4000)
        IF(SOCKLO)THEN
          OUTLINE = ' '
          MESSAGE = 'TEMPLATE not set - no images have been read'
          WRITE(OUTLINE,FMT=6060)MESSAGE(1:LENSTR(MESSAGE))
          CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(OUTLINE),OUTLINE)
        ENDIF
        RETURN
      ENDIF
C     ..
C     .. cycle through segments...
      DO 1000 IC = 1,JSEG,1
C
C---- Set NEWGENF FALSE so it does not CALL START IN CONTROL
C     (which opens a generate file and checks raster box)
C
C     .. Generate now so we have a value for NIVB
C     ..
        SNEWGENF = NEWGENF
        NEWGENF = .FALSE.
        GENOPEN = .FALSE.
        FIRSTTIME = .FALSE.
        IFIRSTPACK = 1
        MODECTRL = 1
        CALL CONTROL(FIRSTTIME,IFIRSTPACK,NEWGENF,GENOPEN,
     +       RPTFIRST,CELLSTR,MODECTRL)
        NEWGENF = SNEWGENF
        IF (DEBUG(106)) THEN
          WRITE(IOUT,FMT=6160) ic, nivb,phirng
          if (online) WRITE(ItOUT,FMT=6160) ic,nivb,phirng
 6160   format(1x,'After CONTROL  IC=',I3,'  NIVB', I3,'  phirng',F6.2)
        END IF

        IF(IC.EQ.1)THEN
          IDTMP(IC) = FIRSTIMG
        ELSE
C     ..
C     .. last segment should be 90 from first if possible
C     .. following assumes a constant oscillation angle for all images
C
          IF((LASTIMG-FIRSTIMG+1)*PHIRNG.GE.90.0+(2*NIVB+1*PHIRNG))THEN
            IDTMP(IC) = INT((90.0*(REAL(IC-1)/REAL(JSEG-1)))/
     $           PHIRNG) + FIRSTIMG - 1
C Changed above to add "FIRSTIMG -1" otherwise failed if the first
C image number was not 1 (CBF files have 1000000). AGWL 18/7/19
C
C was for chunking, changed method + FIRSTIMG - (CHUNK - 1)
          ELSE
C     ..
C     .. need to make sure we can do this if only the first or a very 
C     .. few images exist(s)
C     ..
            IDTMP(IC) = LASTIMG - (REAL(JSEG-IC)/REAL(JSEG)) * 
     $           (LASTIMG-FIRSTIMG) - (2*NIVB) + 1
C was for chunking, changed method  - (CHUNK - 1)
            IF(IDTMP(1).EQ.IDTMP(2))SINGLE = .TRUE.
          ENDIF
C     ..
C     .. set up phi range for second segment
C     .. following assumes a constant oscillation angle for all images
          PHIBEG = PHIBEG + ((IDTMP(2) - IDTMP(1)) * PHIRNG)
          PHIEND = PHIBEG + PHIRNG
        ENDIF
        CALL GENERATE(2,IDTMP(IC),.TRUE.,.FALSE.,LIMIT,.TRUE.,
     +       .TRUE.,NFGEN,.FALSE.,NFULLF)
        IF (DEBUG(106)) THEN
          WRITE(IOUT,FMT=6162) ic, nivb,phirng
          if (online) WRITE(ItOUT,FMT=6162) ic,nivb,phirng
 6162   format(1x,'After generate IC=',I3,'  NIVB', I3,'  phirng',F6.2)
        END IF
C
C---- If mosaicity is very small, NIVB calculates as zero so no selection will
C     be made. Give a message
C
        IF (NIVB.EQ.0) THEN
          ETAD = 2.0*ETA/DTOR
          IF(SOCKLO)THEN
            OUTLINE = ' '
            MESSAGE = ' '
            WRITE(MESSAGE,FMT=6170) ETAD
 6170       FORMAT('With current value for mosaicity (',F6.4,
     +             ') there are too few partials to allow ',
     +             'cell refinement. Increase mosaicity.')
            WRITE(OUTLINE,FMT=6060)MESSAGE(1:LENSTR(MESSAGE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(OUTLINE),OUTLINE)
          END IF
          RETURN
        END IF
C     ..
C     .. make ODFILE and check it exists
        IF (DEBUG(106)) THEN
          write(iout,fmt=6163) IC,IDTMP(IC),IDTMP(IC)+NIVB*2-1,ntdig,
     +                       TEMPLSTART,TEMPLEND
          if (online) write(itout,fmt=6163) IC,IDTMP(IC), 
     +               IDTMP(IC)+NIVB*2-1,ntdig,TEMPLSTART,TEMPLEND
 6163   format(1x,'IC=',i3,'  idtmp(ic)=',I8,' and',i8,
     +         ' ntdig=',i4,/,1X,'TEMPLSTART=',A,/,1X,'TEMPLEND=',A)
        END IF

        DO 980 II = IDTMP(IC),IDTMP(IC)+NIVB*2-1
          CALL TEMPLMAKE(TEMPLSTART,TEMPLEND,NTDIG,II,ODFILE,
     +         IERR)
C
          IF (FDISK(1).EQ.' ') THEN
C
C---- files must be in current working directory
C
            LOGDSK = .FALSE.
          ELSE
            LOGDSK = .TRUE.
            LNDSK = LENSTR(FDISK(NNDIR))
          END IF

          ODFILE = FDISK(NNDIR)(1:LNDSK)//ODFILE(1:LENSTR(ODFILE))

          CALL BADTOGOOD(XODFILE,ODFILE,LENSTR(ODFILE))
          INQUIRE (FILE=ODFILE,EXIST=EFILE,NAME=ODFILE)
          IF(.NOT.EFILE)THEN
            IERR = -1
            WRITE(IOUT,FMT=4020)ODFILE(1:LENSTR(ODFILE))
            IF(ONLINE)WRITE(ITOUT,FMT=4020)ODFILE(1:LENSTR(ODFILE))
            IF(SOCKLO)THEN
              OUTLINE = ' '
              MESSAGE = ' '
              WRITE(MESSAGE,FMT=6080)ODFILE(1:LENSTR(ODFILE))
              WRITE(OUTLINE,FMT=6060)MESSAGE(1:LENSTR(MESSAGE))
              CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(OUTLINE),OUTLINE)
            ENDIF
            RETURN
          ENDIF
 980    ENDDO
C     ..
C     .. check phi range > 0, get values from header if not
        IF(PHIRNG.LT.1E-3)THEN
          MODEOP = 2
          LIPROCESS = 0
          CALL OPENODS(IDENT,IDTMP(IC),NFIRSTF,ODEXT,FDISK,MODEOP,
     +         PACK,ODFILE,SEPCHAR,FORCEREAD,IPACK,
     +         TEMPLSTART,TEMPLEND,LIPROCESS,IERR)
          PHIBEG = HPHIS
          PHIEND = HPHIE
C     ..
C     .. if PHI isn't in the header, return now
          IF(PHIEND-PHIBEG.LT.1E-3)THEN
            IF(SOCKLO)THEN
              OUTLINE = ' '
              MESSAGE = ' '
              MESSAGE = 'Phi values are not in the image header'
              WRITE(OUTLINE,FMT=6060)MESSAGE(1:LENSTR(MESSAGE))
              CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(OUTLINE),OUTLINE)
            ENDIF
            RETURN
          ENDIF
        ENDIF
        PHIRNG = PHIEND - PHIBEG
C     ..
C     .. now we can  do the real work
C
C---- USE 2*NIVB images to ensure accurate cell dimensions from post
C     refinement, as NIVB is no longer doubled in GENERATE . AGWL 14/7/07.
C
C        JIMAG(IC) = MAX(2,NIVB)
        JIMAG(IC) = 2*NIVB

C
C---- If this is the first segment, check that the final image of this segment
C     actually exists
C
        IF ((IC.EQ.1).AND.(FIRSTIMG+JIMAG(IC)-1.GT.
     $       LASTIMG))THEN
C was for chunking, changed method  - (CHUNK - 1)))) THEN
          IF(SOCKLO)THEN
            OUTLINE = ' '
            MESSAGE = ' '
            WRITE(MESSAGE,FMT=6180)
 6180       FORMAT('Too few images available to perform reliable',
     +               ' cell refinement. Enter images manually to',
     +               ' attempt refinement')
            WRITE(OUTLINE,FMT=6060)MESSAGE(1:LENSTR(MESSAGE))
            CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(OUTLINE),OUTLINE)
          END IF
          RETURN
        END IF

 1000 ENDDO
      IF(SINGLE)JSEG = 1
      WRITE(IOUT,FMT=4040) JSEG
      IF(ONLINE)WRITE(ITOUT,FMT=4040) JSEG
      DO 1020 IC=1,JSEG,1
        WRITE(IOUT,FMT=4060)IC,IDTMP(IC),JIMAG(IC)
        IF(ONLINE)WRITE(ITOUT,FMT=4060)IC,IDTMP(IC),JIMAG(IC)
 1020 ENDDO
C     ..
C     .. various outputs 
      IF(SOCKLO)THEN
C        WRITE(*,FMT=6000)JSEG
C
C---- Generate the actual template by sending an ID of -1
C
         IDFLAG = -1
         CALL TEMPLMAKE(TEMPLSTART,TEMPLEND,NTDIG,IDFLAG,
     +       REALTEMPL,IERR)

        OUTLINE = ' '
        WRITE(OUTLINE,FMT=6000)JSEG,REALTEMPL(1:LENSTR(REALTEMPL))
        CALL WRITE_SOCKET_SECTION(SERVERFD,LENSTR(OUTLINE),OUTLINE)
        STRSTA = 1
        OUTLINE = ' '
        DO 1040 IC = 1,JSEG,1
C
C---- need a final check to make sure the images actually exist
C
C          WRITE(*,FMT=6100)IDTMP(IC),JIMAG(IC)
          WRITE(NUVAL,FMT=6100)IDTMP(IC),JIMAG(IC)
          STREND = STRSTA + LENSTR(NUVAL)
          OUTLINE(STRSTA:STREND) = NUVAL
          STRSTA = STREND
 1040   ENDDO
        CALL WRITE_SOCKET_SECTION(SERVERFD,LENSTR(OUTLINE),OUTLINE)
C        WRITE(*,FMT=6040)
        OUTLINE = ' '
        WRITE(OUTLINE,FMT=6040)
        CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(OUTLINE),OUTLINE)
      ENDIF
C     ..
C     .. format statements
 4000 FORMAT(' TEMPLATE hasn''t been set! Use of TEMPLATE is ',
     $     'a prerequisite of the SEGMENT command')
 4020 FORMAT(' Image ',A,' doesn''t exist')
 4040 FORMAT(' Automated segment selection: ',I1,' segments')
 4060 FORMAT(' Segment ',I1,' First image: ',I7,' Number of images: ',
     $     I2)
 5000 FORMAT(' TEMPLSTART = ',A,/,' TEMPLEND = ',A,/,
     $     ' IC = ',I4,/,' ODFILE = ',A,/,'Phi values: ',2F8.2)
 6000 FORMAT('<?xml version="1.0"?>',
     $     '<!DOCTYPE segment_setup_response>',
     $     '<segment_setup_response>',
     $     '<status>',
     $     '<code>ok</code>',
     $     '</status>',
     $     '<total_segments>',I3,'</total_segments>',
     $     '<template>',A,'</template>')
 6040 FORMAT('</segment_setup_response>')
 6060 FORMAT('<?xml version="1.0"?>',
     $     '<!DOCTYPE segment_setup_response>',
     $     '<segment_setup_response>',
     $     '<status>',
     $     '<code>error</code>',
     $     '<message>',A,'</message>',
     $     '</status>',
     $     '</segment_setup_response>')
 6070 FORMAT('<?xml version="1.0"?>',
     $     '<!DOCTYPE segment_setup_response>',
     $     '<segment_setup_response>',
     $     '<status>',
     $     '<code>warning</code>',
     $     '<message>',A,'</message>',
     $     '</status>',
     $     '</segment_setup_response>')
 6080 FORMAT('Image ',A,' doesn''t exist')
 6100 FORMAT('<segment><start>',I7,'</start><range>',I3,
     $     '</range></segment>')
      RETURN
      END
      
C== SETAX ==
C $Id: setax.f,v 1.2 2006/08/29 14:58:22 harry Exp $
C
C
C
C
      SUBROUTINE SETAX(BBEG,BEND,IAX)
      IMPLICIT NONE
C     ================================
C
C
C
C---- Determine order of axes for subroutine REEKE
C     Routine returns IAX where
C
C  IAX(3) r.l. axis most nearly parallel/antiparallel to Z
C        (along rotation axis away from spindle)
C
C  IAX(1) remaining r.l. axis most nearly parallel/antiparallel
C         to X (along xray beam)
C
C  IAX(2) remaining r.l. axis
C
C
C
C
C     .. Array Arguments ..
      REAL BBEG(3,3),BEND(3,3)
      INTEGER IAX(3)
C     ..
C     .. Local Scalars ..
      REAL C,CMAX,D
      INTEGER I
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC ABS,SQRT
C     ..
C
C
C---- Determine IAX(3) ie recip. lattice axis closest (parallel or
C     anti-parallel) to the rotation (z) axis.
C     (We actually determine the cosine of the angle)
C
      CMAX = 0.0
C
C
      DO 10 I = 1,3
        D = SQRT(BBEG(1,I)**2+BBEG(2,I)**2+BBEG(3,I)**2)
        C = ABS((BBEG(3,I)+BEND(3,I))/ (2.0*D))
C
C
        IF (C.GT.CMAX) THEN
          CMAX = C
          IAX(3) = I
        END IF
C
C
   10 CONTINUE
C
C---- Now determine IAX(1) ie recip. lattice axis closest (parallel or
C     anti-parallel) to the X axis or the X-ray beam
C
      CMAX = 0.0
C
C
      DO 20 I = 1,3
C
C
        IF (I.NE.IAX(3)) THEN
          D = SQRT(BBEG(1,I)**2+BBEG(2,I)**2+BBEG(3,I)**2)
          C = ABS((BBEG(1,I)+BEND(1,I))/ (2.0*D))
C
C
          IF (C.GT.CMAX) THEN
            CMAX = C
            IAX(1) = I
          END IF
        END IF
C
C
   20 CONTINUE
C
C---- Set IAX(2) to the remaining axis
C
      DO 30 I = 1,3
C
C
        IF (IAX(1).NE.I) THEN
          IF (IAX(3).NE.I) IAX(2) = I
        END IF
C
C
   30 CONTINUE
C
C
      END
C $Id: setdd.f,v 1.7 2007/12/18 14:55:49 harry Exp $
C
      SUBROUTINE SETDD(DISTANCE, TWOTHETA, DD, DDINV, DN,NUREEK)
C     ====================================================
C
c set matrices etc for prediction (outside madnes); only used for resolution 
C circles.
c
c
c  input:
c     distance    detector distance (mm)
c     twotheta       detector angle (degrees)
c
c  output:
c     dd          detector matrix
c     ddinv       inverse detector matrix
c     dn          detector normal
C
C     CAMCON are the camera constants from the Madnes code (see DDDN.F
C     for explanation) - now in common block REEK
c
      IMPLICIT NONE
C
C     ..
C     .. Scalar Arguments ..
      REAL DISTANCE, TWOTHETA
      LOGICAL NUREEK
C     ..
C     .. Array Arguments ..
      REAL DDINV(3,3), DN(3)
C     ..
C     .. Local Arrays ..
      REAL DD(3,3),LCAMCON(8)
C      INTEGER R(3), W(3)
C     ..
C     .. Local Scalars ..
      REAL DET
C     ..
C     .. External Subroutines ..
      EXTERNAL DDDN,DDMAT,MOVEIT,MINV
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f
C
      LCAMCON(1) = 0.0
      LCAMCON(2) = 0.0
      LCAMCON(3) = DISTANCE
      LCAMCON(4) = 0.0
      LCAMCON(5) = 0.0
      LCAMCON(6) = 0.0
      LCAMCON(7) = 0.0
      LCAMCON(8) = 0.0
      IF(NUREEK)THEN
        CALL DDDN(LCAMCON,DD,DN)
      ELSE
        CALL DDMAT(DISTANCE, TWOTHETA, DD, DN)
      ENDIF
C
C inverse
         CALL MINV33(DDINV,DD,DET)
C      CALL MOVEIT(DD,DDINV,9)
C      CALL MINV(DDINV, 3, DET, R, W)
C
      RETURN
      END
