C---- BGLOCAL(I,J,1) ...   Mean background for box I,J
C---- BGLOCAL(I,J,2) ...   Poissonian sigma (uses GAIN) for box I,J
C---- BGLOCAL(I,J,3) ...   Rms variation in counts for box I,J
C---- BGLOCAL(I,J,4) ...   Average +ve difference between mean background
C                          of box I,J and its neighbours, expressed as
C                          a multiple of the rms variation of box I,J
C                          Used to identify boxes in shadow.
C     IWTBG     Array dimension (MAXBGBOX,MAXBGBOX) holding weight for
C               each local background area.
C     EXCLDICE  True if spots in resolution shells of ice rings are to be 
C               excluded
C     AUTORESLN Set resolution limit to 4A if spots between 4-6 are much
C               weaker than those between 6A and infinity.
C     AUTORES1  The lower resolution bin boundary (default 6A) for AUTORESLN
C     AUTORES2  The higher resolution bin boundary (default 4A) for AUTORESLN
C     AUTOFAC1  The intensity factor (default 0.2) for AUTORESLN
C     AUTOFAC2  The reflection number factor (default 0.25) for AUTORESLN
C     AUTORING  Automatically exclude radial bins that have too many spots
C               eg due to ice rings.
C     RINGFACT  Rings with more than RINGFACT*(average number of spots) are
C               rejected as potential ice/powder rings. Default 4.0.
C     NUMICE    Number of spots rejected as potentailly being ice spots
C     NTOOFEWPIX Number of spots rejected as having too few pixels.
C     NIMGSUMSPOT Number of images to sum when searching for spots for indexing.
C     NRESOLU   Number of spots rejected by automatic resolution reduction to 4.5
C
C
C     .. Scalars in Common Block /SPOTS2/ and /SPOTS2C/ ..
      REAL CUTPIXMAX,CUTPIXMIN,CUTWXMAX,CUTWXMIN,CUTWYMAX,CUTWYMIN,
     +     XSPLIT,YSPLIT,YOFFSET,XOFFSET,THRESH,RMINSP,RMAXSP,
     +     RMINSRCH,RMAXSRCH,SCALSRCH,SPXMIN,SPYMIN,THRESHMIN,
     +     THRESHMAX,RMSFAC,ANISOMAX,AUTORES1,AUTORES2,AUTOFAC1,
     +     AUTOFAC2,RINGFACT,RES2SD
      INTEGER NBINR,NBINT,IBINLIM,NPIXMIN,NPIXMAX,IIMAG,NIMAG,
     +     MEDWXSPOT,MEDWYSPOT,NSEARCH,ITHSET,ISAFE,IRSTRT,
     +     NSPTD,MAXPKS,MAXYEXT,NXBOX,NYBOX,IPIXMIN,IRMSFAC,
     +     NUMICE,NTOOFEWPIX,NIMGSUMSPOT,NRESOLU
      LOGICAL RADX,RADY,NEWSPT,DOFIND,LOCBG,EXCLDICE,
     +     AUTORESLN,AUTORING,AUTOTHRESH,FOUND(20)
C     ..
C     .. Arrays in common /SPOTS2/  and /SPOTS2C/ ....
      INTEGER NPIX(MXSPOT),IWXSPOT(MXSPOT),IWYSPOT(MXSPOT),
     $     IORDER(MXSPOT),INSPOT(MXSPOT),NOIMG(MAXIMG),ISDSPOT(MXSPOT),
     $     NSPK(MXSPOT), IWTBG(MAXBGBOX,MAXBGBOX), AVBG(IXWDTH)
      REAL BGOD(IXWDTH),PHI(MAXIMG),PHISAVE(MAXIMG),
     $     XSPOT(MXSPOT),YSPOT(MXSPOT),RESOLU(MXSPOT),
     $     RSPOT(MXSPOT),PHISTIM(MAXIMG),PHIRNGA(MAXIMG),
     +     BGODA2(21,21,3)
C     ..
C     .. Common Block /SPOTS2/  and /SPOTS2C/ ....
      COMMON /SPOTS2/
C     .. real scalars
     $     CUTPIXMAX,CUTPIXMIN,CUTWXMAX,CUTWXMIN,CUTWYMAX,CUTWYMIN,
     +     XSPLIT,YSPLIT,YOFFSET,XOFFSET,THRESH,RMINSP,RMAXSP,
     +     RMINSRCH,RMAXSRCH,SCALSRCH,SPXMIN,SPYMIN,THRESHMIN,
     +     THRESHMAX,RMSFAC,ANISOMAX,AUTORES1,AUTORES2,AUTOFAC1,
     +     AUTOFAC2,RINGFACT,RES2SD,
C     .. integer scalars
     $     NBINR,NBINT,IBINLIM,NPIXMIN,NPIXMAX,IIMAG,NIMAG,
     +     MEDWXSPOT,MEDWYSPOT,NSEARCH,ITHSET,ISAFE,IRSTRT,
     +     NSPTD,MAXPKS,MAXYEXT,
     +     NXBOX,NYBOX,
     +     IPIXMIN,IRMSFAC,NUMICE,NTOOFEWPIX,NIMGSUMSPOT,NRESOLU,
C     -- logicals 
     $     RADX,RADY,NEWSPT,DOFIND,LOCBG,EXCLDICE,AUTORESLN,
     $     AUTORING,AUTOTHRESH,FOUND,
C     .. integer arrays
     $     NPIX,IWXSPOT,IWYSPOT,IORDER,INSPOT,NOIMG,ISDSPOT,NSPK,
     +        IWTBG,AVBG,
C     .. real arrays
     $     BGOD,PHI,XSPOT,YSPOT,RESOLU,RSPOT,PHISTIM,PHIRNGA,
     $     BGODA2,PHISAVE

      REAL BGLOCAL(MAXBGBOX,MAXBGBOX,4)
       
      COMMON /SPOTS3/BGLOCAL

      CHARACTER IMGTEMPL*100,IMGFN*100,IMGNUM*9
      COMMON /SPOTS2C/ IMGTEMPL,IMGFN,IMGNUM
C&&*&& end_include  ../inc/spots2.f
C&&*&& include  ../inc/test.f
C--- awk generated include file  test.h
C---- START of include file test.h
C
C    Detector limits, used in SPTEST. All are in 10 micron units.
C    In the virtual detector frame, Y is parallel to the rotation axis
C    and X is orthogonal to the rotation axis.
C
C    In the scanner frame, X is parallel to the slow direction in the
C    image, Y is the fast direction.
C
C    RSCANSQ      Radius**2 of the scanned region of the plate (Mar scanners)
C                 This is different to the other limits because it is
C                 applied to the actual scanner coordinates rather than
C                 the virtual detector coordinates. All other limits apply
C                 to virtual detector coordinates.
C    XSCAN        Maximum X coordinate in detector frame (10 micron units)
C    YSCAN        Maximum Y coordinate in detector frame (10 micron units)
C    RSCANX,RSCANY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RSCAN defining the
C                 useable area of the detector.
C    XSCAN,YSCAN,RSCAN are maximum coords relative to the physical centre of 
C                 the detector (ie the mid-point of the image), NOT wrt the 
C                 direct beam position.
C    RMINX,RMINY If non-zero, these are the coordinates (10 micron units)
C                 for the centre of the circle radius RMIN defining the
C                 useable area of the detector.
C    RMXSQD       Maximum radius (squared) in virtual detector frame
C    RMNSQD       Minimum radius (squared) in virtual detector frame
C    XMIN         Minimum X coordinate in  detector frame
C    XMAX         Maximum X coordinate in  detector frame
C    YMIN         Minimum Y coordinate in  detector frame
C    YMAX         Maximum Y coordinate in  detector frame
C    NXYEXC       Number of excluded areas set by user (rectangles, arcs)
C    NXYEXCDET    Number of detector specific excluded rectangles (Pilatus)
C    NOTILES      If set true, ignore all tile boundaries in Pilatus images
C    ICEWIDTH     Width of the exclusion shells for ice, this fraction
C                 of the actual resolution is used as the half-width
C    ICEWIDTHPREF Width of the exclusion shells for ice for post
C                 refinement, this fraction
C                 of the actual resolution is used as the half-width
C    PREFEXICE    Logical, true if reflections in ice rings to be
C                 excluded from post-refinement
C
C     .. Scalars in common block /TEST/ ..
      REAL RMXSQD,RMNSQD,XMIN,XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,
     +     RMINX,RMINY,XSCAN,YSCAN,CIRRAD,ICEWIDTH,ICEWIDTHPREF
      INTEGER NEXCL,NXYEXC,NXYEXCDET,IQUADNO,IARCNO,NEXCL2
      LOGICAL PREFEXICE,NOTILES
C
C     .. Arrays in common block /TEST/
      REAL RESEXL,RESEXH,XYEXC,CNREXC,EXCARC,CIRCEN,PHILIM,RES2EXL,
     +     RES2EXH,RES3EXL,RES3EXH,XYEXCSP
      INTEGER IEXCARC
      LOGICAL LEXCARC
C     ..
C     .. Common Block /TEST/ ..
      COMMON /TEST/RESEXL(MAXEXCL),RESEXH(MAXEXCL),XYEXC(4,MAXEXCL),
     +     CNREXC(8,MAXEXCL),
     $     EXCARC(5,MAXEXCL),CIRCEN(2),PHILIM(2),RMXSQD,RMNSQD,XMIN,
     +     XMAX,YMIN,YMAX,RSCANSQ,RSCANX,RSCANY,RMINX,RMINY,XSCAN,
     $     YSCAN,CIRRAD,IEXCARC(6,MAXEXCL),NEXCL,NXYEXC,IQUADNO,
     $     IARCNO,LEXCARC(MAXEXCL),NXYEXCDET,RES2EXL(MAXEXCL),
     $     RES2EXH(MAXEXCL),NEXCL2,ICEWIDTH,ICEWIDTHPREF,PREFEXICE,
     +     RES3EXL(MAXEXCL),RES3EXH(MAXEXCL),NOTILES,XYEXCSP(4,MAXEXCL)
C     ..
C
C

C&&*&& end_include  ../inc/test.f
C&&*&& include  ../inc/trigparam.f
C 
C $Id: trigparam.f,v 1.3 2008/07/31 11:46:02 harry Exp $
C
C
C     Trigonometric parameters - set here to highly precise values, don't 
C     calculate in code; values from Clemens Vonrhein
C
C     DTOR.. convert degrees to radians
C     RTOD.. convert radians to degrees
C     PI..   value of PI
      REAL PI
      PARAMETER   ( PI = 3.1415926536 )
      REAL          TWOPI
      PARAMETER   ( TWOPI = 6.2831853072 )
      REAL RTOD
      PARAMETER   ( RTOD = 57.2957795131 )
      REAL          DTOR
      PARAMETER   ( DTOR = 0.0174532925 )
C DOUBLE PRECISION...
      DOUBLE PRECISION PI_DOUBLE
      PARAMETER ( PI_DOUBLE = 3.1415926535897932384626433832795029D0 )
      DOUBLE PRECISION TWOPI_DOUBLE
      PARAMETER ( TWOPI_DOUBLE = 
     $     6.2831853071795864769252867665590058D0 )
      DOUBLE PRECISION RTOD_DOUBLE
      PARAMETER ( RTOD_DOUBLE = 57.2957795130823208768D0 )
      DOUBLE PRECISION DTOR_DOUBLE
      PARAMETER ( DTOR_DOUBLE = 0.01745329251994329576D0 )
c

c
C&&*&& end_include  ../inc/trigparam.f

      INTEGER NPARM
      PARAMETER (NPARM=200)
C     ..
C     .. array arguments
C     ..
C     .. scalar arguments
      INTEGER MODE,INSIZE,IFILESIZE,IERR
C     ..
C     .. local scalars
      CHARACTER CALLEDFROM*80,BEAMLINE*15,SERIOUSCOLOUR*6,STRING1*200,
     +          LONGLINE*1024
      INTEGER STARTX,STEPX,WIDTHX,STARTY,STEPY,WIDTHY,IOFFSET

      INTEGER II,JJ
      LOGICAL EFILE,DONE
C     ..
C     .. include files
C&&*&& include  ../inc/lmb.f
C
C $Id: lmb.f,v 1.17 2021/03/30 09:16:05 andrew Exp $
C
C--- awk generated include file  lmb.h
C---- START of include file lmb.h
C ODSCAL is to scale image numbers into the range 0-255 for plotting
C average profiles.
C  GAIN should be equal to the overall gain (image counts per X-ray photon)
C of the system, and is used to evaluate standard deviations based on
C counting statistics assuming independent pixels (ie point spread function
C less than pixel size).
C INVERTX true if image is inverted in the slow (X) direction when read in.
C ISCAL is to scale final integrated intensities and sigmas
C IDIVIDE is the adc offset
C ICONST is a constant to be added to all pixels (normally zero) to
C        allow processing of images with zero pixel values in the scanned
C        area.
C IMGP is true if working with image plate data
C SPIRAL is true for scanners with a spiral readout (Mar, DIP2000)
C ORTHOG is true for scanners with orthogonal scan (FUJI, RAXIS, MD)
C NULLPIX is the value of pixels within the image but not in the active
C area of the detector
C TILED is true if there are inactive areas of the detector within the
C       inscribing circle or square.
C
C NTILEX Number of tiles in X direction
C NTILEY Number of tiles in Y direction
C TILEX  X Coordinates of the midpoints of the null areas between tiles
C TILEY  Y Coordinates of the midpoints of the null areas between tiles
C TILEWX Width of the null areas between tiles in X
C TILEWY Width of the null areas between tiles in Y


C MACHINE and MODEL denote the type of detector.
C DECTRIS_TYPE can be PILATUS, EIGER1 or EIGER2. It is used when setting up
C the positions of the gaps between the tiles.
C
C MACHINE is used in the following subroutines:
C GETBLK, GETHDR, INTPXL, INTPXL2, MXDSPL, OPENODS, PROCESS, PUTPXL
C Currently coded types are:
C
C         MACHINE        MODEL               COMMENTS
C         =======        =====               ========
C         MAR            180, 300, 345
C         RAXI(S)        RAXISII, RAXISIV
C         MD
C         FUJI
C         CCD1           CCD1                Princetown CCD at CHESS,Tiff format
C         CCD2           CCD ?               ESRF CCD detector
C         ADSC           QUAD1               ADSC 2x2 CCD detector
C
C TRUSTED whether or not the image header information can be trusted for 
C         automatic processing
C MICROED indicates whether or not this is electron diffraction data,
C        base on the wavelength being less than 0.05A
C
C
C     .. Scalars in Common Block /LMB/ ..
        REAL ODSCAL,GAIN,LOGA,LOGB
        INTEGER ISCAL,IDIVIDE,ICONST,NULLPIX,NTILEX,NTILEY,
     $       RAXISCOMP,IIDIVIDE,COMPRESSION,GAPVAL,IINVERTX
        LOGICAL IMGP,INVERTX,SPIRAL,ORTHOG,CIRCULAR,TILED,SETADC,
     $       NEWRAXIS,BRUKNEW,TRUSTED,MINICBF,HDF5FILE,GAPMASK,
     $       WRONGGAPVALUE,MICROED
        CHARACTER MACHINE*4,MODEL*8,LDETECTOR*20,DECTRIS_TYPE*10,
     +       CMACHINE*40

C     ..
C     .. Arrays in common /LMB/
        INTEGER TILEX,TILEY,TILEWX,TILEWY
C
C     .. Common Block /LMB/ ..
        COMMON /LMB/ ODSCAL,GAIN,LOGA,LOGB,ISCAL,IDIVIDE,ICONST,
     $       NULLPIX,NTILEX,NTILEY,RAXISCOMP,IIDIVIDE,COMPRESSION,
     $       GAPVAL,IINVERTX,TILEX(20),TILEY(20),TILEWX(20),TILEWY(20),
     $       IMGP,INVERTX,SPIRAL,ORTHOG,CIRCULAR,
     $       TILED,SETADC,NEWRAXIS,BRUKNEW,TRUSTED,MINICBF,HDF5FILE,
     $       GAPMASK,WRONGGAPVALUE,MICROED
        COMMON /LMBC/ MACHINE,MODEL,LDETECTOR,DECTRIS_TYPE,CMACHINE

C&&*&& end_include  ../inc/lmb.f
      DATA DONE/.FALSE./
      EXTERNAL LENSTR
      INTEGER LENSTR
      CALLEDFROM = 'SETDETECT'
      ISCAN = 1
      IERR = 0
C
C---- Number of detector specific excluded rectangles
C     Setting this zero here creates problems, so initialise as zero
C     in MOSDATA instead. AGWL 30/7/15
CAL      NXYEXCDET = 0
C     
C---- Now set up defaults for this type of detector
C     
      IF (MACHINE.EQ.'RAXI') THEN
        SPIRAL = .FALSE.
        CIRCULAR = .FALSE.
        ORTHOG = .TRUE.
        RMINIP = 300
C     ..
C     .. NEWRAXIS value set in gethdr.f
        IF(.NOT.NEWRAXIS)INVERTX = .FALSE.
        TRUSTED = .TRUE.
        IF (MODEL.EQ.'RAXIS ') THEN
          USEHDR = .FALSE.
          TRUSTED = .FALSE.
          IF (IPIX.EQ.0) RAST = 0.105
          HRAST = RAST
          IF (INSIZE.EQ.0) THEN
            NREC = 1900
            IYLEN = 1900
          END IF
C
C---- Set parameters for 200mu scan
C
          IF (IFILESIZE.LE.2371496) THEN
            IF (IPIX.EQ.0) RAST = 0.210
            HRAST = RAST
            IF (INSIZE.EQ.0) THEN
              NREC = 950
              IYLEN = 950
            END IF
          END IF
            
        ELSE IF (MODEL.EQ.'RAXISIV') THEN
          USEHDR = .TRUE.
          TRUSTED = .TRUE.
          IF (INSIZE.EQ.0) THEN
            NREC = 3000
            IYLEN = 3000
          END IF
          IF (IPIX.EQ.0) RAST = 0.1
        ELSE IF (MODEL.EQ.'RAXISHTC') THEN
          USEHDR = .TRUE.
          IF (INSIZE.EQ.0) THEN
            NREC = 3000
            IYLEN = 3000
          END IF
          IF (IPIX.EQ.0) RAST = 0.1
        ELSE IF (MODEL.EQ.'RAXISV') THEN
          USEHDR = .TRUE.
          IF (INSIZE.EQ.0) THEN
            NREC = 4000
            IYLEN = 4000
          END IF
          IF (IPIX.EQ.0) RAST = 0.1
        END IF  
        IF(MODEL.EQ.'RAXIS ')THEN
          IF (ICUT.EQ.0) CUTOFF = 250000
          IF (IPRCUT.EQ.0) PRCUTOFF = 128000
        ELSE
          IF (ICUT.EQ.0) CUTOFF = 1000000
          IF (IPRCUT.EQ.0) PRCUTOFF = 250000
        ENDIF
      END IF  
C     
C---- ADSC
C     
      IF (MACHINE.EQ.'ADSC') THEN
C        MODEL = 'QUAD'
        INVERTX = .TRUE.
        SPIRAL = .FALSE.
        CIRCULAR = .FALSE.
        ORTHOG = .TRUE.
        TILED = .TRUE.
        ISCAN = 1
        OMEGAFD = 0.0
        OMEGAF = OMEGAFD * DTOR
        IF(.NOT.IINULL)NULLPIX = 0
        IF(IIDIVIDE.EQ.0)IDIVIDE = 15
        RMINIP = 300
        IF (XSCAN.EQ.0) XSCAN = 9400
        IF (YSCAN.EQ.0) YSCAN = 9400
        XMAXIP = 9400
        YMAXIP = 9400
        RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
        IF (ILIMIT.EQ.0) THEN 
          XLIMIT = 0.01*(XMAXIP/2)
          LIMIT = NINT(100*XLIMIT)
        END IF
        IF (ICUT.EQ.0) CUTOFF = 65500
        IF (IPRCUT.EQ.0) PRCUTOFF = 65500
        IF (IGAIN.EQ.0) THEN
          IGAIN = 2
C
C---- change default gain to 0.33, found on many detectors
C     AGWL 24/6/13
C
CAL          GAIN = 0.25
          GAIN = 0.33
        ENDIF
        IF(MODEL.EQ.'Q315'.OR.MODEL.EQ.'ADSCQ315')THEN 
          NTILEX = 3
          NTILEY = 3
        ELSE
          NTILEX = 2
          NTILEY = 2
        ENDIF
        TILEX(1) = 1153
        TILEY(1) = 1153
        TILEWX(1) = 5
        TILEWY(1) = 5
      END IF
C     
C---- ADSC
C     
      IF (MACHINE.EQ.'APAD') THEN
        INVERTX = .TRUE.
        SPIRAL = .FALSE.
        CIRCULAR = .FALSE.
        ORTHOG = .TRUE.
C     ..
C     .. gaps between modules vary by ±1
        TILED = .FALSE.
        ISCAN = 1
        OMEGAFD = 0.0
        OMEGAF = OMEGAFD * DTOR
        IF(.NOT.IINULL)NULLPIX = 0
        IF(IIDIVIDE.EQ.0)IDIVIDE = 15
        RMINIP = 300
        IF (IGAIN.EQ.0) THEN
          IGAIN = 2
          GAIN = 0.58
        ENDIF
      END IF
C     
C---- MAR CCD
C     
      IF(MACHINE.EQ.'MARC')THEN
        TRUSTED = .TRUE.
        INVERTX = .TRUE.
        SPIRAL = .FALSE.
        CIRCULAR = .TRUE.
        ORTHOG = .FALSE.
        RMINIP = 300
        ISCAN = 1
        OMEGAFD = 0.0
        OMEGAF = OMEGAFD * DTOR
        IF(.NOT.IINULL)NULLPIX = 0
        IF(IIDIVIDE.EQ.0)IDIVIDE = 0
        IF (ILIMIT.EQ.0) THEN
          XLIMIT = 0.01*(XMAXIP/2)
          LIMIT = NINT(100*XLIMIT)
        END IF
        IF (ICUT.EQ.0) CUTOFF = 65500
        IF (IPRCUT.EQ.0) PRCUTOFF = 65500
        IF (IGAIN.EQ.0) THEN
          IGAIN = 2
          GAIN = 0.3
        ENDIF
        IF(NHBYTE.EQ.0)NHBYTE = 4096
      ENDIF
C     
C---- Jupiter CCD - maybe okay for Saturn & Mercury too? Should rely on
C     active mask to determine edges of tiles.
C     
      IF((MACHINE.EQ.'JUPI').OR.(MACHINE.EQ.'SATU').OR.
     $     (MACHINE.EQ.'MERC').OR.(MACHINE.EQ.'A200').OR.
     $     (MACHINE.EQ.'RIPI').OR.(MACHINE.EQ.'RIEI'))THEN
        SPIRAL = .FALSE.
        CIRCULAR = .FALSE.
        ORTHOG = .TRUE.
        TILED = .FALSE.
        ISCAN = 1
        IF(.NOT.IINULL)NULLPIX = 0
        IF(IIDIVIDE.EQ.0)IDIVIDE = 0
        RMINIP = 300
        IF (ILIMIT.EQ.0) THEN
          XLIMIT = 0.01*(XMAXIP/2)
          LIMIT = NINT(100*XLIMIT)
        END IF
        IF(MACHINE.EQ.'JUPI')THEN
          IF (IGAIN.EQ.0) THEN
            IGAIN = 2
            GAIN = 0.5
          ENDIF
        ELSEIF(MACHINE.EQ.'SATU')THEN
          IF (IGAIN.EQ.0) THEN
            IGAIN = 2
            GAIN = 2.5
          ENDIF
C     
C---- mercury value not known - set to same as SATURN
C     
        ELSEIF(MACHINE.EQ.'MERC')THEN
          IF (IGAIN.EQ.0) THEN
            IGAIN = 2
            GAIN = 2.5
          ENDIF
C     
C---- A200 value - same as Jupiter?
C     
        ELSEIF(MACHINE.EQ.'A200')THEN
          IF (IGAIN.EQ.0) THEN
            IGAIN = 2
            GAIN = 0.5
          ENDIF
          RMINIP = 200
        ELSEIF(MACHINE.EQ.'RIPI')THEN
          TILED = .TRUE.
          IF (IGAIN.EQ.0) THEN
            IGAIN = 2
            GAIN = 0.8
          ENDIF
        ELSEIF(MACHINE.EQ.'RIEI')THEN
          TILED = .TRUE.
          IF (IGAIN.EQ.0) THEN
            IGAIN = 2
            GAIN = 0.8
          ENDIF
        ENDIF
      ENDIF
C     
C---- DIP2000 series
C     
      IF(MACHINE.EQ.'DIP2')THEN
        USEHDR = .FALSE.
        USETAIL = .TRUE.
        SPIRAL = .TRUE.
        CIRCULAR = .TRUE.
        ORTHOG = .FALSE.
        INVERTX = .TRUE.
        NHEAD = 0
        NTAIL = 1
        SETADC = .FALSE.
        OMEGAFD = 180.0
        OMEGAF = OMEGAFD * DTOR
        RMINIP = 300
        MODEL = '16BIT'
        IF (ICUT.EQ.0) CUTOFF = 500000
        IF (IPRCUT.EQ.0) PRCUTOFF = 62000
        IF (IGAIN.EQ.0) THEN
          IGAIN = 2
          GAIN = 1.0
        ENDIF
C
C---- can't set RAST, NREC, IYLEN until an image has been read & IFILESIZE
C     is known!
C
        IF(IFILESIZE.EQ.12501024)THEN
C     ..
C     .. DIP2000 (20cm original)
          IF (IPIX.EQ.0) RAST = 0.080
          NREC = 2500
          IYLEN = 2500
          NBYTE = 5000
          IF(IIDIVIDE.EQ.0)IDIVIDE = 0
          IF (XSCAN.EQ.0) XSCAN = 10000
          IF (YSCAN.EQ.0) YSCAN = 10000
          XMAXIP = 10000
          YMAXIP = 10000
          RMAXIP = 10000
C     
C---- customize for 30cm DIPS - 2030
C     
        ELSEIF(IFILESIZE.EQ.18001024)THEN
          IF (IPIX.EQ.0) RAST = 0.100
          NREC = 3000
          IYLEN = 3000
          NBYTE = 6000
          IF (XSCAN.EQ.0) XSCAN = 15000
          IF (YSCAN.EQ.0) YSCAN = 15000
          XMAXIP = 15000
          YMAXIP = 15000
          RMAXIP = 15000
C     
C---- customize for 40cm DIPS - 2040
C     
        ELSEIF(IFILESIZE.EQ.32001024)THEN
          IF (IPIX.EQ.0) RAST = 0.100
          NREC = 4000
          IYLEN = 4000
          NBYTE = 8000
          IF (XSCAN.EQ.0) XSCAN = 20000
          IF (YSCAN.EQ.0) YSCAN = 20000
          XMAXIP = 20000
          YMAXIP = 20000
          RMAXIP = 20000
C
C---- called from control before reading an image, we don't know 
C     the size yet
        ELSEIF(IFILESIZE.EQ.0)THEN
          WRITE(IOUT,FMT=6000)
          IF(ONLINE)WRITE(ITOUT,FMT=6000)
 6000     FORMAT(1X,'******* Information *******',/,'the detector ',
     $         'model has not been set since an image hasn''t been ',
     $         'read yet',/)
        ELSE
          WRITE(IOUT,FMT=6010)IFILESIZE
          IF(ONLINE)WRITE(ITOUT,FMT=6010)IFILESIZE
 6010     FORMAT(3(1X,'******* FATAL ERROR *******',/),'This is',
     $         ' an unknown size  for a DIP - stopping now!')
          NSHUTERR = 1
          CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
        ENDIF
      ENDIF
C     
C---- SBC1 Westbrook scanner
C     
      IF(MACHINE.EQ.'SBC1')THEN
        USEHDR = .TRUE.
        INVERTX = .FALSE.
        SPIRAL = .FALSE.
        CIRCULAR = .FALSE.
        ORTHOG = .TRUE.
        TILED = .TRUE.
        ISCAN = 1
        OMEGAFD = 0.0
        OMEGAF = OMEGAFD * DTOR
        IF(.NOT.IINULL)NULLPIX = 0
        IF(IIDIVIDE.EQ.0)IDIVIDE = 0
        RMINIP = 300
        IF (XSCAN.EQ.0) XSCAN = 10500
        IF (YSCAN.EQ.0) YSCAN = 10500
        XMAXIP = 10500
        YMAXIP = 10500
        RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
        IF (ILIMIT.EQ.0) THEN
          XLIMIT = 0.01*(XMAXIP/2)
          LIMIT = NINT(100*XLIMIT)
        END IF
        IF (ICUT.EQ.0) CUTOFF = 64999
        IF (IPRCUT.EQ.0) PRCUTOFF = 64999
        IF (IGAIN.EQ.0) THEN
          IGAIN = 2
          GAIN = 1.6
        ENDIF
      ENDIF
C     
C---- NOIR Westbrook lens coupled CCD
C     
      IF(MACHINE.EQ.'NOIR')THEN
        USEHDR = .TRUE.
        TRUSTED = .TRUE.
        INVERTX = .FALSE.
        SPIRAL = .FALSE.
        CIRCULAR = .FALSE.
        ORTHOG = .TRUE.
        TILED = .TRUE.
        ISCAN = 1
        OMEGAFD = 0.0
        OMEGAF = OMEGAFD * DTOR
        IF(.NOT.IINULL)NULLPIX = 0
        IF(IIDIVIDE.EQ.0)IDIVIDE = 0
        RMINIP = 300
        IF (XSCAN.EQ.0) XSCAN = 7950
        IF (YSCAN.EQ.0) YSCAN = 7950
        XMAXIP = 7950
        YMAXIP = 7950
        RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
        IF (ILIMIT.EQ.0) THEN
          XLIMIT = 0.01*(XMAXIP/2)
          LIMIT = NINT(100*XLIMIT)
        END IF
        IF (ICUT.EQ.0) CUTOFF = 63000
        IF (IPRCUT.EQ.0) PRCUTOFF = 63000
        IF (IGAIN.EQ.0) THEN
          IGAIN = 2
          GAIN = 0.3
        ENDIF
      ENDIF
C     
C---- TAURus Westbrook CMOS detector
C     
      IF(MACHINE.EQ.'TAUR')THEN
        USEHDR = .TRUE.
        TRUSTED = .TRUE.
        INVERTX = .FALSE.
        SPIRAL = .FALSE.
        CIRCULAR = .FALSE.
        ORTHOG = .TRUE.
        TILED = .TRUE.
        ISCAN = 1
        OMEGAFD = 180.0
CHRP 29/10/2015 - need reversephi with iMosflm, so surely this should be 0?
        OMEGAFD = 0.0
        OMEGAF = OMEGAFD * DTOR
        IF(.NOT.IINULL)NULLPIX = 0
        IF(IIDIVIDE.EQ.0)IDIVIDE = 0
        RMINIP = 300
        IF (XSCAN.EQ.0) XSCAN = 14775
        IF (YSCAN.EQ.0) YSCAN = 14115
        XMAXIP = 14775
        YMAXIP = 14115
        RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
        IF (ILIMIT.EQ.0) THEN
          XLIMIT = 0.01*(XMAXIP/2)
          LIMIT = NINT(100*XLIMIT)
        END IF
        IF (ICUT.EQ.0) CUTOFF = 14000
        IF (IPRCUT.EQ.0) PRCUTOFF = 14000
        IF (IGAIN.EQ.0) THEN
          IGAIN = 2
          GAIN = 0.3
        ENDIF
      ENDIF
C     
C---- Oxford native format
C     
      IF(MACHINE.EQ.'OXFO')THEN
        GENGON = .TRUE.
        FOURCIRCLE = .TRUE.
        OMEGAFD = 90.0
C     
C---- lots of the following is only set after reading the image header -
C     oxford images come in different sizes, which are indicated by the
C     header 
C     
        NREC = 512
        IYLEN = 512
        RMINIP = 300
        IF (XSCAN.EQ.0) XSCAN = 3072
        IF (YSCAN.EQ.0) YSCAN = 3072
        XMAXIP = 3072
        YMAXIP = 3072
        RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
        IF (ILIMIT.EQ.0) THEN
          XLIMIT = 0.01*(XMAXIP/2)
          LIMIT = NINT(100*XLIMIT)
          INVERTX = .FALSE.
        END IF
        NUREEK = .TRUE.
        GON_KAPPA_SET = 50.0
        USEHDR = .TRUE.
        USETAIL = .FALSE.
        USEDIST = .FALSE.
        USEWAVE = .TRUE.
        USEPHI = .TRUE.
        NHEAD = 1
        HDRSIZE = .TRUE.
        INVERTX = .TRUE.
        SPIRAL = .FALSE.
        CIRCULAR = .FALSE.
        ORTHOG = .TRUE.
        TILED = .FALSE.
        ISCAN = 1
        OMEGAF = OMEGAFD * DTOR
        IF(.NOT.IINULL)NULLPIX = 0
        IF(IIDIVIDE.EQ.0)IDIVIDE = 0
        IF (ICUT.EQ.0) CUTOFF = 65500
        IF (IPRCUT.EQ.0) PRCUTOFF = 65500
        IF (IGAIN.EQ.0)THEN
          IGAIN = 2
          GAIN = 2.0
        ENDIF
        NTILEX = 1
        NTILEY = 1
      ENDIF
C     
C---- Bruker, only works for Smart 1K images at the moment
C     
      IF(MACHINE.EQ.'BRUK')THEN
c     
c---- these next two lines are only true for the 1K smart...
c     
        NREC = 1024
        IYLEN = 1024
C
C---- this should be determined from the header. The value is given on a
C     "DETTYPE" line as the first number, in pixels per cm.
        IF(IPIX.EQ.0)RAST = 0.08999
        INVERTX = .TRUE.
        SPIRAL = .FALSE.
        CIRCULAR = .FALSE.
        ORTHOG = .TRUE.
        TILED = .FALSE.
        TRUSTED = .TRUE.
        ISCAN = 1
        IF(HOSCAXIS.EQ.'OMEGA')THEN
          OMEGAFD = 270.0
        ELSE
          OMEGAFD = 90.0
        ENDIF
        OMEGAF = OMEGAFD * DTOR
        IF(.NOT.IINULL)NULLPIX = 0
        IF(IIDIVIDE.EQ.0)IDIVIDE = 0
        RMINIP = 300
        IF (XSCAN.EQ.0) XSCAN = 18220
        IF (YSCAN.EQ.0) YSCAN = 18220
        XMAXIP = 18220
        YMAXIP = 18220
        RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
        IF (ILIMIT.EQ.0) THEN
          XLIMIT = 0.01*(XMAXIP/2)
          LIMIT = NINT(100*XLIMIT)
        END IF
        IF (ICUT.EQ.0) CUTOFF = 65500
        IF (IPRCUT.EQ.0) PRCUTOFF = 65500
        IF (IGAIN.EQ.0) THEN
          IGAIN = 2
          GAIN = 0.35
        ENDIF
C     
C---- this is for Bruker detectors with 3-circle goniostat at omega = 0 only!
C     ... now read from header...     
c     GON_KAPPA_SET = 54.74
C     
C---- can only handle these angle settings with the NUREEK code!
C     
        NUREEK = .TRUE.
C implementation of GENGON is currently faulty in REEK.F - 
CHRP 12.04.2006        GENGON = .TRUE.
        THREECIRCLE = .TRUE.
      ENDIF
      IF(MACHINE.EQ.'PILA'.or.MACHINE.EQ.'RIPI'.or.
     $     MACHINE.EQ.'RIEI'.or.MACHINE.EQ.'EIGE')THEN
C     ..
C     .. cannot set NREC and IYLEN until after gethdr
        RMINIP = 300
        IF (MACHINE.EQ.'RIPI'.OR.MACHINE.EQ.'EIGE'.OR.
     +      MACHINE.EQ.'RIEI') RMINIP = 200
        IF(IIDIVIDE.EQ.0)IDIVIDE = 0
C     ..
C     .. start: special values for Pilatus/Eiger, determined  experimentally
        PKRAT = 200
        PKACCEPT = .TRUE.
        IF(.NOT.IINULL)NULLPIX = -1
        WRONGGAPVALUE = .FALSE.
        EFAC = 0.000001
        IF(IBGSIG.EQ.0)BGSIG = 4.0
        IF (IBGSIG.EQ.0.AND.MACHINE.EQ.'RIPI')BGSIG = 6.0
        IF (IBGSIG.EQ.0.AND.MACHINE.EQ.'RIEI')BGSIG = 6.0
C
C---- Allow default BGFRAC to be overridden by keyword supplied value
C
        IF (IBGFRAC.EQ.0) BGFRAC = 1.0
        IF(IGRADMAX.EQ.0)GRADMAX = 1.00
        IF(IGRADMAXR.EQ.0)GRADMAXR = 1.00

C     ..
C     .. end: special values for Pilatus, determined  experimentally
        INVERTX = .TRUE.
        SPIRAL = .FALSE.
        CIRCULAR = .FALSE.
        ORTHOG = .TRUE.
        TILED = .TRUE.
        TRUSTED = .TRUE.
        HEADINFO = .FALSE.
        USEHDR = .TRUE.
        
        OMEGAFD = 00.0
C
C     Code has been put into GETHDR for CCD and Dectris detectors at Spring-8
C     That have a reversed phi rotation. 
C     Code below is for other beamlines that have a vertical spindle.
C     Note that for MD3 diffractometers (Petra P14, MaxIV BIOMAX, ESRF ID23-2)
C     the axis is inverted vertical, hence OMEGA=270.
C     The correction to OMEGA is made here, but the
C     polarisation correction also needs to be changed (as for I24). 
C     This is done by setting VERTICAL in CONTROL and testing
C     this in LPCOR.
C
        IF(HSERIAL(1:9).EQ.'60-0115-F')THEN
C     this is Gleb's Pilatus detector on B14, now at PetraII on P14?
          OMEGAFD = 270
          BEAMLINE = 'PETRAII P14'
          WRITE(IOUT,FMT=6012) HSERIAL,BEAMLINE,OMEGAFD
          IF (ONLINE) WRITE(ITOUT,FMT=6012) HSERIAL,BEAMLINE,OMEGAFD
 6012     FORMAT(/,1X,'*** IMPORTANT ***',/,1x,'From the detector',
     +      ' serial number ',A,' this has been identified',
     +      ' as an image from ',A,/,1X,'that has an MD3',
     +      ' diffractometer with an inverted vertical rotation axis.',
     +      /,1X,'The OMEGA angle has therefore been set to',F6.1,
     +      ' instead of the usual value of 0.0.',/,1X,'If this ',
     +      'is not correct, reset OMEGA to 0.0')
        ELSE IF(HSERIAL(1:9).EQ.'E-32-0107')THEN
C     this is Gleb's Eiger detector on Petra P14 (MD3 diffractometer
C     with vertical rotn axis)
          OMEGAFD = 270
          BEAMLINE = 'PETRAII P14'
          WRITE(IOUT,FMT=6012) HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
          IF (ONLINE) WRITE(ITOUT,FMT=6012) HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
        ELSE IF(HSERIAL(1:9).EQ.'E-32-0105')THEN
C     this is the Eiger at BIOMAX beamline at MaxIV (MD3 diffractometer
C     with vertical rotn axis)
          OMEGAFD = 270
          BEAMLINE = 'MaxIV BIOMAX'
          WRITE(IOUT,FMT=6012) HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
          IF (ONLINE) WRITE(ITOUT,FMT=6012) HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
        ELSE IF(HSERIAL(1:7).EQ.'24-0118')THEN
C     this is PILATUS3 2M on ESRF ID23-2, (MD3 diffractometer
C     with vertical rotn axis)
          OMEGAFD = 270
          BEAMLINE = 'ESRF ID23-2'
          WRITE(IOUT,FMT=6012) HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
          IF (ONLINE) WRITE(ITOUT,FMT=6012) HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
        ELSE IF(HSERIAL(1:7).EQ.'60-0126')THEN
C     this is PILATUS3 6M on DLS VMXm, with a vertical rotn axis
C     Need to test date of image, only transferred to VMXm on 17/4/2019.
          TESTDATE = .TRUE.
        ELSE IF(HSERIAL(1:9).EQ.'E-18-0118')THEN
C     this is Eiger on DLS VMXm, with a vertical rotn axis
          OMEGAFD = 90
          BEAMLINE = 'DLS VMXm'
          WRITE(IOUT,FMT=6012) HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
          IF (ONLINE) WRITE(ITOUT,FMT=6012) HSERIAL(1:LENSTR(HSERIAL)),
     +                 BEAMLINE(1:LENSTR(BEAMLINE)),OMEGAFD
        ENDIF
C
C---- Write a warning message
C
C
C---- Non-standard beamline setup (eg vertical rotation axis), OMEGA > 0
C
        IF ((ABS(OMEGAFD).GT.1.0).AND.(SOCKLO).AND.(.NOT.DONE)) THEN
          DONE = .TRUE.
          XMLLINE = ' '
          SERIOUSCOLOUR = 'RED'
          WRITE(XMLLINE,FMT=6016) SERIOUSCOLOUR
          CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF

 6016   FORMAT('<?xml version="1.0"?>',
     $         '<!DOCTYPE warnings>',
     $         '<warnings><process>indexing</process>'
     $         '<warning><type>warning</type>',
     $     '<colour>',A,'</colour>',
     +         '<message>Non standard experimental setup',
     +         '</message>',
     +     '<detail>From the detector serial number, the data',
     +     ' appears to come from a beamline with a vertical',
     +     ' rotation axis. See start of mosflm.lp file for more ',
     +     'details. If this is not the case, reset OMEGA',
     +     ' to 0.0 in Settings->Experiment settings',
     +     ' otherwise indexing will not work.',
     +          '</detail><hint>none</hint>',
     +      '</warning></warnings>')
 
        IF (DEBUG(84)) THEN
          WRITE(IOUT,FMT=6020) OMEGAFD,HSERIAL
          IF (ONLINE) WRITE(ITOUT,FMT=6020) OMEGAFD,HSERIAL
 6020     FORMAT(8X,'Omega:',F7.1,'  header serial number:',A)
        END IF
        OMEGAF = OMEGAFD * DTOR
C     ..
C     .. 22 bit detector - might need to cut this down in control file
        IF (ICUT.EQ.0) CUTOFF = 3538100
        IF (IPRCUT.EQ.0) PRCUTOFF = 3538100
C     ..
C     .. GAIN = 0.87 from one run of Mosflm
        IF (IGAIN.EQ.0)THEN
          IGAIN = 2
          GAIN = 0.87
        ENDIF
CAL        IF(.NOT.HEADONLY)THEN
CAL          WRITE(IOUT,FMT=6050)
CAL          IF(ONLINE)WRITE(ITOUT,FMT=6050)
CAL        ENDIF
      ENDIF
C
C---- Timpix detector
C
      IF (MACHINE.EQ.'TIME') THEN
C     ..
C     .. start: special values for Timepix?
        PKRAT = 200
        PKACCEPT = .TRUE.
        IF(.NOT.IINULL)NULLPIX = -1
        EFAC = 0.000001
        IF(IBGSIG.EQ.0)BGSIG = 4.0
C
C---- Allow default BGFRAC to be overridden by keyword supplied value
C
        IF (IBGFRAC.EQ.0) BGFRAC = 1.0
        IF(IGRADMAX.EQ.0)GRADMAX = 1.00
        IF(IGRADMAXR.EQ.0)GRADMAXR = 1.00

C     ..
        INVERTX = .TRUE.
        SPIRAL = .FALSE.
        CIRCULAR = .FALSE.
        ORTHOG = .TRUE.
        TILED = .TRUE.
        TRUSTED = .TRUE.
        HEADINFO = .FALSE.
        USEHDR = .TRUE.
        
        OMEGAFD = 00.0

      END IF
C
C---- Oxford diffraction Chrysalis pck format
C
      IF (MACHINE.EQ.'OXPK') THEN
        USEHDR = .TRUE.
        TRUSTED = .TRUE.
        INVERTX = .TRUE.
        SPIRAL = .FALSE.
        CIRCULAR = .FALSE.
        ORTHOG = .TRUE.
        TILED = .FALSE.
        ISCAN = 1
        OMEGAFD = 180.0
        OMEGAF = OMEGAFD * DTOR
        IF(.NOT.IINULL)NULLPIX = 0
        IF(IIDIVIDE.EQ.0)IDIVIDE = 0
        RMINIP = 300
        IF (XSCAN.EQ.0) XSCAN = 6300
        IF (YSCAN.EQ.0) YSCAN = 6300
        XMAXIP = 6300
        YMAXIP = 6300
        RMAXIP = SQRT(XMAXIP**2 + YMAXIP**2)
        IF (ILIMIT.EQ.0) THEN
          XLIMIT = 0.01*(XMAXIP/2)
          LIMIT = NINT(100*XLIMIT)
        END IF
        IF (ICUT.EQ.0) CUTOFF = 100000
        IF (IPRCUT.EQ.0) PRCUTOFF = 100000
        IF (IGAIN.EQ.0) THEN
          IGAIN = 2
          GAIN = 1.5
        ENDIF
      END IF        
C     
C---- need to test for Mar flat panel - 
C
      IF(MACHINE.EQ.'MARF')THEN
        IF(MODEL.EQ.'M555')THEN
          TRUSTED = .TRUE.
          NREC = 3072
          IYLEN = 2560
          RMINIP = 300
C     ..
C     .. start: special values (from Pilatus, not optimized for Mar 555)
        PKRAT = 200
        PKACCEPT = .TRUE.
        NULLPIX = 1
chrp 04.07.2011        EFAC = 0.000001
chrp 14.01.2007        BGSIG = 4.0
chrp 14.01.2007        BGFRAC = 1.0
C     ..
C     .. end: special values (from Pilatus, not optimized for Mar 555)
          XSCAN = 25854
          YSCAN = 17792
          XMAXIP = 25854
          YMAXIP = 17792
          IF (ILIMIT.EQ.0) THEN
            XLIMIT = 0.01*(XMAXIP/2)
            LIMIT = NINT(100*XLIMIT)
          END IF
C     
C---- what should RMAXIP be for a rectangular detector? diagonal to 
C     corner
C
          RMAXIP = 31080
          RSCANIP = RMAXIP
          IF (IPIX.EQ.0) RAST = 0.139
          OMEGAFD = 0.0
          OMEGAF = OMEGAFD * DTOR
          SPIRAL = .FALSE.
          ORTHOG = .TRUE.
          CIRCULAR = .FALSE.
          TILED = .FALSE.
          IF (IGAIN.EQ.0)THEN
            IGAIN = 2
            GAIN = 2.4
          ENDIF
C     ..
C     .. 24 bit? detector - might need to cut this down in control file
        IF (ICUT.EQ.0) CUTOFF = 128000
        IF (IPRCUT.EQ.0) PRCUTOFF = 256000
        ENDIF
      ENDIF

      IF (DEBUG(84)) THEN
        WRITE(IOUT,FMT=6040) SPIRAL,ORTHOG,CIRCULAR,INVERTX,USEHDR,
     +       TILED,OMEGAFD,NREC,IYLEN,XMAXIP,YMAXIP,RMINIP,RMAXIP,
     +       XSCAN,YSCAN,XLIMIT,GAIN,CUTOFF,PRCUTOFF,RAST,
     +       MACHINE,MODEL,HSERIAL
        IF (ONLINE) WRITE(ITOUT,FMT=6040) SPIRAL,ORTHOG,CIRCULAR, 
     +       INVERTX,USEHDR,
     +       TILED,OMEGAFD,NREC,IYLEN,XMAXIP,YMAXIP,RMINIP,RMAXIP,
     +       XSCAN,YSCAN,XLIMIT,GAIN,CUTOFF,PRCUTOFF,RAST,
     +       MACHINE,MODEL,HSERIAL
 6040   FORMAT(/,1X,'From SETDETECT, SPIRAL=',L1,' ORTHOG=',L1,
     +       ' CIRCULAR=',L1, ' INVERTX=',L1,' USEHDR=',L1,
     $       ' TILED=',L1,
     +       /,1X,'OMEGAFD=',F7.2,' NREC=',I5,' IYLEN=',I5,' XMAXIP=',
     +       F8.1,' YMAXIP',F8.1,' RMINIP=',F8.1,' RMAXIP=',F8.1,/,1X,
     +       'XSCAN=',F8.1,' YSCAN=',F8.1,' XLIMIT=',F6.1,' GAIN=',
     +       F5.2,' CUTOFF=',I8,' PRCUTOFF=',I8,' RAST',F6.3,/,1X,
     +       'MACHINE: ',A,'  Model:',A, '  Serial number: ',A)
 6050    FORMAT('warning, warning, warning. This detector option',
     $       ' has not been fully enabled yet.',/,/,
     $       'You should be prepared for unexpected results.')
      END IF
      RETURN
      END
      
C== SETMASK ==
C $Id: setmask.f,v 1.4 2006/08/29 14:58:22 harry Exp $
      SUBROUTINE SETMASK(MASK,IRAS)
      IMPLICIT NONE
C     =============================
C
C
C---- Using the raster parameters in array IRAS, this subroutine sets
C     up a mask which defines the areas of the peak and the background,
C     and the points omitted from peak and background areas.
C
C---- N.B. the mask is required to have MM symmetry.
C
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C
C     .. Array Arguments ..
      INTEGER IRAS(5),MASK(MAXBOX)
C     ..
C     .. Local Scalars ..
      INTEGER HX,HY,IC,IJ,IP,IPQ,IQ,IRX,IRY,P,Q
      LOGICAL P1,P2
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC ABS
C     ..
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C
C
      HX = IRAS(1)/2
      HY = IRAS(2)/2
C
c---- Test for IRAS(3)=0...code does not work
C
      IF (IRAS(3).EQ.0) THEN
        WRITE(IOUT,FMT=6000) IRAS
        IF (ONLINE) WRITE(ITOUT,FMT=6000) IRAS
 6000   FORMAT(1X,'Code in SETMASK will not work if corner parameter',
     +         ' of measurement box is zero',/,1X,'Current ',
     +         'measurement box parameters:',5I5)
      END IF
C
      IC = HX + HY - ABS(IRAS(3))
      IRX = HX - IRAS(4)
      IRY = HY - IRAS(5)
C
      IJ = 0
C
C
      DO 20 P = -HX,HX
        IP = ABS(P)
        P1 = (IP.GT.IRX)
        P2 = (IP.EQ.IRX)
C
C
        DO 10 Q = -HY,HY
          IJ = IJ + 1
          IQ = ABS(Q)
          IPQ = IP + IQ
C
C
          IF (P1 .OR. IPQ.GT.IC .OR. IQ.GT.IRY) THEN
C
C
            IF (IRAS(3).NE.0 .OR. IP.LT.IRX .OR. IQ.LT.IRY) THEN
C
C
              IF (IRAS(3).GE.0 .OR. IPQ.LE.IC) THEN
C
C---- Background points
C
                MASK(IJ) = -1
                GO TO 10
              END IF
            END IF
C
C
          ELSE IF (.NOT.P2 .AND. IPQ.NE.IC .AND. IQ.NE.IRY) THEN
C
C---- Peak points
C
            MASK(IJ) = 1
            GO TO 10
          END IF
C
C---- Omitted points, now treated as belonging to peak region
C
          MASK(IJ) = 1
   10   CONTINUE
   20 CONTINUE
C
C
      END
C== SETMASK2 ==
      SUBROUTINE SETMASK2(MASK,IRAS,MASKREJ)
C     ======================================
C
      IMPLICIT NONE
C
C---- Using the raster parameters in array IRAS, this subroutine sets
C     up a mask which defines the areas of the peak and the background,
C     and the points omitted from peak and background areas. Differs
C     from SETMASK in that it uses a list of rejected background pixels
C     suplied in MASKREJ to modify the MASK array. Thus the resulting
C     MASK will not necessarily have mm symmetry.
C
C     Values in MASK are:
C
C     -1     Background pixel
C      0     Rejected background pixel (overlapped by neighbouring spot)
C      1     Peak pixel
C
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C
C     .. Array Arguments ..
      INTEGER IRAS(5),MASK(MAXBOX),MASKREJ(NREJMAX)
C     ..
C     .. Local Scalars ..
      INTEGER HX,HY,IC,IJ,IP,IPQ,IQ,IRX,IRY,P,Q,N,NP,NBREJ
      LOGICAL P1,P2
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC ABS
C     ..
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C
C
      HX = IRAS(1)/2
      HY = IRAS(2)/2
C
c---- Test for IRAS(3)=0...code does not work
C
      IF (IRAS(3).EQ.0) THEN
        WRITE(IOUT,FMT=6000) IRAS
        IF (ONLINE) WRITE(ITOUT,FMT=6000) IRAS
 6000   FORMAT(1X,'Code in SETMASK2 will not work if corner parameter',
     +         ' of measurement box is zero',/,1X,'Current ',
     +         'measurement box parameters:',5I5)
      END IF
      IC = HX + HY - ABS(IRAS(3))
      IRX = HX - IRAS(4)
      IRY = HY - IRAS(5)
C
      IJ = 0
C
C
      DO 20 P = -HX,HX
        IP = ABS(P)
        P1 = (IP.GT.IRX)
        P2 = (IP.EQ.IRX)
C
C
        DO 10 Q = -HY,HY
          IJ = IJ + 1
          IQ = ABS(Q)
          IPQ = IP + IQ
C
C
          IF (P1 .OR. IPQ.GT.IC .OR. IQ.GT.IRY) THEN
C
C
            IF (IRAS(3).NE.0 .OR. IP.LT.IRX .OR. IQ.LT.IRY) THEN
C
C
              IF (IRAS(3).GE.0 .OR. IPQ.LE.IC) THEN
C
C---- Background points
C
                MASK(IJ) = -1
                GO TO 10
              END IF
            END IF
C
C
          ELSE IF (.NOT.P2 .AND. IPQ.NE.IC .AND. IQ.NE.IRY) THEN
C
C---- Peak points
C
            MASK(IJ) = 1
            GO TO 10
          END IF
C
C---- Omitted points, now treated as belonging to peak region
C
          MASK(IJ) = 1
   10   CONTINUE
   20 CONTINUE
C
C---- Now deal with rejected pixels (if any)
C
      NBREJ = MASKREJ(1)
      IF (NBREJ.EQ.0) RETURN
      DO 30 N = 1,NBREJ
        NP = MASKREJ(N+1)
        MASK(NP) = 0
 30   CONTINUE
      
      END
