      INTEGER IDELX,IDELY
C
C     .. Array Arguments ..
      INTEGER IRAS(5),MASK(MAXBOX),MASKNEW(MAXBOX)
C     ..
C     .. Local Scalars ..
      INTEGER HX,HY,IC,IJ,IP,IPQ,IQ,IRX,IRY,P,Q,N,NP,NBREJ,NXX,NYY,IJP
      LOGICAL P1,P2
C     ..
C     .. Local Arrays ..
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC ABS
C     ..
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/debug.f
C
C $Id: debug.f,v 1.8 2021/06/03 09:41:34 andrew Exp $
C
