     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C
CcHRP corrected 27.01.2011 - listed strong to weak (roughly). Top 5 are much
C     stronger than the rest. Then four moderately strong
C
C---- hexagonal ice
C
C     .. 1 1 0 Fc = 111.23
              NEXCL = NEXCL + 1
              RESL(NEXCL) = 2.25906*(1 + WIDTH)
              RESH(NEXCL) = 2.25906*(1 - WIDTH)
C              IF(ONLINE)write(itout,100) NEXCL, nring,resl(1),resh(1)
 100          format(1x,'NEXCL',I4, ' nring',I4,
     +          ' resln',2F6.2)
              IF (NEXCL.EQ.NRING) RETURN
C     .. 0 0 2 Fc = 110.68
              NEXCL = NEXCL + 1
              RESL(NEXCL) = 3.67806*(1 + WIDTH)
              RESH(NEXCL) = 3.67806*(1 - WIDTH)
C              if(online)write(itout,100) NEXCL, nring,resl(2),resh(2)
              IF (NEXCL.EQ.NRING) RETURN
C     .. 1 1 2 Fc = 59.60
              NEXCL = NEXCL + 1
              RESL(NEXCL) = 1.92496*(1 + WIDTH)
              RESH(NEXCL) = 1.92496*(1 - WIDTH)
C              if(online)write(itout,100) NEXCL, nring,resl(3),resh(3)
              IF (NEXCL.EQ.NRING) RETURN
C     .. 1 0 0 Fc = 85.86
              NEXCL = NEXCL + 1
              RESL(NEXCL) = 3.91270*(1 + WIDTH)
              RESH(NEXCL) = 3.91270*(1 - WIDTH)
              IF (NEXCL.EQ.NRING) RETURN
C     .. 1 0 1 Fc = 55.40
              NEXCL = NEXCL + 1
              RESL(NEXCL) = 3.45444*(1 + WIDTH)
              RESH(NEXCL) = 3.45444*(1 - WIDTH)
              IF (NEXCL.EQ.NRING) RETURN
C 
C---- next four strongest, may not need masking
C
C     .. 1 0 3 Fc = 76.59
              NEXCL = NEXCL + 1
              RESL(NEXCL) = 2.07775*(1 + (WIDTH-0.001))
              RESH(NEXCL) = 2.07775*(1 - (WIDTH-0.001))
              IF (NEXCL.EQ.NRING) RETURN
C     .. 1 0 2 Fc = 44.24
              NEXCL = NEXCL + 1
              RESL(NEXCL) = 2.67990*(1 + (WIDTH-0.001))
              RESH(NEXCL) = 2.67990*(1 - (WIDTH-0.001))
              IF (NEXCL.EQ.NRING) RETURN
C     .. 2 1 0 Fc = 30.30 
              NEXCL = NEXCL + 1
              RESL(NEXCL) = 1.47890*(1 + (WIDTH-0.002))
              RESH(NEXCL) = 1.47890*(1 - (WIDTH-0.002))
              IF (NEXCL.EQ.NRING) RETURN
C     .. 3 0 0 Fc = 45.22
              NEXCL = NEXCL + 1
              RESL(NEXCL) = 1.30427*(1 + (WIDTH-0.002))
              RESH(NEXCL) = 1.30427*(1 + (WIDTH-0.002))
              IF (NEXCL.EQ.NRING) RETURN
C
C next four are probably the only others worth worrying about mostly
C
C     .. 2 0 0 Fc = 44.57
              NEXCL = NEXCL + 1
              RESL(NEXCL) = 1.95639*(1 + (WIDTH-0.001))
              RESH(NEXCL) = 1.95639*(1 - (WIDTH-0.001))
              IF (NEXCL.EQ.NRING) RETURN
C     .. 2 0 1 Fc = 31.28
              NEXCL = NEXCL + 1
              RESL(NEXCL) = 1.89067*(1 + (WIDTH-0.001))
              RESH(NEXCL) = 1.89067*(1 - (WIDTH-0.001))
              IF (NEXCL.EQ.NRING) RETURN
C     .. 2 0 3 Fc = 48.42
              NEXCL = NEXCL + 1
              RESL(NEXCL) = 1.52928*(1 + (WIDTH-0.002))
              RESH(NEXCL) = 1.52928*(1 - (WIDTH-0.002))
              IF (NEXCL.EQ.NRING) RETURN
C     .. 2 1 1 Fc = 19.79 
              NEXCL = NEXCL + 1
              RESL(NEXCL) = 1.44988*(1 + (WIDTH-0.002))
              RESH(NEXCL) = 1.44988*(1 - (WIDTH-0.002))
              IF (NEXCL.EQ.NRING) RETURN
C can we forget the rest?
chrp              RESL(NEXCL) = 1.72725*(1 + WIDTH)
chrp              RESH(NEXCL) = 1.72725*(1 - WIDTH)
chrp              NEXCL = NEXCL + 1
chrp
C weak line 2.15952
C two very weak lines 1.66433, 1.66141
chrp              NEXCL = NEXCL + 1
chrpC two very close rings overlapping here!
chrp              RESL(NEXCL) = 1.37708*(1 + WIDTH)
chrp              RESH(NEXCL) = 1.37213*(1 - WIDTH)
chrp              NEXCL = NEXCL + 1
C weak line 1.28424
chrp              RESL(NEXCL) = 1.26638*(1 + WIDTH)
chrp              RESH(NEXCL) = 1.26638*(1 - WIDTH)
chrp              NEXCL = NEXCL + 1
C weak line 1.23281
chrp              RESL(NEXCL) = 1.22926*(1 + WIDTH)
chrp              RESH(NEXCL) = 1.22926*(1 - WIDTH)
chrp              NEXCL = NEXCL + 1
chrp              RESL(NEXCL) = 1.17584*(1 + WIDTH)
chrp              RESH(NEXCL) = 1.17584*(1 - WIDTH)
chrp              NEXCL = NEXCL + 1
C two weak lines 1.6991, 1.15247, 1.15150
chrp              RESL(NEXCL) = 1.12952*(1 + WIDTH)
chrp              RESH(NEXCL) = 1.12952*(1 - WIDTH)
chrp              NEXCL = NEXCL + 1

      RETURN
      END
C $Id: shutdown.f,v 1.19 2021/06/03 09:42:13 andrew Exp $
C== SHUTDOWN ==
      SUBROUTINE SHUTDOWN(CALLEDFROM,LENGTH)
C
C---- modified to include the calling subroutine name and a flag to
C     indicate where in the routine the call was made from
C
      IMPLICIT NONE
C
C---- Close the mtz file, print warning messages and stop
C
C
C           Common block PARAMETER
C     .. Include files ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     ..
C     .. Scalar arguments
       INTEGER LENGTH
      CHARACTER CALLEDFROM*(*)
C     ..
C     .. Local Scalars ..    
      INTEGER MTZPRT,NTOK
C     ..
C     .. Common blocks ..
C&&*&& include  ../inc/debug.f
C
C $Id: debug.f,v 1.8 2021/06/03 09:41:34 andrew Exp $
C
C--- awk generated include file  debug.h
C---- START of include file debug.h
C
C
C
C     .. Arrays in common /DEBUG/ ..
      REAL XWARN
      INTEGER NDEBUG,IWARN,IARRDUMP
      LOGICAL DEBUG,LPRINT,DUMP,WARN
C
C     .. Scalars in common /DEBUG/ ..
      REAL BGRLIM
      INTEGER NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,IERRLEVEL
      LOGICAL SPOT
      CHARACTER MESSAGE*512
C     
C     ..
C     .. Common Block /DEBUG/..
      COMMON /DEBUG/XWARN(MAXIWARN,100),BGRLIM,NDEBUG(200),
     +       IWARN(MAXIWARN,100),
     $       NDUMP,IMINDUMP,IMAXDUMP,MXDUMP,DEBUG(200),LPRINT(20),
     +       DUMP(30),WARN(100),SPOT,IARRDUMP(30),IERRLEVEL

      COMMON /CDEBUG/ MESSAGE
C     ..
C
C&&*&& end_include  ../inc/debug.f
C&&*&& include  ../inc/ioomtz.f
C
C $Id: ioomtz.f,v 1.5 2011/06/27 12:46:46 andrew Exp $
C
C--- awk generated include file  ioomtz.h
C---- START of include file ioomtz.h
C
C
C     .. Scalars in common block /IOOMTZ/ ..
      INTEGER MTZOUT,BESTHKL
      LOGICAL MTZOPEN,BESTOPEN,NEWMTZ
      CHARACTER*100 BSTHKL
C     ..
C     .. Common block /IOOMTZ/ ..
      COMMON /IOOMTZ/ MTZOUT,BESTHKL,MTZOPEN,BESTOPEN,BSTHKL,NEWMTZ
C&&*&& end_include  ../inc/ioomtz.f
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C
       CHARACTER KILLMESSAGE*80,IOLINE2*1024
       INTEGER LENSTR
       EXTERNAL LENSTR
       EXTERNAL CCPERR
       WRITE(IOUT,6000)CALLEDFROM(1:LENGTH),NSHUTERR
       IF(ONLINE)WRITE(ITOUT,6000)CALLEDFROM(1:LENGTH),
     $      NSHUTERR
 6000  FORMAT(72('-'),/,/,8X,'An unrecoverable error has occurred in ',
     $      A,' at mark ',I2,'; ',/,8X,
     $      'performing a clean shutdown of Mosflm',/,/,72('*'))
C
       KILLMESSAGE = '---- MOSFLM HAS TERMINATED EARLY -'//
     $    ' check log file carefully'
        IF(SOCKLO)THEN
 6100     FORMAT('<?xml version="1.0"?>',
     $         '<!DOCTYPE fatal_condition_response>',
     $         '<fatal_condition_response>',
     $         '<status>',
     $         '<code>shutdown</code>',
     $         '</status>',
     $         '<subroutine>',A,'</subroutine>',
     $         '<mark>',I3,'</mark>',
     $         '<message>',A,'</message>',
     $         '<level>',I3'</level>',
     $         '</fatal_condition_response>')
          WRITE(IOLINE2,FMT=6100)CALLEDFROM(1:LENGTH),
     $         NSHUTERR,message(1:lenstr(message)),IERRLEVEL
          CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(IOLINE2),
     $         IOLINE2)
          IF(.NOT.XMLOPEN) THEN
            CALL READ_SOCKET(SERVERFD,IOLINE2, ntok)
            IF (DEBUG(89)) THEN
              WRITE(IOUT,FMT=6200) IOLINE2(1:120)
              IF (ONLINE) WRITE(ITOUT,FMT=6200) IOLINE2(1:120)
 6200         FORMAT(1X,'Socket read in SHUTDOWN:',A)
            END IF
          END IF
        ENDIF
CAL        write(iout,fmt=6300)
CAL        if (online) write(itout,fmt=6300)
 6300   format(1x,'Waiting before shutting down ipmosflm')
CAL        call msleep(5)
        CALL WARNINGS
        CALL GROUT
C
        IF (MTZOPEN) THEN
          MTZPRT = 1
C               *********************
          CALL LWCLOS(MTZOUT,MTZPRT)
C               *********************
          MTZOPEN = .FALSE.
          IF(LBEST.AND.BESTOPEN)THEN
            CLOSE(BESTHKL)
            BESTOPEN = .FALSE.
          ENDIF
        END IF
        IF(DNAOUT)THEN
          CALL DNA_OUTPUT_LIST_START('fatal_mosflm_error')
          CALL DNA_OUTPUT_CHARACTER_ITEM('subroutine',
     $         CALLEDFROM(1:LENGTH))
          CALL DNA_OUTPUT_INTEGER_ITEM('mark',NSHUTERR)
          CALL DNA_OUTPUT_LIST_END
          call dna_end_output
        ENDIF
        CALL CCPERR(1,KILLMESSAGE)
C     
C---- there need be no RETURN from SHUTDOWN!
C
        END
C== SIZRAS ==
C $Id: sizras.f,v 1.3 2012/02/27 14:14:38 andrew Exp $
C
C
      SUBROUTINE SIZRAS(IRAS,NPEAK,NBG)
C     =================================
      IMPLICIT NONE
C
C
C---- Using the raster parameters in array IRAS, this subroutine calculates
C     the number of peak and background pixels. Updated to reflect the fact
C     that there is no longer a ring of "null" pixels around the peak 23/2/12
C
C     .. Scalar Arguments ..
      INTEGER NBG,NPEAK
C     .. Array Arguments ..
      INTEGER IRAS(5)
C     ..
C     .. Local Scalars ..
      INTEGER HX,HY,IC,IJ,IP,IPQ,IQ,IRX,IRY,P,Q
      LOGICAL P1,P2
C     ..
C     .. Intrinsic Functions ..
      INTRINSIC ABS
C     ..
C
C
      HX = IRAS(1)/2
      HY = IRAS(2)/2
C
      IC = HX + HY - ABS(IRAS(3))
      IRX = HX - IRAS(4)
      IRY = HY - IRAS(5)
C
      IJ = 0
      NBG = 0
      NPEAK = 0
C
C
      DO 20 P = -HX,HX
        IP = ABS(P)
        P1 = (IP.GT.IRX)
        P2 = (IP.EQ.IRX)
C
C
        DO 10 Q = -HY,HY
          IJ = IJ + 1
          IQ = ABS(Q)
          IPQ = IP + IQ
C
C
          IF (P1 .OR. IPQ.GT.IC .OR. IQ.GT.IRY) THEN
C
C
            IF (IRAS(3).NE.0 .OR. IP.LT.IRX .OR. IQ.LT.IRY) THEN
C
C
              IF (IRAS(3).GE.0 .OR. IPQ.LE.IC) THEN
C
C---- Background points
C
                NBG = NBG + 1
                GO TO 10
              END IF
            END IF
C
C
          ELSE IF (.NOT.P2 .AND. IPQ.NE.IC .AND. IQ.NE.IRY) THEN
C
C---- Peak points
C
            NPEAK = NPEAK + 1
            GO TO 10
          END IF
C
C---- Omitted points, now treated as belonging to peak region
C
          NPEAK = NPEAK + 1
   10   CONTINUE
   20 CONTINUE
C
C
      END
C $Id: skipimg.f,v 1.3 2003/11/10 12:44:20 harry Exp $
      SUBROUTINE SKIPIMG(INMO)
      IMPLICIT NONE
C
C---- Skip a set of measurement boxes for one complete image. Needed when
C     postrefinement results in more than one set of boxes being written
C     for the same image (if measurement repeated due to large shift)
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     ..
C     .. Scalar Arguments ..
      INTEGER INMO
C     ..
C     .. Local Scalars ..
      INTEGER NREF,MAXR,NPARTEND,LEN,I
      REAL XCEN,YCEN
C     ..
C     .. Local Arrays ..
      INTEGER*2 IIBUF(4),ODBOX(MAXBOX),IBUF(12)
C     ..
C     .. External Subroutines ..
      EXTERNAL PREAD
C     ..
C     .. Include files
C&&*&& include  ../inc/condata.f
C
C $Id: condata.f,v 1.49 2021/02/11 11:30:48 andrew Exp $
C
C--- awk generated include file condata.h 
C---- START of include file condata.h 
C 
C
C     FIXSWAP     Forces reversal of normal byte-swapping choice.
C
C---- SUMPART True if two images are to be stored in memory at the
C               same time. This will be the case if post-refinement
C               (other than POSTHOC post-refinement for off-line
C               scanners) is being performed. Note that SUMPART is NOT
C               used to determine if partials should be added across
C               images (this is ADDPART)
C
C---- NEWPREF True if allowing partials over multiple images in post-
C             refinement.
C
C---- ADDPART True if partials are to be summed across images. This is
C               only appropriate for fixed origin (ie on-line)
C               scanners where the X-ray dose is identical for
C               each image.
C     Direct beam coordinates
C             These are read into XMM(3), YMM(3) where (3) is for A,B,C packs
C             Immediately on reading in, these values are transferred
C             into XCENMM, YCENMM, XCENMMIN(J,3) where J=1->MAXPAX.
C
C             If an IMAGE keyword has been given, XCENMM(1,1)=XMM(1) and
C             YCENMM(1)=YSCAL*YMM(1). If swung out, YCENMM(1,1) is updated.
C             If a BEAM keyword has not been given, XMM,YMM, XCENMM,YCENMM,
C             XCENMMIN are all set to the middle of the image.


C             Then, when reflecting input to logfile, it AGAIN sets up
C             XCENMM,YCENMM for all images using XMM,YMM, this time
C             using YSCAL to set up YCENMM, and updating YCENMM if the
C             detctor is swung out. (label 708), DO loop 710. If image
C             is "inverted", corrects XCENMM for all images.


C             XCEN,YCEN are set in "mosflm" to XCENF, YCENF plus
C             camera constants, and XCENF,YCENF are in turn set from
C             XCENMM,YCENMM. Thus XCENMM,YCENMM are what is actually
C             used to define the beam position.

C
C     LPREF   If TRUE, return to display after refinement over entire
C             image. Only active when integrating interactively. Set by
C             toggle button in Parameter window.
C

C     LOVERLAP  If TRUE, do not call the OVERLAP subroutine

C     ALLOUT  If TRUE, all reflections (whether measured or not, or
C             classified as BADSPOTS or not, will be written to the
C             output MTZ file.
C
C     NTDIG   Number of digits in image number, returned as zero if
C             there is an error in the template. Only used if TEMPLATE
C             keyword given.
C
C     TEMPLATE is TRUE if a TEMPLATE keyword has been given.
C
C     NOLP    If TRUE, do NOT apply the Lorentz Polarisation corrections
C
C     MULTIMTZ True if writing each "block" of images to a separate MTZ file
C
C     DISPMENU True if the run was started with a IMAGE keyword. Not to be
C              confused with WINOPEN which is true if the X-window display
C              is being used, but this is not necessarily starting with
C              a "IMAGE" keyword.
c     newgui - this means that we're talking through the new GUI.
c              except that we can't have it here because the prsummary 
c              subroutine, where we REALLY want it, clashes with this common
C
C     HACTIVEMASK,LACTIVEMASK,LACTIVE - only for Rigaku images which 
C     contain a compressed "active mask" (size=HACTIVEMASK bytes)
C     at the end of the image. Compression uses a modified run length encoding
C     at present (10.01.2003).
C
C     MINBATCH Minimum allowed batch number to be written to an open
C              MTZ file (MTZ library imposes that batch numbers must 
C              increase as file is written).
c
c     MERGELATT If true, prediction lists for multiple lattices will
C               be merged for output to iMosflm
C
C     NIMGSUMREF Number of images to be summed when determining spot
C                centroids for detector parameter refinement. Only
C                works for Pilatus detectors at present.
C     ..
C     .. Arrays in common /CONDATA/ ..
      REAL XCENMM,YCENMM,THFOIL,PHIBEGA,PHIENDA,RSYM,XMM,YMM,
     +     XCENMMIN,YCENMMIN
C     ..
C     .. Arrays in common /CONDATA/ ..
      INTEGER IDPACK,NFPACK,NFIRST,ICASSET
      INTEGER IPACK1A,IPACK2A,ISERAR,PICKER
      LOGICAL AVPROF,FILMPLOT,FORCEB,FORCEC,CONTROLM,CONTROLS
C
C     .. Scalars in common /CONDATA/ ..
C     ..
      REAL RMSLIM,WRMSLIM,VLIM,XMID,SEP,THICK,PTMIN,REFREJ,
     +     YSCALIN,FULLFRAC,WTIME,OVERLAPMAX
      INTEGER NPACK,NCYC,MAXNX,MAXNY,ITHRESHF,NSIG,IRFMIN,
     +        IRFINC,IXSHIFT,IYSHIFT,LIMIT,NBLOCK,INOGEN,NFGEN,MINREF,
     +        ISERADD,NSEG,NSYM,NSYMP,NRUN,NSERTOT,IWAVE,ISWUNG,
     $        IBEAMMU,ITILT,ITWIST,IPIX,IRMINXY,ICUT,IPRCUT,ILIMIT
      INTEGER IMAT,ICELL,IUMAT,LSYMM,IDIST,IBEAM,ISCAN,NLINE,NRLINE,
     +     NTLINE,NTOTLINE,ISTARTP,IRAST,INEWMAT,ISEP,NSAVELINE,IPTIME,
     +     ISTRT,IANGLE,IBACKS,IPOLAR,IDIVH,IDIVV,IGAIN,IBLOCK,
     +     IHKLOUT,IGENF,INRES,NTDIG,DELAY,IMULTI,IMISS,IMISSMAT,
     +     IIDENT,HACTIVEMASK,ITWOTHETA,MINBATCH,ILABVIEW,INVVIEW,
     $     IINVVIEW,IHKLDIR,IBGSIG,NRLEFT,WAIT,IPARTITION,ISIGSET,
     +     NSIGSAVE,ITOL,NIMGSUMREF,IBGFRAC,THISIMG,CHUNK,ICHUNK,
     $     IPTMINSET,IYSCAL
      LOGICAL FINDCC,READCC,NOFID,INTERPOL,CONVOL,NOMEAS,
     +     USEPAR,USEOVR,SUMPART,USEBOX,POSTREF,ADDPART,
     +     FIXED,POWDER,RWEIGHT,NOREF,MULTISEG,FIXSWAP,POSTHOC,
     +     LPREF,LPINTG,DISPMENU,PRMODE,PRCELL,TEMPLATE,
     +     LOVERLAP,ALLOUT,NOLP,NEWPREF,NOBACK,MOSEST,BLKEST,NUSPOT,
     $     NUBACK,NUFIND,HARVESTREADY,HEADINFO,MULTIMTZ,ANDREW, 
     +     spostref,newgui,LACTIVEMASK,USERSPOT,HEADONLY,PHIONLY,
     $     NO_XML,TESTSOCK,PICKLOG,EXPLICIT_CELL,LSIMULATE,
     $     LONGERNAME,TIMER,MERGELATT,NULLPIXTEST,KEEPNULLPIX,CCHUNK,
     +     INVXFORCEREAD
C     ..
C real arrays, then scalars, integer arrays, scalars, logicals
      COMMON /CONDATA/
     $     XCENMM(MAXPAX,3),
     +     YCENMM(MAXPAX,3), THFOIL(3),PHIBEGA(MAXPAX),
     $     PHIENDA(MAXPAX),RSYM(4,4,96),XMM(3),YMM(3),
     $     XCENMMIN(MAXPAX),YCENMMIN(MAXPAX),
     $     RMSLIM,WRMSLIM,VLIM,XMID,SEP,THICK,PTMIN,REFREJ,
     +     YSCALIN,FULLFRAC,WTIME,OVERLAPMAX,
     $     IDPACK(MAXPAX),NFPACK(MAXPAX),NFIRST(MAXPAX),
     +     ICASSET(MAXPAX),IPACK1A(50),
     +     IPACK2A(50),ISERAR(50),PICKER(4),
     $     AVPROF(MAXPAX),FILMPLOT(MAXPAX),FORCEB(MAXPAX),
     +     FORCEC(MAXPAX),
     $     NPACK,NCYC,MAXNX,MAXNY,ITHRESHF,NSIG,IRFMIN,
     +     IRFINC,IXSHIFT,IYSHIFT,LIMIT,NBLOCK,INOGEN,NFGEN,MINREF,
     +     ISERADD,NSEG,NSYM,NSYMP,NRUN,NSERTOT,IWAVE,ISWUNG,
     $     IBEAMMU,ITILT,ITWIST,IPIX,IRMINXY,ICUT,IPRCUT,ILIMIT,
     $     IMAT,ICELL,IUMAT,LSYMM,IDIST,IBEAM,ISCAN,NLINE,NRLINE,
     +     NTLINE,NTOTLINE,ISTARTP,IRAST,INEWMAT,ISEP,NSAVELINE,
     +     IPTIME,ISTRT,IANGLE,IBACKS,IPOLAR,IDIVH,IDIVV,IGAIN,IBLOCK,
     +     IHKLOUT,IGENF,INRES,NTDIG,DELAY,IMULTI,IMISS,IMISSMAT,
     +     IIDENT,HACTIVEMASK,ITWOTHETA,MINBATCH,ILABVIEW,INVVIEW,
     $     IINVVIEW,IHKLDIR,IBGSIG,NRLEFT,WAIT,IYSCAL,
     +     FINDCC,READCC,NOFID,
     +     INTERPOL,CONVOL,NOMEAS,USEPAR,USEOVR,SUMPART,USEBOX,
     +     POSTREF,spostref, ADDPART,FIXED,POWDER,RWEIGHT,NOREF,
     +     MULTISEG,FIXSWAP,POSTHOC,LPREF,LPINTG,DISPMENU,PRMODE,
     $     PRCELL,TEMPLATE,
     +     LOVERLAP,ALLOUT,NOLP,NEWPREF,NOBACK,MOSEST,BLKEST,NUSPOT,
     $     NUBACK,NUFIND,HARVESTREADY,HEADINFO,MULTIMTZ,ANDREW,
     $     newgui,LACTIVEMASK,USERSPOT,HEADONLY,PHIONLY,NO_XML,
     $     TESTSOCK,PICKLOG,EXPLICIT_CELL,LSIMULATE,
     $     LONGERNAME,TIMER,CONTROLM,CONTROLS,IPARTITION,ISIGSET,
     +     NSIGSAVE,ITOL,MERGELATT,NIMGSUMREF,NULLPIXTEST,
     +     KEEPNULLPIX,IBGFRAC,THISIMG,CHUNK,ICHUNK,CCHUNK,IPTMINSET,
     +     INVXFORCEREAD


C&&*&& end_include  ../inc/condata.f
C
C
      IF(NUSPOT)THEN
        CALL SPHDREAD(XCEN,YCEN,NREF,MAXR,NPARTEND)
        DO 20 I = 1,NREF
          CALL SPBDREAD(ODBOX(1),IBUF,LEN)
 20     ENDDO
      ELSE
        READ (INMO) XCEN,YCEN,NREF,MAXR,NPARTEND
        DO 10 I = 1,NREF
          READ (INMO) LEN,IIBUF
C     ************************
          CALL PREAD(ODBOX(1),LEN,INMO)
C     ************************
 10     CONTINUE
      ENDIF
      RETURN
      END
C $Id: smoothdelphi.f,v 1.1 2015/05/11 15:23:26 harry Exp $
      SUBROUTINE SMOOTHDELPHI(NIMAG,NDONE,DELPHI,DELPHISM)
C     ===================================================
C
      IMPLICIT NONE
C
C
C     .. Parameters ..
C&&*&& include  ../inc/reeke.f
C
C $Id: reeke.f,v 1.17 2015/05/11 14:19:27 andrew Exp $
C
C--- awk generated include file  reeke.h
C---- START of include file reeke.h
C
C     TOR     For synchrotron sources, degree of polarisation of the beam
C     IMONO   Collimation flag for polarisation.
C             = 0   Pinhole or mirrors
C             = 1   Graphite Monochromator
C             = 2   Synchrotron, use TOR
C     NWMAX   Maximum reflection width in images
C     DSTMAX  dimensionless rlu, = WAVE/RES where RES is the maximum
C             resolution in Angstrom.
C     DSTMIN  dimensionless rlu, = WAVE/DMAX where DMAX is the maximum
C              Bragg spacing
C     S0      radiation source vector (-1,0,0), may be modified by MU values
C     SOURCE  radiation source vector - basis for s0
C     GONIO_angle:  machine angles for generalized goniostats
C     GONIO_angle_SET: fixed offset angles for 3- and 4-circle goniostats
C                      i.e. currently 54.74 deg for Bruker CHI, 50.0deg for
C                      Nonius and Oxford KAPPA 
C     VERTICAL Logical set TRUE if rotation axis is vertical, only
C              affects polarization correction for synchrotron data
C     NSMOOTH  Number of images to use in smoothing refined values of
C              mosaic spread and missetting angles (if being smoothed).
C     ..
C     .. Arrays in common block /REEKE/ ..
      REAL RMC,AMAT,SCAXIS,S0,s0unit,CAMCON,BEAMMU
C     ..
C     .. Scalars in common block /REEKE/ ..
      REAL X1,X2,Y1,Y2,Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,
     +     DIVH,DIVV,DELAMB,ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,
     +     ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,
     +     BLKSIZE
      INTEGER ISYN,IMONO,NWMAX,IPAD,NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS
C     ..
C     .. logicals in common block /REEKE/ ..
      LOGICAL LOGETA,NUREEK,LCAMCON,GENGON,FOURCIRCLE,THREECIRCLE,
     +        VERTICAL
C     ..
C     .. Common Block /REEKE/ ..
      COMMON /REEKE/RMC(3,3),AMAT(3,3),SCAXIS(3),S0(3),s0unit(3),
     $     CAMCON(8),BEAMMU(2),X1,X2,Y1,Y2,
     +     Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,DIVH,DIVV,DELAMB,
     +     ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,ISYN,IMONO,
     $     NWMAX,IPAD,
     $     NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS,LOGETA,NUREEK,LCAMCON,
     $     GENGON,FOURCIRCLE,THREECIRCLE,
     +     BLKSIZE,VERTICAL
C     ..
C
C
C&&*&& end_include  ../inc/reeke.f
C
C     ..
C     .. Scalar Arguments ..
      INTEGER NIMAG,NDONE
C
C     ..
C     .. Array Arguments ..
      REAL DELPHI(3),DELPHISM(3)
C     ..
C     .. Local Scalars ..
      DOUBLE PRECISION PHIXOLDD,PHIXSMD,PHIXD,
     +                 PHIYOLDD,PHIYSMD,PHIYD,
     +                 PHIZOLDD,PHIZSMD,PHIZD
      REAL PHIXOLD,PHIYOLD,PHIZOLD,PHIXSM,PHIYSM,PHIZSM
      INTEGER NOFFSET
C     ..
C     .. Local Arrays ..
C     ..
C     .. External Functions ..
C     ..
C     .. External Subroutines ..
C     ..
C     .. Intrinsic Functions ..
C     ..
C     .. Common blocks ..
C     ..
C     .. Equivalences ..
      SAVE
C     ..
C     .. Data ..
C     ..
C---- cast reals to doubles
C
      PHIXD = DBLE(DELPHI(1))
      PHIYD = DBLE(DELPHI(2))
      PHIZD = DBLE(DELPHI(3))
C
C
C---- Check if this is the first time a refined value has been obtained
C     in this run.
C
      IF (NDONE.EQ.0) THEN
        NOFFSET = NIMAG
        NDONE = 1
        PHIXOLDD = PHIXD
        PHIXOLD = REAL(PHIXOLDD)
        PHIXSMD = PHIXD
        PHIXSM = REAL(PHIXSMD)
      ELSE
C
C---- Set up the weighting for this value
C
        NDONE = NIMAG - NOFFSET + 1
        NDONE = MIN(NDONE,NSMOOTH)
        IF (NDONE.GT.0) THEN
          PHIXSMD = (DBLE(NDONE-1)/DBLE(NDONE)) * PHIXOLDD + 
     +         (1.0/DBLE(NDONE)) * PHIXD
        ELSE
          PHIXSMD = PHIXD
        END IF
        PHIXOLDD = PHIXSMD
        PHIXOLD = REAL(PHIXOLDD)
        PHIXSM = REAL(PHIXSMD)
      ENDIF
      DELPHISM(1) = PHIXSM
C
C
C
C
C---- Check if this is the first time a refined value has been obtained
C     in this run.
C
      IF (NDONE.EQ.0) THEN
        NOFFSET = NIMAG
        NDONE = 1
        PHIYOLDD = PHIYD
        PHIYOLD = REAL(PHIYOLDD)
        PHIYSMD = PHIYD
        PHIYSM = REAL(PHIYSMD)
      ELSE
C
C---- Set up the weighting for this value
C
        NDONE = NIMAG - NOFFSET + 1
        NDONE = MIN(NDONE,NSMOOTH)
        IF (NDONE.GT.0) THEN
          PHIYSMD = (DBLE(NDONE-1)/DBLE(NDONE)) * PHIYOLDD + 
     +         (1.0/DBLE(NDONE)) * PHIYD
        ELSE
          PHIYSMD = PHIYD
        END IF
        PHIYOLDD = PHIYSMD
        PHIYOLD = REAL(PHIYOLDD)
        PHIYSM = REAL(PHIYSMD)
      ENDIF
      DELPHISM(2) = PHIYSM
C
C
C---- Check if this is the first time a refined value has been obtained
C     in this run.
C
      IF (NDONE.EQ.0) THEN
        NOFFSET = NIMAG
        NDONE = 1
        PHIZOLDD = PHIZD
        PHIZOLD = REAL(PHIZOLDD)
        PHIZSMD = PHIZD
        PHIZSM = REAL(PHIZSMD)
      ELSE
C
C---- Set up the weighting for this value
C
        NDONE = NIMAG - NOFFSET + 1
        NDONE = MIN(NDONE,NSMOOTH)
        IF (NDONE.GT.0) THEN
          PHIZSMD = (DBLE(NDONE-1)/DBLE(NDONE)) * PHIZOLDD + 
     +         (1.0/DBLE(NDONE)) * PHIZD
        ELSE
          PHIZSMD = PHIZD
        END IF
        PHIZOLDD = PHIZSMD
        PHIZOLD = REAL(PHIZOLDD)
        PHIZSM = REAL(PHIZSMD)
      ENDIF
      DELPHISM(3) = PHIZSM
C
C      

      RETURN
      END
C     $Id: solutions.f,v 1.4 2005/02/15 13:23:51 harry Exp $
C     
      SUBROUTINE SOLUTIONS(SDMM,FRAC,DENDISIND,MERIT,SOLN,I,INDEX,
     $     ICRYST,BT,SPLIST, SPLISTR,SPLISTB,PREREF,USERCELL,CELLB,
     $     SAVHCELL,CELLCH,THISONE,DODEN)
C     
C---- routine to write out the results of autoindexing
C     
      IMPLICIT NONE
C     ..
C     .. Scalar arguments
      REAL SDMM,FRAC,DENDISIND
      INTEGER SOLN,I,INDEX,ICRYST,THISONE
      INTEGER*2 MERIT
      CHARACTER*2 BT   
      CHARACTER*70 SPLIST
      CHARACTER*36 SPLISTR
      CHARACTER*57 SPLISTB
      LOGICAL PREREF,USERCELL,DODEN
C     ..
C     .. Array arguments
      REAL CELLB(6),SAVHCELL(6),CELLCH(6)
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C&&*&& include  ../inc/dsplyc.f
C
C $Id: dsplyc.f,v 1.7 2015/05/27 10:36:13 harry Exp $
C
C--- awk generated include file  dsplyc.h
C---- START of include file dsplyc.h
C
C*******************************************************************
C
C  COMMON  /DSPLYC/
C
C       IMGLOW, IMGHI   low & high values of 16-bit image for scaling
C                       integer*2 to byte: IMGLOW maps to  0; 
C                       IMGHI to maximum. Note that these are not
C                       necessarily the actual limits of the data
C       IMGMAX          maximum value recorded on the image. Necessary for 
C                       iMosflm.
C       IMGMIN          Minimum value recorded on image - gaps on PADs, 
C                       necessary for iMosflm
C       JDSPWD          .LT. 0  before image window has been created
C                       = +-1 for image display that can be panned
C                       = +-2 for non-interactive image display
C       MAXDEN          highest level in colour table to fill up to
C                       must be less than ~240 - number of overlay colours
C       LDSPSG          if .true., treat image as signed, ie after dark
C                          subtraction
C                       if .false., treat image as unsigned
C       NZOOM           zoom factor for image, = 0 if no zoom
C       JYZOOM, JZZOOM  1st pixel in zoomed image
C
C----   WINOPEN Flag for whether or not window is open. Do not
C               confuse with DISPMENU (/CONDATA/)which is true if the run was
C               started with a IMAGE keyword.
C
C
C       CDSPTL          banner title
C
      REAL FTOTAL,AVERAG,IMAGERMS
      INTEGER IMGLOW, IMGHI, IMGMAX,IMGMIN,JDSPWD, MAXDEN,
     $     NZOOM, JYZOOM, JZZOOM
      INTEGER PIXEL_INTENSITIES(514)
      LOGICAL LDSPSG,WINOPEN,LPAUSE,LHELP
      COMMON /DSPLYC/ FTOTAL,AVERAG,IMAGERMS,IMGLOW, IMGHI, IMGMAX,
     *     IMGMIN,JDSPWD,MAXDEN, NZOOM, JYZOOM, JZZOOM, 
     $     PIXEL_INTENSITIES,LDSPSG,WINOPEN,LPAUSE,LHELP
C
      CHARACTER  CDSPTL*200,SHORTFN*200
      COMMON /DSPLCC/  CDSPTL,SHORTFN
C                                                           
C
C*******************************************************************


C&&*&& end_include  ../inc/dsplyc.f
C     ..
C     .. Local scalars
      INTEGER K
      CHARACTER*150 LLINE
C     ..
C     ..
C     ..
C     .. External Functions ..
      INTEGER LENSTR
      EXTERNAL LENSTR
C     
C---- 
C
      IF(.NOT.DODEN)THEN
      IF(PREREF)THEN
         IF((MERIT.LE.200).OR.(SOLN.EQ.I))THEN
c     dms21.09.2004   Special format for rhombohedral. 
            IF (INDEX.EQ.12) THEN
               IF (ICRYST.EQ.8) THEN
c     end of cdms insertion
                  WRITE(IOUT,FMT=6000) I,MERIT,SDMM,FRAC,
     +                 BT,(CELLB(K),K=1,6),SPLISTR
                  IF (ONLINE) WRITE(ITOUT,FMT=6000)I,MERIT,SDMM,
     +                 FRAC,BT,(CELLB(K),K=1,6),SPLISTR
                  IF (ONLINE.AND.WINOPEN) THEN
                     WRITE(LLINE,FMT=6000)I,
     +                    MERIT,SDMM,FRAC,BT,(CELLB(K),K=1,6),
     +                    SPLISTR
                     CALL MXDWIO(LLINE,2)
                  ENDIF
                  WRITE (IOUT,FMT=6300) (SAVHCELL(K),K=1,6),
     +                 SPLIST(1:LENSTR(SPLIST))
                  IF(ONLINE)WRITE(ITOUT,FMT=6300)(SAVHCELL(K),K=1,6),
     +                 SPLIST(1:LENSTR(SPLIST))
                  IF (ONLINE.AND.WINOPEN)THEN
                     WRITE (LLINE,FMT=6300) 
     $                    (SAVHCELL(K),K=1,6),
     +                    SPLIST(1:LENSTR(SPLIST))
                     CALL MXDWIO(LLINE,2)
                  ENDIF
               ELSE
                  WRITE(IOUT,FMT=6000) I,MERIT,SDMM,FRAC,
     +                 BT,(CELLB(K),K=1,6),
     +                 SPLIST(1:LENSTR(SPLIST))
                  IF (ONLINE) WRITE(ITOUT,FMT=6000)I,MERIT,SDMM,
     +                 FRAC,BT,(CELLB(K),K=1,6),
     +                 SPLIST(1:LENSTR(SPLIST))
                  IF (ONLINE.AND.WINOPEN) THEN
                     WRITE(LLINE,FMT=6000)I,
     +                    MERIT,SDMM,FRAC,BT,(CELLB(K),K=1,6),
     $                    SPLIST(1:LENSTR(SPLIST))
                     CALL MXDWIO(LLINE,2)
                  ENDIF
                  CALL MATCOPF(CELLCH,CELLB,6,1)
                  CALL CONRHO(1,6,CELLCH)
                  WRITE (IOUT,FMT=6300) (CELLCH(K),K=1,6),SPLISTR
               ENDIF
            ELSE
               WRITE(IOUT,FMT=6000) I,MERIT,
     $              SDMM,FRAC,BT,
     +              (CELLB(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
               IF (ONLINE) WRITE(ITOUT,FMT=6000)I,MERIT,
     $              SDMM,FRAC,
     +              BT,(CELLB(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
               IF (ONLINE.AND.WINOPEN) THEN
                  WRITE(LLINE,FMT=6000)I,
     +                 MERIT,
     $                 SDMM,FRAC,BT,(CELLB(K),K=1,6),
     $                 SPLIST(1:LENSTR(SPLIST))
                  CALL MXDWIO(LLINE, 2)
               ENDIF
               IF (INDEX.EQ.11) THEN
                  WRITE(IOUT,FMT=6200) SPLISTB(1:LENSTR(SPLISTB))
                  IF (ONLINE) WRITE(ITOUT,FMT=6200) 
     $                 SPLISTB(1:LENSTR(SPLISTB))
                  IF (ONLINE.AND.((MERIT.LE.200).OR.(SOLN.EQ.I))
     $                 .AND.WINOPEN)THEN 
                     WRITE(LLINE,FMT=6200) 
     $                    SPLISTB(1:LENSTR(SPLISTB))
                     CALL MXDWIO(LLINE, 2)
                  ENDIF
               END IF
C     
C---- Formats for outputting solutions
C     .. prefinement run first
C     .. full solution
 6000          FORMAT(1X,I3,1X,I4,5X,F5.3,1X,F4.2,2X,A,3F9.2,2X,3F6.1,
     $              3X,A)
C     .. full solution, this one not refined
 6100          FORMAT(1X,I3,1X,I4,5X,' unrefined',2X,A,3F9.2,2X,3F6.1,
     $              3X,A)
C     .. second line of hexagonal list
 6200          FORMAT(78X,A)
C     .. R or H extra line
 6300          FORMAT (28X,3F9.2,2X,3F6.1,3X,A)
C     .. NOT prefinement run
C     .. full solution
 6400          FORMAT(1X,I3,I4,5X,A,3F9.2,2X,3F6.1,3X,A)
C     .. second line of hexagonal list
 6500          FORMAT(65X,A)
C     .. R or H extra line
 6600          FORMAT(15X,3F9.2,2X,3F6.1,3X,A)
C=======================================================================
            ENDIF
         ELSE
C     
C---- MERIT.GT.200 or not a high penalty solution chosen, so not 
C     written to window
C     
c     dms21.09.2004   Special format for rhombohedral.
            IF (INDEX.EQ.12) THEN
               IF (ICRYST.EQ.8) THEN
                  WRITE(IOUT,FMT=6100) I,MERIT,BT,
     +                 (CELLB(K),K=1,6),SPLISTR
                  IF (ONLINE) WRITE(ITOUT,FMT=6100)I,MERIT,
     +                 BT,(CELLB(K),K=1,6),SPLISTR
                  WRITE (IOUT,FMT=6300) (SAVHCELL(K),K=1,6),
     $                 SPLIST(1:LENSTR(SPLIST))
                  IF (ONLINE) WRITE (ITOUT,FMT=6300)
     $                 (SAVHCELL(K),K=1,6),
     $                 SPLIST(1:LENSTR(SPLIST))
               ELSE
                  WRITE(IOUT,FMT=6100) I,MERIT,BT,
     +                 (CELLB(K),K=1,6),
     $                 SPLIST(1:LENSTR(SPLIST))
                  IF (ONLINE) WRITE(ITOUT,FMT=6100)I,MERIT,
     +                 BT,(CELLB(K),K=1,6),
     $                 SPLIST(1:LENSTR(SPLIST))
                  CALL MATCOPF(CELLCH,CELLB,6,1)
                  CALL CONRHO(1,6,CELLCH)
                  WRITE (IOUT,FMT=6300) (CELLCH(K),K=1,6),SPLISTR
                  IF (ONLINE) WRITE (ITOUT,FMT=6300)
     $                 (CELLCH(K),K=1,6),SPLISTR
               ENDIF
            ELSE
               WRITE(IOUT,FMT=6100) I,MERIT,
     $              BT,
     +              (CELLB(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
               IF (ONLINE) WRITE(ITOUT,FMT=6100)I,MERIT,
     +              BT,(CELLB(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
               IF (INDEX.EQ.11) THEN
                  WRITE(IOUT,FMT=6200) SPLISTB(1:LENSTR(SPLISTB))
                  IF (ONLINE) WRITE(ITOUT,FMT=6200) 
     $                 SPLISTB(1:LENSTR(SPLISTB))
               ENDIF
            ENDIF
         ENDIF
      ELSE
C     
C---- output mode if not refining solutions
C     
         IF (INDEX.EQ.12) THEN
            IF (ICRYST.EQ.8) THEN
               WRITE(IOUT,FMT=6400) I,MERIT,BT,
     +              (CELLB(K),K=1,6),SPLISTR
               IF (ONLINE) WRITE(ITOUT,FMT=6400) I,MERIT,
     +              BT,(CELLB(K),K=1,6),SPLISTR
               WRITE (IOUT,FMT=6600) (SAVHCELL(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
               IF (ONLINE) WRITE (ITOUT,FMT=6600)
     $              (SAVHCELL(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
            ELSE
               WRITE(IOUT,FMT=6400) I,MERIT,BT,
     +              (CELLB(K),K=1,6),
     +              SPLIST(1:LENSTR(SPLIST))
               IF (ONLINE) WRITE(ITOUT,FMT=6400) I,MERIT,
     +              BT,(CELLB(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
               CALL MATCOPF(CELLCH,CELLB,6,1)
               CALL CONRHO(1,6,CELLCH)
               WRITE (IOUT,FMT=6600) (CELLCH(K),K=1,6),SPLISTR
               IF (ONLINE) WRITE (ITOUT,FMT=6600)
     $              (CELLCH(K),K=1,6),SPLISTR
            ENDIF
         ELSE
            
            WRITE(IOUT,FMT=6400) I,MERIT,
     +           BT,(CELLB(K),K=1,6),
     +           SPLIST(1:LENSTR(SPLIST))
            IF (ONLINE) WRITE(ITOUT,FMT=6400) I,MERIT,
     +           BT,(CELLB(K),K=1,6),
     $           SPLIST(1:LENSTR(SPLIST))
         ENDIF
         IF(.NOT.USERCELL.AND.ONLINE.AND.((MERIT.LE.200).OR.
     $        (SOLN.EQ.THISONE)).AND.WINOPEN)THEN
c     dms21.09.2004   Special format for rhombohedral.
            IF (INDEX.EQ.12) THEN
               IF (ICRYST.EQ.8) THEN
                  WRITE(LLINE,FMT=6400) I,MERIT,
     +                 BT,(CELLB(K),K=1,6),SPLISTR
                  CALL MXDWIO(LLINE, 2)
                  WRITE (LLINE,FMT=6600) (SAVHCELL(K),K=1,6),
     $                 SPLIST(1:LENSTR(SPLIST))
                  CALL MXDWIO(LLINE, 2)
               ELSE
                  WRITE(LLINE,FMT=6400) I,MERIT,
     +                 BT,(CELLB(K),K=1,6),
     $                 SPLIST(1:LENSTR(SPLIST))
                  CALL MXDWIO(LLINE, 2)
                  CALL MATCOPF(CELLCH,CELLB,6,1)
                  CALL CONRHO(1,6,CELLCH)
                  WRITE (LLINE,FMT=6600) (CELLCH(K),K=1,6),SPLISTR
                  CALL MXDWIO(LLINE, 2)
               ENDIF
            ELSE
               WRITE(LLINE,FMT=6400) I,MERIT,
     +              BT,(CELLB(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
               CALL MXDWIO(LLINE, 2)
            ENDIF
         ENDIF
         IF (INDEX.EQ.11) THEN
            WRITE(IOUT,FMT=6500) SPLISTB(1:LENSTR(SPLISTB))
            IF (ONLINE) WRITE(ITOUT,FMT=6500)
     $           SPLISTB(1:LENSTR(SPLISTB))
            IF(USERCELL)THEN
            ELSE
               IF (ONLINE.AND.((MERIT.LE.200).or.(soln.eq.THISONE))
     $              .AND.WINOPEN)THEN
                  WRITE(LLINE,FMT=6500) 
     $                 SPLISTB(1:LENSTR(SPLISTB))
                  CALL MXDWIO(LLINE, 2)
               ENDIF
            ENDIF
         ENDIF
      ENDIF
      ELSE
C also output distortion index
      IF(PREREF)THEN
         IF((MERIT.LE.200).OR.(SOLN.EQ.I))THEN
c     dms21.09.2004   Special format for rhombohedral. 
            IF (INDEX.EQ.12) THEN
               IF (ICRYST.EQ.8) THEN
c     end of cdms insertion
                  WRITE(IOUT,FMT=7000) I,MERIT,DENDISIND,SDMM,FRAC,
     +                 BT,(CELLB(K),K=1,6),SPLISTR
                  IF (ONLINE) WRITE(ITOUT,FMT=7000)I,MERIT,DENDISIND,
     +                 SDMM,FRAC,BT,(CELLB(K),K=1,6),SPLISTR
                  IF (ONLINE.AND.WINOPEN) THEN
                     WRITE(LLINE,FMT=7000)I,
     +                    MERIT,DENDISIND,SDMM,FRAC,BT,
     +                    (CELLB(K),K=1,6),SPLISTR
                     CALL MXDWIO(LLINE,2)
                  ENDIF
                  WRITE (IOUT,FMT=7300) (SAVHCELL(K),K=1,6),
     +                 SPLIST(1:LENSTR(SPLIST))
                  IF(ONLINE)WRITE(ITOUT,FMT=7300)(SAVHCELL(K),K=1,6),
     +                 SPLIST(1:LENSTR(SPLIST))
                  IF (ONLINE.AND.WINOPEN)THEN
                     WRITE (LLINE,FMT=7300) 
     $                    (SAVHCELL(K),K=1,6),
     +                    SPLIST(1:LENSTR(SPLIST))
                     CALL MXDWIO(LLINE,2)
                  ENDIF
               ELSE
                  WRITE(IOUT,FMT=7000) I,MERIT,DENDISIND,SDMM,FRAC,
     +                 BT,(CELLB(K),K=1,6),
     +                 SPLIST(1:LENSTR(SPLIST))
                  IF (ONLINE) WRITE(ITOUT,FMT=7000)I,MERIT,DENDISIND,
     +                 SDMM,FRAC,BT,(CELLB(K),K=1,6),
     +                 SPLIST(1:LENSTR(SPLIST))
                  IF (ONLINE.AND.WINOPEN) THEN
                     WRITE(LLINE,FMT=7000)I,MERIT,DENDISIND,SDMM,
     +                   FRAC,BT,(CELLB(K),K=1,6),
     $                   SPLIST(1:LENSTR(SPLIST))
                     CALL MXDWIO(LLINE,2)
                  ENDIF
                  CALL MATCOPF(CELLCH,CELLB,6,1)
                  CALL CONRHO(1,6,CELLCH)
                  WRITE (IOUT,FMT=7300) (CELLCH(K),K=1,6),SPLISTR
                  IF(ONLINE)WRITE (ITOUT,FMT=7300) (CELLCH(K),K=1,6),
     $                 SPLISTR
                  IF(ONLINE.AND.WINOPEN)THEN
                    WRITE (LLINE,FMT=7300) (CELLCH(K),K=1,6),
     $                 SPLISTR
                    CALL MXDWIO(LLINE,2)
                  ENDIF
               ENDIF
            ELSE
               WRITE(IOUT,FMT=7000) I,MERIT,DENDISIND,
     $              SDMM,FRAC,BT,
     +              (CELLB(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
               IF (ONLINE) WRITE(ITOUT,FMT=7000)I,MERIT,DENDISIND,
     $              SDMM,FRAC,
     +              BT,(CELLB(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
               IF (ONLINE.AND.WINOPEN) THEN
                  WRITE(LLINE,FMT=7000)I,
     +                 MERIT,DENDISIND,
     $                 SDMM,FRAC,BT,(CELLB(K),K=1,6),
     $                 SPLIST(1:LENSTR(SPLIST))
                  CALL MXDWIO(LLINE, 2)
               ENDIF
               IF (INDEX.EQ.11) THEN
                  WRITE(IOUT,FMT=7200) SPLISTB(1:LENSTR(SPLISTB))
                  IF (ONLINE) WRITE(ITOUT,FMT=7200) 
     $                 SPLISTB(1:LENSTR(SPLISTB))
                  IF (ONLINE.AND.((MERIT.LE.200).OR.(SOLN.EQ.I))
     $                 .AND.WINOPEN)THEN 
                     WRITE(LLINE,FMT=7200) 
     $                    SPLISTB(1:LENSTR(SPLISTB))
                     CALL MXDWIO(LLINE, 2)
                  ENDIF
               END IF
C     
C---- Formats for outputting solutions
C     .. prefinement run first
C     .. full solution
 7000          FORMAT(1X,I3,1X,I4,2X,F6.2,3X,F5.3,1X,F4.2,2X,A,3F9.2,
     $              2X,3F6.1,3X,A)
C     .. full solution, this one not refined
 7100          FORMAT(1X,I3,1X,I4,1X,F6.2,4X,' unrefined',2X,A,3F9.2,
     $              2X,3F6.1,3X,A)
C     .. second line of hexagonal list
 7200          FORMAT(84X,A)
C     .. R or H extra line
 7300          FORMAT (34X,3F9.2,2X,3F6.1,3X,A)
C     .. NOT prefinement run
C     .. full solution
 7400          FORMAT(1X,I3,I4,2X,F6.2,4X,A,3F9.2,2X,3F6.1,3X,A)
C     .. second line of hexagonal list
 7500          FORMAT(72X,A)
C     .. R or H extra line
 7600          FORMAT(22X,3F9.2,2X,3F6.1,3X,A)
C=======================================================================
            ENDIF
         ELSE
C     
C---- MERIT.GT.200 or not a high penalty solution chosen, so not 
C     written to window
C     
c     dms21.09.2004   Special format for rhombohedral.
            IF (INDEX.EQ.12) THEN
               IF (ICRYST.EQ.8) THEN
                  WRITE(IOUT,FMT=7100) I,MERIT,DENDISIND,BT,
     +                 (CELLB(K),K=1,6),SPLISTR
                  IF (ONLINE) WRITE(ITOUT,FMT=7100)I,MERIT,DENDISIND,
     +                 BT,(CELLB(K),K=1,6),SPLISTR
                  WRITE (IOUT,FMT=7300) (SAVHCELL(K),K=1,6),
     $                 SPLIST(1:LENSTR(SPLIST))
                  IF (ONLINE) WRITE (ITOUT,FMT=7300)
     $                 (SAVHCELL(K),K=1,6),
     $                 SPLIST(1:LENSTR(SPLIST))
               ELSE
                  WRITE(IOUT,FMT=7100) I,MERIT,DENDISIND,BT,
     +                 (CELLB(K),K=1,6),
     $                 SPLIST(1:LENSTR(SPLIST))
                  IF (ONLINE) WRITE(ITOUT,FMT=7100)I,MERIT,DENDISIND,
     +                 BT,(CELLB(K),K=1,6),
     $                 SPLIST(1:LENSTR(SPLIST))
                  CALL MATCOPF(CELLCH,CELLB,6,1)
                  CALL CONRHO(1,6,CELLCH)
                  WRITE (IOUT,FMT=7300) (CELLCH(K),K=1,6),SPLISTR
                  IF (ONLINE) WRITE (ITOUT,FMT=7300)
     $                 (CELLCH(K),K=1,6),SPLISTR
               ENDIF
            ELSE
               WRITE(IOUT,FMT=7100) I,MERIT,DENDISIND,
     $              BT,
     +              (CELLB(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
               IF (ONLINE) WRITE(ITOUT,FMT=7100)I,MERIT,DENDISIND,
     +              BT,(CELLB(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
               IF (INDEX.EQ.11) THEN
                  WRITE(IOUT,FMT=7200) SPLISTB(1:LENSTR(SPLISTB))
                  IF (ONLINE) WRITE(ITOUT,FMT=7200) 
     $                 SPLISTB(1:LENSTR(SPLISTB))
               ENDIF
            ENDIF
         ENDIF
      ELSE
C     
C---- output mode if not refining solutions
C     
         IF (INDEX.EQ.12) THEN
            IF (ICRYST.EQ.8) THEN
               WRITE(IOUT,FMT=7400) I,MERIT,DENDISIND,BT,
     +              (CELLB(K),K=1,6),SPLISTR
               IF (ONLINE) WRITE(ITOUT,FMT=7400) I,MERIT,
     +              DENDISIND,BT,(CELLB(K),K=1,6),SPLISTR
               WRITE (IOUT,FMT=7600) (SAVHCELL(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
               IF (ONLINE) WRITE (ITOUT,FMT=7600)
     $              (SAVHCELL(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
            ELSE
               WRITE(IOUT,FMT=7400) I,MERIT,DENDISIND,BT,
     +              (CELLB(K),K=1,6),
     +              SPLIST(1:LENSTR(SPLIST))
               IF (ONLINE) WRITE(ITOUT,FMT=7400) I,MERIT,
     +              DENDISIND,BT,(CELLB(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
               CALL MATCOPF(CELLCH,CELLB,6,1)
               CALL CONRHO(1,6,CELLCH)
               WRITE (IOUT,FMT=7600) (CELLCH(K),K=1,6),SPLISTR
               IF (ONLINE) WRITE (ITOUT,FMT=7600)
     $              (CELLCH(K),K=1,6),SPLISTR
            ENDIF
         ELSE
            
            WRITE(IOUT,FMT=7400) I,MERIT,DENDISIND,
     +           BT,(CELLB(K),K=1,6),
     +           SPLIST(1:LENSTR(SPLIST))
            IF (ONLINE) WRITE(ITOUT,FMT=7400) I,MERIT,
     +           DENDISIND,BT,(CELLB(K),K=1,6),
     $           SPLIST(1:LENSTR(SPLIST))
         ENDIF
         IF(.NOT.USERCELL.AND.ONLINE.AND.((MERIT.LE.200).OR.
     $        (SOLN.EQ.THISONE)).AND.WINOPEN)THEN
c     dms21.09.2004   Special format for rhombohedral.
            IF (INDEX.EQ.12) THEN
               IF (ICRYST.EQ.8) THEN
                  WRITE(LLINE,FMT=7400) I,MERIT,DENDISIND,
     +                 BT,(CELLB(K),K=1,6),SPLISTR
                  CALL MXDWIO(LLINE, 2)
                  WRITE (LLINE,FMT=7600) (SAVHCELL(K),K=1,6),
     $                 SPLIST(1:LENSTR(SPLIST))
                  CALL MXDWIO(LLINE, 2)
               ELSE
                  WRITE(LLINE,FMT=7400) I,MERIT,DENDISIND,
     +                 BT,(CELLB(K),K=1,6),
     $                 SPLIST(1:LENSTR(SPLIST))
                  CALL MXDWIO(LLINE, 2)
                  CALL MATCOPF(CELLCH,CELLB,6,1)
                  CALL CONRHO(1,6,CELLCH)
                  WRITE (LLINE,FMT=7600) (CELLCH(K),K=1,6),SPLISTR
                  CALL MXDWIO(LLINE, 2)
               ENDIF
            ELSE
               WRITE(LLINE,FMT=7400) I,MERIT,DENDISIND,
     +              BT,(CELLB(K),K=1,6),
     $              SPLIST(1:LENSTR(SPLIST))
               CALL MXDWIO(LLINE, 2)
            ENDIF
         ENDIF
         IF (INDEX.EQ.11) THEN
            WRITE(IOUT,FMT=7500) SPLISTB(1:LENSTR(SPLISTB))
            IF (ONLINE) WRITE(ITOUT,FMT=7500)
     $           SPLISTB(1:LENSTR(SPLISTB))
            IF(USERCELL)THEN
            ELSE
               IF (ONLINE.AND.((MERIT.LE.200).or.(soln.eq.THISONE))
     $              .AND.WINOPEN)THEN
                  WRITE(LLINE,FMT=7500) 
     $                 SPLISTB(1:LENSTR(SPLISTB))
                  CALL MXDWIO(LLINE, 2)
               ENDIF
            ENDIF
         ENDIF
      ENDIF
      ENDIF
      RETURN
      END
      
C $Id: sortpart.f,v 1.5 2011/06/27 12:51:14 andrew Exp $
      SUBROUTINE SORTPART(COUNTJ,FXYHKL,IXYHKL,FPARTS,IPARTS,
     +                    NPARTS,FRACTOT)
      IMPLICIT NONE
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C IPARTS  = array for the integer parts(Image number, MPART)
C IXYHKL  = array to hold the indices (H, K, L)
C FPARTS  = array to hold the real parts (I, SIGMAI, FRcalc)
C FXYHKL  = array to hold the film co-ordinates in mm & PHIW (X, Y, PHI and 
C PHIwidth)
      INTEGER   IPARTS(4,MGRA,NGRA),IXYHKL(3,MGRA),NPARTS(MGRA)
      REAL      FPARTS(MGRA,NGRA),FXYHKL(5,MGRA),FRACTOT(MGRA)
      integer i,j,k,COUNTJ
      INTEGER iwksp(MGRA),iiwksp(MGRA)
      INTEGER HKANDL(MGRA)
      REAL wksp(MGRA)
C    USES indexx
C
C First we combine the H,K and L so that we can sort in one step; 
C this should pretty well sort on H first, then K and then L 
C
      DO 10 J=1,COUNTJ,1
         HKANDL(J) = 1000*(IXYHKL(1,J)*1000+IXYHKL(2,J))+
     $        IXYHKL(3,J)
c         if(j.le.20)print*,IXYHKL(1,J),IXYHKL(2,J),IXYHKL(3,J),HKANDL(J)
 10   CONTINUE
      call sortup4(COUNTJ,HKANDL,iwksp)
C
C sorting X and Y coordinate, Phi, phi width and background ratio fields
C
      DO 120 I=1,5,1
         DO 110 J=1,COUNTJ
            WKSP(J)=FXYHKL(I,J)
 110     CONTINUE
         DO 115 J=1,COUNTJ
            FXYHKL(I,J)=WKSP(IWKSP(J))
 115     CONTINUE
 120  CONTINUE
C
C sorting H,K,L fields
C
      do 140 i=1,3,1
         do 130 j=1,COUNTJ
            iiwksp(j)=ixyhkl(i,j)
 130     continue
         do 135 j=1,COUNTJ
            ixyhkl(i,j)=iiwksp(iwksp(j))
 135     continue
 140  continue
C
C sorting the intensity, sigma(I), partiality  fields
C
chrp02071999      do 170 i=1,3,1
         DO 160 j=1,NGRA,1
            do 150 k=1,COUNTJ
               wksp(k)=FPARTS(k,j)
 150        CONTINUE
            do 155 k=1,COUNTJ
               FPARTS(k,j)=wksp(iwksp(k))
 155        CONTINUE
 160     CONTINUE
chrp02071999 170  continue
C
C sorting MPART and image number fields
C
      DO 200 I=1,4,1
         DO 190 J=1,NGRA,1
            DO 180 K=1,COUNTJ
               IIWKSP(K)=IPARTS(I,K,J)
 180        CONTINUE
            DO 185 K=1,COUNTJ
               IPARTS(I,K,J)=IIWKSP(IWKSP(K))
 185        CONTINUE
 190     CONTINUE
 200  CONTINUE
C
C---- Sorting the NPARTS and FRACTOT fields
C
      DO 220 I = 1,COUNTJ
        IIWKSP(I) = NPARTS(I)
        WKSP(I) = FRACTOT(I)
 220  CONTINUE
      DO 230 I = 1,COUNTJ
        NPARTS(I) = IIWKSP(IWKSP(I))
        FRACTOT(I) = WKSP(IWKSP(I))
 230  CONTINUE
      RETURN
      END
C== SORTUP ==
C $Id: sortup2.f,v 1.2 2006/08/29 14:58:20 harry Exp $
C
C
      SUBROUTINE SORTUP2(N,A,IN)
      IMPLICIT NONE
C     ========================
C
C---- Ref:  Comm. ACM VOL.12 #3 MARCH 1969, R.C.SINGLETON
C
C---- Routine returns order of A in IN
C
C
C
C
C     .. Scalar Arguments ..
      INTEGER N
C     ..
C     .. Array Arguments ..
      INTEGER*2 A(N),IN(N)
C     ..
C     .. Local Scalars ..
      INTEGER I,IJ,J,K,L,M
      INTEGER*2 T,TT
C     ..
C     .. Local Arrays ..
      INTEGER*2 IL(16),IU(16)
C     ..
C
C
      DO 10 I = 1,N
        IN(I) = I
   10 CONTINUE
C
C
      M = 1
      I = 1
      J = N
C
   20 IF (I.GE.J) GO TO 80
   30 K = I
      IJ = (I+J)/2
      T = IN(IJ)
C
C
      IF (A(IN(I)).GT.A(T)) THEN
        IN(IJ) = IN(I)
        IN(I) = T
        T = IN(IJ)
      END IF
C
C
      L = J
      IF (A(IN(J)).GE.A(T)) GO TO 50
C
C
      IF (A(IN(J)).GE.A(IN(I))) THEN
        IN(IJ) = IN(J)
        IN(J) = T
        T = IN(IJ)
        GO TO 50
      END IF
C
      IN(IJ) = IN(I)
      IN(I) = IN(J)
      IN(J) = T
      T = IN(IJ)
      GO TO 50
C
   40 IN(L) = IN(K)
      IN(K) = TT
   50 L = L - 1
      IF (A(IN(L)).GT.A(T)) GO TO 50
      TT = IN(L)
   60 K = K + 1
      IF (A(IN(K)).LT.A(T)) GO TO 60
      IF (K.LE.L) GO TO 40
      IF ((L-I).LE. (J-K)) GO TO 70
      IL(M) = I
      IU(M) = L
      I = K
      M = M + 1
      GO TO 90
   70 IL(M) = K
      IU(M) = J
      J = L
      M = M + 1
      GO TO 90
C
   80 M = M - 1
      IF (M.EQ.0) RETURN
      I = IL(M)
      J = IU(M)
   90 IF ((J-I).GE.11) GO TO 30
      IF (I.EQ.1) GO TO 20
      I = I - 1
  100 I = I + 1
      IF (I.EQ.J) GO TO 80
      T = IN(I+1)
      IF (A(IN(I)).LE.A(T)) GO TO 100
      K = I
  110 IN(K+1) = IN(K)
      K = K - 1
      IF (A(T).LT.A(IN(K))) GO TO 110
      IN(K+1) = T
      GO TO 100
C
C
C
      END
C== SORTUP3 ==
C $Id: sortup3.f,v 1.2 2006/08/29 14:58:19 harry Exp $
      SUBROUTINE SORTUP3(N,A,B,C)
      IMPLICIT NONE
C     ===========================
C
C
C---- COMM.ACM VOL.12 #3 MARCH 1969, R.C.SINGLETON
C
C---- Note well
C     Arrays to be sorted are integer*4 (changed 2/9/94)
C
C
C
C
C     .. Scalar Arguments ..
      INTEGER N
C     ..
C     .. Array Arguments ..
      INTEGER*4 A(N),B(N),C(N)
C     ..
C     .. Local Scalars ..
      INTEGER I,IJ,J,K,L,M
      INTEGER*4 T,TT,X,Y
C     ..
C     .. Local Arrays ..
      INTEGER IL(16),IU(16)
C     ..
C
C
      M = 1
      I = 1
      J = N
   10 CONTINUE
      IF (I.GE.J) GO TO 90
   20 K = I
      IJ = (I+J)/2
      T = A(IJ)
C
C
      IF (A(I).GT.T) THEN
        A(IJ) = A(I)
        A(I) = T
        T = A(IJ)
        X = B(I)
        B(I) = B(IJ)
        B(IJ) = X
        Y = C(I)
        C(I) = C(IJ)
        C(IJ) = Y
      END IF
C
C
      L = J
      IF (A(J).GE.T) GO TO 60
C
C
      IF (A(J).GE.A(I)) THEN
        A(IJ) = A(J)
        A(J) = T
        T = A(IJ)
        X = B(IJ)
        B(IJ) = B(J)
        B(J) = X
        Y = C(IJ)
        C(IJ) = C(J)
        C(J) = Y
        GO TO 60
      END IF
C
C
      A(IJ) = A(I)
      A(I) = A(J)
      A(J) = T
      T = A(IJ)
      X = B(J)
      B(J) = B(IJ)
      B(IJ) = B(I)
      B(I) = X
      Y = C(J)
      C(J) = C(IJ)
      C(IJ) = C(I)
      C(I) = Y
      GO TO 60
   50 A(L) = A(K)
      A(K) = TT
      X = B(L)
      B(L) = B(K)
      B(K) = X
      Y = C(L)
      C(L) = C(K)
      C(K) = Y
   60 L = L - 1
      IF (A(L).GT.T) GO TO 60
      TT = A(L)
   70 K = K + 1
      IF (A(K).LT.T) GO TO 70
      IF (K.LE.L) GO TO 50
C
C
      IF ((L-I).GT. (J-K)) THEN
        IL(M) = I
        IU(M) = L
        I = K
        M = M + 1
        GO TO 100
      END IF
C
C
      IL(M) = K
      IU(M) = J
      J = L
      M = M + 1
      GO TO 100
   90 M = M - 1
      IF (M.EQ.0) RETURN
      I = IL(M)
      J = IU(M)
  100 CONTINUE
      IF ((J-I).GE.11) GO TO 20
      IF (I.EQ.1) GO TO 10
      I = I - 1
  110 I = I + 1
      IF (I.EQ.J) GO TO 90
      T = A(I+1)
      IF (A(I).LE.T) GO TO 110
      X = B(I+1)
      Y = C(I+1)
      K = I
  120 A(K+1) = A(K)
      B(K+1) = B(K)
      C(K+1) = C(K)
      K = K - 1
      IF (T.LT.A(K)) GO TO 120
      A(K+1) = T
      B(K+1) = X
      C(K+1) = Y
      GO TO 110
      END
C== SORTUP4 ==
C $Id: sortup4.f,v 1.3 2009/04/29 10:41:08 harry Exp $
      SUBROUTINE SORTUP4(N,A,IN)
      IMPLICIT NONE
C     ========================
C   This is identical to SORTUP except that both arrays are I*4 rather than
C   I*2.
C
C---- Ref:  Comm. ACM VOL.12 #3 MARCH 1969, R.C.SINGLETON
C
C---- Routine returns order of A in IN
C
C
C
C
C     .. Scalar Arguments ..
      INTEGER N
C     ..
C     .. Array Arguments ..
      INTEGER A(N),IN(N)
C     ..
C     .. Local Scalars ..
      INTEGER I,IJ,J,K,L,M,T,TT
C     ..
C     .. Local Arrays ..
      INTEGER IL(32),IU(32)
C     ..
C
C
      DO 10 I = 1,N
        IN(I) = I
   10 CONTINUE
C
C
      M = 1
      I = 1
      J = N
C
   20 IF (I.GE.J) GO TO 80
   30 K = I
      IJ = (I+J)/2
      T = IN(IJ)
C
C
      IF (A(IN(I)).GT.A(T)) THEN
        IN(IJ) = IN(I)
        IN(I) = T
        T = IN(IJ)
      END IF
C
C
      L = J
      IF (A(IN(J)).GE.A(T)) GO TO 50
C
C
      IF (A(IN(J)).GE.A(IN(I))) THEN
        IN(IJ) = IN(J)
        IN(J) = T
        T = IN(IJ)
        GO TO 50
      END IF
C
      IN(IJ) = IN(I)
      IN(I) = IN(J)
      IN(J) = T
      T = IN(IJ)
      GO TO 50
C
   40 IN(L) = IN(K)
      IN(K) = TT
   50 L = L - 1
      IF (A(IN(L)).GT.A(T)) GO TO 50
      TT = IN(L)
   60 K = K + 1
      IF (A(IN(K)).LT.A(T)) GO TO 60
      IF (K.LE.L) GO TO 40
      IF ((L-I).LE. (J-K)) GO TO 70
      IL(M) = I
      IU(M) = L
      I = K
      M = M + 1
      GO TO 90
   70 IL(M) = K
      IU(M) = J
      J = L
      M = M + 1
      GO TO 90
C
   80 M = M - 1
      IF (M.EQ.0) RETURN
      I = IL(M)
      J = IU(M)
   90 IF ((J-I).GE.11) GO TO 30
      IF (I.EQ.1) GO TO 20
      I = I - 1
  100 I = I + 1
      IF (I.EQ.J) GO TO 80
      T = IN(I+1)
      IF (A(IN(I)).LE.A(T)) GO TO 100
      K = I
  110 IN(K+1) = IN(K)
      K = K - 1
      IF (A(T).LT.A(IN(K))) GO TO 110
      IN(K+1) = T
      GO TO 100
C
C
C
      END
C== SORTUP5 ==
C $Id: sortup5.f,v 1.2 2006/08/29 14:58:19 harry Exp $
      SUBROUTINE SORTUP5(N,A,IN)
      IMPLICIT NONE
C     ========================
C   This is identical to SORTUP4 except that array to be sorted is real
C
C---- Ref:  Comm. ACM VOL.12 #3 MARCH 1969, R.C.SINGLETON
C
C---- Routine returns order of A in IN
C
C
C
C
C     .. Scalar Arguments ..
      INTEGER N
C     ..
C     .. Array Arguments ..
      REAL A(N)
      INTEGER IN(N)
C     ..
C     .. Local Scalars ..
      INTEGER I,IJ,J,K,L,M,T,TT
C     ..
C     .. Local Arrays ..
      INTEGER IL(16),IU(16)
C     ..
C
C
      DO 10 I = 1,N
        IN(I) = I
   10 CONTINUE
C
C
      M = 1
      I = 1
      J = N
C
   20 IF (I.GE.J) GO TO 80
   30 K = I
      IJ = (I+J)/2
      T = IN(IJ)
C
C
      IF (A(IN(I)).GT.A(T)) THEN
        IN(IJ) = IN(I)
        IN(I) = T
        T = IN(IJ)
      END IF
C
C
      L = J
      IF (A(IN(J)).GE.A(T)) GO TO 50
C
C
      IF (A(IN(J)).GE.A(IN(I))) THEN
        IN(IJ) = IN(J)
        IN(J) = T
        T = IN(IJ)
        GO TO 50
      END IF
C
      IN(IJ) = IN(I)
      IN(I) = IN(J)
      IN(J) = T
      T = IN(IJ)
      GO TO 50
C
   40 IN(L) = IN(K)
      IN(K) = TT
   50 L = L - 1
      IF (A(IN(L)).GT.A(T)) GO TO 50
      TT = IN(L)
   60 K = K + 1
      IF (A(IN(K)).LT.A(T)) GO TO 60
      IF (K.LE.L) GO TO 40
      IF ((L-I).LE. (J-K)) GO TO 70
      IL(M) = I
      IU(M) = L
      I = K
      M = M + 1
      GO TO 90
   70 IL(M) = K
      IU(M) = J
      J = L
      M = M + 1
      GO TO 90
C
   80 M = M - 1
      IF (M.EQ.0) RETURN
      I = IL(M)
      J = IU(M)
   90 IF ((J-I).GE.11) GO TO 30
      IF (I.EQ.1) GO TO 20
      I = I - 1
  100 I = I + 1
      IF (I.EQ.J) GO TO 80
      T = IN(I+1)
      IF (A(IN(I)).LE.A(T)) GO TO 100
      K = I
  110 IN(K+1) = IN(K)
      K = K - 1
      IF (A(T).LT.A(IN(K))) GO TO 110
      IN(K+1) = T
      GO TO 100
C
C
C
      END
C $Id: spbdread.f,v 1.6 2018/07/18 12:31:06 andrew Exp $
      SUBROUTINE SPBDREAD(ODBOX,IBUF,LEN)
      IMPLICIT NONE
C
C---- routine to read profiles from SPOTOD in chunks using QREAD; this
C     is the initial slow version which reads one reflection profile at
C     a time. 
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C     ..
C     .. Scalar Arguments
      INTEGER LEN
C     ..
C     .. Array Arguments
      INTEGER*2 ODBOX(MAXBOX),IBUF(12)
C     ..
C     .. Local Arrays
      INTEGER*2 LENIIBUF(14)
C     ..
C     .. Local Scalars
      INTEGER I,J,LLEN,IERR,NCMITM
      INTEGER*2 I2LEN(2)
C     ..
C     .. Include files
C&&*&& include  ../inc/ioo.f
C
C $Id: ioo.f,v 1.9 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  ioo.h
C---- START of include file ioo.h
C
C
C
C     .. Scalars in common block /IOO/ ..
      INTEGER IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,ISUMMR,
     +        ICOORD,SERVERFD,SERVERFDIN,NSHUTERR,dnafd
      LOGICAL ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,
     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C&&*&& include  ../inc/pel.f
C     **** This is the IMAGE PLATE version of this common block ****
C
C
C---- START of include file pel.h
C
C
C     .. Scalars in common blocks /PEL/ and /PELC/ ..
      INTEGER IBA,IPOINT,ISTART
      LOGICAL INCORE
C     ..
C     .. Arrays in common blocks /PEL/ and /PELC/ ..
      LOGICAL RDSTRIP
      INTEGER*2 BOXOD,IMAGE,IMAGE2
C     ..
C     .. Common Blocks /PEL/ and /PELC/ ..
      COMMON /PEL/IBA,IPOINT,INCORE,RDSTRIP(IXWDTH),BOXOD(MAXBOX),
     +            ISTART
      COMMON /PELC/ IMAGE(IYLENGTH*IXWDTH),IMAGE2(4400*4400)
C     ..
C
C
C---- END of include file pel.h
C
C&&*&& end_include  ../inc/pel.f
C     ..
C     .. Equivalences
      EQUIVALENCE (LLEN,I2LEN(1))
C
C     .. external routines
      EXTERNAL QMODE,QREADI2
C
      CALL QMODE(INMO,1,NCMITM)
      CALL QREADI2(INMO,LENIIBUF,14,IERR)
      I2LEN(1) = LENIIBUF(1)
      I2LEN(2) = LENIIBUF(2)
      LEN = LLEN
      DO 20 J = 1,12
        IBUF(J) = LENIIBUF(J+2)
 20   ENDDO
C     ************************
      CALL QREADI2(INMO,ODBOX(1),LEN,IERR)
C     ************************
      RETURN
      END

