     $     NODISPLAY,LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,
     $     XMLOPEN,SOCKLOPHIPROF
      CHARACTER dna_image*80,xmlfile*80
C     ..
C     .. Common block /IOO/ ..
c      COMMON /IOO/IOUT,IUNIT,ONLINE,ITIN,ITOUT,INOD,INMO,IDU,NWRN,
c     +            ONEFILE,FHEADER,BRIEF,IBRIEF,GRAPH,ISUMMR,ICOORD,
c     +            IOERR,NODISPLAY,LBELL
C     ..
C
C
      COMMON /IOO/IOUT,IUNIT,ITIN,ITOUT,INOD,INMO,IDU,NWRN,IBRIEF,
     +        ISUMMR,ICOORD,SERVERFD,SERVERFDIN,NSHUTERR, dnafd, 
     +        ONLINE,ONEFILE,FHEADER,BRIEF,GRAPH,IOERR,NODISPLAY,
     $        LBELL,JPGOUT,SOCKLO,LBEST,dnaout,INMOOPEN,XMLOPEN,
     +        SOCKLOPHIPROF
      COMMON /CIOO/dna_image,xmlfile

C&&*&& end_include  ../inc/ioo.f
C&&*&& include  ../inc/pel.f
C     **** This is the IMAGE PLATE version of this common block ****
C
C
C---- START of include file pel.h
C
C
C     .. Scalars in common blocks /PEL/ and /PELC/ ..
      INTEGER IBA,IPOINT,ISTART
      LOGICAL INCORE
C     ..
C     .. Arrays in common blocks /PEL/ and /PELC/ ..
      LOGICAL RDSTRIP
      INTEGER*2 BOXOD,IMAGE,IMAGE2
C     ..
C     .. Common Blocks /PEL/ and /PELC/ ..
      COMMON /PEL/IBA,IPOINT,INCORE,RDSTRIP(IXWDTH),BOXOD(MAXBOX),
     +            ISTART
      COMMON /PELC/ IMAGE(IYLENGTH*IXWDTH),IMAGE2(4400*4400)
C     ..
C
C
C---- END of include file pel.h
C
C&&*&& end_include  ../inc/pel.f
C     ..
C     .. local parameters
      INTEGER NCHUNK,NCMITM
      PARAMETER (NCHUNK = 1000)
      DATA FIRSTTIME /.TRUE./
      SAVE
 1000 IF(FIRSTTIME)THEN
        IBEGIN = (IXWDTH * IYLENGTH / 2) + 1
        IFINISH = IXWDTH * IYLENGTH
        ICURRENT = IBEGIN
        FIRSTTIME = .FALSE.
      ENDIF
C
C---- add another profile to the second half of the IMAGE array
C     
      ICOUNT = ICURRENT+14+L
      IF((ICOUNT).LE.IFINISH)THEN
        CALL RECPACK(LENGTH,L)
        IMAGE(ICURRENT) = LENGTH(1)
        IMAGE(ICURRENT+1) = LENGTH(2)
        ICURRENT = ICURRENT + 1
        DO 100 I = 1,12,1
          IMAGE(ICURRENT+I) = IA(I)
 100    ENDDO
        ICURRENT = ICURRENT + 12
        DO 200 I = 1,L,1
          IMAGE(ICURRENT+I) = IB(I)
 200    ENDDO
        ICURRENT = ICOUNT
      ENDIF
C
C---- If we have NCHUNK profiles to write, _or_ if this is the last spot
C     profile from this image _or_ we have somehow filled up the IMAGE
C     array, write to SPOTOD now.
C 
      IF((MOD(INDF,NCHUNK).EQ.0).OR.(INDF.GE.NREF).OR.
     $     ((ICOUNT).GT.IFINISH))THEN
        CALL QMODE(INMO,1,NCMITM)
        CALL QWRITE(INMO,IMAGE(IBEGIN),(ICURRENT-IBEGIN))
        DO 300 I = IBEGIN,ICURRENT,1
          IMAGE(I) = 0
 300    ENDDO
        FIRSTTIME = .TRUE.
C
C---- if we have inadvertently filled up IMAGE, we have to go back to
C     the start of this routine and add the information for this spot.
C
        IF((ICOUNT).GT.IFINISH)THEN
          GOTO 1000
        ENDIF
      ENDIF
      RETURN
      END
