C     ..
C     .. Equivalences ..
C     ..
      SAVE
C
      CALLEDFROM = 'STORSPOT'
      SPWRITE = .FALSE.
C
      NSPOT = NSPOT + 1
C
C
      IF (DEBUG(29) .AND. (NSPOT.LT.NDEBUG(29))) THEN
        WRITE (IOUT,FMT=6000) NSPOT,IH,X,Y,IREASON,IFREC
        IF (ONLINE) WRITE (ITOUT,FMT=6000) NSPOT,IH,X,Y,IREASON,
     +                        IFREC
      END IF
C
C---- Check for maximum number of spots
C
      IF (NSPOT.GT.NREFLS) THEN
        IFLAG = -1
        RETURN
      ELSE
C
C---- Test spot list
C
        IF (SPWRITE)
     +    WRITE(6,*)0.01*X+100.0,0.01*Y+100.0,FRACSP,PHISP,XINTSP
        XG(NSPOT) = X
        YG(NSPOT) = Y
        IF (DUMP(8)) THEN
          FRACSP = 0.5
          PHISP = 0.5*(PHIBEG+PHIEND)
          XINTSP = 10000
          ISPOT = 10
          CALL MMTOPX(XC,YC,X,Y)
          XC = XC*0.01
          YC = YC*0.01
          IF (INVERTX) XC = NREC*RAST - XC
          WRITE(ISPOT,FMT=6010)XC,YC,FRACSP,PHISP,XINTSP
 6010     FORMAT(1X,4F8.3,F10.1)
        END IF
        IRG(NSPOT) = IREASON
        IMPARTG(NSPOT) = IREASON
        PHIOFFSET(NSPOT) = PHIOFF
        if (debug(29)) then
          write(iout,fmt=6020) nspot, phioff
          if (online) write(itout,fmt=6020) nspot, phioff
        end if
 6020   format(1x,'nspot:',I6,' phioffset',F6.2)
C
C---- Do not store the following for overlapping lattices
C
        IF (MODE.NE.3) THEN
          IMG(NSPOT) = IFREC
          PHIG(NSPOT) = PHI
          PHIWG(NSPOT) = PHIW
          FRACG(NSPOT) = FRAC
C
C---- If calculating the phi profile, store the fraction recorded for the
C     true mosaic spread rather than the inflated one, passed through 
C     common block /PHIPROFILE/
C
          IF (PHIPROF) FRACG(NSPOT) = FRACREAL
C
C---- Must set MISYMG to zero, otherwise in an interactive session if 
C     an image has been integrated MISYMG will have non-zero values
C     and after a prediction GETINDX will return the wrong indices
C
          MISYMG(NSPOT) = 0
        END IF
        DO 8 I = 1,3
          IF (ABS(IH(I)).GT.1000) THEN
            WRITE(IOUT,FMT=6001)
            IF (ONLINE) WRITE(ITOUT,FMT=6001)
             IF (BRIEF) WRITE(IBRIEF,FMT=6001)
 6001       FORMAT(/,1X,'*** FATAL ERROR ***'/,1X,'Cannot store',
     +             ' indices greater than 1000')
            NSHUTERR = 1
            WRITE(MESSAGE,FMT=60011) (IH(K),K=1,3)
60011       FORMAT('Cannot store hkl indices > 1000__nl__',
     +      'Indices are:',3I6)
             CALL SHUTDOWN(CALLEDFROM,LENSTR(CALLEDFROM))
          END IF
 8      CONTINUE
C
C---- Store indices, lattice number and initialise number of overlapping 
C     spots from other lattices.
C
        IHG(NSPOT) = IH(1)
        IKG(NSPOT) = IH(2)
        ILG(NSPOT) = IH(3)
        ILATTG(NSPOT) = ILATT
        NLATTOVLP(NSPOT) = 0        
C
C---- Flag zero level reflections for display in FLMPLOT
C
CAL        IF (IH(JUMPAX).EQ.0) IGFLAG(NSPOT) = 10
      END IF
C
C---- Format statements
C
 6000 FORMAT (1X,'REEKE...NSPOT=',I5,'  H,K,L',3I5,' IX,IY',2F13.6,
     +       '  IR,','IM',2I4)
C
C
      END
C
      SUBROUTINE STRIPSTR(STR,NCH)
C     ==========================
C
C---- STR is a string containing a number in integer or real format.
C     STR is returned with leading blanks removed.
C     NCH is returned as number of non-blank characters in STR
C
      IMPLICIT NONE
C
C
C     .. Scalar Arguments ..
      CHARACTER*(*) STR
      INTEGER NCH
C
C     ..
C     .. Local Scalars ..
      INTEGER NCHTOT,IST,I
C     ..
C     .. Local Arrays ..
C     ..
C     .. External Subroutines ..
C     ..
C     .. Intrinsic Functions ..
C     ..
C     ..
C     .. Extrinsic Functions ..
      INTEGER  LENSTR
      EXTERNAL  LENSTR
C     .. Common blocks ..
C     ..
C     .. Equivalences ..
      SAVE
C     ..
C     .. Data ..
C     ..
C
      NCHTOT = LENSTR(STR)
      DO 10 I = 1,NCHTOT
        IF (STR(I:I).NE.' ') THEN
          IST = I
          GOTO 20
        END IF
 10   CONTINUE
C
      IST = 1
 20   NCH = NCHTOT-IST+1
      STR(1:NCH) = STR(IST:NCHTOT)
      IF (NCH.LT.NCHTOT) STR(NCH+1:NCHTOT) = ' '
      RETURN
      END
      
      SUBROUTINE SUMIMG(ID,IDOLD,NIMGSUM,NIMGSUMOLD,SUMPIXMIN,
     +                  SUMPIXMAX,IREVERSE)
C     ========================================================
C
C
C     ID         Image number. 
C
C---- This routine sums images so that a JPEG of the summed images can be 
C     displayed in iMosflm. At present, it only works for Pilatus or Eiger
C     images.
C     It will sum a total of NIMGSUM images, starting at the current image
C     number (ID), to create the JPEG that is passed to iMosflm. When moving
C     to the next image in a series, the original image is subtracted and
C     the new image is added in.
C
C
C---- Several possibilities exist:
C     1. Current image is the same, only the number of images to be summed
C        has changed. In this case, simply add in or subtract the new images.
C     2. Image number has changed. Can test based on new image number and
C        number of summed images whether there will be any overlap. Depending
C        on level of overlap, either subtract old images and add new ones
C        or start from scratch.
C
C     IREVERSE   Set in this S/R, normally 0, but if preceeding rather than
C                following images have been summed, set to -1 and used in
C                GETSPOTS to calculate correct phi value for the summed images.
C
      IMPLICIT NONE
C
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
c      PARAMETER (IYLENGTH=4096)
      PARAMETER (IYLENGTH=6144)
      INTEGER MAXHEAD
      PARAMETER (MAXHEAD=5120)
      INTEGER MAXBOX
      PARAMETER (MAXBOX=3000)
      INTEGER MAXDIM
      PARAMETER (MAXDIM=41)
      INTEGER MAXPAX
      PARAMETER (MAXPAX=10000)
      INTEGER MXDOV2
      PARAMETER (MXDOV2=MAXDIM/2)
      INTEGER NEXPAND
      PARAMETER (NEXPAND=2)
      INTEGER NNLINE
      PARAMETER (NNLINE=8)
      INTEGER NMASKS
      PARAMETER (NMASKS=49)
      INTEGER MAXBUFF
      PARAMETER (MAXBUFF=42000)
      INTEGER NREFLS
      PARAMETER (NREFLS=250000)
      INTEGER MREF
      PARAMETER (MREF=6000)
      INTEGER NVECT
      PARAMETER (NVECT=10000)
      INTEGER NIMAX
      PARAMETER (NIMAX=400)
      INTEGER NREJMAX
      PARAMETER (NREJMAX=1500)
      INTEGER NSPOTS
      PARAMETER (NSPOTS=5000)
      INTEGER MCOLS
      PARAMETER (MCOLS=18)
      INTEGER MCOLSTR
      PARAMETER (MCOLSTR=6)
      INTEGER NREFSTR
C
C---- Each reflection for strategy run needs MCOLSTR I*2 words
C     plus an I*4 word for the merging
C
      PARAMETER (NREFSTR = IXWDTH*IYLENGTH/(2+MCOLSTR))
      INTEGER MBLENG,MBLINT,MBLREA
      PARAMETER (MBLENG=185,MBLINT=29,MBLREA=156)
      INTEGER NDETREF
      PARAMETER (NDETREF=400)
      INTEGER NRPAR
      PARAMETER (NRPAR=14)
      INTEGER NSEGMAX
      PARAMETER (NSEGMAX=100)
      INTEGER NSEGMAXPR
      PARAMETER (NSEGMAXPR=100)
      INTEGER MULTMAX
      PARAMETER (MULTMAX=100)
      INTEGER MAXDIFF
      PARAMETER (MAXDIFF=100)
      INTEGER NRESBIN
      PARAMETER (NRESBIN=20)
      INTEGER MXSPOT
      PARAMETER (MXSPOT=5000)      
      INTEGER MAXIMG
      PARAMETER (MAXIMG=100)      
      INTEGER NPIXBG
      PARAMETER (NPIXBG=51)
      INTEGER MXCENT
      PARAMETER (MXCENT=500)
      INTEGER    NGRA,MGRA
      PARAMETER (NGRA=100)
      PARAMETER (MGRA=50000)
      INTEGER MAXBGBOX
      PARAMETER (MAXBGBOX=500)
      INTEGER MAXNPEAKS
      PARAMETER (MAXNPEAKS=500)
      INTEGER MAXEXCL
      PARAMETER (MAXEXCL=100)
C     ..
C     ..
      INTEGER NLAUEG
      PARAMETER (NLAUEG = 44)
      INTEGER MAXLATT
      PARAMETER (MAXLATT = 10)
      INTEGER MAXIWARN
      PARAMETER (MAXIWARN = 210)
C&&*&& end_include  ../inc/parameter.f
C
C     ..
C     .. Scalar Arguments ..
      INTEGER ID,IDOLD,NIMGSUM,NIMGSUMOLD,SUMPIXMIN,SUMPIXMAX,IREVERSE
C
C     ..
C     .. Array Arguments ..
C     ..
C     .. Local Scalars ..
      INTEGER I,J,IDSUB,IDEXTRA,NMOD,IDLAST,NOVLP,
     +        ISUBSTART,ISUBEND,IADDSTART,IADDEND,NPIX,IVAL,IOPEN,
     +        INDENT
      REAL SUMPIX,AVGPIX
      LOGICAL SUM
      CHARACTER THIS*30,CALLED*30,COMMENT*100,STRING*10
