     +     ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,
     +     BLKSIZE
      INTEGER ISYN,IMONO,NWMAX,IPAD,NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS
C     ..
C     .. logicals in common block /REEKE/ ..
      LOGICAL LOGETA,NUREEK,LCAMCON,GENGON,FOURCIRCLE,THREECIRCLE,
     +        VERTICAL
C     ..
C     .. Common Block /REEKE/ ..
      COMMON /REEKE/RMC(3,3),AMAT(3,3),SCAXIS(3),S0(3),s0unit(3),
     $     CAMCON(8),BEAMMU(2),X1,X2,Y1,Y2,
     +     Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,DIVH,DIVV,DELAMB,
     +     ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,ISYN,IMONO,
     $     NWMAX,IPAD,
     $     NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS,LOGETA,NUREEK,LCAMCON,
     $     GENGON,FOURCIRCLE,THREECIRCLE,
     +     BLKSIZE,VERTICAL
C     ..
C
C
C&&*&& end_include  ../inc/reeke.f
      EXTERNAL LENSTR
      INTEGER  LENSTR
      EXTERNAL CELLCHK

      IERR = 0
      MATNUM = 12
      LDUM = 80
      XMLLINE = ' '
      CALL CELLCHK(ICRYST,CELL,IERR)
      IF (NUMSPG.GT.0)THEN
        IF (IERR.NE.0)THEN
C
C---- mismatch between cell and space group 
C
          WRITE(IOUT,FMT=6000) NUMSPG,SPGNAM(1:LENSTR(SPGNAM)),CELL
          IF (ONLINE) WRITE(ITOUT,FMT=6000) NUMSPG,
     $         SPGNAM(1:LENSTR(SPGNAM)),CELL
          IF (BRIEF) WRITE(IBRIEF,FMT=6000) NUMSPG,
     $         SPGNAM(1:LENSTR(SPGNAM)),CELL
          IF(SOCKLO)THEN
            XMLLINE = ' '
            WRITE(XMLLINE,FMT=7000)SPGNAM(1:LENSTR(SPGNAM)),CELL
            CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $           LENSTR(XMLLINE),XMLLINE)
          ENDIF
C
C---- cell and space group match
C
        ELSE
C     HRP 13072015 write AMAT here if valid cell, symmetry and  SOCKLO
          IF(SOCKLO)THEN
            CALL CCPDPN(MATNUM,NEWMATNAM,'UNKNOWN','F',LDUM,IERR)
            WRITE(MATNUM,FMT=6780)((AMAT(IC,JC),JC=1,3),IC=1,3),
     $           ((UMAT(IC,JC),JC=1,3),IC=1,3),CELL,SPGNAM
 6780       FORMAT(3(3F12.8,/),3(7X,'0.000'),/,3(3F12.7,/),
     $           6F12.4,/,3(7X,'0.000'),/,'SYMM ',A)
            CLOSE (UNIT=MATNUM)
          ENDIF
          WRITE(IOUT,FMT=6020) SPGNAM(1:LENSTR(SPGNAM)),CELL
          IF (ONLINE) WRITE(ITOUT,FMT=6020)
     $         SPGNAM(1:LENSTR(SPGNAM)),CELL
          IF (BRIEF) WRITE(IBRIEF,FMT=6020)
     $         SPGNAM(1:LENSTR(SPGNAM)),CELL
          IF(SOCKLO)THEN
            XMLLINE = ' '
            WRITE(XMLLINE,FMT=7020)SPGNAM(1:LENSTR(SPGNAM)),CELL
            CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $           LENSTR(XMLLINE),XMLLINE)
          ENDIF
        ENDIF
      ENDIF
C
C---- no symmetry given
C
      IF(NUMSPG.EQ.0)THEN
        WRITE(IOUT,FMT=6040)
        IF(ONLINE)WRITE(ITOUT,FMT=6040)
        IF(BRIEF)WRITE(ITOUT,FMT=6040)
        IF(SOCKLO)THEN
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7040)
          CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $         LENSTR(XMLLINE),XMLLINE)
        ENDIF
      ENDIF
C
C---- no cell given
C
      IF((CELL(1).LE.1E-3).AND.(CELL(2).LE.1E-3).AND.
     $     (CELL(3).LE.1E-3).AND.(CELL(4).LE.1E-3).AND.
     $     (CELL(5).LE.1E-3).AND.(CELL(6).LE.1E-3))THEN
        WRITE(IOUT,FMT=6060)
        IF(ONLINE)WRITE(ITOUT,FMT=6060)
        IF(BRIEF)WRITE(ITOUT,FMT=6060)
        IF(SOCKLO)THEN
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7060)
          CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $         LENSTR(XMLLINE),XMLLINE)
        ENDIF
      ELSEIF((CELL(1).LE.1E-3).OR.(CELL(2).LE.1E-3).OR.
     $     (CELL(3).LE.1E-3).OR.(CELL(4).LE.1E-3).OR.
     $     (CELL(5).LE.1E-3).OR.(CELL(6).LE.1E-3))THEN
        WRITE(IOUT,FMT=6080)
        IF(ONLINE)WRITE(ITOUT,FMT=6080)
        IF(BRIEF)WRITE(ITOUT,FMT=6080)
        IF(SOCKLO)THEN
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7080)CELL
          CALL WRITE_SOCKET_LENGTH(SERVERFD,
     $         LENSTR(XMLLINE),XMLLINE)
        ENDIF
      ENDIF
 6000 FORMAT(//,1X,'*** ERROR ***',/,1X,'Space group number ',
     +     I4,' (',A,') is inconsistent with cell',
     +     ' parameters provided.',/,1X,
     +     '(Cell:',6F10.3,')',
