     $     '</cell>',
     $     '</interface_input_response>')
 7040 FORMAT('<?xml version="1.0"?>',
     $     '<!DOCTYPE interface_input_response>',
     $     '<interface_input_response>',
     $     '<status>',
     $     '<code>error</code>',
     $     '</status>',
     $     '<message>no valid space group given</message>', 
     $     '</interface_input_response>')   
 7060 FORMAT('<?xml version="1.0"?>',
     $     '<!DOCTYPE interface_input_response>',
