     $     '<status>',
     $     '<code>error</code>',
     $     '</status>',
     $     '<message>no cell dimensions given</message>',
     $     '</interface_input_response>')    
 7080 FORMAT('<?xml version="1.0"?>',
     $     '<!DOCTYPE interface_input_response>',
