c-harvest
C&&*&& include  ../inc/mharvest.f
c      INTEGER MCOLS
C     .. Scalars in common block /CHARVEST/ ..
      CHARACTER HVERSION*100,ProjectName*64,Crystalname*64,
     +          DataSetName*64,HBEAMLINE*10,Precipitant*80,
     +          XNAME_COLS(MCOLS+MAXLATT*3)*64,
     +          DNAME_COLS(MCOLS+MAXLATT*3)*64
C     .. Scalars in common block /IHARVEST/ ..
      LOGICAL USECWD,PNAMEgiven,XNAMEgiven,DNAMEgiven,DOHARVEST
      REAL    PHhar,Hartemp,
     +     HARETA(MAXPAX),HARDIV(MAXPAX),HARDIH(MAXPAX)
      CHARACTER*3 MKDIRMODE,CHMODMODE
      INTEGER KHFLMS
C     ..
C     .. Common block /CHARVEST/ ..
      COMMON /CHARVEST/HVERSION,ProjectName,Crystalname,
     +                 DataSetName,HBEAMLINE,Precipitant,
     +                 XNAME_COLS,DNAME_COLS
C     .. Common block /IHARVEST/ ..
      COMMON /IHARVEST/USECWD,PHhar,Hartemp,KHFLMS,
     +                 PNAMEgiven,XNAMEgiven,DNAMEgiven,DOHARVEST,
     +                 HARETA,HARDIV,HARDIH,MKDIRMODE,CHMODMODE
C     ..
C&&*&& end_include  ../inc/mharvest.f
c-harvest
c
c

       IMGP = .true.
      IF (IMGP) THEN
c-harvest
C
C---- may need to name kludge so older iMosflm can run this
C
        HVERSION = 'Mosflm version 7.4.0'//
     $       ' for IP, CCD and PAD'//
     $       ' data Sep 16 2021 '
c-harvest
        if(.not.xmlopen)
     $       WRITE(IOUT,FMT=6000) HVERSION(1:lenstr(HVERSION))
        IF (ONLINE) 
     $       WRITE(ITOUT,FMT=6000) HVERSION(1:lenstr(HVERSION))
        IF(SOCKLO)THEN
          WRITE(LONGLINE,FMT=7200)HVERSION(1:lenstr(HVERSION))
 7200     FORMAT('<',A,'>')
          CALL WRITE_SOCKET_LENGTH(SERVERFD,LENSTR(LONGLINE),LONGLINE)
        ENDIF

C  socket stuff 
c  socket      IF (SOCKLO) THEN
c  socket         WRITE(IOLINE,FMT=6000) HVERSION(1:lenstr(HVERSION))
c  socket         CALL WRITE_SOCKET(SERVERFD,11,IOLINE)
c  socket      ENDIF
      ELSE
c-harvest
        HVERSION = 'Version 5.21 for Film data 10/08/93'
c-harvest
        if(.not.xmlopen)
     $       WRITE(IOUT,FMT=6001)HVERSION(1:lenstr(HVERSION))
        IF (ONLINE)
     $       WRITE(ITOUT,FMT=6001) HVERSION(1:lenstr(HVERSION))
      END IF
 6000 FORMAT(1X,'************ ',a,'  ***********'/,1X,
     +     'Andrew Leslie and Harry Powell,',
     +     ' MRC Laboratory of Molecular Biology,',/,1X,
     +     'Hills Road, Cambridge CB2 0QH, UK',/,1X,
     +     'E-mails: andrew@mrc-lmb.cam.ac.uk, ',
