      REAL SDBEAM,SDCELL,SDDELPHI,DELPHIV,SHIFT
      LOGICAL FCELL,VALSET
C
C     .. Scalars in Common /POSTCHK/ ..
C     ..
      REAL PRRES1,PRRES2,RESIDMAX,SDFAC,SHIFTMAX,SHIFTFAC,
     +     ANGWIDTH,CELLSHIFT,FRACMIN,FRACMAX,FRCSHIFT
      INTEGER PRNS,NREFPR,NADD,NRPT,IPRINTP,NPRMIN,NREFMOS
      LOGICAL USEBEAM,REFCELL,RESCALE,SMOOTHPHI
C     ..
C     .. Common block /POSTCHK/  ..
      COMMON /POSTCHK/ SDBEAM(6),SDCELL(6),SDDELPHI(2*NIMAX),
     +             DELPHIV(3*NIMAX),SHIFT(3),PRRES1,PRRES2,RESIDMAX,
     +             SDFAC,SHIFTMAX,SHIFTFAC,ANGWIDTH,CELLSHIFT, 
     $             FRACMIN,FRACMAX,FRCSHIFT,
     +             PRNS,NREFPR,NADD,NRPT,IPRINTP,
     +             NPRMIN,FCELL(6),USEBEAM,REFCELL,RESCALE,
     +             VALSET(MAXPAX),NREFMOS,SMOOTHPHI
C     ..
C
C
C&&*&& end_include  ../inc/postchk.f
C&&*&& include  ../inc/scn.f
C
C $Id: scn.f,v 1.5 2014/11/18 14:05:40 andrew Exp $
C
C--- awk generated include file  scn.h
C---- START of include file scn.h
C
C     SCNSZ   is pixel size (in microns) divided by 25
C     RAST    pixel size in slow direction in mm
C     FACT    multiplying by FACT converts from 10 micron units 
C             (the standard unit internal to the program) into pixels
C     IYLEN   The number of pixels in the Y (fastest changing) direction
C             in the digitised image.
C     NREC    The number of pixels in the X (slow) direction in the 
C             digitised image.
C     NWORD   The number of I*2 words in the Y direction.
C     NBYTE   The number of bytes in Y direction = NWORD/2
C     NHBYTE  Number of bytes in header
C
C     ICURR   When several images are stored in a single file, ICURR is the
C             pointer to the first record of the current image in the direct
C             access file (only implemented for film data)
C     NEXTRA  The number of additional (unused) bytes padding the end of
C             each record in image file
C     BYTSWAP True if the "endedness" (Big-endian/Little-endian) of the 
C             machine that MOSFLM is running on is different to that of the
C             machine on which the image was written. This is determined by
C             looking at the value of NXPIX in the header record of the
C             image file (subroutine GETHDR)
C
C     LACTIVE True if using Rigaku active mask, False if ignoring it
C     REALLYFORCEREAD True if we want to display an image where we have
C                     changed the activemask
C
C     ROWREADT Time in seconds that the detector takes to read a row of data,
C              required for rolling shutter mode readout of Tietz detector
C              used for microED.
C     ROTSPEED Spindle rotation rate (degrees per second),required for rolling
C              shutter mode readout of Tietz detector used for microED. 
C
C
C     .. Scalars in common block /SCN/ ..
      REAL FACT,SCNSZ,RAST,RASTY,ROWREADT,ROTSPEED
      INTEGER NBYTE,NREC,NWORD,IYLEN,ICURR,NEXTRA,NHBYTE
      LOGICAL BYTSWAP,LACTIVE,REALLYFORCEREAD
C     ..
C     .. Common Block /SCN/ ..
      COMMON /SCN/ FACT,SCNSZ,RAST,RASTY,ROWREADT,ROTSPEED,
     +     NBYTE,NREC,NWORD,IYLEN,
     +     ICURR,NEXTRA,NHBYTE,BYTSWAP,LACTIVE,
     $     REALLYFORCEREAD
C&&*&& end_include  ../inc/scn.f
C&&*&& include  ../inc/reeke.f
C
C $Id: reeke.f,v 1.17 2015/05/11 14:19:27 andrew Exp $
C
C--- awk generated include file  reeke.h
C---- START of include file reeke.h
C
C     TOR     For synchrotron sources, degree of polarisation of the beam
C     IMONO   Collimation flag for polarisation.
C             = 0   Pinhole or mirrors
C             = 1   Graphite Monochromator
C             = 2   Synchrotron, use TOR
C     NWMAX   Maximum reflection width in images
C     DSTMAX  dimensionless rlu, = WAVE/RES where RES is the maximum
C             resolution in Angstrom.
C     DSTMIN  dimensionless rlu, = WAVE/DMAX where DMAX is the maximum
C              Bragg spacing
C     S0      radiation source vector (-1,0,0), may be modified by MU values
C     SOURCE  radiation source vector - basis for s0
C     GONIO_angle:  machine angles for generalized goniostats
C     GONIO_angle_SET: fixed offset angles for 3- and 4-circle goniostats
C                      i.e. currently 54.74 deg for Bruker CHI, 50.0deg for
C                      Nonius and Oxford KAPPA 
C     VERTICAL Logical set TRUE if rotation axis is vertical, only
C              affects polarization correction for synchrotron data
C     NSMOOTH  Number of images to use in smoothing refined values of
C              mosaic spread and missetting angles (if being smoothed).
C     ..
C     .. Arrays in common block /REEKE/ ..
      REAL RMC,AMAT,SCAXIS,S0,s0unit,CAMCON,BEAMMU
C     ..
C     .. Scalars in common block /REEKE/ ..
      REAL X1,X2,Y1,Y2,Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,
     +     DIVH,DIVV,DELAMB,ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,
     +     ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,
     +     BLKSIZE
      INTEGER ISYN,IMONO,NWMAX,IPAD,NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS
C     ..
C     .. logicals in common block /REEKE/ ..
      LOGICAL LOGETA,NUREEK,LCAMCON,GENGON,FOURCIRCLE,THREECIRCLE,
     +        VERTICAL
C     ..
C     .. Common Block /REEKE/ ..
      COMMON /REEKE/RMC(3,3),AMAT(3,3),SCAXIS(3),S0(3),s0unit(3),
     $     CAMCON(8),BEAMMU(2),X1,X2,Y1,Y2,
     +     Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,DIVH,DIVV,DELAMB,
     +     ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,ISYN,IMONO,
     $     NWMAX,IPAD,
     $     NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS,LOGETA,NUREEK,LCAMCON,
     $     GENGON,FOURCIRCLE,THREECIRCLE,
     +     BLKSIZE,VERTICAL
C     ..
C
C
C&&*&& end_include  ../inc/reeke.f
      SAVE
C
C---- SERIOUS is set TRUE if any of the errors are considered serious
C
      SERIOUS = .FALSE.
      WORRYING = .FALSE.
      INFO = .FALSE.
      IGNORE = .TRUE.
      THIS = 'WARNINGS'
      INDENT = 2
C
C---- Sort out averaging of inner profiles
C
      IF (WARN(8).AND.(XWARN(1,8).GT.900)) THEN
C
C---- Get list of inner profiles that have been averaged
C     LIST is a string with the list of averaged inner profile numbers
C     ILIST is an array giving the number of times each of the inner
C     averaged profiles has actually been averaged.
C
        LIST = ' '
        FIRST = .TRUE.
        WORRYING = .TRUE.
        NBADAVG = 0
        NBADPROF = 0
        DO 12 I = 1,NUMBOX
          IF (IWARN(I,8).GT.0) THEN
            NBADAVG = NBADAVG + 1
            STR2 = ' '
            WRITE(STR2,FMT=6240) I
 6240       FORMAT(I2)
            IF (FIRST) THEN
              LIST = STR2
              FIRST = .FALSE.
            ELSE
              LIST = LIST(1:LENSTR(LIST))//','//STR2
            END IF
            ILIST(NBADAVG) = IWARN(I,8)
C
C---- NBADPROF counts the number of profiles where more than a quarter of
C     blocks have been averaged
C
            IF (IWARN(I,8).GT.(NBLOCK+2)/4) NBADPROF = NBADPROF + 1 
          END IF
   12   CONTINUE
        SERIOUS = (NBADPROF.GE.2)
        IF (SERIOUS) XWARN(1,8) = 9999
cal        write(iout,fmt=6666) xwarn(1,8)
cal        if (online) write(itout,fmt=6666) xwarn(1,8)
cal 6666   format(1x,'xwarn from warnings.f',F6.0)
      END IF

      IF (WINOPEN) CALL MXD_FLU(I)
C
C---- Decide if number of profiles with intruding spots is serious or worrying
C     More than 10% gives SERIOUS warning, more than 5% worrying, less than this
C     results in no warning
C
      IF (XWARN(1,36).GT.0) THEN
         FRACBADPROF = 100.0*XWARN(2,36)/XWARN(1,36)
         IF (FRACBADPROF.GT.10.0) THEN
           WARN(37) = .TRUE.
           WARN(36) = .FALSE.
         ELSE IF (FRACBADPROF.GT.5.0) THEN
           WARN(36) = .TRUE.
           WARN(37) = .FALSE.
         ELSE
           WARN(36) = .FALSE.
           WARN(37) = .FALSE.
         END IF
      END IF
C
C---- Print for program flow
C
      CALLED = 'XMLWARN'
      COMMENT = 'to write XML for warnings '
      IF (DEBUG(99)) CALL PRINTFLOW(THIS,CALLED,COMMENT,INDENT)
      IF(SOCKLO)CALL XMLWARN(NBADAVG,ILIST,LIST)
      WARNING = .FALSE.
      DO 10 I=1,50
        IF (WARN(I)) WARNING = .TRUE.
 10   CONTINUE
C
      WORRYING = (WARN(5).OR.WARN(6).OR.WARN(7).OR.
     +            (WARN(14).AND.(.NOT.TILED).AND.(NULLPIX.EQ.0))
     +           .OR.WARN(18).OR.WARN(24).OR.WARN(25).OR.WARN(29)
     +           .OR.(WARN(32).AND.(XWARN(1,32).LT.0.20))
     +           .OR.(WARN(33).OR.(WARN(36).AND.(.NOT.WARN(37))).OR.
     +           (WARN(39).AND.(XWARN(1,39).LT.0.10)))).OR.
     +           WARN(43)
cal      SERIOUS = (WARN(4).OR.(WARN(8).AND.(XWARN(1,8).GT.900))
      SERIOUS = (WARN(4)
     +           .OR.WARN(9).OR.WARN(16).OR.WARN(19)
     +           .OR.(WARN(25).AND.(XWARN(1,25).GE.0.01)).OR.WARN(30)
     +           .OR.(WARN(32).AND.(XWARN(1,32).GE.0.20)).OR.
     +               (WARN(33).AND.(XWARN(1,33).GE.0.20)).OR.
     +                WARN(34).OR.WARN(35).OR.WARN(37).OR.
     +               (WARN(39).AND.(XWARN(1,39).GE.0.10)).OR.
     +                WARN(40).OR.WARN(42).OR.WARN(44))
      INFO = (WARN(1).OR.(WARN(2).AND.IMGP).OR.WARN(3).OR.
     +        (WARN(8).AND.(XWARN(1,8).LT.1))
     +        .OR.WARN(10).OR.WARN(11).OR.(WARN(12).AND.IMGP)
     +        .OR.WARN(20).OR.(WARN(21).AND.(.NOT.DENSE))
     +        .OR.WARN(28).OR.WARN(38))
      IGNORE = (WARN(13).OR.WARN(15).OR.WARN(22)
     +        .OR.WARN(23).OR.WARN(26).OR.WARN(27))
C
C---- For information only
C
C
      IF (WARNING) THEN
        WRITE(ISUMMR,FMT=6000)
        WRITE(IOUT,FMT=6000)
        IF (ONLINE) WRITE(ITOUT,FMT=6000)
C
C---- Give serious errors first
C
        IF(NSHUTERR.NE.0)SERIOUS = .TRUE.
        IF (SERIOUS) THEN
          WRITE(IOUT,FMT=6210)
          WRITE(ISUMMR,FMT=6210)
          IF (ONLINE) WRITE(ITOUT,FMT=6210)
        ELSE
          WRITE(IOUT,FMT=6212)
          WRITE(ISUMMR,FMT=6212)
          IF (ONLINE) WRITE(ITOUT,FMT=6212)
        END IF
 6210   FORMAT(/,1X,'*** SERIOUS PROBLEMS ***',/,1X,
     +              '========================',/,1X,
     +          'The following problems may have a significant effect',
     +          ' on data quality',/,1X,'Action should be taken to ',
     +          'eliminate these warnings.')
 6212   FORMAT(/,1X,'There are no SERIOUS problems.')
        
C---- Too few spots in CENTRS
        IF (WARN(4)) THEN
          I = MIN(IWARN(1,4)+1,25)
          WRITE(ISUMMR,FMT=6008) MINREF, (IWARN(J,4),J=2,I)
          WRITE(IOUT,FMT=6008) MINREF, (IWARN(J,4),J=2,I)
          IF (ONLINE) WRITE(ITOUT,FMT=6008) MINREF, (IWARN(J,4),J=2,I)
        END IF
C---- Inner profiles have been averaged a significant number of times
        IF (WARN(8).AND.(XWARN(1,8).GT.9000)) THEN
          WRITE(ISUMMR,FMT=6009) WAVE/DSTMAX,NBADAVG,
     +         LIST(1:LENSTR(LIST)),(ILIST(I),I=1,NBADAVG)
          WRITE(IOUT,FMT=6009) WAVE/DSTMAX,NBADAVG,
     +         LIST(1:LENSTR(LIST)),(ILIST(I),I=1,NBADAVG)
          IF (ONLINE) WRITE(ITOUT,FMT=6009) WAVE/DSTMAX,NBADAVG,
     +         LIST(1:LENSTR(LIST)),(ILIST(I),I=1,NBADAVG)
        END IF
C---- BGRATIO too large or too small, suggesting incorrect GAIN
        IF (WARN(9)) THEN
          IF (IMGP) THEN
C---- Calculate the mean BGRATIO as average of max and min values.
            X = 0.5*(XWARN(1,9)+XWARN(2,9))
C
C---- Trap the case where there is a big spread in BGRATIO values
C     and the mean is actually close to 1.0 (WITHIN 0.1)
C
            IF (ABS(X-1.0).GT.0.1) THEN
              WRITE(ISUMMR,FMT=6018) XWARN(1,9),XWARN(2,9),
     +                  GAIN, GAIN*X**2
              WRITE(IOUT,FMT=6018) XWARN(1,9),XWARN(2,9),
     +                  GAIN, GAIN*X**2
              IF (ONLINE) WRITE(ITOUT,FMT=6018) XWARN(1,9),XWARN(2,9),
     +                  GAIN, GAIN*X**2
            END IF
          ELSE
            WRITE(ISUMMR,FMT=6020) XWARN(1,9),XWARN(2,9)
            WRITE(IOUT,FMT=6020) XWARN(1,9),XWARN(2,9)
            IF (ONLINE) WRITE(ITOUT,FMT=6020) XWARN(1,9),XWARN(2,9)
          END IF
        END IF
C
C---- Negative refined (mosaic spread + beam divergence)
C
        IF (WARN(16)) THEN 
          WRITE(IOUT,FMT=6046)
          IF (ONLINE) WRITE(ITOUT,FMT=6046)
          WRITE(ISUMMR,FMT=6046)
          IF (PRNS.EQ.2) THEN
            WRITE(IOUT,FMT=6048)
            IF (ONLINE) WRITE(ITOUT,FMT=6048)
            WRITE(ISUMMR,FMT=6048)
          END IF
          IF (USEBEAM) THEN
            IF (PRNS.EQ.1) THEN
              WRITE(IOUT,FMT=6050)
              IF (ONLINE) WRITE(ITOUT,FMT=6050)
              WRITE(ISUMMR,FMT=6050)
            ELSE
              WRITE(IOUT,FMT=6052)
              IF (ONLINE) WRITE(ITOUT,FMT=6052)
              WRITE(ISUMMR,FMT=6052)
            END IF
          END IF
        END IF
C
C---- Refined mosaic spread is positive but less than 0.25*(input value) 
C     and is used
C
        IF (WARN(19).AND.(.NOT.WARN(16))) THEN
          IF (PRNS.EQ.1) THEN
            WRITE(IOUT,FMT=6058)
            IF (ONLINE) WRITE(ITOUT,FMT=6058)
            WRITE(ISUMMR,FMT=6058)
CAL          ELSE IF (PRNS.EQ.2) THEN
CAL            WRITE(IOUT,FMT=6060)
CAL            IF (ONLINE) WRITE(ITOUT,FMT=6060)
CAL            WRITE(ISUMMR,FMT=6060)
          END IF
        END IF
C
C---- YSCAL wrong by more than 0.01
C
        IF (WARN(25).AND.(XWARN(1,25).GE.0.01)) THEN
          WRITE(IOUT,FMT=6096) XWARN(1,25)
          WRITE(ISUMMR,FMT=6096) XWARN(1,25)
          IF (ONLINE) WRITE(ITOUT,FMT=6096) XWARN(1,25)
        END IF
C
C---- Mosaic spread reset
C
        IF (WARN(30)) THEN
          WRITE(IOUT,FMT=6108) OVERLAPMAX
          IF (ONLINE) WRITE(ITOUT,FMT=6108) OVERLAPMAX
        END IF
C
C---- Minimum spot separation spread reset
C
        IF (WARN(31)) THEN
          WRITE(IOUT,FMT=6110) OVERLAPMAX 
          IF (ONLINE) WRITE(ITOUT,FMT=6110) OVERLAPMAX 
        END IF
C
C---- More than 20% of reflections overlapped
C
        IF (WARN(32).AND.(XWARN(1,32).GE.0.20)) THEN
          WRITE(IOUT,FMT=6112) NINT(XWARN(1,32)*100) 
          IF (ONLINE) WRITE(ITOUT,FMT=6112) NINT(XWARN(1,32)*100) 
        END IF
C
C---- Average image to image change in missets greater than 0.2
C
        IF (WARN(33).AND.(XWARN(1,33).GE.0.20)) THEN
          N = 1 + IWARN(1,33)
          WRITE(IOUT,FMT=6114) XWARN(1,33),
     +    IWARN(1,33),NBLOCK,(IWARN(J,33), J = 2,N)
          WRITE(IOUT,FMT=6115)
          IF (ONLINE) WRITE(ITOUT,FMT=6114) XWARN(1,33),
     +    IWARN(1,33),NBLOCK,(IWARN(J,33), J = 2,N)
          IF (ONLINE) WRITE(ITOUT,FMT=6115)
        END IF
C
C---- rejects an averaged standard profile
C
        IF (WARN(34)) THEN
          WRITE(IOUT,FMT=6116) IWARN(1,34),WAVE/DSTMAX
          IF (ONLINE) WRITE(ITOUT,FMT=6116) IWARN(1,34),WAVE/DSTMAX
        END IF 
C
C---- adjacent spots included in peak region of average spot profile
C     in central region of image
C
        IF (WARN(35)) THEN
          IF (IWARN(1,35).EQ.1) THEN
            WRITE(IOUT,FMT=6118) XWARN(2,35),XWARN(1,35)
            IF (ONLINE) WRITE(ITOUT,FMT=6118)XWARN(2,35),XWARN(1,35) 
          ELSE IF (IWARN(1,35).EQ.2) THEN
            WRITE(IOUT,FMT=6118) XWARN(2,35),XWARN(3,35)
C,XWARN(1,35)
            IF (ONLINE) WRITE(ITOUT,FMT=6118)XWARN(2,35),XWARN(3,35)
C     +                        XWARN(1,35)
          END IF
        END IF 
C
C---- adjacent spots included in peak region of standard profile
C
        IF (WARN(37)) THEN
          NBADBLOCK = IWARN(1,36)
          WRITE(IOUT,FMT=6120) FRACBADPROF,TOLMIN,TOL
          IF (ONLINE) WRITE(ITOUT,FMT=6120) FRACBADPROF,TOLMIN,TOL
C
C---- Numbers only stored for first 19 (array bounds limit)
C
          NBADLIMIT = MIN(NBADBLOCK,19)
          WRITE(IOUT,FMT=6122)
          IF (ONLINE) WRITE(ITOUT,FMT=6122)
          DO 30 I = 1,NBADLIMIT
C
C---- Maximum of 9 bad profiles to be listed
C
            NBADBOX = MIN(IWARN(10*I+11,36),9)
            WRITE(IOUT,FMT=6123) IWARN(I+1,36),(IWARN(10*I+11+J,36),
     +           NINT(100*XWARN(10*I+11+J,36)), J = 1,NBADBOX)
            IF (ONLINE) WRITE(ITOUT,FMT=6123) IWARN(I+1,36),
     +        (IWARN(10*I+11+J,36),NINT(100*XWARN(10*I+11+J,36)),
     +         J = 1,NBADBOX)
 30       CONTINUE
        END IF 
C
C---- More than 10% of refections too wide in phi
C
        IF (WARN(39).AND.(XWARN(1,39).GE.0.10)) THEN
          WRITE(IOUT,FMT=6132) NINT(100*XWARN(1,39)),WMAX
          IF (ONLINE) WRITE(ITOUT,FMT=6132) NINT(100*XWARN(1,39)),WMAX 
        END IF
C
C---- Cell refined stopped due to large cell shift (>10%)
C
        IF (WARN(40)) THEN
          WRITE(IOUT,FMT=6134)
          IF (ONLINE) WRITE(ITOUT,FMT=6134)
        END IF                                       
C
C---- One or more images skipped because too large positional residual
C
        IF (WARN(42)) THEN
          IF (IWARN(1,42).EQ.IWARN(100,42)) THEN
            WRITE(IOUT,FMT=6138) XWARN(1,42)
            IF (ONLINE) WRITE(ITOUT,FMT=6138) XWARN(1,42)
C
C----- All images have been rejected
C
          ELSE
            J = MIN(51,1+IWARN(1,42))
            WRITE(IOUT,FMT=6136) IWARN(1,42),XWARN(1,42),
     +                           (IWARN(I,42),I=2,J)
            IF (ONLINE) WRITE(ITOUT,FMT=6136) IWARN(1,42),XWARN(1,42),
     +                (IWARN(I,42),I=2,J)
          END IF                                       
        END IF
C
C---- More than 5% of reflections flagged in MTZ file as "EDGE'
C
        IF (WARN(44)) THEN
          WRITE(IOUT,FMT=6150) 100*XWARN(1,44),NULLPIX
          IF (ONLINE) WRITE(ITOUT,FMT=6150) 100*XWARN(1,44),NULLPIX
        END IF
C
C---- Now "WORRYING" class
C
        IF (WORRYING) THEN
          WRITE(IOUT,FMT=6220)
          WRITE(ISUMMR,FMT=6220)
          IF (ONLINE) WRITE(ITOUT,FMT=6220)
        END IF
 6220   FORMAT(//,1X,'*** PROBLEMS WORTH CONSIDERING ***',/,1X,
     +              '==================================',/,1X,
     +          'The following warnings suggest that the',
     +          ' processing might be improved',/,1X,'if ',
     +          'appropriate action is taken.')
C---- Slippage > (eta + divv)
C     Set in MOSFLM
        IF (WARN(5)) THEN
          WRITE(ISUMMR,FMT=6010) XWARN(1,5),IWARN(1,5)
          WRITE(IOUT,FMT=6010) XWARN(1,5),IWARN(1,5)
          IF (ONLINE) WRITE(ITOUT,FMT=6010) XWARN(1,5),IWARN(1,5)
        END IF
C---- Weighted residual > 1.5
        IF (WARN(6)) THEN
          WRITE(ISUMMR,FMT=6012) XWARN(1,6)
          WRITE(IOUT,FMT=6012) XWARN(1,6)
          IF (ONLINE) WRITE(ITOUT,FMT=6012) XWARN(1,6)
        END IF
C---- Too many badspots (>10)
        IF (WARN(7)) THEN
          WRITE(ISUMMR,FMT=6014) IWARN(1,7)
          WRITE(IOUT,FMT=6014)  IWARN(1,7)
          IF (ONLINE) WRITE(ITOUT,FMT=6014)  IWARN(1,7)
        END IF
C---- Inner profiles have been averaged a significant number of times
        IF (WARN(8).AND.
     +       ((XWARN(1,8).GT.900).AND.(XWARN(1,8).LT.9000))) THEN
          WRITE(ISUMMR,FMT=6009) WAVE/DSTMAX,NBADAVG,
     +         LIST(1:LENSTR(LIST)),(ILIST(I),I=1,NBADAVG)
          WRITE(IOUT,FMT=6009) WAVE/DSTMAX,NBADAVG,
     +         LIST(1:LENSTR(LIST)),(ILIST(I),I=1,NBADAVG)
          IF (ONLINE) WRITE(ITOUT,FMT=6009) WAVE/DSTMAX,NBADAVG,
     +         LIST(1:LENSTR(LIST)),(ILIST(I),I=1,NBADAVG)
        END IF
C
C---- Spots in central region with zero pixel values
C
        IF (WARN(14).AND.(.NOT.TILED).AND.(NULLPIX.EQ.0)) THEN
          ILIM = NINT(0.01*LIMIT)
          WRITE(IOUT,FMT=6042) NULLPIX, NULLPIX,ILIM,
     +            NULLPIX
          IF (ONLINE) WRITE(ITOUT,FMT=6042) NULLPIX, NULLPIX,ILIM,
     +            NULLPIX
          WRITE(ISUMMR,FMT=6042) NULLPIX, NULLPIX,ILIM,
     +            NULLPIX
        END IF
C
C---- Poorly defined cell parameters
C
        IF (WARN(18)) THEN
C
C---- Find out which cell parameters are poorly determined
C
          STR = ' '
          IF (IWARN(1,18).EQ.1)STR=STR(1:MAX(1,LENSTR(STR)))//' A'
          IF (IWARN(2,18).EQ.1)STR=STR(1:MAX(1,LENSTR(STR)))//' B'
          IF (IWARN(3,18).EQ.1)STR=STR(1:MAX(1,LENSTR(STR)))//' C'
          IF (IWARN(4,18).EQ.1)STR=STR(1:MAX(1,LENSTR(STR)))//' ALPHA'
          IF (IWARN(5,18).EQ.1)STR=STR(1:MAX(1,LENSTR(STR)))//' BETA'
          IF (IWARN(6,18).EQ.1)STR=STR(1:MAX(1,LENSTR(STR)))//' GAMMA'
          WRITE(IOUT,FMT=6056) STR(1:MAX(1,LENSTR(STR))),
     +                         (XWARN(I,18),I=1,6)
          IF (ONLINE) WRITE(ITOUT,FMT=6056) STR(1:MAX(1,LENSTR(STR))),
     +                         (XWARN(I,18),I=1,6)
          WRITE(ISUMMR,FMT=6056) STR(1:MAX(1,LENSTR(STR))),
     +                           (XWARN(I,18),I=1,6)
        END IF
C
C----  Rather few reflections for post-refinement of cell
C
        IF (WARN(24)) THEN
          WRITE(IOUT,FMT=6094)
          WRITE(ISUMMR,FMT=6094)
          IF (ONLINE) WRITE(ITOUT,FMT=6094)
        END IF
C
C---- YSCAL wrong by more than 0.005 (and less than 0.01 which is SERIOUS)
C
        IF (WARN(25).AND.(XWARN(1,25).LT.0.01)) THEN
          WRITE(IOUT,FMT=6096) XWARN(1,25)
          WRITE(ISUMMR,FMT=6096) XWARN(1,25)
          IF (ONLINE) WRITE(ITOUT,FMT=6096) XWARN(1,25)
        END IF
C
C----  Profile correlation coefficient less than 0.6. MIN value
C
        IF (WARN(29)) THEN
          IJ = MIN(IWARN(1,29),6)
          WRITE(IOUT,FMT=6104) IWARN(1,29), XWARN(1,29),
     +     (IWARN(2*K,29),IWARN(2*K+1,29),XWARN(K+1,29),K=1,IJ)
          WRITE(ISUMMR,FMT=6104) IWARN(1,29), XWARN(1,29),
     +     (IWARN(2*K,29),IWARN(2*K+1,29),XWARN(K+1,29),K=1,IJ)
          IF (ONLINE) WRITE(ITOUT,FMT=6104) IWARN(1,29), XWARN(1,29),
     +     (IWARN(2*K,29),IWARN(2*K+1,29),XWARN(K+1,29),K=1,IJ)
        END IF
C
C---- More than 10% of reflections overlapped
C
        IF (WARN(32).AND.((XWARN(1,32).GT.0.10).AND.
     +                    (XWARN(1,32).LT.0.20))) THEN 
          WRITE(IOUT,FMT=6112) NINT(XWARN(1,32)*100) 
          IF (ONLINE) WRITE(ITOUT,FMT=6112) NINT(XWARN(1,32)*100) 
        END IF
C
C---- Average image to image change in missets less than 0.2
C
        IF (WARN(33).AND.(XWARN(1,33).LT.0.20)) THEN
          N = 1 + IWARN(1,33)
          WRITE(IOUT,FMT=6114) XWARN(1,33),
     +    IWARN(1,33),NBLOCK,(IWARN(J,33), J = 2,N)
          WRITE(IOUT,FMT=6115)
          IF (ONLINE) WRITE(ITOUT,FMT=6114) XWARN(1,33),
     +    IWARN(1,33),NBLOCK,(IWARN(J,33), J = 2,N)
          IF (ONLINE) WRITE(ITOUT,FMT=6115)
        END IF
C
C---- adjacent spots included in peak region of standard profile,
C     > 5% of all profiles
C
        IF (WARN(36)) THEN
          NBADBLOCK = IWARN(1,36)
          WRITE(IOUT,FMT=6120) FRACBADPROF,TOLMIN,TOL
          IF (ONLINE) WRITE(ITOUT,FMT=6120) FRACBADPROF,TOLMIN,TOL
C
C---- Numbers only stored for first 19 (array bounds limit)
C
          NBADLIMIT = MIN(NBADBLOCK,19)
          WRITE(IOUT,FMT=6122)
          IF (ONLINE) WRITE(ITOUT,FMT=6122)
          DO 32 I = 1,NBADLIMIT
            NBADBOX = IWARN(10*I+11,36)
            WRITE(IOUT,FMT=6123) IWARN(I+1,36),(IWARN(10*I+11+J,36),
     +           NINT(100*XWARN(10*I+11+J,36)), J = 1,NBADBOX)
            IF (ONLINE) WRITE(ITOUT,FMT=6123) IWARN(I+1,36),
     +        (IWARN(10*I+11+J,36),NINT(100*XWARN(10*I+11+J,36)),
     +         J = 1,NBADBOX)
 32       CONTINUE
        END IF 
C
C---- Detector parameters changed for MicroED
C
        IF (WARN(43)) THEN
          WRITE(IOUT,FMT=6140) GAIN, IDIVIDE
          IF (ONLINE) WRITE(ITOUT,FMT=6140) GAIN, IDIVIDE
        END IF
C
C
C---- *******    Now "INFO" class   *******
C
        IF (INFO) THEN
          WRITE(IOUT,FMT=6230)
          WRITE(ISUMMR,FMT=6230)
          IF (ONLINE) WRITE(ITOUT,FMT=6230)
        END IF
 6230   FORMAT(//,1X,'*** THE FOLLOWING ARE MAINLY FOR INFORMATION ***'
     +        ,/,1X,'================================================',
     +          /,1X,'In some cases it may be possible to change',
     +          ' the processing to eliminate',/,1X,'some of these',
     +          ' warnings.',/)

C---- ADDPART
        IF ((WARN(2).OR.WARN(3).OR.WARN(12)).AND.ADDPART) THEN
          WRITE(ISUMMR,FMT=6007)
          WRITE(IOUT,FMT=6007)
          IF (ONLINE) WRITE(ITOUT,FMT=6007)
        END IF
C---- Spot overlap
        IF (WARN(1)) THEN
          WRITE(ISUMMR,FMT=6002) 0.01*IXSEP,0.01*IYSEP,
     +                           (XWARN(K,1),K=1,4),TOL
          WRITE(IOUT,FMT=6002) 0.01*IXSEP,0.01*IYSEP,
     +                           (XWARN(K,1),K=1,4),TOL
          IF (ONLINE) WRITE(ITOUT,FMT=6002) 0.01*IXSEP,0.01*IYSEP,
     +                           (XWARN(K,1),K=1,4),TOL
          IF (.NOT.DENSE) THEN
            WRITE(ISUMMR,FMT=6003)
            WRITE(IOUT,FMT=6003)
            IF (ONLINE) WRITE(ITOUT,FMT=6003)
          END IF
        END IF
C---- ROFF
        IF (WARN(2).AND.IMGP) THEN
          WRITE(ISUMMR,FMT=6004) XWARN(1,2),RAST
          WRITE(IOUT,FMT=6004)  XWARN(1,2),RAST
          IF (ONLINE) WRITE(ITOUT,FMT=6004)  XWARN(1,2),RAST
          IF ((.NOT.FIXPAR(10)).OR.(.NOT.FIXPAR(11))) THEN
            WRITE(ISUMMR,FMT=6005)
            WRITE(IOUT,FMT=6005)
            IF (ONLINE) WRITE(ITOUT,FMT=6005)
          END IF
        END IF
C---- CCOMEGA
        IF (WARN(3)) THEN
          WRITE(ISUMMR,FMT=6006) XWARN(1,3)
          WRITE(IOUT,FMT=6006) XWARN(1,3)
          IF (ONLINE) WRITE(ITOUT,FMT=6006) XWARN(1,3)
          WRITE(ISUMMR,FMT=6106)
          WRITE(IOUT,FMT=6106)
          IF (ONLINE) WRITE(ITOUT,FMT=6106)
        END IF
C---- Profile averaging
        IF (WARN(8)) THEN
          WRITE(ISUMMR,FMT=6016)
          WRITE(IOUT,FMT=6016)
          IF (ONLINE) WRITE(ITOUT,FMT=6016)
        END IF
C---- Too many spots with too few background points
        IF (WARN(10)) THEN
          WRITE(ISUMMR,FMT=6022) IWARN(1,10),NBGMIN,BGSIG
          WRITE(IOUT,FMT=6022) IWARN(1,10),NBGMIN,BGSIG
          IF (ONLINE) WRITE(ITOUT,FMT=6022) IWARN(1,10),NBGMIN,BGSIG
          IF (WARN(1)) THEN
            WRITE(ISUMMR,FMT=6024)
            WRITE(IOUT,FMT=6024)
            IF (ONLINE) WRITE(ITOUT,FMT=6024)
          ELSE
            WRITE(ISUMMR,FMT=6026)
            WRITE(IOUT,FMT=6026)
            IF (ONLINE) WRITE(ITOUT,FMT=6026)
            IF (WARN(9)) THEN
              WRITE(ISUMMR,FMT=6028)
              WRITE(IOUT,FMT=6028)
              IF (ONLINE) WRITE(ITOUT,FMT=6028)
            ELSE
              WRITE(ISUMMR,FMT=6030)
              WRITE(IOUT,FMT=6030)
              IF (ONLINE) WRITE(ITOUT,FMT=6030)
            END IF
          END IF
        END IF
C---- Profiles have long tails
        IF (WARN(11)) THEN
          WRITE(ISUMMR,FMT=6032) 100.0*XWARN(1,11),TOL
          WRITE(IOUT,FMT=6032) 100.0*XWARN(1,11),TOL
          IF (ONLINE) WRITE(ITOUT,FMT=6032)100.0*XWARN(1,11),TOL
        END IF

C---- TOFF
        IF (WARN(12).AND.IMGP) THEN
          WRITE(ISUMMR,FMT=6034) XWARN(1,12)
          WRITE(IOUT,FMT=6034) XWARN(1,12)
          IF (ONLINE) WRITE(ITOUT,FMT=6034) XWARN(1,12)
          IF (ADDPART) THEN
            WRITE(ISUMMR,FMT=6035)
            WRITE(IOUT,FMT=6035)
            IF (ONLINE) WRITE(ITOUT,FMT=6035)
          END IF
        END IF
C
C---- Too many background pixels rejected . DISABLE THIS TEST, IT DOESNT
C     REALLY WORK
CAL        IF (WARN(17)) THEN
CAL          WRITE(IOUT,FMT=6054) BGSIG
CAL          IF (ONLINE) WRITE(ITOUT,FMT=6054) BGSIG
CAL        END IF
        IF (WARN(20)) THEN
          I = IWARN(1,20)
          IPR = MIN(I,19) + 1
          WRITE(IOUT,FMT=6070) I
          WRITE(ISUMMR,FMT=6070) I
          IF (ONLINE) WRITE(ITOUT,FMT=6070) I
          IF (ADDPART) THEN
            WRITE(IOUT,FMT=6073)
            WRITE(ISUMMR,FMT=6073)
            IF (ONLINE) WRITE(ITOUT,FMT=6073)
          END IF
          IF (TOL.GT.0.03) THEN
            WRITE(IOUT,FMT=6072) TOL
            WRITE(ISUMMR,FMT=6072) TOL
            IF (ONLINE) WRITE(ITOUT,FMT=6072) TOL
          END IF
          WRITE(IOUT,FMT=6074) (IWARN(K,20),K=2,IPR)
          WRITE(ISUMMR,FMT=6074) (IWARN(K,20),K=2,IPR)
          IF (ONLINE) WRITE(ITOUT,FMT=6074) (IWARN(K,20),K=2,IPR)
          WRITE(IOUT,FMT=6076) (XWARN(K,20),K=2,IPR)
          WRITE(ISUMMR,FMT=6076) (XWARN(K,20),K=2,IPR)
          IF (ONLINE) WRITE(ITOUT,FMT=6076) (XWARN(K,20),K=2,IPR)
        END IF
        IF (WARN(21).AND.(.NOT.DENSE)) THEN
          WRITE(IOUT,FMT=6080) 100.0*XWARN(1,21)
          WRITE(ISUMMR,FMT=6080) 100.0*XWARN(1,21)
          IF (ONLINE) WRITE(ITOUT,FMT=6080) 100.0*XWARN(1,21)
        END IF
C
C----  Not enough background pixels forcing reduction of RECLEVEL
C
        IF (WARN(28)) THEN
          WRITE(IOUT,FMT=6102) NBGMIN,RECLEVEL
          WRITE(ISUMMR,FMT=6102) NBGMIN,RECLEVEL
          IF (ONLINE) WRITE(ITOUT,FMT=6102) NBGMIN,RECLEVEL
        END IF
C
C---- Profile tolernces increased to reduce number of overlaps
C
        IF (WARN(38)) THEN
          WRITE(IOUT,FMT=6130) TOLMIN,TOL
          WRITE(ISUMMR,FMT=6130) TOLMIN,TOL
          IF (ONLINE) WRITE(ITOUT,FMT=6130) TOLMIN,TOL
        END IF
C
C---- IGNORE remaining
C
       IF (IGNORE) GOTO 14

C
C---- Adjacent images have exposures differing by more than 5% (as 
C     judged from background of spots in post-refinement
C
        IF (WARN(13).AND.ADDPART) THEN
          NBAD = IWARN(1,13)
          WRITE(IOUT,FMT=6036) NBAD
          IF (ONLINE) WRITE(ITOUT,FMT=6036) NBAD
          WRITE(ISUMMR,FMT=6036) NBAD
          WRITE(IOUT,FMT=6038) (IWARN(I,13),I=2,NBAD+1)
          IF (ONLINE) WRITE(ITOUT,FMT=6038) (IWARN(I,13),I=2,NBAD+1)
          WRITE(IOUT,FMT=6040) (XWARN(I,13),I=2,NBAD+1)
          IF (ONLINE) WRITE(ITOUT,FMT=6040) (XWARN(I,13),I=2,NBAD+1)
          WRITE(ISUMMR,FMT=6038) (IWARN(I,13),I=2,NBAD+1)
          WRITE(ISUMMR,FMT=6040) (XWARN(I,13),I=2,NBAD+1)
        END IF
C
C---- Not many fully recorded reflections
C
        IF (WARN(15).AND.(.NOT.USEPAR)) THEN
          WRITE(IOUT,FMT=6044)
          IF (ONLINE) WRITE(ITOUT,FMT=6044)
          WRITE(ISUMMR,FMT=6044)
        END IF
        IF ((WARN(22).OR.WARN(23)).AND.(.NOT.IGNORE)) THEN
          WRITE(ISUMMR,FMT=6200)
          WRITE(IOUT,FMT=6200)
          IF (ONLINE) WRITE(ITOUT,FMT=6200)
C    
          IF (WARN(22).AND.(.NOT.WARN(23))) THEN
            WRITE(IOUT,FMT=6090) IWARN(1,22),PTMIN
            WRITE(ISUMMR,FMT=6090) IWARN(1,22),PTMIN
            IF (ONLINE) WRITE(ITOUT,FMT=6090) IWARN(1,22),PTMIN
            IF (.NOT.PRFULLS) THEN
              WRITE(IOUT,FMT=6091)
              WRITE(ISUMMR,FMT=6091) 
              IF (ONLINE) WRITE(ITOUT,FMT=6091)
            END IF
          END IF
          IF (WARN(23)) THEN
            WRITE(IOUT,FMT=6092) PTMIN
            WRITE(ISUMMR,FMT=6092) PTMIN
            IF (ONLINE) WRITE(ITOUT,FMT=6092) PTMIN
          END IF
        END IF

        IF (WARN(26)) THEN
          WRITE(IOUT,FMT=6098) NPRMIN
          WRITE(ISUMMR,FMT=6098) NPRMIN
          IF (ONLINE) WRITE(ITOUT,FMT=6098) NPRMIN
        END IF
C----- IPAD
C     HRP 23.10.2015 this can never be true? IGNORE is set TRUE if WARN(27)
C     - see line 190.
        IF (WARN(27).AND.(.NOT.IGNORE)) THEN
          WRITE(ISUMMR,FMT=6100) WMAX
          WRITE(IOUT,FMT=6100) WMAX
          IF (ONLINE) WRITE(ITOUT,FMT=6100) WMAX
        END IF
        

C
C---- reset all warning flags and values, except that about inaccurate cell
C     This is only reset if a new cell refinement is done.
C
 14   DO 20  I = 1,100
           IF (I.NE.18) THEN
             WARN(I) = .FALSE.
             DO 22 K=1,MAXIWARN
               IWARN(K,I) = 0
               XWARN(K,I) = 0.0
 22          ENDDO
           ENDIF
 20     ENDDO
      END IF
      RETURN
 6000 FORMAT(//,1X,'*** Warning messages ***')
 6002 FORMAT(/,1X,'SPOT OVERLAP',/,1X,'============',/,1X,
     +       'Adjacent spots overlap. This will produce ',
     +       'systematic errors in the intensities.'
     +       ,/,1X,'Note that this',
     +       ' warning will arise even if only one pair of spots in',
     +       /,1X,'one area of the detector overlap. Look at the ',
     +        'standard profiles',
     +       ' to see how',/,1X,'serious the overlap is.',/,1X,
     +      'The minimum allowed spot separation (SEPARATION keyword)',
     +       ' was ',2F4.1,'mm.',/,1X,'The actual spot size determined',
     +       ' by the mask optimisation is',F4.1,' by',F4.1,'mm',/,1X,
     +       'in the centre of the image and the largest spot size is',
     +       F4.1,' by',F4.1,'mm.',/,1X,'The separation given '
     +       ,'should be at least as large as the spot size',/,1X,
     +       'in the centre of the image (keyword SEPARATION).',/,1X,
     +       'Check standard profiles carefully to ensure that the ',
     +       'optimisation of the',/,1X,'raster parameters has worked',
     +       ' correctly.',/,1X,'The effective size',
     +      ' of the spots can be controlled by PROFILE TOLERANCE ',
     +        /,1X,'keywords. If the peak regions look too large (ie',
     +       ' they include too much of the',/,1X,'tails of the spot)',
     +        ', try increasing TOLERANCE (current value',F6.3,
     +        ') by',/,1X,'eg 0.005 ',
     +        'and see if profiles look better.',/,1X,
     +       '(Increasing TOLERANCE will'
     +      ,' decrease spot size).'/,1X,'As a last resort the profile',
     +       ' optimisation can be turned off ',
     +       'using keywords',/,1X,'PROFILE NOOPT.')
 6003 FORMAT(/,1X,'In cases of serious overlap, (ie if the pattern',
     +       ' is very dense), then the',/,1X,'SEPARATION CLOSE option',
     +       ' should be used (eg SEPARATION  1.0 1.0 CLOSE)',/,1X,
     +       'and it may also help to suppress profile optimisation',
     +       ' in these cases',/,1X,'(PROFILE NOOPT)',
     +       'keyword. See help library for details.')
 6004 FORMAT(/,1X,'RADIAL OFFSET UNSTABLE',/,1X,'====================',
     +        '==',/,1X,'The radial',
     +       ' offset parameter (ROFF) is varying more than it should.'
     +        ,/,1X,'(Maximum variation is',F6.2,'mm)',/,1X,
     +       'If the variation is random, it may be due to weak ',
     +       'data.',/,1X,'In this case, it is best to fix the ',
     +       'ROFF parameter: REFINEMENT FIX ROFF',/,1X,'If known',
     +       ' the correct value can be input: DISTORTION ROFF 0.11 ',
     +       'If not known, the mean refined value can be used.',/,1X,
     +       'In such cases TOFF should also be FIXED.',/,1X,
     +       'If the ROFF values',/,1X,'fall into two or',
     +       ' more sets of values which differ by one pixel (',F4.2,
     +       'mm)',
     +       /,1X,'then there may be a problem with the',
     +       ' locking mechanism of the scanner.'/,1X,'Instability',
     +       ' in TOFF may also cause large changes in ROFF.')
 6005 FORMAT(1X,'Try',
     +       ' fixing RDROFF and RDTOFF first with keywords:',/,1X,
     +       'REFINEMENT FIX RDROFF RDTOFF.',/,1X,'It may also ',
     +       'be necessary to fix TOFF (but then the correct value',
     +       /,1X,'for this scanner should be specified using ',
     +       'keywords DISTORTION TOFF x).')
 6006 FORMAT(/,1X,'CCOMEGA UNSTABLE',/,1X,'================',/,1X,
     +       'The',
     +       ' parameter CCOMEGA is varying more than it should.',
     +       /,1X,'(Maximum variation is',F6.2,' degrees)',/,1X,
     +       /,1X,'This could be due to crystal slippage (look at ',
     +       ' summary file) in which',/,1X,'case the intensities of',
     +       ' partially recorded reflections may have serious ',
     +       /,1X,'errors (check by using FULLS ONLY in ',
     +         'AIMLESS/SCALA)',/,
     +       /,1X,'It may be also due to poor positional refinement',
     +        ' if the images are weak',/,1X,'OR there are',
     +       ' not many spots on each image.')
 6106 FORMAT(1X,'If there',
     +    ' are large changes in both TOFF, ROFF and CCOMEGA, this ',
     +    'suggests',/,1X,'that the refinement is unstable and ',
     + 'ROFF and TOFF should not be refined.',/,1X,'To do this use',
     +  ' keywords: REFINEMENT FIX ROFF TOFF.',/,1X,'The correct ',
     +  'values for this scanner should be specified using ',
     +  'keywords:',/,1X,'DISTORTION TOFF 0.13',
     +  ' ROFF 0.03 (for example).',/,1X,'It is NOT ',
     +  'recommended to FIX CCOMEGA as well (REFINEMENT FIX CCOMEGA).',
     +     /,1X,'as CCOMEGA allows for crystal slippage around',
     +          ' the X-ray beam direction.')
 6007 FORMAT(//,1X,' **** IMPORTANT ****',/,1X,'The ADDPART option ',
     +        'MUST NOT be used if ROFF or TOFF are unstable',/,1X,
     +        'Turn it off using keyword ADDPART OFF')
 6008 FORMAT(/1X,'NOT ENOUGH SPOTS FOR REFINEMENT',/,1X,
     +           '===============================',/,1X,
     +        'Refinement failed because there were fewer than ',I5,
     +        ' spots found in',/,1X,'the central region of the ',
     +        'detector. This could be because the images are weak',
     +        /,1X,'in which case try reducing the minimum number',
     +        ' of reflections (REFINEMENT NREF)',/,1x,
     +        'or the prediction could be wrong, use iMosflm to ',
     +        'check.',/,1X,'The following images were affected',
     +        (1X,10I6))
 6009 FORMAT(/,1x,'VERY POOR STANDARD PROFILES',/,1x,
     +            '===========================',/1x,
     +        'Some inner standard profiles have been averaged.',
     +       /,1X,'This suggests that the current resolution limit (',
     +       F5.2,') is set too high',/,1X,'and this could affect the ',
     +       'data quality.',/,'The following',I3,' inner profiles',
     +       ' have been averaged: ',A,/,1X,'The number of blocks',
     +       ' when this averaging has occurred for these profiles is:',
     +       /,1x,9I4)
 6010 FORMAT(/,1X,'CRYSTAL SLIPPAGE',/,1X,'================',/,1X,
     +        'There is significant slippage between successive',
     +        ' images',/,1X,'(Maximum slippage is',F8.2,' degrees',
     +        ' for image',I7,
     +        ' which is more than',/,1X,'a quarter of the sum',
     +        ' of the beam divergence and mosaic spread.',/,1X,
     +        'There may be serious errors in the intensities of ',
     +        'partially recorded',/,1X,'reflections. This can',
     +        ' be checked by merging only fully recorded ',
     +        'reflections',/,1X,'in AIMLESS/SCALA. ',
     +         'In extreme cases it may be helpful to increase ',
     +        'the',/,1X,'mosaic spread or beam divergence parameters',
     +        ' to improve processing.')
 6012 FORMAT(/,1X,'LARGE WEIGHTED RESIDUAL',/,1X,
     +            '=======================',/,1X,
     +        'The weighted residual is rather large (it should ',
     +        'be unity, actual maximum value',F5.2,').',
     +        /,1X,'This is usually due to poor cell ',
     +        'parameters..check these and possibly try ',
     +        'post-refinement')
 6014 FORMAT(/,1X,'EXCESSIVE NUMBER OF BADSPOTS',/,1X,
     +            '============================',/,1X,
     +        'At least some images have rather a lot of ',
     +        'badspots (Maximum number',I4,')',
     +        /,1X,'They are rejected on the basis of: ',
     +        /,1X,'1) Poor profile fit (PKRATIO >3, ',
     +        'controlled by REJECTION PKRATIO).',/,1X,
     +        '2) Too large a BGRATIO (too much background variation',
     +        ', controlled by',/,3X,' REJECTION BGRATIO).',/,1X,
     +        '3) Too large a background gradient (controlled by',
     +        ' REJECTION GRADMAX)',/,1X,'4) Intensity',
     +        ' negative and more than 5 sigma.',/,1X,'Look at the ',
     +        'list of badspots to see what category they fall under.',
     +        //,1X,'Not defining the backstop shadow can give large',
     +        ' background plane gradients.',
     +        /,1X,'Very intense images can have unusually large ',
     +        'gradients, GRADMAX may have to',/,1X,'be changed ',
     +        'from the default',/,1X,'A pixel dump of the BADSPOTS',
     +        ' can be obtained using REJECTION PLOT',/,1X,'if the ',
     +        'reason for their rejection is not clear')
 6016 FORMAT(/1X,'AVERAGING OF STANDARD PROFILES',/,1X,
     +           '==============================',/,1X,
     +           'Profile averaging has been performed for some ',
     +      'of the standard profiles.',/,1X,
     +     'This is because reflections in some regions of the ',
     +     'detector are too weak',/,1X,'to form reliable profiles,',
     +     'so reflections from adjacent regions are',/,1X,
     +     'being included.',/,
     $     1X,'This is acceptable for outer profiles, but if inner ',
     +     'profiles are being',/,1X,'averaged then the resolution',
     +     ' limit is probably set too high.')
 6018  FORMAT(/1X,'ERROR IN DETECTOR GAIN',/,1X,
     +            '======================',/,1X,
     +          'The ratio of the observed variation in background',
     +          ' pixels to that',/,1X,'expected statistically',
     +          ' (the BGRATIO) lies outside the range',
     +          ' 0.7 to 1.3.',/,1X,'Actual values: minimum:',F6.2,
     +           '  maximum:',F6.2,
     +          /,1X,'The most likely explanation is that the GAIN',
     +          ' of the detector is incorrect.',/,1X,'The current ',
     +          'GAIN is',F5.2,' but the observed BGRATIO suggests ',
     +          'it should be',/,1X,'set to',F5.2,'.',/,1X,
     +          'NOTE however that diffuse scatter can lead to an ',
     +          'increased value of BGRATIO',/,1X,'even when the',
     +          ' gain is correct.',
     +           /,1X,'Since the gain for any detector should remain ',
     +          'constant, it should be worked out',/,1X,'for a ',
     +          'crystal giving strong diffraction and "clean" ',
     +          'spots (ie no disorder or',/,1X, 'diffuse scatter)',
     +          'and kept at this value.',/,1X,'Processing data with',
     +            ' an incorrect gain will result in a systematic ',
     +            /,1X,'overestimate of very weak reflections and ',
     +            'incorrect standard deviations.')
 6020  FORMAT(/1X,'OVERALL BACKGROUND RATIO (BGRATIO)',/,1X,
     +            '==================================',/,1X,
     +          'The average background ratio lies outside the range',
     +          ' 0.7 to 1.3',/,1X,'Actual values: minimum:',F6.2,
     +           '  maximum:',F6.2,
     +          /,1X,'This may be because the Selwyn granularity for',
     +           ' the scanner is',
     +          ' not set correctly.',/,1X,'The true granularity is  ',
     +          'the input granularity multiplied by BGRATIO**2.',/,1X,
     +          'NOTE however that diffuse scatter can lead to an ',
     +          'increased value of BGRATIO even if the granularity ',
     +           'is correct',
     +           /,1X,'Since the granularity for any film type should',
     +          ' remain ',
     +          'constant, it should be worked out for a ',/,1X,
     +          'crystal giving strong diffraction and "clean" ',
     +          'spots (ie no disorder or diffuse scatter)',/,1X,
     +          'and kept at this value',/,1X,'Processing data with',
     +       ' an incorrect granularity will result in a systematic ',
     +            /,1X,'overestimate of very weak reflections and ',
     +            'incorrect standard deviations')
 6022  FORMAT(/1X,'BACKGROUND PIXEL REJECTION',/,1X,
     +            '==========================',/,1X, 
     +          'Too many spots (',I4,') have been rejected because ',
     +            'they have less than',I3,/,1X,'background pixels ',
     +            'after rejection (Number set by MINB on REJECTION ',
     +            'keyword)',/,1X,'Background pixels are rejected ',
     +            'either because they are overlapped by',/,1X,'the ',
     +            'peak of a neighbouring spot, or because they',
     +            ' deviate by',/,1X,'more than',F4.1,' sigma (BGSIG',
