      REAL XC,YC,XCAL,YCAL,DSTSQ,SNSQ,CS2TH,FLP,DMAX,DSTCUT,
     +     BGRAT,PKRAT,GRAD,BESTSIG,CMOSAICN,CMOSAICD,LORENTZ,
     $     CMOSAICNL,CMOSAICDL,X,Y,EDSCALE
      INTEGER I,J,K,ISD,INTPR,ISDPR,NDBG,KSYM,NOUT,IFLAG,NLP,MPART,
     +        IR,IM,MP,IOVER,NCUT,IR1,IR2,IBAD,IPKR,IGOOD,
     $     IFAIL,LDUM,NLATT,ICOL,ILATT,NDBG2
