C&&*&& include  ../inc/mharvest.f
c      INTEGER MCOLS
C     .. Scalars in common block /CHARVEST/ ..
      CHARACTER HVERSION*100,ProjectName*64,Crystalname*64,
     +          DataSetName*64,HBEAMLINE*10,Precipitant*80,
     +          XNAME_COLS(MCOLS+MAXLATT*3)*64,
     +          DNAME_COLS(MCOLS+MAXLATT*3)*64
C     .. Scalars in common block /IHARVEST/ ..
      LOGICAL USECWD,PNAMEgiven,XNAMEgiven,DNAMEgiven,DOHARVEST
      REAL    PHhar,Hartemp,
     +     HARETA(MAXPAX),HARDIV(MAXPAX),HARDIH(MAXPAX)
      CHARACTER*3 MKDIRMODE,CHMODMODE
      INTEGER KHFLMS
C     ..
C     .. Common block /CHARVEST/ ..
      COMMON /CHARVEST/HVERSION,ProjectName,Crystalname,
     +                 DataSetName,HBEAMLINE,Precipitant,
     +                 XNAME_COLS,DNAME_COLS
C     .. Common block /IHARVEST/ ..
      COMMON /IHARVEST/USECWD,PHhar,Hartemp,KHFLMS,
     +                 PNAMEgiven,XNAMEgiven,DNAMEgiven,DOHARVEST,
     +                 HARETA,HARDIV,HARDIH,MKDIRMODE,CHMODMODE
C     ..
C&&*&& end_include  ../inc/mharvest.f
c-harvest
C
C     .. Equivalences ..
C     ..
C---- Note this equivalence makes array RBATCH map into the common block
C     "orient", and CBATCH into the common block "corien" (characters).
C
      EQUIVALENCE       (NWORDS,RBATCH(1))
      EQUIVALENCE       (CBATCH(1), BTITLE)
      SAVE
C     ..

C     .. Data statements ..               
C
      LDUM = 80
      IR1 = 2*IPAD + 1
      IR2 = 2*IPAD + 2
      IR2 = 30*IPAD + 30

      IOVER = 9999
      IF (IMGP) IOVER = 999999
      NDBG = 0
      NDBG2 = 0
      DSTCUT = 10000.0
      NCUT = 0
C
C---- Additional scale factor applied to Lorentz-Polarisation factor
C     to avoid intensities being very small for electron diffraction data,
C     for which the wavelength is assumed to be less than 0.1A.
C
      EDSCALE = 1.0
      IF (WAVE.LT.0.1) EDSCALE = 100.0
C
C---- output for BEST
C
      IF(LBEST)THEN
        CMOSAICN = 0.0
        CMOSAICD = 0.0
        CMOSAICNL = 0.0
        CMOSAICDL = 0.0
      ENDIF
C
      IF (STHCUT.GT.0.0) THEN
        DMAX = SQRT(1.0/STHCUT)
        WRITE(IOUT,FMT=6012) DMAX,RESCUT
        IF (ONLINE) WRITE(ITOUT,FMT=6012) DMAX,RESCUT
 6012   FORMAT(1X,'No data will be written beyond',F6.2,'A ',
     +      'as the mean I/sigma(I) falls below',F6.2)
        DSTCUT = (WAVE/DMAX)**2
      END IF
      IF (DEBUG(50)) THEN
        WRITE(IOUT,FMT=6030) ISEROP,ADDPART,TOSPT,SINGLETON,NLATTICE
        IF (ONLINE) WRITE(ITOUT,FMT=6030) ISEROP,ADDPART,TOSPT,
     +              SINGLETON,NLATTICE
 6030   FORMAT(1X,'Enter WRMTZ',/,1X,'ISEROP',I6,'  ADDPART ',L1,
     +         ' Total number of spots',I6,'  SINGLETON',L2,
     +         '  NLATTICE',I3)
        IF ((NLATTICE.GT.1).AND.(.NOT.SINGLETON)) THEN
          WRITE(IOUT,FMT=6032) NLATTICE,IOVWORK,ILATTICE,
     +            (IOVLATTICE(I),I=1,IOVWORK)
          IF (ONLINE) WRITE(ITOUT,FMT=6032) NLATTICE,IOVWORK,
     +            ILATTICE,(IOVLATTICE(I),I=1,IOVWORK)
 6032     FORMAT(1X,'NLATTICE=',I3,' IOVWORK=',I3,
     +           '  Integrating lattice',I2,
     +           ' allowing overlap from lattices',6I3)
        END IF
      END IF
C
C---- Set up the matrix PHI*DELPIHZ*DELPHIY*DELPHIX*AMAT used to calculate
C     reciprocal lattice coordinates for Lp correction
C
      DELPHI(3) = DELPHI(3) + PHIBEG
      CALL ROTMAT(DELPHI,RMAT,1)
      DELPHI(3) = DELPHI(3) - PHIBEG
      CALL MATMUL3(AHAT,RMAT,AMAT)
C
C---- Set up the batch header. This call transfers the information into
C     the "orient" common block
C
      CALL CRYSTHDR
C
C---- Write the header for batch with serial number ISEROP
C     to the MTZ file open for write  on index INDEX, batch info
C     stored in the two arrays RBATCH (for numbers)
C     and CBATCH (for characters).
C     If this routine is called at all then it must be called for
C     every batch which is to be output - these batch serial numbers
C     are stored in array WOMBAT, and are used in LWCLOS.
C     If it is called with ISEROP = 0 this is a flag to say that the
C     output MTZ file will be a standard file, and not a multi-record
C     one, ie no batches. After this call no batch information is
C     available to the calling program, so don't call it too soon !
C---- Arguments :
C     MTZOUT     INTEGER         indicates which MTZ file - 1 index
C                               points to both input and output files
C     ISEROP     INTEGER         serial number of this batch
C                               if 0 wipe away all batch info for file
C     REAL         RBATCH(MBLENG)
C     RBATCH    REAL(*)         array from which integer and real batch
C                               info is decoded by subroutine wbathd
C                               this should be equivalenced onto the
C                               appropriate COMMON block in the calling
C                               program. The first item is nwords,ie how
C                               many items in the array, if nword is 0
C                               then only the title is written to header
C     CHARACTER*1  CBATCH(CBLENG)
C     CBATCH    CHARACTER(*)*1  as RBATCH, but for character items - no
C                               nwords however; title is 1st 70 chars of
C                               CBATCH.
C
C---- Write out orientation data
C
C          ***********************************
      CALL LWBAT (MTZOUT,ISEROP,RBATCH,CBATCH)
c-harvest
c
      CALL LWBSETIDX (MTZOUT,ISEROP,CrystalName,DataSetName)
c
C---- Subroutine to write dataset ID for batch BATNO to
C     batch headers for multi-record file open on index MINDX
C     If LWBAT has been used, the batch headers in RBATW are used,
C     else those in RBATR are used.
c
c-harvest
C          ***********************************
      NOUT = 0
      NLP = 0
C
C---- assign scan axis in general form - relative to s0 = (-1, 0, 0)
C
      SCAXIS(1) = SIN(GON_OMEGAS * DTOR)
      SCAXIS(2) = -SIN(GON_CHI_SET * DTOR) * COS(GON_OMEGAS * DTOR)
      SCAXIS(3) = COS(GON_CHI_SET * DTOR)
C
C---- Loop over reflections, writing out measured intensities
C
        DO 30 I = 1,TOSPT
          BADPROF = .FALSE.
          FLAGOUT = .TRUE.
C
C----- Initialise MISYMG, so that in find hkl option we know if
C      indices ahave been reduced to au or not.
C
          MISYMG(I) = 0          
C
C
C---- Check if this reflection was measured, flag is set in PROCESS
C
CAL   Change this...now IGFLAG is set to -IBAD which codes the reason
C     for rejecting the spot.
C
C     IBAD       reason
C      1         BGRATIO too large
C      2         PKRATIO too large
C      4         Negative > 5*sigma
C      8         Gradient too high
C     16         Profile fitted overload
C     32         Profile fitted "edge" reflection
C     64         Too few background pixels, no intensity estimate.
C                Not written to MTZ file.
C    128         Off edge of detector, or summed partial with only one half.
C                Not written to MTZ file.
C
          MSRD = (ABS(IGFLAG(I)).GT.0)

          IF (ALLOUT) THEN
            IR = IRG(I)
            MSRD = .TRUE.
C
C---- Omit reflections outside R,X,Y limits (IR=1)
C                      outside resln limit (IR=4)
C                      within cusp (IR=10)
C     Will still keep reflections flagged as too wide in phi
            IF ((IR.EQ.1).OR.(IR.EQ.4).OR.(IR.EQ.10)) MSRD = .FALSE.
          END IF
C
C---- Omit reflections with fewer than 10 background pixels
C
          IF (IGFLAG(I).EQ.-64) MSRD = .FALSE.
C
C---- Reject reflections where too much of the measurement box
C     has "inactive" pixels (pixel value <= NULLPIX). At present
C     reflections with more than one third of peak pixels or one
C     half of the (non-overlapped) background pixels are
C     rejected (this test is in PROCESS) and given a flag of -128.
C     If "badspot editing" has been carried out, rejected reflections
C     are also given a flag of -128. (In BADSPOT).
C
          IF (IGFLAG(I).EQ.-128) MSRD = .FALSE.
          IF (.NOT.MSRD) GOTO 30
          ISD = ISDG(I)
C
C
          ISDPR = ISDPRO(I)
          CALL GETHKL(I,IH)
          DO 10 J = 1,3
            INHKL(J) = IH(J)
            HKL(J) = IH(J)
 10       CONTINUE
C
C---- Compute rlp coordinates and corrections
C
          CALL MATVEC(XHKL,AHAT,HKL)
          DSTSQ = DOT(XHKL,XHKL)
          IF (DSTSQ.GT.DSTCUT) THEN
            NCUT = NCUT + 1
            FLAGOUT = .FALSE.
          END IF
          SNSQ = 0.25*DSTSQ
          CS2TH = 1.0 - 2.0*SNSQ
          IFLAG = 0
          CALL LPCOR(XHKL,CS2TH,FLP,LORENTZ,IFLAG)
          IF (IFLAG.NE.0) THEN
            NLP = NLP + 1
            IGFLAG(I) = -2
            GOTO 30
          END IF
C
C---- Put indices into asymmetric unit
C
C              *************************
          CALL ASUPUT(INHKL,OUTHKL,KSYM)
C              *************************
          RECMTZ(1) = FLOAT(OUTHKL(1))
          RECMTZ(2) = FLOAT(OUTHKL(2))
          RECMTZ(3) = FLOAT(OUTHKL(3))
C
C---- MISYM flag
C
          IR = IRG(I)
          IM = IMG(I)
          IF (ADDPART) THEN
C
C---- With ADDPART option reflections  flagged with IR = 21
C     are fully recorded, flag here with MPART = 10 
C
            IF (IR.EQ.0) THEN
              MPART = 0
            ELSE IF ((IR.EQ.IR1).OR.(NEWPREF.AND.(IR.EQ.IR2))) THEN
              MPART = 10
              FRACG(I) = 1.0
            ELSE
              MPART = IR
            END IF
          ELSE
            IF (IR.EQ.5) THEN
              MPART = IMPARTG(I)
            ELSE
              MPART = IR
            END IF
          END IF
C
          MP = 0
C
C---- MP has value 0 for fulls or added partials, 1 for partials
C
          IF (MPART.GT.10) MP = 1
          RECMTZ(4) = FLOAT(MP*256 + KSYM)
          RECMTZ(5) = FLOAT(ISEROP)
          IF (NOLP) THEN
            RECMTZ(6) = FLOAT(INTG(I))/SCALEUP
            RECMTZ(7) = MAX(FLOAT(ISD)/SCALEUP,1.0)
          ELSE
            RECMTZ(6) = EDSCALE*FLP*FLOAT(INTG(I))/SCALEUP
            RECMTZ(7) = EDSCALE*FLP*MAX(FLOAT(ISD),1.0)/SCALEUP
          END IF
          INTPR = IPRO(I)
          ISDPR = ISDPRO(I)
          IF (DEBUG(50)) THEN
            X = FLOAT(INTPR)/FLOAT(ISDPR)
            Y = FLOAT(INTG(I))/FLOAT(ISD)
            IF ((X.GT.100).OR.(Y.GT.100)) THEN
              WRITE(IOUT,FMT=6060) INHKL,INTG(I),ISD,INTPR,ISDPR
              IF (ONLINE) WRITE(ITOUT,FMT=6060) INHKL,INTG(I),ISD,
     +               INTPR,ISDPR
 6060         FORMAT(1X,'Large I/sigI for reflection',3I5,
     +         '  Summation I,sd',2I8,'  profile I,sd',2I8)
            END IF
          END IF
          IF (NOLP) THEN
            RECMTZ(8) = FLOAT(INTPR)/SCALEUP
            RECMTZ(9) = MAX(FLOAT(ISDPR)/SCALEUP,1.0)
          ELSE
            RECMTZ(8) = EDSCALE*FLP*FLOAT(INTPR)/SCALEUP
            RECMTZ(9) = EDSCALE*FLP*MAX(FLOAT(ISDPR),1.0)/SCALEUP
          END IF
C
C---- Fraction calc
C
          RECMTZ(10) = FRACG(I)
C
C---- Spot coordinates. These are in pixels for CCD,IP, virtual detector mm
C     coordinates for film. Really the distinction should be between
C     on-line and offline detectors rather than IP and film.
C
          IF (IMGP) THEN
            XC = XG(I)
            YC = YG(I)
            CALL MMTOPX(XCAL,YCAL,XC,YC)
C
C---- Convert from 10 micron units to pixels
C
            XCAL = 0.01*XCAL/RAST
            YCAL = 0.01*YCAL/RAST
C
C---- If image has been stored in memory inverted right to left,
C     Correct X coordinate for this.
            IF (INVERTX) XCAL = NREC - XCAL + 1
            XCAL = MAX(XCAL,1.0)
            YCAL = MAX(YCAL,1.0)
            RECMTZ(11) = XCAL
            RECMTZ(12) = YCAL
          ELSE
            RECMTZ(11) = 0.01*XG(I)
            RECMTZ(12) = 0.01*YG(I)
          END IF
C
C---- Phi value
C
          RECMTZ(13) = PHIG(I)
          RECMTZ(14) = PHIWG(I)
          RECMTZ(15) = FLP
          RECMTZ(16) = MPART
C
C---- Reflection flag, see above for codes
C
          IF (IGFLAG(I).EQ.1) THEN
            IBAD = 0
          ELSE
            IBAD = ABS(IGFLAG(I))
          END IF
C
          RECMTZ(17) = IBAD
          RECMTZ(18) = GOODFIT(I)
C
C---- Measurement box parameters
C
          IF (NEWMTZ) THEN
            RECMTZ(19) = NXG(I)
            RECMTZ(20) = NYG(I)
            RECMTZ(21) = NCG(I)
            RECMTZ(22) = NRXG(I)
            RECMTZ(23) = NRYG(I)
          END IF
C
C---- now deal with overlapping lattices.
C
C
C---- If SINGLETON, only write out singletons
C
          IF (SINGLETON.AND.(NLATTOVLP(I).GT.0)) GOTO 29
C
C---- IOVWORK keeps track of the number of lattices actually being handled
C     (some may have been deleted in iMosflm) so use this rather than
C     NLATTICE in deciding whether to write a multilattice MTZ file. 6/9/17
C
C     29/11/18. The above change was a bad mistake and means that the multilattice
C     MTZ files written out after this date (6/9/17) will NOT be recognised
C     by POINTLESS, as test should be IOVWORK.GT.0 RATHER THAN .GT.1.
C     This affects release 7.2.2 of iMosflm/mosflm. 
C
CAL 29/11/18          IF (IOVWORK.GT.1) THEN
CAL 6/9/17  IF (NLATTICE.GT.1) THEN
           IF (IOVWORK.GT.0) THEN
            DO 21 J=19,MCOLS+3*MAXLATT+1
              RECMTZ(J) = 0
 21         CONTINUE
C
            RECMTZ(19) = ILATTICE
C
C---- Assign indices (original) for lattice being integrated
C
            ICOL = 19 +(ILATTICE-1)*3
            DO 22 K = 1,3
              ICOL = ICOL + 1
              RECMTZ(ICOL) = INHKL(K)
 22         CONTINUE
C
C---- How many overlaps for this reflection ?
C
            NLATT = NLATTOVLP(I)
            IF (NLATT.EQ.0) GOTO 28
C
            DO 27 J = 1,NLATT
              ILATT = HKLLATTOVLP(4,I,J)
C
C---- Store indices in appropriate columns
C
 24           ICOL = 19 + (ILATT-1)*3
              DO 26 K = 1,3
                ICOL = ICOL + 1
                RECMTZ(ICOL) = HKLLATTOVLP(K,I,J)
 26           CONTINUE
              IF (DEBUG(88).AND.(NDBG2.LE.NDEBUG(88))) THEN
                NDBG2 = NDBG2 + 1
                WRITE(IOUT,FMT=6110) (INHKL(K),K=1,3),MPART,
     +          NLATT,ILATT,(HKLLATTOVLP(K,I,J),K=1,3),
     +          ICOL-2
                IF (ONLINE) WRITE(ITOUT,FMT=6110) (INHKL(K),K=1,3),
     +          MPART,NLATT,ILATT,(HKLLATTOVLP(K,I,J),K=1,3),
     +          ICOL-2
 6110           FORMAT(1X,'Reflection',3I4,' MPART',I5,
     +          ' has',i2,' overlaps',
     +          /,1x,'overlap lattice',i2,
     +          ' indices',3i4,' stored starting at col',I3)
              END IF
 27         CONTINUE
          END IF


 28       IF (DEBUG(50).AND.((NDBG.LE.NDEBUG(50)).OR.(MPART.EQ.2)))THEN
             NDBG = NDBG + 1
             IGOOD = INT(GOODFIT(I))
             GRAD = GOODFIT(I) - IGOOD
             IPKR = IGOOD/100
             BGRAT = 0.1*(IGOOD-IPKR*100)
             PKRAT = 0.01*IPKR
             WRITE(IOUT,FMT=6000) I,FLAGOUT,INHKL,OUTHKL,
     +             (RECMTZ(K),K=4,MCOLS-1),IR,IM,GRAD,BGRAT,PKRAT
             IF (ONLINE) WRITE(ITOUT,FMT=6000) I,FLAGOUT,INHKL,OUTHKL,
     +       (RECMTZ(K),K=4,MCOLS-1),IR,IM,GRAD,BGRAT,PKRAT
 6000        FORMAT(1X,'Reflection',I5,' FLAGOUT ',L1,'  orig h,k,l',
     +       3I4,' output hkl',3I4,' MISYM',F6.0,
     +       ' ISEROP',F7.0,' Int,sd',F8.0,F6.0,' Intpr,sd',2F8.0,/,1X,
     +       ' Frcalc ',F6.4,'  Det X,Y',2F6.0,' Phi',F9.3,' Width',
     +       F6.3,' Lp Factor',F9.6,' MPART',F5.0,' IGFLAG',F5.0,
     +       ' IR',I3,' IM',I4, 'Grad',F6.3,' BGratio',F6.2,
     +       ' PKratio',F6.2)
          END IF
C
C          *********************
          IF (FLAGOUT) CALL LWREFL(MTZOUT,RECMTZ)
C          *********************
          IF (FLAGOUT) NOUT = NOUT + 1
C
C---- now write ASCII file of reflections for BEST - convert partials
C     to pseudo-fulls by dividing intensity by partiality
C     
          IF(LBEST)THEN
C     
C---- Phi of reflection is recmtz(13) = PHIG(I), width is recmtz(14) =
C     PHIWG(I), fraction is recmtz(10) = FRACG(I), uncorrected (profile)
C     intensity is recmtz(8) = FLOAT(INTPR), Lp factor is RECMTZ(15) = FLP,
C     but should we use LORENTZ here instead?
C     
            CMOSAICN = CMOSAICN + (FLP * PHIWG(I) * SQRT(ABS(SNSQ)))
            CMOSAICD = CMOSAICD + ((FLP * SQRT(ABS(SNSQ))))**2
            CMOSAICNL = CMOSAICNL + 
     $           (PHIWG(I) * SQRT(ABS(SNSQ))/lorentz)
            CMOSAICDL = CMOSAICDL + ((SQRT(ABS(SNSQ)))/lorentz)**2
            IF((RECMTZ(13).GE.PHIBEG).AND.(RECMTZ(13).LE.PHIEND))THEN
              BESTSIG = MAX(RECMTZ(9),1.0)
C     .. flag overloads
C     ..
              IF((IBAD.GE.16).AND.(IBAD.LT.32))BESTSIG = -BESTSIG
C     .. fulls
C     ..
              IF(MP.EQ.0)THEN
                IF(.NOT.BESTOPEN)THEN
                  CALL CCPOPN(-BESTHKL,BSTHKL,1,1,LDUM,IFAIL)
                  BESTOPEN = .TRUE.
                ENDIF
                WRITE(BESTHKL,FMT=6040)INHKL(1),INHKL(2),INHKL(3),
     &               RECMTZ(8),BESTSIG
              ELSEIF (RECMTZ(10).GE.0.1)THEN
C     .. partials with > 0.1 present
C     ..
                IF(.NOT.BESTOPEN)THEN
                  CALL CCPOPN(-BESTHKL,BSTHKL,1,1,LDUM,IFAIL)
                  BESTOPEN = .TRUE.
                ENDIF
                WRITE(BESTHKL,FMT=6040)INHKL(1),INHKL(2),INHKL(3),
     $               RECMTZ(8)/RECMTZ(10),BESTSIG/RECMTZ(10)
C              ELSE
C     .. partials with < 0.1 present - not written
C     ..
C                WRITE(IBEST,FMT=6050)INHKL(1),INHKL(2),INHKL(3),
C     $               BESTSIG,recmtz(10),recmtz(14)
              ENDIF
 6040         FORMAT(3(I4,1X),2(F10.2,1X))
 6050         FORMAT(3I4,'      0.00',F10.2)
            ENDIF
          ENDIF
C
C
C---- Now store converted indices, MISYM, and corrected Intensity and sd for
C     Rsym analysis on image by image basis.
C
 29       IHG(I) = OUTHKL(1)
          IKG(I) = OUTHKL(2)
          ILG(I) = OUTHKL(3)
          MISYMG(I) = NINT(RECMTZ(4))
          IMPARTG(I) = MPART
          IPRO(I) = NINT(RECMTZ(8))
          ISDPRO(I) = MAX(NINT(RECMTZ(9)),1)
          INTG(I) = NINT(RECMTZ(6))
          ISDG(I) = MAX(NINT(RECMTZ(7)),1)
 30   CONTINUE
C
C
C---- Format statements            
C
      WRITE(IOUT,FMT=6010) NOUT,ISEROP
      IF (ONLINE) WRITE(ITOUT,FMT=6010) NOUT,ISEROP
 6010 FORMAT(1X,I6,' Reflections written to MTZ file with batch ',
     +       'number',I8)
C
      IF (NLP.NE.0) THEN 
        WRITE(IOUT,FMT=6020) NLP
        IF (ONLINE) WRITE(ITOUT,FMT=6020) NLP
 6020   FORMAT(1X,I5,' Reflections rejected because LP correction ',
     +         'could not be calculated')
      END IF
      IF (NCUT.NE.0) THEN 
        WRITE(IOUT,FMT=6022) NCUT,DMAX
        IF (ONLINE) WRITE(ITOUT,FMT=6022) NCUT,DMAX
 6022   FORMAT(1X,I5,' Reflections rejected because they were beyond',
     +         ' limiting resolution of',F6.2,'A')
      END IF
C
      IF(LBEST)THEN
        CALL SAVEINP
CHRP        LBEST = .FALSE.
      ENDIF
      END



C $Id: wspot.f,v 1.20 2021/03/15 11:26:53 andrew Exp $
      SUBROUTINE WSPOT(IFLAG)
      IMPLICIT NONE
C
C---- Open file and write an edited spots file (IMSTILLS style)
C     IFLAG if non-zero on input, do not ask for new file name
C     Returns status flag IFLAG
C     IFLAG =  0  OK
C           =  1  Failed to write file
c           = -1  No spots written to file
C
C     .. Parameters ..
C&&*&& include  ../inc/parameter.f
C
C $Id: parameter.f,v 1.34 2020/12/15 20:08:54 andrew Exp $
C
C--- awk generated include file  parameter.h
C---- START of include file parameter.h
C
C       PARAMETERS
C       IYLENGTH.. maximum number of I*2 words of data in the 
C                  "fast" (ie most rapidly changing) direction in the
C                  digitised image. This will be HALF the number of pixels
C                  for film data (each pixel is stored in one byte)
C                  but will equal the number of pixels for IP data.
C       IXWDTH...  The maximum number of "stripes" of data in the scanned image
C                  ie the number of pixels in the "slow" direction
C                  (This is the Y direction in the MOSFLM convention)
C                  Note that the array "IMAGE" used to store the image is
C                  declared as size IYLENGTH*IXWDTH I*2 words for IP data
C                  and 2*IYLENGTH*IXWDTH BYTES for film data.
C                  If this exceeds the
C                  available memory, set ixwdth=1, recompile program
C                  and use keyword "NOCORE" when running program.
C                  Note that for the POSTREF and ADDPART options,
C                  two images have to be stored in memory at once so
C                  IXWDTH should be twice the number of records in an
C                  image.
C       MAXHEAD    maximum length of image header (in 4 byte words)
C       NREFLS.... maximum number of spots per film in generate file (250,000)
C       MAXBOX.... maximum number of pixels in measurement box (3000)
C       MAXDIM.... maximum box size in either direction (pixels) (41)
C       MAXPAX.... maximum number of packs per generate file (10000)
C       MXDOV2..... maxdim/2
C       MAXBUFF... maximum size of buffer (I*2) for storing ods
C                  of active spots in subroutine meas(42,000). 
C                  Must be .GE.  2 * MAXBOX*(NNLINE-1) for subroutine process,
C                  where it is an I*4 array, everywhere else I*2.
C       MREF...... maximum number of reflections to be used in post
C                  refinement (6000)
C       NEXPAND... maximum number of expansions of the input measurement
C                  box (2)
C       NMASKS.... maximum number of different profiles (25). Note the
C                  connection between this parameter and NNLINE
C       NVECT..... maximum number of vectors for storing scanned image
C                  in filmplot (10000)
C       NIMAX..... maximum number of images to be used together in 
C                  postrefinement (NADD or WIDTH options) (400)
C       NNLINE...  maximum number of boundary lines for setting up
C                  the areas for profile fitting. The maximum possible
C                  number of standard profiles will be (NNLINE-1)**2
C                  although for a circular detector the actual number
C                  may be less than this as some boxes will lie entirely
C                  outside the detector.
C       NREJMAX... Maximum number of rejected background pixels, resulting
C                  either from overlap of adjacent spots or outliers from
C                  the background plane
C       NSPOTS...  Maximum number of found spots (for autoindexing) that can
C                  be stored (for all images). Also maximum number in 
C                  a file wriitten by IMSTILLS that can be 
C                  stored/displayed/edited. THis must be an even number
C       MCOLS....  Number of columns in output MTZ file
C       MCOLSTR..  Number of columns in output MTZ file for strategy option
C     
C       MTZ Orientation block
C        MBLENG is total length of block, MBLINT, MBLREA are numbers
C          of integers & reals
C       NDETREF    Maximum number of reflections used for detector parameter
C                  refinement (previously 62)
C       NRPAR....  Maximum number of refineable parameters for detector
C                  positional refinement (subroutine RDIST)
C       NSEGMAX..  Maximum number of segments in STRATEGY
C       NSEGMAXPR  Maximum number of segments in POST-REFINEMENT
C       MULTMAX... Maximum number of observations with same hkl in COMPLETE
C       MAXDIFF... Maximum number of different packs that a given hkl occurs on
C       NRESBIN... Maximum number of resolution bins (COMPLETE)
C
C       MAXIMG...  Maximum number of images that can be read in using the IMAGE
C                  keyword or the "read Image" menu option.
C       MXSPOT...  Maximum number of spots that can be found on one image
C                  (before rejection on spot size).
C       MXCENT...  Maximum number of active spots during spot finding 
C                  (findspots)
C
C       MGRA, NGRA... maximum number of reflections and images over which a 
C                     reflection can be spread for postrefinement.
C       MAXBGBOX    Maximum number of local background background boxes 
C                   in X and Y
C
C       MAXNPEAKS   Maximum number of local maxima within one spot
C       MAXEXCL     Maximum number of excluded areas of the same type
C                   eg reactangles, quadrilaterals, arcs, resolution shells
C
C       NLAUEG      Number of Laue Groups in indexing routines
C
C       MAXLATT     Maximum number of lattices we can find in indexing
C
C       MAXIWARN    Array limit of first element of IWARN
C
C     .. Parameters ..
      INTEGER IXWDTH
c      PARAMETER (IXWDTH=8192)
      PARAMETER (IXWDTH=12288)
      INTEGER IYLENGTH
