     +     DIVH,DIVV,DELAMB,ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,
     +     ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,
     +     BLKSIZE
      INTEGER ISYN,IMONO,NWMAX,IPAD,NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS
C     ..
C     .. logicals in common block /REEKE/ ..
      LOGICAL LOGETA,NUREEK,LCAMCON,GENGON,FOURCIRCLE,THREECIRCLE,
     +        VERTICAL
C     ..
C     .. Common Block /REEKE/ ..
      COMMON /REEKE/RMC(3,3),AMAT(3,3),SCAXIS(3),S0(3),s0unit(3),
     $     CAMCON(8),BEAMMU(2),X1,X2,Y1,Y2,
     +     Z1,Z2,XYS,DSTAR2,DSTMAX,DSTPL,DSTPL2,DIVH,DIVV,DELAMB,
     +     ETA,DELCOR,DSTMAXS,TOR,DSTMIN,WMAX,ETAFRAC,ETASM,
     $     GON_CHI,GON_PHIS,GON_KAPPA,GON_OMEGAS,GON_2THETA,
     $     GON_PHIE,GON_OMEGAE,
     +     GON_CHI_SET,GON_KAPPA_SET,ISYN,IMONO,
     $     NWMAX,IPAD,
     $     NSMOOTH,IGON_CHI,IGON_PHI,
     $     IGON_KAPPA,IGON_OMEGA,IGON_2THETA,
     +     IGON_CHI_SET,IGON_KAPPA_SET,IHOSCAXIS,LOGETA,NUREEK,LCAMCON,
     $     GENGON,FOURCIRCLE,THREECIRCLE,
     +     BLKSIZE,VERTICAL
C     ..
C
C
C&&*&& end_include  ../inc/reeke.f
      SAVE
C     ..
      INFOCOUNT = 0
      WARNCOUNT = 0
      WARNING = .FALSE.
      IGNORE = .TRUE.
C
C---- Decide if number of profiles with intruding spots is serious or worrying
C     More than 10% gives SERIOUS warning, more than 5% worrying, less than this
C     results in no warning
C
      IF (XWARN(1,36).GT.0) THEN
         FRACBADPROF = 100.0*XWARN(2,36)/XWARN(1,36)
         IF (FRACBADPROF.GT.10.0) THEN
           WARN(37) = .TRUE.
           WARN(36) = .FALSE.
         ELSE IF (FRACBADPROF.GT.5.0) THEN
           WARN(36) = .TRUE.
           WARN(37) = .FALSE.
         ELSE
           WARN(36) = .FALSE.
           WARN(37) = .FALSE.
         END IF
      END IF

C
C---- Set traffic light colour for iMosflm Status
C
      TRAFFCOL = 'GREEN'
C
C---- Set up background colours for exclamation mark in warnings list in iMosflm
C
      SERIOUSCOLOUR = 'RED'
      WORRYCOLOUR = 'ORANGE'
      INFOCOLOUR = 'GREEN'
      DO 10 I=1,50
        IF (WARN(I))THEN
          WARNING = .TRUE.
          INFO = ((I.EQ.1).OR.((I.EQ.2).AND.IMGP).OR.(I.EQ.3).OR.
     +        (WARN(8).AND.(XWARN(1,8).LT.1))
     +        .OR.(I.EQ.10).OR.(I.EQ.11).OR.((I.EQ.12).AND.IMGP)
     +        .OR.(I.EQ.20).OR.((I.EQ.21).AND.(.NOT.DENSE))
     +        .OR.(I.EQ.25).OR.(I.EQ.28).OR.(I.EQ.38))
          IF (INFO) THEN
            INFOCOUNT = INFOCOUNT + 1
          ELSE
            WARNCOUNT = WARNCOUNT + 1
          ENDIF
        ENDIF
 10   CONTINUE
C
C---- Set traffic light colour orange for worrying warnings
C
      IF (WARN(5).OR.WARN(6).OR.WARN(7).OR.
     +     (WARN(8).AND.(XWARN(1,8).GT.900)).OR.WARN(18).OR.WARN(24)
     +    .OR.WARN(25).OR.WARN(29).OR.WARN(32).OR.WARN(33)
     +    .OR.WARN(36).OR.WARN(39)) 
     +     TRAFFCOL = 'ORANGE'
C
C---- Set traffic light colour red for serious warnings
C
      IF (WARN(4).OR.(WARN(8).AND.(XWARN(1,8).GT.9000)).OR.
     +  WARN(9).OR.WARN(16).OR.WARN(19).OR.
     + (WARN(25).AND.(XWARN(1,25).GE.0.01)).OR.
     +  (WARN(32).AND.(XWARN(1,32).GT.0.2)).OR.
     +  (WARN(33).AND.(XWARN(1,33).GT.0.2)).OR.
     +  WARN(34).OR.WARN(35).OR.WARN(37).OR.
     +  (WARN(39).AND.(XWARN(1,39).GE.0.10)).OR.
     +  WARN(40).OR.WARN(41).OR.WARN(42).OR.WARN(44)) TRAFFCOL = 'RED'
C
      write(iout,fmt=5000) traffcol
      if (online) write(itout,fmt=5000) traffcol
 5000 format(1x,'Traffic light colour ',A)
      IF((INFOCOUNT.EQ.0).AND.(WARNCOUNT.EQ.0))RETURN
c      WRITE(IOUT,6000)
      XMLLINE = ' '
      WRITE(XMLLINE,6000)
      CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $     XMLLINE)
      XMLLINE = ' '
      WRITE(XMLLINE,6010) TRAFFCOL
      CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $     XMLLINE)
C
C---- Give serious errors first
C
C---- Too few spots in CENTRS
        IF (WARN(4)) THEN
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7008)
          WRITE(XMLLINE,FMT=7008) SERIOUSCOLOUR
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C---- Inner profiles have been averaged
        IF (WARN(8).AND.(XWARN(1,8).GT.9000)) THEN
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7017) SERIOUSCOLOUR,NBADAVG,WAVE/DSTMAX,
     +      LIST(1:LENSTR(LIST)),(ILIST(I),I=1,9)
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C---- BGRATIO too large or too small
        IF (WARN(9)) THEN
          IF (IMGP) THEN
            X = 0.5*(XWARN(1,9)+XWARN(2,9))
            XMLLINE = ' '
            WRITE(XMLLINE,FMT=7018) SERIOUSCOLOUR,XWARN(1,9),XWARN(2,9),
     +           GAIN, GAIN*X**2,GAIN*X**2
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
          ELSE
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7020)XWARN(1,9),XWARN(2,9)
            WRITE(XMLLINE,FMT=7020)SERIOUSCOLOUR,XWARN(1,9),XWARN(2,9)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
          END IF
        END IF

C
C---- Negative refined (mosaic spread + beam divergence)
C
        IF (WARN(16)) THEN 
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7046)
          WRITE(XMLLINE,FMT=7046) SERIOUSCOLOUR
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
C----
          IF (USEBEAM) THEN
            IF (PRNS.EQ.1) THEN
              XMLLINE = ' '
c              WRITE(IOUT,FMT=7050)
              WRITE(XMLLINE,FMT=7050)
              CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $             XMLLINE)
C---- 
            ELSE
              XMLLINE = ' '
c              WRITE(IOUT,FMT=7052)
              WRITE(XMLLINE,FMT=7052)
              CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $             XMLLINE)
            END IF
          END IF
C----
          IF (PRNS.EQ.2) THEN
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7048)
            WRITE(XMLLINE,FMT=7048)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
          END IF
          XMLLINE = ' '
c          WRITE(IOUT,FMT=70031)
          WRITE(XMLLINE,FMT=70031)
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C
C---- Refined mosaic spread less than 0.25* input value and used
C
        IF (WARN(19).AND.(.NOT.WARN(16))) THEN
          IF (PRNS.EQ.1) THEN
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7058)  SERIOUSCOLOUR
            WRITE(XMLLINE,FMT=7058)  SERIOUSCOLOUR
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
CAL          ELSE IF (PRNS.EQ.2) THEN
CAL            XMLLINE = ' '
c            WRITE(IOUT,FMT=7060)
CAL            WRITE(XMLLINE,FMT=7060)
CAL            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
CAL     $           XMLLINE)
          END IF
        END IF
C
C---- too many spatial overlaps (more than 20%)
C
        IF (WARN(32).AND.(XWARN(1,32).GE.0.20)) THEN 
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7106)SERIOUSCOLOUR,NINT(100*XWARN(1,32))
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C
C---- Average image to image change in missets greater than 0.2
C
        IF (WARN(33).AND.(XWARN(1,33).GE.0.20)) THEN
          N = 1 + IWARN(1,33)
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7108) WORRYCOLOUR,XWARN(1,33),
     +    IWARN(1,33),NBLOCK,(IWARN(J,33), J = 2,N)
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          N = 1 + IWARN(1,33)
          WRITE(XMLLINE,FMT=7109) 
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C
C---- rejects an averaged standard profile
C
        IF (WARN(34)) THEN
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7110) SERIOUSCOLOUR,IWARN(1,34),WAVE/DSTMAX
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C
C---- adjacent spots included in  peak area of central profile
C
        IF (WARN(35)) THEN
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7120) SERIOUSCOLOUR,XWARN(2,35),XWARN(3,35)
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C
C---- adjacent spots included in peak region of standard profile for more than
C     10% of profiles
C
        IF (WARN(37)) THEN
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7130) SERIOUSCOLOUR,FRACBADPROF
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
C
C---- Avoid array bounds limit, only list first 19. Note now need to access
C     numbers in IWARN(1,36), as IWARN(1,37) is not used any more
C
          NBADBLOCK = IWARN(1,36)
          NBADLIMIT = MIN(NBADBLOCK,19)
          WRITE(XMLLINE,FMT=7132) 
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)        
          DO 20 I = 1,NBADLIMIT
C
C---- Maximum of 9 bad profiles to be listed
C
            NBADBOX = MIN(IWARN(10*I+11,36),9)
C            write(iout,fmt=9876) i,nbadlimit,nbadbox
C 9876       format(1x,'I:',I3,' NBADLIMIT:',I5,' NBADBOX',I5)
            WRITE(XMLLINE,FMT=7133) IWARN(I+1,36),
     +        (IWARN(10*I+11+J,36), NINT(100*XWARN(10*I+11+J,36)),
     +         J = 1,NBADBOX)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
 20       CONTINUE
          WRITE(XMLLINE,FMT=7134) TOLMIN,TOL
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)        
        END IF

C
C---- too many reflections too wide in phi (more than 10%)
C
        IF (WARN(39).AND.(XWARN(1,39).GE.0.10)) THEN 
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7152) SERIOUSCOLOUR,NINT(100*XWARN(1,39)),
     +                            WMAX,WMAX+5.0
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C
C---- Cell refinement stopped because cell shift > 10%
C
        IF (WARN(40)) THEN 
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7154) SERIOUSCOLOUR
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF

C
C---- Cell refinement stopped postref residual too high
C
        IF (WARN(41)) THEN 
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7156) SERIOUSCOLOUR
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C
C---- One or more images skipped because too large positional residual. Check
C     explicitly to see if all images have been rejected and change warning.
C
        IF (WARN(42)) THEN
          IF (IWARN(1,42).EQ.IWARN(100,42)) THEN
C
C----- All images have been rejected
C
            XMLLINE = ' '
            WRITE(XMLLINE,FMT=7162) SERIOUSCOLOUR,XWARN(1,42)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
            WRITE(XMLLINE,FMT=7164)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          ELSE
            J = MIN(11,1+IWARN(1,42))
            XMLLINE = ' '
            WRITE(XMLLINE,FMT=7158) SERIOUSCOLOUR,
     +            IWARN(1,42),XWARN(1,42),(IWARN(I,42),I=2,J)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
            WRITE(XMLLINE,FMT=7160)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          END IF                                       
        END IF                                       
C
C---- More than 10 reflections flagged as outside active area
C
        IF (WARN(44)) THEN
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7180) SERIOUSCOLOUR,
     +       100*XWARN(1,44),NULLPIX 
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF           
C
C---- Now "WORRYING" class
C
C---- too many spatial overlaps (more than 10%)
C
        IF (WARN(32).AND.((XWARN(1,32).GT.0.10).AND.
     +                    (XWARN(1,32).LT.0.20))) THEN 
          XMLLINE = ' '
CAL          WRITE(IOUT,FMT=7106) WORRYCOLOUR,NINT(100*XWARN(1,32))
          WRITE(XMLLINE,FMT=7106) WORRYCOLOUR,NINT(100*XWARN(1,32))
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C
C---- Slippage > (eta + divv)
C     Set in MOSFLM
        IF (WARN(5)) THEN
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7010) XWARN(1,5),IWARN(1,5)
          WRITE(XMLLINE,FMT=7010) WORRYCOLOUR,XWARN(1,5),IWARN(1,5)
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C---- Weighted residual > 1.5
        IF (WARN(6)) THEN
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7012)XWARN(1,6)
          WRITE(XMLLINE,FMT=7012) WORRYCOLOUR,XWARN(1,6)
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C---- Too many badspots (>10)
        IF (WARN(7)) THEN
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7014) IWARN(1,7)
          WRITE(XMLLINE,FMT=7014) WORRYCOLOUR,IWARN(1,7)
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C---- Inner profiles have been averaged
        IF (WARN(8).AND.
     +       ((XWARN(1,8).GT.900).AND.(XWARN(1,8).LT.9000))) THEN
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=70117) WORRYCOLOUR,NBADAVG,WAVE/DSTMAX,
     +      LIST(1:LENSTR(LIST)),(ILIST(I),I=1,9)
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C
C---- Spots in central region with zero pixel values
C
        IF (WARN(14).AND.(.NOT.TILED).AND.(NULLPIX.EQ.0)) THEN
C          ILIM = NINT(0.01*LIMIT)
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7042) WORRYCOLOUR,NULLPIX,NULLPIX,
c     +          0.01 * LIMIT
c          IF (ONLINE)WRITE(ITOUT,FMT=7042) WORRYCOLOUR,NULLPIX,NULLPIX,
c     +          0.01 * LIMIT
          WRITE(XMLLINE,FMT=7042) WORRYCOLOUR,NULLPIX,
     +                 NULLPIX,0.01 * LIMIT
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C
C---- Poorly defined cell parameters
C
        IF (WARN(18)) THEN
C
C---- Find out which cell parameters are poorly determined
C
          STR = ' '
          IF (IWARN(1,18).EQ.1)STR=STR(1:MAX(1,LENSTR(STR)))//' A'
          IF (IWARN(2,18).EQ.1)STR=STR(1:MAX(1,LENSTR(STR)))//' B'
          IF (IWARN(3,18).EQ.1)STR=STR(1:MAX(1,LENSTR(STR)))//' C'
          IF (IWARN(4,18).EQ.1)STR=STR(1:MAX(1,LENSTR(STR)))//' Alpha'
          IF (IWARN(5,18).EQ.1)STR=STR(1:MAX(1,LENSTR(STR)))//' Beta'
          IF (IWARN(6,18).EQ.1)STR=STR(1:MAX(1,LENSTR(STR)))//' Gamma'
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7056)STR(1:MAX(1,LENSTR(STR))),
c     +                         (XWARN(I,18),I=1,6)
          DO I = 1,6
            PXWARN(I) = MIN(999.0,XWARN(I,18))
          ENDDO

          WRITE(XMLLINE,FMT=7056)WORRYCOLOUR,STR(1:MAX(1,LENSTR(STR))),
     +                         (XWARN(I,18),I=1,6)
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C
C---- not many reflections in post-refinement
C
        IF (WARN(24)) THEN
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7094)
          WRITE(XMLLINE,FMT=7094) WORRYCOLOUR
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C
C---- Large YSCALE deviation, SERIOUS if > 0.01
C
          IF (WARN(25)) THEN
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7096) XWARN(1,25)
            IF (XWARN(1,25).GE.0.01) THEN
              WRITE(XMLLINE,FMT=7096) SERIOUSCOLOUR,XWARN(1,25)
            ELSE
              WRITE(XMLLINE,FMT=7096) WORRYCOLOUR,XWARN(1,25)
            END IF
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          END IF
C
C----  Profile correlation coefficient less than 0.6. MIN value
C
        IF (WARN(29)) THEN
          IJ = MIN(IWARN(1,29),6)
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7104)IWARN(1,29), XWARN(1,29)
          WRITE(XMLLINE,FMT=7104) WORRYCOLOUR,IWARN(1,29), XWARN(1,29)
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          XMLLINE = ' '
          DO 1040 K=1,IJ
c            WRITE(IOUT,FMT=7105)
c     +           IWARN(2*K,29),IWARN(2*K+1,29),XWARN(K+1,29)
            WRITE(XMLLINE,FMT=7105)
     +           IWARN(2*K,29),IWARN(2*K+1,29),XWARN(K+1,29)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
 1040     ENDDO
          XMLLINE = ' '
c          WRITE(IOUT,FMT=71051)
          WRITE(XMLLINE,FMT=71051)
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C
C---- Average image to image change in missets > 0.1 AND < 0.2
C
        IF (WARN(33).AND.(XWARN(1,33).LT.0.20)) THEN
          N = 1 + IWARN(1,33)
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7108) WORRYCOLOUR,XWARN(1,33),
     +    IWARN(1,33),NBLOCK,(IWARN(J,33), J = 2,N)
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          N = 1 + IWARN(1,33)
          WRITE(XMLLINE,FMT=7109) 
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF

C
C---- adjacent spots included in peak region of standard profile for less than
C     10% of profiles
C     
C
        IF (WARN(36)) THEN
          XMLLINE = ' '
          NBADBLOCK = IWARN(1,36)
          NBADLIMIT = MIN(NBADBLOCK,19)
          WRITE(XMLLINE,FMT=7130) WORRYCOLOUR,FRACBADPROF
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          WRITE(XMLLINE,FMT=7132) 
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)        
          DO 30 I = 1,NBADLIMIT
            NBADBOX = IWARN(10*I+11,36)
            WRITE(XMLLINE,FMT=7133) IWARN(I+1,36),
     +        (IWARN(10*I+11+J,36), NINT(100*XWARN(10*I+11+J,36)),
     +         J = 1,NBADBOX)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
 30       CONTINUE
          WRITE(XMLLINE,FMT=7134) TOLMIN,TOL
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)        
        END IF

C
C---- too many reflections too wide in phi (more than 5% but less than 10%)
C
        IF (WARN(39).AND.(XWARN(1,39).LT.0.10)) THEN 
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7152) WORRYCOLOUR,NINT(100*XWARN(1,39)),
     +                            WMAX,WMAX+5.0
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C
C---- Detector parameters changed for MicroED
C
        IF (WARN(43)) THEN
          XMLLINE = ' '
          WRITE(XMLLINE,FMT=7170) WORRYCOLOUR,
     +                            GAIN, IDIVIDE
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF


C
C---- For information only
C    
      IF(INFOCOUNT.GT.0)THEN
C---- ADDPART
        IF ((WARN(2).OR.WARN(3).OR.WARN(12)).AND.ADDPART) THEN
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7007)
          WRITE(XMLLINE,FMT=7007) INFOCOLOUR
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $       XMLLINE)
        END IF

C---- Spot overlap
          IF (WARN(1)) THEN
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7002)0.01*IXSEP,0.01*IYSEP,
c     +                           (XWARN(K,1),K=1,4),TOL
            WRITE(XMLLINE,FMT=7002) INFOCOLOUR,0.01*IXSEP,0.01*IYSEP,
     +                           (XWARN(K,1),K=1,4),TOL
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
            IF (.NOT.DENSE) THEN
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7003)
            WRITE(XMLLINE,FMT=7003)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
            END IF
            XMLLINE = ' '
c            WRITE(IOUT,FMT=70031)
            WRITE(XMLLINE,FMT=70031)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          END IF

C---- ROFF
          IF (WARN(2).AND.IMGP) THEN
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7004)XWARN(1,2),RAST
            WRITE(XMLLINE,FMT=7004) INFOCOLOUR,XWARN(1,2)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
            IF ((.NOT.FIXPAR(10)).OR.(.NOT.FIXPAR(11))) THEN
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7005)
            WRITE(XMLLINE,FMT=7005)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
            END IF
            XMLLINE = ' '
c            WRITE(IOUT,FMT=70031)
            WRITE(XMLLINE,FMT=70031)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          END IF
C---- CCOMEGA
          IF (WARN(3)) THEN
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7006) XWARN(1,3)
            WRITE(XMLLINE,FMT=7006) INFOCOLOUR,XWARN(1,3)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
C---- roff & toff unstable too
            IF(WARN(2).AND.WARN(13))THEN
              XMLLINE = ' '
c              WRITE(IOUT,FMT=70061)
              WRITE(XMLLINE,FMT=70061)
              CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $             XMLLINE)
            ENDIF
            XMLLINE = ' '
c            WRITE(IOUT,FMT=70031)
            WRITE(XMLLINE,FMT=70031)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          END IF

C---- Profile averaging
          IF (WARN(8).AND.(XWARN(1,8).LT.1)) THEN
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7016)
            WRITE(XMLLINE,FMT=7016) INFOCOLOUR
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          END IF
C---- Too many spots with too few background points
          IF (WARN(10)) THEN
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7022)IWARN(1,10),NBGMIN,BGSIG
            WRITE(XMLLINE,FMT=7022) INFOCOLOUR,IWARN(1,10),NBGMIN,BGSIG
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
            IF (WARN(1)) THEN
              XMLLINE = ' '
c              WRITE(IOUT,FMT=7024)
              WRITE(XMLLINE,FMT=7024)
              CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
            ELSE
              XMLLINE = ' '
c              WRITE(IOUT,FMT=7026)
              WRITE(XMLLINE,FMT=7026)
              CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
              IF (WARN(9)) THEN
                XMLLINE = ' '
c                WRITE(IOUT,FMT=7028)
                WRITE(XMLLINE,FMT=7028)
                CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $             XMLLINE)
              ELSE
                XMLLINE = ' '
c                WRITE(IOUT,FMT=7030)
                WRITE(XMLLINE,FMT=7030)
                CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $             XMLLINE)
              END IF
            END IF
            XMLLINE = ' '
c           WRITE(IOUT,FMT=70031)
            WRITE(XMLLINE,FMT=70031)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          END IF
C---- Profiles have long tails
          IF (WARN(11)) THEN
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7032) 100.0*XWARN(1,11),TOL
            WRITE(XMLLINE,FMT=7032) INFOCOLOUR,100.0*XWARN(1,11),TOL
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          END IF

C---- TOFF
          IF (WARN(12).AND.IMGP) THEN
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7034)XWARN(1,12)
            WRITE(XMLLINE,FMT=7034) INFOCOLOUR,XWARN(1,12)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
            IF (ADDPART) THEN
              XMLLINE = ' '
c              WRITE(IOUT,FMT=7035)
              WRITE(XMLLINE,FMT=7035)
              CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
            END IF
            XMLLINE = ' '
c            WRITE(IOUT,FMT=70031)
            WRITE(XMLLINE,FMT=70031)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          END IF

C----Profiles extend beyond peak
C
          IF (WARN(20)) THEN
            I = IWARN(1,20)
            IPR = MIN(I,19) + 1
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7070) I
            WRITE(XMLLINE,FMT=7070) INFOCOLOUR,I
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
C----
            IF (TOL.GT.0.03) THEN
               XMLLINE = ' '
c              WRITE(IOUT,FMT=7072) TOL
              WRITE(XMLLINE,FMT=7072) TOL
              CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $             XMLLINE)
            END IF
C----
            DO 1020 K=2,IPR
              XMLLINE = ' '
c              WRITE(IOUT,FMT=7074)IWARN(K,20),XWARN(K,20)
              WRITE(XMLLINE,FMT=7074)IWARN(K,20),XWARN(K,20)
              CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
 1020       ENDDO
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7075)
            WRITE(XMLLINE,FMT=7075)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
            IF (TOL.GT.0.03) THEN
              XMLLINE = ' '
c              WRITE(IOUT,FMT=7076) TOL
              WRITE(XMLLINE,FMT=7076) TOL
              CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
            END IF
C----
            IF (ADDPART) THEN
              XMLLINE = ' '
c              WRITE(IOUT,FMT=7073)
              WRITE(XMLLINE,FMT=7073)
              CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
            END IF
            XMLLINE = ' '
c            WRITE(IOUT,FMT=70031)
            WRITE(XMLLINE,FMT=70031)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          END IF
C---- Too many background pixels overlapped by neighborouing spots
C
          IF (WARN(21).AND.(.NOT.DENSE)) THEN
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7080) 100.0*XWARN(1,21)
            WRITE(XMLLINE,FMT=7080) INFOCOLOUR,100.0*XWARN(1,21)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          END IF
C
C---- Too few background pixels
C
          IF (WARN(28)) THEN
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7102)NBGMIN,RECLEVEL
            WRITE(XMLLINE,FMT=7102) INFOCOLOUR,NBGMIN,RECLEVEL
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          END IF
C
C---- Profile tolerance increased
C
          IF (WARN(38)) THEN
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7150) TOLMIN,TOL
            WRITE(XMLLINE,FMT=7150) INFOCOLOUR,TOLMIN,TOL
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          END IF

C
C---- End of information messages
C
        END IF

C
C---- IGNORE remaining
C
       IF (IGNORE) THEN
         XMLLINE = ' '
c        WRITE(IOUT,FMT=8000)
         WRITE(XMLLINE,FMT=8000)
         CALL WRITE_SOCKET_LENGTH(SERVERFD, LENSTR(XMLLINE),
     $     XMLLINE)
         RETURN
       END IF

C
C---- Adjacent images have exposures differing by more than 5% (as 
C     judged from background of spots in post-refinement
C
        IF (WARN(13).AND.ADDPART) THEN
          NBAD = IWARN(1,13)
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7036)NBAD
          WRITE(XMLLINE,FMT=7036)NBAD
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
c can't do this quite like this
          DO 1000 I = 2,NBAD+1
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7038)IWARN(I,13),XWARN(I,13)
            WRITE(XMLLINE,FMT=7038)IWARN(I,13),XWARN(I,13)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
 1000     ENDDO
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7040)
          WRITE(XMLLINE,FMT=7040)
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          
        END IF

C
C---- Not many fully recorded reflections
C
        IF (WARN(15).AND.(.NOT.USEPAR)) THEN
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7044)
          WRITE(XMLLINE,FMT=7044)
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF

        IF (WARN(22).AND.(.NOT.WARN(23))) THEN
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7090) IWARN(1,22),PTMIN
          WRITE(XMLLINE,FMT=7090) IWARN(1,22),PTMIN
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
          IF (.NOT.PRFULLS) THEN
            XMLLINE = ' '
c            WRITE(IOUT,FMT=7091)
            WRITE(XMLLINE,FMT=7091)
            CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $           XMLLINE)
            
          END IF
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7089)
          WRITE(XMLLINE,FMT=7089)
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
        IF (WARN(23)) THEN
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7092)PTMIN
          WRITE(XMLLINE,FMT=7092)PTMIN
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF

        IF (WARN(26)) THEN
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7098) NPRMIN
          WRITE(XMLLINE,FMT=7098) NPRMIN
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C---- IPAD
        IF (WARN(27)) THEN
          XMLLINE = ' '
c          WRITE(IOUT,FMT=7100)WMAX
          WRITE(XMLLINE,FMT=7100)WMAX
          CALL WRITE_SOCKET_SECTION(SERVERFD, LENSTR(XMLLINE),
     $         XMLLINE)
        END IF
C     
C---- Too many background pixels rejected . DISABLE THIS TEST, IT DOESNT
C     REALLY WORK
CAL        IF (WARN(17)) THEN
CAL          WRITE(IOUT,FMT=6054) BGSIG
CAL          IF (ONLINE) WRITE(ITOUT,FMT=6054) BGSIG
CAL        END IF
C----
C----
C----
      RETURN
C
C
 6000 FORMAT('<?xml version="1.0"?><!DOCTYPE information_and_warnings>',
     $     '<information_and_warnings>')
 6010 FORMAT('<traffic_light_colour>',A,'</traffic_light_colour>')
CAL 7000 FORMAT('<?xml version="1.0"?><!DOCTYPE warnings><warnings>')
 8000 FORMAT('</information_and_warnings>')
C
C---- Warn(1)
C
 7002 FORMAT('<warning><type>information</type>',
     $     '<colour>',A,'</colour>',
     $     '<summary>Spot overlap</summary>',
     $     '<detail>Adjacent spots overlap. This will produce ',
     +     'systematic errors in the intensities.',
     +     'Note that this',
     +     ' warning will arise even if only one pair of spots in',
     +     'one area of the detector overlap__nl__. Look at the ',
     +     'standard profiles',
     +     ' to see how serious the overlap is.',
     +     'The minimum allowed spot separation',
     +     ' was ',2F4.1,'mm, whereas the actual spot size determined',
